(() => {
  'use strict';
  const NOTES_V2_DATA = {"化学1":{"lessonKey":"化学1","courseCode":"chemistry","subject":"化学","chapter":1,"title":"绪论","syllabus":"预备与基础概念（对应 1.4 物质分类、三态与性质变化）","bookId":"sm1-chemistry-2017","bookCitation":"《马来西亚华文独中教科书 · 化学（上册）》（2017年11月版）第1章 p.1–19","examScopes":["uec"],"chapterOverview":{"summary":"第1章《绪论》确立化学作为“在原子、分子水平上研究物质组成、结构、性质、变化、制备和应用”的中心科学地位，并通过化学史三阶段建立定量实验观念；其中 1.4 节关于元素、纯净物与混合物、单质与化合物分类树、物质三态微观模型以及物理/化学性质与变化判据，是整个高中化学与统考选择题的底层语言。","conceptTree":[{"branch":"1.1 实用的与创造性的科学（p.3–4）","items":["提取自然界物质（金属冶炼、石油炼制、提取药物）","创造自然界不存在的新分子（合成纤维、塑料、橡胶，>3500万种）"]},{"branch":"1.2 中心科学与化学发展史（p.5–8）","items":["古代实用工艺时期（17世纪前）","近代化学时期（波义耳、拉瓦锡、道尔顿、阿伏加德罗、维勒、门捷列夫）","现代化学与表征仪器（量子/结构/核化学 + 光谱/质谱/核磁共振）"]},{"branch":"1.3 化学与能源、环境、材料及健康（p.9–11）","items":["能源演变（柴薪→煤炭→石油→氢能/核能/太阳能）","治污工艺（石灰石-石膏法/氨水法脱硫、汽车尾气催化转化）","合成氨化肥、新药研发与硅芯片材料"]},{"branch":"1.4 化学的研究对象——物质（p.12–19）","items":["1.4.1 元素与元素符号","1.4.2 物质的分类（混合物 vs 纯净物[单质/化合物]）","1.4.3 物质三态微观排列、运动与升华","1.4.4 物理性质/变化 vs 化学性质/变化判据"]}]},"paperFocus":["UEC 统考卷一选择题高频基础题：物质分类辨析（如单质 vs 仅含一种元素的混合物、NaHCO₃ 归属酸式盐、纯净物 vs 混合物如冰水共存/黑火药）、物理变化 vs 化学变化（含古诗词或生活现象判断）。","卷二探究与简答基础表达：从微粒排列与运动角度解释三态宏观性质及升华现象；规范使用“元素”与“原子/分子”术语（如“加钙加锌”指元素）。"],"solvingWorkflow":["判断“物质类别”先问两步：①有几种成分（1种→纯净物，≥2种→混合物）？②若为纯净物，有几种元素（1种→单质，≥2种→化合物）？","判断“无机酸/碱/盐/氧化物”：氧化物只有两种元素且其一为氧；酸式盐（如 NaHCO₃）含金属/铵根阳离子、氢离子与酸根，仍属于盐而非碱。","判断“性质 vs 变化”看关键词：带“能、易、可、会、具有……性”为性质（静态属性）；描述“发生、变成、燃烧、生锈、挥发”为变化（动态过程）。","判断“物理 vs 化学”看唯一标准：是否有新物质（新分子/新微粒组合）生成；发光发热、颜色改变、状态变化或爆炸（如气球爆裂 vs 火药爆炸）不一定都是化学变化。"],"questionTypes":["物质分类正误判断与“铁链/集合交叉图”归类分析（教材 p.19 第6–7题）","古诗词与生活情境中的物理变化、化学变化鉴别（教材 p.18 第10题）","性质与变化四维度分类排序题（教材 p.19 第4题）","物质三态微观排列、微粒间距与升华过程解释","化学史里程碑（波义耳、拉瓦锡、维勒、门捷列夫）与绿色化学脱硫/尾气净化原理"],"scoringNotes":["区分“化学变化”与“物理变化”作答必须紧扣核心得分词“有（或没有）新物质生成”。","分类题写明理由时需指出具体分类标准（如“按是否含同种元素”或“按是否属于盐/氧化物”），避免只答“结构不同”。"],"vid":[{"t":"物质的分类：纯净物、混合物、单质与化合物","q":"物质分类 纯净物 混合物 单质 化合物 高中化学"},{"t":"物理变化与化学变化、物理性质与化学性质辨析","q":"物理变化 化学变化 物理性质 化学性质 化学"},{"t":"化学发展简史：拉瓦锡、道尔顿与门捷列夫","q":"化学史 拉瓦锡 门捷列夫 化学革命"}],"sections":[{"id":"1.1","t":"化学是一门实用的、创造性的科学","anchor":{"pages":"化上 p.2–4","syllabus":"绪论：化学学科定义、实用价值与创造性本质","examScopes":["uec"],"examWeight":"基础学科认知与科技应用情境铺垫（P1 常识题与 P2 综合背景）","terms":"chemistry · practical science · creative science · synthetic material","prerequisites":["初中科学对常见日用品、金属与塑料的初步认知"],"goals":["准确表述教材对“化学”的定义（研究水平与五大核心研究维度）。","举例说明化学“实用性”（提取已有物质）与“创造性”（设计自然界不存在的新分子）的具体体现。","辩证理解“化学不危险，不懂化学才危险”的安全实验与合规使用理念。"]},"concepts":[{"kind":"definition","title":"化学的定义与核心研究尺度","pageRef":"化上 p.2、p.17","body":["**教材定义**：**化学（chemistry）**是在**原子、分子水平**上研究物质的**组成、结构、性质、变化、制备和应用**的自然科学。","**安全观辨析（p.2 交流分享）**：香皂、牙膏、护肤品和药品等化学品造福人类；中毒、爆炸或污染等化学事故并非化学本身“危险”，而是生产和使用中操作不当或认识不足所致——即“**化学不危险，不懂化学才危险**”。"],"takeaway":"记忆化学定义紧扣两要素：研究尺度（原子、分子水平）+ 六大任务（组成、结构、性质、变化、制备、应用）。"},{"kind":"mechanism","title":"实用性（提取与转化）vs 创造性（设计新分子）","pageRef":"化上 p.3–4","body":["**实用性（从自然界获取与加工物质）**：从矿石中冶炼钢铁等金属、从石油和天然气中提炼汽油/柴油、从植物体中提取药物、用超纯硅制造电脑芯片、食品保鲜冷藏与牛奶纯度检测等。","**创造性（制造自然界原本不存在的新物质）**：化学家根据需求设计具有特殊性质或功能的新分子，例如**合成橡胶、合成纤维、塑料、PVC 水管、化学染料与现代医药**。至今化学家发现和创造的化合物已超过 **3500 万种**。"],"takeaway":"“从天然原料提纯或冶炼”体现化学的实用性；“人工设计合成天然不存在的高分子或新药物”凸显化学的创造性。"},{"kind":"table","title":"教材思考题 1a（布里斯罗《化学的今天和明天》）实例归类","pageRef":"化上 p.4","body":["结合教材 p.4 阅读材料，考试常将日常制品与化学分支对应："],"table":{"headers":["生活领域","教材提及实例（p.3–4）","主要体现特性"],"rows":[["衣与日用","合成纤维衣物、合成染料着色天然棉毛、肥皂、牙膏","创造性 + 实用性"],["食与农业","化肥、除草剂、农药、兽医药、食品维生素添加与纯度检测","实用性 + 创造性"],["住与信息","钢筋水泥、涂料、PVC 水管、玻璃、液晶显示器、超纯硅芯片","实用性 + 创造性"],["交通与冶金","矿石冶炼金属与合金、橡胶轮胎、石油化工燃料与防锈油漆","实用性 + 创造性"]]}}],"formulas":[{"title":"实用化学代表：高炉炼铁（赤铁矿还原提取金属）","tex":"\\mathrm{Fe_2O_3(s) + 3CO(g)} \\xrightarrow{\\text{高温}} \\mathrm{2Fe(s) + 3CO_2(g)}","plain":"Fe2O3(s) + 3CO(g) —高温→ 2Fe(s) + 3CO2(g)","conditions":"高温条件；体现化学将天然矿石转化为实用金属材料","pageRef":"化上 p.3–4","note":"该反应在第4章定量计算（例7）还会作为工业计算核心方程。"},{"title":"创造化学代表：乙烯加聚合成聚乙烯塑料","tex":"n\\,\\mathrm{CH_2=CH_2} \\xrightarrow{\\text{催化剂}} \\mathrm{\\left[-CH_2-CH_2-\\right]}_{n}","plain":"n CH2=CH2 → [-CH2-CH2-]n","conditions":"引发剂/催化剂；小分子聚合成自然界不存在的高分子材料","pageRef":"化上 p.3","note":"合成塑料、合成纤维与合成橡胶合称三大合成高分子材料。"}],"pitfalls":[{"title":"把“天然提取”与“人工合成新分子”混为一谈","wrong":"“从植物中提取青蒿素和从石油中分馏汽油证明化学能创造自然界不存在的物质。”","diagnosis":"青蒿素、汽油组分原本已存在于植物或石油中，提取/分馏属于获取已有物质，体现的是实用性而非创造新分子。","right":"提取天然产物、冶炼金属体现**实用性**；合成塑料、合成橡胶、人工合成新药分子才直接体现**创造性**。","checkRule":"问自己：该物质在反应或加工前自然界里是否已经存在？"},{"title":"将化学品安全事故归咎于“化学学科危险”","wrong":"“化学制品都有毒有污染，因此应全面禁止使用化学品。”","diagnosis":"水、食盐、氧气、人体蛋白质本身全都是化学物质；事故源于违规操作或滥用（如乱用食品添加剂）。","right":"必须依靠化学知识规范生产、精准检测纯度与毒理安全，才能趋利避害。","checkRule":"遇到“纯天然不含任何化学物质”的广告或题支，一律判伪科学错误。"}],"examples":[{"label":"例 1.1.1","tier":"L2","tierLabel":"L2 基础应用","title":"教材思考题 1a：化学实用性与创造性事实拆解","prompt":"阅读教材 p.4《化学的今天和明天》节选：人类从矿石中冶炼金属、制造肥皂和牙膏、制作合成纤维衣物、对牛奶进行纯度安全检测、研制新药物及防锈油漆。(1) 哪两项最能说明化学是一门**实用的**科学？(2) 哪两项最能说明化学是一门**创造性的**科学？","clues":"区分“获取/检测/利用已知转化”与“设计自然界不存在的新分子/新材料”。","strategy":"紧扣 p.3–4 课文原文两段对比定义进行归类说明。","given":"冶炼金属、肥皂牙膏、合成纤维、牛奶检测、新药物、防锈油漆","principle":"化学通过研究物质性质实现提取应用（实用性）与分子设计合成（创造性）。","steps":["第(1)问（实用性）：从矿石中冶炼金属（获取有用单质）、对牛奶进行化学纯度与安全检测（保障饮食安全与生活实用）。","第(2)问（创造性）：设计制造合成纤维、研制自然界不存在的新型药物（或防锈涂料分子），创造全新功能材料。"],"answer":"(1) 矿石冶炼金属、牛奶化学检测（实用性）；(2) 合成纤维、设计新型药物分子（创造性）。","markingPoints":["紧扣“获取/检测已有需求”答出实用性实例（2分）","紧扣“创造自然界不存在的新分子/材料”答出创造性实例（2分）"],"verification":"对照教材 p.3–4 正文与思考题 1a(1)(2) 完全吻合。","pitfall":"若仅罗列物品名称而未说明“提取已有 vs 创造新分子”理由，在简答题中易被扣一半分析分。"},{"label":"例 1.1.2","tier":"L3","tierLabel":"L3 概念辨析","title":"识别“纯天然无化学物质”宣传谬误与化学研究范畴","prompt":"某广告宣称：“本矿泉水纯天然提取，绝对不含任何化学物质，安全无害。”请结合化学的定义说明该宣传语在科学上的两处错误，并指出化学从哪一微观水平研究物质。","clues":"自然界一切物质都由元素/原子/分子构成；有害无害取决于成分与浓度而非“是否化学物质”。","strategy":"用“物质客观存在性”与“化学定义（p.2）”反驳该谬误。","given":"“不含任何化学物质”矿泉水宣传语","principle":"一切物质皆属化学研究对象；化学在原子、分子水平上研究物质。","steps":["错误一：水（\\(\\mathrm{H_2O}\\)）及其中溶解的矿物质元素（如 \\(\\mathrm{Ca^{2+}}\\)、\\(\\mathrm{Mg^{2+}}\\) 等）本身就是化学物质，世上不存在“不含化学物质”的实物。","错误二：天然物质不一定绝对安全（如受污染矿泉含重金属），人工化学品只要符合纯度标准也可安全食用（教材 p.4 食品检测）。","化学研究水平：化学是在**原子、分子水平**上研究物质的组成、结构、性质、变化、制备和应用的自然科学。"],"answer":"两处错误：①水与矿物质本身即化学物质；②安全与否取决于成分和含量而非“天然/人工”。研究水平为原子、分子水平。","markingPoints":["指出水和矿物质本身即是化学物质（1分）","指出天然不等于绝对安全、需化学检测（1分）","准确写出“原子、分子水平”（1分）"],"verification":"与教材 p.2 定义及 p.17 习题 1-2 矿物质元素概念一致。","pitfall":"漏答“原子、分子水平”这一核心研究尺度。"}],"practice":[{"id":"chem1-1.1-q1","tier":"L1","tierLabel":"L1 基础","examStyle":"P1 选择","q":"化学科学主要是在下列哪一水平上研究物质的组成、结构、性质、变化、制备和应用的？（　）","options":["A. 天体与宏观星系水平","B. 细胞与组织器官水平","C. 原子、分子水平","D. 地质板块水平"],"correctOption":"C","given":"化学定义（化上 p.2）","method":"直接比对化学与物理/生物/地理的研究尺度差异","principle":"化学关注原子重排与分子构成变化。","steps":["教材 p.2 明确定义：化学是在原子、分子水平上研究物质的组成、结构、性质、变化、制备和应用的自然科学。","细胞属生物学，天体属天文学，地质属地理/地质学。"],"ans":"C","markingPoints":["识别原子、分子研究尺度"],"verification":"对照化上 p.2 黑体字。","pitfall":"与生物学的细胞水平混淆。"},{"id":"chem1-1.1-q2","tier":"L1","tierLabel":"L1 基础","examStyle":"P1 选择","q":"下列人类生产活动中，主要体现化学“创造自然界原本不存在的新物质”这一创造性特征的是（　）。","options":["A. 用蒸馏法从海水中获取淡水","B. 粉碎大块石灰石用于铺路","C. 以石油裂解气为原料人工合成塑料与合成橡胶","D. 从天然牛奶中过滤分离出乳脂"],"correctOption":"C","given":"四种工艺操作","method":"判别是否产生自然界不存在的新分子结构","principle":"化学创造性在于合成新分子与新功能材料。","steps":["A、B、D 均只分离或改变天然已有物质的聚集/物理形态。","C 通过聚合化学反应生成自然界不存在的高分子塑料和合成橡胶。"],"ans":"C","markingPoints":["区分物理提取与化学分子创造"],"verification":"对照化上 p.3 原文。","pitfall":"误选 A，海水淡化只是分离已有水与盐。"},{"id":"chem1-1.1-q3","tier":"L2","tierLabel":"L2 基础","examStyle":"P1 选择","q":"截至教材编著时，化学家已经发现和创造的化合物数量级约为（　）。","options":["A. 超过 100 种","B. 超过 3500 种","C. 超过 350 万种","D. 超过 3500 万种"],"correctOption":"D","given":"元素数量 vs 化合物数量（化上 p.4, p.12）","method":"区分“100 多种元素”与“超过 3500 万种化合物”","principle":"有限百余种元素通过不同组合构成数千万种化合物。","steps":["自然界已发现的元素有 100 多种（p.12），而发现和创造的化合物已超过 3500 万种（p.4）。"],"ans":"D","markingPoints":["识记教材 p.4 关键数据"],"verification":"核对化上 p.4 第4行原文。","pitfall":"将“100 多种元素”误当化合物总数，或看漏“万”字。"},{"id":"chem1-1.1-q4","tier":"L3","tierLabel":"L3 应用","examStyle":"P2 简答","q":"教材 p.3 列举了现代住宅和个人电脑中诸多由化学原理制备的部件，请任举**两项电脑部件材料**及**两项住宅建材**，并简要说明为何说“化学不危险，不懂化学才危险”。","given":"教材 p.2–3 生活事例","method":"提取教材实例 + 辩证分析操作规范","principle":"化学品效用与风险取决于人的认知与操作规程。","steps":["电脑部件材料：液晶显示器材料、主机中的超纯硅芯片（或键盘鼠标塑料外壳）。","住宅建材：钢筋与水泥、墙面涂料、铝合金门窗与玻璃、PVC 水管（任选两项）。","安全理念阐述：化学物质本身是中性的，造福生活；中毒、爆炸和环境污染往往是因为生产或使用时操作不当、或缺乏化学安全知识（如混合不相容清洁剂、燃气泄漏遇明火）所致，因此掌握化学知识才能安全驾驭化学。"],"ans":"电脑：超纯硅、液晶显示器/塑料；住宅：钢筋水泥、PVC水管/涂料/玻璃；事故源于不当操作与无知，懂化学方能趋利避害。","markingPoints":["正确列出两项电脑与两项住宅材料（2分）","紧扣“操作不当/认识不足导致事故，掌握化学知识保障安全”（2分）"],"verification":"对照教材 p.2–3 原文。","pitfall":"泛泛空谈“化学很重要”而未写出教材具体材料示例。"},{"id":"chem1-1.1-q5","tier":"L4","tierLabel":"L4 拓展探究","examStyle":"P2 综合评价","q":"某同学在学习“化学的实用性与创造性”后提出疑问：“既然自然界原本就有硅矿（\\(\\mathrm{SiO_2}\\)），那电脑芯片中的‘超纯硅’和房屋中的‘钢筋’为什么还要靠化学方法制造？”请从物质存在形式与纯度要求角度做出解释。","given":"天然矿石 SiO₂ / Fe₂O₃ 与高纯单质 Si / 合金钢","method":"对比天然化合态矿石与目标单质/合金的组成及纯度差异","principle":"自然界多数活泼/亲氧元素以化合物矿石存在，需化学还原与提纯。","steps":["存在形式不同：自然界中硅几乎全以二氧化硅（石英砂）和硅酸盐等化合物形式存在，铁主要以氧化铁等铁矿石存在，不存在现成的高纯单质。","化学转化与提纯：必须通过高温碳还原（\\(\\mathrm{SiO_2 + 2C \\to Si + 2CO}\\uparrow\\) 及后续化学法提纯至 99.9999999% 以上）才能制得半导体级超纯硅；同理，铁矿石需高炉还原炼铁并精确调控含碳量才能制成高强度钢筋。"],"ans":"天然硅和铁多以氧化物矿石形式存在，须经化学还原反应改变物质组成并精炼提纯，方能满足芯片超高纯度及建筑强度要求。","markingPoints":["指出天然矿物为化合态而非游离纯单质（2分）","说明需化学反应转化及高纯度精炼（2分）"],"verification":"结合 p.3“提取与转化”及 Ch 4 炼铁原理一致。","pitfall":"误以为矿山可以直接挖出高纯单质硅或现成钢筋。"}],"cheatSheet":["化学定义：在**原子、分子水平**上研究物质的组成、结构、性质、变化、制备和应用的自然科学。","两大特质：**实用性**（提取金属、石油炼制、提纯药物）+ **创造性**（设计自然界不存在的新分子，已超 3500 万种化合物）。","安全观念：“化学不危险，不懂化学才危险”，不存在“绝对不含化学物质”的商品。"],"kbEntryIds":["kb-chem1-chemistry-history"],"quiz":{"q":"下列关于化学科学的说法，**错误**的是（　）。","given":"绪论 1.1 基本观点","method":"逐项核对 p.2–4 核心论断","principle":"化学在原子分子水平研究并创造物质。","steps":["“纯天然食物不含任何化学物质”违背物质客观构成，水、糖、维生素全都是化学物质。"],"ans":"认为纯天然食物不含化学物质的说法错误；一切实物皆由化学元素与分子/原子组成。"}},{"id":"1.2","t":"化学发展成为一门中心科学","anchor":{"pages":"化上 p.5–8","syllabus":"化学发展三阶段、关键化学家贡献与现代仪器表征","examScopes":["uec"],"examWeight":"科学史人物配对 + 微观实验方法认识（P1 常识题与科学素养背景）","terms":"central science · Lavoisier · Boyle · Dalton · Avogadro · Mendeleev · Wohler","prerequisites":["科学实验观察与定量测量基本概念"],"goals":["说明化学被称为“中心科学”的原因（与材料、能源、环境、生命科学交叉渗透）。","梳理化学史三大时期（古代、近代、现代），准确匹配波义耳、拉瓦锡、维勒、道尔顿、阿伏加德罗、门捷列夫的里程碑贡献。","识别教材提及的现代化学表征仪器（如高效液相色谱仪、紫外可见分光光度计、质谱、核磁共振等）。"]},"concepts":[{"kind":"definition","title":"为什么化学是一门“中心科学”（Central Science）","pageRef":"化上 p.5、p.8","body":["**中心科学定位**：在**材料、能源、环境和生命科学**等诸多领域，化学所起的作用是其他科学无法替代的；正如美国核化学家**西博格（G. T. Seaborg）**所言：“化学——人类进步的关键”。","**生命科学交叉实例（p.8）**：化学家测定并合成蛋白质结构；20 世纪中叶，化学科学与生命科学共同揭示遗传物质 **DNA** 的结构与遗传规律，使生命科学迈入基因分子研究新阶段。"],"takeaway":"记住西博格名言及“材料、能源、环境、生命”四大交叉核心领域。"},{"kind":"table","title":"化学发展的三大历史时期与核心人物图谱","pageRef":"化上 p.5–7","body":["教材将化学史明确划分为**萌芽期（古代）→ 形成与发展期（近代）→ 现代化学期**三阶段："],"table":{"headers":["历史时期","时间范围与特征","代表人物 / 工艺成就（化上 p.5–7）"],"rows":[["古代化学（萌芽期）","17 世纪以前；尚未形成理论体系，以实用工艺为主","中国、古埃及突出：金属冶炼、酿酒、染色、造纸、火药、陶瓷、玻璃"],["近代化学（形成期）","17 世纪中期–19 世纪；确立定量实验与理论体系，分出四大基础分支","波义耳（定义元素）→ 拉瓦锡（钟罩实验、氧化学说推翻燃素说、质量守恒）→ 道尔顿（1803 原子论）→ 阿伏加德罗/康尼查罗（分子论）→ 维勒（合成尿素打破无机/有机界限）→ 迈耳与门捷列夫（元素周期律）"],["现代化学期","19 世纪末 20 世纪初至今；宏观与微观结合，数学化推理化增强","量子化学、结构化学、核化学三大方向；X射线、原子吸收光谱、紫外/红外光谱、质谱、核磁共振、高效液相色谱"]]}},{"kind":"mechanism","title":"近代化学确立的关键转折（p.7 交流分享解析）","pageRef":"化上 p.6–7","body":["**为什么说拉瓦锡与道尔顿之后化学才真正成为一门科学？** ①在此之前古代工艺只停留在经验摸索，“燃素说”长期误导燃烧解释；②**拉瓦锡**用天平进行精确**定量实验**，以氧化学说推翻燃素说，确立质量守恒定律，建立了近代化学定量实验基础；③**道尔顿**提出**原子论**，从理论上把千变万化的宏观定量定律统一到微观原子模型之中；此后经阿伏加德罗—康尼查罗原子-分子学说与门捷列夫周期律，化学终成严谨的理论科学体系。","**无机与有机界限的打破（p.6）**：19 世纪德国化学家**维勒（F. Wohler）**首次人工合成**尿素**，证明无机物与有机物之间没有不可逾越的鸿沟。"],"takeaway":"化学成为独立科学的两大支柱：拉瓦锡的**定量实验方法** + 道尔顿的**原子微粒理论**。"}],"formulas":[{"title":"拉瓦锡“钟罩实验”探究的金属氧化反应（定量推翻燃素说）","tex":"\\mathrm{2Hg(l) + O_2(g)} \\xrightarrow{\\Delta} \\mathrm{2HgO(s)},\\qquad \\mathrm{2HgO(s)} \\xrightarrow{\\text{强热}} \\mathrm{2Hg(l) + O_2(g)}","plain":"2Hg + O2 —Δ→ 2HgO；2HgO —强热→ 2Hg + O2","conditions":"密闭体系定量称量，证实燃烧是可燃物与空气中 O₂ 的化合","pageRef":"化上 p.6–7","note":"金属煅烧后增重恰好等于消耗的空气中氧气质量，彻底推翻假想“燃素”学说。"},{"title":"维勒人工合成尿素（打破生命力论，沟通无机与有机）","tex":"\\mathrm{NH_4CNO} \\xrightarrow{\\Delta} \\mathrm{CO(NH_2)_2}","plain":"NH4CNO（氰酸铵）—Δ→ CO(NH2)2（尿素）","conditions":"加热条件下由无机盐氰酸铵重排生成典型有机分子尿素","pageRef":"化上 p.6","note":"尿素含氮量约 46.67%，也是现代农业重要高氮化肥。"}],"pitfalls":[{"title":"混淆化学史关键人物的核心贡献","wrong":"“门捷列夫提出了原子论，拉瓦锡最早用人工方法合成尿素。”","diagnosis":"把四位近代化学家的代表作张冠李戴。","right":"**波义耳**：最早给元素下科学定义（《怀疑的化学家》）；**拉瓦锡**：燃烧氧化学说+质量守恒；**道尔顿**：原子论（1803）；**维勒**：人工合成尿素；**门捷列夫**（与迈耳）：元素周期律/周期表。","checkRule":"按时间轴速记：波（元素）→ 拉（定量燃烧）→ 道（原子）→ 阿（分子）→ 维（尿素）→ 门（周期表）。"},{"title":"忽视古代化学的局限性","wrong":"“中国古代四大发明中的造纸和火药说明我国古代已经建立起近代化学理论体系。”","diagnosis":"古代化学工艺虽辉煌，但以经验积累和实用工艺为主，尚未形成原子、分子及定量定律等科学理论体系。","right":"17 世纪以前称为古代化学（萌芽期），17 世纪中期经波义耳、拉瓦锡定量革命后化学才走上科学理论道路。","checkRule":"看到“尚未形成理论体系、实用工艺为主”对应古代萌芽期。"}],"examples":[{"label":"例 1.2.1","tier":"L2","tierLabel":"L2 基础辨析","title":"近代化学三大里程碑人物与贡献匹配","prompt":"请将下列四位科学家与其在化学史上的突破性贡献一一对应，并说明哪两项直接使化学告别“经验技艺”跨入“定量科学”：(1) 拉瓦锡；(2) 道尔顿；(3) 维勒；(4) 门捷列夫。","clues":"回顾教材 p.6–7 原文叙述顺序。","strategy":"逐一匹配实验/理论成果，再用实验+理论双轮驱动说明科学化原因。","given":"四位近代化学史代表人物","principle":"定量实验与微粒学说确立近代化学体系。","steps":["(1) 拉瓦锡：设计钟罩实验，提出燃烧氧化学说，推翻燃素说并确立质量守恒定律。","(2) 道尔顿：1803 年提出原子论要点，指出物质由原子构成且在化学变化中保持本性不变。","(3) 维勒：人工合成尿素，说明无机物与有机物之间没有不可逾越的鸿沟。","(4) 门捷列夫（与迈耳）：提出元素周期律并编制元素周期表，将元素及其化合物纳入规律系统。","跨越关键：拉瓦锡的定量实验（实验方法革命）与道尔顿的原子学说（理论框架革命）。"],"answer":"对应关系见上；拉瓦锡的定量氧化学说与道尔顿的原子论使化学正式成为一门科学。","markingPoints":["四位科学家贡献全部匹配正确（2分）","点出拉瓦锡定量实验与道尔顿原子论（2分）"],"verification":"对照教材 p.6–7 原文完全一致。","pitfall":"把“发现元素周期律”误记为波义耳或道尔顿。"},{"label":"例 1.2.2","tier":"L3","tierLabel":"L3 综合理解","title":"现代化学三大前沿方向与分析表征仪器应用","prompt":"教材 p.7–8 指出，现代化学始于 19 世纪末 20 世纪初，开始由宏观领域进入微观领域。(1) 现代微观化学主要从哪三个方向发展？(2) 教材提及了哪些现代分析测试仪器与技术，它们在化学研究中起什么作用？","clues":"直接查阅化上 p.7 末段与 p.8 图1-13、图1-14。","strategy":"分点准确提取“三大微观分支”和“现代仪器名称+作用”。","given":"现代化学研究前沿与仪器表征","principle":"宏观与微观结合、现代仪器解析分子结构与跟踪反应。","steps":["第(1)问：微观化学主要从**量子化学、结构化学、核化学**三个方向发展。","第(2)问：现代分析与测试技术包括 **X 射线、原子吸收光谱、紫外和红外光谱、质谱、核磁共振**，以及教材图1-13、1-14 展示的**高效液相色谱仪**和**紫外可见分光光度计**；作用在于精确测定物质微观结构、成分含量并跟踪化学反应过程。"],"answer":"(1) 量子化学、结构化学、核化学；(2) X射线、各类光谱、质谱、核磁共振、高效液相色谱仪等，用于测定物质结构与跟踪反应过程。","markingPoints":["完整写出量子化学、结构化学、核化学三方向（2分）","列举≥3种现代仪器并说明结构测定/反应跟踪用途（2分）"],"verification":"对照化上 p.7–8 原文核对。","pitfall":"误将近代四大分支（无机、有机、分析、物理化学）当成现代微观化学三方向。"}],"practice":[{"id":"chem1-1.2-q1","tier":"L1","tierLabel":"L1 基础","examStyle":"P1 选择","q":"在化学史上，通过精确天平定量实验推翻“燃素说”、确立燃烧氧化学说与质量守恒定律的科学家是（　）。","options":["A. 波义耳","B. 拉瓦锡","C. 道尔顿","D. 维勒"],"correctOption":"B","given":"化学史重要人物（化上 p.6–7）","method":"匹配实验与科学家","principle":"拉瓦锡“钟罩实验”定量证明氧气参与燃烧。","steps":["A 波义耳定义元素；B 拉瓦锡推翻燃素说并确立质量守恒；C 道尔顿提原子论；D 维勒人工合成尿素。"],"ans":"B","markingPoints":["识记拉瓦锡化学革命贡献"],"verification":"化上 p.6–7。","pitfall":"混淆波义耳与拉瓦锡。"},{"id":"chem1-1.2-q2","tier":"L1","tierLabel":"L1 基础","examStyle":"P1 选择","q":"下列哪项工艺属于 17 世纪以前“古代化学（萌芽期）”的典型成就？（　）","options":["A. 用 X 射线测定蛋白质晶体结构","B. 人工合成尿素与合成氨技术","C. 古代金属冶炼、酿酒、造纸、烧制陶瓷与火药","D. 建立量子化学与核磁共振技术"],"correctOption":"C","given":"化学史三阶段划分（化上 p.5–7）","method":"识别时代特征","principle":"古代化学以实用手工业技艺为主。","steps":["金属冶炼、酿酒、染色、造纸、火药、陶瓷与玻璃属于古代实用化学工艺；A、D 为现代化学，B 为近现代合成化学。"],"ans":"C","markingPoints":["分辨古代实用工艺与近现代科学成就"],"verification":"化上 p.6 第一段。","pitfall":"无。"},{"id":"chem1-1.2-q3","tier":"L2","tierLabel":"L2 基础","examStyle":"P1 选择","q":"下列关于近代化学四位科学家成就的配对中，**不**正确的是（　）。","options":["A. 波义耳 —— 撰写《怀疑的化学家》，为元素下定义","B. 维勒 —— 人工合成尿素，说明无机物与有机物相互联系","C. 门捷列夫 —— 与迈耳各自发现元素周期律，将元素纳入规律系统","D. 道尔顿 —— 首次提出“双原子分子”概念解释气体反应体积比"],"correctOption":"D","given":"化学史人物配对（化上 p.6–7）","method":"识别道尔顿与阿伏加德罗学说分界","principle":"道尔顿提原子论；阿伏加德罗提分子论与双原子分子。","steps":["A、B、C 均符合教材 p.6–7 原文。","D 错误：道尔顿未区分原子与分子，是阿伏加德罗（1811）与康尼查罗建立起原子—分子学说。"],"ans":"D","markingPoints":["辨析原子论与分子论创立者"],"verification":"结合 Ch 1 p.6 与 Ch 3 p.44。","pitfall":"把双原子分子误安在道尔顿名下。"},{"id":"chem1-1.2-q4","tier":"L3","tierLabel":"L3 综合","examStyle":"P2 简答","q":"化学被称为一门“中心科学”。请结合教材 p.5–8 说明：(1) 化学与哪四大科学领域密不可分？(2) 在生命科学领域，20 世纪中叶化学家与生物学家共同取得了哪项划时代突破？","given":"化上 p.5, p.8 原文","method":"提取交叉学科关键词与 DNA 结构突破","principle":"化学在分子层面为相关前沿学科提供物质与理论支撑。","steps":["(1) 四大核心交叉领域：**材料、能源、环境、生命科学**（p.5 感知生活框）。","(2) 20 世纪中叶，化学科学与生命科学共同揭示了生命遗传物质 **DNA** 的结构与遗传规律（以及蛋白质结构测定与合成），使生命科学进入研究基因组成、结构和功能的新阶段。"],"ans":"(1) 材料、能源、环境、生命科学；(2) 共同揭示了遗传物质 DNA 的结构与遗传规律。","markingPoints":["准确写出四大领域（2分）","答出揭示 DNA 结构与遗传规律（2分）"],"verification":"对照化上 p.5、p.8 核对。","pitfall":"漏写“遗传物质 DNA”。"},{"id":"chem1-1.2-q5","tier":"L4","tierLabel":"L4 探究","examStyle":"P2 实验史分析","q":"18 世纪以前流行“燃素说”，认为金属加热煅烧后之所以变成炉灰，是因为金属放出了“燃素”。但精细称量显示，铜或锡在空气中煅烧后固体质量反而**增加**了。请用拉瓦锡的钟罩定量实验观点解释：(1) 为什么固体质量增加了？(2) 若实验在完全密闭的玻璃钟罩内进行，反应前后整个封闭钟罩体系的总质量如何变化？","given":"燃素说矛盾 + 拉瓦锡钟罩定量实验（p.7）","method":"结合燃烧氧化学说与物质不灭定律作答","principle":"燃烧是物质与氧气化合；封闭体系遵循质量守恒。","steps":["(1) 金属煅烧并不是放出“燃素”，而是金属与空气中的氧气发生化合生成了金属氧化物，固体结合了空气中的氧，因此固体质量增加（增重量等于参加反应的 \\(\\mathrm{O_2}\\) 质量）。","(2) 在完全密闭的玻璃钟罩内，既无气体进入也无气体逸出，体系内只发生原子重新组合，因此反应前后整个钟罩体系的总质量保持不变（物质不灭定律）。"],"ans":"(1) 金属与空气中 O₂ 化合生成氧化物，结合了氧的质量故固体增重；(2) 密闭钟罩总质量不变。","markingPoints":["指出结合了氧气质量（2分）","说明封闭体系总质量守恒不变（2分）"],"verification":"与 Ch 1 p.7 及 Ch 3 p.45 拉瓦锡实验一致。","pitfall":"混淆“固体质量增加”与“密闭总体系质量不变”。"}],"cheatSheet":["化学是材料、能源、环境、生命科学交汇的**中心科学**（西博格：化学——人类进步的关键）。","化学史口诀：古代重实用工艺；近代波义耳（元素）→ 拉瓦锡（定量+氧化学说）→ 道尔顿（原子）→ 阿伏加德罗（分子）→ 维勒（尿素）→ 门捷列夫（周期表）。","现代三分支：**量子化学、结构化学、核化学**；仪器：X射线、质谱、光谱、核磁共振、高效液相色谱。"],"kbEntryIds":["kb-chem1-chemistry-history"],"quiz":{"q":"是谁首先通过“人工合成尿素”证明了无机物与有机物之间没有不可逾越的鸿沟？","given":"19 世纪化学史突破（化上 p.6）","method":"检索近代有机化学里程碑","principle":"维勒打破“生命力论”。","steps":["教材 p.6 明确记载：维勒（F. Wohler）人工合成尿素，说明无机物与有机物之间相互联系。"],"ans":"维勒（F. Wohler）"}},{"id":"1.3","t":"化学与人类社会发展密切相关","anchor":{"pages":"化上 p.9–11","syllabus":"能源变革、环境治理、化工材料与化学相关职业","examScopes":["uec"],"examWeight":"环境化学（脱硫/尾气催化）与可持续发展题干背景","terms":"fossil fuel · hydrogen energy · flue-gas desulfurization · catalytic converter · Haber process","prerequisites":["对空气污染（SO₂、汽车尾气）和能源类型的生活常识"],"goals":["梳理人类能源使用的发展脉络（柴薪→煤炭→石油→绿色新能源）及化学的推动作用。","说明燃煤烟气脱硫（石灰石-石膏法、氨水法）与汽车尾气催化净化的产物与环保意义。","列举化学在农业增产（合成氨）、医药研发、信息芯片（硅与光纤）及多类职业中的关键贡献。"]},"concepts":[{"kind":"mechanism","title":"能源演变史与绿色新能源开发","pageRef":"化上 p.10","body":["**能源利用四阶段**：**柴薪时期**（用火烧烤、陶瓷、冶炼）→ **煤炭时期**（催生冶金、交通与化学工业）→ **石油时期**（石油炼制与石油化工迅猛发展）→ **现代多元清洁能源时期**（核能、**氢能**、太阳能、新型绿色化学电源、生物质能源、海水盐差发电）。","**核心关系**：化学既帮助人类高效获取能源，又保障能源开发与生态保护之间的平衡。"],"takeaway":"记住能源演进顺序“柴薪 → 煤炭 → 石油 → 多元清洁能源”，重点关注第2章将深入学习的**氢能源**。"},{"kind":"mechanism","title":"环境污染治理的两大化学工艺（p.10–11）","pageRef":"化上 p.10–11","body":["**1. 燃煤烟气脱硫（减少 \\(\\mathrm{SO_2}\\) 排放防酸雨）**：化学家发明了**石灰石—石膏法**和**氨水法**，既能消除烟气中的二氧化硫，又分别得到副产品**石膏（\\(\\mathrm{CaSO_4\\cdot 2H_2O}\\)）**和**硫酸铵（\\(\\mathrm{(NH_4)_2SO_4}\\)，可用作氮肥）**，实现变废为宝。","**2. 汽车尾气催化转化**：通过安装在排气管中的汽车尾气处理装置，使有害成分（如 \\(\\mathrm{CO}\\) 与氮氧化物 \\(\\mathrm{NO}_x\\)）在**催化剂**作用下转化为无害的**氮气（\\(\\mathrm{N_2}\\)）、二氧化碳（\\(\\mathrm{CO_2}\\)）和水蒸气（\\(\\mathrm{H_2O}\\)）**。"],"takeaway":"工业脱硫两条途径（石灰石-石膏法得石膏；氨水法得硫酸铵）；尾气催化转化最终生成 \\(\\mathrm{N_2}\\)、\\(\\mathrm{CO_2}\\) 与 \\(\\mathrm{H_2O}\\)。"},{"kind":"table","title":"20 世纪以来化学支撑现代文明的五大支柱与相关职业","pageRef":"化上 p.11","body":["教材 p.11 指出，若没有化学合成技术，现代生活将难以维系；且众多职业均紧密依赖化学："],"table":{"headers":["社会支柱领域","关键化学技术 / 原料（p.11）","相关职业（图1-22）"],"rows":[["粮食安全与农业","合成氨技术提供大量氮肥","农化/化肥质检员、土壤分析员"],["人类健康与医药","新药物（如阿司匹林）研制与食品添加剂","医生、药剂师、药物研制人员"],["材料与日用品","塑料、合成纤维、合成橡胶、化妆品","化工研发工程师、化妆品鉴定师"],["信息时代基石","以硅及其化合物为原料制造芯片和光导纤维","半导体材料师、化学科研人员"],["教育与安全监管","化学质量检测与学科人才培育","化学教师、质量检测人员、法医鉴定员"]]}}],"formulas":[{"title":"汽车尾气催化转化核心反应（有害 CO 与 NO 转为无害 N₂ 与 CO₂）","tex":"\\mathrm{2CO(g) + 2NO(g)} \\xrightarrow{\\text{催化剂}} \\mathrm{N_2(g) + 2CO_2(g)}","plain":"2CO + 2NO —催化剂→ N2 + 2CO2","conditions":"排气管催化剂作用下；将有毒一氧化碳与一氧化氮同步消除","pageRef":"化上 p.11","note":"未燃尽的碳氢化合物同步氧化为 CO₂ 与 H₂O(g)。"},{"title":"石灰石—石膏法烟气脱硫总反应（变废为宝）","tex":"\\mathrm{2CaCO_3(s) + 2SO_2(g) + O_2(g) + 4H_2O(l) \\longrightarrow 2CaSO_4\\cdot 2H_2O(s) + 2CO_2(g)}","plain":"2CaCO3 + 2SO2 + O2 + 4H2O → 2CaSO4·2H2O + 2CO2","conditions":"湿法烟气脱硫塔；副产物生石膏 CaSO₄·2H₂O 可用于建材","pageRef":"化上 p.10–11","note":"氨水法则用氨水吸收 SO₂ 并氧化制得氮肥硫酸铵 (NH₄)₂SO₄。"}],"pitfalls":[{"title":"混淆石灰石—石膏法与氨水法脱硫的副产品","wrong":"“氨水法消除烟气中二氧化硫后，得到的副产品是碳酸铵或石膏。”","diagnosis":"石灰石含钙得到含钙的石膏（硫酸钙）；氨水含氮得到铵盐肥料硫酸铵。","right":"石灰石—石膏法副产品为**石膏**；氨水法副产品为**硫酸铵**（p.10–11）。","checkRule":"按元素守恒核对：石灰石(Ca) → 石膏(CaSO₄)；氨水(NH₃) → 硫酸铵((NH₄)₂SO₄)。"},{"title":"错记光导纤维和芯片的主要原料","wrong":"“信息时代的电脑芯片和光导纤维分别是用铜和塑料制成的。”","diagnosis":"半导体芯片核心为高纯晶体硅（\\(\\mathrm{Si}\\)），光导纤维核心为高纯二氧化硅（\\(\\mathrm{SiO_2}\\)）。","right":"教材 p.11 明确指出：以**硅及其化合物**为原料制造芯片和光导纤维引领我们进入信息时代。","checkRule":"芯片 = 单质硅 \\(\\mathrm{Si}\\)，光纤 = 二氧化硅 \\(\\mathrm{SiO_2}\\)。"}],"examples":[{"label":"例 1.3.1","tier":"L2","tierLabel":"L2 基础应用","title":"燃煤脱硫与汽车尾气净化的化学环保原理","prompt":"某燃煤电厂与城市交通分别排放大量 \\(\\mathrm{SO_2}\\) 和汽车尾气（含 \\(\\mathrm{CO}\\)、氮氧化物及未燃烃类）。请依据教材 p.10–11 回答：(1) 电厂可采用哪两种方法消除 \\(\\mathrm{SO_2}\\)，各自能得到什么有价值的副产品？(2) 汽车尾气处理装置能把有害气体转化成哪三种较安全的气体排出？","clues":"紧扣元素守恒与化上 p.10–11 原文。","strategy":"分条对比两种脱硫副产物及尾气催化转化最终产物。","given":"烟气 SO₂ 与汽车尾气有害成分","principle":"化学工艺在消除污染的同时回收副产品实现绿色循环。","steps":["第(1)问：电厂可采用**石灰石—石膏法**（得副产品**石膏**）或**氨水法**（得副产品**硫酸铵**，作氮肥）。","第(2)问：汽车尾气中的有害成分在催化剂作用下转化为**氮气（\\(\\mathrm{N_2}\\)）、二氧化碳（\\(\\mathrm{CO_2}\\)）和水蒸气（\\(\\mathrm{H_2O(g)}\\)）**。"],"answer":"(1) 石灰石-石膏法（得石膏）和氨水法（得硫酸铵）；(2) 氮气、二氧化碳、水蒸气。","markingPoints":["写出两种脱硫方法并正确匹配石膏、硫酸铵（2分）","写出尾气转化产物 N₂、CO₂、水蒸气（2分）"],"verification":"与化上 p.10–11 原文一字不差。","pitfall":"尾气催化产物易漏写氮气（氮氧化物还原的产物）或误写成氧气。"},{"label":"例 1.3.2","tier":"L3","tierLabel":"L3 综合计算衔接","title":"化学史与社会应用：从合成氨到信息材料的科学逻辑","prompt":"教材 p.11 指出：“20 世纪初，如果没有合成氨技术，就不可能生产出粮食增产所需要的大量氮肥，人类将面临饥饿的威胁。”(1) 写出工业合成氨的原料及化学方程式；(2) 除氮肥外，再列举教材提及的两种由化学支撑的现代关键技术或材料。","clues":"氮肥中的氮元素最终来自空气中的氮气（\\(\\mathrm{N_2}\\)）与氢气（\\(\\mathrm{H_2}\\)）。","strategy":"写出合成氨反应并结合 p.11 提取医药、材料或信息产业例子。","given":"合成氨技术与现代社会支柱","principle":"人工固氮（N₂ → NH₃）开启现代氮肥工业。","steps":["第(1)问：以氮气与氢气为原料，在高温、高压和催化剂下合成氨：\\(\\mathrm{N_2(g) + 3H_2(g)} \\xrightleftharpoons{\\text{高温、高压、催化剂}} \\mathrm{2NH_3(g)}\\)。","第(2)问：如研制新型药物抗击疾病；大量生产塑料、合成纤维与合成橡胶；以硅及其化合物制造电脑芯片与光导纤维等（任举两项）。"],"answer":"(1) \\(\\mathrm{N_2 + 3H_2 \\rightleftharpoons 2NH_3}\\)；(2) 如硅芯片/光导纤维、合成药物/塑料等。","markingPoints":["原料正确并配平合成氨方程（2分）","准确举出两项 p.11 现代化学支撑技术（2分）"],"verification":"合成氨方程在 Ch 2 p.33 与 p.35 同样重点出现。","pitfall":"写合成氨漏配系数 3 和 2 或漏写条件。"}],"practice":[{"id":"chem1-1.3-q1","tier":"L1","tierLabel":"L1 基础","examStyle":"P1 选择","q":"人类历史上使用能源的大致演进顺序为（　）。","options":["A. 煤炭时期 → 柴薪时期 → 石油时期 → 新能源时期","B. 柴薪时期 → 石油时期 → 煤炭时期 → 新能源时期","C. 柴薪时期 → 煤炭时期 → 石油时期 → 多元清洁能源时期","D. 石油时期 → 煤炭时期 → 柴薪时期 → 氢能时期"],"correctOption":"C","given":"能源发展史（化上 p.10）","method":"按人类科技工业化进程排序","principle":"工业革命推动煤炭取代柴薪，内燃机与石化推动石油时代。","steps":["教材 p.10 明确列出：首先是柴薪时期，然后是煤炭时期，直到石油时期，目前开发核能、氢能、太阳能等多元清洁能源。"],"ans":"C","markingPoints":["识记能源发展四阶段顺序"],"verification":"化上 p.10 原文。","pitfall":"颠倒煤炭与石油顺序。"},{"id":"chem1-1.3-q2","tier":"L2","tierLabel":"L2 基础","examStyle":"P1 选择","q":"为减少发电厂燃煤烟气中二氧化硫（\\(\\mathrm{SO_2}\\)）的排放，化学家发明了石灰石—石膏法与氨水法，这两种方法各自得到的副产品分别是（　）。","options":["A. 碳酸钙和尿素","B. 石膏和硫酸铵","C. 生石灰和氯化铵","D. 石膏和硝酸铵"],"correctOption":"B","given":"烟气脱硫工艺（化上 p.10–11）","method":"对照教材与硫元素价态去向","principle":"SO₂ 最终被固定转化为硫酸钙（石膏）或硫酸铵。","steps":["教材 p.10–11 明确写出：既可消除烟气中的二氧化硫，又可得到副产品石膏和硫酸铵。"],"ans":"B","markingPoints":["准确记忆两种脱硫副产品"],"verification":"化上 p.10–11。","pitfall":"误选硝酸铵或碳酸钙。"},{"id":"chem1-1.3-q3","tier":"L2","tierLabel":"L2 基础","examStyle":"P1 选择","q":"引领人类进入信息时代的电子芯片与光导纤维，其核心制造原料主要是（　）。","options":["A. 铁及其氧化物","B. 硅及其化合物","C. 氯气与食盐","D. 铜与铝合金"],"correctOption":"B","given":"信息材料原料（化上 p.11）","method":"对应半导体芯片（Si）与光导纤维（SiO₂）","principle":"硅半导体与二氧化硅光导纤维是信息时代物质基础。","steps":["教材 p.11 原文：“没有以硅及其化合物为原料制造的芯片和光导纤维引领我们进入信息时代”。"],"ans":"B","markingPoints":["识记芯片与光纤核心原料为硅及其化合物"],"verification":"化上 p.11。","pitfall":"误把光纤材料当作塑料或金属铜丝。"},{"id":"chem1-1.3-q4","tier":"L3","tierLabel":"L3 应用","examStyle":"P2 简答","q":"现代汽车普遍装有尾气催化净化装置，可将尾气中的一氧化碳（\\(\\mathrm{CO}\\)）和一氧化氮（\\(\\mathrm{NO}\\)）等有害物质转化为对大气无害的成分。(1) 写出汽车尾气转化生成的三种主要无毒气体或蒸气；(2) 试写出 \\(\\mathrm{CO}\\) 与 \\(\\mathrm{NO}\\) 在催化剂作用下反应的化学方程式。","given":"汽车尾气催化转化（化上 p.11）","method":"由元素组成（C、N、O、H）结合教材给出产物并配平","principle":"催化转化实现有害污染物向大气稳定组分 N₂、CO₂、H₂O 转变。","steps":["(1) 转化为**氮气（\\(\\mathrm{N_2}\\)）、二氧化碳（\\(\\mathrm{CO_2}\\)）和水蒸气（\\(\\mathrm{H_2O}\\)）**。","(2) 配平方程式：\\(\\mathrm{2CO(g) + 2NO(g)} \\xrightarrow{\\text{催化剂}} \\mathrm{N_2(g) + 2CO_2(g)}\\)。"],"ans":"(1) 氮气、二氧化碳、水蒸气；(2) \\(\\mathrm{2CO + 2NO} \\xrightarrow{\\text{催化剂}} \\mathrm{N_2 + 2CO_2}\\)。","markingPoints":["正确写出三种转化产物（2分）","化学式与系数配平完全正确（2分）"],"verification":"方程两边各含 2 C, 2 N, 4 O，守恒。","pitfall":"忘记将 NO 中的 N 写成双原子分子 N₂。"},{"id":"chem1-1.3-q5","tier":"L4","tierLabel":"L4 综合拓展","examStyle":"P2 绿色化学计算","q":"“氨水法”烟气脱硫中，可用氨水吸收 \\(\\mathrm{SO_2}\\) 并经空气氧化制得化肥硫酸铵 \\(\\mathrm{(NH_4)_2SO_4}\\)，总反应可简写为：\\(\\mathrm{4NH_3 + 2SO_2 + O_2 + 2H_2O \\longrightarrow 2(NH_4)_2SO_4}\\)。若某工厂每天需吸收 \\(128\\text{ kg}\\) 二氧化硫（已知式量：\\(\\mathrm{SO_2}=64, (\\mathrm{NH_4})_2\\mathrm{SO_4}=132\\)），理论上每天可副产多少千克硫酸铵化肥？并说明为何该方法符合绿色化学理念。","given":"m(SO₂) = 128 kg，M(SO₂) = 64 g/mol，M((NH₄)₂SO₄) = 132 g/mol","method":"硫元素守恒（1 mol SO₂ → 1 mol (NH₄)₂SO₄）","principle":"反应前后硫原子守恒与资源循环利用。","steps":["由总反应可知系数比 \\(n(\\mathrm{SO_2}) : n((\\mathrm{NH_4})_2\\mathrm{SO_4}) = 2 : 2 = 1 : 1\\)。","吸收 \\(\\mathrm{SO_2}\\) 的物质的量（以 kmol 计）：\\(n(\\mathrm{SO_2}) = \\frac{128\\text{ kg}}{64\\text{ kg/kmol}} = 2.0\\text{ kmol}\\)。","故生成硫酸铵 \\(2.0\\text{ kmol}\\)，理论质量：\\(m = 2.0\\text{ kmol} \\times 132\\text{ kg/kmol} = 264\\text{ kg}\\)。","绿色化学意义：在消除酸雨污染物 \\(\\mathrm{SO_2}\\) 的同时将其转化为农业急需的氮肥，原子利用率高且无二次固体废渣。"],"ans":"理论可副产 \\(264\\text{ kg}\\) 硫酸铵；消除了污染物 \\(\\mathrm{SO_2}\\) 并实现资源化再利用。","markingPoints":["正确算出 n(SO₂) = 2 kmol（1分）","由 1:1 计量比求出 m = 264 kg（2分）","紧扣减排与副产物资源化答出绿色化学意义（1分）"],"verification":"\\(128 / 64 \\times 132 = 264\\text{ kg}\\)，数值准确。","pitfall":"误把方程式系数 2 当成 1:2 比例而算出 528 kg 或 132 kg。"}],"cheatSheet":["能源演进：**柴薪 → 煤炭 → 石油 → 氢能/核能/太阳能等绿色能源**。","环保双工艺：烟气脱硫（**石灰石-石膏法**得石膏，**氨水法**得硫酸铵）；汽车尾气催化转化得 **N₂、CO₂、H₂O**。","信息与粮食：芯片/光纤原料 = **硅及其化合物**；粮食增产氮肥依赖**合成氨技术**。"],"kbEntryIds":["kb-chem1-chemistry-history"],"quiz":{"q":"燃煤电厂采用“氨水法”脱除烟气中的二氧化硫后，能获得的农业有用副产品是什么？","given":"烟气脱硫工艺（化上 p.10–11）","method":"利用氨水与硫氧化物转化规律检索","principle":"NH₃ 与氧化后的含硫组分结合成铵盐化肥。","steps":["教材 p.10–11 明确指出：石灰石—石膏法得到石膏，氨水法得到**硫酸铵**。"],"ans":"硫酸铵（\\(\\mathrm{(NH_4)_2SO_4}\\)）"}},{"id":"1.4","t":"化学的研究对象——物质","anchor":{"pages":"化上 p.12–19","syllabus":"1.4.1 元素 · 1.4.2 物质的分类 · 1.4.3 物质三态 · 1.4.4 物理性质和化学性质","examScopes":["uec"],"examWeight":"全章最核心高频考点！UEC 卷一必出物质分类与物理/化学变化辨析题","terms":"matter · element · pure substance · mixture · elementary substance · compound · sublimation · physical/chemical change","prerequisites":["能辨识水、空气、食盐、铁、氧气等日常常见物质"],"goals":["界定物质与元素的概念，区分“宏观元素”与“微观原子/分子”的表达语境。","默写图 1-26 物质分类树，并准确归类单质（金属/非金属）、无机物（氧化物/酸/碱/盐）、有机物与混合物。","对比固、液、气三态的微粒排列、运动方式与宏观可压缩性，列举常见的升华物质。","严格运用“是否有新物质生成”判别物理变化与化学变化，并区分“性质”与“变化”的语言表述。"]},"concepts":[{"kind":"definition","title":"1.4.1 物质与元素：宏观元素 vs 微观粒子","pageRef":"化上 p.12–13、p.17","body":["**物质（matter）**：具有**质量**且**占有空间**的一切客观存在，既包括看得见摸得着的固体液体（水、金属），也包括看不见摸不着的气体（空气、氢气）。","**元素（element）与元素符号**：具有相同**核电荷数（即质子数）**的同一类原子的总称（p.17 重要概念）。自然界 100 多种元素组成了数千万种单质与化合物，用特有元素符号表示（如 \\(\\mathrm{C}\\) 表示碳元素，\\(\\mathrm{O}\\) 表示氧元素）。","**考试语境提示**：饮料或营养标签中的“含钙、镁、锌、硒等矿物质”，指的是宏观的**元素**，而非单个原子、分子或金属单质（p.17 第2题）。"],"takeaway":"判断元素种类的唯一标准是**质子数（核电荷数）相同**；营养成分表里的“钙、铁、锌”均指**元素**。"},{"kind":"table","title":"1.4.2 物质的分类体系与典型易混物质归属（图1-26）","pageRef":"化上 p.13–14、p.17–19","body":["按照物质**组成**分类是最有效的方法。注意**混合物**无固定组成、各成分保持原有性质、可用物理方法分离；**化合物**各元素必须用**化学方法**才能分开。"],"table":{"headers":["物质类别","判别标准","教材代表物质（p.13–19）","考场高发特例提醒"],"rows":[["混合物","≥2 种不同单质或化合物混合","空气、牛奶、泥土、食盐水、碘酒、海水、黑火药、花岗岩、水泥沙浆","只含一种元素但有多种单质（如 O₂+O₃、金刚石+石墨）仍是混合物！"],["单质（金属/非金属）","同一种元素组成的纯净物","Cu、Fe、Al、Hg（液态金属）；O₂、I₂、S、石墨、金刚石","同种元素可形成多种单质（如金刚石和石墨均由 C 组成）"],["无机化合物","不同元素纯净物（氧化物/酸/碱/盐）","氧化物：H₂O、CO₂、Na₂O、SiO₂；酸：H₂SO₄；碱：NaOH、KOH；盐：NaCl、NaHCO₃、FeCl₃","NaHCO₃ 属钠盐/含氧酸盐/酸式盐，不属于碱（p.18 第8题）"],["有机化合物","含碳化合物（除 CO、CO₂、碳酸盐等）","乙醇（C₂H₅OH）、蔗糖（C₁₂H₂₂O₁₁）、葡萄糖、塑料袋、旧橡胶","CO₂、Na₂CO₃、NaHCO₃ 虽含碳元素，但归为无机化合物"]]}},{"kind":"table","title":"1.4.3 物质三态的微观结构与升华现象","pageRef":"化上 p.15、p.19","body":["一般物质随温度和压强改变可在固态、液态、气态之间转化（如 \\(0\\ ^\\circ\\mathrm{C}\\) 冰、液态水、\\(100\\ ^\\circ\\mathrm{C}\\) 水蒸气属同种物质）。**升华（sublimation）**：固体不经液态直接变成气态，教材点名四例：**碘（\\(\\mathrm{I_2}\\)）、萘、樟脑、干冰**。"],"table":{"headers":["聚集状态","微观结构（排列与空隙）","微粒运动方式","宏观性质（教材 p.19 表填空）"],"rows":[["固态 (s)","微粒排列整齐而紧密，微粒间空隙很小","只能在固定的位置上振动 (vibrate)","有固定的形状和体积，不易被压缩"],["液态 (l)","微粒排列零乱，但微粒间空隙较小","不停地振动、转动 (rotate) 和移动 (move)","没有固定的形状（有固定体积），不易被压缩"],["气态 (g)","微粒排列凌乱，微粒间的空隙很大","不停地振动、转动和高速自由移动","没有固定的形状和体积，容易被压缩"]]}},{"kind":"definition","title":"1.4.4 物理变化/化学变化 与 物理性质/化学性质四维判据","pageRef":"化上 p.15–19","body":["**变化看“有无新物质生成”（动态过程）**：","- **物理变化**（无新物质生成）：水沸腾、冰融化、酒精挥发、湿衣服晾干、海水晒盐、灯泡通电发光发热、氧气液化、硫溶于二硫化碳、使铁带有磁性、宝剑磨砺。","- **化学变化**（有新物质生成）：氢气燃烧生成水、铁生锈、葡萄酿成酒、森林着火、火药爆炸、点燃煤气、牛奶变酸、木材腐烂、铜器出现铜绿、蜡烛燃烧（“蜡炬成灰泪始干”）。","**性质看“是否需要通过化学变化才能表现”（静态固有属性，常含能、易、会、可）**：","- **物理性质**：颜色、气味、熔点、沸点、硬度、密度、挥发性、溶解性、导热导电性、易升华（如镁条银白色光泽、碘易升华、CuO 是黑色粉末）。","- **化学性质**：可燃性、氧化性、酸碱性、还原性、热稳定性（如天然气可以燃烧、通电条件下水可分解、\\(\\mathrm{CO_2}\\) 能使澄清石灰水变浑浊）。"],"takeaway":"“发光发热”或“爆炸”不一定是化学变化（如灯泡通电发光、高压锅/气球爆炸都是物理变化）；而**火药爆炸**和**蜡烛燃烧**生成了新物质，才是化学变化！"}],"diagrams":[{"src":"assets/fig/v2/chem01-matter-tree.svg","caption":"图 1-1 物质的组成与分类树及统考易错辨析（化上 图1-26 p.13–14）","alt":"物质分类树：混合物与纯净物、单质与化合物、无机物与有机物","pageRef":"化上 p.13–14"}],"formulas":[{"title":"物质的三态相变（物理变化：分子本身不变，仅间距与运动方式改变）","tex":"\\mathrm{H_2O(s)} \\xrightarrow{0\\ ^\\circ\\mathrm{C}\\text{ 熔化}} \\mathrm{H_2O(l)} \\xrightarrow{100\\ ^\\circ\\mathrm{C}\\text{ 沸腾}} \\mathrm{H_2O(g)},\\qquad \\mathrm{CO_2(s)} \\xrightarrow{\\text{升华}} \\mathrm{CO_2(g)}","plain":"H2O(s) —0°C→ H2O(l) —100°C→ H2O(g)；CO2(s) —升华→ CO2(g)","conditions":"常压 1.01×10⁵ Pa 下水熔点 0 ℃、沸点 100 ℃；干冰不经液态直接升华","pageRef":"化上 p.15","note":"状态符号 (s)、(l)、(g) 在第4章书写化学方程式时必用。"},{"title":"物理性质（密度）与化学变化代表式（氢气燃烧生成水）","tex":"\\rho = \\frac{m}{V},\\qquad \\mathrm{2H_2(g) + O_2(g)} \\xrightarrow{\\text{点燃}} \\mathrm{2H_2O(l)}","plain":"ρ = m / V；2H2(g) + O2(g) —点燃→ 2H2O(l)","conditions":"密度无需化学变化即可测定（物理性质）；氢气燃烧有新物质 H₂O 生成（化学变化）","pageRef":"化上 p.15–16","note":"氢气“能”在氧气中燃烧则是氢气的化学性质。"}],"pitfalls":[{"title":"把“仅含一种元素”等同于“一定是单质”","wrong":"“某瓶气体经元素分析只含有氧元素，所以它一定是纯净物中的单质。”","diagnosis":"同一种元素可以组成几种不同的单质（如氧气 \\(\\mathrm{O_2}\\) 与臭氧 \\(\\mathrm{O_3}\\)，金刚石与石墨）。将两者混在一起虽仍只含一种元素，但成分有多种。","right":"只含一种元素的物质**可能是单质，也可能是混合物**（如 \\(\\mathrm{O_2}\\) 和 \\(\\mathrm{O_3}\\) 混合气体），但**一定不是化合物**！","checkRule":"遇到“只含一种元素”必查是否混有两种同素异形体单质。"},{"title":"将酸式盐 \\(\\mathrm{NaHCO_3}\\) 误归为碱，或将熟石灰 \\(\\mathrm{Ca(OH)_2}\\) 误归为盐","wrong":"“小苏打 \\(\\mathrm{NaHCO_3}\\) 溶液显碱性，所以它属于碱；熟石灰 \\(\\mathrm{Ca(OH)_2}\\) 是白色固体，所以它属于盐。”","diagnosis":"化学分类依据的是**物质组成结构**而非溶液酸碱性或外观状态（教材 p.18 第8、9题原题陷阱）。","right":"\\(\\mathrm{NaHCO_3}\\) 由 \\(\\mathrm{Na^+}\\) 与酸式酸根 \\(\\mathrm{HCO_3^-}\\) 构成，属于**盐（含氧酸式钠盐）**；熟石灰 \\(\\mathrm{Ca(OH)_2}\\) 由金属阳离子与氢氧根 \\(\\mathrm{OH^-}\\) 构成，属于**碱**。","checkRule":"阴离子全为 \\(\\mathrm{OH^-}\\) 才是碱；金属/铵根 + 酸根（即使带 H）是盐。"},{"title":"把物理变化中的现象（发光、溶解、升华、融化）误当化学变化","wrong":"“电灯泡通电发光发热、海水晒盐得到晶体、干冰升华冒白雾都是化学变化。”","diagnosis":"发光发热是电能转光热能；晒盐是水分蒸发结晶；干冰升华是固态 \\(\\mathrm{CO_2}\\) 变气态并使周围水蒸气液化成雾，均无新物质生成。","right":"判据永远唯一：**是否生成了新物质**。冰水共存也是纯净物，水变冰只是物理变化。","checkRule":"遇到“发光、放热、变色、气泡、爆炸”先问自己：里面生成新分子了吗？"}],"examples":[{"label":"例 1.4.1","tier":"L2","tierLabel":"L2 校内期末","title":"教材 p.14 问题解决 & p.18–19：物质分类与“铁链”归类法","prompt":"(1) 请将下列 6 种常见物质分类归入“混合物、单质、氧化物、酸、碱、盐、有机化合物”中最精确的一类：空气、乙醇（\\(\\mathrm{C_2H_5OH}\\)）、铜、食盐水、碳酸氢钠（\\(\\mathrm{NaHCO_3}\\)）、氢氧化钾（\\(\\mathrm{KOH}\\)）。\n(2) 在教材 p.19“铁链”图（\\(\\mathrm{H_2}\\) —[A]— \\(\\mathrm{CO_2}\\) —[B]— \\(\\mathrm{Na_2O}\\) —[C]— \\(\\mathrm{NaCl}\\) —[D]— \\(\\mathrm{FeCl_3}\\)）中，相邻两种物质可归为一类，请为相交处 A、B、C、D 填入最恰当的分类依据（如“都是氧化物”“都是盐”等）。","clues":"注意区分“食盐（NaCl 晶体，纯净物）”与“食盐水（溶液，混合物）”；注意 A 处连接单质 H₂ 与化合物 CO₂。","strategy":"先定混合物/纯净物，再细划单质与化合物子类；铁链逐对找共性。","given":"6 种生活物质 + 5 种铁链相邻物质","principle":"图 1-26 物质组成树状分类标准。","steps":["第(1)问：混合物 = **空气、食盐水**；金属单质 = **铜**；有机化合物 = **乙醇（\\(\\mathrm{C_2H_5OH}\\)）**；碱 = **氢氧化钾（\\(\\mathrm{KOH}\\)）**；盐（含氧酸式盐）= **碳酸氢钠（\\(\\mathrm{NaHCO_3}\\)）**。","第(2)问：逐段分析铁链交集：","- **A（\\(\\mathrm{H_2}\\) 与 \\(\\mathrm{CO_2}\\)）**：常温常压下都是气体（或都不全属于单质/都是由非金属元素组成的纯净物）。","- **B（\\(\\mathrm{CO_2}\\) 与 \\(\\mathrm{Na_2O}\\)）**：两种物质**都是氧化物**（均只含两种元素且其一为氧）。","- **C（\\(\\mathrm{Na_2O}\\) 与 \\(\\mathrm{NaCl}\\)）**：两种物质**都是钠的化合物**。","- **D（\\(\\mathrm{NaCl}\\) 与 \\(\\mathrm{FeCl_3}\\)）**：两种物质**都是盐**（均为金属阳离子与酸根 \\(\\mathrm{Cl^-}\\) 构成，也可称都是氯化物）。"],"answer":"(1) 混合物：空气、食盐水；单质：铜；有机物：乙醇；碱：KOH；盐：NaHCO₃。(2) A：常温均为气体（或不全是单质）；B：都是氧化物；C：都是钠的化合物；D：都是盐。","markingPoints":["6 种物质全部精确分类（3分）","B、C、D 分别填出氧化物、钠的化合物、盐，A 合理（2分）"],"verification":"与教材 p.14、p.18–19 原题对照完全吻合。","pitfall":"若把食盐水当作盐（纯净物）或把 \\(\\mathrm{NaHCO_3}\\) 当作碱会失分。"},{"label":"例 1.4.2","tier":"L3","tierLabel":"L3 预试辨析","title":"教材 p.19 第4题：变化与性质四维精准甄别","prompt":"请将下列 8 项描述严格分为“物理变化、化学变化、物理性质、化学性质”四类（填序号）：①二氧化碳能使澄清石灰水变浑浊；②钢铁生锈；③电灯发光；④冰雪融化；⑤煤气燃烧；⑥铜器上出现铜绿；⑦镁能燃烧；⑧氧化铜（II）是黑色粉末。","clues":"两步过滤法：第一步分“性质（静态/含能字）”与“变化（动态过程）”；第二步分“物理（无新物质）”与“化学（有新物质）”。","strategy":"建立 2×2 四象限矩阵逐一落位。","given":"8 句教材原题描述","principle":"性质 vs 变化（静态能力 vs 动态过程）；物理 vs 化学（有无新物质）。","steps":["①“能使澄清石灰水变浑浊”——“能”表属性，且反应生成 \\(\\mathrm{CaCO_3}\\) 沉淀 → **化学性质**。","②“钢铁生锈”——正在/已经生成新物质铁锈（\\(\\mathrm{Fe_2O_3\\cdot}x\\mathrm{H_2O}\\)）→ **化学变化**。","③“电灯发光”——钨丝发热发光，无新物质生成 → **物理变化**。","④“冰雪融化”——固态水变液态水，无新物质生成 → **物理变化**。","⑤“煤气燃烧”——生成 \\(\\mathrm{CO_2}\\) 和水等新物质 → **化学变化**。","⑥“铜器上出现铜绿”——生成新物质碱式碳酸铜 → **化学变化**。","⑦“镁能燃烧”——“能”表固有属性，需燃烧化学变化体现 → **化学性质**。","⑧“氧化铜（II）是黑色粉末”——颜色状态无需化学变化即表现 → **物理性质**。"],"answer":"物理变化：③④；化学变化：②⑤⑥；物理性质：⑧；化学性质：①⑦。","markingPoints":["物理变化 ③④ 与物理性质 ⑧ 精准区分（2分）","化学变化 ②⑤⑥ 与化学性质 ①⑦ 精准区分（2分）"],"verification":"逐条核对化上 p.19 第4题。","pitfall":"常把“⑦镁能燃烧”错当化学变化（多了一个“能”字即变为性质），或把“③电灯发光”错当化学变化。"}],"practice":[{"id":"chem1-1.4-q1","tier":"L1","tierLabel":"L1 基础","examStyle":"P1 选择","q":"在饮用水中添加含钙、镁、锌、硒等的矿物质，可以补充人体营养。这里的“钙、镁、锌、硒”指的是（　）。","options":["A. 分子","B. 原子","C. 金属单质","D. 元素"],"correctOption":"D","given":"食品与饮用水成分表述（化上 p.17 习题1-2）","method":"区分宏观元素与微观粒子或金属单质","principle":"生物营养或矿物成分标签上的名称统指元素。","steps":["水中不可能含有金属单质钙或锌（活泼金属会与水剧烈反应），而是以含钙、镁、锌、硒元素的化合物或离子形式存在，宏观上统称为元素。"],"ans":"D","markingPoints":["识别宏观元素语境"],"verification":"教材 p.17 选择题第2题。","pitfall":"误选 B 或 C。"},{"id":"chem1-1.4-q2","tier":"L2","tierLabel":"L2 期末","examStyle":"P1 选择","q":"下列诗句加点部分或日常过程中，主要涉及**化学变化**的是（　）。","options":["A. 月波成露露成霜，借与南枝作淡妆","B. 春蚕到死丝方尽，蜡炬成灰泪始干（“蜡炬成灰”）","C. 宝剑锋从磨砺出，梅花香自苦寒来","D. 莫道雪融便无迹，雪融成水水成冰"],"correctOption":"B","given":"古诗词物理/化学变化判断（化上 p.18 习题1-10）","method":"检视是否有新物质生成","principle":"状态改变、打磨、分子扩散均为物理变化；燃烧成灰为化学变化。","steps":["A 水蒸气液化成露、凝华成霜，均为水三态变化（物理变化）。","B 蜡烛燃烧化作二氧化碳和水蒸气及炭灰，有新物质生成（化学变化）。","C 磨砺改变金属形状，花香扩散是分子运动（均为物理变化）。","D 雪水冰互变全为 \\(\\mathrm{H_2O}\\) 状态改变（物理变化）。"],"ans":"B","markingPoints":["用新物质判据排除三项物理变化"],"verification":"教材 p.18 第10题原题。","pitfall":"被“蜡泪”（蜡熔化滴落，物理变化）混淆，注意题干特指“蜡炬成灰”（燃烧）。"},{"id":"chem1-1.4-q3","tier":"L2","tierLabel":"L2 期末","examStyle":"P1 选择","q":"下列关于物质分类的说法，**不**正确的是（　）。","options":["A. 水（\\(\\mathrm{H_2O}\\)）属于氧化物，硫酸（\\(\\mathrm{H_2SO_4}\\)）属于酸","B. 碳酸氢钠（\\(\\mathrm{NaHCO_3}\\)）属于钠盐、含氧酸盐，也是化合物","C. 冰水共存物属于纯净物，而黑火药属于混合物","D. 熟石灰 [\\(\\mathrm{Ca(OH)_2}\\)] 属于盐，由金刚石和石墨组成的固体属于单质"],"correctOption":"D","given":"物质分类正误判断（化上 p.17–18）","method":"逐项对照图 1-26 与纯净物/混合物边界","principle":"Ca(OH)₂ 为碱；同素异形体混合属混合物。","steps":["A、B、C 均完全正确（冰水共存只有 H₂O 一种分子，是纯净物；黑火药为 KNO₃、S、C 混合物）。","D 有两处错误：熟石灰 \\(\\mathrm{Ca(OH)_2}\\) 属于**碱**而非盐；金刚石与石墨结构不同是两种不同单质，混在一起属于**混合物**而非单质。"],"ans":"D","markingPoints":["识别碱与盐及单质混合物错误"],"verification":"综合教材 p.17–18 第3、8、9题。","pitfall":"看见“金刚石+石墨只含碳元素”就误判为单质。"},{"id":"chem1-1.4-q4","tier":"L3","tierLabel":"L3 预试","examStyle":"P2 简答","q":"(1) 为什么气体很容易被压缩，而固体和液体都不易被压缩？请从物质三态的微观结构与微粒运动角度回答。\n(2) 下列五组物质中各有一种与其余三种不属于同一类别，请找出该物质并说明分类依据（教材 p.19 第6题改编）：\n① \\(\\mathrm{Mg, O_2, N_2, NO}\\)；\n② \\(\\mathrm{Al, Fe, Mg, Hg}\\text{（水银）}\\)；\n③ \\(\\mathrm{SO_2, CO_2, SiO_2, NH_3}\\)。","given":"三态微观结构表 + 物质分类挑异类","method":"(1) 对比微粒间隙大小；(2) 依元素种类、常温状态或氧化物定义判别","principle":"微观空隙决定可压缩性；单质/化合物/状态/氧化物是核心分类标准。","steps":["第(1)问：在气态中，微粒排列凌乱，**微粒间的空隙很大**且可自由高速移动，外加压强易使空隙缩小，故容易被压缩；而在固态和液态中，微粒排列紧密，**微粒间的空隙很小/较小**，几乎没有进一步压缩的空间，故不易被压缩。","第(2)问：","- ① 挑出 **\\(\\mathrm{NO}\\)**：其余三种（\\(\\mathrm{Mg, O_2, N_2}\\)）均为单质，只有 \\(\\mathrm{NO}\\) 是化合物（氧化物）。","- ② 挑出 **\\(\\mathrm{Hg}\\)（水银）**：其余三种（\\(\\mathrm{Al, Fe, Mg}\\)）在常温常压下都是固态金属，只有 \\(\\mathrm{Hg}\\) 在常温下是液态金属。","- ③ 挑出 **\\(\\mathrm{NH_3}\\)**：其余三种（\\(\\mathrm{SO_2, CO_2, SiO_2}\\)）都是氧化物（含氧元素），只有 \\(\\mathrm{NH_3}\\) 是氢化物（不含氧）。"],"ans":"(1) 气态微粒空隙很大故易压缩，固液微粒排列紧密空隙小故难压缩；(2) ① NO（化合物）；② Hg（常温液态金属）；③ NH₃（非氧化物）。","markingPoints":["用“微粒空隙很大 vs 排列紧密空隙小”解释可压缩性（2分）","三组分别准确找出异类并给出化学分类依据（3分）"],"verification":"对照教材 p.15 与 p.19 第5、6题核对。","pitfall":"第①组若挑 Mg（金属 vs 非金属气体）也可自圆其说，但最根本的组成层级标准是单质 vs 化合物（NO）。"},{"id":"chem1-1.4-q5","tier":"L4","tierLabel":"L4 统考综合","examStyle":"P2 综合探究","q":"某实验室有一瓶无色透明液体标签脱落，已知它可能是纯净的蒸馏水（\\(\\mathrm{H_2O}\\)）、双氧水（\\(\\mathrm{H_2O_2}\\) 水溶液）或氯化钠水溶液（\\(\\mathrm{NaCl(aq)}\\)）中的一种。请综合运用“纯净物 vs 混合物”和“物理性质 vs 化学变化”的知识，设计两步简要实验方案鉴别出三者，并指出各步利用了什么性质（物理/化学）。","given":"三种无色液体：纯水 H₂O、H₂O₂ 溶液、NaCl 溶液","method":"第一步用化学反应特征（MnO₂ 催化分解产氧）鉴出 H₂O₂；第二步用物理蒸发法区分纯水与 NaCl 溶液","principle":"纯净物与混合物蒸发残渣差异 + 化学性质差异。","steps":["**第一步（化学性质鉴别 \\(\\mathrm{H_2O_2}\\)）**：分别取少量三种液体于试管中，加入少量黑色 \\(\\mathrm{MnO_2}\\) 粉末。若立即产生大量气泡且能使带余烬木条复燃，则该液体为**双氧水（\\(\\mathrm{H_2O_2}\\) 溶液）**（利用其易分解生成 \\(\\mathrm{O_2}\\) 的**化学性质**）。","**第二步（物理性质/蒸发鉴别纯水与 \\(\\mathrm{NaCl}\\) 溶液）**：将剩余两种无明显现象的液体各取数滴置于洁净蒸发皿（或玻璃片）上加热蒸干。完全挥发无任何残留物的是**纯净的蒸馏水**（纯溶剂沸点固定 100 ℃）；蒸干后留下白色晶体固体残渣的是**氯化钠水溶液**（混合物中溶质不挥发，利用挥发性/溶解性**物理性质**）。"],"ans":"①加 MnO₂ 放 O₂ 鉴出 H₂O₂（化学性质）；②加热蒸发，无残留为蒸馏水、留白色晶体为 NaCl 溶液（物理性质/物理变化）。","markingPoints":["正确利用 MnO₂ 催化放氧现象鉴出 H₂O₂ 并标明化学性质（2分）","利用蒸发后有无白色固体残留区分纯水与 NaCl 溶液并标明物理变化/性质（2分）"],"verification":"切忌在实验室随意用嘴品尝未知试剂区分盐水！蒸发法安全规范。","pitfall":"在实验室答“用嘴尝一下咸味区分 NaCl 溶液”属于严重违反实验安全规范的失分答案。"}],"cheatSheet":["分类两步法：先看成分数（1种=纯净物，≥2种=混合物）；再看元素种数（1种=单质，≥2种=化合物）。**只含一种元素可能是混合物**（如 \\(\\mathrm{O_2+O_3}\\)）。","无机易混：\\(\\mathrm{NaHCO_3}\\) 是**盐**（酸式盐），不是碱；\\(\\mathrm{Ca(OH)_2}\\) 是**碱**，不是盐；\\(\\mathrm{CO_2}\\) 是无机氧化物。","三态与升华：碘、萘、樟脑、干冰可升华；气体空隙大易压缩，固液紧密空隙小难压缩。","变化看有无**新物质**生成；性质常含“能、易、可、会”（静态属性），变化是正在发生的过程。"],"kbEntryIds":["kb-chem1-matter-element","kb-chem1-classification","kb-chem1-states","kb-chem1-properties-changes"],"quiz":{"q":"下列三句话分别描述物质的物理性质、化学性质还是变化？(1) 碘单质易升华；(2) 湿衣服晾干；(3) 天然气可以燃烧。","given":"化上 p.16 思考题 1d","method":"先判“性质 vs 变化”，再判“物理 vs 化学”","principle":"有无新物质生成 + 静态固有属性 vs 动态过程。","steps":["(1) 易升华：固态直接变气态无新物质，“易”表固有属性 → 物理性质。","(2) 湿衣服晾干：水分蒸发成水蒸气无新物质，属变化过程 → 物理变化。","(3) 可以燃烧：“可以”表固有属性，燃烧生成 CO₂ 和 H₂O 新物质 → 化学性质。"],"ans":"(1) 物理性质；(2) 物理变化；(3) 化学性质"}}]},"化学2":{"lessonKey":"化学2","courseCode":"chemistry","subject":"化学","chapter":2,"title":"水和氢","syllabus":"3.1 水和氢（无机化学选答组）","bookId":"sm1-chemistry-2017","bookCitation":"《马来西亚华文独中教科书 · 化学（上册）》（2017年11月版）第2章 p.21–40","examScopes":["uec"],"chapterOverview":{"summary":"第2章《水和氢》是无机元素化合物的开篇核心章，围绕“水是生命之源”与“氢是最轻、最清洁高能元素”展开：先剖析水反常的物理常数（3.98 ℃ 最大密度、最大比热容）及五大类化学反应（与金属、非金属、氧化物、碳化钙、盐类）；再通过水的电解实验建立氢元素概念，系统掌握氢气的实验室与工业制法、验纯与爆炸极限（4%–74%）、还原 CuO 实验操作规范及氢能源六大优势。","conceptTree":[{"branch":"2.1 水的性质（p.23–28）","items":["2.1.1 反常物理性质（3.98 ℃ 最大密度 1.0000 g/mL、比热 4.18×10³ J/(kg·K)、万能溶剂）","2.1.2 五类化学反应（Na/Fe、C/F₂/Cl₂、酸碱性氧化物、CaC₂、水合物与 AlCl₃ 水解）"]},{"branch":"2.2 氢元素与氢气（p.29–36）","items":["活动2 电解水（正氧负氢 1:2，证明水由 H/O 元素组成）","2.2.1 制取：Zn + 稀酸 / Zn,Al + NaOH；工业水煤气、甲烷重整、电解食盐水","2.2.2 性质：最轻气体、验纯与 4%–74% 爆炸极限、可燃性、金属氢化物与还原 CuO","2.2.3 用途：合成氨/盐酸/油脂氢化、氢能源六大优势（热值 142 351 kJ/kg）"]}]},"paperFocus":["UEC 统考卷一选择题与卷二乙部（无机化学 2 选 1 必考高频基础）：水与金属活动性顺序分级反应（冷水 vs 水蒸气 vs 不反应）、氧化物与水反应产物（含 NO₂、SiO₂、CuO 特例）、无水 CuSO₄ 检水、金属与酸制氢反应速率及图像拐点（p.39 第9题）。","卷二实验探究与流程简答：电解水两装置对比（图甲试管 vs 图乙带活塞针筒/滴定管）、实验室制氢选材原因、小试管拇指验纯法及 H₂ 还原 CuO “先通后点、先熄后停”故障诊断（p.40 第8题）。"],"solvingWorkflow":["看到“金属与水反应”先定位金属活动性顺序：K、Ca、Na 与冷水剧烈反应生成碱+H₂；Mg、Al、Zn、Fe 需沸水或高温水蒸气（注意 3Fe + 4H₂O(g) 生成 Fe₃O₄ 而非 Fe₂O₃）；Cu 及以后不反应。","看到“氧化物与水”别盲目套通式：Na₂O、CaO、K₂O 可溶碱性氧化物能化合，CuO、Fe₂O₃ 难溶碱性氧化物不直接反应；SO₂/SO₃/CO₂ 为酸酐直接化合，SiO₂ 不与水反应，2NO₂ + H₂O 生成 HNO₃ 与 HNO₂ 两种酸。","看到“制氢与还原实验”必查三细节：①电解水加少量稀 H₂SO₄/NaOH 只为增强导电性；②制氢选 Zn + 稀 HCl/稀 H₂SO₄（不用 Mg 太快、Fe 太慢、Pb 钝化阻隔、浓 H₂SO₄/HNO₃ 强氧化）；③点燃/加热前先验纯，还原结束先熄灯后停气。","遇到“Zn 与盐酸产氢图像题”（p.39 第9题）：斜线阶段横轴物质（Zn）限量，水平平台阶段另一试剂（HCl）耗尽、横轴物质过量，拐点 P 表示恰好完全反应。"],"questionTypes":["水与金属、非金属、氧化物、CaC₂、盐类的化学方程式书写与石蕊试液变色（p.39 第2–3题）","钠与水反应“浮、熔、游、响、红”实验现象归因（活动1 p.25）","电解水两套装置优缺点评价与气体检验（p.29、p.39 第4题）","金属活动性顺序（图 2-10）与产氢速率/产氢量折线图分析（p.38–39 第7、9题）","氢气验纯正误判断与 H₂ 还原 CuO 异常变黑原因诊断（p.36、p.40 第8题）"],"scoringNotes":["书写化学方程式务必注明条件（高温、Δ、电解、催化剂）及沉淀/状态，特别是 Fe 与高温水蒸气产物必须写 \\(\\mathrm{Fe_3O_4}\\)，Na 与水生成 \\(\\mathrm{NaOH}\\) 而非 \\(\\mathrm{Na_2O}\\)。","实验故障诊断题要写出因果链（如“反应后未继续通 \\(\\mathrm{H_2}\\) 至铜冷却，炽热的铜与空气中氧气重新反应生成黑色 \\(\\mathrm{CuO}\\)”）。"],"vid":[{"t":"水的反常物理性质与化学性质（钠与水、水煤气、水解）","q":"水的性质 钠与水反应 水的电解 高中化学"},{"t":"氢气的实验室制取、验纯及还原氧化铜实验","q":"氢气的制取 验纯 氢气还原氧化铜 实验"},{"t":"金属活动性顺序与酸反应产氢规律","q":"金属活动性顺序 置换反应 氢气图像"}],"sections":[{"id":"2.1","t":"水的性质","anchor":{"pages":"化上 p.23–28","syllabus":"3.1.1 水的物理性质 · 3.1.2 水的化学性质","examScopes":["uec"],"examWeight":"P1 物理反常与反应分类辨析 + P2 金属/氧化物与水化学方程式书写","terms":"specific heat · universal solvent · water gas · water of crystallization · hydrolysis","prerequisites":["第1章物质的分类（氧化物、酸、碱、盐、有机物）与物理/化学性质判据"],"goals":["解读图 2-4、表 2-2 与表 2-3，说明水在 3.98 ℃ 最大密度、冰浮水面及超大比热容对地球生态和气候的意义。","完整描述活动1“钠与水反应”的现象及结论，掌握金属活动性顺序中各金属与冷水/水蒸气反应的分级界限。","熟练书写水与非金属（C、F₂、Cl₂）、酸碱性氧化物（含 NO₂ 特例）、电石（CaC₂）及盐类（结晶水合与 AlCl₃ 水解）的化学方程式。"]},"concepts":[{"kind":"constant","title":"2.1.1 水的三大反常物理性质（图2-4、表2-2/2-3）","pageRef":"化上 p.23–24、p.37","body":["**1. 熔沸点反常高**：在 \\(1.01\\times 10^5\\text{ Pa}\\) 下，式量相近的 \\(\\mathrm{CH_4}\\)（16，沸点 \\(-161\\ ^\\circ\\mathrm{C}\\)）、\\(\\mathrm{NH_3}\\)（17，沸点 \\(-33\\ ^\\circ\\mathrm{C}\\)）常温均为气态，而水（\\(M_r=18\\)）熔点 **\\(0\\ ^\\circ\\mathrm{C}\\)**、沸点 **\\(100\\ ^\\circ\\mathrm{C}\\)**，常温为无色无味透明液态（厚层呈蓝绿色）。","**2. 3.98 ℃ 反常最大密度与冰浮水面（图2-4）**：水在 **\\(3.98\\ ^\\circ\\mathrm{C}\\)** 时体积最小、密度最大（\\(1.0000\\text{ g\\,mL}^{-1}\\)）；低于 \\(3.98\\ ^\\circ\\mathrm{C}\\) 降温反而膨胀，结冰后密度更小而浮于水面，阻隔严冬冷空气，使水底保持约 \\(4\\ ^\\circ\\mathrm{C}\\) 从而保护水生动植物安全越冬。","**3. 已知固液体中最大比热容与万能溶剂（表2-3）**：液态水比热容高达 **\\(4.18\\times 10^3\\text{ J\\,kg}^{-1}\\mathrm{K}^{-1}\\)**（远超乙醇 \\(2.46\\) 与铁 \\(0.45\\)），能有效调节气温，使沿海昼夜温差比内陆小。水能溶解极多物质，被称为**万能溶剂**，有时还可作为**催化剂**，也是生物体内新陈代谢的最优良介质。"],"takeaway":"常考两点生态意义：① \\(3.98\\ ^\\circ\\mathrm{C}\\) 最大密度与冰浮水面保护水生生物越冬；② 高比热容使沿海昼夜温差小。"},{"kind":"experiment","title":"活动探究1：金属钠与水反应的现象与结论","pageRef":"化上 p.25","body":["**实验步骤**：向盛水小烧杯滴入几滴**酚酞试液**；从煤油中取出钠块，用滤纸吸干表面煤油并刮去表面氧化膜，切一小块投入水中（余钠放回原试剂瓶）。","**现象与因果一一对应（口诀：浮、熔、游、响、红）**：","- **浮**在水面：说明金属钠的密度比水**小**（\\(\\rho_\\mathrm{Na} < 1\\text{ g/cm}^3\\)）。","- **熔**成闪亮小球：说明钠与水反应剧烈**放热**，且钠熔点较低（约 \\(97.8\\ ^\\circ\\mathrm{C}\\)）。","- 快速**游**动并发出“嘶嘶”**响**声：钠表面产生大量氢气气体推动小球在水面快速移动。","- 溶液最终完全变**粉红**色：反应生成了碱性物质**氢氧化钠（\\(\\mathrm{NaOH}\\)）**，使酚酞变红。"],"takeaway":"钠保存在煤油中隔绝空气与水；“浮、熔、游、响、红”分别对应密度小、放热熔点低、产气体、生成碱。"},{"kind":"table","title":"2.1.2 水的五大类化学反应全景表（p.26–28）","pageRef":"化上 p.26–28、p.37","body":["水热稳定性极高（加热到 \\(2000\\ ^\\circ\\mathrm{C}\\) 大约只有 \\(2\\%\\) 分解），但在适宜条件下可发生下列五类典型反应："],"table":{"headers":["反应对象类别","教材代表反应方程式（p.26–28）","规律与高发特例提醒"],"rows":[["1. 金属单质","2Na(s) + 2H₂O(l) → 2NaOH(aq) + H₂(g)\n3Fe(s) + 4H₂O(g) —高温→ Fe₃O₄(s) + 4H₂(g)","K/Ca/Na 与冷水反应；Mg/Al/Zn/Fe 只与沸水或高温水蒸气反应；Sn..Au 不反应"],["2. 非金属单质","C(s,炽热) + H₂O(g) —高温→ CO(g) + H₂(g)（水煤气）\n2F₂(g) + 2H₂O(l) → 4HF(aq) + O₂(g)\nCl₂(g) + H₂O(l) ⇌ HCl(aq) + HClO(aq)","炽热炭上洒少许水，炉火更旺因为生成了可燃气体 CO 和 H₂（水煤气，p.28 思考题 2a）"],["3. 金属/非金属氧化物","CaO(s) + H₂O(l) → Ca(OH)₂(aq)；Na₂O + H₂O → 2NaOH\nCO₂/SO₂/SO₃ + H₂O → H₂CO₃/H₂SO₃/H₂SO₄\n2NO₂(g) + H₂O(l) → HNO₃(aq) + HNO₂(aq)","大多数碱性氧化物（CuO、Fe₂O₃）及非金属氧化物 SiO₂ 不能与水直接反应；NO₂ 生成两种酸！"],["4. 金属碳化物","CaC₂(s) + 2H₂O(l) → Ca(OH)₂(s) + C₂H₂(g)","电石（碳化钙）遇水生成氢氧化钙和乙炔气体（可燃，照明/气焊）"],["5. 盐类（水合与水解）","CuSO₄(s,白) + 5H₂O(l) → CuSO₄·5H₂O(s,蓝)\nNa₂CO₃ + 10H₂O → Na₂CO₃·10H₂O；ZnSO₄ + 7H₂O → ZnSO₄·7H₂O\nAlCl₃(s) + 3H₂O(l) ⇌ Al(OH)₃(s) + 3HCl(aq)","无水硫酸铜(II) 白色变蓝是检验痕量水的经典试剂；AlCl₃ 水解为可逆反应"]]}}],"formulas":[{"title":"水的核心物理常数与生态判据","tex":"\\rho_{\\max}(3.98\\ ^\\circ\\mathrm{C}) = 1.0000\\text{ g\\,mL}^{-1},\\qquad c_{\\text{水}} = 4.18\\times 10^3\\text{ J\\,kg}^{-1}\\mathrm{K}^{-1}","plain":"ρ_max(3.98 °C) = 1.0000 g/mL；c_水 = 4.18 × 10³ J/(kg·K)","conditions":"常压 1.01×10⁵ Pa；3.98 ℃ 时液态水密度最大、体积最小","pageRef":"化上 p.23–24、p.37","note":"比热容居已知固体液体之首（乙醇仅 2.46×10³，铁仅 0.45×10³）。"},{"title":"水与铁、碳及二氧化氮的三组高频特殊反应","tex":"\\mathrm{3Fe(s) + 4H_2O(g)} \\xrightarrow{\\text{高温}} \\mathrm{Fe_3O_4(s) + 4H_2(g)},\\quad \\mathrm{C(s) + H_2O(g)} \\xrightarrow{\\text{高温}} \\mathrm{CO(g) + H_2(g)},\\quad \\mathrm{2NO_2(g) + H_2O(l) \\longrightarrow HNO_3(aq) + HNO_2(aq)}","plain":"3Fe + 4H2O(g) —高温→ Fe3O4 + 4H2；C + H2O(g) —高温→ CO + H2；2NO2 + H2O → HNO3 + HNO2","conditions":"铁与水蒸气需高温；炽热焦炭制水煤气需高温；NO₂ 与水歧化生成硝酸与亚硝酸","pageRef":"化上 p.26–27","note":"F₂ 与水则置换出 O₂（2F₂ + 2H₂O → 4HF + O₂），而不生成次氟酸。"}],"pitfalls":[{"title":"误以为“铁与水蒸气”生成 \\(\\mathrm{Fe_2O_3}\\) 或 \\(\\mathrm{Fe(OH)_3}\\)","wrong":"“\\(\\mathrm{2Fe + 3H_2O(g)} \\xrightarrow{\\text{高温}} \\mathrm{Fe_2O_3 + 3H_2}\\)”或“铁能与冷水反应”。","diagnosis":"铁在金属活动性中属于中等活泼金属，不与冷水反应，仅在高温下与水蒸气反应生成磁性黑色四氧化三铁（\\(\\mathrm{Fe_3O_4}\\)）。","right":"正确方程式为 \\(\\mathrm{3Fe(s) + 4H_2O(g)} \\xrightarrow{\\text{高温}} \\mathrm{Fe_3O_4(s) + 4H_2(g)}\\)。","checkRule":"高温下铁在氧气或水蒸气中氧化的固体产物都是 \\(\\mathrm{Fe_3O_4}\\)。"},{"title":"认为“所有碱性/酸性氧化物都能与水直接化合”","wrong":"“\\(\\mathrm{CuO + H_2O \\to Cu(OH)_2}\\)”以及“\\(\\mathrm{SiO_2 + H_2O \\to H_2SiO_3}\\)”。","diagnosis":"只有少数强碱对应的氧化物（\\(\\mathrm{K_2O, Na_2O, CaO}\\)）及部分酸性氧化物（\\(\\mathrm{CO_2, SO_2, SO_3}\\)）能直接与水化合；绝大多数金属氧化物和二氧化硅不溶于水也不直接反应。","right":"\\(\\mathrm{CuO, Fe_2O_3, SiO_2}\\) 均不能与水直接反应（教材 p.27 明确强调）。","checkRule":"看到氧化铜、氧化铁或石英二氧化硅加水，一律判定“不反应”。"},{"title":"把“无色透明清澈的水”等同于“纯净水”","wrong":"“无色、无味、清澈透明的水就是纯水；青少年长期饮用纯水最有益健康。”","diagnosis":"溶解了可溶性矿物质（如 \\(\\mathrm{Ca^{2+}, Mg^{2+}}\\) 等）的天然水或糖盐水同样无色透明；长期只喝不含矿物质的纯水不利于人体微量元素摄取（p.38 选择题第1题）。","right":"地球上的水大多是溶液；“清澈透明”不是纯净物的判据。","checkRule":"判断纯净水只能看成分单一（只有 \\(\\mathrm{H_2O}\\)），不可看外观清澈。"}],"examples":[{"label":"例 2.1.1","tier":"L2","tierLabel":"L2 校内期末","title":"教材 p.28 思考题 2a(3) & p.38：水煤气炉火变旺与“热冰”概念辨析","prompt":"(1) 在炽热的炭上洒少许水，炉火为什么会忽然间旺起来？写出相关化学方程式。\n(2) 科学家在特殊电场或高压环境中可使常温常压下的水瞬间凝结成冰，俗称“热冰”。下列关于“热冰”的说法正确的是（　）：A. “热冰”是纯净物；B. “热冰”与液态水的化学性质不同；C. 液态水变成“热冰”是化学变化；D. “热冰”在任何条件下都不会融化。","clues":"第(1)问回忆水与炽热炭的反应生成了什么可燃气体；第(2)问判断“水变热冰”分子有没有改变。","strategy":"结合水煤气反应热力学特征与物质三态（同分子物理变化）分析。","given":"炽热炭洒水现象；水变“热冰”物理过程","principle":"水与炽热炭生成可燃性水煤气；同种分子聚集态改变属于物理变化。","steps":["第(1)问：在高温下，水蒸气与炽热的炭反应生成了**一氧化碳（\\(\\mathrm{CO}\\)）和氢气（\\(\\mathrm{H_2}\\)）**（水煤气）：\\(\\mathrm{C(s,}\\text{炽热}\\mathrm{) + H_2O(g)} \\xrightarrow{\\text{高温}} \\mathrm{CO(g) + H_2(g)}\\)。生成的 \\(\\mathrm{CO}\\) 和 \\(\\mathrm{H_2}\\) 均为极易燃烧的气态燃料，在空气中猛烈燃烧放出大量热，所以炉火忽然变旺。","第(2)问：“热冰”本质仍是 \\(\\mathrm{H_2O}\\) 分子构成的固态水（**纯净物**，A 正确）；因分子仍是 \\(\\mathrm{H_2O}\\)，故化学性质与普通水相同（B 错），液态水变热冰只是分子排列间距改变的**物理变化**（C 错），撤去特殊条件或升温仍会融化（D 错）。"],"answer":"(1) 高温生成可燃的 CO 和 H₂（水煤气）燃烧放热使火更旺，方程 \\(\\mathrm{C + H_2O(g)} \\xrightarrow{\\text{高温}} \\mathrm{CO + H_2}\\)；(2) A。","markingPoints":["写出生成水煤气（CO 与 H₂）并配平方程式（2分）","说明可燃气体燃烧使火旺（1分）","正确选 A 并辨析物理变化分子不变（1分）"],"verification":"与教材 p.26、p.28 思考题 2a 及 p.38 选择题第2题完全一致。","pitfall":"若洒过多水会使炉温骤降而熄火，题目特指“洒**少许**水”于“**炽热**炭”上。"},{"label":"例 2.1.2","tier":"L3","tierLabel":"L3 预试必答","title":"教材 p.39 第2、3题综合：五种典型物质与水反应及石蕊试液变色","prompt":"写出下列物质分别与水（或水蒸气）反应的化学方程式，并注明反应条件及反应后所得溶液能否使**紫色石蕊试液**变色（若变色写出颜色）：(1) 金属钾（\\(\\mathrm{K}\\)）；(2) 氟气（\\(\\mathrm{F_2}\\)）；(3) 三氧化硫（\\(\\mathrm{SO_3}\\)）；(4) 氧化铁（III）（\\(\\mathrm{Fe_2O_3}\\)）；(5) 氯化铝晶体（\\(\\mathrm{AlCl_3}\\)）。","clues":"钾与钠同属活泼碱金属；氟气与水发生置换放氧；\\(\\mathrm{Fe_2O_3}\\) 为不溶性碱性氧化物；\\(\\mathrm{AlCl_3}\\) 水解产生 \\(\\mathrm{HCl}\\)。","strategy":"逐一核对教材 p.26–28 五类反应规律，再由生成酸/碱判断石蕊颜色（酸红碱蓝）。","given":"K、F₂、SO₃、Fe₂O₃、AlCl₃ 五种物质与水作用","principle":"酸性溶液使紫色石蕊变红，碱性溶液使紫色石蕊变蓝。","steps":["(1) 钾（冷水剧烈反应）：\\(\\mathrm{2K(s) + 2H_2O(l) \\longrightarrow 2KOH(aq) + H_2(g)}\\)，生成强碱 \\(\\mathrm{KOH}\\)，使紫色石蕊试液变**蓝**。","(2) 氟气：\\(\\mathrm{2F_2(g) + 2H_2O(l) \\longrightarrow 4HF(aq) + O_2(g)}\\)，生成氢氟酸（弱酸），使紫色石蕊试液变**红**。","(3) 三氧化硫：\\(\\mathrm{SO_3(g) + H_2O(l) \\longrightarrow H_2SO_4(aq)}\\)，生成强酸硫酸，使紫色石蕊试液变**红**。","(4) 氧化铁（III）：**不反应**（绝大多数碱性氧化物如 \\(\\mathrm{CuO, Fe_2O_3}\\) 不能与水直接反应），故石蕊仍呈**紫**色不变。","(5) 氯化铝晶体（水解可逆）：\\(\\mathrm{AlCl_3(s) + 3H_2O(l) \\rightleftharpoons Al(OH)_3(s) + 3HCl(aq)}\\)，生成强酸盐酸使溶液显酸性，紫色石蕊变**红**。"],"answer":"方程见步骤；石蕊变色结果：(1) 蓝；(2) 红；(3) 红；(4) 不反应不变色；(5) 红。","markingPoints":["正确写出 (1)(2)(3)(5) 化学方程式（含 F₂ 放 O₂ 与 AlCl₃ 可逆号）（4分）","识别 Fe₂O₃ 不与水直接反应（1分）","正确判断全部溶液酸碱性与石蕊颜色（1分）"],"verification":"对照教材 p.26–28 与 p.39 习题完全吻合。","pitfall":"误写 \\(\\mathrm{F_2 + H_2O \\to HF + HFO}\\)（氟无正价，不会生成类似 HClO 的次氟酸，必放 \\(\\mathrm{O_2}\\)）。"}],"practice":[{"id":"chem2-2.1-q1","tier":"L1","tierLabel":"L1 基础","examStyle":"P1 选择","q":"在 \\(1.01\\times 10^5\\text{ Pa}\\) 压强下，纯水密度达到最大值（\\(1.0000\\text{ g\\,mL}^{-1}\\)）时的温度是（　）。","options":["A. 0 ℃","B. 3.98 ℃","C. 25 ℃","D. 100 ℃"],"correctOption":"B","given":"图 2-4 不同温度下水的密度曲线（化上 p.23–24）","method":"读取教材实测密度峰值温度","principle":"水在 0–3.98 ℃ 间具有反常热缩冷胀特性。","steps":["教材 p.24 及 p.37 明确指出：在 1.01×10⁵ Pa 下，水在 3.98 ℃ 时体积最小、密度最大，为 1.0000 g/mL。"],"ans":"B","markingPoints":["识记 3.98 ℃ 最大密度点"],"verification":"化上 p.23 图2-4 与 p.24 正文。","pitfall":"误选 0 ℃（冰水转换点）。"},{"id":"chem2-2.1-q2","tier":"L2","tierLabel":"L2 期末","examStyle":"P1 选择","q":"下列金属分别与水作用，在**常温冷水**条件下即能剧烈反应生成碱和氢气的是（　）。","options":["A. 钠（Na）","B. 镁（Mg）","C. 铝（Al）","D. 铁（Fe）"],"correctOption":"A","given":"金属与水反应活性分级（化上 p.26，p.38 第3题）","method":"按金属活动性顺序分区判别反应温度","principle":"K、Ca、Na 与冷水反应；Mg、Al、Zn、Fe 需沸水或高温水蒸气。","steps":["教材 p.26 分级表：K、Ca、Na 能与冷水反应；Mg、Al、Zn、Fe 只能与沸水或高温水蒸气反应。"],"ans":"A","markingPoints":["区分冷水反应组与水蒸气反应组"],"verification":"化上 p.26 与 p.38 第3题。","pitfall":"误以为镁或铝也能在冷水中剧烈反应。"},{"id":"chem2-2.1-q3","tier":"L2","tierLabel":"L2 期末","examStyle":"P1 选择","q":"将少量金属钠投入滴有酚酞试液的冷水中，下列对实验现象及对应推论的解释，**错误**的是（　）。","options":["A. 钠浮在水面上 —— 钠的密度小于水","B. 钠熔成闪亮小球 —— 钠与水反应放热且钠熔点较低","C. 钠在水面四处游动并发出“嘶嘶”声 —— 反应生成了氧气推动钠块","D. 溶液变为粉红色 —— 反应生成了碱性物质氢氧化钠"],"correctOption":"C","given":"活动探究1 钠与水反应（化上 p.25）","method":"逐项检验现象与化学产物因果关系","principle":"2Na + 2H₂O → 2NaOH + H₂↑，释放的是氢气而非氧气。","steps":["A、B、D 解释完全正确。","C 错误：钠与水反应放出的气体是**氢气（\\(\\mathrm{H_2}\\)）**，而不是氧气。"],"ans":"C","markingPoints":["准确识别产生气体为氢气"],"verification":"化上 p.25–26。","pitfall":"审题粗心未看清选项 C 中写的是“氧气”。"},{"id":"chem2-2.1-q4","tier":"L3","tierLabel":"L3 预试","examStyle":"P2 简答与方程","q":"请根据教材 p.26–28 水的化学性质完成下列问题：\n(1) 电石（碳化钙，\\(\\mathrm{CaC_2}\\)）常用作矿灯乙炔发生剂，写出其与水反应的化学方程式。\n(2) 工业上可用氯气溶于水配制氯水消毒，写出氯气与水发生可逆反应的方程式；若反应中将 \\(\\mathrm{Cl_2}\\) 换作剧毒非金属 \\(\\mathrm{F_2}\\)，产物有何不同？\n(3) 为什么用白色无水硫酸铜粉末可以检验酒精中是否混有微量水分？写出反应方程式及现象变化。","given":"水与碳化物、卤素及无水 CuSO₄ 的反应","method":"直接写出配平化学方程式并说明颜色/产物特征","principle":"电石水解、卤素与水反应差异、结晶水合物显色。","steps":["(1) \\(\\mathrm{CaC_2(s) + 2H_2O(l) \\longrightarrow Ca(OH)_2(s) + C_2H_2(g)}\\)。","(2) 氯气与水：\\(\\mathrm{Cl_2(g) + H_2O(l) \\rightleftharpoons HCl(aq) + HClO(aq)}\\)；而氟气极活泼，与水剧烈反应不生成次氟酸，而是置换出氧气：\\(\\mathrm{2F_2(g) + 2H_2O(l) \\longrightarrow 4HF(aq) + O_2(g)}\\)。","(3) \\(\\mathrm{CuSO_4(s) + 5H_2O(l) \\longrightarrow CuSO_4\\cdot 5H_2O(s)}\\)；原本白色的无水硫酸铜结合水分子后变成**蓝色**的五水合硫酸铜晶体，现象极其敏锐。"],"ans":"见步骤三组配平方程式与白变蓝现象。","markingPoints":["CaC₂ 方程正确配平（1分）","Cl₂ 可逆方程与 F₂ 放 O₂ 对比正确（2分）","CuSO₄·5H₂O 方程及白色变蓝色现象（2分）"],"verification":"与化上 p.26–27 原方程一字不差。","pitfall":"写 \\(\\mathrm{CuSO_4}\\) 检水只写“变蓝”而漏写水合物化学式 \\(\\mathrm{CuSO_4\\cdot 5H_2O}\\)。"},{"id":"chem2-2.1-q5","tier":"L4","tierLabel":"L4 统考综合","examStyle":"P2 实验与计算","q":"某同学在实验室将 \\(16.8\\text{ g}\\) 洁净铁粉装入耐高温玻璃管中，在高温下通入足量水蒸气使其充分反应，直至固体质量不再变化。反应化学方程式为 \\(\\mathrm{3Fe(s) + 4H_2O(g)} \\xrightarrow{\\text{高温}} \\mathrm{Fe_3O_4(s) + 4H_2(g)}\\)（已知 \\(A_r(\\mathrm{Fe})=56, A_r(\\mathrm{O})=16, A_r(\\mathrm{H})=1\\)）。\n(1) 试计算最终生成的固体 \\(\\mathrm{Fe_3O_4}\\) 质量及生成 \\(\\mathrm{H_2}\\) 的物质的量；\n(2) 若实验结束冷却后，某同学误把 \\(\\mathrm{CO_2}\\) 气体代替水蒸气在常温下通入装有固体产物的玻璃管并认为会继续反应，请结合碳、氮、硅氧化物与水的性质，列举两种**能**与水化合生成酸的氧化物和一种**不能**与水化合的非金属氧化物。","given":"m(Fe) = 16.8 g，M(Fe) = 56 g/mol，M(Fe₃O₄) = 232 g/mol","method":"先求 n(Fe)，再按 3 : 1 : 4 计量比计算 Fe₃O₄ 与 H₂；结合 p.27 氧化物与水反应规律作答","principle":"化学计量守恒与酸性氧化物和水的反应特性。","steps":["第(1)问：参加反应的铁粉物质的量 \\(n(\\mathrm{Fe}) = \\frac{16.8\\text{ g}}{56\\text{ g/mol}} = 0.300\\text{ mol}\\)。","由方程式 \\(3\\mathrm{Fe} : 1\\mathrm{Fe_3O_4} : 4\\mathrm{H_2}\\) 得：\\(n(\\mathrm{Fe_3O_4}) = 0.100\\text{ mol}\\)，故 \\(m(\\mathrm{Fe_3O_4}) = 0.100\\text{ mol} \\times 232\\text{ g/mol} = 23.2\\text{ g}\\)。","生成氢气物质的量：\\(n(\\mathrm{H_2}) = \\frac{4}{3} \\times 0.300\\text{ mol} = 0.400\\text{ mol}\\)。","第(2)问：能与水化合生成酸的非金属氧化物（酸酐）如 \\(\\mathrm{CO_2, SO_2, SO_3}\\)（以及 \\(\\mathrm{NO_2}\\) 生成两酸，任举两种）；**不能**与水直接化合的非金属氧化物如 **\\(\\mathrm{SiO_2}\\)**（二氧化硅，或 \\(\\mathrm{CO}\\)）。"],"ans":"(1) 23.2 g Fe₃O₄，0.400 mol H₂；(2) 能反应：CO₂、SO₂/SO₃（或 NO₂）；不能反应：SiO₂。","markingPoints":["算出 n(Fe) = 0.300 mol（1分）","求得 m(Fe₃O₄) = 23.2 g 与 n(H₂) = 0.400 mol（2分）","正确列举能与水反应及不与水反应的非金属氧化物（2分）"],"verification":"质量守恒校核：增重氧 \\(23.2 - 16.8 = 6.4\\text{ g} = 0.400\\text{ mol O}\\)，恰好对应分解 \\(0.400\\text{ mol }\\mathrm{H_2O}\\) 放出 \\(0.400\\text{ mol }\\mathrm{H_2}\\)。","pitfall":"误把 \\(\\mathrm{Fe_3O_4}\\) 式量算成 160（那是 \\(\\mathrm{Fe_2O_3}\\)）而非 \\(3\\times 56 + 4\\times 16 = 232\\)。"}],"cheatSheet":["水的三大反常：**3.98 ℃ 密度最大**（1.0000 g/mL，冰浮水面护生态）、**比热最大**（4.18×10³ J/(kg·K)，沿海温差小）、**bp 100 ℃**（高于同式量 CH₄/NH₃）。","钠与水五字现象：**浮**（密度小）、**熔**（放热熔点低）、**游·响**（产 H₂）、**红**（NaOH 使酚酞变红）。","反应速记：\\(\\mathrm{3Fe + 4H_2O(g) \\to Fe_3O_4 + 4H_2}\\)；\\(\\mathrm{C + H_2O(g) \\to CO + H_2}\\)；\\(\\mathrm{2F_2+2H_2O\\to 4HF+O_2}\\)；\\(\\mathrm{2NO_2+H_2O\\to HNO_3+HNO_2}\\)；\\(\\mathrm{CuO, Fe_2O_3, SiO_2}\\) 不与水反应。"],"kbEntryIds":["kb-chem2-water-physical","kb-chem2-water-chemical"],"quiz":{"q":"将白色的无水硫酸铜（II）粉末加入少量含水液体中，粉末变成什么颜色？写出反应的化学方程式。","given":"化上 p.27 盐类与水的结晶水合反应","method":"利用无水 CuSO₄ 检验水的特征反应","principle":"CuSO₄ 结合 5 个结晶水分子形成蓝色的胆矾晶体。","steps":["现象：白色粉末变为蓝色晶体。","方程式：\\(\\mathrm{CuSO_4(s) + 5H_2O(l) \\longrightarrow CuSO_4\\cdot 5H_2O(s)}\\)。"],"ans":"蓝色；\\(\\mathrm{CuSO_4(s) + 5H_2O(l) \\longrightarrow CuSO_4\\cdot 5H_2O(s)}\\)"}},{"id":"2.2","t":"成水元素之一——氢元素","anchor":{"pages":"化上 p.29–36","syllabus":"活动2 水的电解 · 2.2.1 氢气的制取 · 2.2.2 氢气的性质 · 2.2.3 氢气的用途","examScopes":["uec"],"examWeight":"全章实验重头戏！P1 + P2 必考电解水、实验室制氢、验纯与 H₂ 还原 CuO","terms":"electrolysis · reactivity series · water gas · explosion limit · reduction · hydrogen energy","prerequisites":["第1章化合物分解概念与 2.1 金属活动性初步分级","第1节水的元素组成认识"],"goals":["描述活动2电解水实验步骤、现象及两极气体检验，阐明“水由氢元素和氧元素组成”。","熟记金属活动性顺序（图 2-10），解释实验室选 Zn+稀酸制氢的原因，并写出工业制氢三大路线方程式。","掌握氢气验纯操作、4%–74% 爆炸极限及 H₂ 还原 CuO 的“先通后点、先熄后停”操作铁律。","列举氢气的主要化工用途及氢能源的六大清洁优势（含热值 142 351 kJ/kg）。"]},"concepts":[{"kind":"experiment","title":"活动2：水的电解（图2-9）及双装置对比（p.39 第4题）","pageRef":"化上 p.29、p.39–40","body":["**实验关键**：纯水导电性极弱，向水中加入少量**稀硫酸或氢氧化钠**可**增强水的导电性**（p.40 第8(1)题：使气泡产生又多又快）。接通直流电（碳棒作电极）后：","- **阳极（接电源正极，液面下降较少）**：产生体积较小的气体，能使**带余烬的木条复燃**，证明是**氧气（\\(\\mathrm{O_2}\\)）**。","- **阴极（接电源负极，液面下降较多）**：产生体积约为氧气 **2 倍** 的气体，用点燃火柴移近尖嘴处可燃烧产生**淡蓝色火焰**，上方罩干燥烧杯内壁出现水珠（可使白色无水 \\(\\mathrm{CuSO_4}\\) 变蓝），证明是**氢气（\\(\\mathrm{H_2}\\)）**。","**装置甲 vs 装置乙优缺点对比（p.39 第4题）**：装置甲（倒立试管）**装置简单、操作方便**；装置乙（霍夫曼水电解器/带活塞与刻度管）**能直接读取气体体积比且通过尖嘴活塞便于随时放气验纯与检验产物**。"],"takeaway":"口诀：**正氧负氢，体积比 1:2**（质量比仍为 8:1）。结论：水是由**氢元素和氧元素**组成的，不可说“水是由氢气和氧气组成的”。"},{"kind":"experiment","title":"2.2.1 氢气的实验室制法（活动3）与工业三大路线","pageRef":"化上 p.30–32、p.36","body":["**金属活动性顺序（图2-10）**：`K Ca Na Mg Al Zn Fe Sn Pb (H) Cu Hg Ag Pt Au`。排在 **(H) 前面** 的金属能与稀盐酸或稀硫酸置换出 \\(\\mathrm{H_2}\\)（注意 **Pb** 与稀盐酸/稀硫酸会生成难溶保护膜，不能有效持续反应），排在后面的 Cu..Au 不反应。","**为什么实验室选 Zn 而不选 Mg 或 Fe？（p.36 思考题 2b(1)）**：Mg 反应过于剧烈难以收集控制（且成本高），Fe 反应速率太慢；**Zn** 反应速率适中、平稳易收集（常用 \\(\\mathrm{Zn + 2HCl \\to ZnCl_2 + H_2}\\uparrow\\) 或 \\(\\mathrm{Zn + H_2SO_4(\\text{稀}) \\to ZnSO_4 + H_2}\\uparrow\\)）。另 **Zn、Al** 也可与浓 \\(\\mathrm{NaOH}\\) 溶液反应制氢（如集市充气球）：\\(\\mathrm{Zn + 2NaOH \\to Na_2ZnO_2 + H_2}\\uparrow\\)，\\(\\mathrm{2Al + 2NaOH + 2H_2O \\to 2NaAlO_2 + 3H_2}\\uparrow\\)。","**工业制氢三大路线（p.31–32）**：①**焦炭水煤气法**（\\(1000\\ ^\\circ\\mathrm{C}\\) 制 \\(\\mathrm{CO+H_2}\\)，再在 \\(\\mathrm{Fe_2O_3}\\) 催化 \\(500\\ ^\\circ\\mathrm{C}\\) 下使 \\(\\mathrm{CO + H_2O(g) \\to CO_2 + H_2}\\)，加压水洗除 \\(\\mathrm{CO_2}\\)）；②**天然气甲烷重整**（\\(800\\text{--}900\\ ^\\circ\\mathrm{C}\\)，Ni 催化，\\(\\mathrm{CH_4 + H_2O(g) \\to CO + 3H_2}\\)，再同样变换除 \\(\\mathrm{CO_2}\\)）；③**电解饱和食盐水**（纯度高达 **99.5%–99.8%**）：\\(\\mathrm{2NaCl + 2H_2O \\xrightarrow{\\text{电解}} 2NaOH + H_2 + Cl_2}\\)。"],"takeaway":"实验室制氢选 Zn + 稀硫酸/稀盐酸（不可用浓硫酸或硝酸）；工业高纯氢用电解法，廉价大量氢用煤/甲烷重整转化。"},{"kind":"mechanism","title":"2.2.2 氢气的性质：验纯、爆炸极限与还原金属氧化物","pageRef":"化上 p.32–35、p.40","body":["**物理性质与收集**：标准状况下最轻的气体（\\(\\rho = 0.0899\\text{ kg\\,m}^{-3}\\)），无色无味无毒、难溶于水（可用**排水法**或**向下排空气法**收集）；\\(-252.7\\ ^\\circ\\mathrm{C}\\) 液化，\\(-259.0\\ ^\\circ\\mathrm{C}\\) 呈白色固体。","**爆炸极限与验纯（图2-12, p.33–34）**：氢气与空气或氧气混合在体积分数 **4%–74%** 范围内点燃会发生支链爆炸。点燃前必用**小试管管口朝下、拇指堵住移近酒精灯火焰**：听到尖锐爆鸣声表明不纯，听到轻微“噗”声表明纯净。","**化学性质三层面**：","- (1) **与非金属反应**：\\(\\mathrm{2H_2 + O_2 \\xrightarrow{\\text{点燃}} 2H_2O(g)}\\)（淡蓝色火焰）、\\(\\mathrm{H_2 + Cl_2 \\xrightarrow{\\text{光照}} 2HCl}\\)、\\(\\mathrm{H_2 + S(g) \\rightleftharpoons H_2S}\\)、\\(\\mathrm{3H_2 + N_2 \\xrightleftharpoons{\\text{高温高压催化剂}} 2NH_3}\\)。","- (2) **与活泼金属反应生成离子型氢化物**：高温下生成白色高熔点导电固体 \\(\\mathrm{LiH, NaH, CaH_2}\\)，遇水剧烈释放大量氢气（如 \\(\\mathrm{CaH_2 + 2H_2O \\to Ca(OH)_2 + 2H_2}\\uparrow\\)）。","- (3) **还原金属氧化物（p.34–35）**：\\(\\mathrm{CuO(s) + H_2(g) \\xrightarrow{\\Delta} Cu(s) + H_2O(g)}\\)（**黑色固体变红褐色**，管口有水珠）；\\(\\mathrm{Fe_3O_4 + 4H_2 \\xrightarrow{\\Delta} 3Fe + 4H_2O(g)}\\)。注意：**实验前先通 \\(\\mathrm{H_2}\\) 排空气再加热**（防爆炸），**结束后先熄灭酒精灯继续通 \\(\\mathrm{H_2}\\) 至冷却**（防炽热铜重新氧化变黑）。"],"takeaway":"记忆 H₂ 还原 CuO 八字口诀：**氢气早出晚归，酒精灯迟到早退**。"},{"kind":"table","title":"2.2.3 氢气的用途与氢能源六大核心特点","pageRef":"化上 p.35–36","body":["物质的性质决定用途；氢气作为 21 世纪理想清洁能源具备六大独特优势："],"table":{"headers":["用途类别（p.35）","所利用的氢气性质","氢能源六大特点（p.35–36 资料链接）"],"rows":[["探空气球（早期）/ 导热冷却","密度最小（0.0899 kg·m⁻³，已逐步改用更安全的氦气）","①密度最小 ②导热性最好（比多数气体高 10 倍）"],["氢氧焰切割焊接、火箭高能燃料","可燃性且燃烧热值极高（产物无污染）","④除核燃料外热值最高（142 351 kJ·kg⁻¹，为汽油 3 倍）⑤点燃快、燃速快"],["冶炼金属（Cu、W）与制备高纯硅","高温还原性（夺取氧化物中的氧）","③可循环回收利用（燃烧生成的水可再次电解制氢）"],["合成氨/盐酸、植物油氢化制人造奶油、合成甲醇","可与 N₂、Cl₂、CO 及不饱和植物油发生化学反应","⑥无毒最清洁（产物只有水，无 CO、SO₂、铅与粉尘，无腐蚀）"]]}}],"diagrams":[{"src":"assets/fig/v2/chem02-h2-prep.svg","caption":"图 2-1 实验室制氢、收集、验纯及 H₂ 还原 CuO 装置与防爆操作铁律（化上 p.30–35）","alt":"实验室Zn与稀硫酸制氢、排水法与向下排空气法收集、验纯及氢气还原氧化铜流程图","pageRef":"化上 p.30–35"}],"formulas":[{"title":"电解水与工业制氢核心方程式","tex":"\\mathrm{2H_2O(l)} \\xrightarrow{\\text{电解}} \\mathrm{2H_2(g) + O_2(g)},\\qquad \\mathrm{CH_4(g) + H_2O(g)} \\xrightarrow[800\\text{--}900\\ ^\\circ\\mathrm{C}]{\\mathrm{Ni}} \\mathrm{CO(g) + 3H_2(g)}","plain":"2H2O —电解→ 2H2 + O2；CH4 + H2O(g) —Ni,800–900°C→ CO + 3H2","conditions":"电解水加少量稀 H₂SO₄ 或 NaOH 增强导电性；甲烷水蒸气重整需 Ni 催化","pageRef":"化上 p.29、p.31","note":"饱和食盐水电解：2NaCl + 2H₂O —电解→ 2NaOH + H₂↑ + Cl₂↑（纯度 99.5%–99.8%）。"},{"title":"氢气的还原性及金属氢化物生氢反应","tex":"\\mathrm{CuO(s) + H_2(g)} \\xrightarrow{\\Delta} \\mathrm{Cu(s) + H_2O(g)},\\qquad \\mathrm{CaH_2(s) + 2H_2O(l) \\longrightarrow Ca(OH)_2(s) + 2H_2(g)}","plain":"CuO + H2 —Δ→ Cu + H2O；CaH2 + 2H2O → Ca(OH)2 + 2H2","conditions":"还原 CuO 须先通气后加热、先熄灯后停气；CaH₂ 常作野外便携生氢剂","pageRef":"化上 p.34–35、p.40","note":"教材 p.40 亦考查 WO₃ + 3H₂ —Δ→ W + 3H₂O 及 Fe₃O₄ + 4H₂ —Δ→ 3Fe + 4H₂O。"}],"pitfalls":[{"title":"误以为氢气能还原排在 (H) 前面活泼金属的氧化物（如 CaO、Na₂O）","wrong":"“\\(\\mathrm{H_2}\\) 能将加热的 \\(\\mathrm{CaO}\\) 或 \\(\\mathrm{Na_2O}\\) 还原成金属钙或钠并生成水。”","diagnosis":"钠、钙等极活泼金属对氧的结合力远强于氢，且即便生成钠/钙也会立即与水蒸气剧烈反应重新变成碱和氢（教材 p.38 第8题原题陷阱）。","right":"氢气通常只还原较不活泼或中等活泼金属的氧化物，如 **\\(\\mathrm{CuO, Fe_3O_4, WO_3}\\)**，不能用 \\(\\mathrm{H_2}\\) 还原 \\(\\mathrm{CaO, Na_2O}\\)。","checkRule":"看到加热金属 M 氧化物通干燥 H₂ 出现液滴，M 选 Fe、Cu、W，排除 K、Ca、Na。"},{"title":"验纯时试管口朝上或不用拇指堵住，或用刚刚验纯的试管直接再去集气","wrong":"“收集氢气验纯时将试管口朝上移近酒精灯；若听到尖锐爆鸣声，立刻把同一支试管拿回导气管口继续收集。”","diagnosis":"H₂ 密度远小于空气，管口朝上会瞬间向上逃逸导致误判；若未先熄灭管内可能残留的隐形火焰就重新接导管，极易引燃发生爆炸（p.36 思考题 2b(2)）。","right":"正确验纯必须**管口朝下、拇指堵住**移近火焰；若发出尖锐爆鸣声，须用拇指按紧熄灭残火（或另换一支洁净试管）后再收集检验。","checkRule":"牢记口诀：向下排空气、管口朝下拇指堵、听“噗”声才纯净。"},{"title":"混淆“氢气性质”与“不上升肥皂泡/铜又变黑”实验误差原因","wrong":"“用氢气吹的肥皂泡不上升是因为氢气密度变大了；还原 CuO 后铜变黑是因为加热温度不够。”","diagnosis":"教材 p.40 第8题明确考这两个真实故障：肥皂泡不上升说明氢气中混入了较多密度较大的空气（不纯）或气体太湿重；生成的红铜又变黑是因为**未等冷却就停止通 \\(\\mathrm{H_2}\\)**，空气进入与炽热铜重新反应生成黑色 \\(\\mathrm{CuO}\\)。","right":"肥皂泡不上升 → 氢气**不纯**（混有大量空气，平均密度大于空气）；铜重变黑 → **先停氢后冷却**，高温铜被氧气再次氧化。","checkRule":"还原金属实验后固体变回原色，永远第一时间检查“冷却过程中是否保持保护气/还原气流通”。"}],"examples":[{"label":"例 2.2.1","tier":"L2","tierLabel":"L2 校内期末","title":"教材 p.39 第4题：电解水甲、乙两装置评估与实验进程判断","prompt":"实验室常用如图甲（水中插两倒置装满水试管）和图乙（带刻度和尖嘴活塞的霍夫曼电解器）两套装置电解水。(1) 请各写出装置甲和装置乙的一个明显优点；(2) 若实验开始前在水中加入少量稀 \\(\\mathrm{H_2SO_4}\\)，目的是什么？(3) 若装置甲中左管（接正极，标 A）收集到 \\(6\\text{ mL}\\) 气体，右管（接负极，标 B）中应收集到多少体积气体？如何用简便方法检验两管气体？","clues":"正极氧、负极氢，体积比 1:2；稀硫酸提供自由移动离子增强导电性。","strategy":"结合装置结构特点评价优缺点，再利用电解定量比例与气体特性作答。","given":"V(A, 正极) = 6 mL，装置甲与装置乙","principle":"电解水 2H₂O —电解→ 2H₂↑ + O₂↑，同温同压体积比 2:1。","steps":["第(1)问：装置甲的优点是**仪器简单、取材容易、操作方便**；装置乙的优点是**有刻度便于准确对比两极气体体积比，且带有活塞尖嘴方便随时放气检验产物**。","第(2)问：加入少量稀 \\(\\mathrm{H_2SO_4}\\)（或 \\(\\mathrm{NaOH}\\)）是为了**增强水的导电性**（加速电解）。","第(3)问：A 管接正极（阳极）收集 **\\(\\mathrm{O_2}\\)**（\\(6\\text{ mL}\\)）；B 管接负极（阴极）收集 **\\(\\mathrm{H_2}\\)**，理论体积为 \\(2\\times 6 = 12\\text{ mL}\\)。检验方法：A 管气体用**带余烬的木条**（木条复燃）；B 管气体先验纯后用**燃着的木条/火柴**点燃（产生淡蓝色火焰，干冷烧杯内壁有水珠）。"],"answer":"(1) 甲：装置简单；乙：便于读取体积比及尖嘴检气。(2) 增强水的导电性。(3) B 管 12 mL H₂；O₂ 用带余烬木条复燃，H₂ 用燃着火柴呈淡蓝色火焰。","markingPoints":["准确说出甲、乙装置各自核心优点（2分）","答出增强导电性（1分）","算得 B 管 12 mL 并正确写出氧/氢两气体检验法（2分）"],"verification":"与教材 p.29 活动2 及 p.39 第4题完全对应。","pitfall":"在检验 \\(\\mathrm{H_2}\\) 与 \\(\\mathrm{O_2}\\) 时搞反“燃着的木条”与“带余烬的木条”。"},{"label":"例 2.2.2","tier":"L4","tierLabel":"L4 统考压轴","title":"教材 p.39 第9题拓展：Zn 与稀盐酸反应的限量图像与制氢纯度计算","prompt":"向一定质量分数的稀盐酸中分批加入金属锌粒，测得加入锌的质量与产生氢气质量的关系如教材 p.39 第9题折线图所示（拐点 \\(P\\) 坐标为横轴 \\(a\\text{ g}\\) 锌、纵轴 \\(b\\text{ g}\\) 氢气）。已知某次实验中测得拐点横坐标 \\(a = 13.0\\text{ g}\\)（\\(A_r(\\mathrm{Zn})=65, A_r(\\mathrm{H})=1, A_r(\\mathrm{Cl})=35.5\\)）。\n(1) 拐点 \\(P(a, b)\\) 以及区间 \\(m(\\mathrm{Zn}) > a\\) 分别有什么化学意义？\n(2) 求纵坐标 \\(b\\) 的数值以及原稀盐酸中所含纯 \\(\\mathrm{HCl}\\) 的质量。\n(3) 若改用含不反应杂质 \\(20\\%\\) 的粗锌颗粒代替纯锌去恰好中和该份稀盐酸，至少需要投料多少克粗锌？","clues":"拐点 \\(P\\) 是恰好完全反应点；\\(m(\\mathrm{Zn}) > a\\) 时盐酸已耗尽、锌过量。","strategy":"由拐点 \\(a=13.0\\text{ g}\\) 算出 \\(n(\\mathrm{Zn})\\)，据 \\(\\mathrm{Zn + 2HCl \\to ZnCl_2 + H_2}\\uparrow\\) 求 \\(b\\) 和 \\(m(\\mathrm{HCl})\\)，再除以纯度 \\(80\\%\\)。","given":"Zn + 2HCl → ZnCl₂ + H₂↑，拐点 m(Zn) = 13.0 g，粗锌纯度 80%","principle":"化学计量关系与定量—过量拐点图像解析。","steps":["第(1)问：拐点 \\(P(a, b)\\) 表示 **\\(a\\text{ g}\\) 锌与该份稀盐酸恰好完全反应，生成 \\(b\\text{ g}\\) 氢气**；当 \\(m(\\mathrm{Zn}) > a\\) 时，曲线呈水平线，表示**稀盐酸已完全消耗完（限量），加入的锌过量**，故氢气不再增加。","第(2)问：在 \\(P\\) 点，\\(n(\\mathrm{Zn}) = \\frac{13.0\\text{ g}}{65\\text{ g/mol}} = 0.200\\text{ mol}\\)。","由 \\(\\mathrm{Zn + 2HCl \\longrightarrow ZnCl_2 + H_2}\\uparrow\\) 得：","- 生成氢气：\\(n(\\mathrm{H_2}) = n(\\mathrm{Zn}) = 0.200\\text{ mol}\\)，故 \\(b = 0.200 \\times 2.0 = 0.40\\text{ g}\\)。","- 消耗纯 \\(\\mathrm{HCl}\\)：\\(n(\\mathrm{HCl}) = 2 \\times 0.200 = 0.400\\text{ mol}\\)，故 \\(m(\\mathrm{HCl}) = 0.400 \\times 36.5 = 14.6\\text{ g}\\)。","第(3)问：杂质含量 \\(20\\%\\)，即粗锌纯度为 \\(1 - 20\\% = 80\\%\\)，故所需粗锌质量：\\(m_{\\text{粗锌}} = \\frac{13.0\\text{ g}}{80\\%} = 16.25\\text{ g}\\)。"],"answer":"(1) P 点：a g Zn 与 HCl 恰好完全反应生成 b g H₂；m > a：HCl 耗尽、Zn 过量；(2) b = 0.40 g，纯 HCl 14.6 g；(3) 16.25 g 粗锌。","markingPoints":["准确解释拐点 P 与水平平台意义（2分）","求得 b = 0.40 g 及 m(HCl) = 14.6 g（2分）","正确折算纯度 80% 求得粗锌 16.25 g（1分）"],"verification":"\\(16.25 \\times 0.80 = 13.0\\text{ g}\\)，恰好消耗 \\(0.40\\text{ mol HCl}\\) 产 \\(0.40\\text{ g }\\mathrm{H_2}\\)，无误。","pitfall":"误把“含杂质 20%”直接当纯度 20% 除（应该是 \\(1 - 20\\% = 80\\%\\)）。"}],"practice":[{"id":"chem2-2.2-q1","tier":"L1","tierLabel":"L1 基础","examStyle":"P1 选择","q":"氢气与其他气体相比，最显著的物理特点是（　）。","options":["A. 无色、无味","B. 难溶于水","C. 可以燃烧","D. 密度最小"],"correctOption":"D","given":"氢气的物理性质（化上 p.32，p.38 第5题）","method":"对照“最显著特点”与“物理特点”双限定","principle":"H₂ 是自然界密度最小的气体（0.0899 kg/m³）。","steps":["A、B 很多气体（如 N₂、CH₄）都具备；C 属于化学性质；D 密度最小是氢气独一无二的最显著物理特点。"],"ans":"D","markingPoints":["识别最显著物理特征"],"verification":"教材 p.38 第5题原题。","pitfall":"误选 C（可燃性是化学性质且非独有）。"},{"id":"chem2-2.2-q2","tier":"L2","tierLabel":"L2 期末","examStyle":"P1 选择","q":"下列实验操作或反应中，**不能**生成氢气的是（　）。","options":["A. 通直流电电解加有少量稀硫酸的水","B. 将水蒸气通过灼热的铜丝","C. 金属铝片与浓氢氧化钠溶液反应","D. 将水蒸气通过炽热的焦炭"],"correctOption":"B","given":"氢气生成途径辨析（化上 p.26–31，p.38 第6题）","method":"核对金属活动性顺序及制氢反应条件","principle":"Cu 排在 (H) 后面，与沸水和水蒸气均不反应。","steps":["A 电解水产生 H₂ 和 O₂；C 铝与强碱生成 NaAlO₂ 和 H₂；D 焦炭与高温水蒸气生成水煤气 CO + H₂。","B 不能生成：铜活动性排在氢之后，无论冷水还是高温水蒸气都不反应。"],"ans":"B","markingPoints":["运用金属活动性顺序判断铜不与水蒸气反应"],"verification":"教材 p.38 第6题原题。","pitfall":"误以为铝不会与氢氧化钠反应（Al 与 Zn 为两性金属，可与浓 NaOH 反应放 H₂，p.30）。"},{"id":"chem2-2.2-q3","tier":"L2","tierLabel":"L2 期末","examStyle":"P1 选择","q":"甲、乙两位同学检验新收集氢气的纯度（p.36 思考题 2b(2)）：\n甲同学：先将集有氢气的小试管口朝上，再用拇指堵住管口移近火焰，松开拇指，只听到轻微“噗”声，她认为该氢气纯净。\n乙同学：将集有氢气的小试管口朝下，不用拇指堵住管口直接移近火焰，听到尖锐爆鸣声，他认为该氢气不纯。\n对甲、乙两位同学操作的科学评价是（　）。","options":["A. 甲完全正确，乙操作错误","B. 乙完全正确，甲操作错误","C. 甲和乙均存在操作缺陷：甲管口朝上易致氢气逃逸，乙未用拇指堵口不够安全","D. 甲和乙均完全正确，都能准确检出纯度"],"correctOption":"C","given":"氢气验纯规范操作（化上 p.33 图2-12，p.36）","method":"核对“管口朝下”与“拇指堵口”双规范","principle":"H₂ 密度比空气小（须口朝下防逃逸）+ 堵口靠近火焰后再松开可防未点燃前混入过多空气。","steps":["甲错在“管口朝上”——氢气密度最小会迅速逸散出管外，导致听不到爆鸣声而误判为纯净！","乙错在“不用拇指堵住管口”——移近火焰过程中空气与氢气对流混合，易发生危险，且不符合图 2-12 规范操作。"],"ans":"C","markingPoints":["同时指出甲朝上漏气与乙未堵口隐患"],"verification":"对照 p.33 图2-12 及 p.36 思考题 2b(2)。","pitfall":"只看现象结论对错而忽略甲的“管口朝上”致命假阴性操作。"},{"id":"chem2-2.2-q4","tier":"L3","tierLabel":"L3 预试","examStyle":"P2 实验故障诊断","q":"结合教材 p.34–35 与 p.40 第8题，请用简明化学原理回答下列三个实验现象的原因：\n(1) 某同学用氢气还原氧化铜（II）时，黑色粉末已完全变成亮丽的红褐色铜，但停止实验一会儿后，管内的铜表面又变回了黑色，原因是什么？\n(2) 为什么工业上常用天然气（甲烷）或水煤气在高温下制取氢气时，产物里常含有 \\(\\mathrm{CO, CO_2}\\) 等杂质，而水力发电发达国家采用电解法制得的氢气纯度可达 \\(99.5\\%\\text{--}99.8\\%\\)？请写出电解饱和食盐水制氢的化学方程式。\n(3) 为什么氢气被公认为最理想的清洁能源之一？（写出任意三点，含热值特点）","given":"H₂ 还原 CuO 故障、工业制氢对比、氢能源特点","method":"紧扣“保护气冷却顺序”“电解无碳副产”“氢能源六大特点”","principle":"高温铜易与氧气化合；电解水/盐水只产生气体分子无含碳杂质。","steps":["(1) 原因是**先停止通入氢气（或未等铜冷却就撤走氢气流）**，空气进入试管，在较高温度下炽热的红褐色铜与空气中的氧气重新反应生成了黑色的氧化铜（\\(\\mathrm{2Cu + O_2 \\xrightarrow{\\Delta} 2CuO}\\)）。","(2) 因为焦炭水煤气法与甲烷重整法均使用含碳原料并经过中间体 \\(\\mathrm{CO/CO_2}\\)，分离后难免残留微量含碳气体；而电解饱和食盐水：\\(\\mathrm{2NaCl(aq) + 2H_2O(l)} \\xrightarrow{\\text{电解}} \\mathrm{2NaOH(aq) + H_2(g) + Cl_2(g)}\\)，产物在两极各自逸出且无碳参与，故纯度极高。","(3) 氢能源优势（任选三点）：①燃烧产物只有水，无毒、无任何污染物且可循环制氢；②除核燃料外热值最高（\\(142\\,351\\text{ kJ\\,kg}^{-1}\\)，为汽油 3 倍）；③密度最小、导热性最好、点燃快燃烧性能好。"],"ans":"(1) 铜未冷却前先停 H₂，空气进入使其重新氧化为黑色 CuO；(2) 方程 \\(\\mathrm{2NaCl + 2H_2O \\xrightarrow{\\text{电解}} 2NaOH + H_2 + Cl_2}\\)；(3) 无毒零污染只生成水、可回收循环、热值最高（142 351 kJ/kg）。","markingPoints":["指出未冷却即停 H₂ 导致热铜被 O₂ 再氧化（2分）","写出电解饱和食盐水配平方程式（2分）","准确列出三项氢能源特点含热值或零污染（2分）"],"verification":"逐条核对化上 p.31–36 与 p.40 原题。","pitfall":"第(1)问只答“氧化铜没还原完”而未解释“先变红后**又**变黑”的逆转原因。"},{"id":"chem2-2.2-q5","tier":"L4","tierLabel":"L4 统考综合","examStyle":"P2 转化与定量探究","q":"（改编自教材 p.40 第5、10题）(1) 写出物质转化链 \\(\\mathrm{H_2O} \\xrightarrow{(1)} \\mathrm{H_2} \\xrightarrow{(2)} \\mathrm{HCl} \\xrightarrow{(3)} \\mathrm{H_2} \\xrightarrow{(4)} \\mathrm{H_2O}\\) 四步反应的化学方程式（注明条件）。\n(2) 登山队员常携带固体氢化钙（\\(\\mathrm{CaH_2}\\)）作便携式生氢剂：\\(\\mathrm{CaH_2(s) + 2H_2O(l) \\longrightarrow Ca(OH)_2(s) + 2H_2(g)}\\)。若要迅速制得 \\(4.0\\text{ g}\\) 氢气用于野外燃料（\\(A_r(\\mathrm{Ca})=40, A_r(\\mathrm{H})=1\\)），理论上需要消耗多少克纯 \\(\\mathrm{CaH_2}\\)？若改用锌与足量稀盐酸反应制取同样质量的氢气，需消耗纯锌（\\(A_r(\\mathrm{Zn})=65\\)）多少克？比较两者质量，说明登山队为何优先携带 \\(\\mathrm{CaH_2}\\)。","given":"m(H₂) = 4.0 g；M(CaH₂) = 42 g/mol，M(Zn) = 65 g/mol","method":"分别按 1 mol CaH₂ → 2 mol H₂ 与 1 mol Zn → 1 mol H₂ 求出所需固体质量再比轻便度","principle":"氢的循环转化链与相同产氢量下的质量效率比较。","steps":["第(1)问四步方程式：","- ① \\(\\mathrm{2H_2O(l)} \\xrightarrow{\\text{电解}} \\mathrm{2H_2(g) + O_2(g)}\\)；","- ② \\(\\mathrm{H_2(g) + Cl_2(g)} \\xrightarrow{\\text{光照或点燃}} \\mathrm{2HCl(g)}\\)；","- ③ \\(\\mathrm{Zn(s) + 2HCl(aq) \\longrightarrow ZnCl_2(aq) + H_2(g)}\\)（或用 Fe、Mg 等活泼金属）；","- ④ \\(\\mathrm{2H_2(g) + O_2(g)} \\xrightarrow{\\text{点燃}} \\mathrm{2H_2O(l)}\\)（或 \\(\\mathrm{CuO + H_2 \\xrightarrow{\\Delta} Cu + H_2O}\\)）。","第(2)问计算：需要氢气物质的量 \\(n(\\mathrm{H_2}) = \\frac{4.0\\text{ g}}{2.0\\text{ g/mol}} = 2.0\\text{ mol}\\)。","- 用 \\(\\mathrm{CaH_2}\\)：由 \\(1\\text{ mol }\\mathrm{CaH_2} \\to 2\\text{ mol }\\mathrm{H_2}\\)，需 \\(n(\\mathrm{CaH_2}) = 1.0\\text{ mol}\\)，即质量 \\(m(\\mathrm{CaH_2}) = 1.0\\times 42 = 42.0\\text{ g}\\)。","- 用 \\(\\mathrm{Zn}\\)：由 \\(1\\text{ mol }\\mathrm{Zn} \\to 1\\text{ mol }\\mathrm{H_2}\\)，需 \\(n(\\mathrm{Zn}) = 2.0\\text{ mol}\\)，即质量 \\(m(\\mathrm{Zn}) = 2.0\\times 65 = 130.0\\text{ g}\\)（且还需额外携带大量液体酸）。","比较结论：制取同等质量氢气时，\\(\\mathrm{CaH_2}\\) 所需固体质量不到锌的三分之一（且只需就地取水反应、无需携带腐蚀性液体酸），极其轻便安全！"],"ans":"(1) 见步骤四步配平方程式；(2) 需 42.0 g CaH₂，若用 Zn 则需 130.0 g（外加酸液）；CaH₂ 单位质量产氢量高且取水即用，最适合登山便携。","markingPoints":["正确写出①–④转化方程式及条件（4分）","算得 m(CaH₂) = 42.0 g 与 m(Zn) = 130.0 g（2分）","结合质量比及无需携带酸液说明便携优势（1分）"],"verification":"1 mol CaH₂ 含 2 mol H⁻ 与水中 2 mol H⁺ 归中得 2 mol H₂，故产氢效率极高。","pitfall":"计算 \\(\\mathrm{CaH_2}\\) 时容易看漏方程式右侧系数 **2**（\\(\\mathrm{2H_2}\\)），误算成需要 2 mol \\(\\mathrm{CaH_2}\\)（84 g）。"}],"cheatSheet":["电解水：加稀 \\(\\mathrm{H_2SO_4/NaOH}\\) 增强导电；**正氧负氢体积 1:2**（带余烬复燃 vs 淡蓝火焰+干燥烧杯水珠），证明水由 **H、O 元素**组成。","制氢选材：实验室选 **Zn + 稀 HCl/稀 H₂SO₄**（Mg 太快、Fe 太慢、Pb 钝化、Cu 不反应；Zn/Al 也可与浓 NaOH 制氢）；工业三大法：水煤气、甲烷重整、电解饱和食盐水（纯度最高）。","安全与还原：氢气爆炸极限 **4%–74%**；验纯须**管口朝下拇指堵**听轻微噗声；\\(\\mathrm{H_2}\\) 还原 \\(\\mathrm{CuO}\\) 务必**先通后点、先熄后停**。","氢能源：最轻（\\(0.0899\\text{ kg/m}^3\\)）、热值最高（\\(142\\,351\\text{ kJ/kg}\\)，汽油 3 倍）、产物只有水无污染可循环。"],"kbEntryIds":["kb-chem2-exp-electrolysis","kb-chem2-h2-prep","kb-chem2-h2-physical-purity","kb-chem2-h2-chemical-cuo","kb-chem2-h2-uses"],"quiz":{"q":"用氢气还原氧化铜（II）实验结束时，正确的操作顺序是什么？若顺序颠倒会看到什么异常现象？","given":"化上 p.35 与 p.40 第8(3)题","method":"对照还原金属防再氧化安全规范","principle":"炽热金属铜在空气中会重新被氧气氧化成 CuO。","steps":["正确顺序：先熄灭酒精灯（停止加热），继续通入氢气直至生成的铜完全冷却至室温，再停止通氢气。","若先停气后熄灯或未冷却就撤气，空气进入会使亮红褐色铜重新被氧化成黑色 CuO。"],"ans":"先熄酒精灯，待铜冷却至室温再停通氢气；颠倒会导致红褐色铜重新氧化变黑。"}}]},"化学3":{"lessonKey":"化学3","courseCode":"chemistry","subject":"化学","chapter":3,"title":"原子与分子","syllabus":"1.1.1–1.1.2、1.2.1–1.2.6","bookId":"sm1-chemistry-2017","bookCitation":"《马来西亚华文独中教科书 · 化学（上册）》（2017年11月版）第3章 p.41–76","examScopes":["sem1_final","pre_exam","sem2_final","uec"],"chapterOverview":{"summary":"第3章是从“定性化学”迈向“定量化学”的奠基章：以道尔顿原子学说和阿伏加德罗分子学说建立微观粒子图像，再用物质不灭、定比、倍比三大定量定律连接宏观质量称量与微观原子组合，最终引出全高中化学计算的核心枢纽——物质的量（mol）。","conceptTree":[{"branch":"1. 物质构成学说（p.42–45）","items":["道尔顿原子学说（四观点+局限）","阿伏加德罗分子学说（三观点+双原子分子）"]},{"branch":"2. 基本定量定律（p.45–50）","items":["物质不灭定律（活动探究1）","定比定律（活动探究2）","倍比定律（固定甲元素比乙）"]},{"branch":"3. 原子与相对质量（p.51–57）","items":["质子·中子·电子与质谱仪","12C/12基准（1 amu）与同位素平均Ar"]},{"branch":"4. 化学式与式量（p.57–66）","items":["分子式·实验式·结构式","式量Mr·质量比·质量百分比","化合价法·恒重法·百分比法推式"]},{"branch":"5. 物质的量桥梁（p.66–72）","items":["摩尔（mol）与指明微粒","阿伏加德罗常数 NA = 6.02×10²³ mol⁻¹","摩尔质量 M 与化学方程式计量联系"]}]},"paperFocus":["高三上半年期末考（Ch 3–8, Ch 26–30）：25道选择题（50%）+ 1道实验探究（10%）+ 必答题（40%）。第3章的 NA 陷阱、式量/百分比、燃烧推实验式与敞口天平探究极易直接命题。","预试 / 毕业考 / UEC 统考：卷一 30道选择题（30%，60分钟）；卷二甲部 4题必答（24%）+ 1题探究（10%），乙部有机/无机/物化各2选1（36%，120分钟）。物质的量 n 是卷二化学计量、热化学、反应速率与平衡、电化学及定量实验的全部计算地基。"],"solvingWorkflow":["标注题目给出的物理量（质量 m、粒子数 N、气体体积 V、密度/相对密度 D、百分含量 w），保留单位。","判断适用模型：固/液纯物质用 n = m/M；气体且明确温压才可用气体摩尔体积或阿伏加德罗气体定律 V ∝ n。","涉及燃烧或分解推化学式：先由生成物 CO₂、H₂O 求 m(C)、m(H)，再用总质量差减得 m(O)，最后算原子数比。","校验微粒层级：区分“1 mol 分子”与“原子数、离子数、电子数”，再检查有效数字与单位（Ar/Mr 无单位，M 为 g/mol）。"],"questionTypes":["三大定量定律（物质不灭、定比、倍比）数据表与多氧化物代数推理","质谱仪原理与同位素平均相对原子质量/分子离子峰丰度计算","化学式判断、化肥性价比分析与矿物/混合氧化物纯度推导","铜粉恒重氧化（活动5）及开放体系实验误差诊断（探究题）","燃烧分析法 + 相对密度确定有机物分子式","以 n 为中心的质量—微粒数—结晶水合物—气体密度综合换算"],"scoringNotes":["统考卷二计算题评分通常包含：公式/比例关系列式分、代入数据（mol 换算）过程分、最终数值与有效数字分、单位与微粒指明分。","探究题（10%）要求紧扣实验变量控制与误差物理原因（如“未冷却即称量导致热空气浮力偏小”、“敞口反应逸出气体/白烟”）。"],"vid":[{"t":"物质的量、摩尔质量与阿伏加德罗常数","q":"物质的量 摩尔质量 阿伏加德罗常数 高中化学"},{"t":"实验式与分子式及燃烧分析法","q":"实验式 分子式 燃烧法 高中化学"},{"t":"物质不灭、定比与倍比定律实验探究","q":"质量守恒定律 定比定律 倍比定律 化学"},{"t":"质谱仪与同位素平均相对原子质量","q":"质谱仪 相对原子质量 同位素 计算"}],"sections":[{"id":"3.1","t":"原子学说与分子学说","anchor":{"pages":"化上 p.42–45","syllabus":"1.1.1 微粒观与科学史基础","examScopes":["sem1_final","pre_exam","sem2_final","uec"],"examWeight":"P1 选择题高频概念辨析 + P2 气体体积比推导工具","terms":"Dalton's atomic theory · Avogadro's molecular theory · diatomic molecule · Gay-Lussac's law","prerequisites":["纯净物、单质与化合物的宏观分类（化上 Ch 1.4.2 p.13）","物理变化与化学变化的本质判据（是否有新物质生成，化上 Ch 1.4.4 p.15）"],"goals":["准确复述道尔顿原子学说的四个基本观点，并指出其在现代原子结构与同位素视角下的三处局限。","说明盖·吕萨克气体反应体积定律与道尔顿‘单原子气体假设’的矛盾，阐明阿伏加德罗如何用‘双原子分子’解决该矛盾。","区分原子与分子的微观定义及适用物质类别，并用分子性质解释教材 CO 与血红蛋白结合中毒实例。"]},"concepts":[{"kind":"definition","title":"道尔顿原子学说（1803–1808）及其历史局限","pageRef":"化上 p.43、p.72","body":["**四大基本观点**：①物质由**不能再分割**的微小微粒——原子组成；②原子既不能被消灭，也不能被创造；③同种原子的质量、大小和其他性质都相同，不同种原子的质量、大小和其他性质都不同；④在化学反应中，原子只能以简单的整数比结合。","**历史意义与现代修正**：该学说首次用定量微粒模型解释了物质不灭定律、定比定律和倍比定律；但随科学发展发现其三大局限：①**原子内部可再分**（原子核由质子、中子构成，核外有电子，仅在‘一般化学反应’中原子核不变）；②**同一元素存在同位素**（如 \\({}^{35}\\mathrm{Cl}\\) 与 \\({}^{37}\\mathrm{Cl}\\) 质量不同）；③**未区分原子与分子**，误认为气态单质皆为单原子且水分子为 \\(\\mathrm{HO}\\)。"],"takeaway":"“原子在化学变化中不能再分”，但不能笼统说“原子绝对不可再分”；同种元素的原子核电荷数相同，但质量可以不同（同位素）。"},{"kind":"law","title":"阿伏加德罗分子学说（1811）与气体反应体积矛盾的解决","pageRef":"化上 p.44–45、p.72","body":["**历史矛盾**：盖·吕萨克测得“同温同压下，\\(2\\text{ 体积氢气} + 1\\text{ 体积氧气} \\to 2\\text{ 体积水蒸气}\\)”。若按道尔顿“\\(1\\text{ 体积气体含 }N\\text{ 个原子}\\)”的假设，则 \\(1\\text{ 个氧原子}\\) 必须劈成半个才能生成 \\(2\\text{ 个水微粒}\\)，这与原子不可再分直接冲突。","**阿伏加德罗三观点与解决之道**：①**分子**是保持物质化学性质的最小微粒（同种物质分子性质相同，不同种分子性质不同）；②气体单质微粒（如 \\(\\mathrm{H_2}, \\mathrm{O_2}, \\mathrm{N_2}, \\mathrm{Cl_2}\\)）由两个原子构成**双原子分子**——因此 \\(1\\text{ 个 }\\mathrm{O_2}\\) 分子拆成 \\(2\\text{ 个 }\\mathrm{O}\\) 原子即可与 \\(2\\text{ 个 }\\mathrm{H_2}\\) 生成 \\(2\\text{ 个 }\\mathrm{H_2O}\\) 分子，无需分割原子；③分子处在**不断运动**状态且分子间**存在一定间隔**。","**同温同压关键推论（阿伏加德罗定律）**：同温、同压下，相同体积的任何气体含有相同数目的分子，故 \\(V_1:V_2 = N_1:N_2 = n_1:n_2\\)。"],"takeaway":"双原子分子概念彻底打通了原子学说与气体化合体积定律之间的障碍。"},{"kind":"mechanism","title":"教材实例：CO 与血红蛋白结合揭示‘分子决定化学性质’","pageRef":"化上 p.44","body":["教材图3-5 指出：人体血液中血红蛋白（\\(\\mathrm{Hb}\\)）通过可逆结合 \\(\\mathrm{O_2}\\) 分子形成氧合血红蛋白（\\(\\mathrm{HbO_2}\\)）输送氧气；而一氧化碳（\\(\\mathrm{CO}\\)）分子与 \\(\\mathrm{O_2}\\) 分子构成不同，化学性质截然不同——\\(\\mathrm{CO}\\) 与 \\(\\mathrm{Hb}\\) 结合成碳氧血红蛋白（\\(\\mathrm{HbCO}\\)）的能力极强且不易解离，阻断输氧从而造成煤气中毒。","**分子间间隔与运动现象**：\\(\\mathrm{HCl}\\) 气体与 \\(\\mathrm{NH_3}\\) 气体在密闭管两端扩散相遇生成 \\(\\mathrm{NH_4Cl}\\) 白烟，说明分子在不断运动；\\(50\\text{ mL}\\) 酒精与 \\(50\\text{ mL}\\) 水混合后总体积小于 \\(100\\text{ mL}\\)，证明分子间存在间隔。"],"takeaway":"由分子构成的物质，发生物理变化时分子本身不变（只变间距或运动速率）；发生化学变化时分子破裂成原子，原子重新组合成新分子。"},{"kind":"table","title":"原子与分子的核心区分对照表","pageRef":"化上 p.43–45","body":["考试常考“某物质由原子还是分子直接构成”及“化学变化最小微粒 vs 化学性质最小微粒”。"],"table":{"headers":["比较维度","原子（Atom）","分子（Molecule）"],"rows":[["核心地位","化学变化中的最小微粒","保持（由分子构成的）物质化学性质的最小微粒"],["化学变化中能否再分","不能再分，只发生重新组合","一定拆分为原子后再重新组合"],["直接构成物质举例","金属（Fe、Cu）、金刚石/石墨（C）、晶体硅（Si）、稀有气体（He、Ar）","绝大多数气体非金属单质（H₂、O₂、Cl₂）、多数共价化合物（H₂O、CO₂、CH₄、乙醇）"],["常见误区提醒","NaCl 等离子晶体既不是由分子构成，也不是由中性原子构成，而是由 Na⁺ 与 Cl⁻ 离子按 1:1 排列（p.58）","分子只能保持物质的化学性质，不能保持熔点、沸点、密度、颜色等宏观物理性质"]]}}],"formulas":[{"title":"阿伏加德罗气体体积推论（同温 T、同压 p）","tex":"\\frac{V_1}{V_2} = \\frac{N_1}{N_2} = \\frac{n_1}{n_2}","plain":"V1 / V2 = N1 / N2 = n1 / n2","conditions":"必须同时满足：①全为气体（非液态水/固体）；②同温 T 与同压 p","pageRef":"化上 p.44","note":"同温同压下，气体反应方程式的化学计量数之比即等于反应前后各气体体积之比。"},{"title":"血红蛋白携氧与 CO 中毒竞争反应","tex":"\\mathrm{Hb} + \\mathrm{O_2} \\rightleftharpoons \\mathrm{HbO_2},\\qquad \\mathrm{Hb} + \\mathrm{CO} \\longrightarrow \\mathrm{HbCO}","plain":"Hb + O2 ⇌ HbO2; Hb + CO → HbCO","conditions":"生理体温条件下；Hb 与 CO 亲和力远大于 O₂","pageRef":"化上 p.44","note":"说明不同种分子（O₂ 与 CO）化学性质显著不同。"}],"pitfalls":[{"title":"混淆‘化学性质最小微粒’与‘物质一切性质’","wrong":"“单个水分子拥有水的沸点 100 ℃ 和流动性。”","diagnosis":"密度、熔沸点、硬度、导热性等属于大量微粒聚集后体现的宏观物理性质，单个分子无法体现。","right":"分子只能保持由分子构成的物质的**化学性质**；例如保持金属铁化学性质的最小微粒则是**铁原子**（铁由原子构成，无分子）。","checkRule":"遇到“保持某物质化学性质的最小微粒”，先看该物质由分子、原子还是离子构成。"},{"title":"无条件把体积比当作分子数比","wrong":"“同温同压下，\\(10\\text{ mL}\\) 水与 \\(10\\text{ mL}\\) 氧气所含分子数相等。”","diagnosis":"常温常压下水是液体，分子间距极小，阿伏加德罗定律只适用于气态物质。","right":"必须核对题目所处温度与压强下物质的状态：常温下 \\(\\mathrm{H_2O}, \\mathrm{Br_2}, \\mathrm{CCl_4}\\) 为液态，仅 \\(\\ge 100\\ ^\\circ\\mathrm{C}\\) 或题目写明 \\(\\mathrm{H_2O(g)}\\) 才按气体体积比算。","checkRule":"套用 \\(V\\propto N\\) 前先圈出“气体”和“同温同压”两个前提。"},{"title":"误把离子化合物说成含有独立分子","wrong":"“\\(1\\text{ 个}\\)氯化钠分子由 \\(1\\text{ 个}\\)钠原子和 \\(1\\text{ 个}\\)氯原子组成。”","diagnosis":"氯化钠（\\(\\mathrm{NaCl}\\)）晶体中不存在独立分子，只有交替排列的 \\(\\mathrm{Na^+}\\) 和 \\(\\mathrm{Cl^-}\\)（教材 p.58 图3-13）。","right":"\\(\\mathrm{NaCl}\\) 是表示钠离子与氯离子个数比为 \\(1:1\\) 的**化学式（实验式）**，而非分子式。","checkRule":"看到金属+非金属离子化合物或金属单质，切忌出现“某某分子”字样。"}],"examples":[{"label":"例 3.1.1","tier":"L3","tierLabel":"L3 预试拔高","title":"同温同压气体燃烧体积法推烃分子式","prompt":"在 \\(120\\ ^\\circ\\mathrm{C}\\)、\\(101\\text{ kPa}\\) 下，将 \\(10\\text{ mL}\\) 某气态碳氢化合物 \\(\\mathrm{C}_x\\mathrm{H}_y\\) 与 \\(50\\text{ mL}\\ \\mathrm{O_2}\\) 混合并充分点燃反应。恢复至原温度和压强，测得容器内气体总体积为 \\(65\\text{ mL}\\)；将该混合气体通过足量碱石灰干燥管吸收 \\(\\mathrm{CO_2}\\) 和 \\(\\mathrm{H_2O(g)}\\) 后，最终剩余气体 \\(15\\text{ mL}\\)。求该碳氢化合物的分子式。","clues":"注意温度为 \\(120\\ ^\\circ\\mathrm{C} > 100\\ ^\\circ\\mathrm{C}\\)，生成的水全部是气态 \\(\\mathrm{H_2O(g)}\\)！同温同压下气体体积比等于化学计量数比。","strategy":"先由剩余 \\(\\mathrm{O_2}\\) 求出实际消耗 \\(\\mathrm{O_2}\\) 体积，再列耗氧体积与反应后产物总体积两个独立方程求解 \\(x,y\\)。","given":"V(烃) = 10 mL，初始 V(O₂) = 50 mL，反应后总 V = 65 mL，剩余 O₂ = 15 mL","principle":"阿伏加德罗气体定律（同 T、p 下 V ∝ n）及烃燃烧化学计量关系。","steps":["写出气态烃完全燃烧通式：\\(\\mathrm{C}_x\\mathrm{H}_y\\mathrm{(g)} + \\left(x + \\frac{y}{4}\\right)\\mathrm{O_2(g)} \\longrightarrow x\\mathrm{CO_2(g)} + \\frac{y}{2}\\mathrm{H_2O(g)}\\)。","实际消耗氧气体积：\\(V_{\\text{耗}}(\\mathrm{O_2}) = 50\\text{ mL} - 15\\text{ mL} = 35\\text{ mL}\\)，由计量比得：\\(10\\left(x + \\frac{y}{4}\\right) = 35 \\implies x + \\frac{y}{4} = 3.5\\)（式①）。","反应后被碱石灰吸收的 \\(\\mathrm{CO_2}\\) 与 \\(\\mathrm{H_2O(g)}\\) 总体积：\\(V(\\mathrm{CO_2}) + V(\\mathrm{H_2O}) = 65\\text{ mL} - 15\\text{ mL} = 50\\text{ mL}\\)。","由计量比得：\\(10x + 10 \\times \\frac{y}{2} = 50 \\implies 2x + y = 10\\)（式②）。","联立式①×4 得 \\(4x + y = 14\\)，减去式②得 \\(2x = 4 \\implies x = 2\\)，代回得 \\(y = 6\\)。"],"answer":"该碳氢化合物的分子式为 \\(\\mathrm{C_2H_6}\\)（乙烷）。","markingPoints":["正确判断 120 ℃ 下水为气态（1分）","正确写出燃烧通式并求得耗氧 35 mL（1分）","列出两独立体积守恒方程并解得 x=2, y=6（2分）"],"verification":"代入检验：\\(10\\text{ mL }\\mathrm{C_2H_6}\\) 耗 \\(35\\text{ mL }\\mathrm{O_2}\\)，生 \\(20\\text{ mL }\\mathrm{CO_2} + 30\\text{ mL }\\mathrm{H_2O(g)}\\)，加剩余 \\(15\\text{ mL }\\mathrm{O_2}\\) 恰为 \\(65\\text{ mL}\\)。","pitfall":"若误把 120 ℃ 的水当液态排除体积，会导致方程失效算错。"},{"label":"例 3.1.2","tier":"L2","tierLabel":"L2 校内期末","title":"教材学说演变与微观概念辨析","prompt":"道尔顿曾认为水分子由 1 个氢原子和 1 个氧原子构成（即化学式写作 \\(\\mathrm{HO}\\)），但实际电解水实验中，同温同压下生成氢气与氧气的体积比总是 \\(2:1\\)。请用阿伏加德罗分子学说解释为什么道尔顿的判断不成立，并说明电解水过程中微粒是如何变化的。","clues":"抓住“气体单质是双原子分子”与“化学变化中分子拆成原子、原子重新组合”。","strategy":"用双原子分子写出微观数量守恒方程，反驳单原子模型。","given":"V(H₂) : V(O₂) = 2 : 1","principle":"阿伏加德罗分子学说：气体单质为双原子分子；同 T、p 体积比 = 分子数比。","steps":["根据阿伏加德罗定律，同温同压下生成 \\(\\mathrm{H_2}\\) 与 \\(\\mathrm{O_2}\\) 的体积比为 \\(2:1\\)，意味着生成的氢分子数与氧分子数之比为 \\(2:1\\)。","又因为氢气和氧气均为双原子分子（\\(\\mathrm{H_2}\\)、\\(\\mathrm{O_2}\\)），故每生成 \\(2\\text{ 个 }\\mathrm{H_2}\\) 分子和 \\(1\\text{ 个 }\\mathrm{O_2}\\) 分子，共含 \\(4\\text{ 个 H 原子}\\)和 \\(2\\text{ 个 O 原子}\\)。","原子在化学变化中既不产生也不消失，因此原水分子中氢原子与氧原子的个数比必然为 \\(4:2 = 2:1\\)，即水的分子式只能是 \\(\\mathrm{H_2O}\\) 而非 \\(\\mathrm{HO}\\)。","微观变化过程：通电时水分子破裂为氢原子和氧原子，随后每 2 个氢原子结合成 1 个氢分子，每 2 个氧原子结合成 1 个氧分子。"],"answer":"水的真实分子式为 \\(\\mathrm{H_2O}\\)；电解中水分子拆分为 H、O 原子后重新组合为 \\(\\mathrm{H_2}\\) 和 \\(\\mathrm{O_2}\\) 分子。","markingPoints":["利用体积比 2:1 得到分子数比 2:1（1分）","指出 H₂、O₂ 为双原子分子并推得 H:O 原子数比 2:1（2分）","准确描述分子破裂、原子重组的化学变化本质（1分）"],"verification":"方程 \\(2\\mathrm{H_2O} \\to 2\\mathrm{H_2} + \\mathrm{O_2}\\) 前后 H 原子 4 个、O 原子 2 个完全守恒。","pitfall":"不可写成“水分子中含有 1 个氢分子和半个氧分子”——纯净水中不存在氢气分子或氧气分子。"}],"practice":[{"id":"chem3-3.1-q1","tier":"L1","tierLabel":"L1 基础","examStyle":"P1 选择","q":"下列关于道尔顿原子学说在现代化学视角下的评价，正确的是（　）。","options":["A. 原子在任何物理和化学变化中都绝对不可再分","B. 同一元素的所有原子质量必须完全相等，不存在例外","C. 道尔顿通过区分原子与分子成功解释了气体化合体积定律","D. 在一般化学反应中，原子的种类、数目与质量不会改变，只发生重新组合"],"correctOption":"D","given":"道尔顿原子学说四观点（化上 p.43）","method":"逐项比对现代原子结构与科学史修正","principle":"原子核物理可分割原子；同位素质量不同；阿伏加德罗才区分原子与分子。","steps":["A 错：在核反应或电离中原子可分裂为原子核与电子。","B 错：同种元素存在质子数相同而中子数不同的同位素（如 ³⁵Cl 与 ³⁷Cl），质量不同。","C 错：区分原子与分子的是 1811 年阿伏加德罗，而非道尔顿。","D 对：化学反应本质即原子的重新组合，核不发生变化。"],"ans":"D","markingPoints":["准确识别化学反应中原子守恒这一至今成立的核心结论"],"verification":"对照化上 p.43 原文四观点核对。","pitfall":"误选 A，忽视核化学与电子发现对“绝对不可分”的修正。"},{"id":"chem3-3.1-q2","tier":"L2","tierLabel":"L2 期末","examStyle":"P1 选择","q":"下列宏观现象与微观解释的对应关系中，**错误**的是（　）。","options":["A. 50 mL 水与 50 mL 乙醇混合后总体积小于 100 mL —— 分子之间存在间隔","B. 氧气供呼吸而一氧化碳导致中毒 —— 不同种分子的化学性质不同","C. 液态水受热沸腾变成水蒸气体积剧增 —— 水分子本身受热膨胀变大","D. 将浓氨水与浓盐酸分别置于密闭玻璃管两端，管内会生成白烟 —— 分子不断运动扩散"],"correctOption":"C","given":"分子运动论与教材 p.44 实例","method":"判别物理变化改变的是分子间距还是分子本身大小","principle":"三态变化（物理变化）只改变微粒间平均距离，分子本身体积几乎不变。","steps":["A 正确：两种液体混合相互填补分子间隙，总体积减小。","B 正确：教材 p.44 明确以 HbO₂ 与 HbCO 说明不同分子化学性质不同。","C 错误：液态水汽化时体积增大上千倍，是因为分子间距离急剧增大，水分子本身大小与结构均不改变。","D 正确：NH₃ 与 HCl 分子运动扩散后相遇反应生成 NH₄Cl 固体白烟。"],"ans":"C","markingPoints":["识别相变中“分子间距改变、分子大小不变”"],"verification":"若分子自身受热膨胀，冷却不可能恢复原液体密度且违背共价键键长稳定性。","pitfall":"受热胀冷缩字面误导而误以为分子本身膨胀。"},{"id":"chem3-3.1-q3","tier":"L2","tierLabel":"L2 期末","examStyle":"P2 必答简答","q":"请从微粒观解释下列事实：(1) 为什么 \\(\\mathrm{H_2O}\\) 与 \\(\\mathrm{H_2O_2}\\) 的组成元素相同，化学性质却差异极大？(2) 为什么实验室用双氧水（\\(\\mathrm{H_2O_2}\\)）制氧气属于化学变化，而工业上分离液态空气制氧气属于物理变化？","given":"H₂O 与 H₂O₂ 分子构成、过氧化氢分解及液空分馏","method":"分子构成不同 → 化学性质不同；分子是否改变 → 变化类型判据","principle":"分子是保持物质化学性质的最小微粒；化学变化生成新分子。","steps":["(1) \\(1\\) 个水分子（\\(\\mathrm{H_2O}\\)）由 \\(2\\) 个 \\(\\mathrm{H}\\) 原子和 \\(1\\) 个 \\(\\mathrm{O}\\) 原子构成，而 \\(1\\) 个过氧化氢分子（\\(\\mathrm{H_2O_2}\\)）由 \\(2\\) 个 \\(\\mathrm{H}\\) 原子和 \\(2\\) 个 \\(\\mathrm{O}\\) 原子构成。两者分子构成不同，因此化学性质不同。","(2) \\(\\mathrm{H_2O_2}\\) 分解过程中，过氧化氢分子破裂为氢、氧原子并重新组合成 \\(\\mathrm{H_2O}\\) 分子与 \\(\\mathrm{O_2}\\) 分子，有新分子生成，故为化学变化；而液态空气升温分馏过程中，原有 \\(\\mathrm{N_2}\\) 分子和 \\(\\mathrm{O_2}\\) 分子均未改变，仅利用沸点差异使分子彼此分离，故为物理变化。"],"ans":"(1) 两者分子构成不同（O原子数不同），分子种类决定化学性质；(2) 分解产生了新分子（H₂O、O₂）为化学变化，分馏仅改变分子聚集与距离而未产生新分子为物理变化。","markingPoints":["指出分子构成不同导致化学性质不同（2分）","用“是否生成新分子”严格区分两个制氧过程（2分）"],"verification":"对照教材 p.44 与 p.72 阿伏加德罗学说第1点核对。","pitfall":"只答“元素相同、原子数不同”而漏写“分子是保持化学性质的最小微粒”会扣关键字分。"},{"id":"chem3-3.1-q4","tier":"L3","tierLabel":"L3 预试","examStyle":"P1 选择","q":"在同温同压下，将等体积的一氧化碳（\\(\\mathrm{CO}\\)）和氮气（\\(\\mathrm{N_2}\\)）分别装入两个相同容积的密闭钢瓶中（已知 \\(\\mathrm{C}=12, \\mathrm{N}=14, \\mathrm{O}=16\\)）。关于两瓶气体，下列说法**不**正确的是（　）。","options":["A. 两瓶内气体分子总数一定相等","B. 两瓶内气体的质量一定相等","C. 两瓶内气体所含原子总数一定相等","D. 两瓶内气体的化学性质一定相同"],"correctOption":"D","given":"同 T、p，V(CO) = V(N₂)；M(CO) = 28，M(N₂) = 28","method":"利用阿伏加德罗定律比较分子数、原子数、摩尔质量及化学性质","principle":"同 T、p、同体积气体分子数相同；CO 与 N₂ 为不同分子但式量与原子/分子比恰好相同。","steps":["A 正确：同温同压同体积下，分子数 \\(N\\) 相等。","B 正确：\\(M(\\mathrm{CO})=12+16=28\\text{ g/mol}\\)，\\(M(\\mathrm{N_2})=28\\text{ g/mol}\\)，等物质的量时质量 \\(m = nM\\) 必定相等。","C 正确：两者均为双原子分子，分子数相等故原子总数（\\(2N\\)）也相等。","D 错误：\\(\\mathrm{CO}\\) 有毒且具有强还原性，\\(\\mathrm{N_2}\\) 化学性质稳定且无毒，分子种类不同，化学性质绝不相同。"],"ans":"D","markingPoints":["综合运用阿伏加德罗定律与式量巧比"],"verification":"CO 与 N₂ 式量相等、原子数相等，物理量相似但化学性质截然不同。","pitfall":"看到式量、原子数全相等时错以为化学性质也相同。"},{"id":"chem3-3.1-q5","tier":"L4","tierLabel":"L4 统考压轴","examStyle":"P2 综合计算","q":"密闭容器中装有 \\(20\\text{ mL}\\) 某种气态氮的氧化物 \\(\\mathrm{N}_x\\mathrm{O}_y\\)，在高温催化剂作用下使其完全分解为氮气（\\(\\mathrm{N_2}\\)）和氧气（\\(\\mathrm{O_2}\\)）。恢复至原来温度和压强后，测得混合气体总体积变为 \\(50\\text{ mL}\\)；将该混合气体全部缓慢通过足量灼热的铜网充分除去 \\(\\mathrm{O_2}\\) 后，在同温同压下最终剩余气体体积为 \\(20\\text{ mL}\\)。试通过计算确定该氮氧化物的化学式（提示：\\(\\mathrm{2Cu(s) + O_2(g)} \\xrightarrow{\\Delta} \\mathrm{2CuO(s)}\\)）。","given":"V(NxOy) = 20 mL，分解后总气体 = 50 mL，除 O₂ 后剩余 N₂ = 20 mL","method":"阿伏加德罗定律体积比推分子数比与原子数守恒","principle":"同温同压下气体体积比等于物质的量/分子数之比；分解前后 N、O 原子数守恒。","steps":["灼热铜网只吸收气体 \\(\\mathrm{O_2}\\) 生成固体 \\(\\mathrm{CuO}\\)，剩余 \\(20\\text{ mL}\\) 气体全为生成的 \\(\\mathrm{N_2}\\)，即 \\(V(\\mathrm{N_2}) = 20\\text{ mL}\\)。","故生成的氧气体积为：\\(V(\\mathrm{O_2}) = 50\\text{ mL} - 20\\text{ mL} = 30\\text{ mL}\\)。","写出分解反应体积计量比：\\(\\mathrm{N}_x\\mathrm{O}_y\\mathrm{(g)} \\longrightarrow \\frac{x}{2}\\mathrm{N_2(g)} + \\frac{y}{2}\\mathrm{O_2(g)}\\)。","同温同压下气体体积比等于系数比：\\(V(\\mathrm{N}_x\\mathrm{O}_y) : V(\\mathrm{N_2}) : V(\\mathrm{O_2}) = 20 : 20 : 30 = 2 : 2 : 3\\)。","对比系数得：\\(2 \\times \\frac{x}{2} = 2 \\implies x = 2\\)；\\(2 \\times \\frac{y}{2} = 3 \\implies y = 3\\)。"],"ans":"该氮氧化物的化学式为 \\(\\mathrm{N_2O_3}\\)（三氧化二氮）。","markingPoints":["求出 V(N₂)=20 mL、V(O₂)=30 mL（1分）","依据阿伏加德罗定律写出体积比 2:2:3 对应方程式系数（2分）","由原子守恒得出 x=2, y=3 即 N₂O₃（1分）"],"verification":"验证方程式 \\(2\\mathrm{N_2O_3} \\to 2\\mathrm{N_2} + 3\\mathrm{O_2}\\)：左边 \\(4\\text{ N}, 6\\text{ O}\\)；右边 \\(4\\text{ N}, 6\\text{ O}\\)，体积由 2 份增至 5 份（\\(20\\text{ mL} \\to 50\\text{ mL}\\)），完全吻合。","pitfall":"若忘记氮气和氧气是双原子分子，直接写成 \\(x=1, y=1.5\\) 而忘记乘 2，会错写成无意义的分数下标。"}],"cheatSheet":["道尔顿 4 观点：最小粒子、不灭、同同异异、简整数比；现代修正记住“原子可分核+电子”与“同位素质量不同”。","阿伏加德罗 3 观点 + 双原子分子（H₂、O₂、Cl₂、N₂），彻底解决气体体积整数比与原子不可分之间的矛盾。","同温同压下气体必记公式：\\(V_1/V_2 = N_1/N_2 = n_1/n_2\\)（只适用于气体！）。","化学变化最小微粒 = 原子；保持化学性质最小微粒 = 分子（若由原子或离子直接构成则非分子）。"],"kbEntryIds":["kb-chem3-dalton","kb-chem3-avogadro"],"quiz":{"q":"同温同压下，\\(10\\text{ mL}\\) 气体 \\(\\mathrm{A_2}\\) 与 \\(30\\text{ mL}\\) 气体 \\(\\mathrm{B_2}\\) 恰好完全化合生成 \\(20\\text{ mL}\\) 气态产物 \\(\\mathrm{X}\\)，则 \\(\\mathrm{X}\\) 的化学式是什么？","given":"体积比 A₂ : B₂ : X = 10 : 30 : 20 = 1 : 3 : 2","method":"同温同压气体体积比等于化学计量数比，再由原子守恒求下标","principle":"阿伏加德罗气体定律与原子数目守恒。","steps":["体积比即分子数比：\\(1\\mathrm{A_2} + 3\\mathrm{B_2} \\longrightarrow 2\\mathrm{X}\\)。","由原子守恒，2 个 X 分子含 2 个 A 原子与 6 个 B 原子，故 1 个 X 分子含 1 个 A 与 3 个 B。"],"ans":"\\(\\mathrm{AB_3}\\)"}},{"id":"3.2","t":"物质组成及化学反应中的基本定律","anchor":{"pages":"化上 p.45–50","syllabus":"1.1.1 物质不灭定律、定比定律、倍比定律","examScopes":["sem1_final","pre_exam","sem2_final","uec"],"examWeight":"P1 质量表计算 + P2 实验探究天平误差分析（高一期末及统考高发题区）","terms":"Law of Conservation of Matter · Law of Definite Proportions · Law of Multiple Proportions","prerequisites":["道尔顿原子学说（3.1.1）与阿伏加德罗分子学说（3.1.2）","天平称量操作及基本化学实验现象观察"],"goals":["阐明物质不灭定律（质量守恒定律）的表述、微观原因，并能诊断敞口体系“看似不守恒”的实验原因。","分析教材活动探究1（白磷燃烧与 BaCl₂ 沉淀）及活动探究2（NaOH 与 CuSO₄·5H₂O）中的变量控制与限量判断。","熟练区分并联合运用定比定律与倍比定律进行元素质量比及未知化合物化学式推导。"]},"concepts":[{"kind":"law","title":"3.2.1 物质不灭定律（质量守恒定律，拉瓦锡 1774）","pageRef":"化上 p.45–47、p.72","body":["**定义**：参加化学反应的各物质的质量总和，等于反应后生成的各物质的质量总和（教材使用‘**物质不灭定律**’，英文 Law of Conservation of Matter，又称质量守恒定律）。","**微观解释**：一切化学变化中，反应前后原子的**种类、数目、质量**均未增减，故质量总和必然相等。","**‘六个不变’与‘两个一定变、两个可能变’**：","- **六个一定不变**：宏观总质量、元素种类、各元素质量；微观原子种类、原子数目、原子质量。","- **两个一定改变**：宏观物质种类；微观分子种类。","- **两个可能改变**：分子总数目（如 \\(2\\mathrm{H_2+O_2\\to 2H_2O}\\) 减少）、元素化合价。"],"takeaway":"记住核心限定词：“**参加反应的**”（过量未反应的反应物不可算作参加反应）和“**化学反应**”（物理溶解不适用此定律解释）。"},{"kind":"experiment","title":"活动探究1：密闭白磷燃烧 vs BaCl₂ 沉淀实验（兼论敞口失衡原因）","pageRef":"化上 p.46–47、p.75–76","body":["**实验 1（密闭白磷燃烧）**：\\(\\mathrm{P_4(s) + 5O_2(g)} \\xrightarrow{\\text{点燃}} \\mathrm{2P_2O_5(s)}\\)。锥形瓶底铺**干燥细沙**防止受热不均炸裂瓶底；橡皮塞塞紧（或加小气球缓冲防冲塞）防止 \\(\\mathrm{P_2O_5}\\) 白烟逸出及外界空气进入；**必须待瓶冷却至室温再称量**（热瓶使内部或周围空气对流产生向上浮力，导致天平示数看似偏轻）。","**实验 2（沉淀混合）**：\\(\\mathrm{BaCl_2(aq) + H_2SO_4(aq) \\longrightarrow BaSO_4(s)\\downarrow + 2HCl(aq)}\\)。两种无色溶液混合产生白色沉淀，因无气体参与或逸出，敞口烧杯与密闭瓶中天平均保持平衡。","**敞口体系考场分析模板**：①**烧杯中碳酸钙+稀盐酸**：逸出 \\(\\mathrm{CO_2}\\) 气体使秤盘示数变轻；②**镁带敞口在石棉网上燃烧（教材 p.76 第6(2)题）**：理论上应因吸收空气中 \\(\\mathrm{O_2}\\) 而增重，但实际常意外减重，原因在于燃烧产生大量 \\(\\mathrm{MgO}\\) **白烟逸散到空气中**（带走质量超过吸收氧气质量）或部分产物飞溅/遗落。"],"takeaway":"任何貌似“增重”（如铁生锈、镁燃烧）或“减重”（如蜡烛燃烧、石灰石加酸）的过程，把气体反应物或气体/烟尘产物算入封闭系统后，总质量严格守恒。"},{"kind":"experiment","title":"3.2.2 定比定律与活动探究2（NaOH + CuSO₄·5H₂O 限量反应）","pageRef":"化上 p.48–49、p.72","body":["**定比定律（定组成定律）**：任何纯净的化合物都有固定的组成，不管它在什么地方得到，也不管用什么方法制得，其各组成元素质量比恒定（如所有纯化水电解所得 \\(m_\\mathrm{H}:m_\\mathrm{O}=1:8\\)）。","**活动探究2 教材实测解析（p.48）**：\\(\\mathrm{2NaOH + CuSO_4 \\longrightarrow Cu(OH)_2\\downarrow + Na_2SO_4}\\)。","- 实验1：将 \\(2.0\\text{ g}\\ \\mathrm{NaOH}\\) 溶液加入 \\(6.25\\text{ g}\\ \\mathrm{CuSO_4\\cdot 5H_2O}\\) 溶液中 → 滤出干燥得蓝色沉淀 \\(\\mathrm{Cu(OH)_2}\\) 质量为 **\\(2.45\\text{ g}\\)**。","- 实验2：将 \\(\\mathrm{NaOH}\\) 增至 **\\(4.0\\text{ g}\\)** 仍与 \\(6.25\\text{ g}\\ \\mathrm{CuSO_4\\cdot 5H_2O}\\) 反应 → 所得 \\(\\mathrm{Cu(OH)_2}\\) 沉淀**依然只有 \\(2.45\\text{ g}\\)**。","- **定量启示**：\\(6.25\\text{ g}\\ \\mathrm{CuSO_4\\cdot 5H_2O}\\)（约 \\(0.025\\text{ mol}\\)）最多只能消耗 \\(2.0\\text{ g}\\ \\mathrm{NaOH}\\)（\\(0.050\\text{ mol}\\)），多加的 \\(2.0\\text{ g NaOH}\\) **过量未参加反应**，无法改变产物比例。"],"takeaway":"定比定律可用于鉴别化合物纯度，以及在限量反应中算出“未参加反应的过量试剂质量”。"},{"kind":"law","title":"3.2.3 倍比定律（道尔顿）：先固定一种元素，再比另一种元素","pageRef":"化上 p.50、p.72","body":["**定义**：如果甲、乙两种元素能互相化合生成几种不同的化合物，那么在这些化合物中，**与一定质量甲元素相化合的乙元素的质量**，互成**简单的整数比**。","**教材实例（例3，p.50）**：一氧化碳（\\(\\mathrm{CO}\\)）与二氧化碳（\\(\\mathrm{CO_2}\\)）——若均取含 \\(12\\text{ g}\\) 碳元素作基准，\\(\\mathrm{CO}\\) 中结合氧 \\(16\\text{ g}\\)，\\(\\mathrm{CO_2}\\) 中结合氧 \\(32\\text{ g}\\)，两处氧质量比为 \\(16:32 = 1:2\\)（简单整数比）。","**为什么必须“固定甲的质量”？** 化合物百分比的分母（总式量）彼此不同，直接把甲或乙的质量百分比相除没有同基准意义，务必化为 \\(\\frac{m_{\\text{乙}}}{m_{\\text{甲}}}\\) 再求比值！"],"takeaway":"固定甲求 \\(\\frac{m_\\text{乙}}{m_\\text{甲}}\\) 之比，本质就是比较每 1 个甲原子所结合乙原子数 \\(y_1 : y_2\\)！"},{"kind":"table","title":"三大化学基本定量定律对照速览","pageRef":"化上 p.45–50","body":["考试若问“某实验数据说明了哪一定律”，请按比较对象迅速锁定："],"table":{"headers":["定律名称","研究对象与范围","核心数量关系","微观本源（原子/分子学说）"],"rows":[["物质不灭定律","同一化学反应的前与后","∑m(参加反应物) = ∑m(生成物)","反应前后原子种类、数目、质量全不变"],["定比定律","同一种纯净化合物内部","不同来源样品中 m(A):m(B) = 常数","同一化合物分子中各元素原子个数比固定"],["倍比定律","同两种元素构成的≥2种化合物","固定 m(A) 时，m(B₁):m(B₂) = 简单整数比","原子只能以简单整数比结合（道尔顿观点四）"]]}}],"formulas":[{"title":"物质不灭定律（限定参加反应的量）","tex":"\\sum m_{\\text{参加反应}}(\\text{反应物}) = \\sum m(\\text{产物}),\\qquad m_{\\text{投料}} - m_{\\text{剩余}} = m_{\\text{参加反应}}","plain":"m(参加反应物)总和 = m(生成物)总和","conditions":"仅限化学反应；所有气态反应物、产物与烟尘均需计入","pageRef":"化上 p.47","note":"当有反应物过量未反应完时，投料总质量减去剩余物总质量才等于实际反应物质量。"},{"title":"定比定律与倍比定律转换通式","tex":"\\text{化合物 }\\mathrm{A}_x\\mathrm{B}_y:\\quad \\frac{m(\\mathrm{B})}{m(\\mathrm{A})} = \\frac{y\\,A_r(\\mathrm{B})}{x\\,A_r(\\mathrm{A})},\\qquad \\frac{\\left(m(\\mathrm{B})/m(\\mathrm{A})\\right)_1}{\\left(m(\\mathrm{B})/m(\\mathrm{A})\\right)_2} = \\frac{y_1/x_1}{y_2/x_2}","plain":"[m(B)/m(A)]₁ : [m(B)/m(A)]₂ = (y₁/x₁) : (y₂/x₂)","conditions":"前提必须是同一两种元素构成的纯净化合物","pageRef":"化上 p.48–50","note":"直接用乙、甲质量比之比等于原子下标比之比，无需提前知道两元素的相对原子质量！"}],"pitfalls":[{"title":"用百分比直接相除验证倍比定律","wrong":"“\\(\\mathrm{CO}\\) 含氧 \\(57.1\\%\\)，\\(\\mathrm{CO_2}\\) 含氧 \\(72.7\\%\\)，氧百分比比是 \\(57.1:72.7 \\ne 1:2\\)，不符合倍比定律。”","diagnosis":"两者分母分别是 \\(\\mathrm{CO}\\) 质量与 \\(\\mathrm{CO_2}\\) 质量，碳元素基准不相同！","right":"必须先固定 \\(\\mathrm{C}\\) 质量为 \\(1\\text{ g}\\)：\\(\\mathrm{CO}\\) 中氧/碳 \\(= 57.1/42.9 = 1.33\\text{ g}\\)，\\(\\mathrm{CO_2}\\) 中氧/碳 \\(= 72.7/27.3 = 2.66\\text{ g}\\)，比值为 \\(1.33:2.66 = 1:2\\)。","checkRule":"凡是遇到给出百分比证明倍比定律的题，第一步永远是算出 `另一元素% ÷ 固定元素%`。"},{"title":"将过量投料全部当作反应物代入质量守恒","wrong":"“将 \\(4.0\\text{ g NaOH}\\) 与 \\(6.25\\text{ g }\\mathrm{CuSO_4\\cdot 5H_2O}\\) 反应，反应物总和是 \\(10.25\\text{ g}\\)，所以生成物总和等于 \\(10.25\\text{ g}\\)。”","diagnosis":"严格表述应为：**参加反应的**只有 \\(2.0\\text{ g NaOH}\\) 与 \\(6.25\\text{ g}\\) 晶体，反应后容器内有 \\(2.0\\text{ g NaOH}\\) 未反应而剩余。","right":"反应前总质量（含未反应物）\\(=\\) 反应后总质量（含剩余物+生成物）；但‘生成物总质量’只等于‘**实际参加反应**的反应物质量总和’。","checkRule":"质量表里若某反应物反应后质量不为 0，则参加反应的质量 = `反应前 − 反应后`。"},{"title":"将质量守恒定律套用于物理变化","wrong":"“\\(10\\text{ g}\\) 冰融化成 \\(10\\text{ g}\\) 水，或者 \\(10\\text{ g}\\) 盐溶于 \\(90\\text{ g}\\) 水得 \\(100\\text{ g}\\) 盐水，说明物质不灭定律成立。”","diagnosis":"物质不灭定律是描述**化学变化**中反应物与生成物关系的定律，物理变化不能用来“验证”或“解释为物质不灭定律”。","right":"做选择题遇到“冰融化”、“氯化钠溶于水”、“酒精挥发”等选项，一律直接排除（教材 p.73 第6题考点）。","checkRule":"先判别是不是化学变化（有无新物质生成），不是化学变化则与物质不灭定律无关。"}],"examples":[{"label":"例 3.2.1","tier":"L4","tierLabel":"L4 统考压轴","title":"密闭反应质量表 + 未知产物 X 分子式元素守恒推导","prompt":"（改编自教材 p.73–74 第7题）将 \\(4.6\\text{ g}\\) 乙醇（\\(\\mathrm{C_2H_6O}\\)）和 \\(8.0\\text{ g}\\) 氧气（\\(\\mathrm{O_2}\\)）置于密闭容器中点燃充分反应，测得反应后剩余乙醇 \\(0\\text{ g}\\)、氧气 \\(0\\text{ g}\\)，同时生成 \\(5.4\\text{ g}\\) 水（\\(\\mathrm{H_2O}\\)）、\\(4.4\\text{ g}\\) 二氧化碳（\\(\\mathrm{CO_2}\\)）及一种未知气态产物 \\(\\mathrm{X}\\)。（已知 \\(A_r\\): \\(\\mathrm{C}=12, \\mathrm{H}=1, \\mathrm{O}=16\\)）(1) 求未知产物 \\(\\mathrm{X}\\) 的质量；(2) 通过元素质量守恒计算推断 \\(\\mathrm{X}\\) 的化学式，并求其摩尔质量。","clues":"注意投料是否恰好完全燃烧：\\(4.6\\text{ g}\\) 乙醇（\\(0.10\\text{ mol}\\)）完全燃烧生成 \\(\\mathrm{CO_2}\\) 需 \\(9.6\\text{ g }\\mathrm{O_2}\\)，现在只有 \\(8.0\\text{ g }\\mathrm{O_2}\\)，属于不完全燃烧！","strategy":"(1) 密闭容器总质量守恒直接差减求 \\(m(\\mathrm{X})\\)；(2) 依据原反应物中 C、H、O 各自总质量减去 \\(\\mathrm{H_2O}, \\mathrm{CO_2}\\) 中所含 C、H、O 质量，算出 X 中元素组成与最简原子数比。","given":"m(C₂H₆O) = 4.6 g，m(O₂) = 8.0 g，m(H₂O) = 5.4 g，m(CO₂) = 4.4 g","principle":"物质不灭定律：反应前后总质量守恒，且各元素自身质量与原子数分别守恒。","steps":["第(1)问：根据物质不灭定律，密闭容器反应前后物质总质量相等：\\(4.6\\text{ g} + 8.0\\text{ g} = 5.4\\text{ g} + 4.4\\text{ g} + m(\\mathrm{X}) \\implies m(\\mathrm{X}) = 12.6\\text{ g} - 9.8\\text{ g} = 2.8\\text{ g}\\)。","第(2)问：计算反应物中各元素总质量（\\(M_r(\\mathrm{C_2H_6O}) = 46\\)）：\\(m_{\\text{总}}(\\mathrm{C}) = 4.6 \\times \\frac{24}{46} = 2.4\\text{ g}\\)；\\(m_{\\text{总}}(\\mathrm{H}) = 4.6 \\times \\frac{6}{46} = 0.6\\text{ g}\\)；\\(m_{\\text{总}}(\\mathrm{O}) = (4.6 - 2.4 - 0.6) + 8.0 = 9.6\\text{ g}\\)。","计算已检出产物 \\(\\mathrm{CO_2}\\) 和 \\(\\mathrm{H_2O}\\) 所含元素质量：\\(m_{\\text{产}}(\\mathrm{C}) = 4.4 \\times \\frac{12}{44} = 1.2\\text{ g}\\)；\\(m_{\\text{产}}(\\mathrm{H}) = 5.4 \\times \\frac{2}{18} = 0.6\\text{ g}\\)；\\(m_{\\text{产}}(\\mathrm{O}) = (4.4 - 1.2) + (5.4 - 0.6) = 3.2 + 4.8 = 8.0\\text{ g}\\)。","由元素质量守恒差减得产物 \\(\\mathrm{X}\\) 中元素组成：\\(m_\\mathrm{X}(\\mathrm{C}) = 2.4 - 1.2 = 1.2\\text{ g}\\)；\\(m_\\mathrm{X}(\\mathrm{H}) = 0.6 - 0.6 = 0\\text{ g}\\)；\\(m_\\mathrm{X}(\\mathrm{O}) = 9.6 - 8.0 = 1.6\\text{ g}\\)（校核 \\(1.2 + 1.6 = 2.8\\text{ g}\\) 完全吻合）。","求 X 中原子个数比：\\(n(\\mathrm{C}) : n(\\mathrm{O}) = \\frac{1.2}{12} : \\frac{1.6}{16} = 0.10 : 0.10 = 1 : 1\\)，结合含碳气态不完全燃烧产物，\\(\\mathrm{X}\\) 为 \\(\\mathrm{CO}\\)（一氧化碳，摩尔质量 \\(28\\text{ g/mol}\\)）。"],"answer":"(1) \\(m(\\mathrm{X}) = 2.8\\text{ g}\\)；(2) \\(\\mathrm{X}\\) 的化学式为 \\(\\mathrm{CO}\\)，摩尔质量 \\(28\\text{ g\\,mol}^{-1}\\)。","markingPoints":["正确算出 m(X) = 2.8 g（1分）","正确求出乙醇和 O₂ 提供的 C、H、O 总质量（2分）","差减得到 X 含 1.2 g C 与 1.6 g O 且不含 H（2分）","求得原子比 1:1 并定出 X 为 CO（1分）"],"verification":"把全反应写为 \\(0.1\\mathrm{C_2H_6O} + 0.25\\mathrm{O_2} \\to 0.1\\mathrm{CO_2} + 0.1\\mathrm{CO} + 0.3\\mathrm{H_2O}\\)，两边均含 \\(0.2\\text{ C}, 0.6\\text{ H}, 0.6\\text{ O}\\)。","pitfall":"催化剂质量反应前后不变（前=后），本题反应前 X 为 0 g、反应后 2.8 g，绝不可能是催化剂。"},{"label":"例 3.2.2","tier":"L3","tierLabel":"L3 预试拔高","title":"无需原子量的倍比定律纯代数推导","prompt":"（教材 p.66 思考题 3e 第3题）由 \\(\\mathrm{A}, \\mathrm{B}\\) 两种元素组成的化合物 \\(\\mathrm{R}\\) 和 \\(\\mathrm{S}\\)，经实验测定 \\(\\mathrm{R}\\) 中含元素 \\(\\mathrm{A}\\) 的质量百分比为 \\(44.0\\%\\)，\\(\\mathrm{S}\\) 中含元素 \\(\\mathrm{A}\\) 的质量百分比为 \\(34.4\\%\\)。已知 \\(\\mathrm{R}\\) 的化学式为 \\(\\mathrm{AB_2}\\)，试推求化合物 \\(\\mathrm{S}\\) 的化学式。","clues":"题干根本没有给 \\(\\mathrm{A}\\) 和 \\(\\mathrm{B}\\) 的相对原子质量，说明一定不能直接用质量除以 \\(A_r\\)，必须运用倍比定律“固定 \\(m(\\mathrm{A})\\)，比较 \\(m(\\mathrm{B})\\) 之比等于原子下标比”！","strategy":"固定两种化合物中元素 A 的质量均为 \\(1.00\\text{ g}\\)，算出各自结合的元素 B 质量再做比。","given":"R(AB₂): w(A)=44.0%, w(B)=56.0%；S(ABn): w(A)=34.4%, w(B)=65.6%","principle":"倍比定律：固定 A 的质量时，R 与 S 中结合的 B 元素质量之比等于每个 A 原子结合的 B 原子数目之比。","steps":["在化合物 \\(\\mathrm{R}\\)（\\(\\mathrm{AB_2}\\)）中，\\(w(\\mathrm{B}) = 100\\% - 44.0\\% = 56.0\\%\\)。每 \\(1.00\\text{ g}\\) 元素 \\(\\mathrm{A}\\) 所结合的元素 \\(\\mathrm{B}\\) 质量为：\\(\\frac{m_{\\mathrm{R}}(\\mathrm{B})}{m_{\\mathrm{R}}(\\mathrm{A})} = \\frac{56.0}{44.0} \\approx 1.273\\text{ g}\\)。","在化合物 \\(\\mathrm{S}\\)（设化学式为 \\(\\mathrm{AB}_n\\)）中，\\(w(\\mathrm{B}) = 100\\% - 34.4\\% = 65.6\\%\\)。每 \\(1.00\\text{ g}\\) 元素 \\(\\mathrm{A}\\) 所结合的元素 \\(\\mathrm{B}\\) 质量为：\\(\\frac{m_{\\mathrm{S}}(\\mathrm{B})}{m_{\\mathrm{S}}(\\mathrm{A})} = \\frac{65.6}{34.4} \\approx 1.907\\text{ g}\\)。","依据倍比定律，固定 \\(\\mathrm{A}\\) 为 \\(1.00\\text{ g}\\) 时，\\(\\mathrm{R}\\) 与 \\(\\mathrm{S}\\) 中 \\(\\mathrm{B}\\) 元素的质量比等于两分子中每个 \\(\\mathrm{A}\\) 原子结合的 \\(\\mathrm{B}\\) 原子数之比：\\(\\frac{2}{n} = \\frac{1.273}{1.907} \\approx \\frac{2}{3} \\implies n = 3\\)。"],"answer":"化合物 \\(\\mathrm{S}\\) 的化学式为 \\(\\mathrm{AB_3}\\)。","markingPoints":["避免直接比百分比，先固定 A 质量求出 R、S 中 m(B)/m(A)（2分）","利用倍比比例 1.273 : 1.907 = 2 : 3 导出 B 原子数 n=3（2分）"],"verification":"反向验证：若 \\(A_r(\\mathrm{A}) : A_r(\\mathrm{B}) = 11 : 7\\)，则 \\(\\mathrm{AB_3}\\) 中 \\(w(\\mathrm{A}) = 11 / (11 + 21) = 11 / 32 = 34.375\\% \\approx 34.4\\%\\)。","pitfall":"若拿 \\(44.0\\% : 34.4\\%\\) 去比，得出非整数 \\(1.28\\) 会彻底迷路。"}],"practice":[{"id":"chem3-3.2-q1","tier":"L1","tierLabel":"L1 基础","examStyle":"P1 选择","q":"下列现象能用**物质不灭定律**解释的是（　）。","options":["A. 10 g 冰融化后仍然得到 10 g 液态水","B. 1 L 芝麻和 1 L 大米混合后总体积小于 2 L","C. 将 5 g 食盐完全溶解于 95 g 水中得到 100 g 食盐水","D. 生石灰（CaO）吸收空气中的水蒸气变为熟石灰（Ca(OH)₂），固体质量增加"],"correctOption":"D","given":"四种过程判断","method":"识别哪个过程属于化学反应","principle":"物质不灭定律仅适用于化学变化。","steps":["A 冰融化、B 混合体积、C 物理溶解均没有新物质生成，属物理变化。","D \\(\\mathrm{CaO + H_2O \\to Ca(OH)_2}\\) 属于化合反应，固体增重的质量恰好等于参加反应的水的质量。"],"ans":"D","markingPoints":["判断化学反应归属"],"verification":"对照教材 p.73 第6题原选项构造。","pitfall":"把固体表观“增重”误认为不守恒。"},{"id":"chem3-3.2-q2","tier":"L2","tierLabel":"L2 期末","examStyle":"P1 选择","q":"根据教材活动探究2：已知 \\(2.0\\text{ g NaOH}\\) 恰好能与 \\(6.25\\text{ g }\\mathrm{CuSO_4\\cdot 5H_2O}\\) 完全反应，生成 \\(2.45\\text{ g}\\) 干燥的 \\(\\mathrm{Cu(OH)_2}\\) 沉淀。若实验室将 \\(3.0\\text{ g NaOH}\\) 与 \\(6.25\\text{ g }\\mathrm{CuSO_4\\cdot 5H_2O}\\) 充分混合反应，则下列说法正确的是（　）。","options":["A. 根据物质不灭定律，沉淀质量会变为 3.68 g","B. 反应得到 Cu(OH)₂ 沉淀质量仍为 2.45 g，剩余 1.0 g NaOH 未反应","C. 得到的 Cu(OH)₂ 沉淀中铜元素质量分数会因 NaOH 过量而下降","D. 该实验直接证明了化学反应中的倍比定律"],"correctOption":"B","given":"2.0 g NaOH 完全对应 6.25 g CuSO₄·5H₂O 产生 2.45 g Cu(OH)₂","method":"限量试剂判别 + 定比定律","principle":"化学反应按固定质量比进行，过量试剂不改变生成物产量与组成。","steps":["\\(6.25\\text{ g}\\) 胆矾最多消耗 \\(2.0\\text{ g NaOH}\\)，故加入 \\(3.0\\text{ g NaOH}\\) 时胆矾为限量反应物，有 \\(1.0\\text{ g NaOH}\\) 过量剩余。","实际生成 \\(\\mathrm{Cu(OH)_2}\\) 质量仍为 \\(2.45\\text{ g}\\)；依定比定律，纯净产物 \\(\\mathrm{Cu(OH)_2}\\) 元素质量比固定不变。","此实验探究的是**定比定律**（活动探究2 p.48），并非倍比定律。"],"ans":"B","markingPoints":["识别 NaOH 过量 1.0 g 且沉淀保持 2.45 g"],"verification":"\\(\\mathrm{NaOH}\\) 与 \\(\\mathrm{CuSO_4\\cdot 5H_2O}\\) 反应计量比 \\(2:1\\)。","pitfall":"误把多余投料也按正比扩大产物质量。"},{"id":"chem3-3.2-q3","tier":"L3","tierLabel":"L3 预试","examStyle":"P2 实验探究","q":"（教材 p.75–76 探究题深化）某小组用两个敞口装置探究化学反应前后的质量变化：**装置甲**将盛有 \\(\\mathrm{BaCl_2}\\) 溶液的小试管放入盛有 \\(\\mathrm{Na_2SO_4}\\) 溶液的烧杯中平衡再倾倒混合；**装置乙**将打磨光亮的镁条与石棉网一起平衡后在石棉网上方点燃镁条，反应完将全部所得固体连石棉网放回天平称量。(1) 装置甲中混合后有何现象？天平是否平衡？写出化学方程式。(2) 装置乙中按 \\(\\mathrm{2Mg + O_2 \\to 2MgO}\\) 理论预测质量应变重，但实测反而变轻了！请写出两条合理原因，并提出使装置乙也能严格验证物质不灭定律的改进方案。","given":"甲：BaCl₂+Na₂SO₄ 敞口烧杯；乙：敞口石棉网烧镁条","method":"从反应物态、敞口体系白烟逸散、仪器热效应与封闭气密性设计分析探究误差","principle":"物质不灭定律要求密闭体系且避免烟尘与气体出入。","steps":["(1) 甲装置中生成不溶于水的 \\(\\mathrm{BaSO_4}\\) 白色沉淀；由于既无气体生成也没有气体逸出，放回天平后**仍然保持平衡**；方程式：\\(\\mathrm{BaCl_2(aq) + Na_2SO_4(aq) \\longrightarrow BaSO_4(s)\\downarrow + 2NaCl(aq)}\\)。","(2) 乙装置质量意外减轻的主要原因：①镁条剧烈燃烧生成大量氧化镁**白烟逸散到空气中**，逸出的氧化镁质量大于结合的氧气质量；②部分生成物 \\(\\mathrm{MgO}\\) 飞溅掉落未完全收回石棉网（或未等冷却至室温就称量，热空气上升对流使示数偏小）。","改进方案：将镁条置于**密闭耐热容器**（例如底铺干燥细沙并套紧橡胶气球塞的锥形瓶或密封石英管）中引燃反应，**冷却至室温后再称量**。"],"ans":"(1) 产生白色沉淀；天平仍然平衡；BaCl₂+Na₂SO₄→BaSO₄↓+2NaCl。(2) 白烟（MgO）逸散到空气中且带走质量大于吸收的氧气质量、固体产物飞溅未完全收集（或热对流浮力干扰）；改用密闭容器反应并冷却至室温后再称量。","markingPoints":["现象（白色沉淀）、平衡结论及正确方程式（2分）","准确指出 MgO 白烟逸散质量大于吸收 O₂ 质量（2分）","提出密闭+冷却再称量的科学改进方案（2分）"],"verification":"紧扣教材 p.75–76 图甲、图乙与 p.46 活动探究1 细沙/塞子/冷却设计。","pitfall":"若答成“镁条反应违反物质不灭定律”直接零分；或忘记写“密闭+冷却”会丢完整改进分。"},{"id":"chem3-3.2-q4","tier":"L3","tierLabel":"L3 预试","examStyle":"P2 必答计算","q":"（教材 p.75 作答题第1题精算）有一种被称为“笑气”的氮氧化物样品，经测定含氮元素 \\(2.62\\text{ g}\\)、氧元素 \\(1.50\\text{ g}\\)；另一种氮氧化物则是常见空气污染物，样品中含氮元素 \\(0.655\\text{ g}\\)、氧元素 \\(1.50\\text{ g}\\)。请通过定量计算证明上述数据符合倍比定律，并结合 \\(A_r(\\mathrm{N})=14.0, A_r(\\mathrm{O})=16.0\\) 推断两种氧化物的实验式。","given":"甲（笑气）：m(N)=2.62 g, m(O)=1.50 g；乙（污染物）：m(N)=0.655 g, m(O)=1.50 g","method":"利用 O 质量已恰好相等（均为 1.50 g）直接比 N 质量，并算原子比定式","principle":"倍比定律：固定 O 的质量，两种氧化物中 N 元素质量呈简单整数比。","steps":["两样品中氧元素的质量已经相等（均为 \\(1.50\\text{ g}\\)），可直接比较其中氮元素的质量比：\\(\\frac{m_{\\text{甲}}(\\mathrm{N})}{m_{\\text{乙}}(\\mathrm{N})} = \\frac{2.62\\text{ g}}{0.655\\text{ g}} = 4.00 = \\frac{4}{1}\\)。","比值为简单整数比 \\(4:1\\)，证明两组实验数据严格符合**倍比定律**。","求实验式（甲）：\\(n(\\mathrm{N}):n(\\mathrm{O}) = \\frac{2.62}{14.0} : \\frac{1.50}{16.0} = 0.1871 : 0.09375 \\approx 2.00 : 1\\)，实验式为 \\(\\mathrm{N_2O}\\)。","求实验式（乙）：\\(n(\\mathrm{N}):n(\\mathrm{O}) = \\frac{0.655}{14.0} : \\frac{1.50}{16.0} = 0.04679 : 0.09375 \\approx 1 : 2.00\\)，实验式为 \\(\\mathrm{NO_2}\\)。"],"ans":"氧均取 \\(1.50\\text{ g}\\) 时，氮元素质量比 \\(2.62 : 0.655 = 4 : 1\\)，符合倍比定律；实验式分别为 \\(\\mathrm{N_2O}\\) 和 \\(\\mathrm{NO_2}\\)。","markingPoints":["利用相同氧质量 1.50 g 算出氮质量比 4:1（2分）","算得原子数比分别推出 N₂O 与 NO₂（2分）"],"verification":"\\(2.62/0.655 = 4.000\\) 整除；\\(0.1871/0.09375 = 1.996 \\approx 2\\)。","pitfall":"直接拿百分比比值或忘记求最简整数比。"},{"id":"chem3-3.2-q5","tier":"L4","tierLabel":"L4 统考压轴","examStyle":"P2 综合压轴","q":"某金属元素 \\(\\mathrm{M}\\) 能与氧元素形成两种纯净氧化物 \\(\\mathrm{MO}\\) 和 \\(\\mathrm{M}_x\\mathrm{O}_y\\)。在定量实验中，另取纯 \\(\\mathrm{M}\\) 单质 \\(11.20\\text{ g}\\) 在足量氧中直接生成 \\(\\mathrm{MO}\\) 需耗氧 \\(3.20\\text{ g}\\)；此外将 \\(21.60\\text{ g}\\) 纯 \\(\\mathrm{MO}\\) 置于氧气流中高温充分氧化，最终全部转化为 \\(23.20\\text{ g}\\) 氧化物 \\(\\mathrm{M}_x\\mathrm{O}_y\\)。试求（已知 \\(A_r(\\mathrm{O})=16.0\\)）：(1) 金属 \\(\\mathrm{M}\\) 的相对原子质量；(2) 高价氧化物 \\(\\mathrm{M}_x\\mathrm{O}_y\\) 的实验式；(3) 写出 \\(\\mathrm{MO}\\) 转化为 \\(\\mathrm{M}_x\\mathrm{O}_y\\) 的配平化学方程式，并验证 \\(\\mathrm{MO}\\) 与 \\(\\mathrm{M}_x\\mathrm{O}_y\\) 符合倍比定律。","given":"11.20 g M + 3.20 g O → 14.40 g MO；21.60 g MO + O₂ → 23.20 g MxOy","method":"定比定律求 Ar(M) → 元素质量守恒求 MxOy 中 M 与 O 质量 → 原子数比定式","principle":"元素质量在化学转化过程中完全守恒；定比与倍比定律联动。","steps":["第(1)问：由纯 \\(\\mathrm{M}\\) 生成 \\(\\mathrm{MO}\\) 中，原子比 \\(1:1\\)，故 \\(\\frac{11.20}{A_r(\\mathrm{M})} = \\frac{3.20}{16.0} = 0.200\\text{ mol} \\implies A_r(\\mathrm{M}) = \\frac{11.20}{0.200} = 56.0\\)。","第(2)问：在 \\(21.60\\text{ g MO}\\) 中（\\(M_r(\\mathrm{MO}) = 56.0 + 16.0 = 72.0\\)），金属 \\(\\mathrm{M}\\) 的物质的量为 \\(n(\\mathrm{M}) = \\frac{21.60}{72.0} = 0.300\\text{ mol}\\)，其质量 \\(m(\\mathrm{M}) = 0.300 \\times 56.0 = 16.80\\text{ g}\\)。","转化为 \\(23.20\\text{ g}\\ \\mathrm{M}_x\\mathrm{O}_y\\) 后，金属 \\(\\mathrm{M}\\) 质量守恒仍为 \\(16.80\\text{ g}\\)，则 \\(\\mathrm{M}_x\\mathrm{O}_y\\) 中总氧质量：\\(m(\\mathrm{O}) = 23.20\\text{ g} - 16.80\\text{ g} = 6.40\\text{ g}\\)，即 \\(n(\\mathrm{O}) = \\frac{6.40}{16.0} = 0.400\\text{ mol}\\)。","故原子个数比 \\(n(\\mathrm{M}) : n(\\mathrm{O}) = 0.300 : 0.400 = 3 : 4\\)，实验式为 \\(\\mathrm{M_3O_4}\\)。","第(3)问：配平方程式为 \\(\\mathrm{6MO(s) + O_2(g)} \\xrightarrow{\\Delta} \\mathrm{2M_3O_4(s)}\\)；同固定 \\(16.80\\text{ g M}\\)（\\(0.300\\text{ mol}\\)）时，\\(\\mathrm{MO}\\) 结合氧 \\(4.80\\text{ g}\\) 而 \\(\\mathrm{M_3O_4}\\) 结合氧 \\(6.40\\text{ g}\\)，质量比为 \\(4.80:6.40 = 3:4\\) 为简单整数比，严格符合倍比定律。"],"ans":"(1) \\(A_r(\\mathrm{M}) = 56.0\\)；(2) \\(\\mathrm{M_3O_4}\\)；(3) \\(\\mathrm{6MO + O_2} \\xrightarrow{\\Delta} \\mathrm{2M_3O_4}\\)，固定 M 时氧质量比 \\(3:4\\)。","markingPoints":["算出 Ar(M) = 56.0（1分）","守恒算出 21.60 g MO 含 M 16.80 g 并求得 M₃O₄ 中总 O 为 6.40 g（2分）","求得比值 3:4 及配平方程式、倍比验证 3:4（2分）"],"verification":"\\(21.60\\text{ g MO}\\)（\\(0.300\\text{ mol}\\)）吸收 \\(1.60\\text{ g O}\\)（\\(0.050\\text{ mol }\\mathrm{O_2}\\)）变成 \\(0.100\\text{ mol }\\mathrm{M_3O_4}\\)（\\(0.100\\times 232 = 23.20\\text{ g}\\)），数值完全精确。","pitfall":"算出反应增重 1.60 g 氧后忘记加回原有 4.80 g 氧，会误算成 M₃O₁。"}],"cheatSheet":["物质不灭看同一反应前后（六个不变：总质量/元素种类与质量/原子种类·数目·质量），切忌漏气体或白烟。","定比看同一种纯净化合物；倍比看同两元素≥2种化合物，必先“固定甲元素质量”再比乙。","活动探究1：密闭锥形瓶铺干燥细沙、冷却至室温称量；活动探究2：过量 NaOH 不增产物 Cu(OH)₂（2.45 g）。"],"kbEntryIds":["kb-chem3-conservation","kb-chem3-exp1","kb-chem3-definite","kb-chem3-exp2","kb-chem3-multiple"],"quiz":{"q":"将 \\(6.0\\text{ g}\\) 镁带在充足氧气中完全燃烧后，测得生成氧化镁 \\(10.0\\text{ g}\\)。若仅取镁元素含量相同的某氧化镁样品 \\(5.0\\text{ g}\\)，其中含氧元素多少克？（依据定比与物质不灭定律）","given":"6.0 g Mg 生成 10.0 g MgO","method":"先求反应消耗 O₂ 质量，再用定比定律按比例缩减","principle":"物质不灭定律与定比定律。","steps":["10.0 g MgO 中消耗氧气 = 10.0 - 6.0 = 4.0 g。","依定比定律，5.0 g MgO 中含氧 = 4.0 × (5.0 / 10.0) = 2.0 g。"],"ans":"\\(2.0\\text{ g}\\)"},"diagrams":[{"src":"assets/fig/v2/chem03-laws-compare.svg","caption":"图 3-2 化学反应与物质组成的三大基本定量定律及活动探究对照","alt":"物质不灭定律、定比定律与倍比定律对比图","pageRef":"化上 p.45–50"}]},{"id":"3.3","t":"原子与相对原子质量","anchor":{"pages":"化上 p.51–57","syllabus":"1.1.2 原子构成、质谱仪与相对原子质量（Ar）","examScopes":["sem1_final","pre_exam","sem2_final","uec"],"examWeight":"P1 粒子数与质量数基础题 + 同位素质量/原子百分比与质谱峰比（预试/统考区分度题）","terms":"proton · neutron · electron · mass spectrometer · relative atomic mass · amu","prerequisites":["原子不可再分概念的历史修正（3.1.1）","科学记数法与加权平均数计算"],"goals":["熟练计算原子及单核/多核离子的质子数、中子数、核电荷数与核外电子数。","说明质谱仪测定原子（或分子）相对质量的四个环节与磁场偏转判据。","掌握以 ¹²C 原子质量的 1/12 为标准的 Ar 定义与单位规范，并能进行同位素加权平均及质量分数转换计算。"]},"concepts":[{"kind":"definition","title":"3.3.1 原子的构成与核素表示 \\({}^A_Z\\mathrm{X}\\)","pageRef":"化上 p.51–52、p.57","body":["**三大亚原子微粒**：原子由居于中心带正电的**原子核**（质子 + 中子）和核外带负电的**电子**构成。原子的质量 \\(99.9\\%\\) 以上集中在原子核上，而原子核体积不到原子总体积的万亿分之一。","**关键等量关系**：","- 对**中性原子**：核电荷数 = 质子数（\\(Z\\)）= 核外电子数。","- **质量数（\\(A\\)）** = 质子数（\\(Z\\)）+ 中子数（\\(N\\)），记作 \\({}^A_Z\\mathrm{X}\\)（如 \\({}^{23}_{11}\\mathrm{Na}\\) 含 11 质子、12 中子、11 电子）。","- 对**离子**：阳离子 \\(\\mathrm{X}^{c+}\\) 核外电子数 = \\(Z - c\\)；阴离子 \\(\\mathrm{X}^{a-}\\) 核外电子数 = \\(Z + a\\)。**注意**：得失电子改变化学性质与电荷，**不改变质子数和质量数**。"],"takeaway":"唯一不含中子的常见天然原子是氕（\\({}^1_1\\mathrm{H}\\)），其原子核只有 1 个质子；电子质量约为质子的 1/1836。"},{"kind":"table","title":"三种基本微粒参数与教材表3-3 原子实际质量基准","pageRef":"化上 p.54–57","body":["考试常考质子、中子、电子电荷/相对质量比较及 \\(1\\text{ amu}\\) 换算："],"table":{"headers":["微粒 / 原子","实测实际质量（kg）","相对质量 / 电量","教材关键要点（p.56–57）"],"rows":[["质子 (p⁺)","1.6726 × 10⁻²⁷","相对质量 ≈ 1，带 +1 单位正电荷","决定元素种类（原子序数 Z）"],["中子 (n)","1.6748 × 10⁻²⁷","相对质量 ≈ 1，呈电中性（0）","质子与中子质量约等于 1 amu"],["电子 (e⁻)","≈ 1/1836 m_p","相对质量可忽略，带 -1 单位负电荷","决定原子主要化学性质与成键"],["¹²C（6p + 6n）","1.993 × 10⁻²⁶","定义标准 Ar(¹²C) = 12.0000","1 amu = (1/12)m(¹²C) = 1.661 × 10⁻²⁷ kg"],["表3-3：H / O / Fe","H: 1.674×10⁻²⁷；O: 2.657×10⁻²⁶；Fe: 9.277×10⁻²⁶","Ar: H≈1.008；O≈16.00；Fe≈55.85","由表3-4算得（除以 1.661×10⁻²⁷ kg）"]]}},{"kind":"experiment","title":"3.3.2 质谱仪工作原理与相对原子质量标准演变","pageRef":"化上 p.53–56","body":["**质谱仪（Mass Spectrometer）四步流程（p.53）**：①将气体或气化样品送入电离室；②高速电子束轰击样品使原子/分子失去电子变成**正离子**；③电场将其加速为高速离子束；④进入**磁场**发生偏转——在相同电荷数和速度下，**离子质量越大，在磁场中偏转程度越小（轨迹半径越大）**，从而按质量大小分别打到检测器上记录丰度与质量。","**国际相对原子质量基准演变（p.55–56）**：","- 早年曾以 \\(\\mathrm{H}=1\\) 为标准 → 因氢标准下测其他元素误差不便改用 \\(\\mathrm{O}=16\\) → 发现氧存在 \\({}^{16}\\mathrm{O}, {}^{17}\\mathrm{O}, {}^{18}\\mathrm{O}\\) 同位素后，物理界取 \\({}^{16}\\mathrm{O}=16\\) 而化学界取天然氧混合物 \\(=16\\)，造成两套数值混乱；","- 1959–1961年国际物理学会与化学学会统一规定：以 **\\({}^{12}\\mathrm{C}\\) 原子实际质量的 \\(\\frac{1}{12}\\)** 为标准（1973年定名 **原子质量单位 `amu`**），从此物理与化学基准完全一致。"],"takeaway":"同电荷正离子进入质谱仪磁场：质量越大越难偏转（轨迹越靠外）；质谱峰高度对应同位素天然丰度。"},{"kind":"mechanism","title":"同位素加权平均 Ar vs 质谱分子离子峰（高阶拓展）","pageRef":"化上 p.55–56、p.110 衔接","body":["**元素的相对原子质量**并非单个原子的质量数，而是该元素天然所有稳定同位素的相对原子质量按**原子个数百分比（天然丰度）**加权平均的结果。例如氯有 \\({}^{35}\\mathrm{Cl}\\)（约 \\(75\\%\\)）与 \\({}^{37}\\mathrm{Cl}\\)（约 \\(25\\%\\)），故 \\(A_r(\\mathrm{Cl}) = 35\\times 0.75 + 37\\times 0.25 = 35.5\\)。","**UEC 高阶考向**：当双原子分子（如 \\(\\mathrm{Cl_2}\\)）进入质谱仪电离成 \\(\\mathrm{Cl_2^+}\\) 时，两个位置自由组合出质量数为 **70（¹⁵Cl-³⁵Cl）、72（³⁵Cl-³⁷Cl 与 ³⁷Cl-³⁵Cl）、74（³⁷Cl-³⁷Cl）** 三个分子离子峰，丰度比为 \\(0.75^2 : 2\\times 0.75\\times 0.25 : 0.25^2 = 9:6:1\\)！"],"takeaway":"天然同位素丰度默认指**原子个数比**，绝非质量百分比！需要求质量百分比时必须多乘一步各自质量数。"}],"formulas":[{"title":"相对原子质量与原子质量单位（amu）","tex":"A_r = \\frac{\\text{某原子的平均实际质量}}{\\frac{1}{12}\\,m({}^{12}\\mathrm{C})},\\qquad 1\\text{ amu} = 1.661\\times 10^{-27}\\text{ kg}","plain":"Ar = 原子平均实际质量 / [m(¹²C)/12]","conditions":"Ar 是纯比值，没有单位！注意 kg 与 g 换算（1.661×10⁻²⁴ g）","pageRef":"化上 p.55–57","note":"切勿给相对原子质量写上 g 或 g/mol。"},{"title":"核子组成与同位素加权平均公式","tex":"A = Z + N,\\qquad A_r(\\text{元素}) = \\sum_{i} A_{r,i}\\,x_i\\quad\\left(\\sum_i x_i = 1\\right)","plain":"质量数 A = 质子数 Z + 中子数 N；Ar = Σ(同位素 Ar × 原子分数)","conditions":"xᵢ 必须是天然原子个数百分比（摩尔分数），不是质量分数","pageRef":"化上 p.52, p.57","note":"已知元素平均 Ar 反求二元同位素比例时用十字交叉法最快。"}],"pitfalls":[{"title":"给相对原子质量强行加上‘g’或‘g/mol’单位","wrong":"“\\({}^{12}\\mathrm{C}\\) 的相对原子质量是 \\(12\\text{ g}\\)。”","diagnosis":"实际质量与标准质量之比是无量纲纯数（分子分母单位 kg 互相约去）。","right":"\\({}^{12}\\mathrm{C}\\) 的相对原子质量是 **\\(12\\)**（无单位）；\\(12\\text{ g\\,mol}^{-1}\\) 则是摩尔质量，\\(1.993\\times 10^{-26}\\text{ kg}\\) 是单个碳原子的实际质量。","checkRule":"凡选择题出现“相对原子质量为 12 g / 12 g·mol⁻¹”，一律直接判错（教材 p.73 第4题考点）。"},{"title":"把原子个数百分比直接当成质量百分比","wrong":"“已知氯元素中 \\({}^{35}\\mathrm{Cl}\\) 原子占 \\(75\\%\\)，则天然氯中 \\({}^{35}\\mathrm{Cl}\\) 的质量分数也是 \\(75\\%\\)。”","diagnosis":"\\({}^{35}\\mathrm{Cl}\\) 与 \\({}^{37}\\mathrm{Cl}\\) 每个原子的质量不同，各占总质量的比例不能忽略质量数权重。","right":"\\({}^{35}\\mathrm{Cl}\\) 的质量百分比为 \\(\\frac{75 \\times 35}{75 \\times 35 + 25 \\times 37} = \\frac{26.25}{35.5} = 73.94\\% < 75\\%\\)。","checkRule":"先核对题干问的是‘原子个数（物质的量）百分比’还是‘质量百分比’。"},{"title":"混淆原子质量、质量数与平均相对原子质量","wrong":"“氯元素的相对原子质量是 35.5，说明自然界中存在质量数为 35.5 的氯原子。”","diagnosis":"质量数是质子数与中子数之和，必为整数；35.5 是两种同位素的加权平均值。","right":"单个核素都有整数质量数（35 或 37）；元素的相对原子质量（35.5）是宏观天然混合样品的平均比值。","checkRule":"质量数 A ∈ 正整数，元素平均 Ar 可为小数。"}],"examples":[{"label":"例 3.3.1","tier":"L2","tierLabel":"L2 校内期末","title":"教材表3-4 原子实际质量求 Ar 与核内微粒分析","prompt":"（综合教材 p.56 表3-4 与 p.57 思考题 3c）(1) 已知 \\(1\\) 个 \\({}^{12}\\mathrm{C}\\) 原子的质量为 \\(1.993\\times 10^{-26}\\text{ kg}\\)，\\(1\\) 个铁原子的平均质量为 \\(9.277\\times 10^{-26}\\text{ kg}\\)，试通过严格计算求铁的相对原子质量（保留四位有效数字）；(2) 已知铬原子的核电荷数为 \\(24\\)，其一种核素的相对原子质量约为 \\(52\\)，求该铬原子的质子数、核外电子数及中子数。","clues":"用 \\({}^{12}\\mathrm{C}\\) 质量除以 12 得基准 \\(1\\text{ amu}\\)；注意区分“核电荷数=质子数”与“质量数≈中子数+质子数”。","strategy":"套用定义式 \\(A_r = m_{\\text{原子}} / [m({}^{12}\\mathrm{C})/12]\\) 及原子核组成等式 \\(A = Z + N\\)。","given":"m(¹²C)=1.993×10⁻²⁶ kg, m(Fe)=9.277×10⁻²⁶ kg；Cr: Z=24, A≈52","principle":"相对原子质量 ¹²C 基准与原子电中性条件。","steps":["第(1)问：先求标准基准 \\(1\\text{ amu} = \\frac{1.993\\times 10^{-26}\\text{ kg}}{12} = 1.6608\\times 10^{-27}\\text{ kg} \\approx 1.661\\times 10^{-27}\\text{ kg}\\)。","代入铁原子的实际质量求相对原子质量：\\(A_r(\\mathrm{Fe}) = \\frac{9.277\\times 10^{-26}\\text{ kg}}{1.661\\times 10^{-27}\\text{ kg}} = 55.85\\)（注意 kg 单位消去，结果无单位）。","第(2)问：在中性铬原子中，质子数 = 核电荷数 = 核外电子数 = \\(24\\)；中子数 \\(N \\approx A - Z = 52 - 24 = 28\\)。"],"answer":"(1) 铁的相对原子质量为 \\(55.85\\)；(2) 质子数 \\(24\\)、核外电子数 \\(24\\)、中子数 \\(28\\)。","markingPoints":["正确计算 1/12 m(¹²C) = 1.661×10⁻²⁷ kg（1分）","求得 Ar(Fe) = 55.85 且未加多余单位（2分）","准确给出铬原子的三类微粒数 24、24、28（1分）"],"verification":"与教材表3-4及元素周期表 Fe = 55.845 一致。","pitfall":"指数相除易失误：\\(10^{-26} / 10^{-27} = 10^1 = 10\\)，务必先对齐指数。"},{"label":"例 3.3.2","tier":"L4","tierLabel":"L4 统考压轴","title":"同位素丰度质量分数辨析与 Cl₂ 质谱峰分布","prompt":"天然氯元素主要由 \\({}^{35}\\mathrm{Cl}\\)（相对原子质量 \\(35.0\\)）和 \\({}^{37}\\mathrm{Cl}\\)（相对原子质量 \\(37.0\\)）两种稳定同位素组成，测得天然氯元素的平均相对原子质量为 \\(35.5\\)。试求：(1) 两种同位素的**原子个数百分比**（摩尔分数）；(2) 天然氯中 \\({}^{35}\\mathrm{Cl}\\) 的**质量百分比**；(3) 将纯 \\(\\mathrm{Cl_2}\\) 气体通入质谱仪电离形成 \\(\\mathrm{Cl_2^+}\\) 分子离子时，质谱图会出现几条分子离子峰？其质荷比（相对分子质量）与峰强度比分别是多少？","clues":"注意第(1)问和第(2)问分母不同；第(3)问把两个氯位置看作独立随机抽取同位素！","strategy":"用十字交叉求原子比 → 加权质量总和求质量分数 → 按组合概率 \\((p+q)^2 = p^2 + 2pq + q^2\\) 算分子离子峰。","given":"Ar(³⁵Cl)=35.0, Ar(³⁷Cl)=37.0, Ar(Cl)=35.5","principle":"同位素加权平均及二项分布分子离子统计。","steps":["第(1)问：设 \\({}^{35}\\mathrm{Cl}\\) 原子分数为 \\(x\\)，则 \\(35.0x + 37.0(1-x) = 35.5 \\implies 2.0x = 1.5 \\implies x = 0.750\\)。即 \\({}^{35}\\mathrm{Cl}\\) 占 **\\(75.0\\%\\)**，\\({}^{37}\\mathrm{Cl}\\) 占 **\\(25.0\\%\\)**（原子比 \\(3:1\\)）。","第(2)问：取 \\(1\\text{ mol}\\) 天然氯原子（质量为 \\(35.5\\text{ g}\\)），内含 \\(0.750\\text{ mol}\\ {}^{35}\\mathrm{Cl}\\)（质量 \\(0.750 \\times 35.0 = 26.25\\text{ g}\\)），故其质量百分比为：\\(w({}^{35}\\mathrm{Cl}) = \\frac{26.25}{35.5} \\times 100\\% = 73.94\\%\\)。","第(3)问：两氯原子在分子中共有 3 种相对质量组合（3条峰）：","- \\(M = 35 + 35 = 70\\)（\\({}^{35}\\mathrm{Cl}-{}^{35}\\mathrm{Cl}\\)）：概率 \\(0.75^2 = \\frac{9}{16}\\)；","- \\(M = 35 + 37 = 72\\)（\\({}^{35}\\mathrm{Cl}-{}^{37}\\mathrm{Cl}\\) 与 \\({}^{37}\\mathrm{Cl}-{}^{35}\\mathrm{Cl}\\)）：概率 \\(2 \\times 0.75 \\times 0.25 = \\frac{6}{16}\\)；","- \\(M = 37 + 37 = 74\\)（\\({}^{37}\\mathrm{Cl}-{}^{37}\\mathrm{Cl}\\)）：概率 \\(0.25^2 = \\frac{1}{16}\\)。","故质谱图呈现 \\(70, 72, 74\\) 三条分子离子峰，相对强度比为 **\\(9 : 6 : 1\\)**。"],"answer":"(1) 原子占比 ³⁵Cl 75.0%、³⁷Cl 25.0%；(2) ³⁵Cl 质量分数 73.94%；(3) 3条峰（70, 72, 74），强度比 9 : 6 : 1。","markingPoints":["正确算出原子占比 75% 与 25%（1分）","区分质量百分比与原子百分比并算得 73.94%（2分）","写出 M=70,72,74 且 72 计入系数 2 得到 9:6:1（2分）"],"verification":"\\((0.75 + 0.25)^2 = 9/16 + 6/16 + 1/16 = 1\\)；若只算成 3:2:1（漏了对称排列系数 2）是典型扣分点。","pitfall":"计算 \\(M=72\\) 的峰强度时千万不要漏掉“第一个是 35、第二个是 37”与“第一个是 37、第二个是 35”两种等同组合。"}],"practice":[{"id":"chem3-3.3-q1","tier":"L1","tierLabel":"L1 基础","examStyle":"P1 选择","q":"\\({}^{12}\\mathrm{C}\\) 的相对原子质量是（　）。","options":["A. 12 g","B. 12","C. 1.993 × 10⁻²⁶ kg","D. 1.993 × 10⁻²⁶"],"correctOption":"B","given":"¹²C 原子标准","method":"对照相对原子质量定义与无单位规范","principle":"相对原子质量是与标准比值，无量纲单位。","steps":["A 错：12 g 是 1 mol ¹²C 的质量（摩尔质量 12 g/mol 的数值配克）。","B 对：国际统一将 ¹²C 相对原子质量定为纯比值 12。","C 是单个 ¹²C 原子的实际质量，D 缺少单位且数值不是相对原子质量。"],"ans":"B","markingPoints":["确认 Ar 无单位"],"verification":"教材 p.73 第4题原题巩固。","pitfall":"选 A 或 C 混淆实际质量、摩尔质量与相对原子质量。"},{"id":"chem3-3.3-q2","tier":"L2","tierLabel":"L2 期末","examStyle":"P1 选择","q":"某中性原子中共有 \\(40\\) 个质子、中子与电子粒子，其中有 \\(14\\) 个粒子不带电；另一种常见三价阳离子 \\(\\mathrm{R}^{3+}\\) 核外也有 \\(10\\) 个电子，质量数为 \\(27\\)。则原中性原子的质子数与离子 \\(\\mathrm{R}^{3+}\\) 的中子数分别为（　）。","options":["A. 13 和 14","B. 26 和 14","C. 13 和 17","D. 14 和 13"],"correctOption":"A","given":"中性原子：Z+N+e=40，N=14；离子 R³⁺：电子数=10，A=27","method":"利用电中性条件 Z=e 求解质子数，再对离子还原 Z=电子数+电荷","principle":"中子不带电；阳离子核外电子数 = Z − 电荷数。","steps":["中性原子不带电粒子即中子 \\(N = 14\\)，故质子数+电子数 \\(Z + e = 40 - 14 = 26\\)。因中性 \\(Z = e\\)，得质子数 \\(Z = 13\\)。","离子 \\(\\mathrm{R}^{3+}\\) 核外有 \\(10\\) 个电子，说明失去 3 个电子前原子质子数 \\(Z_{\\mathrm{R}} = 10 + 3 = 13\\)，其中子数 \\(N_{\\mathrm{R}} = A - Z = 27 - 13 = 14\\)（两者其实都是铝元素 \\({}^{27}_{13}\\mathrm{Al}\\)！）。"],"ans":"A","markingPoints":["结合教材 p.73 第5题与离子电子数转化"],"verification":"Al: 13p + 14n + 13e = 40 个粒子；Al³⁺: 10e + 13p + 14n。","pitfall":"算 R³⁺ 质子数时误减成 10 − 3 = 7。"},{"id":"chem3-3.3-q3","tier":"L2","tierLabel":"L2 期末","examStyle":"P2 必答计算","q":"(1) 在质谱仪测试 \\(\\mathrm{Ne}\\) 气体样品时，产生 \\({}^{20}\\mathrm{Ne^+}\\) 和 \\({}^{22}\\mathrm{Ne^+}\\) 两种单电荷正离子，在相同加速电场下垂直进入同一匀强磁场，哪种离子偏转弧线的半径更大？为什么？(2) （教材 p.57 思考题 3c 第2题）已知 \\(1\\) 个 \\({}^{12}\\mathrm{C}\\) 原子的质量为 \\(1.993\\times 10^{-26}\\text{ kg}\\)，铝的相对原子质量为 \\(27.0\\)，计算 \\(1\\) 个铝原子的实际质量（保留三位有效数字，以 kg 表示）。","given":"²⁰Ne⁺ vs ²²Ne⁺；m(¹²C)=1.993×10⁻²⁶ kg, Ar(Al)=27.0","method":"质谱偏转质量判据 + 相对原子质量定义式逆算实际质量","principle":"同价态同加速离子，质量越大在磁场中偏转越难、轨道半径越大；m(Al) = Ar(Al) × (1/12 m(¹²C))。","steps":["(1) \\({}^{22}\\mathrm{Ne^+}\\) 偏转弧线的半径更大（偏转程度更小）。原因：两种离子所带正电荷相同（均为 \\(+1\\)），\\({}^{22}\\mathrm{Ne^+}\\) 的质量比 \\({}^{20}\\mathrm{Ne^+}\\) 大，在相同磁场力作用下惯性更大、更难偏转（教材 p.54）。","(2) 计算标准质量单位：\\(\\frac{1}{12}m({}^{12}\\mathrm{C}) = \\frac{1.993\\times 10^{-26}\\text{ kg}}{12} = 1.661\\times 10^{-27}\\text{ kg}\\)。","铝原子实际质量：\\(m(\\mathrm{Al}) = 27.0 \\times 1.661\\times 10^{-27}\\text{ kg} = 4.485\\times 10^{-26}\\text{ kg} \\approx 4.48\\times 10^{-26}\\text{ kg}\\)。"],"ans":"(1) ²²Ne⁺ 半径更大（质量大、偏转程度小）；(2) 4.48 × 10⁻²⁶ kg（或 4.485 × 10⁻²⁶ kg）。","markingPoints":["准确判断 ²²Ne⁺ 偏转程度更小/半径更大并说明电荷相同时质量大所致（2分）","代对公式求得 m(Al) ≈ 4.48×10⁻²⁶ kg 及正确单位（2分）"],"verification":"精确分数 \\(27/12 \\times 1.993 = 2.25 \\times 1.993 = 4.48425\\)，保留 3 位有效数字为 \\(4.48\\times 10^{-26}\\text{ kg}\\)。","pitfall":"忘记把 1.993×10⁻²⁶ 除以 12 直接乘 27 会放大 12 倍。"},{"id":"chem3-3.3-q4","tier":"L3","tierLabel":"L3 预试","examStyle":"P1 选择","q":"天然铜元素由 \\({}^{63}\\mathrm{Cu}\\)（精确原子质量约为 \\(63.0\\text{ amu}\\)）和 \\({}^{65}\\mathrm{Cu}\\)（精确原子质量约为 \\(65.0\\text{ amu}\\)）两种同位素组成，若测得该天然铜样本的平均相对原子质量为 \\(63.5\\)。下列判断正确的是（　）。","options":["A. 天然铜中 ⁶³Cu 与 ⁶⁵Cu 的原子个数比为 1 : 3","B. 1 mol 天然铜中含 ⁶⁵Cu 约 16.25 g，故 ⁶⁵Cu 质量百分比约为 25.0%","C. 将该天然铜与纯氧（全部视为 ¹⁶O）化合形成氧化亚铜 Cu₂O，在质谱仪中只会出现单一式量 143","D. 该铜样本中 ⁶³Cu 的原子个数百分数为 75.0%，其质量百分比约为 74.4%"],"correctOption":"D","given":"Ar(Cu)=63.5，同位素 63.0 与 65.0","method":"十字交叉求原子比，逐项检验质量分数与 Cu₂O 同位素组合","principle":"原子个数比与质量占比不相等；多种同位素组合会造成多条质谱式量峰。","steps":["设 \\({}^{63}\\mathrm{Cu}\\) 原子占比为 \\(x\\)：\\(63x + 65(1-x) = 63.5 \\implies x = 0.750\\)，即 \\({}^{63}\\mathrm{Cu}:{}^{65}\\mathrm{Cu} = 3:1\\)（原子数比），故 A 错。","B 错：\\(1\\text{ mol}\\) 天然铜含 \\(0.25\\text{ mol}\\ {}^{65}\\mathrm{Cu}\\)（质量 \\(16.25\\text{ g}\\)），其质量百分比为 \\(16.25 / 63.5 = 25.59\\% \\neq 25.0\\%\\)。","C 错：两个 Cu 位点可分别取 63 或 65，存在 \\({}^{63}\\mathrm{Cu}_2{}^{16}\\mathrm{O}(142)\\)、\\({}^{63}\\mathrm{Cu}{}^{65}\\mathrm{Cu}{}^{16}\\mathrm{O}(144)\\)、\\({}^{65}\\mathrm{Cu}_2{}^{16}\\mathrm{O}(146)\\) 三种式量。","D 正确：\\(w({}^{63}\\mathrm{Cu}) = \\frac{0.75 \\times 63.0}{63.5} \\times 100\\% = 74.41\\% \\approx 74.4\\%\\)。"],"ans":"D","markingPoints":["精准区别原子分数 75% 与质量分数 74.4%"],"verification":"验算 \\(47.25 / 63.5 = 0.74409\\)，且 \\(74.41\\% + 25.59\\% = 100.00\\%\\)。","pitfall":"误选 B，因为看到 16.25 刚好算对却直接拿 25% 原子比充当质量比。"},{"id":"chem3-3.3-q5","tier":"L4","tierLabel":"L4 统考压轴","examStyle":"P2 综合压轴","q":"天然硼（\\(\\mathrm{B}\\)）由 \\({}^{10}\\mathrm{B}\\)（相对质量 \\(10.01\\)）和 \\({}^{11}\\mathrm{B}\\)（相对质量 \\(11.01\\)）两种同位素组成，天然硼的平均相对原子质量为 \\(10.81\\)。现将天然硼与天然氯（\\({}^{35}\\mathrm{Cl}\\) 占原子数 \\(75.0\\%\\)，\\({}^{37}\\mathrm{Cl}\\) 占原子数 \\(25.0\\%\\)）充分反应制得气态三氯化硼（\\(\\mathrm{BCl_3}\\)）。试求：(1) 天然硼中 \\({}^{10}\\mathrm{B}\\) 的原子个数百分比；(2) 天然硼中 \\({}^{10}\\mathrm{B}\\) 的质量百分比；(3) 在 \\(\\mathrm{BCl_3}\\) 的质谱分子离子峰中，质量数最小的峰（\\({}^{10}\\mathrm{B}{}^{35}\\mathrm{Cl}_3\\)，质量数 \\(115\\)）与质量数最大的峰（\\({}^{11}\\mathrm{B}{}^{37}\\mathrm{Cl}_3\\)，质量数 \\(122\\)）的峰强度之比是多少？","given":"¹⁰B(10.01), ¹¹B(11.01), Ar(B)=10.81；³⁵Cl 75%, ³⁷Cl 25%；BCl₃","method":"加权平均求硼丰度 → 换算质量占比 → 独立乘积概率求极端质谱峰强度比","principle":"分子离子各组成原子同位素概率彼此独立。","steps":["第(1)问：设 \\({}^{10}\\mathrm{B}\\) 的原子分数为 \\(x\\)，则 \\(10.01x + 11.01(1-x) = 10.81 \\implies 1.00x = 0.20 \\implies x = 0.200\\)，即 **\\(20.0\\%\\)**（\\({}^{11}\\mathrm{B}\\) 占 \\(80.0\\%\\)）。","第(2)问：在 \\(1\\text{ mol}\\) 天然硼（总质量 \\(10.81\\text{ g}\\)）中，\\({}^{10}\\mathrm{B}\\) 占 \\(0.200\\text{ mol}\\)，其质量为 \\(0.200\\times 10.01 = 2.002\\text{ g}\\)，故质量百分比为：\\(\\frac{2.002}{10.81} \\times 100\\% = 18.52\\%\\)。","第(3)问：计算两个极端分子离子峰出现的概率：","- 最小质量数 \\(115\\)（1 个 \\({}^{10}\\mathrm{B}\\) + 3 个 \\({}^{35}\\mathrm{Cl}\\)）：\\(P(115) = 0.200 \\times (0.750)^3 = \\frac{1}{5} \\times \\frac{27}{64} = \\frac{27}{320}\\)；","- 最大质量数 \\(122\\)（1 个 \\({}^{11}\\mathrm{B}\\) + 3 个 \\({}^{37}\\mathrm{Cl}\\)）：\\(P(122) = 0.800 \\times (0.250)^3 = \\frac{4}{5} \\times \\frac{1}{64} = \\frac{4}{320}\\)。","两峰强度之比为：\\(P(115) : P(122) = 27 : 4\\)（即 \\(6.75 : 1\\)）。"],"ans":"(1) 20.0%；(2) 18.52%；(3) 27 : 4。","markingPoints":["求得 ¹⁰B 原子分数 20.0%（1分）","求得质量百分比 18.52%（1分）","分别列出 P(115)=0.2×0.75³ 与 P(122)=0.8×0.25³ 并化为整数比 27:4（3分）"],"verification":"分母同为 320，比率 \\((0.20/0.80) \\times (0.75/0.25)^3 = (1/4) \\times 3^3 = 27/4\\) 简洁无比！","pitfall":"若把质量占比 18.52% 误当成概率代入第(3)问会全算偏。"}],"cheatSheet":["中性原子：核电荷数 = Z = 核外电子数；质量数 A = Z + N；离子改电子数不改 Z 与 A。","质谱仪同电荷下：质量越大偏转半径越大（偏转角度越小）。","1 amu = ¹²C 原子质量的 1/12 = 1.661 × 10⁻²⁷ kg；Ar 无单位！","天然丰度指的是原子个数比；双原子分子质谱峰要计排列系数 2。"],"kbEntryIds":["kb-chem3-atom-structure","kb-chem3-mass-spec","kb-chem3-ar-formula"],"quiz":{"q":"某元素 R 的天然同位素为 \\({}^{69}\\mathrm{R}\\) 与 \\({}^{71}\\mathrm{R}\\)，平均相对原子质量为 \\(69.8\\)，则两种同位素的原子个数比是多少？","given":"69, 71, 平均 69.8","method":"加权平均方程或十字交叉","principle":"Ar = 69x + 71(1−x)","steps":["69x + 71(1−x) = 69.8 ⇒ 2x = 1.2 ⇒ x = 0.60。","故原子个数比 ⁶⁹R : ⁷¹R = 0.60 : 0.40 = 3 : 2。"],"ans":"\\(3 : 2\\)"},"diagrams":[{"src":"assets/fig/v2/chem03-mass-spec.svg","caption":"图 3-3 质谱仪五步工作原理与同位素磁场偏转半径示意图","alt":"质谱仪结构与偏转原理图","pageRef":"化上 p.53–54"}]},{"id":"3.4","t":"化学式与式量","anchor":{"pages":"化上 p.57–62","syllabus":"1.2.1–1.2.2 化学式类型、式量及质量分数计算","examScopes":["sem1_final","pre_exam","sem2_final","uec"],"examWeight":"P1 式量/百分比快速比对 + P2 矿物纯度/混合固体计算","terms":"chemical formula · molecular formula · empirical formula · structural formula · formula mass","prerequisites":["相对原子质量（Ar）与原子数表示（3.3）","常见离子化合物与共价分子的区分（3.1）"],"goals":["严格辨析化学式、分子式、实验式（最简式）与结构式，准确识别哪些晶体只有实验式而无分子式。","完整陈述教材表3-5 化学式表达的五层宏观与微观意义。","熟练完成式量（含结晶水与括号下标）、元素质量比、元素质量百分比以及矿石纯度/肥料性价比应用计算。"]},"concepts":[{"kind":"definition","title":"3.4.1 化学式的三种具体形式：分子式、实验式与结构式","pageRef":"化上 p.57–59、p.72","body":["**化学式**：用元素符号和右下角数字表示纯净物组成的式子。依定比定律，一种纯净物质只有唯一确定的组成。","**分子式（Molecular Formula）**：不仅表示元素组成，还真实反映 **1 个分子内各原子的实际数目**（仅由分子构成的物质才存在分子式，如 \\(\\mathrm{H_2O, O_2, C_2H_2, C_6H_6}\\)）。","**实验式（Empirical Formula，又称最简式）**：仅表示物质中各原子个数的**最简整数比**。凡由**原子直接构成**的晶体（金刚石 \\(\\mathrm{C}\\)、金属铜 \\(\\mathrm{Cu}\\)）或**离子交替排列**构成的离子晶体（氯化钠 \\(\\mathrm{NaCl}\\)）均无独立分子，它们的化学式即是实验式（教材 p.58 图3-13）。有机化合物常出现不同分子式却共有相同实验式，例如乙炔 \\(\\mathrm{C_2H_2}\\) 与苯 \\(\\mathrm{C_6H_6}\\) 实验式均为 \\(\\mathrm{CH}\\)。","**结构式（Structural Formula）**：用短线表示分子中直接相连原子之间的成键情况（如甲烷四个 \\(\\mathrm{C-H}\\) 单键，p.59）。"],"takeaway":"分子式 = (实验式)ₙ；但离子晶体 NaCl、金属 Cu、原子晶体 C 不可以被称为“分子式”。"},{"kind":"table","title":"表3-5 化学式的五层意义（以 H₂O 与 H₂SO₄ 为例）","pageRef":"化上 p.59–60","body":["对照教材表3-5（p.59）与交流分享 \\(\\mathrm{H_2SO_4}\\)（p.60），全面作答化学式意义需涵括宏观 2 条、微观 1 条与定量 2 条："],"table":{"headers":["意义维度","以 H₂O 为例（教材表3-5）","以 H₂SO₄ 为例（教材 p.60 讨论）"],"rows":[["① 宏观物质与微观微粒","表示水这种物质；也表示 1 个水分子","表示硫酸这种物质；也表示 1 个硫酸分子"],["② 元素组成","水由氢、氧两种元素组成","硫酸由氢、硫、氧三种元素组成"],["③ 分子内原子个数比","1个水分子含 2个 H 原子和 1个 O 原子","1个硫酸分子含 2个 H、1个 S、4个 O 原子（个数比 2:1:4）"],["④ 物质的式量 Mr","Mᵣ(H₂O) = 1×2 + 16 = 18","Mᵣ(H₂SO₄) = 1×2 + 32 + 16×4 = 98"],["⑤ 各元素质量比","m_H : m_O = (1×2) : 16 = 1 : 8","m_H : m_S : m_O = 2 : 32 : 64 = 1 : 16 : 32"]]}},{"kind":"mechanism","title":"3.4.2–3.4.3 式量及三大核心计算（含结晶水、多处同元素与不纯物）","pageRef":"化上 p.59–62","body":["**式量（Formula Mass, 符号 \\(M_r\\)）**：化学式中所有原子的相对原子质量总和（分子物质亦可称相对分子质量），无单位。**易漏点**：①化学式中的小圆点 `·`（如 \\(\\mathrm{CuSO_4\\cdot 5H_2O}\\)）是**加上**结晶水的质量，切不可误当成乘号！②同类元素分散在化学式两处时（如 \\(\\mathrm{NH_4NO_3}\\) 中的 2 个 \\(\\mathrm{N}\\)）必须合并相加再算百分含量。","**化肥性价比思维与不纯样品反算**：评估实际农业/工业原料不能仅看元素质量分数，还要结合单价（教材 p.62 思考题 3d）或杂质的干扰元素；反算矿石纯度时常用公式：\\(\\text{纯度} = \\frac{\\text{样品实测某元素质量分数}}{\\text{纯净物理论该元素质量分数}} \\times 100\\%\\)（前提是杂质不含该元素）。"],"takeaway":"判断多种同一类型化合物中某元素含量的高低，可用“归一化法”把另一种元素的原子数统一起来口算，快过硬算式量！"}],"formulas":[{"title":"式量与分子式还原倍比","tex":"M_r = \\sum (N_i\\,A_{r,i}),\\qquad n = \\frac{M_r(\\text{分子式})}{M_r(\\text{实验式})} \\in \\mathbb{Z}^+","plain":"Mr = Σ(原子数 × Ar)；n = 分子式量 / 实验式量","conditions":"结晶水合物中的 · 代表加和，如 Mr(CuSO₄·5H₂O) = 159.5 + 5×18 = 249.5","pageRef":"化上 p.59–60","note":"Mr 是相对质量总和，同样不带单位。"},{"title":"元素质量比、质量百分比与样品纯度","tex":"w(\\mathrm{E}) = \\frac{N_{\\mathrm{E}}\\,A_r(\\mathrm{E})}{M_r} \\times 100\\%,\\qquad \\text{纯度} = \\frac{m_{\\text{纯物质}}}{m_{\\text{样品}}} = \\frac{w_{\\text{样品}}(\\mathrm{E})}{w_{\\text{纯物质}}(\\mathrm{E})}","plain":"w(E) = (原子数 × Ar) / Mr × 100%","conditions":"利用纯度比值公式必须确保所有杂质中均不含元素 E","pageRef":"化上 p.61","note":"若杂质中也含 E，则须设未知数联立质量分数方程。"}],"pitfalls":[{"title":"计算 NH₄NO₃ 或 CH₃COONH₄ 中某元素百分比时漏算第二处原子","wrong":"“\\(\\mathrm{NH_4NO_3}\\) 中氮元素的质量分数 \\(= \\frac{14}{80} = 17.5\\%\\)。”","diagnosis":"式中有铵根里的 N 和硝酸根里的 N 共计 2 个氮原子，只算 1 个会少算一半！","right":"\\(w(\\mathrm{N}) = \\frac{14 \\times 2}{80} \\times 100\\% = 35.0\\%\\)（教材 p.61 例6）。","checkRule":"算百分比前先把分子式简并统计一次：\\(\\mathrm{N_2H_4O_3}\\)，确保各原子不重复不遗漏。"},{"title":"算结晶水合物式量时错把‘·’当成乘号，或忘记把括号外数字乘进水里","wrong":"“\\(\\mathrm{CuSO_4\\cdot 5H_2O}\\) 式量 \\(= 159.5 \\times (5 \\times 18)\\)。”","diagnosis":"结晶水合点号表示分子中结合了结晶水，总质量应**相加**。","right":"\\(M_r(\\mathrm{CuSO_4\\cdot 5H_2O}) = 63.5 + 32 + 16\\times 4 + 5\\times(1\\times 2 + 16) = 159.5 + 90 = 249.5\\)。","checkRule":"遇到结晶水合物，先算 `1×H₂O = 18`，再用无水盐式量 `+ 18x`。"}],"examples":[{"label":"例 3.4.1","tier":"L2","tierLabel":"L2 校内期末","title":"教材思考题 3d：四种氮肥的含氮量与性价比决策","prompt":"（教材 p.62 思考题 3d 表3-6）常用四种氮肥的化学式及市场每吨价格如下：硫酸铵 \\(\\mathrm{(NH_4)_2SO_4}\\) 450 元/吨、硝酸铵 \\(\\mathrm{NH_4NO_3}\\) 810 元/吨、碳酸氢铵 \\(\\mathrm{NH_4HCO_3}\\) 330 元/吨、尿素 \\(\\mathrm{CO(NH_2)_2}\\) 1080 元/吨。（已知 \\(\\mathrm{H}=1, \\mathrm{C}=12, \\mathrm{N}=14, \\mathrm{O}=16, \\mathrm{S}=32\\)）请分别计算四种氮肥中氮元素的质量百分比，并计算买到每元氮肥中最划算的是哪一种？","clues":"性价比指标 = “花 1 元钱能买到多少千克氮元素” = \\(\\frac{w(\\mathrm{N}) \\times 1000\\text{ kg}}{\\text{每吨价格（元）}}\\)。","strategy":"逐一求式量 \\(M_r\\) 与 \\(w(\\mathrm{N})\\)，再除以单价排序；切勿光凭含氮量高就误判尿素最省钱。","given":"四种肥料化学式及吨价（450, 810, 330, 1080）","principle":"元素质量百分比计算及成本效益比公式。","steps":["① 硫酸铵 \\(\\mathrm{(NH_4)_2SO_4}\\)：\\(M_r = 2(14+4)+32+64 = 132\\)，\\(w(\\mathrm{N}) = \\frac{28}{132} = 21.21\\%\\)；每元买氮 \\(= \\frac{212.1\\text{ kg}}{450\\text{ 元}} = 0.471\\text{ kg/元}\\)。","② 硝酸铵 \\(\\mathrm{NH_4NO_3}\\)：\\(M_r = 14+4+14+48 = 80\\)，\\(w(\\mathrm{N}) = \\frac{28}{80} = 35.00\\%\\)；每元买氮 \\(= \\frac{350.0}{810} = 0.432\\text{ kg/元}\\)。","③ 碳酸氢铵 \\(\\mathrm{NH_4HCO_3}\\)：\\(M_r = 14+4+1+12+48 = 79\\)，\\(w(\\mathrm{N}) = \\frac{14}{79} = 17.72\\%\\)；每元买氮 \\(= \\frac{177.2}{330} = 0.537\\text{ kg/元}\\)。","④ 尿素 \\(\\mathrm{CO(NH_2)_2}\\)：\\(M_r = 12+16+2(14+2) = 60\\)，\\(w(\\mathrm{N}) = \\frac{28}{60} = 46.67\\%\\)；每元买氮 \\(= \\frac{466.7}{1080} = 0.432\\text{ kg/元}\\)。","比较每元可购纯氮质量：\\(0.537 > 0.471 > 0.432\\)，碳酸氢铵虽含氮率最低，但因价格极廉，性价比最高！"],"answer":"含氮量：尿素(46.67%) > 硝酸铵(35.00%) > 硫酸铵(21.21%) > 碳酸氢铵(17.72%)；**最划算应选碳酸氢铵**（每元可买 0.537 kg 纯氮）。","markingPoints":["四种氮肥的式量与含氮百分比全算对（2分）","正确计算“每元购氮质量”并选出碳酸氢铵（2分）"],"verification":"验证碳酸氢铵：\\(14/79/0.33 = 14 / 26.07 = 0.5370\\text{ kg/元}\\)。","pitfall":"很多同学只算出尿素含氮 46.7% 最高就选尿素，恰好掉进教材思考题特意设置的商业决策陷阱。"},{"label":"例 3.4.2","tier":"L3","tierLabel":"L3 预试拔高","title":"含铁矿石纯度反算与炼铁质量推算","prompt":"某赤铁矿样品（主要成分为 \\(\\mathrm{Fe_2O_3}\\)，所含杂质均不含铁元素）经化验分析，铁元素的质量百分比为 \\(56.0\\%\\)。（已知 \\(\\mathrm{Fe}=56, \\mathrm{O}=16\\)）(1) 求纯净 \\(\\mathrm{Fe_2O_3}\\) 中铁的质量百分比；(2) 求该赤铁矿样品中 \\(\\mathrm{Fe_2O_3}\\) 的质量分数（纯度）；(3) 若取 \\(1.00\\text{ t}\\)（\\(1000\\text{ kg}\\)）该赤铁矿石在工业高炉中完全冶炼，理论上最多可炼出含碳及其他杂质 \\(4.0\\%\\) 的生铁多少千克？","clues":"纯净的 \\(\\mathrm{Fe_2O_3}\\) 含铁占 \\(70.0\\%\\)，而样品只有 \\(56.0\\%\\)，两者的比值直接给出矿石纯度！","strategy":"以铁元素质量在冶炼前后完全守恒为主线，避免在中间步骤过早四舍五入。","given":"矿石 w(Fe)=56.0%；m(矿石)=1000 kg；生铁含纯铁 96.0%","principle":"元素质量守恒及混合物纯度比例式。","steps":["第(1)问：\\(M_r(\\mathrm{Fe_2O_3}) = 56\\times 2 + 16\\times 3 = 160\\)，纯净物中 \\(w_{\\text{纯}}(\\mathrm{Fe}) = \\frac{112}{160} \\times 100\\% = 70.0\\%\\)。","第(2)问：由于杂质不含铁，矿石的 \\(\\mathrm{Fe_2O_3}\\) 纯度 \\(= \\frac{w_{\\text{样品}}(\\mathrm{Fe})}{w_{\\text{纯}}(\\mathrm{Fe})} = \\frac{56.0\\%}{70.0\\%} = 80.0\\%\\)。","第(3)问：\\(1000\\text{ kg}\\) 矿石中所含纯铁元素的质量为 \\(m(\\mathrm{Fe}) = 1000\\text{ kg} \\times 56.0\\% = 560\\text{ kg}\\)（等效验算：\\(1000\\times 80.0\\%\\times 70.0\\% = 560\\text{ kg}\\)）。","设可炼得含杂生铁 \\(m_{\\text{生铁}}\\)，因生铁含纯铁 \\(1 - 4.0\\% = 96.0\\%\\)：\\(m_{\\text{生铁}} = \\frac{560\\text{ kg}}{96.0\\%} = 583.3\\text{ kg}\\)。"],"answer":"(1) 70.0%；(2) 矿石纯度 80.0%；(3) 理论上最多可炼出生铁 583 kg（或 583.3 kg）。","markingPoints":["算对纯 Fe₂O₃ 含铁 70.0%（1分）","算对纯度 80.0%（1分）","按含铁 560 kg 除以生铁纯度 96% 得 583.3 kg（2分）"],"verification":"\\(583.33\\times 0.96 = 560.0\\text{ kg Fe}\\)，完全自洽。","pitfall":"第(3)问常错写成 \\(560\\times 96\\% = 537.6\\text{ kg}\\)——把“含纯铁 560 kg 折合成含杂生铁应增大质量（除以 0.96）”做成了乘法！"}],"practice":[{"id":"chem3-3.4-q1","tier":"L1","tierLabel":"L1 基础","examStyle":"P1 选择","q":"关于分子式、实验式与化学式，下列说法**正确**的是（　）。","options":["A. 氯化钠的分子式是 NaCl，它表示 1 个 NaCl 分子含 1 个 Na 原子和 1 个 Cl 原子","B. 乙炔（C₂H₂）与苯（C₆H₆）的分子式不同，但它们的实验式都是 CH","C. 所有物质的化学式都等于其分子式","D. 实验式不同的两种有机化合物，各元素的质量百分比一定不相同"],"correctOption":"B","given":"化学式、分子式、实验式概念辨析","method":"逐项比对晶体类型及定义（教材 p.58–59）","principle":"NaCl 为离子晶体只有实验式；实验式决定各元素质量百分比。","steps":["A 错：NaCl 中没有独立分子，NaCl 是实验式。","B 对：C₂H₂ 与 C₆H₆ 最简整数比同为 1:1，实验式均为 CH。","C 错：离子晶体、金属单质、原子晶体无分子式。","D 若两种化合物实验式不同（如 CO 与 CO₂），质量比确实不同；但若实验式相同（如 C₂H₂ 与 C₆H₆）则元素质量比相同，不过 D 说“实验式不同则百分比一定不同”严格看还可能有三元素恰好同质量比等，而 B 是教材 p.58–59 原文明确例子。"],"ans":"B","markingPoints":["依据教材 p.58–59 确认实验式与分子式区分"],"verification":"教材 p.58 原文例示乙炔与苯实验式均为 CH。","pitfall":"误把“NaCl”称作分子式。"},{"id":"chem3-3.4-q2","tier":"L2","tierLabel":"L2 期末","examStyle":"P1 选择","q":"（教材 p.74 第12题）下列各种假设或真实存在的铁的氧化物化学式中，**铁元素的质量百分比最高**的是（　）。","options":["A. FeO","B. Fe₂O","C. Fe₃O₄","D. Fe₂O₃"],"correctOption":"B","given":"FeO, Fe₂O, Fe₃O₄, Fe₂O₃","method":"归一化成每个铁原子结合的氧原子数（即 FeOₓ）","principle":"对仅有 Fe、O 两种元素的化合物，结合 O 越少则含 Fe 质量百分比越高。","steps":["将四种化学式同时标准化为仅含 1 个 Fe 原子的形式：A 为 \\(\\mathrm{FeO_{1.00}}\\)；B 为 \\(\\mathrm{FeO_{0.50}}\\)；C 为 \\(\\mathrm{FeO_{1.33}}\\)；D 为 \\(\\mathrm{FeO_{1.50}}\\)。","每个铁原子结合氧原子越少，氧占比越低、铁占比越高：\\(0.50 < 1.00 < 1.33 < 1.50\\)，故含铁最高的是 B \\(\\mathrm{Fe_2O}\\)（\\(112/128 = 87.5\\%\\)）。"],"ans":"B","markingPoints":["使用归一化快速比大小，避免四次繁琐除法"],"verification":"Fe₂O: 87.5%，FeO: 77.8%，Fe₃O₄: 72.4%，Fe₂O₃: 70.0%。","pitfall":"若觉得“Fe₂O 不是常见稳定氧化物”而不敢选，其实教材 p.74 第12题专门保留该选项考察纯比例计算能力。"},{"id":"chem3-3.4-q3","tier":"L2","tierLabel":"L2 期末","examStyle":"P2 必答计算","q":"（教材 p.74 第14题拓展）欲使三氧化二氮（\\(\\mathrm{N_2O_3}\\)）和二氧化氮（\\(\\mathrm{NO_2}\\)）含有**相同质量的氮元素**，则所需 \\(\\mathrm{N_2O_3}\\) 与 \\(\\mathrm{NO_2}\\) 的质量之比是多少？若改取等质量的 \\(\\mathrm{N_2O_3}\\) 与 \\(\\mathrm{NO_2}\\)，则两者所含氧原子个数之比又是多少？（已知 \\(\\mathrm{N}=14, \\mathrm{O}=16\\)）","given":"Mᵣ(N₂O₃) = 76, Mᵣ(NO₂) = 46","method":"对齐氮原子个数（2个N）比质量；氧原子个数比用 n × O下标","principle":"含氮元素质量相同 ⇔ 含氮原子数目/物质的量相同。","steps":["计算式量：\\(M_r(\\mathrm{N_2O_3}) = 28 + 48 = 76\\)，\\(M_r(\\mathrm{NO_2}) = 14 + 32 = 46\\)。","要含相同氮元素，即含相同数目的 N 原子：取 \\(1\\text{ 个 }\\mathrm{N_2O_3}\\)（含 2 个 N，式量 76）与 \\(2\\text{ 个 }\\mathrm{NO_2}\\)（含 2 个 N，总式量 \\(2\\times 46 = 92\\)）相比，质量比为 \\(76 : 92 = 19 : 23\\)。","若两者质量相等（设各取 \\(m\\text{ g}\\)），则氧原子个数比为：\\(\\left(\\frac{m}{76}\\times 3\\right) : \\left(\\frac{m}{46}\\times 2\\right) = \\frac{3}{76} : \\frac{2}{46} = (3\\times 23) : (1\\times 76) = 69 : 76\\)。"],"ans":"含等氮质量时质量比为 \\(19 : 23\\)；等质量时氧原子数之比为 \\(69 : 76\\)。","markingPoints":["对齐 2N 比式量得 19:23（2分）","算出等质量时氧原子比 (3/76):(2/46) = 69:76（2分）"],"verification":"\\(76/4 = 19\\)，\\(92/4 = 23\\)；\\(3\\times 46 : 2\\times 76 = 138 : 152 = 69 : 76\\)。","pitfall":"第一问忘记把 NO₂ 乘 2 对齐 2 个 N 原子，会错算成 76:46 = 38:23。"},{"id":"chem3-3.4-q4","tier":"L3","tierLabel":"L3 预试","examStyle":"P2 必答计算","q":"某不纯石灰石样品仅含有碳酸钙（\\(\\mathrm{CaCO_3}\\)）和少量二氧化硅（\\(\\mathrm{SiO_2}\\)）杂质。经实验测定，该样品中碳元素（\\(\\mathrm{C}\\)）的质量分数为 \\(10.8\\%\\)。（已知 \\(\\mathrm{C}=12, \\mathrm{O}=16, \\mathrm{Si}=28, \\mathrm{Ca}=40\\)）试求：(1) 该石灰石样品中 \\(\\mathrm{CaCO_3}\\) 的质量纯度；(2) 取 \\(50.0\\text{ g}\\) 该石灰石样品，其中一共含有**氧元素**多少克？（提示：警惕杂质也含氧！）","given":"样品含 C 10.8%；组分 CaCO₃ (M=100) + SiO₂ (M=60)；取样 50.0 g","method":"由 C 只存在于 CaCO₃ 反推 CaCO₃ 纯度，再分别算出 CaCO₃ 与 SiO₂ 两部分的氧质量之和","principle":"元素质量归属分析与加和计算。","steps":["第(1)问：纯 \\(\\mathrm{CaCO_3}\\)（\\(M_r = 40+12+48 = 100\\)）中碳的质量分数为 \\(\\frac{12}{100} = 12.0\\%\\)。因杂质 \\(\\mathrm{SiO_2}\\) 不含碳，故样品纯度为：\\(\\frac{10.8\\%}{12.0\\%} = 90.0\\%\\)。","第(2)问：在 \\(50.0\\text{ g}\\) 样品中，含 \\(\\mathrm{CaCO_3}\\) 的质量为 \\(50.0 \\times 90.0\\% = 45.0\\text{ g}\\)，含杂质 \\(\\mathrm{SiO_2}\\) 的质量为 \\(50.0 - 45.0 = 5.0\\text{ g}\\)。","分别求两部分所含氧元素质量：\\(\\mathrm{CaCO_3}\\) 中含氧 \\(45.0\\text{ g} \\times \\frac{48}{100} = 21.60\\text{ g}\\)；\\(\\mathrm{SiO_2}\\)（\\(M_r = 28+32 = 60\\)）中含氧 \\(5.0\\text{ g} \\times \\frac{32}{60} = 2.67\\text{ g}\\)。","总含氧质量：\\(m_{\\text{总}}(\\mathrm{O}) = 21.60\\text{ g} + 2.67\\text{ g} = 24.27\\text{ g}\\)。"],"ans":"(1) 90.0%；(2) 总含氧元素 24.27 g（或 24.3 g）。","markingPoints":["由 w(C) 求得 CaCO₃ 纯度 90.0%（2分）","没有遗漏杂质 SiO₂ 中所含 2.67 g 氧并正确加得 24.27 g（3分）"],"verification":"验证 50.0 g 样品组成：Ca 18.0 g + C 5.40 g + Si 2.33 g + O 24.27 g = 50.00 g，元素加和百分百守恒！","pitfall":"审题粗心只算了 CaCO₃ 里的氧 21.6 g，忘记杂质 SiO₂ 里也有 2 个氧原子。"},{"id":"chem3-3.4-q5","tier":"L4","tierLabel":"L4 统考压轴","examStyle":"P2 综合压轴","q":"已知某均匀固体混合物仅由氧化亚铁（\\(\\mathrm{FeO}\\)）和氧化铁（\\(\\mathrm{Fe_2O_3}\\)）组成，经实验精准测得该混合物中铁元素的总质量分数为 \\(72.0\\%\\)。（已知 \\(\\mathrm{Fe}=56, \\mathrm{O}=16\\)）试求：(1) 混合物中 \\(\\mathrm{FeO}\\) 与 \\(\\mathrm{Fe_2O_3}\\) 的质量之比；(2) 混合物中 \\(\\mathrm{FeO}\\) 与 \\(\\mathrm{Fe_2O_3}\\) 的物质的量之比。","given":"M(FeO)=72 (w(Fe)=56/72=7/9)；M(Fe₂O₃)=160 (w(Fe)=112/160=70%)；混合 w(Fe)=72%","method":"质量百分比混合方程（或十字交叉法）直接求解","principle":"两纯组分元素质量分数的加权平均（以质量为权重）。","steps":["先计算两纯净物中铁的质量分数：\\(w(\\mathrm{FeO}) = \\frac{56}{72} = \\frac{7}{9}\\)（约 \\(77.78\\%\\)）；\\(w(\\mathrm{Fe_2O_3}) = \\frac{112}{160} = 0.70 = 70.0\\%\\)。","设混合物中 \\(\\mathrm{FeO}\\) 质量为 \\(x\\text{ g}\\)，\\(\\mathrm{Fe_2O_3}\\) 质量为 \\(y\\text{ g}\\)，列铁元素质量守恒方程：\\(\\frac{7}{9}x + 0.70y = 0.72(x + y)\\)。","移项整理：\\(\\left(\\frac{7}{9} - \\frac{72}{100}\\right)x = (0.72 - 0.70)y \\implies \\frac{700 - 648}{900}x = \\frac{2}{100}y \\implies \\frac{52}{900}x = \\frac{18}{900}y\\)。","故第(1)问质量比为：\\(x : y = 18 : 52 = 9 : 26\\)。","第(2)问物质的量之比（将质量分别除以各自摩尔质量 \\(72\\) 与 \\(160\\)）：\\(n(\\mathrm{FeO}) : n(\\mathrm{Fe_2O_3}) = \\frac{9}{72} : \\frac{26}{160} = \\frac{1}{8} : \\frac{13}{80} = 10 : 13\\)。"],"ans":"(1) 质量比为 \\(9 : 26\\)；(2) 物质的量之比为 \\(10 : 13\\)。","markingPoints":["算出 FeO(7/9) 与 Fe₂O₃(0.70) 理论含铁分数，未过早保留小数带来误差（2分）","列式严谨求得质量比 9 : 26（2分）","进一步除以摩尔质量求得物质的量比 10 : 13（1分）"],"verification":"取 \\(9\\text{ g FeO}\\)（含 Fe \\(7.0\\text{ g}\\)）+ \\(26\\text{ g }\\mathrm{Fe_2O_3}\\)（含 Fe \\(18.2\\text{ g}\\)），总质量 \\(35.0\\text{ g}\\)，总 Fe \\(25.2\\text{ g}\\)，\\(25.2/35.0 = 0.720 = 72.0\\%\\) 分毫不差！","pitfall":"若把 \\(56/72\\) 四舍五入为 \\(77.8\\%\\)，算得 \\(2.0:5.8 = 10:29\\) 就会偏离精确整数比 \\(9:26\\)；计算分数比务必保留分数或四位小数。"}],"cheatSheet":["晶态决定式类：分子晶体才有分子式；NaCl、Cu、金刚石的化学式即是实验式。","式量与百分比：结晶水 `·` 用加法（+18x）；NH₄NO₃ 等两处同类原子务必合并。","比含元素高低：把另一元素下标归 1 直接口算；矿石反算纯度：纯度 = w(实测) / w(纯物)。","混合物平均含量问题：设质量 x、y（保留精确分数），再用 n = m/M 转物质的量比。"],"kbEntryIds":["kb-chem3-formulas-types","kb-chem3-formula-calc"],"quiz":{"q":"计算硫酸铜晶体 \\(\\mathrm{CuSO_4\\cdot 5H_2O}\\) 的式量及其中结晶水的质量百分比。（\\(\\mathrm{Cu}=63.5, \\mathrm{S}=32, \\mathrm{O}=16, \\mathrm{H}=1\\)）","given":"CuSO₄·5H₂O","method":"无水部分与 5 个水分子质量相加","principle":"式量加和法则。","steps":["Mr = 63.5 + 32 + 16×4 + 5×18 = 159.5 + 90 = 249.5。","w(H₂O) = 90 / 249.5 × 100% ≈ 36.1%。"],"ans":"式量 \\(249.5\\)；结晶水占比约 \\(36.1\\%\\)。"}},{"id":"3.5","t":"确定化学式的方法","anchor":{"pages":"化上 p.62–66","syllabus":"1.2.3 化合价推式、实验测定法与燃烧分析法","examScopes":["sem1_final","pre_exam","sem2_final","uec"],"examWeight":"P2 必答题核心（实验式推导、恒重实验误差诊断、有机物燃烧与相对密度定分子式）","terms":"valency · polyatomic ion (radical) · empirical formula · constant mass","prerequisites":["化学式、实验式与分子式的区别（3.4.1）","相对原子质量（Ar）与元素质量比（3.3–3.4）"],"goals":["熟记表3-7 常见元素与原子团化合价，熟练运用代数和为零规则书写已知化合物化学式。","理解活动5（铜粉高温氧化恒重测定 CuO）实验步骤，并能诊断未充分氧化或未冷却称量造成的实验误差。","掌握由元素质量、质量百分比或燃烧产物（CO₂、H₂O）求实验式并结合式量/相对密度定分子式的完整算法。"]},"concepts":[{"kind":"table","title":"3.5.1 教材表3-7 常见元素和原子团（根）化合价速查表","pageRef":"化上 p.62–64","body":["**三项铁律（p.63）**：①单质中元素化合价为 **0**；②化合物中正负化合价代数和为 **0**；③金属显正价，氧常为 **-2**，氢常为 **+1**，原子团作为一个整体参与反应。**特别注意（p.64）**：化合价只能用来推导已知存在的物质，不能凭空拼凑自然界不存在的物质！"],"table":{"headers":["类别","常见元素或根名称与符号","教材标准常见化合价","交叉/公倍数写式提醒"],"rows":[["定值正价金属/根","H⁺、Na⁺、K⁺、Ag⁺、NH₄⁺","+1","原子团数量 > 1 时必须加括号，如 (NH₄)₂SO₄"],["二三价金属","Mg、Ca、Zn (+2)；Al (+3)","+2 或 +3","如 Al³⁺ 与 O²⁻ → 最小公倍数 6 → Al₂O₃"],["变价金属","Cu (+1, +2)；Fe (+2, +3)","+1/+2（亚铜/铜）；+2/+3（亚铁/铁）","Fe₃O₄ 可视作 FeO·Fe₂O₃（含 1 个 +2 和 2 个 +3）"],["常见非金属","Cl (-1)；O (-2)；C (+2, +4)；S (-2, +4, +6)；N (-3, +5)","按与金属或高电负性原子组合确定","单质 Cl₂、Fe、O₂ 中元素化合价一律为 0"],["常见负价原子团（根）","OH⁻、NO₃⁻；SO₄²⁻、CO₃²⁻","氢氧根/硝酸根 -1；硫酸根/碳酸根 -2","如 Mg²⁺ 与 NO₃⁻ → Mg(NO₃)₂；Fe³⁺ 与 SO₄²⁻ → Fe₂(SO₄)₃"]]}},{"kind":"experiment","title":"3.5.2 教材活动5：铜粉高温氧化恒重法测定 CuO（p.64–65）","pageRef":"化上 p.64–65","body":["**实验步骤**：干燥洁净瓷舟皿称重（① \\(8.428\\text{ g}\\)）→ 放入极细铜粉称重（② \\(9.278\\text{ g}\\)，故 \\(m(\\mathrm{Cu}) = 0.850\\text{ g}\\)）→ 置于硬质玻璃管中通纯氧高温加热生成黑色 \\(\\mathrm{CuO}\\) → **反复‘加热—冷却—称量’直至连续两次称量质量不变（达到恒重）**（③ \\(9.488\\text{ g}\\)，故 \\(m(\\mathrm{CuO}) = 1.060\\text{ g}\\)，增加氧质量 \\(0.210\\text{ g}\\)）。","**原子数比计算**：\\(n(\\mathrm{Cu}) : n(\\mathrm{O}) = \\frac{0.850}{63.5} : \\frac{0.210}{16} = 0.0134 : 0.0131 \\approx 1:1 \\implies \\mathrm{CuO}\\)。","**探究关键**：为何要“极细铜粉”且“加热至恒重”？极大比表面积保证氧气充分渗透，反复恒重则是为了检验铜粉**已彻底氧化**（避免内部未反应导致测得氧偏少）；冷却时需继续通氧气或于干燥器中冷却（防止刚熄火趁热空气水汽吸附或反被还原）。"],"takeaway":"在硬质管测量氧化物组成的实验中，“加热—冷却—称量至恒重（两次差值 ≤ 0.001–0.01 g）”是定量完备性的核心判据。"},{"kind":"mechanism","title":"3.5.3 由百分比、燃烧产物及气体相对密度定分子式","pageRef":"化上 p.65–66","body":["**三步通法**：①各元素质量（或设 100 g 时的百分比数值）除以各自 \\(A_r\\)，求各原子相对物质的量；②所有值同除以最小数；③遇小数（如 \\(1.5\\to\\times 2\\)，\\(1.33/1.67\\to\\times 3\\)，\\(1.25/1.75\\to\\times 4\\)）同乘整化出**实验式**；④若已知式量 \\(M_r\\)（或同温同压对氢气的相对密度 \\(D = M_{\\text{未知}}/2\\)，或对空气相对密度 \\(M/29\\)），算 \\(n = M_r / M_{\\text{实验式}}\\) 写出**分子式**。","**燃烧分析法铁律**：当有机物 \\(\\mathrm{C}_x\\mathrm{H}_y\\mathrm{O}_z\\) 在 \\(\\mathrm{O_2}\\) 中燃烧只得 \\(\\mathrm{CO_2}\\) 和 \\(\\mathrm{H_2O}\\) 时，产物中所有碳来自有机物、所有氢来自有机物，但产物中的**氧一部分来自外通的 \\(\\mathrm{O_2}\\)**！因此必须先算 \\(m(\\mathrm{C}) = m(\\mathrm{CO_2})\\times \\frac{12}{44}\\)、\\(m(\\mathrm{H}) = m(\\mathrm{H_2O})\\times \\frac{2}{18}\\)，再用 \\(m_{\\text{有机物}} - m(\\mathrm{C}) - m(\\mathrm{H})\\) 判断是否含氧及其质量！"],"takeaway":"算完 m(C) + m(H) 若恰好等于样品总质量 ⇒ 不含氧；若小于样品总质量 ⇒ 差值即必为样品原含氧元素质量 m(O)！"}],"formulas":[{"title":"实验式与分子式测定通式（燃烧与蒸汽密度联动）","tex":"n(\\mathrm{C}):n(\\mathrm{H}):n(\\mathrm{O}) = \\frac{m(\\mathrm{CO_2})}{44} : \\frac{2\\,m(\\mathrm{H_2O})}{18} : \\frac{m_{\\text{样}} - m(\\mathrm{C}) - m(\\mathrm{H})}{16},\\qquad M_r = D_{\\mathrm{H_2}} \\times 2","plain":"n(C) = m(CO₂)/44；n(H) = 2×m(H₂O)/18；Mr = 2 × D(对H₂相对密度)","conditions":"D 为同温同压下两气体的密度比，即摩尔质量比；燃烧氧气需足量","pageRef":"化上 p.65–66","note":"同温同压下，ρ₁/ρ₂ = M₁/M₂ 源于阿伏加德罗气体定律与 n=m/M。"},{"title":"化合价交叉与代数和校验规则","tex":"\\sum_i (\\text{下标}_i \\times \\text{化合价}_i) = 0","plain":"正化合价总和 + 负化合价总和 = 0","conditions":"单质化合价为 0；多原子根超过 1 组时必加括号","pageRef":"化上 p.63–64","note":"交叉写出下标后若存在公因数务必约分（如 +4 与 -2 约分后得 XO₂，非 X₂O₄），部分分子过氧化物除外。"}],"pitfalls":[{"title":"对 1.33 / 1.5 等小数比值强行四舍五入成 1","wrong":"“算得 \\(n(\\mathrm{Fe}) : n(\\mathrm{O}) = 1 : 1.33\\)，约等于 \\(1:1\\) 写成 \\(\\mathrm{FeO}\\)。”","diagnosis":"\\(1.33\\) 是实验小数，等于分数 \\(4/3\\)，不是测量微小误差！强行舍去小数会算错真实化学式（如把 \\(\\mathrm{Fe_3O_4}\\) 错成 \\(\\mathrm{FeO}\\)）。","right":"遇 `0.5` 同乘 2；遇 `0.33 / 0.67` 同乘 3；遇 `0.25 / 0.75` 同乘 4；遇 `0.2 / 0.4 / 0.6 / 0.8` 同乘 5！如 \\(1 : 1.33 \\xrightarrow{\\times 3} 3 : 4\\)，得 \\(\\mathrm{Fe_3O_4}\\)。","checkRule":"只有在极接近整数（如 \\(1.01, 1.99, 2.98\\)）时才属测定误差可取整。"},{"title":"直接把生成的 CO₂ 与 H₂O 中的氧加起来当作有机物原含氧","wrong":"“燃烧生成 \\(2.2\\text{ g }\\mathrm{CO_2}\\) 与 \\(0.9\\text{ g }\\mathrm{H_2O}\\)，里面共含氧 \\(1.6 + 0.8 = 2.4\\text{ g}\\)，这就是样品含的氧。”","diagnosis":"外部通入了大量 \\(\\mathrm{O_2}\\) 助燃，产物总氧远高于有机物自身含氧。","right":"永远采用**差减法**求原样品中氧质量：\\(m(\\mathrm{O}) = m_{\\text{样品}} - m(\\mathrm{C}) - m(\\mathrm{H})\\)。","checkRule":"算完 C 与 H 质量相加，先和原样品总重核对一次，绝对不会超过样品总重。"}],"examples":[{"label":"例 3.5.1","tier":"L3","tierLabel":"L3 预试拔高","title":"教材思考题 3e 第2题：金属氧化物还原测定与恒重条件","prompt":"（教材 p.66 思考题 3e 第2题深化）实验室在硬质玻璃管中用干燥纯净的 \\(\\mathrm{H_2}\\) 还原 \\(2.32\\text{ g}\\) 某种金属元素 \\(\\mathrm{R}\\) 的纯净氧化物，反应至固体不再减重（达到恒重）后冷却，得到 \\(1.68\\text{ g}\\) 纯金属 \\(\\mathrm{R}\\)。已知该金属元素的相对原子质量为 \\(56.0\\)，\\(A_r(\\mathrm{O})=16.0\\)。(1) 试计算确定该氧化物的化学式；(2) 若实验结束停火后未继续通 \\(\\mathrm{H_2}\\) 冷却，而是直接撤去酒精灯并在空气中冷却，测得的氧下标结果会偏大还是偏小？","clues":"固体减重 = 被夺走的氧元素质量！未继续通 H₂ 保护高温金属会让灼热金属重新氧化增重。","strategy":"(1) 差减出 \\(m(\\mathrm{O})\\)，再分别除以各自 \\(A_r\\) 比整数；(2) 追踪偏小/偏大误差对差减值 \\(m(\\mathrm{O}) = m_{\\text{氧化物}} - m_{\\text{测金属}}\\) 的影响方向。","given":"m(氧化物) = 2.32 g, m(R) = 1.68 g；Ar(R)=56.0, Ar(O)=16.0","principle":"元素质量守恒及固体还原定量误差分析。","steps":["第(1)问：氧化物中氧元素的质量为：\\(m(\\mathrm{O}) = 2.32\\text{ g} - 1.68\\text{ g} = 0.64\\text{ g}\\)。","分别求金属 \\(\\mathrm{R}\\) 与氧 \\(\\mathrm{O}\\) 的物质的量（相对原子数）：\\(n(\\mathrm{R}) = \\frac{1.68}{56.0} = 0.0300\\text{ mol}\\)；\\(n(\\mathrm{O}) = \\frac{0.64}{16.0} = 0.0400\\text{ mol}\\)。","原子数最简整数比：\\(n(\\mathrm{R}) : n(\\mathrm{O}) = 0.0300 : 0.0400 = 3 : 4\\)，故该金属氧化物的化学式为 \\(\\mathrm{R_3O_4}\\)（即四氧化三铁 \\(\\mathrm{Fe_3O_4}\\)）。","第(2)问：灼热的铁粉直接接触空气会重新部分氧化，导致称得的金属质量 \\(m_{\\text{测}}(\\mathrm{R}) > 1.68\\text{ g}\\)，因此计算得到的减重值 \\(m_{\\text{测}}(\\mathrm{O}) = 2.32 - m_{\\text{测}}(\\mathrm{R})\\) **偏小**，且分母 \\(m_{\\text{测}}(\\mathrm{R})\\) **偏大**，双作用使算出的氧原子下标 \\(y/x\\) **明显偏小**。"],"answer":"(1) 氧化物化学式为 \\(\\mathrm{R_3O_4}\\)（\\(\\mathrm{Fe_3O_4}\\)）；(2) 测得的氧下标会**偏小**（灼热铁被重新氧化使残留固体增重、视在失氧量减少）。","markingPoints":["正确差减得 m(O)=0.64 g 并算出 n(R):n(O)=0.03:0.04=3:4（2分）","写出化学式 R₃O₄ / Fe₃O₄（1分）","精准指明再氧化导致固体偏重、视在失氧偏少、最终氧下标偏小（2分）"],"verification":"\\(M_r(\\mathrm{Fe_3O_4}) = 168 + 64 = 232\\)，取 \\(0.010\\text{ mol}\\) 恰重 \\(2.32\\text{ g}\\)。","pitfall":"第(2)问极易想反方向：觉得“空气带入氧气所以氧下标偏大”，忘记了氧气加在产物金属秤盘上导致的是金属质量虚高、减出来的氧质量减少！"},{"label":"例 3.5.2","tier":"L4","tierLabel":"L4 统考压轴","title":"燃烧分析 + 蒸汽相对密度联合确定分子式","prompt":"取 \\(1.80\\text{ g}\\) 某仅含 \\(\\mathrm{C}, \\mathrm{H}, \\mathrm{O}\\) 三种元素的纯净有机化合物 \\(\\mathrm{A}\\)，置于足量 \\(\\mathrm{O_2}\\) 中完全燃烧，生成 \\(2.64\\text{ g}\\ \\mathrm{CO_2}\\) 和 \\(1.08\\text{ g}\\ \\mathrm{H_2O}\\)。另在同温同压下测得化合物 \\(\\mathrm{A}\\) 蒸气的密度是氢气（\\(\\mathrm{H_2}\\)）密度的 \\(45\\) 倍。（\\(\\mathrm{C}=12, \\mathrm{H}=1, \\mathrm{O}=16\\)）求 \\(\\mathrm{A}\\) 的实验式与分子式。","clues":"利用 \\(M_r(\\mathrm{A}) = 45 \\times M_r(\\mathrm{H_2}) = 90\\)；必须用总质量 \\(1.80\\text{ g}\\) 差减求原有机物含氧质量！","strategy":"分算 C, H 质量 → 差减求 O 质量 → 算实验式 → 利用相对密度定出 \\(M_r\\) 与倍数 \\(n\\)。","given":"m(A)=1.80 g；m(CO₂)=2.64 g；m(H₂O)=1.08 g；D(H₂)=45","principle":"元素质量守恒及阿伏加德罗气体密度比定律。","steps":["计算样品中碳与氢的质量与物质的量：\\(m(\\mathrm{C}) = 2.64\\text{ g} \\times \\frac{12}{44} = 0.72\\text{ g}\\)，\\(n(\\mathrm{C}) = \\frac{0.72}{12} = 0.060\\text{ mol}\\)；\\(m(\\mathrm{H}) = 1.08\\text{ g} \\times \\frac{2}{18} = 0.12\\text{ g}\\)，\\(n(\\mathrm{H}) = \\frac{0.12}{1} = 0.120\\text{ mol}\\)。","判断是否含氧并求 \\(m(\\mathrm{O})\\)：\\(m(\\mathrm{C}) + m(\\mathrm{H}) = 0.72 + 0.12 = 0.84\\text{ g} < 1.80\\text{ g}\\)，故必含氧元素：\\(m(\\mathrm{O}) = 1.80\\text{ g} - 0.84\\text{ g} = 0.96\\text{ g}\\)，\\(n(\\mathrm{O}) = \\frac{0.96}{16} = 0.060\\text{ mol}\\)。","求原子个数最简整数比：\\(n(\\mathrm{C}) : n(\\mathrm{H}) : n(\\mathrm{O}) = 0.060 : 0.120 : 0.060 = 1 : 2 : 1\\)，实验式为 **\\(\\mathrm{CH_2O}\\)**（实验式量 \\(12 + 2 + 16 = 30\\)）。","由同温同压气体密度比等于式量比：\\(M_r(\\mathrm{A}) = 45 \\times 2 = 90\\)，故聚合倍数 \\(n = \\frac{90}{30} = 3\\)，分子式为 **\\(\\mathrm{C_3H_6O_3}\\)**。"],"answer":"实验式为 \\(\\mathrm{CH_2O}\\)；分子式为 \\(\\mathrm{C_3H_6O_3}\\)。","markingPoints":["准确算出 m(C)=0.72 g、m(H)=0.12 g、差减得 m(O)=0.96 g（2分）","推出实验式 CH₂O 及式量 30（1分）","利用相对密度求得 Mr=90 并得出分子式 C₃H₆O₃（2分）"],"verification":"\\(1.80 / 90 = 0.020\\text{ mol}\\ \\mathrm{C_3H_6O_3} \\to 0.060\\text{ mol }\\mathrm{CO_2} + 0.060\\text{ mol }\\mathrm{H_2O}\\)（\\(2.64\\text{ g}\\) 与 \\(1.08\\text{ g}\\)）完全精准。","pitfall":"若把相对密度对氢气写成乘以 1（氢原子）而非 2（双原子氢分子），会算出 Mr=45 无法整除 30。"}],"practice":[{"id":"chem3-3.5-q1","tier":"L1","tierLabel":"L1 基础","examStyle":"P1 选择","q":"（教材 p.74 第9题）已知 \\(\\mathrm{X}, \\mathrm{Y}, \\mathrm{Z}\\) 三种元素在化合物中的化合价分别为 \\(+1\\)、\\(+4\\) 和 \\(-2\\)，则由这三种元素组成的化合物的化学式可能是（　）。","options":["A. XYZ","B. X₄YZ₃","C. X₂YZ₃","D. X₃YZ₂"],"correctOption":"C","given":"v(X)=+1, v(Y)=+4, v(Z)=-2","method":"逐项检验正负化合价代数和是否等于 0","principle":"化合物电中性：代数和等于 0。","steps":["A: \\((+1) + (+4) + (-2) = +3 \\ne 0\\)。","B: \\(4(+1) + (+4) + 3(-2) = +2 \\ne 0\\)。","C: \\(2(+1) + (+4) + 3(-2) = +6 - 6 = 0\\)（相当于 \\(\\mathrm{Na_2CO_3}\\) 或 \\(\\mathrm{H_2CO_3}\\) 结构）。","D: \\(3(+1) + (+4) + 2(-2) = +3 \\ne 0\\)。"],"ans":"C","markingPoints":["化合价代数和检验"],"verification":"例如 \\(\\mathrm{Na_2CO_3}\\)（Na +1, C +4, O -2）正符合 \\(\\mathrm{X_2YZ_3}\\)。","pitfall":"正负号代错造成错判。"},{"id":"chem3-3.5-q2","tier":"L2","tierLabel":"L2 期末","examStyle":"P1 选择","q":"（教材 p.74 第13题）元素 \\(\\mathrm{X}\\) 和 \\(\\mathrm{Y}\\) 的相对原子质量之比为 \\(7 : 8\\)，在它们所组成的一种化合物中，\\(\\mathrm{X}\\) 和 \\(\\mathrm{Y}\\) 的质量比为 \\(7 : 4\\)，则该化合物的实验式为（　）。","options":["A. XY","B. X₂Y","C. XY₂","D. X₂Y₃"],"correctOption":"B","given":"Ar(X):Ar(Y) = 7:8；m(X):m(Y) = 7:4","method":"n = m / Ar 求原子个数比","principle":"化学式原子数比即元素质量与各自 Ar 之比。","steps":["直接用各自质量比例除以相对原子质量比例：\\(n(\\mathrm{X}) : n(\\mathrm{Y}) = \\frac{7}{7} : \\frac{4}{8} = 1 : 0.5 = 2 : 1\\)。","故化学式为 \\(\\mathrm{X_2Y}\\)（其实若取 X=N 14、Y=O 16，14:16=7:8，N₂O 中质量比正是 28:16=7:4！）。"],"ans":"B","markingPoints":["直接带比例做比求出 2:1"],"verification":"代入真实物质 \\(\\mathrm{N_2O}\\)：\\(A_r(\\mathrm{N}):A_r(\\mathrm{O}) = 14:16 = 7:8\\)，质量比 \\(28:16 = 7:4\\)，完全吻合！","pitfall":"若上下倒反乘成 \\((7\\times 7):(4\\times 8)\\) 会错。"},{"id":"chem3-3.5-q3","tier":"L3","tierLabel":"L3 预试","examStyle":"P2 实验探究","q":"在还原或氧化制备测式实验中（如教材活动5 铜粉在氧气流中高温氧化测定氧化铜化学式），操作如下：①称干燥空瓷舟皿 \\(m_1\\)；②加铜粉后称 \\(m_2\\)；③在氧气流中高温充分加热至恒重、冷却后称 \\(m_3\\)。请判断以下三种实验失误，分别会使最终算出的铜、氧原子个数比 \\(n(\\mathrm{O})/n(\\mathrm{Cu})\\) **偏大、偏小还是无影响**，并简述理由：\n(a) 加热时间不足，瓷舟皿内铜粉表面变黑但内部仍有未反应的紫红色铜（未恒重即称量）；\n(b) 铜粉在称量 \\(m_2\\) 时其实表面混入了少量水分，高温加热过程中水蒸气随氧气流挥发逸出；\n(c) 实验后改用纯净过量但混有少许不反应砂粒的铜粉，加热前后砂粒质量均未改变。","given":"m(Cu) = m₂ − m₁；m(O) = m₃ − m₂；求算比 n(O)/n(Cu) = [(m₃−m₂)/16] / [(m₂−m₁)/63.5]","method":"将每种实验失误代入分子 (m₃−m₂) 与分母 (m₂−m₁) 判断商的变化趋势","principle":"定量探究实验误差传递分析法。","steps":["(a) **偏小**。因为铜未完全反应，结合的氧质量比理论值少（即 \\(m_3\\) 偏小，分子 \\(m_3 - m_2\\) 偏小而分母不变），故测得 \\(n(\\mathrm{O})/n(\\mathrm{Cu})\\) 偏小。","(b) **偏小**。假设水分质量为 \\(\\Delta m\\)，称 \\(m_2\\) 时算进了铜粉里使视在铜质量 \\(m_2 - m_1\\) **偏大**；加热后水蒸气挥发，使 \\(m_3\\) 仅含实际氧化铜，导致算出的氧质量 \\(m_3 - m_2\\) 比真实结合氧**偏小** \\(\\Delta m\\)（分子偏小且分母偏大），双因素叠加令比值显著**偏小**。","(c) **偏小**。设砂粒质量为 \\(s\\)，由于 \\(m_3 = m_{\\text{CuO}} + m_1 + s\\) 且 \\(m_2 = m_{\\text{Cu}} + m_1 + s\\)，两者相减 \\(m_3 - m_2 = m_{\\text{CuO}} - m_{\\text{Cu}}\\)（分子**实际结合氧质量不变**！），但分母 \\(m_2 - m_1 = m_{\\text{Cu}} + s\\) 被砂粒拉**偏大**，所以比值整体**偏小**。"],"ans":"(a) 偏小；(b) 偏小；(c) 偏小（均附严格分子分母变化推导）。","markingPoints":["每项给出正确结论（各1分）并清晰利用表达式分子 (m₃−m₂) 与分母 (m₂−m₁) 解释原因（各1分，共6分）"],"verification":"尤其注意 (c) 与 (b) 区分：惰性不挥发杂质不改变增重量 \\(m_3-m_2\\)，只增大分母 \\(m_2-m_1\\)；易挥发杂质既减分子又增分母！","pitfall":"在 (c) 误以为“砂粒反应前后不变所以对实验结果无影响”——错！砂粒虽在增重中消掉，却留在了分母“视在铜质量”中。"},{"id":"chem3-3.5-q4","tier":"L3","tierLabel":"L3 预试","examStyle":"P2 必答计算","q":"称取 \\(14.30\\text{ g}\\) 晶莹剔透的结晶水合碳酸钠晶体（\\(\\mathrm{Na_2CO_3\\cdot}\\ x\\mathrm{H_2O}\\)），置于坩埚中加热至完全失去全部结晶水并达到恒重后，测得残留无水白色碳酸钠（\\(\\mathrm{Na_2CO_3}\\)）质量为 \\(5.30\\text{ g}\\)。（已知 \\(\\mathrm{H}=1, \\mathrm{C}=12, \\mathrm{O}=16, \\mathrm{Na}=23\\)）求结晶水数目 \\(x\\) 的整数值及结晶水的质量分数。","given":"m(水合物)=14.30 g, m(Na₂CO₃)=5.30 g","method":"差减得结晶水质量，分别转成物质的量求 n(H₂O) : n(Na₂CO₃)","principle":"结晶水合物分子式即无水盐与结晶水的物质的量整比。","steps":["失去结晶水的质量：\\(m(\\mathrm{H_2O}) = 14.30\\text{ g} - 5.30\\text{ g} = 9.00\\text{ g}\\)。","分别求两者的物质的量（\\(M(\\mathrm{Na_2CO_3}) = 46+12+48 = 106\\text{ g/mol}\\)；\\(M(\\mathrm{H_2O}) = 18\\text{ g/mol}\\)）：\\(n(\\mathrm{Na_2CO_3}) = \\frac{5.30}{106} = 0.0500\\text{ mol}\\)；\\(n(\\mathrm{H_2O}) = \\frac{9.00}{18} = 0.500\\text{ mol}\\)。","求结晶水系数：\\(x = \\frac{n(\\mathrm{H_2O})}{n(\\mathrm{Na_2CO_3})} = \\frac{0.500}{0.0500} = 10\\)（即十水合碳酸钠 \\(\\mathrm{Na_2CO_3\\cdot 10H_2O}\\)，俗称晶碱/洗涤碱）。","结晶水质量分数：\\(w(\\mathrm{H_2O}) = \\frac{9.00}{14.30} \\times 100\\% = 62.94\\%\\)。"],"ans":"\\(x = 10\\)（化学式 \\(\\mathrm{Na_2CO_3\\cdot 10H_2O}\\)）；结晶水质量分数为 \\(62.94\\%\\)。","markingPoints":["算出水质量 9.00 g 并正确求得两项物质的量 0.0500 mol 与 0.500 mol（2分）","求得 x = 10 及质量百分比 62.94%（2分）"],"verification":"\\(106 + 10\\times 18 = 286\\)，\\(0.0500\\times 286 = 14.30\\text{ g}\\) 完全精确。","pitfall":"切忌拿残留物 5.30 g 直接比总质量 14.30 g 来求 x。"},{"id":"chem3-3.5-q5","tier":"L4","tierLabel":"L4 统考压轴","examStyle":"P2 综合压轴","q":"将 \\(4.60\\text{ g}\\) 某常见易挥发有机化合物 \\(\\mathrm{B}\\) 在足量氧气中完全燃烧，经吸收测得仅生成 \\(8.80\\text{ g}\\ \\mathrm{CO_2}\\) 和 \\(5.40\\text{ g}\\ \\mathrm{H_2O}\\)。（已知 \\(\\mathrm{C}=12, \\mathrm{H}=1, \\mathrm{O}=16\\)）(1) 通过定量计算推断 \\(\\mathrm{B}\\) 是否含氧元素，并写出 \\(\\mathrm{B}\\) 的实验式；(2) 本题并没有给出 \\(\\mathrm{B}\\) 的相对分子质量（或蒸汽密度），但仅根据以上实验式即可唯一确定 \\(\\mathrm{B}\\) 的**分子式**！请写出分子式并说明充分理由。","given":"m(B)=4.60 g；生成 8.80 g CO₂、5.40 g H₂O","method":"燃烧元素差减求实验式 → 利用碳四价饱和氢原子数上限判断 n=1 唯一解","principle":"元素质量守恒 + 含碳化合物氢原子数上界 \\(H_{\\max} = 2C + 2\\)。","steps":["第(1)问：计算碳、氢元素质量与物质的量：\\(m(\\mathrm{C}) = 8.80 \\times \\frac{12}{44} = 2.40\\text{ g}\\)（\\(0.200\\text{ mol}\\)）；\\(m(\\mathrm{H}) = 5.40 \\times \\frac{2}{18} = 0.60\\text{ g}\\)（\\(0.600\\text{ mol}\\)）。","因 \\(2.40 + 0.60 = 3.00\\text{ g} < 4.60\\text{ g}\\)，故 \\(\\mathrm{B}\\) 必含氧元素，\\(m(\\mathrm{O}) = 4.60 - 3.00 = 1.60\\text{ g}\\)（\\(n(\\mathrm{O}) = \\frac{1.60}{16} = 0.100\\text{ mol}\\)）。","原子个数最简比：\\(n(\\mathrm{C}) : n(\\mathrm{H}) : n(\\mathrm{O}) = 0.200 : 0.600 : 0.100 = 2 : 6 : 1\\)，实验式为 **\\(\\mathrm{C_2H_6O}\\)**。","第(2)问：设分子式为 \\((\\mathrm{C_2H_6O})_n = \\mathrm{C}_{2n}\\mathrm{H}_{6n}\\mathrm{O}_n\\)（\\(n \\ge 1\\) 整数）。根据碳的四价成键饱和极限，含 \\(2n\\) 个碳原子的有机分子中氢原子数**最多不能超过** \\(2(2n) + 2 = 4n + 2\\)（氧原子为二价只插入单键不增加饱和氢数）。","令 \\(6n \\le 4n + 2 \\implies 2n \\le 2 \\implies n \\le 1\\)，因此正整数只能取 \\(n = 1\\)，分子式唯一确定为 **\\(\\mathrm{C_2H_6O}\\)**（乙醇或二甲醚）。"],"ans":"(1) 含氧 1.60 g，实验式 \\(\\mathrm{C_2H_6O}\\)；(2) 分子式必为 \\(\\mathrm{C_2H_6O}\\)，因为当 \\(n \\ge 2\\) 时氢原子数 \\(6n\\) 超出碳四价饱和上限 \\(4n+2\\)。","markingPoints":["算出 C、H、O 质量及实验式 C₂H₆O（3分）","明确利用“氢原子饱和上限 2C+2”证明 n=1 为唯一可能正整数解（2分）"],"verification":"此为 UEC 与 SPM/预试极爱考的“实验式+化学常识直接确定分子式”跨有机化学桥接压轴题。","pitfall":"部分考生会误答“缺少式量数据无法确定分子式”，忽略了饱和烷烃衍生物（如 CH₃、C₂H₆O、CH₄O 等）实验式即分子式！"}],"cheatSheet":["化合价规则：单质=0，化合物代数和=0；多原子根超过1个加括号；只用于已知存在化合物。","活动5铜粉氧化：恒重标准 = 连续称量质量不再变化；注意惰性杂质 vs 易挥发杂质误差方向。","非整比倍率口诀：0.5→×2；0.33/0.67→×3；0.25/0.75→×4；绝不四舍五入。","有机物燃烧必先用总重减 C、H 判别是否含 O；饱和实验式（如 CH₃、C₂H₆O）直接就是分子式！"],"kbEntryIds":["kb-chem3-valence-table","kb-chem3-exp5-empirical"],"quiz":{"q":"某碳氢化合物中含氢质量分数为 \\(20.0\\%\\)，在同温同压下其对 \\(\\mathrm{H_2}\\) 相对密度为 \\(15.0\\)，求其实验式与分子式。","given":"C 80%, H 20%; D(H₂)=15.0","method":"质量百分比求实验式，再结合 Mr=30 定分子式","principle":"实验式与相对密度联动法（教材例7同型）。","steps":["n(C):n(H) = (80/12):(20/1) = 6.67:20 = 1:3 ⇒ 实验式 CH₃（式量 15）。","Mr = 15.0 × 2 = 30 ⇒ n = 30 / 15 = 2 ⇒ 分子式 C₂H₆。"],"ans":"实验式 \\(\\mathrm{CH_3}\\)，分子式 \\(\\mathrm{C_2H_6}\\)"}},{"id":"3.6","t":"物质的量","anchor":{"pages":"化上 p.66–72","syllabus":"1.2.4–1.2.6 物质的量、摩尔、阿伏加德罗常数与摩尔质量","examScopes":["sem1_final","pre_exam","sem2_final","uec"],"examWeight":"全高中定量计算核心（P1 必考 NA 陷阱题 + P2 全部化学计算基石）","terms":"amount of substance (n) · mole (mol) · Avogadro constant (NA) · molar mass (M)","prerequisites":["原子、分子、离子与电子微粒层级区分（3.1, 3.3）","式量 Mr 计算（3.4）"],"goals":["准确表述物质的量（n）、摩尔（mol）与阿伏加德罗常数（NA ≈ 6.02×10²³ mol⁻¹）的物理定义，并严格落实‘指明微粒’规范。","厘清摩尔质量 M（单位 g/mol）与相对分子/原子质量 Mr/Ar（无单位）的联系与区别。","熟练以物质的量 n 为中枢，完成宏观质量 m、粒子数（分子/原子/离子/电子数）N、结晶水合物及混合气体平均摩尔质量之间的综合换算。"]},"concepts":[{"kind":"definition","title":"物质的量（n）、摩尔（mol）与阿伏加德罗常数（NA）","pageRef":"化上 p.66–67、p.72","body":["**物质的量（Amount of Substance）**：国际单位制（SI）七大基本物理量之一，符号 \\(n\\)，表示含有一定数目微粒的集合体，单位为**摩尔**（简称摩，符号 \\(\\mathrm{mol}\\)）。","**教材核心标定与阿伏加德罗常数**：\\(1\\text{ mol}\\) 任何微粒集合体所含微粒数与 \\(0.012\\text{ kg}\\ {}^{12}\\mathrm{C}\\) 中所含原子数相同；\\(0.012\\text{ kg}\\ {}^{12}\\mathrm{C}\\) 所含的碳原子数称为**阿伏加德罗常数（\\(N_A\\)）**，其**近似值**为 **\\(6.02\\times 10^{23}\\text{ mol}^{-1}\\)**（注意单位是 \\(\\mathrm{mol}^{-1}\\)！注：2019年起现代 SI 将 \\(N_A\\) 精准定为 \\(6.02214076\\times 10^{23}\\text{ mol}^{-1}\\)）。","**铁规：必须指明微粒种类（p.72 第13条）**：摩尔只适用于微观粒子（分子、原子、离子、电子、质子、中子、原子团），且必须明确指出微粒名称或化学式——不可笼统说“\\(1\\text{ mol}\\) 氧”或“\\(1\\text{ mol}\\) 大米”。"],"takeaway":"“物质的量”是专用物理量全称，不可简写成“物质量”或等同于“物质的质量（m）”！"},{"kind":"formula","title":"摩尔质量（M）与以 n 为枢纽的微粒拆分关系","pageRef":"化上 p.68–70","body":["**摩尔质量（Molar Mass, 符号 \\(M\\)）**：单位物质的量的物质所具有的质量，即 \\(M = \\frac{m}{n}\\)，常用单位为 **\\(\\mathrm{g\\,mol^{-1}}\\)**（或 \\(\\mathrm{g/mol}\\)）。当物质质量以克（g）为单位时，摩尔质量在**数值上等于**该微粒的式量或相对原子质量（如 \\(M(\\mathrm{H_2SO_4}) = 98\\text{ g\\,mol}^{-1}\\)；\\(M(\\mathrm{SO_4^{2-}}) = 96\\text{ g\\,mol}^{-1}\\)）。","**化学方程式计量桥接（p.70）**：反应 \\(\\mathrm{C + O_2 \\to CO_2}\\) 既可读作 1 个 C 与 1 个 O₂ 生成 1 个 CO₂，也可在宏观上等价读作 **\\(1\\text{ mol C}\\) 与 \\(1\\text{ mol }\\mathrm{O_2}\\) 完全反应生成 \\(1\\text{ mol }\\mathrm{CO_2}\\)**——这正是第4章全章计算的基础！"],"takeaway":"无论求宏观质量、微观粒子数、还是以后结合气体体积 V 或溶液浓度 c，永远是：未知量 → 先算 n → 转化学计量比 → 再算目标量。"},{"kind":"mechanism","title":"复杂微粒与电子/离子拆分 + 混合气平均摩尔质量（高阶思维）","pageRef":"化上 p.69 例10、p.75 第2题拓展","body":["**多层级粒子拆解**：先算“整份化学式”的物质的量 \\(n\\)，再乘以“每 1 个化学式内所含的目标粒子数目”。例如 \\(1\\text{ mol }\\mathrm{Na_2SO_4\\cdot 10H_2O}\\) 中含：\\(2\\text{ mol }\\mathrm{Na^+}\\)、\\(1\\text{ mol }\\mathrm{SO_4^{2-}}\\)（共 \\(3\\text{ mol}\\) 离子）、\\(10\\text{ mol }\\mathrm{H_2O}\\) 分子、\\(14\\text{ mol O}\\) 原子（\\(4 + 10\\)）。算**总电子数**或**质子数**时，只需把化学式内所有原子的序数 \\(Z\\) 相加再加减电荷（如 \\(1\\text{ 个 }\\mathrm{CO_2}\\) 含 \\(6 + 8\\times 2 = 22\\) 个电子；\\(1\\text{ 个 }\\mathrm{NH_4^+}\\) 含 \\(7 + 4 - 1 = 10\\) 个电子）。","**混合气体平均摩尔质量 \\(\\bar{M}\\)**：\\(\\bar{M} = \\frac{m_{\\text{总}}}{n_{\\text{总}}} = \\sum_i x_i M_i\\)（\\(x_i\\) 为体积分数/物质的量分数）；若测得同温同压下对 \\(\\mathrm{H_2}\\) 的相对密度为 \\(D\\)，则 \\(\\bar{M} = 2D\\)。"],"takeaway":"求总电子数前切记检查是**中性分子**还是**带电离子**（阳离子减电荷，阴离子加电荷）！"}],"formulas":[{"title":"物质的量中心换算枢纽（m ⇄ n ⇄ N ⇄ 气体 V）","tex":"n = \\frac{m}{M} = \\frac{N}{N_A}\\quad\\left(\\text{气体：}n = \\frac{V}{V_m}\\right),\\qquad N_A \\approx 6.02\\times 10^{23}\\text{ mol}^{-1}","plain":"n = m / M = N / NA（标准状况理想气体 Vm ≈ 22.4 L/mol）","conditions":"m 必以 g 计、M 以 g/mol 计；V/Vm 仅限气态且标清温压（标准状况 0℃, 1 atm 约为 22.4 L/mol）","pageRef":"化上 p.67–68","note":"水（H₂O）、酒精、CCl₄、SO₃ 在标准状况（0 ℃）下均为液态或固态，严禁套用 22.4 L/mol！"},{"title":"混合气体平均摩尔质量与相对密度","tex":"\\bar{M} = \\frac{m_{\\text{总}}}{n_{\\text{总}}} = \\sum_i x_i M_i = D_{\\text{对B}} \\cdot M(\\mathrm{B})","plain":"M̄ = m总 / n总 = D × M(B)","conditions":"xᵢ 为气体体积分数（即物质的量分数）；D 为同温同压下的密度比","pageRef":"化上 p.44 与 p.68 综合衔接","note":"空气平均摩尔质量常近似取 29 g/mol，H₂ 取 2 g/mol。"}],"pitfalls":[{"title":"混淆摩尔质量（M）、1 mol 物质的质量与相对分子质量（Mr）的单位","wrong":"“\\(1\\text{ mol HCl}\\) 的质量是 \\(36.5\\text{ g\\,mol}^{-1}\\)；氯气的摩尔质量等于它的式量。”","diagnosis":"“1 mol 物质的质量”单位是 **g**（\\(36.5\\text{ g}\\)）；“摩尔质量”单位是 **g/mol**；“式量”**无单位**！三者仅在克每摩单位体系下**数值相等**。","right":"\\(1\\text{ mol HCl}\\) 的质量是 **\\(36.5\\text{ g}\\)**；\\(\\mathrm{HCl}\\) 的摩尔质量是 **\\(36.5\\text{ g\\,mol}^{-1}\\)**；\\(\\mathrm{HCl}\\) 的式量是 **\\(36.5\\)**（教材 p.75 第17题原陷阱）。","checkRule":"看到“质量是 …… g/mol”或“摩尔质量是 …… g（或等于式量）”，立刻判错！"},{"title":"阿伏加德罗常数 NA 经典‘非气态/未定温压/共价键与水合’四大坑","wrong":"“标准状况下，\\(22.4\\text{ L}\\) 水所含分子数为 \\(N_A\\)（教材 p.75 第16题 D 选项诱饵）。”","diagnosis":"标准状况为 \\(0\\ ^\\circ\\mathrm{C}\\)、\\(1\\text{ atm}\\)，此时水为液态（密度 \\(1\\text{ g/mL}\\)），\\(22.4\\text{ L}\\) 水质量达 \\(22\\,400\\text{ g}\\)，远超 \\(1\\text{ mol}\\)！","right":"做 NA 题四重过滤：①看状态（标况下 \\(\\mathrm{H_2O}, \\mathrm{HF}, \\mathrm{Br_2}, \\mathrm{CCl_4}, \\mathrm{SO_3}, \\text{己烷}\\) 均非气体）；②看条件（常温常压 \\(22.4\\text{ L}\\) 气体少于 \\(1\\text{ mol}\\)）；③看粒子层级（\\(\\mathrm{O_2}\\) 分子数 vs \\(\\mathrm{O}\\) 原子数、离子数、电子数）；④看等最简式混合气（如 \\(\\mathrm{NO_2}\\) 与 \\(\\mathrm{N_2O_4}\\)）。","checkRule":"见到 `22.4 L` 必须立刻检查两项：**①是否为气体？②是否为标准状况？**"},{"title":"说“物质的量就是物质的质量”或未指明微粒","wrong":"“\\(1\\text{ mol}\\) 氢的质量是 \\(2\\text{ g}\\)。”","diagnosis":"“氢”未指明是氢原子 \\(\\mathrm{H}\\)（\\(1\\text{ g}\\)）还是氢分子 \\(\\mathrm{H_2}\\)（\\(2\\text{ g}\\)）还是氢离子 \\(\\mathrm{H^+}\\)。","right":"“物质的量”是衡量**微粒数目**的物理量（单位 \\(\\mathrm{mol}\\)），不是质量（单位 \\(\\mathrm{kg/g}\\)）；使用摩尔必须明确写出 \\(1\\text{ mol}\\ \\mathrm{H_2}\\) 或 \\(1\\text{ mol}\\ \\mathrm{H}\\)。","checkRule":"遇到汉字单个元素名（氢/氧/氮/氯）配摩尔时，一律算未指明微粒（除非化学式已明确标出）。"}],"examples":[{"label":"例 3.6.1","tier":"L2","tierLabel":"L2 校内期末","title":"教材例10升华：结晶水合物的离子、水分子与总氧原子拆解","prompt":"（改编自教材 p.69 例10）称取 \\(32.2\\text{ g}\\) 芒硝晶体（\\(\\mathrm{Na_2SO_4\\cdot 10H_2O}\\)），（已知 \\(M_r = 322\\)，\\(N_A = 6.02\\times 10^{23}\\text{ mol}^{-1}\\)）试求该晶体中：(1) 晶体的物质的量；(2) 所含 \\(\\mathrm{Na^+}\\) 与 \\(\\mathrm{SO_4^{2-}}\\) 的总物质的量（及离子总数）；(3) 所含结晶水分子数目及全部**氧原子**总物质的量。","clues":"1 份 \\(\\mathrm{Na_2SO_4\\cdot 10H_2O}\\) 中包含 2 个 \\(\\mathrm{Na^+}\\)、1 个 \\(\\mathrm{SO_4^{2-}}\\)（共 3 个离子）和 10 个 \\(\\mathrm{H_2O}\\) 分子；氧原子在硫酸根（4个）与水分子（10个）中均有分布！","strategy":"先由 \\(n = m/M\\) 求整份晶体物质的量，再按化学式脚标逐层倍乘。","given":"m(Na₂SO₄·10H₂O) = 32.2 g, M = 322 g/mol","principle":"物质的量公式 \\(n = m/M = N/N_A\\) 及结构微粒比例。","steps":["第(1)问：晶体的摩尔质量 \\(M = 322\\text{ g\\,mol}^{-1}\\)，物质的量：\\(n = \\frac{32.2\\text{ g}}{322\\text{ g\\,mol}^{-1}} = 0.100\\text{ mol}\\)。","第(2)问：\\(n(\\mathrm{Na^+}) = 0.100\\times 2 = 0.200\\text{ mol}\\)；\\(n(\\mathrm{SO_4^{2-}}) = 0.100\\times 1 = 0.100\\text{ mol}\\)；故离子总物质的量 \\(= 0.300\\text{ mol}\\)，离子总数 \\(= 0.300\\times 6.02\\times 10^{23} = 1.806\\times 10^{23} \\approx 1.81\\times 10^{23}\\) 个。","第(3)问：水分子物质的量 \\(n(\\mathrm{H_2O}) = 0.100\\times 10 = 1.00\\text{ mol}\\)，水分子数 \\(= 6.02\\times 10^{23}\\) 个；每份晶体共含 \\(4 + 10 = 14\\) 个氧原子，故总氧原子 \\(n(\\mathrm{O}) = 0.100 \\times 14 = 1.40\\text{ mol}\\)。"],"answer":"(1) 0.100 mol；(2) Na⁺ 0.200 mol、SO₄²⁻ 0.100 mol，总离子数 1.81×10²³ 个；(3) 水分子数 6.02×10²³ 个，氧原子总量 1.40 mol。","markingPoints":["算对晶体 0.100 mol（1分）","正确分别拆出 Na⁺、SO₄²⁻ 与总离子数（2分）","合并硫酸根与结晶水两处氧原子求出 1.40 mol O（2分）"],"verification":"校验教材例10（p.69）：483 g 为 1.50 mol，本题 32.2 g 为 0.100 mol 比例完全一致。","pitfall":"第(3)问常漏掉硫酸根内的 4 个 O 或漏掉结晶水中的 10 个 O，或者错把水分子算成“离子”。"},{"label":"例 3.6.2","tier":"L4","tierLabel":"L4 统考压轴","title":"NA 高频多陷阱排查与等最简式混合体系微粒守恒","prompt":"设 \\(N_A\\) 为阿伏加德罗常数的值。下列各组关于微粒数目的判断中，**完全准确且不受温度压强限制**的是哪几项？请对错误项逐一精准改错：\n① 标准状况下，\\(22.4\\text{ L}\\) 乙烷（\\(\\mathrm{C_2H_6}\\)）与 \\(22.4\\text{ L}\\) 液态水所含分子数均为 \\(N_A\\)；\n② 常温常压下，\\(46.0\\text{ g}\\) 由 \\(\\mathrm{NO_2}\\) 和 \\(\\mathrm{N_2O_4}\\) 组成的混合气体中共含原子总数为 \\(3N_A\\)；\n③ \\(1\\text{ mol}\\ \\mathrm{CH_4}\\) 与 \\(1\\text{ mol}\\ \\mathrm{NH_4^+}\\) 中所含的质子数相等、电子数也相等；\n④ \\(28.0\\text{ g}\\) 由 \\(\\mathrm{CO}\\) 和 \\(\\mathrm{N_2}\\) 组成的混合气体中，所含分子总数为 \\(N_A\\)、原子总数为 \\(2N_A\\)、总电子数为 \\(14N_A\\)。","clues":"运用“相同最简式法”与“等摩尔质量/等电子体法”，避开无法分开求各组分质量的死胡同！","strategy":"逐项拆解微粒结构与物质状态，检验哪些量与混合比例无关。","given":"四项常见 NA 高阶统考命题","principle":"态判别 + 最简式原子守恒（NO₂/N₂O₄）+ 等电子双原子气体守恒（CO/N₂）。","steps":["① **错误**。标准状况（\\(0\\ ^\\circ\\mathrm{C}\\)）下水是**液体**（\\(22.4\\text{ L}\\) 水约含 \\(1244\\text{ mol}\\)），不能用 \\(22.4\\text{ L/mol}\\)；仅标况气态 \\(\\mathrm{C_2H_6}\\) 为 \\(N_A\\)。","② **完全准确（核心技巧）**。\\(\\mathrm{NO_2}\\) 与 \\(\\mathrm{N_2O_4}\\) 的最简式（实验式）完全相同，都是 \\(\\mathrm{NO_2}\\)（每个 \\(\\mathrm{NO_2}\\) 单元式量为 \\(46\\)、含 \\(3\\) 个原子）！故无论混合比例、温度压强或可逆平衡如何，\\(46.0\\text{ g}\\) 混合气必定含 \\(1.00\\text{ mol}\\) \\(\\mathrm{NO_2}\\) 单元，原子总数恒为 \\(3N_A\\)。","③ **一半对一半错**。\\(\\mathrm{CH_4}\\) 含质子 \\(6+4=10\\)、电子 \\(10\\)；\\(\\mathrm{NH_4^+}\\) 含质子 \\(7+4=11\\)、电子 \\(11-1=10\\)。故两者**电子数相等**（均为 \\(10N_A\\)），但**质子数不等**（\\(10N_A \\ne 11N_A\\)）！","④ **完全准确（核心技巧）**。\\(\\mathrm{CO}\\) 与 \\(\\mathrm{N_2}\\) 的摩尔质量均为 \\(28\\text{ g/mol}\\)，同为双原子分子，且单分子电子数同为 \\(6+8=14\\) 与 \\(7+7=14\\)。所以无论两者按何种比例混合，\\(28.0\\text{ g}\\) 混合气体物质的量恒为 \\(1.00\\text{ mol}\\)，分子数 \\(N_A\\)、原子数 \\(2N_A\\)、电子数 \\(14N_A\\)（质子数也是 \\(14N_A\\)）全部不依赖组成而成立！"],"answer":"② 和 ④ 完全准确；① 错因标况下水非气体；③ 错因 CH₄(10) 与 NH₄⁺(11) 质子数不等。","markingPoints":["准确识别标况水态与 CH₄/NH₄⁺ 质子数差异（2分）","掌握 NO₂/N₂O₄ 同实验式法及 CO/N₂ 等式量等电子体法（3分）"],"verification":"此两招（同最简式、同摩尔质量等电子体）在 UEC Paper 1 第 1–10 题几乎每年必现。","pitfall":"算 ③ 时以为“电荷不影响总微粒数”，误把 NH₄⁺ 质子数也当成 10；或面对未知比例的混合气体时认为条件不足。"}],"practice":[{"id":"chem3-3.6-q1","tier":"L1","tierLabel":"L1 基础","examStyle":"P1 选择","q":"（综合教材 p.74–75 第15、17题）下列有关物质的量及摩尔质量的说法中，**正确**的是（　）。","options":["A. “物质的量”就是“物质的质量”，两者的国际单位制单位均可用 g 或 mol","B. 1 mol HCl 的质量是 36.5 g·mol⁻¹","C. 硫酸根离子（SO₄²⁻）的摩尔质量是 96 g·mol⁻¹","D. 氯气的摩尔质量等于它的式量，均为 71"],"correctOption":"C","given":"概念与单位规范判断","method":"逐项比对物理量定义及单位（mol, g, g/mol, 无单位）","principle":"物理量与单位严格对应，数值相等不代表量纲相等。","steps":["A 错：物质的量（符号 n，单位 mol）衡量微粒数目；质量（m，单位 kg/g）衡量惯性物重，完全不是同一物理量。","B 错：1 mol HCl 的质量单位只能是 g，应为 36.5 g。","C 对：SO₄²⁻ 式量为 32 + 64 = 96（电子质量可忽略），摩尔质量带有正确单位 96 g·mol⁻¹。","D 错：摩尔质量有单位 g·mol⁻¹，式量无单位，不能用“等于”混为一谈。"],"ans":"C","markingPoints":["精准识别 g、g/mol 与无单位差异"],"verification":"与教材 p.74 第15题、p.75 第17题官方要点完全一致。","pitfall":"误选 B 或 D，在考场看快了忽略单位后缀。"},{"id":"chem3-3.6-q2","tier":"L2","tierLabel":"L2 期末","examStyle":"P1 选择","q":"（改编自教材 p.75 第16题）在下列各组指定状态的物质或微粒中，**质量最大**和**分子/粒子个数最多**的组合（前为质量最大，后为指定微粒数最多，已知 \\(\\mathrm{H}=1, \\mathrm{O}=16, \\mathrm{Cu}=63.5\\)）分别是（　）。\n① \\(0.5\\text{ mol Cu}\\) 金属原子；② \\(6.02\\times 10^{23}\\text{ 个}\\ \\mathrm{H_2}\\) 分子；③ \\(16.0\\text{ g}\\) 氧气；④ 标准状况（0 ℃）下 \\(22.4\\text{ mL}\\) 水（密度 \\(1.0\\text{ g/mL}\\)）。","options":["A. 质量最大为 ①，分子/原子数最多为 ④","B. 质量最大为 ②，分子/原子数最多为 ②","C. 质量最大为 ①，分子/原子数最多为 ②","D. 质量最大为 ④，分子/原子数最多为 ④"],"correctOption":"A","given":"①0.5 mol Cu; ②6.02×10²³ H₂; ③16 g O₂; ④22.4 mL H₂O","method":"全部换算为质量（g）与物质的量（mol）比较大小","principle":"n = m/M = N/NA；液态水 m = ρV。","steps":["① \\(0.5\\text{ mol Cu}\\)：质量 \\(0.5\\times 63.5 = 31.75\\text{ g}\\)；原子 \\(0.5\\text{ mol}\\)。","② \\(6.02\\times 10^{23}\\text{ 个}\\ \\mathrm{H_2}\\)：即 \\(1.0\\text{ mol}\\ \\mathrm{H_2}\\)，质量 \\(2.0\\text{ g}\\)，分子数 \\(1.0\\text{ mol}\\)（原子数 \\(2.0\\text{ mol}\\)）。","③ \\(16.0\\text{ g}\\ \\mathrm{O_2}\\)：质量 \\(16.0\\text{ g}\\)；\\(n = 16/32 = 0.50\\text{ mol}\\) 分子。","④ 标况下 \\(22.4\\text{ mL}\\) 水是**液体**！质量 \\(m = 22.4\\text{ mL}\\times 1.0\\text{ g/mL} = 22.4\\text{ g}\\)；水分子物质的量 \\(n = \\frac{22.4}{18} \\approx 1.24\\text{ mol} > 1.0\\text{ mol}\\)！","综上：质量最大为 ①（31.75 g）；分子数最多为 ④（1.24 mol 分子，即约 7.49×10²³ 个，甚至连总数也大于 ② 的分子数！）。"],"ans":"A","markingPoints":["避免把 22.4 mL 水按标况气体 22.4 L/mol 除以 22400，准确用密度 1 g/mL 求得 1.24 mol 水分子"],"verification":"\\(31.75 > 22.4 > 16.0 > 2.0\\)；水分子 \\(1.24\\text{ mol} > 1.00\\text{ mol}\\ \\mathrm{H_2} > 0.50\\text{ mol}\\ \\mathrm{Cu},\\mathrm{O_2}\\)。","pitfall":"若把 ④ 误按气体算出 \\(0.001\\text{ mol}\\) 就会错选 C！"},{"id":"chem3-3.6-q3","tier":"L2","tierLabel":"L2 期末","examStyle":"P2 必答计算","q":"（教材 p.75 作答题第2题完整计算）现有 \\(0.50\\text{ mol}\\) 的二氧化碳（\\(\\mathrm{CO_2}\\)）气体（已知 \\(\\mathrm{C}=12, \\mathrm{O}=16\\)，碳原子和氧原子核外电子数分别为 \\(6\\) 和 \\(8\\)，\\(N_A = 6.02\\times 10^{23}\\text{ mol}^{-1}\\)）。求：(1) 其质量是多少克？(2) 含有多少个 \\(\\mathrm{CO_2}\\) 分子？(3) 含有多少个氧原子？(4) 一共含有多少个电子？","given":"n(CO₂)=0.50 mol；C 6e⁻, O 8e⁻","method":"由物质的量出发，逐级乘摩尔质量 M、阿伏加德罗常数 NA 及分子内微粒数","principle":"微观层级递推：分子数 → 原子数 → 电子数。","steps":["(1) \\(M(\\mathrm{CO_2}) = 12 + 16\\times 2 = 44\\text{ g\\,mol}^{-1}\\)，质量 \\(m = 0.50\\text{ mol}\\times 44\\text{ g\\,mol}^{-1} = 22.0\\text{ g}\\)。","(2) \\(\\mathrm{CO_2}\\) 分子数：\\(N(\\mathrm{CO_2}) = 0.50\\text{ mol}\\times 6.02\\times 10^{23}\\text{ mol}^{-1} = 3.01\\times 10^{23}\\) 个。","(3) 每个 \\(\\mathrm{CO_2}\\) 分子含 2 个 O 原子，氧原子物质的量 \\(n(\\mathrm{O}) = 0.50\\times 2 = 1.00\\text{ mol}\\)，故氧原子数 \\(N(\\mathrm{O}) = 6.02\\times 10^{23}\\) 个。","(4) 每个 \\(\\mathrm{CO_2}\\) 分子含电子数为 \\(6 + 8\\times 2 = 22\\) 个，总电子物质的量 \\(n(e^-) = 0.50\\times 22 = 11.0\\text{ mol}\\)，总电子数 \\(N(e^-) = 11.0 \\times 6.02\\times 10^{23} = 6.622\\times 10^{24} \\approx 6.62\\times 10^{24}\\) 个。"],"ans":"(1) 22.0 g；(2) 3.01×10²³ 个 CO₂ 分子；(3) 6.02×10²³ 个 O 原子；(4) 6.62×10²⁴ 个电子。","markingPoints":["每小问结果与单位、科学记数法（10 的幂次有效数字规范）均正确各得 1 分，共 4 分"],"verification":"\\(11 \\times 6.02 = 66.22\\)，转化为标准科学记数法即 \\(6.622\\times 10^{24}\\)。","pitfall":"第(4)问算成 \\(66.22\\times 10^{23}\\) 未改写成标准科学记数法，或漏乘 O 原子下标 2。"},{"id":"chem3-3.6-q4","tier":"L3","tierLabel":"L3 预试","examStyle":"P2 必答计算","q":"（教材 p.75 作答题第4题加深）(1) \\(4.50\\text{ g}\\) 水（\\(\\mathrm{H_2O}\\)）与多少克纯硫酸（\\(\\mathrm{H_2SO_4}\\)）所含的分子数目相等？在这种条件下，两者所含氧原子数之比和氢原子数之比各是多少？(2) 若改要求两者所含的**氧原子数目**相等，则此时水与纯硫酸的质量比应当是多少？（已知 \\(\\mathrm{H}=1, \\mathrm{O}=16, \\mathrm{S}=32\\)）","given":"m(H₂O) = 4.50 g (M=18); M(H₂SO₄) = 98","method":"分子数相等 ⇔ 物质的量 n 相等；氧原子相等 ⇔ n(H₂O)×1 = n(H₂SO₄)×4","principle":"微观粒子数之比等同于其物质的量之比。","steps":["(1) \\(n(\\mathrm{H_2O}) = \\frac{4.50\\text{ g}}{18\\text{ g\\,mol}^{-1}} = 0.250\\text{ mol}\\)。分子数相等即 \\(n(\\mathrm{H_2SO_4}) = 0.250\\text{ mol}\\)，需硫酸质量 \\(m = 0.250 \\times 98 = 24.5\\text{ g}\\)。","等分子数（均为 \\(0.250\\text{ mol}\\)）时：氧原子数之比 \\(= 1 : 4\\)；氢原子数之比 \\(= 2 : 2 = 1 : 1\\)。","(2) 若令两者氧原子数相等，需满足 \\(n(\\mathrm{H_2O}) \\times 1 = n(\\mathrm{H_2SO_4}) \\times 4 \\implies n(\\mathrm{H_2O}) : n(\\mathrm{H_2SO_4}) = 4 : 1\\)。","此时质量比为：\\(m(\\mathrm{H_2O}) : m(\\mathrm{H_2SO_4}) = (4 \\times 18) : (1 \\times 98) = 72 : 98 = 36 : 49\\)。"],"ans":"(1) 24.5 g 硫酸；氧原子比 1 : 4，氢原子比 1 : 1；(2) 等氧原子数时水与硫酸质量比为 36 : 49。","markingPoints":["算出 n=0.250 mol 得 24.5 g 硫酸（1分）","算对氧比 1:4 与氢比 1:1（2分）","由氧相等导出物质的量比 4:1 并求得质量比 36:49（2分）"],"verification":"\\(36\\text{ g}\\) 水（2 mol O）与 \\(49\\text{ g}\\) 硫酸（0.5×4 = 2 mol O）氧原子全等。","pitfall":"第(2)问容易反算成 1:4 导致得出 18:392。"},{"id":"chem3-3.6-q5","tier":"L4","tierLabel":"L4 统考压轴","examStyle":"P2 综合压轴","q":"在同温同压下，某由一氧化碳（\\(\\mathrm{CO}\\)）和二氧化碳（\\(\\mathrm{CO_2}\\)）组成的均匀混合气体，测得其密度是同条件下氢气（\\(\\mathrm{H_2}\\)）密度的 \\(18.0\\) 倍。（已知 \\(\\mathrm{H}=1, \\mathrm{C}=12, \\mathrm{O}=16\\)）试求：(1) 该混合气体的平均摩尔质量 \\(\\bar{M}\\)；(2) 混合气体中 \\(\\mathrm{CO}\\) 与 \\(\\mathrm{CO_2}\\) 的体积比及质量比；(3) 取 \\(7.20\\text{ g}\\) 该混合气体，共含碳原子多少摩尔、氧原子多少摩尔？含总电子数为多少 \\(N_A\\)？","given":"D(对H₂) = 18.0；M(CO)=28, M(CO₂)=44；取样 m = 7.20 g","method":"密度比定平均摩尔质量 → 加权公式求组分体积比/物质的量比 → 转质量求总电子数","principle":"阿伏加德罗气体密度定律、平均摩尔质量及电子守恒。","steps":["(1) 同温同压下，混合气体平均摩尔质量：\\(\\bar{M} = 18.0 \\times M(\\mathrm{H_2}) = 18.0 \\times 2.0 = 36.0\\text{ g\\,mol}^{-1}\\)。","(2) 设 \\(1.00\\text{ mol}\\) 混合气体中 \\(\\mathrm{CO}\\) 占 \\(x\\text{ mol}\\)、\\(\\mathrm{CO_2}\\) 占 \\((1-x)\\text{ mol}\\)：\\(28x + 44(1-x) = 36.0 \\implies 16x = 8.0 \\implies x = 0.500\\)。","同温同压下体积比等于物质的量比，即 \\(V(\\mathrm{CO}) : V(\\mathrm{CO_2}) = 0.500 : 0.500 = 1 : 1\\)；质量比为 \\((0.500\\times 28) : (0.500\\times 44) = 28 : 44 = 7 : 11\\)。","(3) \\(7.20\\text{ g}\\) 混合气体的总物质的量为 \\(n_{\\text{总}} = \\frac{7.20\\text{ g}}{36.0\\text{ g\\,mol}^{-1}} = 0.200\\text{ mol}\\)，由 \\(1:1\\) 比知其中含 \\(0.100\\text{ mol}\\ \\mathrm{CO}\\) 和 \\(0.100\\text{ mol}\\ \\mathrm{CO_2}\\)。","每个分子均含 1 个 C，故 \\(n(\\mathrm{C}) = 0.100 + 0.100 = 0.200\\text{ mol}\\)；氧原子 \\(n(\\mathrm{O}) = 0.100\\times 1 + 0.100\\times 2 = 0.300\\text{ mol}\\)。","单分子电子数：\\(\\mathrm{CO}\\) 含 \\(6+8=14\\)，\\(\\mathrm{CO_2}\\) 含 \\(6+16=22\\)，故总电子数 \\(N(e^-) = (0.100\\times 14 + 0.100\\times 22) N_A = 3.60\\,N_A\\)（即 \\(2.17\\times 10^{24}\\) 个）。"],"ans":"(1) 36.0 g·mol⁻¹；(2) 体积比 1:1，质量比 7:11；(3) 含 C 0.200 mol、O 0.300 mol，总电子数 3.60 NA（2.17×10²⁴ 个）。","markingPoints":["算得 M̄ = 36.0 g/mol（1分）","解得体积比 1:1 与质量比 7:11（2分）","求得 0.200 mol 总气体内 C 0.200 mol、O 0.300 mol 及总电子 3.60 NA（3分）"],"verification":"另解验算第(3)问电子数：0.200 mol C（×6=1.20）+ 0.300 mol O（×8=2.40）= 3.60 mol 电子！两条路径完美吻合！","pitfall":"算完体积比 1:1 后忘记各自乘以摩尔质量 28 与 44，误以为质量比也是 1:1。"}],"cheatSheet":["中心换算公式：n = m/M = N/NA；NA ≈ 6.02×10²³ mol⁻¹；M（g/mol）数值=式量。","使用 mol 务必指明微粒；22.4 L/mol 仅限标况气体（液体 H₂O、Br₂、CCl₄ 禁用）。","混合 NA 秒杀两招：①相同最简式（如 NO₂/N₂O₄）；②同式量+同电子数（如 CO/N₂）。","多层级微粒计数：先求总 n，再乘化学式下标；带电离子电子数 = 质子数总和 ± 电荷。"],"kbEntryIds":["kb-chem3-mole-avogadro"],"quiz":{"q":"相同温度和压强下，\\(2.8\\text{ g}\\) 氮气（\\(\\mathrm{N_2}\\)）与 \\(4.4\\text{ g}\\) 二氧化碳（\\(\\mathrm{CO_2}\\)）相比，两者的分子数、原子数与气体体积比各是多少？","given":"2.8 g N₂ (M=28), 4.4 g CO₂ (M=44)","method":"先算物质的量 n，同 T、p 下气体体积比 = 分子数比 = n 比","principle":"阿伏加德罗定律与物质的量。","steps":["n(N₂) = 2.8/28 = 0.10 mol；n(CO₂) = 4.4/44 = 0.10 mol。","分子数比 = 体积比 = 1 : 1；原子数比 = (0.10×2) : (0.10×3) = 2 : 3。"],"ans":"分子数比 \\(1:1\\)，体积比 \\(1:1\\)，原子数比 \\(2:3\\)。"},"diagrams":[{"src":"assets/fig/v2/chem03-mole-hub.svg","caption":"图 3-6 以物质的量 (n) 为中心的宏观质量—微粒数—气体体积定量换算枢纽","alt":"物质的量定量换算思维图","pageRef":"化上 p.66–70"}]}]},"化学4":{"lessonKey":"化学4","courseCode":"chemistry","subject":"化学","chapter":4,"title":"化学方程式与化学计算","syllabus":"1.2.7–1.2.9 化学反应类型、离子方程式、配平与化学计量计算","bookId":"sm1-chemistry-2017","bookCitation":"《马来西亚华文独中教科书 · 化学（上册）》（2017年11月版）第4章 p.77–100","examScopes":["sem1_final","pre_exam","sem2_final","uec"],"chapterOverview":{"summary":"第4章是高三上学期期末考、预试与 UEC 统考绝对核心的**必考计算与化学语言枢纽**：4.1 节确立化学方程式书写规范、四大基本反应类型、离子方程式“写拆删查”四步法及观察法/代数法配平；4.2 节以第3章确立的物质的量（mol）为中心，打通纯物质计量、含杂质（纯度）换算、限量反应物（含折线拐点图像）、产率计算及连续多步反应等统考压轴计算题型。","conceptTree":[{"branch":"4.1 化学反应与化学方程式（p.78–86）","items":["4.1.1 化学方程式书写两原则、状态条件标注、定性与定量五层信息","4.1.2 四大基本反应类型（化合/分解/置换/复分解）与非四大类特例；离子方程式四步法","4.1.3 配平方法（观察法、奇数配偶法、待定系数/代数法、离子电荷守恒）"]},{"branch":"4.2 根据化学方程式的计算（p.87–95）","items":["4.2.1 以 mol 为中心的三步规范与质量/气体/溶液/连续反应计量","4.2.2 不纯物计算（代纯不代杂，纯度正逆换算）","4.2.3 限量反应物与过量反应物（n/系数比值法 + 图像拐点分析）","4.2.4 产率计算（实际产量/理论产量，顺乘逆除原则）"]}]},"paperFocus":["高三上半年期末考（Ch 3–8）：P1 选择题必考离子方程式正误（拆与不拆/电荷/产物价态）、配平系数、反应类型及 1 mol 物质耗氧/结晶水失水计算；P2 必答题核心考查含杂质矿石冶炼、限量反应与产率分步计算。","预试 / 毕业考 / UEC 统考：卷二甲部必答计算（10–14 分）几乎必考一道综合化学计量题，将“离子/化学方程式配平 + 纯度 + 限量反应物（或溶液溶质质量分数）+ 多步连续反应产率”串联考查。"],"solvingWorkflow":["第一步（写与平）：写出真实发生的化学方程式并严格配平（离子方程核对原子数与总电荷双守恒），切勿凭空编造化学式。","第二步（折纯与转 mol）：遇到含杂质矿石、废金属或溶液，先乘纯度 w%（或质量分数）算出纯净物质量，再统一折算为物质的量 n = m/M。","第三步（判限量）：同时给出两种反应物投料时，分别计算 n(A)/a 与 n(B)/b，比值较小者为限量反应物，全盘后续计算一律以限量反应物为基准。","第四步（连续与产率）：多步串联反应优先用原子守恒建立“始态~终态关系式”；顺求实际产物乘产率，逆推原料投料量先除以产率、再除以原料纯度。"],"questionTypes":["化学方程式正误诊断与“写拆删查”离子方程式书写（p.80、p.84–85、p.98）","复杂化学/离子方程式的奇数配偶法与代数法配平","四大基本反应类型识别与酸碱盐置换/复分解现象分析（表 4-1）","含杂质矿石（赤铁矿、石灰石）纯度正逆计算（p.90 例7–8、p.95）","双投料限量反应物判定、过量剩余质量与折线拐点图像解析（p.91–93）","连续多步反应（关系式法）结合溶液、纯度与产率的统考压轴计算（p.94、p.99）"],"scoringNotes":["统考卷二计算题按步骤给分：写出配平方程式（1分）、将已知量换算成 mol 并进行限量对比（1–2分）、列比例求理论量（1分）、纯度/产率校正及有效数字与单位（1–2分）。","若未显式检验限量而碰巧蒙对限量物质，往往会扣除 1 分“限量判定分”；务必写出“因为 n(A)/a < n(B)/b，所以 A 为限量反应物”。"],"vid":[{"t":"离子方程式书写“写拆删查”与常见拆分陷阱","q":"离子方程式 书写 写拆删查 高中化学"},{"t":"复杂化学方程式配平（观察法、奇数配偶法与待定系数法）","q":"化学方程式配平 待定系数法 奇数配偶法"},{"t":"化学计量综合：纯度、限量试剂、产率与连续反应","q":"限量反应物 产率 纯度 化学方程式计算"}],"sections":[{"id":"4.1","t":"化学反应与化学方程式","anchor":{"pages":"化上 p.78–86","syllabus":"4.1.1 化学方程式 · 4.1.2 化学反应的类型与离子方程式 · 4.1.3 化学方程式的配平","examScopes":["sem1_final","pre_exam","sem2_final","uec"],"examWeight":"P1 选择题高频必考（离子方程式正误、反应类型、配平系数）+ P2 全部计算的前提基础","terms":"chemical equation · combination · decomposition · displacement · double decomposition · ionic equation · balancing","prerequisites":["第1章化合物分类与第3章物质不灭定律（原子守恒）、化合价推化学式（3.5.1）"],"goals":["牢记化学方程式的两大书写原则，规范标注物质状态 (s)/(l)/(g)/(aq) 与反应条件，完整读取定性与定量五层信息。","准确判断化合、分解、置换、复分解四种基本反应类型及其适用边界，掌握复分解反应发生的三条件。","熟练运用“写、拆、删、查”四步法书写离子方程式，并能用观察法、奇数配偶法、待定系数（代数）法及电荷守恒配平各类方程式。"]},"concepts":[{"kind":"definition","title":"4.1.1 化学方程式的书写原则、标注规范与五层信息","pageRef":"化上 p.79–80、p.86","body":["**两大书写原则（缺一不可）**：①**必须以客观事实为基础**，绝不能凭空编造不存在的物质或反应（如 p.80 错例 `Fe₂O₃ + 2CO → Fe₂O + 2CO₂` 中 \\(\\mathrm{Fe_2O}\\) 不存在，实际炼铁产物为 \\(\\mathrm{Fe}\\)）；②**遵循物质不灭定律**，反应前后元素种类与各原子总数必须相等。","**状态符号与条件规范（p.79）**：`(s)` 固体、`(l)` 液体、`(g)` 气体、`(aq)` 水溶液；催化剂、点燃等条件写在箭头上方，有两种以上条件时通常把加热符号 `Δ` 写在箭头下方（如 \\(\\mathrm{2KClO_3(s)} \\xrightarrow[\\Delta]{\\mathrm{MnO_2}} \\mathrm{2KCl(s) + 3O_2(g)}\\)）。","**配平化学方程式提供的信息（p.86）**：","- **定性信息**：说明反应物、生成物及反应条件。","- **定量信息**（以 \\(\\mathrm{2H_2(g) + O_2(g) \\xrightarrow{\\text{点燃}} 2H_2O(l)}\\) 为例）：分子数比 `2 : 1 : 2`、物质的量比 `2 mol : 1 mol : 2 mol`、质量比 `4 g : 32 g : 36 g`。"],"takeaway":"注意 \\(\\mathrm{H_2O}\\) 和 \\(\\mathrm{H_2O_2}\\) 下标差一个数字就是截然不同的物质，配平时绝不能改动化学式下标！"},{"kind":"table","title":"4.1.2 四大基本反应类型、复分解三条件与非四大类特例","pageRef":"化上 p.81–83","body":["初中及高中初级阶段常将反应分为四种基本类型，但教材 p.83 特别强调：**这四种基本分类不能概括全部化学反应**（如 \\(\\mathrm{CO_2(g) + 2NaOH(aq) \\to Na_2CO_3(aq) + H_2O(l)}\\) 及高炉炼铁 \\(\\mathrm{Fe_2O_3 + 3CO \\xrightarrow{\\Delta} 2Fe + 3CO_2}\\) 均不属于任何一类）。"],"table":{"headers":["反应类型","通式与特征","教材典例与活动实验现象（p.81–83）","发生条件 / 考场提醒"],"rows":[["化合反应","A + B → AB（多变一）","Fe + S —Δ→ FeS；Cl₂ + PCl₃ → PCl₅；PbO₂ + SO₂ —Δ→ PbSO₄","单质或化合物均能化合（不一定都是氧化还原，如 CaO + H₂O）"],["分解反应","AB → A + B（一变多）","CaCO₃ —Δ→ CaO + CO₂；2H₂O —电解→ 2H₂ + O₂；2HgO —Δ→ 2Hg + O₂","常需加热、通电或催化剂条件"],["置换反应","单质 + 化合物 → 新单质 + 新化合物","活动1：Fe + CuSO₄ → FeSO₄ + Cu（铁钉附红棕色铜，蓝变浅绿）\n活动2：Cl₂ + 2NaBr → 2NaCl + Br₂(l)（无色变橙黄）","活泼金属置换弱金属/H；活泼非金属（Cl₂）置换弱非金属（Br₂、I₂）"],["复分解反应","AB + CD → AD + CB（交换成分）","HCl + NaOH → NaCl + H₂O；BaCl₂ + H₂SO₄ → BaSO₄↓ + 2HCl；FeS + 2HCl → FeCl₂ + H₂S↑","必具备三条件之一：①生成难溶沉淀；②生成挥发性气体；③生成难电离物质（如 H₂O）"]]}},{"kind":"mechanism","title":"离子反应与离子方程式“写、拆、删、查”四步法（p.84–85）","pageRef":"化上 p.83–85、p.96","body":["**定义**：有离子参加或生成的反应称为离子反应；用实际参加反应的离子来表示的式子称为**离子方程式**（能代表同一类型的所有反应）。","**四步书写铁律（以 \\(\\mathrm{Na_2CO_3 + 2HCl}\\) 为例）**：","- **① 写**：写出配平的化学方程式：\\(\\mathrm{Na_2CO_3(aq) + 2HCl(aq) \\to 2NaCl(aq) + CO_2(g) + H_2O(l)}\\)。","- **② 拆**：把**溶于水且完全电离**的强电解质（强酸 \\(\\mathrm{HCl, H_2SO_4, HNO_3}\\)、强碱 \\(\\mathrm{NaOH, KOH, Ba(OH)_2, Ca(OH)_2}\\) 澄清液及可溶性盐）拆成自由移动离子；**不拆名单**：难溶物（\\(\\mathrm{CaCO_3, BaSO_4, AgCl, Fe(OH)_3, Mg(OH)_2}\\)）、气体（\\(\\mathrm{CO_2, H_2}\\)）、水及**难电离弱酸/弱碱**（如醋酸 \\(\\mathrm{CH_3COOH}\\)、氨水 \\(\\mathrm{NH_3\\cdot H_2O}\\)）、单质与氧化物。","- **③ 删**：删去左右两边完全相同的旁观离子（如 \\(\\mathrm{2Na^+}\\) 和 \\(\\mathrm{2Cl^-}\\)），得 \\(\\mathrm{CO_3^{2-}(aq) + 2H^+(aq) \\to CO_2(g) + H_2O(l)}\\)。","- **④ 查**：双重核查——两边**各元素原子总数相等** AND 两边**离子所带净电荷总数相等**！"],"takeaway":"记住微溶物 \\(\\mathrm{Ca(OH)_2}\\) 的处理：**澄清石灰水**作反应物可拆为 \\(\\mathrm{Ca^{2+} + 2OH^-}\\)（如 p.99 第4(1)(3)题），石灰乳浑浊液则不拆！"},{"kind":"mechanism","title":"4.1.3 化学方程式三大配平技巧（观察法、奇数配偶法、代数法）","pageRef":"化上 p.85–86","body":["**1. 观察法（教材主推，p.85）**：从化学式较复杂的产物（或反应物）出发定为 1，再顺次推算其余物种系数。如 \\(\\mathrm{Fe + O_2 \\xrightarrow{\\Delta} Fe_3O_4}\\)，先看 \\(\\mathrm{Fe_3O_4}\\) 定出 `3Fe` 和 `2O₂`。","**2. 奇数配偶法**：某元素在式子中多次出现且呈一奇一偶（如燃烧或硫铁矿煅烧 \\(\\mathrm{FeS_2 + O_2 \\to Fe_2O_3 + SO_2}\\)），把奇数氧所在的 \\(\\mathrm{Fe_2O_3}\\) 系数先设为 `2`（偶数），随即推得 `4 FeS₂`、`8 SO₂` 及 `11 O₂`。","**3. 待定系数法（代数法，通杀复杂氧化还原/燃烧方程）**：设各系数为 \\(a, b, c, d\\dots\\)（先令某最复杂物质系数 \\(= 1\\)），按各元素原子守恒及离子电荷守恒列出线性方程组解出分数，最后同乘分母最小公倍数化为互质正整数。"],"takeaway":"最后检查：所有系数必须化为**最大公约数为 1 的最小正整数**，不可留分数或未约分的公因数。"}],"formulas":[{"title":"化学方程式的定量比例通式（微粒数 = 物质的量比）","tex":"a\\mathrm{A} + b\\mathrm{B} \\longrightarrow c\\mathrm{C} + d\\mathrm{D}\\implies N_{\\mathrm{A}}:N_{\\mathrm{B}}:N_{\\mathrm{C}}:N_{\\mathrm{D}} = n_{\\mathrm{A}}:n_{\\mathrm{B}}:n_{\\mathrm{C}}:n_{\\mathrm{D}} = a:b:c:d","plain":"N_A : N_B : N_C : N_D = n_A : n_B : n_C : n_D = a : b : c : d","conditions":"质量比则等于化学计量数乘以各自摩尔质量之比：aM(A) : bM(B) : cM(C) : dM(D)","pageRef":"化上 p.86","note":"同温同压下，参与反应的气体体积比也等于系数比。"},{"title":"离子方程式双守恒判据（原子守恒 + 电荷守恒）","tex":"\\sum_{\\text{左}} N_{i}(\\text{原子}) = \\sum_{\\text{右}} N_{i}(\\text{原子}),\\qquad \\sum_{\\text{左}} q_{j} = \\sum_{\\text{右}} q_{j}","plain":"左边各元素原子数 = 右边各元素原子数；左边净电荷总数 = 右边净电荷总数","conditions":"任何离子方程式配平完成后必须同时满足上述两式","pageRef":"化上 p.84、p.96","note":"如 Fe + Fe³⁺ → 2Fe²⁺ 原子守恒但电荷左 +3 ≠ 右 +4，必须配平为 Fe + 2Fe³⁺ → 3Fe²⁺（左 +6 = 右 +6）。"}],"pitfalls":[{"title":"忽略强酸与 \\(\\mathrm{Ba(OH)_2}\\) 反应或弱酸参与时的离子拆写禁忌","wrong":"“稀硫酸与氢氧化钡溶液反应的离子方程式可简写为 \\(\\mathrm{Ba^{2+} + SO_4^{2-} \\to BaSO_4}\\downarrow\\) 或 \\(\\mathrm{H^+ + OH^- \\to H_2O}\\)。”","diagnosis":"两者同时反应既生成难溶 \\(\\mathrm{BaSO_4}\\) 沉淀，又生成难电离的 \\(\\mathrm{2H_2O}\\)，四个离子全部参与反应，一个都不能删！（教材 p.97 第4题 C 选项）。","right":"正确离子方程式必须完整写为：\\(\\mathrm{Ba^{2+}(aq) + 2OH^-(aq) + 2H^+(aq) + SO_4^{2-}(aq) \\longrightarrow BaSO_4(s) + 2H_2O(l)}\\)。","checkRule":"看到“硫酸 + 氢氧化钡”或“碳酸钠 + 醋酸（弱酸不可拆）”，绝对不可约掉一半！"},{"title":"铁与稀酸/硫酸铜反应错写成生成 \\(\\mathrm{Fe^{3+}}\\)，或将 \\(\\mathrm{CaCO_3}\\) 拆成离子","wrong":"“铁与稀盐酸：\\(\\mathrm{2Fe + 6H^+ \\to 2Fe^{3+} + 3H_2}\\uparrow\\)；大理石与盐酸：\\(\\mathrm{CO_3^{2-} + 2H^+ \\to CO_2\\uparrow + H_2O}\\)。”","diagnosis":"这是教材 p.98 第10题 A、D 两个经典错例！铁与非氧化性酸（稀盐酸、稀硫酸）或 \\(\\mathrm{Cu^{2+}}\\) 置换只生成亚铁离子 **\\(\\mathrm{Fe^{2+}}\\)**（溶液呈浅绿色）；碳酸钙难溶于水，不可拆成 \\(\\mathrm{CO_3^{2-}}\\)。","right":"铁与稀酸：\\(\\mathrm{Fe(s) + 2H^+(aq) \\to Fe^{2+}(aq) + H_2(g)}\\)；碳酸钙与盐酸：\\(\\mathrm{CaCO_3(s) + 2H^+(aq) \\to Ca^{2+}(aq) + CO_2(g) + H_2O(l)}\\)。","checkRule":"核对三高发雷区：①难溶盐/弱酸不拆；②Fe 置换必出 \\(\\mathrm{Fe^{2+}}\\)；③净电荷必须相等。"},{"title":"为了强行凑平而篡改物质化学式下标","wrong":"“配平 \\(\\mathrm{NaOH + CO_2 \\to Na_2CO_3 + H_2O}\\) 时，写成 \\(\\mathrm{NaOH + CO_2 \\to NaCO_3 + H_2O}\\)。”","diagnosis":"碳酸钠化学式由化合价（\\(\\mathrm{Na^+}\\) 与 \\(\\mathrm{CO_3^{2-}}\\)）唯一决定为 \\(\\mathrm{Na_2CO_3}\\)，违背化学式客观真实性。","right":"只能在化学式**前面**加计量数：\\(\\mathrm{2NaOH(aq) + CO_2(g) \\to Na_2CO_3(aq) + H_2O(l)}\\)。","checkRule":"配平动“前面大数字”，绝对不动“右下角小数字”。"}],"examples":[{"label":"例 4.1.1","tier":"L2","tierLabel":"L2 校内期末","title":"教材 p.85、p.99 第4题：离子方程式“写拆删查”标准实战","prompt":"按“写、拆、删、查”四步写出下列三个反应的离子方程式：\n(1) 碳酸钠溶液与**过量醋酸（\\(\\mathrm{CH_3COOH}\\)）**溶液反应（p.85 问题解决(3)）；\n(2) 氯气通入**澄清石灰水**中反应生成氯化钙、次氯酸钙和水（p.99 第4(1)题）；\n(3) 向氯化镁溶液中加入**澄清石灰水**（p.99 第4(3)题）。","clues":"醋酸是溶于水但难电离的弱酸（不拆）；澄清石灰水中的 \\(\\mathrm{Ca(OH)_2}\\) 完全电离（拆）；\\(\\mathrm{Mg(OH)_2}\\) 是白色难溶沉淀（不拆）。","strategy":"逐一写全化学方程式，标出不拆物质，删去旁观离子并检验电荷。","given":"三组典型酸/碱/盐溶液离子反应","principle":"强电解质拆、弱电解质/难溶物/气体/水保留化学式；原子与电荷双守恒。","steps":["(1) 化学方程式：\\(\\mathrm{Na_2CO_3(aq) + 2CH_3COOH(aq) \\to 2CH_3COONa(aq) + CO_2(g) + H_2O(l)}\\)。","拆（\\(\\mathrm{Na_2CO_3}\\) 与 \\(\\mathrm{CH_3COONa}\\) 拆，弱酸 \\(\\mathrm{CH_3COOH}\\)、气体、水不拆），删去 \\(\\mathrm{2Na^+}\\) 得：","**\\(\\mathrm{CO_3^{2-}(aq) + 2CH_3COOH(aq) \\longrightarrow 2CH_3COO^-(aq) + CO_2(g) + H_2O(l)}\\)**（核查电荷：左 \\(-2\\)，右 \\(-2\\)）。","(2) 化学方程式：\\(\\mathrm{2Cl_2(g) + 2Ca(OH)_2(aq) \\to CaCl_2(aq) + Ca(ClO)_2(aq) + 2H_2O(l)}\\)。","拆去可溶物与澄清石灰水，删去 \\(\\mathrm{2Ca^{2+}}\\) 并约去公因数 2 得：","**\\(\\mathrm{Cl_2(g) + 2OH^-(aq) \\longrightarrow Cl^-(aq) + ClO^-(aq) + H_2O(l)}\\)**（核查电荷：左 \\(-2\\)，右 \\(-2\\)）。","(3) 化学方程式：\\(\\mathrm{MgCl_2(aq) + Ca(OH)_2(aq) \\to Mg(OH)_2(s) + CaCl_2(aq)}\\)。","拆并删去 \\(\\mathrm{Ca^{2+}, 2Cl^-}\\) 得：**\\(\\mathrm{Mg^{2+}(aq) + 2OH^-(aq) \\longrightarrow Mg(OH)_2(s)}\\)**（核查电荷：左 \\(+2-2=0\\)，右 \\(0\\)）。"],"answer":"(1) \\(\\mathrm{CO_3^{2-} + 2CH_3COOH \\to 2CH_3COO^- + CO_2 + H_2O}\\)；(2) \\(\\mathrm{Cl_2 + 2OH^- \\to Cl^- + ClO^- + H_2O}\\)；(3) \\(\\mathrm{Mg^{2+} + 2OH^- \\to Mg(OH)_2(s)}\\)。","markingPoints":["正确保留弱酸 CH₃COOH 不拆并配平（2分）","正确拆写澄清石灰水并约简至最简整数比（2分）","准确写出 Mg(OH)₂ 沉淀生成离子式（1分）"],"verification":"三式两边原子总数与净电荷完全相等，系数已约至互质。","pitfall":"第(1)题错把醋酸拆成 \\(\\mathrm{H^+}\\)；第(2)题忘了把 `2, 4, 2, 2, 2` 约去公因数 `2`。"},{"label":"例 4.1.2","tier":"L3","tierLabel":"L3 预试拔高","title":"待定系数（代数）法与电荷守恒配平复杂化学与离子方程式","prompt":"请用**待定系数法（代数法）**或**奇数配偶法**配平下列两道较复杂的方程式：\n(1) 工业制硫酸核心焙烧反应：\\(\\mathrm{FeS_2(s) + O_2(g) \\xrightarrow{\\text{高温}} Fe_2O_3(s) + SO_2(g)}\\)；\n(2) 酸性高锰酸钾氧化亚铁离子（离子方程式）：\\(\\mathrm{MnO_4^-(aq) + Fe^{2+}(aq) + H^+(aq) \\longrightarrow Mn^{2+}(aq) + Fe^{3+}(aq) + H_2O(l)}\\)。","clues":"第(1)题令最复杂物质 \\(\\mathrm{Fe_2O_3}\\) 系数为 1 解方程（或奇数配偶化整）；第(2)题利用原子守恒和**净电荷守恒**联立方程。","strategy":"设未知系数 → 列元素与电荷守恒线性方程组 → 通分化为最小正整数。","given":"FeS₂ 燃烧未配平式；MnO₄⁻ + Fe²⁺ 离子未配平式","principle":"元素原子守恒与离子净电荷守恒。","steps":["**第(1)题代数法**：设 \\(a\\mathrm{FeS_2} + b\\mathrm{O_2} \\to c\\mathrm{Fe_2O_3} + d\\mathrm{SO_2}\\)，令 \\(c = 1\\)：","- Fe 守恒：\\(a = 2c = 2\\)；","- S 守恒：\\(d = 2a = 4\\)；","- O 守恒：\\(2b = 3c + 2d = 3(1) + 2(4) = 11 \\implies b = \\frac{11}{2}\\)；","- 全式同乘分母 2 化为最小正整数：**\\(\\mathrm{4FeS_2(s) + 11O_2(g) \\xrightarrow{\\text{高温}} 2Fe_2O_3(s) + 8SO_2(g)}\\)**。","**第(2)题离子方程式代数+电荷守恒**：设 \\(a\\mathrm{MnO_4^-} + b\\mathrm{Fe^{2+}} + c\\mathrm{H^+} \\to d\\mathrm{Mn^{2+}} + e\\mathrm{Fe^{3+}} + f\\mathrm{H_2O}\\)，令 \\(a = 1\\)：","- Mn 守恒得 \\(d = 1\\)；O 守恒得 \\(f = 4a = 4\\)；H 守恒得 \\(c = 2f = 8\\)；Fe 守恒得 \\(e = b\\)。","- 代入**电荷守恒**：左总电荷 \\(= (-1)\\times 1 + (+2)b + (+1)\\times 8 = 7 + 2b\\)；右总电荷 \\(= (+2)\\times 1 + (+3)b = 2 + 3b\\)。","- 令左右电荷相等：\\(7 + 2b = 2 + 3b \\implies b = 5\\)，故 \\(e = 5\\)。","- 最终配平式：**\\(\\mathrm{MnO_4^-(aq) + 5Fe^{2+}(aq) + 8H^+(aq) \\longrightarrow Mn^{2+}(aq) + 5Fe^{3+}(aq) + 4H_2O(l)}\\)**。"],"answer":"(1) \\(\\mathrm{4FeS_2 + 11O_2 \\xrightarrow{\\text{高温}} 2Fe_2O_3 + 8SO_2}\\)；(2) \\(\\mathrm{MnO_4^- + 5Fe^{2+} + 8H^+ \\to Mn^{2+} + 5Fe^{3+} + 4H_2O}\\)。","markingPoints":["第(1)题正确解出分数 11/2 并通分化整得 4, 11, 2, 8（2分）","第(2)题正确运用原子守恒与电荷守恒解出系数 1, 5, 8, 1, 5, 4（3分）"],"verification":"验证(2)：原子 Mn:1, O:4, H:8, Fe:5 全等；电荷左 -1+10+8 = +17，右 +2+15 = +17。","pitfall":"第(2)题只看 Mn、O、H 原子守恒会误以为 \\(b = e = 1\\) 任意取值即可，忘记核对电荷守恒导致错误。"}],"practice":[{"id":"chem4-4.1-q1","tier":"L1","tierLabel":"L1 基础","examStyle":"P1 选择","q":"下列化学反应中，**不属于**化合、分解、置换、复分解四种基本反应类型中的任何一种的是（　）。","options":["A. \\(\\mathrm{CaCO_3(s) \\xrightarrow{\\Delta} CaO(s) + CO_2(g)}\\)","B. \\(\\mathrm{Fe(s) + CuSO_4(aq) \\longrightarrow FeSO_4(aq) + Cu(s)}\\)","C. \\(\\mathrm{CO_2(g) + 2NaOH(aq) \\longrightarrow Na_2CO_3(aq) + H_2O(l)}\\)","D. \\(\\mathrm{BaCl_2(aq) + H_2SO_4(aq) \\longrightarrow BaSO_4(s) + 2HCl(aq)}\\)"],"correctOption":"C","given":"四种基本反应类型边界（化上 p.81–83）","method":"逐项套用四种基本反应类型定义","principle":"酸性氧化物与碱反应（或 CO 还原金属氧化物）不属于四大基本类型。","steps":["A 一变多（分解）；B 单质+化合物→新单质+新化合物（置换）；D 两化合物互相交换成分得沉淀（复分解）。","C 中两种化合物反应并未互相交换正负离子团，不属复分解亦不属其他三类（教材 p.83 原例）。"],"ans":"C","markingPoints":["识别非四大基本反应类型特例"],"verification":"化上 p.83 原文例式。","pitfall":"看见两个化合物变成另外两个化合物就误选 C 为复分解。"},{"id":"chem4-4.1-q2","tier":"L2","tierLabel":"L2 期末","examStyle":"P1 选择","q":"下列化学反应中，**不能**用离子方程式 \\(\\mathrm{Ba^{2+}(aq) + SO_4^{2-}(aq) \\longrightarrow BaSO_4(s)}\\) 来表示的是（　）。","options":["A. 稀硫酸与硝酸钡溶液反应","B. 硫酸钾溶液与氯化钡溶液反应","C. 稀硫酸与氢氧化钡溶液反应","D. 硫酸钠溶液与硝酸钡溶液反应"],"correctOption":"C","given":"教材 p.97 选择题第4题原题","method":"写出各反应除 BaSO₄ 外的另一产物，看是否拆为旁观离子","principle":"生成水（难电离物）时 H⁺ 和 OH⁻ 不可删去。","steps":["A 另一产物 HNO₃ 可拆删；B 另一产物 KCl 可拆删；D 另一产物 NaNO₃ 可拆删。","C 反应为 \\(\\mathrm{H_2SO_4 + Ba(OH)_2 \\to BaSO_4\\downarrow + 2H_2O}\\)，生成的 \\(\\mathrm{H_2O}\\) 不能拆，故完整离子方程式必包含 \\(\\mathrm{2H^+ + 2OH^- \\to 2H_2O}\\)。"],"ans":"C","markingPoints":["识破强酸强碱生成水不能被删去的隐含条件"],"verification":"教材 p.97 第4题。","pitfall":"误以为只要生成硫酸钡沉淀就都能写成该离子方程式。"},{"id":"chem4-4.1-q3","tier":"L2","tierLabel":"L2 期末","examStyle":"P1 选择","q":"下列离子方程式的书写完全正确的是（　）。","options":["A. 碳酸钙和盐酸反应：\\(\\mathrm{CO_3^{2-}(aq) + 2H^+(aq) \\longrightarrow H_2O(l) + CO_2(g)}\\)","B. 金属钠与水反应：\\(\\mathrm{Na(s) + H_2O(l) \\longrightarrow Na^+(aq) + OH^-(aq) + H_2(g)}\\)","C. 向硝酸银溶液中加稀盐酸：\\(\\mathrm{Ag^+(aq) + Cl^-(aq) \\longrightarrow AgCl(s)}\\)","D. 向稀盐酸中加铁粉：\\(\\mathrm{2Fe(s) + 6H^+(aq) \\longrightarrow 2Fe^{3+}(aq) + 3H_2(g)}\\)"],"correctOption":"C","given":"教材 p.98 选择题第10题原题","method":"依次核对“不拆原则、质量/电荷守恒、客观产物价态”","principle":"写拆删查四步判据。","steps":["A 错：碳酸钙难溶于水，必须写化学式 \\(\\mathrm{CaCO_3(s)}\\)，不可拆成 \\(\\mathrm{CO_3^{2-}}\\)。","B 错：氢原子与电荷均未配平（左边 2 H、右边 3 H；应为 \\(\\mathrm{2Na + 2H_2O \\to 2Na^+ + 2OH^- + H_2}\\)）。","C 正确：\\(\\mathrm{AgNO_3}\\) 与 \\(\\mathrm{HCl}\\) 均全电离，\\(\\mathrm{AgCl}\\) 难溶不拆，原子与电荷均守恒。","D 错：铁与稀盐酸反应只生成浅绿色亚铁离子 \\(\\mathrm{Fe^{2+}}\\)，而非 \\(\\mathrm{Fe^{3+}}\\)。"],"ans":"C","markingPoints":["排除不拆错、未配平及产物价态错误"],"verification":"教材 p.98 第10题。","pitfall":"最易漏检 B 选项中 H 原子数左边 2 个、右边 3 个的不配平。"},{"id":"chem4-4.1-q4","tier":"L3","tierLabel":"L3 预试","examStyle":"P2 书写与配平","q":"完成并配平下列反应的化学方程式，并按要求作答：\n(1) 铝热焊接钢轨：铝粉与氧化铁（III）在高温下反应生成氧化铝和铁（注明**基本反应类型**）；\n(2) 碳酸氢铵（\\(\\mathrm{NH_4HCO_3}\\)）受热分解生成氨气、水和二氧化碳（注明**基本反应类型**）；\n(3) 胃药氢氧化铝（\\(\\mathrm{Al(OH)_3}\\)）中和过量胃酸（稀盐酸），写出**化学方程式**及**离子方程式**。","given":"教材 p.98 第1题改编","method":"写准化学式 → 观察法配平 → 判断类型 → 遵循写拆删查写离子式","principle":"四大反应类型判据与难溶碱 \\(\\mathrm{Al(OH)_3}\\) 不拆原则。","steps":["(1) \\(\\mathrm{2Al(s) + Fe_2O_3(s)} \\xrightarrow{\\text{高温}} \\mathrm{Al_2O_3(s) + 2Fe(s)}\\)，属于**置换反应**。","(2) \\(\\mathrm{NH_4HCO_3(s)} \\xrightarrow{\\Delta} \\mathrm{NH_3(g) + H_2O(g) + CO_2(g)}\\)，属于**分解反应**。","(3) 化学方程式：\\(\\mathrm{Al(OH)_3(s) + 3HCl(aq) \\longrightarrow AlCl_3(aq) + 3H_2O(l)}\\)；因 \\(\\mathrm{Al(OH)_3}\\) 难溶于水不可拆，删去 \\(\\mathrm{3Cl^-}\\) 得离子方程式：\\(\\mathrm{Al(OH)_3(s) + 3H^+(aq) \\longrightarrow Al^{3+}(aq) + 3H_2O(l)}\\)。"],"ans":"(1) \\(\\mathrm{2Al+Fe_2O_3 \\xrightarrow{\\text{高温}} Al_2O_3+2Fe}\\)（置换）；(2) \\(\\mathrm{NH_4HCO_3 \\xrightarrow{\\Delta} NH_3+H_2O+CO_2}\\)（分解）；(3) \\(\\mathrm{Al(OH)_3+3H^+ \\to Al^{3+}+3H_2O}\\)。","markingPoints":["第(1)(2)题化学方程式、条件及反应类型全对（4分）","第(3)题正确保留 Al(OH)₃ 不拆并写出配平离子方程式（2分）"],"verification":"均满足原子与电荷守恒。","pitfall":"第(3)题写出离子方程式时误把难溶碱 \\(\\mathrm{Al(OH)_3}\\) 拆成 \\(\\mathrm{OH^-}\\)。"},{"id":"chem4-4.1-q5","tier":"L4","tierLabel":"L4 统考压轴","examStyle":"P2 代数与电荷配平","q":"在化学工业与实验室中经常遇到较复杂的氧化还原或有机燃烧反应，试结合**待定系数法（代数法）**与**电荷守恒**完成下列两题：\n(1) 铜与稀硝酸反应的未配平离子式为：\\(a\\mathrm{Cu(s)} + b\\mathrm{H^+(aq)} + c\\mathrm{NO_3^-(aq)} \\longrightarrow d\\mathrm{Cu^{2+}(aq)} + e\\mathrm{NO(g)} + f\\mathrm{H_2O(l)}\\)。请通过列写原子守恒与电荷守恒方程，求出最小正整数系数 \\(a, b, c, d, e, f\\)。\n(2) 写出通式为 \\(\\mathrm{C}_n\\mathrm{H}_{2n+2}\\) 的烷烃在足量氧气中完全燃烧生成 \\(\\mathrm{CO_2(g)}\\) 和 \\(\\mathrm{H_2O(l)}\\) 的配平化学方程式（系数用 \\(n\\) 表示，允许 \\(\\mathrm{O_2}\\) 为半整数或整式倍）。","given":"铜与稀硝酸离子反应；烷烃完全燃烧通式","method":"设 Cu 系数为 1，联立 Cu、N、H、O 原子守恒与总电荷守恒解出系数","principle":"线性守恒方程组唯一确定最小整数化学计量数。","steps":["第(1)问：令 \\(a = 1\\)（由 Cu 守恒得 \\(d = 1\\)）：","- N 守恒：\\(e = c\\)；","- H 守恒：\\(b = 2f\\)；","- O 守恒：\\(3c = e + f \\implies 3c = c + f \\implies f = 2c\\)，代回 H 守恒得 \\(b = 4c\\)；","- 电荷守恒：左边总电荷 \\(= b - c = 4c - c = 3c\\)；右边总电荷 \\(= 2d = 2\\)。故 \\(3c = 2 \\implies c = \\frac{2}{3}\\)，进而 \\(e = \\frac{2}{3},\\ f = \\frac{4}{3},\\ b = \\frac{8}{3}\\)。","- 全部系数同乘 3 化为最小正整数：**\\(a=3, b=8, c=2, d=3, e=2, f=4\\)**，即 \\(\\mathrm{3Cu + 8H^+ + 2NO_3^- \\longrightarrow 3Cu^{2+} + 2NO(g) + 4H_2O(l)}\\)。","第(2)问：令 \\(\\mathrm{C}_n\\mathrm{H}_{2n+2}\\) 系数为 1，由 C 守恒得 \\(n\\mathrm{CO_2}\\)，由 H 守恒得 \\((n+1)\\mathrm{H_2O}\\)；右边 O 原子总数 \\(= 2n + (n+1) = 3n+1\\)，故需 \\(\\frac{3n+1}{2}\\mathrm{O_2}\\)：","整数化形式：\\(\\mathrm{2C}_n\\mathrm{H}_{2n+2} + (3n+1)\\mathrm{O_2} \\xrightarrow{\\text{点燃}} 2n\\,\\mathrm{CO_2} + (2n+2)\\mathrm{H_2O}\\)。"],"ans":"(1) 3, 8, 2, 3, 2, 4；(2) \\(\\mathrm{2C}_n\\mathrm{H}_{2n+2} + (3n+1)\\mathrm{O_2} \\xrightarrow{\\text{点燃}} 2n\\,\\mathrm{CO_2} + (2n+2)\\mathrm{H_2O}\\)。","markingPoints":["正确联立原子与电荷方程求得分数 2/3 并化整得 3, 8, 2, 3, 2, 4（3分）","正确写出含 n 的烷烃燃烧配平通式（2分）"],"verification":"验证(1)：Cu=3, H=8, N=2, O=6；电荷左 +8-2 = +6，右 3×(+2) = +6。验证(2)：C=2n, H=4n+4, O=6n+2，完全守恒。","pitfall":"第(1)问忘记列电荷守恒方程，导致解少一个自由度无法唯一确定。"}],"cheatSheet":["化学方程式两大原则：**客观事实**（不编造假物质）+ **物质不灭**（不动化学式右下角下标）。","四大类型外有特例：\\(\\mathrm{CO_2 + 2NaOH \\to Na_2CO_3 + H_2O}\\) 与炼铁 \\(\\mathrm{Fe_2O_3 + 3CO \\to 2Fe + 3CO_2}\\) 均**不属于**四大基本类型。","离子方程式“**写、拆、删、查**”：只拆可溶强酸/强碱/可溶盐；难溶物、弱酸（\\(\\mathrm{CH_3COOH}\\)）、水、气体、单质氧化物一律不拆；必查**原子+电荷**双守恒。","复杂方程配平：先令最复杂物质为 1，按元素+电荷守恒解线性方程再通分化整（如 \\(\\mathrm{4FeS_2 + 11O_2 \\to 2Fe_2O_3 + 8SO_2}\\)）。"],"kbEntryIds":["kb-chem4-equation-rules","kb-chem4-reaction-types","kb-chem4-ionic-equation","kb-chem4-balancing"],"quiz":{"q":"请写出稀硫酸（\\(\\mathrm{H_2SO_4}\\)）与氢氧化钡（\\(\\mathrm{Ba(OH)_2}\\)）溶液发生中和沉淀反应的**离子方程式**，并说明为什么不能简化为 \\(\\mathrm{Ba^{2+} + SO_4^{2-} \\to BaSO_4}\\)。","given":"教材 p.97 第4题 C 选项","method":"按“写、拆、删、查”四步检查是否有旁观离子可删","principle":"同时生成难溶沉淀 BaSO₄ 和难电离物质 H₂O，四种离子全参与反应。","steps":["写并拆：\\(\\mathrm{2H^+ + SO_4^{2-} + Ba^{2+} + 2OH^- \\to BaSO_4(s) + 2H_2O(l)}\\)。","左右两侧没有任何相同的可删旁观离子，故四类离子全部保留。"],"ans":"\\(\\mathrm{Ba^{2+}(aq) + 2OH^-(aq) + 2H^+(aq) + SO_4^{2-}(aq) \\longrightarrow BaSO_4(s) + 2H_2O(l)}\\)"}},{"id":"4.2","t":"根据化学方程式的计算","anchor":{"pages":"化上 p.87–95","syllabus":"4.2.1 计算反应物和生成物的量 · 4.2.2 不纯物计算 · 4.2.3 限量反应物 · 4.2.4 产率计算","examScopes":["sem1_final","pre_exam","sem2_final","uec"],"examWeight":"高三上期末及 UEC 统考卷二必答压轴核心（占分极高，考纯度+限量+产率+连续反应）","terms":"stoichiometry · purity · limiting reactant · excess reactant · theoretical yield · actual yield · percentage yield","prerequisites":["第3章物质的量 n = m/M = N/NA（3.6）与相对分子质量 Mr 计算（3.4）","第4.1节化学方程式书写与严格配平"],"goals":["规范执行以物质的量（mol）为中心的三步化学计量步骤，灵活处理质量、气体体积与溶液质量分数转换。","熟练应用“代纯不代杂”原则完成含杂质矿石原料与不纯产品的正逆纯度计算。","掌握双投料下的限量反应物判定（n/系数较小组）及过量剩余量计算，并能解读限量—过量折线拐点图像。","掌握理论产量、实际产量与产率公式，运用关系式法求解连续多步反应耦合纯度与产率的工业综合计算题。"]},"concepts":[{"kind":"law","title":"4.2.1 化学计算三步规范与全通道物质的量桥梁","pageRef":"化上 p.87–89","body":["**教材三步格式（例3–6，p.87–89）**：①**设**所求的量为 \\(x\\)（注意单位写明是 `mol` 还是 `g`）；②**写**出配平的化学方程式，并在有关物质的化学式正下方对齐标出已知量和未知量（保持“**上下单位一致，左右计量对应**”）；③**列**正比例式求解，最后写出完整答句。","**例5 经典模型（p.88–89）**：制取 \\(30\\text{ g}\\ \\mathrm{O_2}\\) 至少需要分解多少 \\(\\mathrm{KClO_3}\\)？先转成物质的量 \\(n(\\mathrm{O_2}) = \\frac{30}{32}\\text{ mol}\\)，由 \\(2\\mathrm{KClO_3} \\to 3\\mathrm{O_2}\\) 得 \\(n(\\mathrm{KClO_3}) = 0.625\\text{ mol}\\)，再乘以 \\(M=122.5\\text{ g\\,mol}^{-1}\\) 得 **\\(76.6\\text{ g}\\)**。","**高阶拓展——连续多步反应“关系式法”**：若上一步的生成物全部进入下一步反应（中间体无损失），切勿每步四舍五入，应直接利用原子守恒建立**始态 ~ 终态关系式**（如工业制硫酸 \\(\\mathrm{FeS_2} \\sim 2\\mathrm{SO_2} \\sim 2\\mathrm{SO_3} \\sim 2\\mathrm{H_2SO_4}\\)，硫原子守恒一步直达）。"],"takeaway":"物质的量 \\(n\\) 是连接“质量 \\(m\\)、粒子数 \\(N\\)、气体体积 \\(V\\)、溶液溶质”的唯一通用中转站；连续反应优先找**关键元素守恒关系式**。"},{"kind":"formula","title":"4.2.2 关于不纯物的计算（代纯不代杂原则）","pageRef":"化上 p.90–91、p.95","body":["**核心铁律**：化学方程式表达的是**纯净物**之间的定量关系，矿石、粗金属、废料或溶液中的**不纯物（杂质）质量绝对不能直接代入方程式**！","**两类考法（教材例7 & 例8）**：","- **类型一（已知不纯原料求产物，或已知不纯产品求原料，例7 p.90）**：生产 \\(1000\\text{ t}\\) 含 \\(95\\%\\) 铁的生铁，需含 \\(60\\%\\ \\mathrm{Fe_2O_3}\\) 的赤铁矿多少吨？设需矿石 \\(x\\text{ t}\\)，则纯 \\(\\mathrm{Fe_2O_3} = (x\\times 60\\%)\\text{ t}\\)，纯 \\(\\mathrm{Fe} = (1000\\times 95\\%)\\text{ t}\\)，由 \\(160 : (x\\times 60\\%) = 112 : 950\\) 解得 **\\(x = 2262\\text{ t}\\)**。","- **类型二（由纯产物反推样品纯度，例8 p.90–91）**：含杂质的 \\(\\mathrm{CuO}\\) 样品 \\(12\\text{ g}\\) 被 \\(\\mathrm{H_2}\\) 还原得 \\(8\\text{ g}\\ \\mathrm{Cu}\\) → 算出纯 \\(\\mathrm{CuO} = 10\\text{ g}\\) → 样品质量百分比 \\(= \\frac{10\\text{ g}}{12\\text{ g}}\\times 100\\% = 83.33\\%\\)。"],"takeaway":"警惕“杂质也留在最终固体中”的情形（如 p.95 思考题 4b(2) 石灰石煅烧留下的生石灰总质量 = 生成的纯 \\(\\mathrm{CaO}\\) + 未分解的杂质）！"},{"kind":"mechanism","title":"4.2.3 利用限量反应物的计算（双投料必先比大小）","pageRef":"化上 p.91–93","body":["**定义**：在反应中**完全消耗掉**的反应物称为**限量反应物**（limiting reactant，决定生成物最大量）；未完全消耗而**有剩余**的称为**过量反应物**（excess reactant）。","**判定黄金公式**：给定 \\(a\\mathrm{A} + b\\mathrm{B} \\to c\\mathrm{C}\\) 中两反应物的物质的量 \\(n(\\mathrm{A})\\) 与 \\(n(\\mathrm{B})\\)，分别计算各自折算份数 **\\(\\frac{n(\\mathrm{A})}{a}\\)** 与 **\\(\\frac{n(\\mathrm{B})}{b}\\)**：","- 若 \\(\\frac{n(\\mathrm{A})}{a} < \\frac{n(\\mathrm{B})}{b}\\)，则 **A 为限量反应物**，B 过量；产物一律按 \\(n(\\mathrm{A})\\) 计算，剩余 B 的量为 \\(n_0(\\mathrm{B}) - \\frac{b}{a}n(\\mathrm{A})\\)。","- **教材例9 与例10 提示（p.92–93）**：\\(0.6\\text{ mol NaOH} + 0.2\\text{ mol }\\mathrm{H_2SO_4}\\) 中 \\(\\frac{0.6}{2}=0.3 > \\frac{0.2}{1}=0.2\\)，故 \\(\\mathrm{H_2SO_4}\\) 限量、\\(\\mathrm{NaOH}\\) 过量剩余 \\(0.2\\text{ mol}\\)，溶液呈碱性使石蕊变蓝；\\(12\\text{ g }\\mathrm{CuSO_4}\\)（\\(0.075\\text{ mol}\\)）与 \\(2.8\\text{ g Fe}\\)（\\(0.050\\text{ mol}\\)）反应，\\(\\mathrm{Fe}\\) 限量，仅消耗 \\(8\\text{ g }\\mathrm{CuSO_4}\\)，生成 \\(0.05\\text{ mol }\\mathrm{FeSO_4}\\)。"],"takeaway":"千万不要比较原始质量 \\(m\\) 或原始摩尔数 \\(n\\) 的大小，必须除以各自的**化学计量数**后再比较！"},{"kind":"formula","title":"4.2.4 产率（Percentage Yield）计算与顺逆校正规则","pageRef":"化上 p.93–94、p.99","body":["**定义与原因**：根据化学方程式算出的最大可能生成物量称为**理论产量**（theoretical yield）；实验或工业生产中真正收集到的量称为**实际产量**（actual yield）。由于反应不完全、存在副反应或输送漏失，实际产量通常少于理论产量。","**顺乘逆除原则（p.94 例11）**：用 \\(4\\text{ t}\\) 含 \\(96\\%\\ \\mathrm{CaCO_3}\\) 的石灰石理论上可得 \\(\\mathrm{CaO} = 4\\times 96\\% \\times \\frac{56}{100} = 2.15\\text{ t}\\)；实际每 \\(2\\text{ t}\\) 石灰石产 \\(1\\text{ t}\\)（即 \\(4\\text{ t}\\) 实产 \\(2\\text{ t}\\)），故产率 \\(= \\frac{2\\text{ t}}{2.15\\text{ t}}\\times 100\\% = 93\\%\\)。"],"takeaway":"**顺向算实际产物：× 产率**（结果变小）；**逆向反推所需原料：÷ 产率 ÷ 纯度**（原料必须多投，结果变大）。"}],"diagrams":[{"src":"assets/fig/v2/chem04-stoich-flow.svg","caption":"图 4-1 化学方程式计量全通道转换与纯度/产率校正图（化上 4.2 p.87–95）","alt":"物质的量中心桥梁：质量、气体体积、溶液、微粒数与纯度产率校正流程图","pageRef":"化上 p.87–95"},{"src":"assets/fig/v2/chem04-limiting-graph.svg","caption":"图 4-2 限量反应物与产物质量随投料量变化的折线特征与拐点解析（化上 p.39、p.91–93）","alt":"限量反应物与过量反应物折线拐点图","pageRef":"化上 p.91–93"}],"formulas":[{"title":"化学计量核心桥梁与不纯物纯度公式","tex":"\\frac{n(\\mathrm{A})}{a} = \\frac{n(\\mathrm{B})}{b} = \\frac{n(\\mathrm{C})}{c},\\qquad m_{\\text{纯}} = m_{\\text{样品}}\\times w_{\\text{纯度}},\\qquad w_{\\text{纯度}} = \\frac{m_{\\text{纯净物}}}{m_{\\text{不纯样品}}}\\times 100\\%","plain":"n(A)/a = n(B)/b = n(C)/c；m_纯 = m_样品 × 纯度","conditions":"只有纯净物的质量或物质的量才允许代入化学方程式比例式","pageRef":"化上 p.87–90","note":"对多步连续反应，直接令 n(始)/a_始 = n(终)/c_终 需依据守恒原子数校正系数。"},{"title":"限量判断法则与产率公式","tex":"\\text{若 }\\frac{n(\\mathrm{A})}{a} < \\frac{n(\\mathrm{B})}{b} \\implies \\mathrm{A}\\text{ 限量},\\qquad \\text{产率} = \\frac{\\text{实际产量}}{\\text{理论产量}} \\times 100\\%","plain":"比较 n(A)/a 与 n(B)/b，较小者限量；产率 = (实际产量 / 理论产量) × 100%","conditions":"分子与分母的物理量单位必须统一（同为 g、t 或同为 mol）","pageRef":"化上 p.91–94","note":"理论产量必须根据限量反应物结合纯度算出。"}],"pitfalls":[{"title":"把含杂质样品总质量直接代入方程式，或用错“杂质百分比”与“纯度”","wrong":"“煅烧 \\(50\\text{ t}\\) 含 \\(6\\%\\) 杂质的石灰石，纯碳酸钙是 \\(50\\times 6\\% = 3\\text{ t}\\)。”","diagnosis":"审题看反了“杂质占比”与“有效成分纯度”（教材 p.95 思考题 4b(2) 原题坑）。","right":"含杂质 \\(6\\%\\) 意味着纯度为 \\(1 - 6\\% = 94\\%\\)，纯 \\(\\mathrm{CaCO_3}\\) 质量应为 \\(50\\times 94\\% = 47\\text{ t}\\)！","checkRule":"遇到百分比先用笔圈出后面跟着的是“有效成分名称”还是“杂质”二字。"},{"title":"限量判定只比较质量或摩尔数本身，漏除化学计量数","wrong":"“\\(0.04\\text{ mol }\\mathrm{FeCl_3}\\) 与 \\(0.06\\text{ mol NaOH}\\) 反应（p.93 问题解决第2题），因为 \\(0.04 < 0.06\\)，所以 \\(\\mathrm{FeCl_3}\\) 限量！”","diagnosis":"方程式为 \\(\\mathrm{FeCl_3 + 3NaOH \\to Fe(OH)_3\\downarrow + 3NaCl}\\)，\\(1\\text{ mol }\\mathrm{FeCl_3}\\) 需消耗 \\(3\\text{ mol NaOH}\\)。","right":"比较份数：\\(\\frac{0.04}{1} = 0.04 > \\frac{0.06}{3} = 0.02\\)，因此 **\\(\\mathrm{NaOH}\\) 才是限量反应物**，仅生成 **\\(0.02\\text{ mol }\\mathrm{Fe(OH)_3}\\)**，\\(\\mathrm{FeCl_3}\\) 过量剩余 \\(0.02\\text{ mol}\\)！","checkRule":"双投料必先列分式 `n(物质) ÷ 方程式系数`，比值小的才限量。"},{"title":"把“原料纯度”和“反应产率”混为一谈或倒除为乘","wrong":"“已知生产了 \\(1100\\text{ t}\\) 铁，产率 \\(90\\%\\)，求所需理论铁矿时把 \\(1100\\) 乘以 \\(90\\%\\)。”","diagnosis":"实际产量是已经打折（小于理论产量）的量，反推所需原料应当还原放大。","right":"已知**实际产量**求所需原料：必须先用 `理论产量 = 实际产量 ÷ 产率`，再除以原料纯度。","checkRule":"常识验算：反推出来的原料需要量一定要**大于**无损耗纯理论需要量！"}],"examples":[{"label":"例 4.2.1","tier":"L3","tierLabel":"L3 预试必答","title":"教材 p.95 思考题 4b(2)：含杂质石灰石煅烧与生石灰产品纯度追踪","prompt":"煅烧石灰石制取生石灰的反应为：\\(\\mathrm{CaCO_3(s)} \\xrightarrow{\\Delta} \\mathrm{CaO(s) + CO_2(g)}\\)。现煅烧 \\(50\\text{ t}\\) 含 **\\(6\\%\\) 杂质**（假设杂质不分解、不反应）的石灰石（已知 \\(M(\\mathrm{CaCO_3})=100\\text{ g/mol}, M(\\mathrm{CaO})=56\\text{ g/mol}\\)）：\n(1) 理论上可制得纯净氧化钙（\\(\\mathrm{CaO}\\)）多少吨？\n(2) 若杂质全部留在生成的生石灰固体中，则所得生石灰产品的总质量与纯度各是多少？","clues":"含 6% 杂质 → 纯度为 94%；杂质 3 t 全程留在最终生石灰固体中作为分母一部分！","strategy":"先折纯算出纯 CaCO₃，按方程式求纯 CaO 质量，最后将纯 CaO 与原杂质质量相加作总质量求纯度。","given":"m(石灰石) = 50 t，杂质占比 = 6%，M(CaCO₃)=100，M(CaO)=56","principle":"化学方程式仅计算纯净物转化；固体杂质在反应前后质量不变。","steps":["第(1)问：石灰石中纯 \\(\\mathrm{CaCO_3}\\) 的质量为：\\(m(\\mathrm{CaCO_3}) = 50\\text{ t}\\times (1 - 6\\%) = 47.0\\text{ t}\\)，未反应杂质质量 \\(= 50\\text{ t} - 47.0\\text{ t} = 3.0\\text{ t}\\)。","由方程式 \\(\\mathrm{CaCO_3 \\xrightarrow{\\Delta} CaO + CO_2}\\uparrow\\) 得比例：\\(100 : 47.0\\text{ t} = 56 : m(\\mathrm{CaO})\\)，解得制得纯净氧化钙：**\\(m(\\mathrm{CaO}) = \\frac{47.0 \\times 56}{100} = 26.32\\text{ t}\\)**。","第(2)问：反应后留在窑内的生石灰固体总质量 \\(= m(\\mathrm{CaO}) + m_{\\text{杂质}} = 26.32\\text{ t} + 3.0\\text{ t} = 29.32\\text{ t}\\)。","故所得生石灰产品的纯度为：\\(w(\\mathrm{CaO}) = \\frac{26.32\\text{ t}}{29.32\\text{ t}} \\times 100\\% = 89.77\\%\\)。"],"answer":"(1) 可制得纯 CaO 26.32 t；(2) 生石灰总质量 29.32 t，纯度 89.77%。","markingPoints":["正确算出纯 CaCO₃ = 47.0 t 与杂质 3.0 t（1分）","代入方程式求得纯 CaO = 26.32 t（2分）","将杂质加回生石灰总质量 29.32 t 并求得纯度 89.77%（2分）"],"verification":"物质不灭校核：逸出 \\(\\mathrm{CO_2} = 47.0\\times 44/100 = 20.68\\text{ t}\\)，剩余固体 \\(= 50 - 20.68 = 29.32\\text{ t}\\)，严丝合缝。","pitfall":"第(2)问误以为杂质质量还是占 6%，或者忘了把 3.0 t 杂质加回分母。"},{"label":"例 4.2.2","tier":"L4","tierLabel":"L4 统考压轴","title":"限量反应物 + 过量计算 + 连续还原 + 产率综合计算","prompt":"某实验小组将 \\(7.80\\text{ g}\\) 锌粒投入含有 \\(7.30\\text{ g}\\) 纯 \\(\\mathrm{HCl}\\) 的稀盐酸中充分反应：\\(\\mathrm{Zn(s) + 2HCl(aq) \\longrightarrow ZnCl_2(aq) + H_2(g)}\\)。随后将产生的全部氢气干燥后通入装有足量加热氧化铜（II）的玻璃管中还原（假设 \\(\\mathrm{H_2}\\) 完全通入反应管）：\\(\\mathrm{CuO(s) + H_2(g)} \\xrightarrow{\\Delta} \\mathrm{Cu(s) + H_2O(g)}\\)，实验结束冷却称量，实际收集到红色铜粉 \\(4.48\\text{ g}\\)（已知 \\(A_r(\\mathrm{Zn})=65, A_r(\\mathrm{H})=1, A_r(\\mathrm{Cl})=35.5, A_r(\\mathrm{Cu})=64\\)）。\n试求：(1) 第一步反应中哪一种反应物是限量反应物？另一种过量反应物剩余多少克？\n(2) 理论上共可还原得到多少克铜？\n(3) 本次还原实验铜的实际产率是多少？","clues":"第一步同时给出 Zn 与 HCl 投料，务必先算 \\(n/\\text{系数}\\)；第二步用第一步生成的 \\(n(\\mathrm{H_2})\\) 算铜理论产量。","strategy":"双投料比份额定限量 → 算剩余质量 → 串联第二步算理论 m(Cu) → 算产率。","given":"m(Zn)=7.80 g, m(HCl)=7.30 g, m_实(Cu)=4.48 g","principle":"限量判定原则、连续化学计量关系与产率公式。","steps":["第(1)问：分别计算两反应物初始物质的量：","- \\(n(\\mathrm{Zn}) = \\frac{7.80\\text{ g}}{65\\text{ g/mol}} = 0.120\\text{ mol}\\)，份数 \\(\\frac{0.120}{1} = 0.120\\)；","- \\(n(\\mathrm{HCl}) = \\frac{7.30\\text{ g}}{36.5\\text{ g/mol}} = 0.200\\text{ mol}\\)，份数 \\(\\frac{0.200}{2} = 0.100\\)。","因为 \\(0.100 < 0.120\\)，所以 **\\(\\mathrm{HCl}\\) 是限量反应物**，锌粒过量。实际消耗锌 \\(0.100\\text{ mol}\\)，剩余锌的物质的量 \\(= 0.120 - 0.100 = 0.020\\text{ mol}\\)，剩余质量 \\(= 0.020\\times 65 = 1.30\\text{ g}\\)。","第(2)问：由限量 \\(\\mathrm{HCl}\\) 求得生成氢气 \\(n(\\mathrm{H_2}) = \\frac{1}{2}n(\\mathrm{HCl}) = 0.100\\text{ mol}\\)；通入第二步还原反应 \\(\\mathrm{CuO + H_2 \\xrightarrow{\\Delta} Cu + H_2O}\\)，理论可得铜 \\(n_{\\text{理}}(\\mathrm{Cu}) = 0.100\\text{ mol}\\)，故理论产量 \\(m_{\\text{理}}(\\mathrm{Cu}) = 0.100 \\times 64 = 6.40\\text{ g}\\)。","第(3)问：铜的实际产率为 \\(\\frac{4.48\\text{ g}}{6.40\\text{ g}} \\times 100\\% = 70.0\\%\\)。"],"answer":"(1) HCl 限量，剩余 Zn 1.30 g；(2) 理论可得 6.40 g Cu；(3) 产率 70.0%。","markingPoints":["正确通过 n/系数 判定 HCl 限量并算出剩余 Zn 1.30 g（2分）","两步串联求得理论 Cu = 6.40 g（2分）","正确代公式求得产率 70.0%（1分）"],"verification":"产率 70.0% 合乎 H₂ 还原实验因“先通 H₂ 排空气、后通 H₂ 冷却”导致部分气体未参与还原的真实情况。","pitfall":"若第一步忘记判限量而误用 0.120 mol Zn 去算氢气，后续理论产量与产率将连环全错。"}],"practice":[{"id":"chem4-4.2-q1","tier":"L1","tierLabel":"L1 基础","examStyle":"P1 选择","q":"将 \\(8\\text{ g}\\) 纯铜粉在充足空气中持续加热充分氧化成氧化铜（II），最多能生成氧化铜（II）的质量是（已知 \\(A_r(\\mathrm{Cu})=64, A_r(\\mathrm{O})=16\\)）（　）。","options":["A. 10 g","B. 16 g","C. 18 g","D. 80 g"],"correctOption":"A","given":"教材 p.98 选择题第7题原题","method":"由 2Cu + O₂ —Δ→ 2CuO，按 64 : 80 质量比直接求算","principle":"铜原子守恒（1 mol Cu → 1 mol CuO）。","steps":["\\(n(\\mathrm{Cu}) = \\frac{8}{64} = 0.125\\text{ mol}\\)，故最多生成 \\(0.125\\text{ mol CuO}\\)，质量 \\(= 0.125 \\times (64+16) = 10\\text{ g}\\)。"],"ans":"A","markingPoints":["由摩尔比 1:1 算出 10 g"],"verification":"教材 p.98 第7题。","pitfall":"错用“100% 翻倍”选 16 g。"},{"id":"chem4-4.2-q2","tier":"L2","tierLabel":"L2 期末","examStyle":"P1 选择","q":"将 **\\(1\\text{ mol}\\)** 下列四种物质分别与足量氧气完全反应，消耗氧气的质量**最多**的是（　）。","options":["A. \\(\\mathrm{Mg}\\)","B. \\(\\mathrm{Al}\\)","C. \\(\\mathrm{Na}\\)","D. \\(\\mathrm{H_2}\\)"],"correctOption":"B","given":"教材 p.98 选择题第5题原题（注意给定 1 mol 而非 1 g！）","method":"分别写出与 O₂ 化合配平方程式，对比 1 mol 物质对应耗氧 mol 数","principle":"化学计量数决定等物质的量反应物耗氧量。","steps":["A. \\(\\mathrm{2Mg + O_2 \\to 2MgO}\\)：1 mol Mg 耗 **0.50 mol** \\(\\mathrm{O_2}\\)；","B. \\(\\mathrm{4Al + 3O_2 \\to 2Al_2O_3}\\)：1 mol Al 耗 **0.75 mol** \\(\\mathrm{O_2}\\)；","C. \\(\\mathrm{4Na + O_2 \\to 2Na_2O}\\)：1 mol Na 耗 **0.25 mol** \\(\\mathrm{O_2}\\)；","D. \\(\\mathrm{2H_2 + O_2 \\to 2H_2O}\\)：1 mol \\(\\mathrm{H_2}\\) 耗 **0.50 mol** \\(\\mathrm{O_2}\\)。","耗氧最多为 **Al**（0.75 mol，即 24 g）。"],"ans":"B","markingPoints":["逐一配平四种金属/氢气氧化方程式比对耗氧摩尔数"],"verification":"教材 p.98 第5题。","pitfall":"题目问的是“1 mol 下列物质”，常有人误按“1 g 下列物质”而秒选 H₂。"},{"id":"chem4-4.2-q3","tier":"L2","tierLabel":"L2 期末","examStyle":"P1 选择","q":"当胆矾晶体（\\(\\mathrm{CuSO_4\\cdot 5H_2O}\\)）受热充分失去结晶水时：\\(\\mathrm{CuSO_4\\cdot 5H_2O(s) \\xrightarrow{\\Delta} CuSO_4(s) + 5H_2O(g)}\\)。若有 \\(25\\text{ g}\\) 该晶体受热完全分解，则生成的无水硫酸铜（II）质量是（已知 \\(A_r: \\mathrm{Cu}=64, \\mathrm{S}=32, \\mathrm{O}=16, \\mathrm{H}=1\\)）（　）。","options":["A. 9 g","B. 24.1 g","C. 16 g","D. 25 g"],"correctOption":"C","given":"教材 p.98 选择题第8题原题","method":"计算式量 M(CuSO₄·5H₂O)=250 与 M(CuSO₄)=160，按比例求算","principle":"结晶水合物脱水的摩尔守恒。","steps":["\\(M(\\mathrm{CuSO_4\\cdot 5H_2O}) = 64 + 32 + 64 + 5\\times 18 = 250\\text{ g/mol}\\)；\\(M(\\mathrm{CuSO_4}) = 160\\text{ g/mol}\\)。","\\(25\\text{ g}\\) 胆矾为 \\(0.10\\text{ mol}\\)，故生成 \\(0.10\\text{ mol}\\ \\mathrm{CuSO_4}\\)，质量 \\(= 0.10\\times 160 = 16\\text{ g}\\)（同时失去 \\(9\\text{ g}\\) 水）。"],"ans":"C","markingPoints":["正确计算含 5H₂O 的总摩尔质量 250 g/mol"],"verification":"教材 p.98 第8题。","pitfall":"算错 \\(M(\\mathrm{CuSO_4\\cdot 5H_2O})\\) 时漏加 5 份水或把 \\(9\\text{ g}\\) 失水量选为选项 A。"},{"id":"chem4-4.2-q4","tier":"L3","tierLabel":"L3 预试","examStyle":"P2 限量与产率计算","q":"(1)（教材 p.99 第8题）将 \\(32\\text{ g}\\) 纯铜片放入溶有 \\(85\\text{ g}\\) 硝酸银（\\(\\mathrm{AgNO_3}\\)）的溶液中充分反应：\\(\\mathrm{Cu(s) + 2AgNO_3(aq) \\longrightarrow Cu(NO_3)_2(aq) + 2Ag(s)}\\)。完全反应后，能析出多少摩尔金属银？反应后哪种反应物剩余，剩余多少克？\n(2)（教材 p.99 第9题）实验室用 \\(255\\text{ g}\\) 含 \\(98\\%\\ \\mathrm{NaCl}\\) 的食盐与足量浓硫酸在强热下反应：\\(\\mathrm{2NaCl(s) + H_2SO_4(aq) \\xrightarrow{\\Delta} Na_2SO_4(aq) + 2HCl(g)}\\)，实际制得 \\(148\\text{ g HCl}\\) 气体，求本实验中 \\(\\mathrm{HCl}\\) 的产率（保留一位小数，已知 \\(A_r: \\mathrm{Cu}=64, \\mathrm{Ag}=108, \\mathrm{N}=14, \\mathrm{O}=16, \\mathrm{Na}=23, \\mathrm{Cl}=35.5, \\mathrm{H}=1\\)）。","given":"(1) 32 g Cu + 85 g AgNO₃；(2) 255 g (98% NaCl)，实得 148 g HCl","method":"(1) 先折算 mol 并判限量；(2) 先折纯 NaCl 再算理论 HCl，最后算产率","principle":"限量计算法则与纯度-产率串联计算。","steps":["第(1)问：\\(n(\\mathrm{Cu}) = \\frac{32}{64} = 0.50\\text{ mol}\\)；\\(M(\\mathrm{AgNO_3}) = 108+14+48 = 170\\text{ g/mol}\\)，故 \\(n(\\mathrm{AgNO_3}) = \\frac{85}{170} = 0.50\\text{ mol}\\)。","比较份数：\\(\\frac{0.50}{1} = 0.50 > \\frac{0.50}{2} = 0.25\\)，故 **\\(\\mathrm{AgNO_3}\\) 是限量反应物**，\\(\\mathrm{Cu}\\) 过量。","由限量 \\(\\mathrm{AgNO_3}\\) 得析出银：**\\(n(\\mathrm{Ag}) = n(\\mathrm{AgNO_3}) = 0.50\\text{ mol}\\)**；消耗 \\(\\mathrm{Cu} = 0.25\\text{ mol}\\)，故铜剩余 \\(0.50 - 0.25 = 0.25\\text{ mol}\\)，质量 \\(= 0.25\\times 64 = 16\\text{ g}\\)。","第(2)问：纯 \\(\\mathrm{NaCl}\\) 质量 \\(= 255\\times 98\\% = 249.9\\text{ g}\\)，其物质的量 \\(n(\\mathrm{NaCl}) = \\frac{249.9}{58.5} = 4.2718\\text{ mol}\\)。","由 1:1 计量关系得理论 \\(\\mathrm{HCl}\\) 质量：\\(m_{\\text{理}}(\\mathrm{HCl}) = 4.2718\\times 36.5 = 155.92\\text{ g}\\)。","故产率 \\(= \\frac{148\\text{ g}}{155.92\\text{ g}} \\times 100\\% = 94.9\\%\\)。"],"ans":"(1) 析出 0.50 mol Ag，Cu 过量剩余 16 g；(2) HCl 产率为 94.9%。","markingPoints":["判定 AgNO₃ 限量，求得析出 0.50 mol Ag 及剩余 16 g Cu（3分）","折纯 249.9 g NaCl 并算得理论 HCl 155.92 g（2分）","正确求得产率 94.9%（1分）"],"verification":"均源自教材 p.99 原题数据，数值验证无误。","pitfall":"第(1)题看到 0.50 mol Cu 和 0.50 mol AgNO₃ 摩尔数相同就误以为恰好完全反应。"},{"id":"chem4-4.2-q5","tier":"L4","tierLabel":"L4 统考压轴","examStyle":"P2 工业连续反应综合","q":"工业上采用接触法以黄铁矿（主要成分 \\(\\mathrm{FeS_2}\\)，杂质不含硫）为原料连续三步生产浓硫酸：\n① \\(\\mathrm{4FeS_2(s) + 11O_2(g)} \\xrightarrow{\\text{高温}} \\mathrm{2Fe_2O_3(s) + 8SO_2(g)}\\)\n② \\(\\mathrm{2SO_2(g) + O_2(g)} \\xrightleftharpoons[\\Delta]{\\text{催化剂}} \\mathrm{2SO_3(g)}\\)\n③ \\(\\mathrm{SO_3(g) + H_2O(l) \\longrightarrow H_2SO_4(aq)}\\)\n若某化工厂使用的黄铁矿中 \\(\\mathrm{FeS_2}\\) 质量分数（纯度）为 \\(80.0\\%\\)，且从黄铁矿到硫酸的总生产产率（硫元素总利用率）为 \\(90.0\\%\\)。现欲实际生产出 \\(196\\text{ t}\\) 质量分数为 \\(98.0\\%\\) 的浓硫酸，试通过计算求（已知 \\(A_r: \\mathrm{Fe}=56, \\mathrm{S}=32, \\mathrm{H}=1, \\mathrm{O}=16\\)）：\n(1) 写出 \\(\\mathrm{FeS_2}\\) 与最终产物 \\(\\mathrm{H_2SO_4}\\) 之间的理论物质的量关系式；\n(2) 这 \\(196\\text{ t}\\) 浓硫酸中共含纯 \\(\\mathrm{H_2SO_4}\\) 多少摩尔（或千摩尔 kmol）？\n(3) 至少需要投入这种 \\(80.0\\%\\) 纯度的黄铁矿石多少吨（保留一位小数）？","given":"m(浓硫酸)=196 t，w(H₂SO₄)=98.0%，总产率=90.0%，矿石纯度=80.0%","method":"利用硫原子守恒建关系式 FeS₂ ~ 2H₂SO₄，再用逆推“÷ 产率 ÷ 纯度”求矿石吨数","principle":"连续反应关系式法 + 纯度与产率联合逆推。","steps":["第(1)问：由三步方程式 \\(4\\mathrm{FeS_2} \\to 8\\mathrm{SO_2} \\to 8\\mathrm{SO_3} \\to 8\\mathrm{H_2SO_4}\\)（或直接依据硫原子守恒），得关系式：**\\(\\mathrm{FeS_2 \\sim 2H_2SO_4}\\)**。","第(2)问：实际制得纯 \\(\\mathrm{H_2SO_4}\\) 的质量为：\\(m(\\mathrm{H_2SO_4}) = 196\\text{ t} \\times 98.0\\% = 192.08\\text{ t}\\)。","因 \\(M(\\mathrm{H_2SO_4}) = 98\\text{ g/mol}\\)，故实际得到纯硫酸的物质的量为：\\(n(\\mathrm{H_2SO_4}) = \\frac{192.08\\times 10^6\\text{ g}}{98\\text{ g/mol}} = 1.96\\times 10^6\\text{ mol}\\)（即 \\(1960\\text{ kmol}\\)）。","第(3)问：若不计损失，制得 \\(1.96\\times 10^6\\text{ mol }\\mathrm{H_2SO_4}\\) 理论上仅需纯 \\(\\mathrm{FeS_2}\\) 为 \\(\\frac{1.96\\times 10^6}{2} = 0.98\\times 10^6\\text{ mol}\\)。","因 \\(M(\\mathrm{FeS_2}) = 56 + 2\\times 32 = 120\\text{ g/mol}\\)，故无损理论纯 \\(\\mathrm{FeS_2}\\) 质量 \\(= 0.98\\times 10^6\\times 120\\text{ g} = 117.6\\text{ t}\\)。","计入 \\(90.0\\%\\) 总产率与 \\(80.0\\%\\) 矿石纯度（逆推均须除）：\\(m_{\\text{黄铁矿}} = \\frac{117.6\\text{ t}}{90.0\\% \\times 80.0\\%} = \\frac{117.6}{0.72} = 163.3\\text{ t}\\)。"],"ans":"(1) \\(\\mathrm{FeS_2 \\sim 2H_2SO_4}\\)；(2) \\(1.96\\times 10^6\\text{ mol}\\)（1960 kmol）；(3) 163.3 t。","markingPoints":["依据三步转化正确写出关系式 FeS₂ ~ 2H₂SO₄（1分）","折纯算出 192.08 t 及 1.96×10⁶ mol H₂SO₄（2分）","正确算得无损需 117.6 t 纯 FeS₂，并正确除以 0.90 与 0.80 得 163.3 t（3分）"],"verification":"正算回代检验：\\(163.333\\text{ t} \\times 80\\% = 130.667\\text{ t}\\ \\mathrm{FeS_2}\\)（\\(1.0889\\times 10^6\\text{ mol}\\)）→ 理论产 \\(2.1778\\times 10^6\\text{ mol }\\mathrm{H_2SO_4} = 213.42\\text{ t}\\) → 乘产率 \\(90\\%\\) 实得 \\(192.08\\text{ t}\\) 纯酸 → 折合 \\(98\\%\\) 浓硫酸恰好 \\(196.0\\text{ t}\\)。","pitfall":"逆推矿石时错将 117.6 t 乘以 0.90 或忘了先将 196 t 浓硫酸乘以 98.0% 折算纯酸。"}],"cheatSheet":["计算铁律四句：①**代纯不代杂**（含杂质先乘纯度）；②**算限不算过**（比 \\(n/\\text{系数}\\) 小者限量）；③**顺乘逆除**（已知原料求产物乘产率，已知产物反推原料除以产率和纯度）；④**串联找守恒关系式**。","不纯固体产后纯度（如石灰石煅烧生石灰）：留在固体中的杂质**照加进分母**（\\(w = m_{\\text{纯 CaO}} / (m_{\\text{纯 CaO}} + m_{\\text{杂质}})\\)）。","限量折线图像：斜线段代表横轴试剂限量，拐点 \\(P(a, b)\\) 代表恰好完全反应，水平平台代表另一定量试剂耗尽、横轴试剂过量。"],"kbEntryIds":["kb-chem4-stoich-purity","kb-chem4-limiting-yield"],"quiz":{"q":"某钢铁厂每天投入 \\(2000\\text{ t}\\) 含 \\(85\\%\\) 氧化铁（III）的赤铁矿，经 \\(\\mathrm{Fe_2O_3 + 3CO \\xrightarrow{\\Delta} 2Fe + 3CO_2}\\) 实际生产出 \\(1100\\text{ t}\\) 纯铁（假设计作纯铁产量，\\(M(\\mathrm{Fe_2O_3})=160, M(\\mathrm{Fe})=56\\)），求该炼铁厂的产率。","given":"教材 p.94 问题解决原题：2000 t 矿石（含 85% Fe₂O₃），实产 1100 t Fe","method":"先折纯算出纯 Fe₂O₃，求理论产铁量，再求实际/理论百分比","principle":"纯度折算 + 产率定义式。","steps":["纯 \\(\\mathrm{Fe_2O_3} = 2000 \\times 85\\% = 1700\\text{ t}\\)。","理论产铁量：\\(m_{\\text{理}}(\\mathrm{Fe}) = 1700\\text{ t} \\times \\frac{2\\times 56}{160} = 1190\\text{ t}\\)。","产率 \\(= \\frac{1100\\text{ t}}{1190\\text{ t}} \\times 100\\% = 92.4\\%\\)。"],"ans":"\\(92.4\\%\\)"}}]},"化学5":{"lessonKey":"化学5","courseCode":"chemistry","subject":"化学","chapter":5,"title":"原子结构","syllabus":"1.3 原子结构","bookId":"sm1-chemistry-2017","bookCitation":"《马来西亚华文独中教科书 · 化学（上册）》（2017年11月版）第5章 p.102–132","examScopes":["sem1_final","pre_exam","sem2_final","uec"],"chapterOverview":{"summary":"第5章把学生的视野从第3章的宏观定量微粒引入原子内部：先沿着汤姆生发现电子—卢瑟福 α 粒子散射确立有核模型—查德威克发现中子的科学史建立原子核外模型，再定量定义原子序数 Z、质量数 A 与同位素平均相对原子质量，随后通过氢原子线光谱与玻尔能阶理论迈向现代量子力学电子云、轨域（s/p/d/f）和核外电子排布三大规律（含 Cr/Cu 半满全满特例），为第6章元素周期表和第7章化学键提供全部结构根基。","conceptTree":[{"branch":"5.1 原子模型的演化与三大亚原子粒子（p.103–108）","items":["阴极射线实验（电子）· 阳极射线（质子）· 云室轰击铍核（查德威克中子）","道尔顿实心球 → 汤姆生“葡萄干面包式” → 卢瑟福 α 粒子散射有核模型"]},{"branch":"5.2 原子序数、质量数与同位素（p.108–112）","items":["Z = 质子数 = 核电荷数 = 中性原子核外电子数；A = Z + N","核素与同位素（氕 氘 氚、碳十四断代、稳定/放射性同位素）","同位素丰度（原子百分比）加权计算平均相对原子质量"]},{"branch":"5.3 核外电子的能阶与玻尔理论（p.113–117）","items":["光的波粒二象性与电磁波谱；连续光谱 vs 氢原子可见光区线光谱","玻尔三点假设：定态轨道、能量不连续（能阶）、跃迁吸收/放出光子"]},{"branch":"5.4 原子核外电子的排布（p.118–126）","items":["电子云（s 球形、p 哑铃形、d 花瓣形）、电子层 K–Q（轨域数 n²、最大电子数 2n²）与电子自旋","能量最低原理（能级交错 4s < 3d）、鲍利不相容原理、汉德规则与 Cr/Cu 特例"]}]},"paperFocus":["高三上半年期末考（Ch 3–8, Ch 26–30）：第5章几乎必考 2–4 道 P1 选择题（α 散射现象结论、质子/中子/电子换算、同位素百分比反推、Cr/Cu 电子排布与未成对电子数）及 P2 必答题的原子结构/轨域表示式填空。","预试 / 毕业考 / UEC 统考：核外电子排布式（1–36 号，尤其过渡元素 Sc–Zn 及离子 Fe²⁺/Fe³⁺/Cu²⁺）与“未成对电子数”是连接第6章周期表定位与第16章过渡元素配合物的必考核心。"],"solvingWorkflow":["处理核素符号 ᴬ_Z Xⁿ±：先写清 Z（质子数）、N = A − Z（中子数），再按电荷还原核外电子数 e⁻ = Z − (所带正电荷) 或 Z + (所带负电荷)。","计算平均相对原子质量：确认题目给的是“原子百分比（摩尔分数）”还是“质量分数”，建立方程 Ar = Σ(Ar,i · xᵢ) 求解。","书写基态电子排布（1–36）：按能级交错顺序 1s 2s 2p 3s 3p 4s 3d 4p 填入，遇见 Z=24 (Cr) 改写 3d⁵4s¹，遇见 Z=29 (Cu) 改写 3d¹⁰4s¹；若是过渡金属阳离子，务必先失最外层 4s 电子，再失 3d 电子！","统计未成对电子数与轨域数：画出最外或未满副层的方框轨域表示式（↑↓ / ↑），严格应用汉德规则先分占再成对。"],"questionTypes":["原子模型实验事实与推论配对（阴极射线、α 粒子散射实验现象与核特征）","微粒/多核分子/离子中质子数、中子数、电子数与质量数综合换算（含重水 D₂¹⁶O 类题）","同位素天然丰度、平均相对原子质量及双原子分子同位素组合比例计算","氢原子线光谱特征与玻尔能阶跃迁吸光/放光波长大小比较","1–36 号原子及常见离子的电子排布式、轨域表示式、空轨域/未成对电子数及 Cr/Cu 特殊稳定态"],"scoringNotes":["统考卷二书写电子排布式时，注意上标位置清晰，简写式务必写明稀有气体核心如 [Ar]3d⁵4s¹；画轨域表示式必须用方框（或短线）和相反箭头（↑↓），简并轨域箭头方向需保持平行（全朝上或全朝下）。","用文字解释“为什么 K 先填 4s 再填 3d”或“为什么 Mg/P、Cr/Cu 排布特殊”时，必须点出教材关键词：“多电子原子能阶交错（4s 能量低于 3d）”、“同一电子副层半充满（d⁵）或全充满（d¹⁰）体系能量较低、更稳定”。"],"vid":[{"t":"卢瑟福 α 粒子散射实验与原子模型演变","q":"卢瑟福 alpha粒子散射实验 原子模型 高中化学"},{"t":"质子中子电子、质量数与同位素丰度计算","q":"原子序数 质量数 同位素 相对原子质量 计算"},{"t":"氢原子线光谱与玻尔能阶理论","q":"氢原子光谱 玻尔理论 能阶跃迁 化学"},{"t":"核外电子排布三大规律与 Cr/Cu 特例","q":"核外电子排布 能量最低 泡利 洪特 Cr Cu"}],"sections":[{"id":"5.1","t":"原子模型","anchor":{"pages":"化上 p.103–108","syllabus":"1.3.1 亚原子微粒的发现与原子结构模型演变","examScopes":["sem1_final","pre_exam","sem2_final","uec"],"examWeight":"P1 选择题高频科学史与实验推论对应题","terms":"cathode ray · subatomic particle · Thomson plum-pudding model · Rutherford α-scattering · nucleus","prerequisites":["道尔顿原子学说“实心不可分割球体”观点（化上 3.1.1 p.43）","基本电荷吸引与排斥及磁场对运动电荷的偏转作用"],"goals":["阐明阴极射线实验如何证明电子存在并推翻“原子不可再分”旧观念，简述质子与中子的发现过程。","比较汤姆生“葡萄干面包式”模型与卢瑟福有核原子模型的结构差异。","准确将卢瑟福 α 粒子散射实验的三条现象（直穿、微偏、弹回）与原子核的体积、密度、电性结论逐一对应。"]},"concepts":[{"kind":"experiment","title":"5.1.1 电子、质子、中子的发现实验","pageRef":"化上 p.104–106","body":["**电子的发现（汤姆生阴极射线实验，活动 1，p.104–105）**：阴极射线管接上高压电源后，阴极放出一束射线并在荧光板上产生绿光；将磁铁 N 极垂直靠近射线时，射线发生**向下弯曲**（在电场中向正极板偏转）。实验证明：任何原子都含有带负电荷、质量极小（约为最轻的氢原子质量的 \\(\\frac{1}{1836}\\)）的亚原子粒子——**电子（electron）**。","**质子的发现（p.106）**：科学家进一步发现带正电的阳极也能放出射线，且在电场/磁场中偏转方向与阴极射线刚好相反，由此证实了带正电的亚原子粒子——**质子（proton）**的存在，其电荷量与电子相等、电性相反，质量略小于氢原子。","**中子的发现（1932，查德威克，p.106）**：1910 年汤姆生发现存在质量不同的两种氖原子，启发科学家寻找电中性微粒；1932 年英国物理学家查德威克用 \\(\\alpha\\) 粒子轰击铍核，并通过云室实验证实了**不带电、质量与质子大约相等**的新微粒——**中子（neutron）**。"],"takeaway":"三大亚原子粒子发现顺序：**电子（汤姆生，1897）→ 质子 → 中子（查德威克，1932）**；中子因不带电而最晚被发现。"},{"kind":"definition","title":"5.1.2 汤姆生“葡萄干面包式”原子模型（1904）","pageRef":"化上 p.106–107","body":["针对电中性原子中同时存在极轻的负电电子与质量大得多的正电荷，汤姆生在 1904 年提出：**原子是一个均匀带正电荷的球体，带负电荷的电子像葡萄干一样镶嵌在球体中**（图 5-8）。","**局限性**：按汤姆生均匀球体模型，正电荷分散在整个原子空间内，无法产生足以使高速、较重的带正电 \\(\\alpha\\) 粒子（氦核 \\({}^{4}_{2}\\mathrm{He}^{2+}\\)）发生大角度反弹的强库仑斥力。"],"takeaway":"汤姆生模型虽然首次引入“原子内部有电子”，但错误地把正电荷分散在整个球体内。"},{"kind":"experiment","title":"5.1.3 卢瑟福 α 粒子散射实验与有核原子模型（1909–1911）","pageRef":"化上 p.107–108","body":["**实验设计（图 5-9，p.107）**：将放射性元素钋放在铅盒内，射出高速带正电的 \\(\\alpha\\) 粒子流（含 2 个质子和 2 个中子的氦核）轰击极薄的金箔，四周用涂有硫化锌（\\(\\mathrm{ZnS}\\)）的荧光屏接收闪光。","**现象与三大推论**：","- ① **绝大多数 \\(\\alpha\\) 粒子直接穿过金箔（未偏转）**：说明原子内部**几乎是空的**（原子核体积相对原子体积极小）。","- ② **少数 \\(\\alpha\\) 粒子发生轻微偏移**：因从带正电的原子核附近掠过，受到同性正电荷的静电斥力。","- ③ **极少数 \\(\\alpha\\) 粒子被直接反弹回来**：说明原子中心有一个**体积很小、密度很大且带正电荷的中心核（原子核）**，几乎集中了原子的全部质量。","**卢瑟福模型（1911）**：原子中心是带 \\(Z\\) 个单位正电荷的原子核，核外有 \\(Z\\) 个电子绕核做圆周运动，整个原子呈电中性（类行星模型）。"],"takeaway":"卢瑟福模型成功确立了“原子核+核外电子”，但经典电磁理论无法解释“加速圆周运动的电子为何不辐射能量而坠入原子核”。"},{"kind":"table","title":"近代五大原子结构模型演化里程碑对照","pageRef":"化上 p.106–108、p.127","body":["整理教材“本章知识梳理”所列的原子模型演进脉络，常用于科学史排序题。"],"table":{"headers":["模型名称","提出者与年份","核心图像","历史贡献与被修正之处"],"rows":[["道尔顿实心球模型","道尔顿（1803）","不可再分割的坚实小球","奠定化学定量学说；未认识亚原子微粒"],["汤姆生模型","汤姆生（1904）","带正电球体内镶嵌电子（葡萄干面包）","纳入电子；无法解释 α 粒子大角度散射"],["卢瑟福有核模型","卢瑟福（1911）","中心极小致密正电核 + 核外电子绕转","确立原子核；无法解释电子不坠核及线光谱"],["玻尔量子轨道模型","玻尔（1913）","电子在能量不连续的特定轨道运动并跃迁","成功解释氢原子线光谱；不适用于多电子精密描述"],["现代电子云模型","量子力学（20世纪20年代）","原子核 + 核外电子按几率分布形成电子云","引入轨域与自旋，准确描述多电子原子排布"]]}}],"formulas":[{"title":"电子与质子质量对比关系","tex":"m_e \\approx \\frac{1}{1836}\\,m_{\\mathrm{H}} \\approx \\frac{1}{1836}\\,m_p","plain":"m_e ≈ (1/1836) m_p","conditions":"近似比较，通常化学计算中可忽略电子质量","pageRef":"化上 p.105、p.109","note":"因此原子的质量几乎全集中在原子核上。"},{"title":"卢瑟福模型电中性电荷平衡","tex":"Q_{\\text{核}} = +Z\\,e,\\qquad Q_{\\text{核外电子}} = -Z\\,e,\\qquad Q_{\\text{原子}} = 0","plain":"核电荷数 = +Z，核外电子总电荷 = -Z，原子总电荷 = 0","conditions":"电中性基态或激发态原子","pageRef":"化上 p.107","note":"离子态则不再满足核外电子数等于 Z。"}],"pitfalls":[{"title":"将 α 粒子反弹误归因于‘撞到核外电子’","wrong":"“极少数 α 粒子被金箔反弹回来，是因为 α 粒子正面撞上了质量很大的金原子电子。”","diagnosis":"电子质量仅约质子的 1/1836，而一个 \\(\\alpha\\) 粒子（氦核）质量约为电子的 7300 倍，高速 \\(\\alpha\\) 粒子撞上电子犹如炮弹撞蚊子，绝不可能被弹回。","right":"\\(\\alpha\\) 粒子被直接弹回，充分说明原子中心存在一个**质量远大于 \\(\\alpha\\) 粒子、体积很小且带正电**的原子核。","checkRule":"看到 α 粒子反弹，立即联想“原子核质量集中 + 体积小 + 带正电”。"},{"title":"误以为卢瑟福直接发现了中子","wrong":"“卢瑟福通过 α 粒子散射实验同时发现了原子核里的质子和中子。”","diagnosis":"1911 年卢瑟福发现的是带正电的原子核；中子直到 1932 年才由查德威克发现。","right":"发现电子：汤姆生（1897）；确立原子核：卢瑟福（1911）；发现中子：查德威克（1932）。","checkRule":"科学史人物与微粒严格配对：汤姆生-电子，卢瑟福-原子核，查德威克-中子。"}],"examples":[{"label":"例 5.1.1","tier":"L2","tierLabel":"L2 校内期末","title":"卢瑟福 α 粒子散射实验现象与推论诊断","prompt":"1909 年卢瑟福用放射性钋放出的高速 \\(\\alpha\\) 粒子轰击金箔，观察到如下现象：①绝大多数 \\(\\alpha\\) 粒子穿过金箔后仍沿原方向前进；②少数 \\(\\alpha\\) 粒子发生较大角度偏转；③极少数（约八千分之一）\\(\\alpha\\) 粒子被直接反弹回来。请回答：(1) 实验所用“金箔”为什么必须锤打得极薄？(2) 由现象①和③分别能推出原子内部的什么结构特征？(3) 若改用相同厚度的铝箔替换金箔，发生大角度偏转的 \\(\\alpha\\) 粒子比例会增加还是减少？简述原因。","clues":"金核电荷数为 79，铝核电荷数为 13；静电斥力与核电荷数正相关。","strategy":"逐条把宏观荧光屏观测结果翻译成微观核体积、质量与电荷特征。","given":"Au (Z=79, Ar≈197) vs Al (Z=13, Ar≈27)；α 粒子 (Z=2, Ar=4)","principle":"原子核体积小、质量极大、带正电荷；库仑斥力随核电荷数增大而增强。","steps":["(1) 金具有极佳延展性，锤打极薄（仅数千层原子厚）可减少 \\(\\alpha\\) 粒子被多层原子连续碰撞或完全吸收的干扰，确保观察单次散射行为。","(2) 由现象①（绝大多数直穿）推出：**原子核体积远小于整个原子体积，原子内部绝大部分是空旷空间**；由现象③（极少数直接弹回）推出：**原子中心存在一个质量极大、密度极高且带正电荷的原子核**。","(3) 若改用铝箔（\\(Z=13\\)，原子核质量也小得多），由于铝原子核电荷数远小于金（\\(Z=79\\)），对 \\(\\alpha\\) 粒子的静电排斥力显著减弱，因此发生大角度偏转和反弹的 \\(\\alpha\\) 粒子比例会**明显减少**。"],"answer":"(1) 减少多次散射与能量吸收干扰；(2) ①原子内部几乎是空的，③中心有极小致密且带正电的原子核；(3) 减少，因铝核电荷数（13）及质量远小于金核（79）。","markingPoints":["点出金箔极薄是为了减少多重碰撞或吸收（1分）","现象①对应“原子核极小/内部几乎为空”（1分），现象③对应“原子核集中几乎全部质量且带正电”（1分）","判断铝箔偏转减少并从核电荷数/质量角度解释（1分）"],"verification":"对照化上 p.107 图 5-9 及其下三段文字核对。","pitfall":"第(3)问若误以为“铝较软、核间距不同”而答偏转增加，忽略了大角度散射本质是核电荷静电斥力与核质量反冲。"},{"label":"例 5.1.2","tier":"L2","tierLabel":"L2 校内期末","title":"阴极射线性质与微粒偏转方向综合判断","prompt":"在汤姆生阴极射线管实验（化上 p.105 活动 1）中，若将一对平行金属板分别接上直流高压电（上板接正极、下板接负极），则原本沿水平向右射出的阴极射线将向哪一侧偏转？若换用相同实验装置研究阳极射线（质子束），其偏转方向与偏转幅度与阴极射线有何不同？","clues":"阴极射线为带负电的电子流；质子带正电且质量远大于电子。","strategy":"先判电性定偏转方向，再由质量差异定相同电场下偏转弯曲程度。","given":"电子：电荷 -e，质量 me；质子：电荷 +e，质量 mp ≈ 1836 me","principle":"异种电荷相吸；质量越大惯性越大，相同电场力下加速度及偏转角越小。","steps":["阴极射线由带负电的电子组成，进入平行板电场后受到朝向正极板（上板）的静电引力，故射线**向上弯曲偏转**。","阳极射线中的质子带正电，进入同一电场时受负极板吸引，故向**下板（负极）偏转**，方向与阴极射线刚好相反。","由于质子质量约为电子的 \\(1836\\) 倍，在电荷量大小相等（均为 \\(1.602\\times 10^{-19}\\text{ C}\\)）时，质子的惯性远大于电子，因此其偏转弯曲程度（偏转角）比阴极射线**小得多**。"],"answer":"阴极射线向上（正极板）偏转；质子束向下（负极板）偏转且偏转幅度小得多。","markingPoints":["指明阴极射线带负电故向正极板上偏转（1分）","指明质子带正电故向相反方向（负极板）偏转（1分）","利用质子质量远大于电子解释偏转幅度更小（1分）"],"verification":"与化上 p.105–106 原文“偏转方向相反、质子质量远大于电子”一致。","pitfall":"只答出偏转方向相反，漏掉质量比 1836:1 带来的偏转幅度差异。"}],"practice":[{"id":"chem5-5.1-q1","tier":"L1","tierLabel":"L1 基础","examStyle":"P1 选择","q":"最先通过阴极射线实验证实原子内含有带负电亚原子粒子（电子），并提出“葡萄干面包式”原子模型的科学家是（　）。","options":["A. 道尔顿","B. 汤姆生","C. 卢瑟福","D. 查德威克"],"correctOption":"B","given":"原子模型发展史（化上 p.104–107）","method":"对应科学家与发现微粒及模型","principle":"汤姆生发现电子（1897）并提出葡萄干面包模型（1904）。","steps":["A 道尔顿提出实心不可分割原子学说；B 汤姆生发现电子并建葡萄干面包模型；C 卢瑟福提出有核模型；D 查德威克发现中子。"],"ans":"B","markingPoints":["准确识别汤姆生贡献"],"verification":"化上 p.104–107。","pitfall":"将发现中子的查德威克与发现电子的汤姆生混淆。"},{"id":"chem5-5.1-q2","tier":"L2","tierLabel":"L2 期末","examStyle":"P1 选择","q":"在卢瑟福 \\(\\alpha\\) 粒子散射实验中，绝大多数 \\(\\alpha\\) 粒子能够毫无阻挡地直接穿过金箔，这一事实直接证明了（　）。","options":["A. 原子核带有正电荷","B. 原子中电子的排布是分层的","C. 原子内部几乎是空的，原子核体积很小","D. 原子核内含有不带电的中子"],"correctOption":"C","given":"α 粒子散射现象①：绝大多数直穿","method":"区分实验各现象对应的单一微观推论","principle":"直穿现象反映核占原子体积比重极微。","steps":["A 是由发生偏转与反弹的斥力推出的；B 属于玻尔与量子力学内容；C 正确对应“绝大多数直穿”；D 为查德威克后续发现。"],"ans":"C","markingPoints":["现象与推论一对一精准匹配"],"verification":"化上 p.107 最后一段。","pitfall":"把“带正电”与“几乎是空的”两个现象对应关系张冠李戴。"},{"id":"chem5-5.1-q3","tier":"L2","tierLabel":"L2 期末","examStyle":"P2 简答","q":"为什么在原子中质子（带正电）和电子（带负电）发现得较早，而中子直到 1932 年才被查德威克发现？中子的发现解决了原子质量计算中的什么疑难问题？","given":"质子、电子与中子电性及质量对比","method":"从电场/磁场对微粒的作用条件及原子核质量差分析","principle":"电场和磁场只使带电粒子偏转；一般原子核质量约等于质子+中子之和。","steps":["早期物理实验主要依靠电场和磁场偏转射线来探测粒子。质子和电子均带电荷，易在电磁场中偏转而被检测；而**中子呈电中性，不受电场或磁场偏转**，因此难以用常规电磁方法捕捉，直到 1932 年查德威克用 \\(\\alpha\\) 粒子轰击铍核才通过碰撞间接证实。","此前人们发现氦核（电荷数 2）的质量却是氢核的 4 倍（而非 2 倍），且同种元素（如氖）存在不同质量的原子，中子的发现正好解释了核内除质子外还有等质量级别的电中性粒子。"],"ans":"中子不带电、不受电磁场偏转而难以探测；中子的发现解释了原子核质量大于质子总质量及同位素存在质量差异的原因。","markingPoints":["指出中子不带电不受电磁场偏转（2分）","说明中子解释了核质量（如 He 质量数为 4 而质子数为 2）及同位素质量差异（2分）"],"verification":"结合化上 p.106 资料链接与表 5-1 核对。","pitfall":"只答“以前仪器落后”，未扣住“电中性粒子不受电场/磁场偏转”这一核心物理原因。"},{"id":"chem5-5.1-q4","tier":"L3","tierLabel":"L3 预试","examStyle":"P1 选择","q":"按原子结构模型发展的先后顺序，下列排列完全正确的是（　）。","options":["A. 实心球模型 → 有核模型 → 葡萄干面包模型 → 玻尔轨道模型 → 电子云模型","B. 实心球模型 → 葡萄干面包模型 → 有核模型 → 玻尔轨道模型 → 电子云模型","C. 葡萄干面包模型 → 实心球模型 → 玻尔轨道模型 → 有核模型 → 电子云模型","D. 实心球模型 → 葡萄干面包模型 → 电子云模型 → 玻尔轨道模型 → 有核模型"],"correctOption":"B","given":"五种经典原子模型","method":"时间线与物理问题驱动顺序校验","principle":"道尔顿(1803) → 汤姆生(1904) → 卢瑟福(1911) → 玻尔(1913) → 量子电子云(1926)。","steps":["依次为：道尔顿实心球 → 汤姆生葡萄干面包 → 卢瑟福有核 → 玻尔定态跃迁 → 现代电子云模型。"],"ans":"B","markingPoints":["把握 1904→1911→1913 关键年份顺序"],"verification":"对照教材 p.127 知识梳理框图核对。","pitfall":"混淆汤姆生(1904)与卢瑟福(1911)或玻尔(1913)与电子云的顺序。"},{"id":"chem5-5.1-q5","tier":"L4","tierLabel":"L4 统考拔高","examStyle":"P1 选择","q":"卢瑟福模型虽然圆满解释了 \\(\\alpha\\) 粒子散射实验，但它在当时面临一个致命的理论困境而促使玻尔提出新理论。该困境是（　）。","options":["A. 无法解释原子为什么整体显电中性","B. 无法解释不同元素的原子为什么质量不同","C. 按经典电磁理论，绕核做圆周加速运动的电子会不断辐射电磁波失去能量而很快坠毁到原子核上，且原子光谱应是连续的而非线状的","D. 无法解释 α 粒子本身为什么带有两个单位正电荷"],"correctOption":"C","given":"卢瑟福模型局限性与 5.3 玻尔理论衔接","method":"联系经典电动力学与原子稳定性、线光谱事实","principle":"原子稳定存在且发射离散线光谱，与经典电磁连续辐射矛盾。","steps":["A、B 卢瑟福模型均能用 Z 个电子平衡 Z 个核电荷及核子数差异解释；C 是经典物理学下有核模型的“原子坍缩”与“连续光谱”悖论，正是 1913 年玻尔引入量子化轨道定态假设的直接动因。"],"ans":"C","markingPoints":["理解从卢瑟福模型跃升至玻尔模型的核心科学问题"],"verification":"结合 p.107 与 p.115–116 玻尔第一条假设核对。","pitfall":"错选 A 或 B，没有理解经典力学无法保证核外电子稳定绕转。"}],"cheatSheet":["亚原子发现顺序：阴极射线发现**电子**（汤姆生）→ 阳极射线发现**质子** → \\(\\alpha\\) 轰击铍核发现**中子**（查德威克，1932）。","模型演变五步曲：道尔顿实心球 → 汤姆生葡萄干面包 → 卢瑟福有核模型 → 玻尔量子轨道 → 现代电子云。","α 粒子散射三现象：① 多数直穿 = 内部几乎空；② 少数偏转 = 核带正电斥力；③ 极少弹回 = 核集中几乎全部质量且体积微乎其微。"],"kbEntryIds":["kb-chem5-thomson-rutherford"],"quiz":{"q":"一个高速 \\(\\alpha\\) 粒子流轰击金箔时，若某 \\(\\alpha\\) 粒子几乎沿原路被弹回 \\(180^\\circ\\)，它究竟遭到了什么微粒的排斥？","given":"α 粒子为 ⁴₂He²⁺（质量数 4，带 +2 电荷）","method":"比较电子与金原子核的质量及电荷作用","principle":"正电荷间库仑斥力及质量极大中心核的反冲。","steps":["电子质量太小无法弹回 α 粒子；只有极接近或正对带有 +79 正电荷、质量约为 197 的金原子核时，才会因巨大静电斥力被大角度弹回。"],"ans":"金原子中心体积很小、质量极大且带正电荷的**原子核**。"}},{"id":"5.2","t":"原子序数、质量数和同位素","anchor":{"pages":"化上 p.108–112","syllabus":"1.3.2 核素符号、质子/中子/电子关系与同位素平均相对原子质量","examScopes":["sem1_final","pre_exam","sem2_final","uec"],"examWeight":"P1 必考粒子数对比 + P2 同位素丰度计算","terms":"atomic number (Z) · mass number (A) · nuclide · isotope · isotopic abundance","prerequisites":["碳-12 相对原子质量基准（1 amu，化上 3.3.2 p.55）","质子、中子与电子的相对质量与电量"],"goals":["熟练读取并书写核素符号 \\({}^{A}_{Z}\\mathrm{X}\\) 及离子符号 \\({}^{A}_{Z}\\mathrm{X}^{n\\pm}\\)，迅速换算质子数、中子数、电子数与质量数。","准确区分核素、同位素（同质子数不同中子数）与同素异形体，列举氢、碳、氧、铀常见同位素及应用。","运用同位素原子百分比（丰度）公式计算元素平均相对原子质量，或已知平均值反求二元同位素天然百分比。"]},"concepts":[{"kind":"table","title":"5.2.1 质子、中子、电子参数（表 5-1）与原子序数、质量数定义","pageRef":"化上 p.109–110","body":["**原子序数（\\(Z\\)）**：莫斯莱由 X 射线实验确立，按原子核中核电荷数由小到大的顺序给元素编排的序号。在**电中性原子**中：\\(\\text{原子序数 } Z = \\text{核电荷数} = \\text{质子数} = \\text{核外电子数}\\)。","**质量数（\\(A\\)）**：忽略微小的电子质量，将原子核中所有质子和中子的相对质量取整数相加得到的数值，即 \\(A = Z + N\\)（质子数 + 中子数）。核素完整记号写作 \\({}^{A}_{Z}\\mathrm{X}\\)（如 \\({}^{19}_{9}\\mathrm{F}\\) 含 9 个质子、10 个中子、9 个电子）。"],"table":{"headers":["微粒名称","实际质量 / kg","相对质量（以 ¹²C/12 为 1）","电量 / C","核素计数归属"],"rows":[["质子 (p)","1.673 × 10⁻²⁷","1.007（取整 1）","+1.602 × 10⁻¹⁹（+1）","决定元素种类（Z）"],["中子 (n)","1.675 × 10⁻²⁷","1.008（取整 1）","0（电中性）","决定同位素种类（N = A − Z）"],["电子 (e⁻)","9.109 × 10⁻³¹","1 / 1836（忽略）","−1.602 × 10⁻¹⁹（−1）","决定化学性质与离子电荷"]]},"takeaway":"元素的“化学身份”由质子数 \\(Z\\) 唯一决定；核素质量数 \\(A\\) 必为整数，且数值上略近似于该核素的相对原子质量。"},{"kind":"definition","title":"5.2.2 核素与同位素（以氢、碳同位素为例）","pageRef":"化上 p.110–111","body":["**核素（nuclide）**：具有一定数目质子和一定数目中子的一种原子叫做核素。例如氢元素有三种核素：氕（\\({}^{1}_{1}\\mathrm{H}\\)，0 中子）、氘（\\({}^{2}_{1}\\mathrm{H}\\) 或 \\(\\mathrm{D}\\)，重氢，1 中子）、氚（\\({}^{3}_{1}\\mathrm{H}\\) 或 \\(\\mathrm{T}\\)，超重氢，2 中子）；氦有 \\({}^{3}_{2}\\mathrm{He}\\)、\\({}^{4}_{2}\\mathrm{He}\\) 等核素。","**同位素（isotope）**：**质子数相同而中子数不同的同一元素的不同原子**互称同位素（“同位”意指在元素周期表中占有同一位置）。例如碳的三种同位素 \\({}^{12}_{6}\\mathrm{C}\\)（6n）、\\({}^{13}_{6}\\mathrm{C}\\)（7n）、\\({}^{14}_{6}\\mathrm{C}\\)（8n）；铀有 \\({}^{234}_{92}\\mathrm{U}\\)、\\({}^{235}_{92}\\mathrm{U}\\)、\\({}^{238}_{92}\\mathrm{U}\\)。","**稳定 vs 放射性同位素及应用（p.110–111）**：自然界稳定存在的为稳定同位素（如 \\({}^{12}\\mathrm{C},{}^{13}\\mathrm{C}\\)）；不能稳定存在而具有放射性的为放射性同位素（如 \\({}^{14}\\mathrm{C}\\) 用于考古测定文物年代；\\({}^{2}\\mathrm{H}\\) 与 \\({}^{3}\\mathrm{H}\\) 制造氢弹；医用放射性同位素用于显像、诊断、灭菌与肿瘤治疗）。"],"takeaway":"同位素的质子数和核外电子数相同，因此**化学性质几乎完全相同**，但物理性质（如密度、熔沸点、扩散速率、质量）有微小差异。"},{"kind":"mechanism","title":"同位素丰度（表 5-4）与天然元素平均相对原子质量计算","pageRef":"化上 p.112","body":["**同位素丰度（isotopic abundance）**：用**原子百分比**表示的天然某元素中各同位素的相对含量。例如氧的同位素丰度为 \\({}^{16}\\mathrm{O}\\;99.76\\%\\)、\\({}^{17}\\mathrm{O}\\;0.04\\%\\)、\\({}^{18}\\mathrm{O}\\;0.20\\%\\)；自然界中 \\(\\mathrm{F, Na, Al}\\) 等 21 种元素只有一种天然同位素（丰度 \\(100\\%\\)）。","**教材计算示范（表 5-4 氖元素，p.112）**：\\({}^{20}_{10}\\mathrm{Ne}\\)（\\(19.998860\\)，占 \\(90.92\\%\\)）、\\({}^{21}_{10}\\mathrm{Ne}\\)（\\(21.000589\\)，占 \\(0.26\\%\\)）、\\({}^{22}_{10}\\mathrm{Ne}\\)（\\(21.998270\\)，占 \\(8.82\\%\\)），故氖的相对原子质量 \\(= 19.998860\\times 90.92\\% + 21.000589\\times 0.26\\% + 21.998270\\times 8.82\\% = 20.18\\)。","**同位素丰度自然规律（p.112 资料链接）**：① \\(Z < 27\\) 的元素往往有一种同位素占绝对优势（如 \\({}^{14}\\mathrm{N}\\) 占 \\(99.64\\%\\)）；② 原子序数为偶数的元素，往往中子数为偶数的同位素丰度最大（如 \\({}^{32}\\mathrm{S}\\) 占 \\(95.02\\%\\)）。"],"takeaway":"缺乏同位素精确相对原子质量时，题中常以“同位素质量数 \\(A_i\\)”近似代替计算元素平均相对原子质量。"}],"formulas":[{"title":"原子与离子微粒数量关系式","tex":"A = Z + N,\\qquad \\text{电子数 } e^- = Z - c\\quad(\\text{对于微粒 } {}^{A}_{Z}\\mathrm{X}^{c})","plain":"A = Z + N；微粒电子数 = Z - 电荷代数值 c","conditions":"阳离子 c > 0（失电子，e⁻ < Z）；阴离子 c < 0（得电子，e⁻ > Z）；原子 c = 0","pageRef":"化上 p.109–110","note":"例如 ²⁷₁₃Al³⁺ 含 p=13, n=14, e⁻=13−3=10；¹⁶₈O²⁻ 含 p=8, n=8, e⁻=8−(−2)=10。"},{"title":"同位素丰度加权平均相对原子质量","tex":"A_r = \\sum_{i} A_{r,i}\\,w_i \\approx \\sum_{i} A_i\\,w_i\\quad\\left(\\sum_i w_i = 1\\right)","plain":"Ar = Σ(同位素 Ar × 原子百分比)","conditions":"wᵢ 必须为原子个数分数（物质的量分数），而非质量分数","pageRef":"化上 p.112","note":"二元同位素已知 Ar 反推丰度时，设 x 与 (1−x) 列一次方程或用十字交叉法最稳妥。"}],"pitfalls":[{"title":"混淆‘同位素’与‘同素异形体’","wrong":"“\\(\\mathrm{O_2}\\) 和 \\(\\mathrm{O_3}\\) 的质子数相同，所以它们互为同位素。”","diagnosis":"同位素的研究对象是**原子（核素）**；\\(\\mathrm{O_2}\\) 与 \\(\\mathrm{O_3}\\) 是由同种氧元素构成的不同**单质分子**，属于同素异形体。","right":"\\({}^{16}\\mathrm{O}, {}^{17}\\mathrm{O}, {}^{18}\\mathrm{O}\\) 互称同位素；\\(\\mathrm{O_2}\\) 与 \\(\\mathrm{O_3}\\)（或金刚石与石墨、红磷与白磷）互称**同素异形体**；\\(\\mathrm{H_2O}\\) 与 \\(\\mathrm{D_2O}\\) 则是同一种化合物（只是由不同核素构成的水分子）。","checkRule":"先看比较对象是“单个原子”（同位素）还是“单质物质”（同素异形体）。"},{"title":"误认为所有原子核都必含中子","wrong":"“任何元素的任何原子，其原子核都由质子和中子共同构成。”","diagnosis":"氢元素最常见的核素氕（\\({}^{1}_{1}\\mathrm{H}\\)）质量数 \\(A=1\\)、质子数 \\(Z=1\\)，其中子数 \\(N = 1 - 1 = 0\\)。","right":"\\({}^{1}_{1}\\mathrm{H}\\) 原子核内只有 \\(1\\) 个质子，**不含中子**（它是唯一不含中子的稳定核素）。","checkRule":"遇到“所有原子都含质子、中子、电子”这类绝对判断，立即用 \\({}^{1}_{1}\\mathrm{H}\\) 举反例。"},{"title":"计算重水（D₂O / ²H₂¹⁶O）时把 D 当成质子数 2","wrong":"“\\(1\\text{ 个 } {}^{2}_{1}\\mathrm{H}_2{}^{16}_{8}\\mathrm{O}\\) 分子中共有 \\(2\\times 2 + 8 = 12\\) 个质子。”","diagnosis":"氘（\\(\\mathrm{D}={}^{2}_{1}\\mathrm{H}\\)）仍是氢元素，质子数仍为 \\(1\\)，只是中子数为 \\(1\\)、质量数为 \\(2\\)！","right":"\\(1\\text{ 个 } \\mathrm{D_2^{16}O}\\) 分子中：质子数 \\(= 1\\times 2 + 8 = 10\\)，电子数 \\(= 10\\)，中子数 \\(= (2-1)\\times 2 + (16-8) = 10\\)，相对分子质量 \\(= 2\\times 2 + 16 = 20\\)。","checkRule":"遇到 D/T，心里立刻写成 \\({}^{2}_{1}\\mathrm{H}\\) 和 \\({}^{3}_{1}\\mathrm{H}\\) 再数质子和中子（教材 p.131 第 8 题高频考点！）。"}],"examples":[{"label":"例 5.2.1","tier":"L2","tierLabel":"L2 校内期末","title":"教材 p.131 第 3 & 8 题改编：碳同位素百分比与重水粒子数计算","prompt":"(1) 已知自然界碳元素主要由 \\({}^{12}_{6}\\mathrm{C}\\)（准确相对原子质量 \\(12.000\\)）和 \\({}^{13}_{6}\\mathrm{C}\\)（\\(13.003\\)）两种同位素组成，测得天然碳的相对原子质量为 \\(12.011\\)，试求 \\({}^{12}_{6}\\mathrm{C}\\) 与 \\({}^{13}_{6}\\mathrm{C}\\) 的原子百分比；(2) 现有 \\(10.0\\text{ g}\\) 由 \\({}^{2}_{1}\\mathrm{H}\\)（\\(\\mathrm{D}\\)）与 \\({}^{16}_{8}\\mathrm{O}\\) 构成的重水（\\(\\mathrm{D_2O}\\)）液体，求其中所含的质子数、中子数与电子数（以 \\(N_A\\) 或具体数值表示，\\(N_A = 6.02\\times 10^{23}\\text{ mol}^{-1}\\)）。","clues":"第(1)问设 ¹²C 丰度为 x；第(2)问先求 D₂¹⁶O 摩尔质量 = 2×2 + 16 = 20 g/mol。","strategy":"分步列同位素丰度方程与物质的量—微粒换算桥。","given":"Ar(C)=12.011；m(D₂¹⁶O)=10.0 g，M=20.0 g/mol","principle":"同位素丰度加权公式；n = m/M；1 个 D₂¹⁶O 含 10p、10n、10e⁻。","steps":["第(1)问：设 \\({}^{12}_{6}\\mathrm{C}\\) 的原子百分数为 \\(x\\)，则 \\({}^{13}_{6}\\mathrm{C}\\) 为 \\(1 - x\\)。","代入公式：\\(12.000\\,x + 13.003\\,(1 - x) = 12.011 \\implies 1.003\\,x = 0.992 \\implies x = 0.9890 = 98.90\\%\\)。","故 \\({}^{12}_{6}\\mathrm{C}\\) 占 \\(98.90\\%\\)，\\({}^{13}_{6}\\mathrm{C}\\) 占 \\(1.10\\%\\)（若用质量数 12 与 13 近似计算，则 \\(x = 98.9\\%\\)）。","第(2)问：\\(\\mathrm{D_2^{16}O}\\) 的摩尔质量 \\(M = 2\\times 2 + 16 = 20.0\\text{ g/mol}\\)，故重水的物质的量 \\(n(\\mathrm{D_2^{16}O}) = \\frac{10.0\\text{ g}}{20.0\\text{ g/mol}} = 0.500\\text{ mol}\\)。","每 \\(1\\text{ 个 }\\mathrm{D_2^{16}O}\\) 分子含质子 \\(1\\times 2 + 8 = 10\\) 个、中子 \\((2-1)\\times 2 + (16-8) = 10\\) 个、电子 \\(10\\) 个。","因此三者物质的量均为 \\(0.500\\text{ mol} \\times 10 = 5.00\\text{ mol}\\)，个数均为 \\(5.00\\times 6.02\\times 10^{23} = 3.01\\times 10^{24}\\) 个。"],"answer":"(1) ¹²C 为 98.90%，¹³C 为 1.10%；(2) 质子数、中子数、电子数均为 5.00 mol（即 3.01×10²⁴ 个）。","markingPoints":["正确列写碳同位素加权方程并解得 98.90% 和 1.10%（2分）","算得重水摩尔质量 20 g/mol 即 0.500 mol（1分）","正确数出每个 D₂¹⁶O 分子含 10p、10n、10e⁻ 并换算得 3.01×10²⁴（2分）"],"verification":"验证加权值：\\(12.000\\times 0.9890 + 13.003\\times 0.0110 = 11.868 + 0.143 = 12.011\\)。","pitfall":"第(2)问极易习惯性按普通水 \\(M = 18\\text{ g/mol}\\) 计算或忘记扣除质量数中的质子数而错算中子数。"},{"label":"例 5.2.2","tier":"L3","tierLabel":"L3 预试拔高","title":"核素与同位素分子组合统计（教材 p.131 第 8(1) 题延伸）","prompt":"自然界氧元素有 \\({}^{16}_{8}\\mathrm{O},{}^{17}_{8}\\mathrm{O},{}^{18}_{8}\\mathrm{O}\\) 三种核素，氢元素有 \\({}^{1}_{1}\\mathrm{H},{}^{2}_{1}\\mathrm{H},{}^{3}_{1}\\mathrm{H}\\) 三种核素。(1) 这 6 种核素一共可以构成多少种**不同核素组成的水分子**？(2) 这些水分子共有多少种**不同的相对分子质量**？(3) 已知铜元素有 \\({}^{63}\\mathrm{Cu}\\) 与 \\({}^{65}\\mathrm{Cu}\\) 两种同位素，平均相对原子质量为 \\(63.55\\)，而溴（\\(\\mathrm{Br}\\)）有 \\({}^{79}\\mathrm{Br}\\) 与 \\({}^{81}\\mathrm{Br}\\)（丰度各约 \\(50\\%\\)），则在 \\(\\mathrm{CuBr_2}\\) 质谱分析中可能出现多少种不同质量数的 \\(\\mathrm{CuBr_2}\\) 化学式单元？","clues":"H₂O 分子中两个氢位置是对称等价的，(¹H, ²H) 与 (²H, ¹H) 是同一种水分子！","strategy":"先枚举 H 的无序两原子组合，再与 O 组合并统计总质量数去重。","given":"3 种 H 核素，3 种 O 核素；2 种 Cu 同位素，2 种 Br 同位素","principle":"组合去重计数与质量数加和枚举。","steps":["第(1)问：水分子含 2 个等效氢位与 1 个氧位。从 3 种 H 中允许重复、不计顺序地选 2 个，组合有 \\(\\binom{3+2-1}{2} = 6\\) 种：（1,1）、（1,2）、（1,3）、（2,2）、（2,3）、（3,3）。再分别搭配 3 种 O 核素，共得 \\(6 \\times 3 = 18\\) 种不同水分子。","第(2)问：两个 H 质量数之和可能是 \\(1+1=2, 1+2=3, 1+3=4\\text{ (或 }2+2\\text{)}, 2+3=5, 3+3=6\\)，共 \\(2,3,4,5,6\\) 五种总氢质量。加上 O 的 \\(16,17,18\\)，水分子的最小质量数为 \\(2+16=18\\)，最大为 \\(6+18=24\\)，且中间 \\(18,19,20,21,22,23,24\\) 每个整数均可取到，故共有 **7 种**不同的相对分子质量。","第(3)问：两个 Br 位无序组合有（79,79）、（79,81）、（81,81）共 3 种；Cu 有 2 种（63, 65）。两者组合共 \\(2\\times 3 = 6\\) 种化学式组成，其质量数分别为：63+158=221，63+160=223，63+162=225，65+158=223，65+160=225，65+162=227。去重后质量数共有 **221, 223, 225, 227** 四种，按组成核素种类则有 6 种。"],"answer":"(1) 18 种水分子；(2) 7 种相对分子质量（18–24）；(3) 6 种核素组合（对应 4 种不同质量数）。","markingPoints":["避免重复计数（¹H²HO 与 ²H¹HO 为同一分子），算出 H 组合 6 种、水分子 18 种（2分）","枚举质量数范围 18 到 24 得 7 种（1分）","正确枚举 CuBr₂ 的 6 种核素组合并去重得 4 种质量数（2分）"],"verification":"教材 p.131 第 8(1) 题若只考虑 ¹⁶O、¹H、²H，则 H 组合 (1,1), (1,2), (2,2) 共 3 种，配 ¹⁶O 最多构成 3 种水分子。","pitfall":"第(1)问最常犯“排列而非组合”错误，误算成 \\(3\\times 3\\times 3 = 27\\) 种。"}],"practice":[{"id":"chem5-5.2-q1","tier":"L1","tierLabel":"L1 基础","examStyle":"P1 选择","q":"某放射性核素 \\({}^{131}_{53}\\mathrm{I}\\) 常用于医学甲状腺疾病诊断与治疗。关于该核素的说法，正确的是（　）。","options":["A. 原子核内含有 131 个中子","B. 原子核内含有 78 个质子","C. 核外电子数为 53，中子数为 78","D. 其化学性质与天然碘 ¹²⁷₅₃I 完全不同"],"correctOption":"C","given":"核素 ¹³¹₅₃I","method":"对照 ᴬ_Z X 读取 Z、A 并算 N = A − Z","principle":"Z=质子数=电子数；N=A−Z；同位素化学性质几乎相同。","steps":["质子数 \\(Z=53\\)，核外电子数 \\(=53\\)，质量数 \\(A=131\\)，中子数 \\(N = 131 - 53 = 78\\)。","同位素电子排布完全相同，化学性质几乎一致，故 D 错，C 对。"],"ans":"C","markingPoints":["准确区分 Z、A、N"],"verification":"53 + 78 = 131。","pitfall":"把质量数 131 误当中子数或把 78 误当质子数。"},{"id":"chem5-5.2-q2","tier":"L2","tierLabel":"L2 期末","examStyle":"P1 选择","q":"下列关于“同位素”和“核素”的说法中，正确的是（　）。","options":["A. ⁴⁰₁₈Ar 与 ⁴⁰₂₀Ca 的质量数相同，因此它们互为同位素","B. 氕（¹H）、氘（²H）、氚（³H）是三种不同的元素","C. 某元素在自然界的所有同位素之和构成一种元素，每种元素有且只有一种核素","D. 自然界中的 ¹⁹F、²³Na、²⁷Al 等单核素元素，其该种核素的同位素丰度为 100%"],"correctOption":"D","given":"核素与同位素定义（化上 p.111–112）","method":"逐项对照教材同位素三要素（同质子数、不同中子数、同一元素）","principle":"同位素必须具有相同的质子数 Z。","steps":["A 错：⁴⁰Ar 与 ⁴⁰Ca 质子数分别为 18 和 20，属于不同元素（互称同量异位素）。","B 错：氕、氘、氚质子数均为 1，同属氢元素，互为同位素（三种不同核素）。","C 错：大多数元素有多种核素（如碳有 3 种、锡有 10 种）。","D 对：化上 p.112 原文明确指出 F、Na、Al 等 21 种元素在自然界只有一种同位素，丰度 100%。"],"ans":"D","markingPoints":["紧扣“质子数相同”判断同位素"],"verification":"化上 p.111–112 原文。","pitfall":"容易把质量数相同的 ⁴⁰Ar 和 ⁴⁰Ca 误认为同位素。"},{"id":"chem5-5.2-q3","tier":"L2","tierLabel":"L2 期末","examStyle":"P2 必答计算","q":"（教材 p.131 第 2 题）氧有 3 种天然同位素，其相对原子质量与原子百分比如下：\\({}^{16}_{8}\\mathrm{O}\\)（\\(15.994\\)，\\(99.759\\%\\)），\\({}^{17}_{8}\\mathrm{O}\\)（\\(16.999\\)，\\(0.037\\%\\)），\\({}^{18}_{8}\\mathrm{O}\\)（\\(17.999\\)，\\(0.204\\%\\)）。试列式计算氧元素的相对原子质量（保留五位有效数字），并指出 \\({}^{18}_{8}\\mathrm{O}^{2-}\\) 离子的质子数、中子数与核外电子数。","given":"三种氧同位素相对原子质量及百分比","method":"同位素丰度加权平均；阴离子电子数 = Z + 负电荷数","principle":"Ar = Σ(Ar,i · wᵢ)；阴离子得电子故 e⁻ > Z。","steps":["氧元素相对原子质量：\\(A_r(\\mathrm{O}) = 15.994\\times 99.759\\% + 16.999\\times 0.037\\% + 17.999\\times 0.204\\%\\)。","分项求和：\\(15.95545 + 0.00629 + 0.03672 = 15.99846 \\approx 15.998\\)（保留三位小数/五位有效数字）。","对于 \\({}^{18}_{8}\\mathrm{O}^{2-}\\) 离子：质子数 \\(Z = 8\\)；中子数 \\(N = 18 - 8 = 10\\)；核外电子数 \\(= 8 + 2 = 10\\)。"],"ans":"Ar(O) = 15.998；¹⁸₈O²⁻ 含 8 个质子、10 个中子、10 个电子。","markingPoints":["正确列写加权平均算式（1分）","精确算得 15.998 且不带单位（2分）","正确给出 ¹⁸O²⁻ 的 p=8, n=10, e⁻=10（1分）"],"verification":"百分比和 \\(99.759\\% + 0.037\\% + 0.204\\% = 100.000\\%\\)，且结果极接近 15.999。","pitfall":"计算微小百分比 \\(0.037\\% = 0.00037\\) 时小数点错位，或把阴离子电子数误减 2 写成 6。"},{"id":"chem5-5.2-q4","tier":"L3","tierLabel":"L3 预试","examStyle":"P1 选择","q":"已知某阳离子 \\(\\mathrm{R}^{2+}\\) 核外有 \\(a\\) 个电子，核内有 \\(b\\) 个中子，则 \\(\\mathrm{R}\\) 原子的质量数与表示该核素的符号应为（　）。","options":["A. a + b − 2；ᵃ⁺ᵇ⁻²_ₐ₋₂ R","B. a + b + 2；ᵃ⁺ᵇ⁺²_ₐ₊₂ R","C. a + b；ᵃ⁺ᵇ_ₐ R","D. a + b + 2；ᵃ⁺ᵇ⁺²_ₐ R"],"correctOption":"B","given":"阳离子 R²⁺：电子数 = a，中子数 = b","method":"先由离子电子数还原质子数 Z，再求质量数 A = Z + N","principle":"R 失去 2 个电子形成 R²⁺，故 Z = e⁻ + 2。","steps":["中性 \\(\\mathrm{R}\\) 原子失去 2 个电子后剩 \\(a\\) 个电子，故原子质子数 \\(Z = a + 2\\)。","核内中子数不变，仍为 \\(b\\)，故质量数 \\(A = Z + b = a + b + 2\\)。","核素符号为 \\({}^{a+b+2}_{a+2}\\mathrm{R}\\)。"],"ans":"B","markingPoints":["先还原质子数 Z = a + 2 再求 A"],"verification":"代入具体例子如 ²⁴₁₂Mg²⁺（a=10, b=12）：Z=10+2=12，A=10+12+2=24，完全符合。","pitfall":"符号代入时误把阳离子减 2，写成 Z = a − 2。"},{"id":"chem5-5.2-q5","tier":"L4","tierLabel":"L4 统考压轴","examStyle":"P2 综合计算","q":"已知溴元素在自然界只有 \\({}^{79}\\mathrm{Br}\\)（\\(A_r \\approx 79\\)）和 \\({}^{81}\\mathrm{Br}\\)（\\(A_r \\approx 81\\)）两种稳定同位素，且测得溴元素的平均相对原子质量为 \\(79.9\\)；镁元素有 \\({}^{24}\\mathrm{Mg}\\)（占 \\(79.0\\%\\)）、\\({}^{25}\\mathrm{Mg}\\)（占 \\(10.0\\%\\)）和 \\({}^{26}\\mathrm{Mg}\\)（占 \\(11.0\\%\\)）三种同位素。试求：(1) 天然溴中 \\({}^{79}\\mathrm{Br}\\) 的原子百分比与质量百分比；(2) 若让天然镁与溴化合生成 \\(\\mathrm{MgBr_2}\\)，则所有可能的 \\(\\mathrm{MgBr_2}\\) 微粒中，化学式式量恰好为 \\(184\\) 的 \\(\\mathrm{MgBr_2}\\) 有哪几种核素组成（写出全部组合）？","given":"Ar(Br)=79.9（⁷⁹Br, ⁸¹Br）；Mg 同位素 24, 25, 26","method":"方程求原子百分比 → 乘质量数算质量百分比 → 不定方程枚举核素组合","principle":"同位素丰度定义；整数质量数满足 A(Mg) + A(Br₁) + A(Br₂) = 184。","steps":["第(1)问：设 \\({}^{79}\\mathrm{Br}\\) 原子百分比为 \\(x\\)，则 \\(79x + 81(1 - x) = 79.9 \\implies 2x = 1.1 \\implies x = 55.0\\%\\)，\\({}^{81}\\mathrm{Br}\\) 为 \\(45.0\\%\\)。","求 \\({}^{79}\\mathrm{Br}\\) 的质量百分比：\\(w_{\\text{质量}} = \\frac{55.0\\times 79}{55.0\\times 79 + 45.0\\times 81} = \\frac{4345}{7990} = 54.38\\%\\)。","第(2)问：两个 Br 的质量数之和只可能是 \\(79+79=158\\)、\\(79+81=160\\)、\\(81+81=162\\)。","要使 \\(A(\\mathrm{Mg}) + A(\\mathrm{Br_2}) = 184\\)，依次检验三种 \\(\\mathrm{Br_2}\\) 组合：若 \\(\\mathrm{Br_2}=158\\)，需 \\(A(\\mathrm{Mg})=26\\)（存在 \\({}^{26}\\mathrm{Mg}\\)！）；若 \\(\\mathrm{Br_2}=160\\)，需 \\(A(\\mathrm{Mg})=24\\)（存在 \\({}^{24}\\mathrm{Mg}\\)！）；若 \\(\\mathrm{Br_2}=162\\)，需 \\(A(\\mathrm{Mg})=22\\)（不存在）。","因此共有 **2 种**核素组成满足式量 184：\\({}^{26}\\mathrm{Mg}\\,{}^{79}\\mathrm{Br_2}\\) 与 \\({}^{24}\\mathrm{Mg}\\,{}^{79}\\mathrm{Br}\\,{}^{81}\\mathrm{Br}\\)。"],"ans":"(1) ⁷⁹Br 原子百分比 55.0%，质量百分比 54.38%；(2) 2 种组成：²⁶Mg⁷⁹Br₂ 和 ²⁴Mg⁷⁹Br⁸¹Br。","markingPoints":["正确解得 ⁷⁹Br 原子百分比 55.0%（1分）","区分原子与质量百分比算得 54.38%（2分）","穷举并正确找出两种满足总质量数 184 的核素组合（2分）"],"verification":"\\(26+79+79=184\\)，\\(24+79+81=184\\)，两组合均由天然存在核素构成。","pitfall":"第(1)问直接把 55.0% 当质量分数；第(2)问漏掉 ²⁶Mg + ⁷⁹Br₂ = 184 这一组合。"}],"cheatSheet":["核素符号 \\({}^{A}_{Z}\\mathrm{X}^{c}\\)：质子数 \\(= Z\\)，中子数 \\(= A - Z\\)，电子数 \\(= Z - c\\)（阴离子 \\(c<0\\) 反加）。","同位素：**同质子数、不同中子数**的原子（化学性质几乎相同）；氕 \\({}^{1}_{1}\\mathrm{H}\\) 无中子；\\(\\mathrm{D_2^{16}O}\\) 质子=中子=电子=10。","同位素平均 \\(A_r = \\sum A_{r,i}\\cdot x_i\\) 中的 \\(x_i\\) 是**原子个数百分比**（非质量百分比）。"],"kbEntryIds":["kb-chem5-z-a-isotope","kb-chem5-isotope-abundance"],"quiz":{"q":"天然镓（\\(\\mathrm{Ga}\\)）存在 \\({}^{69}\\mathrm{Ga}\\) 与 \\({}^{71}\\mathrm{Ga}\\) 两种同位素，平均相对原子质量为 \\(69.72\\)，求 \\({}^{69}\\mathrm{Ga}\\) 的天然原子百分比。","given":"A₁=69, A₂=71, Ar=69.72","method":"设丰度为 x 列加权平均方程","principle":"Ar = 69x + 71(1 − x)","steps":["\\(69x + 71(1-x) = 69.72 \\implies 2x = 1.28 \\implies x = 0.64 = 64\\%\\)。"],"ans":"\\(64\\%\\)"}},{"id":"5.3","t":"核外电子的能阶","anchor":{"pages":"化上 p.113–117","syllabus":"1.3.3 光谱与玻尔原子理论（能阶与电子跃迁）","examScopes":["sem1_final","pre_exam","sem2_final","uec"],"examWeight":"P1 光谱类型/跃迁能量判断 + P2 玻尔理论简答","terms":"wave-particle duality · continuous spectrum · line spectrum · energy level · excited state","prerequisites":["卢瑟福有核原子模型的稳定性与连续光谱悖论（5.1.3）","光的折射、频率、波长基本关系 c = λν"],"goals":["理解光的波粒二象性，并按波长/频率/能量大小排序常见电磁波谱。","区分白炽灯产生的连续光谱与气体原子发射的线光谱（以图 5-15 氢原子可见光区四条谱线为例）。","复述玻尔原子理论的三点假设，并用“能阶不连续”和“激发态向低能阶跃迁放出光子”解释线光谱的成因。"]},"concepts":[{"kind":"definition","title":"5.3.1–5.3.2 光的波粒二象性与连续光谱 vs 线光谱","pageRef":"化上 p.114–115","body":["**光的波粒二象性**：光既具有波的性质（可发生衍射、干涉、折射，具有波长 \\(\\lambda\\) 与频率 \\(\\nu\\)），又具有粒子的性质（光由一份份不连续的光子组成，单光子能量 \\(E = h\\nu = \\frac{hc}{\\lambda}\\)）。","**电磁波谱顺序（p.116–117 资料链接）**：波长由大到小（频率与光子能量由小到大）依次为：**无线电波 < 微波 < 红外线 < 可见光（红→橙→黄→绿→蓝→靛→紫）< 紫外线 < X 射线 < \\(\\gamma\\) 射线**。电磁波真空传播速度约为每秒 \\(30\\) 万千米（\\(3.0\\times 10^8\\text{ m/s}\\)）。","**连续光谱 vs 线光谱（图 5-14 & 5-15，p.115）**：白光（如白炽灯泡）含各种连续频率的光，经三棱镜折射后在感光纸上形成连续无间断的彩色带，称为**连续光谱**；而低压氢气放电管通高压电发光后经三棱镜分光，在暗背景上仅出现几条分立的彩色细线，称为**线光谱（原子光谱）**。不同元素拥有各自特征的线光谱（元素“指纹”）。"],"takeaway":"波长越短、频率越高、单光子能量越大（如紫光 \\(4.10\\times 10^{-7}\\text{ m}\\) 光子能量高于红光 \\(6.56\\times 10^{-7}\\text{ m}\\)）。"},{"kind":"law","title":"5.3.3 玻尔原子理论的三点核心假设（1913）","pageRef":"化上 p.115–116","body":["为解释氢原子线光谱的不连续性，丹麦物理学家玻尔（N. Bohr）把量子论引入原子结构，提出三点假设：","- **① 轨道量子化（定态）**：电子在原子核外只能在一定的符合条件的**轨道（orbit）**上运动；电子在这些定态轨道上运动时，**既不释放能量，也不吸收能量**（解决了“电子坠核”危机）。","- **② 能阶不连续**：在特定轨道上运动的电子具有特定能量，轨道离原子核越远，电子能量越高；由于轨道分布不连续，电子能量状态也不连续，形成了不同的**能阶（energy level）**。","- **③ 跃迁与光子辐射**：电子从低能阶向高能阶跃迁时，**必须吸收**恰好等于两能阶差值的能量；电子处于高能量的**激发态（excited state）**不稳定，向低能阶跃迁时会以**光辐射（光子）**的形式放出等于两能阶能量差的能量，该差值决定发射光的频率（\\(\\Delta E = h\\nu\\)）。"],"takeaway":"因为氢原子的能阶是分立的，各能阶之间的差值 \\(\\Delta E\\) 也只能取特定离散值，所以发射光只能对应特定频率——这就是**原子光谱呈线状而非连续**的根本原因。"},{"kind":"table","title":"氢原子可见光区四条特征线光谱数据（图 5-15）","pageRef":"化上 p.115","body":["教材图 5-15 给出了氢原子在可见光区的 4 条谱线（巴耳末系，均是电子从高能阶 \\(n \\ge 3\\) 跃迁回 \\(n=2\\) 所放出，另还有不可见的紫外区与红外区谱线）。"],"table":{"headers":["谱线颜色","波长 \\(\\lambda\\)（教材图 5-15）","能阶跃迁方向","能阶差 \\(\\Delta E\\) 与光子频率 \\(\\nu\\)"],"rows":[["红光","6.56 × 10⁻⁷ m（656 nm）","n = 3 → n = 2","四条中最小 ΔE，最低频率"],["绿（青）光","4.86 × 10⁻⁷ m（486 nm）","n = 4 → n = 2","次小 ΔE"],["蓝光","4.34 × 10⁻⁷ m（434 nm）","n = 5 → n = 2","较大 ΔE"],["紫光","4.10 × 10⁻⁷ m（410 nm）","n = 6 → n = 2","四条中最大 ΔE，最高频率"]]}}],"formulas":[{"title":"波速、波长与频率关系及光子能量（普朗克-爱因斯坦关系）","tex":"c = \\lambda \\nu,\\qquad E = h\\nu = \\frac{hc}{\\lambda}","plain":"c = λν；E = hν = hc / λ","conditions":"真空中 c ≈ 3.0×10⁸ m/s；波长 λ 与频率 ν、能量 E 成反比","pageRef":"化上 p.114–116","note":"能阶差 ΔE 越大，辐射出光子的频率 ν 越大、波长 λ 越短。"},{"title":"玻尔跃迁能量守恒条件","tex":"\\Delta E = |E_{\\text{高}} - E_{\\text{低}}| = h\\nu","plain":"ΔE = |E高 - E低| = hν","conditions":"吸能跃迁（低→高）需吸收正好等于 ΔE 的能量；放能跃迁（高→低）放出频率 ν 的光子","pageRef":"化上 p.116","note":"若入射光子能量不等于任意两能阶差值（且未达到电离能），电子不会吸收该光子。"}],"pitfalls":[{"title":"把“轨道离核越近能量越高”或把“低→高跃迁说成放光”弄反","wrong":"“电子从 \\(n=3\\) 轨道跃迁到 \\(n=1\\) 轨道时吸收能量，且 \\(n=1\\) 轨道能量高于 \\(n=3\\)。”","diagnosis":"电子带负电被正电核吸引，把电子拉开至离核更远的轨道必须做功，故外层轨道能量更高（均为负值，越往外越接近 0）。","right":"轨道离核越远，电子能量越**高**（\\(E_1 < E_2 < E_3 < \\cdots\\)）；**低→高吸能**（受激发），**高→低放光**（发射特征线光谱）。","checkRule":"记住口诀：“外高内低；上吸下放”。"},{"title":"把发射的紫光与红光的跃迁能量差大小搞反","wrong":"“氢原子发射红光时电子跃迁的能阶差比发射紫光时大，因为红光波长 \\(6.56\\times 10^{-7}\\text{ m}\\) 更大。”","diagnosis":"能量与频率成正比、与**波长成反比**（\\(\\Delta E = hc/\\lambda\\)）。","right":"紫光波长更短（\\(4.10\\times 10^{-7}\\text{ m}\\)），频率更高，对应的能阶差 \\(\\Delta E\\) **更大**（由 \\(n=6\\to 2\\) 跃迁）；红光波长最长，对应能阶差最小（\\(n=3\\to 2\\)）。","checkRule":"波长短 = 频率高 = 能量大。"}],"examples":[{"label":"例 5.3.1","tier":"L2","tierLabel":"L2 校内期末","title":"玻尔能阶跃迁吸放光与电磁波区域判断","prompt":"氢原子的基态能阶为 \\(n=1\\)，激发态依次为 \\(n=2, 3, 4, 5, \\dots\\)，已知相邻能阶之间的能量差随 \\(n\\) 增大而迅速减小（即 \\(E_2 - E_1 > E_3 - E_2 > E_4 - E_3\\)）。试回答：(1) 当电子从 \\(n=1\\) 跃迁至 \\(n=3\\) 时，是吸收还是放出能量？(2) 比较电子由 \\(n=2 \\to n=1\\)（放出一光子）与由 \\(n=3 \\to n=2\\)（放出一光子）所发射光波的频率和波长大小（提示：\\(n\\ge 2 \\to n=1\\) 属于紫外区，\\(n\\ge 3 \\to n=2\\) 属于可见光区）。","clues":"利用 E₁ < E₂ < E₃ 及 ΔE = hc/λ 判断。","strategy":"先定能量高低与能阶差 ΔE 大小，再换算频率 ν 和波长 λ。","given":"跃迁 A: 1→3；跃迁 B: 2→1；跃迁 C: 3→2","principle":"玻尔能阶跃迁条件 ΔE = hν = hc/λ。","steps":["(1) 由于离核越远轨道能量越高（\\(E_3 > E_1\\)），电子从低能阶 \\(n=1\\) 跃迁至高能阶 \\(n=3\\) 时**必须吸收能量**。","(2) 跃迁 \\(2\\to 1\\) 与 \\(3\\to 2\\) 均是从高能阶向低能阶回落，都会以光子形式放出能量。","比较能阶差：题目提示 \\(E_2 - E_1 > E_3 - E_2\\)（因紫外光光子能量高于可见光），故 \\(\\Delta E_{2\\to 1} > \\Delta E_{3\\to 2}\\)。","由 \\(\\Delta E = h\\nu = \\frac{hc}{\\lambda}\\) 可知：\\(2\\to 1\\) 辐射光子的**频率较高**、**波长较短**；而 \\(3\\to 2\\) 辐射的恰好是图 5-15 可见光区的红光（\\(6.56\\times 10^{-7}\\text{ m}\\)），频率较低、波长较长。"],"answer":"(1) 吸收能量；(2) n=2→1 发射光子频率较高、波长较短；n=3→2 频率较低、波长较长。","markingPoints":["正确判断 1→3 吸收能量（1分）","利用 ΔE₂₋₁ > ΔE₃₋₂ 得到频率 ν(2→1) > ν(3→2)（1分）","正确反推出波长 λ(2→1) < λ(3→2)（1分）"],"verification":"紫外光波长（约 122 nm）确实远短于可见红光（656 nm）。","pitfall":"若把“能量差大”错当成“波长长”，第(2)问波长大小关系会正好写反。"},{"label":"例 5.3.2","tier":"L3","tierLabel":"L3 预试拔高","title":"原子线光谱形成机制与焰色试验联系（为第9章铺垫）","prompt":"实验室做氢气放电管实验时观察到分立的四条可见光特征谱线，而白炽灯丝通电发光却观察到连续光谱。请用玻尔原子理论解释：(1) 为什么氢气放电管的线光谱不是连续的？(2) 若有一群氢原子被激发至 \\(n=4\\) 能阶，它们自发向低能阶跃迁时最多能辐射出多少种不同频率的光子？","clues":"任何两个不同能阶之间都能发生向下跃迁：从 4 个能阶中任选 2 个！","strategy":"第(1)问紧扣能阶不连续；第(2)问用组合数 C(4, 2) 枚举全部向下跃迁路径。","given":"白炽灯连续光谱 vs 氢放电管线光谱；最高激发能阶 n=4","principle":"原子能阶量子化；组合计数 C(n, 2)。","steps":["(1) 单个气态氢原子的核外电子只能处在能量分立、不连续的定态能阶上。当处于激发态的电子从较高能阶跃迁至较低能阶时，放出的光子能量等于两能阶能量差 \\(\\Delta E\\)，因能阶不连续，差值也是分立的特定数值，因此对应的光频率不连续，形成线光谱。","(2) 一群处于 \\(n=4\\) 能阶的氢原子向下跃迁的可能路径共有 \\(\\binom{4}{2} = \\frac{4\\times 3}{2} = 6\\) 条：","- 终态为 \\(n=1\\)（3 条）：\\(4\\to 1,\\; 3\\to 1,\\; 2\\to 1\\)；","- 终态为 \\(n=2\\)（2 条）：\\(4\\to 2\\)（绿光 \\(4.86\\times 10^{-7}\\text{ m}\\)）、\\(3\\to 2\\)（红光 \\(6.56\\times 10^{-7}\\text{ m}\\)）；","- 终态为 \\(n=3\\)（1 条）：\\(4\\to 3\\)（红外区）。","因各能阶差均互不相等，故最多可辐射出 **6 种**不同频率的光子（其中可见光有 2 条）。"],"answer":"(1) 原子能阶分布不连续导致跃迁能量差及发射光频率不连续；(2) 最多辐射 6 种不同频率的光子。","markingPoints":["准确指出“能阶不连续 → 能量差不连续 → 光频率不连续”（2分）","正确枚举或用 C(4,2) 算出 6 种光子频率（2分）"],"verification":"注意“一群氢原子”可同时走多条路径故为 C(4,2)=6；若是“1 个氢原子”从 n=4 逐级跃迁最多只有 3 条（4→3→2→1）。","pitfall":"把“一群原子”误按“1 个原子”只算成 3 条。"}],"practice":[{"id":"chem5-5.3-q1","tier":"L1","tierLabel":"L1 基础","examStyle":"P1 选择","q":"将下列各种常见现象产生的光通过三棱镜分光后，能够形成“线光谱”的是（　）。","options":["A. 太阳光","B. 炽热的钨丝白炽灯","C. 氢气放电管通高压电发出的光","D. 高温烧红的铁块发出的光"],"correctOption":"C","given":"连续光谱与线光谱区分（化上 p.114–115）","method":"区分固体/高压白光发射与稀薄气态原子发射","principle":"气态离散原子发光形成特征线光谱。","steps":["A、B、D 均产生各频率混合的连续光谱；C 为稀薄氢气原子激发跃迁发光，经三棱镜分光得到 4 条可见线光谱。"],"ans":"C","markingPoints":["记住教材图 5-14 与 5-15 对比"],"verification":"化上 p.115。","pitfall":"误以为太阳光也是纯粹线光谱（注：太阳表面吸收线是在连续背景上的暗线，高中基础主要考察白光连谱与氢管发射线谱对照）。"},{"id":"chem5-5.3-q2","tier":"L2","tierLabel":"L2 期末","examStyle":"P1 选择","q":"根据玻尔的原子结构理论，以下说法**错误**的是（　）。","options":["A. 电子在符合条件的定态轨道上绕核运动时，既不吸收也不释放能量","B. 离原子核越远的轨道，电子所具有的能量越高","C. 电子由高能阶轨道向低能阶轨道跃迁时，必须从外界吸收特定能量","D. 氢原子光谱的不连续性证明了原子内部能量变化是不连续的"],"correctOption":"C","given":"玻尔理论三点假设（化上 p.116）","method":"逐项比对玻尔三假设","principle":"高能阶 → 低能阶释放光子；低能阶 → 高能阶吸收能量。","steps":["A、B、D 均符合教材 p.116 玻尔理论原话；C 错，高→低跃迁是**放出**能量（光辐射），低→高跃迁才吸收能量。"],"ans":"C","markingPoints":["精准判断吸能与放能方向"],"verification":"化上 p.116 第③点。","pitfall":"粗心漏读“高能阶向低能阶”的方向。"},{"id":"chem5-5.3-q3","tier":"L2","tierLabel":"L2 期末","examStyle":"P1 选择","q":"下列电磁波按单光子能量由**小到大**排列，正确的是（　）。","options":["A. X 射线 < 紫外线 < 可见光 < 红外线","B. 红外线 < 红光 < 紫光 < 紫外线","C. 紫光 < 蓝光 < 绿光 < 红光","D. 微波 < X 射线 < 红外线 < γ 射线"],"correctOption":"B","given":"电磁波谱能量与波长顺序（化上 p.116–117）","method":"波长越短，频率越高，光子能量越大","principle":"E = hν = hc/λ","steps":["波长由长到短：无线电波 > 微波 > 红外线 > 红光 > 绿光 > 蓝光 > 紫光 > 紫外线 > X 射线 > γ 射线。","能量恰好完全相反，故红外线 < 红光 < 紫光 < 紫外线。"],"ans":"B","markingPoints":["把握红外—红—紫—紫外顺序"],"verification":"化上 p.115–117。","pitfall":"把波长排序与能量排序弄混。"},{"id":"chem5-5.3-q4","tier":"L3","tierLabel":"L3 预试","examStyle":"P2 简答","q":"观察教材图 5-15（氢原子可见光区线光谱）中的两条谱线：红光（\\(\\lambda_1 = 6.56\\times 10^{-7}\\text{ m}\\)）和紫光（\\(\\lambda_2 = 4.10\\times 10^{-7}\\text{ m}\\)）。(1) 哪一条谱线对应的电子跃迁能阶差 \\(\\Delta E\\) 较大？说明依据；(2) 已知电子从高能阶跃迁到 \\(n=2\\) 时才发射可见光（巴耳末系），那么红光与紫光分别对应从哪一个高能阶跃迁回 \\(n=2\\)（仅考虑 \\(n=3\\) 与 \\(n=6\\)）？(3) 为什么用激光（单色光）或白炽灯去研究时，不同元素总能凭借线光谱进行化学成分鉴别？","given":"λ(红)=6.56×10⁻⁷ m，λ(紫)=4.10×10⁻⁷ m","method":"ΔE = hc/λ 对比能量差；各元素核电荷与能阶结构独一无二","principle":"玻尔跃迁公式与元素特征光谱原理。","steps":["(1) 紫光对应的能阶差 \\(\\Delta E\\) 较大。依据：由 \\(\\Delta E = h\\nu = \\frac{hc}{\\lambda}\\) 可知，光子能量与波长成反比，紫光波长更短，频率与能量均大于红光。","(2) 因为 \\(E_6 - E_2 > E_3 - E_2\\)，所以能阶差较大的**紫光**对应 \\(n=6 \\to n=2\\)，能阶差较小的**红光**对应 \\(n=3 \\to n=2\\)。","(3) 每种元素原子核电荷数与核外电子排布均不同，拥有一套独一无二的能阶分布，因此电子跃迁发射的谱线波长组合具有唯一特征性（犹如“元素指纹”），可据此定性鉴别元素。"],"ans":"(1) 紫光 ΔE 较大（波长更短）；(2) 紫光 n=6→2，红光 n=3→2；(3) 不同元素能阶分布独特，线光谱犹如特征指纹。","markingPoints":["正确指出紫光 ΔE 大并写明波长反比依据（1分）","正确配对 n=6→2 和 n=3→2（1分）","说明不同元素能阶唯一导致线光谱具有特征性（2分）"],"verification":"对照化上 p.115 原文“不同的元素有不同特性的线光谱”核对。","pitfall":"第(2)问若直接背错或颠倒 \\(n=3\\) 与 \\(n=6\\) 对应关系会丢分。"},{"id":"chem5-5.3-q5","tier":"L4","tierLabel":"L4 统考拔高","examStyle":"P1 选择","q":"已知氢原子基态能量设为 \\(E_1 = -13.6\\text{ eV}\\)，第 \\(n\\) 能阶能量满足 \\(E_n = -\\frac{13.6}{n^2}\\text{ eV}\\)（\\(n=1,2,3,\\dots\\)）。现有一群处于基态（\\(n=1\\)）的氢原子，若用下列能量的光子分别去照射它们，能被基态氢原子吸收而发生跃迁的是（　）。","options":["A. 10.0 eV","B. 10.2 eV","C. 11.5 eV","D. 12.5 eV"],"correctOption":"B","given":"E₁ = -13.6 eV, E₂ = -3.4 eV, E₃ = -1.51 eV, E₄ = -0.85 eV","method":"计算从 n=1 跃迁到 n=2, 3, 4 所需的精确能量差 ΔE","principle":"玻尔量子化吸收规则：吸收光子能量必须恰好等于两能阶差。","steps":["计算各能阶能量：\\(E_1 = -13.6\\text{ eV}\\)；\\(E_2 = -13.6/4 = -3.40\\text{ eV}\\)；\\(E_3 = -13.6/9 = -1.51\\text{ eV}\\)；\\(E_4 = -13.6/16 = -0.85\\text{ eV}\\)。","所需跃迁能量差：\\(\\Delta E_{1\\to 2} = -3.40 - (-13.6) = 10.2\\text{ eV}\\)；\\(\\Delta E_{1\\to 3} = 12.09\\text{ eV}\\)；\\(\\Delta E_{1\\to 4} = 12.75\\text{ eV}\\)。","只有 **10.2 eV** 恰好等于 \\(n=1\\to 2\\) 的能阶差，其余能量不等于任何两定态差（且均小于电离能 13.6 eV），故不能被吸收。"],"ans":"B","markingPoints":["理解吸收光子的精确能量匹配要求"],"verification":"\\(13.6 \\times (1 - 1/4) = 13.6 \\times 0.75 = 10.2\\text{ eV}\\)。","pitfall":"误以为只要能量大于 10.2 eV 就能跃迁到 n=2（实际上电子运动只能接收刚好匹配的能量，除非 ≥13.6 eV 直接电离）。"}],"cheatSheet":["电磁波能量顺序：无线电波 < 微波 < 红外线 < 可见光（红→紫）< 紫外线 < X 射线 < γ 射线（波长越短，能量越大）。","连续光谱（白光）vs 线光谱（气态原子跃迁，“元素指纹”）。","玻尔三假设：定态不辐射 + 能阶不连续（外高内低） + 跃迁 \\(\\Delta E = h\\nu = hc/\\lambda\\)（上吸下放）。"],"kbEntryIds":["kb-chem5-bohr-spectrum"],"quiz":{"q":"氢原子电子从较高能阶 \\(E_a\\) 跃迁到较低能阶 \\(E_b\\) 时会释放出紫外线，而从 \\(E_c\\) 跃迁到 \\(E_b\\) 时会释放出红光，则 \\(E_a\\) 与 \\(E_c\\) 哪个能量更高？","given":"紫外光光子能量 > 可见红光光子能量；终点均为 Eb","method":"比较两次跃迁的 ΔE 大小","principle":"ΔE = E高 − E低 = hν","steps":["因紫外线能量大于红光，故 \\(E_a - E_b > E_c - E_b \\implies E_a > E_c\\)。"],"ans":"\\(E_a\\) 能量更高。"}},{"id":"5.4","t":"原子核外电子的排布","anchor":{"pages":"化上 p.118–126","syllabus":"1.3.4 电子云、原子轨域与核外电子排布规律","examScopes":["sem1_final","pre_exam","sem2_final","uec"],"examWeight":"全章分值最高节：P1/P2 必考电子排布式、轨域表示式、未成对电子与 Cr/Cu 特例","terms":"electron cloud · electron shell · subshell (s, p, d, f) · orbital · electron spin · Aufbau / Pauli / Hund","prerequisites":["能阶概念与玻尔氢原子理论局限（5.3）","元素周期表 1–36 号元素名称与原子序数"],"goals":["用电子云（几率密度）解释现代原子模型，掌握电子层（K–Q）、电子副层（s, p, d, f）形状/伸展方向与轨域容量公式（n² 与 2n²）。","熟记多电子原子轨域能量高低与能级交错次序（4s < 3d），正确书写 1–36 号基态原子与离子的电子排布式和轨域表示式。","准确运用能量最低原理、鲍利不相容原理、汉德规则及半充满/全充满稳定态，解释 K(4s¹)、Cr(3d⁵4s¹) 与 Cu(3d¹⁰4s¹) 的真实排布。"]},"concepts":[{"kind":"definition","title":"5.4.1–5.4.2 电子云、电子层、电子副层与自旋（表 5-5）","pageRef":"化上 p.118–122","body":["**电子云（electron cloud）**：电子质量极小、运动速度极快，不能像宏观物体那样同时测准位置和速度（测不准），只能用电子在核外空间各处出现的**几率密度**绘制图像——小黑点疏密表示几率大小，形象称为电子云。","**决定电子运动状态的四大方面（p.122）**：① **电子层（\\(n\\)）**：由内向外 \\(n=1,2,3,4,5,6,7\\) 对应符号 **K, L, M, N, O, P, Q**，能量随 \\(n\\) 增大而升高；② **电子副层（subshell）与形状**：\\(\\mathrm{s}\\) 呈球形、\\(\\mathrm{p}\\) 呈哑铃形、\\(\\mathrm{d}\\) 呈花瓣形、\\(\\mathrm{f}\\) 更复杂；③ **空间伸展方向（确定原子轨域 orbital）**：\\(\\mathrm{s}\\) 有 \\(1\\) 个方向，\\(\\mathrm{p}\\) 有 \\(3\\) 个互相垂直方向（\\(\\mathrm{p}_x, \\mathrm{p}_y, \\mathrm{p}_z\\)），\\(\\mathrm{d}\\) 有 \\(5\\) 个，\\(\\mathrm{f}\\) 有 \\(7\\) 个；④ **电子自旋（electron spin）**：顺时针与逆时针两种自旋状态（用 \\(\\uparrow\\) 和 \\(\\downarrow\\) 表示）。","**多电子原子轨域能量比较规律（p.122）**：① 同电子层：\\(n\\mathrm{s} < n\\mathrm{p} < n\\mathrm{d} < n\\mathrm{f}\\)；② 同形状：\\(1\\mathrm{s} < 2\\mathrm{s} < 3\\mathrm{s} < 4\\mathrm{s} < \\dots\\)；③ 同层同副层（如 \\(2\\mathrm{p}_x, 2\\mathrm{p}_y, 2\\mathrm{p}_z\\)）能量相等（简并轨域）。"],"table":{"headers":["电子层 (n)","包含电子副层","各副层轨域数","该层轨域总数 (n²)","最多容纳电子数 (2n²)"],"rows":[["K (n = 1)","1s","1","1","2"],["L (n = 2)","2s, 2p","1, 3","4","8"],["M (n = 3)","3s, 3p, 3d","1, 3, 5","9","18"],["N (n = 4)","4s, 4p, 4d, 4f","1, 3, 5, 7","16","32"]]},"takeaway":"把“电子层+形状+伸展方向”唯一确定为一个**原子轨域**（如 \\(2\\mathrm{p}_x\\)），再加自旋方向（\\(\\uparrow\\) 或 \\(\\downarrow\\)）就唯一确定一个电子的运动状态——同一原子内不存在运动状态完全相同的两个电子。"},{"kind":"law","title":"5.4.3 核外电子排布三大规律与能级交错","pageRef":"化上 p.123–125","body":["**① 能量最低原理（基态 ground state）与能阶交错（图 5-23 & 5-24）**：电子总是尽量先占据能量最低的轨域，使整个原子能量最低。在多电子原子中，其他电子排斥削弱了核对最外层电子的吸引，导致从第 3 层起出现**能阶交错**：\\(E(4\\mathrm{s}) < E(3\\mathrm{d})\\)（同理 \\(5\\mathrm{s} < 4\\mathrm{d}\\)，\\(6\\mathrm{s} < 4\\mathrm{f} < 5\\mathrm{d}\\)）。因此 \\({}_{19}\\mathrm{K}\\) 排完 \\(3\\mathrm{p}^6\\) 后先填 \\(4\\mathrm{s}^1\\) 而非 \\(3\\mathrm{d}^1\\)！完整次序为：\\(1\\mathrm{s}\\to 2\\mathrm{s}\\to 2\\mathrm{p}\\to 3\\mathrm{s}\\to 3\\mathrm{p}\\to 4\\mathrm{s}\\to 3\\mathrm{d}\\to 4\\mathrm{p}\\to 5\\mathrm{s}\\to 4\\mathrm{d}\\to 5\\mathrm{p}\\to 6\\mathrm{s}\\dots\\)。","**② 鲍利不相容原理（Pauli exclusion principle）**：**每一个轨域最多只能排布 2 个电子，且同一轨域中的两个电子自旋方向必然相反**（记作 `[↑↓]`）。","**③ 汉德规则（Hund's rule）**：原子核外电子在能量相同的各个轨域（简并轨域，如 3 个 \\(2\\mathrm{p}\\) 或 5 个 \\(3\\mathrm{d}\\) 轨域）中排布时，**尽可能分占不同的轨域，且自旋方向相同**（如碳的 \\(2\\mathrm{p}^2\\) 为 `[↑ ][↑ ][  ]`，氮的 \\(2\\mathrm{p}^3\\) 为 `[↑ ][↑ ][↑ ]`）。"],"takeaway":"三种规律各司其职：能量最低定“**填哪个副层顺序**”，鲍利定“**一格最多 2 个且反自旋**”，汉德定“**简并方框先单占同向**”。"},{"kind":"mechanism","title":"电子排布式、轨域表示式与 Cr/Cu 特殊稳定态","pageRef":"化上 p.125–126","body":["**表示方法（表 5-6）**：① **电子排布式**：如 \\({}_{6}\\mathrm{C}: 1\\mathrm{s}^2 2\\mathrm{s}^2 2\\mathrm{p}^2\\)；原子序数较大时可用稀有气体原子实简写，如 \\({}_{21}\\mathrm{Sc}: [\\mathrm{Ar}]\\,3\\mathrm{d}^1 4\\mathrm{s}^2\\)（注意书写时习惯按主量子数 \\(n\\) 由小到大将 \\(3\\mathrm{d}\\) 写在 \\(4\\mathrm{s}\\) 前，尽管填充顺序是先 \\(4\\mathrm{s}\\) 后 \\(3\\mathrm{d}\\)）；② **轨域表示式（方框图）**：用方框表示每个轨域，箭头表示电子自旋。","**特殊稳定态（半充满、全充满、全空）**：对于同一电子副层，当排布为**全充满（\\(\\mathrm{p}^6, \\mathrm{d}^{10}, \\mathrm{f}^{14}\\)）、半充满（\\(\\mathrm{p}^3, \\mathrm{d}^5, \\mathrm{f}^7\\)）或全空（\\(\\mathrm{p}^0, \\mathrm{d}^0, \\mathrm{f}^0\\)）**时，电子云分布呈对称，体系能量最低、最稳定。","**两大必背特例（p.125–126）**：","- **\\({}_{24}\\mathrm{Cr}\\)（铬）**：不是 \\([\\mathrm{Ar}]3\\mathrm{d}^4 4\\mathrm{s}^2\\)，而是 **\\([\\mathrm{Ar}]\\,3\\mathrm{d}^5 4\\mathrm{s}^1\\)**（\\(3\\mathrm{d}\\) 半充满 + \\(4\\mathrm{s}\\) 半充满，共有 **6 个**未成对电子！教材 p.131 第 5(4) 题原题）。","- **\\({}_{29}\\mathrm{Cu}\\)（铜）**：不是 \\([\\mathrm{Ar}]3\\mathrm{d}^9 4\\mathrm{s}^2\\)，而是 **\\([\\mathrm{Ar}]\\,3\\mathrm{d}^{10} 4\\mathrm{s}^1\\)**（\\(3\\mathrm{d}\\) 全充满 + \\(4\\mathrm{s}\\) 半充满，只有 **1 个**未成对电子）。"],"takeaway":"教材特别提醒（p.126）：排布规律只是实验总结的近似规律，实际原子核外电子排布一律以**光谱实验测定结果**为准！"}],"formulas":[{"title":"第 n 电子层轨域数与最大容纳电子数公式","tex":"N_{\\text{轨域}}(n) = n^2,\\qquad N_{e,\\max}(n) = 2n^2","plain":"第 n 层轨域数 = n²；最多容纳电子数 = 2n²","conditions":"单个电子层理论容量（各副层容量 s:2, p:6, d:10, f:14）","pageRef":"化上 p.121 表 5-5","note":"切勿和“最外层电子数最多不超过 8（K 层不超过 2）”混淆——例如 M 层最多可容 18 个电子，但它作为最外层时不能超过 8 个（因 4s 先于 3d 填充）。"},{"title":"能量最低原理填充序列与 Cr / Cu 特例排布式","tex":"1\\mathrm{s} < 2\\mathrm{s} < 2\\mathrm{p} < 3\\mathrm{s} < 3\\mathrm{p} < 4\\mathrm{s} < 3\\mathrm{d} < 4\\mathrm{p},\\qquad {}_{24}\\mathrm{Cr}: 1\\mathrm{s}^2 2\\mathrm{s}^2 2\\mathrm{p}^6 3\\mathrm{s}^2 3\\mathrm{p}^6 3\\mathrm{d}^5 4\\mathrm{s}^1","plain":"1s < 2s < 2p < 3s < 3p < 4s < 3d < 4p；Cr: [Ar]3d⁵4s¹；Cu: [Ar]3d¹⁰4s¹","conditions":"基态原子；形成过渡金属阳离子时先失 4s 再失 3d","pageRef":"化上 p.123–125","note":"例如 Fe²⁺ 为 [Ar]3d⁶（非 [Ar]3d⁴4s²），Fe³⁺ 为 [Ar]3d⁵（3d 半满极稳！）。"}],"pitfalls":[{"title":"过渡金属失电子时错先失去 3d 电子而保留 4s²","wrong":"“\\({}_{26}\\mathrm{Fe}\\) 是 \\([\\mathrm{Ar}]3\\mathrm{d}^6 4\\mathrm{s}^2\\)，所以失去 2 个电子形成 \\(\\mathrm{Fe}^{2+}\\) 应变成 \\([\\mathrm{Ar}]3\\mathrm{d}^4 4\\mathrm{s}^2\\)。”","diagnosis":"填电子时因能阶交错先填 \\(4\\mathrm{s}\\)；但一旦 \\(3\\mathrm{d}\\) 也有电子后，\\(4\\mathrm{s}\\) 处于更外层（\\(n=4\\) 离核更远，能量反而高于已收缩的 \\(3\\mathrm{d}\\)），故电离时必然先失去最外层 \\(4\\mathrm{s}\\) 电子！","right":"\\({}_{26}\\mathrm{Fe}^{2+}\\) 为 **\\([\\mathrm{Ar}]3\\mathrm{d}^6\\)**，\\({}_{26}\\mathrm{Fe}^{3+}\\) 为 **\\([\\mathrm{Ar}]3\\mathrm{d}^5\\)**（\\(\\mathrm{Fe}^{3+}\\) 有 5 个未成对电子且 \\(3\\mathrm{d}\\) 半满，因此比 \\(\\mathrm{Fe}^{2+}\\) 更稳定）；\\({}_{29}\\mathrm{Cu}^{2+}\\) 为 **\\([\\mathrm{Ar}]3\\mathrm{d}^9\\)**。","checkRule":"牢记口诀：“先填 4s 再填 3d；**先失 4s 再失 3d**！”"},{"title":"将电子云形状当成电子运动轨迹，或算错 Cr 的未成对电子数","wrong":"“电子云图表示电子沿哑铃形或球形轨道绕核画圈，且 \\({}_{24}\\mathrm{Cr}\\) 只有 4 个未成对电子。”","diagnosis":"电子云是统计**几率密度**而非真实路径；Cr 因半满稳定态把 1 个 \\(4\\mathrm{s}\\) 电子激发进 \\(3\\mathrm{d}\\)，使 \\(3\\mathrm{d}^5\\) 与 \\(4\\mathrm{s}^1\\) 皆全单占！","right":"电子云反映电子在核外空间出现几率大小；\\({}_{24}\\mathrm{Cr}\\) 为 \\([\\mathrm{Ar}]3\\mathrm{d}^5 4\\mathrm{s}^1\\)，共有 \\(5 + 1 = 6\\) 个未成对电子（1–36 号元素中未成对电子数最多！）。","checkRule":"遇到 Cr 问未成对电子数：5(3d) + 1(4s) = **6**，绝不是 4！"},{"title":"把简并轨域写反自旋或提前成对","wrong":"“氮原子 \\(2\\mathrm{p}^3\\) 排成 `[↑↓][↑ ][  ]`，或者 `[↑ ][↓ ][↑ ]`。”","diagnosis":"前者违背汉德规则“尽可能分占不同轨域”；后者违背汉德规则“分占时自旋方向相同”。","right":"氮原子 \\(2\\mathrm{p}^3\\) 必须分占 \\(2\\mathrm{p}_x, 2\\mathrm{p}_y, 2\\mathrm{p}_z\\) 三个轨域且自旋平行：`[↑ ][↑ ][↑ ]`。","checkRule":"填完方框后检查两遍：有没有能分开却挤在一起的？单占箭头的方向是不是一致？"}],"examples":[{"label":"例 5.4.1","tier":"L2","tierLabel":"L2 校内期末","title":"教材思考题 5d & 习题 4–7 综合：排布式、电子层与未成对电子","prompt":"(1) 写出 \\({}_{15}\\mathrm{P}\\) 原子的完整电子排布式与轨域表示式，并指出其未成对电子数与共有多少种能量不同的电子？(2) 核电荷数为 \\(19\\) 的钾（\\(\\mathrm{K}\\)）元素原子的核外电子排布为什么是 \\(1\\mathrm{s}^2 2\\mathrm{s}^2 2\\mathrm{p}^6 3\\mathrm{s}^2 3\\mathrm{p}^6 4\\mathrm{s}^1\\)，而不是 \\(1\\mathrm{s}^2 2\\mathrm{s}^2 2\\mathrm{p}^6 3\\mathrm{s}^2 3\\mathrm{p}^6 3\\mathrm{d}^1\\)？(3) 某基态原子核外共有 4 个电子层，最外层有 2 个电子（教材 p.131 第 7 题），请写出所有原子序数 \\(Z \\le 30\\) 中满足条件的原子符号（提示：考虑第 4 周期 s 区与 d 区）。","clues":"1 个副层代表 1 种能量；4 个电子层最外层 2e⁻ 除 Ca (4s²) 外，Sc–Zn 大部分也是 3dⁿ4s²（排除 Cr 与 Cu）！","strategy":"逐层统计电子副层种类与方框单占数；第(3)问别漏了过渡金属！","given":"P (Z=15)；K (Z=19)；4个电子层且最外层=2e⁻ (Z≤30)","principle":"能量最低原理（能级交错）、鲍利原理、汉德规则与半满/全满特例。","steps":["第(1)问：\\({}_{15}\\mathrm{P}\\) 电子排布式为 \\(1\\mathrm{s}^2 2\\mathrm{s}^2 2\\mathrm{p}^6 3\\mathrm{s}^2 3\\mathrm{p}^3\\)。共有 \\(1\\mathrm{s}, 2\\mathrm{s}, 2\\mathrm{p}, 3\\mathrm{s}, 3\\mathrm{p}\\) **5 种**能量不同的电子（3 个 3p 轨域能量相等）；\\(3\\mathrm{p}^3\\) 依汉德规则分占 3 个 3p 轨域且自旋平行，故有 **3 个**未成对电子。","第(2)问：在多电子原子中，由于电子间的相互排斥削弱了原子核对外层电子的吸引，出现**能阶交错现象**，使得 \\(4\\mathrm{s}\\) 轨域的能量低于 \\(3\\mathrm{d}\\) 轨域。根据**能量最低原理**，第 19 个电子优先填入能量更低的 \\(4\\mathrm{s}\\) 轨域（实验光谱也证实 K 为 \\(4\\mathrm{s}^1\\)）。","第(3)问：第 4 周期（\\(Z=19\\sim 36\\)）共有 4 个电子层。在 \\(Z\\le 30\\) 中，最外层即 N 层（\\(4\\mathrm{s}\\) 电子）：\\({}_{20}\\mathrm{Ca}\\)（\\(4\\mathrm{s}^2\\)）符合；过渡元素 \\({}_{21}\\mathrm{Sc}\\sim {}_{30}\\mathrm{Zn}\\) 一般为 \\(3\\mathrm{d}^{1\\sim 10}4\\mathrm{s}^2\\)，唯独 \\({}_{24}\\mathrm{Cr}\\)（\\(3\\mathrm{d}^54\\mathrm{s}^1\\)）与 \\({}_{29}\\mathrm{Cu}\\)（\\(3\\mathrm{d}^{10}4\\mathrm{s}^1\\)）最外层只有 1 个电子。故满足条件的元素有：**\\(\\mathrm{Ca, Sc, Ti, V, Mn, Fe, Co, Ni, Zn}\\)** 共 9 种！"],"answer":"(1) 1s²2s²2p⁶3s²3p³，3 个未成对电子，5 种不同能量电子；(2) 因能阶交错 E(4s)<E(3d) 及能量最低原理；(3) Ca, Sc, Ti, V, Mn, Fe, Co, Ni, Zn。","markingPoints":["正确写出 P 排布式并区分“5 种能量”与“9 个轨域 / 15 种运动状态”（2分）","准确点明能阶交错 E(4s) < E(3d) 及能量最低原理（1分）","第(3)问能想到过渡金属且正确剔除 Cr 和 Cu（2分）"],"verification":"对照化上 p.126 思考题 5d 第 4 题与 p.131 第 7 题核对。","pitfall":"第(3)问若只写 Ca 忽略了 3dⁿ4s² 的 8 种过渡金属，或误把 Cr、Cu 也算进去，都会扣分。"},{"label":"例 5.4.2","tier":"L4","tierLabel":"L4 统考压轴","title":"1–36 号原子与离子电子结构综合推断（运动状态、未成对电子与稳定态）","prompt":"有 \\(\\mathrm{A, B, C, D, E}\\) 五种原子序数依次增大的前四周期（\\(Z\\le 36\\)）元素：\\(\\mathrm{A}\\) 原子的核外电子共有 6 种不同的运动状态；\\(\\mathrm{B}\\) 原子最外层 p 副层呈半充满状态且只存在 2 个电子层；\\(\\mathrm{C}\\) 元素 \\(+3\\) 价阳离子与 \\(\\mathrm{Ne}\\) 具有相同电子层结构；\\(\\mathrm{D}\\) 基态原子拥有前四周期中**最多的未成对电子数**；\\(\\mathrm{E}\\) 原子 M 层全充满、N 层仅有 1 个电子。试推断这五种元素并回答：(1) 写出 \\(\\mathrm{D}\\) 原子的简写电子排布式与 \\(\\mathrm{D}^{3+}\\) 离子的电子排布式；(2) 写出 \\(\\mathrm{E}\\) 的元素符号、基态电子排布式，并解释 \\(\\mathrm{E}^+\\) 离子在水中常不稳定易歧化或被氧化为 \\(\\mathrm{E}^{2+}\\) 的原因（结合第 5 章排布与第 16 章思考）；(3) \\(\\mathrm{A}\\) 与 \\(\\mathrm{B}\\) 基态原子各自有多少个空轨域？","clues":"电子运动状态数 = 电子总数（鲍利原理）；前四周期未成对电子最多是 Cr（6 个）；M 层全满 3s²3p⁶3d¹⁰ 即 18 个电子！","strategy":"逐个破译结构线索，核对 Cr 和 Cu 的电子数、轨域数和离子排布。","given":"A: 6种状态；B: 2层、2p半满；C³⁺ 与 Ne 等电子；D: 最多未成对电子；E: M全满+N=1","principle":"电子运动状态唯一性、汉德规则、半满/全满特例及 4s 先电离规则。","steps":["推断元素：\\(\\mathrm{A}\\) 有 6 个电子 ⇒ \\({}_{6}\\mathrm{C}\\)（\\(1\\mathrm{s}^2 2\\mathrm{s}^2 2\\mathrm{p}^2\\)）；\\(\\mathrm{B}\\) 为 2 层 \\(2\\mathrm{p}^3\\) 半满 ⇒ \\({}_{7}\\mathrm{N}\\)（\\(1\\mathrm{s}^2 2\\mathrm{s}^2 2\\mathrm{p}^3\\)）；\\(\\mathrm{C}^{3+}\\) 有 10e⁻ ⇒ \\({}_{13}\\mathrm{Al}\\)；\\(\\mathrm{D}\\) 具有前四周期最多未成对电子（6 个）⇒ \\({}_{24}\\mathrm{Cr}\\)（\\([\\mathrm{Ar}]3\\mathrm{d}^5 4\\mathrm{s}^1\\)）；\\(\\mathrm{E}\\) 的 K(2), L(8), M(18), N(1) 共 29 个电子 ⇒ \\({}_{29}\\mathrm{Cu}\\)（\\([\\mathrm{Ar}]3\\mathrm{d}^{10} 4\\mathrm{s}^1\\)）。","(1) \\(\\mathrm{D}\\;({}_{24}\\mathrm{Cr})\\) 简写电子排布式为 \\([\\mathrm{Ar}]\\,3\\mathrm{d}^5 4\\mathrm{s}^1\\)；失去 3 个电子（先失 \\(4\\mathrm{s}^1\\)，再失 2 个 \\(3\\mathrm{d}\\)）得 \\(\\mathrm{Cr}^{3+}\\): **\\([\\mathrm{Ar}]\\,3\\mathrm{d}^3\\)**。","(2) \\(\\mathrm{E}\\) 为 **\\(\\mathrm{Cu}\\)**，基态排布为 \\(1\\mathrm{s}^2 2\\mathrm{s}^2 2\\mathrm{p}^6 3\\mathrm{s}^2 3\\mathrm{p}^6 3\\mathrm{d}^{10} 4\\mathrm{s}^1\\)（或 \\([\\mathrm{Ar}]3\\mathrm{d}^{10}4\\mathrm{s}^1\\)）；\\(\\mathrm{Cu}^+\\) 为 \\([\\mathrm{Ar}]3\\mathrm{d}^{10}\\)（全满，气态稳定），而在水溶液中 \\(\\mathrm{Cu}^{2+}\\)（\\([\\mathrm{Ar}]3\\mathrm{d}^9\\)）具有更高电荷密度与水合能而更稳定。","(3) \\({}_{6}\\mathrm{C}\\)（\\(1\\mathrm{s}^2 2\\mathrm{s}^2 2\\mathrm{p}^2\\)）的 \\(2\\mathrm{p}\\) 三个轨域中有 2 个半占，剩 **1 个**空轨域；\\({}_{7}\\mathrm{N}\\)（\\(1\\mathrm{s}^2 2\\mathrm{s}^2 2\\mathrm{p}^3\\)）的 \\(2\\mathrm{p}\\) 三个轨域各占 1 个电子，故有 **0 个**空轨域。"],"answer":"A=C, B=N, C=Al, D=Cr, E=Cu；(1) Cr: [Ar]3d⁵4s¹, Cr³⁺: [Ar]3d³；(2) Cu: [Ar]3d¹⁰4s¹；(3) C 有 1 个空轨域，N 有 0 个空轨域。","markingPoints":["全部正确推出 A–E 五种元素（2分）","正确写出 Cr 简写排布与 Cr³⁺ 先失 4s 后得 [Ar]3d³（1分）","正确写出 Cu 全满特例排布（1分）","按汉德规则数出 C(1) 与 N(0) 的空轨域数（1分）"],"verification":"M 层有 3s(2)+3p(6)+3d(10)=18 个电子，加 K(2)+L(8)+N(1) 恰为 29 号 Cu。","pitfall":"误把 N 算成 1 个空轨域（忽略汉德规则，错把 2p³ 填成 `[↑↓][↑][ ]`）。"}],"practice":[{"id":"chem5-5.4-q1","tier":"L1","tierLabel":"L1 基础","examStyle":"P1 选择","q":"原子核外 M 层（\\(n=3\\)）所包含的原子轨域总数和最多可容纳的电子数分别是（　）。","options":["A. 3 和 6","B. 4 和 8","C. 9 和 18","D. 16 和 32"],"correctOption":"C","given":"M 层（n = 3）","method":"代入公式：轨域数 = n²，最大电子数 = 2n²","principle":"M 层含 3s(1)、3p(3)、3d(5) 共 9 个轨域，每轨域容 2 电子。","steps":["\\(n=3\\) 时，轨域总数 \\(= 3^2 = 9\\)，最多容纳电子数 \\(= 2\\times 3^2 = 18\\)。"],"ans":"C","markingPoints":["熟记表 5-5 的 n² 与 2n² 规律"],"verification":"1 + 3 + 5 = 9；2 + 6 + 10 = 18。","pitfall":"把 M 层（n=3）误当成最外层最多 8 个电子。"},{"id":"chem5-5.4-q2","tier":"L2","tierLabel":"L2 期末","examStyle":"P1 选择","q":"下列基态原子的核外电子排布式或轨域表示式中，书写**正确**的是（　）。","options":["A. ₁₉K：1s² 2s² 2p⁶ 3s² 3p⁶ 3d¹","B. ₂₄Cr：[Ar] 3d⁴ 4s²","C. ₂₉Cu：[Ar] 3d¹⁰ 4s¹","D. ₈O 的 2p 轨域：[↑↓][↑↓][  ]"],"correctOption":"C","given":"K, Cr, Cu, O 电子排布","method":"依次核对能量最低、半满全满特例与汉德规则","principle":"能级交错 4s < 3d；Cr 3d⁵4s¹；Cu 3d¹⁰4s¹；汉德规则先单占。","steps":["A 错：K 应为 4s¹（E(4s) < E(3d)）；B 错：Cr 应为 3d⁵4s¹（半满更稳）；C 对：Cu 为 [Ar]3d¹⁰4s¹（全满更稳）；D 错：O 的 2p⁴ 依汉德规则应为 `[↑↓][↑ ][↑ ]`。"],"ans":"C","markingPoints":["识别四大排布正误"],"verification":"化上 p.124–126。","pitfall":"误选 A 或 B。"},{"id":"chem5-5.4-q3","tier":"L2","tierLabel":"L2 期末","examStyle":"P2 简答","q":"(1) 用稀有气体核心简写写出 \\({}_{26}\\mathrm{Fe}\\) 与 \\({}_{26}\\mathrm{Fe}^{3+}\\) 的电子排布式；(2) 写出 \\({}_{17}\\mathrm{Cl}\\) 原子的核外电子排布式，并比较 \\({}_{7}\\mathrm{N}\\)、\\({}_{14}\\mathrm{Si}\\)、\\({}_{12}\\mathrm{Mg}\\)、\\({}_{24}\\mathrm{Cr}\\) 四种基态原子的未成对电子数大小（教材 p.131 第 5 题）。","given":"Fe(26), Fe³⁺, Cl(17), N(7), Si(14), Mg(12), Cr(24)","method":"先排原子的 4s 与 3d，阳离子先失 4s；逐一画出价层方框数未成对电子","principle":"三大排布规律与 d⁵/d¹⁰ 稳定态。","steps":["(1) \\({}_{26}\\mathrm{Fe}\\): \\([\\mathrm{Ar}]\\,3\\mathrm{d}^6 4\\mathrm{s}^2\\)；失去 3 个电子（先失 \\(4\\mathrm{s}^2\\)，再失 1 个 \\(3\\mathrm{d}\\)）得 \\(\\mathrm{Fe}^{3+}\\): **\\([\\mathrm{Ar}]\\,3\\mathrm{d}^5\\)**。","(2) \\({}_{17}\\mathrm{Cl}\\): \\(1\\mathrm{s}^2 2\\mathrm{s}^2 2\\mathrm{p}^6 3\\mathrm{s}^2 3\\mathrm{p}^5\\)。","统计未成对电子数：\\(\\mathrm{Mg}\\)（\\(3\\mathrm{s}^2\\)）有 **0** 个；\\(\\mathrm{Si}\\)（\\(3\\mathrm{p}^2\\)）有 **2** 个；\\(\\mathrm{N}\\)（\\(2\\mathrm{p}^3\\)）有 **3** 个；\\(\\mathrm{Cr}\\)（\\(3\\mathrm{d}^5 4\\mathrm{s}^1\\)）有 **6** 个。顺序：\\(\\mathrm{Cr}(6) > \\mathrm{N}(3) > \\mathrm{Si}(2) > \\mathrm{Mg}(0)\\)。"],"ans":"(1) Fe: [Ar]3d⁶4s², Fe³⁺: [Ar]3d⁵；(2) Cl: 1s²2s²2p⁶3s²3p⁵；未成对电子 Cr(6) > N(3) > Si(2) > Mg(0)。","markingPoints":["正确写出 Fe 与 Fe³⁺ 排布式（2分）","正确写出 Cl 排布式（1分）","准确求出 Mg(0), Si(2), N(3), Cr(6) 未成对电子数并排序（2分）"],"verification":"化上 p.131 第 5 题原题核对。","pitfall":"把 Fe³⁺ 错写成 [Ar]3d³4s² 或把 Cr 未成对电子误算为 4。"},{"id":"chem5-5.4-q4","tier":"L3","tierLabel":"L3 预试","examStyle":"P1 选择","q":"碳原子的核外电子排布写成 `1s:[↑↓]  2s:[↑↓]  2p:[↑ ][↑ ][  ]`，而不是 `1s:[↑↓]  2s:[↑↓]  2p:[↑↓][  ][  ]`。决定这一排布方式的是（　）。","options":["A. 仅由鲍利不相容原理决定","B. 仅由能级交错规律决定","C. 汉德规则（简并轨域分占且自旋平行）","D. 半充满特殊稳定态"],"correctOption":"C","given":"碳原子 2p² 两种排布方式对比（化上 p.124 交流分享）","method":"定位发生分歧的是同一 2p 副层的不同轨域分布","principle":"汉德规则规定能量相同的轨域应先分占且自旋相同。","steps":["两者均满足能量最低（都填在 2p）和鲍利原理（无同自旋挤入一格）；唯一区别在于 2p 两个电子是“挤一格”还是“分占不同 2p 轨域且同向”，这正是汉德规则。"],"ans":"C","markingPoints":["精准辨别三大原理各自控制的维度"],"verification":"化上 p.124 交流分享原型题。","pitfall":"误选 A 鲍利不相容原理。"},{"id":"chem5-5.4-q5","tier":"L4","tierLabel":"L4 统考压轴","examStyle":"P2 综合探究","q":"下表是 1–36 号某四种常见基态原子的结构特征信息：\n- 甲：最外层电子数是次外层电子数的 3 倍；\n- 乙：第三电子层上有 3 个未成对电子；\n- 丙：第四周期元素，其 \\(3\\mathrm{d}\\) 副层恰好半充满而 \\(4\\mathrm{s}\\) 副层全充满；\n- 丁：第四周期元素，基态原子共有 2 个未成对电子且原子序数大于 25。\n请回答：(1) 写出甲、乙、丙、丁的元素符号；(2) 比较丙（\\(\\mathrm{Mn}\\) 型 vs \\(\\mathrm{Cr}\\) 型）与相邻元素 \\(\\mathrm{Cr}\\) 的 \\(3\\mathrm{d}\\) 电子数及未成对电子数；(3) 写出丁元素可能的所有基态电子排布式（在 \\(25 < Z \\le 36\\) 范围内逐一排查）。","given":"甲最外层=3×次外层；乙第3层3个单电子；丙 3d⁵4s²；丁 Z>25 且 2 个未成对电子","method":"由内而外限定电子层结构；对 26–36 号元素逐一检查 d/p 未成对电子数","principle":"核外电子排布规律及 3d/4p 未成对电子计数。","steps":["(1) **甲**：次外层必为 K 层（2e⁻），最外层为 6e⁻ ⇒ **O**（\\(1\\mathrm{s}^2 2\\mathrm{s}^2 2\\mathrm{p}^4\\)）；**乙**：M 层未成对电子为 3 的是 \\(3\\mathrm{s}^2 3\\mathrm{p}^3\\) ⇒ **P**（注：第 4 周期的 V 虽是 3d³，但第 3 层仅在原子不完整时才算；若只看 3 层原子为 **P**）；**丙**：\\(3\\mathrm{d}^5 4\\mathrm{s}^2\\) ⇒ **Mn**（\\(Z=25\\)）；","(2) \\(\\mathrm{Mn}\\)（\\([\\mathrm{Ar}]3\\mathrm{d}^5 4\\mathrm{s}^2\\)）有 5 个 3d 电子、**5 个**未成对电子；\\(\\mathrm{Cr}\\)（\\([\\mathrm{Ar}]3\\mathrm{d}^5 4\\mathrm{s}^1\\)）同样有 5 个 3d 电子，但有 **6 个**未成对电子。","(3) 排查 \\(26\\le Z\\le 36\\) 中有 **2 个**未成对电子的元素：","- \\(Z=26\\;\\mathrm{Fe}\\)（\\(3\\mathrm{d}^6 4\\mathrm{s}^2\\)）：4 个未成对；\\(Z=27\\;\\mathrm{Co}\\)（\\(3\\mathrm{d}^7 4\\mathrm{s}^2\\)）：3 个未成对；","- **\\(Z=28\\;\\mathrm{Ni}\\)**（\\(3\\mathrm{d}^8 4\\mathrm{s}^2\\)）：\\(3\\mathrm{d}\\) 呈 `[↑↓][↑↓][↑↓][↑ ][↑ ]` ⇒ **2 个未成对**（符合！）；","- \\(Z=29\\;\\mathrm{Cu}\\)：1 个；\\(Z=30\\;\\mathrm{Zn}\\)：0 个；\\(Z=31\\;\\mathrm{Ga}\\)（\\(4\\mathrm{p}^1\\)）：1 个；","- **\\(Z=32\\;\\mathrm{Ge}\\)**（\\(4\\mathrm{p}^2\\)）：\\(4\\mathrm{p}\\) 呈 `[↑ ][↑ ][  ]` ⇒ **2 个未成对**（符合！）；","- \\(Z=33\\;\\mathrm{As}\\)（\\(4\\mathrm{p}^3\\)）：3 个；**\\(Z=34\\;\\mathrm{Se}\\)**（\\(4\\mathrm{p}^4\\)）：\\(4\\mathrm{p}\\) 呈 `[↑↓][↑ ][↑ ]` ⇒ **2 个未成对**（符合！）；\\(\\mathrm{Br}\\)：1 个；\\(\\mathrm{Kr}\\)：0 个。","因此丁可能是 **\\(\\mathrm{Ni}, \\mathrm{Ge}, \\mathrm{Se}\\)** 三种之一。"],"ans":"(1) 甲 O, 乙 P, 丙 Mn, 丁 Ni/Ge/Se；(2) 均为 5 个 3d 电子，未成对数 Mn=5, Cr=6；(3) Ni: [Ar]3d⁸4s²; Ge: [Ar]3d¹⁰4s²4p²; Se: [Ar]3d¹⁰4s²4p⁴。","markingPoints":["正确推出甲 O、乙 P、丙 Mn（2分）","准确对比 Mn 与 Cr 的 3d 电子与未成对电子数（1分）","完整排查并找出 28号 Ni、32号 Ge、34号 Se 三种可能性（2分）"],"verification":"d⁸ 与 p²、p⁴ 依汉德规则均恰好剩 2 个单电子。","pitfall":"第(3)问只写出 Ni 而遗漏了 p 区的 Ge（4p²）与 Se（4p⁴）。"}],"cheatSheet":["电子云（几率密度）非轨迹；副层容量：s(1格2e⁻)、p(3格6e⁻)、d(5格10e⁻)、f(7格14e⁻)；第 \\(n\\) 层轨域 \\(n^2\\)、最多 \\(2n^2\\)。","三大排布规律：**能量最低**（能级交错 \\(4\\mathrm{s}<3\\mathrm{d}\\)）+ **鲍利不相容**（1 格最多 2 个相反自旋）+ **汉德规则**（简并先单占同向）。","两大必考特例：**\\({}_{24}\\mathrm{Cr}: [\\mathrm{Ar}]3\\mathrm{d}^5 4\\mathrm{s}^1\\)**（6 个单电子），**\\({}_{29}\\mathrm{Cu}: [\\mathrm{Ar}]3\\mathrm{d}^{10} 4\\mathrm{s}^1\\)**（1 个单电子）；阳离子**先失 4s 再失 3d**。"],"kbEntryIds":["kb-chem5-orbitals-subshells","kb-chem5-config-rules"],"quiz":{"q":"写出 \\({}_{29}\\mathrm{Cu}\\) 原子与 \\({}_{29}\\mathrm{Cu}^{2+}\\) 离子的简写电子排布式，并指出两者各自有多少个未成对电子。","given":"Z = 29，d 副层全充满稳定态","method":"先用特例写 Cu，再按先失 4s 后失 3d 得 Cu²⁺","principle":"Cu 3d¹⁰4s¹ 全充满稳态；过渡离子先电离最外层 4s。","steps":["\\(\\mathrm{Cu}\\): \\([\\mathrm{Ar}]3\\mathrm{d}^{10}4\\mathrm{s}^1\\)（4s¹ 为 **1 个**未成对电子）。","失去 2 个电子（先失 4s¹，再失 1 个 3d）得 \\(\\mathrm{Cu}^{2+}\\): \\([\\mathrm{Ar}]3\\mathrm{d}^9\\)（3d⁹ 中 4 对成对、**1 个**未成对电子）。"],"ans":"Cu: \\([\\mathrm{Ar}]3\\mathrm{d}^{10}4\\mathrm{s}^1\\)（1个单电子）；Cu²⁺: \\([\\mathrm{Ar}]3\\mathrm{d}^9\\)（1个单电子）。"},"diagrams":[{"src":"assets/fig/v2/chem05-energy-levels.svg","caption":"图 5-1 氢原子玻尔能阶跃迁与多电子能级交错排布及 Cr/Cu 特例示意图","alt":"玻尔能阶跃迁与电子填充顺序图","pageRef":"化上 p.115–125"}]}]},"化学6":{"lessonKey":"化学6","courseCode":"chemistry","subject":"化学","chapter":6,"title":"元素周期表","syllabus":"1.4 元素周期表","bookId":"sm1-chemistry-2017","bookCitation":"《马来西亚华文独中教科书 · 化学（上册）》（2017年11月版）第6章 p.133–160","examScopes":["sem1_final","pre_exam","sem2_final","uec"],"chapterOverview":{"summary":"第6章把第5章的核外电子排布规律系统映射为“元素周期表”的二维坐标系：先回顾德贝莱纳、迈耳至门捷列夫发现元素周期律的历史演进，再剖析现行长式周期表的“7周期 + 18纵列 + s/p/d/f 四分区”结构，最终聚焦元素五大基本性质（原子/离子半径、第一电离能与逐级电离能、电负性、金属性/非金属性）的周期性递变与半满/全满反常峰，是贯穿无机元素化学（第9–16章）的“总导航图”。","conceptTree":[{"branch":"6.1 元素周期表的发展简史（p.134–137）","items":["德贝莱纳“三元素组”（1829）· 迈耳“六元素表”与原子体积曲线（1864–1868）","门捷列夫（1869）按 Ar 编排 63 种元素与留空预言 → 现代以核电荷数 Z 为本质基准"]},{"branch":"6.2 元素周期表的结构（p.137–140）","items":["7 个周期：短周期（2,8,8）+ 长周期（18,18,32,32）；镧系/锕系（内过渡元素）与超铀元素","18 纵列 16 族：8 主族（典型元素）+ 7 副族 + 第 VIIIB 族（8,9,10 三列）；周期=层数，主族=最外层电子数"]},{"branch":"6.3 解读元素周期表与性质递变（p.140–151）","items":["元素周期律与电子构型四大分区：s 区（2列）、p 区（6列）、d 区（10列）、f 区","原子半径 & 离子半径（含等电子体 Z 越大半径越小）","第一电离能 I₁（含 IIA>IIIA、VA>VIA 反常）与逐级电离能突跃判最高氧化数","电子亲和能、鲍林电负性（F=4.0）与金属性/非金属性递变"]}]},"paperFocus":["高三上半年期末考（Ch 3–8, Ch 26–30）：第6章是 P1 和 P2 必考“周期表片段位—构—性推理题”的直接出题区（直接对应教材 p.159–160 第 6、7 题型），尤其常考半径大小排序、I₁ 反常解释与逐级电离能突跃判断主族。","预试 / 毕业考 / UEC 统考：常与第5章电子排布、第7章电负性差判键型及第9–16章无机化合物酸碱性/氧化性联动命题（占 P1 约 2–4 题 + P2 必答题核心小问）。"],"solvingWorkflow":["位—构互推第一步：由电子排布式定周期序数（最大主量子数 n = 电子层数）和族序数（主族看最外层电子数，d 区看 (n-1)d + ns 总和或特例）。","比微粒半径三步口诀：① 先比电子层数（层多半径大）；② 层数同看核电荷数 Z（Z 大半径小，适用同周期原子与等电子体离子）；③ 同元素看电荷（阴离子 > 原子 > 阳离子）。","比第一电离能 I₁：先用大趋势（左→右增大，下→上增大），再检查是否踩中 **IIA vs IIIA**（如 Mg > Al, Be > B）与 **VA vs VIA**（如 P > S, N > O）两大反常陷阱！","读逐级电离能表（I₁, I₂, I₃…）：找相邻两级电离能数值突然暴增（通常 >3–5 倍）的“断层”，突跃前的电子数即为价电子数 / 常见正氧化数 / 主族序数。"],"questionTypes":["周期表局部方格中字母元素的定位、分区（s/p/d/f）与电子排布式推导","微粒半径大小排序（如 O²⁻, F⁻, Na⁺, Mg²⁺, Al³⁺ 等电子体与同主族/同周期混排）","第一电离能曲线图判读与 Mg>Al / P>S（或 Be>B / N>O）反常原因简答","逐级电离能数据表判断元素所属主族、价电子数及与卤素/氧所成化合物化学式","电负性、金属性/非金属性、最高价氧化物对应水化物酸碱性综合比较"],"scoringNotes":["解释“等电子体离子半径变化（如 Na⁺ < F⁻）”时，必须明确写全两点：“两离子具有相同的电子层结构（电子层数相同），Na⁺ 核电荷数更大，原子核对核外电子的吸引力更强，因此半径更小”。","解释“Mg 的 I₁ 大于 Al”或“P 的 I₁ 大于 S”时，必须点出对应外围电子构型（Mg 为 3s² 全充满；P 为 3s²3p³ 半充满），说明“全满/半满结构能量较低、较稳定，失去电子需要更多能量”。"],"vid":[{"t":"元素周期表结构与 s/p/d/f 四大分区","q":"元素周期表 结构 分区 s p d f 高中化学"},{"t":"原子半径与等电子体离子半径大小比较","q":"原子半径 离子半径 等电子体 比较 化学"},{"t":"第一电离能变化规律、半满全满反常与逐级电离能","q":"第一电离能 逐级电离能 突跃 反常 高中化学"},{"t":"电负性与元素金属性非金属性递变","q":"电负性 金属性 非金属性 元素周期律"}],"sections":[{"id":"6.1","t":"元素周期表的发展简史","anchor":{"pages":"化上 p.134–137","syllabus":"1.4.1 元素周期表的历史演变与本质基准","examScopes":["sem1_final","pre_exam","sem2_final","uec"],"examWeight":"P1 科学史概念题 + 周期律本质辨析","terms":"Dobereiner's triads · Meyer · Mendeleev · atomic number","prerequisites":["相对原子质量 Ar 与原子序数 Z（核电荷数）的区别（Ch 3 & Ch 5）","元素性质相似性的初步概念"],"goals":["简述德贝莱纳“三元素组”和迈耳“六元素表”在元素分类史上的探索与局限。","阐明 1869 年门捷列夫元素周期表的排列依据、科学预言价值（如留空位）及其历史局限。","指出引起元素性质周期性变化的根本原因（不是相对原子质量，而是核电荷数即核外电子排布的周期性变化）。"]},"concepts":[{"kind":"definition","title":"6.1.1 早期元素组合探索：三元素组与六元素表","pageRef":"化上 p.134–135","body":["**德贝莱纳的“三元素组”（1829，图 6-1）**：德国化学家德贝莱纳把性质相似的元素三人一组，归纳出 5 个“三元素组”（`Li-Na-K`、`Ca-Sr-Ba`、`P-As-Sb`、`S-Se-Te`、`Cl-Br-I`），并发现中间元素的相对原子质量约等于首尾两元素的算术平均值（如 \\(\\mathrm{Na}\\approx (7+39)/2=23\\)）。局限：大量元素无法纳入三元素组。","**迈耳的“六元素表”与原子体积曲线（1864–1868，图 6-2）**：德国化学家迈耳按原子量递增将性质相似的元素六个一组分族，并在 1868 年发表原子体积—原子量曲线图，展示出明显的周期波峰（碱金属）和波谷规律。"],"takeaway":"早期分类只覆盖局部元素或偏重物理体积曲线，尚未形成统领全部元素的完整二维周期表。"},{"kind":"law","title":"6.1.2 门捷列夫与第一张元素周期表（1869）","pageRef":"化上 p.136","body":["**门捷列夫的核心贡献**：1869 年俄国化学家门捷列夫总结规律——“元素（以及由它所形成的单质和化合物）的性质随着**相对原子质量**的递增而呈现周期性变化”，据此将当时已知的 **63 种元素**全部列入表中发表第一张元素周期表。","**胆识与科学方法**：门捷列夫敢于打破机械排序——为把性质相似的元素排入同一族，他果断在表中**留出空位**并成功预言了未知元素（如“类铝”镓、“类硼”钪、“类硅”锗）的相对原子质量与化合物性质，且修正了若干测错的原子量。"],"takeaway":"门捷列夫的伟大之处在于“以化学性质周期性为主导，大胆留空预言新元素”。"},{"kind":"mechanism","title":"从“相对原子质量”到“核电荷数（原子序数）”的本质飞跃","pageRef":"化上 p.136","body":["**门捷列夫的历史局限**：受当时科技限制（尚未发现质子、电子层和原子序数），门捷列夫无法解释“为什么性质会随相对原子质量呈周期性变化”，也难以解释个别“原子量倒挂”现象（如 \\({}_{18}\\mathrm{Ar}=39.95 > {}_{19}\\mathrm{K}=39.10\\)，\\({}_{52}\\mathrm{Te}=127.6 > {}_{53}\\mathrm{I}=126.9\\)）。","**20 世纪现代修正**：随着原子结构研究深入，科学家发现引起元素性质周期性变化的**本质原因**不是相对原子质量递增，而是**核电荷数（原子序数）的递增**，即**原子核外电子排布的周期性变化**。"],"takeaway":"现代元素周期表的编排规则：**电子层数相同**的元素按原子序数递增从左到右排成横行（周期）；**最外层电子数相同**（主族）的元素按电子层数递增从上到下排成纵列（族）。"}],"formulas":[{"title":"德贝莱纳三元素组相对原子质量经验均值","tex":"A_r(\\text{中间元素}) \\approx \\frac{A_r(\\text{首元素}) + A_r(\\text{尾元素})}{2}","plain":"中间元素 Ar ≈ (首元素 Ar + 尾元素 Ar) / 2","conditions":"仅作 1829 年历史经验估算（如 Cl 35.5, I 127 → 均值 81.25 ≈ Br 80）","pageRef":"化上 p.134","note":"并非严格物理定律，后期被更全面的周期律取代。"},{"title":"周期律因果逻辑链","tex":"\\text{核电荷数 }Z\\text{ 递增} \\implies \\text{核外电子排布周期性变化} \\implies \\text{元素性质周期性变化}","plain":"核电荷数 Z 递增 ⇒ 核外电子排布周期性变化 ⇒ 元素性质周期性变化","conditions":"适用整个现代元素周期表（解释 Ar/K、Te/I 原子量倒挂）","pageRef":"化上 p.136","note":"性质呈周期性变化的根本原因（本质）是核外电子排布的周期性。"}],"pitfalls":[{"title":"误以为现代元素周期表仍按“相对原子质量”递增排列","wrong":"“现行元素周期表中，同一周期元素一定严格按照相对原子质量由小到大排列。”","diagnosis":"门捷列夫 1869 年用相对原子质量，但有些相邻元素因中子数较多导致质量反超（如 Ar 39.95 > K 39.10；Te 127.6 > I 126.9；Co 58.93 > Ni 58.69）。","right":"现行元素周期表严格按照**原子序数（核电荷数）**由小到大排列，从而自动使性质相近的元素精准对齐。","checkRule":"遇到元素周期表排序依据，一律选“原子序数 / 核电荷数”，不选“相对原子质量”。"},{"title":"混淆周期律的“直接原因”与“外部表现”","wrong":"“元素性质呈现周期性变化的本质原因是元素原子半径随原子序数呈现周期性变化。”","diagnosis":"原子半径、电离能、化合价等都是周期性的**结果与表现**，而不是**本质原因**。","right":"元素性质呈现周期性变化的本质（根本）原因是**原子核外电子排布（特别是最外层电子排布）的周期性变化**。","checkRule":"问“本质/根本原因”必答“核外电子排布的周期性变化”。"}],"examples":[{"label":"例 6.1.1","tier":"L2","tierLabel":"L2 校内期末","title":"门捷列夫周期表的科学预言与“原子量倒挂”解释","prompt":"1869 年门捷列夫在发表第一张元素周期表时曾将已知的碘（\\(A_r=126.9\\)）排在碲（\\(A_r=127.6\\)）的后面，并在铝（\\(\\mathrm{Al}\\)）下方留下空位命名为“类铝”。请回答：(1) 门捷列夫为什么要冒着违背自己“按相对原子质量递增”原则的风险，把碘放在碲的后面？(2) 现代原子结构理论如何完美证明门捷列夫把碲排在碘前面是完全正确的？(3) 后来发现的“类铝”是哪一种元素？门捷列夫的探索过程给我们什么科学启示（思考题 6a）？","clues":"查看碲（Te, Z=52）与碘（I, Z=53）在族中的位置及质子数。","strategy":"结合第5章原子序数与第6章同族性质相似性作答。","given":"Te (Z=52, Ar=127.6) vs I (Z=53, Ar=126.9)；类铝 Ga","principle":"化学性质由核电荷数（质子数）和最外层电子数决定，而非中子数与相对原子质量。","steps":["(1) 因为碘在化学性质上明显与氯、溴相似（均为卤素，易形成 \\(-1\\) 价盐），而碲的性质与氧、硫、硒相似（均为 \\(-2\\) 价与 \\(+6\\) 价）。为了使性质相似的元素归入同一族，门捷列夫判断当时的相对原子质量可能有误或有例外，坚持按化学性质将碲放 VIA 族、碘放 VIIA 族。","(2) 20 世纪确定原子序数 \\(Z\\) 后查明：\\(\\mathrm{Te}\\) 质子数为 **52**（最外层 6 个电子），\\(\\mathrm{I}\\) 质子数为 **53**（最外层 7 个电子）。\\(\\mathrm{Te}\\) 相对原子质量略高仅仅是因为其高丰度同位素（\\({}^{128}\\mathrm{Te},{}^{130}\\mathrm{Te}\\)）中子数较多。按原子序数递增编排，\\(\\mathrm{Te}\\)（52）天然排在 \\(\\mathrm{I}\\)（53）之前！","(3) “类铝”即为 1875 年法国化学家布瓦博德朗发现的**镓（\\(\\mathrm{Ga}\\)）**。启示：科学规律的发现需要前人积累与订正（德贝莱纳、迈耳到门捷列夫），要尊重客观实验性质而非教条套用早期规则，同时理论随科技（原子内部结构发现）而不断深化修正。"],"answer":"(1) 为了保持同族元素化学性质的相似性；(2) Te 的原子序数（52）小于 I（53），Te 质量较大仅因中子数多；(3) 镓（Ga）；启示为尊重事实、敢于假设预言并在科学发展中修正本质。","markingPoints":["指出依据化学性质归族（1分）","点明 Te(Z=52) < I(Z=53) 及中子数影响 Ar（2分）","答出“镓 (Ga)”并给出合理科学启示（1分）"],"verification":"周期表第 5 周期 52 号 Te 确在 53 号 I 左侧。","pitfall":"第(2)问若仅答“当时测错了碘的相对原子质量”，其实并不是测错，而是天然碲确实比天然碘重。"},{"label":"例 6.1.2","tier":"L3","tierLabel":"L3 预试拔高","title":"周期律编排规则与原子序数关系推导","prompt":"科学家按“电子层数相同按 \\(Z\\) 递增排成横行，最外层电子数相同排成纵列”构建周期表。(1) 已知氩（\\({}_{18}\\mathrm{Ar}, A_r=39.95\\)）和钾（\\({}_{19}\\mathrm{K}, A_r=39.10\\)），请分别写出它们的电子排布式并说明为什么钾必须排在下一周期第一格而不能接在氩同一周期？(2) 根据德贝莱纳“三元素组”法（图 6-1），若已知 \\({}_{20}\\mathrm{Ca}\\)（\\(A_r=40.1\\)）与 \\({}_{56}\\mathrm{Ba}\\)（\\(A_r=137.3\\)），试估算中间元素锶（\\(\\mathrm{Sr}\\)）的相对原子质量，并与实际值 \\(87.6\\) 比较误差。","clues":"K 的第 19 个电子进入 4s 轨域（第 4 电子层）。","strategy":"第(1)问从电子层数跃升至第 4 层解答；第(2)问套用三元素组平均值公式。","given":"₁₈Ar, ₁₉K；Ca(40.1), Ba(137.3), Sr(实际 87.6)","principle":"能级交错导致 K 开启新周期；算术平均估算。","steps":["(1) \\({}_{18}\\mathrm{Ar}\\): \\(1\\mathrm{s}^2 2\\mathrm{s}^2 2\\mathrm{p}^6 3\\mathrm{s}^2 3\\mathrm{p}^6\\)（共 3 个电子层，最外层 8 电子，排第 3 周期末位 VIIIA 族）；\\({}_{19}\\mathrm{K}\\): \\(1\\mathrm{s}^2 2\\mathrm{s}^2 2\\mathrm{p}^6 3\\mathrm{s}^2 3\\mathrm{p}^6 4\\mathrm{s}^1\\)（共 **4 个电子层**，最外层 1 电子，故必须另起第 4 周期且归入 IA 族）。","(2) 德贝莱纳估算值：\\(A_r(\\mathrm{Sr}) \\approx \\frac{40.1 + 137.3}{2} = 88.7\\)。与实际值 \\(87.6\\) 仅相差 \\(1.1\\)（相对误差约 \\(1.26\\%\\)），在 19 世纪初期极具启发意义。"],"answer":"(1) K 具有 4 个电子层且最外层为 4s¹，故进入第 4 周期 IA 族；(2) 估算 88.7，仅差 1.1。","markingPoints":["正确写出 Ar 与 K 电子排布式并点明 K 有 4 个电子层（2分）","算得 Sr 估算值 88.7 及偏差 1.1（2分）"],"verification":"化上 p.134 图 6-1 确包含 Ca-Sr-Ba 三元素组。","pitfall":"第(1)问只说“钾是金属、氩是稀有气体”，未从电子排布的层数与最外层电子数角度说明。"}],"practice":[{"id":"chem6-6.1-q1","tier":"L1","tierLabel":"L1 基础","examStyle":"P1 选择","q":"1869 年发表第一张元素周期表、把当时已知的 63 种元素纳入表中的科学家是（　）。","options":["A. 德贝莱纳","B. 门捷列夫","C. 莫斯莱","D. 迈耳"],"correctOption":"B","given":"元素周期表发展简史（化上 p.134–136）","method":"人物与年代/成果一一对应","principle":"门捷列夫于 1869 年发表第一张元素周期表。","steps":["德贝莱纳(1829)三元素组；迈耳(1864)六元素表；门捷列夫(1869)第一张元素周期表（63 种元素）；莫斯莱(1913)确立原子序数。"],"ans":"B","markingPoints":["识记门捷列夫 1869 年及 63 种元素"],"verification":"化上 p.136。","pitfall":"混淆德国化学家迈耳（1864/1868）与门捷列夫（1869）。"},{"id":"chem6-6.1-q2","tier":"L2","tierLabel":"L2 期末","examStyle":"P1 选择","q":"现代化学认为，引起元素性质呈现周期性变化的本质原因是（　）。","options":["A. 元素相对原子质量的周期性递增","B. 原子核内中子数的周期性变化","C. 原子核电荷数递增引起核外电子排布的周期性变化","D. 元素化合价和原子半径的周期性变化"],"correctOption":"C","given":"元素周期律本质（化上 p.136）","method":"区分本质原因（结构）与宏观结果（性质）","principle":"结构决定性质：核外电子排布的周期性变化决定元素性质周期性变化。","steps":["A 是门捷列夫早期认识，已被修正；B 中子数不影响化学性质周期律；D 是结果而非原因；C 正确。"],"ans":"C","markingPoints":["明确本质原因是核电荷数递增与核外电子排布周期性变化"],"verification":"化上 p.136 原文。","pitfall":"误选 A 或 D。"},{"id":"chem6-6.1-q3","tier":"L2","tierLabel":"L2 期末","examStyle":"P2 简答","q":"为什么说德贝莱纳的“三元素组”（1829）和门捷列夫的元素周期表（1869）既体现了科学研究的继承性，又体现了科学理论的可修正性？请各举一项史实说明。","given":"6.1 元素周期表发展简史","method":"分别列举“继承相似分类思想”与“由 Ar 修正为 Z”的史实","principle":"科学在继承经验规律并随微观结构认识深入而自我修正中发展。","steps":["**继承性**：德贝莱纳首次发现性质相似元素的相对原子质量存在递变关联（如 Cl, Br, I），迈耳按原子量递增分族，门捷列夫正是在前人工作基础上订正、分析与概括，才建立起涵盖当时全部 63 种元素的周期表。","**可修正性**：门捷列夫以相对原子质量递增为基础，无法从理论上解释为何 Ar/K、Te/I 会出现原子量倒挂；直到 20 世纪原子内部核电荷数（原子序数）与核外电子排布规律发现后，周期表的排列基准成功修正为“核电荷数递增”。"],"ans":"继承性体现为从三元素组、六元素表到周期表的族分类思想一脉相承；可修正性体现为编排基准从门捷列夫的相对原子质量修正为现代核电荷数（电子排布）。","markingPoints":["给出继承性史实（2分）","给出从相对原子质量修正为原子序数的史实（2分）"],"verification":"化上 p.134–136。","pitfall":"回答过于空泛，缺少具体人物或物理量名词。"},{"id":"chem6-6.1-q4","tier":"L3","tierLabel":"L3 预试","examStyle":"P1 选择","q":"在下列门捷列夫当年曾面对的元素顺序中，若机械地按“相对原子质量由小到大”排列会与现行周期表位置颠倒的一组是（　）。","options":["A. 氮和氧","B. 钠和镁","C. 碲和碘","D. 氯和溴"],"correctOption":"C","given":"常见相对原子质量：N(14), O(16); Na(23), Mg(24.3); Te(127.6), I(126.9); Cl(35.5), Br(79.9)","method":"检索教材重点讨论的原子量倒挂对","principle":"Ar(₅₂Te) = 127.6 > Ar(₅₃I) = 126.9。","steps":["只有 C 选项中的碲（52 号，127.6）相对原子质量反而大于紧邻其后的碘（53 号，126.9）。"],"ans":"C","markingPoints":["熟记 Ar/K、Co/Ni、Te/I 三对经典倒挂"],"verification":"对照标准元素周期表原子量核对。","pitfall":"对 Te 与 I 相对原子质量不熟而瞎猜。"},{"id":"chem6-6.1-q5","tier":"L4","tierLabel":"L4 统考拔高","examStyle":"P1 选择","q":"1871 年门捷列夫根据“类硅（eka-silicon）”在周期表中的位置，成功预言了它的相对原子质量约为 72、密度约 5.5 g/cm³、氧化物为 \\(\\mathrm{XO_2}\\)。1886 年德国化学家温克勒发现该元素并命名为锗（Ge，\\(A_r=72.6\\)）。门捷列夫之所以能如此精准地预言“类硅”，根本依据在于（　）。","options":["A. 当时已经通过 X 射线测出了锗的原子序数 32","B. 同主族（IVA 族）元素的核外最外层电子数相同，性质随周期递增呈规律性递变","C. 门捷列夫直接用质谱仪测定了锗的同位素丰度","D. 所有元素都符合德贝莱纳“三元素组”的严格算术平均关系"],"correctOption":"B","given":"“类硅”Ge 在 IVA 族介于 Si 与 Sn 之间","method":"识别“同一纵列性质相似递变”与时代技术边界","principle":"同主族元素构型相似、性质呈规律递变（现代解释即最外层电子数相同）；1871 年尚无 X 射线定序和质谱仪。","steps":["A 错：莫斯莱 X 射线定原子序数是 1913 年的事；C 错：质谱仪发明于 20 世纪初；D 错：三元素组仅粗略经验公式；B 正确揭示了周期表“同族垂直内插”的科学原理。"],"ans":"B","markingPoints":["排除时代错位技术并定位同主族递变规律"],"verification":"化上 p.136。","pitfall":"忽略历史时间线错选 A。"}],"cheatSheet":["简史三步：德贝莱纳（1829 三元素组）→ 迈耳（1864 六元素表）→ **门捷列夫（1869，63种元素，按 Ar 排并留空预言 Ga/Sc/Ge）**。","现代基准：按**核电荷数（原子序数 Z）**递增排列；性质周期性变化的本质原因是**核外电子排布的周期性变化**。","记住周期表三对“原子量倒挂”（但序数正常）：\\({}_{18}\\mathrm{Ar}(39.95)>{}_{19}\\mathrm{K}(39.10)\\)、\\({}_{27}\\mathrm{Co}>{}_{28}\\mathrm{Ni}\\)、\\({}_{52}\\mathrm{Te}>{}_{53}\\mathrm{I}\\)。"],"kbEntryIds":["kb-chem6-history-mendeleev"],"quiz":{"q":"如果某一未知元素排在第 4 周期 IVA 族（碳、硅下方，锡上方），它的核外电子层数与最外层电子数分别是多少？","given":"第 4 周期 IVA 族","method":"周期序数 = 电子层数；主族序数 = 最外层电子数","principle":"现代元素周期表排布原则（p.136–138）。","steps":["第 4 周期 ⇒ 4 个电子层；IVA 族 ⇒ 最外层 4 个电子（即 ₃₂Ge）。"],"ans":"4 个电子层，最外层 4 个电子。"}},{"id":"6.2","t":"元素周期表的结构","anchor":{"pages":"化上 p.137–140","syllabus":"1.4.2 周期与族的划分、短长周期容量与元素定位","examScopes":["sem1_final","pre_exam","sem2_final","uec"],"examWeight":"P1 周期/族/原子序数换算题必考节","terms":"short period · long period · lanthanides · actinides · transuranium elements · main group · subgroup","prerequisites":["1–36 号电子排布与电子层容量 2, 8, 18, 32（Ch 5.4）","稀有气体元素符号与原子序数（He 2, Ne 10, Ar 18, Kr 36, Xe 54, Rn 86, Og 118）"],"goals":["熟记 7 个周期的分类（1–3 短周期 2/8/8；4–7 长周期 18/18/32/32）以及镧系、锕系（内过渡元素）和超铀元素的位置。","准确区分周期表的 18 个纵列与 16 个族（8 主族 A、7 副族 B 与占 8,9,10 三列的第 VIIIB 族），区分典型元素与过渡元素。","掌握原子序数与周期、族序数的快速互推方法（含同主族上下周期序数差规律）。"]},"concepts":[{"kind":"table","title":"6.2.1 七个周期的容量、短长周期与内过渡元素","pageRef":"化上 p.138","body":["元素周期表共有 **7 个横行（周期）**，其**周期序数 = 该周期元素原子的核外电子层数**。","- **短周期（第 1–3 周期）**：分别含有 **2、8、8** 种元素；","- **长周期（第 4–7 周期）**：分别含有 **18、18、32、32** 种元素（2016 年 IUPAC 确认 113、115、117、118 号元素后，第 7 周期已完全填满）。","- **镧系、锕系与超铀元素**：第 6、7 周期各有 **15 种**电子层结构和性质极相似的元素（分别称为**镧系元素**和**锕系元素**），合称**内过渡元素（inner transition elements）**，在周期表中各占同一格并另列于表下方；锕系中铀（U, \\(Z=92\\)）后面的元素多由人工核反应制得，称为**超铀元素（transuranium elements）**。"],"table":{"headers":["周期序数","类型","元素数目","原子序数范围","稀有气体终点与电子层特征"],"rows":[["第 1 周期","短周期","2","1 – 2","₂He（1层，K层2e⁻）"],["第 2 周期","短周期","8","3 – 10","₁₀Ne（2层，2, 8）"],["第 3 周期","短周期","8","11 – 18","₁₈Ar（3层，2, 8, 8）"],["第 4 周期","长周期","18","19 – 36","₃₆Kr（4层，2, 8, 18, 8）"],["第 5 周期","长周期","18","37 – 54","₅₄Xe（5层）"],["第 6 周期","长周期（含镧系15）","32","55 – 86","₈₆Rn（6层）"],["第 7 周期","长周期（含锕系15）","32","87 – 118","₁₁₈Og（7层，2016填满）"]]},"takeaway":"记住各周期末尾稀有气体原子序数 **2, 10, 18, 36, 54, 86, 118**，就能瞬间把任意元素定位到第几周期、第几列！"},{"kind":"definition","title":"6.2.2 族的划分：18 个纵列、16 个族与典型/过渡元素","pageRef":"化上 p.138–139","body":["元素周期表共有 **18 个纵列**，分为 **16 个族**（7 个主族 + VIIIA 族共 8 个 A 族；7 个副族 + 占第 8, 9, 10 三纵列的 **VIIIB 族**共 8 个 B 族）：","- **主族（IA–VIIA）与零族/VIIIA 族**：由短周期和长周期元素共同构成（第 1, 2, 13–18 列）。主族元素的**族序数 = 该族元素原子最外层电子数**（仅限 A 族！）；第 18 列 VIIIA 族（稀有气体）最外层电子数为 8（氦 \\(\\mathrm{He}\\) 为 2），化学性质很不活泼。教材将所有主族元素（包含 VIIIA 或专指 IA–VIIA 典型族）称为**典型元素（representative elements）**。","- **副族（IB–VIIB 及 VIIIB）**：只出现在长周期（第 4–7 周期，第 3–12 列）。所有副族元素（教材明确含第 8,9,10 列的 VIIIB 以及镧系和锕系）统称**过渡元素（transition elements）**。","**18 列排布顺序陷阱**：周期表从左到右纵列族号并非 I→VIII 连排，而是：**IA, IIA, IIIB, IVB, VB, VIB, VIIB, VIIIB（3列）, IB, IIB, IIIA, IVA, VA, VIA, VIIA, VIIIA**！"],"takeaway":"核心口诀：**18 列 = 16 族**（因为 VIIIB 独占第 8、9、10 三列）；IB、IIB 排在 VIIIB 之后，而不是排在 IIIB 前面！"},{"kind":"mechanism","title":"金属、非金属与准金属分区及原子序数定位技巧","pageRef":"化上 p.139–140、p.156","body":["**元素类别分布**：在已发现的 118 种元素中绝大多数是金属元素（包括所有 s 区除 H、全部 d 区、全部 f 区以及 p 区左下角的 Al, Ga, In, Tl, Sn, Pb, Bi 等）；沿着 **B–Si–As–Te–At** 对角阶梯线附近的元素性质介于金属与非金属之间，称为**准金属（metalloid）**（如 Si, Ge, As 等，常作半导体）；右上角为非金属与稀有气体。","**主族上下周期相邻元素原子序数差**：","- 第 1→2→3 周期（IA、VIIA）：H(1)+2→Li(3)+8→Na(11)；He(2)+8→Ne(10)+8→Ar(18)；","- 第 3→4 周期：**IA、IIA 差 +8**（如 Na 11→K 19），而 **IIIA–VIIIA 差 +18**（因为中间插入了 10 列 d 区过渡元素！如 Al 13→Ga 31 差 18，Cl 17→Br 35 差 18）；","- 第 4→5 周期：全部差 +18；第 5→6 周期：IA/IIA 差 +18，IIIB 之后插进 14 种镧系而差 **+32**！"],"takeaway":"利用 **“左侧主族（IA/IIA）向下加本周期数，右侧主族（IIIA–VIIA）向下加下一周期数”** 规律，永不出错！"}],"formulas":[{"title":"主族元素在周期表中的位置公式","tex":"\\text{周期序数} = n_{\\max}\\text{（电子层数）},\\qquad \\text{主族序数} = N_{\\text{最外层 }e^-}","plain":"周期序数 = 电子层数；主族序数 = 最外层电子数","conditions":"族序数等于最外层电子数仅适用于主族（A 族，不包括 He 及过渡元素）","pageRef":"化上 p.138","note":"例如 ₁₅P 为 2,8,5 ⇒ 3 层（第3周期）、最外层 5（VA 族）；₃₅Br 为 [Ar]3d¹⁰4s²4p⁵ ⇒ 4 层、最外层 7（VIIA 族）。"},{"title":"同主族上下周期元素原子序数递增差","tex":"\\Delta Z(\\mathrm{IA, IIA}): 2, 8, 8, 18, 18, 32;\\qquad \\Delta Z(\\mathrm{IIIA\\sim VIIA}): 8, 18, 18, 32, 32","plain":"IA/IIA 向下依次加 2, 8, 8, 18, 18, 32；IIIA–VIIA 向下依次加 8, 18, 18, 32, 32","conditions":"第 4 周期起插入 10 列 d 区；第 6 周期起插入 14 列 f 区（合入 IIIB 同格）","pageRef":"化上 p.138–139","note":"已知 17 号 Cl 在第 3 周期 VIIA 族，则下一周期的 Br = 17 + 18 = 35，I = 35 + 18 = 53，At = 53 + 32 = 85。"}],"pitfalls":[{"title":"误把“18 个纵列”当成“18 个族”，或误以为所有稀有气体最外层都是 8 电子","wrong":"“周期表有 18 个纵列即 18 个族；且所有稀有气体原子最外层电子数都是 8。”","diagnosis":"第 8、9、10 三个纵列合称为一个族（第 VIIIB 族），因此 18 个纵列只有 **16 个族**；且第 1 周期的氦（\\({}_2\\mathrm{He}\\)）只有 K 层，最外层仅 **2** 个电子（教材 p.156 第 3 题原选项 B 陷阱！）。","right":"共有 18 个纵列、**16 个族**；稀有气体中除 \\(\\mathrm{He}\\) 最外层为 2 个电子外，其余（Ne, Ar, Kr, Xe, Rn, Og）最外层均为 8 个电子。","checkRule":"看到“均”、“都”描述稀有气体最外层 8 电子，立即找 \\(\\mathrm{He}\\) 判错！"},{"title":"把“最外层只有 2 个电子的原子”全划进 IIA 族","wrong":"“某原子基态最外层有 2 个电子，它一定是 IIA 族碱土金属元素。”","diagnosis":"至少有三类原子最外层都是 2 个电子：① 第 1 周期的 **He**（\\(1\\mathrm{s}^2\\)，VIIIA 族）；② 第 4–7 周期大多数 **d 区/f 区过渡元素**（如 Sc, Ti, Fe, Zn 等 \\((n-1)\\mathrm{d}^k n\\mathrm{s}^2\\)）；③ IIA 族（Be, Mg, Ca…）。","right":"只有在**已知为主族元素**或排除了 He 与过渡金属后，最外层 2 个电子才对应 IIA 族。","checkRule":"最外层 1e⁻ 也可能是 H(IA)、Cr(VIB)、Cu(IB)！单靠最外层电子数无法排除过渡元素和 He。"},{"title":"同主族右侧周期表序数加错 +8 而不是 +18","wrong":"“第 3 周期 VIA 族是 16 号硫（S），所以第 4 周期 VIA 族元素原子序数是 16 + 8 = 24。”","diagnosis":"第 4 周期在 IIA 与 IIIA 之间多出了 10 个 d 区过渡元素，因此右侧主族元素（IIIA–VIIIA）从第 3 周期到第 4 周期序数差是 **+18** 而不是 +8！","right":"第 4 周期 VIA 族是 **16 + 18 = 34 号硒（Se）**；而 24 号其实是过渡金属铬（Cr, VIB 族）。","checkRule":"从第 3 周期跳第 4 周期：左两列（IA, IIA）加 **8**，右六列（IIIA–VIIIA）加 **18**！"}],"examples":[{"label":"例 6.2.1","tier":"L2","tierLabel":"L2 校内期末","title":"稀有气体定位法：由原子序数秒定元素在周期表中的位置","prompt":"不查周期表，请用稀有气体原子序数（2, 10, 18, 36, 54, 86）快速推算以下四种元素所在的周期与族：(1) \\({}_{16}\\mathrm{S}\\)；(2) \\({}_{35}\\mathrm{Br}\\)；(3) \\({}_{51}\\mathrm{Sb}\\)；(4) \\({}_{26}\\mathrm{Fe}\\)。","clues":"比上一个稀有气体多几个电子 = 在下一周期从左往右第几列；或比本周期末稀有气体少几格 = 从第 18 列倒数！","strategy":"优先利用同周期末尾稀有气体 Z_end 倒推最简单（如 Z_end - Z = 1 就是 VIIA 族）。","given":"Z = 16, 35, 51, 26","principle":"7 个周期末端稀有气体位置（第 18 列 VIIIA 族）。","steps":["(1) \\(Z = 16\\)：介于 10(Ne) 与 18(Ar) 之间，故在**第 3 周期**；比 18 少 2 列（18 − 2 = 16），从 VIIIA 倒数 2 格即 **VIA 族**。","(2) \\(Z = 35\\)：介于 18(Ar) 与 36(Kr) 之间，故在**第 4 周期**；比第 4 周期末位 36 少 1 格，即 **VIIA 族**。","(3) \\(Z = 51\\)：介于 36(Kr) 与 54(Xe) 之间，故在**第 5 周期**；比末位 54 少 3 格（8 − 3 = 5），即 **VA 族**。","(4) \\(Z = 26\\)：介于 18(Ar) 与 36(Kr) 之间，故在**第 4 周期**；从第 1 列起数为 \\(26 - 18 = 8\\)，即第 8 纵列——属于 **第 VIIIB 族**（排布为 \\([\\mathrm{Ar}]3\\mathrm{d}^6 4\\mathrm{s}^2\\)）。"],"answer":"(1) 第3周期 VIA 族；(2) 第4周期 VIIA 族；(3) 第5周期 VA 族；(4) 第4周期 VIIIB 族。","markingPoints":["准确判定 4 种元素的周期序数（2分）","正确倒推/顺推得到 VIA, VIIA, VA, VIIIB 族（2分）"],"verification":"周期表第 8、9、10 列对应 Z=26 Fe、27 Co、28 Ni（铁系元素），皆为 VIIIB 族。","pitfall":"第(4)问若把“第 8 列”写成“VIIIA 族”就犯了把过渡金属当成稀有气体的错误。"},{"label":"例 6.2.2","tier":"L3","tierLabel":"L3 预试拔高","title":"长周期原子序数关系与“元素周期表局部拼图”","prompt":"（改编自教材 p.159 第 7 题周期表局部网格）右图周期表片段包含第 1 至第 4 周期的主族与过渡区部分元素：已知短周期元素 \\(\\mathrm{X}\\) 的原子最外层电子数是次外层电子数的 2 倍；\\(\\mathrm{Y}\\) 与 \\(\\mathrm{X}\\) 同主族且位于下一周期；\\(\\mathrm{Z}\\) 位于 \\(\\mathrm{Y}\\) 右侧相邻一格；\\(\\mathrm{W}\\) 与 \\(\\mathrm{Z}\\) 同主族且位于第 4 周期。请回答：(1) 写出 \\(\\mathrm{X, Y, Z, W}\\) 四种元素的符号及 \\(\\mathrm{W}\\) 的原子序数；(2) 以上四种元素中，属于**准金属**的有哪些？(3) 若某金属元素 \\(\\mathrm{M}\\) 位于第 4 周期第 10 纵列，写出 \\(\\mathrm{M}\\) 在周期表中的族序数及基态简写电子排布式。","clues":"最外层 = 2 × 次外层 ⇒ 次外层只能是 2（若为 8 则最外层 16 不可能）；Z 是第 3 周期 VA 族 P，W 在第 4 周期要加 18！","strategy":"逐一确定网格坐标，注意第 3→4 周期 VA 族序数差为 +18。","given":"X(短周期，外层=2×次外层)；Y(X下方)；Z(Y右侧)；W(Z下方第4周期)","principle":"电子层排布制约；短长周期序数差与 d 区列数。","steps":["(1) 短周期中次外层电子数为 2 时，最外层为 4 ⇒ **\\(\\mathrm{X = C}\\)**（第 2 周期 IVA 族，\\(Z=6\\)）。\\(\\mathrm{Y}\\) 在 \\(\\mathrm{C}\\) 正下方（第 3 周期 IVA 族）⇒ **\\(\\mathrm{Y = Si}\\)**（\\(Z=14\\)）。\\(\\mathrm{Z}\\) 在 \\(\\mathrm{Si}\\) 右侧（第 3 周期 VA 族）⇒ **\\(\\mathrm{Z = P}\\)**（\\(Z=15\\)）。\\(\\mathrm{W}\\) 在 \\(\\mathrm{P}\\) 正下方第 4 周期 VA 族，序数 \\(= 15 + 18 = 33\\) ⇒ **\\(\\mathrm{W = As}\\)**（砷）。","(2) 依据教材准金属分界线（B, Si, Ge, As, Sb, Te），以上四种中 **\\(\\mathrm{Si}\\) 和 \\(\\mathrm{As}\\)** 属于准金属（碳与磷是非金属）。","(3) 第 4 周期第 10 纵列属于 **VIIIB 族**（第 8、9、10 列合称 VIIIB），其原子序数为 \\(18 + 10 = 28\\)（镍 \\(\\mathrm{Ni}\\)），基态简写排布式为 **\\([\\mathrm{Ar}]\\,3\\mathrm{d}^8 4\\mathrm{s}^2\\)**。"],"answer":"(1) X=C, Y=Si, Z=P, W=As (Z=33)；(2) Si, As；(3) VIIIB 族，[Ar]3d⁸4s²。","markingPoints":["正确推出 C, Si, P 及加 18 得到 As(33)（2分）","准确识别准金属 Si 与 As（1分）","正确给出第 10 列对应 VIIIB 族及 Ni 的 [Ar]3d⁸4s²（2分）"],"verification":"表 6-4 亦明确把 Si 标为准金属，周期表阶梯线旁 As 亦为准金属。","pitfall":"第(1)问把 W 的原子序数误算成 15+8=23（V）；第(3)问把第 10 列误写成 XB 族（不存在 XB 族，8–10 列全叫 VIIIB 族）。"}],"practice":[{"id":"chem6-6.2-q1","tier":"L1","tierLabel":"L1 基础","examStyle":"P1 选择","q":"下列关于现行元素周期表结构的叙述中，**错误**的是（　）。","options":["A. 元素周期表共有 7 个周期，第 1–3 周期为短周期","B. 元素周期表共有 18 个纵列、16 个族，分为主族和副族（含 VIIIA 与 VIIIB）","C. 稀有气体元素（VIIIA 族）原子的最外层电子数均为 8","D. 第 6 周期镧系元素和第 7 周期锕系元素各有 15 种，合称内过渡元素"],"correctOption":"C","given":"周期表结构基本事实（化上 p.138, p.156 第 3 题）","method":"逐项核查长短周期、族数、稀有气体及内过渡元素定义","principle":"氦（He）核外仅 1 层，最外层只有 2 个电子。","steps":["A、B、D 均完全符合教材 p.138 原文；C 错，第 1 周期的氦（He）最外层只有 2 个电子，其余稀有气体为 8 个。"],"ans":"C","markingPoints":["发现“均为 8”遗漏氦的 2 电子稳定结构"],"verification":"化上 p.156 练习题一第 3 题原型。","pitfall":"忘记第一周期只有 2 个元素导致漏看 He。"},{"id":"chem6-6.2-q2","tier":"L2","tierLabel":"L2 期末","examStyle":"P1 选择","q":"某主族元素 \\(\\mathrm{R}\\) 原子的核外电子排布式为 \\(1\\mathrm{s}^2 2\\mathrm{s}^2 2\\mathrm{p}^6 3\\mathrm{s}^2 3\\mathrm{p}^6 3\\mathrm{d}^{10} 4\\mathrm{s}^2 4\\mathrm{p}^4\\)。则元素 \\(\\mathrm{R}\\) 在元素周期表中的位置是（　）。","options":["A. 第 4 周期 IVB 族","B. 第 4 周期 VIA 族","C. 第 4 周期 VIB 族","D. 第 3 周期 VIA 族"],"correctOption":"B","given":"电子排布式结尾为 3d¹⁰ 4s² 4p⁴","method":"最大主量子数定周期；最外层 s+p 电子数定主族序数","principle":"最后填充 4p，属 p 区主族元素；最外层 4s²4p⁴ 共 6 个价电子。","steps":["最大电子层 \\(n = 4\\) ⇒ **第 4 周期**；最外层为第 4 层（\\(4\\mathrm{s}^2 4\\mathrm{p}^4\\)），共有 \\(2 + 4 = 6\\) 个最外层电子，且 \\(3\\mathrm{d}\\) 已全满 ⇒ **VIA 族**（即 34 号硒 Se）。"],"ans":"B","markingPoints":["从最大层数 4 与最外层 6e⁻ 精准定位"],"verification":"Z = 2+8+18+6 = 34，在 36 Kr 前 2 格，确为 VIA 族。","pitfall":"看到排布里有 3d¹⁰ 就误以为它是副族（B 族）元素，实际上 3d 全满后填入 4p 的都是 p 区主族元素！"},{"id":"chem6-6.2-q3","tier":"L2","tierLabel":"L2 期末","examStyle":"P2 简答","q":"请回答下列有关元素周期表位置的问题：(1) 主族元素在周期表中的位置由原子结构的哪两个直接参数决定（p.156 第 2 题）？(2) 为什么周期表第 6 周期含有 32 种元素，而不是 18 种？其中被另列于表下方的 15 种元素称为什么？(3) 已知第 118 号元素（Og）于 2016 年由 IUPAC 确认命名从而填满第 7 周期，则假若某超铀元素的原子序数为 \\(115\\)，它位于周期表的第几周期、第几族？","given":"p.138 周期与族概念；118 号元素为第 7 周期末位","method":"定位法则与 118 倒推列数","principle":"电子层数=周期序数，最外层电子数=主族序数；第 6 周期含 15 种镧系元素。","steps":["(1) 由原子核外**电子层数**（决定周期序数）和**最外层电子数**（决定主族序数）决定。","(2) 因为从第 6 周期起电子开始填入 \\(4\\mathrm{f}\\) 副层（可容 14 个电子），共新增 14 种元素合入 IIIB 族同格，故总元素数为 \\(18 + 14 = 32\\) 种；这 15 种（La–Lu）另列于表下方的元素称为**镧系元素**。","(3) 118 号位于第 7 周期第 18 列（VIIIA 族），故 **115 号**（镆 Mc）位于第 7 周期从末位倒数第 3 列，即**第 7 周期 VA 族**。"],"ans":"(1) 电子层数和最外层电子数；(2) 因插入 14 种填 4f 电子的镧系元素（合称 15 种镧系元素）；(3) 第 7 周期 VA 族。","markingPoints":["准确写出电子层数与最外层电子数（1分）","点出 4f 副层容 14 电子与镧系元素（2分）","利用 118 倒推出第 7 周期 VA 族（1分）"],"verification":"118(VIIIA) → 117(VIIA) → 116(VIA) → 115(VA)。","pitfall":"第(3)问算成倒数第 3 格 = IV 族而不是 VA 族（应是 8 − 3 = 5）。"},{"id":"chem6-6.2-q4","tier":"L3","tierLabel":"L3 预试","examStyle":"P1 选择","q":"已知甲、乙两种元素在周期表中位于同一主族且上下相邻，甲的原子序数为 \\(x\\)。则乙的原子序数**不可**能是下列哪一项？（　）","options":["A. x + 2","B. x + 8","C. x + 18","D. x + 26"],"correctOption":"D","given":"同主族上下相邻两元素的原子序数差","method":"对照上下周期序数差表（2, 8, 18, 32）","principle":"相邻两周期同主族元素序数之差只可能是某一周期的长度（2, 8, 18, 32）。","steps":["如 H(1) 与 Li(3) 差 2（A 可能）；Li(3) 与 Na(11) 差 8（B 可能）；Cl(17) 与 Br(35) 差 18（C 可能）；没有任何一个周期的长度是 26，故上下相邻不可能差 26（除非隔了周期）。"],"ans":"D","markingPoints":["掌握相邻周期同主族序数差只能取 2, 8, 18, 32"],"verification":"各周期容量集合为 {2, 8, 8, 18, 18, 32, 32}。","pitfall":"若没注意“上下相邻”，误把隔了两周期的 8+18=26 当成可能。"},{"id":"chem6-6.2-q5","tier":"L4","tierLabel":"L4 统考拔高","examStyle":"P1 选择","q":"某元素 \\(\\mathrm{X}\\) 的二价阳离子 \\(\\mathrm{X}^{2+}\\) 核外排布式为 \\([\\mathrm{Ar}]\\,3\\mathrm{d}^9\\)；另一元素 \\(\\mathrm{Y}\\) 与 \\(\\mathrm{X}\\) 同周期，且 \\(\\mathrm{Y}\\) 的最高正氧化数比其最低负氧化数的绝对值大 4。则 \\(\\mathrm{X}\\) 与 \\(\\mathrm{Y}\\) 在周期表中的族序数分别是（　）。","options":["A. IB 族 和 VIA 族","B. VIIIB 族 和 VA 族","C. IB 族 和 VIIA 族","D. IIB 族 和 VIA 族"],"correctOption":"A","given":"X²⁺: [Ar]3d⁹；Y 与 X 同周期且 |最高正| − |最低负| = 4","method":"还原 X 原子电子数定第 11 列 IB 族；由最高+最低绝对值和=8 列方程定 Y 主族序数","principle":"X 阳离子先失 4s 再失 3d；非金属主族 |最高|+|最低|=8。","steps":["\\(\\mathrm{X}^{2+}\\) 有 \\(18 + 9 = 27\\) 个电子，故原子 \\(\\mathrm{X}\\) 有 \\(27 + 2 = 29\\) 个电子（\\(\\mathrm{Cu}\\)），在周期表第 4 周期第 **11 纵列**，即 **IB 族**！","设主族非金属 \\(\\mathrm{Y}\\) 最外层有 \\(a\\) 个电子，则最高正氧化数为 \\(+a\\)，最低负氧化数为 \\(-(8-a)\\)。依题意：\\(a - (8 - a) = 4 \\implies 2a = 12 \\implies a = 6\\)，故 \\(\\mathrm{Y}\\) 位于 **VIA 族**（第 4 周期 VIA 为 34 号 Se，+6 − |−2| = 4）。"],"ans":"A","markingPoints":["还原 Cu(29) 并对应 IB 族（1分）","列方程解得最外层 6e⁻ 对应 VIA 族（1分）"],"verification":"第 11 列：3(IIIB), 4(IVB), 5(VB), 6(VIB), 7(VIIB), 8-10(VIIIB), 11(IB), 12(IIB)。","pitfall":"误把 Cu(29) 当成 VIIIB 族，或不会用“最高正价 − |最低负价| = 2a − 8”求解主族。"}],"cheatSheet":["7 个周期容量：**2, 8, 8, 18, 18, 32, 32**；稀有气体末尾序数：**2, 10, 18, 36, 54, 86, 118**。","18 个纵列 = **16 个族**：IA, IIA, IIIB–VIIB, **VIIIB（第8,9,10三列）**, **IB, IIB**, IIIA–VIIIA。","第 6 周期镧系（15 种）、第 7 周期锕系（15 种）= **内过渡元素**；U(92) 后人工元素 = **超铀元素**；主族定位：周期=电子层数，主族序数=最外层电子数。"],"kbEntryIds":["kb-chem6-table-structure"],"quiz":{"q":"核电荷数为 \\(25\\) 的锰（\\(\\mathrm{Mn}\\)）和核电荷数为 \\(30\\) 的锌（\\(\\mathrm{Zn}\\)）在周期表中分别位于第几周期、第几族？","given":"Z(Mn)=25, Z(Zn)=30，均介于 18(Ar) 与 36(Kr) 之间","method":"Z − 18 得第 4 周期纵列号，再对应族序数","principle":"第 4 周期 3–12 列依次为 IIIB, IVB, VB, VIB, VIIB, VIIIB(8–10), IB, IIB。","steps":["Mn：\\(25 - 18 = 7\\) ⇒ 第 4 周期第 7 列 = **VIIB 族**。","Zn：\\(30 - 18 = 12\\) ⇒ 第 4 周期第 12 列 = **IIB 族**。"],"ans":"Mn：第4周期 VIIB 族；Zn：第4周期 IIB 族。"}},{"id":"6.3","t":"解读元素周期表","anchor":{"pages":"化上 p.140–151","syllabus":"1.4.3 元素周期律、s/p/d/f 分区与性质递变规律","examScopes":["sem1_final","pre_exam","sem2_final","uec"],"examWeight":"全章最高频核心节：P1/P2 必考分区、半径、I₁ 反常、逐级电离能与电负性综合推理","terms":"periodic law · s/p/d/f block · atomic/ionic radius · ionization energy · electron affinity · electronegativity · metalloid","prerequisites":["核外电子排布与半满/全满稳定态（5.4）","周期表 7 周期与 16 族结构（6.2）"],"goals":["理解元素周期律并能按最后填充电子的副层将元素划分进 s、p、d、f 四个分区。","掌握原子半径、阴/阳离子半径及等电子体离子半径的递变规律与理论解释。","掌握第一电离能（含 IIA>IIIA、VA>VIA 反常）和逐级电离能突跃的应用，辨析电负性与金属性/非金属性递变（表 6-2, 6-3, 6-4）。"]},"concepts":[{"kind":"definition","title":"6.3.1–6.3.2 元素周期律与电子结构四大分区（图 6-8）","pageRef":"化上 p.141–143","body":["**元素周期律（periodic law）**：元素的性质随着原子序数递增呈周期性变化的规律（同周期最外层电子数由 1 增至 8，第 4 周期从 \\(4\\mathrm{s}^1\\) 经过 \\(3\\mathrm{d}^{1\\sim 10} 4\\mathrm{s}^{1\\sim 2}\\) 过渡到 \\(4\\mathrm{s}^2 4\\mathrm{p}^6\\)）。","**四大分区（依最后一个填充电子所处副层划分，图 6-8，p.142–143）**：","- **s 区（2 纵列，IA、IIA 族）**：最后电子填入 \\(\\mathrm{s}\\) 轨域（外围 \\(n\\mathrm{s}^{1\\sim 2}\\)），除氢（与按 \\(1\\mathrm{s}^2\\) 计入的氦）外皆为活泼金属元素。","- **p 区（6 纵列，IIIA–VIIIA 族）**：最后电子填入 \\(\\mathrm{p}\\) 轨域（\\(n\\mathrm{s}^2 n\\mathrm{p}^{1\\sim 6}\\)，He 除外），既含非金属与稀有气体，也含准金属与 Al/Sn/Pb 等金属。","- **d 区（10 纵列，IIIB–IIB 族，含 VIIIB）**：最后电子填入次外层 \\((n-1)\\mathrm{d}\\) 轨域（\\((n-1)\\mathrm{d}^{1\\sim 10} n\\mathrm{s}^{1\\sim 2}\\)），全是金属元素（过渡元素）。","- **f 区（表下方两行，镧系与锕系）**：最后电子填入倒数第三层 \\((n-2)\\mathrm{f}\\) 轨域，性质极其相似（内过渡元素）。"],"takeaway":"问“Cu、Fe 属于哪个区？”答 **d 区**（最后填 3d）；问“Cl、Al、C 属于哪个区？”答 **p 区**；问“Ca、Na”答 **s 区**。"},{"kind":"law","title":"6.3.3(1) 原子半径与离子半径递变规律（图 6-9 & 6-10）","pageRef":"化上 p.143–145","body":["**影响半径的两大竞争因素**：① **核外电子层数**（层数越多半径越大）；② **核电荷数 \\(Z\\)**（层数相同时，\\(Z\\) 越大核对电子吸引越强，半径越小）。","**原子半径规律（p.143–144，图 6-9）**：① **同周期主族元素（稀有气体除外）从左到右逐渐减小**（如第 3 周期 Na 186 pm → Cl 99 pm）；② **同主族元素从上到下逐渐增大**（如 Li 156 → Cs 262 pm；F 69 → I 138 pm）。","**离子半径规律（p.144–145，图 6-10）**：","- 阳离子半径 **小于** 对应原子半径（失电子后核吸引增强且常少一层，如 \\(r(\\mathrm{Na}^+)=116\\text{ pm} < r(\\mathrm{Na})=186\\text{ pm}\\)）；","- 阴离子半径 **大于** 对应原子半径（得电子后电子间排斥增强、核吸引减弱，如 \\(r(\\mathrm{Cl}^-)=167\\text{ pm} > r(\\mathrm{Cl})=99\\text{ pm}\\)）；","- 同一周期阳离子半径一般小于阴离子半径（如第 3 周期 \\(\\mathrm{Na^+, Mg^{2+}, Al^{3+}}\\) 为 2 层 10 电子，\\(\\mathrm{P^{3-}, S^{2-}, Cl^-}\\) 为 3 层 18 电子）；","- **等电子体离子铁律**：电子层结构相同的离子（如 10 电子体 \\(\\mathrm{N^{3-}, O^{2-}, F^-, Na^+, Mg^{2+}, Al^{3+}}\\)），**核电荷数越大，半径越小**！"],"takeaway":"比较两种微粒半径的三步顺序：**①先比电子层数 → ②层数相同比核电荷数（Z大反而小）→ ③质子数相同比电子数（多者大，阴离子 > 原子 > 阳离子）**。"},{"kind":"law","title":"6.3.3(2) 第一电离能（I₁）、反常峰与逐级电离能（表 6-2）","pageRef":"化上 p.145–147","body":["**价电子与第一电离能（\\(I_1\\)）**：某元素基态**气态原子**失去 1 个电子形成 \\(+1\\) 价气态阳离子所需的**最低能量**称为第一电离能（单位 \\(\\mathrm{kJ\\,mol^{-1}}\\)），如 \\(\\mathrm{Mg(g) \\to Mg^+(g) + e^-},\\; I_1=738\\text{ kJ\\,mol}^{-1}\\)；\\(I_1\\) 越小越易失电子、金属性越强。","**\\(I_1\\) 总体递变（图 6-11 & 6-12）**：同主族从上到下半径增大，\\(I_1\\) **逐渐减小**；同周期从左到右总体**呈增大趋势**（碱金属最小，稀有气体最大）。","**同周期两处重要反常（p.147）**：\\(I_1(\\mathrm{IIA}) > I_1(\\mathrm{IIIA})\\)（如 **\\(\\mathrm{Mg} > \\mathrm{Al}\\)**、**\\(\\mathrm{Be} > \\mathrm{B}\\)**），\\(I_1(\\mathrm{VA}) > I_1(\\mathrm{VIA})\\)（如 **\\(\\mathrm{P} > \\mathrm{S}\\)**、**\\(\\mathrm{N} > \\mathrm{O}\\)**）。原因：全满（\\(\\mathrm{s}^2\\)）与半满（\\(\\mathrm{p}^3\\)）轨域电子排布能量较低、更稳定，电离更困难！","**逐级电离能（表 6-2，p.147）**：同一原子失电子数越多，剩余正电荷吸引越紧，故 \\(I_1 < I_2 < I_3 < \\dots\\)；当把价电子剥离完毕、要从内层稳定壳层剥离电子时，电离能发生**数量级突跃**——可据此反推主族序数与最高正氧化数！"],"table":{"headers":["元素","I₁ / kJ·mol⁻¹","I₂ / kJ·mol⁻¹","I₃ / kJ·mol⁻¹","I₄ / kJ·mol⁻¹","突跃位置与推断"],"rows":[["Na","496","4 562（×9.2！）","6 912","9 543","I₁≪I₂ ⇒ 1 个价电子，IA 族，+1 价"],["Mg","738","1 451","7 733（×5.3！）","10 540","I₂≪I₃ ⇒ 2 个价电子，IIA 族，+2 价"],["Al","578","1 817","2 745","11 575（×4.2！）","I₃≪I₄ ⇒ 3 个价电子，IIIA 族，+3 价"]]},"takeaway":"第 3 周期第一电离能完整排序（表 6-3）：\\(\\mathrm{Na < Al < Mg < Si < S < P < Cl < Ar}\\)（牢记 Mg-Al 倒挂、P-S 倒挂！）。"},{"kind":"table","title":"6.3.3(3)–(4) 电子亲和能、电负性与金属性/非金属性递变（表 6-3 & 6-4）","pageRef":"化上 p.148–151","body":["**电子亲和能（p.148 资料链接）**：气态基态原子得 1 个电子成为 \\(-1\\) 价气态离子所放出的能量（\\(\\mathrm{A(g)+e^-\\to A^-(g)},\\; E_{A1}<0\\)）；第一电子亲和能绝对值越大，越易得电子、非金属性越强。","**电负性（electronegativity，鲍林 1932，p.148–149）**：衡量元素原子在**化合物中吸引电子能力**大小的尺度，定**氟（F）= 4.0** 为最大值（稀有气体通常不计）。规律：**同周期从左到右逐渐增大，同主族从上到下逐渐减小**（周期表右上角 F 非金属性最强、电负性最大；左下角 Cs/Fr 金属性最强、电负性最小）。","**金属性与非金属性（p.149–151）**：金属性衡量失电子难易（越易失电子越强），非金属性衡量得电子难易（越易得电子越强）。同周期从左到右金属性减弱、非金属性增强；同主族从上到下金属性增强、非金属性减弱（如 IVA 族从 C 非金属 → Si/Ge 准金属 → Sn/Pb 金属）。"],"table":{"headers":["第 3 周期元素","₁₁Na","₁₂Mg","₁₃Al","₁₄Si","₁₅P","₁₆S","₁₇Cl","₁₈Ar"],"rows":[["最外层电子数","1","2","3","4","5","6","7","8"],["原子半径 / 10⁻¹⁰ m","1.86","1.60","1.43","1.18","1.09","1.03","0.99","0.98"],["I₁ / kJ·mol⁻¹","495.9","738.1","577.9","786.3","1 012","999.5","1 251","1 521"],["电负性（鲍林）","0.9","1.2","1.5","1.8","2.1","2.5","3.0","—"],["元素性质与类别","强金属","金属","金属","准金属","非金属","非金属","强非金属","稀有气体"]]},"takeaway":"记住第 3 周期电负性等差递增口诀：**0.9, 1.2, 1.5, 1.8, 2.1, 2.5, 3.0**（几乎步长 0.3–0.5）！电负性差值还能在下一章直接判断离子键 vs 共价键。"}],"formulas":[{"title":"第一与第二电离能定义热化学/电离方程","tex":"\\mathrm{M(g)} \\longrightarrow \\mathrm{M^+(g)} + \\mathrm{e^-}\\;(\\Delta H = I_1 > 0),\\qquad \\mathrm{M^+(g)} \\longrightarrow \\mathrm{M^{2+}(g)} + \\mathrm{e^-}\\;(\\Delta H = I_2 > I_1)","plain":"M(g) → M⁺(g) + e⁻ (I₁)；M⁺(g) → M²⁺(g) + e⁻ (I₂)","conditions":"必须是气态基态原子或气态阳离子；单位 kJ/mol；电离吸热恒为正值","pageRef":"化上 p.146","note":"切勿把固态金属钠升华+电离混为第一电离能，第一电离能严格针对气态孤立原子。"},{"title":"同电子层结构微粒半径排序通式（10e⁻ 与 18e⁻ 常见序列）","tex":"r(\\mathrm{N^{3-}}) > r(\\mathrm{O^{2-}}) > r(\\mathrm{F^-}) > r(\\mathrm{Na^+}) > r(\\mathrm{Mg^{2+}}) > r(\\mathrm{Al^{3+}})","plain":"10电子体离子半径：N³⁻ > O²⁻ > F⁻ > Na⁺ > Mg²⁺ > Al³⁺","conditions":"电子数及电子层结构完全相同（均为 1s²2s²2p⁶）","pageRef":"化上 p.145 图 6-10","note":"同理 18 电子体序列：r(P³⁻) > r(S²⁻) > r(Cl⁻) > r(K⁺) > r(Ca²⁺)。"}],"pitfalls":[{"title":"误把同周期 I₁ 当成“严格单调递增”，漏掉 Mg>Al 和 P>S（或 Be>B 和 N>O）","wrong":"“同周期元素从左到右，第一电离能依次为：\\(\\mathrm{Na < Mg < Al < Si < P < S < Cl < Ar}\\)。”","diagnosis":"Al 失去的是能量更高的 \\(3\\mathrm{p}^1\\) 电子而 Mg 需破坏稳定的 \\(3\\mathrm{s}^2\\) 全满；S 失去的是 \\(3\\mathrm{p}^4\\) 中的成对电子（排斥较大）而 P 需破坏稳定的 \\(3\\mathrm{p}^3\\) 半满。","right":"正确排序：\\(\\mathrm{Na < Al < Mg < Si < S < P < Cl < Ar}\\)（第 2 周期同理为 \\(\\mathrm{Li < B < Be < C < O < N < F < Ne}\\)）。","checkRule":"凡是周期表里比较 I₁ 遇到“IIA vs IIIA”或“VA vs VIA”，一律反转大小号！"},{"title":"忽略“等电子体离子 Z 越大半径越小”，反把阳离子排得比阴离子大","wrong":"“因为 Na 原子半径大于 F 原子，所以 \\(\\mathrm{Na^+}\\) 半径也大于 \\(\\mathrm{F^-}\\)。”","diagnosis":"\\(\\mathrm{Na}\\)（3 层）失去最外层变成 \\(\\mathrm{Na^+}\\)（2 层，\\(Z=11\\)），\\(\\mathrm{F}\\)（2 层）得电子变成 \\(\\mathrm{F^-}\\)（2 层，\\(Z=9\\)）。两者同为 10 电子结构，质子数 11 对 10 个电子的拉力远大于质子数 9！","right":"\\(r(\\mathrm{Na}) > r(\\mathrm{F})\\)，但离子恰好相反：**\\(r(\\mathrm{F^-}) > r(\\mathrm{Na^+})\\)**（图 6-10：F⁻ = 119 pm > Na⁺ = 116 pm，或 O²⁻ 126 pm > F⁻ 119 pm > Na⁺ 116 pm > Mg²⁺ 86 pm > Al³⁺ 68 pm）。","checkRule":"看到阴离子与下一周期阳离子比半径，立刻数电子数是否相同（10e⁻ 或 18e⁻）！"},{"title":"认为 Fe、Cu 等 d 区元素“只有最外层 4s 电子是价电子”","wrong":"“\\({}_{26}\\mathrm{Fe}\\) 最外层排布是 \\(4\\mathrm{s}^2\\)，所以铁只有 2 个价电子。”","diagnosis":"化上 p.145 明确指出：有些元素除最外层电子外，**次外层上的电子也能参与化学反应**，这些电子也叫做价电子（如 Fe 在反应中还能失去 1 个次外层 \\(3\\mathrm{d}\\) 电子形成 \\(\\mathrm{Fe}^{3+}\\)，表现 +2 和 +3 氧化数）。","right":"主族元素价电子即最外层电子；过渡元素的价电子包括最外层 \\(n\\mathrm{s}\\) 和部分或全部次外层 \\((n-1)\\mathrm{d}\\) 电子。","checkRule":"主族看最外层；过渡元素看 \\((n-1)\\mathrm{d} + n\\mathrm{s}\\)。"}],"examples":[{"label":"例 6.3.1","tier":"L2","tierLabel":"L2 校内期末","title":"教材 p.159 第 6 题改编：第一电离能反常与电负性区间推断","prompt":"(1) 已知第 3 周期部分元素数据缺失，请依据周期律推断铝（Al）的第一电离能范围应介于哪两个相邻主族金属/非金属之间（写成 `___ < Al < ___`，从 \\(\\mathrm{Na, Mg, Si}\\) 中选填元素符号），并解释为什么 Mg 的 \\(I_1\\) 大于 Al？(2) 根据教材 p.159 表给出的电负性值：\\(\\mathrm{Na}=0.93, \\mathrm{Al}=1.61, \\mathrm{Si}=1.90, \\mathrm{Be}=1.57, \\mathrm{Li}=0.98\\)，请推断镁（\\(\\mathrm{Mg}\\)）元素电负性的最小区间范围（形如 `___ < Mg < ___`），并总结元素电负性与金属性、非金属性的关系。","clues":"注意 Al(578) 低于 Mg(738) 但高于 Na(496)；电负性没有“半满/全满锯齿倒挂”，同周期同族严格单调！","strategy":"区分第一电离能（有锯齿反常）与电负性（单调递增递减）两条规律的差异。","given":"Na(I₁=496, EN=0.93), Mg(I₁=738), Al(I₁=578, EN=1.61), Be(EN=1.57)","principle":"全充满 s² 稳定态对 I₁ 的影响；电负性在同周期及同主族中的严格单调递变。","steps":["(1) 第 3 周期中 \\(I_1(\\mathrm{Na})=496 < I_1(\\mathrm{Al})=578 < I_1(\\mathrm{Mg})=738 < I_1(\\mathrm{Si})=786\\)（单位 \\(\\mathrm{kJ\\,mol^{-1}}\\)）。因此 Al 的 \\(I_1\\) 范围为：**\\(\\mathrm{Na < Al < Mg}\\)**（注意：Al 虽排在 Mg 后，但 \\(I_1\\) 反常小于 Mg！）。原因：Mg 的外围电子排布为 \\(3\\mathrm{s}^2\\)，\\(\\mathrm{s}\\) 轨域处于**全充满**稳定状态、能量较低，失去 1 个电子所需能量大；而 Al 为 \\(3\\mathrm{s}^2 3\\mathrm{p}^1\\)，\\(3\\mathrm{p}\\) 仅 1 个电子且能量高于 \\(3\\mathrm{s}\\)，相对更易失去。","(2) 电负性在同周期从左到右严格增大（故 \\(\\mathrm{Na}(0.93) < \\mathrm{Mg} < \\mathrm{Al}(1.61)\\)），在同主族从上到下严格减小（故 \\(\\mathrm{Mg} < \\mathrm{Be}(1.57)\\)）。取两个上界的较小者（1.57），得到最窄区间：**\\(0.93 < \\mathrm{EN(Mg)} < 1.57\\)**（即 \\(\\mathrm{Na < Mg < Be}\\)，实际值约 1.31）。","关系总结：电负性数值越大，原子吸引电子能力越强，**非金属性越强、金属性越弱**。"],"answer":"(1) Na < Al < Mg；Mg 的 3s² 为全充满稳定结构；(2) 0.93 < Mg < 1.57（即 Na < Mg < Be）；电负性越大非金属性越强、金属性越弱。","markingPoints":["利用反常正确写出 Na < Al < Mg（1分）","从 3s² 全充满稳定态对比 3p¹ 解释 Mg > Al（2分）","同时联立同周期(Na)与同主族(Be)边界定出最窄电负性区间 0.93–1.57（2分）"],"verification":"教材 p.159 第 6 题完美解答：注意电负性最小范围一定要联立上下左右取交集（1.57 比 1.61 更紧！）。","pitfall":"第(2)问只看第 3 周期写成 0.93 < Mg < 1.61，没有用同主族上方的 Be(1.57) 进一步收紧上界。"},{"label":"例 6.3.2","tier":"L4","tierLabel":"L4 统考压轴","title":"教材 p.160 第 7(2) 题：逐级电离能突跃 + 位构性综合推导","prompt":"下表为锂及另外两种前 20 号元素 \\(\\mathrm{X, Y}\\) 逐级失去电子的电离能数据（单位：\\(\\mathrm{kJ\\,mol^{-1}}\\)）：\n- 锂（Li）：\\(I_1=519,\\; I_2=7296,\\; I_3=11799\\)\n- \\(\\mathrm{X}\\)：\\(I_1=502,\\; I_2=4570,\\; I_3=6920,\\; I_4=9550\\)\n- \\(\\mathrm{Y}\\)：\\(I_1=580,\\; I_2=1820,\\; I_3=2750,\\; I_4=11600\\)\n请结合元素周期律回答：(1) 为什么锂原子失去第 2 个电子所需能量（7296）远远大于失去第 1 个电子（519）？(2) \\(\\mathrm{X}\\) 在周期表中属于哪一区、哪一族？它最可能是第 3 周期中的哪一种元素（写出符号及理由）？(3) \\(\\mathrm{Y}\\) 是周期表中哪一族元素？若某第 3 周期元素 \\(\\mathrm{J}\\)（主族最高氧化数为 +6，电负性远大于 \\(\\mathrm{X}\\)）与 \\(\\mathrm{X}\\)、\\(\\mathrm{Y}\\) 分别化合，写出所得典型化合物的化学式并判断两者晶体中 \\(\\mathrm{X}\\) 的阳离子与 \\(\\mathrm{Y}\\) 的阳离子半径大小。","clues":"X 在 I₁→I₂ 发生 9 倍突跃（IA 族）且 I₁(502)<Li(519)；Y 在 I₃→I₄ 发生 4 倍突跃（IIIA 族）；第 3 周期 +6 最高价是 S（或看图 j 位置）。","strategy":"逐级电离能找断层定族序数 → 再比 I₁ 大小定周期 → 结合电荷与层数比离子半径。","given":"Li(I₁=519), X(I₁=502≪I₂=4570), Y(I₃=2750≪I₄=11600)","principle":"逐级电离能突跃对应内层稳定构型；同主族 I₁ 从上到下减小；等电子体离子半径比较。","steps":["(1) 锂（\\(1\\mathrm{s}^2 2\\mathrm{s}^1\\)）失去第 1 个电子后形成具有稀有气体（He）全满稳定结构的 \\(\\mathrm{Li}^+\\)（\\(1\\mathrm{s}^2\\)）；第 2 个电子处于离核更近的 \\(1\\mathrm{s}\\) 内层，原子核对其吸引力极强且要破坏稳定结构，因此 \\(I_2 \\gg I_1\\)。","(2) \\(\\mathrm{X}\\) 的 \\(I_2(4570)\\) 约为 \\(I_1(502)\\) 的 9.1 倍，突跃发生在失第 2 个电子时，说明 \\(\\mathrm{X}\\) 最外层仅有 1 个电子，属于 **s 区 IA 族**。又因 \\(I_1(\\mathrm{X})=502 < I_1(\\mathrm{Li})=519\\)，同主族自上而下 \\(I_1\\) 减小，第 3 周期 IA 族恰为 **\\(\\mathrm{Na}\\)**（\\(I_1\\approx 496\\sim 502\\)）。","(3) \\(\\mathrm{Y}\\) 的 \\(I_4(11600)\\) 远大于 \\(I_3(2750)\\)，说明最外层有 3 个价电子，属于 **IIIA 族**（\\(I_1=580\\) 对应第 3 周期 **Al**）。第 3 周期最高正价 +6 族为 **S**（VIA 族），与 Na、Al 分别形成 **\\(\\mathrm{Na_2S}\\)** 和 **\\(\\mathrm{Al_2S_3}\\)**。因 \\(\\mathrm{Na^+}\\) 与 \\(\\mathrm{Al^{3+}}\\) 均是 10 电子（2 层）离子，而 \\(\\mathrm{Al^{3+}}\\) 核电荷数（13）大于 \\(\\mathrm{Na^+}\\)（11），故半径：**\\(r(\\mathrm{Na^+}) > r(\\mathrm{Al^{3+}})\\)**。"],"answer":"(1) 失第1个电子后达 He 稳定内层，第2个电子离核更近、受核吸引极强；(2) s 区 IA 族，最可能为 Na；(3) IIIA 族（Al）；化学式 Na₂S、Al₂S₃；半径 r(Na⁺) > r(Al³⁺)。","markingPoints":["指出 Li⁺ 达稳定结构及内层离核近引力强（1分）","由 I₂≫I₁ 判断 X 属 s 区 IA 族并比对 I₁ 定出 Na（2分）","由 I₄≫I₃ 定出 Y 属 IIIA 族、写出化学式并用 Z(Al)>Z(Na) 比较半径（2分）"],"verification":"对照化上 p.147 表 6-2（Na 496/4562, Al 578/1817/2745/11575）与 p.160 原题数据完全吻合。","pitfall":"第(2)问只答出 IA 族，漏答分区（s 区）；或第(3)问误认为 Al³⁺ 质量大所以半径大。"}],"practice":[{"id":"chem6-6.3-q1","tier":"L1","tierLabel":"L1 基础","examStyle":"P1 选择","q":"按照原子核外电子层结构对元素周期表进行分区，下列元素的最后填入电子分别使硅（\\({}_{14}\\mathrm{Si}\\)）、钙（\\({}_{20}\\mathrm{Ca}\\)）、铁（\\({}_{26}\\mathrm{Fe}\\)）属于哪个区？（　）","options":["A. s 区、p 区、d 区","B. p 区、s 区、d 区","C. p 区、d 区、f 区","D. d 区、s 区、p 区"],"correctOption":"B","given":"Si (Z=14), Ca (Z=20), Fe (Z=26)","method":"写出价电子构型并看最后一个填充的电子副层","principle":"s 区 IA/IIA；p 区 IIIA–VIIIA；d 区 IIIB–IIB。","steps":["Si 为 [Ne]3s²3p²（p 区）；Ca 为 [Ar]4s²（s 区）；Fe 为 [Ar]3d⁶4s²（最后填 3d，属 d 区）。"],"ans":"B","markingPoints":["准确将主副族与 s/p/d 分区对应"],"verification":"化上 p.142 图 6-8。","pitfall":"把 p 区的 Si 与 s 区的 Ca 顺序搞混。"},{"id":"chem6-6.3-q2","tier":"L2","tierLabel":"L2 期末","examStyle":"P1 选择","q":"下列微粒半径大小比较中，**正确**的是（　）。","options":["A. r(Na⁺) > r(Mg²⁺) > r(F⁻) > r(O²⁻)","B. r(Cl⁻) > r(S²⁻) > r(Cl) > r(S)","C. r(O²⁻) > r(F⁻) > r(Na⁺) > r(Al³⁺)","D. r(Li) > r(Na) > r(K) > r(Rb)"],"correctOption":"C","given":"四组微粒半径排序","method":"同电子层比核电荷数 Z；同主族比层数","principle":"等电子体 Z 越大半径越小；同主族从上到下半径增大。","steps":["A 错：10 电子等电子体 Z(O)=8 < Z(F)=9 < Z(Na)=11 < Z(Mg)=12，故 r(O²⁻) > r(F⁻) > r(Na⁺) > r(Mg²⁺)。","B 错：18 电子体 Z(S)=16 < Z(Cl)=17，故 r(S²⁻) > r(Cl⁻)，且同周期 r(S) > r(Cl)。","C 对：四者均为 10 电子微粒，质子数 8 < 9 < 11 < 13，半径依次减小。","D 错：同主族从上到下电子层数增多，半径应 Li < Na < K < Rb。"],"ans":"C","markingPoints":["熟练应用等电子体核电荷数反比规律"],"verification":"图 6-9 与图 6-10（O²⁻ 126 > F⁻ 119 > Na⁺ 116 > Al³⁺ 68 pm）。","pitfall":"误以为阳离子电荷越高半径越大。"},{"id":"chem6-6.3-q3","tier":"L2","tierLabel":"L2 期末","examStyle":"P2 简答","q":"请根据第 2、3 周期元素第一电离能曲线（图 6-11 & 6-12）回答：(1) 同周期元素中，第二周期氮（N）与氧（O）哪一个的第一电离能更大？请从核外电子排布规则解释原因；(2) 若某元素气态原子的第一、二、三、四电离能依次为 \\(738, 1451, 7733, 10540\\text{ kJ\\,mol}^{-1}\\)，该元素最外层有几个电子？它常显什么正氧化数？","given":"N(Z=7) vs O(Z=8)；电离能数据 738, 1451, 7733, 10540","method":"写出 N(2p³) 与 O(2p⁴) 排布比对半满稳定态；找电离能数据突跃点","principle":"2p³ 半充满稳定结构；I₃ ≫ I₂ 突跃指示 2 个价电子。","steps":["(1) **氮（N）**的第一电离能大于氧（O）。原因：N 原子的价电子排布为 \\(2\\mathrm{s}^2 2\\mathrm{p}^3\\)，三个 \\(2\\mathrm{p}\\) 轨域处于**半充满**的稳定状态（能量较低），失去 1 个电子需要克服较高能量；而 O 为 \\(2\\mathrm{s}^2 2\\mathrm{p}^4\\)，有一个 \\(2\\mathrm{p}\\) 轨域排入了 2 个自旋相反的电子，电子间排斥较大，较易失去其中 1 个电子变为半满构型。","(2) 从 \\(I_2(1451)\\) 到 \\(I_3(7733)\\) 能量暴增 5 倍以上，说明失去 2 个电子后即达稳定的内层稀有气体结构，因此该元素最外层有 **2 个**电子（IIA 族 Mg），常显 **+2** 氧化数。"],"ans":"(1) N > O（N 的 2p³ 为半充满稳定态）；(2) 最外层 2 个电子，常显 +2 氧化数。","markingPoints":["正确判断 N > O 并给出 2p³ 半充满 vs 2p⁴ 解释（2分）","指出 I₂→I₃ 突跃，答出最外层 2 个电子与 +2 氧化数（2分）"],"verification":"化上 p.147 表 6-2 与图 6-11。","pitfall":"第(1)问受同周期左→右大趋势迷惑而误答 O > N。"},{"id":"chem6-6.3-q4","tier":"L3","tierLabel":"L3 预试","examStyle":"P1 选择","q":"下列关于元素周期律及性质递变的表述中，**正确**的是（　）。","options":["A. 从 F → Cl → Br → I，元素的电负性、第一电离能与非金属性依次增强","B. 第 3 周期主族元素（Na → Cl），最高正化合价从 +1 依次升至 +7，原子半径依次增大","C. 同一周期中，金属元素的电负性数值一般小于非金属元素（通常金属 < 1.8，非金属 > 1.8）","D. 在已知自然元素中，第一电离能最大和电负性最大的元素分别是 F 和 He"],"correctOption":"C","given":"卤素递变、第3周期递变、电负性边界与极值元素","method":"逐项校验递增方向和极值位置","principle":"同主族自上而下电负性/I₁/非金属性减弱；He 电离能最大，F 电负性最大。","steps":["A 错：同主族 F → I 半径增大，电负性、I₁ 和非金属性均依次**减弱**。","B 错：第 3 周期 Na → Cl 原子半径应依次**减小**。","C 对：化上 p.172 明确以 1.8 为金属与非金属电负性一般界限，金属电负性比非金属小。","D 错：顺序写反了！**He** 第一电离能最大，**F** 电负性最大。"],"ans":"C","markingPoints":["准确辨别周期内与主族内四大性质递变方向"],"verification":"化上 p.144–151 及 p.172。","pitfall":"D 选项把“He 的 I₁ 最大”与“F 的电负性最大”读反顺序。"},{"id":"chem6-6.3-q5","tier":"L4","tierLabel":"L4 统考压轴","examStyle":"P2 综合推理","q":"已知 A、B、C、D、E 是原子序数依次增大的五种短周期主族元素：A 是原子半径最小的元素；B 的电负性在同周期中最大（不含稀有气体）且没有正氧化数；C 元素的逐级电离能（\\(\\mathrm{kJ\\,mol^{-1}}\\)）分别为 \\(496, 4562, 6912, 9543\\)；D 原子的 \\(3\\mathrm{p}\\) 副层恰好半充满；E 的 \\(-1\\) 价阴离子与 \\(\\mathrm{Ar}\\) 具有相同电子层结构。试回答：(1) 分别写出 A–E 五种元素的名称与符号；(2) 比较 B、C、E 各自简单离子的半径大小（用离子符号及 `>` 表示）；(3) 比较 D 与同周期相邻元素（\\({}_{16}\\mathrm{S}\\)）的**第一电离能**和**电负性**大小；(4) 用元素符号表示 C 与 E、C 与 B 形成化合物的化学式，并比较两化合物中化学键的离子性相对强弱。","given":"A 半径最小；B 第2周期电负性最大无正价；C I₂≫I₁ 且为短周期；D 3p³；E⁻ 与 Ar 等电子","method":"五步破译 A–E → 比离子层数与 Z → 区分 I₁ 半满反常 vs 电负性单调性 → 依 ΔEN 判离子性强弱","principle":"元素周期律全景应用与 ΔEN 判键极性衔接。","steps":["(1) 破译元素：A 半径最小 ⇒ **H**（氢）；B 无正氧化数且同周期电负性最大 ⇒ **F**（氟）；C 为短周期且 \\(I_1=496\\ll I_2\\) ⇒ **Na**（钠）；D 为 \\(3\\mathrm{p}^3\\) 半满 ⇒ **P**（磷）；E⁻ 有 18 个电子 ⇒ **Cl**（氯）。","(2) 三种离子 \\(\\mathrm{F^-}\\)（2 层 10e⁻）、\\(\\mathrm{Na^+}\\)（2 层 10e⁻）、\\(\\mathrm{Cl^-}\\)（3 层 18e⁻）：先看电子层数，\\(\\mathrm{Cl^-}\\) 最多故最大；同为 10 电子的 \\(\\mathrm{F^-}\\) 与 \\(\\mathrm{Na^+}\\) 中 \\(Z(\\mathrm{F})=9 < Z(\\mathrm{Na})=11\\)，故 \\(r(\\mathrm{F^-}) > r(\\mathrm{Na^+})\\)。完整排序：**\\(r(\\mathrm{Cl^-}) > r(\\mathrm{F^-}) > r(\\mathrm{Na^+})\\)**。","(3) \\(\\mathrm{D(P)}\\) 与 \\(\\mathrm{S}\\) 相比：因 P 为 \\(3\\mathrm{p}^3\\) 半满稳定构型，故**第一电离能 \\(I_1(\\mathrm{P}) > I_1(\\mathrm{S})\\)**（1012 > 999.5）；但吸引电子的**电负性 \\(\\mathrm{EN(S)} > \\mathrm{EN(P)}\\)**（2.58 > 2.19），因 S 原子半径更小、核电荷数更高。","(4) 化学式：**\\(\\mathrm{NaCl}\\)** 与 **\\(\\mathrm{NaF}\\)**。因 \\(\\Delta\\mathrm{EN}(\\mathrm{NaF}) = 4.0 - 0.9 = 3.1 > \\Delta\\mathrm{EN}(\\mathrm{NaCl}) = 3.0 - 0.9 = 2.1\\)，故 **\\(\\mathrm{NaF}\\) 中离子键的离子性更强**。"],"ans":"(1) H, F, Na, P, Cl；(2) r(Cl⁻) > r(F⁻) > r(Na⁺)；(3) I₁: P > S，电负性: S > P；(4) NaCl 与 NaF，NaF 离子性更强。","markingPoints":["准确推断 A–E 五元素（2分）","正确排定 r(Cl⁻) > r(F⁻) > r(Na⁺)（1分）","区分 P vs S 的第一电离能（P>S）与电负性（S>P）差异（2分）","写出化学式并从电负性差值判断 NaF 离子性更强（1分）"],"verification":"所有趋势与数据完全符合教材表 6-2、6-3 与图 6-10。","pitfall":"第(3)问误以为既然 P 的第一电离能大于 S，电负性也是 P 大于 S（电负性不存在 VA>VIA 反常！）。"}],"cheatSheet":["四大分区：**s 区**（IA/IIA）、**p 区**（IIIA–VIIIA，不含 He）、**d 区**（IIIB–IIB 过渡元素）、**f 区**（镧系/锕系）。","微粒半径比法：先比**层数** → 同层比 **Z**（等电子体 \\(Z\\) 大反而小：\\(\\mathrm{O^{2-}>F^->Na^+>Mg^{2+}>Al^{3+}}\\)）→ 同元素阴 > 原 > 阳。","第 3 周期 \\(I_1\\) 口诀：**Na < Al < Mg < Si < S < P < Cl < Ar**（Mg 3s² 全满、P 3p³ 半满突高）；逐级电离能突跃点前电子数 = 价电子数 = 主族序数。","电负性 F=4.0 最大（无反常！同周期左→右↑，同族上→下↓），与非金属性一致、与金属性相反。"],"kbEntryIds":["kb-chem6-blocks-spdf","kb-chem6-radius-trend","kb-chem6-ionization-energy","kb-chem6-electronegativity"],"quiz":{"q":"将微粒 \\(\\mathrm{S^{2-}}\\)、\\(\\mathrm{K^+}\\)、\\(\\mathrm{Cl^-}\\)、\\(\\mathrm{Ca^{2+}}\\) 按离子半径由大到小排列。","given":"四种离子均含 18 个电子（[Ar] 构型）","method":"等电子体离子比较核电荷数 Z（16, 17, 19, 20）","principle":"电子层结构相同时，核电荷数越大，对电子吸引力越强，半径越小。","steps":["质子数 \\(Z(\\mathrm{S})=16 < Z(\\mathrm{Cl})=17 < Z(\\mathrm{K})=19 < Z(\\mathrm{Ca})=20\\)，故半径相反减小。"],"ans":"\\(r(\\mathrm{S^{2-}}) > r(\\mathrm{Cl^-}) > r(\\mathrm{K^+}) > r(\\mathrm{Ca^{2+}})\\)"},"diagrams":[{"src":"assets/fig/v2/chem06-periodic-trends.svg","caption":"图 6-1 元素周期表 s/p/d/f 四大分区、性质周期性递变及第3周期第一电离能锯齿总图","alt":"周期表分区与性质周期性递变图","pageRef":"化上 p.141–150"}]}]},"化学7":{"lessonKey":"化学7","courseCode":"chemistry","subject":"化学","chapter":7,"title":"化学键与分子间作用力","syllabus":"1.5 化学键","bookId":"sm1-chemistry-2017","bookCitation":"《马来西亚华文独中教科书 · 化学（上册）》（2017年11月版）第7章 p.161–196","examScopes":["sem1_final","pre_exam","sem2_final","uec"],"chapterOverview":{"summary":"第7章解释原子如何聚集成丰富多彩的宏观物质：从强相互作用的三大化学键（离子键、共价键/配位键、金属键）及其决定的分子空间构型（VSEPR）和极性，延伸到较弱的分子间作用力（范德华力与氢键对熔沸点、密度与溶解度的调控），最终汇入离子、原子、分子、金属四大晶体类型的结构与物理性质对照，是解决结构—性质推理题的核心枢纽。","conceptTree":[{"branch":"7.1 三大化学键与分子空间构型（p.162–175）","items":["离子键（八隅体规则、电子转移、静电作用、ΔEN > 1.7、电子式）","共价键（轨域重叠共用电子对、非极性 vs 极性、配位键 NH₄⁺/H₃O⁺）","VSEPR 空间构型与分子极性判别（CO₂/CH₄ 非极性 vs H₂O/NH₃ 极性）","金属键（金属阳离子 + 自由电子“电子海洋”模型）"]},{"branch":"7.2 分子间作用力：范德华力与氢键（p.176–181）","items":["范德华力（极性吸引 + 瞬间极性；卤素单质熔沸点随 Mr 升高）","氢键 X—H···Y（强度比 100:10:1；H₂O/HF/NH₃ 沸点反常、冰密度与溶解度）"]},{"branch":"7.3 四大晶体及其特性对照（p.182–190）","items":["离子晶体（NaCl, BaCl₂：熔融/水溶液导电）· 原子晶体（金刚石, SiO₂, SiC, BN：高熔点极硬）","分子晶体（干冰, 冰, P₄, S₈, I₂：低熔点不导电）· 金属晶体（Na, Cr, W：自由电子导电延展）"]}]},"paperFocus":["高三上半年期末考（Ch 3–8, Ch 26–30）：第7章在 P1 选择和 P2 必答题中比重极高——必考电子式书写（NaCl/MgCl₂/N₂/NH₄⁺）、VSEPR 构型与极性判别、氢键引起的沸点反常（图 7-14）、以及“根据熔点/导电性判断晶体类型”的推理题（p.195–196 原题风格）。","预试 / 毕业考 / UEC 统考：常以未知晶体物理性质表或氢化物沸点曲线图形式命题，结合第6章周期律考察“为什么 SiO₂ 熔点 1723℃ 而 CO₂ 常温为气体”、“为什么 HF>HI>HBr>HCl”以及“熔化/蒸发/分解克服的作用力辨析”。"],"solvingWorkflow":["判化学键与化合物类型：两原子 ΔEN > 1.7（典型活泼金属+活泼非金属）多为离子键；非金属之间（0 < ΔEN < 1.7）为极性共价键，同种原子为非极性键；金属单质/合金内部为金属键。","判分子极性两步走：① 先用 VSEPR 确定中心原子价层电子对与空间构型（直线、平面三角、正四面体、三角锥、角形）；② 检查所有键偶极是否空间对称完全抵消。","判物质物理性质（熔沸点、溶解度）：首先判断**晶体类型**（原子晶体 > 离子晶体 > 分子晶体；金属晶体跨度大另比半径与自由电子数）→ 若同为分子晶体，**先看有无分子间氢键**（H₂O/HF/NH₃/醇/羧酸显著偏高），**再比相对分子质量 Mr**（Mr 越大范德华力越强）。","判物态变化/化学变化断键类型：分子晶体熔化/升华只断**分子间作用力**（不断共价键）；原子晶体熔化断**共价键**；离子晶体熔化/电离断**离子键**；分子受热分解断**共价键**。"],"questionTypes":["电子式、结构式正误辨析与配位键（NH₄⁺, H₃O⁺）形成过程描述","常见分子（CO₂, H₂O, NH₃, CH₄, CCl₄, BF₃）键极性、空间构型与分子极性配对","卤素单质、氢化物及烷烃同系物熔沸点排序与氢键反常现象解释","已知熔点、硬度及固态/熔融/水溶液导电性表判定四种晶体类型","干冰 vs 二氧化硅、碘升华 vs 碘化氢分解所克服作用力的精准对比"],"scoringNotes":["解释“干冰（CO₂）与石英（SiO₂）熔点差异极大”或“H₂O 沸点高于 H₂S”时，必须先定性说出各自的**微粒类型与破坏的作用力**（干冰克服微弱的分子间范德华力，SiO₂ 破坏极强的 Si—O 共价键；水分子间存在氢键，H₂S 只有较弱的范德华力），绝不可空泛答“结构不同”。","证明某晶体属于“离子晶体”最充分的实验判据是**“固态不导电，但熔融状态能导电”**（教材 p.195 第 4 题标准答案——注意“水溶液导电”不能单独排除如 HCl 等分子晶体！）。"],"vid":[{"t":"离子键、共价键、配位键与电子式书写","q":"离子键 共价键 配位键 电子式 高中化学"},{"t":"VSEPR 分子空间构型与极性/非极性分子判别","q":"VSEPR 空间构型 极性分子 非极性分子"},{"t":"范德华力、氢键与氢化物沸点反常","q":"范德华力 氢键 沸点反常 高中化学"},{"t":"四大晶体结构、作用力与物理性质比较","q":"离子晶体 原子晶体 分子晶体 金属晶体 性质"}],"sections":[{"id":"7.1","t":"化学键","anchor":{"pages":"化上 p.162–175","syllabus":"1.5.1–1.5.3 离子键、共价键（含配位键/VSEPR/分子极性）与金属键","examScopes":["sem1_final","pre_exam","sem2_final","uec"],"examWeight":"P1/P2 必考电子式、配位键、VSEPR 构型与分子极性判别","terms":"octet rule · ionic bond · covalent bond · dative/coordinate bond · VSEPR theory · polar molecule · metallic bond","prerequisites":["原子核外最外层电子排布（5.4）","电负性概念与周期表递变（6.3.3）"],"goals":["用八隅体规则与电子转移解释离子键形成，并依据电负性差（ΔEN > 1.7）区分离子键与共价键。","熟练书写常见离子化合物和共价分子的电子式与结构式，理解配位键（NH₄⁺, H₃O⁺）形成及等价性。","运用 VSEPR 理论预测 CO₂、H₂O、NH₃、CH₄ 的空间构型与分子极性，并简述金属键“电子海洋”模型。"]},"concepts":[{"kind":"definition","title":"7.1.1 八隅体规则与离子键（p.162–165）","pageRef":"化上 p.163–164","body":["**八隅体规则（Octet rule）**：原子相互作用时，一般趋于形成最外层 **8 个电子**的稀有气体稳定结构（H、Li、Be 等趋于 2 电子稳定结构）。","**离子键的形成（图 7-1）**：活泼金属原子（电负性小）易失去价电子形成**阳离子**（如 \\(\\mathrm{Na \\to Na^+ + e^-}\\)），活泼非金属原子（电负性大）易得到电子形成**阴离子**（如 \\(\\mathrm{Cl + e^- \\to Cl^-}\\)）；带相反电荷的阴、阳离子之间通过**静电作用（electrostatic interaction）**结合在一起的作用力称为**离子键**。","**离子键特点与电子式**：离子键没有方向性和饱和性；离子化合物（如 \\(\\mathrm{NaCl, MgO, BaCl_2}\\)）中不存在单个独立分子；用电子式表示离子化合物时，阴离子必须用方括号 `[ ]` 括起最外层 8 电子并在右上角标明电荷（如 \\(\\mathrm{Na^+\\,[:\\ddot{Cl}:]^-}\\)）。"],"takeaway":"离子键不只是异性电荷相互吸引，还包括原子核间及电子云间的排斥——静电引力与斥力达到平衡形成稳定离子间距。"},{"kind":"definition","title":"7.1.2 共价键、电负性判据与配位键（p.165–172）","pageRef":"化上 p.165–172","body":["**共价键的形成与本质（图 7-4）**：电负性相近或非金属原子间通过**共用电子对**（原子轨域/电子云部分重叠，两核间电子云密度增大）形成的强烈相互作用，称为**共价键**。按共用电子对数目分为单键（\\(\\mathrm{Cl-Cl}\\)）、双键（\\(\\mathrm{O=O}\\)）、叁键（\\(\\mathrm{N\\equiv N}\\)）。","**极性键 vs 非极性键（图 7-9，p.171–172）**：","- **非极性共价键（\\(\\Delta\\mathrm{EN} = 0\\)）**：同种非金属原子成键（如 \\(\\mathrm{H_2, Cl_2, N_2}\\)），共用电子对不偏向任何一方。","- **极性共价键（\\(0 < \\Delta\\mathrm{EN} < 1.7\\)）**：不同原子成键时电子对偏向电负性大的原子（带部分负电荷 \\(\\delta^-\\)），另一原子带部分正电荷 \\(\\delta^+\\)，如 \\(\\overset{\\delta+}{\\mathrm{H}}-\\overset{\\delta-}{\\mathrm{Cl}}\\)。","- **教材经验界限（p.172）**：一般认为**电负性 \\(> 1.8\\) 为非金属，\\(< 1.8\\) 为金属**；两元素**\\(\\Delta\\mathrm{EN} > 1.7\\) 通常形成离子键，\\(< 1.7\\) 通常形成共价键**（极性共价键是介于非极性共价键与离子键之间的过渡形式）。","**配位键（dative / coordinate bond，图 7-6，p.169）**：由**一个原子单方面提供一对孤对电子**与另一个**提供空轨域接受电子**的原子形成的共价键，用箭头 `→` 指向接受孤对电子的原子。如 \\(\\mathrm{NH_3 + H^+ \\to [NH_4]^+}\\)（结构式为 \\(\\mathrm{N\\to H}\\)）以及 \\(\\mathrm{H_2O + H^+ \\to [H_3O]^+}\\)。一旦形成，\\(\\mathrm{NH_4^+}\\) 中 **4 个 \\(\\mathrm{N-H}\\) 键的键长、键角与化学性质完全相同**！"],"takeaway":"配位键**属于共价键**的一种特殊形成方式（教材思考题 7c 第 3 题）；离子化合物如 \\(\\mathrm{NH_4Cl}\\)、\\(\\mathrm{NaOH}\\) 内部同时存在离子键与共价键（\\(\\mathrm{NH_4Cl}\\) 还含配位键）！"},{"kind":"law","title":"VSEPR 理论、分子空间构型（表 7-3）与分子极性判别","pageRef":"化上 p.173–174","body":["**价层电子对互斥理论（VSEPR theory，p.174 资料链接）**：① 分子立体构型由中心原子周围的“价层电子对”（包括**成键电子对**与**孤对电子**）相互排斥决定；② 电子对趋向尽可能彼此远离以减小斥力；③ 中心原子价层电子对数为 **2、3、4** 时，电子对几何分布分别为**直线形**、**平面三角形**、**正四面体**。","**分子极性 vs 非极性判别（p.174）**：","- **非极性分子**：整个分子电子云分布均匀（对称）。包括① 只含非极性键的分子（\\(\\mathrm{H_2, O_2, Cl_2, N_2}\\)）；② 含极性键但空间几何高度对称、各键极性相互抵消的多原子分子（如直线形 \\(\\mathrm{CO_2}\\)、正四面体 \\(\\mathrm{CH_4}\\) 与 \\(\\mathrm{CCl_4}\\)、平面三角形 \\(\\mathrm{BF_3}\\)）。","- **极性分子**：电子云分布不均匀（不对称）。包括① 含极性键的双原子分子（\\(\\mathrm{HCl, CO, HF}\\)）；② 键极性空间不对称无法抵消的多原子分子（如角形/V形 \\(\\mathrm{H_2O}\\)、三角锥形 \\(\\mathrm{NH_3}\\)）。"],"table":{"headers":["分子","中心原子价层电子对数（孤对数）","分子空间构型","化学键类型","分子极性"],"rows":[["CO₂","2 对（0 孤对，双键计 1 对方向）","直线形（180°）","C=O 极性共价键","非极性分子（对称抵消）"],["CH₄","4 对（0 孤对）","正四面体（109.5°）","C—H 极性共价键","非极性分子（完全对称）"],["NH₃","4 对（1 孤对）","三角锥形（≈107°）","N—H 极性共价键","极性分子（不对称）"],["H₂O","4 对（2 孤对）","角形 / V 形（≈104.5°）","O—H 极性共价键","极性分子（不对称）"],["HCl / Cl₂","双原子分子","直线形","HCl 极性键；Cl₂ 非极性键","HCl 极性；Cl₂ 非极性"]]},"takeaway":"**“极性键不一定构成极性分子”**——关键看空间构型中所有化学键的极性矢量是否**对称抵消**（如 \\(\\mathrm{CO_2}\\) 与 \\(\\mathrm{CH_4}\\)）。"},{"kind":"definition","title":"7.1.3 金属键与“电子海洋”模型","pageRef":"化上 p.175","body":["**金属键（metallic bond）**：金属原子的部分或全部外围电子受原子核束缚较弱，在金属晶体中脱离原子核成为可在整个金属晶体中自由移动的**自由电子（free electron）**，而金属原子变成按一定规律堆积的**金属阳离子**。","**“电子海洋”图像**：自由电子不再属于某一个特定金属离子，而是被许多金属离子所共用——可想象成金属阳离子沉浸在自由电子形成的“电子海洋”中，自由电子与金属阳离子之间的强烈相互作用即为金属键。"],"takeaway":"金属键既无方向性也无饱和性，这正是金属能够自由锻造延展、导热与导电（电子海洋受外电压定向移动）的微观根源。"}],"formulas":[{"title":"电负性差（ΔEN）判断化学键类型经验标尺","tex":"\\Delta\\mathrm{EN} = |\\mathrm{EN}_A - \\mathrm{EN}_B|: \\quad \\Delta\\mathrm{EN}=0\\text{（非极性）},\\quad 0<\\Delta\\mathrm{EN}<1.7\\text{（极性共价）},\\quad \\Delta\\mathrm{EN}>1.7\\text{（离子键）}","plain":"ΔEN = 0 非极性共价键；0 < ΔEN < 1.7 极性共价键；ΔEN > 1.7 离子键","conditions":"一般规律（存在少数特例：如 HF 虽 ΔEN=1.9 仍属共价分子；BeCl₂ ΔEN=1.5 与 AlCl₃ ΔEN=1.5 亦为共价化合物）","pageRef":"化上 p.171–172","note":"图 7-9 显示离子性百分数随 ΔEN 呈 S 形平滑递增，不存在绝对截断。"},{"title":"配位键形成过程化学表达","tex":"\\mathrm{H_3N: + H^+} \\longrightarrow [\\mathrm{NH_4}]^+,\\qquad \\mathrm{H_2\\ddot{O}: + H^+} \\longrightarrow [\\mathrm{H_3O}]^+","plain":"NH₃(孤对电子) + H⁺(空轨域) → [NH₄]⁺；H₂O + H⁺ → [H₃O]⁺","conditions":"配体原子必有孤对电子（如 N, O, Cl⁻），中心原子或离子必有空轨域（如 H⁺, AlCl₃, Cu²⁺）","pageRef":"化上 p.169","note":"NH₄⁺ 与 H₃O⁺ 中形成配位键后，所有 N—H 或 O—H 键彼此完全等同。"}],"pitfalls":[{"title":"误把离子化合物（或分子晶体）画成错误电子式，或漏标 [ ] 与电荷","wrong":"“氯化镁电子式写作 `Cl:Mg:Cl`，或氨气中 N 周围未画孤对电子写成 `H:N(H):H`。”","diagnosis":"\\(\\mathrm{MgCl_2}\\) 是离子化合物（不能画成共价共用电子对），且两个 \\(\\mathrm{Cl^-}\\) 不可合并写成 `Cl₂²⁻`；共价分子的电子式必须把所有成键与未成键的最外层电子全部点出。","right":"\\(\\mathrm{MgCl_2}\\) 正确电子式：`[:Cl:]⁻ Mg²⁺ [:Cl:]⁻`（两旁各有完整 8 点）；\\(\\mathrm{NH_3}\\) 的 N 上方必须画出一对孤对电子；\\(\\mathrm{N_2}\\) 为 `:N⋮⋮N:`（3 对共用电子+各 1 对孤对电子）。","checkRule":"电子式检查两步：① 离子还是共价（有方括号+电荷 vs 共用点对）；② 每个原子最外层是否达到 8（或 H 的 2）电子？"},{"title":"把“含极性键”直接等同于“极性分子”，或把“金属+非金属”全判成离子键","wrong":"“\\(\\mathrm{CO_2}\\) 和 \\(\\mathrm{CH_4}\\) 分子内都含有极性共价键，所以它们都是极性分子；且 \\(\\mathrm{AlCl_3}\\) 含金属 Al 和非金属 Cl，所以它是离子化合物。”","diagnosis":"\\(\\mathrm{CO_2}\\)（直线形）和 \\(\\mathrm{CH_4}\\)（正四面体）空间对称使键极性抵消，均是非极性分子；而教材 p.172 交流分享特意点出 \\(\\mathrm{AlCl_3}\\)（\\(\\Delta\\mathrm{EN} = 3.0 - 1.5 = 1.5 < 1.7\\)）和 \\(\\mathrm{BeCl_2}\\)（\\(\\Delta\\mathrm{EN} = 3.0 - 1.5 = 1.5 < 1.7\\)）属于**共价化合物**！","right":"判断分子极性既看键极性更看**空间对称性**；判断金属与非金属间成键看电负性差（\\(\\mathrm{BeCl_2, AlCl_3}\\) 为共价化合物，熔点很低且熔融不导电）。","checkRule":"遇到 \\(\\mathrm{BeCl_2, AlCl_3}\\)，立即想起它们是“金属+非金属但 \\(\\Delta\\mathrm{EN}=1.5<1.7\\)”的共价化合物经典反例！"},{"title":"认为配位键形成后，原配位键在长度或性质上不同于其他共价键","wrong":"“\\(\\mathrm{NH_4^+}\\) 离子中有一个配位键，因此这 1 个键比另外 3 个普通 N—H 键更弱、更容易先断掉。”","diagnosis":"配位键只是**形成来源**不同（由 N 单方提供电子对），形成之后电子云完全重新分配均等化。","right":"化上 p.169 原文强调：在 \\(\\mathrm{NH_4^+}\\) 中，**4 个 N—H 键的键长、键角（109.5° 正四面体）和化学性质完全相同**！","checkRule":"问“NH₄⁺ 中 4 个键是否完全等价？”答：**是，完全相同**。"}],"examples":[{"label":"例 7.1.1","tier":"L2","tierLabel":"L2 校内期末","title":"教材 p.172 & p.196 第 2 题综合：电负性判键型、配位键与分子极性","prompt":"现有八种微粒或物质：① \\(\\mathrm{F_2}\\) ② \\(\\mathrm{NaF}\\) ③ \\(\\mathrm{BeCl_2}\\) ④ \\(\\mathrm{NH_3}\\) ⑤ \\(\\mathrm{NH_4^+}\\) ⑥ \\(\\mathrm{H_3O^+}\\) ⑦ \\(\\mathrm{CO_2}\\) ⑧ \\(\\mathrm{CH_4}\\)。（电负性：H 2.1, Be 1.5, C 2.5, N 3.0, O 3.5, F 4.0, Na 0.9, Cl 3.0）。请回答：(1) 属于离子化合物的是哪个？请写出其电负性差 \\(\\Delta\\mathrm{EN}\\) 并说明为什么 \\(\\mathrm{BeCl_2}\\) 不属于离子化合物；(2) 以上微粒中，含有**配位键**的有哪些？含有**非极性共价键**的是哪个？(3) ⑦ \\(\\mathrm{CO_2}\\) 与 ⑧ \\(\\mathrm{CH_4}\\) 分子内都是极性共价键，为什么它们却都是非极性分子？","clues":"计算 ΔEN(NaF) 与 ΔEN(BeCl₂) 和 1.7 比较；配位键看 N 或 O 的孤对电子接纳 H⁺。","strategy":"逐项对照电负性界限 1.7、配位键形成条件及 VSEPR 对称抵消。","given":"8 种物质及教材电负性数据","principle":"ΔEN > 1.7 为离子键；单方供电子对成配位键；键偶极对称抵消为非极性分子。","steps":["(1) ② \\(\\mathrm{NaF}\\) 中 \\(\\Delta\\mathrm{EN} = 4.0 - 0.9 = 3.1 > 1.7\\)，属于**离子化合物**；而 ③ \\(\\mathrm{BeCl_2}\\) 中 \\(\\Delta\\mathrm{EN} = 3.0 - 1.5 = 1.5 < 1.7\\)，故通常形成共价键，属于共价化合物。","(2) 含有配位键的是 **⑤ \\(\\mathrm{NH_4^+}\\) 与 ⑥ \\(\\mathrm{H_3O^+}\\)**（分别由 \\(\\mathrm{NH_3}\\) 的 N 和 \\(\\mathrm{H_2O}\\) 的 O 提供孤对电子与 \\(\\mathrm{H^+}\\) 空轨域结合）；含非极性共价键的是 **① \\(\\mathrm{F_2}\\)**（同种 F 原子成键，\\(\\Delta\\mathrm{EN}=0\\)）。","(3) \\(\\mathrm{CO_2}\\) 为**直线形**对称分子（键角 \\(180^\\circ\\)），两个方向相反、大小相等的 \\(\\mathrm{C=O}\\) 极性相互抵消；\\(\\mathrm{CH_4}\\) 为**正四面体**对称结构（键角 \\(109.5^\\circ\\)），4 个 \\(\\mathrm{C-H}\\) 键空间均匀分布、极性矢量和为零，因此整个分子的电子云分布均匀，皆为非极性分子。"],"answer":"(1) ② NaF（ΔEN=3.1>1.7）；BeCl₂ ΔEN=1.5<1.7 属共价化合物；(2) 配位键：⑤ NH₄⁺、⑥ H₃O⁺；非极性键：① F₂；(3) 空间构型高度对称（直线形/正四面体），极性键矢量相互抵消。","markingPoints":["利用 ΔEN 与 1.7 比较区分 NaF 与 BeCl₂（2分）","正确识别 NH₄⁺, H₃O⁺ 含配位键及 F₂ 含非极性键（2分）","指出直线形/正四面体空间对称使极性相互抵消（1分）"],"verification":"化上 p.172 交流分享第 2 题与 p.196 第 2 题核对。","pitfall":"第(1)问盲目按“金属+非金属”把 BeCl₂ 误判为离子化合物；第(2)问漏掉 H₃O⁺ 中的配位键。"},{"label":"例 7.1.2","tier":"L3","tierLabel":"L3 预试拔高","title":"含多种化学键的复杂物质解析与 VSEPR 键角比较","prompt":"(1) 分析下列四种常见物质中各自包含的所有化学键类型（从“离子键、极性共价键、非极性共价键、配位键、金属键”中选填）：\\(\\mathrm{NH_4Cl}\\)、\\(\\mathrm{Na_2O_2}\\)（过氧化钠）、\\(\\mathrm{NaOH}\\)、合金钢。(2) 已知 \\(\\mathrm{CH_4, NH_3, H_2O}\\) 三者的中心原子价层电子对总数均为 4 对，请运用 VSEPR 理论中“孤对电子对成键电子对排斥力大于成键电子对之间排斥力”的原理，解释三者键角依次递减（\\(109.5^\\circ > 107^\\circ > 104.5^\\circ\\)）的原因。","clues":"过氧化钠含有过氧根离子 [O—O]²⁻；孤对电子只受一个原子核束缚，电子云更肥大、斥力更强！","strategy":"先拆阴阳离子找离子键，再拆多原子离子内部找共价键/配位键；第(2)问比较孤对电子个数 0, 1, 2 对斥力的影响。","given":"NH₄Cl, Na₂O₂, NaOH, 钢；CH₄(0孤), NH₃(1孤), H₂O(2孤)","principle":"复杂离子化合物内部多键共存；VSEPR 斥力顺序：孤对–孤对 > 孤对–成键 > 成键–成键。","steps":["(1) **\\(\\mathrm{NH_4Cl}\\)**：\\(\\mathrm{NH_4^+}\\) 与 \\(\\mathrm{Cl^-}\\) 间为**离子键**，\\(\\mathrm{NH_4^+}\\) 内部含 3 个**极性共价键**与 1 个**配位键**（统称含离子键、极性共价键和配位键）；**\\(\\mathrm{Na_2O_2}\\)**：\\(\\mathrm{Na^+}\\) 与 \\(\\mathrm{O_2^{2-}}\\) 间为**离子键**，\\(\\mathrm{O_2^{2-}}\\) 内部为 O—O **非极性共价键**；**\\(\\mathrm{NaOH}\\)**：\\(\\mathrm{Na^+}\\) 与 \\(\\mathrm{OH^-}\\) 间为**离子键**，\\(\\mathrm{OH^-}\\) 内部为 O—H **极性共价键**；**合金钢**：金属阳离子与自由电子间的**金属键**。","(2) \\(\\mathrm{CH_4, NH_3, H_2O}\\) 中心原子价层电子对均为 4 对，但孤对电子数依次为 **0、1、2**。由于孤对电子仅受中心原子核单方吸引，电子云较为松散肥大，对相邻成键电子对的排斥力大于成键电子对之间的排斥力，因此孤对电子越多，对成键电子对的挤压越大，键角依次缩小（\\(109.5^\\circ > 107^\\circ > 104.5^\\circ\\)）。"],"answer":"(1) NH₄Cl（离子+极性共价+配位）、Na₂O₂（离子+非极性共价）、NaOH（离子+极性共价）、合金钢（金属键）；(2) 孤对电子数 0→1→2 增多，孤对对成键电子对排斥力更强，把键角压缩变小。","markingPoints":["准确析出 NH₄Cl 与 Na₂O₂ 内部的多种化学键（3分）","点出孤对电子数递增（0,1,2）及“孤对斥力 > 成键斥力”压缩键角（2分）"],"verification":"过氧化钠与氢氧化钠电子式是 UEC 卷一/卷二经典多键共存辨析题。","pitfall":"误把 Na₂O₂ 当成纯离子键而漏掉过氧根内部的 O—O 非极性键。"}],"practice":[{"id":"chem7-7.1-q1","tier":"L1","tierLabel":"L1 基础","examStyle":"P1 选择","q":"下列物质中，全部以共价键结合形成的共价化合物是（　）。","options":["A. NaCl","B. MgO","C. NH₃","D. NaOH"],"correctOption":"C","given":"四种常见化合物","method":"识别含金属阳离子的离子化合物 vs 全非金属共价化合物","principle":"全非金属元素原子间通常以共用电子对形成共价化合物（除铵盐等）。","steps":["A NaCl、B MgO 均含离子键；D NaOH 含 Na⁺ 与 OH⁻ 间离子键（及 OH⁻ 内共价键），属于离子化合物；C NH₃ 全由极性共价键构成，属于共价化合物。"],"ans":"C","markingPoints":["识别 NaOH 是离子化合物而非共价化合物"],"verification":"化上 p.163–168。","pitfall":"看到 NaOH 中有 O—H 共价键就误选为共价化合物（凡含离子键的化合物一律叫离子化合物）。"},{"id":"chem7-7.1-q2","tier":"L2","tierLabel":"L2 期末","examStyle":"P1 选择","q":"下列分子中，既含有极性共价键、又属于**非极性分子**的是（　）。","options":["A. H₂O","B. NH₃","C. CO₂","D. Cl₂"],"correctOption":"C","given":"四种分子：H₂O, NH₃, CO₂, Cl₂","method":"先筛除含非极性键的 Cl₂，再检验分子空间对称性","principle":"直线形 CO₂ 两 C=O 极性键方向相反相互抵消。","steps":["A H₂O（角形）与 B NH₃（三角锥）均为极性键+极性分子；D Cl₂ 含非极性键+非极性分子；C CO₂ 含 C=O 极性键，因直线形对称抵消而成为非极性分子。"],"ans":"C","markingPoints":["严格区分“键极性”与“分子极性”"],"verification":"化上 p.174 原文示例。","pitfall":"误选 D（只含非极性键）或 A/B。"},{"id":"chem7-7.1-q3","tier":"L2","tierLabel":"L2 期末","examStyle":"P2 简答","q":"试回答：(1) 什么是配位键？用带箭头的结构式表示出 \\(\\mathrm{NH_4^+}\\) 离子的结构，并说明 \\(\\mathrm{NH_3}\\) 与 \\(\\mathrm{H^+}\\) 形成 \\(\\mathrm{NH_4^+}\\) 时双方分别提供了什么？(2) 金属导体为什么能导电、导热且具有延展性？请用“电子海洋”金属键模型简要说明（p.175）。","given":"配位键定义（p.169）；金属键模型（p.175）","method":"紧扣教材原话：孤对电子+空轨域；自由电子在外电场/热振动/受外力滑移中的作用","principle":"配位键与金属键微观机制。","steps":["(1) 由一个原子单方面提供一对孤对电子与另一个接受电子（有空轨域）的原子形成的共价键，叫做**配位键**。结构式表示为带方括号的正离子，其中 3 个普通 `N—H` 键与 1 个 `N→H` 配位键（整体标 `+` 电荷）。形成过程中，\\(\\mathrm{NH_3}\\) 的 N 原子提供了**一对孤对电子**，\\(\\mathrm{H^+}\\) 提供了 **1s 空轨域**。","(2) 金属晶体中金属阳离子沉浸在**自由电子**构成的“电子海洋”中。通电时自由电子在外加电压下**定向移动**而导电；受热时自由电子通过快速运动和碰撞传递热量而导热；受外力敲打使金属离子层发生相对滑移时，自由电子仍能如润滑胶黏剂般将错位后的金属阳离子维系在一起，金属键不断裂，因此具有良好延展性。"],"ans":"(1) 单方供孤对电子成共价键；N 提供孤对电子，H⁺ 提供 1s 空轨域；(2) 自由电子定向移动导电、碰撞传热、维系层间滑移不断键而具延展性。","markingPoints":["完整叙述配位键定义及 N 供孤对电子、H⁺ 供空轨域（2分）","正确画出含箭头结构式（1分）","用自由电子解释金属导电与延展性（2分）"],"verification":"对照化上 p.169 图 7-6 与 p.175 金属键文本核对。","pitfall":"解释金属导电时误答“金属阳离子定向移动导电”（教材 p.195 第 8 题专考此坑，金属导电靠**自由电子**定向移动，而非阳离子！）。"},{"id":"chem7-7.1-q4","tier":"L3","tierLabel":"L3 预试","examStyle":"P1 选择","q":"查阅教材图 7-9 电负性表（H 2.1, C 2.5, N 3.0, O 3.5, F 4.0, S 2.5, Cl 3.0, Br 2.8, I 2.5, Na 0.9），在下列共价键中，**键的极性最强**的是（　）。","options":["A. H—I","B. H—Cl","C. N—F","D. O—H"],"correctOption":"D","given":"各原子鲍林电负性值","method":"计算每个共价键两端原子的电负性差值 ΔEN 并比较大小","principle":"元素电负性差值越大，对应原子形成的键极性越强（p.172）。","steps":["A. \\(\\Delta\\mathrm{EN}(\\mathrm{H-I}) = 2.5 - 2.1 = 0.4\\)；","B. \\(\\Delta\\mathrm{EN}(\\mathrm{H-Cl}) = 3.0 - 2.1 = 0.9\\)；","C. \\(\\Delta\\mathrm{EN}(\\mathrm{N-F}) = 4.0 - 3.0 = 1.0\\)；","D. \\(\\Delta\\mathrm{EN}(\\mathrm{O-H}) = 3.5 - 2.1 = 1.4\\)。","差值最大的是 **O—H**（1.4），故键的极性最强。"],"ans":"D","markingPoints":["利用 ΔEN 数值大小精准比较键的极性"],"verification":"化上 p.171–172 & p.196 第 2 题方法一致。","pitfall":"看到 C 选项有电负性最大的 F 就直觉选 C，没算差值（4.0 − 3.0 = 1.0 < 1.4）。"},{"id":"chem7-7.1-q5","tier":"L4","tierLabel":"L4 统考拔高","examStyle":"P1 选择","q":"下列各组物质中，所有微粒的化学键组成特征与空间结构分析**完全正确**的是（　）。","options":["A. H₂O₂：既含极性共价键又含非极性共价键，属于极性分子","B. CCl₄：只含非极性共价键，正四面体构型，属于非极性分子","C. NH₄NO₃：全部由共价键构成，不存在离子键","D. SO₂ 与 CO₂：均由极性键构成，分子空间构型均为直线形"],"correctOption":"A","given":"H₂O₂, CCl₄, NH₄NO₃, SO₂, CO₂ 结构特征","method":"逐一检验分子/盐内键型与 VSEPR 构型（注意 S 有一对孤对电子！）","principle":"H—O—O—H 含极性 O—H 与非极性 O—O 且呈半展开不对称构型；NH₄NO₃ 为离子化合物。","steps":["A 对：\\(\\mathrm{H_2O_2}\\) 结构式 \\(\\mathrm{H-O-O-H}\\) 中，O—H 为极性键、O—O 为非极性键，且两 H 不对称（呈书页展开角），故为极性分子。","B 错：\\(\\mathrm{CCl_4}\\) 中 C—Cl 是**极性共价键**，只因正四面体对称而为非极性分子。","C 错：\\(\\mathrm{NH_4NO_3}\\) 是由 \\(\\mathrm{NH_4^+}\\) 与 \\(\\mathrm{NO_3^-}\\) 构成的**离子化合物**，含离子键！","D 错：\\(\\mathrm{CO_2}\\) 中心 C 无孤对电子是直线形；而 \\(\\mathrm{SO_2}\\) 中心 S 有 6 个价电子，成 2 个双键后剩 **1 对孤对电子**，故为角形（V形）极性分子！"],"ans":"A","markingPoints":["同时掌握 H₂O₂ 键型极性与排查 CCl₄/NH₄NO₃/SO₂ 陷阱"],"verification":"H₂O₂ 为典型极性分子（偶极矩 > 0），SO₂ 键角约 119° 呈 V 形。","pitfall":"错选 D，误以为所有 AB₂ 型三原子分子都是直线形。"}],"cheatSheet":["电负性判别（p.172）：\\(>1.8\\) 非金属，\\(<1.8\\) 金属；**\\(\\Delta\\mathrm{EN} > 1.7\\) 离子键，\\(<1.7\\) 共价键**（牢记 \\(\\mathrm{BeCl_2, AlCl_3}\\) 虽含金属但为共价化合物）。","配位键（\\(\\mathrm{NH_4^+, H_3O^+}\\)）：一方供孤对电子 + 一方供空轨域，形成后所有共价键**键长、键角、性质完全相同**。","VSEPR 与分子极性：**\\(\\mathrm{CO_2}\\)（直线）、\\(\\mathrm{CH_4}\\)（正四面体）**对称抵消 = **非极性分子**；**\\(\\mathrm{H_2O}\\)（角形）、\\(\\mathrm{NH_3}\\)（三角锥）**不对称 = **极性分子**。"],"kbEntryIds":["kb-chem7-ionic-bond","kb-chem7-covalent-coordinate","kb-chem7-vsepr-polarity"],"quiz":{"q":"二氯甲烷（\\(\\mathrm{CH_2Cl_2}\\)）和四氯化碳（\\(\\mathrm{CCl_4}\\)）都是以碳为中心的四面体分子，请问哪一个是极性分子、哪一个是非极性分子？","given":"C—H 与 C—Cl 键电负性及键长不同","method":"检验四面体 4 个顶点原子是否完全相同","principle":"正四面体完全对称才可抵消各极性键矢量。","steps":["\\(\\mathrm{CCl_4}\\) 四个顶点全为 Cl，正四面体完全对称，极性相互抵消 ⇒ **非极性分子**。","\\(\\mathrm{CH_2Cl_2}\\) 两个顶点为 H、两个为 Cl，键极性大小不等，矢量无法抵消 ⇒ **极性分子**。"],"ans":"\\(\\mathrm{CH_2Cl_2}\\) 是极性分子，\\(\\mathrm{CCl_4}\\) 是非极性分子。"},"diagrams":[{"src":"assets/fig/v2/chem07-vsepr-shapes.svg","caption":"图 7-1 常见共价分子（CO₂ / H₂O / NH₃ / CH₄）的 VSEPR 空间构型与分子极性判别","alt":"VSEPR空间构型与分子极性图","pageRef":"化上 p.173–174"}]},{"id":"7.2","t":"分子间作用力","anchor":{"pages":"化上 p.176–181","syllabus":"1.5.4 范德华力与氢键及其对物质物理性质的影响","examScopes":["sem1_final","pre_exam","sem2_final","uec"],"examWeight":"P1 熔沸点/溶解度排序 + P2 氢化物沸点反常曲线（图 7-14）必考分析","terms":"intermolecular forces · van der Waals forces · instantaneous dipole · hydrogen bond","prerequisites":["极性分子与非极性分子概念（7.1.2）","元素的电负性与原子半径大小（F, O, N 处于第 2 周期右上角）"],"goals":["理解范德华力的静电本质（含非极性分子瞬间极性机制），并用相对分子质量（Mr）解释卤素单质 F₂→I₂ 熔沸点递增（表 7-5）。","掌握氢键 X—H···Y 的形成条件（X,Y 为 F, O, N）及强度阶梯（共价键:氢键:范德华力 ≈ 100:10:1）。","能够用分子间氢键解释 H₂O/HF/NH₃ 沸点反常、水/冰在 4℃ 密度异常及乙醇/氨水极易溶于水现象。"]},"concepts":[{"kind":"mechanism","title":"7.2.1 范德华力（van der Waals forces）与表 7-5 卤素熔沸点规律","pageRef":"化上 p.176–178","body":["**概念与特点**：分子与分子之间存在的一种普遍而较弱的静电作用力，固体、液体和气体分子间都存在，与共价键不同，范德华力**一般没有饱和性和方向性**。","**产生机制（图 7-11）**：① **极性分子**之间（如 \\(\\mathrm{HCl}\\)）靠带异种部分电荷的一端相互吸引；② **非极性分子**（如 \\(\\mathrm{H_2, Cl_2}\\)）虽然平均电荷均匀，但电子不停运动会在某一瞬间相对集中到一端形成**瞬间极性**，从而诱导邻近分子产生吸引。","**影响因素（表 7-5）**：对于组成和结构相似且无氢键的分子，**相对分子质量越大**，电子数越多、越容易极化，分子间范德华力越强，物质的**熔点和沸点越高**。"],"table":{"headers":["卤素单质","相对分子质量 Mr","熔点 / ℃","沸点 / ℃","常温常压状态"],"rows":[["F₂","38","−219.6","−188.1","浅黄绿色气体"],["Cl₂","71","−101","−34.6","黄绿色气体"],["Br₂","160","−7.2","58.8","深红棕色液体"],["I₂","254","113.5","184.4","紫黑色固体"]]},"takeaway":"卤素单质熔沸点 \\(\\mathrm{F_2 < Cl_2 < Br_2 < I_2}\\) 由**范德华力**决定；而 \\(\\mathrm{F_2}\\) 到 \\(\\mathrm{I_2}\\) 化学活泼性/热稳定性减弱则由**共价键**键能决定，两者切勿混为一谈！"},{"kind":"law","title":"7.2.2 氢键（X—H···Y）的形成条件与强度比例（p.178–179）","pageRef":"化上 p.178–179","body":["**氢键形成机制（以 HF 为例）**：在 \\(\\mathrm{H-F}\\) 分子中，由于 F 的电负性极大（4.0）且半径小，共用电子对强烈偏向 F，使 H 原子几乎成为“裸露”带部分正电荷（\\(\\delta^+\\)）的质子；这个半径极小的正电 H 核会强烈吸引另一分子中电负性大、半径小且有孤对电子的 F、O 或 N 原子，产生比一般范德华力强得多的静电作用——**氢键（hydrogen bond）**。","**通式与类别**：记作 **\\(\\mathrm{X-H\\cdots Y}\\)**（其中 X、Y 代表电负性大而原子半径较小的非金属元素，主要指 **F、O、N**）。氢键既可存在于**分子之间**（如 \\(\\mathrm{HF, H_2O, NH_3}\\)、乙醇），也可存在于**分子内部**（如蛋白质、DNA 双螺旋结构两条链的碱基配对，p.180）。","**强度比例（p.179 原文）**：氢键不是化学键，是一种较强的分子间作用力，大约有：**共价键 : 氢键 : 范德华力 = 100 : 10 : 1**。"],"takeaway":"记住形成氢键的“三巨头”：**F、O、N**！而 HCl、H₂S、PH₃ 因 Cl、S、P 原子半径较大或电负性不够大，分子间**不能形成氢键**。"},{"kind":"mechanism","title":"氢键对沸点反常（图 7-14）、冰的密度及溶解度的三大影响","pageRef":"化上 p.179–180","body":["**① 氢化物沸点反常升高（图 7-14，p.180）**：固/液态物质熔化或汽化时必须额外消耗能量克服分子间氢键，使含氢键的物质熔沸点远高于同族规律预期：","- **IVA 族（无氢键）**：\\(\\mathrm{CH_4 < SiH_4 < GeH_4 < SnH_4}\\)（完全按 \\(M_r\\) 递增）；","- **VIA 族**：\\(\\mathrm{H_2O\\;(100\\,^\\circ\\mathrm{C}) \\gg H_2Te > H_2Se > H_2S}\\)（每个水分子平均可形成更多氢键，故水沸点高于 HF！）；","- **VIIA 族**：\\(\\mathrm{HF\\;(\\text{约 }20\\,^\\circ\\mathrm{C}) > HI > HBr > HCl}\\)（注意比较 HCl < HBr < HI < HF）；","- **VA 族**：\\(\\mathrm{SbH_3 > NH_3\\;(-33\\,^\\circ\\mathrm{C}) > AsH_3 > PH_3}\\)（\\(\\mathrm{NH_3}\\) 虽高于 \\(\\mathrm{PH_3, AsH_3}\\)，但仍略低于高 \\(M_r\\) 的 \\(\\mathrm{SbH_3}\\)，仔细看图 7-14 曲线即可发现！）。","**② 水和冰的反常密度（图 7-13，p.179）**：低于 \\(4\\,^\\circ\\mathrm{C}\\) 时，水分子因氢键的方向性排成高度有序的**敞开式**三维网状结构，分子间隙变大，故冰的密度小于液态水（液态水在 \\(4\\,^\\circ\\mathrm{C}\\) 时密度最大）。","**③ 极易溶解现象（p.179–180）**：\\(\\mathrm{NH_3}\\) 极易溶于水（1:700）、乙醇（\\(\\mathrm{CH_3CH_2OH}\\)）能与水任意比例互溶，均因为溶质分子与水分子之间能形成大量的**分子间氢键**。"],"takeaway":"观察教材图 7-14 细节：**沸点最高是 \\(\\mathrm{H_2O}\\)（而非 \\(\\mathrm{HF}\\)）**，因 1 个 \\(\\mathrm{H_2O}\\) 分子可同时形成 2 倍于 \\(\\mathrm{HF}\\) 的平均氢键数；而 \\(\\mathrm{HF}\\) 虽高于 \\(\\mathrm{HI}\\)，\\(\\mathrm{NH_3}\\) 却仍低于 \\(\\mathrm{SbH_3}\\)！"}],"formulas":[{"title":"三种微观作用力相对强度数量级关系","tex":"\\text{共价键} : \\text{氢键} : \\text{范德华力} \\approx 100 : 10 : 1","plain":"共价键 : 氢键 : 范德华力 ≈ 100 : 10 : 1","conditions":"数量级对比（典型共价键 200–500 kJ/mol，氢键 10–40 kJ/mol，范德华力 1–10 kJ/mol）","pageRef":"化上 p.179","note":"氢键比范德华力强得多，但仍远弱于共价键，因此氢键属于“较强的分子间作用力”，不是化学键。"},{"title":"不同族氢化物沸点反常比较序列（图 7-14）","tex":"\\mathrm{H_2O} > \\mathrm{HF} > \\mathrm{NH_3} > \\mathrm{CH_4};\\qquad \\mathrm{H_2O} > \\mathrm{H_2Te} > \\mathrm{H_2Se} > \\mathrm{H_2S};\\qquad \\mathrm{HF} > \\mathrm{HI} > \\mathrm{HBr} > \\mathrm{HCl}","plain":"H₂O > HF > NH₃ > CH₄；H₂O > H₂Te > H₂Se > H₂S；HF > HI > HBr > HCl","conditions":"101.3 kPa 常压下沸点","pageRef":"化上 p.180 图 7-14","note":"注意卤化氢熔点（表 p.196 第 4 题）中 HI (-50.79℃) > HF (-83.57℃) > HBr (-86.81℃) > HCl (-114.18℃)，熔点与沸点排名略有不同！"}],"pitfalls":[{"title":"误认为“氢键属于化学键”或“氢键决定分子的热稳定性”","wrong":"“因为 \\(\\mathrm{H_2O}\\) 分子间存在氢键，所以水受热到 \\(1000\\,^\\circ\\mathrm{C}\\) 都不易分解成氢气和氧气，稳定性极高。”","diagnosis":"水沸腾变成水蒸气破坏的是**分子间氢键**；而水受热分解为 \\(\\mathrm{H_2}\\) 和 \\(\\mathrm{O_2}\\) 破坏的是水分子内部的 **O—H 共价键**（教材 p.195 第 10 题 B 选项经典误区！）。","right":"氢键是**分子间作用力**（不是化学键），它只能升高物质的**熔点、沸点**和影响溶解度，**不能**增强分子内部化学键的热稳定性（热稳定性仅由分子内共价键强弱决定）。","checkRule":"遇到“氢键增强分子稳定性 / 分解温度”一律判错；记住“熔沸点看分子间，稳定性看共价键”。"},{"title":"把“形成氢键能力”与“氢键个数”搞混，误以为 HF 沸点高于 H₂O","wrong":"“氟的电负性大于氧，单个 H—F···H 氢键比 O—H···O 强，所以 HF 沸点高于 H₂O。”","diagnosis":"单个 F—H···F 氢键确实略强于 O—H···O，但在液态 HF 中 1 个 HF 只能与相邻分子平均形成 **1 个**氢键（锯齿链），而 1 个 H₂O 分子有 2 个 H 和 2 对孤对电子，平均可形成 **2 个**氢键（三维网络）！","right":"液态 \\(\\mathrm{H_2O}\\)（沸点 \\(100\\,^\\circ\\mathrm{C}\\)）需要破坏多得多的分子间氢键，故沸点远高于 \\(\\mathrm{HF}\\)（约 \\(20\\,^\\circ\\mathrm{C}\\)）。","checkRule":"牢记：单键强度 HF > H₂O > NH₃，但**沸点顺序一定是 H₂O (100℃) > HF (20℃) > NH₃ (-33℃)**。"},{"title":"误以为只有 NH₃、H₂O、HF 三种纯净物才能形成氢键","wrong":"“能够形成氢键的分子只有 NH₃、H₂O 和 HF 三种。”","diagnosis":"教材 p.195 第 10 题 D 选项专设此坑！凡含有 **F—H、O—H、N—H** 基团的分子（如乙醇 \\(\\mathrm{CH_3CH_2OH}\\)、乙酸 \\(\\mathrm{CH_3COOH}\\)、氨水、葡萄糖、蛋白质、DNA）均能形成氢键！","right":"\\(\\mathrm{NH_3, H_2O, HF}\\) 只是简单无机氢化物代表，绝大多数含 `-OH` 或 `-NH₂` 的有机分子与生物大分子都存在氢键。","checkRule":"看到“只有”二字限定能形成氢键的物质，立刻想起乙醇和生物大分子而判错。"}],"examples":[{"label":"例 7.2.1","tier":"L2","tierLabel":"L2 校内期末","title":"教材 p.180 交流分享 & p.196 第 4 题：氢化物熔沸点与氨水溶解度分析","prompt":"结合教材图 7-14（氢化物沸点曲线）与表（卤化氢熔点：\\(\\mathrm{HF}\\;-83.57\\,^\\circ\\mathrm{C},\\; \\mathrm{HCl}\\;-114.18\\,^\\circ\\mathrm{C},\\; \\mathrm{HBr}\\;-86.81\\,^\\circ\\mathrm{C},\\; \\mathrm{HI}\\;-50.79\\,^\\circ\\mathrm{C}\\)）回答：(1) 为什么 IVA 族氢化物 \\(\\mathrm{CH_4, SiH_4, GeH_4, SnH_4}\\) 的沸点随周期数增大而依次升高，而 \\(\\mathrm{H_2O, HF, NH_3}\\) 却显著偏离同族趋势反常升高？(2) 为什么卤化氢中 HCl 沸点低于 HBr、HBr 低于 HI，但热稳定性却是 \\(\\mathrm{HCl > HBr > HI}\\)？(3) 从分子间作用力解释为什么氨气极易溶于水，而甲烷极难溶于水？","clues":"分别对比“分子间作用力（Mr / 氢键）”与“分子内共价键键能”两个不同层次的作用力。","strategy":"严格锁定“物态变化找范德华力/氢键，分解稳定性找共价键，溶解性找溶质-水氢键与极性相似”。","given":"IVA/VA/VIA/VIIA 氢化物沸点；卤化氢熔点与稳定性；NH₃ vs CH₄ 溶解度","principle":"范德华力随 Mr 递增；F, O, N 氢化物形成分子间氢键；共价键键能随原子半径增大而减弱。","steps":["(1) IVA 族氢化物结构相似且分子间**均不含氢键**，从 \\(\\mathrm{CH_4}\\) 到 \\(\\mathrm{SnH_4}\\) 相对分子质量依次增大，分子间**范德华力依次增强**，故沸点依次升高；而 \\(\\mathrm{H_2O, HF, NH_3}\\) 中 H 分别与电负性大、半径小的 O、F、N 相连，分子间除了范德华力还形成了更强的**氢键**，汽化时需消耗更多能量克服氢键，因此沸点反常偏高。","(2) HCl、HBr、HI 分子间均无氢键，沸点由范德华力决定，因 \\(M_r(\\mathrm{HCl}) < M_r(\\mathrm{HBr}) < M_r(\\mathrm{HI})\\)，范德华力依次增大故沸点升高；而热稳定性取决于分子内部 **H—X 共价键的强弱**，从 Cl 到 I 原子半径增大，H—X 键长变长、键能减小，故热稳定性 \\(\\mathrm{HCl > HBr > HI}\\)。","(3) \\(\\mathrm{NH_3}\\) 是极性分子，且溶解后能与极性溶剂水分子之间形成大量**分子间氢键**（\\(\\mathrm{H_3N\\cdots H-OH}\\) 等），因此极易溶于水；而 \\(\\mathrm{CH_4}\\) 是非极性分子，既不具极性又不能与水分子形成氢键，故极难溶于水。"],"answer":"(1) IVA 族无氢键靠 Mr 增大增强范德华力；H₂O/HF/NH₃ 分子间存在氢键；(2) 沸点比范德华力（Mr），热稳定性比 H—X 共价键强弱；(3) NH₃ 为极性分子且能与水形成氢键。","markingPoints":["准确区分 IVA 族范德华力与 O/F/N 氢化物分子间氢键（2分）","说明沸点看范德华力、热稳定性看共价键（2分）","指出氨气与水分子间形成氢键及极性相似（1分）"],"verification":"化上 p.180 交流分享与 p.195 第 10 题核对。","pitfall":"第(2)问把“热稳定性”和“沸点”全混在一起用范德华力解释。"},{"label":"例 7.2.2","tier":"L3","tierLabel":"L3 预试拔高","title":"氢键方向性与物理性质综合推理（冰密度 + 液氨蒸发 + 分子内氢键）","prompt":"(1) 已知 \\(\\mathrm{H_2O(l)}\\) 汽化变成 \\(\\mathrm{H_2O(g)}\\) 时，实际破坏了哪几种作用力（有没有破坏共价键）？(2) 为什么冰（\\(0\\,^\\circ\\mathrm{C}\\)）能浮在 \\(4\\,^\\circ\\mathrm{C}\\) 的液态水面上？从微观结构（图 7-13）解释 \\(0\\,^\\circ\\mathrm{C}\\) 冰熔化成 \\(4\\,^\\circ\\mathrm{C}\\) 液态水时体积为什么反而缩小？(3) 邻羟基苯甲醛（分子内可形成氢键）与对羟基苯甲醛（分子间形成氢键）的分子式和相对分子质量完全相同，试预测哪一种物质的沸点更高，并简述理由。","clues":"液态水仅靠物理加热沸腾，H₂O 分子依然完整；分子间氢键拉近不同分子，而分子内氢键自我封闭，减少了分子间牵绊！","strategy":"紧扣“氢键存在于分子间还是分子内”对分子间聚集力的不同效果。","given":"水汽化、冰熔化、邻/对羟基苯甲醛对比","principle":"物理相变不破坏分子内共价键；冰的敞开式氢键；分子间氢键升高沸点而分子内氢键降低沸点。","steps":["(1) 水汽化是物理变化，只破坏水分子之间的**氢键和范德华力**，**没有**破坏水分子内部的 O—H 共价键。","(2) 在 \\(0\\,^\\circ\\mathrm{C}\\) 的冰晶体中，每个水分子借方向性强的氢键与周围 4 个水分子形成**高度有序的敞开式四面体排列**，晶体内部空隙大，故密度较小、能浮在水面；熔化成 \\(0\\sim 4\\,^\\circ\\mathrm{C}\\) 液态水时，部分有序氢键断裂，敞开结构塌陷使水分子排列更紧密，因此体积缩小、\\(4\\,^\\circ\\mathrm{C}\\) 时密度达到最大。","(3) **对羟基苯甲醛**的沸点更高。因为对位距离远，只能形成**分子间氢键**，大大增强了分子与分子之间的结合力；而邻羟基苯甲醛的 `-OH` 与 `-CHO` 相邻，优先形成**分子内氢键**，减少了它与其他分子之间形成氢键的机会，分子间作用力较弱，沸点较低。"],"answer":"(1) 仅破坏分子间氢键与范德华力，不断共价键；(2) 冰中氢键形成敞开式多空隙结构，熔化时部分氢键断裂塌陷致密；(3) 对羟基苯甲醛沸点更高（分子间氢键 vs 分子内氢键）。","markingPoints":["明确水汽化不断共价键（1分）","描述冰的敞开式氢键结构及熔化后塌陷致密过程（2分）","对比分子间氢键增强分子引力 vs 分子内氢键削弱分子间作用（2分）"],"verification":"对羟基苯甲醛沸点约 310℃，邻羟基苯甲醛（水杨醛）沸点仅 197℃，相差逾 110℃！","pitfall":"第(3)问误以为“只要有氢键就都一样高”，忽略了分子内氢键对沸点的降低效应。"}],"practice":[{"id":"chem7-7.2-q1","tier":"L1","tierLabel":"L1 基础","examStyle":"P1 选择","q":"下列物质的液态或固态分子之间，**不存在**氢键的是（　）。","options":["A. H₂O","B. NH₃","C. HF","D. HCl"],"correctOption":"D","given":"四种简单氢化物","method":"对照氢键三元素（F, O, N）检查中心原子","principle":"Cl 电负性相对较低（3.0）且原子半径远大于 F/O/N，HCl 分子间不形成氢键。","steps":["A(O)、B(N)、C(F) 均可形成分子间氢键；D(Cl) 原子半径较大，不形成氢键（故 HCl 沸点 -85℃ 远低于 HF 的 +19.5℃）。"],"ans":"D","markingPoints":["记住只有 F, O, N 连接的 H 能形成典型氢键"],"verification":"化上 p.179。","pitfall":"看到 Cl 的电负性是 3.0 与 N 相同，误以为 HCl 也有氢键（忽略 Cl 是第 3 周期原子，半径比 N 大很多！）。"},{"id":"chem7-7.2-q2","tier":"L2","tierLabel":"L2 期末","examStyle":"P1 选择","q":"卤素单质 \\(\\mathrm{F_2, Cl_2, Br_2, I_2}\\) 的沸点依次升高（\\(-188.1\\,^\\circ\\mathrm{C} \\to 184.4\\,^\\circ\\mathrm{C}\\)），其主要原因是（　）。","options":["A. 分子内共价键的键能依次增强","B. 卤素单质分子间形成了越来越强的氢键","C. 相对分子质量增大，分子间范德华力依次增强","D. 非金属性依次增强"],"correctOption":"C","given":"表 7-5 卤素单质数据（化上 p.177）","method":"定性单质晶体类型（分子晶体）及随 Mr 变化趋势","principle":"结构相似的无氢键分子晶体，相对分子质量越大，范德华力越强，熔沸点越高。","steps":["卤素单质均由非极性分子构成、无 H 原子不可能有氢键；沸腾只克服分子间范德华力（与分子内键能无关）。从 F₂ 到 I₂，Mr 从 38 增至 254，范德华力显著增强，故选 C。"],"ans":"C","markingPoints":["识别 Mr 增大导致范德华力增强"],"verification":"化上 p.177 表 7-5 与 p.188 问题解决第 1 题。","pitfall":"误选 A，混淆了熔沸点（分子间作用力）与化学键强度（其实 F—F 到 I—I 键能并非单调增强）。"},{"id":"chem7-7.2-q3","tier":"L2","tierLabel":"L2 期末","examStyle":"P2 简答","q":"请根据氢键与范德华力知识解释下列现象：(1) 为什么乙醇（\\(\\mathrm{C_2H_5OH}\\)）能与水以任意比例互溶，而相对分子质量相近的二甲醚（\\(\\mathrm{CH_3OCH_3}\\)）在水中溶解度却很低，且乙醇沸点（\\(78.5\\,^\\circ\\mathrm{C}\\)）远高于二甲醚（\\(-24.8\\,^\\circ\\mathrm{C}\\)）？(2) 请写出共价键、氢键和范德华力三者的近似强度比例关系，并说明“液氨受热蒸发”（p.195 第 5 题）克服的主要微粒间作用力。","given":"乙醇 vs 二甲醚（同分异构体，Mr=46）；液氨蒸发","method":"检查分子结构中是否存在 `-OH` 或 `N—H` 以判别氢键","principle":"乙醇含 O—H 基团，分子间及与水分子间均可形成氢键；二甲醚无 O—H，只能靠范德华力。","steps":["(1) 乙醇分子中含羟基（\\(\\mathrm{-OH}\\)），既能在乙醇分子间形成氢键使沸点显著升高，又能在溶于水时与水分子之间形成大量氢键，因而与水任意互溶；二甲醚中所有氢均与碳相连（无 O—H），既不能自身形成氢键也不易与水形成氢键，故沸点低且难溶于水。","(2) 教材 p.179 近似强度比：**共价键 : 氢键 : 范德华力 = 100 : 10 : 1**。液氨（\\(\\mathrm{NH_3}\\)）受热蒸发是分子晶体的汽化过程，吸收热量主要用于克服**分子间作用力（氢键与范德华力）**，分子内部 N—H 共价键不断裂。"],"ans":"(1) 乙醇含 -OH 可形成分子间氢键及与水形成氢键，二甲醚无氢键；(2) 100:10:1；克服分子间作用力（氢键与范德华力）。","markingPoints":["指出乙醇 -OH 可形成自身分子间氢键及与水分子间氢键（2分）","正确写出 100:10:1 比例并指出液氨蒸发克服分子间作用力（2分）"],"verification":"化上 p.179 原文与 p.195 第 5 题核对。","pitfall":"第(2)问漏说液氨中除范德华力外还有分子间氢键。"},{"id":"chem7-7.2-q4","tier":"L3","tierLabel":"L3 预试","examStyle":"P1 选择","q":"下列关于氢键的说法中，**正确**的是（　）。","options":["A. 氢键比范德华力强，因此氢键属于一种较弱的共价化学键","B. 分子间形成氢键会使物质熔沸点升高，同时也会大幅提高分子的热分解温度","C. 氨气极易溶于水，是因为氨分子与水分子之间形成了分子间氢键","D. 非极性分子之间不存在任何形式的分子间作用力"],"correctOption":"C","given":"氢键与范德华力概念辨析（化上 p.195 第 10 题改编）","method":"逐项排除“是化学键”、“提高稳定性”、“无范德华力”三大常见错项","principle":"氢键是非键分子间静电吸引；瞬间极性使非极性分子间亦存在范德华力。","steps":["A 错：氢键不是化学键；B 错：氢键不决定共价分子的热分解稳定性；C 对：NH₃ 与 H₂O 间形成氢键且均为极性分子；D 错：非极性分子（如 H₂、I₂、CO₂）因瞬间极性仍存在范德华力。"],"ans":"C","markingPoints":["准确避开教材 p.195 第 10 题全套陷阱"],"verification":"化上 p.177、p.179、p.195。","pitfall":"错选 A 或 B。"},{"id":"chem7-7.2-q5","tier":"L4","tierLabel":"L4 统考拔高","examStyle":"P1 选择","q":"观察教材图 7-14（一些氢化物的沸点曲线）与烷烃（\\(\\mathrm{CH_4, C_2H_6, C_3H_8}\\)）的沸点规律，下列四组物质按沸点由**高到低**排列完全正确的是（　）。","options":["A. HF > H₂O > NH₃ > CH₄","B. H₂O > SbH₃ > NH₃ > PH₃","C. H₂O > H₂S > H₂Se > H₂Te","D. HI > HF > HBr > HCl"],"correctOption":"B","given":"图 7-14 氢化物实测沸点数据","method":"回忆图 7-14 四条折线相对位置，特别核对 VA 族 SbH₃ vs NH₃ 细节！","principle":"H₂O(100℃) > HF(20℃) > SbH₃(-17℃) > NH₃(-33℃) > AsH₃(-55℃) > PH₃(-88℃)。","steps":["A 错：H₂O(100℃) > HF(20℃)，H₂O 排第一；","B 对：VA 族中第 5 周期的 \\(\\mathrm{SbH_3}\\)（\\(M_r\\approx 125\\)，沸点约 \\(-17\\,^\\circ\\mathrm{C}\\)）范德华力很大，其沸点略高于存在氢键但 \\(M_r\\) 极小的 \\(\\mathrm{NH_3}\\)（\\(-33\\,^\\circ\\mathrm{C}\\)），图 7-14 清楚显示橙线右侧 SbH₃ 高于左侧 NH₃，再往下是 PH₃（\\(-88\\,^\\circ\\mathrm{C}\\)）！","C 错：应为 H₂O > H₂Te > H₂Se > H₂S；","D 错：卤化氢沸点最高的是 HF（20℃ > HI -35℃），不是 HI。"],"ans":"B","markingPoints":["精准掌握图 7-14 VA 族 SbH₃ > NH₃ > AsH₃ > PH₃ 曲线细节"],"verification":"对照化上 p.180 图 7-14：纵坐标 SbH₃ 在 -25℃ 上方（约 -17℃），NH₃ 在 -25℃ 下方（-33℃），图线清晰无误。","pitfall":"死背“凡是第二周期氢化物沸点永远高于同族所有后续元素”，从而错选或错排 VA 族！"}],"cheatSheet":["范德华力无方向性、无饱和性；结构相似无氢键时 **\\(M_r\\) 越大、范德华力越强、熔沸点越高**（如 \\(\\mathrm{F_2<Cl_2<Br_2<I_2}\\)）。","氢键 \\(\\mathrm{X-H\\cdots Y}\\)（X, Y = **F, O, N**），强度比：**共价键 : 氢键 : 范德华力 = 100 : 10 : 1**。","图 7-14 沸点细节：**H₂O (100℃) > HF (20℃) > NH₃ (-33℃)**；VA 族注意 **SbH₃ > NH₃ > AsH₃ > PH₃**；氢键决定熔沸点与溶解度、冰低密度，**不决定分子热稳定性**。"],"kbEntryIds":["kb-chem7-vdw-forces","kb-chem7-hydrogen-bond"],"quiz":{"q":"将下列第 3 周期及第 2 周期氢化物按常压下**沸点由高到低**排序：\\(\\mathrm{H_2O,\\; HCl,\\; HF,\\; CH_4}\\)。","given":"H₂O(100℃), HF(~20℃), HCl(-85℃), CH₄(-161℃)","method":"先分“有氢键”与“无氢键”两组，再分别比氢键数或 Mr","principle":"分子间氢键显著升高沸点；无氢键比 Mr（HCl 36.5 > CH₄ 16）。","steps":["含氢键组：\\(\\mathrm{H_2O > HF}\\)；无氢键组：\\(\\mathrm{HCl > CH_4}\\)。"],"ans":"\\(\\mathrm{H_2O > HF > HCl > CH_4}\\)"}},{"id":"7.3","t":"晶体及其特性","anchor":{"pages":"化上 p.182–190","syllabus":"1.5.5 四大晶体（离子、原子、分子、金属晶体）的结构与性质比较","examScopes":["sem1_final","pre_exam","sem2_final","uec"],"examWeight":"P1 物理性质判晶体类型 + P2 结构—性质对照表与熔点排序大题必考点","terms":"ionic crystal · atomic crystal · molecular crystal · metallic crystal · melting point · electrical conductivity","prerequisites":["离子键、共价键与金属键的微观结合方式（7.1）","范德华力与氢键对分子聚集的作用（7.2）"],"goals":["掌握离子晶体、原子晶体、分子晶体、金属晶体各自的构成微粒和微粒间作用力。","熟练依据熔沸点、硬度与导电性实验特征（尤其是固态 vs 熔融态导电性）准确判断未知晶体类型。","能够比较同类晶体内部熔点高低（离子半径/电荷、共价键键长、分子 Mr/氢键、金属原子半径与自由电子数）。"]},"concepts":[{"kind":"table","title":"四大晶体类型结构与性质全面对照（综合表 7-6 & 表 7-9）","pageRef":"化上 p.183、p.190","body":["固体分为晶体（内部微粒在空间呈规则重复排列，具规则几何外形与固定熔点）和非晶体。按构成微粒不同，晶体分为**离子晶体、原子晶体、分子晶体、金属晶体**四大类。"],"table":{"headers":["比较项目","7.3.1 离子晶体","7.3.2 原子晶体","7.3.3 分子晶体","7.3.4 金属晶体"],"rows":[["构成微粒","阴离子、阳离子","原子","分子（或单原子稀有气体）","金属阳离子和自由电子"],["微粒间作用力","离子键（强静电作用）","共价键（三维空间网状）","范德华力（部分含氢键）","金属键（电子海洋）"],["熔点、沸点","较高（NaCl 801℃, BaCl₂ 1560℃）","很高（金刚石 3550℃, SiO₂ 1723℃）","较低（白磷 44.1℃, S 112.8℃）","差异极大（Hg −38.9℃ ~ W 3410℃）"],["硬度与机械性","较硬而脆（错位同电相斥易碎）","很大（很硬/硬脆）","较小（软或脆）","从柔软（Na）到硬（W），具延展性"],["导电性","固态不导电，**熔融或水溶液能导电**","固态、熔融均不导电（Si 半导体）","固态、熔融均不导电（部分水溶液电离导）","固态、熔融态皆为电的良导体"],["典型实例","NaCl, BaCl₂, CsCl, NaOH, K₂S","金刚石, SiO₂, 晶体 Si, SiC, BN","干冰 CO₂, 冰, P₄, S₈, I₂, 蔗糖, Ne","Na, Mg, Al, Fe, Cu, Cr, W"]]},"takeaway":"判断未知物晶体类型的最可靠“三步诊断法”：① **固态导电** ⇒ 金属晶体（注：石墨层状混合晶体例外）；② **固态不导、熔融导电** ⇒ 离子晶体；③ **固态、熔融皆不导** ⇒ 看熔点：很高（>1000℃）多为**原子晶体**，较低/易挥发升华多为**分子晶体**。"},{"kind":"mechanism","title":"原子晶体（金刚石 & 二氧化硅）vs 分子晶体（干冰）对比","pageRef":"化上 p.186–188","body":["**原子晶体结构（图 7-19，p.186）**：在金刚石晶体中，每个 C 原子与相邻 4 个 C 原子以共价键结合形成正四面体三维空间网状结构；在二氧化硅（石英 \\(\\mathrm{SiO_2}\\)）晶体中，每个 Si 原子与相邻 **4 个** O 原子结合，每个 O 原子与相邻 **2 个** Si 原子结合，形成无限延伸的空间网状结构——**晶体中不存在单个 \\(\\mathrm{SiO_2}\\) 分子**（\\(\\mathrm{SiO_2}\\) 仅是原子数比 1:2 的实验式！）。","**干冰 vs 二氧化硅（p.188 感知生活）**：\\(\\mathrm{CO_2}\\) 与 \\(\\mathrm{SiO_2}\\) 虽化学式相似，但干冰是由独立 \\(\\mathrm{CO_2}\\) 分子靠微弱**范德华力**结合而成的**分子晶体**（常温常压为气体，固态极易升华），而石英是靠极强 **Si—O 共价键**连成整块网状巨分子的**原子晶体**（熔点 \\(1723\\,^\\circ\\mathrm{C}\\)），因此物理性质天差地别！"],"takeaway":"常见原子晶体五大家族必背：**金刚石（C）、晶体硅（Si）、二氧化硅（SiO₂）、金刚砂（SiC）、氮化硼（BN）**。"},{"kind":"mechanism","title":"同类晶体内部熔沸点高低比较规律（教材 p.189 表 7-8 & p.196 第 5 题）","pageRef":"化上 p.189–190、p.196","body":["**① 离子晶体熔点比法**：离子半径越小、离子所带电荷越高，阴阳离子间静电引力（晶格能）越强，熔点越高。如：\\(\\mathrm{NaCl > KCl > CsCl}\\)（阳离子半径 \\(\\mathrm{Na^+ < K^+ < Cs^+}\\)）。","**② 原子晶体熔点比法**：共价键键长越短（成键原子半径越小）、键能越大，原子晶体熔点越高、硬度越大。如：\\(\\text{金刚石 (C–C)} > \\text{碳化硅 (Si–C)} > \\text{晶体硅 (Si–Si)}\\)。","**③ 分子晶体熔点比法**：先看有无氢键（有氢键偏高，如 \\(\\mathrm{H_2O > H_2Se > H_2S}\\)）；无氢键比 \\(M_r\\)（如 \\(\\mathrm{SiCl_4 > SiBr_4}\\)? 相反应是 \\(\\mathrm{SiI_4 > SiBr_4 > SiCl_4 > SiF_4 > SiH_4}\\)，即 \\(M_r\\) 越大范德华力越强）。","**④ 金属晶体熔点比法（表 7-8，p.189）**：金属元素**原子半径越小、单位体积内自由电子数目越多**，金属键越强，硬度与熔沸点越高。如同周期 \\(\\mathrm{Na\\;(97.5\\,^\\circ\\mathrm{C}) < Mg\\;(650\\,^\\circ\\mathrm{C}) < Al\\;(660\\,^\\circ\\mathrm{C})}\\)，而同主族碱金属 \\(\\mathrm{Li > Na > K}\\)（半径增大导致金属键减弱，熔点降低——恰好与卤素单质 \\(\\mathrm{F_2 < Cl_2 < Br_2 < I_2}\\) 相反！）。"],"takeaway":"绝妙对比（p.189 感知生活）：碱金属 Li→Na→K 熔点**降低**（金属键减弱），卤素单质 F₂→I₂ 熔点**升高**（范德华力增强）！"}],"formulas":[{"title":"四大晶体熔沸点一般阶梯与结构决定关系","tex":"\\text{熔点一般阶梯：原子晶体} > \\text{离子晶体} > \\text{分子晶体};\\qquad \\text{金属键强弱} \\propto \\frac{N_{\\text{自由 }e^-}}{r_{\\text{原子}}}","plain":"原子晶体 > 离子晶体 > 分子晶体；金属键越强 ⇔ 原子半径越小、价电子越多","conditions":"存在例外交叉（如部分高熔点离子晶体 MgO 2852℃ 高于 Si 1414℃；金属 W 3410℃ 高于绝大多数离子晶体）","pageRef":"化上 p.183–190","note":"同主族/同周期同类晶体内部比较严格适用微观键能/引力规律。"},{"title":"原子晶体熔点反比键长规律","tex":"r_{\\mathrm{C-C}} < r_{\\mathrm{Si-C}} < r_{\\mathrm{Si-Si}} \\implies \\text{熔点/硬度：金刚石 (C)} > \\text{金刚砂 (SiC)} > \\text{晶体硅 (Si)}","plain":"键长 C-C < Si-C < Si-Si ⇒ 熔点与硬度：金刚石 > SiC > 晶体硅","conditions":"均为正四面体三维共价网状原子晶体","pageRef":"化上 p.186、p.196 第 5(4) 题","note":"原子半径 C < Si，故 C—C 键最短、键能最大。"}],"pitfalls":[{"title":"把“单质晶体中一定含共价键”或“分子晶体内部不含共价键”绝对化","wrong":"“稀有气体固态晶体是分子晶体，其晶体中存在共价键；且金属晶体中存在离子键。”","diagnosis":"稀有气体（如 He, Ne, Ar）是**单原子分子**，形成分子晶体时微粒间**只有范德华力**，内部没有任何化学键！单质晶体中一定不存在离子键，但可以存在共价键（I₂, 金刚石）、金属键（Cu）或分子间作用力（O₂, Ne）。","right":"稀有气体分子晶体不含任何化学键；金属晶体中只有**金属键**（金属阳离子与自由电子之间），不存在阴离子故绝无离子键。","checkRule":"遇到“在单质晶体中，一定不存在……”题，必选 **离子键**（教材 p.195 第 7 题原题！）。"},{"title":"认为“水溶液能导电的晶体一定是离子晶体”","wrong":"“某固体物质溶于水后溶液能够导电，因此该固体必定是离子晶体。”","diagnosis":"许多分子晶体（如固态 \\(\\mathrm{HCl}\\)、\\(\\mathrm{SO_3}\\)、冰醋酸 \\(\\mathrm{CH_3COOH}\\)）本身是共价分子，但溶于水后在极性水分子作用下发生电离产生自由离子也能导电！","right":"鉴别离子晶体的决定性实验特征是**“固态时不导电，但在熔融状态下能导电”**（教材 p.195 第 4 题标准选 D：固态不导电，熔融态能导电）。","checkRule":"固态不导 + 熔融导 = 离子晶体；水溶液导 ≠ 离子晶体！"},{"title":"在分子晶体中数错熔化断键类型，或在 SiO₂ 中误以为存在独立 SiO₂ 分子","wrong":"“冰熔化成水破坏了 O—H 共价键；\\(1\\text{ mol }\\mathrm{SiO_2}\\) 晶体中含有 \\(1\\text{ mol }\\mathrm{SiO_2}\\) 分子和 \\(2\\text{ mol }\\mathrm{Si-O}\\) 键。”","diagnosis":"冰是分子晶体，熔化只破坏分子间氢键与范德华力；石英（\\(\\mathrm{SiO_2}\\)）是原子晶体，不存在独立分子，且每个 Si 连 **4 个** O 原子形成 **4 条** Si—O 单键！","right":"\\(1\\text{ mol }\\mathrm{SiO_2}\\) 原子晶体中不含分子，含有 **4 mol Si—O 共价键**；同理 \\(1\\text{ mol}\\) 金刚石（12 g C）含 **2 mol C—C 键**（每条键 2 个 C 均摊：\\(4\\div 2 = 2\\)）。","checkRule":"SiO₂ 1 个 Si 连 4 根单键不均摊（每根键连 1 Si 1 O）⇒ 1 mol SiO₂ 含 **4 mol** Si—O 键！"}],"examples":[{"label":"例 7.3.1","tier":"L2","tierLabel":"L2 校内期末","title":"教材 p.196 第 1 & 6 题综合：依据物理性质判定晶体类型与破坏作用力","prompt":"(1) 已知溴化硼（\\(\\mathrm{BBr_3}\\)）的熔点是 \\(-46\\,^\\circ\\mathrm{C}\\)，碳化硅（\\(\\mathrm{SiC}\\)）的熔点是 \\(2700\\,^\\circ\\mathrm{C}\\)；氮化硼（\\(\\mathrm{BN}\\)）和二氧化碳中化学键均为共价键，但氮化硼熔点极高且硬度极大，而干冰松软且极易升华。据此判断 \\(\\mathrm{BBr_3}\\)、\\(\\mathrm{SiC}\\)、干冰和 \\(\\mathrm{BN}\\) 分别属于何种晶体类型？(2) 根据熔化或升华时所克服的微粒间作用力，把下列六种物质归类并写明克服的作用力名称：① 氧化钠（\\(\\mathrm{Na_2O}\\)） ② 二氧化硅（\\(\\mathrm{SiO_2}\\)） ③ 镁（\\(\\mathrm{Mg}\\)） ④ 碘（\\(\\mathrm{I_2}\\)） ⑤ 蔗糖 ⑥ 氯化钠（\\(\\mathrm{NaCl}\\)）。","clues":"低熔点共价物为分子晶体；高熔点硬脆非金属共价物为原子晶体；活跃金属与盐按金属/离子归类。","strategy":"先由熔点/元素组成定出四类晶体，再一一对应其微粒间作用力。","given":"BBr₃(-46℃), SiC(2700℃), BN(高熔极硬), 干冰(易升华); 6 种常见晶体","principle":"晶体熔化/升华克服的是构成晶体微粒之间的相互作用力。","steps":["(1) \\(\\mathrm{BBr_3}\\) 熔点极低（\\(-46\\,^\\circ\\mathrm{C}\\)），属于**分子晶体**；\\(\\mathrm{SiC}\\) 熔点高达 \\(2700\\,^\\circ\\mathrm{C}\\)，属于**原子晶体**；干冰松软易升华，属于**分子晶体**；氮化硼（\\(\\mathrm{BN}\\)）共价结合且高熔点大硬度，属于**原子晶体**。","(2) 归类及熔化/升华克服的作用力：","- **离子晶体**（① \\(\\mathrm{Na_2O}\\)、⑥ \\(\\mathrm{NaCl}\\)）：克服**离子键**；","- **原子晶体**（② \\(\\mathrm{SiO_2}\\)）：克服**共价键**；","- **金属晶体**（③ \\(\\mathrm{Mg}\\)）：克服**金属键**；","- **分子晶体**（④ 碘、⑤ 蔗糖）：克服**分子间作用力（范德华力）**（注：蔗糖分子中含大量羟基 `-OH`，还需克服分子间**氢键**）。"],"answer":"(1) BBr₃ 分子晶体，SiC 原子晶体，干冰分子晶体，BN 原子晶体；(2) 离子晶体(①⑥)克服离子键；原子晶体(②)克服共价键；金属晶体(③)克服金属键；分子晶体(④⑤)克服分子间作用力（蔗糖含氢键）。","markingPoints":["正确判断四种物质晶体类型（2分）","准确归类六种物质并写出对应克服的四种作用力（3分）"],"verification":"化上 p.196 二、作答题第 1 & 6 题原题核对。","pitfall":"把含共价键的 BN 和 SiC 与干冰混为一谈，或漏写蔗糖/碘属于分子晶体。"},{"label":"例 7.3.2","tier":"L4","tierLabel":"L4 统考压轴","title":"综合熔点排序（教材 p.196 第 5 题）与未知晶体性质表推理","prompt":"(1) 将下列各组化合物按其晶体的**熔点由高到低**排列，并分别用微粒作用力简要说明原因：\n- (a) 氯化铯（\\(\\mathrm{CsCl}\\)）、氯化钾（\\(\\mathrm{KCl}\\)）、氯化钠（\\(\\mathrm{NaCl}\\)）；\n- (b) 四氯化硅（\\(\\mathrm{SiCl_4}\\)）、四氟化硅（\\(\\mathrm{SiF_4}\\)）、四氢化硅（\\(\\mathrm{SiH_4}\\)）；\n- (c) 硒化氢（\\(\\mathrm{H_2Se}\\)）、硫化氢（\\(\\mathrm{H_2S}\\)）、水（\\(\\mathrm{H_2O}\\)）；\n- (d) 晶体硅（\\(\\mathrm{Si}\\)）、碳化硅（\\(\\mathrm{SiC}\\)）、金刚石（\\(\\mathrm{C}\\)）。\n(2) 某研究测得四种未知纯晶体 W, X, Y, Z 的物理性质如下：\n- W：熔点 \\(1414\\,^\\circ\\mathrm{C}\\)，硬而脆，固态和熔融态微弱导电（半导体），不溶于水；\n- X：熔点 \\(113\\,^\\circ\\mathrm{C}\\)，易升华，固态、熔融及水溶液皆不导电；\n- Y：熔点 \\(801\\,^\\circ\\mathrm{C}\\)，较硬脆，固态不导电，熔融态及水溶液导电良好；\n- Z：熔点 \\(1900\\,^\\circ\\mathrm{C}\\)，硬而有延展性，固态和熔融态皆极易导电。\n请判定 W, X, Y, Z 各自所属晶体类型，并推测它们最可能对应的教材表 7-6/7-8 具体物质。","clues":"第(1)问四组正好分别对应四大熔点规律；第(2)问紧扣导电性、延展性与教材熔点表数值！","strategy":"逐组先辨晶体类型再找关键差异量（离子半径 / Mr / 氢键 / 键长）；第(2)问对比熔点数据匹配教材典型物。","given":"四组晶体熔点排序 + W/X/Y/Z 物理性质","principle":"四大晶体结构与物理性质规律（p.183–190）。","steps":["(1)(a) **\\(\\mathrm{NaCl > KCl > CsCl}\\)**。三者均为离子晶体，电荷相同（+1, −1），因阳离子半径 \\(r(\\mathrm{Na^+}) < r(\\mathrm{K^+}) < r(\\mathrm{Cs^+})\\)，离子键依次减弱，故熔点降低。","(1)(b) **\\(\\mathrm{SiCl_4 > SiF_4 > SiH_4}\\)**。三者均为结构相似（正四面体）且无氢键的分子晶体，相对分子质量 \\(M_r(\\mathrm{SiCl_4}=170) > M_r(\\mathrm{SiF_4}=104) > M_r(\\mathrm{SiH_4}=32)\\)，范德华力依次减弱，故熔点降低。","(1)(c) **\\(\\mathrm{H_2O > H_2Se > H_2S}\\)**。三者均为分子晶体，\\(\\mathrm{H_2O}\\) 分子间存在较强的**氢键**故熔点最高；\\(\\mathrm{H_2Se}\\) 与 \\(\\mathrm{H_2S}\\) 间无氢键，因 \\(M_r(\\mathrm{H_2Se}) > M_r(\\mathrm{H_2S})\\)，范德华力更强故 \\(\\mathrm{H_2Se > H_2S}\\)。","(1)(d) **\\(\\text{金刚石} > \\mathrm{SiC} > \\text{晶体硅}\\)**。三者均为原子晶体，原子半径 \\(\\mathrm{C < Si}\\)，共价键键长 \\(\\mathrm{C-C < Si-C < Si-Si}\\)、键能依次减小，故熔点降低。","(2) 判定：W 为**原子晶体**（晶体硅 \\(\\mathrm{Si}\\)，熔点 1414℃ 半导体）；X 为**分子晶体**（碘 \\(\\mathrm{I_2}\\) 113.5℃ 或硫 \\(\\mathrm{S}\\) 112.8℃）；Y 为**离子晶体**（氯化钠 \\(\\mathrm{NaCl}\\) 801℃）；Z 为**金属晶体**（铬 \\(\\mathrm{Cr}\\) 1900℃，教材表 7-8 原数据）。"],"answer":"(1) (a) NaCl>KCl>CsCl；(b) SiCl₄>SiF₄>SiH₄；(c) H₂O>H₂Se>H₂S；(d) 金刚石>SiC>Si；(2) W 原子晶体(Si), X 分子晶体(I₂/S), Y 离子晶体(NaCl), Z 金属晶体(Cr)。","markingPoints":["第(1)问四组排序全部正确且分别点明离子半径、Mr/范德华力、氢键、共价键键长（4分）","第(2)问准确判定 W/X/Y/Z 晶体类型并匹配物质（2分）"],"verification":"与化上 p.183 表 7-6、p.189 表 7-8 及 p.196 第 5 题完全吻合。","pitfall":"第(1)(b)问误以为 F 电负性强就排 SiF₄ 第一；第(1)(c)问把 H₂S 错排到 H₂Se 前面。"}],"practice":[{"id":"chem7-7.3-q1","tier":"L1","tierLabel":"L1 基础","examStyle":"P1 选择","q":"下列各组物质的晶体中，属于同一种晶体类型的是（　）。","options":["A. O₂ 和 SiO₂","B. NaI 和 I₂","C. CO₂ 和 H₂O","D. CCl₄ 和 NaCl"],"correctOption":"C","given":"四组晶体对照（化上 p.195 第 3 题）","method":"逐个辨别每组两物质的晶体分类","principle":"CO₂ 与 H₂O 均由独立分子靠分子间作用力构成，均为分子晶体。","steps":["A 项 O₂ 是分子晶体、SiO₂ 是原子晶体；B 项 NaI 是离子晶体、I₂ 是分子晶体；C 项 CO₂（干冰）与 H₂O（冰）同属分子晶体；D 项 CCl₄ 是分子晶体、NaCl 是离子晶体。"],"ans":"C","markingPoints":["准确区分常见氧化物与卤化物的晶体归属"],"verification":"化上 p.195 选择题第 3 题原题。","pitfall":"看到 SiO₂ 与 O₂ 或 CO₂ 都叫氧化物就误以为同属分子晶体。"},{"id":"chem7-7.3-q2","tier":"L2","tierLabel":"L2 期末","examStyle":"P1 选择","q":"下列实验事实中，能够最充分地证明某固体晶体一定是**离子晶体**的是（　）。","options":["A. 具有较高的熔点（如 >1000 ℃）","B. 易溶于水且其水溶液能够导电","C. 固态时不导电，但在熔融状态下能导电","D. 固态和熔融状态下都能够导电"],"correctOption":"C","given":"四大晶体导电性差异（化上 p.195 第 4 题）","method":"逐项排除原子晶体、共价分子电解质和金属晶体","principle":"离子晶体固态离子被束缚不导电，熔融时自由移动阴阳离子导电。","steps":["A 原子晶体与高熔金属熔点也很高；B 分子晶体 HCl 水溶液也能导电；C 是离子晶体独有的特征判据（原子、分子晶体熔融均不导电，金属固态就导电）；D 是金属晶体特征。"],"ans":"C","markingPoints":["掌握离子晶体导电性决定判据"],"verification":"化上 p.195 选择题第 4 题原题。","pitfall":"误选 B（忽略 HCl、SO₃、AlCl₃ 等分子溶于水后也会导电）。"},{"id":"chem7-7.3-q3","tier":"L2","tierLabel":"L2 期末","examStyle":"P2 简答","q":"右表列出了四种晶体物质微粒与性质的相关说法（化上 p.195 第 9 题 & p.196 第 3 题）：(1) 下述四种晶体微粒间作用力的描述中有哪**一项**是错误的，并请改正：① 硫化钾（\\(\\mathrm{K_2S}\\)）：微粒为阴、阳离子，作用力为离子键；② 干冰（\\(\\mathrm{CO_2}\\)）：微粒为分子，作用力为共价键；③ 金刚石（\\(\\mathrm{C}\\)）：微粒为原子，作用力为共价键；④ 碘（\\(\\mathrm{I_2}\\)）：微粒为分子，作用力为范德华力。(2) 现有三种固态单质 \\(\\mathrm{Cu, Si, Ne}\\)，请把它们依次填入下列描述中：由分子间作用力结合而成、熔点很低的是______；固体易导电、熔点高的是______；由共价键结合成网状晶体、熔点很高的是______。","given":"K₂S, CO₂, 金刚石, I₂；Cu, Si, Ne","method":"区分“晶体微粒间作用力”与“分子内部化学键”","principle":"分子晶体中分子微粒之间的作用力是分子间作用力（范德华力/氢键），而非共价键。","steps":["(1) **② 干冰**的描述错误！干冰晶体中虽然 \\(\\mathrm{CO_2}\\) 分子内部是 C=O 共价键，但构成晶体的分子微粒**之间**的作用力是**范德华力**（分子间作用力），而非共价键。","(2) 熔点很低的单原子分子晶体是 **Ne**；固体导电高熔点金属晶体是 **Cu**；共价网状原子晶体是 **Si**。"],"ans":"(1) ② 干冰错误，微粒间作用力应改为范德华力；(2) Ne；Cu；Si。","markingPoints":["准确挑出干冰错误并改为范德华力（2分）","正确配对 Ne, Cu, Si（3分）"],"verification":"化上 p.195 第 9 题与 p.196 第 3 题原题核对。","pitfall":"看到干冰里确实有共价键就误判 ② 也正确，没审清表头写的是“晶体微粒间存在的作用力”。"},{"id":"chem7-7.3-q4","tier":"L3","tierLabel":"L3 预试","examStyle":"P1 选择","q":"下列关于金属晶体性质及其递变规律的叙述中，**错误**的是（　）。","options":["A. 金属能导电是因为金属晶体中的自由电子在外加电压下可发生定向移动","B. 碱金属单质 Li、Na、K 的熔点依次降低，是因为随原子序数增大，原子半径增大、金属键减弱","C. 第 3 周期金属 Na、Mg、Al 的硬度与熔点依次升高（97.5℃ < 650℃ < 660℃），是因为半径减小且自由电子数增多、金属键增强","D. 所有金属晶体在常温下都是固体，且熔点一定高于所有分子晶体"],"correctOption":"D","given":"金属晶体结构与表 7-8 数据（化上 p.189–190）","method":"逐项核查金属熔点跨度与常温态特例","principle":"汞（Hg）常温为液态（-38.9℃），碱金属 Cs（28.4℃）熔点低于蔗糖、碘（113.5℃）等许多分子晶体！","steps":["A、B、C 均完全符合教材 p.189–190 原文；D 错，金属汞（Hg，熔点 −38.9℃）常温为液体，钠（97.8℃）熔点还低于白硫（112.8℃）和碘（113.5℃）等分子晶体！"],"ans":"D","markingPoints":["牢记 Hg 液态与 Na(97.8℃) < I₂(113.5℃) 实例"],"verification":"化上 p.183 表 7-6（硫 112.8℃ > 钠 97.8℃）及 p.189 原文。","pitfall":"直觉以为“金属一定比分子晶体熔点高”。"},{"id":"chem7-7.3-q5","tier":"L4","tierLabel":"L4 统考压轴","examStyle":"P2 综合对比","q":"请从微粒间作用力、微观化学键数与结构特性全面比较二氧化碳（\\(\\mathrm{CO_2}\\)）与二氧化硅（\\(\\mathrm{SiO_2}\\)）：(1) 两者属于第 IVA 族的最高价氧化物，为什么常温常压下 \\(\\mathrm{CO_2}\\) 是气体而 \\(\\mathrm{SiO_2}\\) 却是熔点 \\(1723\\,^\\circ\\mathrm{C}\\) 的坚硬固体？(2) 在 \\(60\\text{ g}\\) 纯净石英（\\(\\mathrm{SiO_2}\\)，\\(M_r=60\\)）和 \\(44\\text{ g}\\) 干冰（\\(\\mathrm{CO_2}\\)，\\(M_r=44\\)）晶体中，各自含有的共用电子对（或极性键）物质的量是多少（注意 \\(\\mathrm{CO_2}\\) 含碳氧双键）？(3) 常温下将石英晶体与干冰分别投入足量热的浓 \\(\\mathrm{NaOH}\\) 溶液中，最终都能反应生成硅酸钠与碳酸钠，试从微观断键角度说明两者都能与强碱反应却物理性质迥异的根本原因。","given":"60 g SiO₂ (1 mol 单元)；44 g CO₂ (1 mol 分子)","method":"区分晶体聚集状态作用力 vs 化学反应断键；精准数单键 vs 双键数目","principle":"SiO₂ 中 1 个 Si 连 4 个 Si—O 单键；CO₂ 结构式 O=C=O 含 2 个双键（4 对共用电子）。","steps":["(1) 干冰是由离散 \\(\\mathrm{CO_2}\\) 分子靠极弱的**范德华力**构成的**分子晶体**，只需极少能量即可克服范德华力汽化；而 \\(\\mathrm{SiO_2}\\) 中每个 Si 与 4 个 O、每个 O 与 2 个 Si 以极强的 **Si—O 共价键**连成无限延伸的三维空间网状**原子晶体**，熔化必须断裂大量共价键，故熔点极高、硬度大。","(2) \\(60\\text{ g}\\) \\(\\mathrm{SiO_2}\\) 含 \\(1\\text{ mol Si}\\) 原子，每个 Si 原子与 4 个 O 原子形成 4 条 Si—O 单键（每条单键 1 对共用电子，且只连该 1 个 Si 原子不与邻 Si 重复），故含 **4 mol Si—O 单键（4 mol 共用电子对）**；\\(44\\text{ g}\\) 干冰含 \\(1\\text{ mol }\\mathrm{CO_2}\\) 分子，每个分子结构式为 \\(\\mathrm{O=C=O}\\)，有 2 个 C=O 双键，共含 **4 mol 共用电子对**（2 mol 双键 / 4 mol 键对）。","(3) 物理性质（熔沸点、硬度）由晶体结构及**物理相变所需破坏的作用力**决定（范德华力 vs 共价网）；而化学性质（与强碱生成对应含氧酸盐）由元素本质与 Si(+4)/C(+4) 酸性氧化物化学键反应活性决定。"],"ans":"(1) 干冰为分子晶体靠范德华力，SiO₂ 为原子晶体靠三维共价网；(2) 均含 4 mol 共用电子对（SiO₂ 含 4 mol Si—O 单键，CO₂ 含 2 mol C=O 双键）；(3) 物理性质取决于晶体类型，化学性质取决于化学键反应本质。","markingPoints":["精准对比范德华力 vs 三维 Si—O 共价键网（2分）","正确算出 60 g SiO₂ 含 4 mol Si—O 键（非 2 mol！）及 CO₂ 含 4 mol 共用电子对（2分）","点出物理性质与化学性质决定的微观层面差异（1分）"],"verification":"每 1 个 Si 形成 4 个半键？不！Si—O—Si 中每个 O 连 2 个 Si，1 个 Si 连 4 个 O，所以有 4 条 Si—O 键！常误算成 2 mol 是全高中最高发坑。","pitfall":"算 1 mol SiO₂ 中的 Si—O 键数时错乘 1/2 得出 2 mol（只有金刚石 C—C 才因两头都是 C 需除以 2，SiO₂ 一头是 Si 一头是 O，不重复计数就是 4 mol！）。"}],"cheatSheet":["晶体判据铁三角：**固态导 = 金属**；**固态不导、熔融导 = 离子**；**都不导、高熔硬 = 原子**，**低熔软/易升华 = 分子**。","必背原子晶体 5 强：**金刚石(C)、Si、SiO₂、SiC、BN**；记住 **1 mol SiO₂ 含 4 mol Si—O 键**，**1 mol 金刚石含 2 mol C—C 键**。","熔点比法：原子比键长（\\(\\mathrm{C > SiC > Si}\\)）；离子比半径电荷（\\(\\mathrm{NaCl > KCl > CsCl}\\)）；分子先氢键后 \\(M_r\\)；金属比半径小且自由电子多（\\(\\mathrm{Na < Mg < Al}\\)，\\(\\mathrm{Li > Na > K}\\)）。"],"kbEntryIds":["kb-chem7-four-crystals"],"quiz":{"q":"为什么 \\(\\mathrm{NaCl}\\)（熔点 \\(801\\,^\\circ\\mathrm{C}\\)）和 \\(\\mathrm{SiCl_4}\\)（熔点 \\(-70\\,^\\circ\\mathrm{C}\\)）都是氯化物，熔点却相差接近 \\(900\\,^\\circ\\mathrm{C}\\)？","given":"NaCl ΔEN = 2.1（离子晶体）；SiCl₄ ΔEN = 1.2（分子晶体）","method":"定位两者的晶体类型与熔化时破坏的作用力","principle":"离子键 ≫ 分子间范德华力。","steps":["\\(\\mathrm{NaCl}\\) 是离子晶体，熔化需破坏极强的离子键；\\(\\mathrm{SiCl_4}\\) 是分子晶体，熔化只需克服微弱的分子间范德华力。"],"ans":"NaCl 为离子晶体（克服强离子键），SiCl₄ 为分子晶体（仅克服微弱范德华力）。"},"diagrams":[{"src":"assets/fig/v2/chem07-crystals-bonds.svg","caption":"图 7-2 四大晶体类型（离子、原子、分子、金属晶体）构成微粒、作用力与物理性质全对照","alt":"四大晶体类型对照图","pageRef":"化上 p.182–190"}]}]},"化学8":{"lessonKey":"化学8","courseCode":"chemistry","subject":"化学","chapter":8,"title":"氧化还原反应","syllabus":"1.6 氧化还原反应","bookId":"sm1-chemistry-2017","bookCitation":"《马来西亚华文独中教科书 · 化学（上册）》（2017年11月版）第8章 p.197–216","examScopes":["sem1_final","pre_exam","sem2_final","uec"],"chapterOverview":{"summary":"第8章建立化学反应最核心的电子转移框架：从宏观的得失氧拓展到微观的电子得失与电子对偏移，引入“氧化数”这一精准定量工具及其八条计算规则，厘清氧化剂/还原剂/氧化产物/还原产物的对立统一与强弱判据，并系统训练“氧化数法”和“离子—电子法（酸、碱性介质）”两大配平技巧，为后续无机元素氧化还原（第9–16章）和电化学（第24章）打下关键基础。","conceptTree":[{"branch":"8.1 氧化还原反应的本质（p.198–200）","items":["得失氧（狭义）→ 电子得失或共用电子对偏移（本质）→ 氧化数变化（特征）","与四大基本反应类型的关系（置换全属、复分解全非、单质参与的化合/分解属）"]},{"branch":"8.2 氧化数规则与双线桥（p.200–204）","items":["八条规则（单质0、F恒−1、H特殊−1、O特殊+2/−1/−1/2）与主族最高/最低氧化数（表8-1）","半反应式（half-equation）与双线桥表示电子转移方向和数目"]},{"branch":"8.3 氧化剂、还原剂与强弱比较（p.205–209）","items":["升失氧（还原剂）→ 氧化产物；降得还（氧化剂）→ 还原产物","常见氧化剂/还原剂分类 · 氧化性/还原性强弱四大判据（价态、活动性、强制弱、反应条件）"]},{"branch":"8.4 氧化还原方程式配平（p.210–213）","items":["氧化数法四步骤（标数 → 求升降 → 最小公倍数 → 观察守恒）","离子—电子法五步骤（酸性介质用 H⁺/H₂O，碱性介质用 OH⁻/H₂O，电荷与原子双守恒）"]}]},"paperFocus":["高三上半年期末考（Ch 3–8, Ch 26–30）：第8章必考 P1 选择题 2–4 题（特例氧化数计算、氧化剂/还原剂/电子转移数计算、氧化性强弱比较、酸的多重作用）以及 P2 必答题的**双线桥标注**和**离子—电子法配平（酸性/碱性）**。","预试 / 毕业考 / UEC 统考：氧化还原配平与电子守恒计算（如 KMnO₄/K₂Cr₂O₇ 滴定、XO₄⁻ 与 H₂O₂ 计量推氧化数，教材 p.215 第 11 题）几乎年年必考，也是第 24 章电化学电极反应书写的直接前置技能。"],"solvingWorkflow":["算氧化数先定“标杆元素”：F 恒 −1 → IA(+1)/IIA(+2) → H(+1, 金属氢化物 −1) → O(−2, OF₂ +2, 过氧化物 −1, 超氧化物 −1/2) → 用代数和 0 或离子电荷求解其余未知元素；含原子团的离子化合物（如 NH₄NO₃）务必拆开离子分别算！","分析反应角色背口诀：**“升（氧化数）失（电子）氧（被氧化）还剂（是还原剂），降（氧化数）得（电子）还（被还原）氧剂（是氧化剂）”**；反应前看“剂”，反应后看“产物”。","氧化数法配平歧化反应（如 Cl₂ + KOH → KCl + KClO₃ + H₂O）：从**产物逆推**配平比从反应物正推简单得多！","离子—电子法配平两介质秘诀：在**酸性溶液**中缺 O 补 \\(\\mathrm{H_2O}\\)、缺 H 补 \\(\\mathrm{H^+}\\)；在**碱性溶液**中，多 1 个 O 的那一侧加 1 个 \\(\\mathrm{H_2O}\\)、另一侧加 2 个 \\(\\mathrm{OH^-}\\)（或先按酸液配好后两边同加等量 \\(\\mathrm{OH^-}\\) 抵消 \\(\\mathrm{H^+}\\)），最后加 \\(\\mathrm{e^-}\\) 配平电荷并校验原子与电荷双守恒。"],"questionTypes":["氧化还原反应判断及与四大基本反应类型的关系辨析","复杂/特殊物质氧化数计算（H₂O₂, Na₂O₂, KO₂, OF₂, NaH, FeS₂, Fe₃O₄, NH₄NO₃, S₂O₃²⁻）","双线桥规范标注及指定反应的转移电子数与氧化/还原产物比例计算（歧化/归中/多元素变价）","利用化学反应比较氧化性、还原性强弱及金属置换实验推理（活动2）","酸性与碱性条件下氧化还原方程式（氧化数法 + 离子—电子法）严格配平"],"scoringNotes":["统考卷二画**双线桥**时，两条箭头必须从**反应物变价原子**精确指到**生成物对应变价原子**，桥上文字务必写全三要素：① 得/失电子数目（如“失去 \\(6\\mathrm{e^-}\\)”——是总电子数而非单原子数！）、② 氧化数升高/降低、③ 被氧化/被还原。","用**离子—电子法**答题时，若题干要求写出离子方程式并补全介质粒子，切记不可在酸性溶液中出现 \\(\\mathrm{OH^-}\\)，也不可在碱性溶液中保留 \\(\\mathrm{H^+}\\)；最后务必核查“元素原子守恒 + 离子总电荷守恒”。"],"vid":[{"t":"氧化还原反应本质、氧化数规则与双线桥","q":"氧化还原反应 氧化数 双线桥 高中化学"},{"t":"氧化剂还原剂强弱判断四大规律","q":"氧化性 还原性 强弱比较 化学"},{"t":"氧化数法与离子电子法配平（酸性/碱性）","q":"离子电子法 半反应法 配平 酸性 碱性"},{"t":"歧化反应与多变价反应配平及电子守恒计算","q":"歧化反应 配平 电子转移守恒 化学"}],"sections":[{"id":"8.1","t":"氧化还原反应","anchor":{"pages":"化上 p.198–200","syllabus":"1.6.1 氧化还原反应的概念演变与电子转移本质","examScopes":["sem1_final","pre_exam","sem2_final","uec"],"examWeight":"P1 概念辨析与反应类型归类高频小题","terms":"oxidation-reduction (redox) reaction · electron transfer · electron shift","prerequisites":["离子键电子得失与共价键电子对偏移（Ch 7.1）","四大基本反应类型（化合、分解、置换、复分解，Ch 4.1.2）"],"goals":["说明氧化反应与还原反应在同一个反应中必然同时发生、不可分割。","理解氧化还原反应从“得失氧”到“电子得失或共用电子对偏移”的本质升华。","准确判断氧化还原反应与四大基本反应类型的交叉包含关系。"]},"concepts":[{"kind":"definition","title":"从“得失氧”到“电子转移”的三层次定义","pageRef":"化上 p.198–200","body":["**① 狭义定义（得失氧角度，p.198）**：在 \\(\\mathrm{CuO(s) + H_2(g)} \\xrightarrow{\\Delta} \\mathrm{Cu(s) + H_2O(l)}\\) 中，\\(\\mathrm{H_2}\\) 夺取了氧（得氧）发生**氧化反应**，\\(\\mathrm{CuO}\\) 失去氧发生**还原反应**。但是，许多不含氧参加的反应（如 \\(\\mathrm{2Na + Cl_2 \\to 2NaCl}\\)）同样具有相同本质。","**② 本质定义（电子转移角度，p.199–200）**：一切氧化还原反应的实质是**原子或离子之间发生电子的得失或共用电子对的偏移**（教材 p.215 第 3 题核心标准答案）。","- **电子完全得失（离子化合物形成）**：如 \\(\\mathrm{2Na + Cl_2 \\to 2NaCl}\\) 中，\\(\\mathrm{Na}\\) 失去电子被氧化为 \\(\\mathrm{Na^+}\\)，\\(\\mathrm{Cl_2}\\) 得到电子被还原为 \\(\\mathrm{Cl^-}\\)；","- **共用电子对偏移（共价化合物形成）**：如 \\(\\mathrm{H_2 + Cl_2 \\to 2HCl}\\) 中，\\(\\mathrm{H-Cl}\\) 共用电子对偏向电负性更强的 \\(\\mathrm{Cl}\\)（使 Cl 显部分负性、H 显部分正性），即发生电子对偏移——\\(\\mathrm{H_2}\\) 被氧化，\\(\\mathrm{Cl_2}\\) 被还原。","**③ 表观判据（氧化数角度，p.203）**：反应前后**有元素氧化数发生升降变化**的化学反应就是氧化还原反应。"],"takeaway":"记住核心结论：**氧化与还原永远同时发生、同时存在**，绝不可能只有氧化而没有还原！"},{"kind":"mechanism","title":"氧化还原反应与四大基本反应类型的关系","pageRef":"化上 p.198–200、Ch 4.1.2 衔接","body":["初中/第 4 章按形式分为化合、分解、置换、复分解四大类；第 8 章按“有无电子转移（氧化数变化）”将化学反应二分：**氧化还原反应** vs **非氧化还原反应**：","- **置换反应**：**全部属于**氧化还原反应（必有单质变化合物、化合物变单质，氧化数必变，如 \\(\\mathrm{Zn + 2HCl \\to ZnCl_2 + H_2\\uparrow}\\)）；","- **复分解反应**：**全部不属于**氧化还原反应（阴阳离子简单交换，各元素氧化数均不变，如 \\(\\mathrm{NaOH + HCl \\to NaCl + H_2O}\\)、\\(\\mathrm{BaCl_2 + H_2SO_4 \\to BaSO_4\\downarrow + 2HCl}\\)）；","- **化合反应与分解反应**：**部分属于**——凡**有单质参加**的化合反应或**有单质生成**的分解反应一定是氧化还原反应（如 \\(\\mathrm{2H_2+O_2\\to 2H_2O}\\)、\\(\\mathrm{2KClO_3\\to 2KCl+3O_2\\uparrow}\\)）；而无单质参与/生成的化合或分解反应通常不是（如 \\(\\mathrm{CaO + H_2O \\to Ca(OH)_2}\\)、\\(\\mathrm{CaCO_3} \\xrightarrow{\\Delta} \\mathrm{CaO + CO_2\\uparrow}\\)）。"],"takeaway":"注意反例：同素异形体转化（如 \\(\\mathrm{3O_2 \\to 2O_3}\\)）虽然有单质参加与生成，但两头氧化数都是 0，**不是**氧化还原反应！"},{"kind":"table","title":"生活中与实验室常见氧化还原 vs 非氧化还原对照","pageRef":"化上 p.198–200、p.207","body":["结合教材图 8-1 及第 8 章练习整理常见反应判别清单。"],"table":{"headers":["反应实例","基本类型","是否氧化还原","微观依据（电子转移 / 氧化数变化）"],"rows":[["木柴燃烧、金属生锈、干电池放电、呼吸作用","综合变化","是","存在氧/金属与氧或电解质间电子转移"],["CuO(s) + H₂(g) → Cu(s) + H₂O(l)","置换反应","是","H(0→+1) 失/偏离电子；Cu(+2→0) 得电子"],["2Na(s) + Cl₂(g) → 2NaCl(s)","化合反应","是","电子完全转移：Na → Na⁺，Cl → Cl⁻"],["H₂(g) + Cl₂(g) → 2HCl(g)","化合反应","是","共用电子对偏移向 Cl（H 0→+1, Cl 0→−1）"],["CaO(s) + H₂O(l) → Ca(OH)₂(aq)","化合反应","否","Ca(+2), O(−2), H(+1) 均无电子转移"],["NaOH(aq) + HCl(aq) → NaCl(aq) + H₂O(l)","复分解反应","否","酸碱中和仅是 H⁺ 与 OH⁻ 结合，无氧化数变化"]]}}],"formulas":[{"title":"电子得失型氧化还原微观表达","tex":"2\\mathrm{Na(s)} + \\mathrm{Cl_2(g)} \\longrightarrow 2\\mathrm{Na^+Cl^-(s)}\\quad (\\mathrm{Na}\\text{ 失 }e^-,\\;\\mathrm{Cl}\\text{ 得 }e^-)","plain":"2Na + Cl₂ → 2Na⁺Cl⁻（电子完全得失）","conditions":"活泼金属与活泼非金属之间（离子反应）","pageRef":"化上 p.199","note":"离子化合物生成过程中电子发生完全转移。"},{"title":"电子对偏移型氧化还原微观表达","tex":"\\mathrm{H_2(g)} + \\mathrm{Cl_2(g)} \\xrightarrow{\\text{点燃/光照}} 2\\overset{\\delta+}{\\mathrm{H}}-\\overset{\\delta-}{\\mathrm{Cl}}\\mathrm{(g)}","plain":"H₂ + Cl₂ → 2Hδ⁺—Clδ⁻（共用电子对偏向 Cl）","conditions":"非金属之间形成极性共价化合物","pageRef":"化上 p.199–200","note":"虽无离子产生，仍属于氧化还原反应（H 被氧化，Cl 被还原）。"}],"pitfalls":[{"title":"认为“没有氧气参加的反应就不是氧化反应”","wrong":"“氢气在氯气中燃烧生成 \\(\\mathrm{HCl}\\)，反应物中不含氧，所以不是氧化还原反应。”","diagnosis":"停留在初中/狭义“得失氧”层面，没有上升到“电子转移”本质。","right":"\\(\\mathrm{H_2 + Cl_2 \\to 2HCl}\\) 中共用电子对偏向 Cl，H 氧化数从 0 升至 +1（被氧化）、Cl 从 0 降至 −1（被还原），是典型的氧化还原反应。","checkRule":"判定氧化还原反应的唯一黄金准则：看**有无电子转移（或元素氧化数升降）**，与有没有氧气无关！"},{"title":"把“有单质生成的分解反应”与“所有分解反应”混为一谈","wrong":"“碳酸钙高温分解（\\(\\mathrm{CaCO_3 \\to CaO + CO_2\\uparrow}\\)）也是氧化还原反应；而 \\(\\mathrm{3O_2 \\to 2O_3}\\) 因为有单质参加所以也是氧化还原反应。”","diagnosis":"\\(\\mathrm{CaCO_3}\\) 分解前后 Ca(+2), C(+4), O(−2) 氧化数完全不变；\\(\\mathrm{3O_2 \\to 2O_3}\\) 反应前后 O 氧化数都是 0，均无电子转移！","right":"无单质生成的分解反应（如 \\(\\mathrm{CaCO_3}\\)、\\(\\mathrm{NH_4HCO_3}\\) 分解）通常是非氧化还原反应；同素异形体互变（\\(\\mathrm{O_2 \\rightleftharpoons O_3}\\)、石墨变金刚石）也**不是**氧化还原反应。","checkRule":"务必逐一核对反应前后元素氧化数有没有变化！"}],"examples":[{"label":"例 8.1.1","tier":"L2","tierLabel":"L2 校内期末","title":"反应类型判别：哪些属于氧化还原反应？","prompt":"下列五个化学反应中，属于氧化还原反应的有哪些？并说明每个氧化还原反应的电子转移形式（完全得失还是共用电子对偏移）：\n① \\(\\mathrm{Fe(s) + CuSO_4(aq) \\longrightarrow FeSO_4(aq) + Cu(s)}\\)\n② \\(\\mathrm{SO_3(g) + H_2O(l) \\longrightarrow H_2SO_4(aq)}\\)\n③ \\(\\mathrm{2F_2(g) + 2H_2O(l) \\longrightarrow 4HF(aq) + O_2(g)}\\)\n④ \\(\\mathrm{2NaHCO_3(s)} \\xrightarrow{\\Delta} \\mathrm{Na_2CO_3(s) + H_2O(g) + CO_2(g)}\\)\n⑤ \\(\\mathrm{2CO(g) + O_2(g)} \\xrightarrow{\\text{点燃}} \\mathrm{2CO_2(g)}\\)","clues":"标出关键元素前后氧化数是否有变化，再按离子键/共价键区分转移方式。","strategy":"逐个排查化合价/氧化数变化 → 定性反应类型 → 分析电子得失或偏移。","given":"5 个典型化学反应","principle":"氧化还原反应实质为电子得失或电子对偏移（表现为氧化数变化）。","steps":["① 置换反应：Fe(0→+2)、Cu(+2→0) 变化 ⇒ **是**（发生金属与离子间电子得失）。","② 化合反应：S 始终 +6、H 始终 +1、O 始终 −2 ⇒ **否**（非氧化还原反应）。","③ 教材 p.207 原题：F(0→−1)、水中部分 O(−2→0) 变化 ⇒ **是**（共价分子间电子转移/偏移）。","④ 分解反应：Na(+1), H(+1), C(+4), O(−2) 全都不变 ⇒ **否**。","⑤ 化合反应（含单质 \\(\\mathrm{O_2}\\)）：C(+2→+4)、O(0→−2) 变化 ⇒ **是**（共价分子间共用电子对偏移）。"],"answer":"属于氧化还原反应的是 ①、③、⑤；① 主要为电子得失，③、⑤ 涉及共价键电子对偏移。","markingPoints":["准确挑出 ①、③、⑤ 并排除 ②、④（3分）","说明离子反应得失电子 vs 共价反应电子对偏移（1分）"],"verification":"对照化上 p.199–200 及 p.207 交流分享核对。","pitfall":"把无单质参与的化合反应 ② 或分解反应 ④ 误选进去。"},{"label":"例 8.1.2","tier":"L3","tierLabel":"L3 预试拔高","title":"基本反应类型与氧化还原反应交叉集合逻辑辨析","prompt":"用集合思维分析下列论断是否正确，若错误请举出一个具体的化学方程式作为反例：(1) “所有化合反应都是氧化还原反应”；(2) “所有置换反应都是氧化还原反应”；(3) “所有复分解反应都不是氧化还原反应”；(4) “有单质参加且有单质生成的反应一定是氧化还原反应”。","clues":"注意第(4)问的超级经典反例——同素异形体之间的转化！","strategy":"逐一检验集合包含关系，遇绝对命题找反例。","given":"四大基本反应类型与氧化还原反应交集命题","principle":"判断元素氧化数是否必然改变。","steps":["(1) **错误**。只有当化合反应中有单质参加（或变价元素化合，如 \\(\\mathrm{2FeCl_2 + Cl_2 \\to 2FeCl_3}\\)）才是；反例：\\(\\mathrm{CaO + H_2O \\to Ca(OH)_2}\\)（氧化数全不变）。","(2) **正确**。置换反应通式 \\(\\mathrm{A + BC \\to AC + B}\\) 中，游离态单质变为化合态、化合态变为游离态单质，氧化数必然一升一降。","(3) **正确**。复分解反应是两种化合物互相交换离子成分，反应前后各元素氧化数保持不变。","(4) **错误**。反例：高空雷电将氧气转化为臭氧 \\(\\mathrm{3O_2(g)} \\xrightarrow{\\text{放电}} \\mathrm{2O_3(g)}\\)，或石墨高温高压转为金刚石。反应物与生成物均为单质，氧化数恒为 0，没有电子转移。"],"answer":"(1) 错（反例 CaO+H₂O→Ca(OH)₂）；(2) 对；(3) 对；(4) 错（反例 3O₂→2O₃）。","markingPoints":["准确判断四条正误（2分）","给出有效反例 CaO+H₂O（或 NH₃+HCl）及 3O₂→2O₃（2分）"],"verification":"此四题为 UEC P1 氧化还原集合概念常青树题目。","pitfall":"第(4)问极易误判为正确，忘掉同素异形体转化。"}],"practice":[{"id":"chem8-8.1-q1","tier":"L1","tierLabel":"L1 基础","examStyle":"P1 选择","q":"（教材 p.215 第 3 题）从微观角度看，一切氧化还原反应的实质是（　）。","options":["A. 原子核内质子数的变化","B. 分子中各原子的重新组合","C. 电子的得失或共用电子对的偏移","D. 物质分子中氧原子的得失"],"correctOption":"C","given":"氧化还原反应本质（化上 p.199–200, p.215）","method":"区分宏观表象（得失氧、化合价升降）与微观实质（电子转移）","principle":"电子的得失或偏移是氧化还原反应本质。","steps":["A 是核反应；B 是所有化学反应的共同特征；C 是氧化还原反应本质；D 是狭义早期定义。"],"ans":"C","markingPoints":["牢记电子得失或偏移"],"verification":"化上 p.215 原题。","pitfall":"在“氧化数的变化”（表象）和“电子得失或偏移”（实质）之间犹豫选错。"},{"id":"chem8-8.1-q2","tier":"L2","tierLabel":"L2 期末","examStyle":"P1 选择","q":"下列化学反应中，**既不属于**四种基本反应类型中的任何一种，**又属于**氧化还原反应的是（　）。","options":["A. 2Na(s) + 2H₂O(l) → 2NaOH(aq) + H₂(g)","B. CH₄(g) + 2O₂(g) → CO₂(g) + 2H₂O(l)","C. CaCO₃(s) → CaO(s) + CO₂(g)","D. NaOH(aq) + HCl(aq) → NaCl(aq) + H₂O(l)"],"correctOption":"B","given":"四个反应方程式","method":"分别判断基本反应类型与是否氧化还原","principle":"甲烷燃烧有两产物，不属化合/分解/置换/复分解，且有 O₂ 参与为氧化还原。","steps":["A 是置换反应（氧化还原）；B 不是四大基本反应类型，且 C(-4→+4)、O(0→−2) 属于氧化还原反应；C 是分解反应（非氧化还原）；D 是复分解反应（非氧化还原）。"],"ans":"B","markingPoints":["同时检验“非四大基本类型”与“氧化还原”双条件"],"verification":"A 为置换，C 为分解，D 为复分解。","pitfall":"误选 A（置换反应属于四大基本反应类型）。"},{"id":"chem8-8.1-q3","tier":"L2","tierLabel":"L2 期末","examStyle":"P2 简答","q":"请从电子转移的角度，分别说明下列两个反应中电子是如何转移的，并指出各自哪个元素发生氧化反应、哪个元素发生还原反应：(1) \\(\\mathrm{Mg(s) + Cl_2(g)} \\xrightarrow{\\text{点燃}} \\mathrm{MgCl_2(s)}\\)；(2) \\(\\mathrm{H_2(g) + Cl_2(g)} \\xrightarrow{\\text{光照}} \\mathrm{2HCl(g)}\\)。","given":"离子生成反应 vs 共价分子生成反应","method":"离子键反应写电子完全得失；共价键反应写共用电子对偏移方向","principle":"金属电负性小失电子被氧化；电负性较大原子吸引电子对或得电子被还原。","steps":["(1) 在 \\(\\mathrm{Mg + Cl_2 \\to MgCl_2}\\) 中发生**电子的完全得失**：每个 Mg 原子失去 2 个电子变成 \\(\\mathrm{Mg^{2+}}\\)，镁元素发生**氧化反应**；每个 \\(\\mathrm{Cl_2}\\) 分子中的两个 Cl 原子各得到 1 个电子变成 \\(\\mathrm{Cl^-}\\)，氯元素发生**还原反应**。","(2) 在 \\(\\mathrm{H_2 + Cl_2 \\to 2HCl}\\) 中发生**共用电子对的偏移**：由于 Cl 电负性（3.0）大于 H（2.1），\\(\\mathrm{H-Cl}\\) 共价键中共用电子对偏向 Cl 原子、偏离 H 原子，因此氢元素发生**氧化反应**，氯元素发生**还原反应**。"],"ans":"(1) 电子完全得失：Mg 失电子氧化，Cl 得电子还原；(2) 共用电子对偏向 Cl：H 偏离电子氧化，Cl 吸引电子还原。","markingPoints":["区分(1)电子完全得失与(2)共用电子对偏移（2分）","准确指明两反应中发生氧化与还原的元素（2分）"],"verification":"化上 p.199–200 原文机制。","pitfall":"在(2)中误写成“H 原子完全失去电子变成 H⁺ 离子”。"},{"id":"chem8-8.1-q4","tier":"L3","tierLabel":"L3 预试","examStyle":"P1 选择","q":"下列反应中，不属于氧化还原反应的是（　）。","options":["A. 2H₂O₂(aq) → 2H₂O(l) + O₂(g)","B. NH₃(g) + HCl(g) → NH₄Cl(s)","C. 2Na(s) + 2H₂O(l) → 2NaOH(aq) + H₂(g)","D. S(s) + O₂(g) → SO₂(g)"],"correctOption":"B","given":"四个化学反应（含教材 p.207 例）","method":"检验元素氧化数变化","principle":"NH₃ + HCl 形成配位键与离子键，属于非氧化还原酸碱/化合反应。","steps":["A 中 O(−1→−2 和 0) 变价；B 中 N 始终 −3、H 始终 +1、Cl 始终 −1，只是 \\(\\mathrm{NH_3}\\) 的孤对电子与 \\(\\mathrm{H^+}\\) 形成配位键（非电子得失转移），故**不是**氧化还原反应；C 中 Na, H 变价；D 中 S, O 变价。"],"ans":"B","markingPoints":["识别配位键形成（酸碱加合）不改变氧化数"],"verification":"NH₃ + HCl → NH₄Cl 全程无任何元素氧化数改变。","pitfall":"看到“生成离子化合物 NH₄Cl”就错以为一定是电子转移氧化还原反应。"},{"id":"chem8-8.1-q5","tier":"L4","tierLabel":"L4 统考拔高","examStyle":"P1 选择","q":"某同学在学习第 8 章后对反应类别作出如下四点推理，其中**完全正确**的一项是（　）。","options":["A. 只要反应前后某元素的质量分数发生改变，该反应就一定是氧化还原反应","B. 某元素从游离态（单质）转变为化合态（化合物），该元素一定被氧化","C. 有单质参加且没有氧元素参加的化合反应，一定不是氧化还原反应","D. 在一个反应中，如果某种元素原子失去了电子，那么必有另一种（或同种）元素的原子得到了等量电子"],"correctOption":"D","given":"氧化还原四条深化判断","method":"逐项找反例或核对电子守恒定律","principle":"电子不能凭空产生或消失；单质变化合物可被氧化（金属）也可被还原（Cl₂, O₂）。","steps":["A 错：如 \\(\\mathrm{CaCO_3 \\to CaO + CO_2}\\) 固相中 Ca 质量分数改变但非氧化还原；B 错（教材 p.215 第 7 题）：单质变化合物可能被氧化（如 Na→NaCl），也可能被还原（如 Cl₂→NaCl）；C 错：如 \\(\\mathrm{H_2 + Cl_2 \\to 2HCl}\\) 无氧参与却是氧化还原；D 对：氧化反应与还原反应同时发生且电子得失守恒。"],"ans":"D","markingPoints":["综合排除质量分数、游离态、无氧参加三大迷思"],"verification":"化上 p.210 思考题 8c(4) & p.215 第 7 题一致。","pitfall":"误选 B（平时习惯想金属单质变阳离子被氧化，忘了非金属单质如 F₂, Cl₂ 变化合物常是被还原！）。"}],"cheatSheet":["氧化还原三层次：**得失氧（狭义）→ 电子得失或偏移（本质）→ 氧化数升降（判据）**。","与四大类型关系：**置换 100% 是**；**复分解 100% 不是**；有单质参加/生成的化合或分解通常是（**特例：\\(\\mathrm{3O_2\\to 2O_3}\\) 不是**！）。","某元素从**游离态（单质）变化合物**，**可能被氧化，也可能被还原**（取决于化合后是正价还是负价）。"],"kbEntryIds":["kb-chem8-redox-essence"],"quiz":{"q":"在反应 \\(\\mathrm{2Na(s) + 2H_2O(l) \\longrightarrow 2NaOH(aq) + H_2(g)}\\) 中，哪个元素被氧化、哪个元素被还原？","given":"Na(0→+1), H(+1→+1 和 0), O(−2→−2)","method":"核对反应前后氧化数升高和降低的元素","principle":"氧化数升高被氧化，降低被还原。","steps":["Na 从 0 升到 +1（失电子，被氧化）；水中部分 H 从 +1 降到 0 生成 \\(\\mathrm{H_2}\\)（得电子，被还原）。"],"ans":"Na 被氧化；水中部分 H 被还原。"}},{"id":"8.2","t":"氧化数","anchor":{"pages":"化上 p.200–204","syllabus":"1.6.2 氧化数计算规则、表 8-1 及双线桥表示电子转移","examScopes":["sem1_final","pre_exam","sem2_final","uec"],"examWeight":"P1 特例氧化数必考 + P2 双线桥书写必考点","terms":"oxidation number · peroxide · superoxide · half-equation · double-line bridge","prerequisites":["元素电负性大小顺序（F > O > Cl ≈ N > C > H > 金属，Ch 6 & Ch 7）","常见原子团（NH₄⁺, SO₄²⁻, NO₃⁻, MnO₄⁻, Cr₂O₇²⁻）的电荷数"],"goals":["熟记并准确应用计算氧化数的八条规则，处理 OF₂、过氧化物、超氧化物、NaH、FeS₂、NH₄NO₃ 等特例。","掌握主族元素最高正氧化数与最低负氧化数的周期规律（表 8-1）。","熟练书写氧化半反应与还原半反应，并规范画出“双线桥”标示电子转移方向与总数。"]},"concepts":[{"kind":"law","title":"8.2.1 计算氧化数的八条一般规则（含特例清单）","pageRef":"化上 p.201–202","body":["**氧化数（oxidation number）**是显示某元素在化合状态下电子得失情况的“想象”电荷数，**可以是正数、负数、零，也可以是分数**。在共价分子中，正负号取决于两原子**电负性**的相对大小（电负性大的呈负氧化数）。","**教材八条规则（p.201–202）**：","- ① **单质**：元素氧化数为 **0**（如 \\(\\mathrm{Ca, O_2, S_8, P_4}\\)）。","- ② **IA 族**在化合物中永远是 **+1**；③ **IIA 族**在化合物中永远是 **+2**。","- ④ **VIIA 族（卤素）**在简单卤化物（如 \\(\\mathrm{NaCl, CaBr_2}\\)）中一般为 **−1**（在含氧酸盐如 \\(\\mathrm{ClO^-, ClO_3^-, ClO_4^-}\\) 中呈正价 +1, +5, +7）。","- ⑤ **氟（F）**电负性最大（4.0），在所有化合物中氧化数**永远是 −1**（无正价！）。","- ⑥ **氢（H）**一般为 **+1**；但在**活泼金属氢化物**（如 \\(\\mathrm{NaH, KH, CaH_2}\\)，因 H 电负性 2.1 > 金属 0.9–1.0）中为 **−1**。","- ⑦ **氧（O）**一般为 **−2**；但有三大著名特例：在二氟化氧（**\\(\\mathrm{OF_2}\\)**）中为 **+2**；在过氧化物（**\\(\\mathrm{H_2O_2, Na_2O_2, BaO_2}\\)**）中为 **−1**；在超氧化物（如超氧化钾 **\\(\\mathrm{KO_2}\\)**）中为 **\\(-\\frac{1}{2}\\)**。","- ⑧ **代数和规则**：中性化合物中各元素氧化数代数和等于 **0**；多原子离子中各元素氧化数代数和等于该离子所带的**电荷数**。"],"takeaway":"遇到特例切勿慌：先固定“**绝对不变铁律**”——F 永远 −1，IA 永远 +1，IIA 永远 +2，再用代数和反推 H 或 O！"},{"kind":"table","title":"主族元素最高正氧化数与最低负氧化数（表 8-1）及易错特例分子","pageRef":"化上 p.202–203、p.216","body":["结合教材表 8-1（1–3 周期）及常见高阶化合物整理易错氧化数："],"table":{"headers":["化合物 / 离子","目标元素","氧化数结果","推导要点 / 注意事项"],"rows":[["OF₂ / H₂O₂ / KO₂","O","+2 / −1 / −1/2","F 恒 −1 ⇒ O 为 +2；Na₂O₂ 中 Na 恒 +1 ⇒ O 为 −1；KO₂ 中 K +1 ⇒ O 为 −1/2"],["NaH / CaH₂","H","−1","金属 IA(+1)/IIA(+2) 恒正，故氢为 −1"],["(NH₄)₂SO₄ / NH₄NO₃","N","−3（前）/ −3 与 +5（后）","NH₄⁺ 中 N+4(+1)=+1 ⇒ −3；NO₃⁻ 中 N+3(−2)=−1 ⇒ +5（不可混平均！）"],["ClO⁻ / ClO₃⁻ / ClO₄⁻","Cl","+1 / +5 / +7","O 为 −2，代数和分别为 −1, −1, −1"],["MnO₄⁻ / Cr₂O₇²⁻","Mn / Cr","+7 / +6","2Cr + 7(−2) = −2 ⇒ Cr = +6"],["FeS₂（黄铁矿）/ Fe₃O₄","Fe, S / Fe","Fe +2, S −1 / Fe 平均 +8/3","FeS₂ 含过硫离子 S₂²⁻；Fe₃O₄ 为 1个 Fe(+2) 与 2个 Fe(+3)"]]},"takeaway":"表 8-1 主族规律：**最高正氧化数 = 最外层电子数**（O、F 除外）；**非金属最低负氧化数 = 最外层电子数 − 8**（或与氢化合的负价）。"},{"kind":"mechanism","title":"8.2.2 氧化数升降、半反应式与双线桥画法规范","pageRef":"化上 p.203–204","body":["**氧化数角度重定义**：元素**氧化数升高**的反应是**氧化反应**（相当于失去电子带更多正电荷）；元素**氧化数降低**的反应是**还原反应**（相当于得到电子带更多负电荷）。","**半反应（half-equation）**：因氧化与还原同时发生，可把完整反应拆写为两个半反应式（以教材 p.204 例题 \\(\\mathrm{Zn(s) + CuSO_4(aq) \\to ZnSO_4(aq) + Cu(s)}\\) 为例）：","- 氧化半反应：\\(\\mathrm{Zn(s) \\longrightarrow Zn^{2+}(aq) + 2e^-}\\)（失 \\(2\\mathrm{e^-}\\)，氧化数 0→+2 升高，被氧化）；","- 还原半反应：\\(\\mathrm{Cu^{2+}(aq) + 2e^- \\longrightarrow Cu(s)}\\)（得 \\(2\\mathrm{e^-}\\)，氧化数 +2→0 降低，被还原）。","**双线桥规范标注（p.204 & p.216 第 2 题）**：一条线桥从反应物失电子元素指向生成物对应元素，另一条从反应物得电子元素指向生成物对应元素；每条线桥上标明**“失去/得到 \\(n\\,\\mathrm{e^-}\\)，氧化数升高/降低，被氧化/被还原”**，且两条线桥的得失电子**总数必须严格相等**！"],"takeaway":"注意区别：氧化数标号写成 **`+2`、`−1`**（符号在数字**前**），而离子电荷写成 **`2+`、`−`**（符号在数字**后**），规范答题不可混淆！"}],"formulas":[{"title":"化合物与多原子离子氧化数代数和守恒式","tex":"\\sum_i n_i\\,\\mathrm{ON}_i = 0\\;(\\text{化合物}),\\qquad \\sum_i n_i\\,\\mathrm{ON}_i = q\\;(\\text{多原子离子})","plain":"化合物各元素氧化数代数和 = 0；离子各元素氧化数代数和 = 离子电荷数 q","conditions":"存在多个相同原子团或不同价态同一元素（如 NH₄NO₃）时应分别拆算","pageRef":"化上 p.202","note":"如 S₂O₃²⁻（硫代硫酸根）：2×ON(S) + 3×(−2) = −2 ⇒ 平均 ON(S) = +2。"},{"title":"主族非金属最高正与最低负氧化数关系","tex":"\\mathrm{ON}_{\\max} = N_{\\text{价}e^-},\\qquad \\mathrm{ON}_{\\min} = N_{\\text{价}e^-} - 8,\\qquad \\mathrm{ON}_{\\max} + |\\mathrm{ON}_{\\min}| = 8","plain":"主族最高正氧化数 = 最外层电子数；非金属最低负氧化数 = 最外层电子数 − 8","conditions":"主族第 IVA–VIIA 族适用（F 无正价，O 通常不显 +6 最高正价）","pageRef":"化上 p.202–203 表 8-1","note":"如 Cl(+7, −1)、S(+6, −2)、N(+5, −3)、C(+4, −4)。"}],"pitfalls":[{"title":"把“离子电荷符号（2+）”和“氧化数符号（+2）”写反，或把 NH₄NO₃ 中两个 N 平均成 +1","wrong":"“\\(\\mathrm{NH_4NO_3}\\) 中氮元素的氧化数是 \\((+1) \\text{?}\\) 因为 \\(2N + 4 - 6 = 0\\)；且铜离子的氧化数是 \\(2+\\)。”","diagnosis":"\\(\\mathrm{NH_4NO_3}\\) 由 \\(\\mathrm{NH_4^+}\\) 和 \\(\\mathrm{NO_3^-}\\) 两种独立离子构成，两个 N 处于完全不同的化学环境，必须分别计算！另外氧化数符号在**数字前面**。","right":"\\(\\mathrm{NH_4^+}\\) 中 N 为 **−3**，\\(\\mathrm{NO_3^-}\\) 中 N 为 **+5**；\\(\\mathrm{Cu^{2+}}\\) 中铜的氧化数为 **+2**。","checkRule":"遇到铵盐含氧酸盐（如 \\(\\mathrm{NH_4NO_3}\\)）必拆成阳离子和阴离子分开算！"},{"title":"双线桥算错“总转移电子数”或箭头连错反应物/产物","wrong":"“在 \\(\\mathrm{2KClO_3 \\to 2KCl + 3O_2\\uparrow}\\) 中，标成‘Cl 降低 6 得到 6e⁻’、‘O 升高 2 失去 2e⁻’。”","diagnosis":"方程式中有 **2 个** Cl 原子（共得 \\(2\\times 6 = 12\\mathrm{e^-}\\)）和 **6 个** O 原子（共失 \\(6\\times 2 = 12\\mathrm{e^-}\\)），单原子标数未乘以化学计量数与下标！","right":"双线桥必须乘以实际变价原子总个数：Cl 桥写“得到 \\(2\\times 6\\mathrm{e^-} = 12\\mathrm{e^-}\\)”，O 桥写“失去 \\(6\\times 2\\mathrm{e^-} = 12\\mathrm{e^-}\\)”，上下电子总数严格相等（均为 \\(12\\mathrm{e^-}\\)）。","checkRule":"画完双线桥必查一步：**上桥失电子总数 == 下桥得电子总数**！"},{"title":"习惯性把过氧化物或氢化物中的 O 算成 −2、H 算成 +1","wrong":"“\\(\\mathrm{Na_2O_2}\\) 中 O 是 −2 价，所以 Na 是 +2 价；\\(\\mathrm{NaH}\\) 中 H 是 +1 价，所以 Na 是 −1 价。”","diagnosis":"违背规则②优先级：IA 族金属（Li, Na, K）电负性极小，在化合物中**永远只能是 +1**，绝无 −1 或 +2！","right":"先定 IA 族 Na = +1，故 \\(\\mathrm{Na_2O_2}\\) 中 O 为 **−1**；\\(\\mathrm{NaH}\\) 中 H 为 **−1**。","checkRule":"IA(+1), IIA(+2), F(−1) 三者优先级永远高于 H(+1) 和 O(−2)！"}],"examples":[{"label":"例 8.2.1","tier":"L2","tierLabel":"L2 校内期末","title":"教材 p.202 交流分享 & p.216 第 1 题：复杂与特例物质氧化数全练","prompt":"请逐一计算下列物质或离子中划线/指定元素的氧化数：\n(1) 过氧化钠（\\(\\mathrm{Na_2O_2}\\)）中的 O；(2) 二氟化氧（\\(\\mathrm{OF_2}\\)）中的 O；(3) 超氧化钾（\\(\\mathrm{KO_2}\\)）中的 O；(4) 氢化钙（\\(\\mathrm{CaH_2}\\)）中的 H；(5) 次氯酸（\\(\\mathrm{HClO}\\)）与高氯酸根（\\(\\mathrm{ClO_4^-}\\)）中的 Cl；(6) 硫酸铵（\\(\\mathrm{(NH_4)_2SO_4}\\)）中的 N 与 S；(7) 二氧化二铁还是黄铁矿（\\(\\mathrm{FeS_2}\\)，已知 Fe 显 +2）中的 S；(8) 重铬酸根（\\(\\mathrm{Cr_2O_7^{2-}}\\)）中的 Cr。","clues":"利用“F 恒 −1、IA 恒 +1、IIA 恒 +2”优先级和离子拆算原则。","strategy":"逐个列代数和方程，注意分数氧化数（−1/2）在超氧化物中的合法性。","given":"8 组特例化合物与多原子离子","principle":"计算氧化数的八条一般规则（化上 p.201–202）。","steps":["(1) \\(\\mathrm{Na_2O_2}\\)：Na 恒 +1 ⇒ \\(2(+1) + 2x = 0 \\implies x = -1\\)。","(2) \\(\\mathrm{OF_2}\\)：F 恒 −1 ⇒ \\(x + 2(-1) = 0 \\implies x = +2\\)。","(3) \\(\\mathrm{KO_2}\\)：K 恒 +1 ⇒ \\(+1 + 2x = 0 \\implies x = -\\frac{1}{2}\\)。","(4) \\(\\mathrm{CaH_2}\\)：Ca 恒 +2 ⇒ \\(+2 + 2x = 0 \\implies x = -1\\)。","(5) \\(\\mathrm{HClO}\\)：\\(+1 + x + (-2) = 0 \\implies x = +1\\)；\\(\\mathrm{ClO_4^-}\\)：\\(x + 4(-2) = -1 \\implies x = +7\\)。","(6) 拆分为 \\(\\mathrm{NH_4^+}\\) 与 \\(\\mathrm{SO_4^{2-}}\\)：\\(x_{\\mathrm{N}} + 4(+1) = +1 \\implies -3\\)；\\(x_{\\mathrm{S}} + 4(-2) = -2 \\implies +6\\)。","(7) \\(\\mathrm{FeS_2}\\)：已知 Fe 为 +2 ⇒ \\(+2 + 2x_{\\mathrm{S}} = 0 \\implies x_{\\mathrm{S}} = -1\\)（类似过氧化物结构）。","(8) \\(\\mathrm{Cr_2O_7^{2-}}\\)：\\(2x + 7(-2) = -2 \\implies 2x = +12 \\implies x = +6\\)。"],"answer":"(1) −1；(2) +2；(3) −1/2；(4) −1；(5) +1, +7；(6) N −3, S +6；(7) −1；(8) +6。","markingPoints":["准确算出过氧化物(−1)、OF₂(+2)、超氧化物(−1/2)、CaH₂(−1)（2分）","正确拆算 (NH₄)₂SO₄ 与多原子离子 ClO₄⁻, Cr₂O₇²⁻（2分）"],"verification":"化上 p.202 交流分享 & p.216 第 1 题核对无误。","pitfall":"第(3)问误以为氧化数必须是整数而不敢写 −1/2；第(7)问误以为 S 永远是 −2 而反推 Fe=+4（Fe 无 +4 简单阳离子！）。"},{"label":"例 8.2.2","tier":"L3","tierLabel":"L3 预试拔高","title":"教材 p.216 第 2 题精选：规范书写双线桥并剖析半反应","prompt":"请写出下列两个氧化还原反应的**氧化半反应式**和**还原半反应式**，并用文字精确描述**双线桥**的起止元素与电子转移总数：\n(1) \\(\\mathrm{3H_2(g) + Fe_2O_3(s)} \\longrightarrow \\mathrm{3H_2O(l) + 2Fe(s)}\\)\n(2) \\(\\mathrm{2H_2S(g) + SO_2(g)} \\longrightarrow \\mathrm{3S(s) + 2H_2O(l)}\\)","clues":"第(2)问是归中反应：H₂S 中的 S(−2) 与 SO₂ 中的 S(+4) 均变价生成 0 价 S，遵循“高价降、低价升，只靠拢不交叉”！","strategy":"先标所有变价元素反应前后的氧化数，再按总数配对写入双线桥与半反应。","given":"反应(1) 3H₂ + Fe₂O₃；反应(2) 2H₂S + SO₂ (归中反应)","principle":"电子得失守恒；双线桥连同种变价元素；归中反应氧化数变化互不交叉。","steps":["反应(1)：\\(\\mathrm{H}\\) 由 \\(0 \\to +1\\)（共 \\(6\\) 个 H 原子，共失 \\(6\\mathrm{e^-}\\)）；\\(\\mathrm{Fe}\\) 由 \\(+3 \\to 0\\)（共 \\(2\\) 个 Fe 原子，共得 \\(6\\mathrm{e^-}\\)）。","- 氧化半反应：\\(\\mathrm{3H_2(g) \\longrightarrow 6H^+ + 6e^-}\\)；还原半反应：\\(\\mathrm{Fe_2O_3(s) + 6H^+ + 6e^- \\longrightarrow 2Fe(s) + 3H_2O(l)}\\)（或简写 \\(\\mathrm{2Fe^{3+} + 6e^- \\to 2Fe}\\)）。","- 双线桥描述：上桥从 \\(\\mathrm{3H_2}\\) 的 H 指向 \\(\\mathrm{3H_2O}\\) 的 H：“失去 \\(6\\mathrm{e^-}\\)，氧化数由 \\(0\\) 升高到 \\(+1\\)，被氧化”；下桥从 \\(\\mathrm{Fe_2O_3}\\) 的 Fe 指向 \\(\\mathrm{2Fe}\\)：“得到 \\(6\\mathrm{e^-}\\)，氧化数由 \\(+3\\) 降低到 \\(0\\)，被还原”。","反应(2)（归中反应）：\\(\\mathrm{2H_2S}\\) 中 S 由 \\(-2 \\to 0\\)（2 个 S 失 \\(4\\mathrm{e^-}\\)）；\\(\\mathrm{SO_2}\\) 中 S 由 \\(+4 \\to 0\\)（1 个 S 得 \\(4\\mathrm{e^-}\\)），共生成 3 mol S（其中 2 mol 是氧化产物、1 mol 是还原产物）。","- 双线桥描述：上桥从 \\(\\mathrm{2H_2S}\\) 的 S 指向 \\(\\mathrm{3S}\\)：“失去 \\(4\\mathrm{e^-}\\)，氧化数由 \\(-2\\) 升高到 \\(0\\)，被氧化”；下桥从 \\(\\mathrm{SO_2}\\) 的 S 指向 \\(\\mathrm{3S}\\)：“得到 \\(4\\mathrm{e^-}\\)，氧化数由 \\(+4\\) 降低到 \\(0\\)，被还原”。"],"answer":"(1) 转移 6e⁻：3H₂ 失 6e⁻ 被氧化，Fe₂O₃ 得 6e⁻ 被还原；(2) 转移 4e⁻：2H₂S 中 S(−2→0) 失 4e⁻ 被氧化，SO₂ 中 S(+4→0) 得 4e⁻ 被还原。","markingPoints":["第(1)问双线桥起止正确且电子总数为 6e⁻（2分）","第(2)问准确识别归中反应（2 份 S 升 + 1 份 S 降），转移 4e⁻（3分）"],"verification":"归中反应电子数核对：\\(2\\times 2 = 4\\mathrm{e^-}\\)，\\(1\\times 4 = 4\\mathrm{e^-}\\)，得失完全守恒。","pitfall":"反应(2)极易错算成转移 6e⁻（误以为全升 6 或直接 2+4=6）或连成单一一条线桥。"}],"practice":[{"id":"chem8-8.2-q1","tier":"L1","tierLabel":"L1 基础","examStyle":"P1 选择","q":"下列物质中，氯（Cl）元素与氧（O）元素的氧化数分别为 \\(+5\\) 和 \\(-1\\) 的组合是（　）。","options":["A. KClO₃ 和 H₂O","B. KClO₃ 和 H₂O₂","C. KClO₄ 和 Na₂O₂","D. HClO 和 OF₂"],"correctOption":"B","given":"四组含氯、含氧物质","method":"分别代入规则计算 Cl 与 O 的氧化数","principle":"K(+1), H(+1), Na(+1), F(−1)，过氧化物 O 为 −1。","steps":["\\(\\mathrm{KClO_3}\\) 中：\\(+1 + x_{\\mathrm{Cl}} + 3(-2) = 0 \\implies x_{\\mathrm{Cl}} = +5\\)；\\(\\mathrm{H_2O_2}\\) 中：\\(2(+1) + 2x_{\\mathrm{O}} = 0 \\implies x_{\\mathrm{O}} = -1\\)。故选 B。"],"ans":"B","markingPoints":["掌握氯酸盐与过氧化物氧化数"],"verification":"C 项 KClO₄ 中 Cl 为 +7；D 项 HClO 中 Cl 为 +1、OF₂ 中 O 为 +2。","pitfall":"把 KClO₃ 与 KClO₄ 算混。"},{"id":"chem8-8.2-q2","tier":"L2","tierLabel":"L2 期末","examStyle":"P1 选择","q":"在反应 \\(\\mathrm{2KMnO_4(s) + 16HCl(aq) \\longrightarrow 2KCl(aq) + 2MnCl_2(aq) + 5Cl_2(g) + 8H_2O(l)}\\) 中，当消耗 \\(2\\text{ mol }\\mathrm{KMnO_4}\\) 时，反应中转移电子的总物质的量为（　）。","options":["A. 5 mol","B. 10 mol","C. 16 mol","D. 32 mol"],"correctOption":"B","given":"2 mol KMnO₄ 完全反应生成 5 mol Cl₂","method":"从 Mn(+7→+2) 或 Cl₂(2×(−1→0)) 任选一条线桥算总电子数","principle":"2 mol Mn(+7→+2) 共得 2×5 = 10 mol 电子；10 mol Cl⁻(−1→0) 共失 10 mol 电子。","steps":["反应中 16 mol HCl 仅有 10 mol 的 Cl⁻ 被氧化为 5 mol Cl₂（另 6 mol HCl 生成盐显酸性），故转移电子 \\(= 2\\times (7-2) = 10\\text{ mol}\\)。"],"ans":"B","markingPoints":["算准高锰酸钾与浓盐酸反应转移 10 mol e⁻（非 16 mol！）"],"verification":"化上 p.212 离子—电子法例题恰好把还原半反应 ×2（共 10e⁻）。","pitfall":"错选 C（误以为 16 mol HCl 全部被氧化转移 16 mol 电子）或 A（忘乘系数 2）。"},{"id":"chem8-8.2-q3","tier":"L2","tierLabel":"L2 期末","examStyle":"P2 简答","q":"写出下列指定物质或离子中划线/特定元素的氧化数：(1) \\(\\mathrm{Na_2S_2O_3}\\)（硫代硫酸钠）中的 S；(2) \\(\\mathrm{NH_4NO_3}\\) 中的两个 N；(3) \\(\\mathrm{KO_2}\\) 中的 O；(4) 若某金属过氧化物 \\(\\mathrm{BaO_2}\\) 与稀硫酸反应生成 \\(\\mathrm{BaSO_4\\downarrow}\\) 和 \\(\\mathrm{H_2O_2}\\)，判断该反应**是否**属于氧化还原反应，并说明理由。","given":"Na₂S₂O₃, NH₄NO₃, KO₂；BaO₂ + H₂SO₄ → BaSO₄ + H₂O₂","method":"规则计算氧化数并比较反应前后 O 氧化数是否改变","principle":"BaO₂ 与 H₂O₂ 同为过氧化物，O 均显 −1 价。","steps":["(1) \\(\\mathrm{Na_2S_2O_3}\\)：\\(2(+1) + 2x + 3(-2) = 0 \\implies x = +2\\)。","(2) \\(\\mathrm{NH_4^+}\\) 中 N 为 **−3**，\\(\\mathrm{NO_3^-}\\) 中 N 为 **+5**。","(3) \\(\\mathrm{KO_2}\\) 中 K 为 +1，故 O 为 **−1/2**。","(4) **不属于**氧化还原反应！因为 \\(\\mathrm{BaO_2}\\) 是过氧化物（Ba 为 +2，O 为 **−1**），产物 \\(\\mathrm{H_2O_2}\\) 中 O 也仍是 **−1**，\\(\\mathrm{SO_4^{2-}}\\) 中 S(+6) 和 O(−2) 均未改变，全程无任何元素氧化数变化（实质为复分解反应）。"],"ans":"(1) +2；(2) −3 和 +5；(3) −1/2；(4) 不是，反应前后 O 均保持 −1（在过氧根内）或 −2（在硫酸根内），无氧化数变化。","markingPoints":["正确给出 +2, −3/+5, −1/2（3分）","准确判断 BaO₂+H₂SO₄ 非氧化还原反应并指出 O 均保持 −1（2分）"],"verification":"过氧化钡制双氧水是教材经典非氧化还原特例。","pitfall":"第(4)问没认出 BaO₂ 和 H₂O₂ 的 O 都是 −1 价，而误判成了氧化还原反应。"},{"id":"chem8-8.2-q4","tier":"L3","tierLabel":"L3 预试","examStyle":"P1 选择","q":"下列叙述中，元素氧化数变化标注或双线桥说法**错误**的是（　）。","options":["A. 在 Na₂O₂ 与 CO₂ 反应生成 Na₂CO₃ 和 O₂ 中，每生成 1 mol O₂ 转移 2 mol 电子","B. 在 2KClO₃ → 2KCl + 3O₂↑ 中，若生成 3 mol O₂，则共有 12 mol 电子从氧元素转移给氯元素","C. 在 Cu + 4HNO₃(浓) → Cu(NO₃)₂ + 2NO₂↑ + 2H₂O 中，所有 N 原子的氧化数都从 +5 降至 +4","D. 在 Fe₃O₄ 中，铁元素的平均氧化数为 +8/3（内含 1 个 +2 价 Fe 与 2 个 +3 价 Fe）"],"correctOption":"C","given":"四个高阶氧化数与电子转移分析","method":"逐一核对变价原子比例与守恒计算","principle":"浓硝酸与铜反应时，4 mol HNO₃ 只有 2 mol 被还原为 NO₂，另 2 mol 生成 Cu(NO₃)₂ 显酸性（N 仍为 +5）。","steps":["A 对：\\(\\mathrm{2Na_2O_2 + 2CO_2 \\to 2Na_2CO_3 + O_2}\\) 属于过氧根内氧的歧化（一半 −1→−2，一半 −1→0），生成 1 mol O₂ 共转移 2 mol e⁻；","B 对：2 个 Cl(+5→−1) 得 12e⁻，6 个 O(−2→0) 失 12e⁻；","C 错：生成物 \\(\\mathrm{Cu(NO_3)_2}\\) 中的 2 个 \\(\\mathrm{NO_3^-}\\) 里的 N 依然是 +5，并未降价！","D 对：Fe₃O₄ = FeO·Fe₂O₃，平均 +8/3。"],"ans":"C","markingPoints":["识别 HNO₃ 既显氧化性又显酸性的部分变价特征"],"verification":"对照化上 p.209 与 p.216 第 4 题原理。","pitfall":"选 A，算错 2Na₂O₂ + 2CO₂ 的转移电子数（经常错算成 4 mol e⁻，实际是 2 个 −1 价 O 升到 0 价只转移 **2 mol e⁻**！）。"},{"id":"chem8-8.2-q5","tier":"L4","tierLabel":"L4 统考压轴","examStyle":"P2 综合计算","q":"工业上常用黄铁矿（主要成分 \\(\\mathrm{FeS_2}\\)）在高温下与氧气煅烧制备二氧化硫和氧化铁：\\(\\mathrm{4FeS_2(s) + 11O_2(g)} \\xrightarrow{\\text{高温}} \\mathrm{2Fe_2O_3(s) + 8SO_2(g)}\\)。已知 \\(\\mathrm{FeS_2}\\) 中铁元素显 \\(+2\\) 价，硫元素显 \\(-1\\) 价。试回答：(1) 写出该反应中所有发生氧化数变化的元素及其反应前后的氧化数；(2) 该反应中哪几种元素被氧化、哪几种元素被还原？(3) 若有 \\(1\\text{ mol }\\mathrm{FeS_2}\\) 完全参加反应，总共转移了多少摩尔电子？","given":"4FeS₂ + 11O₂ → 2Fe₂O₃ + 8SO₂；FeS₂ 中 Fe(+2), S(−1)","method":"多种元素同时升价时，还原方电子数之和必须等于氧化方（O₂）得电子数！","principle":"电子得失总守恒：4FeS₂ 失电子总和 = 11O₂ 得电子总数 = 44e⁻。","steps":["(1) 变价元素有 3 种：**Fe**（\\(+2 \\to +3\\)）、**S**（\\(-1 \\to +4\\)）、**O**（\\(0 \\to -2\\)）。","(2) Fe 和 S 氧化数均升高，两者**都被氧化**；O 氧化数降低，**被还原**。","(3) 按反应方程式计算 \\(4\\text{ mol }\\mathrm{FeS_2}\\) 转移总电子：\\(4\\text{ mol Fe}\\)（\\(+2\\to +3\\)）失 \\(4\\times 1 = 4\\text{ mol }e^-\\)；\\(8\\text{ mol S}\\)（\\(-1\\to +4\\)）失 \\(8\\times 5 = 40\\text{ mol }e^-\\)；总共失电子 \\(4 + 40 = 44\\text{ mol }e^-\\)（校验：\\(11\\text{ mol O}_2\\) 共 22 mol O 原子从 0→−2 恰好得 \\(22\\times 2 = 44\\text{ mol }e^-\\)！）。","因此每消耗 \\(1\\text{ mol }\\mathrm{FeS_2}\\)，转移电子为 \\(44 \\div 4 = 11\\text{ mol}\\)！"],"ans":"(1) Fe(+2→+3), S(−1→+4), O(0→−2)；(2) Fe 与 S 被氧化，O 被还原；(3) 11 mol 电子。","markingPoints":["准确列出 3 种变价元素前后氧化数（2分）","指出 Fe 和 S 同时被氧化、O 被还原（1分）","双边校验算得 4 mol FeS₂ 转移 44 mol e⁻ ⇒ 1 mol 转移 11 mol e⁻（2分）"],"verification":"1 mol FeS₂ 消耗 \\(\\frac{11}{4}\\text{ mol }\\mathrm{O_2}\\)，得电子 \\(\\frac{11}{4}\\times 4 = 11\\text{ mol}\\)，完全匹配。","pitfall":"漏算 Fe(+2→+3) 的 1 个电子而错算出 10 mol e⁻！"}],"cheatSheet":["氧化数必背特例：**O**：一般 −2，**OF₂ 中 +2**，**过氧化物(H₂O₂/Na₂O₂) −1**，**超氧化物(KO₂) −1/2**；**H**：一般 +1，**NaH/CaH₂ 中 −1**；**F 恒 −1**。","多核离子盐拆算：**NH₄NO₃** = **−3** (NH₄⁺) + **+5** (NO₃⁻)；**FeS₂** = Fe(+2) + S(−1)；**Fe₃O₄** = 平均 +8/3。","双线桥三检查：① 箭头连**同种元素**；② 写清**失/得总 e⁻ 数 + 氧化数变化 + 被氧化/还原**；③ **总失电子 == 总得电子**。"],"kbEntryIds":["kb-chem8-oxidation-rules","kb-chem8-double-bridge"],"quiz":{"q":"在消毒反应 \\(\\mathrm{Cl_2 + 2NaOH \\longrightarrow NaCl + NaClO + H_2O}\\) 中，\\(1\\text{ mol }\\mathrm{Cl_2}\\) 完全反应时转移多少摩尔电子？","given":"Cl₂(0) → Cl⁻(−1) + ClO⁻(+1)","method":"歧化反应中 1 mol Cl₂ 拆成 1 mol Cl 升价 + 1 mol Cl 降价","principle":"电子转移数目等于升价总值（或降价总值）。","steps":["1 mol Cl₂ 中 1 mol Cl 原子由 0 升至 +1（失 1 mol e⁻），另 1 mol Cl 原子由 0 降至 −1（得 1 mol e⁻），故转移 1 mol 电子。"],"ans":"\\(1\\text{ mol}\\) 电子。"}},{"id":"8.3","t":"氧化剂与还原剂","anchor":{"pages":"化上 p.205–209","syllabus":"1.6.3 氧化剂与还原剂判别及氧化性/还原性强弱规律","examScopes":["sem1_final","pre_exam","sem2_final","uec"],"examWeight":"P1 常见剂类判断 & 氧化性排序 + P2 金属置换探究（活动 2）与酸的多重性","terms":"oxidizing agent (oxidant) · reducing agent (reductant) · oxidation product · reduction product","prerequisites":["氧化数计算与双线桥分析（8.2）","金属活动性顺序与卤素非金属性递变（Ch 6）"],"goals":["精准辨别反应中的氧化剂、还原剂、氧化产物与还原产物，并理解同一物质（如 S、H₂O₂）的多重角色。","熟记教材列举的四类常见氧化剂与四类常见还原剂。","熟练运用四大方法（价态规律、元素活动性、反应方向强制弱、同一起点反应条件难易）比较物质的氧化性与还原性强弱。"]},"concepts":[{"kind":"definition","title":"氧化剂、还原剂与氧化产物、还原产物（图 8-3）","pageRef":"化上 p.205–206","body":["**核心定义（p.205）**：","- **氧化剂（oxidizing agent）**：在氧化还原反应中**得到电子**、元素**氧化数降低**、自身**被还原**的反应物（生成**还原产物**）；","- **还原剂（reducing agent）**：在氧化还原反应中**失去电子**、元素**氧化数升高**、自身**被氧化**的反应物（生成**氧化产物**）。","**氧化剂/还原剂的相对性（p.207）**：某物质作氧化剂还是还原剂不是绝对的，取决于它在特定反应中对手的强弱。例如硫单质（\\(\\mathrm{S}\\)，0 价，中间氧化数）：与强氧化剂 \\(\\mathrm{O_2}\\) 反应（\\(\\mathrm{S + O_2 \\to SO_2}\\)）时 S 升至 +4 作**还原剂**；与 \\(\\mathrm{H_2}\\) 反应（\\(\\mathrm{S + H_2 \\to H_2S}\\)）时 S 降至 −2 作**氧化剂**。而在 \\(\\mathrm{2H_2O_2 \\to 2H_2O + O_2\\uparrow}\\) 中，\\(\\mathrm{H_2O_2}\\) 既是氧化剂又是还原剂（**歧化反应**）。"],"takeaway":"必背八字口诀：**“升失氧还剂，降得还氧剂”**；以及**“还原剂 → 氧化产物；氧化剂 → 还原产物”**（千万别对应反了！）。"},{"kind":"table","title":"教材整理的常见氧化剂与常见还原剂四大类别","pageRef":"化上 p.207–208","body":["整理化上 p.207–208 两栏“资料链接”中的四类典型物质，考场上看到即可快速定性。"],"table":{"headers":["分类序号","常见氧化剂（氧化数易降低，p.207）","常见还原剂（氧化数易升高，p.208）"],"rows":[["① 单质类","活泼非金属单质：F₂, Cl₂, Br₂, I₂, O₂","活泼金属单质（K, Ca, Na, Al, Zn, Fe）与部分非金属（H₂, C）"],["② 金属离子类","含最高氧化数的金属阳离子化合物：FeCl₃（Fe³⁺）、Cu²⁺ 等","含较低氧化数的金属阳离子化合物：FeCl₂（Fe²⁺）等"],["③ 含氧酸/盐/化合物","含较高氧化数元素的化合物：浓 H₂SO₄, HNO₃, KMnO₄, K₂Cr₂O₇, KClO₃","含较低氧化数元素化合物：CO, SO₂, H₂S, HI, Na₂SO₃, Na₂S₂O₃"],["④ 特殊化合物","过氧化物（如 H₂O₂, Na₂O₂）","（注：H₂O₂ 遇更强氧化剂 KMnO₄ 时亦可作还原剂放出 O₂）"]]},"takeaway":"酸（如 \\(\\mathrm{HCl, H_2SO_4, HNO_3}\\)）在氧化还原中常扮演双重角色（既当氧化剂/还原剂，又提供 \\(\\mathrm{H^+/Cl^-/SO_4^{2-}}\\) 生成盐而显**酸性**，教材 p.216 第 4 题专项考察）。"},{"kind":"law","title":"比较氧化性、还原性强弱的四大核心判据（p.208–209）","pageRef":"化上 p.208–209","body":["**方法一：利用元素氧化数（价态）判断**：同一元素的不同价态中，**最高价只具有氧化性**（如 \\(\\mathrm{Fe^{3+}, H^+}\\)），**最低价只具有还原性**（如 \\(\\mathrm{I^-, S^{2-}}\\)），**中间价态既有氧化性又有还原性**（如 \\(\\mathrm{Fe^{2+}, S, SO_2, H_2O_2}\\)）。对铁元素：氧化性 \\(\\mathrm{Fe < Fe^{2+} < Fe^{3+}}\\)，还原性 \\(\\mathrm{Fe > Fe^{2+} > Fe^{3+}}\\)（教材 p.209 原文，注：一般不提价态越高质量越绝对，仅限同元素或主族相邻比较）。","**方法二：利用元素活动性顺序**：","- 金属单质还原性：\\(\\mathrm{K > Ca > Na > Mg > Al > \\dots > Hg > Ag > Pt > Au}\\) ⇒ 对应金属阳离子氧化性相反：**\\(\\mathrm{K^+ < Ca^{2+} < Na^+ < Mg^{2+} < Al^{3+} < \\dots < Hg^{2+} < Ag^+ < Pt^{2+} < Au^+}\\)**（注：\\(\\mathrm{Fe^{3+}}\\) 氧化性强于 \\(\\mathrm{Cu^{2+}}\\)）；","- 非金属单质氧化性：\\(\\mathrm{F_2 > Cl_2 > Br_2 > I_2 > S}\\) ⇒ 对应阴离子还原性相反：**\\(\\mathrm{F^- < Cl^- < Br^- < I^- < S^{2-}}\\)**。","**方法三：利用已知氧化还原反应方向（“强制弱”铁律）**：在一般正向自发反应中，**氧化性：氧化剂 > 氧化产物**；**还原性：还原剂 > 还原产物**（如 \\(\\mathrm{2FeCl_3 + Cu \\to CuCl_2 + 2FeCl_2}\\) 说明氧化性 \\(\\mathrm{Fe^{3+} > Cu^{2+}}\\)，还原性 \\(\\mathrm{Cu > Fe^{2+}}\\)）。","**方法四：利用同一起点反应的难易（反应条件）**：反应条件越温和、越容易发生，对应剂越强。如 Cu 与**浓硝酸**在**常温**即可剧烈反应（产生 \\(\\mathrm{NO_2}\\)），而与**浓硫酸**需**加热**才反应（产生 \\(\\mathrm{SO_2}\\)），故氧化性：**浓硝酸 > 浓硫酸**。"],"takeaway":"“强制弱”口诀在 P1 选择题无往不利：已知反应能发生，直接写 **氧化剂 > 氧化产物**、**还原剂 > 还原产物**，切忌比较“氧化剂与还原产物”！"}],"formulas":[{"title":"氧化性与还原性强弱的反应方向判据（强制弱公式）","tex":"\\text{氧化剂} + \\text{还原剂} \\longrightarrow \\text{还原产物} + \\text{氧化产物} \\implies \\begin{cases} \\text{氧化性：氧化剂} > \\text{氧化产物} \\\\ \\text{还原性：还原剂} > \\text{还原产物} \\end{cases}","plain":"自发反应中：氧化性 氧化剂 > 氧化产物；还原性 还原剂 > 还原产物","conditions":"常规正向自发进行的水溶液或热化学氧化还原反应（非强行电解/气体持续逸出拉动平衡）","pageRef":"化上 p.209","note":"注意是斜交叉配对：氧化剂比氧化产物，还原剂比还原产物。"},{"title":"同一元素不同价态氧化性与还原性对比（Fe 与 Cu 体系）","tex":"\\text{氧化性：}\\mathrm{Fe^{3+} > Cu^{2+} > Fe^{2+}},\\qquad \\text{还原性：}\\mathrm{Fe > Cu > Fe^{2+}}","plain":"氧化性 Fe³⁺ > Cu²⁺ > Fe²⁺；还原性 Fe > Cu > Fe²⁺","conditions":"由 Fe+Cu²⁺→Fe²⁺+Cu 与 2Fe³⁺+Cu→2Fe²⁺+Cu²⁺ 联合推导","pageRef":"化上 p.209","note":"故 FeCl₃ 溶液可以腐蚀印刷电路板上的金属铜，生成 CuCl₂ 和 FeCl₂。"}],"pitfalls":[{"title":"误以为“金属阳离子只具有氧化性”或“氧化剂降价越多氧化性就越强”","wrong":"“凡是金属阳离子都处于正价，所以只具有氧化性；且稀硝酸被还原成 NO（降 3 价）比浓硝酸被还原成 NO₂（降 1 价）氧化性更强。”","diagnosis":"第一句错在低价/中间价阳离子如 **\\(\\mathrm{Fe^{2+}}\\)、\\(\\mathrm{Cu^+}\\)、\\(\\mathrm{Sn^{2+}}\\)** 既能降价作氧化剂，又能继续升价（如 \\(\\mathrm{Fe^{2+}\\to Fe^{3+}}\\)）作还原剂（教材 p.210 思考题 8c(1) 判 ×！）；第二句错在氧化性强弱取决于**得电子的难易（反应剧烈程度/电位）**，与单个原子得电子数量无关（浓 HNO₃ 氧化性强于稀 HNO₃，就像 Na 只失 1 个电子比 Al 失 3 个电子还原性更强一样！）。","right":"金属阳离子不一定只有氧化性（\\(\\mathrm{Fe^{2+}}\\) 兼具氧化性与还原性）；强弱只看**得失电子难易程度**，不看转移电子个数。","checkRule":"看到“金属阳离子一定只具有氧化性”直接判错；看到“失电子越多还原性越强”直接判错！"},{"title":"比较氧化性强弱时，错把“氧化剂”和“还原剂”或“氧化产物”配错对","wrong":"“已知 \\(\\mathrm{Cl_2 + 2Fe^{2+} \\to 2Cl^- + 2Fe^{3+}}\\)，说明氧化性 \\(\\mathrm{Cl_2 > Fe^{2+}}\\)，或 \\(\\mathrm{Fe^{2+} > Fe^{3+}}\\)。”","diagnosis":"氧化性比较必须在“同类型能力（得电子能力）”间进行，\\(\\mathrm{Fe^{2+}}\\) 在此作还原剂！","right":"该反应中 \\(\\mathrm{Cl_2}\\) 是氧化剂、\\(\\mathrm{Fe^{3+}}\\) 是氧化产物 ⇒ 氧化性 **\\(\\mathrm{Cl_2 > Fe^{3+}}\\)**；\\(\\mathrm{Fe^{2+}}\\) 是还原剂、\\(\\mathrm{Cl^-}\\) 是还原产物 ⇒ 还原性 **\\(\\mathrm{Fe^{2+} > Cl^-}\\)**。","checkRule":"标出“氧、还、还产、氧产”四顶帽子后，严格按 `氧 > 氧产` 和 `还 > 还产` 写不等式。"},{"title":"忽略酸在反应中的“双重作用”（教材 p.216 第 4 题）","wrong":"“在 \\(\\mathrm{Cu + 2H_2SO_4}(\\text{浓}) \\xrightarrow{\\Delta} \\mathrm{CuSO_4 + SO_2\\uparrow + 2H_2O}\\) 中，\\(\\mathrm{H_2SO_4}\\) 全部作氧化剂。”","diagnosis":"2 mol \\(\\mathrm{H_2SO_4}\\) 中只有 1 mol 降价变成 \\(\\mathrm{SO_2}\\)（作氧化剂），另 1 mol S 仍是 +6 价进入 \\(\\mathrm{CuSO_4}\\)（表现酸性）。","right":"浓硫酸在该反应中**既表现氧化性，又表现酸性**；类似地，浓盐酸在 \\(\\mathrm{MnO_2 + 4HCl(\\text{浓}) \\to MnCl_2 + Cl_2\\uparrow + 2H_2O}\\) 中**既表现还原性，又表现酸性**。","checkRule":"只要产物中出现了对应酸根的盐（如 \\(\\mathrm{CuSO_4, MnCl_2, Cu(NO_3)_2}\\)），该酸就必同时表现了**酸性**！"}],"examples":[{"label":"例 8.3.1","tier":"L2","tierLabel":"L2 校内期末","title":"教材 p.208 活动 2 & p.215 第 9 题综合：金属还原性推理与黑火药反应分析","prompt":"(1)（活动 2，p.208）有四种金属 X、Y、Z、W，实验测得：① 碳分别与这四种金属的氧化物共热，只能从 X、W 的氧化物中把 X、W 还原出来；② 这四种金属中，常温下只有 Z 能与水反应放出氢气；③ 这四种金属中，Y、Z、W 能与稀盐酸反应放出氢气。请排出这四种金属单质**还原性由强到弱**的顺序。(2) 黑火药爆炸反应为：\\(\\mathrm{2KNO_3(s) + S(s) + 3C(s) \\longrightarrow K_2S(s) + N_2(g) + 3CO_2(g)}\\)，指出该反应的氧化剂、还原剂、氧化产物与还原产物，并计算生成 \\(1\\text{ mol }\\mathrm{N_2}\\) 时转移电子的物质的量。","clues":"与水常温反应最强(Z) > 置换稀酸(W, Y) > 不可置换稀酸(X)；且 C 能还原 W 而不能还原 Y 说明 Y > C > W！","strategy":"第(1)问用三步反应门槛把金属依次分段；第(2)问仔细标出 KNO₃(N+5→0)、S(0→−2)、C(0→+4) 的氧化数变化。","given":"金属 X, Y, Z, W 实验事实；黑火药爆炸方程式","principle":"还原性越强越易失电子（与水反应 > 置换酸 > 难被碳还原）。","steps":["(1) 由②常温与水反应只有 Z ⇒ **Z 最强**；由③能与稀盐酸置换 H₂ 的有 Y、Z、W ⇒ **X 最弱**（排在 H 之后）；在 Y 和 W 之间，由①碳能还原 W 的氧化物而不能还原 Y 的氧化物 ⇒ **Y 比 W 更活泼（更难被还原）**。综合排序：**\\(\\mathrm{Z > Y > W > X}\\)**（对应典型元素例如 Na > Al > Fe > Cu）。","(2) 黑火药中：N(+5→0，2 mol N 共得 \\(10\\text{ mol }e^-\\))，S(0→−2，1 mol S 得 \\(2\\text{ mol }e^-\\))，C(0→+4，3 mol C 共失 \\(12\\text{ mol }e^-\\))。","因此：**氧化剂**是 **\\(\\mathrm{KNO_3}\\) 和 \\(\\mathrm{S}\\)**（N 和 S 元素被还原），**还原剂**是 **\\(\\mathrm{C}\\)**；**氧化产物**是 **\\(\\mathrm{CO_2}\\)**，**还原产物**是 **\\(\\mathrm{N_2}\\) 和 \\(\\mathrm{K_2S}\\)**；每生成 \\(1\\text{ mol }\\mathrm{N_2}\\) 转移电子 **12 mol**。"],"answer":"(1) 还原性：Z > Y > W > X；(2) 氧化剂 KNO₃ 和 S，还原剂 C，氧化产物 CO₂，还原产物 N₂ 和 K₂S；转移 12 mol 电子。","markingPoints":["利用三个实验判据精准排出 Z > Y > W > X（2分）","识别黑火药有 2 种氧化剂（KNO₃, S）和 2 种还原产物（N₂, K₂S）（2分）","算得转移电子 12 mol（1分）"],"verification":"得电子 \\(2\\times 5 + 1\\times 2 = 12\\text{ mol}\\)，失电子 \\(3\\times 4 = 12\\text{ mol}\\)，完全守恒。","pitfall":"第(2)问极易只把 KNO₃ 当氧化剂而漏掉 S(0→−2) 也是氧化剂，并错算转移电子为 10 mol！"},{"label":"例 8.3.2","tier":"L4","tierLabel":"L4 统考压轴","title":"未知反应序列推理氧化还原强弱顺序与“强制弱”应用","prompt":"已知在常温水溶液中存在如下三个自发反应：\n① \\(\\mathrm{2Fe^{3+} + 2I^- \\longrightarrow 2Fe^{2+} + I_2}\\)\n② \\(\\mathrm{2Fe^{2+} + Br_2 \\longrightarrow 2Fe^{3+} + 2Br^-}\\)\n③ \\(\\mathrm{Cl_2 + 2Br^- \\longrightarrow 2Cl^- + Br_2}\\)\n(另参考：\\(\\mathrm{MnO_4^-}\\) 在酸性中可将 \\(\\mathrm{Cl^-}\\) 氧化为 \\(\\mathrm{Cl_2}\\)，而 \\(\\mathrm{Fe^{3+}}\\) 不能)。\n试回答：(1) 将 \\(\\mathrm{MnO_4^-\\,(H^+)}\\), \\(\\mathrm{Cl_2}\\), \\(\\mathrm{Br_2}\\), \\(\\mathrm{Fe^{3+}}\\), \\(\\mathrm{I_2}\\) 按**氧化性由强到弱**排序；(2) 将 \\(\\mathrm{Cl^-}\\), \\(\\mathrm{Br^-}\\), \\(\\mathrm{Fe^{2+}}\\), \\(\\mathrm{I^-}\\) 按**还原性由强到弱**排序；(3) 向同时含有等物质的量的 \\(\\mathrm{Fe^{2+}}\\) 和 \\(\\mathrm{I^-}\\) 的混合溶液中**逐滴**通入少量 \\(\\mathrm{Cl_2}\\) 时，哪种微粒会**最先**被 \\(\\mathrm{Cl_2}\\) 氧化？写出该优先反应的离子方程式；若向含有 \\(1\\text{ mol }\\mathrm{FeI_2}\\) 的溶液中通入 \\(1.2\\text{ mol }\\mathrm{Cl_2}\\)，写出反应后溶液中的离子及其物质的量。","clues":"利用“强氧化剂优先氧化最强的还原剂”原则：先找出还原性排序 I⁻ > Fe²⁺ > Br⁻ > Cl⁻！","strategy":"逐条写出“氧化剂>氧化产物”、“还原剂>还原产物”链条，再按定量 1.2 mol Cl₂ 分两步依次消耗 I⁻ 和 Fe²⁺。","given":"3 个水相氧化还原反应 + 1 mol FeI₂ + 1.2 mol Cl₂","principle":"强制弱链式推导；定量分步反应优先原则（强者先反应）。","steps":["(1) 氧化性链条：由 MnO₄⁻ 氧化 Cl⁻ 得 \\(\\mathrm{MnO_4^-(H^+) > Cl_2}\\)；由③得 \\(\\mathrm{Cl_2 > Br_2}\\)；由②得 \\(\\mathrm{Br_2 > Fe^{3+}}\\)；由①得 \\(\\mathrm{Fe^{3+} > I_2}\\)。总排序：**\\(\\mathrm{MnO_4^-(H^+) > Cl_2 > Br_2 > Fe^{3+} > I_2}\\)**。","(2) 还原性链条（或对偶反转）：由①得 \\(\\mathrm{I^- > Fe^{2+}}\\)；由②得 \\(\\mathrm{Fe^{2+} > Br^-}\\)；由③得 \\(\\mathrm{Br^- > Cl^-}\\)。总排序：**\\(\\mathrm{I^- > Fe^{2+} > Br^- > Cl^-}\\)**。","(3) 因还原性 \\(\\mathrm{I^- > Fe^{2+}}\\)，通入少量 \\(\\mathrm{Cl_2}\\) 时 **\\(\\mathrm{I^-}\\) 最先被氧化**：\\(\\mathrm{Cl_2 + 2I^- \\longrightarrow 2Cl^- + I_2}\\)。","定量计算（\\(1\\text{ mol }\\mathrm{FeI_2}\\) 含 \\(1\\text{ mol }\\mathrm{Fe^{2+}}\\) 与 \\(2\\text{ mol }\\mathrm{I^-}\\)）：","- 第一步：\\(2\\text{ mol }\\mathrm{I^-}\\) 全部被氧化耗去 \\(1.0\\text{ mol }\\mathrm{Cl_2}\\)，生成 \\(2.0\\text{ mol }\\mathrm{Cl^-}\\) 和 \\(1.0\\text{ mol }\\mathrm{I_2}\\)；","- 第二步：剩余 \\(1.2 - 1.0 = 0.2\\text{ mol }\\mathrm{Cl_2}\\) 继续氧化 \\(\\mathrm{Fe^{2+}}\\)（\\(\\mathrm{Cl_2 + 2Fe^{2+} \\to 2Cl^- + 2Fe^{3+}}\\)），消耗 \\(0.4\\text{ mol }\\mathrm{Fe^{2+}}\\)，生成 \\(0.4\\text{ mol }\\mathrm{Fe^{3+}}\\) 与 \\(0.4\\text{ mol }\\mathrm{Cl^-}\\)。","最终溶液中阳/阴离子：\\(\\mathrm{Fe^{2+}}\\) 剩 **0.6 mol**，\\(\\mathrm{Fe^{3+}}\\) 生成 **0.4 mol**，\\(\\mathrm{Cl^-}\\) 共 **2.4 mol**（\\(\\mathrm{I^-}\\) 耗尽为 0）。"],"answer":"(1) MnO₄⁻(H⁺) > Cl₂ > Br₂ > Fe³⁺ > I₂；(2) I⁻ > Fe²⁺ > Br⁻ > Cl⁻；(3) I⁻ 最先被氧化（Cl₂+2I⁻→2Cl⁻+I₂）；最终离子：Fe²⁺ 0.6 mol, Fe³⁺ 0.4 mol, Cl⁻ 2.4 mol。","markingPoints":["正确排定氧化性与还原性两条完整序列（2分）","指明 I⁻ 优先被氧化并写出离子方程式（1分）","分步算出 1.0 mol Cl₂ 先耗尽 I⁻，余 0.2 mol Cl₂ 氧化 0.4 mol Fe²⁺ 得最终离子量（2分）"],"verification":"电荷守恒验算：正电荷 \\(0.6\\times 2 + 0.4\\times 3 = 2.4\\text{ mol}\\)，负电荷 \\(2.4\\times 1 = 2.4\\text{ mol}\\)，完全平衡！","pitfall":"误认为 Cl₂ 同时按比例氧化 Fe²⁺ 和 I⁻（实际由于 \\(\\mathrm{Fe^{3+}}\\) 会立刻把残留 \\(\\mathrm{I^-}\\) 氧化回 \\(\\mathrm{Fe^{2+}}\\)，所以逻辑上等价于 \\(\\mathrm{I^-}\\) 彻底耗尽后才净产生 \\(\\mathrm{Fe^{3+}}\\)）。"}],"practice":[{"id":"chem8-8.3-q1","tier":"L1","tierLabel":"L1 基础","examStyle":"P1 选择","q":"（教材 p.215 第 5 题）农药波尔多液不能用铁制容器盛放，是因为铁能与该农药中的硫酸铜(II)反应：\\(\\mathrm{Fe + CuSO_4 \\to FeSO_4 + Cu}\\)。在该反应中，铁（　）。","options":["A. 是氧化剂","B. 是还原剂","C. 氧化数降低","D. 被还原"],"correctOption":"B","given":"Fe(0) + CuSO₄(+2) → FeSO₄(+2) + Cu(0)","method":"标出氧化数升降，套用口诀“升失氧还剂”","principle":"Fe 氧化数由 0 升至 +2，失电子被氧化，作还原剂。","steps":["Fe 氧化数升高、失去电子、自身被氧化，因此铁是还原剂（CuSO₄ 是氧化剂）。"],"ans":"B","markingPoints":["熟练辨认还原剂"],"verification":"化上 p.215 原题。","pitfall":"把“还原剂”与“被还原”混淆而错选 D。"},{"id":"chem8-8.3-q2","tier":"L2","tierLabel":"L2 期末","examStyle":"P1 选择","q":"（教材 p.215 第 8 题）下列各微粒的转化过程，**必须**加入适当的**氧化剂**才能实现的是（　）。","options":["A. PCl₃ → PCl₅","B. MnO₂ → Mn²⁺","C. SO₂ → SO₃²⁻","D. Fe₂O₃ → Fe"],"correctOption":"A","given":"四种元素转化方向","method":"加氧化剂 ⇒ 自身必须作还原剂 ⇒ 自身氧化数必须**升高**！","principle":"需要加氧化剂实现的转化，目标元素氧化数必然升高（排除自身分解）。","steps":["A. P 从 +3 升至 +5（升高，需加如 Cl₂ 等氧化剂）；","B. Mn 从 +4 降至 +2（降低，需加还原剂）；","C. S 始终为 +4（不变，只需加碱或水，非氧化还原）；","D. Fe 从 +3 降至 0（降低，需加 CO/C 等还原剂）。"],"ans":"A","markingPoints":["将“需加氧化剂”精确翻译为“自身氧化数升高”"],"verification":"化上 p.215 原题。","pitfall":"看到 B 或 D 涉及著名氧化剂 MnO₂ 就瞎选，或者忘了 SO₂ → SO₃²⁻ 化合价没变。"},{"id":"chem8-8.3-q3","tier":"L2","tierLabel":"L2 期末","examStyle":"P2 简答","q":"（改编自教材 p.216 第 3 & 4 题）(1) 在微粒 \\(\\mathrm{Fe^{2+}, Fe^{3+}, Mg^{2+}, S, I^-, H^+}\\) 中，指出**只有氧化性**的有哪些、**只有还原性**的有哪些、**既有氧化性又有还原性**的有哪些？(2) 分析下列两个反应中酸所起的作用（酸性 / 氧化性 / 还原性）：\n- ① \\(\\mathrm{MnO_2(s) + 4HCl}(\\mathrm{aq},\\text{浓}) \\xrightarrow{\\Delta} \\mathrm{MnCl_2(aq) + Cl_2(g) + 2H_2O(l)}\\)\n- ② \\(\\mathrm{H_2S(g) + H_2SO_4}(\\mathrm{aq},\\text{浓}) \\longrightarrow \\mathrm{S(s) + SO_2(g) + 2H_2O(l)}\\)","given":"6 种微粒；浓 HCl 与浓 H₂SO₄ 的两个反应","method":"按元素最高/中间/最低氧化数归类微粒；检查反应后酸根元素是否部分或全部变价","principle":"最高价仅氧化性，最低价仅还原性，中间价兼具；形成盐则显酸性，降价显氧化性，升价显还原性。","steps":["(1) **只有氧化性**（最高价态）：\\(\\mathrm{Fe^{3+}}\\)（Fe 最高常见稳价）、\\(\\mathrm{Mg^{2+}}\\)（+2 最高价）、\\(\\mathrm{H^+}\\)（+1 最高价）；**只有还原性**（最低价态）：\\(\\mathrm{I^-}\\)（−1 最低价）；**既有氧化性又有还原性**（中间价态）：\\(\\mathrm{Fe^{2+}}\\)（可升至+3或降至0）、\\(\\mathrm{S}\\)（可升至+4/+6或降至−2）。","(2) 反应①中，4 mol HCl 有 2 mol Cl⁻ 升价成 \\(\\mathrm{Cl_2}\\)（显**还原性**），另 2 mol Cl⁻ 价态不变生成 \\(\\mathrm{MnCl_2}\\)（显**酸性**）；反应②中，\\(\\mathrm{H_2SO_4}\\) 中 S 全部由 +6 降至 +4 生成 \\(\\mathrm{SO_2}\\)（未生成任何硫酸盐！），故**只表现氧化性**（不表现酸性）。"],"ans":"(1) 只氧化性：Fe³⁺, Mg²⁺, H⁺；只还原性：I⁻；兼具：Fe²⁺, S；(2) ① HCl 兼具还原性与酸性；② H₂SO₄ 只表现氧化性。","markingPoints":["准确将 6 种微粒归入三大价态属性（3分）","区分 ① 兼显还原性与酸性、② 无硫酸盐生成故只显氧化性（2分）"],"verification":"化上 p.216 第 3 & 4 题原题核对。","pitfall":"第(2)②误以为浓硫酸只要参加反应就一定也显酸性。"},{"id":"chem8-8.3-q4","tier":"L3","tierLabel":"L3 预试","examStyle":"P1 选择","q":"（教材 p.215 第 6 题）氢化钠（\\(\\mathrm{NaH}\\)）是一种储氢材料，与水反应的化学方程式为 \\(\\mathrm{NaH(s) + H_2O(l) \\longrightarrow NaOH(aq) + H_2(g)}\\)。在该反应中，水（　）。","options":["A. 是氧化剂","B. 是还原剂","C. 既是氧化剂，又是还原剂","D. 既不是氧化剂，也不是还原剂"],"correctOption":"A","given":"NaH + H₂O → NaOH + H₂","method":"注意 NaH 中 H 是 −1 价，H₂O 中 H 是 +1 价，两者发生归中反应！","principle":"NaH(H=−1→0) 失电子作还原剂；H₂O(H=+1→0) 得电子作氧化剂。","steps":["\\(\\mathrm{NaH}\\) 中 Na 为 +1，H 为 **−1**；反应后归中生成 0 价 \\(\\mathrm{H_2}\\)（其中一半 H 来自 NaH 升至 0，一半 H 来自 \\(\\mathrm{H_2O}\\) 降至 0）。水中氧（−2）和钠（+1）均不变价，故水只得电子作**氧化剂**。"],"ans":"A","markingPoints":["准确识别归中反应中水只降价作氧化剂"],"verification":"化上 p.215 原题。","pitfall":"未识出 NaH 中 H 是 −1 价，或受 2Na + 2H₂O 干扰乱选。"},{"id":"chem8-8.3-q5","tier":"L4","tierLabel":"L4 统考拔高","examStyle":"P1 选择","q":"（教材 p.210 思考题 8c 第 2 题改编）航天飞船常用肼（\\(\\mathrm{N_2H_4}\\)）与四氧化二氮（\\(\\mathrm{N_2O_4}\\)）作推进剂，反应如下：\\(\\mathrm{2N_2H_4(g) + N_2O_4(g) \\longrightarrow 3N_2(g) + 4H_2O(g)}\\)。关于该反应，下列说法正确的是（　）。","options":["A. 该反应属于置换反应，N₂H₄ 是氧化剂","B. N₂O₄ 中的氮元素被氧化，N₂H₄ 中的氮元素被还原","C. N₂ 既是氧化产物，又是还原产物，且氧化产物与还原产物的物质的量之比为 2 : 1","D. 每生成 3 mol N₂ 共有 12 mol 电子发生转移"],"correctOption":"C","given":"2N₂H₄ + N₂O₄ → 3N₂ + 4H₂O","method":"计算两反应物中 N 的氧化数，按归中规律统计氧化/还原产物比例与电子转移","principle":"N₂H₄ 中 N(−2→0) 失电子；N₂O₄ 中 N(+4→0) 得电子。","steps":["\\(\\mathrm{2N_2H_4}\\) 中共 4 mol N 从 −2 升至 0（失 \\(4\\times 2 = 8\\text{ mol }e^-\\)，作**还原剂**，生成 **2 mol N₂** 氧化产物）；","\\(\\mathrm{N_2O_4}\\) 中共 2 mol N 从 +4 降至 0（得 \\(2\\times 4 = 8\\text{ mol }e^-\\)，作**氧化剂**，生成 **1 mol N₂** 还原产物）。","因此：A 错（非置换且 N₂H₄ 是还原剂）；B 错（反了）；C 对（氧化产物 2 mol N₂ : 还原产物 1 mol N₂ = **2 : 1**）；D 错（共转移 **8 mol** 电子而非 12 mol）。"],"ans":"C","markingPoints":["精确求解归中反应氧化产物与还原产物比例 2:1 及转移 8 mol e⁻"],"verification":"化上 p.210 思考题 8c 第 2 题原型扩展。","pitfall":"误算成转移 12 mol e⁻ 或把 2:1 弄反成 1:2。"}],"cheatSheet":["角色对应：**氧化剂**（降价/得 e⁻/被还原）→ **还原产物**；**还原剂**（升价/失 e⁻/被氧化）→ **氧化产物**。","价态口诀：**最高只氧化、最低只还原、中间兼具**（如 \\(\\mathrm{Fe^{2+}, S, SO_2, H_2O_2}\\)）。","强弱四大比法：活动性顺序（\\(\\mathrm{F_2>Cl_2>Br_2>I_2>S}\\)，阴离子相反）；**强制弱**（\\(\\text{氧化剂}>\\text{氧化产物}\\)）；条件越温和剂越强（浓 \\(\\mathrm{HNO_3}\\) 常温氧化 Cu > 浓 \\(\\mathrm{H_2SO_4}\\) 加热）。"],"kbEntryIds":["kb-chem8-oxidant-reductant"],"quiz":{"q":"在反应 \\(\\mathrm{3S(s) + 6KOH(aq) \\longrightarrow 2K_2S(aq) + K_2SO_3(aq) + 3H_2O(l)}\\)（p.215 第 10 题）中，**被氧化**与**被还原**的硫原子数之比是多少？","given":"3S(0) → 2K₂S(−2) + K₂SO₃(+4)","method":"直接数生成物中升价 S(+4) 与降价 S(−2) 的原子个数","principle":"电子守恒（1×4 = 2×2）直接决定比例。","steps":["1 个 S 原子升至 +4（进入 \\(\\mathrm{K_2SO_3}\\)，被氧化）；2 个 S 原子降至 −2（进入 \\(\\mathrm{2K_2S}\\)，被还原）。"],"ans":"\\(1 : 2\\)（注意审题顺序是“被氧化 : 被还原”）"}},{"id":"8.4","t":"氧化还原反应方程式的配平","anchor":{"pages":"化上 p.210–213","syllabus":"1.6.4 氧化数法与离子—电子法配平（含酸性与碱性介质）","examScopes":["sem1_final","pre_exam","sem2_final","uec"],"examWeight":"P2 必考手写配平计算核心（氧化数法 + 离子—电子法）","terms":"oxidation number method · ion-electron method · half-reaction · acidic/basic medium","prerequisites":["氧化数计算规则与化学计量守恒（8.2）","离子方程式拆写（强酸、强碱、可溶盐拆为离子，Ch 4 & Ch 23）"],"goals":["熟练使用“氧化数法”四步规程配平全分子形式氧化还原方程式（含部分显酸性反应与歧化反应）。","熟练掌握“离子—电子法”五步规程，并能在酸性（H⁺/H₂O）和碱性（OH⁻/H₂O）不同介质中正确配平氧氢原子与电荷。","能够逆向运用离子—电子法或电子守恒解决未知产物氧化数推断题（教材 p.215 第 11 题 & p.213 思考题 8d(4)）。"]},"concepts":[{"kind":"mechanism","title":"8.4.1 氧化数法配平四步规程（p.211 示例：FeCl₃ + H₂S）","pageRef":"化上 p.211","body":["原理：所有氧化还原反应都严格遵守**氧化数升高总数 = 氧化数降低总数**（即电子得失相等）。","**教材四步规程（以 \\(\\mathrm{FeCl_3(aq) + H_2S(g) \\to FeCl_2(aq) + HCl(aq) + S(s)}\\) 为例）**：","- **① 标数**：标出变价元素反应前后氧化数（\\(\\mathrm{Fe}: +3 \\to +2\\)；\\(\\mathrm{S}: -2 \\to 0\\)）。","- **② 求升降**：算出每个结构单元的升降数值（Fe 降低 \\(1\\)，S 升高 \\(2\\)）。","- **③ 取最小公倍数配主干**：\\(\\mathrm{LCM}(1, 2) = 2\\)，故给降价的 \\(\\mathrm{FeCl_3}\\) 配系数 \\(2\\)（\\(1\\times 2\\)），给升价的 \\(\\mathrm{H_2S}\\) 配系数 \\(1\\)（\\(2\\times 1\\)），相应产物 \\(\\mathrm{FeCl_2}\\) 为 \\(2\\)、\\(\\mathrm{S}\\) 为 \\(1\\)。","- **④ 观察法配其余**：由质量守恒，左 6 个 Cl、右 \\(\\mathrm{2FeCl_2}\\) 仅占 4 个 Cl，故 \\(\\mathrm{HCl}\\) 系数为 **2**（同时右 2 个 H 恰好与左 \\(\\mathrm{1H_2S}\\) 守恒！）。最终：\\(\\mathrm{2FeCl_3(aq) + H_2S(g) \\longrightarrow 2FeCl_2(aq) + 2HCl(aq) + S(s)}\\)。"],"takeaway":"遇到**歧化反应**（同一物既升又降，如 \\(\\mathrm{S + KOH \\to K_2S + K_2SO_3 + H_2O}\\)）或**多原子单元**（如 \\(\\mathrm{K_2Cr_2O_7}\\) 含 2 个 Cr），第②步务必以**整分子/产物端变价原子数**作基准配系数，然后再加合左端系数！"},{"kind":"mechanism","title":"8.4.2 离子—电子法配平五步规程（酸性介质规则，p.212–213）","pageRef":"化上 p.212–213","body":["原理：将氧化还原离子反应拆成氧化半反应与还原半反应，先按介质补原子、再补电子配电荷，最后令得失电子数相等相加。","**教材五步规程（以酸性条件下 \\(\\mathrm{KMnO_4 + HCl}\\) 为例，p.212–213）**：","- **① 写离子框**：删去未参加反应的旁观离子（\\(\\mathrm{K^+}\\)），得框架 \\(\\mathrm{MnO_4^- + Cl^- \\to Mn^{2+} + Cl_2}\\)。","- **② 拆半反应并配原子（关键规则！）**：先配变价主原子（如 Cl 配 \\(2\\mathrm{Cl^- \\to Cl_2}\\)），再用介质粒子配 O 和 H——**酸性溶液中缺几个 O 就加几个 \\(\\mathrm{H_2O}\\)，缺几个 H 就加几个 \\(\\mathrm{H^+}\\)**：\n还原半反应：\\(\\mathrm{MnO_4^-(aq) + 8H^+(aq) \\longrightarrow Mn^{2+}(aq) + 4H_2O(l)}\\)；\n氧化半反应：\\(\\mathrm{2Cl^-(aq) \\longrightarrow Cl_2(g)}\\)。","- **③ 加电子 \\(\\mathrm{e^-}\\) 配平电荷**：左 +7 右 +2 ⇒ 还原半反应加 \\(5\\mathrm{e^-}\\)；左 −2 右 0 ⇒ 氧化半反应加 \\(2\\mathrm{e^-}\\)。","- **④ 倍数叠加消去 \\(\\mathrm{e^-}\\)**：\\(\\mathrm{LCM}(5, 2) = 10\\)，还原式 \\(\\times 2\\) + 氧化式 \\(\\times 5\\)，消去 \\(10\\mathrm{e^-}\\) 得净离子方程式：\\(\\mathrm{2MnO_4^-(aq) + 16H^+(aq) + 10Cl^-(aq) \\longrightarrow 2Mn^{2+}(aq) + 5Cl_2(g) + 8H_2O(l)}\\)。","- **⑤ 补回旁观离子**：16 个 HCl 提供 16 个 Cl⁻（10 个变 \\(\\mathrm{Cl_2}\\)，4 个配 2Mn²⁺，2 个配 2K⁺），得完整化学方程式：\\(\\mathrm{2KMnO_4(s) + 16HCl(aq) \\longrightarrow 2MnCl_2(aq) + 2KCl(aq) + 5Cl_2(g) + 8H_2O(l)}\\)。"],"takeaway":"离子—电子法比氧化数法更稳妥的地方在于：**它能自动帮你算出究竟需要几个 \\(\\mathrm{H^+}\\) 和几份 \\(\\mathrm{H_2O}\\)**，无需肉眼死凑！"},{"kind":"table","title":"酸性溶液 vs 碱性溶液“配 O 和 H”原子配平规则对照","pageRef":"化上 p.212、p.213 思考题 8d(4)","body":["教材 p.212 明确写出：“酸性溶液用 \\(\\mathrm{H^+, H_2O}\\)，碱性溶液用 \\(\\mathrm{OH^-, H_2O}\\)，配 O 用 \\(\\mathrm{H_2O}\\)，配 H 用 \\(\\mathrm{H^+}\\)”。碱性介质配平提供两种零失误方法："],"table":{"headers":["溶液介质","可用配平微粒","半反应原子配平实操口诀","典型示例（半反应）"],"rows":[["酸性溶液","H⁺、H₂O","缺 n 个 O ⇒ 在缺 O 侧加 n 个 H₂O；再在另一侧加 2n 个 H⁺","MnO₄⁻ + 8H⁺ + 5e⁻ → Mn²⁺ + 4H₂O"],["碱性溶液（直接法）","OH⁻、H₂O","多 n 个 O ⇒ 在**多 O 侧**加 n 个 H₂O，在另一侧加 2n 个 OH⁻","MnO₄⁻ + 2H₂O + 3e⁻ → MnO₂↓ + 4OH⁻"],["碱性溶液（先酸后碱法——强烈推荐！）","先借 H⁺/H₂O 再加 OH⁻ 中和","先按酸性规则配出 m 个 H⁺，然后方程式左右两边**同时加上 m 个 OH⁻**（把 H⁺+OH⁻ 合并为 H₂O 并约简两侧水）","如 ClO⁻ + 2H⁺ + 2e⁻ → Cl⁻ + H₂O；两边各加 2OH⁻ 得：ClO⁻ + H₂O + 2e⁻ → Cl⁻ + 2OH⁻"]]},"takeaway":"考试中最不容易错的方法是 **“碱性先酸后碱法”**（假装在酸中配好半反应，再在两边同加与 \\(\\mathrm{H^+}\\) 等量的 \\(\\mathrm{OH^-}\\) 变成水后对消），100% 不会写反 \\(\\mathrm{OH^-}\\) 和 \\(\\mathrm{H_2O}\\) 的方向！"}],"formulas":[{"title":"氧化还原计量与电子守恒通用方程","tex":"n_{\\text{氧化剂}} \\times |\\Delta\\mathrm{ON}_{\\text{降}}| = n_{\\text{还原剂}} \\times |\\Delta\\mathrm{ON}_{\\text{升}}| = n_{e^-}","plain":"n(氧化剂) × 每mol得电子数 = n(还原剂) × 每mol失电子数 = 转移电子总物质的量","conditions":"用于未知产物氧化数计算（如教材 p.215 第 11 题、p.213 思考题 8d(4)）","pageRef":"化上 p.211–215","note":"已知两剂摩尔比即可一步解出降价或升价幅度。"},{"title":"双守恒检验准则（离子方程式终审）","tex":"\\sum m_{\\text{左原子}} = \\sum m_{\\text{右原子}},\\qquad \\sum q_{\\text{左电荷}} = \\sum q_{\\text{右电荷}}","plain":"左右两侧每种元素原子个数相等 AND 左右两侧离子总电荷代数和相等","conditions":"所有配平好的离子方程式必过这两关","pageRef":"化上 p.212–213","note":"只要电荷不平，化学计量系数必定错了，立刻回溯检查半反应电子数。"}],"pitfalls":[{"title":"在碱性介质离子方程式里误留下 H⁺，或忘记还原“部分显酸性”的酸分子数","wrong":"“碱性中 \\(\\mathrm{Cl_2 + 2OH^- \\to Cl^- + ClO^- + 2H^+}\\)”；或把 \\(\\mathrm{KMnO_4 + HCl}\\) 中浓盐酸系数只填 10（只算被氧化的 \\(\\mathrm{Cl^-}\\)）。","diagnosis":"碱性水溶液中 \\(\\mathrm{H^+}\\) 与 \\(\\mathrm{OH^-}\\) 不能大量共存；而写全化学方程式时，盐中的阴离子（\\(\\mathrm{KCl, MnCl_2}\\)）也全来自 \\(\\mathrm{HCl}\\)。","right":"碱性介质只能出现 \\(\\mathrm{OH^-}\\) 和 \\(\\mathrm{H_2O}\\)（如 \\(\\mathrm{Cl_2 + 2OH^- \\to Cl^- + ClO^- + H_2O}\\)）；配平 \\(\\mathrm{2KMnO_4 + 16HCl}\\) 时必将 10 个变价 Cl 与 6 个成盐 Cl 合并为 **16** 个 HCl。","checkRule":"还原全分子方程式前，先配金属阳离子生成盐的数量，再把非变价酸根与变价酸根相加！"},{"title":"忽略化学式自带的“下标”（如 Cr₂O₇²⁻ 含 2 个 Cr、C₂O₄²⁻ 含 2 个 C）导致升降算漏一半","wrong":"“在 \\(\\mathrm{Cr_2O_7^{2-} + H_2O_2 \\to Cr^{3+} + O_2}\\) 中，Cr 从 +6 降至 +3 变化 3，O 从 −1 升至 0 变化 1，于是取比 1:3。”","diagnosis":"1 个 \\(\\mathrm{Cr_2O_7^{2-}}\\) 含 **2 个** Cr 原子（降 \\(2\\times 3 = 6\\)），而 1 个 \\(\\mathrm{H_2O_2}\\) 含 **2 个** O 原子（升 \\(2\\times 1 = 2\\)），整体升降比是 6 : 2 = 3 : 1，恰好搞反了倍数！","right":"半反应一定要先配主原子：\\(\\mathrm{Cr_2O_7^{2-} + 14H^+ + 6e^- \\to 2Cr^{3+} + 7H_2O}\\) 与 \\(\\mathrm{H_2O_2 \\to O_2\\uparrow + 2H^+ + 2e^-}\\) ⇒ 1 mol \\(\\mathrm{Cr_2O_7^{2-}}\\) 配 **3 mol** \\(\\mathrm{H_2O_2}\\)。","checkRule":"用**离子—电子法拆半反应并先配平变价主原子个数**，绝不会犯“漏下标”的错！"}],"examples":[{"label":"例 8.4.1","tier":"L2","tierLabel":"L2 校内期末","title":"教材 p.212–213 & p.216 第 5 题精选：酸性介质离子—电子法标准配平","prompt":"用**离子—电子法**详细配平下列两个在酸性溶液中进行的重要反应（写出氧化半反应、还原半反应及配平后的总离子方程式）：\n(1)（p.213 问题解决(1)）\\(\\mathrm{MnO_4^-(aq) + SO_2(g) \\longrightarrow Mn^{2+}(aq) + SO_4^{2-}(aq)}\\)\n(2)（p.216 第 5(1) 题）\\(\\mathrm{MnO_4^-(aq) + C_2O_4^{2-}(aq) + H^+(aq) \\longrightarrow Mn^{2+}(aq) + CO_2(g) + H_2O(l)}\\)","clues":"注意第(2)问 C₂O₄²⁻ 有 2 个 C（+3→+4，每个草酸根失 2e⁻）！配 O 用 H₂O，配 H 用 H⁺。","strategy":"严格按照半反应法五步流程：拆半反应 → 配主原子 → 配 O(H₂O) 和 H(H⁺) → 配电荷(e⁻) → 倍数叠加。","given":"酸性水溶液中 MnO₄⁻ 氧化 SO₂ 与 C₂O₄²⁻","principle":"酸性介质以 H₂O 配氧、H⁺ 配氢；原子与电荷双守恒。","steps":["第(1)题 \\(\\mathrm{MnO_4^- + SO_2}\\)：","- 还原半反应：\\(\\mathrm{MnO_4^- + 8H^+ + 5e^- \\longrightarrow Mn^{2+} + 4H_2O}\\)；","- 氧化半反应：\\(\\mathrm{SO_2 + 2H_2O \\longrightarrow SO_4^{2-} + 4H^+ + 2e^-}\\)；","- 最小公倍数 10：还原式 \\(\\times 2\\) + 氧化式 \\(\\times 5\\)，合并消去两侧共有的 \\(10\\mathrm{e^-}\\)、\\(8\\mathrm{H_2O}\\) 和 \\(16\\mathrm{H^+}\\) 得：\n**\\(\\mathrm{2MnO_4^-(aq) + 5SO_2(g) + 2H_2O(l) \\longrightarrow 2Mn^{2+}(aq) + 5SO_4^{2-}(aq) + 4H^+(aq)}\\)**。","第(2)题 \\(\\mathrm{MnO_4^- + C_2O_4^{2-}}\\)（经典高锰酸钾滴定草酸反应）：","- 还原半反应：\\(\\mathrm{MnO_4^- + 8H^+ + 5e^- \\longrightarrow Mn^{2+} + 4H_2O}\\)；","- 氧化半反应：先配 C 得 \\(\\mathrm{C_2O_4^{2-} \\longrightarrow 2CO_2}\\)，检查 O 已平，加电荷 \\(\\mathrm{C_2O_4^{2-} \\longrightarrow 2CO_2 + 2e^-}\\)；","- 还原式 \\(\\times 2\\) + 氧化式 \\(\\times 5\\) 消去 \\(10\\mathrm{e^-}\\) 得：\n**\\(\\mathrm{2MnO_4^-(aq) + 5C_2O_4^{2-}(aq) + 16H^+(aq) \\longrightarrow 2Mn^{2+}(aq) + 10CO_2(g) + 8H_2O(l)}\\)**。"],"answer":"(1) 2MnO₄⁻ + 5SO₂ + 2H₂O → 2Mn²⁺ + 5SO₄²⁻ + 4H⁺；(2) 2MnO₄⁻ + 5C₂O₄²⁻ + 16H⁺ → 2Mn²⁺ + 10CO₂ + 8H₂O。","markingPoints":["正确写出两组氧化与还原半反应并配平电荷（3分）","正确约简两侧同有的 H⁺ 与 H₂O 并核准双守恒（2分）"],"verification":"电荷检验：(1) 左 −2，右 +4 −10 +4 = −2；(2) 左 −2 −10 +16 = +4，右 +4，全部完美平衡。","pitfall":"第(1)问把 SO₂ 这侧的 H₂O 和 H⁺ 放在反应物里配不出来（其实是左边消耗 2H₂O，右边净生成 4H⁺）。"},{"label":"例 8.4.2","tier":"L4","tierLabel":"L4 统考压轴","title":"教材 p.213 思考题 8d(4) & p.215 第 11 题：碱性介质反应式推断与电子守恒定未知氧化数","prompt":"(1)（思考题 8d 第(4)题）在氢氧化钠（碱性）环境下氯气（\\(\\mathrm{Cl_2}\\)）与碘化钠（\\(\\mathrm{NaI}\\)）反应，已知**每 \\(1\\text{ mol }\\mathrm{NaI}\\) 完全反应转移 \\(6\\text{ mol}\\) 电子**。试先确定含碘产物的化学式，再用离子—电子法写出并配平该反应的离子方程式与化学方程式。(2)（p.215 第 11 题）当水溶液中 \\(\\mathrm{XO_4^-}\\) 与 \\(\\mathrm{H_2O_2}\\)（反应后生成 \\(\\mathrm{O_2}\\)）的微粒数目之比恰好为 **\\(2 : 5\\)** 时恰好完全反应，则被还原后 X 元素的氧化数变为多少？","clues":"1 mol I⁻(−1) 失去 6 mol e⁻ ⇒ I 氧化数变为 −1 + 6 = +5（IO₃⁻ 碘酸根！）；第(2)问 1 mol H₂O₂ 变 O₂ 失 2 mol e⁻。","strategy":"先由转移电子数定出变价终态氧化数，再用“先酸后碱法”或“直接法”配平碱性介质。","given":"(1) NaI(−1) + Cl₂(0) in NaOH, 6e⁻/NaI；(2) n(XO₄⁻):n(H₂O₂) = 2:5","principle":"氧化还原电子得失守恒方程；碱性溶液半反应配平（OH⁻/H₂O）。","steps":["(1) \\(\\mathrm{I^-}\\) 中 I 初始氧化数为 \\(-1\\)，失 \\(6\\) 个电子后氧化数变为 \\(-1 + 6 = +5\\)，在碱性溶液中形成碘酸根 **\\(\\mathrm{IO_3^-}\\)**（即 \\(\\mathrm{NaIO_3}\\)）；而 \\(\\mathrm{Cl_2}\\) 得电子被还原为 \\(\\mathrm{Cl^-}\\)。","写半反应（“先酸后碱”稳妥法）：\n- 氧化半反应：先按酸液写 \\(\\mathrm{I^- + 3H_2O \\to IO_3^- + 6H^+ + 6e^-}\\)，两边同加 \\(6\\mathrm{OH^-}\\) 得 **\\(\\mathrm{I^- + 6OH^- \\longrightarrow IO_3^- + 3H_2O + 6e^-}\\)**；\n- 还原半反应：\\(\\mathrm{Cl_2 + 2e^- \\longrightarrow 2Cl^-}\\)。","将还原式 \\(\\times 3\\) 与氧化式相加消去 \\(6\\mathrm{e^-}\\) 得离子方程式：\n**\\(\\mathrm{3Cl_2(g) + I^-(aq) + 6OH^-(aq) \\longrightarrow 6Cl^-(aq) + IO_3^-(aq) + 3H_2O(l)}\\)**。","补回旁观离子 \\(\\mathrm{Na^+}\\) 得化学方程式：**\\(\\mathrm{3Cl_2(g) + NaI(aq) + 6NaOH(aq) \\longrightarrow 6NaCl(aq) + NaIO_3(aq) + 3H_2O(l)}\\)**。","(2) \\(\\mathrm{XO_4^-}\\) 中设 X 原氧化数为 \\(+x\\)，由 \\(x + 4(-2) = -1\\) 得 \\(x = +7\\)。\\(\\mathrm{H_2O_2}\\) 作还原剂变为 \\(\\mathrm{O_2}\\)，每个 \\(\\mathrm{H_2O_2}\\) 中 2 个 O 从 −1 升至 0，共失 **2 个**电子。设每个 X 降低 \\(\\Delta\\)，依电子守恒：\\(2 \\times \\Delta = 5 \\times 2 \\implies \\Delta = 5\\)。因此还原后 X 的氧化数变为 \\(+7 - 5 = \\mathbf{+2}\\)（例如 \\(\\mathrm{MnO_4^- \\to Mn^{2+}}\\)！）。"],"answer":"(1) 离子式：3Cl₂ + I⁻ + 6OH⁻ → 6Cl⁻ + IO₃⁻ + 3H₂O；化学式：3Cl₂ + NaI + 6NaOH → 6NaCl + NaIO₃ + 3H₂O；(2) +2。","markingPoints":["推出 I 变为 +5 价（IO₃⁻）（1分）","正确在碱性介质用 OH⁻/H₂O 配平离子式与化学式（3分）","利用 2×Δ = 5×2 求得 X 终态氧化数为 +2（2分）"],"verification":"电荷守恒检验：左 −1 − 6 = −7，右 −6 − 1 = −7；(2) 即 2MnO₄⁻ + 5H₂O₂ + 6H⁺ → 2Mn²⁺ + 5O₂↑ + 8H₂O。","pitfall":"第(1)问错以为生成 I₂（只失 1 个电子）而没看清“转移 6 mol 电子”这一关键条件；第(2)问把 H₂O₂ 误当成每分子只失 1e⁻（漏掉下标 2）。"}],"practice":[{"id":"chem8-8.4-q1","tier":"L1","tierLabel":"L1 基础","examStyle":"P1 选择","q":"用氧化数法配平化学方程式：\\(a\\,\\mathrm{Cu} + b\\,\\mathrm{HNO_3}(\\text{稀}) \\longrightarrow c\\,\\mathrm{Cu(NO_3)_2} + d\\,\\mathrm{NO}\\uparrow + e\\,\\mathrm{H_2O}\\)，配平后最小整数化学计量数 \\(a, b, d\\) 依次为（　）。","options":["A. 3, 8, 2","B. 3, 6, 2","C. 1, 4, 2","D. 2, 6, 3"],"correctOption":"A","given":"Cu(0→+2) + HNO₃(+5→+2) → Cu(NO₃)₂ + NO + H₂O","method":"最小公倍数法配 Cu 与 NO，再加未变价硝酸根得 HNO₃ 总系数","principle":"Cu 升 2，N 降 3，LCM(2,3)=6。","steps":["Cu 系数 \\(a=3\\)（共升 6），NO 系数 \\(d=2\\)（共降 6），故 \\(c=3\\)。","右侧总 N 原子数 \\(= 3\\times 2 + 2 = 8\\)，故 \\(b=8\\)，\\(e=4\\)。方程式为 \\(\\mathrm{3Cu + 8HNO_3 \\to 3Cu(NO_3)_2 + 2NO\\uparrow + 4H_2O}\\)。"],"ans":"A","markingPoints":["先配变价（3, 2）再汇总全部 N（8）"],"verification":"O 原子核查：左 8×3=24，右 3×6 + 2 + 4 = 24，完全守恒。","pitfall":"忘记算上 \\(\\mathrm{Cu(NO_3)_2}\\) 中未变价的 6 个 N 而误选 b=2。"},{"id":"chem8-8.4-q2","tier":"L2","tierLabel":"L2 期末","examStyle":"P1 选择","q":"某同学在酸性条件下配平如下离子方程式，其中各微粒系数及电荷守恒**完全正确**的是（　）。","options":["A. 2MnO₄⁻ + 5Fe²⁺ + 16H⁺ → 2Mn²⁺ + 5Fe³⁺ + 8H₂O","B. Cr₂O₇²⁻ + 6Fe²⁺ + 14H⁺ → 2Cr³⁺ + 6Fe³⁺ + 7H₂O","C. IO₃⁻ + 5I⁻ + 3H⁺ → 3I₂ + 3H₂O","D. MnO₄⁻ + 5H₂O₂ + 6H⁺ → Mn²⁺ + 5O₂↑ + 8H₂O"],"correctOption":"B","given":"四个酸性离子方程式","method":"逐个核查“原子守恒”和“左右电荷总数相等”","principle":"电荷不平或原子不平的离子方程式一律错误。","steps":["A 错：左电荷 −2+10+16=+24，右 +4+15=+19（应 1MnO₄⁻ 配 5Fe²⁺ + 8H⁺）；","B 对：Cr₂O₇²⁻(2×3=6e⁻) 配 6Fe²⁺(6e⁻)，左电荷 −2+12+14=+24，右 2×3+6×3=+24，H(14=7×2), O(7=7) 全平！","C 错：左 3 个 H，右 6 个 H（应 6H⁺）；","D 错：1MnO₄⁻ 只得 5e⁻，不能氧化 5 个 H₂O₂（需 10e⁻），正确系数是 2MnO₄⁻ + 5H₂O₂ + 6H⁺。"],"ans":"B","markingPoints":["用电荷守恒与电子守恒秒杀选择题"],"verification":"教材 p.212 问题解决(4)(5) 同类题验证。","pitfall":"只看电子转移不查 H 原子或电荷总数。"},{"id":"chem8-8.4-q3","tier":"L2","tierLabel":"L2 期末","examStyle":"P2 配平计算","q":"（教材 p.211–212 问题解决改编）试用**氧化数法**或**离子—电子法**配平下列两道方程式（需写出关键变价或半反应推导过程）：\n(1) \\(\\mathrm{K_2Cr_2O_7(aq) + H_2O_2(aq) + H_2SO_4(aq) \\longrightarrow K_2SO_4(aq) + Cr_2(SO_4)_3(aq) + H_2O(l) + O_2(g)}\\)\n(2) \\(\\mathrm{ClO_3^-(aq) + Fe^{2+}(aq) + H^+(aq) \\longrightarrow Cl^-(aq) + Fe^{3+}(aq) + H_2O(l)}\\)（p.210 活动 3(2)）。","given":"两道酸性氧化还原配平题","method":"半反应先配主原子与介质原子，或氧化数法取整分子最小公倍数","principle":"电子得失守恒、质量守恒与电荷守恒。","steps":["(1) 还原半反应：\\(\\mathrm{Cr_2O_7^{2-} + 14H^+ + 6e^- \\longrightarrow 2Cr^{3+} + 7H_2O}\\)；氧化半反应：\\(\\mathrm{H_2O_2 \\longrightarrow O_2\\uparrow + 2H^+ + 2e^-}\\)。","氧化式 \\(\\times 3\\) 相加得离子式：\\(\\mathrm{Cr_2O_7^{2-} + 3H_2O_2 + 8H^+ \\longrightarrow 2Cr^{3+} + 3O_2\\uparrow + 7H_2O}\\)。","补回 \\(\\mathrm{K^+}\\) 与 \\(\\mathrm{SO_4^{2-}}\\) 得全分子方程式：\n**\\(\\mathrm{K_2Cr_2O_7(aq) + 3H_2O_2(aq) + 4H_2SO_4(aq) \\longrightarrow K_2SO_4(aq) + Cr_2(SO_4)_3(aq) + 3O_2(g) + 7H_2O(l)}\\)**。","(2) 还原半反应：\\(\\mathrm{ClO_3^- + 6H^+ + 6e^- \\longrightarrow Cl^- + 3H_2O}\\)；氧化半反应：\\(\\mathrm{Fe^{2+} \\longrightarrow Fe^{3+} + e^-}\\)（\\(\\times 6\\)）。","相加得配平离子方程式：**\\(\\mathrm{ClO_3^-(aq) + 6Fe^{2+}(aq) + 6H^+(aq) \\longrightarrow Cl^-(aq) + 6Fe^{3+}(aq) + 3H_2O(l)}\\)**。"],"ans":"(1) K₂Cr₂O₇ + 3H₂O₂ + 4H₂SO₄ → K₂SO₄ + Cr₂(SO₄)₃ + 3O₂↑ + 7H₂O；(2) ClO₃⁻ + 6Fe²⁺ + 6H⁺ → Cl⁻ + 6Fe³⁺ + 3H₂O。","markingPoints":["第(1)问正确配出 1:3:4 系数并检查 H₂O 为 7（3分）","第(2)问正确写出 1:6:6 系数与 3H₂O（2分）"],"verification":"电荷与原子核查：(1) 两侧 S 4=1+3, H 14=7×2, O 29=4+6+16? 左 7+6+16=29，右 4+12+6+7=29；(2) 左 −1+12+6=+17，右 −1+18=+17。","pitfall":"第(1)问在补硫酸时容易把 8H⁺ 误写成 8H₂SO₄ 而不是 4H₂SO₄。"},{"id":"chem8-8.4-q4","tier":"L3","tierLabel":"L3 预试","examStyle":"P1 选择","q":"在碱性条件下，用高铁酸根（\\(\\mathrm{FeO_4^{2-}}\\)）处理含硫离子（\\(\\mathrm{S^{2-}}\\)）的废水，生成氢氧化铁沉淀（\\(\\mathrm{Fe(OH)_3}\\)）和硫酸根（\\(\\mathrm{SO_4^{2-}}\\)）。当用离子—电子法配平该离子方程式时，\\(\\mathrm{FeO_4^{2-}}\\) 与 \\(\\mathrm{S^{2-}}\\) 的化学计量数之比，以及补充进方程式**反应物一侧**的微粒（\\(\\mathrm{H_2O}\\) 或 \\(\\mathrm{OH^-}\\)）分别是（　）。","options":["A. 8 : 3，反应物需加 H₂O","B. 8 : 3，反应物需加 OH⁻","C. 3 : 8，反应物需加 H₂O","D. 4 : 3，反应物需加 H₂O"],"correctOption":"A","given":"FeO₄²⁻(+6→+3) + S²⁻(−2→+6) → Fe(OH)₃↓ + SO₄²⁻（碱性）","method":"先算电子公倍数定 8:3，再直接核对两侧电荷差决定反应物是加 H₂O 还是 OH⁻","principle":"碱性介质原子、电荷双守恒。","steps":["\\(\\mathrm{FeO_4^{2-}}\\) 中 Fe(+6→+3) 得 3e⁻；\\(\\mathrm{S^{2-}}\\) 中 S(−2→+6) 失 8e⁻。故 \\(\\mathrm{LCM}(3,8)=24\\)，比率 **\\(8\\,\\mathrm{FeO_4^{2-}} : 3\\,\\mathrm{S^{2-}}\\)**。","先写主干：\\(8\\mathrm{FeO_4^{2-}} + 3\\mathrm{S^{2-}} \\longrightarrow 8\\mathrm{Fe(OH)_3} + 3\\mathrm{SO_4^{2-}}\\)。","检查电荷：左总电荷 \\(= -16 - 6 = -22\\)；右当前总电荷 \\(= -6\\)。为了在碱性中使两边电荷相等，**右边必须加上 16 个 \\(\\mathrm{OH^-}\\)**（使右变为 \\(-6 - 16 = -22\\)）！","再数 H 原子：右边现有 \\(8\\times 3 + 16 = 40\\) 个 H，故**左边（反应物）需加上 20 个 \\(\\mathrm{H_2O}\\)**！核查 O：左 \\(32 + 20 = 52\\)，右 \\(24 + 12 + 16 = 52\\)，完全平衡！"],"ans":"A","markingPoints":["算得 8:3 并用电荷差一步判断 OH⁻ 在生成物、H₂O 在反应物"],"verification":"\\(8\\mathrm{FeO_4^{2-} + 3S^{2-} + 20H_2O \\longrightarrow 8Fe(OH)_3\\downarrow + 3SO_4^{2-} + 16OH^-}\\)。","pitfall":"习惯性以为“碱性反应物就必须有 OH⁻”，实际上很多碱性离子方程式生成 OH⁻（水在反应物侧消耗）。"},{"id":"chem8-8.4-q5","tier":"L4","tierLabel":"L4 统考压轴","examStyle":"P2 综合计算与配平","q":"（结合教材 p.213 思考题 8d 与工业/滴定综合）某含铬酸性废水中的重铬酸根离子（\\(\\mathrm{Cr_2O_7^{2-}}\\)）可用绿矾（\\(\\mathrm{FeSO_4\\cdot 7H_2O}\\)）还原转化为低毒的 \\(\\mathrm{Cr^{3+}}\\)，然后再调至碱性沉淀除去。(1) 用**离子—电子法**写出并配平酸性条件下 \\(\\mathrm{Cr_2O_7^{2-}}\\) 与 \\(\\mathrm{Fe^{2+}}\\) 反应的离子方程式；(2) 若要完全处理 \\(100.0\\text{ mL}\\) 含 \\(\\mathrm{Cr_2O_7^{2-}}\\) 浓度为 \\(0.050\\text{ mol/L}\\) 的废水，至少需要加入多少克的 \\(\\mathrm{FeSO_4\\cdot 7H_2O}\\)（已知相对原子质量：\\(\\mathrm{Fe}=56, \\mathrm{S}=32, \\mathrm{O}=16, \\mathrm{H}=1\\)）？(3) 若在强碱性溶液中改用 \\(\\mathrm{H_2O_2}\\) 把 \\(\\mathrm{Cr(OH)_3}\\) 氧化回黄色 \\(\\mathrm{CrO_4^{2-}}\\)（\\(\\mathrm{H_2O_2}\\) 自身还原为 \\(\\mathrm{H_2O}\\)），试用离子—电子法写出并配平该碱性氧化反应的离子方程式。","given":"酸性 Cr₂O₇²⁻ + Fe²⁺；V=100.0 mL, c=0.050 mol/L；碱性 Cr(OH)₃ + H₂O₂ → CrO₄²⁻ + H₂O","method":"半反应配平 → n=cV 与化学计量比算质量 → 碱性“先酸后碱法”配 Cr(OH)₃+H₂O₂","principle":"电子得失守恒、物质的量计算（Ch 3）、碱性介质半反应法。","steps":["(1) 还原半反应：\\(\\mathrm{Cr_2O_7^{2-} + 14H^+ + 6e^- \\longrightarrow 2Cr^{3+} + 7H_2O}\\)；氧化半反应：\\(\\mathrm{6Fe^{2+} \\longrightarrow 6Fe^{3+} + 6e^-}\\)。","配平离子方程式：**\\(\\mathrm{Cr_2O_7^{2-} + 6Fe^{2+} + 14H^+ \\longrightarrow 2Cr^{3+} + 6Fe^{3+} + 7H_2O}\\)**。","(2) 废水中 \\(n(\\mathrm{Cr_2O_7^{2-}}) = 0.050\\text{ mol/L} \\times 0.1000\\text{ L} = 0.0050\\text{ mol}\\)。","由计量比 \\(1:6\\) 得至少需要 \\(n(\\mathrm{FeSO_4\\cdot 7H_2O}) = 6 \\times 0.0050 = 0.030\\text{ mol}\\)。","绿矾摩尔质量 \\(M = 56 + 32 + 4\\times 16 + 7\\times 18 = 152 + 126 = 278\\text{ g/mol}\\)，所需质量 \\(m = 0.030 \\times 278 = \\mathbf{8.34\\text{ g}}\\)。","(3) 碱性半反应：\n- 氧化：\\(\\mathrm{Cr(OH)_3 + H_2O \\to CrO_4^{2-} + 5H^+ + 3e^-}\\)，两边加 \\(5\\mathrm{OH^-}\\) 得 **\\(\\mathrm{Cr(OH)_3 + 5OH^- \\longrightarrow CrO_4^{2-} + 4H_2O + 3e^-}\\)**；\n- 还原：\\(\\mathrm{H_2O_2 + 2H^+ + 2e^- \\to 2H_2O}\\)，两边加 \\(2\\mathrm{OH^-}\\) 得 **\\(\\mathrm{H_2O_2 + 2e^- \\longrightarrow 2OH^-}\\)**。","氧化式 \\(\\times 2\\) + 还原式 \\(\\times 3\\) 消去 \\(6\\mathrm{e^-}\\) 与重复 \\(6\\mathrm{OH^-}\\) 得：\n**\\(\\mathrm{2Cr(OH)_3(s) + 3H_2O_2(aq) + 4OH^-(aq) \\longrightarrow 2CrO_4^{2-}(aq) + 8H_2O(l)}\\)**。"],"ans":"(1) Cr₂O₇²⁻ + 6Fe²⁺ + 14H⁺ → 2Cr³⁺ + 6Fe³⁺ + 7H₂O；(2) 8.34 g；(3) 2Cr(OH)₃ + 3H₂O₂ + 4OH⁻ → 2CrO₄²⁻ + 8H₂O。","markingPoints":["正确配平(1)酸性离子方程式（2分）","算得 0.030 mol 绿矾及 8.34 g（含结晶水 7×18=126）（2分）","正确在碱性条件下配平(3)并消去多余 OH⁻（2分）"],"verification":"(3) 原子核查：Cr 2=2；O 6+6+4=16 vs 8+8=16；H 6+6+4=16 vs 16；电荷 −4 = −4，完全平衡！","pitfall":"第(2)问计算摩尔质量时忘记把结晶水 \\(7\\mathrm{H_2O}\\)（126 g/mol）算入绿矾中，错算成 152 g/mol。"}],"cheatSheet":["氧化数法四步：标数 → 求升降（带下标）→ **最小公倍数**配主干 → 观察质量守恒（遇歧化反应从产物端往回配）。","离子—电子法五步：写框架 → 拆半反应并配原子（**酸用 H⁺/H₂O**，**碱用 OH⁻/H₂O**）→ 加 e⁻ 平电荷 → 倍数叠加消 e⁻ → 还原检查。","终极防错检验：**原子守恒 + 电荷守恒**双验证；**碱性先酸后碱法**（借酸配出 \\(m\\mathrm{H^+}\\) 后两边同加 \\(m\\mathrm{OH^-}\\) 消水）零失误。"],"kbEntryIds":["kb-chem8-balance-oxnum","kb-chem8-balance-ionelec"],"quiz":{"q":"用离子—电子法配平碱性反应：\\(\\mathrm{MnO_4^-(aq) + SO_3^{2-}(aq) + H_2O(l) \\longrightarrow MnO_2(s) + SO_4^{2-}(aq) + OH^-(aq)}\\)，写出配平后的完整离子方程式。","given":"Mn(+7→+4, 得 3e⁻)；S(+4→+6, 失 2e⁻)","method":"写出两个碱性半反应，取 LCM(3,2)=6 叠加消去 e⁻ 和多余微粒","principle":"碱性介质配平规则（OH⁻/H₂O）及电荷、原子双守恒。","steps":["还原半反应（×2）：\\(\\mathrm{MnO_4^- + 2H_2O + 3e^- \\longrightarrow MnO_2 + 4OH^-}\\)。","氧化半反应（×3）：\\(\\mathrm{SO_3^{2-} + 2OH^- \\longrightarrow SO_4^{2-} + H_2O + 2e^-}\\)。","相加消去 \\(6\\mathrm{e^-}\\)、\\(6\\mathrm{OH^-}\\) 与 \\(3\\mathrm{H_2O}\\)。"],"ans":"\\(\\mathrm{2MnO_4^-(aq) + 3SO_3^{2-}(aq) + H_2O(l) \\longrightarrow 2MnO_2(s) + 3SO_4^{2-}(aq) + 2OH^-(aq)}\\)"},"diagrams":[{"src":"assets/fig/v2/chem08-redox-transfer.svg","caption":"图 8-1 双线桥电子转移示意与离子—电子法配平五步流程图","alt":"双线桥法与离子电子法五步流程图","pageRef":"化上 p.203–213"}]}]},"化学9":{"lessonKey":"化学9","courseCode":"chemistry","subject":"化学","chapter":9,"title":"IA族元素：钠和钾","syllabus":"3.2 IA族元素","bookId":"sm1-chemistry-2017","bookCitation":"《马来西亚华文独中教科书 · 化学（上册）》（2017年11月版）第9章 p.217–234","examScopes":["sem2_final","uec"],"chapterOverview":{"summary":"第9章是元素化合物学习的开篇主族章，以 IA 族碱金属代表元素钠（Na）和钾（K）为切入点，建立“最外层电子构型 ns¹ → 强还原性 → 同族从上到下金属性递变”的核心逻辑，贯穿单质与氧气/卤素/水/酸反应、焰色试验物理本质及烧碱/纯碱/小苏打转化网络，是 UEC 统考选择题与无机大题的高频基石。","conceptTree":[{"branch":"9.1 钠和钾的性质（p.218–222）","items":["IA 族（Li–Fr）最外层 ns¹ 结构与递变规律","表 9-2 物理性质与煤油保存原理","与 O₂（Na₂O vs Na₂O₂ vs KO₂）、卤素（表 9-3）、水（浮熔游响红）、酸反应","电解熔融 NaCl 制钠（图 9-2）与热还原蒸馏法制钾"]},{"branch":"9.2 焰色试验（p.223–225）","items":["活动探究 1：铂丝洗涤、灼烧、蘸取操作五步法","Na 黄色 vs K 透过蓝色钴玻璃呈浅紫色","电子跃迁受激发射光谱机制（物理变化）"]},{"branch":"9.3 钠和钾的重要化合物（p.225–230）","items":["NaCl 与氯碱工业离子膜电解槽（图 9-7）","NaOH 潮解变质检验与腐蚀玻璃（SiO₂）/两性金属（Al）","Na₂CO₃（纯碱）vs NaHCO₃（小苏打）溶解度、碱性、热稳定性（图 9-8）与酸反应速率","KNO₃ 吸热溶解、氮钾肥与受热分解制氧"]}]},"paperFocus":["高三下半年期末考 & UEC 统考：卷一（30% 选择题）常考 Na/K 密度与保存（Li 用石蜡、Na/K 用煤油）、Na₂O vs Na₂O₂ 产物与条件、焰色试验透过蓝色钴玻璃滤黄光、Na₂CO₃ 与 NaHCO₃ 鉴别与除杂。","UEC 卷二乙部（无机化学选答题）及探究题（10%）：常以课本 U 形管煤油—水反应装置（p.233）、加热 NaHCO₃ 分解（图 9-8）或氯碱/氨碱流程框图切入，考查离子方程式配平、氧化还原定量计算与 NaOH 变质实验设计。"],"solvingWorkflow":["定位反应条件与体系：金属钠在空气中切开（常温生成白色 Na₂O）vs 加热燃烧（生成淡黄色 Na₂O₂）；钾燃烧在空气/纯氧中可至超氧化钾 KO₂。","定量计算 Na₂O₂ 或混合物与 H₂O/CO₂ 反应：优先使用“固体质量差量法”或“电子转移守恒”（1 mol Na₂O₂ 无论与 CO₂ 还是 H₂O 反应均转移 1 mol e⁻，生成 0.5 mol O₂）。","处理 Na₂CO₃ 与 NaHCO₃ 混合物：固体去杂优先加热（使 NaHCO₃ → Na₂CO₃）；溶液去杂则向 Na₂CO₃ 中通足量 CO₂（得 NaHCO₃）或向 NaHCO₃ 中加适量 NaOH（得 Na₂CO₃）。","离子鉴别与检验：见到溶液无明显颜色而需区分 Na⁺/K⁺，立刻锁定“焰色试验（K⁺ 必配蓝色钴玻璃）”；见到 NaOH 变质检验，先排除 Na₂CO₃ 本身显碱性的干扰（不可仅用酚酞）。"],"questionTypes":["IA 族递变规律预测（Fr/Rb/Cs 密度、熔沸点、氧化物与水反应剧烈程度）","钠与水反应“浮熔游响红”现象解释及 U 形管煤油-水缓冲实验探究（p.233）","过氧化钠与 CO₂/H₂O 气体体积差、固体增重及氧化还原配平计算","焰色试验操作正误判断与蓝色钴玻璃作用机理","Na₂CO₃ 与 NaHCO₃ 溶解度（活动 10）、热稳定性（活动 11）与盐酸反应（活动 12）综合实验及框图推断"],"scoringNotes":["书写热化学或无机方程式时，统考评分严格要求注明反应条件（如“点燃”、“△”、“电解”、“高温”）及气体/沉淀箭头（↑、↓）。","解释“为什么钾要透过蓝色钴玻璃观察焰色”时，必须点明“滤去微量钠盐杂质产生的强黄色光干扰”，只写“为了看得更清楚”不给满分。"],"vid":[{"t":"钠和钾的化学性质与水反应实验","q":"钠和钾 化学性质 与水反应 浮熔游响红"},{"t":"焰色反应操作规范与蓝色钴玻璃原理","q":"焰色试验 蓝色钴玻璃 钠 钾 高中化学"},{"t":"碳酸钠与碳酸氢钠的性质对比及相互转化","q":"碳酸钠 碳酸氢钠 性质比较 热稳定性 高中化学"}],"sections":[{"id":"9.1","t":"钠和钾的性质","anchor":{"pages":"化上 p.218–222","syllabus":"3.2.1–3.2.2 碱金属原子结构、物理性质及钠钾单质化学反应与工业制法","examScopes":["sem2_final","uec"],"examWeight":"P1 高频概念辨析 + P2 实验探究（煤油-水 U 形管）与工业制备方程","terms":"Alkali metals · Kerosene storage · Sodium peroxide (Na₂O₂) · Potassium superoxide (KO₂) · Thermal reduction","prerequisites":["元素周期律与同主族递变规律（化上 Ch 6.3）","氧化还原反应电子转移与方程式配平（化上 Ch 8）"],"goals":["从原子电子排布（Na 3s¹、K 4s¹）阐明 IA 族碱金属强还原性的成因及从 Li 到 Fr 的性质递变规律。","对比表 9-2 中钠和钾的物理性质，解释“煤油保存钠钾”及钠投入水中“浮、熔、游、响、红”五现象的物理化学原因。","准确书写钠、钾在不同条件下与氧气、卤素（表 9-3）、水、酸反应的方程式，并说明电解熔融 NaCl 制钠与热还原法制钾的工业原理。"]},"concepts":[{"kind":"definition","title":"IA 族碱金属结构特征与表 9-2 物理性质","pageRef":"化上 p.219–220、p.231","body":["**族序与结构**：IA 族包含锂（Li）、钠（Na）、钾（K）、铷（Rb）、铯（Cs）和放射性元素钫（Fr），统称**碱金属（alkali metals）**。其原子最外层都只有 **1 个价电子（\\(ns^1\\)）**，极易失去电子形成 +1 价阳离子，因而自然界中**无游离态单质**，全部以化合态存在。","**递变规律**：从 Li 到 Fr，原子序数与电子层数依次递增，原子半径依次增大，核对最外层电子引力减弱，失电子能力增强，故**金属性与还原性依次增强**：\\(\\mathrm{Li < Na < K < Rb < Cs}\\)。但与通常金属相反，碱金属的**熔沸点随原子序数增大而降低**（金属键随半径增大而减弱）。","**生理与工业用途（p.218–219）**：人体神经传导与肌肉控制需 \\(\\mathrm{Na^+}\\) 与 \\(\\mathrm{K^+}\\)（WHO 建议每日食盐 \\(3\\text{–}5\\text{ g}\\)）；常温液态 **Na-K 合金**用作快中子反应堆热交换剂；高压钠灯黄光射程远、透雾力强；钠用于从 \\(\\mathrm{Ti, Zr}\\) 等氯化物中置换金属。"],"table":{"headers":["单质","颜色与状态","密度 / kg·m⁻³","熔点 / ℃","沸点 / ℃","硬度与保存"],"rows":[["钠（Na）","银白色固体","970（0.97 g·cm⁻³）","97.81","882.9","质软（小刀可切），保存在煤油中"],["钾（K）","银白色固体","860（0.86 g·cm⁻³）","63.65","774","质软（比钠更软），保存在煤油中"]]},"takeaway":"记忆密度关系：煤油（~800 kg·m⁻³）< K（860）< Na（970）< 水（1000）。因锂密度仅 530 kg·m⁻³ 小于煤油，故锂不能保存在煤油中而须封在石蜡中！"},{"kind":"mechanism","title":"与氧气、卤素（表 9-3）反应及产物随条件变化","pageRef":"化上 p.221","body":["**常温氧化 vs 点燃燃烧**：","- 切开钠、钾在空气中表面迅速变暗：钠生成白色 **\\(\\mathrm{Na_2O}\\)**，钾生成淡黄色 **\\(\\mathrm{K_2O}\\)**。","- 加热或点燃燃烧时，钠发出黄色火焰生成**过氧化钠（\\(\\mathrm{Na_2O_2}\\)，淡黄色固体）**；钾发出浅紫色火焰生成**过氧化钾（\\(\\mathrm{K_2O_2}\\)）**，在纯氧中燃烧还可生成更复杂的**超氧化钾（\\(\\mathrm{KO_2}\\)）**。","**与卤素室温反应对比（表 9-3）**：通式 \\(2\\mathrm{M(s)} + \\mathrm{X_2} \\to 2\\mathrm{MX(s)}\\)。室温下与 \\(\\mathrm{Cl_2}\\) 均剧烈燃烧；与 \\(\\mathrm{Br_2}\\) 时 Na 仅在表面反应而 K **剧烈爆炸**；与 \\(\\mathrm{I_2}\\) 时 Na **不反应**而 K **剧烈燃烧**——直观印证还原性 \\(\\mathrm{K > Na}\\)。"],"takeaway":"过氧化钠（Na₂O₂）中氧元素的氧化数为 −1 价，而超氧化钾（KO₂）中氧元素的平均氧化数为 −1/2 价！"},{"kind":"experiment","title":"活动 1–5：钠钾与水反应现象（浮熔游响红）及工业制取（图 9-2）","pageRef":"化上 p.219–220、p.222","body":["**绿豆大小钠投入滴有酚酞的水中（活动 3）五字现象**：①**浮**（浮在水面，因 \\(\\rho(\\mathrm{Na}) < \\rho(\\text{水})\\)）；②**熔**（熔成闪亮银白色小球，因反应放热且钠熔点仅 97.81 ℃）；③**游**（四处游动，因产生 \\(\\mathrm{H_2}\\) 气体推动）；④**响**（发出嘶嘶声响，因反应剧烈放气）；⑤**红**（溶液变红，因生成强碱 \\(\\mathrm{NaOH}\\)）。","**钾与水反应对比（活动 5）**：将芝麻大小钾投入水中并立即盖上玻璃片（防止液滴飞溅伤人），反应比钠更剧烈，产生的氢气立即被反应放热引燃并发出**浅紫色火焰**与轻微爆炸声。","**与酸反应与安全提示**：钠、钾与酸先直接与溶液中 \\(\\mathrm{H^+}\\) 反应（比与水更剧烈，极易爆炸），若钠过量才会再与水反应；**钠着火时绝不能用水或泡沫/CO₂ 灭火，必须用干燥细沙盖灭**（p.232 练习 5）。","**工业制法（p.222 图 9-2）**：①**电解熔融 NaCl** 制钠（阳极逸出 \\(\\mathrm{Cl_2}\\)，阴极得液态 \\(\\mathrm{Na}\\)）；②**热还原法制钾**：\\(\\mathrm{KCl(l) + Na(l)} \\xrightarrow{\\text{高温}} \\mathrm{NaCl(l) + K(g)}\\uparrow\\)。尽管金属活动性 \\(\\mathrm{K > Na}\\)，但因**钾的沸点（774 ℃）低于钠（882.9 ℃）**，高温下不断蒸出钾蒸气促使反应持续向右进行，经真空蒸馏纯度可达 99.99%。"],"takeaway":"工业用 Na 置换 KCl 制 K 不是因为 Na 比 K 活泼，而是利用勒夏特列平衡移动原理——钾的沸点比钠低，气态钾不断逸出驱动反应正向进行！"}],"formulas":[{"title":"钠、钾与氧气及水的核心反应方程式","tex":"4\\mathrm{Na(s)} + \\mathrm{O_2(g)} \\longrightarrow 2\\mathrm{Na_2O(s)},\\qquad 2\\mathrm{Na(s)} + \\mathrm{O_2(g)} \\xrightarrow{\\text{点燃}} \\mathrm{Na_2O_2(s)}","plain":"4Na + O2 → 2Na2O (常温); 2Na + O2 → Na2O2 (点燃)","conditions":"注意反应条件对产物的决定作用；钾燃烧还生成 KO₂","pageRef":"化上 p.221","note":"离子态书写时，Na₂O₂ 为离子晶体，由 Na⁺ 与 O₂²⁻（过氧根）构成。"},{"title":"钠、钾与水及盐酸反应的离子方程式","tex":"2\\mathrm{M(s)} + 2\\mathrm{H_2O(l)} \\longrightarrow 2\\mathrm{M^+(aq)} + 2\\mathrm{OH^-(aq)} + \\mathrm{H_2(g)}\\uparrow,\\qquad 2\\mathrm{M(s)} + 2\\mathrm{H^+(aq)} \\longrightarrow 2\\mathrm{M^+(aq)} + \\mathrm{H_2(g)}\\uparrow","plain":"2M + 2H2O → 2M⁺ + 2OH⁻ + H2↑; 2M + 2H⁺ → 2M⁺ + H2↑ (M = Na, K)","conditions":"金属 M（不可拆）与水（不可拆）反应，生成可溶强碱 MOH","pageRef":"化上 p.222","note":"切忌在钠与水离子方程式中漏掉电荷守恒（2M⁺ + 2OH⁻）。"},{"title":"工业制钠与热还原制钾方程式","tex":"2\\mathrm{NaCl(l)} \\xrightarrow{\\text{电解}} 2\\mathrm{Na(s)} + \\mathrm{Cl_2(g)}\\uparrow,\\qquad \\mathrm{KCl(l)} + \\mathrm{Na(l)} \\xrightarrow{\\text{高温}} \\mathrm{NaCl(l)} + \\mathrm{K(g)}\\uparrow","plain":"2NaCl(l) —(电解)→ 2Na + Cl2↑; KCl(l) + Na(l) —(高温)→ NaCl(l) + K(g)↑","conditions":"制钠必须电解熔融无水 NaCl（水溶液只能得 NaOH、H₂、Cl₂）","pageRef":"化上 p.222","note":"K 的沸点 774 ℃ < Na 的沸点 882.9 ℃，故高温下 K 率先汽化逸出。"}],"pitfalls":[{"title":"混淆钠在常温与点燃下的氧化产物","wrong":"“金属钠在空气中燃烧生成白色的氧化钠 \\(\\mathrm{Na_2O}\\)。”","diagnosis":"忽视温度条件差异；燃烧高温下生成更稳定的过氧化钠。","right":"常温下钠与氧气反应生成白色 \\(\\mathrm{Na_2O}\\)；**点燃燃烧时生成淡黄色的 \\(\\mathrm{Na_2O_2}\\)**。且常温下置于空气中的钠最终还会吸收水与 \\(\\mathrm{CO_2}\\) 依次变为 \\(\\mathrm{NaOH} \\to \\mathrm{Na_2CO_3\\cdot 10H_2O} \\to \\mathrm{Na_2CO_3}\\) 粉末（p.222 思考题 9a-3）。","checkRule":"审题看清“常温/切开表面变暗”还是“坩埚加热/空气中燃烧”。"},{"title":"误以为钠可以置换出硫酸铜溶液中的金属铜","wrong":"“将钠投入 \\(\\mathrm{CuSO_4}\\) 溶液中，发生反应 \\(2\\mathrm{Na} + \\mathrm{CuSO_4} \\to \\mathrm{Na_2SO_4} + \\mathrm{Cu}\\)。”","diagnosis":"溶液中有大量水分子，极活泼的钠直接与水剧烈反应放 \\(\\mathrm{H_2}\\) 和 \\(\\mathrm{OH^-}\\)，不会置换出铜单质。","right":"正确现象为：钠浮熔游响，并生成**蓝色 \\(\\mathrm{Cu(OH)_2}\\) 絮状沉淀**，反应总式：\\(2\\mathrm{Na} + 2\\mathrm{H_2O} + \\mathrm{CuSO_4} \\to \\mathrm{Cu(OH)_2}\\downarrow + \\mathrm{Na_2SO_4} + \\mathrm{H_2}\\uparrow\\)。","checkRule":"凡是活泼金属（K、Ca、Na）投入任何盐的水溶液中，永远是“先与水反应”，再看生成的碱是否与盐复分解。"},{"title":"误以为钠能保存在密度比它大的四氯化碳（CCl₄）中","wrong":"“\\(\\mathrm{CCl_4}\\) 不与钠反应且密度更大，可以把钠保存在 \\(\\mathrm{CCl_4}\\) 中隔绝空气。”","diagnosis":"教材 p.233 作答题 4 经典考点：若液体密度大于钠（如 \\(\\rho(\\mathrm{CCl_4}) = 1.59\\text{ g/cm}^3 > 0.97\\text{ g/cm}^3\\)），钠会浮在液面上方直接暴露于空气中氧化。","right":"隔绝空气保存液必须同时满足：**①不与钠反应；②密度小于钠**（让钠沉在底部），故只能用煤油或石蜡油。","checkRule":"检查保存液体密度必须“小于被保存金属”。"}],"examples":[{"label":"例 9.1.1","tier":"L2","tierLabel":"L2 期末必考","title":"课本 U 形管煤油—水反应实验装置分析（p.233 作答题 5）","prompt":"如图所示装置（煤油密度 \\(0.87\\text{ g\\,cm}^{-3}\\)，水密度 \\(1.0\\text{ g\\,cm}^{-3}\\)，钠密度 \\(0.97\\text{ g\\,cm}^{-3}\\)）用于平稳进行钠与水反应并收集检验气体。(1) 加入一小块钠并塞紧橡皮塞后，反应开始前钠位于何处（a 煤油中部、b 煤油与水界面、c 水底）？(2) 为什么反应后钠在界面附近跳动且反应能平缓、连续进行？(3) 漏斗在该装置中的主要作用是什么？","clues":"比较三种物质密度大小 \\(0.87 < 0.97 < 1.0\\)，结合气体推动与液面压强平衡分析。","strategy":"密度定位初始位置 → 浮力与气泡推力解释上下跳动 → 连通器漏斗防压强过大爆塞。","given":"ρ(煤油)=0.87 g/cm³，ρ(Na)=0.97 g/cm³，ρ(水)=1.0 g/cm³","principle":"阿基米德浮沉条件、反应局部隔绝限速及连通器压强缓冲。","steps":["(1) 因为 \\(\\rho(\\text{煤油}) < \\rho(\\mathrm{Na}) < \\rho(\\text{水})\\)，钠沉过煤油层但浮在水面上，故反应开始前钠位于 **b（煤油与水的界面处）**。","(2) 钠接触水反应产生 \\(\\mathrm{H_2}\\) 气泡附着在表面，浮力增大将钠推入上层煤油中，反应立即暂停（煤油隔绝水）；气泡逸出后钠在重力作用下重新下沉回界面与水反应。如此反复“上下跳动”，使钠与水接触面和反应热及时消散，反应因而**平缓、连续**进行。","(3) **漏斗作用**：收集并容纳反应产生气体增大压强时被压入左管的液体，起到**平衡压强、防止橡皮塞被冲开**（安全缓冲）的作用。","(4) 该装置另一显著优点是**排除了空气中 \\(\\mathrm{O_2}\\) 的干扰**，避免生成的 \\(\\mathrm{H_2}\\) 与空气混合点燃发生爆炸，同时能使钠在液下温和反应而不致飞溅。"],"answer":"(1) b 处；(2) 气泡托举钠进入煤油暂停反应，气泡逸出后重落界面继续反应，反复跳动限速散热；(3) 平衡系统压强，容纳被压出液体，防止冲塞。","markingPoints":["正确判断 b 处并给出三者密度排序（1分）","清晰阐述“生成气泡上浮入煤油暂停 → 气泡脱离下沉续反应”动态循环（2分）","指出漏斗平衡压强缓冲及隔绝空气防爆优点（2分）"],"verification":"对照教材 p.233–234 习题 5 五个设问逐一吻合。","pitfall":"误答漏斗只用来“往里加水”，忽略反应过程中密闭产气时液面上升的安全缓冲作用。"},{"label":"例 9.1.2","tier":"L4","tierLabel":"L4 统考压轴","title":"Na₂O₂ 与 CO₂/H₂O 反应固体增重与差量定量计算","prompt":"向装有 \\(15.6\\text{ g}\\) 固体过氧化钠（\\(\\mathrm{Na_2O_2}\\)）的密闭容器（预先抽真空）中通入一定量的 \\(\\mathrm{CO_2}\\) 和水蒸气混合气体，充分反应后测得容器内剩余气体在标准状况下体积为 \\(2.24\\text{ L}\\)，固体质量由 \\(15.6\\text{ g}\\) 增至 \\(21.2\\text{ g}\\)。（已知 \\(M(\\mathrm{Na_2O_2}) = 78\\text{ g\\,mol}^{-1}\\)，标况 \\(V_m = 22.4\\text{ L\\,mol}^{-1}\\)）(1) 求参与反应的 \\(\\mathrm{Na_2O_2}\\) 物质的量及最终固体成分；(2) 求原混合气体中 \\(\\mathrm{CO_2}\\) 与 \\(\\mathrm{H_2O(g)}\\) 各自的物质的量。","clues":"写明“增重差量本质”：\\(\\mathrm{Na_2O_2 + CO_2 \\to Na_2CO_3 + \\frac{1}{2}O_2}\\) 相当于吸收 \\(\\mathrm{CO}\\)（增重 \\(28\\text{ g/mol}\\)）；\\(\\mathrm{Na_2O_2 + H_2O \\to 2NaOH + \\frac{1}{2}O_2}\\) 相当于吸收 \\(\\mathrm{H_2}\\)（增重 \\(2\\text{ g/mol}\\)）！","strategy":"先由标况氧气体积反推实际反应的 \\(\\mathrm{Na_2O_2}\\) 总量 → 检验是否完全反应 → 联立物质的量方程与差量质量方程求解。","given":"m(Na₂O₂) = 15.6 g (0.200 mol), m_solid_final = 21.2 g, Δm = 5.6 g, V(O₂) = 2.24 L (0.100 mol)","principle":"Na₂O₂ 歧化电子守恒（2 mol Na₂O₂ 放 1 mol O₂）与固体质量差量法。","steps":["初始过氧化钠物质的量：\\(n_0(\\mathrm{Na_2O_2}) = \\frac{15.6}{78} = 0.200\\text{ mol}\\)。","反应生成氧气物质的量：\\(n(\\mathrm{O_2}) = \\frac{2.24}{22.4} = 0.100\\text{ mol}\\)。由计量比 \\(2\\mathrm{Na_2O_2} \\sim \\mathrm{O_2}\\) 可知，参加反应的 \\(\\mathrm{Na_2O_2}\\) 恰为 \\(0.200\\text{ mol}\\)，故 \\(\\mathrm{Na_2O_2}\\) **完全反应**，剩余气体全部为 \\(\\mathrm{O_2}\\)（固体产物为 \\(\\mathrm{Na_2CO_3}\\) 与 \\(\\mathrm{NaOH}\\)）。","设参加反应的 \\(\\mathrm{CO_2}\\) 为 \\(x\\text{ mol}\\)，\\(\\mathrm{H_2O(g)}\\) 为 \\(y\\text{ mol}\\)。由化学计量关系得：\\(x + y = 0.200\\)（式①）。","由固体净增重 \\(\\Delta m = 21.2 - 15.6 = 5.6\\text{ g}\\)。因为每反应 \\(1\\text{ mol }\\mathrm{CO_2}\\) 净增 \\(28\\text{ g}\\)（相当于 \\(\\mathrm{CO}\\)），每反应 \\(1\\text{ mol }\\mathrm{H_2O}\\) 净增 \\(2\\text{ g}\\)（相当于 \\(\\mathrm{H_2}\\)），故：\\(28x + 2y = 5.6\\)（式②）。","将 \\(y = 0.200 - x\\) 代入式②：\\(28x + 2(0.200 - x) = 5.6 \\implies 26x = 5.2 \\implies x = 0.200\\text{ mol}\\)，从而 \\(y = 0\\text{ mol}\\)！"],"answer":"(1) 反应的 \\(\\mathrm{Na_2O_2}\\) 为 \\(0.200\\text{ mol}\\)，最终固体全为 \\(\\mathrm{Na_2CO_3}\\)；(2) 原混合气体含 \\(\\mathrm{CO_2}\\ 0.200\\text{ mol}\\)，\\(\\mathrm{H_2O(g)}\\ 0\\text{ mol}\\)。","markingPoints":["利用 O₂ 生成量 0.100 mol 确认 0.200 mol Na₂O₂ 恰好全部耗尽（1分）","正确建立差量增重方程 28x + 2y = 5.6（2分）","解出 x = 0.200 mol, y = 0 mol 并判断固体纯为 Na₂CO₃（1分）"],"verification":"检验：\\(0.200\\text{ mol }\\mathrm{Na_2CO_3}\\) 质量为 \\(0.200 \\times 106 = 21.2\\text{ g}\\)，完全吻合！注意：若 \\(\\mathrm{CO_2}\\) 过量还会先把 \\(\\mathrm{NaOH}\\) 转化为 \\(\\mathrm{Na_2CO_3}\\)，故只要 \\(0.200\\text{ mol }\\mathrm{Na_2O_2}\\) 消耗净且固体正好增重 \\(5.6\\text{ g}\\)，混合气体必全为 \\(\\mathrm{CO_2}\\)。","pitfall":"若未用差量法而直接按原气体质量列式，容易忘记扣除生成的氧气质量 \\(3.2\\text{ g}\\) 而算错。"}],"practice":[{"id":"chem9-9.1-q1","tier":"L1","tierLabel":"L1 基础","examStyle":"P1 选择","q":"下列关于金属钠与金属钾的性质和用途的说法中，**正确**的是（　）。","options":["A. 钾元素的金属性弱于钠，故钾与水反应不如钠剧烈","B. 金属钠和钾的密度都小于水，实验室都保存在四氯化碳中","C. 钾的原子半径大于钠，因此金属钾的熔点低于金属钠","D. 在自然界中海盐里含有大量游离态的金属钠单质"],"correctOption":"C","given":"IA 族钠和钾物理化学性质（表 9-2）","method":"逐项比对电子层数、密度、熔点及存在形态","principle":"IA 族随原子序数增大，金属性增强，但金属键减弱导致熔沸点降低。","steps":["A 错：K 比 Na 多一个电子层，金属性 K > Na，与水反应 K 更剧烈。","B 错：CCl₄ 密度大于水（1.59 g/cm³），Na、K 浮在 CCl₄ 上面无法隔绝空气，应保存在煤油中。","C 对：表 9-2 显示熔点 K（63.65 ℃）< Na（97.81 ℃）。","D 错：Na 极活泼，自然界只以 NaCl 等化合态存在。"],"ans":"C","markingPoints":["准确区分碱金属熔点随原子序数增大而降低的反常递变规律"],"verification":"对照化上 p.220 表 9-2 核对。","pitfall":"误以为金属活动性越强熔点越高。"},{"id":"chem9-9.1-q2","tier":"L2","tierLabel":"L2 期末","examStyle":"P1 选择","q":"根据碱金属元素的递变规律，预测第 6 周期 IA 族元素铯（\\(\\mathrm{Cs}\\)）的性质，下列推断**不正确**的是（　）。","options":["A. 铯在空气中燃烧只能生成化学式为 \\(\\mathrm{Cs_2O}\\) 的简单氧化物","B. 铯的氢氧化物的化学式为 \\(\\mathrm{CsOH}\\)，是极强的碱","C. 铯能与水发生剧烈反应甚至立即爆炸，放出氢气","D. 铯原子最外层只有 1 个电子，具有极强的还原性"],"correctOption":"A","given":"IA 族结构递变规律（p.233 第 10 题同类延伸）","method":"依据 Li → Na → K 燃烧产物规律外推至 Cs","principle":"碱金属从上到下金属性增强，燃烧生成的氧化物愈发复杂（Li₂O → Na₂O₂ → KO₂/CsO₂）。","steps":["A 不正确：Na 燃烧已生成过氧化物 Na₂O₂，K 生成 KO₂，更活泼的 Cs 在空气中燃烧绝不会只生成简单的 Cs₂O，而是生成过氧化物或超氧化物。","B、C、D 均符合 IA 族从上到下金属性增强的规律。"],"ans":"A","markingPoints":["识别燃烧产物由普通氧化物向过氧化物/超氧化物递变的规律"],"verification":"对照化上 p.221 与 p.233 选择题 10 核对。","pitfall":"机械套用化学价推式法误以为所有碱金属燃烧都只生成 M₂O。"},{"id":"chem9-9.1-q3","tier":"L2","tierLabel":"L2 期末","examStyle":"P2 简答","q":"工业上分别用不同方法冶炼金属钠和金属钾：(1) 写出电解熔融氯化钠制钠及钠热还原熔融氯化钾制钾的化学方程式；(2) 从化学平衡和物质物理性质解释：金属钠的金属性明明弱于钾，为什么高温下金属钠却能从熔融 \\(\\mathrm{KCl}\\) 中置换出金属钾？","given":"p.222 工业制法及表 9-2 沸点数据（Na 882.9 ℃，K 774 ℃）","method":"写出工业反应条件并利用沸点差异与平衡移动原理作答","principle":"高温下产物 K 汽化脱离液相反应体系，驱动平衡持续向右移动。","steps":["(1) 制钠：\\(2\\mathrm{NaCl(l)} \\xrightarrow{\\text{电解}} 2\\mathrm{Na(s)} + \\mathrm{Cl_2(g)}\\uparrow\\)；制钾：\\(\\mathrm{KCl(l)} + \\mathrm{Na(l)} \\xrightarrow{\\text{高温}} \\mathrm{NaCl(l)} + \\mathrm{K(g)}\\uparrow\\)。","(2) 高温熔融体系中存在可逆平衡 \\(\\mathrm{KCl + Na \\rightleftharpoons NaCl + K}\\)。因为金属钾的沸点（\\(774\\ ^\\circ\\mathrm{C}\\)）低于金属钠的沸点（\\(882.9\\ ^\\circ\\mathrm{C}\\)），控制温度使反应产生的钾不断变成钾蒸气逸出并被真空冷凝分离，降低生成物浓度从而促使反应持续正向进行。"],"ans":"(1) 2NaCl(l)—(电解)→2Na+Cl₂↑；KCl(l)+Na(l)—(高温)→NaCl(l)+K(g)↑；(2) 因钾沸点低于钠，高温下不断蒸出钾蒸气促使平衡向右移动。","markingPoints":["正确写出两方程式并标明状态、条件（2分）","点出 K 沸点（774 ℃）低于 Na（882.9 ℃）且不断分离气态钾使反应持续进行（2分）"],"verification":"教材 p.222 原文明确阐述“钾的沸点比钠低，不断地将钾的蒸气分离出去，就能使反应持续进行”。","pitfall":"若误答“高温下钠的还原性比钾强”是错误的原理表述。"},{"id":"chem9-9.1-q4","tier":"L3","tierLabel":"L3 预试","examStyle":"P1 选择","q":"将 \\(4.6\\text{ g}\\) 金属钠分别投入等体积（均足量）的水、\\(0.5\\text{ mol\\,L}^{-1}\\) 稀盐酸和硫酸铜溶液中（已知 \\(A_r(\\mathrm{Na})=23\\)），下列关于三个实验的比较**正确**的是（　）。","options":["A. 三个实验中金属钠放出的气体体积在同温同压下相等","B. 投入硫酸铜溶液的实验中，烧杯底部会析出大量红色铜单质","C. 钠投入稀盐酸中反应速率比投入纯水中更慢","D. 只有投入纯水中的反应才有气体产生"],"correctOption":"A","given":"n(Na) = 4.6 / 23 = 0.20 mol；三份溶液均足量","method":"依据钠在足量水溶液中完全反应均按 2Na ~ H₂↑ 定量放出氢气","principle":"足量水溶液中 Na 完全失去 0.20 mol 电子全部交给 H⁺，固定生成 0.10 mol H₂。","steps":["A 正确：三组中钠均作为限量反应物完全转化为 \\(\\mathrm{Na^+}\\)，转移电子数均为 \\(0.20\\text{ mol}\\)，故无论先与酸中的 \\(\\mathrm{H^+}\\) 反应还是与水反应，最终均生成 \\(0.10\\text{ mol}\\ \\mathrm{H_2}\\) 气体。","B 错误：投入硫酸铜溶液中生成蓝色 \\(\\mathrm{Cu(OH)_2}\\) 沉淀与 \\(\\mathrm{H_2}\\)，不会置换出红色铜。","C 错误：稀盐酸中 \\(\\mathrm{H^+}\\) 浓度远大于纯水，故反应速率更快更剧烈。","D 错误：三组均剧烈放出 \\(\\mathrm{H_2}\\)。"],"ans":"A","markingPoints":["运用电子守恒迅速确认足量液相条件下 2Na ~ H₂ 的恒定关系"],"verification":"无论溶剂是稀酸、纯水还是中性盐溶液，只要水/酸过量，2 mol Na 必生成 1 mol H₂。","pitfall":"误选 B 或忘记 Na 与酸反应也是放出 H₂。"},{"id":"chem9-9.1-q5","tier":"L4","tierLabel":"L4 统考压轴","examStyle":"P2 综合计算","q":"把 \\(7.8\\text{ g}\\) 过氧化钠（\\(\\mathrm{Na_2O_2}\\)）和 \\(4.6\\text{ g}\\) 金属钠共同放入 \\(100\\text{ g}\\) 水中，充分反应后恢复至室温（假设水完全过量且无蒸气损失）。试求：(1) 反应共产生标准状况下的混合气体总体积（保留三位有效数字）；(2) 将所得混合气体在密闭容器内用电火花引燃充分反应后，冷却至原温度与压强，容器内最终剩余什么气体？其体积在标况下是多少？（\\(A_r: \\mathrm{Na}=23, \\mathrm{O}=16\\)）","given":"n(Na₂O₂) = 7.8 / 78 = 0.100 mol; n(Na) = 4.6 / 23 = 0.200 mol","method":"分别写出两反应生成 H₂ 与 O₂ 的物质的量，再判断电火花引燃时 H₂ 与 O₂ 的限量关系","principle":"2Na₂O₂ + 2H₂O → 4NaOH + O₂↑；2Na + 2H₂O → 2NaOH + H₂↑；2H₂ + O₂ → 2H₂O。","steps":["计算反应物物质的量：\\(n(\\mathrm{Na_2O_2}) = \\frac{7.8}{78} = 0.100\\text{ mol}\\)，\\(n(\\mathrm{Na}) = \\frac{4.6}{23} = 0.200\\text{ mol}\\)。","由 \\(2\\mathrm{Na_2O_2} + 2\\mathrm{H_2O} \\to 4\\mathrm{NaOH} + \\mathrm{O_2}\\uparrow\\)，得 \\(n(\\mathrm{O_2}) = \\frac{1}{2} \\times 0.100 = 0.0500\\text{ mol}\\)。","由 \\(2\\mathrm{Na} + 2\\mathrm{H_2O} \\to 2\\mathrm{NaOH} + \\mathrm{H_2}\\uparrow\\)，得 \\(n(\\mathrm{H_2}) = \\frac{1}{2} \\times 0.200 = 0.100\\text{ mol}\\)。","第(1)问：产生混合气体总物质的量 \\(n_{\\text{总}} = 0.0500 + 0.100 = 0.150\\text{ mol}\\)，标况总体积 \\(V_{\\text{总}} = 0.150 \\times 22.4 = 3.36\\text{ L}\\)。","第(2)问：用电火花引燃发生 \\(2\\mathrm{H_2(g)} + \\mathrm{O_2(g)} \\xrightarrow{\\text{点燃}} 2\\mathrm{H_2O(l)}\\)。由于恰好满足 \\(n(\\mathrm{H_2}) : n(\\mathrm{O_2}) = 0.100 : 0.0500 = 2 : 1\\)，两者**恰好完全反应**生成液态水，故最终剩余气体体积为 **\\(0\\text{ L}\\)**（无气体剩余）。"],"ans":"(1) 混合气体标况总体积为 3.36 L；(2) H₂ 与 O₂ 恰好按 2:1 完全反应生成液态水，无气体剩余（0 L）。","markingPoints":["正确算出 n(O₂)=0.050 mol 与 n(H₂)=0.100 mol（2分）","求出混合气体总体积 3.36 L（1分）","判断出 H₂ 与 O₂ 为 2:1 恰好完全化合且室温下水为液态，故剩余气体 0 L（2分）"],"verification":"电子转移核对：Na 失 0.200 mol 电子生成 0.100 mol H₂，Na₂O₂ 歧化 0.100 mol 电子生成 0.050 mol O₂，反应后 H₂ 与 O₂ 化合正好转移 0.200 mol 电子。","pitfall":"若把 Na₂O₂ 反应产氧系数错写成 1:1（误得 0.100 mol O₂），会导致后面全部算错。"}],"cheatSheet":["密度对比：煤油（~0.80）< K（0.86）< Na（0.97）< 水（1.00）；Li（0.53）须存石蜡中。","钠与空气反应：常温白色 \\(\\mathrm{Na_2O}\\)；燃烧淡黄色 \\(\\mathrm{Na_2O_2}\\)；钾在纯氧燃烧得 \\(\\mathrm{KO_2}\\)。","钠入水五现象：“浮、熔、游、响、红”；失火用干燥细沙扑救，严禁用水或 CO₂。","工业制取：电解熔融 \\(\\mathrm{NaCl}\\) 得 Na；高温 Na 置换熔融 \\(\\mathrm{KCl}\\) 并蒸出 K 气（沸点 K < Na）。"],"kbEntryIds":["kb-chem9-alkali-props","kb-chem9-na-k-reactions"],"quiz":{"q":"将 \\(2.3\\text{ g}\\) 金属钠投入 \\(97.8\\text{ g}\\) 水中完全反应，求所得氢氧化钠溶液的质量分数（\\(A_r: \\mathrm{Na}=23, \\mathrm{H}=1, \\mathrm{O}=16\\)）。","given":"m(Na)=2.3 g (0.10 mol), m(H₂O)=97.8 g","method":"先求生成 NaOH 质量，再用质量守恒扣除逸出的 H₂ 质量得溶液总质量","principle":"2Na + 2H₂O → 2NaOH + H₂↑，溶液总质量 = 反应前总质量 − 逸出气体质量。","steps":["\\(n(\\mathrm{Na}) = 2.3/23 = 0.10\\text{ mol}\\)，生成 \\(n(\\mathrm{NaOH}) = 0.10\\text{ mol}\\)（质量 \\(0.10 \\times 40 = 4.0\\text{ g}\\)）。","生成 \\(n(\\mathrm{H_2}) = 0.050\\text{ mol}\\)（质量 \\(0.050 \\times 2 = 0.10\\text{ g}\\)）。","溶液总质量 \\(= 2.3 + 97.8 - 0.10 = 100.0\\text{ g}\\)，故质量分数 \\(= \\frac{4.0}{100.0} \\times 100\\% = 4.0\\%\\)。"],"ans":"\\(4.0\\%\\)"}},{"id":"9.2","t":"焰色试验","anchor":{"pages":"化上 p.223–225","syllabus":"3.2.3 焰色试验操作方法、常见金属焰色及原子光谱成因","examScopes":["sem2_final","uec"],"examWeight":"P1 操作正误判断 + P2 金属离子鉴别步骤得分关键字","terms":"Flame test · Platinum wire · Cobalt blue glass · Atomic emission spectrum","prerequisites":["能阶跃迁与原子发射光谱基础（化上 Ch 5.3）","碱金属及其盐类基本概念（9.1）"],"goals":["熟练复述“洗、烧、蘸、烧、洗”的焰色试验标准实验步骤及铂丝（或光洁无锈铁丝）洗涤原理。","牢记锂、钠、钾、钙、铜的特征火焰颜色，并准确解释检验钾元素时使用蓝色钴玻璃的作用。","辨明焰色试验属于元素的物理性质（物理变化），无论游离态金属还是化合态盐溶液均呈现相同特征焰色。"]},"concepts":[{"kind":"experiment","title":"活动探究 1（活动 6–7）：焰色试验操作规范与注意事项","pageRef":"化上 p.223","body":["**实验步骤五字诀**：","- ① **洗**：用**稀盐酸**洗净焊在玻璃棒上的铂丝（或光洁无锈的铁丝）——因金属氯化物在高温下较易挥发，便于灼烧除净杂质。","- ② **烧**：将洗净的铂丝放在酒精灯（最好用几乎无色的煤气灯）**外焰**上灼烧，直至火焰与**原来的火焰颜色相同**为止。","- ③ **蘸**：用洁净铂丝蘸取待测液（如 \\(\\mathrm{Na_2CO_3}\\) 或 \\(\\mathrm{K_2CO_3}\\) 溶液或固体粉末）。","- ④ **烧**：放在外焰上灼烧并观察颜色。观察钾盐时，**必须透过蓝色钴玻璃**观察。","- ⑤ **洗**：每次实验后，必须再次用稀盐酸洗净铂丝并灼烧至无色，再做下一次测试。","**工具替代限制**：没有铂丝时可用**光洁无锈的铁丝**代替（铁在火焰中不产生干扰显色），但**绝对不可用铜丝**（铜自身有绿色焰色干扰）或直接用普通玻璃棒（玻璃含硅酸钠，本身显黄色焰色！）。"],"takeaway":"千万不能用稀硫酸洗铂丝！硫酸盐沸点高不易挥发，残留硫酸盐会长期污染铂丝！"},{"kind":"table","title":"教材常见金属特征焰色一览表（图 9-4 & 10.4）","pageRef":"化上 p.224、p.248","body":["许多金属及其化合物在无色火焰上灼烧时会呈现特征颜色，据此可**初步检验**金属或金属离子的存在（注意：只能定性检验金属元素本身，无法判断是哪种阴离子）。"],"table":{"headers":["金属元素","特征焰色","观察注意事项"],"rows":[["锂（Li / Li⁺）","紫红色 / 红色","直接观察（图 9-4）"],["钠（Na / Na⁺）","黄色","极灵敏，痕量钠即可发出明亮黄光"],["钾（K / K⁺）","浅紫色","必须透过蓝色钴玻璃滤去钠黄光干扰"],["钙（Ca / Ca²⁺）","砖红色","结合草酸铵沉淀综合确认（p.248）"],["铜（Cu / Cu²⁺）","绿色 / 蓝绿色","故不能用铜丝替代铂丝作焰色试验"]]},"takeaway":"节日烟花的五彩缤纷正是利用了不同金属盐的焰色反应原理（图 9-3）。"},{"kind":"mechanism","title":"金属焰色的微观成因（资料链接）与物理变化属性","pageRef":"化上 p.224–225","body":["**量子能阶解释（p.224）**：进行焰色试验时，金属原子或离子核外处于基态的电子从火焰中吸收一定热量能量，被激发跃迁到高能阶的**激发态**；激发态极不稳定，电子迅速回落到较低能阶（基态）时，就会放出具有**一定能量、一定波长**的光子形成光谱谱线，落在可见光区便呈现各元素特征的火焰颜色。","**核心物理变化属性**：焰色试验过程中**没有新物质生成**，纯粹是原子内部电子能级跃迁发光，属于**物理变化**。因此，无论是金属单质 \\(\\mathrm{Na}\\) 还是离子化合物 \\(\\mathrm{NaCl}\\)、\\(\\mathrm{Na_2CO_3}\\)，灼烧时均呈现完全相同的黄色火焰。"],"takeaway":"焰色试验是“元素的性质”，不是“某一种离子独有的化学反应”；玻璃含钠元素，故玻璃管口点燃 H₂ 或 CO 火焰泛黄（p.225 思考题 9b-3）。"}],"formulas":[{"title":"电子能级跃迁发射特征光子公式（衔接第 5 章）","tex":"\\Delta E = E_{\\text{激发态}} - E_{\\text{基态}} = h\\nu = \\frac{hc}{\\lambda}","plain":"ΔE = E_激发态 - E_基态 = hν = hc / λ","conditions":"每种元素原子能阶差 ΔE 固定唯一，故发射光波长 λ 为元素指纹特征","pageRef":"化上 p.224","note":"同种元素的单质与盐在高温火焰下蒸发的原子具有相同能阶结构，故焰色相同。"},{"title":"蓝色钴玻璃滤光原理示意","tex":"\\text{复合焰色光}\\;(\\text{浅紫} + \\text{黄干扰}) \\xrightarrow{\\text{蓝色钴玻璃（吸收黄光）}} \\text{透射浅紫色光}\\;(\\mathrm{K^+}\\text{ 特征})","plain":"复合焰色光(浅紫+黄) → [蓝色钴玻璃吸收黄光] → 浅紫色(K⁺)","conditions":"钾盐中常混有微量钠盐杂质，黄光极强会掩盖浅紫色","pageRef":"化上 p.223","note":"即使待测液看起来很纯，实验室规范检验 K⁺ 仍必须透过蓝色钴玻璃。"}],"pitfalls":[{"title":"误把焰色试验归类为化学变化","wrong":"“氯化钠做焰色试验时火焰呈黄色，是因为氯化钠在火焰中分解生成了金属钠并与氧气发生化学反应。”","diagnosis":"混淆了物理光发射与化学反应；高温并未把 Na⁺ 还原为单质钠，只是电子受热激发后跃迁回落发射光谱。","right":"焰色试验属于**物理变化**，是钠元素的原子光谱特征；\\(\\mathrm{Na}\\) 与 \\(\\mathrm{Na^+}\\) 焰色相同（p.232 练习 4）。","checkRule":"选择题问“焰色反应是否属于化学变化”，一律判“否（物理变化）”。"},{"title":"误用玻璃棒、铜丝或稀硫酸做焰色试验","wrong":"“实验室找不到铂丝时，可以直接用玻璃棒蘸取待测液，或者用稀硫酸洗涤铁丝。”","diagnosis":"玻璃的主要成分含有硅酸钠（\\(\\mathrm{Na_2SiO_3}\\)），本身会发出明亮黄光干扰实验；硫酸洗后生成难挥发的硫酸盐残留铁丝上洗不干净。","right":"只能用**铂丝**或**光洁无锈的铁丝**，并且只能用**稀盐酸**洗涤（氯化物易挥发，灼烧即可彻底除去）。","checkRule":"牢记：铁丝行、铜丝不行、玻璃棒不行；稀盐酸行、稀硫酸/水洗不行。"}],"examples":[{"label":"例 9.2.1","tier":"L2","tierLabel":"L2 期末必考","title":"无标签四瓶溶液（NaCl、KCl、Na₂CO₃、K₂CO₃）鉴别设计（p.234 习题 6）","prompt":"实验室现有四瓶失去标签的无色溶液，已知分别是 \\(\\mathrm{NaCl}\\)、\\(\\mathrm{KCl}\\)、\\(\\mathrm{Na_2CO_3}\\) 和 \\(\\mathrm{K_2CO_3}\\)。请设计一套简明、现象明显的化学与物理联合鉴别方案将它们全部区分开。","clues":"四种物质本质上是两种阳离子（\\(\\mathrm{Na^+}, \\mathrm{K^+}\\)）与两种阴离子（\\(\\mathrm{Cl^-}, \\mathrm{CO_3^{2-}}\\)）的 2×2 组合！分两步先分阴离子、再分阳离子（或反之）即可一次搞定。","strategy":"第一步用稀盐酸（或 \\(\\mathrm{BaCl_2}\\)）区分氯化物与碳酸盐；第二步对各组用焰色试验（含蓝色钴玻璃）区分 \\(\\mathrm{Na^+}\\) 与 \\(\\mathrm{K^+}\\)。","given":"四瓶未知溶液：NaCl, KCl, Na₂CO₃, K₂CO₃","principle":"CO₃²⁻ + 2H⁺ → CO₂↑ + H₂O；Na⁺ 黄色焰色，K⁺ 透钴玻璃浅紫色焰色。","steps":["**第一步（鉴别阴离子，分为两组）**：分别取四瓶溶液少许于 4 支编号试管中，各滴加足量稀盐酸（或 \\(\\mathrm{CaCl_2}\\) 溶液）。","- 立即产生无色无味气泡（加 \\(\\mathrm{CaCl_2}\\) 则生白色沉淀）的两瓶为碳酸盐组（\\(\\mathrm{Na_2CO_3}\\) 与 \\(\\mathrm{K_2CO_3}\\)）；无明显现象的两瓶为氯化物组（\\(\\mathrm{NaCl}\\) 与 \\(\\mathrm{KCl}\\)）。","**第二步（鉴别阳离子，做焰色试验）**：用稀盐酸洗净并灼烧至无色的铂丝，分别蘸取四瓶原溶液在酒精灯外焰上灼烧：","- 氯化物组中，直接观察火焰呈**黄色**的为 **\\(\\mathrm{NaCl}\\)**；透过**蓝色钴玻璃**观察火焰呈**浅紫色**的为 **\\(\\mathrm{KCl}\\)**。","- 碳酸盐组中，火焰呈**黄色**的为 **\\(\\mathrm{Na_2CO_3}\\)**；透过**蓝色钴玻璃**观察火焰呈**浅紫色**的为 **\\(\\mathrm{K_2CO_3}\\)**。"],"answer":"先加稀盐酸按“有无气泡”分出碳酸盐与氯化物，再用洁净铂丝作焰色试验（K⁺ 透过蓝色钴玻璃看浅紫色，Na⁺ 看黄色）一一确认。","markingPoints":["第一步准确选择稀盐酸或 CaCl₂ 区分 CO₃²⁻ 与 Cl⁻ 并写出气泡/沉淀现象（2分）","第二步规范描述铂丝盐酸洗净灼烧及蓝色钴玻璃观察 K⁺ 浅紫色（2分）","完整对应出全部四种物质标签（1分）"],"verification":"每步互不干扰，避免仅用 AgNO₃（Ag₂CO₃ 也是沉淀，加酸才能排除 CO₃²⁻ 干扰）。","pitfall":"不可在第二步直接蘸取“第一步加完盐酸后残留的试管溶液”，虽然金属离子还在，但规范实验应取原待测液少许；若用 AgNO₃ 检验 Cl⁻，必须先加稀硝酸酸化排除 CO₃²⁻ 干扰。"},{"label":"例 9.2.2","tier":"L3","tierLabel":"L3 预试拔高","title":"混合盐焰色试验现象推断与原理辨析","prompt":"某白色固体粉末可能是 \\(\\mathrm{NaCl}\\)、\\(\\mathrm{KNO_3}\\)、\\(\\mathrm{CuSO_4}\\) 和 \\(\\mathrm{CaCO_3}\\) 中的一种或几种。某同学取少量该粉末溶于足量水，充分搅拌后得**无色澄清溶液**；接着用稀盐酸洗净并灼烧至无色的铂丝蘸取该溶液，放在煤气灯外焰灼烧，直接观察到**黄色火焰**；再透过蓝色钴玻璃观察，发现火焰呈**浅紫色**。请判断原白色粉末的组成并说明理由。","clues":"“无色澄清溶液”先排除有色离子和难溶物；黄色焰色确认 \\(\\mathrm{Na^+}\\)，透钴玻璃浅紫色确认 \\(\\mathrm{K^+}\\)。","strategy":"溶解外观排查难溶/有色盐 → 焰色双条件锁定阳离子 → 注意尚未检验阴离子（或已能唯一对应各阳离子来源盐）。","given":"候选：NaCl, KNO₃, CuSO₄, CaCO₃；水溶无色澄清；直接黄光，透钴玻璃浅紫","principle":"物质溶解性与颜色、焰色反应特征及蓝色钴玻璃滤光原理。","steps":["粉末溶于水得**无色澄清溶液**：由于 \\(\\mathrm{CaCO_3}\\) 难溶于水，\\(\\mathrm{CuSO_4}\\) 溶液呈蓝色，故原粉末中**一定不含 \\(\\mathrm{CaCO_3}\\) 和 \\(\\mathrm{CuSO_4}\\)**。","直接观察火焰呈黄色，说明溶液中一定含有 \\(\\mathrm{Na^+}\\)，在候选盐中只能来自 **\\(\\mathrm{NaCl}\\)**。","透过蓝色钴玻璃滤去黄色光后观察到浅紫色火焰，说明溶液中一定含有 \\(\\mathrm{K^+}\\)，在候选盐中只能来自 **\\(\\mathrm{KNO_3}\\)**。"],"answer":"原白色粉末**一定含有 \\(\\mathrm{NaCl}\\) 和 \\(\\mathrm{KNO_3}\\)**，**一定不含 \\(\\mathrm{CuSO_4}\\) 和 \\(\\mathrm{CaCO_3}\\)**。","markingPoints":["由“无色澄清”排除 CaCO₃ 与 CuSO₄（2分）","由直接黄色焰色确定 NaCl（1分）","由透钴玻璃浅紫色确定 KNO₃（1分）"],"verification":"NaCl 与 KNO₃ 混合溶于水不反应且无色澄清，符合所有条件。","pitfall":"若没看到“透过蓝色钴玻璃呈浅紫色”，仅看到黄色时，只能证明含 Na⁺，不能排除微量 K⁺ 是否存在；本题两者皆明确观测到，故可确定均存在。"}],"practice":[{"id":"chem9-9.2-q1","tier":"L1","tierLabel":"L1 基础","examStyle":"P1 选择","q":"观察钾盐焰色反应时，必须透过蓝色钴玻璃观察，其目的是（　）。","options":["A. 使火焰温度升高，让钾盐更易气化","B. 吸收钾发出的紫色光，保护实验者眼睛","C. 滤去杂质钠盐发出的黄色光干扰","D. 与挥发出的氯化钾反应产生紫色络合物"],"correctOption":"C","given":"p.223 活动 7","method":"对照教材蓝色钴玻璃滤光注释","principle":"蓝色钴玻璃吸收黄光而透过蓝紫光，排除微量钠污染干扰。","steps":["钠盐黄光极其灵敏明亮，会完全掩盖钾的浅紫色；蓝色钴玻璃在光学上吸收黄光波长，使浅紫色显现。"],"ans":"C","markingPoints":["理解蓝色钴玻璃滤黄光作用"],"verification":"教材 p.223 原文标注“蓝色钴玻璃的作用是滤去黄色的光，避免碳酸钾中所含的微量钠盐造成干扰”。","pitfall":"误选 A 或 D 把光学滤光误解为化学反应或升温。"},{"id":"chem9-9.2-q2","tier":"L2","tierLabel":"L2 期末","examStyle":"P1 选择","q":"下列关于焰色试验操作注意事项的说法（教材 p.233 第 9 题），正确的是（　）。\n①钾的火焰颜色要透过蓝色钴玻璃观察；②先将铂丝灼烧到与原来火焰的颜色相同，再蘸取被检验的物质；③每次实验后，要用稀盐酸洗净铂丝；④实验时最好选择本身颜色较浅的火焰；⑤没有铂丝时，也可用光洁无锈的铁丝代替。","options":["A. 只有③不正确","B. 只有④不正确","C. 只有⑤不正确","D. 全部正确"],"correctOption":"D","given":"p.233 教材选择题 9 原题","method":"逐条对照活动探究 1 规范核查","principle":"稀盐酸洗铂丝使杂质成易挥发氯化物，浅色火焰不掩盖特征焰色，光洁无锈铁丝不呈显色。","steps":["①②③④⑤ 五项操作细节全部严格符合教材 p.223 活动 6–7 的实验规范，因此全部正确。"],"ans":"D","markingPoints":["全面掌握焰色试验 5 项实验细节"],"verification":"化上 p.223 活动探究 1 原文逐句印证。","pitfall":"误以为铁丝不能替代铂丝而错选 C。"},{"id":"chem9-9.2-q3","tier":"L3","tierLabel":"L3 预试","examStyle":"P2 简答","q":"（教材 p.225 思考题 9b-3）纯碱（\\(\\mathrm{Na_2CO_3}\\)）是制造普通玻璃的主要原料之一。在实验室中，当在玻璃管口点燃纯净的氢气或一氧化碳气体时，观察到火焰常常呈现黄色。由此能否说明氢气或一氧化碳本身燃烧的火焰呈黄色？请从微粒发光机理简要解释原因。","given":"玻璃含 Na₂SiO₃，纯净 H₂/CO 火焰原本分别为淡蓝色/浅蓝色","method":"区分气体自身燃烧焰色与玻璃管壁钠元素的焰色反应","principle":"高温火焰加热玻璃管口使玻璃中的 Na⁺ 电子受激跃迁发光，掩盖气体本身火焰颜色。","steps":["不能说明氢气或一氧化碳本身的火焰为黄色。","原因：普通玻璃中含有钠的硅酸盐（来自原料纯碱 \\(\\mathrm{Na_2CO_3}\\)）。点燃气体时，高温外焰加热玻璃管口，使其中的 \\(\\mathrm{Na^+}\\) 核外电子吸收能量跃迁至激发态，回落基态时发射出钠元素的特征黄色光谱，从而使火焰看起来呈黄色（实际纯净 \\(\\mathrm{H_2}\\) 燃烧为淡蓝色、\\(\\mathrm{CO}\\) 为浅蓝色）。"],"ans":"不能；黄色是由玻璃管所含钠元素的焰色反应引起的，纯净 H₂ 与 CO 自身火焰呈淡/浅蓝色。","markingPoints":["明确回答“不能”（1分）","指出玻璃原料含纯碱/钠元素，高温下钠发生焰色反应发黄光（2分）"],"verification":"对照教材 p.224 焰色成因与 p.225 思考题 9b-3 核对。","pitfall":"未指出“玻璃管含钠元素”，只写“有杂质”不够精准。"},{"id":"chem9-9.2-q4","tier":"L4","tierLabel":"L4 统考压轴","examStyle":"P2 实验探究","q":"某同学想用焰色试验检验一瓶固体样品中是否同时含有 \\(\\mathrm{Na^+}\\)、\\(\\mathrm{K^+}\\) 和 \\(\\mathrm{Cu^{2+}}\\)。他先用稀硫酸洗净铜丝，烧红后立即蘸取样品放在酒精灯内焰灼烧，发现火焰呈亮绿色，便得出“样品只含 \\(\\mathrm{Cu^{2+}}\\)、不含 \\(\\mathrm{Na^+}\\) 和 \\(\\mathrm{K^+}\\)”的结论。请指出该同学实验操作与推理中的 **4 处错误**，并给出正确改进方案。","given":"错误操作：稀硫酸洗涤、铜丝、内焰灼烧、仅凭亮绿否定 Na⁺/K⁺","method":"逐项对照焰色试验五步标准及干扰排查规律","principle":"试剂选稀盐酸、金属丝选铂/铁丝、外焰温度高且无色、铜绿色光与钠黄光相互干扰须联合检验。","steps":["错误 1：**使用铜丝**。铜本身焰色呈绿色，会直接假阳性干扰 \\(\\mathrm{Cu^{2+}}\\) 判断，应改用**铂丝或光洁无锈铁丝**。","错误 2：**使用稀硫酸洗涤**。硫酸盐不易挥发，灼烧无法除尽杂质，应改用**稀盐酸**，并在外焰灼烧至火焰与原火焰颜色相同后再蘸样。","错误 3：**在内焰灼烧**。酒精灯内焰温度低且常有不完全燃烧炭黑发光干扰，应放在**外焰**（或无色煤气灯外焰）灼烧。","错误 4：**推理错误**。铜丝自身发出的亮绿色或微量杂质遮蔽下不可直接否定 \\(\\mathrm{Na^+}/\\mathrm{K^+}\\)；且检验 \\(\\mathrm{K^+}\\) 必须**透过蓝色钴玻璃**排除黄光干扰，而 \\(\\mathrm{Cu^{2+}}\\) 更宜结合水溶液蓝色及加氨水生成深蓝色络合物（或加 \\(\\mathrm{NaOH}\\) 生蓝色沉淀）综合确认。"],"ans":"4 处错误：①用铜丝（应改铂/铁丝）；②用稀硫酸洗（应改稀盐酸并烧至无色）；③放内焰烧（应放外焰）；④未透蓝色钴玻璃看 K⁺ 且用铜丝绿色误判样品含 Cu²⁺（Cu²⁺ 宜辅助溶液沉淀法确认）。","markingPoints":["指出铜丝自身发绿光干扰及改用铂/铁丝（1分）","指出稀硫酸难挥发应改稀盐酸并灼烧至无色（1分）","指出应在外焰灼烧（1分）","指出测 K⁺ 须用蓝色钴玻璃且推理不可单靠错用铜丝下结论（1分）"],"verification":"4 处错误覆盖仪器材质、洗涤酸、火焰区、光学滤色推理四维考点。","pitfall":"容易漏掉“在内焰灼烧”这一隐蔽操作错误。"}],"cheatSheet":["焰色操作五字诀：稀盐酸洗 → 外焰烧至无色 → 蘸取样品 → 外焰烧观察 → 盐酸再洗。","器材禁忌：可用铂丝或光洁无锈铁丝；严禁用铜丝（绿光干扰）、玻璃棒（含钠黄光）、稀硫酸洗（难挥发）。","颜色速记：Li 红（紫红）、Na 黄、K 浅紫（须透蓝色钴玻璃）、Ca 砖红、Cu 绿/蓝绿。","变化本质：电子受激跃迁发射特征光谱，属于物理变化（元素性质，Na 与 Na⁺ 同色）。"],"kbEntryIds":["kb-chem9-flame-test"],"quiz":{"q":"某溶液做焰色试验时直接观察呈黄色火焰，透过蓝色钴玻璃观察却未看到浅紫色火焰，则该溶液中关于 \\(\\mathrm{Na^+}\\) 与 \\(\\mathrm{K^+}\\) 的结论是什么？","given":"直接观察：黄色；透蓝色钴玻璃：无浅紫色","method":"利用钴玻璃滤除黄光后的结果判断 K⁺ 是否存在","principle":"Na⁺ 发黄光，K⁺ 须透蓝色钴玻璃才可确认。","steps":["直接呈黄色确认含 \\(\\mathrm{Na^+}\\)；蓝色钴玻璃滤去黄光后仍无浅紫色，说明不含 \\(\\mathrm{K^+}\\)。"],"ans":"一定含有 \\(\\mathrm{Na^+}\\)，不含 \\(\\mathrm{K^+}\\)。"}},{"id":"9.3","t":"钠和钾的重要化合物","anchor":{"pages":"化上 p.225–230","syllabus":"3.2.4 氯化钠、氢氧化钠、碳酸钠、碳酸氢钠及硝酸钾的性质、转化与工业制法","examScopes":["sem2_final","uec"],"examWeight":"P1 鉴别除杂 + P2 氯碱工业/氨碱转化流程及热稳定性探究","terms":"Chlor-alkali industry · Caustic soda (NaOH) · Soda ash (Na₂CO₃) · Baking soda (NaHCO₃) · Thermal stability","prerequisites":["酸碱盐复分解与离子方程式书写","钠和钾单质氧化还原基础（9.1）"],"goals":["写出氯碱工业离子膜电解槽（图 9-7）的总反应方程式及阳极、阴极产物与阳离子膜作用。","解释 NaOH 易潮解吸 CO₂ 变质与腐蚀玻璃塞的原因，并设计两套独立实验方案检验 NaOH 是否变质（p.226 问题解决）。","全面对比 Na₂CO₃（纯碱）与 NaHCO₃（小苏打）在水溶性（活动 10）、热稳定性（活动 11）、与盐酸反应剧烈程度（活动 12）的差异并熟练实现两者的相互转化与除杂。"]},"concepts":[{"kind":"mechanism","title":"氯化钠、氯碱工业（图 9-7）与氢氧化钠的腐蚀及变质检验","pageRef":"化上 p.225–227","body":["**氯化钠与氯化钾**：\\(\\mathrm{NaCl}\\)（熔点 801 ℃，沸点 1413 ℃）主要来自海盐、岩盐和井盐；\\(\\mathrm{KCl}\\)（熔点 770 ℃）用于临床电解质平衡调节药及钾肥。图 9-5、9-6 展示海水蒸发结晶晒盐。","**氯碱工业（图 9-7）**：利用**阳离子交换膜电解槽**电解饱和食盐水，同时获得 **\\(\\mathrm{NaOH}\\)、\\(\\mathrm{Cl_2}\\) 和 \\(\\mathrm{H_2}\\)**：阳极室 \\(\\mathrm{Cl^-}\\) 失电子生成 \\(\\mathrm{Cl_2}\\)，阴极室 \\(\\mathrm{H_2O}\\) 得电子生成 \\(\\mathrm{H_2}\\) 和 \\(\\mathrm{OH^-}\\)，阳离子膜只允许 \\(\\mathrm{Na^+}\\) 通过进入阴极室，防止 \\(\\mathrm{Cl_2}\\) 与 \\(\\mathrm{NaOH}\\) 或 \\(\\mathrm{H_2}\\) 混合。","**氢氧化钠（烧碱/火碱/苛性钠）三性**：①**吸湿潮解并吸 \\(\\mathrm{CO_2}\\) 变质**：\\(\\mathrm{CO_2 + 2NaOH \\to Na_2CO_3 + H_2O}\\)；②**腐蚀玻璃（\\(\\mathrm{SiO_2}\\)）**：\\(\\mathrm{SiO_2 + 2NaOH \\to Na_2SiO_3 + H_2O}\\)（黏性硅酸钠粘住玻璃塞，故必须用**橡皮塞**）；③**与两性金属反应**：\\(2\\mathrm{Al + 2NaOH + 2H_2O \\to 2NaAlO_2 + 3H_2\\uparrow}\\)。","**p.226 问题解决（检验 NaOH 是否变质二法）**：①取样加水溶解后滴加**足量稀盐酸**，若有气泡生成证明含 \\(\\mathrm{Na_2CO_3}\\)（已变质）；②取样加水溶解后滴加 **\\(\\mathrm{BaCl_2}\\) 或 \\(\\mathrm{CaCl_2}\\) 溶液**，若生成白色沉淀（\\(\\mathrm{BaCO_3\\downarrow}\\) / \\(\\mathrm{CaCO_3\\downarrow}\\)）证明已变质（且可先加过量 \\(\\mathrm{BaCl_2}\\) 除尽 \\(\\mathrm{CO_3^{2-}}\\) 后，上层清液滴酚酞判断是部分变质还是全部变质！）。"],"takeaway":"绝不可直接用酚酞试液检验 NaOH 是否变质，因为变质产物 Na₂CO₃ 水溶液同样呈碱性，也会使酚酞变红！"},{"kind":"table","title":"活动探究 2–4：Na₂CO₃（纯碱）与 NaHCO₃（小苏打）性质全对比","pageRef":"化上 p.227–230","body":["\\(\\mathrm{Na_2CO_3}\\)（俗称纯碱、苏打，结晶水合物 \\(\\mathrm{Na_2CO_3\\cdot 10H_2O}\\) 俗称碱块）与 \\(\\mathrm{NaHCO_3}\\)（俗称小苏打）在溶解性、热稳定性与酸反应上存在显著差异，是考试高频鉴别依据。"],"table":{"headers":["比较项目","碳酸钠（Na₂CO₃，纯碱/苏打）","碳酸氢钠（NaHCO₃，小苏打）"],"rows":[["外观与溶解性（活动 10）","白色粉末，加水放热并较快完全溶解（溶解度较大）","白色细小粉末，加水溶解度明显小于 Na₂CO₃（部分不溶）"],["水溶液酸碱性（活动 9–10）","显较强碱性（滴酚酞深红色），热纯碱液可去油污","显弱碱性（同浓度滴酚酞浅红色，碱性：Na₂CO₃ > NaHCO₃）"],["热稳定性（活动 11 图 9-8）","受热极稳定，不分解（可用作熔融试剂）","受热易分解：2NaHCO₃ —(△)→ Na₂CO₃ + H₂O + CO₂↑（管口有水珠、石灰水浑浊）"],["与稀盐酸反应速率（活动 12）","反应较慢（先 CO₃²⁻+H⁺→HCO₃⁻，再生成 CO₂↑）","反应极剧烈（一步完成 HCO₃⁻+H⁺→CO₂↑+H₂O）"],["与 CaCl₂ / BaCl₂ 溶液","产生白色沉淀（CaCO₃↓ / BaCO₃↓，活动 8）","一般不产生沉淀（与澄清石灰水 Ca(OH)₂ 两者均生成 CaCO₃↓）"],["相互转化路径","向饱和 Na₂CO₃ 溶液通 CO₂ → 析出 NaHCO₃ 晶体","加热固体或向溶液中加适量 NaOH → 转化为 Na₂CO₃"]]},"takeaway":"鉴别 Na₂CO₃ 与 NaHCO₃ 溶液时，可用 CaCl₂（仅 Na₂CO₃ 沉淀）或逐滴加稀盐酸观察是否“立即产气泡”，但**绝不能用澄清石灰水**（两者都会产生 CaCO₃ 白色沉淀）！"},{"kind":"definition","title":"硝酸钾（KNO₃）的性质与用途及除杂技巧","pageRef":"化上 p.230","body":["**硝酸钾（\\(\\mathrm{KNO_3}\\)）**：白色颗粒或结晶性粉末，易溶于水且**溶于水时显著吸热使溶液温度降低**；在空气中**不吸潮**，加热时具强氧化性并分解放出氧气：\\(2\\mathrm{KNO_3(s)} \\xrightarrow{\\Delta} 2\\mathrm{KNO_2(s)} + \\mathrm{O_2(g)}\\uparrow\\)。","**核心用途**：制造黑火药（一硫二硝三木炭）及含氮、钾两种营养元素的优质复合化肥（占全球产量 70%）。","**思考题 9c-2 除杂实战**：除去混在 \\(\\mathrm{Na_2CO_3}\\) 粉末中的 \\(\\mathrm{NaHCO_3}\\)，最简便无残留的方法是**充分加热（至质量不再减轻）**，使 \\(\\mathrm{NaHCO_3}\\) 全部分解为 \\(\\mathrm{Na_2CO_3}\\)、\\(\\mathrm{CO_2}\\) 和水蒸气逸出。"],"takeaway":"“固体除杂用加热，溶液除杂看目标”：除去 Na₂CO₃ 固体中的 NaHCO₃ 用加热；除去 Na₂CO₃ 溶液中的 NaHCO₃ 加适量 NaOH；除去 NaHCO₃ 溶液中的 Na₂CO₃ 通足量 CO₂。"}],"formulas":[{"title":"氯碱工业离子膜电解反应","tex":"2\\mathrm{NaCl(aq)} + 2\\mathrm{H_2O(l)} \\xrightarrow{\\text{电解}} 2\\mathrm{NaOH(aq)} + \\mathrm{Cl_2(g)}\\uparrow + \\mathrm{H_2(g)}\\uparrow","plain":"2NaCl(aq) + 2H2O(l) —(电解)→ 2NaOH(aq) + Cl2↑ + H2↑","conditions":"饱和食盐水，阳离子交换膜隔开阳极室与阴极室","pageRef":"化上 p.226–227","note":"阳极得 Cl₂，阴极得 H₂ 和 NaOH，切勿混淆电极产物。"},{"title":"碳酸钠与碳酸氢钠相互转化方程式","tex":"\\mathrm{Na_2CO_3(aq)} + \\mathrm{CO_2(g)} + \\mathrm{H_2O(l)} \\longrightarrow 2\\mathrm{NaHCO_3(s)}\\downarrow,\\qquad 2\\mathrm{NaHCO_3(s)} \\xrightarrow{\\Delta} \\mathrm{Na_2CO_3(s)} + \\mathrm{H_2O(l)} + \\mathrm{CO_2(g)}\\uparrow","plain":"Na2CO3 + CO2 + H2O → 2NaHCO3↓; 2NaHCO3 —(△)→ Na2CO3 + H2O + CO2↑","conditions":"前式因 NaHCO₃ 溶解度较小而在饱和液中结晶析出；后式用于焙制面包蓬松及鉴别/除杂","pageRef":"化上 p.230","note":"溶液中 NaHCO₃ 与 NaOH 反应离子式：HCO₃⁻ + OH⁻ → CO₃²⁻ + H₂O。"},{"title":"硝酸钾受热分解反应","tex":"2\\mathrm{KNO_3(s)} \\xrightarrow{\\Delta} 2\\mathrm{KNO_2(s)} + \\mathrm{O_2(g)}\\uparrow","plain":"2KNO3(s) —(△)→ 2KNO2(s) + O2(g)↑","conditions":"固态加热，产物为亚硝酸钾与氧气（非 NO₂）","pageRef":"化上 p.230","note":"金属活泼性高的 IA 族硝酸盐加热仅分解成亚硝酸盐与氧气（衔接 Ch 13.4）。"}],"pitfalls":[{"title":"加热 NaHCO₃ 实验（图 9-8）试管口向上倾斜导致炸裂","wrong":"“组装加热碳酸氢钠固体分解装置时，试管口应略向上倾斜，便于气体往上逸出。”","diagnosis":"忽视反应有水生成！冷凝水倒流至灼热的试管底部会使玻璃受冷不均而炸裂。","right":"图 9-8 中盛固体 \\(\\mathrm{NaHCO_3}\\) 的试管口必须**略向下倾斜**，且实验结束时应先将导管移出澄清石灰水再熄灭酒精灯（防倒吸）。","checkRule":"凡是“加热固体且可能产生水（或含结晶水）”，试管口一律略向下倾斜。"},{"title":"用澄清石灰水鉴别 Na₂CO₃ 和 NaHCO₃ 溶液","wrong":"“向两瓶溶液中分别滴加澄清石灰水 \\(\\mathrm{Ca(OH)_2}\\)，产生白色沉淀的是 \\(\\mathrm{Na_2CO_3}\\)，不沉淀的是 \\(\\mathrm{NaHCO_3}\\)。”","diagnosis":"忽略了 \\(\\mathrm{OH^-}\\) 会先把 \\(\\mathrm{HCO_3^-}\\) 转化为 \\(\\mathrm{CO_3^{2-}}\\)，同样立即生成 \\(\\mathrm{CaCO_3}\\) 沉淀！","right":"\\(\\mathrm{Na_2CO_3}\\) 与 \\(\\mathrm{NaHCO_3}\\) 遇澄清石灰水**都会产生白色 \\(\\mathrm{CaCO_3}\\) 沉淀**；必须改用 **\\(\\mathrm{CaCl_2}\\) 或 \\(\\mathrm{BaCl_2}\\) 溶液**（只与 \\(\\mathrm{Na_2CO_3}\\) 沉淀）。","checkRule":"区分 CO₃²⁻ 与 HCO₃⁻ 只能用中性钙/钡盐（CaCl₂/BaCl₂），严禁用强碱钙/钡溶液（Ca(OH)₂/Ba(OH)₂）。"},{"title":"误把等质量纯碱与小苏打产气量记反","wrong":"“等质量的 \\(\\mathrm{Na_2CO_3}\\) 和 \\(\\mathrm{NaHCO_3}\\) 分别与足量稀盐酸反应，\\(\\mathrm{Na_2CO_3}\\) 产生的 \\(\\mathrm{CO_2}\\) 更多、更快。”","diagnosis":"式量算反：\\(M(\\mathrm{Na_2CO_3}) = 106\\text{ g/mol}\\)，\\(M(\\mathrm{NaHCO_3}) = 84\\text{ g/mol}\\)，两者每摩尔均含 1 mol C。","right":"等**质量**时，\\(\\mathrm{NaHCO_3}\\) 式量更小、物质的量更多，因此产生 \\(\\mathrm{CO_2}\\) **既更快又更多**（且消耗 HCl 更少）。","checkRule":"等质量比产 CO₂ 看式量倒数（1/84 > 1/106）；等物质的量比产 CO₂ 才相等（1:1）。"}],"examples":[{"label":"例 9.3.1","tier":"L2","tierLabel":"L2 期末必考","title":"部分变质氢氧化钠固体成分定性与定量探究（p.226 问题解决拓展）","prompt":"实验室发现一瓶敞口放置一段时间的 \\(\\mathrm{NaOH}\\) 固体，已确定部分吸水变质。(1) 请设计一个能**同时验证该样品中既有 \\(\\mathrm{Na_2CO_3}\\) 又有未变质 \\(\\mathrm{NaOH}\\)** 的实验方案；(2) 称取该变质样品 \\(10.0\\text{ g}\\) 溶于水后加入足量 \\(\\mathrm{BaCl_2}\\) 溶液，将沉淀过滤、洗涤、干燥后称重得 \\(3.94\\text{ g}\\)，计算样品中 \\(\\mathrm{Na_2CO_3}\\) 的质量分数（\\(M(\\mathrm{BaCO_3}) = 197\\text{ g\\,mol}^{-1}\\)，\\(M(\\mathrm{Na_2CO_3}) = 106\\text{ g\\,mol}^{-1}\\)）。","clues":"难点在于先用中性盐彻底沉淀 \\(\\mathrm{CO_3^{2-}}\\)，防止碱性碳酸钠干扰 \\(\\mathrm{OH^-}\\) 的酚酞检测！","strategy":"过量 BaCl₂/CaCl₂ 检验并除去 CO₃²⁻ → 上层清液滴酚酞检验剩余 OH⁻ → BaCO₃ 摩尔数折算 Na₂CO₃。","given":"m(样品)=10.0 g, m(BaCO₃)=3.94 g","principle":"Ba²⁺ + CO₃²⁻ → BaCO₃↓；中性 BaCl₂ 不影响溶液 pH，除尽 CO₃²⁻ 后酚酞变红即可确认残存 NaOH。","steps":["**第(1)问实验方案**：取少量样品溶于适量蒸馏水，先加入**足量（过量）中性 \\(\\mathrm{BaCl_2}\\)（或 \\(\\mathrm{CaCl_2}\\)）溶液**，观察到有白色沉淀生成，静置后再向上层清液滴加过量 \\(\\mathrm{BaCl_2}\\) 若无新沉淀产生，证明 \\(\\mathrm{CO_3^{2-}}\\) 已检出且被完全除去；随后向上层清液中滴入 2 滴**酚酞试液**，若溶液变红，则证明原固体中还含有未变质的 \\(\\mathrm{NaOH}\\)。","**第(2)问定量计算**：生成碳酸钡沉淀物质的量 \\(n(\\mathrm{BaCO_3}) = \\frac{3.94}{197} = 0.0200\\text{ mol}\\)。","由碳守恒知 \\(n(\\mathrm{Na_2CO_3}) = n(\\mathrm{BaCO_3}) = 0.0200\\text{ mol}\\)，其质量 \\(m(\\mathrm{Na_2CO_3}) = 0.0200 \\times 106 = 2.12\\text{ g}\\)。","故样品中碳酸钠的质量分数为：\\(w(\\mathrm{Na_2CO_3}) = \\frac{2.12}{10.0} \\times 100\\% = 21.2\\%\\)。"],"answer":"(1) 先加过量 BaCl₂ 溶液产生白色沉淀证明含 Na₂CO₃ 并除尽 CO₃²⁻，再向清液滴酚酞变红证明含 NaOH；(2) 21.2%。","markingPoints":["强调加入“足量/过量”中性 BaCl₂/CaCl₂ 既检验又除尽 CO₃²⁻（2分）","向上层清液滴加酚酞（或测 pH）验证残余 NaOH（1分）","算得 n(BaCO₃)=0.0200 mol 并正确求得 21.2%（2分）"],"verification":"若步骤中先加过量稀盐酸或 Ca(OH)₂（引入 OH⁻），都会破坏第二阶段的 OH⁻ 检验，只有中性过量 BaCl₂/CaCl₂ 正确。","pitfall":"在未确保 CO₃²⁻ 完全沉淀时就滴酚酞，或误用 Ba(OH)₂ 导致额外引入 OH⁻ 造成假阳性。"},{"label":"例 9.3.2","tier":"L4","tierLabel":"L4 统考压轴","title":"碳酸钠与碳酸氢钠混合固体热分解差量及互滴图像推断","prompt":"现有 \\(\\mathrm{Na_2CO_3}\\) 与 \\(\\mathrm{NaHCO_3}\\) 的白色固体混合物 \\(27.4\\text{ g}\\)，将其充分加热至恒重后，冷却称得剩余固体质量为 \\(21.2\\text{ g}\\)（已知 \\(M(\\mathrm{Na_2CO_3})=106, M(\\mathrm{NaHCO_3})=84\\)）。(1) 求原混合物中 \\(\\mathrm{NaHCO_3}\\) 的质量及物质的量分数；(2) 若将加热后所得 \\(21.2\\text{ g}\\) 固体全部溶于水配成溶液，再向其中逐滴加入 \\(1.0\\text{ mol\\,L}^{-1}\\) 稀盐酸，从开始滴加到刚有气泡产生时，消耗盐酸的体积是多少毫升？至不再产生气泡共消耗盐酸多少毫升？","clues":"利用 \\(2\\mathrm{NaHCO_3} \\xrightarrow{\\Delta} \\mathrm{Na_2CO_3} + \\mathrm{H_2O}\\uparrow + \\mathrm{CO_2}\\uparrow\\) 每 \\(2\\text{ mol }\\mathrm{NaHCO_3}\\)（\\(168\\text{ g}\\)）分解减少质量 \\(62\\text{ g}\\)（\\(18+44\\)）！","strategy":"热分解差量法秒算 \\(n(\\mathrm{NaHCO_3})\\) → 求原组成 → 对全部转化的 \\(\\mathrm{Na_2CO_3}\\) 应用分步酸化计量（\\(\\mathrm{CO_3^{2-} \\to HCO_3^- \\to CO_2\\uparrow}\\)）。","given":"m_mix=27.4 g, m_final=21.2 g, Δm=6.2 g, c(HCl)=1.0 mol/L","principle":"热分解差量法及碳酸根逐滴酸化两步计量（1:1 分步）。","steps":["第(1)问：加热减少的质量为逸出的 \\(\\mathrm{H_2O(g)}\\) 与 \\(\\mathrm{CO_2}\\) 总质量：\\(\\Delta m = 27.4 - 21.2 = 6.2\\text{ g}\\)。","由方程 \\(2\\mathrm{NaHCO_3} \\xrightarrow{\\Delta} \\mathrm{Na_2CO_3} + \\mathrm{H_2O(g)}\\uparrow + \\mathrm{CO_2(g)}\\uparrow\\)，每 \\(2\\text{ mol}\\)（\\(168\\text{ g}\\)）\\(\\mathrm{NaHCO_3}\\) 分解减重 \\(18 + 44 = 62\\text{ g}\\)。","故原混合物中 \\(n(\\mathrm{NaHCO_3}) = 2 \\times \\frac{6.2}{62} = 0.200\\text{ mol}\\)，其质量为 \\(0.200 \\times 84 = 16.8\\text{ g}\\)。","原 \\(\\mathrm{Na_2CO_3}\\) 质量为 \\(27.4 - 16.8 = 10.6\\text{ g}\\)，即 \\(n_0(\\mathrm{Na_2CO_3}) = \\frac{10.6}{106} = 0.100\\text{ mol}\\)。所以 \\(\\mathrm{NaHCO_3}\\) 物质的量分数为 \\(\\frac{0.200}{0.200+0.100} = 66.7\\%\\)。","第(2)问：加热后 \\(21.2\\text{ g}\\) 固体全为 \\(\\mathrm{Na_2CO_3}\\)，物质的量 \\(n = \\frac{21.2}{106} = 0.200\\text{ mol}\\)。","逐滴加盐酸先发生 \\(\\mathrm{CO_3^{2-} + H^+ \\to HCO_3^-}\\)（无气泡），恰好完全转化消耗 \\(n(\\mathrm{HCl}) = 0.200\\text{ mol}\\)，即体积 \\(V_1 = \\frac{0.200}{1.0} = 0.200\\text{ L} = 200\\text{ mL}\\)（此时**刚要开始产生气泡**）。","继续滴加发生 \\(\\mathrm{HCO_3^- + H^+ \\to CO_2\\uparrow + H_2O}\\)，再耗 \\(0.200\\text{ mol}\\)，故总消耗盐酸体积 \\(V_{\\text{总}} = 400\\text{ mL}\\)。"],"answer":"(1) 含 NaHCO₃ 16.8 g，物质的量分数 66.7%；(2) 刚产气泡耗盐酸 200 mL，完全反应共耗 400 mL。","markingPoints":["利用 2NaHCO₃ 减重 62 g 算得 n(NaHCO₃)=0.200 mol（16.8 g）（2分）","算得原 Na₂CO₃ 0.100 mol 及摩尔分数 66.7%（1分）","正确分步写出先无气泡消耗 200 mL、再产气泡总耗 400 mL（2分）"],"verification":"分解生成 \\(0.100\\text{ mol }\\mathrm{Na_2CO_3}\\)（10.6 g），加上原有 10.6 g 恰好为 21.2 g。","pitfall":"第(1)问把差量 62 g 误当成 1 mol NaHCO₃ 的减重（漏乘系数 2），会导致整个组分计算差一倍。"}],"practice":[{"id":"chem9-9.3-q1","tier":"L1","tierLabel":"L1 基础","examStyle":"P1 选择","q":"下列物质中，可用作农业氮钾复合肥料的是（　）。","options":["A. 硝酸钾（\\(\\mathrm{KNO_3}\\)）","B. 氢氧化钾（\\(\\mathrm{KOH}\\)）","C. 碳酸钠（\\(\\mathrm{Na_2CO_3}\\)）","D. 氯化钠（\\(\\mathrm{NaCl}\\)）"],"correctOption":"A","given":"p.230 硝酸钾用途 & p.232 教材题 7","method":"根据植物三大营养元素 N、P、K 判断","principle":"KNO₃ 同时含氮（N）和钾（K）两种关键营养元素。","steps":["B 强碱腐蚀土壤和根系；C、D 只含 Na 不含 N/P/K；A 为优质氮钾复合肥（占世界产量 70%）。"],"ans":"A","markingPoints":["记忆三大肥料与 KNO₃ 双营养成分"],"verification":"化上 p.230 原文“硝酸钾是含氮元素和钾元素的优质化肥”。","pitfall":"误以为所有含钾化合物（如强腐蚀性的 KOH）都能当化肥。"},{"id":"chem9-9.3-q2","tier":"L2","tierLabel":"L2 期末","examStyle":"P1 选择","q":"下列关于 \\(\\mathrm{Na_2CO_3}\\) 和 \\(\\mathrm{NaHCO_3}\\) 的比较中，**错误**的是（　）。","options":["A. 相同温度下，在水中的溶解度：\\(\\mathrm{Na_2CO_3 > NaHCO_3}\\)","B. 相同温度、相同物质的量浓度水溶液的 pH：\\(\\mathrm{Na_2CO_3 > NaHCO_3}\\)","C. 与相同浓度稀盐酸反应的剧烈程度：\\(\\mathrm{Na_2CO_3 > NaHCO_3}\\)","D. 热稳定性：\\(\\mathrm{Na_2CO_3 > NaHCO_3}\\)"],"correctOption":"C","given":"活动探究 3–4（p.228–230）","method":"逐项比对溶解度、碱性、酸反应速率、热稳定性四大核心指标","principle":"HCO₃⁻ 一步直接结合 H⁺ 生成 H₂CO₃ 分解放 CO₂，速率更快。","steps":["A、B、D 均正确；C 错误：碳酸氢钠与稀盐酸反应一步放出 CO₂，速率远比碳酸钠剧烈。"],"ans":"C","markingPoints":["识别四大比较维度的唯一反向项（酸反应剧烈度 NaHCO₃ > Na₂CO₃）"],"verification":"教材 p.229 活动 12 与 p.230 对比。","pitfall":"机械记忆“所有指标都是碳酸钠更大”，忽视反应速率恰恰相反。"},{"id":"chem9-9.3-q3","tier":"L2","tierLabel":"L2 期末","examStyle":"P1 选择","q":"要除去 \\(\\mathrm{NaHCO_3}\\) 溶液中混有的少量 \\(\\mathrm{Na_2CO_3}\\) 杂质，最合理的方法是（　）。","options":["A. 加入适量稀盐酸","B. 加热蒸发溶液","C. 通入足量的 \\(\\mathrm{CO_2}\\) 气体","D. 加入适量澄清石灰水后过滤"],"correctOption":"C","given":"Na₂CO₃ 与 NaHCO₃ 溶液相互转化","method":"利用不引入新杂质的除杂原则","principle":"Na₂CO₃(aq) + CO₂ + H₂O → 2NaHCO₃(aq)，把杂质直接转化为目标物。","steps":["A 会同时消耗 NaHCO₃ 且引入 NaCl；B 加热会促使 NaHCO₃ 分解成 Na₂CO₃；C 通足量 CO₂ 将杂质 Na₂CO₃ 全部转为 NaHCO₃，无杂质残留；D 石灰水会同时沉淀目标物。"],"ans":"C","markingPoints":["应用不增、不减、转杂为纯的溶液除杂策略"],"verification":"对照化上 p.230 转化方程式核对。","pitfall":"误选 A 或 B 导致主体物质被破坏。"},{"id":"chem9-9.3-q4","tier":"L3","tierLabel":"L3 预试","examStyle":"P2 简答","q":"实验室中盛放 \\(\\mathrm{NaOH}\\) 溶液的试剂瓶为什么不能使用玻璃塞而必须使用橡皮塞？若用无水乙醇或硅胶干燥瓶中空气时，氯碱工业阳极室产物 \\(\\mathrm{Cl_2}\\) 若不慎与阴极室产物 \\(\\mathrm{NaOH}\\) 混合会发生什么反应？请写出两个相关化学方程式。","given":"p.226–227 NaOH 性质与氯碱工业","method":"写出 SiO₂ 与 NaOH 反应及 Cl₂ 与冷 NaOH 歧化反应","principle":"酸性氧化物 SiO₂ 腐蚀生黏性硅酸钠；Cl₂ 遇碱液歧化。","steps":["原因：玻璃中含有二氧化硅（\\(\\mathrm{SiO_2}\\)），它能与 \\(\\mathrm{NaOH}\\) 溶液缓慢反应生成具有黏合性的硅酸钠（\\(\\mathrm{Na_2SiO_3}\\)），日久会将玻璃塞与磨口瓶口紧紧粘连打不开，故改用橡皮塞。","反应①：\\(\\mathrm{SiO_2(s)} + 2\\mathrm{NaOH(aq)} \\longrightarrow \\mathrm{Na_2SiO_3(aq)} + \\mathrm{H_2O(l)}\\)。","反应②（\\(\\mathrm{Cl_2}\\) 混入冷 \\(\\mathrm{NaOH}\\)）：\\(\\mathrm{Cl_2(g)} + 2\\mathrm{NaOH(aq)} \\longrightarrow \\mathrm{NaCl(aq)} + \\mathrm{NaClO(aq)} + \\mathrm{H_2O(l)}\\)（这正是图 9-7 中阳离子交换膜必须隔开阴阳两极的原因之一）。"],"ans":"玻璃中 SiO₂ 与 NaOH 生成黏性硅酸钠粘住瓶塞；SiO₂+2NaOH→Na₂SiO₃+H₂O；Cl₂+2NaOH→NaCl+NaClO+H₂O。","markingPoints":["指出生成黏性硅酸钠粘连瓶塞并写出 SiO₂+2NaOH 方程式（2分）","正确写出 Cl₂ 与冷 NaOH 歧化生成 NaCl 与 NaClO（2分）"],"verification":"化上 p.226、p.286 及图 9-7 相互印证。","pitfall":"只答“NaOH 腐蚀玻璃”而未写出生成硅酸钠的黏结机制与方程式。"},{"id":"chem9-9.3-q5","tier":"L4","tierLabel":"L4 统考压轴","examStyle":"P2 综合计算","q":"（氯碱工业综合计算）某氯碱厂用阳离子交换膜电解槽电解 \\(500\\text{ mL}\\) 饱和 \\(\\mathrm{NaCl}\\) 溶液（假设温度不变且溶液体积保持 \\(500\\text{ mL}\\)）。通电一段时间后，阳极室共收集到标准状况下 \\(\\mathrm{Cl_2}\\) 气体 \\(2.24\\text{ L}\\)，随即停止通电并充分搅拌阴极室溶液。(1) 阴极室同时收集到标准状况下 \\(\\mathrm{H_2}\\) 体积是多少？(2) 若将阴极室中生成的 \\(\\mathrm{NaOH}\\) 溶液全部取出，通入 \\(3.36\\text{ L}\\)（标况）\\(\\mathrm{CO_2}\\) 气体充分吸收（忽略气体溶解与挥发），试通过计算确定所得溶液中溶质的成分及其各自物质的量。","given":"V(Cl₂)=2.24 L (0.100 mol), V(CO₂)=3.36 L (0.150 mol)","method":"电解定量关系求 n(NaOH) → 比较 n(CO₂)/n(NaOH) 确定 Na₂CO₃ 与 NaHCO₃ 比例","principle":"2NaCl + 2H₂O → 2NaOH + Cl₂↑ + H₂↑；CO₂ 与 NaOH 先生成 Na₂CO₃，过量再生成 NaHCO₃。","steps":["第(1)问：由电解方程式 \\(2\\mathrm{NaCl} + 2\\mathrm{H_2O} \\xrightarrow{\\text{电解}} 2\\mathrm{NaOH} + \\mathrm{Cl_2}\\uparrow + \\mathrm{H_2}\\uparrow\\)，知 \\(n(\\mathrm{Cl_2}) = \\frac{2.24}{22.4} = 0.100\\text{ mol}\\)，故 \\(n(\\mathrm{H_2}) = 0.100\\text{ mol}\\)（标况体积 **\\(2.24\\text{ L}\\)**），生成 \\(n(\\mathrm{NaOH}) = 2 \\times 0.100 = 0.200\\text{ mol}\\)。","第(2)问：通入 \\(n(\\mathrm{CO_2}) = \\frac{3.36}{22.4} = 0.150\\text{ mol}\\)。比较计量比：\\(\\frac{n(\\mathrm{CO_2})}{n(\\mathrm{NaOH})} = \\frac{0.150}{0.200} = \\frac{3}{4}\\)。","因 \\(\\frac{1}{2} < \\frac{3}{4} < 1\\)，故溶质为 **\\(\\mathrm{Na_2CO_3}\\) 与 \\(\\mathrm{NaHCO_3}\\) 的混合物**。","设含 \\(\\mathrm{Na_2CO_3}\\) 为 \\(x\\text{ mol}\\)，\\(\\mathrm{NaHCO_3}\\) 为 \\(y\\text{ mol}\\)。由钠守恒与碳守恒联立方程：\\(2x + y = 0.200\\)（式①），\\(x + y = 0.150\\)（式②）。","两式相减得 \\(x = 0.0500\\text{ mol}\\)，代回得 \\(y = 0.100\\text{ mol}\\)。"],"ans":"(1) H₂ 为 2.24 L；(2) 溶质为 0.0500 mol Na₂CO₃ 和 0.100 mol NaHCO₃。","markingPoints":["算出 n(H₂)=0.100 mol (2.24 L) 与 n(NaOH)=0.200 mol（2分）","利用 n(CO₂)/n(NaOH)=0.75 介于 0.5–1 之间判断产物为两盐共存（1分）","由 Na、C 元素守恒解得 Na₂CO₃ 0.0500 mol、NaHCO₃ 0.100 mol（2分）"],"verification":"验证：0.05 mol×2 + 0.10 mol×1 = 0.20 mol Na；0.05 + 0.10 = 0.15 mol C，完全正确。","pitfall":"忘记元素守恒法而强行分步写两个方程容易算乱；记住 CO₂/NaOH 比值区间（≤0.5 为碱/正盐；0.5–1 为正盐/酸式盐；≥1 全为酸式盐）最快！"}],"cheatSheet":["氯碱工业：\\(2\\mathrm{NaCl} + 2\\mathrm{H_2O} \\xrightarrow{\\text{电解}} 2\\mathrm{NaOH} + \\mathrm{Cl_2}\\uparrow + \\mathrm{H_2}\\uparrow\\)（阳膜只透 \\(\\mathrm{Na^+}\\)）。","NaOH 保存：密封防潮解及吸 \\(\\mathrm{CO_2}\\) 变质；用橡皮塞不用玻璃塞（防生 \\(\\mathrm{Na_2SiO_3}\\)）；变质检验用过量 \\(\\mathrm{BaCl_2}\\) 不可单用酚酞。","纯碱 vs 小苏打：溶解度、碱性、热稳定性均纯碱 > 小苏打；与酸反应剧烈度 & 等质量产 \\(\\mathrm{CO_2}\\) 量均小苏打 > 纯碱。","鉴别除杂口诀：鉴别溶液用 \\(\\mathrm{CaCl_2}\\)（不可用石灰水）；除纯碱固体中小苏打靠加热，除溶液相互按通 \\(\\mathrm{CO_2}\\) / 加 \\(\\mathrm{NaOH}\\)。"],"kbEntryIds":["kb-chem9-chlor-alkali-naoh","kb-chem9-carbonate-bicarbonate"],"quiz":{"q":"现有一包 \\(\\mathrm{Na_2CO_3}\\) 固体混有少量 \\(\\mathrm{NaHCO_3}\\)，加热至恒重后质量减少了 \\(3.1\\text{ g}\\)，求原固体中混有的 \\(\\mathrm{NaHCO_3}\\) 质量。","given":"加热减重 Δm = 3.1 g, M(NaHCO₃)=84 g/mol, 2 mol 分解减重 62 g","method":"差量法：2NaHCO₃ —(△)→ Na₂CO₃ + H₂O↑ + CO₂↑ 减重 62 g","principle":"碳酸钠热稳定不分解，全部质量损失来自 NaHCO₃ 放出的 H₂O 与 CO₂。","steps":["设含 \\(m(\\mathrm{NaHCO_3})\\)，由比例 \\(\\frac{168}{62} = \\frac{m}{3.1}\\)","解得 \\(m = \\frac{168 \\times 3.1}{62} = 8.4\\text{ g}\\)。"],"ans":"\\(8.4\\text{ g}\\)"},"diagrams":[{"src":"assets/fig/v2/chem09-na-cycle.svg","caption":"图 9-1 钠及其重要化合物转化关系与焰色要点网络","alt":"钠单质、氧化钠、过氧化钠、氢氧化钠、碳酸钠、碳酸氢钠及氯化钠转化关系图","pageRef":"化上 p.220–231"}]}]},"化学10":{"lessonKey":"化学10","courseCode":"chemistry","subject":"化学","chapter":10,"title":"IIA族元素：镁和钙","syllabus":"3.3 IIA族元素","bookId":"sm1-chemistry-2017","bookCitation":"《马来西亚华文独中教科书 · 化学（上册）》（2017年11月版）第10章 p.235–252","examScopes":["sem2_final","uec"],"chapterOverview":{"summary":"第10章聚焦 IIA 族碱土金属镁（Mg）和钙（Ca）。相比同周期 IA 族，IIA 族原子半径更小、价电子数为 2（ns²），金属键更强，故熔沸点与密度明显升高，活泼性则略弱于同周期碱金属；但镁能在 CO₂ 与 N₂ 中剧烈燃烧，海水提镁（图 10-3）、石灰三兄弟（CaCO₃—CaO—Ca(OH)₂）、硬水软化与 Mg²⁺/Ca²⁺ 综合检验均是 UEC 统考无机化学的核心命题点。","conceptTree":[{"branch":"10.1 镁和钙的性质（p.236–241）","items":["IIA 族（Be–Ra）ns² 电子结构与金属性递变","表 10-3 物理性质（金属键强于 IA 族）","海水提镁工艺流程（图 10-3）与方案评价（表 10-1）","与 O₂、N₂、H₂O、CO₂（禁止 CO₂ 灭火！）、酸反应及 CaH₂ 野外制氢"]},{"branch":"10.2 镁的重要化合物（p.242–244）","items":["叶绿素中心离子 Mg²⁺ 与镁肥","MgO（苦土，熔点 2852 ℃ 耐火材料）","MgCl₂·6H₂O（苦卤潮解，电解熔融制镁而非 MgO）与 MgSO₄"]},{"branch":"10.3 钙的重要化合物（p.244–246）","items":["CaO（生石灰）、Ca(OH)₂（熟石灰/石灰乳/石灰水）与 CaCO₃ 循环","CaCO₃ ⇌ Ca(HCO₃)₂ 溶洞形成与硬水（暂时硬度 vs 永久硬度）软化","石膏 CaSO₄·2H₂O ⇌ 熟石膏 (CaSO₄)₂·H₂O 脱水与膨胀应用","无水 CaCl₂ 强吸水性与禁止干燥 NH₃ 原因"]},{"branch":"10.4 镁离子和钙离子的检验（p.247–248）","items":["活动 4–5：Mg²⁺ + NaOH / 氨水 → 不溶于过量碱的白色 Mg(OH)₂↓","活动 6–7：Ca²⁺ + 草酸铵 → 白色 CaC₂O₄↓（不溶醋酸、溶于稀盐酸）","活动 8：Ca²⁺ 砖红色焰色试验与综合检验必要性"]}]},"paperFocus":["高三下半年期末考 & UEC 统考：卷一（30% 选择题）重点考查 Mg 在空气与 CO₂ 中的燃烧产物及灭火禁忌、工业电解 MgCl₂ 而非 MgO 的原因、石灰乳 vs 石灰水、石膏与熟石膏化学式、CaCl₂ 不能干燥 NH₃、以及 Ca²⁺/Mg²⁺ 鉴别特征。","UEC 卷二乙部（无机化学）及实验探究（10%）：高频出现海水提镁流程图（p.237 & p.251）、空气除杂制备氮化镁装置连接题（p.251 练习 5）、等质量镁在不同气体中燃烧固体质量比较（p.252 练习 7）以及硬水软化原理。"],"solvingWorkflow":["识别金属与非金属/氧化物反应条件：Mg 在空气中燃烧同时生成 MgO（主要）和少量淡黄色 Mg₃N₂；在 CO₂ 中燃烧生成 MgO 和黑色碳单质 C。","处理多步流程提纯（海水提镁 / 粗盐精制）：先定位沉淀剂（贝壳煅烧制 Ca(OH)₂ 成本最低），再定位浓缩母液（苦卤，表 10-1），最后注意 MgCl₂·6H₂O 加热脱水时需防 Mg²⁺ 水解。","解决 Mg²⁺/Ca²⁺ 混合鉴别题：Mg²⁺ 用 NaOH 或氨水生成白色沉淀（且不溶于过量碱，区别 Al³⁺）；Ca²⁺ 用 (NH₄)₂C₂O₄ 生白色 CaC₂O₄ 沉淀并用“醋酸不溶、盐酸溶”及“砖红色焰色”双重确认。","硬水软化判断：碳酸氢盐（HCO₃⁻）引起暂时硬度，煮沸或加石灰即可除去；硫酸盐/氯化物引起永久硬度，煮沸无效，需加纯碱 Na₂CO₃ 沉淀。"],"questionTypes":["空气制备 Mg₃N₂ 的气体除杂、除水、除氧及尾气防倒吸装置串联排序（p.251 第 5 题）","海水晒盐苦卤提镁工艺评价与 Ca(OH)₂ 杂质去除（p.251 第 6 题）","镁在 O₂、N₂、CO₂ 中燃烧的固体产物质量定量对比（p.252 第 7 题）","石灰石—生石灰—熟石灰—石膏—无水 CaCl₂ 性质及硬水软化应用分析","Mg²⁺、Ca²⁺、Al³⁺、Ba²⁺ 离子鉴别与沉淀溶解性辨析"],"scoringNotes":["解释“镁在空气中燃烧产物中为何 MgO 远多于 Mg₃N₂”（尽管空气中 N₂ 占 78%）时，必须答出“O₂ 的氧化性远强于 N₂，且 N≡N 键能大、N₂ 化学性质在常温及一般燃烧下相对稳定”，切忌只说“氧气更活泼”。","书写海水提镁中贝壳参与的三步反应时，务必区分“石灰乳”为 Ca(OH)₂(s/悬浊液) 与 MgCl₂(aq) 发生沉淀转化。"],"vid":[{"t":"镁在二氧化碳与氮气中的燃烧实验","q":"镁 二氧化碳 燃烧 氮化镁 化学"},{"t":"海水提镁工业流程与苦卤浓缩原理","q":"海水提镁 工艺流程 高中化学"},{"t":"硬水软化与钙镁离子鉴别","q":"硬水软化 钙离子 镁离子 检验 化学"}],"sections":[{"id":"10.1","t":"镁和钙的性质","anchor":{"pages":"化上 p.236–241","syllabus":"3.3.1–3.3.2 碱土金属结构与物理性质、镁钙化学性质及海水提镁工业","examScopes":["sem2_final","uec"],"examWeight":"P1 镁燃烧与递变规律 + P2 海水提镁流程及空气制 Mg₃N₂ 实验探究","terms":"Alkaline earth metals · Seawater extraction · Magnesium nitride (Mg₃N₂) · Combustion in CO₂ · Calcium hydride (CaH₂)","prerequisites":["IA 族元素递变规律及金属活动性比较（化上 Ch 9.1）","氧化还原反应配平与极限计算（化上 Ch 4, Ch 8）"],"goals":["对比 IIA 族（ns²）与同周期 IA 族（ns¹）的原子半径与金属键强弱，解释镁钙密度、熔沸点高于钠钾的原因。","完整梳理图 10-3 海水提镁五步工艺反应，并用表 10-1 论证选择晒盐苦卤与海边贝壳的经济合理性。","掌握镁和钙与 O₂、N₂、H₂O、CO₂、HCl 的化学方程式，解释镁条免煤油密封、镁着火禁 CO₂ 灭火及 CaH₂ 野外制氢原理。"]},"concepts":[{"kind":"definition","title":"IIA 族结构递变与表 10-3 镁钙物理性质","pageRef":"化上 p.236、p.239","body":["**族序与存在**：IIA 族包括铍（Be）、镁（Mg）、钙（Ca）、锶（Sr）、钡（Ba）和放射性镭（Ra），统称**碱土金属（alkaline earth metals）**，最外层都有 **2 个电子（\\(ns^2\\)）**，易失 2 个电子呈 +2 价。地壳中 Mg 占 **2.00%**、Ca 占 **3.45%**，均只以化合态存在（光卤石、菱镁矿、白云石、石灰石、石膏等）。","**同周期对比 IA 族**：同周期 IIA 族（Mg、Ca）的核电荷数大于 IA 族（Na、K），原子半径更小、价电子数更多，**金属键强于碱金属**，因此与同周期钠、钾相比，镁和钙的**密度更大、硬度更大、熔点和沸点高得多**。","**同主族与水反应递变（p.241 问题解决）**：从 Be 到 Ba，电子层数递增、原子半径增大、失电子能力增强：Be 与水不反应 → Mg 与冷水极慢、与热水较快 → Ca 与冷水较剧烈 → Sr、Ba 与水剧烈反应。"],"table":{"headers":["单质","颜色","密度 / kg·m⁻³","熔点 / ℃","沸点 / ℃","表面氧化膜特征与保存"],"rows":[["镁（Mg）","银白","1740（1.74 g·cm⁻³）","648.8","1090","常温形成致密坚固 MgO 膜抗腐蚀，无需煤油密封（使用前砂纸擦去）"],["钙（Ca）","银白","1550（1.55 g·cm⁻³）","839","1484","氧化膜疏松且易与水反应，须密封保存于干燥容器或石蜡油中"]]},"takeaway":"注意密度大小：\\(\\rho(\\mathrm{Ca}) = 1550 < \\rho(\\mathrm{Mg}) = 1740\\)（都是轻金属但均大于水的 1000 kg·m⁻³，投入水中沉在水底，与浮在水面的 Na、K 不同！）。"},{"kind":"experiment","title":"海水提镁工艺流程（图 10-3）与三套富集方案评价（表 10-1）","pageRef":"化上 p.237–238、p.251","body":["**背景数据**：海水中镁总储量约 \\(1.8 \\times 10^{15}\\text{ t}\\)，但浓度极稀（每千克海水仅含 \\(5.11\\text{ g}\\ \\mathrm{MgCl_2}\\)），必须先富集再沉淀。","**表 10-1 富集方案评价**：","- **方案 1（直接向海水加沉淀剂）**：不合理——海水量巨大且 \\(\\mathrm{Mg^{2+}}\\) 极稀，沉淀剂消耗极巨、沉淀难以收集。","- **方案 2（高温加热蒸发海水再加沉淀剂）**：不合理——蒸发海量海水消耗天量燃料能量，经济成本极高。","- **方案 3（向晒盐后的苦卤中加沉淀剂）**：**合理**——利用太阳能晒盐结晶出 \\(\\mathrm{NaCl}\\) 后的母液（苦卤）天然浓缩富集了高浓度 \\(\\mathrm{MgCl_2}\\)，几乎零额外能耗！","**五步工艺链（图 10-3）**：①海边**贝壳**（\\(\\mathrm{CaCO_3}\\)）高温煅烧得 \\(\\mathrm{CaO}\\)；②加水制**石灰乳** \\(\\mathrm{Ca(OH)_2}\\)（不用昂贵的 \\(\\mathrm{NaOH}\\)，就地取材降低成本）；③加入苦卤沉淀池得 \\(\\mathrm{Mg(OH)_2}\\) 过滤；④加盐酸溶解、浓缩结晶得 \\(\\mathrm{MgCl_2\\cdot 6H_2O}\\)；⑤（在 HCl 气流中防“水解”）脱水得无水 \\(\\mathrm{MgCl_2}\\)，最后**电解熔融 \\(\\mathrm{MgCl_2}\\)** 得 \\(\\mathrm{Mg}\\) 和副产 \\(\\mathrm{Cl_2}\\)（\\(\\mathrm{Cl_2}\\) 与 \\(\\mathrm{H_2}\\) 合成 \\(\\mathrm{HCl}\\) 循环使用）。"],"takeaway":"海水提镁三大经济亮点：①海边贝壳制廉价沉淀剂石灰乳；②利用晒盐副产苦卤；③电解副产 Cl₂ 回收制 HCl 循环利用。"},{"kind":"mechanism","title":"活动 1–3：镁的标志性反应（空气、CO₂、水、酸）与 CaH₂ 制氢","pageRef":"化上 p.238–241","body":["**与 \\(\\mathrm{O_2}\\) 和 \\(\\mathrm{N_2}\\) 燃烧**：点燃镁条发出耀眼白光（制信号弹、焰火），在空气中燃烧主要生成白色 **\\(\\mathrm{MgO}\\)** 和少量淡黄色 **\\(\\mathrm{Mg_3N_2}\\)**（\\(\\mathrm{Mg_3N_2}\\) 遇水剧烈水解：\\(\\mathrm{Mg_3N_2 + 6H_2O \\to 3Mg(OH)_2\\downarrow + 2NH_3\\uparrow}\\)）。钙在空气中燃烧主要生成 \\(\\mathrm{CaO}\\) 和少量 \\(\\mathrm{Ca_3N_2}\\)。","**活动 1（镁在二氧化碳中燃烧）**：将燃着的镁条伸入充满 \\(\\mathrm{CO_2}\\) 的集气瓶中，镁条**继续剧烈燃烧**，发出耀眼白光，瓶内壁附着白色固体粉末（\\(\\mathrm{MgO}\\)）和黑色固体颗粒（\\(\\mathrm{C}\\)）：\\(2\\mathrm{Mg(s) + CO_2(g)} \\xrightarrow{\\text{点燃}} 2\\mathrm{MgO(s) + C(s)}\\)。故**镁着火时严禁用 \\(\\mathrm{CO_2}\\) 灭火器或干粉（\\(\\mathrm{NaHCO_3}\\)）灭火**（p.250 练习 9A）！","**活动 2（与水反应）**：擦去氧化膜的镁条投入滴有酚酞的冷水中，几乎无现象（仅极缓慢放出微弱气泡）；加热至沸腾时气泡加快，溶液变为浅红色：\\(\\mathrm{Mg(s) + 2H_2O(g)} \\xrightarrow{\\Delta} \\mathrm{Mg(OH)_2(s) + H_2(g)}\\uparrow\\)（与沸水亦同理生成 \\(\\mathrm{Mg(OH)_2}\\) 与 \\(\\mathrm{H_2}\\)）。钙与冷水即较剧烈反应放 \\(\\mathrm{H_2}\\)。","**思考题 10a-2（\\(\\mathrm{CaH_2}\\) 野外制氢）**：高温下 \\(\\mathrm{Ca(s) + H_2(g)} \\xrightarrow{\\Delta} \\mathrm{CaH_2(s)}\\)（离子型氢化物，其中 H 为 −1 价）；遇水立即发生归中反应放出大量氢气：\\(\\mathrm{CaH_2(s) + 2H_2O(l) \\to Ca(OH)_2(s) + 2H_2(g)}\\uparrow\\)（轻便高效！）。"],"takeaway":"活动 1–3 前务必用砂纸擦去镁条表面的致密 MgO 氧化膜，否则反应极难启动或现象极不明显！"}],"formulas":[{"title":"镁与氧气、氮气、二氧化碳燃烧方程式","tex":"2\\mathrm{Mg(s)} + \\mathrm{O_2(g)} \\xrightarrow{\\text{点燃}} 2\\mathrm{MgO(s)},\\quad 3\\mathrm{Mg(s)} + \\mathrm{N_2(g)} \\xrightarrow{\\text{点燃}} \\mathrm{Mg_3N_2(s)},\\quad 2\\mathrm{Mg(s)} + \\mathrm{CO_2(g)} \\xrightarrow{\\text{点燃}} 2\\mathrm{MgO(s)} + \\mathrm{C(s)}","plain":"2Mg+O2→2MgO; 3Mg+N2→Mg3N2; 2Mg+CO2→2MgO+C","conditions":"点燃高温条件下；与 CO₂ 反应体现镁的强还原性","pageRef":"化上 p.240–241","note":"注意氮化镁中 N 为 −3 价，化学式下标交叉为 Mg₃N₂。"},{"title":"海水提镁关键反应与 CaH₂ 制氢方程式","tex":"\\mathrm{MgCl_2(l)} \\xrightarrow{\\text{电解}} \\mathrm{Mg(l)} + \\mathrm{Cl_2(g)}\\uparrow,\\qquad \\mathrm{CaH_2(s)} + 2\\mathrm{H_2O(l)} \\longrightarrow \\mathrm{Ca(OH)_2(s)} + 2\\mathrm{H_2(g)}\\uparrow","plain":"MgCl2(l)—(电解)→Mg(l)+Cl2↑; CaH2+2H2O→Ca(OH)2+2H2↑","conditions":"电解无水熔融氯化镁（不能电解氯化镁水溶液）","pageRef":"化上 p.237、p.241","note":"CaH₂ 与 H₂O 反应中，1 mol CaH₂ 转移 2 mol 电子生成 2 mol H₂。"}],"pitfalls":[{"title":"误以为所有燃烧都可以用二氧化碳灭火器扑救","wrong":"“实验室金属镁条着火时，应立即使用二氧化碳灭火器或干粉（碳酸氢钠）灭火器灭火。”","diagnosis":"忽略了 \\(\\mathrm{Mg}\\) 能在 \\(\\mathrm{CO_2}\\) 中剧烈燃烧生成 \\(\\mathrm{MgO}\\) 和 \\(\\mathrm{C}\\)（助燃而非灭火）；干粉中的 \\(\\mathrm{NaHCO_3}\\) 受热分解同样放出 \\(\\mathrm{CO_2}\\) 和水，都会加剧火势。","right":"金属镁着火（以及钠、钾着火）严禁使用水、\\(\\mathrm{CO_2}\\) 或干粉灭火器，应当用**干燥的细沙**覆盖扑灭。","checkRule":"遇到“Mg 着火能否用 CO₂/干粉/水灭火”，一律判错！"},{"title":"误以为镁在空气中燃烧产物中 Mg₃N₂ 比 MgO 多","wrong":"“空气中氮气占 78%、氧气只占 21%，所以镁条在空气中燃烧生成的氮化镁质量比氧化镁多。”","diagnosis":"教材 p.252 习题 7-(3) 陷阱：产物的比例取决于反应物的化学性质（氧化性强弱与反应活化能）及反应速率，而不单纯取决于气体体积分数。","right":"\\(\\mathrm{N_2}\\) 分子中氮氮三键（\\(\\mathrm{N\\equiv N}\\)）键能很大、化学性质远比 \\(\\mathrm{O_2}\\) 稳定，\\(\\mathrm{O_2}\\) 的氧化性远强于 \\(\\mathrm{N_2}\\)，故镁在空气中燃烧产物以白色 **\\(\\mathrm{MgO}\\) 为主**，\\(\\mathrm{Mg_3N_2}\\) 仅为少量。","checkRule":"化学反应竞争看“活度/氧化还原趋势与速率”，不单看体积比例。"}],"examples":[{"label":"例 10.1.1","tier":"L3","tierLabel":"L3 实验探究","title":"实验室利用空气制备氮化镁（Mg₃N₂）装置串联与误差分析（p.251 第 5 题）","prompt":"实验室利用空气和如图装置（①镁粉硬质玻璃管、②浓硫酸洗气瓶、③\\(\\mathrm{NaOH}\\) 溶液洗气瓶、④储气瓶（进水口 G 驱空气）、⑤铜粉硬质玻璃管）制备少量 \\(\\mathrm{Mg_3N_2}\\)（\\(\\mathrm{Mg_3N_2}\\) 遇水剧烈反应）。请回答：(1) 气流从左到右时，正确的装置连接序号顺序是什么？(2) 实验开始时应先在 G 处通自来水排空气，再依次点燃装有哪种金属粉的酒精灯？(3) 分别写出装置 ③、②、⑤ 的作用及相关方程式。","clues":"空气中含 \\(\\mathrm{N_2, O_2, CO_2, H_2O(g)}\\)，而 \\(\\mathrm{Mg}\\) 不仅与 \\(\\mathrm{O_2}\\) 反应，还能与 \\(\\mathrm{CO_2}\\) 和水蒸气反应！且最后必须干燥后才能进入铜管/镁管。","strategy":"先除酸性气体 \\(\\mathrm{CO_2}\\)（碱洗）→ 再除水蒸气 \\(\\mathrm{H_2O}\\)（浓硫酸干燥，防先干后湿）→ 灼热铜粉除 \\(\\mathrm{O_2}\\) → 纯净干燥 \\(\\mathrm{N_2}\\) 进入镁粉管。","given":"装置：①Mg粉、②浓H₂SO₄、③NaOH溶液、④储气瓶、⑤Cu粉","principle":"气体除杂顺序“先除杂质气体，后干燥”；先点铜管除净氧再点镁管，防镁被残余氧氧化。","steps":["(1) **装置连接顺序**：从储气瓶 ④ 排出空气 → 先经 ③（\\(\\mathrm{NaOH}\\) 溶液除去 \\(\\mathrm{CO_2}\\)）→ 再经 ②（浓硫酸除去水蒸气）→ 进入 ⑤（灼热铜粉除去 \\(\\mathrm{O_2}\\)）→ 最后进入 ①（镁粉与纯净 \\(\\mathrm{N_2}\\) 反应）。顺序为：**④ → ③ → ② → ⑤ → ①**（注：若先把 ⑤ 放在 ② 前面，则先除氧、再除 CO₂ 与水也可，但从储气瓶出来必先 ③ 后 ②，且 ⑤ 需干燥气体以防玻璃管炸裂，故 ④→③→②→⑤→① 最规范）。","(2) **加热顺序**：应先在 G 处接通自来水排出部分空气，再先点燃**装有铜粉的酒精灯（⑤）**，待装置内氧气被充分消耗后，再点燃**装有镁粉的酒精灯（①）**（否则未排尽的 \\(\\mathrm{O_2}\\) 会直接与 \\(\\mathrm{Mg}\\) 生成 \\(\\mathrm{MgO}\\) 杂质）。","(3) **各装置作用**：","- 装置 ③（饱和 \\(\\mathrm{NaOH}\\) 溶液）：吸收空气中的 \\(\\mathrm{CO_2}\\)，\\(2\\mathrm{NaOH(aq) + CO_2(g) \\to Na_2CO_3(aq) + H_2O(l)}\\)。","- 装置 ②（浓硫酸）：干燥气体、除去水蒸气（防止水与热铜/镁反应，也防止生成的 \\(\\mathrm{Mg_3N_2}\\) 水解）。","- 装置 ⑤（灼热铜粉）：除去空气中的 \\(\\mathrm{O_2}\\)，\\(2\\mathrm{Cu(s) + O_2(g)} \\xrightarrow{\\Delta} 2\\mathrm{CuO(s)}\\)。"],"answer":"(1) ④→③→②→⑤→①；(2) 先点铜粉处（⑤），后点镁粉处（①）；(3) ③ 除 CO₂、② 除水蒸气、⑤ 除 O₂（方程式见上）。","markingPoints":["准确排定气体除杂“先碱洗(③)后浓硫酸干燥(②)”再经铜粉(⑤)入镁粉(①)（2分）","明确先点铜粉后点镁粉（1分）","正确写出 ③ 与 ⑤ 的化学方程式及各步试剂作用（2分）"],"verification":"对照化上 p.251 习题 5：从储气瓶④出来的空气依次洗去 CO₂、H₂O、O₂ 后，进入①的纯净气体即为 N₂。","pitfall":"若把 ②（浓硫酸）放在 ③（NaOH 水溶液）前面，气体经过水溶液后会重新带出水蒸气，导致干燥白费！"},{"label":"例 10.1.2","tier":"L4","tierLabel":"L4 统考压轴","title":"等质量镁在 O₂、N₂、CO₂ 中燃烧的固体产物质量定量对比（p.252 第 7-(4) 题）","prompt":"取三份**等质量**（均为 \\(24.0\\text{ g}\\)，即 \\(1.00\\text{ mol}\\)）的纯净镁条，分别在足量的干燥纯 \\(\\mathrm{O_2}\\)、纯 \\(\\mathrm{N_2}\\) 和纯 \\(\\mathrm{CO_2}\\) 中充分点燃完全反应，冷却后称得三种情况下生成的**全部固体产物总质量**分别为 \\(m_1\\)、\\(m_2\\) 和 \\(m_3\\)。试通过计算排出 \\(m_1, m_2, m_3\\) 的大小顺序。","clues":"注意 \\(\\mathrm{Mg}\\) 在 \\(\\mathrm{CO_2}\\) 中生成的单质碳 \\(\\mathrm{C(s)}\\) 也是固体！不能漏算碳的质量。","strategy":"以 \\(1.00\\text{ mol Mg}\\)（24.0 g）为基准，分别按化学计量比求出每种情况的固体产物总质量。","given":"n(Mg) = 1.00 mol (24.0 g)，三种气体均足量","principle":"化学方程式计量比及产物物态判断（MgO(s), Mg₃N₂(s), C(s) 皆为固体）。","steps":["在足量 \\(\\mathrm{O_2}\\) 中：\\(2\\mathrm{Mg} + \\mathrm{O_2} \\xrightarrow{\\text{点燃}} 2\\mathrm{MgO(s)}\\)。\\(1.00\\text{ mol Mg}\\) 生成 \\(1.00\\text{ mol MgO}\\)，固体质量：\\(m_1 = 1.00 \\times (24 + 16) = 40.0\\text{ g}\\)。","在足量 \\(\\mathrm{N_2}\\) 中：\\(3\\mathrm{Mg} + \\mathrm{N_2} \\xrightarrow{\\text{点燃}} \\mathrm{Mg_3N_2(s)}\\)。\\(1.00\\text{ mol Mg}\\) 生成 \\(\\frac{1}{3}\\text{ mol }\\mathrm{Mg_3N_2}\\)，固体质量：\\(m_2 = \\frac{1}{3} \\times (24 \\times 3 + 14 \\times 2) = \\frac{100}{3} \\approx 33.3\\text{ g}\\)。","在足量 \\(\\mathrm{CO_2}\\) 中：\\(2\\mathrm{Mg} + \\mathrm{CO_2} \\xrightarrow{\\text{点燃}} 2\\mathrm{MgO(s)} + \\mathrm{C(s)}\\)。\\(1.00\\text{ mol Mg}\\) 生成 \\(1.00\\text{ mol MgO}\\)（\\(40.0\\text{ g}\\)）和 \\(0.500\\text{ mol C(s)}\\)（\\(0.500 \\times 12 = 6.0\\text{ g}\\)），故固体总质量：\\(m_3 = 40.0 + 6.0 = 46.0\\text{ g}\\)。","比较三者数值：\\(46.0\\text{ g} > 40.0\\text{ g} > 33.3\\text{ g}\\)。"],"answer":"固体产物总质量大小关系为 **\\(m_3 > m_1 > m_2\\)**（即 \\(\\mathrm{CO_2} > \\mathrm{O_2} > \\mathrm{N_2}\\)）。","markingPoints":["正确求得 m₁(O₂)=40.0 g 与 m₂(N₂)=33.3 g（2分）","算得 m₃(CO₂) 包含 MgO(40.0 g) 与碳粉 C(6.0 g) 共 46.0 g（2分）","正确排列 m₃ > m₁ > m₂（1分）"],"verification":"换用固定 1 mol Mg 结合的非金属质量检验：在 O₂ 中结合 16 g O；在 N₂ 中结合 9.33 g N；在 CO₂ 中结合 16 g O + 6 g C = 22 g，故 22 > 16 > 9.33，完美一致！","pitfall":"在算 \\(m_3\\) 时容易只算 \\(\\mathrm{MgO}\\) 的质量而忽略了置换出来的碳单质也是固体，误得 \\(m_3 = m_1\\)。"}],"practice":[{"id":"chem10-10.1-q1","tier":"L1","tierLabel":"L1 基础","examStyle":"P1 选择","q":"下列关于金属镁的性质描述中，**不正确**的是（　）。","options":["A. 镁在空气中燃烧发出耀眼的白光，可用作信号弹和照明弹","B. 镁在二氧化碳中不能燃烧，因此镁着火可用二氧化碳灭火器扑灭","C. 镁能与热水（沸水）反应产生氢气和氢氧化镁","D. 常温下镁表面易形成致密氧化膜，因此具有一定抗腐蚀性能"],"correctOption":"B","given":"p.240–241 镁的性质及思考题 10a-1","method":"逐项比对镁与 O₂、CO₂、H₂O 的实验事实","principle":"2Mg + CO₂ —(点燃)→ 2MgO + C，CO₂ 不但不能灭火反而助燃。","steps":["A、C、D 均为教材明确阐述的正确事实；B 错，镁着火不能用 CO₂ 灭火器。"],"ans":"B","markingPoints":["掌握镁在 CO₂ 中继续剧烈燃烧的特性"],"verification":"对照化上 p.241 思考题 10a-1 核对。","pitfall":"用一般可燃物常识误推镁条着火也能用 CO₂ 灭火。"},{"id":"chem10-10.1-q2","tier":"L2","tierLabel":"L2 期末","examStyle":"P1 选择","q":"从海水中提取金属镁时（图 10-3），将海岸边的贝壳煅烧制得石灰乳作为沉淀剂，这主要体现了化学工业中的哪两项原则？（　）","options":["A. 用 CaCO₃ 直接沉淀海水中的 Mg²⁺ 并回收 Cl₂","B. 利用晒盐母液（苦卤）富集 Mg²⁺ 并就地取材以廉价生石灰代替昂贵烧碱","C. 用高温蒸发全部海水的方式提高 MgCl₂ 浓度","D. 电解氯化镁水溶液直接获得纯金属镁"],"correctOption":"B","given":"图 10-3 及表 10-1 海水提镁方案评价","method":"分析沉淀剂来源、富集介质与电解质状态","principle":"苦卤已浓缩 Mg²⁺，贝壳 CaCO₃ → Ca(OH)₂ 廉价高效，电解必须用熔融 MgCl₂。","steps":["A 错，CaCO₃ 难溶无法直接沉淀 Mg²⁺；C 错，蒸发全海水能耗过高（表 10-1 方案 2）；D 错，电解 MgCl₂ 水溶液只能析出 H₂ 得不到 Mg；B 正确。"],"ans":"B","markingPoints":["理解工业生产成本与工艺合理性评价"],"verification":"对照化上 p.237–238 图 10-3 与表 10-1。","pitfall":"误选 D，忘记活泼金属 Mg 必须电解熔融无水盐。"},{"id":"chem10-10.1-q3","tier":"L2","tierLabel":"L2 期末","examStyle":"P2 简答","q":"金属镁、金属钙和金属钠都属于活泼金属，但在实验室中保存方式却不相同：钠保存在煤油中，钙必须密封保存在干燥容器或石蜡油中，而镁条通常直接放置在干燥试剂瓶或铁盒里而无需煤油浸没。请结合其表面氧化膜的结构特点解释原因，并写出常温下用砂纸擦去氧化膜后的镁条与沸水反应的化学方程式。","given":"p.238–241 镁、钙表面氧化膜对比","method":"对比致密氧化膜（MgO）与疏松氧化膜（CaO）对金属的保护作用","principle":"致密坚固氧化膜阻止内部继续被空气氧化，疏松氧化膜不能阻止且 CaO 易吸水反应。","steps":["原因：常温下镁在空气中表面迅速形成一层**致密而坚固的氧化镁（\\(\\mathrm{MgO}\\)）保护膜**，阻止内部镁继续氧化，故无需密封浸油保存；而钙表面生成的氧化钙（\\(\\mathrm{CaO}\\)）结构**疏松**，不能阻挡空气进入且极易与水反应，故钙须密封保存；钠不仅氧化膜疏松且极易与空气中的水、氧剧烈反应，故须浸没在煤油中。","镁与沸水反应：\\(\\mathrm{Mg(s)} + 2\\mathrm{H_2O(l)} \\xrightarrow{\\Delta} \\mathrm{Mg(OH)_2(s)} + \\mathrm{H_2(g)}\\uparrow\\)。"],"ans":"镁表面形成致密坚固 MgO 膜阻隔进一步氧化；钙表面 CaO 疏松且易吸水；Mg + 2H₂O —(△)→ Mg(OH)₂ + H₂↑。","markingPoints":["对比 MgO 致密抗腐蚀 vs CaO 疏松易吸水反应（2分）","正确配平镁与热水/沸水反应方程式并标注加热条件与气体箭头（2分）"],"verification":"教材 p.240 原文明确指出 MgO 致密坚固、CaO 疏松易与水反应。","pitfall":"误答“镁不活泼所以不用密封保存”——镁其实很活泼，只是靠致密氧化膜保护。"},{"id":"chem10-10.1-q4","tier":"L3","tierLabel":"L3 预试","examStyle":"P1 选择","q":"将 \\(2.4\\text{ g}\\) 金属镁条在空气中充分点燃燃烧（空气中含 \\(\\mathrm{O_2}\\) 和 \\(\\mathrm{N_2}\\)），收集燃烧后的全部白色及淡黄色固体粉末，再将其加入足量 \\(1.0\\text{ mol\\,L}^{-1}\\) 稀盐酸中完全溶解。已知整个反应中镁全部转化为 \\(\\mathrm{Mg^{2+}}\\)，则下列说法**正确**的是（　）。（\\(A_r(\\mathrm{Mg}) = 24\\)）","options":["A. 燃烧固体加稀盐酸后不可能放出任何气体","B. 最终溶液中产生的 \\(\\mathrm{MgCl_2}\\) 物质的量一定等于 \\(0.10\\text{ mol}\\)","C. 燃烧产物中只含 \\(\\mathrm{MgO}\\) 一种物质","D. 若燃烧固体加水，则所有固体全部迅速溶解得澄清溶液"],"correctOption":"B","given":"n(Mg) = 2.4 / 24 = 0.10 mol；在空气中点燃生成 MgO 与少量 Mg₃N₂","method":"利用镁原子守恒判断最终 MgCl₂ 的量，并注意 Mg₃N₂ 与水/酸反应生成 NH₃/NH₄⁺","principle":"无论中间生成 MgO 还是 Mg₃N₂，最终溶于足量稀盐酸时，Mg 原子全部进入 MgCl₂。","steps":["A 错：虽 MgO 与稀盐酸不产气，但若产物含 Mg₃N₂ 则会与稀盐酸反应生成 MgCl₂ 与 NH₄Cl（不产气），但若镁未燃尽剩余单质则会产 H₂；不过本题若完全燃烧，Mg₃N₂ 加水才产 NH₃ 气体，加过量酸生成 NH₄Cl。无论如何看 B 最稳妥确定！","B 正确：由镁元素原子守恒，\\(n(\\mathrm{MgCl_2}) = n(\\mathrm{Mg}) = 0.10\\text{ mol}\\)，与中间产物中 MgO 与 Mg₃N₂ 的比例毫无关系！","C 错：空气中燃烧还生成少量淡黄色 Mg₃N₂。","D 错：MgO 难溶于水，Mg₃N₂ 与水反应生成白色难溶 Mg(OH)₂ 沉淀。"],"ans":"B","markingPoints":["利用镁元素原子守恒跳过中间复杂比例"],"verification":"原子守恒在多路径无机反应计算中最快最稳。","pitfall":"误选 C 忘记 Mg 在空气中还会与 N₂ 生成少量 Mg₃N₂。"},{"id":"chem10-10.1-q5","tier":"L4","tierLabel":"L4 统考压轴","examStyle":"P2 综合计算","q":"将一定质量的 \\(\\mathrm{Mg}\\) 和 \\(\\mathrm{Ca}\\) 合金粉末 \\(6.4\\text{ g}\\) 投入足量冷水中充分反应（假设 \\(\\mathrm{Mg}\\) 在冷水中反应极慢可忽略，仅 \\(\\mathrm{Ca}\\) 完全反应；或再另取等质量 \\(6.4\\text{ g}\\) 该合金粉末投入足量稀盐酸中使其**完全溶解**），实验测得：(1) 投入足量稀盐酸时，在标准状况下共收集到 \\(\\mathrm{H_2}\\ 4.48\\text{ L}\\)；(2) 求原合金中 \\(\\mathrm{Mg}\\) 和 \\(\\mathrm{Ca}\\) 的物质的量及质量分数。（\\(A_r: \\mathrm{Mg}=24, \\mathrm{Ca}=40\\)）","given":"m(合金)=6.4 g, 投入足量稀盐酸生成标况 V(H₂)=4.48 L (n=0.200 mol)","method":"利用二元合金总质量与总产氢物质的量列二元一次方程组","principle":"1 mol Mg 和 1 mol Ca 均失去 2 mol 电子，各自与足量稀盐酸均生成 1 mol H₂。","steps":["计算稀盐酸实验生成氢气总量：\\(n(\\mathrm{H_2}) = \\frac{4.48}{22.4} = 0.200\\text{ mol}\\)。","设 \\(6.4\\text{ g}\\) 合金中含 \\(\\mathrm{Mg}\\) 为 \\(x\\text{ mol}\\)，\\(\\mathrm{Ca}\\) 为 \\(y\\text{ mol}\\)。","由质量守恒得：\\(24x + 40y = 6.4\\)（式①）。","由 \\(\\mathrm{Mg + 2HCl \\to MgCl_2 + H_2}\\uparrow\\) 及 \\(\\mathrm{Ca + 2HCl \\to CaCl_2 + H_2}\\uparrow\\) 得产氢守恒：\\(x + y = 0.200\\)（式②）。","式①减去 \\(24 \\times\\) 式②：\\(16y = 6.4 - 4.8 = 1.6 \\implies y = 0.100\\text{ mol}\\)，代回式②得 \\(x = 0.100\\text{ mol}\\)。","计算质量分数：\\(m(\\mathrm{Mg}) = 0.100 \\times 24 = 2.40\\text{ g}\\)（占比 \\(\\frac{2.40}{6.40} \\times 100\\% = 37.5\\%\\)）；\\(m(\\mathrm{Ca}) = 0.100 \\times 40 = 4.00\\text{ g}\\)（占比 \\(62.5\\%\\)）。"],"ans":"合金含 Mg 0.100 mol（2.40 g，占 37.5%）与 Ca 0.100 mol（4.00 g，占 62.5%）。","markingPoints":["算得 n(H₂)=0.200 mol 并写出两金属与 HCl 计量关系（2分）","建立质量与物质的量联立方程组并解出 x=0.100, y=0.100（2分）","算得质量分数 37.5% 与 62.5%（1分）"],"verification":"2.40 g + 4.00 g = 6.40 g；总金属 0.200 mol 对应 +2 价离子放出 0.200 mol H₂，完全吻合。","pitfall":"若把 Ca 误按 +1 价计算（受 Na 干扰），会导致式②出错。"}],"cheatSheet":["IIA 族（ns²）：密度、硬度、熔沸点远高于同周期 IA 族；与水反应剧烈度 Be < Mg < Ca < Sr < Ba。","海水提镁：苦卤 + 石灰乳（贝壳煅烧）→ \\(\\mathrm{Mg(OH)_2}\\) + 盐酸 → \\(\\mathrm{MgCl_2}\\) —(熔融电解)→ Mg + \\(\\mathrm{Cl_2}\\)。","镁的特异燃烧：空气中得 \\(\\mathrm{MgO}\\)（主）+ 少量 \\(\\mathrm{Mg_3N_2}\\)；在 \\(\\mathrm{CO_2}\\) 中剧烈燃烧生 \\(\\mathrm{MgO + C}\\)，着火严禁用 \\(\\mathrm{CO_2}\\) 灭火！","等质量 Mg 在足量气体中燃烧固体质量顺序：\\(\\mathrm{CO_2}\\;(46\\text{ g/mol Mg}) > \\mathrm{O_2}\\;(40\\text{ g}) > \\mathrm{N_2}\\;(33.3\\text{ g})\\)。"],"kbEntryIds":["kb-chem10-alkaline-earth","kb-chem10-mg-seawater"],"quiz":{"q":"镁条着火时若误用干粉灭火器（主要成分 \\(\\mathrm{NaHCO_3}\\) 粉末）扑救，为什么反而火势更旺？","given":"NaHCO₃ 受热分解放出 CO₂ 与水蒸气","method":"结合 NaHCO₃ 热分解产物与 Mg 的强还原性反应作答","principle":"2Mg + CO₂ —(点燃)→ 2MgO + C；Mg + 2H₂O(g) —(△)→ Mg(OH)₂ + H₂↑。","steps":["干粉中的 \\(\\mathrm{NaHCO_3}\\) 受热分解产生 \\(\\mathrm{CO_2}\\) 和 \\(\\mathrm{H_2O(g)}\\)。","炽热的镁不仅能在 \\(\\mathrm{CO_2}\\) 中剧烈燃烧生成 \\(\\mathrm{MgO}\\) 和 \\(\\mathrm{C}\\)，还能与水蒸气剧烈反应生成易爆的 \\(\\mathrm{H_2}\\)，因此火势更旺（只能用干燥细沙盖灭）。"],"ans":"因 \\(\\mathrm{NaHCO_3}\\) 分解生成的 \\(\\mathrm{CO_2}\\) 和水蒸气均能与灼热镁剧烈反应放热并产生可燃气体 \\(\\mathrm{H_2}\\)。"}},{"id":"10.2","t":"镁的重要化合物","anchor":{"pages":"化上 p.242–244","syllabus":"3.3.3 氧化镁、氯化镁与硫酸镁的性质、制法及工业用途","examScopes":["sem2_final","uec"],"examWeight":"P1 熔点耐火材料与工业电解原料选择 + P2 转化方程式","terms":"Magnesia (MgO) · Refractory material · Magnesium chloride (MgCl₂·6H₂O) · Epsom salt (MgSO₄) · Chlorophyll","prerequisites":["金属镁化学性质与海水提镁（10.1）","离子晶体熔点与晶格能定性概念（化上 Ch 7.3）"],"goals":["记住氧化镁（苦土）高熔点（2852 ℃）的特性、耐火材料用途及工业由菱镁矿煅烧制取的反应。","解释为什么工业冶炼金属镁采用电解熔融 MgCl₂ 而不采用电解熔融 MgO（p.250 作答题 3）。","掌握 MgCl₂ 易潮解造成粗盐受潮的原理，以及 MgSO₄ 在工业和农业（叶绿素合成）中的作用。"]},"concepts":[{"kind":"definition","title":"氧化镁（MgO，苦土/镁氧）与氯化镁（MgCl₂）","pageRef":"化上 p.243、p.250","body":["**氧化镁（\\(\\mathrm{MgO}\\)）**：俗称**苦土**或镁氧（矿物为方镁石，图 10-5）。它是轻而松软的白色粉末，**熔点高达 2852 ℃，沸点 3600 ℃**，因此是极为优良的**耐火材料**（制造耐火砖、耐火管、耐火坩埚）。","**MgO 化学性质与工业制法**：\\(\\mathrm{MgO}\\) 是**碱性氧化物**，暴露空气中易缓慢吸水生成氢氧化镁：\\(\\mathrm{MgO(s) + H_2O(l) \\to Mg(OH)_2(s)}\\)；易溶于稀酸：\\(\\mathrm{MgO(s) + 2HCl(aq) \\to MgCl_2(aq) + H_2O(l)}\\)。工业上不用昂贵的燃烧镁条法，而是将**菱镁矿（\\(\\mathrm{MgCO_3}\\)）**在 550 ℃ 高温煅烧：\\(\\mathrm{MgCO_3(s)} \\xrightarrow{\\text{高温}} \\mathrm{MgO(s) + CO_2(g)}\\uparrow\\)。","**为什么冶炼镁电解熔融 \\(\\mathrm{MgCl_2}\\) 而非 \\(\\mathrm{MgO}\\)？（p.250 作答题 3）**：\\(\\mathrm{MgO}\\) 的熔点高达 **2852 ℃**，将其加热至熔融态会消耗极巨大的电能并损坏电解槽耐火材料；而 \\(\\mathrm{MgCl_2}\\) 的熔点仅约 **714 ℃**，熔融电解能耗低、经济可行得多。","**氯化镁（\\(\\mathrm{MgCl_2}\\)）**：无色晶体，易溶于水，有苦味，**极易潮解**。生活中**粗制食盐**容易吸湿受潮，正是因为其中含有少量 \\(\\mathrm{MgCl_2}\\) 杂质！通常以六水合物 \\(\\mathrm{MgCl_2\\cdot 6H_2O}\\) 晶体存在（加热直接脱水易发生部分水解生成 \\(\\mathrm{Mg(OH)Cl}\\)，工业需在干燥 \\(\\mathrm{HCl}\\) 气流中脱水）。"],"takeaway":"记住两大高熔点耐火氧化物：MgO（2852 ℃）和 Al₂O₃（2054 ℃）；工业炼镁用熔融 MgCl₂（~714 ℃）避开高熔点 MgO，而炼铝用冰晶石助熔降低 Al₂O₃ 熔点。"},{"kind":"definition","title":"硫酸镁（MgSO₄）与生物体中的镁元素（图 10-4 叶绿素）","pageRef":"化上 p.242–243","body":["**生命化学作用（p.242 感知生活）**：镁是动植物必需元素，作为多种酶的活化剂维持肌肉代谢与中枢神经正常功能；更重要的是，**每个植物叶绿素（chlorophyll）分子的中心都有一个镁离子（\\(\\mathrm{Mg^{2+}}\\)）**（图 10-4），缺乏镁时植物叶片会失绿变黄，无法进行光合作用。","**硫酸镁（\\(\\mathrm{MgSO_4}\\)）**：易溶于水（七水合物 \\(\\mathrm{MgSO_4\\cdot 7H_2O}\\) 俗称泻盐），广泛用作**媒染剂、医用泻盐**，也用于造纸、纺织、陶瓷和油漆工业，并在农业上作为重要的**镁肥**。"],"takeaway":"叶绿素中心离子是 Mg²⁺，血红蛋白中心离子是 Fe²⁺——生物与化学跨学科常考！"},{"kind":"mechanism","title":"镁盐—氧化物—氢氧化物核心转化链（p.244 思考题 10b）","pageRef":"化上 p.244、p.250","body":["**教材核心链（p.244 思考题 10b-1）**：\\(\\mathrm{MgCO_3 \\to MgO \\to Mg(OH)_2 \\to MgSO_4}\\)：","- ① \\(\\mathrm{MgCO_3(s)} \\xrightarrow{\\text{高温}} \\mathrm{MgO(s) + CO_2(g)}\\uparrow\\)","- ② \\(\\mathrm{MgO(s) + H_2O(l) \\to Mg(OH)_2(s)}\\)（注：若快速大量转化也可先加盐酸得 \\(\\mathrm{MgCl_2}\\) 再加 \\(\\mathrm{NaOH}\\) 沉淀）","- ③ \\(\\mathrm{Mg(OH)_2(s) + H_2SO_4(aq) \\to MgSO_4(aq) + 2H_2O(l)}\\)","**镁化合物与其它物质鉴别（p.244 思考题 10b-2）**：区分白色粉末状的 \\(\\mathrm{MgCl_2}\\) 和 \\(\\mathrm{MgCO_3}\\)，只需**取样加水**（\\(\\mathrm{MgCl_2}\\) 易溶得澄清溶液，\\(\\mathrm{MgCO_3}\\) 难溶呈白色浑浊）或**滴加稀盐酸**（\\(\\mathrm{MgCO_3}\\) 冒无色气泡，\\(\\mathrm{MgCl_2}\\) 无气泡）。"],"takeaway":"Mg(OH)₂ 是中强碱（难溶于水），只溶于酸而不溶于过量强碱，与两性 Al(OH)₃ 截然不同。"}],"formulas":[{"title":"菱镁矿煅烧与氧化镁水合/酸溶方程","tex":"\\mathrm{MgCO_3(s)} \\xrightarrow{\\text{高温}(550\\ ^\\circ\\mathrm{C})} \\mathrm{MgO(s)} + \\mathrm{CO_2(g)}\\uparrow,\\qquad \\mathrm{MgO(s)} + 2\\mathrm{H^+(aq)} \\longrightarrow \\mathrm{Mg^{2+}(aq)} + \\mathrm{H_2O(l)}","plain":"MgCO3 —(550℃)→ MgO + CO2↑; MgO + 2H⁺ → Mg²⁺ + H2O","conditions":"MgO 为碱性氧化物，易溶于强酸，不溶于碱","pageRef":"化上 p.243","note":"注意 MgCO₃ 分解温度（约 550 ℃）显著低于 CaCO₃（约 900 ℃）。"},{"title":"氢氧化镁沉淀与酸溶反应","tex":"\\mathrm{Mg^{2+}(aq)} + 2\\mathrm{OH^-(aq)} \\longrightarrow \\mathrm{Mg(OH)_2(s)}\\downarrow,\\qquad \\mathrm{Mg(OH)_2(s)} + 2\\mathrm{H^+(aq)} \\longrightarrow \\mathrm{Mg^{2+}(aq)} + 2\\mathrm{H_2O(l)}","plain":"Mg²⁺ + 2OH⁻ → Mg(OH)2↓; Mg(OH)2 + 2H⁺ → Mg²⁺ + 2H2O","conditions":"生成白色沉淀且不溶于过量 NaOH 溶液","pageRef":"化上 p.244、p.247","note":"工业上用 Ca(OH)₂ 石灰乳替代 NaOH 沉淀海水中的 Mg²⁺，利用 Mg(OH)₂ 溶解度更小实现沉淀转化。"}],"pitfalls":[{"title":"误以为工业上通过燃烧镁条来制取氧化镁","wrong":"“工业上通常将金属镁条在空气中点燃来大量生产氧化镁。”","diagnosis":"教材 p.244 思考题 10b-3 陷阱：金属镁本身就需要耗费大量电能从海水中电解冶炼得来，拿昂贵的金属镁去烧成廉价的氧化镁本末倒置！","right":"工业上是将天然**菱镁矿（\\(\\mathrm{MgCO_3}\\)）在 550 ℃ 高温煅烧**制取氧化镁，原料廉价易得。","checkRule":"工业原料选择必须符合“矿石 → 目标产品”经济路径，绝不拿高能耗单质反烧氧化物。"},{"title":"误以为粗盐潮解是因为氯化钠自身极易吸湿","wrong":"“纯氯化钠晶体放在潮湿空气中也会迅速吸水潮解化水。”","diagnosis":"纯净的 \\(\\mathrm{NaCl}\\) 几乎不潮解；潮解的是海盐粗盐中混有的极易吸湿的卤化物杂质。","right":"粗制食盐容易吸湿受潮，是因为其中含有少量极易潮解的 **\\(\\mathrm{MgCl_2}\\)（及 \\(\\mathrm{CaCl_2}\\)）**杂质（p.243）。","checkRule":"精制食盐不潮解，粗盐潮解归因于 MgCl₂ 杂质。"}],"examples":[{"label":"例 10.2.1","tier":"L2","tierLabel":"L2 期末必考","title":"镁及其化合物转化网络与工业原料经济辨析（p.250 第 3、4 题）","prompt":"(1) 用化学方程式实现如下转化（p.250 第 4-(1) 题）：\\(\\mathrm{Mg \\to MgO \\to MgCl_2 \\to Mg(OH)_2 \\to MgCl_2}\\)；(2) 简要解释工业冶炼金属镁时，为什么电解熔融的氯化镁（\\(\\mathrm{MgCl_2}\\)）而不是熔融的氧化镁（\\(\\mathrm{MgO}\\)）？","clues":"注意第 3 步与第 4 步可逆转化（碱沉淀与酸溶解），氧化镁高熔点达 2852 ℃。","strategy":"按顺序逐一配平并标明条件；结合表 10-2/p.243 的熔点数值从能耗与设备寿命作答。","given":"转化链：Mg → MgO → MgCl₂ → Mg(OH)₂ → MgCl₂","principle":"碱性氧化物酸溶、复分解沉淀及熔点对电解能耗的决定性影响。","steps":["第(1)问四步方程式：","- ① \\(2\\mathrm{Mg(s) + O_2(g)} \\xrightarrow{\\text{点燃}} 2\\mathrm{MgO(s)}\\)","- ② \\(\\mathrm{MgO(s) + 2HCl(aq) \\longrightarrow MgCl_2(aq) + H_2O(l)}\\)","- ③ \\(\\mathrm{MgCl_2(aq) + 2NaOH(aq) \\longrightarrow Mg(OH)_2(s)\\downarrow + 2NaCl(aq)}\\)","- ④ \\(\\mathrm{Mg(OH)_2(s) + 2HCl(aq) \\longrightarrow MgCl_2(aq) + 2H_2O(l)}\\)","第(2)问原因：氧化镁（\\(\\mathrm{MgO}\\)）属于离子晶体，离子键极强，熔点高达 **\\(2852\\ ^\\circ\\mathrm{C}\\)**（因此才用作耐火坩埚），将其熔融需耗费极高电能且对电解槽耐温材料要求极苛刻；而氯化镁（\\(\\mathrm{MgCl_2}\\)）熔点仅约 **\\(714\\ ^\\circ\\mathrm{C}\\)**，熔融电解能耗大幅降低、易于工业实现。"],"answer":"(1) 见上述四步方程式；(2) MgO 熔点高达 2852 ℃ 熔融能耗极大，而 MgCl₂ 熔点低得多（~714 ℃），经济节能。","markingPoints":["四步转化方程式及条件/沉淀符号全部准确（3分）","点出 MgO 熔点极高（2852 ℃）导致能耗高，MgCl₂ 熔点较低（2分）"],"verification":"对照化上 p.243 氧化镁熔点数据及 p.250 习题 3–4 核对。","pitfall":"若写 ②③ 时漏掉水溶液状态或沉淀符号（↓），会在卷二必答题中扣细节分。"},{"label":"例 10.2.2","tier":"L3","tierLabel":"L3 预试拔高","title":"含 Mg(OH)₂ 与 Ca(OH)₂ 混合沉淀的提纯（p.251 第 6-(3) 题）","prompt":"在海水提镁流程中，向苦卤加入石灰乳过滤后得到的 \\(\\mathrm{Mg(OH)_2}\\) 沉淀中，有时会混有少量未反应或析出的 \\(\\mathrm{Ca(OH)_2}\\) 固体杂质。请设计一套简明的实验步骤除去 \\(\\mathrm{Mg(OH)_2}\\) 中的 \\(\\mathrm{Ca(OH)_2}\\) 杂质（提示：比较 \\(\\mathrm{Mg(OH)_2}\\) 与 \\(\\mathrm{Ca(OH)_2}\\) 的溶解性差异）。","clues":"利用“沉淀转化原理”：\\(\\mathrm{Mg(OH)_2}\\) 难溶而 \\(\\mathrm{Ca(OH)_2}\\) 微溶（溶解度较大），只要加入可溶性镁盐（如 \\(\\mathrm{MgCl_2}\\) 溶液），就能把 \\(\\mathrm{Ca(OH)_2}\\) 全部转化为目标物 \\(\\mathrm{Mg(OH)_2}\\)！","strategy":"加过量 \\(\\mathrm{MgCl_2}\\) 溶液充分搅拌转化 → 过滤 → 洗涤（注意不能加稀盐酸！）。","given":"固体混合物：Mg(OH)₂（主）+ Ca(OH)₂（少量杂质）","principle":"沉淀转化向更难溶方向进行：Ca(OH)₂(s) + Mg²⁺(aq) → Mg(OH)₂(s) + Ca²⁺(aq)。","steps":["第一步：将混有 \\(\\mathrm{Ca(OH)_2}\\) 的 \\(\\mathrm{Mg(OH)_2}\\) 沉淀放入烧杯中，加入**足量的 \\(\\mathrm{MgCl_2}\\) 溶液**，充分搅拌使其发生沉淀转化反应：\\(\\mathrm{Ca(OH)_2(s) + MgCl_2(aq) \\longrightarrow Mg(OH)_2(s)\\downarrow + CaCl_2(aq)}\\)。","第二步：充分反应后进行**过滤**，并用蒸馏水**洗涤**滤渣 2–3 次（除去表面残留的 \\(\\mathrm{CaCl_2}\\) 和过量 \\(\\mathrm{MgCl_2}\\)），干燥即得纯净 \\(\\mathrm{Mg(OH)_2}\\)。"],"answer":"向沉淀中加入足量 MgCl₂ 溶液充分搅拌，使 Ca(OH)₂ 转化为 Mg(OH)₂ 与可溶的 CaCl₂，再过滤、水洗即得纯净 Mg(OH)₂。","markingPoints":["选用足量 MgCl₂（或 MgSO₄）溶液作除杂试剂（2分）","写出沉淀转化原理并包含过滤、洗涤步骤（2分）"],"verification":"此法不但除掉了 Ca(OH)₂，还把杂质里的 OH⁻ 转化为更多的目标物 Mg(OH)₂，零损失！","pitfall":"切忌答“加大量水溶解过滤”，虽然 Ca(OH)₂ 微溶，但直接水洗耗水量极巨且效率低；更切忌加稀酸（会同时溶解 Mg(OH)₂）。"}],"practice":[{"id":"chem10-10.2-q1","tier":"L1","tierLabel":"L1 基础","examStyle":"P1 选择","q":"植物进行光合作用必不可少的叶绿素分子中，其中心配位的金属离子是（　）。","options":["A. \\(\\mathrm{Fe^{2+}}\\)","B. \\(\\mathrm{Ca^{2+}}\\)","C. \\(\\mathrm{Mg^{2+}}\\)","D. \\(\\mathrm{Na^+}\\)"],"correctOption":"C","given":"p.242 图 10-4 叶绿素分子结构","method":"直接记忆植物叶绿素中心离子","principle":"每个叶绿素分子中心都有一个 Mg²⁺，故硫酸镁在农业上常用作镁肥。","steps":["对照图 10-4，卟啉环中心配位的金属离子为 Mg²⁺。"],"ans":"C","markingPoints":["识别叶绿素中的 Mg²⁺"],"verification":"化上 p.242 原文明确说明。","pitfall":"与动物血红蛋白中心的 Fe²⁺ 混淆而错选 A。"},{"id":"chem10-10.2-q2","tier":"L2","tierLabel":"L2 期末","examStyle":"P1 选择","q":"下列关于氧化镁（\\(\\mathrm{MgO}\\)）的说法中，**正确**的是（　）（p.244 思考题 10b-3）。","options":["A. 氧化镁是酸性氧化物，可与氢氧化钠溶液反应","B. 氧化镁熔点高达 2852 ℃，是制造耐火砖和耐火坩埚的优良耐火材料","C. 氧化镁是易溶于水的白色晶体","D. 工业上通常通过大量燃烧金属镁条来制备氧化镁"],"correctOption":"B","given":"p.243 氧化镁性质与 p.244 思考题 10b-3","method":"排除错误类别、溶解度与工业原料选项","principle":"MgO 是高熔点碱性氧化物，难溶于水（仅缓慢吸水反应），工业由菱镁矿煅烧制取。","steps":["A 错：MgO 是碱性氧化物；C 错：极难溶；D 错：工业煅烧菱镁矿 MgCO₃；B 正确。"],"ans":"B","markingPoints":["牢记 MgO 耐火材料特性与碱性氧化物类别"],"verification":"化上 p.243 原文及 p.244 思考题 10b-3 原题。","pitfall":"受 Al₂O₃ 两性干扰错以为 MgO 也呈两性。"},{"id":"chem10-10.2-q3","tier":"L3","tierLabel":"L3 预试","examStyle":"P2 简答","q":"某同学在实验室发现两瓶无标签白色固体粉末，已知分别是 \\(\\mathrm{MgCl_2}\\) 和 \\(\\mathrm{MgCO_3}\\)。请设计两种基于不同原理的简便实验方案将它们鉴别出来，并简述现象与结论。","given":"p.244 思考题 10b-2","method":"分别利用溶解性差异（物理+外观）与碳酸盐遇酸产气差异","principle":"MgCl₂ 易溶于水且不与酸产气；MgCO₃ 难溶于水且与稀盐酸反应放出 CO₂。","steps":["**方案 1（水溶法）**：各取少量粉末于两支试管中，加入适量蒸馏水充分振荡。固体迅速全部溶解得无色澄清溶液的为 **\\(\\mathrm{MgCl_2}\\)**；固体不溶解、呈白色悬浊液的为 **\\(\\mathrm{MgCO_3}\\)**。","**方案 2（加稀盐酸法）**：各取少量粉末于两支试管中，分别滴加稀盐酸。固体溶解并立即有大量无色无味气泡产生（能使澄清石灰水变浑浊）的为 **\\(\\mathrm{MgCO_3}\\)**（\\(\\mathrm{MgCO_3 + 2HCl \\to MgCl_2 + H_2O + CO_2\\uparrow}\\)）；固体直接溶解但无气泡产生的为 **\\(\\mathrm{MgCl_2}\\)**。"],"ans":"方案 1 加水（溶解为 MgCl₂，不溶为 MgCO₃）；方案 2 加稀盐酸（冒泡为 MgCO₃，无泡为 MgCl₂）。","markingPoints":["方案 1 准确利用水溶性差异区分（2分）","方案 2 利用稀盐酸产气泡并给出清晰现象判断（2分）"],"verification":"还可采用充分灼烧测失重或石灰水检验分解产物 CO₂ 的方法。","pitfall":"若误用澄清石灰水直接滴入固体悬浊液，可能无法立即看清变化，加稀盐酸产气泡现象最直观。"},{"id":"chem10-10.2-q4","tier":"L4","tierLabel":"L4 统考压轴","examStyle":"P2 工业定量","q":"工业上将纯净菱镁矿（主要成分 \\(\\mathrm{MgCO_3}\\)，其余杂质不分解也不溶于酸）矿石 \\(10.0\\text{ g}\\) 在 \\(550\\ ^\\circ\\mathrm{C}\\) 下高温煅烧至恒重，冷却后称得固体总质量为 \\(5.60\\text{ g}\\)。求：(1) 反应生成的 \\(\\mathrm{CO_2}\\) 在标准状况下的体积；(2) 该菱镁矿中 \\(\\mathrm{MgCO_3}\\) 的质量分数（\\(A_r: \\mathrm{Mg}=24, \\mathrm{C}=12, \\mathrm{O}=16\\)）。","given":"m(矿石)=10.0 g, 煅烧后 m(固体)=5.60 g, Δm=4.40 g, M(MgCO₃)=84, M(CO₂)=44","method":"利用恒重质量减少量即等于逸出的 CO₂ 气体质量进行守恒计算","principle":"MgCO₃(s) —(高温)→ MgO(s) + CO₂(g)↑，固体减重全部来自 CO₂。","steps":["第(1)问：根据物质不灭定律，减少的质量全部为逸出的二氧化碳质量：\\(m(\\mathrm{CO_2}) = 10.0 - 5.60 = 4.40\\text{ g}\\)。","其物质的量 \\(n(\\mathrm{CO_2}) = \\frac{4.40}{44} = 0.100\\text{ mol}\\)，故标准状况下体积为：\\(V(\\mathrm{CO_2}) = 0.100 \\times 22.4 = 2.24\\text{ L}\\)。","第(2)问：由方程式 \\(\\mathrm{MgCO_3(s)} \\xrightarrow{\\text{高温}} \\mathrm{MgO(s) + CO_2(g)}\\uparrow\\)，知 \\(n(\\mathrm{MgCO_3}) = n(\\mathrm{CO_2}) = 0.100\\text{ mol}\\)。","故 \\(m(\\mathrm{MgCO_3}) = 0.100 \\times 84 = 8.40\\text{ g}\\)，质量分数为：\\(w(\\mathrm{MgCO_3}) = \\frac{8.40}{10.0} \\times 100\\% = 84.0\\%\\)。"],"ans":"(1) 标况下 CO₂ 体积为 2.24 L；(2) 菱镁矿中 MgCO₃ 质量分数为 84.0%。","markingPoints":["识别减重 4.40 g 即 CO₂ 质量并求出 0.100 mol / 2.24 L（2分）","由 1:1 计量求得 MgCO₃ 8.40 g 及纯度 84.0%（2分）"],"verification":"生成 0.100 mol MgO 质量为 4.00 g，加上不分解杂质 1.60 g 正好为 5.60 g。","pitfall":"误把残余固体 5.60 g 当作纯净 \\(\\mathrm{MgO}\\) 直接折算，会漏掉不反应杂质 1.60 g 而算出超过 100% 的荒谬纯度。"}],"cheatSheet":["MgO（苦土）：高熔点（2852 ℃）碱性氧化物，优良耐火材料，工业由菱镁矿（\\(\\mathrm{MgCO_3}\\)）550 ℃ 煅烧制得。","工业炼镁电解熔融 \\(\\mathrm{MgCl_2}\\)（~714 ℃）而不电解高熔点 \\(\\mathrm{MgO}\\)，大幅节约能耗。","\\(\\mathrm{MgCl_2}\\) 极易潮解是粗制食盐受潮的元凶；\\(\\mathrm{Mg^{2+}}\\) 是叶绿素分子中心离子（镁肥 \\(\\mathrm{MgSO_4}\\)）。"],"kbEntryIds":["kb-chem10-mg-compounds"],"quiz":{"q":"粗制食盐放置久了容易吸湿潮解结块，其主要原因是什么？","given":"粗盐杂质与表 10.2 氯化镁性质","method":"指出粗盐中易潮解的杂质成分","principle":"纯 NaCl 不易潮解，粗盐含少量极易潮解的 MgCl₂（及 CaCl₂）。","steps":["海盐粗盐中含有少量 \\(\\mathrm{MgCl_2}\\)（以及少量 \\(\\mathrm{CaCl_2}\\)），由于 \\(\\mathrm{MgCl_2}\\) 具有极强的吸湿潮解性，导致粗盐吸湿受潮。"],"ans":"粗盐中混有少量极易吸湿潮解的 \\(\\mathrm{MgCl_2}\\)（及 \\(\\mathrm{CaCl_2}\\)）杂质。"}},{"id":"10.3","t":"钙的重要化合物","anchor":{"pages":"化上 p.244–246","syllabus":"3.3.4 氧化钙、氢氧化钙、碳酸钙、硫酸钙、氯化钙及硬水软化","examScopes":["sem2_final","uec"],"examWeight":"P1 石膏/CaCl₂ 禁忌/石灰乳辨析 + P2 钙转化网与硬水软化原理","terms":"Quicklime (CaO) · Slaked lime (Ca(OH)₂) · Gypsum (CaSO₄·2H₂O) · Plaster of Paris · Hard water softening","prerequisites":["碳酸盐与碳酸氢盐转化规律（化上 Ch 9.3, Ch 12.2）","常见碱与盐的溶解性"],"goals":["掌握石灰石（CaCO₃）—生石灰（CaO）—熟石灰（Ca(OH)₂）的工业转化方程式及石灰乳与石灰水的区别。","阐明 CaCO₃ 与 Ca(HCO₃)₂ 的可逆转化机制，并系统区分暂时硬水与永久硬水的成因及软化方法。","记住生石膏与熟石膏的脱水反应（150–170 ℃）及无水 CaCl₂ 不能用于干燥氨气（NH₃）的原因。"]},"concepts":[{"kind":"mechanism","title":"生石灰（CaO）、熟石灰（Ca(OH)₂）与石灰石（CaCO₃）三角循环","pageRef":"化上 p.244–245","body":["**生理与存在**：人体骨骼与牙齿主要矿物质为羟基磷灰石 \\(\\mathrm{Ca_5(PO_4)_3OH}\\)；自然界钙矿主要有石灰石、大理石、方解石、白垩（均为 \\(\\mathrm{CaCO_3}\\)）、石膏、萤石（\\(\\mathrm{CaF_2}\\)）和白云石。","**生石灰（\\(\\mathrm{CaO}\\)）**：白色固体，碱性氧化物，强吸湿性（常用作干燥剂如食品干燥包），易吸收空气中 \\(\\mathrm{CO_2}\\) 与水分变硬成 \\(\\mathrm{CaCO_3}\\)。工业上通过**高温煅烧石灰石**制备：\\(\\mathrm{CaCO_3(s)} \\xrightarrow{\\text{高温}} \\mathrm{CaO(s) + CO_2(g)}\\uparrow\\)。","**熟石灰 / 消石灰（\\(\\mathrm{Ca(OH)_2}\\)）**：生石灰遇水剧烈反应并**放出大量热**：\\(\\mathrm{CaO(s) + H_2O(l) \\to Ca(OH)_2(s)}\\)。它是白色粉末，具强碱性（溶解度随温度升高而减小！）：","- **石灰乳**：\\(\\mathrm{Ca(OH)_2}\\) 与水形成的白色悬浊液（用于粉刷墙壁、制漂白粉、海水提镁沉淀剂）。","- **石灰水**：\\(\\mathrm{Ca(OH)_2}\\) 的澄清饱和水溶液（实验室检验 \\(\\mathrm{CO_2}\\)，粉刷墙壁硬化反应：\\(\\mathrm{Ca(OH)_2 + CO_2 \\to CaCO_3\\downarrow + H_2O}\\)）。","- 农业上熟石灰常用来**降低土壤酸性、改良酸性土壤**，生熟石灰也是制电石、纯碱和冶金助熔剂的重要原料。"],"takeaway":"CaO、Ca(OH)₂、CaCO₃ 构成工业与建筑化学经典三角：煅烧分解（CaCO₃→CaO）、加水放热（CaO→Ca(OH)₂）、吸碳硬化（Ca(OH)₂→CaCO₃）。"},{"kind":"law","title":"溶洞形成机制与硬水分类（暂时硬度 vs 永久硬度）及软化方法","pageRef":"化上 p.245、p.279 综合","body":["**溶洞与水垢的可逆平衡（p.279 衔接）**：难溶于水的 \\(\\mathrm{CaCO_3}\\) 在含 \\(\\mathrm{CO_2}\\) 的地下水作用下缓慢转化为可溶于水的 \\(\\mathrm{Ca(HCO_3)_2}\\) 形成喀斯特溶洞；当 \\(\\mathrm{Ca(HCO_3)_2}\\) 溶液受热或减压时又分解沉积出 \\(\\mathrm{CaCO_3}\\) 形成钟乳石、石笋及锅炉水垢：\\(\\mathrm{CaCO_3(s) + H_2O(l) + CO_2(g) \\rightleftharpoons Ca(HCO_3)_2(aq)}\\)。","**硬水的分类与软化（UEC 统考高频应用）**：含有较多可溶性钙、镁离子（\\(\\mathrm{Ca^{2+}, Mg^{2+}}\\)）的水称为**硬水**（硬水与肥皂反应生成浮渣，锅炉使用易结水垢引发受热不均甚至爆炸）。按伴随阴离子分为两类："],"table":{"headers":["硬水类型","主要溶质离子","能否用煮沸法软化","常用软化方法与核心反应"],"rows":[["暂时硬水","Ca(HCO₃)₂、Mg(HCO₃)₂","可以（最简便）","①煮沸：Ca(HCO₃)₂ —(△)→ CaCO₃↓ + H₂O + CO₂↑；Mg(HCO₃)₂ 煮沸进一步水解成更难溶的 Mg(OH)₂↓；②石灰法：加适量 Ca(OH)₂ 沉淀"],["永久硬水","CaSO₄、MgSO₄、CaCl₂、MgCl₂","不能（煮沸不沉淀）","①药剂法（加纯碱 Na₂CO₃）：Ca²⁺ + CO₃²⁻ → CaCO₃↓；②离子交换树脂（磺化煤，Na⁺ 置换 Ca²⁺/Mg²⁺）或蒸馏法"]]},"takeaway":"记忆口诀：“暂时硬度靠煮沸，永久硬度加纯碱”；既有暂时又有永久硬度时，工业常采用“石灰—纯碱法”联合软化！"},{"kind":"definition","title":"硫酸钙（石膏与熟石膏）与无水氯化钙（干燥剂禁忌）","pageRef":"化上 p.245–246","body":["**生石膏与熟石膏（p.245–246）**：天然石膏矿主要成分是二水合硫酸钙 **\\(\\mathrm{CaSO_4\\cdot 2H_2O}\\)**（称石膏或生石膏）。加热到 **150–170 ℃** 时失去大部分结晶水变为**熟石膏 \\(\\mathrm{(CaSO_4)_2\\cdot H_2O}\\)**（即半水硫酸钙）；熟石膏加水后重新转化为石膏，并伴随**微量的体积膨胀和放热**，因此可用来浇铸各种细腻雕塑模型（图 10-7）及制作医用**石膏绷带**；生石膏还用来调节**水泥的硬化速度**，食用级石膏粉作豆腐凝固剂。","**氯化钙（\\(\\mathrm{CaCl_2}\\)）**：白色颗粒，常以六水合盐 \\(\\mathrm{CaCl_2\\cdot 6H_2O}\\) 存在，易溶于水且**溶水放大量热**；加热至 **200 ℃ 以上**完全脱水生成**无水氯化钙**。它吸水性极强，常用作干燥剂、道路融冰剂及电解制金属钙的原料。","**干燥剂重要禁忌（p.246 思考题 10c-1）**：无水 \\(\\mathrm{CaCl_2}\\) 虽是常用中性干燥剂（可干 \\(\\mathrm{H_2, O_2, CO_2, HCl}\\) 等），但**绝对不能用来干燥氨气（\\(\\mathrm{NH_3}\\)）**，因为无水 \\(\\mathrm{CaCl_2}\\) 会与 \\(\\mathrm{NH_3}\\) 剧烈吸附并配位反应生成固态络合物 \\(\\mathrm{CaCl_2\\cdot 8NH_3}\\)（干燥 \\(\\mathrm{NH_3}\\) 应改用**碱石灰**）。"],"takeaway":"牢记化学式区分：生石膏是 CaSO₄·2H₂O，熟石膏是 (CaSO₄)₂·H₂O（或 CaSO₄·½H₂O）；无水 CaCl₂ 可干 CO₂/HCl 但严禁干 NH₃！"}],"formulas":[{"title":"石膏与熟石膏可逆转化方程式","tex":"2\\mathrm{CaSO_4}\\cdot 2\\mathrm{H_2O(s)} \\xrightarrow{\\Delta(150\\text{–}170\\ ^\\circ\\mathrm{C})} (\\mathrm{CaSO_4})_2\\cdot \\mathrm{H_2O(s)} + 3\\mathrm{H_2O(l)}","plain":"2CaSO4·2H2O(s) —(150–170℃)→ (CaSO4)2·H2O(s) + 3H2O(l)","conditions":"控制温度 150–170 ℃（温度过高全脱水成“死烧石膏”失去凝结能力）","pageRef":"化上 p.245","note":"逆反应加水凝结伴有微量体积膨胀，使石膏像填充模具棱角分明。"},{"title":"无水氯化钙吸收氨气及石灰硬水转化反应","tex":"\\mathrm{CaCl_2(s)} + 8\\mathrm{NH_3(g)} \\longrightarrow \\mathrm{CaCl_2}\\cdot 8\\mathrm{NH_3(s)},\\qquad \\mathrm{Ca(HCO_3)_2(aq)} \\xrightarrow{\\Delta} \\mathrm{CaCO_3(s)}\\downarrow + \\mathrm{H_2O(l)} + \\mathrm{CO_2(g)}\\uparrow","plain":"CaCl2 + 8NH3 → CaCl2·8NH3; Ca(HCO3)2 —(△)→ CaCO3↓ + H2O + CO2↑","conditions":"无水 CaCl₂ 禁止作 NH₃ 干燥剂；煮沸法只软化暂时硬水","pageRef":"化上 p.246、p.279","note":"永久硬水中的 Ca²⁺ 需加纯碱反应：Ca²⁺(aq) + CO₃²⁻(aq) → CaCO₃(s)↓。"}],"pitfalls":[{"title":"误用无水 CaCl₂ 干燥氨气","wrong":"“无水氯化钙属于中性干燥剂，既不显酸性也不显碱性，因此可以用来干燥氨气。”","diagnosis":"仅从酸碱角度判断而忽视了 \\(\\mathrm{Ca^{2+}}\\) 与 \\(\\mathrm{NH_3}\\) 之间极强的络合配位吸附反应。","right":"无水 \\(\\mathrm{CaCl_2}\\) 能与 \\(\\mathrm{NH_3}\\) 结合生成 \\(\\mathrm{CaCl_2\\cdot 8NH_3}\\)，**不能干燥 \\(\\mathrm{NH_3}\\)**（同理浓硫酸因酸性也不能干燥 \\(\\mathrm{NH_3}\\)）；干燥 \\(\\mathrm{NH_3}\\) 必须用**碱石灰（\\(\\mathrm{NaOH + CaO}\\)）**。","checkRule":"干燥剂选择不仅看酸碱中和，还要查是否发生氧化还原（如浓硫酸与 H₂S/HI）或络合反应（CaCl₂ 与 NH₃）。"},{"title":"混淆粉刷墙壁石灰浆固化与煅烧方向","wrong":"“粉刷墙壁的熟石灰浆变硬是因为发生 \\(\\mathrm{Ca(OH)_2 \\to CaO + H_2O}\\) 干燥脱水。”","diagnosis":"教材 p.249 练习 4 易错选项：常温下 \\(\\mathrm{Ca(OH)_2}\\) 不会脱水变成 \\(\\mathrm{CaO}\\)（需高温才能分解），墙壁变硬是因为吸收空气中的 \\(\\mathrm{CO_2}\\)。","right":"粉刷墙壁的石灰浆固化主要反应是 \\(\\mathrm{Ca(OH)_2(s) + CO_2(g) \\to CaCO_3(s) + H_2O(l)}\\)（生成坚硬的碳酸钙并放出水分，所以新刷房子刚住进去显得潮湿，常点炭火加速碳化！）。","checkRule":"石灰浆硬化是吸收 CO₂ 生成 CaCO₃，绝非 Ca(OH)₂ 分解成 CaO。"}],"examples":[{"label":"例 10.3.1","tier":"L2","tierLabel":"L2 期末必考","title":"氧化钙与硫酸钙固体简便鉴别及钙化合物转化链（p.246 思考题 10c-2 & p.250）","prompt":"(1) 请用最简便的实验方法鉴别白色固体 \\(\\mathrm{CaO}\\) 与 \\(\\mathrm{CaSO_4}\\)，写出实验操作、现象与结论；(2) 写出如下转化的化学方程式：\\(\\mathrm{Ca \\to Ca(OH)_2 \\to CaCO_3 \\to CaO \\to Ca(OH)_2}\\)。","clues":"利用 \\(\\mathrm{CaO}\\) 遇水剧烈放热变成碱性 \\(\\mathrm{Ca(OH)_2}\\)，而 \\(\\mathrm{CaSO_4}\\) 微溶几乎不放热且呈中性。","strategy":"取少许粉末加水溶解（测温变化 + 滴酚酞/测 pH）；按反应类型写出 4 步钙家族方程式。","given":"待鉴别固体：CaO vs CaSO₄；转化链：Ca → Ca(OH)₂ → CaCO₃ → CaO → Ca(OH)₂","principle":"CaO + H₂O → Ca(OH)₂（强放热、强碱性）；CaSO₄ 微溶于水呈中性且无明显放热。","steps":["**第(1)问简便鉴别**：取两支干燥试管各加入少许待测白色固体，分别加入适量蒸馏水振荡，**用手触摸试管外壁（并可向清液滴入 1 滴酚酞试液）**。","- 若试管壁**明显发烫**（且溶液使酚酞变红），则原固体为 **\\(\\mathrm{CaO}\\)**；","- 若试管壁**无明显温度升高**、大部分固体仍未溶解（且溶液不使酚酞变红），则原固体为 **\\(\\mathrm{CaSO_4}\\)**。","**第(2)问四步方程式**：","- ① \\(\\mathrm{Ca(s) + 2H_2O(l) \\longrightarrow Ca(OH)_2(s) + H_2(g)}\\uparrow\\)","- ② \\(\\mathrm{Ca(OH)_2(aq) + CO_2(g) \\longrightarrow CaCO_3(s)\\downarrow + H_2O(l)}\\)（或加 \\(\\mathrm{Na_2CO_3}\\) 溶液）","- ③ \\(\\mathrm{CaCO_3(s)} \\xrightarrow{\\text{高温}} \\mathrm{CaO(s) + CO_2(g)}\\uparrow\\)","- ④ \\(\\mathrm{CaO(s) + H_2O(l) \\longrightarrow Ca(OH)_2(s)}\\)"],"answer":"(1) 加水测温（发烫且使酚酞变红为 CaO，不烫不红为 CaSO₄）；(2) 见上述 4 式。","markingPoints":["第(1)问抓住加水放热与溶液碱性双重直观判据（2分）","第(2)问 4 个化学方程式全部配平并标明气体/沉淀/高温条件（3分）"],"verification":"对照教材 p.245–246 反应性质与 p.250 作答题 4-(2) 完全吻合。","pitfall":"若只答“加水看是否溶解”，因 Ca(OH)₂ 与 CaSO₄ 均属微溶，单独看浑浊度极易误判，必须结合**放热**或**酚酞显红**！"},{"label":"例 10.3.2","tier":"L3","tierLabel":"L3 预试拔高","title":"硬水成因判断与石灰—纯碱联合软化计量分析","prompt":"某地区地下水经检测同时含有较多的 \\(\\mathrm{Ca(HCO_3)_2}\\) 和 \\(\\mathrm{MgSO_4}\\)，因此具有较高的硬度。(1) 该地下水属于哪种类型的硬水？若直接将其在家庭水壶中煮沸，能除去哪部分硬度？会留下什么白色水垢？(2) 工业上常先加入适量熟石灰 \\(\\mathrm{Ca(OH)_2}\\)，再加入纯碱 \\(\\mathrm{Na_2CO_3}\\) 来软化该硬水。请解释先加 \\(\\mathrm{Ca(OH)_2}\\) 后再加 \\(\\mathrm{Na_2CO_3}\\) 的顺序原因，并写出各步主要离子方程式。","clues":"注意 \\(\\mathrm{Ca(OH)_2}\\) 既能沉淀 \\(\\mathrm{HCO_3^-}\\) 和 \\(\\mathrm{Mg^{2+}}\\)，自身又会引入新的 \\(\\mathrm{Ca^{2+}}\\)；后加 \\(\\mathrm{Na_2CO_3}\\) 刚好把过量引入的及原有的 \\(\\mathrm{Ca^{2+}}\\) 一并沉淀干净！","strategy":"分辨暂时硬度与永久硬度 → 分析石灰沉淀 \\(\\mathrm{Mg^{2+}/HCO_3^-}\\) 并引入 \\(\\mathrm{Ca^{2+}}\\) → 纯碱收尾除净 \\(\\mathrm{Ca^{2+}}\\)。","given":"硬水含 Ca(HCO₃)₂（暂时硬度）与 MgSO₄（永久硬度）","principle":"石灰除 Mg²⁺ 与 HCO₃⁻，纯碱除 Ca²⁺；加药顺序决定除杂是否彻底。","steps":["(1) 该水既含碳酸氢盐又含硫酸盐，属于**同时具有暂时硬度和永久硬度的混合硬水**。煮沸只能除去 \\(\\mathrm{Ca(HCO_3)_2}\\)（暂时硬度），留下难溶的 **\\(\\mathrm{CaCO_3}\\)** 白色水垢；而 \\(\\mathrm{MgSO_4}\\) 造成的永久硬度煮沸无法除去。","(2) **先加 \\(\\mathrm{Ca(OH)_2}\\) 后加 \\(\\mathrm{Na_2CO_3}\\) 的原因**：熟石灰先将 \\(\\mathrm{Mg^{2+}}\\) 沉淀为 \\(\\mathrm{Mg(OH)_2}\\) 并把 \\(\\mathrm{HCO_3^-}\\) 转化为 \\(\\mathrm{CaCO_3}\\) 沉淀，但此步反应会向水中引入新的 \\(\\mathrm{Ca^{2+}}\\)（来自 \\(\\mathrm{Ca(OH)_2}\\) 与 \\(\\mathrm{MgSO_4}\\) 反应生成的 \\(\\mathrm{CaSO_4}\\) 等）；随后加入 **\\(\\mathrm{Na_2CO_3}\\)**，就能把水体原有及前一步残留的全部 \\(\\mathrm{Ca^{2+}}\\) 一次性沉淀为 \\(\\mathrm{CaCO_3}\\) 除去（如果顺序颠倒，后加的 \\(\\mathrm{Ca(OH)_2}\\) 反而会使水体重新变硬）。","**核心离子方程式**：\\(\\mathrm{Mg^{2+} + 2OH^- \\to Mg(OH)_2\\downarrow}\\)；\\(\\mathrm{Ca^{2+} + 2HCO_3^- + 2OH^- \\to CaCO_3\\downarrow + CO_3^{2-} + 2H_2O}\\)；\\(\\mathrm{Ca^{2+} + CO_3^{2-} \\to CaCO_3\\downarrow}\\)。"],"answer":"(1) 混合硬水；煮沸除 Ca(HCO₃)₂ 生 CaCO₃ 水垢，不能除 MgSO₄；(2) 先加石灰除 Mg²⁺ 与 HCO₃⁻，后加纯碱除净包括石灰引入在内的所有 Ca²⁺。","markingPoints":["正确判断混合硬水并指出煮沸仅除暂时硬度（1分）","清晰说明纯碱在石灰之后能顺便除去石灰引入的 Ca²⁺（2分）","写出 Mg(OH)₂ 与 CaCO₃ 沉淀离子方程式（2分）"],"verification":"此逻辑与粗盐提纯中“Na₂CO₃ 必须加在 BaCl₂ 之后以顺便除去过量 Ba²⁺”同出一辙。","pitfall":"答错顺序或只写 Ca(OH)₂ 只除 HCO₃⁻ 而忘了它也能沉淀 Mg²⁺。"}],"practice":[{"id":"chem10-10.3-q1","tier":"L1","tierLabel":"L1 基础","examStyle":"P1 选择","q":"某地区烧水壶内壁常沉积一层厚厚的白色水垢，向其中滴加稀盐酸有大量气泡产生。形成这种水垢的主要反应是（　）。","options":["A. \\(\\mathrm{CaO(s) + H_2O(l) \\to Ca(OH)_2(s)}\\)","B. \\(\\mathrm{Ca(HCO_3)_2(aq)} \\xrightarrow{\\Delta} \\mathrm{CaCO_3(s)\\downarrow + H_2O(l) + CO_2(g)\\uparrow}\\)","C. \\(\\mathrm{CaSO_4\\cdot 2H_2O} \\to \\mathrm{(CaSO_4)_2\\cdot H_2O + 3H_2O}\\)","D. \\(\\mathrm{CaCO_3(s)} \\xrightarrow{\\text{高温}} \\mathrm{CaO(s) + CO_2(g)\\uparrow}\\)"],"correctOption":"B","given":"p.279 感知生活水垢沉积 & p.249 练习 4","method":"对照暂时硬水受热分解产生 CaCO₃ 沉淀的原理","principle":"天然水中的可溶 Ca(HCO₃)₂ 煮沸分解为难溶 CaCO₃ 附着在壶壁。","steps":["水垢主要成分 CaCO₃ 遇酸冒泡；其受热形成源于水中的 Ca(HCO₃)₂ 热分解，故 B 正确。"],"ans":"B","markingPoints":["辨明水垢成因即暂时硬水热分解"],"verification":"化上 p.279 明确以水壶水垢作为 Ca(HCO₃)₂ 分解实例。","pitfall":"与石灰乳刷墙硬化（A/Ca(OH)₂+CO₂）混淆。"},{"id":"chem10-10.3-q2","tier":"L2","tierLabel":"L2 期末","examStyle":"P1 选择","q":"下列关于钙的重要化合物性质及用途的叙述中，**错误**的是（　）。","options":["A. 熟石膏（\\(\\mathrm{(CaSO_4)_2\\cdot H_2O}\\)）加水后可重新转化为石膏，并伴随微量体积膨胀，适于制作石膏模型","B. 无水氯化钙吸水性强，是实验室干燥氨气（\\(\\mathrm{NH_3}\\)）和二氧化碳的优良干燥剂","C. 氢氧化钙的澄清水溶液叫石灰水，白色悬浊液叫石灰乳，熟石灰可用于改良酸性土壤","D. 石膏矿可用于调节水泥的硬化速度，食用级石膏粉可作豆制品凝固剂"],"correctOption":"B","given":"p.245–246 石膏与氯化钙性质","method":"逐项比对熟石膏性质、石灰乳/水及 CaCl₂ 干燥限制","principle":"无水 CaCl₂ 能与 NH₃ 形成 CaCl₂·8NH₃ 配合物，严禁干燥 NH₃。","steps":["A、C、D 均完全符合教材原文；B 错误，无水 CaCl₂ 不能用于干燥 NH₃（只可干燥 CO₂ 等不与它反应的气体）。"],"ans":"B","markingPoints":["牢记无水 CaCl₂ 干燥剂适用范围与氨气禁忌"],"verification":"化上 p.246 明确指出“无水氯化钙对氨气有较强的吸附能力”及思考题 10c-1。","pitfall":"只看到前半句“干燥二氧化碳”正确就忽略后半句“氨气”错误。"},{"id":"chem10-10.3-q3","tier":"L3","tierLabel":"L3 预试","examStyle":"P2 简答","q":"某同学想验证家中自来水是暂时硬水还是永久硬水（或软水），请帮他设计一套简便的检验实验（可用普通烧杯、酒精灯与肥皂水），说明实验操作、可能观察到的现象及对应判断结论。","given":"肥皂水鉴别硬水，煮沸法区分暂时硬水与永久硬水","method":"先测原水样与肥皂水泡沫/浮渣判断是否为硬水，再将水样煮沸冷却后加肥皂水对比","principle":"软水加肥皂水泡沫丰富；硬水加肥皂水泡沫少且产生大量白色浮渣（钙镁肥皂沉淀）。煮沸能软化暂时硬水。","steps":["操作 1：取少量原水样于试管，滴加等量肥皂水充分振荡。若泡沫丰富无浮渣，则为**软水**；若泡沫极少且有大量浮渣，则为**硬水**。","操作 2：另取一份原水样置于烧杯中充分**煮沸**数分钟，冷却静置后取上层清液再滴加等量肥皂水振荡：","- 若产生白色水垢且清液加肥皂水后变为**泡沫丰富、浮渣消失**，则为**暂时硬水**；","- 若仍**无水垢或清液加肥皂水后依然泡沫很少、浮渣多**，则说明水样含有**永久硬度**（属于永久硬水或混合硬水）。"],"ans":"先加肥皂水区分软/硬水；硬水充分煮沸取清液再加肥皂水，若软化（泡沫变多）为暂时硬水，否则含永久硬水。","markingPoints":["采用肥皂水作为软硬水指示剂（1分）","利用煮沸前后加肥皂水现象对比区分暂时硬水与永久硬水（3分）"],"verification":"逻辑严密，对照硬水定义与两类硬水煮沸行为完全吻合。","pitfall":"只答“煮沸看有无水垢”，忽略既含暂时硬度又含永久硬度的水煮沸同样有水垢但水仍然很硬。"},{"id":"chem10-10.3-q4","tier":"L4","tierLabel":"L4 统考压轴","examStyle":"P2 综合计算","q":"将 \\(34.4\\text{ g}\\) 天然生石膏（\\(\\mathrm{CaSO_4\\cdot 2H_2O}\\)，式量 \\(172\\)）置于可控温电炉中在 \\(150\\text{–}170\\ ^\\circ\\mathrm{C}\\) 下小心加热脱水一段时间，冷却后称得剩余固体质量为 \\(29.0\\text{ g}\\)。试通过计算判断所得固体产物是否为纯净的熟石膏 \\(\\mathrm{(CaSO_4)_2\\cdot H_2O}\\)？若继续高温灼烧至完全失去全部结晶水，剩余无水硫酸钙质量应为多少克？（\\(A_r: \\mathrm{Ca}=40, \\mathrm{S}=32, \\mathrm{O}=16, \\mathrm{H}=1\\)）","given":"m(CaSO₄·2H₂O) = 34.4 g (0.200 mol), 剩余固体 = 29.0 g, Δm = 5.40 g","method":"由失去水的物质的量与原石膏物质的量比值确定结晶水化学式下标","principle":"2CaSO₄·2H₂O —(150–170℃)→ (CaSO₄)₂·H₂O + 3H₂O↑；1 mol 生石膏全脱水失 2 mol H₂O。","steps":["初始生石膏物质的量：\\(n(\\mathrm{CaSO_4\\cdot 2H_2O}) = \\frac{34.4}{172} = 0.200\\text{ mol}\\)，其中含 \\(\\mathrm{CaSO_4}\\ 0.200\\text{ mol}\\)（质量 \\(0.200 \\times 136 = 27.2\\text{ g}\\)）及结晶水 \\(0.400\\text{ mol}\\)（质量 \\(7.20\\text{ g}\\)）。","加热至 \\(29.0\\text{ g}\\) 时，失去的水的质量为：\\(\\Delta m = 34.4 - 29.0 = 5.40\\text{ g}\\)，即失去结晶水 \\(n_{\\text{失}}(\\mathrm{H_2O}) = \\frac{5.40}{18} = 0.300\\text{ mol}\\)。","剩余固体中仍保留结晶水：\\(n_{\\text{余}}(\\mathrm{H_2O}) = 0.400 - 0.300 = 0.100\\text{ mol}\\)。","因此固体中 \\(n(\\mathrm{CaSO_4}) : n_{\\text{余}}(\\mathrm{H_2O}) = 0.200 : 0.100 = 2 : 1\\)，化学式恰为 **\\(\\mathrm{(CaSO_4)_2\\cdot H_2O}\\)（纯净熟石膏）**！","若继续高温完全脱水，剩余全部为无水 \\(\\mathrm{CaSO_4}\\)，质量为：\\(0.200 \\times 136 = 27.2\\text{ g}\\)。"],"ans":"所得 29.0 g 固体恰为纯净的熟石膏 (CaSO₄)₂·H₂O；完全脱水剩余无水 CaSO₄ 27.2 g。","markingPoints":["算得初始生石膏 0.200 mol 及失水 0.300 mol（2分）","求得剩余 n(CaSO₄):n(H₂O) = 2:1 证明恰为熟石膏 (CaSO₄)₂·H₂O（2分）","算得完全脱水质量 27.2 g（1分）"],"verification":"验证式量：\\(M[\\mathrm{(CaSO_4)_2\\cdot H_2O}] = 2\\times 136 + 18 = 290\\text{ g/mol}\\)，\\(0.100\\text{ mol} \\times 290 = 29.0\\text{ g}\\)，完全吻合！","pitfall":"计算 \\(\\mathrm{(CaSO_4)_2\\cdot H_2O}\\) 的式量时忘记把 \\(\\mathrm{CaSO_4}\\) 乘 2（即 272+18=290），会算出错误摩尔数。"}],"cheatSheet":["钙三角循环：\\(\\mathrm{CaCO_3} \\xrightarrow{\\text{高温}} \\mathrm{CaO} \\xrightarrow{\\mathrm{+H_2O}} \\mathrm{Ca(OH)_2} \\xrightarrow{\\mathrm{+CO_2}} \\mathrm{CaCO_3}\\)。","硬水软化：暂时硬度（\\(\\mathrm{HCO_3^-}\\)）靠**煮沸**或石灰法；永久硬度（\\(\\mathrm{SO_4^{2-}/Cl^-}\\)）靠**纯碱 \\(\\mathrm{Na_2CO_3}\\)** 或离子交换树脂。","石膏脱水：\\(\\mathrm{CaSO_4\\cdot 2H_2O}\\)（生石膏）\\(\\xrightarrow{150\\text{–}170\\ ^\\circ\\mathrm{C}}\\) \\(\\mathrm{(CaSO_4)_2\\cdot H_2O}\\)（熟石膏），加水膨胀凝结作模型/绷带。","干燥禁忌：无水 \\(\\mathrm{CaCl_2}\\) 吸收 \\(\\mathrm{NH_3}\\) 生成 \\(\\mathrm{CaCl_2\\cdot 8NH_3}\\)，严禁干燥氨气！"],"kbEntryIds":["kb-chem10-ca-compounds","kb-chem10-hard-water"],"diagrams":[{"src":"assets/fig/v2/chem10-ca-cycle.svg","caption":"图 10-1 钙及其重要化合物（石灰石—生石灰—熟石灰—硬水转化网络）","alt":"碳酸钙、氧化钙、氢氧化钙、碳酸氢钙转化及石膏硬水软化图","pageRef":"化上 p.244–247"}],"quiz":{"q":"下列试剂中，能够安全有效地干燥氨气（\\(\\mathrm{NH_3}\\)）的是哪一种（碱石灰、浓硫酸、无水氯化钙）？请简述排除另外两种的原因。","given":"候选干燥剂：碱石灰、浓硫酸、无水 CaCl₂","method":"逐一检验各干燥剂是否与碱性且强配位的 NH₃ 发生化学反应","principle":"碱性气体 NH₃ 不能用酸性干燥剂（浓 H₂SO₄），也不能用络合它的无水 CaCl₂。","steps":["浓 \\(\\mathrm{H_2SO_4}\\) 为酸性，与 \\(\\mathrm{NH_3}\\) 反应生成 \\(\\mathrm{(NH_4)_2SO_4}\\)；","无水 \\(\\mathrm{CaCl_2}\\) 会吸附 \\(\\mathrm{NH_3}\\) 生成 \\(\\mathrm{CaCl_2\\cdot 8NH_3}\\)；","只有碱性的**碱石灰**（\\(\\mathrm{NaOH + CaO}\\)）不与 \\(\\mathrm{NH_3}\\) 反应且吸水性强。"],"ans":"碱石灰"}},{"id":"10.4","t":"镁离子和钙离子的检验","anchor":{"pages":"化上 p.247–248","syllabus":"3.3.5 水溶液中 Mg²⁺ 和 Ca²⁺ 的沉淀鉴别方法与钙焰色反应","examScopes":["sem2_final","uec"],"examWeight":"P1 试剂与沉淀现象判断 + P2 混合盐鉴别及实验探究必答题","terms":"Magnesium hydroxide precipitation · Calcium oxalate (CaC₂O₄) · Acetic acid insolubility · Brick-red flame test","prerequisites":["弱酸强酸复分解条件与难溶物溶解性","焰色试验操作规范（化上 Ch 9.2）"],"goals":["掌握向 Mg²⁺ 溶液滴加 NaOH 或氨水均生成不溶于过量碱的白色 Mg(OH)₂ 沉淀（区别 Al³⁺）。","熟练描述 Ca²⁺ 与草酸铵 (NH₄)₂C₂O₄ 反应生成白色 CaC₂O₄ 沉淀及其在醋酸与稀盐酸中的溶解性差异（活动 6）。","结合钙的砖红色焰色试验（活动 8），设计方案独立鉴别 MgSO₄、CaSO₄、MgCl₂ 和 CaCl₂ 等多种白色固体或溶液（p.250 作答题 2）。"]},"concepts":[{"kind":"experiment","title":"活动探究 1（活动 4–5）：水溶液中 Mg²⁺ 的检验","pageRef":"化上 p.247–249","body":["**活动 4（\\(\\mathrm{MgCl_2}\\) + \\(\\mathrm{NaOH}\\) 溶液至过量）**：逐滴加入 \\(\\mathrm{NaOH}\\) 溶液，立即产生**白色沉淀（\\(\\mathrm{Mg(OH)_2}\\)）**，继续滴加 \\(\\mathrm{NaOH}\\) 至过量，**白色沉淀不溶解**。","**活动 5（\\(\\mathrm{MgCl_2}\\) + 氨水至过量）**：逐滴加入氨水（\\(\\mathrm{NH_3\\cdot H_2O}\\)），同样产生白色沉淀，滴至过量**沉淀也不溶解**：\\(\\mathrm{Mg^{2+}(aq) + 2NH_3\\cdot H_2O(aq) \\to Mg(OH)_2(s)\\downarrow + 2NH_4^+(aq)}\\)。","**易混区分提示**：虽然 \\(\\mathrm{Ca^{2+}}\\) 遇浓 \\(\\mathrm{NaOH}\\) 时也可能因 \\(\\mathrm{Ca(OH)_2}\\) 微溶出现浑浊，但**\\(\\mathrm{Ca^{2+}}\\) 遇稀氨水不产生沉淀**（氨水碱性弱），因此用氨水（或结合后续 \\(\\mathrm{Ca^{2+}}\\) 草酸铵检验）可更稳妥地识别 \\(\\mathrm{Mg^{2+}}\\)；而与 \\(\\mathrm{Al^{3+}}\\) 相比，\\(\\mathrm{Mg(OH)_2}\\) 不溶于过量强碱，\\(\\mathrm{Al(OH)_3}\\) 则溶于过量 \\(\\mathrm{NaOH}\\)。"],"takeaway":"检验 Mg²⁺ 加 NaOH 或氨水均可生成白色沉淀，且两者加至过量沉淀均不消失！"},{"kind":"experiment","title":"活动探究 2（活动 6–8）：Ca²⁺ 的沉淀溶解辨析与焰色反应","pageRef":"化上 p.247–249","body":["**活动 6（草酸铵沉淀 + 两酸对照）**：向 \\(\\mathrm{CaCl_2}\\) 溶液滴加草酸铵 \\(\\mathrm{(NH_4)_2C_2O_4}\\) 溶液，立即生成白色**草酸钙（\\(\\mathrm{CaC_2O_4}\\)）沉淀**：\\(\\mathrm{Ca^{2+}(aq) + C_2O_4^{2-}(aq) \\to CaC_2O_4(s)\\downarrow}\\)。将该白色沉淀均分两份：","- 一份滴加足量**醋酸（\\(\\mathrm{CH_3COOH}\\)）**：**白色沉淀不溶解**（因醋酸酸性不足以破坏极难溶的草酸钙平衡，草酸 \\(\\mathrm{H_2C_2O_4}\\) 酸性强于醋酸！）；","- 另一份滴加足量**稀盐酸（\\(\\mathrm{HCl}\\)）**：**白色沉淀溶解**（强酸 \\(\\mathrm{H^+}\\) 与 \\(\\mathrm{C_2O_4^{2-}}\\) 结合生成弱酸草酸，推动沉淀溶解平衡右移）。","**活动 7（稀 \\(\\mathrm{Na_2SO_4}\\) 对照）**：向稀 \\(\\mathrm{CaCl_2}\\) 溶液滴加稀 \\(\\mathrm{Na_2SO_4}\\) 溶液，通常**无明显沉淀产生**（因 \\(\\mathrm{CaSO_4}\\) 微溶于水而非完全不溶，需极浓溶液才微有沉淀；这与 \\(\\mathrm{Ba^{2+}}\\) 遇稀 \\(\\mathrm{SO_4^{2-}}\\) 立即生成大量不溶于酸的 \\(\\mathrm{BaSO_4}\\) 沉淀明显不同）。","**活动 8（焰色试验）**：用洁净铂丝蘸取 \\(\\mathrm{CaCl_2}\\) 溶液在无色外焰灼烧，火焰呈特征的**砖红色（brick red）**。"],"takeaway":"记住草酸钙核心判据：“溶于稀盐酸，不溶于醋酸”！为什么教材强调 Ca²⁺ 要综合检验？因为 Sr²⁺、Ba²⁺ 与草酸铵也有类似沉淀反应，必须结合焰色（Ca 砖红、Ba 黄绿）及硫酸盐溶解度综合确认！"},{"kind":"table","title":"常见 II A 族阳离子（Mg²⁺、Ca²⁺）及易混离子（Al³⁺、Ba²⁺）检验速查表","pageRef":"化上 p.247–248","body":["考场面对多种无色阳离子联合鉴别题时，将沉淀溶解性与焰色结合可做到零误判。"],"table":{"headers":["待检离子","试剂 1：过量 NaOH","试剂 2：过量氨水","试剂 3：(NH₄)₂C₂O₄","试剂 4：稀 Na₂SO₄ & 焰色"],"rows":[["Mg²⁺","白色沉淀（过量不溶）","白色沉淀（过量不溶）","通常不沉淀（微溶）","不沉淀；无明显特征焰色"],["Ca²⁺","浓液生白色微溶浑浊","无沉淀","白色 CaC₂O₄↓（不溶醋酸、溶盐酸）","稀液无沉淀；**砖红色**焰色"],["Al³⁺（对照）","先白沉淀，过量**溶解**","白色沉淀（过量不溶）","—","不沉淀"],["Ba²⁺（对照）","无沉淀","无沉淀","白色 BaC₂O₄↓","立即生成不溶于稀硝酸的白色 BaSO₄↓"]]},"takeaway":"Mg²⁺ vs Ca²⁺ 溶液先分法：加稀氨水只沉淀 Mg²⁺；再向滤液加 (NH₄)₂C₂O₄ 检验 Ca²⁺（沉淀不溶醋酸、溶盐酸，且焰色砖红）！"}],"formulas":[{"title":"草酸钙沉淀生成及酸溶对比方程式","tex":"\\mathrm{Ca^{2+}(aq)} + \\mathrm{C_2O_4^{2-}(aq)} \\longrightarrow \\mathrm{CaC_2O_4(s)}\\downarrow,\\qquad \\mathrm{CaC_2O_4(s)} + 2\\mathrm{H^+(aq)} \\longrightarrow \\mathrm{Ca^{2+}(aq)} + \\mathrm{H_2C_2O_4(aq)}","plain":"Ca²⁺ + C2O4²⁻ → CaC2O4↓; CaC2O4 + 2H⁺ → Ca²⁺ + H2C2O4","conditions":"在强酸稀盐酸中溶解，在弱酸醋酸 CH₃COOH 中不溶解","pageRef":"化上 p.247、p.249","note":"因为草酸 H₂C₂O₄ 的酸性强于醋酸 CH₃COOH，故“弱酸不能制强酸”，醋酸不能溶解 CaC₂O₄。"},{"title":"镁离子与碱液反应离子方程式","tex":"\\mathrm{Mg^{2+}(aq)} + 2\\mathrm{OH^-(aq)} \\longrightarrow \\mathrm{Mg(OH)_2(s)}\\downarrow,\\qquad \\mathrm{Mg^{2+}(aq)} + 2\\mathrm{NH_3}\\cdot\\mathrm{H_2O(aq)} \\longrightarrow \\mathrm{Mg(OH)_2(s)}\\downarrow + 2\\mathrm{NH_4^+(aq)}","plain":"Mg²⁺ + 2OH⁻ → Mg(OH)2↓; Mg²⁺ + 2NH3·H2O → Mg(OH)2↓ + 2NH4⁺","conditions":"过量 NaOH 或过量氨水均不使 Mg(OH)₂ 溶解","pageRef":"化上 p.247","note":"氨水为弱电解质，在离子方程式中写化学式 NH₃·H₂O，不可拆成 OH⁻。"}],"pitfalls":[{"title":"误把草酸钙记成“能溶于醋酸”或“不溶于稀盐酸”","wrong":"“白色草酸钙沉淀加入醋酸后迅速溶解，加入稀盐酸后不溶解。”","diagnosis":"完全记反溶解性：将 CaC₂O₄ 与一般碳酸钙（CaCO₃ 溶于醋酸）或硫酸钡（BaSO₄ 不溶于稀盐酸）混淆。","right":"\\(\\mathrm{CaC_2O_4}\\) **不溶于醋酸，但溶于稀盐酸**（而 \\(\\mathrm{CaCO_3}\\) 既溶于醋酸又溶于稀盐酸，\\(\\mathrm{BaSO_4}\\) 两者都不溶）。","checkRule":"牢记：CaCO₃（弱酸强酸盐，醋酸即溶） vs CaC₂O₄（中强酸盐，醋酸不溶、盐酸溶） vs BaSO₄（强酸盐，盐酸不溶）。"},{"title":"忽略氨水与 NaOH 离子方程式拆分规范","wrong":"“氯化镁与氨水反应的离子方程式为 \\(\\mathrm{Mg^{2+} + 2OH^- \\to Mg(OH)_2\\downarrow}\\)。”","diagnosis":"一水合氨（\\(\\mathrm{NH_3\\cdot H_2O}\\)）是弱碱（弱电解质），书写离子方程式时绝对不能拆写为 \\(\\mathrm{OH^-}\\)。","right":"必须写为 \\(\\mathrm{Mg^{2+}(aq) + 2NH_3\\cdot H_2O(aq) \\to Mg(OH)_2(s)\\downarrow + 2NH_4^+(aq)}\\)。","checkRule":"遇到弱酸（CH₃COOH、H₂CO₃）或弱碱（NH₃·H₂O），在离子方程式中一律保留分子式。"}],"examples":[{"label":"例 10.4.1","tier":"L2","tierLabel":"L2 期末必考","title":"四瓶无标签白色固体（MgSO₄、CaSO₄、MgCl₂、CaCl₂）鉴别方案（p.250 作答题 2）","prompt":"实验室有四瓶失去标签的白色固体，已知分别是 \\(\\mathrm{MgSO_4}\\)、\\(\\mathrm{CaSO_4}\\)、\\(\\mathrm{MgCl_2}\\) 和 \\(\\mathrm{CaCl_2}\\)。请设计简明的实验步骤将它们一一鉴别出来，并写出有关反应的化学（或离子）方程式。","clues":"利用两组正交特征：① \\(\\mathrm{CaSO_4}\\) 微溶水（其余三者易溶），先加水即可一眼拎出 \\(\\mathrm{CaSO_4}\\)；② 对易溶的三种溶液，再分别用 \\(\\mathrm{BaCl_2}\\)（检 \\(\\mathrm{SO_4^{2-}}\\)）与 \\(\\mathrm{NaOH}\\) / 氨水（检 \\(\\mathrm{Mg^{2+}}\\)）或 \\(\\mathrm{(NH_4)_2C_2O_4}\\)（检 \\(\\mathrm{Ca^{2+}}\\)）。","strategy":"加水初筛出微溶 \\(\\mathrm{CaSO_4}\\) → 易溶三瓶分取检验 \\(\\mathrm{SO_4^{2-}}\\)（得 \\(\\mathrm{MgSO_4}\\)）→ 剩余两氯化物检验 \\(\\mathrm{Mg^{2+}}\\) 与 \\(\\mathrm{Ca^{2+}}\\)。","given":"四瓶固体：MgSO₄, CaSO₄, MgCl₂, CaCl₂","principle":"溶解性差异、Ba²⁺+SO₄²⁻→BaSO₄↓、Mg²⁺+2NH₃·H₂O→Mg(OH)₂↓、Ca²⁺+C₂O₄²⁻→CaC₂O₄↓。","steps":["**第一步（加水区分 \\(\\mathrm{CaSO_4}\\)）**：分别取少量四种固体于 4 支试管中，加入足量蒸馏水充分振荡。**大部分不溶、呈白色浑浊**的为 **\\(\\mathrm{CaSO_4}\\)**；其余三份均完全溶解成无色澄清溶液（\\(\\mathrm{MgSO_4, MgCl_2, CaCl_2}\\)）。","**第二步（检验 \\(\\mathrm{SO_4^{2-}}\\) 区分 \\(\\mathrm{MgSO_4}\\)）**：取上述三份澄清溶液少许于 3 支新试管中，分别滴加 \\(\\mathrm{BaCl_2}\\) 溶液（及稀盐酸酸化）。立即产生**不溶于酸的白色沉淀**的为 **\\(\\mathrm{MgSO_4}\\)**（\\(\\mathrm{MgSO_4 + BaCl_2 \\to BaSO_4\\downarrow + MgCl_2}\\)）；无现象的两份为 \\(\\mathrm{MgCl_2}\\) 与 \\(\\mathrm{CaCl_2}\\)。","**第三步（区分 \\(\\mathrm{MgCl_2}\\) 与 \\(\\mathrm{CaCl_2}\\)）**：另取后两者溶液少许，分别滴加**氨水**（或 \\(\\mathrm{(NH_4)_2C_2O_4}\\) 溶液，或做焰色试验）。滴加氨水产生**白色沉淀**的为 **\\(\\mathrm{MgCl_2}\\)**（\\(\\mathrm{MgCl_2 + 2NH_3\\cdot H_2O \\to Mg(OH)_2\\downarrow + 2NH_4Cl}\\)）；无现象（且滴 \\(\\mathrm{(NH_4)_2C_2O_4}\\) 生白色沉淀、焰色砖红）的为 **\\(\\mathrm{CaCl_2}\\)**。"],"answer":"①加水难溶者为 CaSO₄；②其余澄清液加 BaCl₂ 产白沉淀者为 MgSO₄；③余下两液加氨水产白沉淀者为 MgCl₂，无沉淀（且与草酸铵沉淀/砖红焰色）为 CaCl₂。","markingPoints":["利用水溶性直接筛出微溶 CaSO₄（1分）","用 BaCl₂ 检出 MgSO₄ 并写出正确方程式（2分）","用氨水（或 NaOH / 草酸铵 / 焰色）区分 MgCl₂ 与 CaCl₂ 并写对反应式（2分）"],"verification":"注意不能在第二步直接加 AgNO₃ 检验 Cl⁻，因为 Ag₂SO₄ 微溶在浓 MgSO₄ 中也会出现微弱浑浊干扰，用 BaCl₂ 检 SO₄²⁻ 零干扰！","pitfall":"若第一步未加水直接做焰色试验，硫酸钙难挥发焰色极微弱不易观察，加水初筛最简洁。"},{"label":"例 10.4.2","tier":"L4","tierLabel":"L4 统考压轴","title":"含 Mg²⁺、Ca²⁺、Al³⁺ 混合溶液的分步分离与检验设计","prompt":"现有一瓶混合无色溶液，怀疑同时含有 \\(\\mathrm{Mg^{2+}}\\)、\\(\\mathrm{Ca^{2+}}\\) 和 \\(\\mathrm{Al^{3+}}\\) 三种金属阳离子。请设计一套不互相干扰的**分步分离与逐一确认**实验流程，简要写出每步所加试剂（须过量还是适量）、现象及确认各离子的依据。","clues":"利用三者的碱/盐溶度差异分步打击：①用**过量氨水**把 \\(\\mathrm{Mg^{2+}}\\) 和 \\(\\mathrm{Al^{3+}}\\) 一起沉淀，过滤使 \\(\\mathrm{Ca^{2+}}\\) 留在滤液中单独检验；②再用**过量 \\(\\mathrm{NaOH}\\)** 分开滤渣中的 \\(\\mathrm{Mg(OH)_2}\\)（不溶）与 \\(\\mathrm{Al(OH)_3}\\)（溶成 \\(\\mathrm{AlO_2^-}\\)）！","strategy":"过量氨水分开 [Mg(OH)₂ + Al(OH)₃] 与 [Ca²⁺ 滤液] → 滤液用草酸铵检 Ca²⁺ → 滤渣加过量 NaOH 留 Mg(OH)₂、溶出 AlO₂⁻ → 通 CO₂ 复现 Al(OH)₃ 确认 Al³⁺。","given":"混合溶液可能含 Mg²⁺, Ca²⁺, Al³⁺","principle":"NH₃·H₂O 不溶 Al(OH)₃ 且不沉淀 Ca²⁺；过量 NaOH 溶解 Al(OH)₃ 而不溶 Mg(OH)₂；CO₂ 酸化 AlO₂⁻ 复生 Al(OH)₃。","steps":["**第一步（分离并检验 \\(\\mathrm{Ca^{2+}}\\)）**：向混合液中加入**足量（过量）氨水**至不再产生沉淀，过滤。向所得**滤液**中滴加 \\(\\mathrm{(NH_4)_2C_2O_4}\\) 溶液，若产生**白色沉淀且该沉淀不溶于醋酸、溶于稀盐酸**（并可测得砖红色焰色），确认原溶液含 **\\(\\mathrm{Ca^{2+}}\\)**。","**第二步（分离并检验 \\(\\mathrm{Mg^{2+}}\\)）**：向第一步所得**白色滤渣**（可能含 \\(\\mathrm{Mg(OH)_2}\\) 与 \\(\\mathrm{Al(OH)_3}\\)）中加入**足量过量 \\(\\mathrm{NaOH}\\) 溶液**，充分搅拌后过滤。若仍有**不溶解的白色固体滤渣**留存，证明原溶液含 **\\(\\mathrm{Mg^{2+}}\\)**（\\(\\mathrm{Mg(OH)_2}\\) 不溶于过量强碱）。","**第三步（确认 \\(\\mathrm{Al^{3+}}\\)）**：向第二步所得**强碱性滤液**中通入**足量 \\(\\mathrm{CO_2}\\) 气体**（或逐滴加稀盐酸至微酸性），若重新析出**白色胶状沉淀（\\(\\mathrm{Al(OH)_3}\\)）**，证明原溶液含 **\\(\\mathrm{Al^{3+}}\\)**（\\(\\mathrm{AlO_2^- + CO_2 + 2H_2O \\to Al(OH)_3\\downarrow + HCO_3^-}\\)）。"],"answer":"①加过量氨水过滤，滤液加草酸铵（醋酸不溶、盐酸溶）确认 Ca²⁺；②滤渣加过量 NaOH 过滤，余白色滤渣确认 Mg²⁺；③偏铝酸钠滤液通足量 CO₂ 复现白色沉淀确认 Al³⁺。","markingPoints":["利用过量氨水将 Ca²⁺ 留在滤液并规范用草酸铵两酸对照检出 Ca²⁺（2分）","利用过量 NaOH 溶解 Al(OH)₃ 留下 Mg(OH)₂ 确认 Mg²⁺（2分）","向碱性滤液通 CO₂ 复现白色沉淀确认 Al³⁺（1分）"],"verification":"三步各离子彻底分离互不掩盖，即使 Mg²⁺ 与 Al³⁺ 沉淀同为白色也能通过溶解性完美剥离。","pitfall":"若第一步错用过量 NaOH，不仅可能带下微溶的 Ca(OH)₂ 浑浊干扰 Mg(OH)₂，还会导致滤液中同时混有 AlO₂⁻ 与 Ca²⁺。"}],"practice":[{"id":"chem10-10.4-q1","tier":"L1","tierLabel":"L1 基础","examStyle":"P1 选择","q":"用洁净铂丝蘸取氯化钙溶液在无色火焰上灼烧，观察到的火焰特征颜色是（　）。","options":["A. 黄色","B. 浅紫色","C. 砖红色","D. 绿色"],"correctOption":"C","given":"p.248 活动 8 & 本章知识梳理","method":"直接对照教材钙焰色结论","principle":"钙元素特征焰色为砖红色。","steps":["Na 黄色、K 浅紫色、Ca 砖红色、Cu 绿色。"],"ans":"C","markingPoints":["记忆钙元素砖红色焰色"],"verification":"化上 p.248 知识梳理明确标注“钙 — 焰色反应 — 砖红色”。","pitfall":"与锂的紫红色或钠的黄色混淆。"},{"id":"chem10-10.4-q2","tier":"L2","tierLabel":"L2 期末","examStyle":"P1 选择","q":"检验水溶液中是否含有 \\(\\mathrm{Ca^{2+}}\\) 时，常先滴加草酸铵 \\(\\mathrm{(NH_4)_2C_2O_4}\\) 溶液生成白色沉淀，随后把沉淀均分两份分别滴加足量醋酸和稀盐酸，观察到的正确现象是（　）。","options":["A. 醋酸中溶解，稀盐酸中不溶解","B. 醋酸中不溶解，稀盐酸中溶解","C. 两者中均不溶解","D. 两者中均迅速溶解并放出气泡"],"correctOption":"B","given":"p.247 活动 6 & p.249 本章重要概念 7","method":"比对草酸与醋酸、盐酸的酸性强弱","principle":"盐酸酸性强于草酸，可溶解 CaC₂O₄；醋酸酸性弱于草酸，不能溶解 CaC₂O₄。","steps":["生成白色 CaC₂O₄ 沉淀后，加足量醋酸不溶解，加足量稀盐酸溶解，无气体放出（非碳酸盐）。"],"ans":"B","markingPoints":["准确区分 CaC₂O₄ 在醋酸与盐酸中的溶解行为"],"verification":"化上 p.249 本章重要概念第 7 条原文原句。","pitfall":"误选 D 把草酸钙沉淀与碳酸钙混淆。"},{"id":"chem10-10.4-q3","tier":"L3","tierLabel":"L3 预试","examStyle":"P1 选择","q":"要将混在氯化钙溶液中的少量氯化镁杂质除去（保留 \\(\\mathrm{CaCl_2}\\) 溶液不引入新杂质），最简便合理的试剂选择是（　）。","options":["A. 加入过量 \\(\\mathrm{NaOH}\\) 溶液后过滤","B. 加入足量 \\(\\mathrm{Ca(OH)_2}\\) 溶液（或石灰乳）充分反应后过滤，再用适量稀盐酸调至中性","C. 加入足量 \\(\\mathrm{Na_2CO_3}\\) 溶液后过滤","D. 加入足量 \\(\\mathrm{(NH_4)_2C_2O_4}\\) 溶液后过滤"],"correctOption":"B","given":"CaCl₂ 中除少量 MgCl₂","method":"利用不引入新阳离子的碱沉淀 Mg²⁺","principle":"Ca(OH)₂ 只引入 Ca²⁺（原本阳离子）与 OH⁻（加适量 HCl 转变为 Cl⁻ 与 H₂O），且 Mg(OH)₂ 远比 Ca(OH)₂ 难溶。","steps":["A 会引入 Na⁺ 杂质；C、D 会把主体 Ca²⁺ 一并沉淀；B 用 Ca(OH)₂ 把 Mg²⁺ 沉淀为 Mg(OH)₂ 滤去，过量微溶 Ca(OH)₂ 用适量稀盐酸中和转为 CaCl₂ 与水，无任何新杂质。"],"ans":"B","markingPoints":["运用同离子不引入新杂质原则设计除杂方案"],"verification":"反应：MgCl₂ + Ca(OH)₂ → Mg(OH)₂↓ + CaCl₂。","pitfall":"错选 A 忽视 Na⁺ 会残留在氯化钙溶液中成为新杂质。"},{"id":"chem10-10.4-q4","tier":"L4","tierLabel":"L4 统考压轴","examStyle":"P2 实验探究","q":"已知某无色透明溶液可能含有 \\(\\mathrm{Na^+}\\)、\\(\\mathrm{K^+}\\)、\\(\\mathrm{Mg^{2+}}\\)、\\(\\mathrm{Ca^{2+}}\\)、\\(\\mathrm{Ba^{2+}}\\) 中的一种或几种。某同学进行了以下实验探究：(1) 取少量溶液滴加稀 \\(\\mathrm{Na_2SO_4}\\) 溶液，**无沉淀产生**；(2) 另取少量溶液滴加过量氨水，**立即产生白色沉淀**；(3) 将(2)过滤后的滤液滴加 \\(\\mathrm{(NH_4)_2C_2O_4}\\) 溶液，**无沉淀产生**；(4) 取原溶液做焰色试验，直接观察呈**黄色**，透过蓝色钴玻璃**未见浅紫色**。请判断该溶液中一定含有哪些阳离子？一定不含哪些阳离子？为什么(1)步先加稀 \\(\\mathrm{Na_2SO_4}\\) 对排除干扰至关重要？","given":"实验(1)-(4)结果","method":"逐条推理并排除 Ba²⁺、Ca²⁺、K⁺，确认 Mg²⁺ 与 Na⁺","principle":"Ba²⁺ 遇稀 SO₄²⁻ 必生 BaSO₄↓；Mg²⁺ 遇氨水生白沉淀；Ca²⁺ 遇草酸铵生白沉淀；Na⁺ 黄光与 K⁺ 钴玻璃滤光。","steps":["由(1)加稀 \\(\\mathrm{Na_2SO_4}\\) 无沉淀，说明**一定不含 \\(\\mathrm{Ba^{2+}}\\)**（因 \\(\\mathrm{BaSO_4}\\) 极难溶，稀溶液也会立即沉淀；同时说明若 \\(\\mathrm{Ca^{2+}}\\) 存在其在稀溶液中不一定沉淀）。","由(2)加过量氨水生白色沉淀，说明**一定含有 \\(\\mathrm{Mg^{2+}}\\)**（\\(\\mathrm{Mg(OH)_2\\downarrow}\\)）。","由(3)滤液加 \\(\\mathrm{(NH_4)_2C_2O_4}\\) 无沉淀，说明**一定不含 \\(\\mathrm{Ca^{2+}}\\)**。","由(4)焰色试验直接呈黄色且透蓝色钴玻璃无浅紫色，说明**一定含有 \\(\\mathrm{Na^+}\\)**、**一定不含 \\(\\mathrm{K^+}\\)**。","(1)步重要性：因为 \\(\\mathrm{Ba^{2+}}\\) 也会与草酸铵产生白色 \\(\\mathrm{BaC_2O_4}\\) 沉淀干扰 \\(\\mathrm{Ca^{2+}}\\) 判断，先用稀 \\(\\mathrm{Na_2SO_4}\\) 确认无 \\(\\mathrm{Ba^{2+}}\\) 才能避免误判（教材 p.248 提到 Ca 盐与 Sr、Ba 盐反应相似需综合检验）。"],"ans":"一定含 Mg²⁺、Na⁺；一定不含 Ba²⁺、Ca²⁺、K⁺。（1）步先加稀 Na₂SO₄ 用于排除 Ba²⁺ 对后续草酸铵沉淀的干扰。","markingPoints":["准确逐一判断 5 种离子的存在与否（3分）","阐明先检验排除 Ba²⁺ 对草酸铵（Ca²⁺）检验干扰的重要性（2分）"],"verification":"对照教材 p.247–248 活动 4–8 及说明文字完全吻合。","pitfall":"若认为稀 \\(\\mathrm{Na_2SO_4}\\) 无沉淀就已经能直接排除 \\(\\mathrm{Ca^{2+}}\\)，则忽略了教材活动 7 中 \\(\\mathrm{CaSO_4}\\) 微溶在稀液中本就不易沉淀的事实！"}],"cheatSheet":["\\(\\mathrm{Mg^{2+}}\\) 检验：加 \\(\\mathrm{NaOH}\\) 或氨水均生白色 \\(\\mathrm{Mg(OH)_2}\\) 沉淀，且**过量均不溶解**。","\\(\\mathrm{Ca^{2+}}\\) 检验：加 \\(\\mathrm{(NH_4)_2C_2O_4}\\) 生白色 \\(\\mathrm{CaC_2O_4}\\) 沉淀，**不溶于醋酸、溶于稀盐酸**；稀 \\(\\mathrm{Na_2SO_4}\\) 无沉淀（区别 \\(\\mathrm{Ba^{2+}}\\)）；焰色呈**砖红色**。","含 \\(\\mathrm{Mg^{2+}/Ca^{2+}/Al^{3+}}\\) 混合液分离：先加过量氨水滤出 \\(\\mathrm{Ca^{2+}}\\)；滤渣加过量 \\(\\mathrm{NaOH}\\) 留 \\(\\mathrm{Mg(OH)_2}\\)、溶出 \\(\\mathrm{AlO_2^-}\\)。"],"kbEntryIds":["kb-chem10-mg-ca-test"],"quiz":{"q":"如何一步区分 \\(\\mathrm{MgCl_2}\\) 溶液与 \\(\\mathrm{AlCl_3}\\) 溶液？简述试剂与现象。","given":"待检溶液：MgCl₂ vs AlCl₃","method":"利用 Mg(OH)₂ 不溶于过量强碱而 Al(OH)₃ 溶于过量强碱的两性差异","principle":"Mg²⁺+2OH⁻→Mg(OH)₂↓；Al(OH)₃+OH⁻→AlO₂⁻+2H₂O。","steps":["分别向两溶液中逐滴加入 **NaOH 溶液至过量**：","均先生成白色沉淀，继续滴加过量 NaOH 后，沉淀不溶解的为 \\(\\mathrm{MgCl_2}\\)；沉淀完全溶解得澄清溶液的为 \\(\\mathrm{AlCl_3}\\)。"],"ans":"逐滴加过量 NaOH 溶液：沉淀不溶为 \\(\\mathrm{MgCl_2}\\)，先沉淀后溶解为 \\(\\mathrm{AlCl_3}\\)。"}}]},"化学11":{"lessonKey":"化学11","courseCode":"chemistry","subject":"化学","chapter":11,"title":"IIIA族元素：铝","syllabus":"3.4 IIIA族元素","bookId":"sm1-chemistry-2017","bookCitation":"《马来西亚华文独中教科书 · 化学（上册）》（2017年11月版）第11章 p.253–266","examScopes":["sem2_final","uec"],"chapterOverview":{"summary":"第11章研究地壳中含量最高的金属元素——铝（IIIA 族，3s²3p¹）。由于位于元素周期表金属与非金属分界线附近，铝单质既能与酸反应又能与强碱反应放 H₂，并在常温冷浓 HNO₃/H₂SO₄ 中发生钝化；其氧化物 Al₂O₃ 与氢氧化物 Al(OH)₃ 呈典型两性，沉淀—溶解定量曲线（3:1 与 1:3）及以冰晶石助熔的铝土矿提纯电解炼铝工艺是 UEC 统考无机必考点与高分拉分题源。","conceptTree":[{"branch":"11.1 铝的性质（p.254–258）","items":["丰度 7.73%（金属首位，图 11-2）与 3s²3p¹ 电子构型","致密 Al₂O₃ 保护膜与冷浓 HNO₃/H₂SO₄ 钝化（passivation）","既溶强酸又溶强碱（Al + NaOH + H₂O）及等氢计量规律","铝热反应（图 11-3：Al + Fe₂O₃ 焊接铁轨与高熔点金属冶炼）"]},{"branch":"11.2 铝的重要化合物（p.258–261）","items":["两性氧化物 Al₂O₃（高熔点 2054 ℃、红/蓝宝石与耐火材料）","两性氢氧化物 Al(OH)₃（氨水制备法、胃酸中和剂、无公害阻燃剂）","铝盐/偏铝酸盐沉淀—溶解定量曲线（3:1 与 1:3）","复盐明矾 KAl(SO₄)₂·12H₂O 水解生成 Al(OH)₃ 胶体净水"]},{"branch":"11.3 铝的冶炼（p.262–263）","items":["铝土矿碱溶—CO₂ 酸化—灼烧提纯工艺流程（图 11-8）","冰晶石（Na₃AlF₆）作助熔剂降低电解熔融温度至约 1000 ℃","金属转化框图推断（p.266 第 5 题 A/B/C/D/E 铝家族网）"]}]},"paperFocus":["高三下半年期末考 & UEC 统考：卷一（30% 选择题）极爱考铝在冷浓硝酸/浓硫酸中的钝化现象、铝与等量 HCl/NaOH 产氢比（1:1 vs 消耗酸碱比 3:1）、氧化铝/氢氧化铝与氨水或 CO₂ 反应不溶解、以及冰晶石作用（助熔剂而非催化剂）。","UEC 卷二乙部（无机化学）及计算题：铝及其化合物“三角转化框图推断”（Al—Al₂O₃—Al(OH)₃—Al³⁺—AlO₂⁻）、图像坐标题（向 AlCl₃ 滴 NaOH 或向偏铝酸钠滴 HCl 沉淀量折线）与铝土矿电解产铝化学计算。"],"solvingWorkflow":["铝与酸碱产氢对比题：先写出 2Al + 6HCl → 2AlCl₃ + 3H₂↑ 和 2Al + 2NaOH + 2H₂O → 2NaAlO₂ + 3H₂↑；看清题干问的是“等量 Al 放 H₂ 比”（1:1）、“放等量 H₂ 耗 Al 比”（1:1）还是“放等量 H₂ 耗 HCl 与 NaOH 之比”（3:1）。","铝热反应判断题：只有比铝不活泼的金属氧化物（如 Fe₂O₃、Fe₃O₄、CrO₃、MnO₂、V₂O₅）能与 Al 高温反应；比 Al 更活泼的金属氧化物（如 MgO、CaO）不能发生铝热反应。","氢氧化铝沉淀与图像计算题：已知某点沉淀量小于最大值时，先思考“是否有碱不足（未全沉淀）与碱过量（部分沉淀再溶解）”**两个解**！","铝土矿工艺流程题：见到“铝土矿加 NaOH”即知 Al₂O₃ 溶为 NaAlO₂，Fe₂O₃ 留在残渣；见到“酸化”通入的是足量 CO₂ 而非强酸，生成沉淀 Al(OH)₃ 和溶液 NaHCO₃。"],"questionTypes":["铝与盐酸、氢氧化钠溶液反应消耗量与产气体积比计算（p.258、p.265）","铝及其氧化物在冷浓 HNO₃/H₂SO₄ 中钝化与铝制炊具使用禁忌（p.256、p.263）","铝热反应实验操作细节（滤纸漏斗、KClO₃ 与 Mg 条作用、铁轨焊接）及反应物筛选（p.257、p.265）","向 Al³⁺/H⁺ 混合液滴加 NaOH 或向 AlO₂⁻/OH⁻ 滴加 HCl 的沉淀量坐标曲线定量解析","图 11-8 铝土矿提纯与 p.266 铝家族五元转化框图（A–E）综合推断"],"scoringNotes":["写铝与氢氧化钠溶液反应离子方程式时，允许写 \\(2\\mathrm{Al + 2OH^- + 2H_2O \\to 2AlO_2^- + 3H_2\\uparrow}\\) 或 \\(2\\mathrm{Al + 2OH^- + 6H_2O \\to 2Al(OH)_4^- + 3H_2\\uparrow}\\)，但水分子数必须与偏铝酸根写法严格配套！","在铝土矿图 11-8 流程题中，答“冰晶石的作用”必须写**助熔剂**（或降低氧化铝熔点至 ~1000 ℃ 节约电能），切勿错写为“催化剂”。"],"vid":[{"t":"铝与强酸强碱反应及钝化、铝热反应实验","q":"铝 氢氧化钠 钝化 铝热反应 高中化学"},{"t":"两性氢氧化物 Al(OH)3 沉淀溶解定量曲线","q":"氢氧化铝 两性 沉淀曲线 图像计算"},{"t":"铝土矿提纯与电解氧化铝制铝工艺","q":"电解氧化铝 冰晶石 铝土矿 冶炼铝"}],"sections":[{"id":"11.1","t":"铝的性质","anchor":{"pages":"化上 p.254–258","syllabus":"3.4.1–3.4.2 铝的存在与物理性质、铝的钝化、与酸碱反应及铝热反应","examScopes":["sem2_final","uec"],"examWeight":"P1 产氢比/钝化/铝热辨析 + P2 金属酸碱混合计算与铝热实验探究","terms":"Passivation · Amphoteric metal · Thermite reaction · Aluminothermy · Bauxite","prerequisites":["金属活动性顺序与氧化还原电子守恒（化上 Ch 8）","IA/IIA 族金属化学性质对比（化上 Ch 9–10）"],"goals":["记住铝在地壳中的丰度（7.73%，金属元素首位）与物理性质（密度 2700 kg·m⁻³、熔点 660 ℃），解释铝合金的工程优势。","说明铝表面致密氧化膜（Al₂O₃）在空气抗腐蚀及冷浓硝酸/冷浓硫酸钝化中的作用，及实验前须砂纸打磨的原因。","熟练书写铝与盐酸、氢氧化钠溶液、二氧化碳及氧化铁（铝热反应，图 11-3）的方程式，并完成两性产氢定量计算。"]},"concepts":[{"kind":"definition","title":"铝的丰度（图 11-2）、结构与 11.1.1 物理性质（表 11-1）","pageRef":"化上 p.254–255","body":["**存在与丰度**：铝位于第 3 周期 IIIA 族，原子最外层电子排布为 **\\(3s^23p^1\\)**。地壳丰度（图 11-2）为氧 48.60%、硅 26.30%、**铝 7.73%**、铁 4.75%，铝是**地壳中含量最多的金属元素**，在自然界全部以化合态存在（主要是铝土矿 bauxite，主要成分 \\(\\mathrm{Al_2O_3}\\)，含 \\(\\mathrm{Fe_2O_3}\\)、\\(\\mathrm{SiO_2}\\) 杂质）。","**物理性质与表 11-1 用途**：银白色轻金属，密度 **2700 kg·m⁻³（2.70 g·cm⁻³）**，硬度小，熔点 **660 ℃**，沸点 **2327 ℃**。导电性好（制作导线、电缆）、延展性好（压成铝箔包装食品饮料）、铝粉呈银白色粉末（与油漆混合制银色油漆）。","**铝合金优势**：某些铝合金强度可与钢媲美，且具备密度小、塑性好、抗腐蚀强等优点，广泛用于航空航天、汽车与门窗建筑。"],"takeaway":"记忆地壳元素含量前三名口诀：“养（O 48.6%）闺（Si 26.3%）女（Al 7.73%）”——铝居金属第一位！"},{"kind":"mechanism","title":"氧化膜保护、冷浓酸钝化及铝与强酸、强碱反应（活动 1–2）","pageRef":"化上 p.255–256","body":["**致密氧化膜与活动 1**：常温下铝在空气中立即被氧化，表面生成一层极薄却**坚固致密的 \\(\\mathrm{Al_2O_3}\\) 氧化膜**，阻止内部铝继续氧化，因而铝具抗腐蚀性；做铝条与酸碱反应实验（活动 1）前，**必须先用砂纸打磨除去氧化膜**，否则刚放入时无气泡（氧化膜先被缓慢溶解后铝才与酸碱反应放气）。","**冷浓硝酸/冷浓硫酸钝化（passivation，p.256）**：常温下铝（以及铁）放入**冷的浓硝酸或浓硫酸**中时，表面迅速被强氧化生成致密氧化膜阻止反应继续进行，称为**钝化**。因此工业上可用**铝制或铁制容器贮存、运输冷的浓硝酸或浓硫酸**（注意：加热或改用稀硫酸/稀硝酸则会溶解！）。","**既溶酸又溶强碱的特异金属**：多数金属（如 Mg、Fe）不与碱反应，但铝既能与非氧化性酸又能与强碱溶液反应放出 \\(\\mathrm{H_2}\\)：","- 与稀盐酸：\\(2\\mathrm{Al(s) + 6HCl(aq) \\longrightarrow 2AlCl_3(aq) + 3H_2(g)}\\uparrow\\)","- 与氢氧化钠：\\(2\\mathrm{Al(s) + 2NaOH(aq) + 2H_2O(l) \\longrightarrow 2NaAlO_2(aq) + 3H_2(g)}\\uparrow\\)","**氧化剂深度辨析**：在铝与 \\(\\mathrm{NaOH}\\) 溶液反应中，\\(\\mathrm{Al}\\) 是还原剂（\\(0 \\to +3\\)），而真正作氧化剂得到电子的是 **\\(\\mathrm{H_2O}\\)**（先发生 \\(2\\mathrm{Al + 6H_2O \\to 2Al(OH)_3 + 3H_2\\uparrow}\\)，生成的 \\(\\mathrm{Al(OH)_3}\\) 随即溶于 \\(\\mathrm{NaOH}\\) 推动反应持续进行）！"],"takeaway":"为什么铝制炊具不能长时间盛放酸、碱或含食盐的菜肴（p.263 思考题 11c-3）？酸与碱会直接破坏 Al₂O₃ 膜并溶解 Al，而食盐 Cl⁻ 会破坏氧化膜引发原电池腐蚀，铝离子摄入过多有害健康！"},{"kind":"experiment","title":"活动 3：铝热反应（图 11-3）与二氧化碳还原反应","pageRef":"化上 p.256–257","body":["**活动 3 实验细节（图 11-3）**：将 2 张圆形滤纸折成双层漏斗（内层底部剪一小孔并用**水润湿**防漏料与防烧穿），架在铁圈上，下方放**盛有细沙的蒸发皿**（接住炽热熔融铁水，防炸裂实验台）。装入混匀的 **5 g 干燥 \\(\\mathrm{Fe_2O_3}\\) 粉与 2 g 铝粉**（即**铝热剂 thermite**），上方撒少量**氯酸钾 \\(\\mathrm{KClO_3}\\)**（助燃剂，受热放氧），中间插一根**镁条**（引燃剂）。戴墨镜点燃镁条，立即发出耀眼白光、放出大量热，高温熔融液态铁流落入蒸发皿冷却成铁珠！","**铝热反应应用（图 11-4）**：野外焊接铁轨（无需电源、设备简便、焊接速度快），以及工业冶炼高熔点金属（如 \\(\\mathrm{Cr, Mn, V}\\)）：\\(2\\mathrm{Al(s) + CrO_3(s)} \\xrightarrow{\\text{点燃}} \\mathrm{Cr(l) + Al_2O_3(l)}\\)；\\(4\\mathrm{Al + 3MnO_2} \\xrightarrow{\\text{高温}} 3\\mathrm{Mn + 2Al_2O_3}\\)。","**与 \\(\\mathrm{CO_2}\\) 反应**：高温下铝也能还原 \\(\\mathrm{CO_2}\\)：\\(4\\mathrm{Al(s) + 3CO_2(g) \\longrightarrow 2Al_2O_3(s) + 3C(s)}\\)。"],"takeaway":"铝热剂口诀：镁条来引燃，氯酸钾助燃放氧，细沙接铁水；铝粉做还原剂，只能还原活动性比铝弱的金属氧化物（不能还原 MgO、CaO）。"}],"formulas":[{"title":"铝与强酸及强碱溶液反应方程式","tex":"2\\mathrm{Al(s)} + 6\\mathrm{H^+(aq)} \\longrightarrow 2\\mathrm{Al^{3+}(aq)} + 3\\mathrm{H_2(g)}\\uparrow,\\qquad 2\\mathrm{Al(s)} + 2\\mathrm{OH^-(aq)} + 2\\mathrm{H_2O(l)} \\longrightarrow 2\\mathrm{AlO_2^-(aq)} + 3\\mathrm{H_2(g)}\\uparrow","plain":"2Al+6H⁺→2Al³⁺+3H2↑; 2Al+2OH⁻+2H2O→2AlO2⁻+3H2↑","conditions":"酸为非氧化性酸（稀HCl、稀H₂SO₄）；强碱液中也可写生成 2Al(OH)₄⁻（左边配 6H₂O）","pageRef":"化上 p.256","note":"每 1 mol Al 反应无论遇酸还是遇碱均失 3 mol 电子，定量生成 1.5 mol H₂。"},{"title":"铝热反应核心方程式（铁、铬、锰冶炼）","tex":"2\\mathrm{Al(s)} + \\mathrm{Fe_2O_3(s)} \\xrightarrow{\\text{点燃}} 2\\mathrm{Fe(l)} + \\mathrm{Al_2O_3(l)},\\qquad 4\\mathrm{Al(s)} + 3\\mathrm{MnO_2(s)} \\xrightarrow{\\text{高温}} 3\\mathrm{Mn(l)} + 2\\mathrm{Al_2O_3(l)}","plain":"2Al+Fe2O3→2Fe+Al2O3; 4Al+3MnO2→3Mn+2Al2O3","conditions":"需用 Mg 条 + KClO₃ 高温引燃；只能置换比 Al 活动性弱的金属","pageRef":"化上 p.257、p.266","note":"反应剧烈放热使铁与氧化铝均呈熔融液态，铁沉下、炉渣浮上。"}],"pitfalls":[{"title":"混淆“钝化”与“不发生化学反应”","wrong":"“常温下铝不与浓硝酸和浓硫酸反应，所以铝罐可以装冷浓硝酸。”","diagnosis":"把钝化误解为“绝对不反应”（物理隔绝概念不清）。","right":"钝化**属于化学变化**！铝与冷浓 \\(\\mathrm{HNO_3}\\) / 浓 \\(\\mathrm{H_2SO_4}\\) 在表面瞬间发生氧化还原反应，生成一层极其致密的氧化物保护膜阻止反应继续向深层推进（p.264 练习 1D vs 1B）。","checkRule":"看到“铝在常温下不与氧气或冷浓酸反应”皆错——常温下恰恰是**极快地表面氧化反应生成致密氧化膜**！"},{"title":"算错“等氢气”下消耗的盐酸与氢氧化钠比例","wrong":"“等物质的量铝与足量稀盐酸和 \\(\\mathrm{NaOH}\\) 反应产生等量氢气时，消耗 \\(\\mathrm{HCl}\\) 和 \\(\\mathrm{NaOH}\\) 的物质的量之比也是 1 : 1。”","diagnosis":"把消耗铝之比（1 : 1）张冠李戴成消耗酸、碱之比（教材 p.265 练习 10）。","right":"由 \\(2\\mathrm{Al \\sim 6HCl \\sim 3H_2}\\) 与 \\(2\\mathrm{Al \\sim 2NaOH \\sim 3H_2}\\) 可知：产生等体积 \\(\\mathrm{H_2}\\) 时，消耗 \\(\\mathrm{Al}\\) 之比为 **1 : 1**，而消耗 \\(\\mathrm{HCl}\\) 与 \\(\\mathrm{NaOH}\\) 之比为 **3 : 1**！","checkRule":"先写两式系数（6HCl vs 2NaOH），明确看题干问“消耗的铝比”还是“消耗的酸碱比”。"}],"examples":[{"label":"例 11.1.1","tier":"L3","tierLabel":"L3 预试必考","title":"铝粉与一定量稀盐酸、氢氧化钠溶液反应产氢综合判断","prompt":"甲、乙两个烧杯中分别盛有 \\(100\\text{ mL}\\ 3.0\\text{ mol\\,L}^{-1}\\) 的稀盐酸和 \\(100\\text{ mL}\\ 3.0\\text{ mol\\,L}^{-1}\\) 的 \\(\\mathrm{NaOH}\\) 溶液。向两烧杯中分别加入**等质量**的纯净铝粉（已擦除氧化膜），充分反应后，在同温同压下测得产生氢气的体积比 \\(V_{\\text{甲}} : V_{\\text{乙}} = 1 : 2\\)。试通过限量分析计算加入每份铝粉的质量（\\(A_r(\\mathrm{Al}) = 27\\)）。","clues":"注意酸碱的物质的量均相等（\\(0.30\\text{ mol}\\)），而耗酸碱比是 3 : 1！相同铝量时 \\(\\mathrm{HCl}\\) 先不够用（甲不足、乙足量）！","strategy":"先算 \\(n(\\mathrm{HCl})\\) 与 \\(n(\\mathrm{NaOH})\\) 各自最大理论产氢量 → 确定必定是甲烧杯盐酸限量、乙烧杯铝粉限量 → 由甲的产氢量乘 2 算乙中铝的质量！","given":"n(HCl) = 0.30 mol, n(NaOH) = 0.30 mol, V(H₂,甲) : V(H₂,乙) = 1 : 2","principle":"2Al + 6HCl → 2AlCl₃ + 3H₂↑; 2Al + 2NaOH + 2H₂O → 2NaAlO₂ + 3H₂↑。","steps":["两烧杯溶质物质的量：\\(n(\\mathrm{HCl}) = 0.100 \\times 3.0 = 0.30\\text{ mol}\\)；\\(n(\\mathrm{NaOH}) = 0.100 \\times 3.0 = 0.30\\text{ mol}\\)。","极限分析：①若铝均不足（全反应），两烧杯产氢比应为 \\(1 : 1\\)；②若酸碱均不足，\\(0.30\\text{ mol HCl}\\) 产 \\(0.15\\text{ mol }\\mathrm{H_2}\\)，\\(0.30\\text{ mol NaOH}\\) 产 \\(0.45\\text{ mol }\\mathrm{H_2}\\)，产氢比应为 \\(1 : 3\\)。","实测产氢比 \\(1 : 2\\) 恰好介于 \\(1 : 1\\) 与 \\(1 : 3\\) 之间！因此必然是：**甲烧杯中 \\(\\mathrm{HCl}\\) 耗尽（铝过量），乙烧杯中铝粉完全反应（\\(\\mathrm{NaOH}\\) 过量）**。","由甲烧杯 \\(\\mathrm{HCl}\\) 限量计算甲产生氢气：\\(n_{\\text{甲}}(\\mathrm{H_2}) = \\frac{1}{2}n(\\mathrm{HCl}) = \\frac{1}{2} \\times 0.30 = 0.150\\text{ mol}\\)。","故乙烧杯产生氢气为：\\(n_{\\text{乙}}(\\mathrm{H_2}) = 2 \\times 0.150 = 0.300\\text{ mol}\\)。","因乙中铝粉全部反应，由 \\(2\\mathrm{Al} \\sim 3\\mathrm{H_2}\\) 得：\\(n(\\mathrm{Al}) = \\frac{2}{3} \\times 0.300 = 0.200\\text{ mol}\\)，故铝粉质量 \\(m(\\mathrm{Al}) = 0.200 \\times 27 = 5.40\\text{ g}\\)。"],"answer":"加入每份铝粉的质量为 **\\(5.40\\text{ g}\\)**。","markingPoints":["利用极限比值 1:1 和 1:3 准确判断甲盐酸不足、乙铝粉不足（2分）","算得 n_甲(H₂)=0.150 mol 及 n_乙(H₂)=0.300 mol（2分）","反算铝粉物质的量 0.200 mol 及质量 5.40 g（1分）"],"verification":"验证：0.200 mol Al 在甲中最多消耗 0.600 mol HCl（而只有 0.300 mol，确过量）；在乙中只需 0.200 mol NaOH（共有 0.300 mol，确完全溶解），完全符合 1:2！","pitfall":"如果不做极限范围分析而瞎猜哪组过量，极易算反或忽略“铝在甲过量而在乙不足”的中间态。"},{"label":"例 11.1.2","tier":"L4","tierLabel":"L4 统考压轴","title":"铝热剂与镁铝铁合金与酸碱反应探究综合","prompt":"某铝热剂由 \\(\\mathrm{Al}\\) 粉和 \\(\\mathrm{Fe_2O_3}\\) 粉均匀混合而成（总质量 \\(37.5\\text{ g}\\)）。在高温隔绝空气条件下充分发生铝热反应后，冷却得到固体混合物。将冷却后全部固体均分为两等份：(1) 向第一份中加入**足量 \\(\\mathrm{NaOH}\\) 溶液**，收集到标准状况下气体 \\(3.36\\text{ L}\\)；(2) 向第二份中加入**足量稀盐酸**，收集到标准状况下气体 \\(6.72\\text{ L}\\)。试判断铝热反应后 \\(\\mathrm{Al}\\) 与 \\(\\mathrm{Fe_2O_3}\\) 谁过量？并求原铝热剂中 \\(\\mathrm{Al}\\) 与 \\(\\mathrm{Fe_2O_3}\\) 的质量比。（\\(A_r: \\mathrm{Al}=27, \\mathrm{Fe}=56, \\mathrm{O}=16\\)）","clues":"碱只与反应剩余的金属 \\(\\mathrm{Al}\\) 产气（生成的 \\(\\mathrm{Al_2O_3}\\) 虽溶碱但不产气！）；酸既与剩余 \\(\\mathrm{Al}\\) 产气，又与铝热生成的 \\(\\mathrm{Fe}\\) 产气！","strategy":"由第一份碱产氢算出剩余 \\(\\mathrm{Al}\\) → 从第二份酸总产氢扣除这部分 \\(\\mathrm{Al}\\) 产氢，差值即为生成 \\(\\mathrm{Fe}\\) 产氢 → 由铁守恒算 \\(\\mathrm{Fe_2O_3}\\) 与耗 \\(\\mathrm{Al}\\)，并加总质量校验。","given":"总 m=37.5 g，每份 18.75 g；加足量 NaOH 产 H₂ 3.36 L (0.150 mol)；加足量 HCl 产 H₂ 6.72 L (0.300 mol)","principle":"只有单质 Al 与 NaOH 产 H₂（Al₂O₃ 不产 H₂）；Al 与 Fe 均与稀盐酸产 H₂。","steps":["分析每份固体（占原总量的 \\(1/2\\)，即对应原铝热剂 \\(18.75\\text{ g}\\)）：","**步骤 1（求剩余未反应的 Al）**：加足量 \\(\\mathrm{NaOH}\\) 产生 \\(\\mathrm{H_2}\\ 3.36\\text{ L}\\)（即 \\(\\frac{3.36}{22.4} = 0.150\\text{ mol}\\)），这证明铝热反应后**金属铝粉过量**！由 \\(2\\mathrm{Al} \\sim 3\\mathrm{H_2}\\) 得每份中剩余 \\(n_{\\text{余}}(\\mathrm{Al}) = \\frac{2}{3} \\times 0.150 = 0.100\\text{ mol}\\)。","**步骤 2（求生成的 Fe 与消耗的 Fe₂O₃）**：第二份加足量稀盐酸共产生 \\(\\mathrm{H_2}\\ \\frac{6.72}{22.4} = 0.300\\text{ mol}\\)。其中剩余 \\(\\mathrm{Al}\\) 在盐酸中仍产生 \\(0.150\\text{ mol }\\mathrm{H_2}\\)，故铝热生成的单质铁与盐酸反应产氢为：\\(n_{\\mathrm{Fe}}(\\mathrm{H_2}) = 0.300 - 0.150 = 0.150\\text{ mol}\\)。","由 \\(\\mathrm{Fe + 2HCl \\to FeCl_2 + H_2}\\uparrow\\) 得每份含铁 \\(n(\\mathrm{Fe}) = 0.150\\text{ mol}\\)。回溯铝热反应 \\(2\\mathrm{Al + Fe_2O_3} \\xrightarrow{\\text{高温}} 2\\mathrm{Fe + Al_2O_3}\\)，知每份中原有 \\(n(\\mathrm{Fe_2O_3}) = \\frac{1}{2}n(\\mathrm{Fe}) = 0.0750\\text{ mol}\\)，同时消耗掉的 \\(\\mathrm{Al}\\) 为 \\(n_{\\text{耗}}(\\mathrm{Al}) = 0.150\\text{ mol}\\)。","**步骤 3（总质量复核与质量比）**：原每份含总铝 \\(n_{\\text{总}}(\\mathrm{Al}) = 0.100 + 0.150 = 0.250\\text{ mol}\\)（质量 \\(0.250 \\times 27 = 6.75\\text{ g}\\)）；原每份含 \\(\\mathrm{Fe_2O_3}\\) 质量 \\(0.0750 \\times 160 = 12.0\\text{ g}\\)。校验总质量：\\(6.75 + 12.0 = 18.75\\text{ g}\\)，两份合计 \\(37.5\\text{ g}\\) 完全自洽！故原铝热剂中 \\(m(\\mathrm{Al}) : m(\\mathrm{Fe_2O_3}) = 6.75 : 12.0 = 9 : 16\\)。"],"answer":"铝粉过量；原铝热剂中 Al 与 Fe₂O₃ 质量比为 6.75 : 12.0 = **9 : 16**。","markingPoints":["判断加 NaOH 产气证明 Al 过量并求出剩余 Al 0.100 mol/份（2分）","扣除剩余 Al 产氢后求得 Fe 为 0.150 mol/份、耗 Al 0.150 mol、Fe₂O₃ 0.0750 mol（2分）","算得两份合计质量比 9 : 16 并与总质量 37.5 g 吻合（1分）"],"verification":"每份 0.250 mol Al (6.75 g) + 0.0750 mol Fe₂O₃ (12.0 g) = 18.75 g，两份合计 37.5 g。","pitfall":"误以为反应生成的 \\(\\mathrm{Al_2O_3}\\) 与 \\(\\mathrm{NaOH}\\) 反应也会放出氢气，或误把 Fe 算成与 NaOH 反应。"}],"practice":[{"id":"chem11-11.1-q1","tier":"L1","tierLabel":"L1 基础","examStyle":"P1 选择","q":"常温下，工业上常可用铝制槽车安全运输浓硝酸或浓硫酸，其主要原因是（　）。","options":["A. 铝的金属活动性极弱，比铜还稳定","B. 铝在常温下遇冷的浓硝酸或浓硫酸表面发生钝化，形成致密氧化膜","C. 浓硝酸和浓硫酸不含氢离子，不具有酸性","D. 铝只与碱溶液反应，绝不与任何酸发生反应"],"correctOption":"B","given":"p.256 铝的钝化","method":"对照冷浓酸钝化机理判断","principle":"常温下冷浓 HNO₃、冷浓 H₂SO₄ 使 Al、Fe 表面生成坚固致密氧化膜阻止继续反应。","steps":["A 错，铝很活泼；C 错，浓硝酸、浓硫酸有强氧化性与酸性；D 错，铝与稀酸剧烈放氢；B 正确。"],"ans":"B","markingPoints":["掌握冷浓硝酸/浓硫酸使铝钝化"],"verification":"化上 p.256 原文明确说明“可用铝制的容器储存冷的浓硝酸或浓硫酸”。","pitfall":"注意前提必须是“冷的”浓酸，加热时钝化膜会被破坏而剧烈反应！"},{"id":"chem11-11.1-q2","tier":"L2","tierLabel":"L2 期末","examStyle":"P1 选择","q":"将两份质量相等的铝粉，分别投入足量的稀盐酸和足量的氢氧化钠溶液中充分反应，在相同状况下收集到氢气的体积比是（　）。（p.258 思考题 11a-2）","options":["A. 1 : 1","B. 1 : 2","C. 2 : 1","D. 1 : 3"],"correctOption":"A","given":"铝质量相等，稀盐酸与 NaOH 均足量","method":"依据铝失电子数守恒直接比较产氢量","principle":"1 mol Al 无论在足量酸还是足量强碱中均失去 3 mol 电子生成 1.5 mol H₂。","steps":["铝为限量反应物且均完全转化，故产生 H₂ 物质的量与体积比恒为 1 : 1。"],"ans":"A","markingPoints":["快速运用电子守恒判断等量铝遇足量酸碱产氢相等"],"verification":"化上 p.258 思考题 11a-2 改编。","pitfall":"误选 D 把消耗酸与碱的计量比（3:1）当成产生氢气的体积比。"},{"id":"chem11-11.1-q3","tier":"L2","tierLabel":"L2 期末","examStyle":"P1 选择","q":"下列各组粉末混合物在高温镁条引燃条件下，**不能**发生剧烈置换（铝热）反应的是（　）。（p.265 教材题 8）","options":["A. 铝粉和四氧化三铁（\\(\\mathrm{Fe_3O_4}\\)）粉末","B. 五氧化二钒（\\(\\mathrm{V_2O_5}\\)）粉末和铝粉","C. 铝粉和氧化镁（\\(\\mathrm{MgO}\\)）粉末","D. 铝粉和二氧化锰（\\(\\mathrm{MnO_2}\\)）粉末"],"correctOption":"C","given":"p.265 练习题 8","method":"比较金属活动性顺序（K Ca Na Mg Al Zn Fe ...）","principle":"还原剂铝只能置换出活动性比铝弱的金属氧化物中的金属。","steps":["Mg 的金属活动性强于 Al，故高温下 Al 无法从 MgO 中夺取氧置换出 Mg，C 不能发生反应；Fe、V、Mn 均不如 Al 活泼，A、B、D 均能剧烈发生铝热反应。"],"ans":"C","markingPoints":["利用金属活动性顺序判定铝热反应可行性"],"verification":"教材 p.265 第 8 题原题核对。","pitfall":"误选 B 不认识五氧化二钒，其实常见过渡金属 V、Cr、Mn、Fe 氧化物皆可被 Al 还原。"},{"id":"chem11-11.1-q4","tier":"L3","tierLabel":"L3 预试","examStyle":"P2 简答","q":"（活动 1 与思考题 11c-3）(1) 在活动 1 中，为什么取两根未用砂纸打磨的铝条分别直接投入稀盐酸和 \\(\\mathrm{NaOH}\\) 溶液中时，开始几秒钟看不到气泡冒出，片刻后才剧烈冒泡？写出氧化膜溶解的化学方程式。(2) 为什么家庭中铝制炊具不能长时间盛放酸性、碱性或含食盐的食品？","given":"p.256 活动 1 & p.263 思考题 11c-3","method":"从致密两性氧化膜 Al₂O₃ 的先溶解及 Cl⁻ 破坏氧化膜切入","principle":"Al₂O₃ 既溶于酸又溶于强碱（不产气泡），除尽后内层 Al 才与酸碱反应产 H₂。","steps":["(1) 铝条表面覆盖一层致密的 \\(\\mathrm{Al_2O_3}\\) 氧化膜。刚放入酸或碱时，两性氧化物 \\(\\mathrm{Al_2O_3}\\) 先与盐酸或 \\(\\mathrm{NaOH}\\) 反应溶解（此步**不产生气体**）：\\(\\mathrm{Al_2O_3 + 6HCl \\to 2AlCl_3 + 3H_2O}\\)、\\(\\mathrm{Al_2O_3 + 2NaOH \\to 2NaAlO_2 + H_2O}\\)；待氧化膜溶尽、内层金属铝裸露后，才开始剧烈反应放出 \\(\\mathrm{H_2}\\) 气泡。","(2) 酸性、碱性食品会直接溶解铝表面的 \\(\\mathrm{Al_2O_3}\\) 保护膜并进一步腐蚀金属铝；含食盐（\\(\\mathrm{Cl^-}\\)）的溶液会渗透破坏致密氧化膜引发电化学腐蚀；同时溶解产生的 \\(\\mathrm{Al^{3+}}\\) 进入食物被人长期摄入会危害神经与骨骼健康。"],"ans":"(1) 先溶解表面 Al₂O₃ 膜（无气体），露出的 Al 再与酸/碱反应放 H₂；(2) 酸碱直接腐蚀溶解 Al₂O₃ 与 Al，Cl⁻ 破坏氧化膜加速腐蚀且铝摄入有害健康。","markingPoints":["写出氧化膜先溶解无气体生成及两个两性溶解方程式（3分）","准确说明酸碱溶膜、盐中 Cl⁻ 破坏膜及铝积累危害健康（2分）"],"verification":"化上 p.256、p.261、p.263 知识点全面串联。","pitfall":"只答“有氧化膜挡着”而漏写酸化/碱化溶解过程。"},{"id":"chem11-11.1-q5","tier":"L4","tierLabel":"L4 统考压轴","examStyle":"P2 实验探究","q":"某研究小组按图 11-3 装置完成 \\(2\\mathrm{Al + Fe_2O_3} \\xrightarrow{\\text{点燃}} 2\\mathrm{Fe + Al_2O_3}\\) 铝热反应实验：(1) 写出实验中加入氯酸钾（\\(\\mathrm{KClO_3}\\)）、插入镁条以及下方蒸发皿铺细沙的作用；(2) 有同学将冷却后的黑色铁珠取出，用磁铁一吸全部吸起，但另一同学指出里面可能仍夹杂少量未反应的铝粉或生成的金属化合物。请用纯化学试剂（不借助磁铁）设计实验检验该固体块中是否还混有单质铝。","given":"图 11-3 铝热实验装置及产物检验","method":"紧扣装置部件功能及 Al 独有的“遇强碱产 H₂”特性设计检验方案","principle":"Fe、Fe₂O₃、Al₂O₃ 遇 NaOH 均不放气体（Al₂O₃ 仅溶解无气体），只有单质 Al 与 NaOH 溶液放出 H₂。","steps":["(1) **镁条**：燃烧放出强热提供引燃温度；**氯酸钾 \\(\\mathrm{KClO_3}\\)**：受热分解放出氧气助燃镁条，确保持续产生高温引燃铝热剂；**细沙**：吸收炽热液态熔融物的热量并缓冲冲击，防止高温铁水直接烫裂（炸裂）蒸发皿。","(2) **检验残留单质 Al 的实验方案**：取少量冷却碾碎后的产物固体于试管中，加入**足量 \\(\\mathrm{NaOH}\\) 溶液**，观察现象。若有**无色气泡产生**（收集点燃有爆鸣声，即 \\(\\mathrm{H_2}\\)），说明混有未反应完的单质铝（\\(2\\mathrm{Al + 2NaOH + 2H_2O \\to 2NaAlO_2 + 3H_2\\uparrow}\\)）；若固体部分或完全不产生气泡，则不含单质铝。"],"ans":"(1) 镁条引燃供热，KClO₃ 分解放氧助燃，细沙隔热缓冲防蒸发皿炸裂；(2) 加足量 NaOH 溶液，有气泡产生则含单质 Al。","markingPoints":["完整答出 Mg 条、KClO₃ 及细沙各自实验功能（3分）","利用 NaOH 溶液独与单质 Al 产 H₂（而与 Fe、Al₂O₃ 均不产气）检验（2分）"],"verification":"注意不能加稀盐酸检验铝，因为 Fe 和 Al 遇稀盐酸都会产生 H₂ 无法区分！","pitfall":"检验铁珠中是否含铝时误加稀盐酸——铁也与盐酸反应放氢气，无法区别！"}],"cheatSheet":["地壳丰度：O (48.6%) > Si (26.3%) > **Al (7.73%)** > Fe (4.75%)；铝在冷浓 \\(\\mathrm{HNO_3/H_2SO_4}\\) 中发生**钝化**（化学变化）。","铝与酸碱定量比：等量 Al 遇足量酸/碱产 \\(\\mathrm{H_2}\\) 为 **1 : 1**；产等量 \\(\\mathrm{H_2}\\) 耗 \\(\\mathrm{HCl}\\) 与 \\(\\mathrm{NaOH}\\) 物质的量之比为 **3 : 1**。","铝热剂（\\(\\mathrm{Al + Fe_2O_3}\\)）：Mg 条引燃 + \\(\\mathrm{KClO_3}\\) 助燃 + 细沙接铁水；Al 不能还原比它更活泼的 MgO。"],"kbEntryIds":["kb-chem11-al-props","kb-chem11-al-acid-base-thermite"],"quiz":{"q":"将 \\(5.4\\text{ g}\\) 铝粉分别与足量稀硫酸和足量 \\(\\mathrm{NaOH}\\) 溶液完全反应，共消耗氧化剂（\\(\\mathrm{H_2SO_4}\\) 与 \\(\\mathrm{H_2O}\\)）转移的电子数各是多少摩尔？（\\(A_r(\\mathrm{Al})=27\\)）","given":"m(Al)=5.4 g (0.20 mol)","method":"由 Al → Al³⁺ / AlO₂⁻ 失 3e⁻ 计算两反应转移电子数","principle":"Al 无论与酸还是强碱反应，氧化数均由 0 升至 +3。","steps":["\\(n(\\mathrm{Al}) = 5.4 / 27 = 0.20\\text{ mol}\\)。","每 \\(1\\text{ mol Al}\\) 失去 \\(3\\text{ mol }e^-\\)，故两个反应转移电子物质的量完全相等，各为 \\(0.20 \\times 3 = 0.60\\text{ mol}\\)。"],"ans":"各为 \\(0.60\\text{ mol}\\)"}},{"id":"11.2","t":"铝的重要化合物","anchor":{"pages":"化上 p.258–261","syllabus":"3.4.3 氧化铝（两性氧化物）、氢氧化铝（两性氢氧化物）、沉淀曲线及明矾","examScopes":["sem2_final","uec"],"examWeight":"P1 两性判断与沉淀制备试剂选择 + P2 沉淀溶解定量曲线与离子方程","terms":"Amphoteric oxide (Al₂O₃) · Amphoteric hydroxide (Al(OH)₃) · Aluminate (AlO₂⁻ / Al(OH)₄⁻) · Alum","prerequisites":["金属铝与酸碱反应（11.1）","盐类水解与胶体净水基础"],"goals":["定义两性氧化物与两性氢氧化物，准确书写 Al₂O₃ 与 Al(OH)₃ 分别和强酸、强碱反应的化学及离子方程式。","熟练绘制并定量解析 Al³⁺ 加 NaOH/氨水 及 AlO₂⁻ 加 HCl/CO₂ 的四条沉淀—溶解曲线（图 11-1）。","说明实验室制取 Al(OH)₃ 选用氨水的原因，以及明矾（KAl(SO₄)₂·12H₂O）复盐组成与净水胶体吸附机理。"]},"concepts":[{"kind":"definition","title":"两性氧化物（Al₂O₃）与两性氢氧化物（Al(OH)₃）的本质","pageRef":"化上 p.258–260、p.264","body":["**两性氧化物（amphoteric oxide）**：既可以与酸反应生成盐和水，又可以与强碱反应生成盐和水的氧化物。**氧化铝（\\(\\mathrm{Al_2O_3}\\)）**是典型代表（白色难溶固体，**熔点 2054 ℃**、硬度大；红宝石含微量 Cr、蓝宝石含微量 Fe 和 Ti，用于陶瓷、磨料、耐火材料与冶炼铝原料）：","- 与酸：\\(\\mathrm{Al_2O_3(s) + 3H_2SO_4(aq) \\longrightarrow Al_2(SO_4)_3(aq) + 3H_2O(l)}\\)（离子式：\\(\\mathrm{Al_2O_3 + 6H^+ \\to 2Al^{3+} + 3H_2O}\\)）","- 与强碱：\\(\\mathrm{Al_2O_3(s) + 2NaOH(aq) \\longrightarrow 2NaAlO_2(aq) + H_2O(l)}\\)（离子式：\\(\\mathrm{Al_2O_3 + 2OH^- \\to 2AlO_2^- + H_2O}\\)）","**两性氢氧化物（amphoteric hydroxide）**：既能与酸反应生成盐和水，又能与强碱溶液反应生成盐和水的氢氧化物。**氢氧化铝（\\(\\mathrm{Al(OH)_3}\\)）**是白色不溶胶状物，既溶强酸也溶强碱（注意：\\(\\mathrm{Al_2O_3}\\) 和 \\(\\mathrm{Al(OH)_3}\\) **都不溶于弱碱氨水**和弱酸碳酸，见 p.265 练习 6–7！）：","- 酸溶：\\(\\mathrm{Al(OH)_3(s) + 3H^+(aq) \\longrightarrow Al^{3+}(aq) + 3H_2O(l)}\\)","- 碱溶：\\(\\mathrm{Al(OH)_3(s) + OH^-(aq) \\longrightarrow Al(OH)_4^-(aq)}\\)（也可等价写为 \\(\\mathrm{Al(OH)_3 + OH^- \\to AlO_2^- + 2H_2O}\\)）","**医学与防火应用（p.260）**：\\(\\mathrm{Al(OH)_3}\\) 碱性温和不刺激胃壁，是常用**胃酸中和剂**（\\(\\mathrm{Al(OH)_3 + 3HCl \\to AlCl_3 + 3H_2O}\\)）；受热分解吸收大量热并释放水蒸气冲淡可燃气体：\\(2\\mathrm{Al(OH)_3(s)} \\xrightarrow{\\Delta} \\mathrm{Al_2O_3(s) + 3H_2O(l)}\\)，兼具**阻燃、消烟、填充**三大功能，被誉为无公害阻燃剂。"],"takeaway":"记住“两性只溶强，不溶弱”：Al₂O₃ 和 Al(OH)₃ 均能溶于强酸（HCl/H₂SO₄）和强碱（NaOH/KOH），但均不溶于弱碱（氨水）和弱酸（H₂CO₃/CO₂）！"},{"kind":"law","title":"活动 4–5：氢氧化铝制备试剂选择与四条沉淀—溶解定量曲线","pageRef":"化上 p.259–261、p.263","body":["**实验室制备 \\(\\mathrm{Al(OH)_3}\\) 最佳方法（p.259–263）**：向铝盐（如 \\(\\mathrm{Al_2(SO_4)_3}\\) 或 \\(\\mathrm{AlCl_3}\\)）溶液中滴加**氨水**（弱碱）：\\(\\mathrm{Al_2(SO_4)_3 + 6NH_3\\cdot H_2O \\to 2Al(OH)_3\\downarrow + 3(NH_4)_2SO_4}\\)。因为氨水过量时沉淀**不溶解**；若用 \\(\\mathrm{NaOH}\\) 溶液，稍过量就会导致生成的 \\(\\mathrm{Al(OH)_3}\\) 重新溶解损失，很难控制用量。","**以偏铝酸盐制备 \\(\\mathrm{Al(OH)_3}\\) 最佳方法（p.263）**：向 \\(\\mathrm{NaAlO_2}\\) 溶液中通入**二氧化碳（弱酸）**：\\(\\mathrm{NaAlO_2(aq) + CO_2(g) + 2H_2O(l) \\to Al(OH)_3(s)\\downarrow + NaHCO_3(aq)}\\)，过量 \\(\\mathrm{CO_2}\\) 也不溶解沉淀！","**四大定量沉淀比（必背坐标折线，见图 11-1）**：","- 向 \\(1\\text{ mol }\\mathrm{Al^{3+}}\\) 逐滴加 \\(\\mathrm{NaOH}\\)：沉淀达最大（\\(1\\text{ mol}\\)）耗 \\(3\\text{ mol }\\mathrm{OH^-}\\)，完全溶解耗 \\(1\\text{ mol }\\mathrm{OH^-}\\)，比例 **3 : 1**。","- 向 \\(1\\text{ mol }\\mathrm{AlO_2^-}\\) 逐滴加 \\(\\mathrm{HCl}\\)：沉淀达最大（\\(1\\text{ mol}\\)）耗 \\(1\\text{ mol }\\mathrm{H^+}\\)，完全溶解耗 \\(3\\text{ mol }\\mathrm{H^+}\\)，比例 **1 : 3**。"],"takeaway":"互滴鉴别 \\(\\mathrm{AlCl_3}\\) 与 \\(\\mathrm{NaOH}\\)（不用其他试剂）：将 A 滴入 B 立即产生沉淀且迅速消失（后大量沉淀），则是将 \\(\\mathrm{AlCl_3}\\) 滴入 \\(\\mathrm{NaOH}\\)；立即沉淀、后才消失，则是将 \\(\\mathrm{NaOH}\\) 滴入 \\(\\mathrm{AlCl_3}\\)！"},{"kind":"definition","title":"硫酸铝钾与明矾（KAl(SO₄)₂·12H₂O）复盐及净水机制","pageRef":"化上 p.260–261","body":["**复盐（double salt）**：由两种不同的金属阳离子（或铵根）和一种酸根离子构成的盐。典型代表为硫酸铝钾 \\(\\mathrm{KAl(SO_4)_2}\\)，十二水合物 **\\(\\mathrm{KAl(SO_4)_2\\cdot 12H_2O}\\)** 俗称**明矾（alum）**（图 11-6 无色晶体，易溶于水）。","**明矾净水原理（p.261）**：","- ① 完全电离：\\(\\mathrm{KAl(SO_4)_2(s) \\longrightarrow K^+(aq) + Al^{3+}(aq) + 2SO_4^{2-}(aq)}\\)；","- ② 水解生胶体：\\(\\mathrm{Al^{3+}(aq) + 3H_2O(l) \\rightleftharpoons Al(OH)_3(\\text{胶体}) + 3H^+(aq)}\\)；","- ③ 胶体吸附聚沉：生成的 \\(\\mathrm{Al(OH)_3}\\) 胶体吸附能力极强，使水中悬浮微粒聚沉澄清（只能**去悬浮杂质**，不能**杀菌消毒**）。","**环保新趋势**：由于铝在人体内长期积累有害健康，目前饮用水净水正逐步用**含铁净水剂**取代含铝净水剂。"],"takeaway":"明矾净水是“Al³⁺ 水解生成氢氧化铝胶体吸附悬浮物聚沉”，但无法杀灭细菌病毒；杀菌需用 Cl₂/ClO₂。"}],"formulas":[{"title":"氧化铝与氢氧化铝的两性离子方程式","tex":"\\mathrm{Al_2O_3} + 6\\mathrm{H^+} \\longrightarrow 2\\mathrm{Al^{3+}} + 3\\mathrm{H_2O},\\qquad \\mathrm{Al_2O_3} + 2\\mathrm{OH^-} \\longrightarrow 2\\mathrm{AlO_2^-} + \\mathrm{H_2O}","plain":"Al2O3 + 6H⁺ → 2Al³⁺ + 3H2O; Al2O3 + 2OH⁻ → 2AlO2⁻ + H2O","conditions":"Al₂O₃ 不溶于水，不与氨水/碳酸反应","pageRef":"化上 p.259–260","note":"Al(OH)₃ 与强碱反应也可写为 Al(OH)₃ + OH⁻ → Al(OH)₄⁻。"},{"title":"明矾电离水解及 CO₂ 酸化偏铝酸钠方程式","tex":"\\mathrm{Al^{3+}(aq)} + 3\\mathrm{H_2O(l)} \\rightleftharpoons \\mathrm{Al(OH)_3(\\text{胶体})} + 3\\mathrm{H^+(aq)},\\qquad \\mathrm{NaAlO_2(aq)} + \\mathrm{CO_2(g)} + 2\\mathrm{H_2O(l)} \\longrightarrow \\mathrm{Al(OH)_3(s)}\\downarrow + \\mathrm{NaHCO_3(aq)}","plain":"Al³⁺ + 3H2O ⇌ Al(OH)3(胶体) + 3H⁺; NaAlO2 + CO2 + 2H2O → Al(OH)3↓ + NaHCO3","conditions":"Al(OH)₃ 胶体不写 ↓（仅作净水絮凝用）；通足量 CO₂ 生成 NaHCO₃ 而不溶解 Al(OH)₃","pageRef":"化上 p.261、p.263","note":"注意当通入少量 CO₂ 时，反应产物为 Na₂CO₃（2NaAlO₂ + CO₂ + 3H₂O → 2Al(OH)₃↓ + Na₂CO₃）。"}],"pitfalls":[{"title":"误以为氧化铝能直接溶于水或溶于氨水","wrong":"“\\(\\mathrm{Al_2O_3}\\) 既能溶于氨水，也能直接和水化合生成 \\(\\mathrm{Al(OH)_3}\\)。”","diagnosis":"教材 p.265 练习 6–7 经典错误选项：\\(\\mathrm{Al_2O_3}\\) 是高晶格能难溶固体，绝不与水化合；它和 \\(\\mathrm{Al(OH)_3}\\) 均只溶于强酸/强碱，不溶于弱碱氨水。","right":"制备 \\(\\mathrm{Al(OH)_3}\\) 必须先将 \\(\\mathrm{Al_2O_3}\\) 溶于强酸得 \\(\\mathrm{Al^{3+}}\\) 再加氨水沉淀（或溶于强碱得 \\(\\mathrm{AlO_2^-}\\) 再通 \\(\\mathrm{CO_2}\\) 沉淀）。","checkRule":"凡是选项出现“Al₂O₃ + H₂O → Al(OH)₃”或“Al(OH)₃ 溶于氨水”，直接判错！"},{"title":"定量沉淀计算漏掉“强碱过量回溶”的双解","wrong":"“向 \\(0.10\\text{ mol }\\mathrm{AlCl_3}\\) 溶液中加 \\(\\mathrm{NaOH}\\) 生成 \\(0.05\\text{ mol }\\mathrm{Al(OH)_3}\\) 沉淀，消耗 \\(\\mathrm{NaOH}\\) 只有 \\(0.15\\text{ mol}\\)。”","diagnosis":"只考虑了沉淀上升段（碱不足），忘记了沉淀完全后继续加碱回溶下降段（碱过量）也会经过 \\(0.05\\text{ mol}\\) 沉淀！","right":"该题应有**两组解**：①碱不足：\\(n(\\mathrm{NaOH}) = 3 \\times 0.05 = 0.15\\text{ mol}\\)；②碱过量：先用 \\(0.30\\text{ mol}\\) 全沉淀得 \\(0.10\\text{ mol}\\)，再消耗 \\((0.10 - 0.05) = 0.05\\text{ mol}\\) 溶解掉一半，总耗 **\\(0.35\\text{ mol}\\)**！","checkRule":"见图 11-1：若生成的沉淀 \\(n < n_{\\max}\\)，必须画水平线交曲线于两点（除非题目明确说明“溶液无 AlO₂⁻”或“最小/最大耗碱量”）。"}],"examples":[{"label":"例 11.2.1","tier":"L2","tierLabel":"L2 期末必考","title":"Al、Al₂O₃、Al(OH)₃ 耗碱与产酸能力定量对比（p.265 教材题 9）","prompt":"(1) 分别取 \\(1.0\\text{ mol}\\) 的 \\(\\mathrm{Al}\\)、\\(\\mathrm{Al_2O_3}\\) 和 \\(\\mathrm{Al(OH)_3}\\)，逐一加入等物质的量浓度的 \\(\\mathrm{NaOH}\\) 溶液直至均完全溶解（无固体剩余），求三者消耗 \\(\\mathrm{NaOH}\\) 溶液的体积之比；(2) 若三者均改为与等浓度稀盐酸反应至完全溶解，消耗稀盐酸的体积之比又是多少？","clues":"利用“铝元素守恒”直接看产物 \\(\\mathrm{NaAlO_2}\\) 和 \\(\\mathrm{AlCl_3}\\) 中的铝原子个数！","strategy":"1 mol Al → 1 mol NaAlO₂（耗 1 NaOH）；1 mol Al₂O₃ → 2 mol NaAlO₂（耗 2 NaOH）；1 mol Al(OH)₃ → 1 mol NaAlO₂（耗 1 NaOH）。","given":"n(Al) = n(Al₂O₃) = n(Al(OH)₃) = 1.0 mol","principle":"元素守恒与最终产物 NaAlO₂ (Na:Al=1:1) / AlCl₃ (Cl:Al=3:1) 组成比。","steps":["第(1)问（耗 \\(\\mathrm{NaOH}\\)）：三者完全溶于 \\(\\mathrm{NaOH}\\) 后铝元素全部转化为 \\(\\mathrm{NaAlO_2}\\)（\\(\\mathrm{Na^+}\\) 与 \\(\\mathrm{AlO_2^-}\\) 物质的量之比为 \\(1:1\\)）。","- \\(1.0\\text{ mol Al}\\) 含 \\(1.0\\text{ mol Al}\\) → 需 \\(1.0\\text{ mol NaOH}\\)（\\(2\\mathrm{Al + 2NaOH + 2H_2O \\to 2NaAlO_2 + 3H_2\\uparrow}\\)）；","- \\(1.0\\text{ mol }\\mathrm{Al_2O_3}\\) 含 \\(2.0\\text{ mol Al}\\) → 需 \\(2.0\\text{ mol NaOH}\\)（\\(\\mathrm{Al_2O_3 + 2NaOH \\to 2NaAlO_2 + H_2O}\\)）；","- \\(1.0\\text{ mol }\\mathrm{Al(OH)_3}\\) 含 \\(1.0\\text{ mol Al}\\) → 需 \\(1.0\\text{ mol NaOH}\\)（\\(\\mathrm{Al(OH)_3 + NaOH \\to NaAlO_2 + 2H_2O}\\)）。","浓度相等时体积比等于物质的量之比 = **1 : 2 : 1**。","第(2)问（耗 \\(\\mathrm{HCl}\\)）：三者完全溶于稀盐酸后铝元素全部转化为 \\(\\mathrm{AlCl_3}\\)（\\(\\mathrm{Cl^-:Al^{3+}=3:1}\\)），故消耗 \\(\\mathrm{HCl}\\) 分别为 \\(3.0\\text{ mol}\\)、\\(6.0\\text{ mol}\\)、\\(3.0\\text{ mol}\\)，体积比仍为 **1 : 2 : 1**！"],"answer":"(1) 消耗 NaOH 体积比为 1 : 2 : 1；(2) 消耗稀盐酸体积比为 1 : 2 : 1。","markingPoints":["利用最终产物 NaAlO₂ 中 Na:Al = 1:1 写出耗 NaOH 为 1:2:1（2分）","利用 AlCl₃ 中 Cl:Al = 3:1 推出耗 HCl 比仍为 1:2:1（2分）"],"verification":"对照教材 p.265 选择题 9 选项 C（1 : 2 : 1）完全一致。","pitfall":"若误把 1 mol Al₂O₃ 当作只含 1 mol Al 而错选 1:1:1，或混淆耗 NaOH 与耗 HCl 系数导致算错。"},{"label":"例 11.2.2","tier":"L4","tierLabel":"L4 统考压轴","title":"含 H⁺ 与 Al³⁺ 混合溶液滴加 NaOH 的分段定量曲线计算","prompt":"向 \\(100\\text{ mL}\\) 含有 \\(\\mathrm{HCl}\\) 和 \\(\\mathrm{AlCl_3}\\) 的混合溶液中，逐滴加入 \\(1.0\\text{ mol\\,L}^{-1}\\) 的 \\(\\mathrm{NaOH}\\) 溶液，并实时记录生成白色 \\(\\mathrm{Al(OH)_3}\\) 沉淀的物质的量 \\(n\\) 随加入 \\(\\mathrm{NaOH}\\) 溶液体积 \\(V\\) 的变化：实验测得在 \\(V = 0\\text{–}40\\text{ mL}\\) 期间**无沉淀生成**；当 \\(V = 160\\text{ mL}\\) 时沉淀达到最大值；继续滴加至某一体积 \\(V_{\\text{终}}\\) 时沉淀恰好完全消失。试求：(1) 原混合溶液中 \\(\\mathrm{HCl}\\) 与 \\(\\mathrm{AlCl_3}\\) 的物质的量浓度；(2) 沉淀恰好完全消失时 \\(V_{\\text{终}}\\) 的数值以及达到最大沉淀量的一半时消耗 \\(\\mathrm{NaOH}\\) 的体积（所有可能值）。","clues":"紧扣离子反应先后顺序：**酸碱中和永远最优先**（\\(\\mathrm{H^+ + OH^- \\to H_2O}\\)）→ 其次生成沉淀（\\(\\mathrm{Al^{3+} + 3OH^- \\to Al(OH)_3\\downarrow}\\)）→ 最后沉淀溶解（\\(\\mathrm{Al(OH)_3 + OH^- \\to AlO_2^- + 2H_2O}\\)）！","strategy":"三段法拆解体积区间：0–40 mL 算 HCl；40–160 mL（120 mL）算 AlCl₃；按 3:1 求溶解段体积（40 mL）；再对最大沉淀一半（0.020 mol）求双解。","given":"V_mix=100 mL, c(NaOH)=1.0 mol/L; 0–40 mL 无沉淀；40–160 mL 沉淀达最大","principle":"中和优先于沉淀，沉淀优先于两性溶解；沉淀生成与溶解耗 OH⁻ 比 3 : 1。","steps":["**第一段（\\(0\\text{–}40\\text{ mL}\\)，中和 \\(\\mathrm{H^+}\\)）**：发生 \\(\\mathrm{H^+ + OH^- \\to H_2O}\\)，故 \\(n(\\mathrm{HCl}) = 1.0 \\times 0.040 = 0.040\\text{ mol}\\)，所以 \\(c(\\mathrm{HCl}) = \\frac{0.040}{0.100} = 0.40\\text{ mol\\,L}^{-1}\\)。","**第二段（\\(40\\text{–}160\\text{ mL}\\)，沉淀 \\(\\mathrm{Al^{3+}}\\)）**：此段消耗 \\(\\mathrm{NaOH}\\) 体积为 \\(160 - 40 = 120\\text{ mL}\\)（即 \\(0.120\\text{ mol }\\mathrm{OH^-}\\)）。由 \\(\\mathrm{Al^{3+} + 3OH^- \\to Al(OH)_3\\downarrow}\\) 得 \\(n(\\mathrm{AlCl_3}) = \\frac{0.120}{3} = 0.040\\text{ mol}\\)，故 \\(c(\\mathrm{AlCl_3}) = \\frac{0.040}{0.100} = 0.40\\text{ mol\\,L}^{-1}\\)（最大沉淀量 \\(n_{\\max} = 0.040\\text{ mol}\\)）。","**第三段（溶解沉淀至消失）**：由 \\(3:1\\) 规律，溶解 \\(0.040\\text{ mol }\\mathrm{Al(OH)_3}\\) 需再消耗 \\(0.040\\text{ mol NaOH}\\)（体积 \\(40\\text{ mL}\\)），故 \\(V_{\\text{终}} = 160 + 40 = 200\\text{ mL}\\)。","**求最大沉淀一半（\\(0.020\\text{ mol}\\)）时的双解体积**：","- 情况 ①（沉淀上升段）：中和完 \\(40\\text{ mL}\\) 后生成 \\(0.020\\text{ mol}\\) 沉淀需 \\(0.060\\text{ mol }\\mathrm{OH^-}\\)（\\(60\\text{ mL}\\)），总体积 \\(= 40 + 60 = 100\\text{ mL}\\)；","- 情况 ②（沉淀溶解下降段）：达 \\(160\\text{ mL}\\) 最大沉淀后溶解掉 \\(0.020\\text{ mol}\\) 需 \\(0.020\\text{ mol }\\mathrm{OH^-}\\)（\\(20\\text{ mL}\\)），总体积 \\(= 160 + 20 = 180\\text{ mL}\\)。"],"answer":"(1) c(HCl) = 0.40 mol·L⁻¹，c(AlCl₃) = 0.40 mol·L⁻¹；(2) V_终 = 200 mL；达到最大沉淀一半时耗 NaOH 体积为 **100 mL 或 180 mL**。","markingPoints":["正确分出 0–40 mL 对应 HCl 算出 0.40 mol/L（1分）","利用 40–160 mL 差值 120 mL 算出 AlCl₃ 0.40 mol/L（2分）","用 3:1 求得 V_终 = 200 mL（1分）","完整写出 100 mL 与 180 mL 两个解（2分）"],"verification":"验证 200 mL：0.040 mol H⁺(40 mL) + 0.040 mol Al³⁺ 转 AlO₂⁻ 共耗 4×0.040=0.160 mol (160 mL)，40+160=200 mL，零误差！","pitfall":"算第二段体积时误把 160 mL 直接除以 3 而忘记减去前面消耗在 HCl 上的 40 mL。"}],"practice":[{"id":"chem11-11.2-q1","tier":"L1","tierLabel":"L1 基础","examStyle":"P1 选择","q":"要使氯化铝（\\(\\mathrm{AlCl_3}\\)）溶液中的 \\(\\mathrm{Al^{3+}}\\) 完全转化为氢氧化铝沉淀且避免过量溶解，最理想的试剂是（　）。（p.263 思考题 11c-1）","options":["A. 稀盐酸","B. 氢氧化钠溶液","C. 氨水","D. 硝酸银溶液"],"correctOption":"C","given":"p.263 思考题 11c-1 原题","method":"利用 Al(OH)₃ 溶于强碱而不溶于弱碱氨水的特性","principle":"Al³⁺ + 3NH₃·H₂O → Al(OH)₃↓ + 3NH₄⁺，过量氨水不溶解 Al(OH)₃。","steps":["A 不反应；B 过量会溶解沉淀生成 NaAlO₂；D 只沉淀 Cl⁻ 为 AgCl；C 氨水安全彻底。"],"ans":"C","markingPoints":["牢记制备 Al(OH)₃ 实验室必选氨水"],"verification":"化上 p.260 与 p.263 思考题 11c-1。","pitfall":"误以为强碱 NaOH 沉淀更彻底而忽略其过量会溶解沉淀。"},{"id":"chem11-11.2-q2","tier":"L2","tierLabel":"L2 期末","examStyle":"P1 选择","q":"下列关于氧化铝（\\(\\mathrm{Al_2O_3}\\)）与氢氧化铝（\\(\\mathrm{Al(OH)_3}\\)）的叙述中，**正确**的是（　）。（p.265 第 7 题改编）","options":["A. 氧化铝是典型的两性氧化物，可直接与氨水反应生成偏铝酸盐","B. 氢氧化铝受热易分解吸收大量热量，可用作无公害阻燃剂和医用胃酸中和剂","C. 氧化铝与水反应可以直接制得氢氧化铝","D. 氢氧化铝因为受热分解才被称为两性氢氧化物"],"correctOption":"B","given":"p.259–260 性质与用途 & p.265 第 7 题","method":"逐项排查弱碱溶解性、水合能力及两性定义","principle":"Al(OH)₃ 碱性温和可中和胃酸，受热吸热分解 2Al(OH)₃ → Al₂O₃ + 3H₂O 作阻燃剂。","steps":["A 错，Al₂O₃ 不溶于氨水；C 错，Al₂O₃ 难溶于水不直接水合；D 错，两性是指既能与酸反应又能与强碱反应生成盐和水；B 完全正确。"],"ans":"B","markingPoints":["掌握 Al(OH)₃ 胃药、阻燃剂用途与两性真实定义"],"verification":"化上 p.260 原文明确指出其“被誉为无公害阻燃剂”和“医用胃酸中和剂”。","pitfall":"误以为强碱与弱碱都能溶解两性化合物而误选 A。"},{"id":"chem11-11.2-q3","tier":"L3","tierLabel":"L3 预试","examStyle":"P2 简答","q":"(1) 明矾的化学式为 \\(\\mathrm{KAl(SO_4)_2\\cdot 12H_2O}\\)，请简述其净水原理并写出关键离子方程式；(2) 如何通过实验方案证明明矾水溶液中确实含有 \\(\\mathrm{Al^{3+}}\\)？（p.266 作答题 6）","given":"p.261 明矾净水机制 & p.266 习题 6","method":"电离 + 水解生胶体解释净水；用“逐滴加 NaOH 至过量（先白沉淀后溶解）”检验 Al³⁺","principle":"Al³⁺ + 3H₂O ⇌ Al(OH)₃(胶体) + 3H⁺；Al³⁺ + 3OH⁻ → Al(OH)₃↓，Al(OH)₃ + OH⁻ → Al(OH)₄⁻。","steps":["(1) 明矾溶于水完全电离出 \\(\\mathrm{Al^{3+}}\\)，\\(\\mathrm{Al^{3+}}\\) 水解生成表面积大、吸附性强的氢氧化铝胶体：\\(\\mathrm{Al^{3+}(aq) + 3H_2O(l) \\rightleftharpoons Al(OH)_3(\\text{胶体}) + 3H^+(aq)}\\)，胶体能凝聚并吸附水中悬浮杂质沉降澄清，达到净水目的。","(2) **检验 \\(\\mathrm{Al^{3+}}\\) 实验方案**：取少量明矾晶体溶于蒸馏水配成无色溶液，向其中**逐滴加入 \\(\\mathrm{NaOH}\\) 溶液直至过量**，观察现象：开始立即产生**白色胶状沉淀**，继续滴加过量 \\(\\mathrm{NaOH}\\) 溶液并振荡，**白色沉淀完全溶解**（变回澄清溶液），即可证明溶液中含有 \\(\\mathrm{Al^{3+}}\\)（也可向此澄清液再通入过量 \\(\\mathrm{CO_2}\\) 复现白色沉淀进一步确认）。"],"ans":"(1) Al³⁺ 水解生成 Al(OH)₃ 胶体吸附悬浮颗粒沉降；(2) 逐滴加 NaOH 溶液至过量，出现“先生成白色胶状沉淀，后沉淀完全溶解”现象即可证明含 Al³⁺。","markingPoints":["写出 Al³⁺ 水解离子式及“Al(OH)₃ 胶体吸附悬浮杂质沉降”（2分）","设计加 NaOH 至过量“先沉淀后溶解”特征鉴别现象（2分）"],"verification":"与 Mg²⁺（过量 NaOH 不溶）形成唯一区分，完美回答教材 p.266 第 6 题。","pitfall":"检验 \\(\\mathrm{Al^{3+}}\\) 时若写“滴加氨水产生白色沉淀”，会因为 \\(\\mathrm{Mg^{2+}}\\)、\\(\\mathrm{Zn^{2+}}\\) 等也产白沉淀而无法单独确证 \\(\\mathrm{Al^{3+}}\\)！"},{"id":"chem11-11.2-q4","tier":"L4","tierLabel":"L4 统考压轴","examStyle":"P2 图像计算","q":"向 \\(50.0\\text{ mL}\\) 某浓度的 \\(\\mathrm{NaAlO_2}\\)（即 \\(\\mathrm{NaAl(OH)_4}\\)）溶液中缓慢通入 \\(\\mathrm{CO_2}\\) 气体或改用逐滴加入 \\(2.0\\text{ mol\\,L}^{-1}\\) 稀盐酸。(1) 若向其中逐滴加入 \\(2.0\\text{ mol\\,L}^{-1}\\) 稀盐酸至 \\(50.0\\text{ mL}\\) 时刚好使溶液里的偏铝酸根全部转化为沉淀（恰好达到沉淀最大值），求原 \\(\\mathrm{NaAlO_2}\\) 溶液的物质的量浓度；(2) 继续滴加上述稀盐酸使沉淀完全溶解，共需消耗该稀盐酸总体积多少毫升？(3) 若另取等体积 \\(50.0\\text{ mL}\\) 原 \\(\\mathrm{NaAlO_2}\\) 溶液改通入足量（过量）\\(\\mathrm{CO_2}\\)，最终能获得多少克干燥 \\(\\mathrm{Al(OH)_3}\\) 沉淀？（\\(M(\\mathrm{Al(OH)_3}) = 78\\text{ g\\,mol}^{-1}\\)）","given":"V(NaAlO₂)=50.0 mL, c(HCl)=2.0 mol/L; 达最大沉淀耗 V₁(HCl)=50.0 mL","method":"紧扣图 11-1B 中 AlO₂⁻ 加 HCl 沉淀与溶解耗酸比 1 : 3 及过量 CO₂ 不溶沉淀规律","principle":"AlO₂⁻ + H⁺ + H₂O → Al(OH)₃↓；Al(OH)₃ + 3H⁺ → Al³⁺ + 3H₂O；AlO₂⁻ + CO₂ + 2H₂O → Al(OH)₃↓ + HCO₃⁻。","steps":["第(1)问：达最大沉淀时发生 \\(\\mathrm{AlO_2^- + H^+ + H_2O \\to Al(OH)_3\\downarrow}\\)，消耗 \\(n(\\mathrm{HCl}) = 2.0 \\times 0.0500 = 0.100\\text{ mol}\\)，故 \\(n(\\mathrm{NaAlO_2}) = 0.100\\text{ mol}\\)。","原浓度 \\(c(\\mathrm{NaAlO_2}) = \\frac{0.100}{0.0500} = 2.0\\text{ mol\\,L}^{-1}\\)。","第(2)问：由定量曲线 1 : 3 关系，溶解这 \\(0.100\\text{ mol }\\mathrm{Al(OH)_3}\\) 需再消耗 \\(3 \\times 0.100 = 0.300\\text{ mol HCl}\\)（体积 \\(3 \\times 50.0 = 150.0\\text{ mL}\\)），故沉淀完全溶解共耗稀盐酸总体积 \\(= 50.0 + 150.0 = 200.0\\text{ mL}\\)。","第(3)问：通入足量 \\(\\mathrm{CO_2}\\) 生成 \\(\\mathrm{Al(OH)_3}\\) 且过量 \\(\\mathrm{CO_2}\\) 不溶解沉淀，故最终获 \\(0.100\\text{ mol }\\mathrm{Al(OH)_3}\\)，质量 \\(= 0.100 \\times 78 = 7.80\\text{ g}\\)。"],"ans":"(1) 2.0 mol·L⁻¹；(2) 200.0 mL；(3) 7.80 g。","markingPoints":["利用 1:1 关系求出 c(NaAlO₂) = 2.0 mol/L（2分）","利用 1:3 比例求得全溶总体积 200.0 mL（2分）","判断足量 CO₂ 不溶解 Al(OH)₃ 并算出 7.80 g（1分）"],"verification":"总反应 \\(\\mathrm{AlO_2^- + 4H^+ \\to Al^{3+} + 2H_2O}\\) 耗酸为沉淀段的 4 倍：\\(4 \\times 50.0 = 200.0\\text{ mL}\\)，完全吻合！","pitfall":"第(2)问只算溶解段 150 mL 而漏加沉淀段 50 mL，或第(3)问误以为过量 CO₂ 也能把 Al(OH)₃ 溶掉。"}],"cheatSheet":["两性定义：\\(\\mathrm{Al_2O_3}\\) 与 \\(\\mathrm{Al(OH)_3}\\) 均溶于**强酸**和**强碱**，但**不溶于氨水和碳酸**。","沉淀曲线核心比：\\(\\mathrm{Al^{3+}}\\) 滴 \\(\\mathrm{NaOH}\\) 沉淀与溶解耗碱比 **3 : 1**；\\(\\mathrm{AlO_2^-}\\) 滴 \\(\\mathrm{HCl}\\) 沉淀与溶解耗酸比 **1 : 3**。","制备最优试剂：由 \\(\\mathrm{Al^{3+}}\\) 制 \\(\\mathrm{Al(OH)_3}\\) 用**氨水**；由 \\(\\mathrm{AlO_2^-}\\) 制 \\(\\mathrm{Al(OH)_3}\\) 通 **\\(\\mathrm{CO_2}\\)**。","明矾 \\(\\mathrm{KAl(SO_4)_2\\cdot 12H_2O}\\) 为复盐，净水靠 \\(\\mathrm{Al^{3+}}\\) 水解生 \\(\\mathrm{Al(OH)_3}\\) 胶体吸附聚沉（不能杀菌）。"],"kbEntryIds":["kb-chem11-amphoteric","kb-chem11-alum"],"diagrams":[{"src":"assets/fig/v2/chem11-al-amphoteric.svg","caption":"图 11-1 铝盐加碱与偏铝酸盐加酸的氢氧化铝定量沉淀曲线","alt":"1 mol Al3+ 加 NaOH/氨水 与 1 mol AlO2- 加 HCl/CO2 沉淀曲线对比图","pageRef":"化上 p.259–263"}],"quiz":{"q":"向 \\(0.10\\text{ mol }\\mathrm{AlCl_3}\\) 溶液中加入一定量 \\(\\mathrm{NaOH}\\) 溶液，充分反应后过滤干燥得 \\(3.9\\text{ g}\\ \\mathrm{Al(OH)_3}\\) 沉淀（\\(M = 78\\text{ g\\,mol}^{-1}\\)），求所加 \\(\\mathrm{NaOH}\\) 物质的量的所有可能值。","given":"n(Al³⁺)=0.10 mol, n(沉淀)=3.9/78=0.050 mol (< 0.10 mol)","method":"沉淀量未达最大值必有碱不足与碱过量溶解两解","principle":"Al³⁺ + 3OH⁻ → Al(OH)₃↓；Al(OH)₃ + OH⁻ → AlO₂⁻ + 2H₂O。","steps":["情况①（NaOH 不足）：仅部分沉淀，\\(n(\\mathrm{NaOH}) = 3 \\times 0.050 = 0.15\\text{ mol}\\)。","情况②（NaOH 过量）：先耗 \\(0.30\\text{ mol}\\) 全沉淀得 \\(0.10\\text{ mol}\\)，再溶掉 \\(0.050\\text{ mol}\\) 需再耗 \\(0.050\\text{ mol}\\)，总耗 \\(0.30 + 0.050 = 0.35\\text{ mol}\\)。"],"ans":"\\(0.15\\text{ mol}\\) 或 \\(0.35\\text{ mol}\\)"}},{"id":"11.3","t":"铝的冶炼","anchor":{"pages":"化上 p.262–263","syllabus":"3.4.4 铝土矿提纯工艺流程及电解熔融氧化铝炼铝（冰晶石助熔剂）","examScopes":["sem2_final","uec"],"examWeight":"P1 冰晶石作用与熔盐电解原料 + P2 铝土矿流程图方程式与框图推断","terms":"Hall-Héroult process · Cryolite (Na₃AlF₆) · Flux · Bauxite purification","prerequisites":["氧化铝与氢氧化铝的两性及热分解（11.2）","活泼金属冶炼通用原理（热还原 vs 电解法）"],"goals":["解释为什么工业采用电解熔融氧化铝法而非热还原法炼铝，并说明 19 世纪前铝比金贵的历史原因。","写出图 11-8 铝土矿提纯为高纯 Al₂O₃ 的全部四步化学方程式（溶解、CO₂ 酸化、灼烧、电解）。","准确表述冰晶石（Na₃AlF₆）在霍尔—埃鲁电解法中作助熔剂降低熔融温度（2054 ℃ → ~1000 ℃）的原理，并辨析不能电解 AlCl₃ 的原因。"]},"concepts":[{"kind":"mechanism","title":"铝的冶炼史与霍尔—埃鲁电解法（冰晶石 Na₃AlF₆ 的关键作用）","pageRef":"化上 p.262、p.264–265","body":["**历史与原理（p.262）**：铝元素丰度虽高，但因性质极活泼、\\(\\mathrm{Al^{3+}}\\) 很难被一般还原剂还原，19 世纪以前人们只能用昂贵的金属钠还原氯化铝或氧化铝制铝，导致当时铝比钠、比黄金还贵！","**现代电解冶炼铝（霍尔—埃鲁法）**：先从铝土矿提取纯净的氧化铝（\\(\\mathrm{Al_2O_3}\\)），再用熔化的**冰晶石（cryolite，\\(\\mathrm{Na_3AlF_6}\\)）作助熔剂**，使熔点高达 **2054 ℃** 的 \\(\\mathrm{Al_2O_3}\\) 在 **1000 ℃ 左右**溶解在液态冰晶石中成为熔融体，随后通直流电电解：\\(2\\mathrm{Al_2O_3(l)} \\xrightarrow{\\text{电解 / 冰晶石}} 4\\mathrm{Al(l) + 3O_2(g)}\\uparrow\\)（实际使用石墨作阳极，阳极放出的 \\(\\mathrm{O_2}\\) 会在高温下腐蚀石墨电极产生 \\(\\mathrm{CO/CO_2}\\)，故需定期更换阳极炭块）。","**两个统考核心辨析**：①**冰晶石的作用是“助熔剂”**（降低氧化铝的熔融/溶解温度、节约大量电能），**绝不是催化剂**（p.264 练习 3）；②**为什么不电解熔融 \\(\\mathrm{AlCl_3}\\)？**因 \\(\\mathrm{AlCl_3}\\) 虽熔点很低（190 ℃），但它属于**共价分子晶体**，熔融状态下不电离出自由离子、**不导电**，无法电解；而 \\(\\mathrm{Al_2O_3}\\) 为离子晶体，熔融后导电。"],"takeaway":"冰晶石（Na₃AlF₆）= 助熔剂（2054 ℃ → ~1000 ℃）；不电解 AlCl₃ 是因为共价化合物熔融不导电！"},{"kind":"experiment","title":"图 11-8 铝土矿制纯氧化铝与炼铝工艺流程全解析","pageRef":"化上 p.262–263、p.266","body":["教材图 11-8 展示了以含 \\(\\mathrm{Al_2O_3}\\)（及少量 \\(\\mathrm{Fe_2O_3}\\) 等杂质）的铝土矿冶炼铝的完整工业链：","- ① **溶解（碱溶）**：加入过量 \\(\\mathrm{NaOH}\\) 溶液，两性 \\(\\mathrm{Al_2O_3}\\) 溶解为 \\(\\mathrm{NaAlO_2}\\)，而碱性氧化物 \\(\\mathrm{Fe_2O_3}\\) 不溶：\\(\\mathrm{Al_2O_3(s) + 2NaOH(aq) \\longrightarrow 2NaAlO_2(aq) + H_2O(l)}\\)。","- ② **过滤（除残渣）**：滤去不溶的红棕色 \\(\\mathrm{Fe_2O_3}\\) 等残渣（俗称赤泥）。","- ③ **酸化（通入足量 \\(\\mathrm{CO_2}\\)）**：\\(\\mathrm{NaAlO_2(aq) + CO_2(g) + 2H_2O(l) \\longrightarrow Al(OH)_3(s)\\downarrow + NaHCO_3(aq)}\\)（过滤得滤渣 \\(\\mathrm{Al(OH)_3}\\)，滤液含可回收利用的 \\(\\mathrm{NaHCO_3}\\)）。","- ④ **灼烧（脱水）**：\\(2\\mathrm{Al(OH)_3(s)} \\xrightarrow{\\Delta} \\mathrm{Al_2O_3(s) + 3H_2O(l)}\\)。","- ⑤ **熔盐电解**：加入冰晶石，在 ~1000 ℃ 下电解熔融 \\(\\mathrm{Al_2O_3}\\) 得液态铝：\\(2\\mathrm{Al_2O_3(l)} \\xrightarrow{\\text{电解}} 4\\mathrm{Al(l) + 3O_2(g)}\\uparrow\\)。"],"takeaway":"记住图 11-8 六步环节：“铝土矿 + NaOH → 过滤(弃残渣) → +CO₂ 酸化 → 过滤(弃 NaHCO₃ 滤液) → 灼烧(得 Al₂O₃) → 电解(得 Al)”。"},{"kind":"table","title":"常见活泼金属工业冶炼方法对比总结（Ch 9–11 串联）","pageRef":"化上 p.222, p.237, p.250, p.262","body":["结合第 9、10、11 章三种主族金属的工业冶炼方法，精准区分电解原料的物理化学原因："],"table":{"headers":["目标金属","工业冶炼原料与方法","助熔剂 / 关键工艺条件","不选其它化合物的原因"],"rows":[["钠（Na）","电解熔融 \\(\\mathrm{NaCl}\\)","无水熔融，常加少量 \\(\\mathrm{CaCl_2}\\) 降熔点","电解食盐水溶液只能生成 \\(\\mathrm{NaOH}\\) 与 \\(\\mathrm{H_2}\\)"],["钾（K）","高温 Na 置换熔融 \\(\\mathrm{KCl}\\)","真空蒸馏（K 沸点 774 ℃ < Na 882.9 ℃）","电解熔融 KOH 危险且 K 易溶于熔盐"],["镁（Mg）","电解熔融 \\(\\mathrm{MgCl_2}\\)","从苦卤提取，HCl 气流防脱水时水解","不用 \\(\\mathrm{MgO}\\) 因 \\(\\mathrm{MgO}\\) 熔点高达 2852 ℃ 能耗极高"],["铝（Al）","电解熔融 \\(\\mathrm{Al_2O_3}\\)","冰晶石 \\(\\mathrm{Na_3AlF_6}\\) 助熔（2054 ℃ → ~1000 ℃）","不用 \\(\\mathrm{AlCl_3}\\) 因 \\(\\mathrm{AlCl_3}\\) 为共价分子晶体熔融不导电"]]},"takeaway":"这是 UEC 无机选择题经典对比组：炼 Mg 用氯化物（避 MgO 高熔点），炼 Al 用氧化物+冰晶石（避 AlCl₃ 不导电）！"}],"formulas":[{"title":"铝土矿提纯核心两步化学方程式","tex":"\\mathrm{Al_2O_3(s)} + 2\\mathrm{NaOH(aq)} \\longrightarrow 2\\mathrm{NaAlO_2(aq)} + \\mathrm{H_2O(l)},\\qquad \\mathrm{NaAlO_2(aq)} + \\mathrm{CO_2(g)} + 2\\mathrm{H_2O(l)} \\longrightarrow \\mathrm{Al(OH)_3(s)}\\downarrow + \\mathrm{NaHCO_3(aq)}","plain":"Al2O3 + 2NaOH → 2NaAlO2 + H2O; NaAlO2 + CO2 + 2H2O → Al(OH)3↓ + NaHCO3","conditions":"通入足量 CO₂ 保证偏铝酸钠完全转化为 Al(OH)₃ 沉淀且不过度溶解","pageRef":"化上 p.259、p.263","note":"铝土矿中若含 SiO₂ 杂质也会微溶进入 Na₂SiO₃，工业拜耳法利用高压控温沉淀分离。"},{"title":"灼烧脱水与熔盐电解炼铝方程式","tex":"2\\mathrm{Al(OH)_3(s)} \\xrightarrow{\\Delta} \\mathrm{Al_2O_3(s)} + 3\\mathrm{H_2O(l)},\\qquad 2\\mathrm{Al_2O_3(l)} \\xrightarrow{\\text{电解（冰晶石）}} 4\\mathrm{Al(l)} + 3\\mathrm{O_2(g)}\\uparrow","plain":"2Al(OH)3 —(△)→ Al2O3 + 3H2O; 2Al2O3(l) —(电解/冰晶石)→ 4Al(l) + 3O2↑","conditions":"熔融温度约 1000 ℃；阳极产物 O₂，阴极产物液态 Al","pageRef":"化上 p.260、p.262","note":"生成 4 mol Al 转移 12 mol 电子，即每冶炼 1 mol Al（27 g）需转移 3 mol 电子。"}],"pitfalls":[{"title":"把冰晶石错当成催化电解反应的催化剂","wrong":"“电解氧化铝制铝时加入冰晶石，是因为冰晶石作催化剂加快了氧化铝的分解速率。”","diagnosis":"混淆了物理助熔剂与化学催化剂概念（p.264 教材练习 3）。","right":"冰晶石（\\(\\mathrm{Na_3AlF_6}\\)）是**助熔剂**，作用是溶解 \\(\\mathrm{Al_2O_3}\\) 并显著降低体系熔融温度（从 2054 ℃ 降至 ~1000 ℃），从而减少能耗、保护电解槽。","checkRule":"问“冰晶石的作用”选“助熔剂/降低熔点”，绝对不选“催化剂”或“还原剂”。"},{"title":"误以为炼铝也可像炼镁一样电解熔融氯化铝","wrong":"“\\(\\mathrm{AlCl_3}\\) 熔点仅 190 ℃ 比 \\(\\mathrm{Al_2O_3}\\) 低得多，工业上直接电解熔融 \\(\\mathrm{AlCl_3}\\) 岂不更省电？”","diagnosis":"只看熔点高低，忽视了物质晶体类型与熔融导电性！","right":"\\(\\mathrm{AlCl_3}\\) 属于共价化合物（分子晶体），熔融态下以分子形式存在，几乎没有自由移动的离子，**不导电**；故只能电解离子晶体熔融的 \\(\\mathrm{Al_2O_3}\\)。","checkRule":"炼镁用 \\(\\mathrm{MgCl_2}\\)（离子晶体），炼铝用 \\(\\mathrm{Al_2O_3}\\)（离子晶体）+ 冰晶石。"}],"examples":[{"label":"例 11.3.1","tier":"L3","tierLabel":"L3 框图推断","title":"教材 p.266 铝及其重要化合物五元转化框图（A–E）推断","prompt":"（教材 p.266 作答题 5）已知 A、B、C、D、E 五种物质中均含有同一种常见金属元素，它们的转化关系如下：\\(\\mathrm{A} \\xrightarrow{\\Delta} \\mathrm{B} + \\mathrm{H_2O}\\)；B 为白色难溶固体，E 易溶于水；B 在熔融状态下电解生成单质 C；A、B、C 分别与稀盐酸反应均生成 D，分别与 \\(\\mathrm{NaOH}\\) 溶液反应均生成 E；D 与 \\(\\mathrm{NaOH}\\) 反应可生成 E，E 与盐酸反应或加过量试剂也能转化回 D。(1) 写出 A、B、C、D、E 的化学式；(2) 写出 B→C 和 B→D 的化学方程式；(3) 写出 A→D 和 C→D 的离子方程式。","clues":"“熔融电解 B 得金属单质 C，且 A 加热分解得 B（两性氢氧化物脱水得两性氧化物），A、B、C 均能既溶盐酸得 D 又溶 NaOH 得 E”——铁定锁定铝家族！","strategy":"由“两性加热脱水”与“熔融电解”确定 A=\\(\\mathrm{Al(OH)_3}\\)、B=\\(\\mathrm{Al_2O_3}\\)、C=\\(\\mathrm{Al}\\) → 顺推酸溶产物 D=\\(\\mathrm{AlCl_3}\\)、碱溶产物 E=\\(\\mathrm{NaAlO_2}\\)。","given":"B 白色难溶熔融电解得 C；A 加热得 B；A/B/C 皆溶 HCl 得 D、溶 NaOH 得 E","principle":"Al、Al₂O₃、Al(OH)₃ 均具备既溶于强酸得 Al³⁺ 又溶于强碱得 AlO₂⁻ 的特征转化关系。","steps":["第(1)问推断结果：\\(\\mathrm{A}: \\mathrm{Al(OH)_3}\\)，\\(\\mathrm{B}: \\mathrm{Al_2O_3}\\)，\\(\\mathrm{C}: \\mathrm{Al}\\)，\\(\\mathrm{D}: \\mathrm{AlCl_3}\\)，\\(\\mathrm{E}: \\mathrm{NaAlO_2}\\)（或 \\(\\mathrm{Na[Al(OH)_4]}\\)）。","第(2)问化学方程式：","- \\(\\mathrm{B \\to C}\\): \\(2\\mathrm{Al_2O_3(l)} \\xrightarrow{\\text{电解（冰晶石）}} 4\\mathrm{Al(l)} + 3\\mathrm{O_2(g)}\\uparrow\\)","- \\(\\mathrm{B \\to D}\\): \\(\\mathrm{Al_2O_3(s)} + 6\\mathrm{HCl(aq)} \\longrightarrow 2\\mathrm{AlCl_3(aq)} + 3\\mathrm{H_2O(l)}\\)","第(3)问离子方程式：","- \\(\\mathrm{A \\to D}\\): \\(\\mathrm{Al(OH)_3(s)} + 3\\mathrm{H^+(aq)} \\longrightarrow \\mathrm{Al^{3+}(aq)} + 3\\mathrm{H_2O(l)}\\)","- \\(\\mathrm{C \\to D}\\): \\(2\\mathrm{Al(s)} + 6\\mathrm{H^+(aq)} \\longrightarrow 2\\mathrm{Al^{3+}(aq)} + 3\\mathrm{H_2(g)}\\uparrow\\)"],"answer":"(1) A: Al(OH)₃, B: Al₂O₃, C: Al, D: AlCl₃, E: NaAlO₂；(2)(3) 方程式见上。","markingPoints":["正确推断出 A–E 五种物质化学式（2分）","正确写出 B→C（注冰晶石与条件）及 B→D 化学方程式（2分）","正确写出 A→D 与 C→D 离子方程式（2分）"],"verification":"对照化上 p.266 习题 5 转换框图逐条箭头的试剂与产物检验完全自洽。","pitfall":"在写 B→C 电解方程式时忘记加冰晶石助熔条件，或者在写 C→D 离子方程式时忘配平电荷（左 +6、右 +6）或漏写氢气。"},{"label":"例 11.3.2","tier":"L4","tierLabel":"L4 统考压轴","title":"铝土矿提纯炼铝工业产率与原料消耗计算","prompt":"某铝厂以含 \\(\\mathrm{Al_2O_3}\\) 质量分数为 \\(51.0\\%\\) 的铝土矿为原料（其余杂质均不与 \\(\\mathrm{NaOH}\\) 溶液反应），采用图 11-8 工艺流程生产纯铝：碱溶 → 过滤 → 通足量 \\(\\mathrm{CO_2}\\) 酸化 → 过滤 → 灼烧 → 电解。已知生产 \\(1.00\\text{ t}\\) 该铝土矿理论上需要处理：(1) 若铝元素完全转化且电解无损失，可冶炼出纯铝多少吨（保留三位有效数字）？(2) 在“通入足量 \\(\\mathrm{CO_2}\\) 酸化”环节理论上至少需要通入多少立方米（标准状况）\\(\\mathrm{CO_2}\\) 气体？(3) 实际工业电解中，由于阳极炭块不断被产生的 \\(\\mathrm{O_2}\\) 氧化消耗生成 \\(\\mathrm{CO_2}\\)，若电解产生的 \\(\\mathrm{O_2}\\) 全部与石墨阳极反应转化为 \\(\\mathrm{CO_2}\\)，理论上每产 \\(1\\text{ t}\\) 铝需消耗多少吨纯碳阳极？（\\(A_r: \\mathrm{Al}=27, \\mathrm{O}=16, \\mathrm{C}=12\\)）","clues":"利用铝元素质量守恒一步算出铝产量；由 \\(\\mathrm{NaAlO_2 + CO_2 + 2H_2O \\to Al(OH)_3\\downarrow + NaHCO_3}\\) 知 **\\(1\\text{ mol Al} \\sim 1\\text{ mol }\\mathrm{CO_2}\\)**！","strategy":"吨先换算千克/克算摩尔（或直接按 kmol 计算：\\(1\\text{ t} = 10^6\\text{ g}\\)，\\(1\\text{ kmol} \\times 22.4\\text{ m}^3/\\text{kmol}\\)）！","given":"m(矿)=1.00 t, w(Al₂O₃)=51.0%, M(Al₂O₃)=102 g/mol","principle":"元素原子守恒及总计量比：Al₂O₃ ~ 2Al ~ 2CO₂（酸化）；2Al₂O₃ → 4Al + 3O₂, 3O₂ + 3C → 3CO₂。","steps":["第(1)问：\\(1.00\\text{ t}\\) 矿石含 \\(m(\\mathrm{Al_2O_3}) = 1.00 \\times 51.0\\% = 0.510\\text{ t} = 5.10 \\times 10^5\\text{ g}\\)，即 \\(n(\\mathrm{Al_2O_3}) = \\frac{5.10 \\times 10^5}{102} = 5.00 \\times 10^3\\text{ mol} = 5.00\\text{ kmol}\\)。","由铝原子守恒，可产纯铝 \\(n(\\mathrm{Al}) = 2 \\times 5.00 = 10.0\\text{ kmol}\\)，质量 \\(m(\\mathrm{Al}) = 10.0\\text{ kmol} \\times 27\\text{ kg/kmol} = 270\\text{ kg} = 0.270\\text{ t}\\)。","第(2)问：由 \\(\\mathrm{Al_2O_3 \\sim 2NaAlO_2 \\sim 2CO_2}\\)（足量酸化生成 \\(\\mathrm{NaHCO_3}\\)），故需 \\(n(\\mathrm{CO_2}) = n(\\mathrm{Al}) = 10.0\\text{ kmol} = 1.00 \\times 10^4\\text{ mol}\\)。","标况下需 \\(\\mathrm{CO_2}\\) 体积 \\(V = 1.00 \\times 10^4 \\times 22.4\\text{ L} = 2.24 \\times 10^5\\text{ L} = 224\\text{ m}^3\\)（注意若未写足量也可以写最小通入生成 Na₂CO₃ 减半，但图 11-8 明确写明产物为 NaHCO₃，故 1:1 最标准！）。","第(3)问：由 \\(2\\mathrm{Al_2O_3} \\to 4\\mathrm{Al} + 3\\mathrm{O_2}\\uparrow\\) 及 \\(\\mathrm{C + O_2 \\to CO_2}\\)，合并得计量关系 \\(4\\mathrm{Al} \\sim 3\\mathrm{O_2} \\sim 3\\mathrm{C}\\)。","故每生产 \\(1\\text{ t Al}\\)（\\(1000/27\\text{ kmol}\\)）消耗碳 \\(m(\\mathrm{C}) = \\frac{1.00}{27} \\times \\frac{3}{4} \\times 12 = \\frac{1.00}{3} \\approx 0.333\\text{ t}\\)。"],"answer":"(1) 0.270 t；(2) 224 m³；(3) 0.333 t。","markingPoints":["利用 Al 元素守恒算出纯铝 0.270 t（2分）","依据图 11-8 生成 NaHCO₃ 得 1 mol Al 耗 1 mol CO₂ 算出 224 m³（2分）","建立 4Al ~ 3O₂ ~ 3C 关系算出阳极炭消耗 0.333 t（2分）"],"verification":"kmol 配 m³ 计算：\\(1\\text{ kmol}\\) 标况气体体积恰为 \\(22.4\\text{ m}^3\\)，避免大指数换算出错；\\(4 \\times 27 = 108\\text{ g Al}\\) 对应 \\(3 \\times 12 = 36\\text{ g C}\\)，质量比恰好 3 : 1，所以 1 t Al 耗 1/3 t C，极其精妙！","pitfall":"在第(2)问误把 \\(\\mathrm{CO_2}\\) 系数按 1:2（即 1 mol CO₂ 对应 2 mol NaAlO₂ 生成 Na₂CO₃）来算，忽略了教材图 11-8 明确给出的方程式生成的是 \\(\\mathrm{NaHCO_3}\\)。"}],"practice":[{"id":"chem11-11.3-q1","tier":"L1","tierLabel":"L1 基础","examStyle":"P1 选择","q":"工业上用电解法冶炼金属铝时，需要向氧化铝中加入冰晶石（\\(\\mathrm{Na_3AlF_6}\\)），其主要作用是（　）。（p.264 教材题 3）","options":["A. 助熔剂（降低氧化铝的熔融温度）","B. 催化剂（加快电解反应速率）","C. 还原剂（把氧化铝直接还原为铝）","D. 氧化剂（提供氧元素）"],"correctOption":"A","given":"p.262 冰晶石作用 & p.264 选择题 3","method":"直接记忆霍尔—埃鲁熔盐电解工艺原理","principle":"Al₂O₃ 熔点 2054 ℃，溶解在熔融冰晶石中可在 ~1000 ℃ 电解。","steps":["教材 p.262 原文指出“用熔化的冰晶石作助熔剂，可使氧化铝在 1000 ℃ 左右溶解在液态的冰晶石里”。"],"ans":"A","markingPoints":["明确冰晶石作助熔剂"],"verification":"化上 p.264 选择题 3 原题。","pitfall":"误选 B 把物理降熔点助熔剂当作化学催化剂。"},{"id":"chem11-11.3-q2","tier":"L2","tierLabel":"L2 期末","examStyle":"P1 选择","q":"工业上不用还原剂还原氧化铝，而是采用电解熔融氧化铝的方法冶炼金属铝。关于该工艺的下列叙述，**正确**的是（　）。（p.265 教材题 5 综合）","options":["A. 铝单质的还原性强，较难用普通化学还原剂从氧化铝中还原出铝","B. 工业上直接电解熔融氯化铝会更省电且可行","C. 在铝土矿提纯时，向偏铝酸钠溶液加过量稀盐酸比通二氧化碳更佳","D. 氧化铝中铝元素为 +3 价，故只有还原性没有氧化性"],"correctOption":"A","given":"p.262–265 铝冶炼原理","method":"逐项比对活泼金属冶炼选择、AlCl₃ 导电性及氧化铝酸化试剂","principle":"越活泼金属（K Ca Na Mg Al）越难用热还原法，通常采用熔盐电解；Al³⁺ 处于最高价只有氧化性。","steps":["A 正确（p.265 题 5C）；B 错，熔融 AlCl₃ 不导电；C 错，过量盐酸会溶解 Al(OH)₃ 沉淀；D 错，+3 价最高价只能降价体现氧化性。"],"ans":"A","markingPoints":["理解金属活泼性与冶炼方法对应关系"],"verification":"化上 p.265 选择题 5 原题印证。","pitfall":"误选 B 忽略 AlCl₃ 是共价分子晶体。"},{"id":"chem11-11.3-q3","tier":"L3","tierLabel":"L3 预试","examStyle":"P2 简答","q":"参考教材图 11-8“用铝土矿（主要成分 \\(\\mathrm{Al_2O_3}\\)，含少量不溶碱性氧化物杂质 \\(\\mathrm{Fe_2O_3}\\)）制备金属铝的工艺流程图”：铝土矿 →（加入 \\(\\mathrm{NaOH}\\) 溶液溶解）→ 过滤（得残渣）→（向滤液通入 \\(\\mathrm{CO_2}\\) 酸化）→ 过滤（得滤液与沉淀）→ 灼烧（放出 \\(\\mathrm{H_2O}\\)）→ 电解得铝。请回答：(1) 第一次过滤所得“残渣”的主要成分是什么？(2) 写出“酸化”步骤中发生反应生成沉淀的化学方程式，并说明为什么工业上该步骤选用 \\(\\mathrm{CO_2}\\) 而不用稀硫酸？","given":"图 11-8 工艺流程","method":"根据氧化铝两性与氧化铁碱性筛选分离结果；对比弱酸 CO₂ 与强酸 H₂SO₄ 对 Al(OH)₃ 溶解度影响","principle":"Fe₂O₃ 不溶于 NaOH 留作残渣；CO₂ 过量不溶 Al(OH)₃ 而强酸难控用量会回溶损失。","steps":["(1) 第一次过滤的残渣主要成分是 **\\(\\mathrm{Fe_2O_3}\\)**（碱性氧化物，不与 \\(\\mathrm{NaOH}\\) 溶液反应）。","(2) 酸化步骤方程式：\\(\\mathrm{NaAlO_2(aq) + CO_2(g) + 2H_2O(l) \\longrightarrow Al(OH)_3(s)\\downarrow + NaHCO_3(aq)}\\)。","选用 \\(\\mathrm{CO_2}\\) 的原因：\\(\\mathrm{Al(OH)_3}\\) 具有两性，能溶于强酸（如稀硫酸）却**不溶于碳酸**。若使用稀硫酸，稍过量就会使生成的 \\(\\mathrm{Al(OH)_3}\\) 重新溶解为 \\(\\mathrm{Al_2(SO_4)_3}\\)，用量极难控制；而通入过量 \\(\\mathrm{CO_2}\\) 沉淀不仅不会溶解，还能使 \\(\\mathrm{AlO_2^-}\\) 彻底沉淀（且 \\(\\mathrm{CO_2}\\) 廉价易得）。"],"ans":"(1) Fe₂O₃；(2) NaAlO₂+CO₂+2H₂O→Al(OH)₃↓+NaHCO₃；因 Al(OH)₃ 不溶于过量碳酸而溶于强酸，使用 CO₂ 易控且沉淀完全。","markingPoints":["指出残渣为 Fe₂O₃（1分）","正确写出图 11-8 给定酸化方程式（2分）","从 Al(OH)₃ 溶于强酸不溶于弱酸碳酸说明选择 CO₂ 的原因（2分）"],"verification":"对照化上 p.263 图 11-8 完全一致。","pitfall":"若写酸化生成 Na₂CO₃ 而未按图 11-8 给定“+ NaHCO₃”，在足量 CO₂ 工艺下不够精准。"},{"id":"chem11-11.3-q4","tier":"L4","tierLabel":"L4 统考压轴","examStyle":"P2 电化学计算","q":"某大型电解铝厂电解槽以熔融氧化铝为原料，在冰晶石助熔下进行电解：\\(2\\mathrm{Al_2O_3(l)} \\xrightarrow{\\text{电解}} 4\\mathrm{Al(l)} + 3\\mathrm{O_2(g)}\\uparrow\\)。已知每生产 \\(1\\text{ mol}\\) 铝需要转移 \\(3\\text{ mol}\\) 电子，假设电流效率为 \\(100\\%\\)：(1) 若电解某批高纯氧化铝恰好得到 \\(54.0\\text{ kg}\\) 金属铝，则阴极共通过了多少摩尔电子？同时在标准状况下阳极理论放出氧气多少立方米？(2) 若铝土矿中除了 \\(\\mathrm{Al_2O_3}\\)（\\(68.0\\%\\)）外还含有 \\(12.0\\%\\) 的二氧化硅（\\(\\mathrm{SiO_2}\\)，注意常温下 \\(\\mathrm{SiO_2}\\) 与稀碱反应极慢，但在工业高温高压碱溶时 \\(\\mathrm{SiO_2 + 2NaOH \\to Na_2SiO_3 + H_2O}\\) 也会部分溶解！），请问随后向碱性滤液中通入足量 \\(\\mathrm{CO_2}\\) 时，\\(\\mathrm{Na_2SiO_3}\\) 混入后会带来什么不良杂质沉淀？如何表示该反应？","given":"m(Al)=54.0 kg (2.00 kmol), M(Al)=27 g/mol","method":"利用铝的摩尔数算电子转移与氧气；结合第 12 章硅酸钠吸 CO₂ 析胶知识迁移预测杂质","principle":"Al³⁺ + 3e⁻ → Al；2O²⁻ - 4e⁻ → O₂↑；Na₂SiO₃ + 2CO₂ + 2H₂O → H₂SiO₃↓ + 2NaHCO₃。","steps":["第(1)问：得到金属铝 \\(n(\\mathrm{Al}) = \\frac{54.0 \\times 10^3\\text{ g}}{27\\text{ g/mol}} = 2.00 \\times 10^3\\text{ mol} = 2.00\\text{ kmol}\\)。","转移电子物质的量：\\(n(e^-) = 3 \\times 2.00 \\times 10^3 = 6.00 \\times 10^3\\text{ mol}\\)。","由 \\(4\\mathrm{Al} \\sim 3\\mathrm{O_2}\\) 得生成氧气：\\(n(\\mathrm{O_2}) = \\frac{3}{4} \\times 2.00\\text{ kmol} = 1.50\\text{ kmol}\\)，标况体积 \\(V(\\mathrm{O_2}) = 1.50 \\times 22.4 = 33.6\\text{ m}^3\\)。","第(2)问（跨章衔接第 12 章）：若碱溶滤液混入 \\(\\mathrm{Na_2SiO_3}\\)，通入足量 \\(\\mathrm{CO_2}\\) 时因碳酸酸性强于硅酸，会同时析出白色难溶的**硅酸（\\(\\mathrm{H_2SiO_3}\\)）沉淀**混入 \\(\\mathrm{Al(OH)_3}\\) 中（灼烧后变为 \\(\\mathrm{SiO_2}\\) 污染电解产物铝的纯度）：\\(\\mathrm{Na_2SiO_3(aq) + 2CO_2(g) + 2H_2O(l) \\longrightarrow H_2SiO_3(s)\\downarrow + 2NaHCO_3(aq)}\\)。"],"ans":"(1) 转移电子 6.00×10³ mol，阳极理论产 O₂ 33.6 m³；(2) 会伴随生成不溶的硅酸 H₂SiO₃ 沉淀污染产品，反应式见上。","markingPoints":["正确换算 54.0 kg Al 为 2000 mol 并求得 6.00×10³ mol 电子与 33.6 m³ O₂（3分）","迁移强酸制弱酸原理指出混入 H₂SiO₃ 沉淀杂质并写对反应式（2分）"],"verification":"电子守恒核对：1.50 kmol O₂ × 4 = 6.00 kmol 电子，完美匹配！","pitfall":"算体积时注意单位换算（\\(10^3\\text{ L} = 1\\text{ m}^3\\)），千万不要把 \\(33.6\\text{ m}^3\\) 错写成 \\(33.6\\text{ L}\\)！"}],"cheatSheet":["霍尔—埃鲁炼铝：\\(2\\mathrm{Al_2O_3(l)} \\xrightarrow{\\text{电解 / 冰晶石 }\\mathrm{Na_3AlF_6}} 4\\mathrm{Al(l)} + 3\\mathrm{O_2(g)}\\uparrow\\)。","冰晶石（\\(\\mathrm{Na_3AlF_6}\\)）是**助熔剂**（把 2054 ℃ 降至 ~1000 ℃），不是催化剂；不可电解 \\(\\mathrm{AlCl_3}\\)（熔融不导电）。","铝土矿提纯四步：碱溶（弃 \\(\\mathrm{Fe_2O_3}\\)）→ 通 \\(\\mathrm{CO_2}\\)（生 \\(\\mathrm{Al(OH)_3\\downarrow + NaHCO_3}\\)）→ 灼烧（得 \\(\\mathrm{Al_2O_3}\\)）→ 电解得铝。"],"kbEntryIds":["kb-chem11-smelting"],"quiz":{"q":"工业上冶炼金属镁采用电解熔融 \\(\\mathrm{MgCl_2}\\) 而冶炼金属铝却采用电解熔融 \\(\\mathrm{Al_2O_3}\\)（加冰晶石），分别不选用 \\(\\mathrm{MgO}\\) 和 \\(\\mathrm{AlCl_3}\\) 的原因是什么？","given":"MgO (m.p. 2852 ℃), AlCl₃ (共价分子晶体 m.p. 190 ℃)","method":"从熔点能耗与熔融导电性两个维度精准区分","principle":"熔融电解质既要熔点适中节能，又必须能电离导电。","steps":["不电解 \\(\\mathrm{MgO}\\) 是因为 \\(\\mathrm{MgO}\\) 熔点高达 \\(2852\\ ^\\circ\\mathrm{C}\\)，熔融耗能极大；","不电解 \\(\\mathrm{AlCl_3}\\) 是因为 \\(\\mathrm{AlCl_3}\\) 为共价分子晶体，熔融态不电离、不导电。"],"ans":"MgO 熔点过高（2852 ℃）耗能大；AlCl₃ 为共价化合物，熔融状态下不导电。"}}]},"化学12":{"lessonKey":"化学12","courseCode":"chemistry","subject":"化学","chapter":12,"title":"IVA族元素：碳和硅","syllabus":"3.6 IVA族元素","bookId":"sm1-chemistry-2017","bookCitation":"《马来西亚华文独中教科书 · 化学（上册）》（2017年11月版）第12章 p.267–296","examScopes":["sem2_final","uec"],"chapterOverview":{"summary":"第12章深入周期表核心非金属与半导体主族——IVA 族碳和硅（ns²np²）。碳元素以丰富同素异形体（金刚石、石墨、富勒烯 C₆₀、无定形碳）和 CO/CO₂/碳酸盐/碳化物/气体燃料构成地球生命与能源基石；硅元素（地壳第二丰度 26%）则通过晶体硅半导体、SiO₂ 原子晶体（与 HF 及 NaOH 的特征反应）以及水玻璃、陶瓷、玻璃、水泥三大硅酸盐工业支撑现代信息与材料文明。","conceptTree":[{"branch":"12.1 碳（p.268–274）","items":["12.1.1 IVA 族（C–Fl）ns²np² 递变（非金属性 C > Si，金属性递增）","12.1.2 碳的同素异形体：金刚石（正四面体）、石墨（层状导电润滑）、C₆₀（巴基球）、无定形碳","12.1.3 碳的常温稳定性与高温还原性（CuO、CO₂、水煤气）"]},{"branch":"12.2 碳的重要化合物（p.274–284）","items":["12.2.1 CO（毒理、蓝焰、冶金、甲醇）vs CO₂（干冰、石灰水检验与四朵小花探究）","12.2.2 碳酸盐与碳酸氢盐（表 12-2、溶洞平衡、索尔维氨碱法 vs 侯氏制碱法）","12.2.3 无机碳化物：CaC₂（电石制乙炔）、CS₂、SiC（金刚砂）","12.2.4 含碳气体燃料：天然气、水煤气（CO+H₂）、发生炉煤气（CO+N₂）、石油气"]},{"branch":"12.3 硅和它的重要化合物（p.284–291）","items":["12.3.1 晶体硅（1410 ℃ 半导体）、工业碳还原制粗硅（SiO₂ + 2C → Si + 2CO↑）","12.3.2 SiO₂ 1:2 原子晶体（vs CO₂ 分子晶体）、与 HF/NaOH 反应、光导纤维与水玻璃","12.3.3 硅酸盐工业：普通/精密陶瓷、普通玻璃（纯碱/石灰石/石英）、水泥与混凝土"]}]},"paperFocus":["高三下半年期末考 & UEC 统考：卷一（30% 选择题）常考金刚石/石墨/C₆₀ 结构与物理性质对应、CO₂ 四朵石蕊小花控制变量、不能用玻璃瓶装氢氟酸与玻璃塞装烧碱的原因、SiO₂ 与 CO₂ 晶体类型差异、普通玻璃/水泥/光导纤维原料与成分。","UEC 卷二乙部（无机化学）及探究计算：高频命题点为索尔维/侯氏制碱法“先通 NH₃ 后通 CO₂”原因与流程框图（p.295 第 7 题）、SiO₂→Na₂SiO₃→H₂SiO₃ 酸性对比框图推断（p.296 第 9 题）、制粗硅/金刚砂中氧化剂与还原剂之比（p.296 第 8 题）及玻璃氧化物组成比计算（p.295 第 6 题）。"],"solvingWorkflow":["结构决定物理性质：遇到“导电润滑”选石墨（余 1 自由电子 + 层间范德华力）；遇到“硬度最大不导电”选金刚石（4 个共价键正四面体）；遇到“SiO₂ 与 CO₂ 熔沸点悬殊”立即答“SiO₂ 为原子晶体而 CO₂ 为分子晶体”。","非金属性与酸性比较：由周期律 C > Si 推出最高价含氧酸酸性 H₂CO₃ > H₂SiO₃，再由“强酸制弱酸”判断 Na₂SiO₃ 溶液在空气中吸 CO₂ 生成 H₂SiO₃ 白色浑浊。","氧化剂还原剂比例辨析：工业制粗硅 SiO₂ + 2C → Si + 2CO↑ 中 SiO₂ 是氧化剂、C 是还原剂（1 : 2）；工业制金刚砂 SiO₂ + 3C → SiC + 2CO↑ 中 **SiO₂ 化合价未变**，仅 **C 既作氧化剂（1 mol 降价）又作还原剂（2 mol 升价）**，比例为 1 : 2！","纯碱工艺气体顺序：氨碱法/侯氏法永远是“先通足量 NH₃ 使饱和食盐水呈碱性，再通 CO₂”以大幅提高 HCO₃⁻ 浓度促使 NaHCO₃ 析出。"],"questionTypes":["碳的同素异形体结构模型及纯物质/混合物辨析（p.271 交流分享 & p.293 题 1–3）","CO₂ 溶于水生成酸的四组对比实验控制变量分析（p.284 思考题 12b-3）","索尔维氨碱法与侯氏制碱法流程对比与实验细节（p.280–281 & p.295 第 7 题）","玻璃原料、水泥成分与 SiO₂ 特殊反应（HF 刻蚀玻璃、NaOH 用橡皮塞）","碳还原 SiO₂ 制粗硅与 SiC 电子转移及 SiO₂→Na₂SiO₃→H₂SiO₃ 综合推断（p.296 第 8–9 题）"],"scoringNotes":["解释“为什么金刚石和石墨混合得到的是混合物”时，必须指出“虽然只含碳一种元素，但两者原子排列（晶体结构）不同，属于两种不同物质”（只说元素相同则误判为纯净物）。","写工业制粗硅或金刚砂化学方程式时，产物碳氧化物务必写 **CO** 而非 CO₂（高温下过量炽热碳将 CO₂ 还原为 CO），且注明“高温”和气体箭头。"],"vid":[{"t":"碳的同素异形体结构与晶体类型比较","q":"金刚石 石墨 富勒烯 同素异形体 结构"},{"t":"二氧化硅原子晶体性质与硅酸盐工业","q":"二氧化硅 硅酸钠 玻璃 水泥 高中化学"},{"t":"侯氏制碱法与二氧化碳实验室探究","q":"侯氏制碱法 氨碱法 碳酸钠 高中化学"}],"sections":[{"id":"12.1","t":"碳","anchor":{"pages":"化上 p.268–274","syllabus":"3.6.1–3.6.3 IVA 族元素递变、碳的同素异形体（金刚石/石墨/C₆₀/无定形碳）及碳单质化学性质","examScopes":["sem2_final","uec"],"examWeight":"P1 晶体结构与用途对应 + P2 碳还原金属氧化物/水蒸气方程式","terms":"Carbon family · Allotropism · Diamond · Graphite · Buckminsterfullerene (C₆₀) · Amorphous carbon","prerequisites":["共价键、分子间作用力（范德华力）与原子/分子晶体概念（化上 Ch 7）","元素周期律与主族元素性质递变（化上 Ch 6.3）"],"goals":["总结 IVA 族（C, Si, Ge, Sn, Pb, Fl）ns²np² 的价电子特征及从上到下非金属性减弱、金属性增强的递变规律。","从微观晶体结构解释金刚石、石墨与富勒烯（C₆₀）物理性质差异巨大的本质原因，并区分各类无定形碳的用途。","说明碳单质常温下的化学稳定性（古代字画不变色）与高温下的可燃性及强还原性（还原 CuO、CO₂、水蒸气）。"]},"concepts":[{"kind":"definition","title":"12.1.1 碳族元素（IVA 族）存在形态与递变规律","pageRef":"化上 p.269","body":["**族序与电子排布**：IVA 族包括碳（C）、硅（Si）、锗（Ge）、锡（Sn）、铅（Pb）和人造放射性元素鈇（Fl）。原子最外层均有 **4 个价电子（\\(ns^2np^2\\)）**（C 为 \\(2s^22p^2\\)，Si 为 \\(3s^23p^2\\)），既不易全失 4 个电子也不易得 4 个电子，故通常易形成**共价键**（主要呈 +2、+4 价）。","**自然界存在**：碳占地壳总质量仅 **0.03%**，却分布极广，形成化合物种类居所有元素之首，且是组成生物界有机物的核心（人体含碳量达 \\(23\\text{ mg\\,g}^{-1}\\)）；硅主要以硅酸盐与石英矿存在；锡矿为**锡石矿（\\(\\mathrm{SnO_2}\\)）**，铅主要矿石为**方铅矿（\\(\\mathrm{PbS}\\)）**。","**同主族递变（p.269 问题解决）**：从 C 到 Pb，电子层数递增、原子半径依次增大、得电子能力减弱、失电子能力增强 → **非金属性依次减弱（C > Si > Ge），金属性依次增强（Sn、Pb 为典型金属）**。"],"takeaway":"从上到下，最高价含氧酸酸性减弱（H₂CO₃ > H₂SiO₃），气态氢化物稳定性减弱（CH₄ > SiH₄）。"},{"kind":"table","title":"12.1.2 碳的同素异形体：结构决定性质（金刚石 vs 石墨 vs C₆₀ vs 无定形碳）","pageRef":"化上 p.270–272","body":["**同素异形现象（allotropism）**：由同一种元素形成几种不同单质的现象，这些单质互称**同素异形体（allotrope）**。金刚石、石墨、富勒烯都是碳元素的同素异形体，它们燃烧产物完全相同（均只有 \\(\\mathrm{CO_2}\\)），但因**晶体中碳原子排列方式不同**，物理性质截然不同。","**p.271 交流分享辨析**：将金刚石和石墨混合在一起得到的物质，虽然只含碳一种元素，但包含两种不同结构与性质的物质，因此属于**混合物**！"],"table":{"headers":["单质类型","微观晶体结构特征","关键物理性质","主要用途"],"rows":[["金刚石（图 12-5）","原子晶体；每个 C 与相邻 4 个 C 形成共价键，呈**空间正四面体网状**，无自由电子","无色透明，天然**最硬**，熔点极高，**不导电**","钻探钻头、玻璃刀/磨削工具、高档装饰品"],["石墨（图 12-7）","混合型层状晶体；层内每个 C 与 3 个 C 成共价键成六边形网状，**余 1 个自由移动电子**；层间以弱**范德华力**结合","灰黑色金属光泽，**质软有滑腻感**，熔点高，**良好导电导热性**","润滑剂、电极、轻轨接触点、核反应堆中子减速剂、铅笔芯"],["富勒烯 C₆₀（图 12-9）","分子晶体；60 个 C 组成球形三十二面体（**12 个五边形 + 20 个六边形**），又称巴基球","高稳定性分子固体；与碱金属形成化合物具**超导性**","超导材料、催化剂载体、高能电池、医药"],["无定形碳","由细小**石墨微晶无序排列**而成（非真正非晶态）","多孔、表面积大（经活化后称**活性炭**吸附力极强）","木炭（燃料/火药）、焦炭（炼铁/水煤气）、炭黑（油墨/轮胎耐磨）、活性炭（防毒面具/脱色）、碳纤维（航天/球拍）"]]},"takeaway":"记住 C₆₀ 结构数字：**12 个正五边形 + 20 个正六边形**（共 32 个面，形如足球）。"},{"kind":"mechanism","title":"12.1.3 碳单质的化学性质（常温惰性 vs 高温可燃性与还原性）","pageRef":"化上 p.272–273","body":["**常温稳定性**：在常温下碳的化学性质很稳定，不与空气、水、稀酸、稀碱反应——因此中国古代用墨汁创作的字画（图 12-4）历经千年纸已微腐而墨色依然不变；同理将埋入地下的木桩表面烤焦形成木炭层可防腐（p.273 思考题 12a-2）。","**可燃性（随氧气量变化）**：","- 氧气充足（完全燃烧）：\\(\\mathrm{C(s) + O_2(g)} \\xrightarrow{\\text{点燃}} \\mathrm{CO_2(g)}\\)","- 氧气不足（不完全燃烧）：\\(2\\mathrm{C(s) + O_2(g)} \\xrightarrow{\\text{点燃}} 2\\mathrm{CO(g)}\\)","**高温还原性（三大必考还原反应）**：","- 还原金属氧化物：\\(2\\mathrm{CuO(s) + C(s)} \\xrightarrow{\\text{高温}} 2\\mathrm{Cu(s) + CO_2(g)}\\uparrow\\)（黑色固体变亮红色并产生使澄清石灰水变浑浊的气体）","- 还原二氧化碳：\\(\\mathrm{CO_2(g) + C(s)} \\xrightarrow{\\text{高温}} 2\\mathrm{CO(g)}\\)（吸热反应，高炉炼铁与煤气发生炉核心反应）","- 还原水蒸气（制水煤气）：\\(\\mathrm{H_2O(g) + C(s)} \\xrightarrow{\\text{高温}} \\mathrm{CO(g) + H_2(g)}\\)"],"takeaway":"注意碳单质在常温极稳定而高温极其活泼，能从水蒸气、CO₂、CuO、Fe₂O₃ 及 SiO₂ 中夺取氧！"}],"formulas":[{"title":"碳的不完全燃烧及高温还原 CO₂ / 水蒸气方程式","tex":"2\\mathrm{C(s)} + \\mathrm{O_2(g)} \\xrightarrow{\\text{点燃}} 2\\mathrm{CO(g)},\\qquad \\mathrm{CO_2(g)} + \\mathrm{C(s)} \\xrightarrow{\\text{高温}} 2\\mathrm{CO(g)},\\qquad \\mathrm{H_2O(g)} + \\mathrm{C(s)} \\xrightarrow{\\text{高温}} \\mathrm{CO(g)} + \\mathrm{H_2(g)}","plain":"2C+O2→2CO; CO2+C—(高温)→2CO; H2O(g)+C—(高温)→CO+H2","conditions":"后两式均为高温吸热反应（水煤气反应中 H₂O 必须是气态水蒸气）","pageRef":"化上 p.273","note":"门捷列夫 1888 年提出的“煤炭地下气化”正是利用上述三个反应生产可燃性 CO 与 H₂。"},{"title":"碳高温还原氧化铜方程式","tex":"2\\mathrm{CuO(s)} + \\mathrm{C(s)} \\xrightarrow{\\text{高温}} 2\\mathrm{Cu(s)} + \\mathrm{CO_2(g)}\\uparrow","plain":"2CuO(s) + C(s) —(高温)→ 2Cu(s) + CO2(g)↑","conditions":"高温（通常加网罩集中火焰提高温度）","pageRef":"化上 p.273","note":"现象：黑色粉末逐渐变为光亮红色，产生的气体使澄清石灰水变浑浊。"}],"pitfalls":[{"title":"误以为由同一种元素组成的物质一定是纯净物","wrong":"“将金刚石和石墨混合后，里面只含有碳一种元素，因此所得固体仍是纯净物（单质）。”","diagnosis":"混淆了“元素组成”与“物质种类”（教材 p.271 交流分享及 p.294 第 3 题考点）。","right":"纯净物必须只含**一种物质**（具有固定的组成与结构）。金刚石与石墨结构与性质完全不同，混合后含有**两种不同单质**，属于**混合物**。","checkRule":"遇“某几种同素异形体混合（如 O₂ 与 O₃、白磷与红磷、金刚石与石墨）”，一律判定为**混合物**。"},{"title":"误以为金刚石、石墨、C₆₀ 属于同种物质或互为同位素","wrong":"“金刚石、石墨和 \\(\\mathrm{C_{60}}\\) 互称为碳元素的同位素。”","diagnosis":"混淆“同位素”（研究原子核：质子同、中子异，如 ¹²C 与 ¹⁴C）和“同素异形体”（研究单质：同元素、不同结构单质）。","right":"金刚石、石墨与 \\(\\mathrm{C_{60}}\\) 互称为碳元素的**同素异形体**；它们在化学性质（如足量燃烧生成 \\(\\mathrm{CO_2}\\)）上相似，但在硬度、导电性等物理性质上因原子排列不同而差异巨大。","checkRule":"原子之间比中子数 = 同位素；单质之间比排列方式 = 同素异形体。"}],"examples":[{"label":"例 12.1.1","tier":"L2","tierLabel":"L2 期末必考","title":"碳单质物理结构与实际用途对应匹配（p.274 思考题 12a & p.293）","prompt":"(1) 轻轨电车（LRT）开动时，受电弓与架空电线的接触点因高速摩擦会产生高温，因此接触滑块材料应具有耐高温、不易氧化且良好导电性的特点（p.274 题 3）。在金刚石、铝、石墨和铜四种材料中最宜选用哪一种？为什么？(2) 分别指出切割玻璃、作电极、冶炼生铁、防毒面具吸附毒气所对应的碳单质类型，并简述它们在结构或微观层面的共同或各自原因。","clues":"铜与铝虽导电但高温摩擦易氧化或熔化软化（铝熔点仅 660 ℃）；石墨熔点极高、自润滑且能导电！","strategy":"逐一用“结构→性质→用途”主线匹配材料特性。","given":"候选：金刚石、铝、石墨、铜；用途：滑块、割玻璃、电极、炼铁、防毒吸附","principle":"石墨层内自由电子导电、层间易滑动润滑、高熔点；金刚石高硬度；焦炭还原性；活性炭多孔大表面积。","steps":["(1) 应选用**石墨**。原因：石墨熔点极高（耐高温）、层间能相对滑动（自润滑减少磨损）、常温下不易被氧化，同时层内每个碳原子有 1 个自由移动电子使它具有优良的**导电性**（铜和铝在高温摩擦下易软化磨损且金属氧化，金刚石不导电）。","(2) 对应碳单质及其原理：","- **切割玻璃**：**金刚石**（空间正四面体共价网状结构，硬度极大）；","- **作电极**：**石墨**（层内自由电子能导电且化学性质稳定）；","- **冶炼生铁**：**焦炭**（在高温下具强还原性，燃烧生热并生成 CO 还原铁矿石）；","- **防毒面具吸附剂**：**活性炭**（结构疏松多孔、经活化后比表面积极大，物理吸附毒气）。"],"answer":"(1) 选用石墨；(2) 割玻璃-金刚石，电极-石墨，炼生铁-焦炭，吸附剂-活性炭。","markingPoints":["选出石墨并从耐高温、导电、润滑不易氧化三点解释滑块材料（2分）","准确匹配四种用途的碳单质及对应结构/性质依据（3分）"],"verification":"对照教材 p.270–274 原文与思考题 12a-3、4 核对。","pitfall":"误选铜作电车受电弓滑块，忽略高速摩擦高温下铜易熔损氧化且缺少固体自润滑性。"},{"label":"例 12.1.2","tier":"L3","tierLabel":"L3 预试拔高","title":"碳与氧气不完全反应混合气体成分测定与热化学定量联系","prompt":"将 \\(6.0\\text{ g}\\) 纯木炭粉放入装有 \\(8.96\\text{ L}\\)（标准状况）纯氧气的密闭刚性容器中，用电弧引燃使其完全反应（假设反应物全部耗尽，容器内既无碳粉剩余也无氧气剩余）。冷却恢复至标准状况，测得气体产物为 \\(\\mathrm{CO}\\) 与 \\(\\mathrm{CO_2}\\) 的混合气体。(1) 通过计算确定混合气体中 \\(\\mathrm{CO}\\) 与 \\(\\mathrm{CO_2}\\) 的物质的量；(2) 若要使反应后的混合气体只剩下纯净 \\(\\mathrm{CO_2}\\)，需如何处理并额外通入至少多少升（标况）氧气？","clues":"利用 **C 原子守恒**与 **O 原子守恒**列二元一次方程组，远比凑两个反应方程式更快！","strategy":"算出 \\(n(\\mathrm{C})=0.500\\text{ mol}\\) 与 \\(n(\\mathrm{O})=0.800\\text{ mol}\\) → 列式 \\(x + y = 0.500\\) 与 \\(x + 2y = 0.800\\) 求解。","given":"m(C)=6.0 g (0.500 mol), V(O₂)=8.96 L (0.400 mol, 含 O 0.800 mol)","principle":"碳原子与氧原子守恒；1 < n(O)/n(C) < 2 时产物为 CO 与 CO₂ 混合。","steps":["计算初始反应物：\\(n(\\mathrm{C}) = \\frac{6.0}{12} = 0.500\\text{ mol}\\)；\\(n(\\mathrm{O_2}) = \\frac{8.96}{22.4} = 0.400\\text{ mol}\\)，即氧原子总数 \\(n(\\mathrm{O}) = 0.800\\text{ mol}\\)。","校验比例：\\(\\frac{n(\\mathrm{O})}{n(\\mathrm{C})} = \\frac{0.800}{0.500} = 1.60\\)，介于 1（纯 \\(\\mathrm{CO}\\)）和 2（纯 \\(\\mathrm{CO_2}\\)）之间，故反应物全部耗尽且生成 **\\(\\mathrm{CO}\\) 与 \\(\\mathrm{CO_2}\\) 的混合气体**。","设生成 \\(\\mathrm{CO}\\) 为 \\(x\\text{ mol}\\)，\\(\\mathrm{CO_2}\\) 为 \\(y\\text{ mol}\\)，列守恒方程组：","- C 守恒：\\(x + y = 0.500\\)（式①）","- O 守恒：\\(x + 2y = 0.800\\)（式②）","式②减式①得 \\(y = 0.300\\text{ mol}\\)（\\(\\mathrm{CO_2}\\)），代回得 \\(x = 0.200\\text{ mol}\\)（\\(\\mathrm{CO}\\)）。","第(2)问：由 \\(2\\mathrm{CO + O_2} \\xrightarrow{\\text{点燃}} 2\\mathrm{CO_2}\\)，将 \\(0.200\\text{ mol CO}\\) 全部燃烧转化为 \\(\\mathrm{CO_2}\\)，需再通入氧气 \\(0.100\\text{ mol}\\)，标况体积 \\(V = 0.100 \\times 22.4 = 2.24\\text{ L}\\)。"],"answer":"(1) 含 CO 0.200 mol、CO₂ 0.300 mol；(2) 再通入 2.24 L（标况）O₂ 并点燃。","markingPoints":["算出 n(C)=0.500 mol 与 n(O)=0.800 mol 并判断共存（2分）","列出 C、O 原子守恒方程组求得 CO 0.200 mol 与 CO₂ 0.300 mol（2分）","算得补加点燃转化所需标况 O₂ 为 2.24 L（1分）"],"verification":"总氧原子验证：0.400 mol + 0.100 mol = 0.500 mol O₂，恰好将 0.500 mol C 完全氧化为 0.500 mol CO₂。","pitfall":"若题目中“碳与氧气比例恰好在 1:1 到 1:2 之间”时，千万别忽略“先把 \\(V(\\mathrm{O_2})\\) 换算成 \\(n(\\mathrm{O}) = 2n(\\mathrm{O_2})\\)”再列 O 守恒！"}],"practice":[{"id":"chem12-12.1-q1","tier":"L1","tierLabel":"L1 基础","examStyle":"P1 选择","q":"金刚石和石墨都是由碳元素组成的单质，但两者的硬度和导电性等物理性质却相差悬殊，其根本原因是（　）。（p.293 教材题 1）","options":["A. 金刚石是纯净的碳单质，而石墨含有大量金属杂质","B. 金刚石是单质，石墨是化合物","C. 金刚石和石墨的组成元素质量分数不同","D. 金刚石和石墨晶体中碳原子的排列方式不同"],"correctOption":"D","given":"p.293 选择题 1 原题","method":"对照同素异形体物理性质差异的微观原因","principle":"结构决定性质：金刚石为正四面体三维共价网状，石墨为六边形平面层状。","steps":["金刚石与石墨都是纯碳单质（含碳 100%），性质悬殊完全是因为碳原子空间排列方式（晶体结构）不同。"],"ans":"D","markingPoints":["确立“原子排列不同导致物理性质差异”"],"verification":"化上 p.270 与 p.293 选择题 1 核对。","pitfall":"误以为金刚石和石墨化学性质也完全不同——其实两者完全燃烧都生成 CO₂。"},{"id":"chem12-12.1-q2","tier":"L2","tierLabel":"L2 期末","examStyle":"P1 选择","q":"某新型“石墨炸弹”在空中爆炸时，能在方圆几百米范围内撒下大量细微石墨纤维，使高压输电线与变电站设备迅速发生短路损坏。这是利用了石墨的哪项性质？（　）（p.293 教材题 2）","options":["A. 具有强放射性","B. 极易燃易爆","C. 具有良好的导电性","D. 具有剧毒腐蚀性"],"correctOption":"C","given":"p.293 选择题 2 原题","method":"从电路短路机理联系石墨导电原理","principle":"石墨层内每个碳原子余有 1 个自由移动电子，导电性极佳。","steps":["大量石墨纤维搭接在裸露高压输电线之间，因石墨能导电而造成相间短路烧毁电网设备。"],"ans":"C","markingPoints":["结合石墨导电性解释真实物理情景"],"verification":"化上 p.293 选择题 2 原题。","pitfall":"误选 B 认为炸弹起作用的是石墨燃烧。"},{"id":"chem12-12.1-q3","tier":"L3","tierLabel":"L3 预试","examStyle":"P2 简答","q":"(1) 为什么我国古代用墨汁书写的字画（图 12-4）历经数百年甚至千年仍墨色不褪，而在工业炼铁和高炉煤气化中焦炭却能剧烈反应？(2) 请写出门捷列夫设想的“煤炭地下气化”（p.273 问题解决）生成可燃性气体 \\(\\mathrm{CO}\\) 与 \\(\\mathrm{H_2}\\) 的三个核心化学方程式。","given":"p.268、p.272–273 碳单质化学性质","method":"对比碳在常温下的惰性与高温下的强还原性","principle":"碳原子最外层 4 个电子既难全失又难全得，常温下反应活化能高极稳定；高温下具强还原性。","steps":["(1) 墨汁主要成分是炭黑（碳单质）。常温下碳的化学性质极稳定，不与空气、水或一般物质反应，故字画千年不变色；但在**高温**条件下碳原子能量升高，展现出强还原性，能与 \\(\\mathrm{O_2, CO_2, H_2O(g)}\\) 及金属氧化物剧烈反应。","(2) 煤炭地下气化三个反应：①\\(2\\mathrm{C(s) + O_2(g)} \\xrightarrow{\\text{点燃}} 2\\mathrm{CO(g)}\\)（或先完全燃烧 \\(\\mathrm{C + O_2 \\to CO_2}\\)）；②\\(\\mathrm{CO_2(g) + C(s)} \\xrightarrow{\\text{高温}} 2\\mathrm{CO(g)}\\)；③\\(\\mathrm{H_2O(g) + C(s)} \\xrightarrow{\\text{高温}} \\mathrm{CO(g) + H_2(g)}\\)。"],"ans":"(1) 碳单质常温稳定，高温具强还原性；(2) 2C+O₂→2CO、CO₂+C—(高温)→2CO、H₂O(g)+C—(高温)→CO+H₂。","markingPoints":["准确对比常温稳定性与高温还原性（2分）","写出煤炭气化相关三个反应方程式并注条件（3分）"],"verification":"化上 p.272–273 问题解决原文完全吻合。","pitfall":"写水煤气反应时忘记标注水为气态 \\(\\mathrm{H_2O(g)}\\) 或漏写高温条件。"},{"id":"chem12-12.1-q4","tier":"L4","tierLabel":"L4 统考压轴","examStyle":"P2 实验定量","q":"某同学在隔绝空气条件下，将 \\(1.20\\text{ g}\\) 纯木炭粉与 \\(16.0\\text{ g}\\) 纯净黑色氧化铜（\\(\\mathrm{CuO}\\)）粉末充分混合研细后，装入硬质试管强热至充分反应（假设固体完全反应）。冷却后将产生的全部气体通入足量澄清石灰水中，收集并干燥白色沉淀。(1) 反应后硬质试管内残留固体的组成与总质量各是多少？（\\(A_r: \\mathrm{C}=12, \\mathrm{Cu}=64, \\mathrm{O}=16\\)）(2) 理论上在澄清石灰水中最多能得到多少克 \\(\\mathrm{CaCO_3}\\) 沉淀？（\\(M(\\mathrm{CaCO_3}) = 100\\text{ g\\,mol}^{-1}\\)）","given":"n(C) = 1.20/12 = 0.100 mol; n(CuO) = 16.0/80 = 0.200 mol","method":"判断 2CuO + C —(高温)→ 2Cu + CO₂↑ 中两者恰为 2:1 计量比，再按物质不灭与 CaCO₃ 沉淀算","principle":"2CuO(s) + C(s) —(高温)→ 2Cu(s) + CO₂(g)↑；CO₂ + Ca(OH)₂ → CaCO₃↓ + H₂O。","steps":["计算投料：\\(n(\\mathrm{C}) = \\frac{1.20}{12} = 0.100\\text{ mol}\\)，\\(n(\\mathrm{CuO}) = \\frac{16.0}{80} = 0.200\\text{ mol}\\)。","由方程式 \\(2\\mathrm{CuO(s) + C(s)} \\xrightarrow{\\text{高温}} 2\\mathrm{Cu(s) + CO_2(g)}\\uparrow\\)，知 \\(n(\\mathrm{CuO}) : n(\\mathrm{C}) = 0.200 : 0.100 = 2 : 1\\)，两者**恰好完全反应**！","第(1)问：试管内残留固体全部为单质铜（\\(\\mathrm{Cu}\\)），物质的量 \\(n(\\mathrm{Cu}) = 0.200\\text{ mol}\\)，质量 \\(m(\\mathrm{Cu}) = 0.200 \\times 64 = 12.8\\text{ g}\\)。","第(2)问：生成 \\(\\mathrm{CO_2}\\) 为 \\(0.100\\text{ mol}\\)，通入足量澄清石灰水全部转化为 \\(\\mathrm{CaCO_3}\\) 沉淀：\\(n(\\mathrm{CaCO_3}) = 0.100\\text{ mol}\\)，质量 \\(= 0.100 \\times 100 = 10.0\\text{ g}\\)。"],"ans":"(1) 残留固体全为 Cu，质量 12.8 g；(2) 最多得到 10.0 g CaCO₃ 沉淀。","markingPoints":["算得 n(C)=0.100 mol 与 n(CuO)=0.200 mol 确认 2:1 恰好完全反应（2分）","求得残留固体 Cu 为 12.8 g（1分）","求得 CaCO₃ 沉淀为 10.0 g（1分）"],"verification":"总质量核对：反应前固体 1.20 + 16.0 = 17.2 g；反应后固体 12.8 g + 逸出 CO₂ (0.100×44=4.4 g) = 17.2 g，严格守恒！","pitfall":"若误把 2CuO + C 写成生成 CO，会少算 CaCO₃ 且质量比偏离（不过若题目没给足量石灰水而是过量 C，才可能产生 CO）。"}],"cheatSheet":["IVA 族（\\(ns^2np^2\\)）：从 C 到 Pb 非金属性减弱、金属性增强；酸性 \\(\\mathrm{H_2CO_3 > H_2SiO_3}\\)。","碳同素异形体：金刚石（正四面体最硬不导电）、石墨（层状导电润滑）、\\(\\mathrm{C_{60}}\\)（12 五边+20 六边）；金刚石+石墨 = **混合物**。","高温碳还原三核心：\\(2\\mathrm{CuO+C \\to 2Cu+CO_2\\uparrow}\\)、\\(\\mathrm{CO_2+C \\to 2CO}\\)、\\(\\mathrm{H_2O(g)+C \\to CO+H_2}\\)。"],"kbEntryIds":["kb-chem12-c-allotropes"],"quiz":{"q":"富勒烯 \\(\\mathrm{C_{60}}\\) 分子中由多少个五边形和多少个六边形组成？它属于什么晶体类型？","given":"p.271 图 12-9 C₆₀ 分子结构","method":"回忆巴基球几何面数与分子结构分类","principle":"C₆₀ 为由独立 60 原子分子构成的分子晶体，熔点远低于原子晶体金刚石。","steps":["\\(\\mathrm{C_{60}}\\) 是由 60 个碳原子构成的球形三十二面体，包含 **12 个五边形**和 **20 个六边形**；由于由独立 \\(\\mathrm{C_{60}}\\) 分子通过范德华力聚集，属于**分子晶体**。"],"ans":"12 个五边形和 20 个六边形；属于分子晶体。"}},{"id":"12.2","t":"碳的重要化合物","anchor":{"pages":"化上 p.274–284","syllabus":"3.6.4–3.6.7 CO 与 CO₂、碳酸盐与碳酸氢盐、无机碳化物（CaC₂/CS₂/SiC）及碳气体燃料","examScopes":["sem2_final","uec"],"examWeight":"P1 制碱流程/碳化物/气体燃料组分 + P2 四朵小花探究及制碱/碳酸盐计算","terms":"CO vs CO₂ · Dry ice · Solvay & Hou's process · Calcium carbide (CaC₂) · Silicon carbide (SiC) · Water gas","prerequisites":["碳单质性质及 Na₂CO₃/NaHCO₃ 基础（化上 Ch 9.3 & 12.1）","实验控制变量设计与氧化还原配平"],"goals":["全面对比 CO（毒理、蓝焰可燃性、冶金还原、合成甲醇）与 CO₂（干冰、石灰水检验与过量变清、温室效应）的理化性质。","分析教材 CO₂ 溶于水四朵紫色石蕊小花对照实验（p.284）的科学严谨性，掌握实验室制 CO₂（图 12-12）选酸禁忌。","对比索尔维氨碱法与侯氏联合制碱法的原理与优缺点，并记住 CaC₂、CS₂、SiC 及水煤气/发生炉煤气等气体燃料成分。"]},"concepts":[{"kind":"table","title":"12.2.1 一氧化碳（CO）与二氧化碳（CO₂）全面对比及实验室制取","pageRef":"化上 p.274–278、p.284","body":["**CO₂ 实验室制法（活动 2 图 12-12）**：用大理石/石灰石（\\(\\mathrm{CaCO_3}\\)）与**稀盐酸**反应（\\(\\mathrm{CaCO_3 + 2HCl \\to CaCl_2 + H_2O + CO_2\\uparrow}\\)），因密度大于空气且能溶于水，用**向上排空气法**收集。**绝不能用稀硫酸代替稀盐酸**（生成的 \\(\\mathrm{CaSO_4}\\) 微溶于水覆盖在石灰石表面，阻止反应继续进行！）。","**活动 5 & 思考题 12b-3（四朵干石蕊小花对照探究，p.284）**：①单独喷水（不变色，证明水不能使石蕊变红）；②单独喷稀醋酸（变红，证明酸能使石蕊变红）；③干燥小花直接入干 \\(\\mathrm{CO_2}\\) 瓶（不变色，证明 \\(\\mathrm{CO_2}\\) 气体本身不能使石蕊变红）；④喷水后放入 \\(\\mathrm{CO_2}\\) 瓶（变红，且加热后恢复紫色，严格证明 **\\(\\mathrm{CO_2 + H_2O \\rightleftharpoons H_2CO_3}\\) 生成了碳酸**）。"],"table":{"headers":["比较维度","一氧化碳（CO）","二氧化碳（CO₂）"],"rows":[["物理性质与毒性","无色无味，密度比空气**略小**，难溶于水；**剧毒**（与血红蛋白强结合阻断输氧）","无色无味，密度比空气**大**，微溶于水（约 1:1）；无毒（高浓度致窒息）；固态称**干冰**（-78.5 ℃ 升华制冷/人工降雨）"],["可燃性与助燃性","有可燃性（**浅蓝色火焰**）：\\(2\\mathrm{CO + O_2} \\xrightarrow{\\text{点燃}} 2\\mathrm{CO_2}\\)","不燃烧也不支持一般燃烧（常用灭火剂，但 Mg 条除外）"],["氧化还原与有机合成","强还原性（高炉炼铁 \\(\\mathrm{Fe_2O_3 + 3CO \\to 2Fe + 3CO_2}\\)）；合成甲醇 \\(\\mathrm{CO + 2H_2 \\to CH_3OH}\\)","酸性氧化物（两步电离 \\(\\mathrm{H_2CO_3 \\rightleftharpoons H^+ + HCO_3^-}\\)）；温室效应主因（家居碳排 ≈ 用电 kWh × 0.96 kg，p.276）"],["检验与除杂","除 CO 中混有 CO₂：通入 **NaOH 溶液**（勿用石灰水，吸收量小）","检验 CO₂：通澄清石灰水（先变浑浊 \\(\\mathrm{CaCO_3\\downarrow}\\)，**过量变澄清**生成 \\(\\mathrm{Ca(HCO_3)_2}\\)）；除 CO₂ 中少量 CO：通过灼热 **CuO**"]]},"takeaway":"记住除杂口诀：除 CO 中的 CO₂ 用 NaOH 溶液；除 CO₂ 中的 CO 用灼热 CuO；检验 CO₂ 用澄清石灰水（切忌直接说“浑浊”，还需强调适量或防过量变清）。"},{"kind":"mechanism","title":"12.2.2 碳酸盐与碳酸氢盐（表 12-2）及索尔维 vs 侯氏制碱法","pageRef":"化上 p.279–281、p.295","body":["**表 12-2 碳酸盐与碳酸氢盐性质通律**：①**水溶性**：除 \\(\\mathrm{K^+},\\ \\mathrm{Na^+},\\ \\mathrm{NH_4^+}\\) 的碳酸盐易溶外，其余大多不溶或微溶；碳酸氢盐则大多能溶于水（注意 \\(\\mathrm{NaHCO_3}\\) 溶解度远小于 \\(\\mathrm{Na_2CO_3}\\)）；②**热稳定性**：除 \\(\\mathrm{K_2CO_3},\\ \\mathrm{Na_2CO_3}\\) 外，其它碳酸盐高温均分解；所有碳酸氢盐受热均易分解；③**与 \\(\\mathrm{CO_2}\\) 反应**：可溶或难溶碳酸盐在水溶液中能继续吸 \\(\\mathrm{CO_2}\\) 转为碳酸氢盐，碳酸氢盐不与 \\(\\mathrm{CO_2}\\) 反应。","**索尔维氨碱法（1861）核心反应**：向饱和食盐水先通入足量 \\(\\mathrm{NH_3}\\)，再通入足量 \\(\\mathrm{CO_2}\\)，析出溶解度较小的 \\(\\mathrm{NaHCO_3}\\) 晶体，过滤煅烧得纯碱：\\(\\mathrm{NaCl(aq) + NH_3(g) + CO_2(g) + H_2O(l) \\longrightarrow NaHCO_3(s)\\downarrow + NH_4Cl(aq)}\\)；\\(2\\mathrm{NaHCO_3(s)} \\xrightarrow{\\Delta} \\mathrm{Na_2CO_3(s) + CO_2(g) + H_2O(l)}\\)。缺点：食盐利用率仅 **70%**，氨损失多且副产无用 \\(\\mathrm{CaCl_2}\\) 废渣。","**侯德榜联合制碱法（1942，p.281）**：基本原理相同，但向滤出 \\(\\mathrm{NaHCO_3}\\) 后的母液中加入 **\\(\\mathrm{NaCl}\\) 粉末**并通入 **\\(\\mathrm{NH_3}\\)** 降温结晶析出副产品 **\\(\\mathrm{NH_4Cl}\\)（作氮肥）**，母液（含未析出 \\(\\mathrm{NaCl}\\)）循环使用，大幅提高食盐利用率且免去石灰蒸氨废渣！"],"takeaway":"为什么制碱通气顺序“先通 NH₃ 后通 CO₂”不能颠倒（p.295 题 7-(2)）？因为 NH₃ 极易溶于水（1:700）使溶液呈碱性，能大幅增加溶解度很小的 CO₂（1:1）的吸收量，生成足够浓度的 HCO₃⁻ 从而促使 NaHCO₃ 结晶析出！"},{"kind":"definition","title":"12.2.3 无机碳化物（CaC₂、CS₂、SiC）与 12.2.4 碳气体燃料","pageRef":"化上 p.281–283","body":["**碳化钙（电石，\\(\\mathrm{CaC_2}\\)）**：由生石灰与焦炭在电炉 2000 ℃ 制得：\\(\\mathrm{CaO(s) + 3C(s)} \\xrightarrow{\\text{高温}} \\mathrm{CaC_2(s) + CO(g)}\\uparrow\\)。电石遇水剧烈反应生成**乙炔（\\(\\mathrm{C_2H_2}\\)，又称电石气，氧炔焰用于焊接切割）**：\\(\\mathrm{CaC_2(s) + 2H_2O(l) \\longrightarrow Ca(OH)_2(aq) + C_2H_2(g)}\\uparrow\\)。","**二硫化碳（\\(\\mathrm{CS_2}\\)）**：无色易挥发（沸点 **46.2 ℃**）易燃液体，由炽热木炭与硫蒸气反应制得：\\(\\mathrm{C(s,\\text{炽热}) + 2S(g) \\to CS_2(l)}\\)，优良非极性溶剂（可溶解硫、白磷、橡胶）。","**碳化硅（金刚砂，\\(\\mathrm{SiC}\\)，图 12-18）**：沙子（\\(\\mathrm{SiO_2}\\)）与焦炭在 2000 ℃ 电炉制得：\\(\\mathrm{SiO_2(s) + 3C(s)} \\xrightarrow{\\text{高温}} \\mathrm{SiC(s) + 2CO(g)}\\uparrow\\)。结构与金刚石相似（每个 Si 连 4 C、每个 C 连 4 Si），硬度极高仅次于金刚石，作**优良研磨剂（砂纸、砂轮）**。","**四大含碳气体燃料对比（p.282–283）**：**天然气**（主要成分甲烷 \\(\\mathrm{CH_4}\\)）、**水煤气**（水蒸气过炽热焦炭：\\(\\mathrm{CO + H_2}\\)）、**发生炉煤气**（空气过炽热焦炭：\\(\\mathrm{CO + N_2}\\)）、**液化石油气**（炼油低沸点烃，主要成分丙烷 \\(\\mathrm{C_3H_8}\\) 和丁烷 \\(\\mathrm{C_4H_{10}}\\)）。"],"takeaway":"区分易混成分：水煤气 = CO + H₂；发生炉煤气 = CO + N₂；天然气 = CH₄；石油气 = C₃H₈/C₄H₁₀（p.294 练习 6）。"}],"formulas":[{"title":"CO 还原氧化铁及过量 CO₂ 通入澄清石灰水方程式","tex":"\\mathrm{Fe_2O_3(s)} + 3\\mathrm{CO(g)} \\xrightarrow{\\text{高温}} 2\\mathrm{Fe(s)} + 3\\mathrm{CO_2(g)},\\qquad \\mathrm{CaCO_3(s)} + \\mathrm{CO_2(g)} + \\mathrm{H_2O(l)} \\longrightarrow \\mathrm{Ca(HCO_3)_2(aq)}","plain":"Fe2O3+3CO—(高温)→2Fe+3CO2; CaCO3+CO2+H2O→Ca(HCO3)2","conditions":"过量 CO₂ 使原 CaCO₃ 浑浊重新溶解变澄清；加热后逆向再变浑浊","pageRef":"化上 p.275、p.278","note":"不能用点燃法检验或除去混在 CO₂ 中的少量 CO（CO₂ 不助燃，点不着）。"},{"title":"制碱核心反应及电石、金刚砂高温制备方程","tex":"\\mathrm{NaCl(aq)} + \\mathrm{NH_3(g)} + \\mathrm{CO_2(g)} + \\mathrm{H_2O(l)} \\longrightarrow \\mathrm{NaHCO_3(s)}\\downarrow + \\mathrm{NH_4Cl(aq)},\\qquad \\mathrm{SiO_2(s)} + 3\\mathrm{C(s)} \\xrightarrow{\\text{高温}} \\mathrm{SiC(s)} + 2\\mathrm{CO(g)}\\uparrow","plain":"NaCl+NH3+CO2+H2O→NaHCO3↓+NH4Cl; SiO2+3C—(高温)→SiC+2CO↑","conditions":"制碱先通 NH₃ 后通 CO₂；SiC 制备中氧化剂 C 与还原剂 C 之比为 1 : 2","pageRef":"化上 p.280、p.282","note":"过滤得 NaHCO₃ 晶体后，滤液主要溶质是 NH₄Cl（及少量未反应 NaCl/NaHCO₃）。"}],"pitfalls":[{"title":"误以为实验室制 CO₂ 可用稀硫酸或浓盐酸","wrong":"“实验室制取 \\(\\mathrm{CO_2}\\) 时，用石灰石和稀硫酸反应比稀盐酸更快更纯。”","diagnosis":"忽视 \\(\\mathrm{CaSO_4}\\) 的微溶性阻隔作用。","right":"\\(\\mathrm{CaCO_3}\\) 与稀硫酸反应生成微溶的 **\\(\\mathrm{CaSO_4}\\)** 覆盖在石灰石块表面，导致反应很快停止！而用浓盐酸则因挥发性太强混入大量 \\(\\mathrm{HCl}\\) 气体杂质，因此必须使用**稀盐酸**（p.277、p.295 题 13）。","checkRule":"除去石英砂（SiO₂）中的少量 CaCO₃ 也只能用**稀盐酸**溶解过滤，不可用稀硫酸（p.295 选择题 13）！"},{"title":"误算制取金刚砂（SiC）中氧化剂与还原剂的物质的量之比","wrong":"“在 \\(\\mathrm{SiO_2 + 3C} \\xrightarrow{\\text{高温}} \\mathrm{SiC + 2CO}\\uparrow\\) 中，\\(\\mathrm{SiO_2}\\) 是氧化剂，\\(\\mathrm{C}\\) 是还原剂，两者物质的量之比为 1 : 3。”","diagnosis":"教材 p.296 作答题 8-(3) 高阶陷阱！没核对硅元素氧化数变化：\\(\\mathrm{SiO_2}\\) 中 Si 为 +4 价，\\(\\mathrm{SiC}\\) 中 C 电负性更强呈 −4 价，Si 仍为 **+4 价**！","right":"该反应中 \\(\\mathrm{Si}\\)（+4）与 \\(\\mathrm{O}\\)（−2）化合价均**未发生变化**！氧化还原反应仅在碳原子之间发生归中/歧化：**1 mol C 由 0 价降为 \\(\\mathrm{SiC}\\) 中的 −4 价（作氧化剂）**，**2 mol C 由 0 价升为 \\(\\mathrm{CO}\\) 中的 +2 价（作还原剂）**，故氧化剂与还原剂物质的量之比为 **1 : 2**！","checkRule":"配平或定比例前，务必逐一标出所有元素反应前后的氧化数，切忌凭经验猜 SiO₂ 被还原！"}],"examples":[{"label":"例 12.2.1","tier":"L3","tierLabel":"L3 实验探究","title":"CO₂ 溶于水生成碳酸的四朵石蕊小花控制变量分析（p.284 思考题 12b-3）","prompt":"如图所示，某同学用四朵干燥的喷有紫色石蕊试液的纸花做了四个实验：I. 向小花喷水（不变色）；II. 向小花喷稀醋酸（变红色）；III. 将干燥小花直接放入干燥 \\(\\mathrm{CO_2}\\) 集气瓶中（不变色）；IV. 将小花喷水后放入 \\(\\mathrm{CO_2}\\) 集气瓶中（变红色）。(1) 写出实验 I、III 的实验目的和实验 IV 的结论；(2) 若只做实验 IV，能否得出“\\(\\mathrm{CO_2}\\) 与水反应生成了酸”的结论？为什么？若不做实验 II，又会有什么逻辑漏洞？","clues":"控制变量法逐一排除单因素假阳性：排除“水”、排除“干 CO₂”、确认“酸能使石蕊变红”。","strategy":"逐项拆解四个对照组分别排除了哪一个自变量干扰。","given":"I(水→不变), II(稀醋酸→变红), III(干CO₂→不变), IV(水+CO₂→变红)","principle":"对照实验单一变量控制逻辑。","steps":["(1) 实验 I 目的：**证明水本身不能使紫色石蕊变红色**；实验 III 目的：**证明干燥的二氧化碳气体本身不能使紫色石蕊变红色**；实验 IV 结论：**二氧化碳与水反应生成了碳酸（酸性物质），使紫色石蕊变红**。","(2) **若只做实验 IV**：无法知道究竟是喷上的水、瓶中的 \\(\\mathrm{CO_2}\\) 气体还是两者的反应产物使小花变红（缺乏阴性对照 I、III 与阳性对照 II），故只能模糊得出“水和 \\(\\mathrm{CO_2}\\) 共同作用可能使石蕊变红，或无法确定是哪种物质变红”。","**若不做实验 II**：缺乏“酸能使紫色石蕊变红”的阳性依据，即使 IV 变红也无法证明 \\(\\mathrm{CO_2}\\) 与水反应生成的新物质属于**酸**！"],"answer":"(1) I: 证明水不变色；III: 证明干 CO₂ 不变色；IV: CO₂ 溶于水生成酸使石蕊变红。(2) 只做 IV 不能确定变红原因；不做 II 无法确认新产物是“酸”。","markingPoints":["精准写出 I、III 对照目的与 IV 最终结论（3分）","清晰剖析缺少对照实验 I/III 或 II 各自造成的逻辑漏洞（2分）"],"verification":"教材 p.284 思考题 12b-3 逐空核对完全一致。","pitfall":"在解释不做实验 II 的漏洞时，容易笼统写成“实验不严谨”，而漏掉“未证明酸性溶液使石蕊变红这一判据”。"},{"label":"例 12.2.2","tier":"L4","tierLabel":"L4 统考压轴","title":"实验室模拟制碱流程（p.295 第 7 题）及过量气体吸收判断","prompt":"（教材 p.295 作答题 7）实验室模拟工业制备纯碱（\\(\\mathrm{Na_2CO_3}\\)）的主要流程如下：饱和食盐水 \\(\\xrightarrow{\\text{(1) 通入足量 }\\mathrm{NH_3}}\\) 氨盐水 \\(\\xrightarrow{\\text{(2) 通入足量 }\\mathrm{CO_2}}\\) 悬浊液 \\(\\xrightarrow{\\text{(3) 过滤}}\\) 得到晶体与滤液；晶体 \\(\\xrightarrow{(4)}\\) 挥发物 + 白色固体。(1) 步骤③过滤得到的晶体化学名称是什么？滤液中主要含有的溶质是什么？(2) 简述操作①和②的先后顺序不能颠倒的原因。(3) 操作④的名称是什么？写出操作④发生的化学方程式，并说明实际生产中“挥发物”的哪些成分可循环利用。","clues":"利用 \\(\\mathrm{NaHCO_3}\\) 在氨盐水中的最小溶解度先结晶析出；NH₃ 与 CO₂ 溶解度差异高达 700 倍！","strategy":"写出制碱双步方程 → 由溶解度差异解顺序 → 煅烧分解回收 CO₂。","given":"饱和 NaCl(aq) → +足量 NH₃ → +足量 CO₂ → 过滤 → 晶体加热","principle":"NaCl+NH₃+CO₂+H₂O→NaHCO₃↓+NH₄Cl；2NaHCO₃—(△)→Na₂CO₃+CO₂↑+H₂O。","steps":["(1) 步骤③过滤得到的晶体名称是**碳酸氢钠（\\(\\mathrm{NaHCO_3}\\)）**，滤液中主要含有的溶质是**氯化铵（\\(\\mathrm{NH_4Cl}\\)）**（及少量未析出的 \\(\\mathrm{NaCl}\\)、\\(\\mathrm{NaHCO_3}\\)）。","(2) **顺序不能颠倒的原因**：\\(\\mathrm{CO_2}\\) 在水中的溶解度很小（常温常压约 1:1），若先通 \\(\\mathrm{CO_2}\\) 仅生成极少量 \\(\\mathrm{H_2CO_3}\\)，溶液呈弱酸性不利于继续吸收，难以生成足够量的 \\(\\mathrm{HCO_3^-}\\) 析出沉淀；而 \\(\\mathrm{NH_3}\\) 极易溶于水（约 1:700）并生成碱性氨水，**先通足量 \\(\\mathrm{NH_3}\\) 使溶液呈较强碱性后，再通 \\(\\mathrm{CO_2}\\) 即可大量吸收转化生成高浓度 \\(\\mathrm{HCO_3^-}\\)**，从而促使 \\(\\mathrm{NaHCO_3}\\) 晶体顺利析出。","(3) 操作④是**加热（或煅烧）**，反应方程式为：\\(2\\mathrm{NaHCO_3(s)} \\xrightarrow{\\Delta} \\mathrm{Na_2CO_3(s) + H_2O(g)\\uparrow + CO_2(g)\\uparrow}\\)。挥发物中的 **\\(\\mathrm{CO_2}\\)**（及水蒸气）可通回步骤②中**循环利用**！"],"answer":"(1) 碳酸氢钠；氯化铵；(2) 先通易溶碱性 NH₃ 可大幅提高对难溶 CO₂ 的吸收量以产生高浓度 HCO₃⁻；(3) 加热（煅烧），2NaHCO₃—(△)→Na₂CO₃+H₂O+CO₂↑，CO₂ 可循环利用。","markingPoints":["准确写出晶体（NaHCO₃）与滤液主溶质（NH₄Cl）（2分）","从溶解度（NH₃ 极易溶 vs CO₂ 微溶）与酸碱性（碱液高效吸 CO₂）解释顺序（2分）","写出操作④名称、分解方程式及 CO₂ 循环利用（2分）"],"verification":"对照教材 p.280 及 p.295 第 7 题设问全部精准吻合。","pitfall":"第(1)问易误答过滤得到的晶体直接是“碳酸钠”，忘记氨碱法析出的是溶解度更小的碳酸氢钠！"}],"practice":[{"id":"chem12-12.2-q1","tier":"L1","tierLabel":"L1 基础","examStyle":"P1 选择","q":"家用瓶装液化石油气（LPG）中主要含有的气体燃料成分是（　）。（p.294 教材题 6）","options":["A. \\(\\mathrm{CO}\\)、\\(\\mathrm{H_2}\\) 和 \\(\\mathrm{CO_2}\\)","B. \\(\\mathrm{CO}\\)、\\(\\mathrm{H_2}\\) 和 \\(\\mathrm{N_2}\\)","C. 丙烷（\\(\\mathrm{C_3H_8}\\)）和丁烷（\\(\\mathrm{C_4H_{10}}\\)）","D. \\(\\mathrm{CH_4}\\)、\\(\\mathrm{CO}\\) 和 \\(\\mathrm{H_2}\\)"],"correctOption":"C","given":"p.283 石油气成分 & p.294 题 6","method":"对照四大气体燃料成分表","principle":"石油炼制产生的低沸点混合烃主要是丙烷和丁烷，易加压液化装钢瓶。","steps":["天然气主要为 CH₄，水煤气为 CO + H₂，发生炉煤气为 CO + N₂，石油气主要为丙烷和丁烷。"],"ans":"C","markingPoints":["准确区分石油气与水煤气/发生炉煤气成分"],"verification":"化上 p.283 原文及 p.294 选择题 6。","pitfall":"与水煤气（CO+H₂）混淆。"},{"id":"chem12-12.2-q2","tier":"L2","tierLabel":"L2 期末","examStyle":"P1 选择","q":"将燃着的木条伸入盛有某种无色气体的集气瓶中，木条立即熄灭。据此现象对瓶中气体的判断，**错误**的是（　）。（p.283 思考题 12b-2）","options":["A. 瓶中气体一定是二氧化碳","B. 瓶中气体一定不是氧气","C. 瓶中气体可能是二氧化碳","D. 瓶中气体可能是氮气"],"correctOption":"A","given":"p.283 思考题 12b-2 原题","method":"利用性质的必要非充分条件排除绝对判断","principle":"不支持燃烧的气体除 CO₂ 外，还有 N₂、稀有气体、CO（纯 CO 中缺乏氧气也不支持木条燃烧）等。","steps":["木条熄灭只能否定它是助燃的氧气（B 对），无法唯一确定必为 CO₂（C、D 对，A 过于绝对错误）。"],"ans":"A","markingPoints":["辨别检验气体现象的逻辑唯一性"],"verification":"化上 p.283 思考题 12b-2 原题。","pitfall":"误把“能灭火的气体”等同于“一定是二氧化碳”（真正检验 CO₂ 必须用澄清石灰水！）。"},{"id":"chem12-12.2-q3","tier":"L3","tierLabel":"L3 预试","examStyle":"P2 简答","q":"试写出下列物质转化的化学方程式（教材 p.295 作答题 5）：\\(\\mathrm{CaCO_3 \\xrightarrow{(1)} Ca(HCO_3)_2 \\xrightarrow{(2)} CaCO_3 \\xrightarrow{(3)} CaO \\xrightarrow{(4)} CaC_2 \\xrightarrow{(5)} C_2H_2}\\)。","given":"p.295 习题 5 五步转化链","method":"依次写出溶洞溶解、受热沉积、高温煅烧、电炉制电石、电石水解五步方程式","principle":"碳酸钙—碳酸氢钙可逆转换与电石制乙炔反应。","steps":["① \\(\\mathrm{CaCO_3(s) + H_2O(l) + CO_2(g) \\longrightarrow Ca(HCO_3)_2(aq)}\\)","② \\(\\mathrm{Ca(HCO_3)_2(aq)} \\xrightarrow{\\Delta} \\mathrm{CaCO_3(s)\\downarrow + H_2O(l) + CO_2(g)\\uparrow}\\)","③ \\(\\mathrm{CaCO_3(s)} \\xrightarrow{\\text{高温}} \\mathrm{CaO(s) + CO_2(g)\\uparrow}\\)","④ \\(\\mathrm{CaO(s) + 3C(s)} \\xrightarrow{\\text{高温}(2000\\ ^\\circ\\mathrm{C})} \\mathrm{CaC_2(s) + CO(g)\\uparrow}\\)","⑤ \\(\\mathrm{CaC_2(s) + 2H_2O(l) \\longrightarrow Ca(OH)_2(aq) + C_2H_2(g)\\uparrow}\\)"],"ans":"见上述五步完整配平化学方程式。","markingPoints":["每步方程式化学式、配平、条件与气体/沉淀符号各占 1 分（共 5 分）"],"verification":"对照化上 p.279 与 p.281 原文方程式逐一核对。","pitfall":"第④步制电石容易误将产物 \\(\\mathrm{CO}\\) 错写成 \\(\\mathrm{CO_2}\\) 导致碳配平错误（正确是 + 3C → CaC₂ + CO）。"},{"id":"chem12-12.2-q4","tier":"L4","tierLabel":"L4 统考压轴","examStyle":"P2 综合计算","q":"某实验小组将 \\(200\\text{ mL}\\) 某浓度的澄清石灰水（\\(\\mathrm{Ca(OH)_2}\\) 溶液）分成两等份（每份 \\(100\\text{ mL}\\)）进行 \\(\\mathrm{CO_2}\\) 吸收实验：向第一份中通入标准状况下 \\(V\\text{ L}\\ \\mathrm{CO_2}\\)，测得生成了 \\(1.00\\text{ g}\\) 白色 \\(\\mathrm{CaCO_3}\\) 沉淀；向第二份中改为直接通入过量（足量）\\(\\mathrm{CO_2}\\) 气体至沉淀完全溶解后，测量得知共吸收了 \\(4.48\\text{ L}\\)（标况）\\(\\mathrm{CO_2}\\) 才刚好全溶（不计 \\(\\mathrm{CO_2}\\) 纯水溶解）。(1) 求原澄清石灰水中 \\(\\mathrm{Ca(OH)_2}\\) 的物质的量浓度；(2) 求第一份中通入的 \\(\\mathrm{CO_2}\\) 标况体积 \\(V\\) 的所有可能值。（\\(M(\\mathrm{CaCO_3}) = 100\\text{ g\\,mol}^{-1}\\)）","given":"每份 100 mL；第二份恰好全溶耗 CO₂ 4.48 L (0.200 mol)；第一份生 CaCO₃ 1.00 g (0.0100 mol)","method":"第二份总反应 Ca(OH)₂ + 2CO₂ → Ca(HCO₃)₂ 求 n[Ca(OH)₂]；第一份类似两性沉淀曲线有 CO₂ 不足与过量部分溶解两解！","principle":"Ca(OH)₂ + CO₂ → CaCO₃↓ + H₂O；CaCO₃ + CO₂ + H₂O → Ca(HCO₃)₂。","steps":["第(1)问：第二份中刚好全部溶解为 \\(\\mathrm{Ca(HCO_3)_2}\\)，总反应为 \\(\\mathrm{Ca(OH)_2 + 2CO_2 \\to Ca(HCO_3)_2}\\)。","已知消耗 \\(n(\\mathrm{CO_2}) = \\frac{4.48}{22.4} = 0.200\\text{ mol}\\)，故每份 \\(100\\text{ mL}\\) 中含 \\(n(\\mathrm{Ca(OH)_2}) = \\frac{0.200}{2} = 0.100\\text{ mol}\\)（注：按化学计量假定溶质浓度为 \\(\\frac{0.100}{0.100} = 1.00\\text{ mol\\,L}^{-1}\\)，若实际石灰水饱和度低，此题作理想溶液计量模型）。","第(2)问：第一份中最多可生成 \\(0.100\\text{ mol }\\mathrm{CaCO_3}\\)，实测仅得 \\(\\frac{1.00}{100} = 0.0100\\text{ mol} < 0.100\\text{ mol}\\)，故必有**两组解**：","- 情况 ①（\\(\\mathrm{CO_2}\\) 不足）：仅部分沉淀，耗 \\(n(\\mathrm{CO_2}) = 0.0100\\text{ mol}\\)，\\(V_1 = 0.0100 \\times 22.4 = 0.224\\text{ L}\\)；","- 情况 ②（\\(\\mathrm{CO_2}\\) 过量）：先耗 \\(0.100\\text{ mol }\\mathrm{CO_2}\\) 全沉淀得 \\(0.100\\text{ mol }\\mathrm{CaCO_3}\\)，再耗 \\((0.100 - 0.0100) = 0.0900\\text{ mol }\\mathrm{CO_2}\\) 溶解掉 \\(0.0900\\text{ mol}\\)，共耗 \\(0.190\\text{ mol }\\mathrm{CO_2}\\)，\\(V_2 = 0.190 \\times 22.4 = 4.26\\text{ L}\\)。"],"ans":"(1) 1.00 mol·L⁻¹；(2) V 的可能值为 0.224 L 或 4.26 L。","markingPoints":["利用第二份 1:2 全溶关系求得 n[Ca(OH)₂]=0.100 mol 及浓度 1.00 mol/L（2分）","识别第一份 CaCO₃ 沉淀少于最大值存在双解（1分）","分别算出 CO₂ 不足 0.224 L 与过量部分溶解 4.26 L（2分）"],"verification":"沉淀与溶解等腰三角形对称关系：0.01 mol 与 0.19 mol 和为总耗 0.20 mol！","pitfall":"只算出不足解 0.224 L 而漏掉过量部分溶解的 4.26 L。"}],"cheatSheet":["CO₂ 制取用石灰石 + **稀盐酸**（忌用稀硫酸生微溶 CaSO₄ 阻隔）；检验用澄清石灰水（过量变清）。","制碱口诀：**先通氨（极易溶呈碱），后通碳（大量吸生成 HCO₃⁻）**；侯氏加 NaCl 降温析 NH₄Cl 肥提高利用率。","制电石（\\(\\mathrm{CaO + 3C \\to CaC_2 + CO}\\)）与制金刚砂（\\(\\mathrm{SiO_2 + 3C \\to SiC + 2CO}\\)）副产气体皆为 **CO**；SiC 中 C 既是氧化剂又是还原剂（1 : 2）。","四大燃料：天然气（\\(\\mathrm{CH_4}\\)）、水煤气（\\(\\mathrm{CO+H_2}\\)）、发生炉煤气（\\(\\mathrm{CO+N_2}\\)）、石油气（\\(\\mathrm{C_3H_8/C_4H_{10}}\\)）。"],"kbEntryIds":["kb-chem12-co-co2","kb-chem12-solvay-hou","kb-chem12-carbides-fuels"],"quiz":{"q":"如何除去 \\(\\mathrm{CO_2}\\) 气体中混有的少量 \\(\\mathrm{CO}\\) 气体杂质？能否直接点燃除去？","given":"混合气体：CO₂（主）+ CO（少量杂质）","method":"利用灼热金属氧化物氧化 CO 为 CO₂ 而不增加新杂质","principle":"CO + CuO —(△)→ Cu + CO₂；混合气中大量 CO₂ 不助燃导致少量 CO 点不着。","steps":["不能直接点燃（大量 \\(\\mathrm{CO_2}\\) 环境下少量 \\(\\mathrm{CO}\\) 无法燃烧）。","正确方法：将混合气体缓慢通过**灼热的氧化铜（\\(\\mathrm{CuO}\\)）粉末**，发生 \\(\\mathrm{CO + CuO} \\xrightarrow{\\Delta} \\mathrm{Cu + CO_2}\\)，把杂质 \\(\\mathrm{CO}\\) 转化为纯净的 \\(\\mathrm{CO_2}\\)。"],"ans":"通过灼热的 CuO 粉末（不能直接点燃）。"}},{"id":"12.3","t":"硅和它的重要化合物","anchor":{"pages":"化上 p.284–291","syllabus":"3.6.8–3.6.10 硅的结构性质制备、二氧化硅、水玻璃与硅酸盐工业（陶瓷、玻璃、水泥）","examScopes":["sem2_final","uec"],"examWeight":"P1 原子晶体对比/试剂瓶保存/硅酸盐原料 + P2 工业制硅计算与框图推断","terms":"Crystalline silicon · Semiconductor · Silicon dioxide (SiO₂) · Hydrofluoric acid · Water glass · Silicate industry","prerequisites":["原子晶体结构特征及化学键比较（化上 Ch 7.3）","IVA 族非金属性递变规律（12.1）"],"goals":["掌握晶体硅的原子晶体结构、高熔沸点（1410 ℃）及半导体应用，并写出碳还原二氧化硅制粗硅的方程式及氧化还原比例。","对比 SiO₂（1:2 空间网状原子晶体）与 CO₂（分子晶体）的物理性质差异，牢记 SiO₂ 与 HF（刻蚀玻璃）和 NaOH（橡皮塞）的特征反应。","了解水玻璃（Na₂SiO₃）的性质与存放，以及陶瓷、普通玻璃、水泥的原料、核心反应和产品差异。"]},"concepts":[{"kind":"definition","title":"12.3.1 硅的结构、物理化学性质及工业制备","pageRef":"化上 p.285–286、p.296","body":["**存在与丰度**：硅在地壳中含量约为 **26%**（26.30%），在所有元素中**排第二位**（仅次于氧）。硅亲氧性极强，自然界**没有游离态单质**，全部以二氧化硅（石英、玛瑙、沙子）和硅酸盐（高岭土、滑石、正长石、锆石，图 12-23~26）存在。","**结构与物理性质（图 12-27）**：晶体硅是灰黑色、有金属光泽、质硬而脆的**原子晶体**，熔点 **1410 ℃**，沸点 **2355 ℃**。结构与金刚石相似，每个硅原子与另外 4 个硅原子形成 4 个共价单键成正四面体网状结构。硅是优良的**半导体材料**（用于电脑芯片与太阳能电池板，图 12-21~22）。","**化学性质与制备**：常温下较稳定，**除氟气（\\(\\mathrm{F_2}\\)）、氢氟酸（\\(\\mathrm{HF}\\)）和强碱溶液外**，很难与氧气、氯气、硫酸、硝酸反应；加热时能与 \\(\\mathrm{O_2, Cl_2}\\) 反应（\\(\\mathrm{Si + O_2} \\xrightarrow{\\Delta} \\mathrm{SiO_2}\\)；\\(\\mathrm{Si + 2Cl_2} \\xrightarrow{\\text{高温}} \\mathrm{SiCl_4(l)}\\)）。工业用焦炭高温还原石英砂制取粗硅：\\(\\mathrm{SiO_2(s) + 2C(s)} \\xrightarrow{\\text{高温}} \\mathrm{Si(s) + 2CO(g)}\\uparrow\\)（其中氧化剂 \\(\\mathrm{SiO_2}\\) 与还原剂 \\(\\mathrm{C}\\) 的物质的量之比为 **1 : 2**，产物是 **CO** 而非 \\(\\mathrm{CO_2}\\)！）。"],"takeaway":"工业制粗硅反应 SiO₂ + 2C —(高温)→ Si + 2CO↑ 务必记住两考点：①气体产物写 CO；②氧化剂与还原剂之比为 1 : 2。"},{"kind":"mechanism","title":"12.3.2 二氧化硅（SiO₂）结构特征反应（HF/NaOH）与水玻璃（Na₂SiO₃）","pageRef":"化上 p.286–289","body":["**为什么 \\(\\mathrm{SiO_2}\\) 是高熔点固体而 \\(\\mathrm{CO_2}\\) 是气体？（p.287 问题解决）**：\\(\\mathrm{SiO_2}\\) 晶体（图 12-30）是每个 Si 周围连 4 个 O、每个 O 连 2 个 Si 构成的 **1:2 空间网状原子晶体**，晶体中**不存在独立的 \\(\\mathrm{SiO_2}\\) 分子**，熔化须破坏极强的 \\(\\mathrm{Si-O}\\) 共价键，故熔沸点极高、硬度大；而 \\(\\mathrm{CO_2}\\) 是**分子晶体**，分子间仅靠微弱的范德华力结合，故常温呈气态。","**二氧化硅特征反应（极重要！）**：常温下 \\(\\mathrm{SiO_2}\\) 不溶于水也不与一般强酸（如硫酸、盐酸、浓硝酸）反应，但能与以下两类物质反应：","- ① **与氢氟酸反应（唯一能溶 \\(\\mathrm{SiO_2}\\) 的酸）**：\\(\\mathrm{SiO_2(s) + 4HF(aq) \\longrightarrow SiF_4(g)\\uparrow + 2H_2O(l)}\\) → 工业用于**在玻璃仪器上刻字做标记**，同时决定**氢氟酸绝对不能用玻璃瓶盛放，必须用塑料瓶**（p.294 题 9）！","- ② **与强碱/碱性氧化物反应（酸性氧化物通性）**：常温缓慢与强碱液反应 \\(\\mathrm{SiO_2 + 2NaOH \\to Na_2SiO_3 + H_2O}\\)（故**烧碱溶液瓶不可用玻璃塞，必用橡皮塞**，p.286 感知生活）；高温与 \\(\\mathrm{CaO}\\) 共熔 \\(\\mathrm{SiO_2 + CaO} \\xrightarrow{\\text{高温}} \\mathrm{CaSiO_3}\\)。","**重要应用（p.287–289）**：高纯度石英玻璃熔体拉制**光导纤维**（图 12-31~32，互联网通信与医用内窥镜，主要成分即 **\\(\\mathrm{SiO_2}\\)**）；**水玻璃**是可溶性硅酸钠（\\(\\mathrm{Na_2SiO_3}\\)）的水溶液，不燃耐腐作矿物胶与**木材防火剂**，暴露空气中易吸 \\(\\mathrm{CO_2}\\) 变浑浊析出硅酸胶体：\\(\\mathrm{Na_2SiO_3 + CO_2 + H_2O \\to Na_2CO_3 + H_2SiO_3\\downarrow}\\)（证明酸性 \\(\\mathrm{H_2CO_3 > H_2SiO_3}\\)，p.291 思考题 12c-3）。"],"takeaway":"实验室试剂瓶两大特殊禁忌：①氢氟酸用**塑料瓶**装；②烧碱、纯碱、水玻璃等碱性溶液用玻璃瓶配**橡皮塞**（不用玻璃塞）！"},{"kind":"table","title":"12.3.3 三大传统硅酸盐工业：陶瓷、玻璃与水泥对比","pageRef":"化上 p.289–291","body":["以含硅物质（硅石、硅酸盐矿物等）为原料经高温加热制成硅酸盐产品的工业称为**硅酸盐工业（silicate industry）**。记住：三大产品的原料、关键添加剂及普通玻璃两步高温反应！"],"table":{"headers":["硅酸盐产品","主要原料","核心制备反应 / 工艺特点","成分特性与分类延伸"],"rows":[["陶瓷","普通陶瓷：**高岭土**等黏土天然硅酸盐","成型后高温烧结而成","**精密陶瓷**（特种陶瓷）还用 \\(\\mathrm{Al_2O_3, ZrO_2, SiC, Si_3N_4}\\) 等高纯粉末制人工骨骼与耐高温陶瓷发动机"],["普通玻璃","**纯碱（\\(\\mathrm{Na_2CO_3}\\)）、石灰石（\\(\\mathrm{CaCO_3}\\)）、石英（\\(\\mathrm{SiO_2}\\)）**","\\(\\mathrm{SiO_2 + Na_2CO_3} \\xrightarrow{\\text{高温}} \\mathrm{Na_2SiO_3 + CO_2\\uparrow}\\)\n\\(\\mathrm{SiO_2 + CaCO_3} \\xrightarrow{\\text{高温}} \\mathrm{CaSiO_3 + CO_2\\uparrow}\\)","成分为 \\(\\mathrm{Na_2SiO_3, CaSiO_3}\\) 与 \\(\\mathrm{SiO_2}\\) 熔合的玻璃态物质（非晶体，无固定熔点）；功能玻璃有钢化/光致变色玻璃"],["水泥","**石灰石和黏土**（熟化后加**石膏**研磨）","石灰石与黏土高温煅烧熟料，加石膏调节硬化速度；遇水生成水合物硬化","水泥+沙+水=水泥砂浆；+碎石=混凝土；+钢筋=钢筋混凝土（图 12-35）"]]},"takeaway":"玻璃和水泥都需要用**石灰石（CaCO₃）**（p.294 题 11）；生产水泥时加入**石膏**以调节水泥的硬化速度；**硅单质**不是制水泥的原料（p.294 题 10D）！"}],"formulas":[{"title":"二氧化硅特征反应（与 HF、NaOH、焦炭反应）","tex":"\\mathrm{SiO_2(s)} + 4\\mathrm{HF(aq)} \\longrightarrow \\mathrm{SiF_4(g)}\\uparrow + 2\\mathrm{H_2O(l)},\\qquad \\mathrm{SiO_2(s)} + 2\\mathrm{C(s)} \\xrightarrow{\\text{高温}} \\mathrm{Si(s)} + 2\\mathrm{CO(g)}\\uparrow","plain":"SiO2+4HF→SiF4↑+2H2O; SiO2+2C—(高温)→Si+2CO↑","conditions":"HF 唯一刻蚀玻璃；制粗硅产物为 CO，氧化剂与还原剂比 1 : 2","pageRef":"化上 p.285、p.287","note":"SiO₂ 与强碱反应：SiO₂ + 2NaOH → Na₂SiO₃ + H₂O；在高温熔融下也可与 Na₂CO₃ 反应释放 CO₂。"},{"title":"普通玻璃高温反应及水玻璃变质方程","tex":"\\mathrm{SiO_2(s)} + \\mathrm{Na_2CO_3(s)} \\xrightarrow{\\text{高温}} \\mathrm{Na_2SiO_3(s)} + \\mathrm{CO_2(g)}\\uparrow,\\qquad \\mathrm{Na_2SiO_3(aq)} + \\mathrm{CO_2(g)} + \\mathrm{H_2O(l)} \\longrightarrow \\mathrm{Na_2CO_3(aq)} + \\mathrm{H_2SiO_3(s)}\\downarrow","plain":"SiO2+Na2CO3—(高温)→Na2SiO3+CO2↑; Na2SiO3+CO2+H2O→Na2CO3+H2SiO3↓","conditions":"前式高温固相驱动 CO₂ 气体逸出（非强酸制弱酸）；后式水溶液遵循强酸制弱酸（H₂CO₃ > H₂SiO₃）","pageRef":"化上 p.290–291","note":"对比两式：高温下高沸点 SiO₂ 反而能制出低沸点气体 CO₂，是因为气体逸出推动反应向右，不违背水溶液酸性强弱律！"}],"pitfalls":[{"title":"误以为高温制玻璃反应违背“H₂CO₃ 酸性强于 H₂SiO₃”","wrong":"“玻璃熔炉中 \\(\\mathrm{SiO_2 + Na_2CO_3} \\xrightarrow{\\text{高温}} \\mathrm{Na_2SiO_3 + CO_2}\\uparrow\\) 说明硅酸的酸性比碳酸强。”","diagnosis":"混淆了**水溶液中的酸碱强弱**与**高温固相挥发平衡驱动**。","right":"在水溶液中确实是酸性 \\(\\mathrm{H_2CO_3 > H_2SiO_3}\\)（故水玻璃吸 \\(\\mathrm{CO_2}\\) 析出 \\(\\mathrm{H_2SiO_3}\\) 沉淀）；而在高温熔炉（无水环境）中，生成的 \\(\\mathrm{CO_2}\\) 不断气化逸出而 \\(\\mathrm{SiO_2}\\) 难挥发，依靠平衡移动使高沸点氧化物取代挥发性气体氧化物。","checkRule":"比较非金属最高价含氧酸酸性强弱（如 \\(\\mathrm{H_2CO_3}\\) vs \\(\\mathrm{H_2SiO_3}\\)），必须看**水溶液中**的复分解反应！"},{"title":"误把硅酸（H₂SiO₃）写成 SiO₂ 直接溶于水制得","wrong":"“把石英砂（\\(\\mathrm{SiO_2}\\)）放入热水中充分搅拌，即可溶解得到硅酸 \\(\\mathrm{H_2SiO_3}\\)。”","diagnosis":"\\(\\mathrm{SiO_2}\\) 虽然是硅酸的酸酐（酸性氧化物），但它属于坚固原子晶体，极难溶于水且不与水直接化合。","right":"\\(\\mathrm{SiO_2}\\) 不溶于水也不与水反应；制备 \\(\\mathrm{H_2SiO_3}\\) 必须先将 \\(\\mathrm{SiO_2}\\) 转化为可溶性 \\(\\mathrm{Na_2SiO_3}\\)，再加酸（如盐酸或通 \\(\\mathrm{CO_2}\\)）复分解沉淀析出（类比 \\(\\mathrm{Al_2O_3}\\) 制 \\(\\mathrm{Al(OH)_3}\\)）。","checkRule":"牢记两大“不溶于水也不与水反应”的对应氧化物：\\(\\mathrm{Al_2O_3}\\) 与 \\(\\mathrm{SiO_2}\\)。"}],"examples":[{"label":"例 12.3.1","tier":"L3","tierLabel":"L3 框图推断","title":"教材 p.296 硅及其化合物五元转化框图（A–E）推断","prompt":"（教材 p.296 作答题 9）某高熔点固体物质 A，与纯碱（\\(\\mathrm{Na_2CO_3}\\)）在高温下熔融生成 B 并放出气体 C；将气体 C 通入 B 的水溶液中又重新生成纯碱和白色胶状化合物 D；化合物 D 很不稳定，在干燥空气中失水变成 E，加热 E 又进一步失水变回原物质 A。(1) 试推断 A、B、C、D、E 各是什么物质并写出化学式；(2) 写出 ① A 与纯碱反应 和 ② C 与 B 溶液反应的化学方程式。","clues":"高熔点固体与纯碱高温熔融放气体，且生成的溶液反通入该气体又析出可两次脱水的白色胶状物（正硅酸/原硅酸 \\(\\mathrm{H_4SiO_4}\\) → 硅酸 \\(\\mathrm{H_2SiO_3}\\) → \\(\\mathrm{SiO_2}\\)）！","strategy":"锁定高熔点 A = \\(\\mathrm{SiO_2}\\) → 熔融产物 B = \\(\\mathrm{Na_2SiO_3}\\)、气体 C = \\(\\mathrm{CO_2}\\) → 根据两次连续失水确定 D 为原硅酸 \\(\\mathrm{H_4SiO_4}\\)、E 为硅酸 \\(\\mathrm{H_2SiO_3}\\)。","given":"A 高熔点；A + Na₂CO₃ —(高温)→ B + C↑；C + B(aq) → Na₂CO₃ + D；D —(干燥空气失水)→ E —(△失水)→ A","principle":"SiO₂ 高温制硅酸盐反应；强酸制弱酸析出 H₄SiO₄，两步脱水成 H₂SiO₃ 与 SiO₂。","steps":["(1) 物质推断：A 是 **\\(\\mathrm{SiO_2}\\)**，B 是 **\\(\\mathrm{Na_2SiO_3}\\)**，C 是 **\\(\\mathrm{CO_2}\\)**；D 在干燥空气中即失水变成 E，加热 E 再失水变成 \\(\\mathrm{SiO_2}\\)，故 D 是原硅酸 **\\(\\mathrm{H_4SiO_4}\\)**，E 是硅酸 **\\(\\mathrm{H_2SiO_3}\\)**（\\(\\mathrm{H_4SiO_4 \\to H_2SiO_3 + H_2O}\\)；\\(\\mathrm{H_2SiO_3 \\xrightarrow{\\Delta} SiO_2 + H_2O}\\)）。","(2) 化学方程式：","- ① A 与纯碱反应：\\(\\mathrm{SiO_2(s) + Na_2CO_3(s)} \\xrightarrow{\\text{高温}} \\mathrm{Na_2SiO_3(s) + CO_2(g)}\\uparrow\\)","- ② C 与 B 溶液反应（若生成原硅酸或硅酸，对应写出）：\\(\\mathrm{CO_2(g) + Na_2SiO_3(aq) + 2H_2O(l) \\longrightarrow Na_2CO_3(aq) + H_4SiO_4(s)}\\downarrow\\)（或写生成 \\(\\mathrm{H_2SiO_3\\downarrow}\\) 配 \\(1\\mathrm{H_2O}\\)，按两步脱水 D 写 \\(\\mathrm{H_4SiO_4}\\) 最严谨！）。"],"answer":"(1) A: SiO₂, B: Na₂SiO₃, C: CO₂, D: H₄SiO₄, E: H₂SiO₃；(2) ① SiO₂+Na₂CO₃—(高温)→Na₂SiO₃+CO₂↑；② CO₂+Na₂SiO₃+2H₂O→Na₂CO₃+H₄SiO₄↓。","markingPoints":["正确推断出 A, B, C 分别为 SiO₂, Na₂SiO₃, CO₂（2分）","依据两级脱水推断出 D 为 H₄SiO₄、E 为 H₂SiO₃（2分）","正确配平反应 ① 和 ②（2分）"],"verification":"对照化上 p.296 作答题 9 题干“D 在干燥空气失水成 E，加热 E 又失水成 A”，\\(\\mathrm{H_4SiO_4 \\xrightarrow{-H_2O} H_2SiO_3 \\xrightarrow{-H_2O} SiO_2}\\) 完全吻合。","pitfall":"若把 D 直接猜成 \\(\\mathrm{H_2SiO_3}\\)，那么 E 就无法再写出另一个含水硅酸中间体而只能直接脱水成 \\(\\mathrm{SiO_2}\\)，漏掉原硅酸 \\(\\mathrm{H_4SiO_4}\\)。"},{"label":"例 12.3.2","tier":"L4","tierLabel":"L4 统考压轴","title":"普通玻璃氧化物组成比例计算与制粗硅/金刚砂尾气处理（p.295 题 6 & p.296 题 8）","prompt":"(1)（教材 p.295 题 6）某种普通钠钙玻璃经测定含有质量分数 \\(13.0\\%\\) 的 \\(\\mathrm{Na_2O}\\)、\\(11.7\\%\\) 的 \\(\\mathrm{CaO}\\) 和 \\(75.3\\%\\) 的 \\(\\mathrm{SiO_2}\\)。试计算该玻璃中三种氧化物的**物质的量之比**并写出以氧化物形式表示的化学组成式（\\(M: \\mathrm{Na_2O}=62, \\mathrm{CaO}=56, \\mathrm{SiO_2}=60\\)）。(2)（教材 p.296 题 8-(4)）工业制粗硅和金刚砂时均产生大量 \\(\\mathrm{CO}\\) 气体，从环境保护和资源再利用角度看，应采取什么理想措施？","clues":"用各自质量百分比除以各自摩尔质量（\\(n = w / M\\)），再化为最简整数比；\\(\\mathrm{CO}\\) 是高热值可燃气体与化工原料！","strategy":"取 \\(100\\text{ g}\\) 玻璃计算各氧化物摩尔数 → 同除以最小摩尔数化简整数比。","given":"w(Na₂O)=13.0%, w(CaO)=11.7%, w(SiO₂)=75.3%","principle":"元素组成最简摩尔比法及 CO 气体燃料/还原剂回收利用。","steps":["第(1)问：取 \\(100\\text{ g}\\) 该普通玻璃，计算各氧化物的物质的量：","- \\(n(\\mathrm{Na_2O}) = \\frac{13.0}{62} \\approx 0.210\\text{ mol}\\)","- \\(n(\\mathrm{CaO}) = \\frac{11.7}{56} \\approx 0.209\\text{ mol}\\)","- \\(n(\\mathrm{SiO_2}) = \\frac{75.3}{60} = 1.255\\text{ mol}\\)","三者同时除以最小的 \\(0.209\\)：\\(n(\\mathrm{Na_2O}) : n(\\mathrm{CaO}) : n(\\mathrm{SiO_2}) \\approx 1.00 : 1.00 : 6.00\\)（即 **1 : 1 : 6**）。","因此其氧化物形式可写作：**\\(\\mathrm{Na_2O \\cdot CaO \\cdot 6SiO_2}\\)**（即对应 \\(\\mathrm{Na_2SiO_3 \\cdot CaSiO_3 \\cdot 4SiO_2}\\)）。","第(2)问：工业制粗硅与金刚砂副产的大量 \\(\\mathrm{CO}\\) 有毒且直接排放浪费能源，理想的附加措施是：**收集净化副产的 \\(\\mathrm{CO}\\) 气体，将其燃烧放热用作预热原料/发电燃料（或作为化工原料合成甲醇等有机物）**，严禁直接排空造成中毒与污染。"],"answer":"(1) 物质的量之比为 1 : 1 : 6，组成式 \\(\\mathrm{Na_2O\\cdot CaO\\cdot 6SiO_2}\\)；(2) 收集净化 CO 用作燃料供热或有机合成原料（绝不直接排放）。","markingPoints":["准确算出三种氧化物摩尔数 0.210, 0.209, 1.255 mol（2分）","化为最简整数比 1:1:6 并写出 Na₂O·CaO·6SiO₂（2分）","指出收集 CO 作燃料供热或合成原料以达环保节能（1分）"],"verification":"验证式量：62 + 56 + 6×60 = 478，\\(62/478 = 12.97\\%\\)、\\(56/478 = 11.72\\%\\)、\\(360/478 = 75.31\\%\\)，与题给 13.0%、11.7%、75.3% 完美契合！","pitfall":"算比值时若不小心把 \\(\\mathrm{Na_2O}\\) 式量错算成 46+16=62 没错，但有人误把 Na 算成 1 个（39），或者忘记化简 \\(1.255/0.209 \\approx 6\\)。"}],"practice":[{"id":"chem12-12.3-q1","tier":"L1","tierLabel":"L1 基础","examStyle":"P1 选择","q":"下列试剂中，**不能**用普通玻璃瓶盛放的是（　）。（p.294 教材题 9）","options":["A. 氢氟酸（\\(\\mathrm{HF}\\)）","B. 饱和碳酸钠溶液","C. 浓硫酸","D. 氢氧化钠溶液"],"correctOption":"A","given":"p.287 SiO₂+4HF 反应 & p.294 题 9","method":"区分“腐蚀玻璃瓶身（HF）”与“仅粘连玻璃瓶塞但可用橡皮塞玻璃瓶装（NaOH/Na₂CO₃）”","principle":"HF 剧烈腐蚀玻璃中的 SiO₂ 生成气态 SiF₄，故必须用塑料瓶盛放。","steps":["A（氢氟酸）剧烈溶解玻璃瓶壁，绝对不能用玻璃瓶盛放；B、D 碱性溶液虽会缓慢腐蚀磨口塞（需用橡皮塞），但仍可用玻璃瓶身盛放；C 浓硫酸不与玻璃反应。"],"ans":"A","markingPoints":["明确区分 HF 禁用玻璃瓶与强碱禁用玻璃塞"],"verification":"化上 p.294 选择题 9 原题。","pitfall":"误选 D——题目问的是“玻璃瓶”而不是“玻璃塞”！"},{"id":"chem12-12.3-q2","tier":"L2","tierLabel":"L2 期末","examStyle":"P1 选择","q":"下列关于硅和硅酸盐材料的用途与成分叙述中，**错误**的是（　）。（p.294 教材题 10–12 综合）","options":["A. 晶体硅是良好的半导体，用于制造太阳能电池和计算机芯片","B. 光导纤维的主要成分是高纯度的二氧化硅（\\(\\mathrm{SiO_2}\\)）","C. 生产普通玻璃和水泥的共同原料之一是石灰石（\\(\\mathrm{CaCO_3}\\)）","D. 大理石和水泥一样，主要成分都是硅酸盐"],"correctOption":"D","given":"p.285–290 硅材料与硅酸盐工业","method":"逐项比对芯片、光纤、玻璃/水泥原料及大理石成分","principle":"大理石的主要成分是碳酸钙（CaCO₃），不是硅酸盐！","steps":["A、B、C 均为教材原文重点事实；D 错误，大理石、石灰石成分是碳酸钙，只有陶瓷、玻璃、水泥是硅酸盐产品。"],"ans":"D","markingPoints":["区分碳酸钙矿物与硅酸盐工业产品"],"verification":"化上 p.294 题 10、11、12 综合印证。","pitfall":"误把同样用作建筑材料的大理石归入硅酸盐。"},{"id":"chem12-12.3-q3","tier":"L2","tierLabel":"L2 期末","examStyle":"P1 选择","q":"下列各组物质之间，在指定条件下**不能**发生化学反应的是（　）。（p.291 思考题 12c-2）","options":["A. 二氧化硅与氧化钙（高温）","B. 二氧化硅与氢氧化钠溶液（常温）","C. 二氧化硅与碳（高温）","D. 二氧化硅与浓硝酸（常温）"],"correctOption":"D","given":"p.291 思考题 12c-2 原题","method":"比对 SiO₂ 的酸性氧化物性质、碳还原性及耐一般强酸腐蚀性","principle":"除氢氟酸外，SiO₂ 不与任何一般酸（包括浓硝酸、浓硫酸、盐酸）反应。","steps":["A：SiO₂ + CaO —(高温)→ CaSiO₃；B：SiO₂ + 2NaOH → Na₂SiO₃ + H₂O；C：SiO₂ + 2C —(高温)→ Si + 2CO↑；D：常温浓硝酸不与 SiO₂ 反应。"],"ans":"D","markingPoints":["掌握 SiO₂ 仅与 HF 反应而不与其它酸反应"],"verification":"化上 p.291 思考题 12c-2 原题。","pitfall":"误以为强氧化性浓硝酸能氧化或溶解 SiO₂。"},{"id":"chem12-12.3-q4","tier":"L3","tierLabel":"L3 预试","examStyle":"P2 简答","q":"(1) 石英砂（主要成分 \\(\\mathrm{SiO_2}\\)）中混有少量碳酸钙（\\(\\mathrm{CaCO_3}\\)），应选用什么试剂和方法除去杂质？请写出反应方程式并说明为什么不能用稀硫酸；(2) 水玻璃（\\(\\mathrm{Na_2SiO_3}\\) 溶液）若长期敞口暴露在空气中会变浑浊产生白色胶状沉淀，请结合元素周期律比较碳和硅的非金属性强弱，并写出变质反应的化学方程式。","given":"p.291 思考题 12c-1、3 & p.295 题 13","method":"稀盐酸溶 CaCO₃ 过滤除杂；用 H₂CO₃ > H₂SiO₃ 解释水玻璃吸 CO₂ 析胶","principle":"CaCO₃ + 2HCl → CaCl₂ + H₂O + CO₂↑；Na₂SiO₃ + CO₂ + H₂O → Na₂CO₃ + H₂SiO₃↓。","steps":["(1) 选用**足量稀盐酸**溶解后**过滤、洗涤、干燥**即得纯净石英砂：\\(\\mathrm{CaCO_3(s) + 2HCl(aq) \\to CaCl_2(aq) + H_2O(l) + CO_2(g)}\\uparrow\\)（\\(\\mathrm{SiO_2}\\) 不溶于稀盐酸）。不能用稀硫酸，因为生成的 \\(\\mathrm{CaSO_4}\\) 微溶于水会覆盖在 \\(\\mathrm{CaCO_3}\\) 表面阻止反应进行且会混入滤渣杂质。","(2) C 与 Si 同属 IVA 族且 C 在 Si 上方，非金属性 **C > Si**，故最高价含氧酸酸性 **\\(\\mathrm{H_2CO_3 > H_2SiO_3}\\)**。水玻璃吸收空气中 \\(\\mathrm{CO_2}\\) 发生强酸制弱酸反应析出白色难溶硅酸胶体：\\(\\mathrm{Na_2SiO_3(aq) + CO_2(g) + H_2O(l) \\longrightarrow Na_2CO_3(aq) + H_2SiO_3(s)}\\downarrow\\)（若 \\(\\mathrm{CO_2}\\) 过量还可生成 \\(\\mathrm{NaHCO_3}\\)）。"],"ans":"(1) 稀盐酸溶解后过滤洗涤（不用稀硫酸因生成微溶 CaSO₄ 混入杂质）；(2) 非金属性 C > Si ⇒ 酸性 H₂CO₃ > H₂SiO₃，Na₂SiO₃ + CO₂ + H₂O → Na₂CO₃ + H₂SiO₃↓。","markingPoints":["选用稀盐酸过滤并说明禁用稀硫酸原因（2分）","从周期律非金属性推酸性 H₂CO₃ > H₂SiO₃ 并写出变质方程式（3分）"],"verification":"化上 p.291 与 p.295 第 13 题、第 1 题全面对接。","pitfall":"第(1)问漏掉“过滤、洗涤、干燥”分离操作步骤。"},{"id":"chem12-12.3-q5","tier":"L4","tierLabel":"L4 统考压轴","examStyle":"P2 综合计算","q":"工业上采用焦炭在电炉中高温还原石英砂（\\(\\mathrm{SiO_2}\\)）来生产粗硅：\\(\\mathrm{SiO_2(s) + 2C(s)} \\xrightarrow{\\text{高温}} \\mathrm{Si(s) + 2CO(g)}\\uparrow\\)，再将粗硅用氯气氯化生成 \\(\\mathrm{SiCl_4}\\)（经分馏提纯后用氢气还原制取高纯电子级多晶硅）。现用 \\(150\\text{ kg}\\) 含二氧化硅 \\(80.0\\%\\) 的石英砂（其余杂质不与焦炭反应）与足量焦炭充分反应：(1) 该反应中氧化剂与还原剂的物质的量之比是多少？(2) 理论上最多可制得粗硅中纯硅多少千克？同时放出标准状况下 \\(\\mathrm{CO}\\) 气体多少立方米？（\\(A_r: \\mathrm{Si}=28, \\mathrm{O}=16\\)）(3) 若所制得的纯硅在后续提纯过程中有 \\(10\\%\\) 的损耗（总产率 \\(90\\%\\)），实际能获得多少千克高纯晶体硅？","given":"m(石英砂)=150 kg, w(SiO₂)=80.0%, M(SiO₂)=60 g/mol, 收率=90%","method":"先算纯 SiO₂ 物质的量，再按 1:1 算纯 Si 与 1:2 算 CO 体积，最后乘产率 90%","principle":"SiO₂ + 2C —(高温)→ Si + 2CO↑；1 kmol 标况气体 = 22.4 m³。","steps":["第(1)问：反应中 \\(\\mathrm{SiO_2}\\) 中 Si 由 +4 降为 0 价作**氧化剂**，\\(\\mathrm{C}\\) 由 0 升为 +2 价作**还原剂**，二者物质的量之比为 **1 : 2**。","第(2)问：石英砂中纯 \\(\\mathrm{SiO_2}\\) 质量 \\(= 150 \\times 80.0\\% = 120\\text{ kg} = 1.20 \\times 10^5\\text{ g}\\)。","\\(n(\\mathrm{SiO_2}) = \\frac{1.20 \\times 10^5}{60} = 2.00 \\times 10^3\\text{ mol} = 2.00\\text{ kmol}\\)。","由计量比 \\(1:1:2\\)，理论可制得纯硅 \\(n(\\mathrm{Si}) = 2.00\\text{ kmol}\\)，质量 \\(m(\\mathrm{Si}) = 2.00 \\times 28 = 56.0\\text{ kg}\\)；","理论产生 \\(n(\\mathrm{CO}) = 2 \\times 2.00 = 4.00\\text{ kmol}\\)，标况体积 \\(V(\\mathrm{CO}) = 4.00 \\times 22.4 = 89.6\\text{ m}^3\\)。","第(3)问：计入 \\(90\\%\\) 总收率后，实际可得高纯硅质量 \\(= 56.0 \\times 90\\% = 50.4\\text{ kg}\\)。"],"ans":"(1) 1 : 2；(2) 理论纯硅 56.0 kg，标况 CO 89.6 m³；(3) 实际获高纯硅 50.4 kg。","markingPoints":["正确判断氧化剂 SiO₂ 与还原剂 C 为 1:2（1分）","算出纯 SiO₂ 2.00 kmol 并求得理论硅 56.0 kg 及 CO 89.6 m³（3分）","乘以产率 90% 求得实际高纯硅 50.4 kg（1分）"],"verification":"单位校验：kmol × 28 kg/kmol = kg；kmol × 22.4 m³/kmol = m³，数值无数量级偏差。","pitfall":"第(1)问注意区分“制粗硅（1:2）”与“制金刚砂 SiC（C 内部 1:2）”中各自真正的氧化剂是谁。"}],"cheatSheet":["\\(\\mathrm{SiO_2}\\)（1:2 原子晶体，高熔点无独立分子） vs \\(\\mathrm{CO_2}\\)（分子晶体，常温气体）。","\\(\\mathrm{SiO_2}\\) 两大特征反应：①\\(\\mathrm{SiO_2 + 4HF \\to SiF_4\\uparrow + 2H_2O}\\)（**塑料瓶**装 HF）；②\\(\\mathrm{SiO_2 + 2NaOH \\to Na_2SiO_3 + H_2O}\\)（碱瓶用**橡皮塞**）。","制粗硅：\\(\\mathrm{SiO_2 + 2C} \\xrightarrow{\\text{高温}} \\mathrm{Si + 2CO}\\uparrow\\)（氧化剂 : 还原剂 = 1 : 2）；水玻璃在空气中吸 \\(\\mathrm{CO_2}\\) 析 \\(\\mathrm{H_2SiO_3\\downarrow}\\)。","硅酸盐三大工业：陶瓷（黏土）、玻璃（**纯碱、石灰石、石英**）、水泥（**石灰石、黏土** + 石膏调凝）。"],"kbEntryIds":["kb-chem12-si-sio2","kb-chem12-silicate-industry"],"diagrams":[{"src":"assets/fig/v2/chem12-c-si-compare.svg","caption":"图 12-1 金刚石、石墨与二氧化硅晶体结构及碳硅核心性质转化对比","alt":"金刚石/晶体硅正四面体、石墨层状与二氧化硅1:2网状结构及碳硅重要反应对比图","pageRef":"化上 p.269–288"}],"quiz":{"q":"高纯二氧化硅是制造光导纤维的原料。为什么在常温下 \\(\\mathrm{SiO_2}\\) 不与盐酸、浓硫酸和浓硝酸反应，却必须绝对避免与氢氟酸接触？","given":"SiO₂ 化学稳定性与氢氟酸刻蚀反应","method":"写出 SiO₂ 与 HF 反应生成挥发性 SiF₄ 气体的化学方程式","principle":"SiO₂ + 4HF → SiF₄↑ + 2H₂O。","steps":["\\(\\mathrm{SiO_2}\\) 是结构极其稳固的原子晶体，常温下耐水及一般强酸腐蚀；","但它能与氢氟酸剧烈反应生成极易挥发的气态四氟化硅：\\(\\mathrm{SiO_2(s) + 4HF(aq) \\to SiF_4(g)\\uparrow + 2H_2O(l)}\\)，从而破坏光纤或玻璃结构。"],"ans":"因为 \\(\\mathrm{SiO_2}\\) 能与 \\(\\mathrm{HF}\\) 发生反应 \\(\\mathrm{SiO_2 + 4HF \\to SiF_4\\uparrow + 2H_2O}\\) 而被迅速腐蚀溶解。"}}]},"化学13":{"lessonKey":"化学13","courseCode":"chemistry","subject":"化学","chapter":13,"title":"VA族元素：氮和磷","syllabus":"3.7 VA族元素","bookId":"sm1-chemistry-2017","bookCitation":"《马来西亚华文独中教科书 · 化学（上册）》（2017年11月版）第13章 p.298–335","examScopes":["sem2_final","uec"],"chapterOverview":{"summary":"第13章围绕VA族两种核心非金属元素氮（N，−3 至 +5 价）和磷（P，0、+3、+5 价）展开：从氮气分子三键的惰性与固氮途径出发，串联氮的氧化物（NO、NO₂、N₂O）、硝酸的强氧化性与钝化、硝酸盐热分解三类规律及棕色环检验，再深入氨的喷泉实验、哈伯合成氨、铵盐性质与白磷/红磷/磷酸/磷肥，是统考无机化学大题与实验推断的绝对高频章。","conceptTree":[{"branch":"1. 氮气与氮氧化物（p.298–304）","items":["N≡N 三键稳态 · 放电/高温/固氮","NO（无色难溶易氧化）vs NO₂（红棕 2NO₂⇌N₂O₄）vs N₂O（笑气）","光化学烟雾 · 硝酸型酸雨 · 尾气催化转化"]},{"branch":"2. 硝酸与硝酸盐（p.305–314）","items":["见光分解 · 王水(1:3) · 冷浓硝酸钝化 Fe/Al","浓/稀硝酸 + Cu 氧化还原 · 实验室曲颈甑与奥斯特瓦尔德法","硝酸盐热分解三类规律（表13-4）· NO₃⁻ 棕色环检验"]},{"branch":"3. 氨气与铵盐（p.315–323）","items":["氢键易液化 · 喷泉实验(1:700) · NH₃·H₂O 弱碱性","NH₄Cl+Ca(OH)₂ 固固加热制氨（碱石灰干燥）· 哈伯法","铵盐热分解（化学变化）· 加碱加热检验 NH₄⁺"]},{"branch":"4. 磷及其重要化合物（p.323–328）","items":["白磷(P₄, 40℃自燃存水中) vs 红磷(240℃) 同素异形体","P₂O₅ + 冷/热水（偏磷酸 vs 正磷酸）· 工业 Ca₃(PO₄)₂ 制磷酸","普钙 · 重过磷酸钙 · 氮磷复合肥"]}]},"paperFocus":["下半年期末考 / UEC 统考卷一（30%）：重点考查 N₂/NH₃/NO/NO₂ 物理与收集方法辨析、浓/稀硝酸与金属反应产物及钝化判断、白磷红磷性质对照、铵盐与碘升华本质区别。","UEC 统考卷二甲部必答/探究（34%）及乙部无机选答（18%）：高频命制“氮元素价类转化推断框图题”、喷泉实验与氨气干燥装置改错探究题、硝酸与铜反应及 NO/NO₂ 通入水或 NaOH 的电子守恒定量计算、硝酸盐热分解及棕色环检验实验题。"],"solvingWorkflow":["先定中心元素价态：判断氮元素是处于 −3（NH₃/NH₄⁺）、0（N₂）、+2（NO）、+4（NO₂）还是 +5（HNO₃/NO₃⁻），快速定位氧化剂/还原剂方向。","遇到金属与硝酸反应计算：切忌只按 H⁺ 算！务必用得失电子守恒（如 1 mol NO₃⁻ → NO 得 3 mol e⁻，→ NO₂ 得 1 mol e⁻）并核对硝酸是否兼具“酸性（成盐）”与“氧化性（变气体）”。","实验装置与干燥剂审查：NH₃ 为碱性气体严禁用浓硫酸或无水 CaCl₂；NO 禁用排空气法；NO₂ 易溶于水且与水反应只能用向上排空气或冰盐冷却收集。","混合气体（NO、NO₂、O₂）溶于水定量计算：善用总反应 4NO₂ + O₂ + 2H₂O = 4HNO₃ 与 4NO + 3O₂ + 2H₂O = 4HNO₃ 一步判断过量与剩余气体体积。"],"questionTypes":["氮化合物“价—类”转化框图推断与工业流程（哈伯法、奥斯特瓦尔德法）","浓硝酸 vs 稀硝酸与铜、铁反应的实验现象、电子转移及氮原子守恒计算","喷泉实验压强分析、氨气实验室制法与除杂干燥改错探究","硝酸盐受热分解产物判断与混合气体（NO₂ + O₂）气体计量分析","NH₄⁺、NO₃⁻（棕色环）离子检验及白磷/红磷/磷酸/磷肥综合辨析"],"scoringNotes":["书写化学方程式务必注明反应条件（如光照、高温高压催化剂、Pt-Rh/Δ、浓/稀），漏写“浓”“稀”或条件在卷二常扣 0.5–1 分。","实验现象描述题须写全颜色、状态与试纸/溶液变化（如“红棕色气体、溶液呈蓝色”或“湿润红色石蕊试纸变蓝”，漏写“湿润”或错写“无水试纸”会扣分）。"],"vid":[{"t":"氮气、一氧化氮与二氧化氮转化计算","q":"氮的氧化物 NO NO2 与水反应 计算 高中化学"},{"t":"硝酸强氧化性、钝化与金属反应定量规律","q":"硝酸的强氧化性 铜与浓稀硝酸 计算 高中化学"},{"t":"氨气的喷泉实验、实验室制法与铵盐检验","q":"氨气的制取 喷泉实验 铵盐检验 高中化学"},{"t":"白磷红磷同素异形体及磷酸盐","q":"白磷 红磷 磷酸 磷肥 高中化学"}],"sections":[{"id":"13.1","t":"氮气","anchor":{"pages":"化上 p.298–301","syllabus":"3.7.1 VA族通性及氮气的结构、性质、制法与用途","examScopes":["sem2_final","uec"],"examWeight":"P1 概念辨析（N≡N 稳定性、固氮反应、液空分离）+ P2 基础方程式","terms":"nitrogen fixation · triple covalent bond · magnesium nitride · fractional distillation of liquid air","prerequisites":["共价三键的键能与分子稳定性（化上 Ch 7.1.2）","元素周期律同主族非金属性递变（化上 Ch 6.3）"],"goals":["结合表13-1 概述VA族元素最外层电子排布（ns²np³）及从非金属（N、P）到金属（Sb、Bi）的递变。","从氮氮三键（N≡N）角度解释氮气常温惰性，并写出高温/放电条件下与 H₂、O₂、Mg、Li 反应的方程式。","对比工业分离液态空气制氮与实验室亚硝酸钠+氯化铵溶液加热制氮的原理与收集方式。"]},"concepts":[{"kind":"table","title":"VA族（氮族）元素原子结构与主要性质（表13-1）","pageRef":"化上 p.298","body":["VA族位于周期表第15纵行，包括氮（N）、磷（P）、砷（As）、锑（Sb）、铋（Bi）和镆（Mc）。最外层均有 \\(5\\) 个电子（\\(ns^2np^3\\)），随核电荷数递增，原子半径增大，得电子能力减弱，非金属性减弱、金属性增强。"],"table":{"headers":["元素","原子序数","最外层排布","主要氧化数","状态与外观（常温）","密度 / \\(\\mathrm{kg\\,m^{-3}}\\)","熔/沸点（℃）"],"rows":[["氮（N）","7","\\(2s^2 2p^3\\)","−3, +1, +2, +3, +4, +5","无色气体","1.25","−210 / −196"],["磷（P）","15","\\(3s^2 3p^3\\)","−3, +3, +5","白磷（白/淡黄固体）；红磷（暗红粉）","1830（白）/ 2340（红）","44（白）/ 280（白沸）"],["砷（As）","33","\\(4s^2 4p^3\\)","−3, +3, +5","灰砷（灰色固体，准金属）","5727","818（高压）/ 615升华"],["锑（Sb）","51","\\(5s^2 5p^3\\)","+3, +5","银白色金属","6680","630 / 1635"],["铋（Bi）","83","\\(6s^2 6p^3\\)","+3, +5","银白微红金属","9780","271 / 1420"]]},"takeaway":"N 和 P 为典型非金属，As 呈准金属性，Sb 和 Bi 为金属，清晰体现同主族金属性递增规律。"},{"kind":"definition","title":"氮气分子的三键稳定性与高温化学反应","pageRef":"化上 p.299","body":["**物理性质**：纯净 \\(\\mathrm{N_2}\\) 是无色、无味气体，密度比空气稍小（\\(1.25\\text{ kg}\\cdot\\mathrm{m^{-3}}\\)），难溶于水（\\(1\\) 体积水仅溶解约 \\(0.02\\) 体积），液氮沸点 \\(-196\\ ^\\circ\\mathrm{C}\\)。","**结构决定稳定性**：氮分子结构式为 \\(\\mathrm{N\\equiv N}\\)，氮氮三键键能极大、极牢固，故常温下化学性质很不活泼。","**高温/高压/放电下的反应**：① 与 \\(\\mathrm{H_2}\\) 合成氨（\\(\\mathrm{N_2}\\) 作氧化剂）；② 雷电/高温下与 \\(\\mathrm{O_2}\\) 化合生成 \\(\\mathrm{NO}\\)（\\(\\mathrm{N_2}\\) 作还原剂）；③ 与活泼金属（Mg、Ca、Sr、Ba、Li）高温生成氮化物，如镁在空气中燃烧除生成 \\(\\mathrm{MgO}\\) 外还生成微量 \\(\\mathrm{Mg_3N_2}\\)，锂则生成 \\(\\mathrm{Li_3N}\\)。"],"takeaway":"氮气在氧气中不能“燃烧”（该反应吸热且需放电/极高温），且仅能被极高能量打断三键。"},{"kind":"experiment","title":"氮气的工业制法、实验室制法与低温用途","pageRef":"化上 p.300","body":["**工业制法（物理变化）**：先将空气加压降温液化，再缓慢升温分馏——因液态氮沸点（\\(-196\\ ^\\circ\\mathrm{C}\\)）低于液态氧沸点（\\(-183\\ ^\\circ\\mathrm{C}\\)），氮气先汽化蒸出，留下液氧。","**实验室制法（排水集气法）**：加热亚硝酸钠溶液与氯化铵溶液反应：\\(\\mathrm{NaNO_2(aq) + NH_4Cl(aq)} \\xrightarrow{\\Delta} \\mathrm{NaCl(aq) + N_2(g) + 2H_2O(l)}\\)；另可用氨气通过红热氧化铜(II)被氧化制氮：\\(\\mathrm{3CuO(s) + 2NH_3(g) \\longrightarrow 3Cu(s) + 3H_2O(l) + N_2(g)}\\)。","**主要用途**：① 工业合成氨与生产硝酸的原料；② 充作保护气（灯泡、食品防腐、化工防氧化）；③ 液氮作低温冷冻剂（超导材料低温测试、医学冷冻麻醉手术）。"],"takeaway":"实验室一般不用“铜网除空气中氧气”来制高纯氮气（空气还含约 1% 稀有气体与 CO₂），纯净 N₂ 常用 NaNO₂ + NH₄Cl 溶液共热制得。"}],"formulas":[{"title":"氮气与氧气、氢气、镁及锂的典型反应","tex":"\\mathrm{N_2(g) + O_2(g)} \\xrightarrow{\\text{高温、高压/放电}} \\mathrm{2NO(g)},\\qquad \\mathrm{3Mg(s) + N_2(g) \\longrightarrow Mg_3N_2(s)},\\qquad \\mathrm{6Li(s) + N_2(g) \\longrightarrow 2Li_3N(s)}","plain":"N2 + O2 --高温/放电--> 2NO; 3Mg + N2 -> Mg3N2; 6Li + N2 -> 2Li3N","conditions":"N₂ 与 O₂ 需放电或极高温且为可逆吸热；Mg、Li 在点燃或高温下直接化合","pageRef":"化上 p.299","note":"空气中点燃镁条时，主产物为 MgO，副产物为 Mg₃N₂（遇水可水解产生 NH₃）。"},{"title":"实验室制取氮气的两个反应方程式","tex":"\\mathrm{NaNO_2(aq) + NH_4Cl(aq)} \\xrightarrow{\\Delta} \\mathrm{NaCl(aq) + N_2(g) + 2H_2O(l)},\\qquad \\mathrm{3CuO(s,\\text{红热}) + 2NH_3(g) \\longrightarrow 3Cu(s) + 3H_2O(l) + N_2(g)}","plain":"NaNO2 + NH4Cl --Δ--> NaCl + N2 + 2H2O; 3CuO + 2NH3 -> 3Cu + 3H2O + N2","conditions":"前者温和加热并排水法收集；后者为 N 的归中/氨被氧化反应","pageRef":"化上 p.300","note":"两反应中氮元素化合价变化均为：+3/−3 → 0（归中）与 −3 → 0（氧化）。"}],"pitfalls":[{"title":"误认为氮气可以在氧气中“燃烧”","wrong":"“氮气和氧气混合点燃即可剧烈燃烧生成红棕色二氧化氮。”","diagnosis":"\\(\\mathrm{N_2 + O_2 \\to 2NO}\\) 是吸热反应，不能自发维持燃烧；且直接生成的是无色 \\(\\mathrm{NO}\\)，不是 \\(\\mathrm{NO_2}\\)。","right":"必须在闪电放电或内燃机极高温高压下生成 \\(\\mathrm{NO}\\)，随后 \\(\\mathrm{NO}\\) 遇空气再被氧化成 \\(\\mathrm{NO_2}\\)。","checkRule":"遇到“N₂ 在 O₂ 中燃烧直接得 NO₂”必属错项（教材思考题 13a 第2题B）。"},{"title":"用排空气法收集氮气","wrong":"“氮气难溶于水，也可直接用向上排空气法收集纯净氮气。”","diagnosis":"\\(M(\\mathrm{N_2}) = 28\\text{ g/mol}\\) 与空气平均摩尔质量 \\(29\\text{ g/mol}\\) 过于接近，排空气极易混入空气。","right":"实验室制取 \\(\\mathrm{N_2}\\) 应选用**排水集气法**（难溶于水且不与水反应）。","checkRule":"摩尔质量在 26–32 g/mol 之间（如 N₂=28、NO=30、CO=28）均不宜用排空气法。"}],"examples":[{"label":"例 13.1.1","tier":"L2","tierLabel":"L2 校内期末","title":"空气分馏原理与镁条在空气中燃烧产物定量分析","prompt":"(1) 工业上将空气液化后升温分馏分离氧气和氮气，哪一种气体先蒸出？原因是什么？(2) 将 \\(4.8\\text{ g}\\) 洁净镁条在空气中充分燃烧，若产物全部为 \\(\\mathrm{MgO}\\) 和 \\(\\mathrm{Mg_3N_2}\\)，测得固体总质量为 \\(7.6\\text{ g}\\)，试求产物中 \\(\\mathrm{Mg_3N_2}\\) 的质量。（相对原子质量：\\(\\mathrm{Mg}=24,\\ \\mathrm{N}=14,\\ \\mathrm{O}=16\\)）","clues":"(1) 比较沸点 \\(-196\\ ^\\circ\\mathrm{C}\\) 与 \\(-183\\ ^\\circ\\mathrm{C}\\)；(2) 利用镁原子守恒与质量方程。","strategy":"设产物中 MgO 与 Mg₃N₂ 的物质的量分别为 x, y mol，联立 Mg 守恒与总质量方程。","given":"m(Mg) = 4.8 g (0.20 mol)，产物总质量 = 7.6 g","principle":"液态混合物沸点低者先汽化；化学反应中 Mg 原子守恒。","steps":["(1) **氮气**先蒸出。因为标准大气压下液氮沸点（\\(-196\\ ^\\circ\\mathrm{C}\\)）比液氧沸点（\\(-183\\ ^\\circ\\mathrm{C}\\)）低，升温时氮气先达到沸点汽化。","(2) 参加反应的镁：\\(n(\\mathrm{Mg}) = \\frac{4.8\\text{ g}}{24\\text{ g}\\cdot\\mathrm{mol^{-1}}} = 0.20\\text{ mol}\\)。","设生成 \\(\\mathrm{MgO}\\) 为 \\(x\\text{ mol}\\)，\\(\\mathrm{Mg_3N_2}\\)（\\(M=100\\text{ g}\\cdot\\mathrm{mol^{-1}}\\)）为 \\(y\\text{ mol}\\)。","由 Mg 原子守恒：\\(x + 3y = 0.20\\)；由产物总质量：\\(40x + 100y = 7.6\\)。","将第一式乘以 40 得 \\(40x + 120y = 8.0\\)，减去第二式得 \\(20y = 0.40 \\implies y = 0.020\\text{ mol}\\)。","故 \\(m(\\mathrm{Mg_3N_2}) = 0.020\\text{ mol} \\times 100\\text{ g}\\cdot\\mathrm{mol^{-1}} = 2.0\\text{ g}\\)。"],"answer":"(1) 氮气先蒸出（液氮沸点 −196℃ 低于液氧 −183℃）；(2) \\(2.0\\text{ g}\\)。","markingPoints":["准确写出液氮先蒸出及沸点比较依据（1分）","正确列出 Mg 原子守恒与总质量守恒方程（2分）","解得 n(Mg₃N₂)=0.020 mol 及质量 2.0 g（1分）"],"verification":"反算：\\(x = 0.20 - 3(0.020) = 0.14\\text{ mol}\\)，\\(m(\\mathrm{MgO}) = 0.14 \\times 40 = 5.6\\text{ g}\\)，\\(5.6 + 2.0 = 7.6\\text{ g}\\)。","pitfall":"若忘记 \\(1\\text{ mol }\\mathrm{Mg_3N_2}\\) 含 \\(3\\text{ mol Mg}\\)，将守恒写成 \\(x+y=0.20\\)，计算必然错误。"},{"label":"例 13.1.2","tier":"L3","tierLabel":"L3 预试拔高","title":"亚硝酸钠与氯化铵共热制氮气及实验设计","prompt":"实验室常用 \\(\\mathrm{NaNO_2}\\) 与 \\(\\mathrm{NH_4Cl}\\) 浓溶液共热制取少量纯净氮气。(1) 写出该反应的离子方程式并指出氧化产物与还原产物；(2) 若将干燥后的氨气通入装有灼热氧化铜的硬质玻璃管中，请写出反应方程式并说明可观察到的固体颜色变化。","clues":"NaNO₂ 中 N 为 +3 价，NH₄⁺ 中 N 为 −3 价，产物同为 N₂（0价）。","strategy":"由电子守恒确认归中反应比例 1:1；由 CuO(黑) → Cu(紫红) 回答颜色变化。","given":"反应物 NaNO₂ + NH₄Cl；CuO + NH₃","principle":"归中反应电子守恒与氨气的还原性。","steps":["(1) 离子方程式：\\(\\mathrm{NO_2^-(aq) + NH_4^+(aq)} \\xrightarrow{\\Delta} \\mathrm{N_2(g)\\uparrow + 2H_2O(l)}\\)。","其中 \\(\\mathrm{NH_4^+}\\) 中 N 从 \\(-3\\) 升至 \\(0\\)，\\(\\mathrm{NO_2^-}\\) 中 N 从 \\(+3\\) 降至 \\(0\\)，故 \\(\\mathrm{N_2}\\) **既是氧化产物也是还原产物**（两者物质的量之比为 \\(1:1\\)）。","(2) 化学方程式：\\(\\mathrm{3CuO(s) + 2NH_3(g)} \\xrightarrow{\\Delta} \\mathrm{3Cu(s) + 3H_2O(l) + N_2(g)}\\)。","固体颜色变化：硬质玻璃管内**黑色固体逐渐变为紫红色**，管壁出现无色液滴（水）。"],"answer":"(1) \\(\\mathrm{NO_2^- + NH_4^+} \\xrightarrow{\\Delta} \\mathrm{N_2\\uparrow + 2H_2O}\\)，N₂ 既是氧化产物也是还原产物；(2) 黑色粉末变紫红色。","markingPoints":["正确写出离子方程式并指出 N₂ 双重产物身份（2分）","写出 CuO+NH₃ 配平方程式与黑色变紫红色现象（2分）"],"verification":"电子守恒核验：\\(3 \\times (+2 \\to 0) = 6\\)，\\(2 \\times (-3 \\to 0) = 6\\)，完全配平。","pitfall":"误答“CuO 变成红褐色沉淀”，紫红色固体才是单质 Cu。"}],"practice":[{"id":"chem13-13.1-q1","tier":"L1","tierLabel":"L1 基础","examStyle":"P1 选择","q":"下列关于VA族元素及氮气的叙述，**错误**的是（　）。","options":["A. VA族元素原子最外层均有 5 个电子，随着原子序数增大，非金属性逐渐减弱","B. 通常状况下氮气化学性质很稳定，主要原因是氮分子内存在牢固的氮氮三键","C. 氮气在空气中点燃能直接剧烈燃烧并生成二氧化氮气体","D. 工业上可利用液态氮与液态氧沸点不同，通过分馏液态空气制取氮气"],"correctOption":"C","given":"VA族性质与 N₂ 化学性质（化上 p.298–300）","method":"逐项比对教材表13-1及氮气化学性质","principle":"N≡N 三键稳态；N₂ 与 O₂ 需高温高压或放电生成 NO 而非直接燃烧得 NO₂。","steps":["A、B、D 均符合教材原文表述。","C 错：N₂ 与 O₂ 的反应吸热，无法在空气中点燃燃烧，且放电条件下第一步产物是 NO。"],"ans":"C","markingPoints":["识别 N₂ 不能在空气中燃烧（1分）"],"verification":"对照化上 p.301 思考题 13a 第2题。","pitfall":"误把闪电生成 NO₂ 当作 N₂ 直接燃烧。"},{"id":"chem13-13.1-q2","tier":"L2","tierLabel":"L2 期末","examStyle":"P1 选择","q":"下列化学变化中，氮气（\\(\\mathrm{N_2}\\)）仅作为**还原剂**参与反应的是（　）。","options":["A. 工业合成氨：\\(\\mathrm{N_2 + 3H_2} \\rightleftharpoons \\mathrm{2NH_3}\\)","B. 雷电固氮：\\(\\mathrm{N_2 + O_2} \\xrightarrow{\\text{放电}} \\mathrm{2NO}\\)","C. 镁带在空气中燃烧生成氮化镁：\\(\\mathrm{3Mg + N_2 \\longrightarrow Mg_3N_2}\\)","D. 金属锂与氮气化合：\\(\\mathrm{6Li + N_2 \\longrightarrow 2Li_3N}\\)"],"correctOption":"B","given":"四个含 N₂ 的典型反应","method":"判断 N 元素的氧化数升高还是降低","principle":"氧化数升高作还原剂；氧化数降低作氧化剂。","steps":["A、C、D 中 N 均由 0 价降至 −3 价（NH₃、Mg₃N₂、Li₃N），N₂ 作氧化剂。","B 中 N 由 0 价升至 +2 价（NO），N₂ 失电子作还原剂。"],"ans":"B","markingPoints":["准确判定 N 氧化数升高方向"],"verification":"NO 中 O 为 −2，故 N 为 +2 > 0。","pitfall":"误选 A（合成氨中 N₂ 是氧化剂，H₂ 是还原剂）。"},{"id":"chem13-13.1-q3","tier":"L3","tierLabel":"L3 预试","examStyle":"P2 探究简答","q":"某同学在实验室利用亚硝酸钠与氯化铵溶液加热制取氮气，并提出可用“灼热铜粉除去空气中氧气”来代替该反应制取纯净氮气。(1) 写出亚硝酸钠与氯化铵反应方程式，并说明为何不能用排空气法收集制得的氮气；(2) 从空气组成角度评价该同学替代方案所得气体是否纯净。","given":"NaNO₂ + NH₄Cl 反应；空气组分（N₂ 78%, O₂ 21%, 稀有气体约 0.94%, CO₂/水汽）","method":"比较气体摩尔质量与空气成分","principle":"密度与空气接近的气体不能用排空气法；除氧后的空气仍含稀有气体等杂质。","steps":["(1) \\(\\mathrm{NaNO_2(aq) + NH_4Cl(aq)} \\xrightarrow{\\Delta} \\mathrm{NaCl(aq) + N_2(g) + 2H_2O(l)}\\)。氮气摩尔质量 \\(28\\text{ g}\\cdot\\mathrm{mol^{-1}}\\) 与空气平均摩尔质量 \\(29\\text{ g}\\cdot\\mathrm{mol^{-1}}\\) 十分接近，用排空气法无法排尽空气，故须用排水法。","(2) 不纯净。空气中除 \\(\\mathrm{N_2}\\) 和 \\(\\mathrm{O_2}\\) 外，还含有约 \\(0.94\\%\\) 的氩气等稀有气体以及 \\(\\mathrm{CO_2}\\)、水蒸气，灼热铜粉只能除去 \\(\\mathrm{O_2}\\)，所得氮气中仍混有稀有气体等杂质。"],"ans":"(1) 因 N₂ 密度与空气过于接近，须用排水法；(2) 不纯净，仍含稀有气体（约 1%）及 CO₂ 等。","markingPoints":["写出反应方程式（1分）","用密度相近解释不能排空气收集（1分）","指出空气中含稀有气体与 CO₂ 导致不纯（2分）"],"verification":"对照教材 p.299–300 及空气组分常识核验。","pitfall":"只答“混有水蒸气”，漏掉化学性质极不活泼、碱石灰和铜粉都除不掉的稀有气体（Ar 等）。"},{"id":"chem13-13.1-q4","tier":"L4","tierLabel":"L4 统考压轴","examStyle":"P2 综合计算","q":"将一定质量的金属锂（\\(\\mathrm{Li}\\)）和镁（\\(\\mathrm{Mg}\\)）组成的合金样品在足量纯净氮气中完全反应，生成 \\(\\mathrm{Li_3N}\\) 和 \\(\\mathrm{Mg_3N_2}\\) 的固体混合物共 \\(13.5\\text{ g}\\)。随后向该固体混合物中加入足量水，生成白色沉淀，并收集到标准状况下氨气 \\(6.72\\text{ L}\\)（已知金属氮化物水解通式：\\(\\mathrm{M}_x\\mathrm{N}_y + 3y\\mathrm{H_2O} \\longrightarrow x\\mathrm{M(OH)}_{3y/x} + y\\mathrm{NH_3\\uparrow}\\)，且标准状况气体摩尔体积为 \\(22.4\\text{ L}\\cdot\\mathrm{mol^{-1}}\\)）。求原合金中锂的质量分数。（\\(\\mathrm{Li}=7,\\ \\mathrm{Mg}=24,\\ \\mathrm{N}=14\\)）","given":"m(氮化物)=13.5 g，V(NH₃, STP)=6.72 L","method":"由 n(NH₃) 得 n(N)，由总固体质量减去 m(N) 得金属合金总质量，联立 Li 与 Mg 方程求解","principle":"氮原子守恒与二元一次方程组。","steps":["氨气的物质的量：\\(n(\\mathrm{NH_3}) = \\frac{6.72\\text{ L}}{22.4\\text{ L}\\cdot\\mathrm{mol^{-1}}} = 0.30\\text{ mol}\\)。","由氮原子守恒，氮化物中氮原子总量 \\(n(\\mathrm{N}) = 0.30\\text{ mol}\\)，其质量 \\(m(\\mathrm{N}) = 0.30 \\times 14 = 4.2\\text{ g}\\)。","故原合金总质量：\\(m(\\text{合金}) = 13.5\\text{ g} - 4.2\\text{ g} = 9.3\\text{ g}\\)。","设合金中 \\(n(\\mathrm{Li}) = x\\text{ mol}\\)，\\(n(\\mathrm{Mg}) = y\\text{ mol}\\)。由化学式 \\(\\mathrm{Li_3N}\\) 与 \\(\\mathrm{Mg_3N_2}\\) 可知：\\(n(\\mathrm{N}) = \\frac{x}{3} + \\frac{2y}{3} = 0.30 \\implies x + 2y = 0.90\\)。","合金质量方程：\\(7x + 24y = 9.3\\)。将上式乘 12 得 \\(12x + 24y = 10.8\\)，两式相减得 \\(5x = 1.5 \\implies x = 0.30\\text{ mol}\\)，\\(y = 0.30\\text{ mol}\\)。","锂的质量分数：\\(w(\\mathrm{Li}) = \\frac{0.30 \\times 7}{9.3} \\times 100\\% = \\frac{2.1}{9.3} \\times 100\\% \\approx 22.6\\%\\)。"],"ans":"原合金中锂的质量分数约为 \\(22.6\\%\\)。","markingPoints":["求得 n(N)=0.30 mol 并反算出合金总质量 9.3 g（2分）","列出方程 x+2y=0.90 与 7x+24y=9.3（2分）","解出 x=0.30 mol 并算得 22.6%（1分）"],"verification":"\\(0.10\\text{ mol }\\mathrm{Li_3N}(3.5\\text{ g}) + 0.10\\text{ mol }\\mathrm{Mg_3N_2}(10.0\\text{ g}) = 13.5\\text{ g}\\)，放 \\(\\mathrm{NH_3}\\) 共 \\(0.10+0.20=0.30\\text{ mol}\\)。","pitfall":"容易把 Mg₃N₂ 中 N 的系数算反，记住“金属总正价 = 3 × n(N)”即 \\(1x + 2y = 3n(\\mathrm{N})\\) 最不易出错。"}],"cheatSheet":["VA族（ns²np³）：从 N、P（非金属）→ As（准金属）→ Sb、Bi（金属）。","N≡N 三键极其稳定；工业液空分馏先出 N₂（−196℃ < −183℃）；实验室制法 NaNO₂ + NH₄Cl —Δ→ N₂↑ + NaCl + 2H₂O。","高温/放电三大反应：N₂+3H₂⇌2NH₃（N₂作氧化剂）、N₂+O₂→2NO（N₂作还原剂）、3Mg+N₂→Mg₃N₂。"],"kbEntryIds":["kb-chem13-n2-properties"],"quiz":{"q":"下列反应中，属于“自然界氮的固定”且氮元素被氧化的是哪一个？","given":"固氮定义为将游离态氮 N₂ 转化为化合态氮","method":"对照高空雷电反应中 N 氧化数的变化","principle":"N₂(0) → NO(+2) 为氧化；N₂(0) → NH₃(−3) 为还原。","steps":["雷电固氮：\\(\\mathrm{N_2(g) + O_2(g)} \\xrightarrow{\\text{放电}} \\mathrm{2NO(g)}\\)。","N 由 0 价升至 +2 价，被氧化。"],"ans":"雷电作用下的 \\(\\mathrm{N_2 + O_2} \\xrightarrow{\\text{放电}} \\mathrm{2NO}\\)"}},{"id":"13.2","t":"氮的氧化物","anchor":{"pages":"化上 p.301–304","syllabus":"3.7.2 NO、NO₂、N₂O 的性质与制法及氮氧化物污染防治","examScopes":["sem2_final","uec"],"examWeight":"P1 气体性质与收集辨析 + P2 混合气体溶于水定量计算高频考点","terms":"nitrogen monoxide · nitrogen dioxide · dinitrogen tetroxide · photochemical smog · acid rain","prerequisites":["氧化还原反应配平与氧化数判断（化上 Ch 8）","阿伏加德罗气体体积定律（化上 Ch 3.1）"],"goals":["比较 NO、NO₂（含 N₂O₄ 聚合平衡）和 N₂O 的颜色、气味、水溶性、毒性、实验室制法及收集方法。","写出 NO 遇氧变红棕、NO₂ 与水及 NaOH 溶液反应的方程式并指出其歧化本质。","阐明氮氧化物引起光化学烟雾与酸雨的成因，以及汽车尾气催化转化器的治理原理。"]},"concepts":[{"kind":"table","title":"三种常见氮氧化物（NO、NO₂、N₂O）性质与制法对照","pageRef":"化上 p.302–303","body":["氮与氧能形成六种氧化物：\\(\\mathrm{N_2O(+1)}\\)、\\(\\mathrm{NO(+2)}\\)、\\(\\mathrm{N_2O_3(+3)}\\)、\\(\\mathrm{NO_2/N_2O_4(+4)}\\)、\\(\\mathrm{N_2O_5(+5)}\\)。其中 \\(\\mathrm{NO}\\) 与 \\(\\mathrm{CO}\\) 同为不成盐（中性）氧化物；\\(\\mathrm{N_2O_3}\\) 与 \\(\\mathrm{N_2O_5}\\) 分别为 \\(\\mathrm{HNO_2}\\) 和 \\(\\mathrm{HNO_3}\\) 的酸酐。"],"table":{"headers":["氧化物","氮氧化数","外观与水溶性","实验室制取反应","收集方法与核心特性"],"rows":[["一氧化氮（\\(\\mathrm{NO}\\)）","+2","无色无味有毒，难溶于水","\\(\\mathrm{3Cu + 8HNO_3(\\text{稀}) \\to 3Cu(NO_3)_2 + 2NO\\uparrow + 4H_2O}\\)","**排水法**收集（禁排空气）；遇空气立刻变为红棕 \\(\\mathrm{NO_2}\\)；人体血管舒张信号分子"],["二氧化氮（\\(\\mathrm{NO_2}\\)）","+4","红棕色刺激性有毒，易溶于水","\\(\\mathrm{Cu + 4HNO_3(\\text{浓}) \\to Cu(NO_3)_2 + 2NO_2\\uparrow + 2H_2O}\\)；或热分解 \\(\\mathrm{Pb(NO_3)_2}\\)","**向上排空气法**或**冰+盐U型管冷却法**（图13-7）；低温聚合为无色 \\(\\mathrm{N_2O_4(l)}\\)"],["一氧化二氮（\\(\\mathrm{N_2O}\\)）","+1","无色微甜，微溶于水","\\(\\mathrm{NH_4NO_3(s)} \\xrightarrow{\\Delta} \\mathrm{N_2O(g) + 2H_2O(g)}\\)","作麻醉剂（笑气）；高温分解 \\(\\mathrm{2N_2O \\to 2N_2 + O_2}\\)，能助燃"]]},"takeaway":"NO₂ 与水反应生成 HNO₃ 和 HNO₂，工业进一步转化为 3NO₂ + H₂O → 2HNO₃ + NO，并不是单纯的 HNO₃ 酸酐！"},{"kind":"mechanism","title":"二氧化氮的歧化反应与聚合平衡（2NO₂ ⇌ N₂O₄）","pageRef":"化上 p.302–303","body":["**与水歧化**：\\(\\mathrm{2NO_2(g) + H_2O(l) \\longrightarrow HNO_3(aq) + HNO_2(aq)}\\)。在此反应中，\\(\\mathrm{NO_2}\\) 既是氧化剂又是还原剂（+4 价部分升为 +5 价、部分降为 +3 价）。","**与碱歧化吸收尾气**：\\(\\mathrm{2NO_2(g) + 2NaOH(aq) \\longrightarrow NaNO_3(aq) + NaNO_2(aq) + H_2O(l)}\\)，实验室常用 NaOH 溶液吸收多余 \\(\\mathrm{NO_2}\\)。","**可逆聚合平衡**：\\(\\mathrm{2NO_2(g)} \\underset{\\text{加热}}{\\stackrel{\\text{冷却}}{\\rightleftharpoons}} \\mathrm{N_2O_4(l)}\\)（红棕色气体冷却后颜色变浅/变无色液化，受热又变深）。"],"takeaway":"由于存在 2NO₂ ⇌ N₂O₄ 平衡，标况或常温下 1 mol NO₂ 气体所含分子数必定小于 NA！"},{"kind":"definition","title":"光化学烟雾、硝酸型酸雨与汽车尾气催化转化","pageRef":"化上 p.304、p.330","body":["**光化学烟雾（Photochemical smog）**：汽车、工厂排放的碳氢化合物（\\(\\mathrm{C}_x\\mathrm{H}_y\\)）与氮氧化物（\\(\\mathrm{NO}_x\\)）等一次污染物，在阳光紫外线照射下诱导生成臭氧等二次污染物（含气体与气溶胶），形成具刺激气味、刺眼伤植物、降低能见度的有毒烟雾。","**酸雨（\\(\\mathrm{pH} < 5.6\\)）**：氮氧化物溶于水生成硝酸和亚硝酸构成硝酸型酸雨（来源：化肥生产、金属冶炼、汽车尾气）。","**防治措施**：① 使用洁净能源，减少 \\(\\mathrm{NO}_x\\) 排放；② 为汽车安装尾气催化转化装置，将 \\(\\mathrm{CO}\\) 与 \\(\\mathrm{NO}\\) 转化为无毒的 \\(\\mathrm{CO_2}\\) 和 \\(\\mathrm{N_2}\\)：\\(\\mathrm{2CO + 2NO} \\xrightarrow{\\text{催化剂}} \\mathrm{2CO_2 + N_2}\\)。"],"takeaway":"正常雨水因溶解空气中 CO₂ 呈弱酸性（pH ≈ 5.6），仅当雨水 pH < 5.6 时才称为酸雨。"}],"formulas":[{"title":"NO 氧化与 NO₂ 歧化反应","tex":"\\mathrm{2NO(g) + O_2(g) \\longrightarrow 2NO_2(g)},\\qquad \\mathrm{2NO_2(g) + 2NaOH(aq) \\longrightarrow NaNO_3(aq) + NaNO_2(aq) + H_2O(l)}","plain":"2NO + O2 -> 2NO2; 2NO2 + 2NaOH -> NaNO3 + NaNO2 + H2O","conditions":"常温即可迅速发生","pageRef":"化上 p.302–303","note":"实验室用 NaOH 溶液吸收尾气时，NO 单独不能被吸收，但若按 NO : NO₂ = 1 : 1 混合可被吸收：NO + NO₂ + 2NaOH → 2NaNO₂ + H₂O。"},{"title":"氮氧化物与氧气混合完全溶于水定量总式（统考核心）","tex":"\\mathrm{4NO_2(g) + O_2(g) + 2H_2O(l) \\longrightarrow 4HNO_3(aq)},\\qquad \\mathrm{4NO(g) + 3O_2(g) + 2H_2O(l) \\longrightarrow 4HNO_3(aq)}","plain":"4NO2 + O2 + 2H2O -> 4HNO3; 4NO + 3O2 + 2H2O -> 4HNO3","conditions":"水足量且氧气充分参与循环氧化","pageRef":"化上 p.302–303、p.308","note":"4 份 NO₂ 配 1 份 O₂ 恰好全溶（无气体剩余）；4 份 NO 配 3 份 O₂ 恰好全溶。"}],"pitfalls":[{"title":"忽视 2NO₂ ⇌ N₂O₄ 对气体体积与分子数的影响","wrong":"“标准状况下，46 g 二氧化氮气体约含 \\(6.02 \\times 10^{23}\\) 个分子，体积为 22.4 L。”","diagnosis":"气态 \\(\\mathrm{NO_2}\\) 随时发生可逆聚合 \\(\\mathrm{2NO_2 \\rightleftharpoons N_2O_4}\\)，总分子数减少；且标况（0℃）时 \\(\\mathrm{N_2O_4}\\) 已接近液化。","right":"\\(46\\text{ g }\\mathrm{NO_2}\\) 所含**原子总数**一定为 \\(3N_A\\)（\\(1N_A\\) 个 N + \\(2N_A\\) 个 O），但**分子总数一定小于 \\(N_A\\)**。","checkRule":"碰到 NO₂ 计算原子数看质量守恒（准确），算分子数或气体体积必小于理论值。"},{"title":"误判 NO₂ 与水反应中水作还原剂","wrong":"“\\(\\mathrm{2NO_2 + H_2O \\to HNO_3 + HNO_2}\\) 中，水被氧化或被还原。”","diagnosis":"反应前后 H 保持 +1 价、O 保持 −2 价，水既未得电子也未失电子。","right":"只有 \\(\\mathrm{NO_2}\\) 中 +4 价氮发生自身氧化还原（歧化），\\(\\mathrm{NO_2}\\) 既是氧化剂又是还原剂（教材思考题 13b 第3题）。","checkRule":"判断氧化还原角色必先逐一标出所有元素反应前后的氧化数。"}],"examples":[{"label":"例 13.2.1","tier":"L3","tierLabel":"L3 预试拔高","title":"NO₂ 与 O₂ 混合气倒立水槽后的剩余气体分类讨论","prompt":"将装有 \\(\\mathrm{NO_2}\\) 和 \\(\\mathrm{O_2}\\) 混合气体共 \\(20\\text{ mL}\\) 的试管倒立于盛满水的水槽中，充分反应后，同温同压下试管内最终剩余气体 \\(2\\text{ mL}\\)。试求原混合气体中 \\(\\mathrm{NO_2}\\) 和 \\(\\mathrm{O_2}\\) 的体积各为多少毫升？（忽略 \\(\\mathrm{N_2O_4}\\) 影响）","clues":"剩余的 2 mL 无色气体可能是过量的 O₂，也可能是过量的 NO₂ 与水反应后剩余的 NO！必须分两种情况讨论。","strategy":"利用总反应 4NO₂ + O₂ + 2H₂O → 4HNO₃ 分别按“O₂ 过量”和“NO₂ 过量（依 3NO₂+H₂O→2HNO₃+NO）”列式。","given":"总体积 = 20 mL，最终剩余气体 = 2 mL","principle":"4NO₂ + O₂ + 2H₂O = 4HNO₃；3NO₂ + H₂O = 2HNO₃ + NO。","steps":["**情况一：剩余的 \\(2\\text{ mL}\\) 气体为 \\(\\mathrm{O_2}\\)**。则实际参与反应的总气体体积为 \\(20 - 2 = 18\\text{ mL}\\)。","依据 \\(4\\mathrm{NO_2} + \\mathrm{O_2} + 2\\mathrm{H_2O} \\to 4\\mathrm{HNO_3}\\)，参与反应的 \\(\\mathrm{NO_2}\\) 与 \\(\\mathrm{O_2}\\) 体积比为 \\(4:1\\)：","\\(V(\\mathrm{NO_2}) = 18 \\times \\frac{4}{5} = 14.4\\text{ mL}\\)，\\(V(\\mathrm{O_2}) = 20 - 14.4 = 5.6\\text{ mL}\\)。","**情况二：剩余的 \\(2\\text{ mL}\\) 气体为 \\(\\mathrm{NO}\\)（即原 \\(\\mathrm{NO_2}\\) 过量）**。","由 \\(3\\mathrm{NO_2} + \\mathrm{H_2O} \\to 2\\mathrm{HNO_3} + \\mathrm{NO}\\) 可知，生成 \\(2\\text{ mL }\\mathrm{NO}\\) 需过量 \\(\\mathrm{NO_2}\\) 为 \\(2 \\times 3 = 6\\text{ mL}\\)。","则按 \\(4:1\\) 完全消耗的混合气体为 \\(20 - 6 = 14\\text{ mL}\\)，其中 \\(V(\\mathrm{O_2}) = 14 \\times \\frac{1}{5} = 2.8\\text{ mL}\\)，\\(V(\\mathrm{NO_2}) = 20 - 2.8 = 17.2\\text{ mL}\\)。"],"answer":"有两种可能：① \\(V(\\mathrm{NO_2}) = 14.4\\text{ mL},\\ V(\\mathrm{O_2}) = 5.6\\text{ mL}\\)；② \\(V(\\mathrm{NO_2}) = 17.2\\text{ mL},\\ V(\\mathrm{O_2}) = 2.8\\text{ mL}\\)。","markingPoints":["指出剩余气体存在 O₂ 或 NO 两种可能（1分）","情况一按 4:1 求得 14.4 mL 和 5.6 mL（1.5分）","情况二先由 2 mL NO 换算 6 mL 过量 NO₂ 再算得 17.2 mL 和 2.8 mL（1.5分）"],"verification":"情况二检验：17.2 mL NO₂ 中 11.2 mL 与 2.8 mL O₂ 恰好 4:1 反应，余下 6 mL NO₂ 与水生成 2 mL NO。","pitfall":"若误以为剩下的 2 mL 就是未反应的 NO₂（NO₂ 会继续溶于水！），或漏掉情况二，必丢一半分数。"},{"label":"例 13.2.2","tier":"L2","tierLabel":"L2 校内期末","title":"实验室收集 NO₂ 与热分解硝酸铅(II)实验剖析","prompt":"实验室制取并收集二氧化氮可采用如图13-7 所示装置（Cu 与浓硝酸反应后通入置于冰+盐冷却浴中的U型管）。(1) 写出铜与浓硝酸反应及加热硝酸铅(II)制取 \\(\\mathrm{NO_2}\\) 的化学方程式；(2) 为什么收集 \\(\\mathrm{NO_2}\\) 不能使用排水法，而要采用冰+盐冷却法？","clues":"参考教材 p.302 图13-7，冰+盐降温可使 NO₂ 聚合液化为 N₂O₄。","strategy":"结合 NO₂ 易溶于水且与水反应、降温易发生 2NO₂ ⇌ N₂O₄ 液化的特性作答。","given":"Cu + 浓 HNO₃；Pb(NO₃)₂ 热分解；图13-7 冰+盐装置","principle":"NO₂ 与水反应；降温使 2NO₂ ⇌ N₂O₄ 平衡正向移动并液化。","steps":["(1) 铜与浓硝酸：\\(\\mathrm{Cu(s) + 4HNO_3(aq,\\text{浓}) \\longrightarrow Cu(NO_3)_2(aq) + 2NO_2(g)\\uparrow + 2H_2O(l)}\\)。","热分解硝酸铅(II)：\\(\\mathrm{2Pb(NO_3)_2(s)} \\xrightarrow{\\Delta} \\mathrm{2PbO(s) + 4NO_2(g)\\uparrow + O_2(g)\\uparrow}\\)。","(2) 因为 \\(\\mathrm{NO_2}\\) 易溶于水且与水反应生成 \\(\\mathrm{HNO_3}\\) 和 \\(\\mathrm{NO}\\)（\\(\\mathrm{3NO_2 + H_2O \\to 2HNO_3 + NO}\\)），所以不能用排水法收集；利用冰+盐低温冷却可使 \\(\\mathrm{NO_2}\\) 聚合并液化为 \\(\\mathrm{N_2O_4}\\) 聚集在 U 型管中（且能与不液化的 \\(\\mathrm{O_2}\\) 分离）。"],"answer":"(1) 见步骤；(2) NO₂ 易与水反应不能排水收集，冰盐浴使其冷却聚合液化聚集。","markingPoints":["两个方程式完全配平（2分）","说明 NO₂ 与水反应及冰盐浴使其冷却液化（2分）"],"verification":"对照教材 p.302 原文和图13-7 确认细节。","pitfall":"热分解 Pb(NO₃)₂ 容易漏写产物 O₂。"}],"practice":[{"id":"chem13-13.2-q1","tier":"L1","tierLabel":"L1 基础","examStyle":"P1 选择","q":"下列氮的氧化物中，既有麻醉作用俗称“笑气”、又在高温下因分解生成氧气而能助燃的是（　）。","options":["A. \\(\\mathrm{NO}\\)","B. \\(\\mathrm{NO_2}\\)","C. \\(\\mathrm{N_2O}\\)","D. \\(\\mathrm{N_2O_5}\\)"],"correctOption":"C","given":"四种氮的氧化物性质","method":"直接对应教材 p.303 知识","principle":"NH₄NO₃ —Δ→ N₂O↑ + 2H₂O；2N₂O —高温→ 2N₂ + O₂。","steps":["N₂O 为无色微甜气体，少量吸入使人发笑称笑气，高温分解放出 O₂ 助燃。"],"ans":"C","markingPoints":["识别 N₂O 的俗称与分解助燃特性"],"verification":"对照化上 p.303。","pitfall":"把治疗心绞痛的信号分子 NO 与笑气 N₂O 混淆。"},{"id":"chem13-13.2-q2","tier":"L2","tierLabel":"L2 期末","examStyle":"P1 选择","q":"实验室分别收集下列四种气体时，**绝对不能**用排空气法收集的是（　）。","options":["A. \\(\\mathrm{N_2O}\\)","B. \\(\\mathrm{NO}\\)","C. \\(\\mathrm{NO_2}\\)","D. \\(\\mathrm{CO_2}\\)"],"correctOption":"B","given":"气体与空气反应性及摩尔质量对比","method":"检查气体是否与空气中 O₂ 反应","principle":"NO 常温下立即与 O₂ 化合为 NO₂，无法用排空气法收集。","steps":["NO 常温与空气中 O₂ 反应 \\(\\mathrm{2NO + O_2 \\to 2NO_2}\\)，只能用排水法收集。"],"ans":"B","markingPoints":["识别 NO 与 O₂ 反应不可排空气"],"verification":"对照教材思考题 13b 第2题。","pitfall":"误选 C，NO₂ 密度大于空气可用向上排空气法。"},{"id":"chem13-13.2-q3","tier":"L3","tierLabel":"L3 预试","examStyle":"P1 选择","q":"某地区监测到严重光化学烟雾与酸雨污染，下列关于氮氧化物污染及防治的说法中，**错误**的是（　）。","options":["A. 汽车尾气中的 \\(\\mathrm{NO}\\) 和未燃烃类在紫外线作用下可引发光化学烟雾","B. 氮氧化物进入大气后可形成以 \\(\\mathrm{HNO_3}\\) 和 \\(\\mathrm{HNO_2}\\) 为主的酸雨","C. 汽车尾气催化转化器中的反应为 \\(\\mathrm{2CO + 2NO} \\xrightarrow{\\text{催化剂}} \\mathrm{2CO_2 + N_2}\\)","D. 使用 \\(\\mathrm{NaOH}\\) 溶液能将单独存在的 \\(\\mathrm{NO}\\) 气体完全吸收除去"],"correctOption":"D","given":"NOₓ 环境影响与治理","method":"逐项排查化学反应可行性","principle":"NO 为不成盐氧化物，单独不与 NaOH 溶液反应。","steps":["A、B、C 均为教材 p.304 原文核心结论。","D 错：NO 是中性（不成盐）氧化物，不与 NaOH 反应，必须先混入等体积 NO₂ 或适量 O₂ 才可被碱液吸收。"],"ans":"D","markingPoints":["明确 NO 不成盐特性"],"verification":"检验 NO 价态 +2 居中，无 +2 价含氧酸对应盐。","pitfall":"把 NO₂ 与 NaOH 反应误套用到 NO 身上。"},{"id":"chem13-13.2-q4","tier":"L4","tierLabel":"L4 统考压轴","examStyle":"P2 综合计算","q":"将 \\(12\\text{ mL}\\) 一氧化氮（\\(\\mathrm{NO}\\)）和 \\(10\\text{ mL}\\) 二氧化氮（\\(\\mathrm{NO_2}\\)）以及 \\(x\\text{ mL}\\) 氧气（\\(\\mathrm{O_2}\\)）充分混合后，一起倒扣在盛满水的大烧杯中，使气体与水充分接触反应。当同温同压下最终只剩下 \\(2\\text{ mL}\\) 无色气体时，试计算通入氧气 \\(x\\) 的可能取值（设此条件下 \\(\\mathrm{NO_2}\\) 不发生二聚）。","given":"V(NO)=12 mL, V(NO₂)=10 mL, V(O₂)=x mL，剩余无色气体=2 mL","method":"分两种情况（剩余 O₂ 或剩余 NO）运用总计量式","principle":"4NO + 3O₂ + 2H₂O = 4HNO₃；4NO₂ + O₂ + 2H₂O = 4HNO₃；3NO₂ + H₂O = 2HNO₃ + NO。","steps":["若全部 \\(12\\text{ mL NO}\\) 和 \\(10\\text{ mL }\\mathrm{NO_2}\\) 恰好全溶为硝酸，所需 \\(\\mathrm{O_2}\\) 体积为：\\(V_{\\text{需}}(\\mathrm{O_2}) = \\frac{3}{4} \\times 12 + \\frac{1}{4} \\times 10 = 9 + 2.5 = 11.5\\text{ mL}\\)。","**情况一：氧气过量，最终剩余 \\(2\\text{ mL}\\) 为 \\(\\mathrm{O_2}\\)**。则 \\(x = 11.5 + 2 = 13.5\\text{ mL}\\)。","**情况二：氧气不足，最终剩余 \\(2\\text{ mL}\\) 为 \\(\\mathrm{NO}\\)**。","实际被氧化吸收进入 \\(\\mathrm{HNO_3}\\) 的部分相当于少消耗了 \\(2\\text{ mL NO}\\)（因 \\(10\\text{ mL }\\mathrm{NO_2}\\) 单独遇水会产 \\(3.33\\text{ mL NO} > 2\\text{ mL}\\)，故必为 O₂ 先消耗部分氮氧化物后仅余 2 mL NO）。","由电子守恒：\\(3(12 - 2) + 1 \\times 10 = 4x \\implies 40 = 4x \\implies x = 10.0\\text{ mL}\\)。"],"ans":"\\(x = 13.5\\text{ mL}\\) 或 \\(x = 10.0\\text{ mL}\\)。","markingPoints":["算出恰好完全吸收所需氧气体积 11.5 mL（1.5分）","情况一剩 O₂ 得 x=13.5 mL（1分）","情况二由电子守恒得 x=10.0 mL（1.5分）"],"verification":"电子守恒核验情况二：被氧化至 HNO₃(+5) 的 N 总失电子等价 \\(3\\times 10 + 1\\times 10 = 40\\) 份，对应 \\(\\mathrm{O_2}\\) 得 4 份电子即 \\(10.0\\text{ mL}\\)。","pitfall":"复杂体系强行分步写极易算乱，最稳妥的方法是**直接用电子守恒**：\\(3V_{\\text{耗}}(\\mathrm{NO}) + 1V_{\\text{耗}}(\\mathrm{NO_2}) = 4V_{\\text{耗}}(\\mathrm{O_2})\\)！"}],"cheatSheet":["NO：无色难溶，只能排水收，遇空气立刻 2NO + O₂ → 2NO₂（红棕）。","NO₂：红棕有毒，存在 2NO₂ ⇌ N₂O₄；与水 3NO₂ + H₂O → 2HNO₃ + NO（仅 2/3 转硝酸）；与碱 2NO₂ + 2NaOH → NaNO₃ + NaNO₂ + H₂O。","混合气体溶于水万能守恒：4NO₂+O₂=4HNO₃，4NO+3O₂=4HNO₃，剩余 2 mL 必讨论 O₂ 或 NO。"],"kbEntryIds":["kb-chem13-nox-oxides"],"quiz":{"q":"同温同压下，将等体积的 \\(\\mathrm{NO}\\) 和 \\(\\mathrm{NO_2}\\) 混合后通入足量氢氧化钠溶液，若混合气完全被吸收转化为单一钠盐，写出化学方程式。","given":"V(NO) : V(NO₂) = 1 : 1，无气体剩余","method":"利用 +2 价 N 与 +4 价 N 归中至 +3 价亚硝酸盐","principle":"归中反应与碱液中和。","steps":["NO(+2) 与 NO₂(+4) 各 1 份，平均氧化数为 +3，在碱性中生成 NaNO₂。"],"ans":"\\(\\mathrm{NO(g) + NO_2(g) + 2NaOH(aq) \\longrightarrow 2NaNO_2(aq) + H_2O(l)}\\)"}},{"id":"13.3","t":"硝酸","anchor":{"pages":"化上 p.305–309","syllabus":"3.7.3 硝酸的性质（酸性、不稳定性、强氧化性、钝化）与制法","examScopes":["sem2_final","uec"],"examWeight":"P1/P2 核心重点（铜与浓稀硝酸、钝化、奥斯特瓦尔德法工业制硝酸）","terms":"passivation · aqua regia · Ostwald process · catalytic oxidation of ammonia","prerequisites":["酸的通性与强电解质电离（化上 Ch 4）","氧化还原方程式配平与电子守恒（化上 Ch 8.4）"],"goals":["解释浓硝酸呈现黄色的原因（见光分解产生 NO₂ 溶于酸）及棕色试剂瓶阴凉保存规范。","对比浓硝酸与稀硝酸与铜反应的现象和方程式，理解“冷浓硝酸使 Fe、Al 钝化”及王水溶金原理。","掌握实验室浓硫酸+硝酸钠曲颈甑制法及工业氨催化氧化法（Ostwald process）三阶段反应与循环吸收。"]},"concepts":[{"kind":"definition","title":"硝酸的物理性质、见光分解与强酸通性","pageRef":"化上 p.305–306","body":["**物理性质**：纯硝酸是无色、易挥发、有刺激性气味的液体；市售工业常用浓硝酸质量分数约 \\(69\\%\\)（物质的量浓度约 \\(16\\text{ mol}\\cdot\\mathrm{L^{-1}}\\)）。","**不稳定性（活动1）**：实验室浓硝酸常呈黄色，是因为硝酸常温见光或受热即分解产生红棕色 \\(\\mathrm{NO_2}\\) 溶于硝酸中：\\(\\mathrm{4HNO_3(aq)} \\xrightarrow{\\text{光照}} \\mathrm{2H_2O(l) + 4NO_2(g) + O_2(g)}\\)，故须盛于**棕色试剂瓶**并置于阴凉处。","**强酸通性**：无论是浓硝酸还是稀硝酸都是强酸，能使石蕊变红、与碱中和、与碳酸盐放出 \\(\\mathrm{CO_2}\\)。但硝酸与金属反应**不生成氢气**（由 \\(+5\\) 价氮而非 \\(+1\\) 价氢得电子）。"],"takeaway":"浓硝酸变黄的“罪魁祸首”是分解生成的 NO₂ 溶于酸，向发黄浓硝酸中鼓入 O₂ 或空气即可使之褪回无色。"},{"kind":"experiment","title":"活动2：浓/稀硝酸与铜片反应、强氧化性与钝化","pageRef":"化上 p.306–307","body":["**活动2（注射器封闭实验，表13-2）**：① 铜与浓硝酸反应剧烈，产生红棕色气体（\\(\\mathrm{NO_2}\\)），溶液变蓝（或呈绿因溶解黄棕气体）；② 铜与稀硝酸反应较缓，注射器内生成无色气体（\\(\\mathrm{NO}\\)），溶液呈蓝色；拔去胶头吸入空气后，无色气体立刻在管内变红棕色（\\(\\mathrm{2NO + O_2 \\to 2NO_2}\\)）。","**强氧化性规律**：硝酸几乎能氧化除金（Au）、铂（Pt）外的所有金属及许多非金属（如 \\(\\mathrm{C + 4HNO_3(\\text{浓}) \\to CO_2\\uparrow + 4NO_2\\uparrow + 2H_2O}\\)）。一般来说，**硝酸越稀、金属越活泼，氮被还原后的氧化数越低**（\\(+5 \\to +4 \\to +3 \\to +2 \\to +1 \\to 0 \\to -3\\)）。","**钝化与王水**：常温下冷浓硝酸可使 **Fe、Al** 表面迅速生成致密氧化膜阻止内部金属继续反应（钝化，故可用铝槽车储运浓硝酸，但加热后会破坏氧化膜剧烈反应）；浓硝酸与浓盐酸按体积比 **1:3** 混合称为**王水（aqua regia）**，可溶解金、铂。"],"takeaway":"稀硝酸并不是弱酸！“稀硝酸是弱酸、浓硝酸是强酸”是经典错误命题；浓稀硝酸都是强酸和强氧化剂。"},{"kind":"mechanism","title":"硝酸的实验室曲颈甑制法与工业奥斯特瓦尔德法","pageRef":"化上 p.307–308","body":["**实验室制法（图13-9）**：利用难挥发性浓硫酸与硝酸钠晶体共热：\\(\\mathrm{NaNO_3(s) + H_2SO_4(aq,\\text{浓})} \\xrightarrow{\\Delta} \\mathrm{NaHSO_4(s) + HNO_3(g)}\\)，硝酸蒸汽导入水冷接受瓶凝集；全套仪器使用磨口玻璃曲颈甑（因硝酸强氧化性会腐蚀橡胶塞）。","**工业制法——氨的催化氧化法（Ostwald process，图13-10）**：① 催化氧化：在铂—铑合金催化加热下 \\(\\mathrm{4NH_3(g) + 5O_2(g)} \\xrightarrow{\\text{Pt-Rh}/\\Delta} \\mathrm{4NO(g) + 6H_2O(g)}\\)；② 一氧化氮氧化：\\(\\mathrm{2NO + O_2 \\to 2NO_2}\\)；③ 水吸收：\\(\\mathrm{2NO_2 + H_2O \\to HNO_3 + HNO_2}\\)、\\(\\mathrm{3HNO_2 \\to 2NO + HNO_3 + H_2O}\\)，总反应 \\(\\mathrm{3NO_2(g) + H_2O(l) \\longrightarrow 2HNO_3(aq) + NO(g)}\\)。","**循环补氧**：每 \\(3\\) 份 \\(\\mathrm{NO_2}\\) 仅 \\(2/3\\) 变成 \\(\\mathrm{HNO_3}\\)，剩余 \\(1/3\\) 变成 \\(\\mathrm{NO}\\)，因此吸收塔中常需不断补充空气将 \\(\\mathrm{NO}\\) 氧化回 \\(\\mathrm{NO_2}\\) 循环吸收。"],"takeaway":"工业制硝酸三步总原子经济性公式：NH₃ + 2O₂ → HNO₃ + H₂O（1 mol NH₃ 理论可制 1 mol HNO₃）。"}],"formulas":[{"title":"铜与浓硝酸、稀硝酸反应的化学方程式及离子方程式","tex":"\\mathrm{Cu + 4H^+ + 2NO_3^- \\longrightarrow Cu^{2+} + 2NO_2\\uparrow + 2H_2O}\\text{（浓）},\\qquad \\mathrm{3Cu + 8H^+ + 2NO_3^- \\longrightarrow 3Cu^{2+} + 2NO\\uparrow + 4H_2O}\\text{（稀）}","plain":"Cu + 4H+ + 2NO3- -> Cu2+ + 2NO2 + 2H2O (浓); 3Cu + 8H+ + 2NO3- -> 3Cu2+ + 2NO + 4H2O (稀)","conditions":"浓硝酸约 16 mol/L；稀硝酸需适当微热加快反应","pageRef":"化上 p.307","note":"浓硝酸中仅 1/2 的 HNO₃ 体现氧化性；稀硝酸中仅 1/4 的 HNO₃ 体现氧化性，其余均体现酸性生成 Cu(NO₃)₂！"},{"title":"氨催化氧化法（奥斯特瓦尔德法）总阶段方程","tex":"\\mathrm{4NH_3(g) + 5O_2(g)} \\xrightarrow{\\text{Pt-Rh}/\\Delta} \\mathrm{4NO(g) + 6H_2O(g)},\\qquad \\mathrm{3NO_2(g) + H_2O(l) \\longrightarrow 2HNO_3(aq) + NO(g)}","plain":"4NH3 + 5O2 -> 4NO + 6H2O; 3NO2 + H2O -> 2HNO3 + NO","conditions":"铂—铑合金网催化，吸收塔补充空气","pageRef":"化上 p.308","note":"利用热交换器可实现氨氧化反应余热预热进料混合气。"}],"pitfalls":[{"title":"把铜加入“浓硝酸”反应到后期只当生成 NO₂","wrong":"“足量铜与一定量浓硝酸反应，收集到的气体全是纯净的 \\(\\mathrm{NO_2}\\)。”","diagnosis":"随着反应进行，浓硝酸不断被消耗且生成水，浓度变稀后，反应转为 \\(\\mathrm{3Cu + 8HNO_3(\\text{稀}) \\to 3Cu(NO_3)_2 + 2NO\\uparrow + 4H_2O}\\)。","right":"足量铜与一定量浓硝酸反应时，先产生 \\(\\mathrm{NO_2}\\)，后期变为生成 \\(\\mathrm{NO}\\)，最终收集到 \\(\\mathrm{NO_2}\\) 与 \\(\\mathrm{NO}\\) 的混合气体。","checkRule":"遇到“足量 Cu + 一定量浓 HNO₃”，计算时不能单用 1:2 比例，须用 **N 原子守恒**与**电子守恒**联立！"},{"title":"混淆“钝化”与“不反应”","wrong":"“常温下铁和铝不与浓硝酸发生化学反应，所以可用铝槽车装运浓硝酸。”","diagnosis":"钝化恰恰是表面发生了剧烈但迅速终止的氧化反应，生成致密氧化膜覆盖金属表面。","right":"常温下冷浓硝酸使 Fe、Al 表面生成致密氧化膜而**钝化**（属于化学变化），从而阻止内部继续反应。","checkRule":"题目出现“常温下不反应”字样评价冷浓硫酸/冷浓硝酸与 Fe/Al 时必错（教材思考题 14g 第1题C）。"}],"examples":[{"label":"例 13.3.1","tier":"L4","tierLabel":"L4 统考压轴","title":"浓硝酸变稀反应（Cu 溶解）的氮原子与电子守恒计算","prompt":"将 \\(25.6\\text{ g}\\) 铜片加入 \\(100\\text{ mL}\\) 浓度为 \\(12.0\\text{ mol}\\cdot\\mathrm{L^{-1}}\\) 的浓硝酸中，反应过程中硝酸由浓变稀，最终铜片恰好完全溶解且溶液中不再有剩余硝酸（设气态还原产物仅为 \\(\\mathrm{NO_2}\\) 和 \\(\\mathrm{NO}\\)，不考虑 \\(\\mathrm{N_2O_4}\\)）。求：(1) 被还原的硝酸的总物质的量及其中表现酸性的硝酸物质的量；(2) 标准状况下生成混合气体的总体积以及 \\(\\mathrm{NO_2}\\) 与 \\(\\mathrm{NO}\\) 的物质的量之比。","clues":"铜与硝酸反应时，硝酸同时扮演两种角色：变成 Cu(NO₃)₂ 体现酸性，变成气体 NO₂/NO 体现氧化性（被还原）。","strategy":"先算总 n(Cu) 与总 n(HNO₃)，用 Cu(NO₃)₂ 求出起酸性作用的 n(NO₃⁻)，再用 N 守恒求气体总物质的量，最后结合电子守恒分离 NO₂ 与 NO。","given":"m(Cu) = 25.6 g (0.40 mol)；n(HNO₃) = 0.100 × 12.0 = 1.20 mol","principle":"氮原子守恒（酸中 N = 盐中 N + 气体中 N）与得失电子守恒。","steps":["计算投料：\\(n(\\mathrm{Cu}) = \\frac{25.6\\text{ g}}{64\\text{ g}\\cdot\\mathrm{mol^{-1}}} = 0.40\\text{ mol}\\)，\\(n(\\mathrm{HNO_3}) = 0.100\\text{ L} \\times 12.0\\text{ mol}\\cdot\\mathrm{L^{-1}} = 1.20\\text{ mol}\\)。","(1) 生成 \\(\\mathrm{Cu(NO_3)_2}\\) 为 \\(0.40\\text{ mol}\\)，故起酸性作用（未变价）的硝酸为 \\(2 \\times 0.40 = 0.80\\text{ mol}\\)。","由氮原子守恒，被还原的硝酸：\\(n_{\\text{还原}}(\\mathrm{HNO_3}) = n(\\mathrm{NO_2}) + n(\\mathrm{NO}) = 1.20 - 0.80 = 0.40\\text{ mol}\\)。","(2) 标准状况下混合气体总体积：\\(V_{\\text{总}} = 0.40\\text{ mol} \\times 22.4\\text{ L}\\cdot\\mathrm{mol^{-1}} = 8.96\\text{ L}\\)。","设 \\(n(\\mathrm{NO_2}) = x\\text{ mol}\\)，\\(n(\\mathrm{NO}) = y\\text{ mol}\\)。依电子守恒（\\(0.40\\text{ mol Cu}\\) 失去 \\(0.80\\text{ mol }e^-\\)）：","\\(x + y = 0.40\\)，\\(1\\cdot x + 3\\cdot y = 0.80\\)。两式相减得 \\(2y = 0.40 \\implies y = 0.20\\text{ mol}\\)，\\(x = 0.20\\text{ mol}\\)，故 \\(n(\\mathrm{NO_2}) : n(\\mathrm{NO}) = 1 : 1\\)。"],"answer":"(1) 被还原硝酸 \\(0.40\\text{ mol}\\)，起酸性作用 \\(0.80\\text{ mol}\\)；(2) 总体积 \\(8.96\\text{ L}\\)，\\(n(\\mathrm{NO_2}) : n(\\mathrm{NO}) = 1 : 1\\)。","markingPoints":["区分表现酸性的硝酸 0.80 mol 与被还原的硝酸 0.40 mol（2分）","算出混合气体标况总体积 8.96 L（1分）","运用电子守恒联立求得 n(NO₂):n(NO)=1:1（2分）"],"verification":"验证：0.10 mol Cu + 0.40 mol 浓 HNO₃ → 0.20 mol NO₂；0.30 mol Cu + 0.80 mol 稀 HNO₃ → 0.20 mol NO；总 Cu=0.40 mol，总 HNO₃=1.20 mol！","pitfall":"切勿死套单一浓硝酸比例 1:2 去算气体，浓转稀必须用“盐中 N + 电子守恒”解法。"},{"label":"例 13.3.2","tier":"L2","tierLabel":"L2 校内期末","title":"稀硝酸余液加稀硫酸再溶铜的离子反应原理","prompt":"向盛有过量铜粉的试管中加入一定量稀硝酸，充分反应后停止冒泡，试管底部仍有铜粉剩余，此时溶液呈蓝色。若再向该试管中滴加少量稀硫酸，观察到铜粉表面重新产生无色气泡且在试管口变成红棕色。(1) 解释加入稀硫酸后铜粉为什么能继续溶解；(2) 写出此时发生反应的离子方程式。","clues":"溶液中大量存在 Cu(NO₃)₂ 提供的 NO₃⁻，缺乏的只是 H⁺！","strategy":"指出稀硫酸补足了 H⁺，使溶液中原本不反应的 NO₃⁻ 重新获得强氧化性。","given":"溶液含 Cu(NO₃)₂（即 NO₃⁻），余有 Cu，加入稀 H₂SO₄（即 H⁺）","principle":"NO₃⁻ 在酸性条件（H⁺ 存在）下具有强氧化性，与酸的来源无关。","steps":["(1) 反应停止时，稀硝酸中的 \\(\\mathrm{H^+}\\) 已耗尽，但溶液中仍留有大量未参与还原的 \\(\\mathrm{NO_3^-}\\)（来自生成的 \\(\\mathrm{Cu(NO_3)_2}\\)）。滴加稀硫酸后引入了 \\(\\mathrm{H^+}\\)，使 \\(\\mathrm{NO_3^-}\\) 在酸性环境下重新表现强氧化性，继续将剩余铜氧化溶解并放出 \\(\\mathrm{NO}\\) 气体（在管口遇空气氧化成红棕色 \\(\\mathrm{NO_2}\\)）。","(2) 离子方程式：\\(\\mathrm{3Cu(s) + 8H^+(aq) + 2NO_3^-(aq) \\longrightarrow 3Cu^{2+}(aq) + 2NO(g)\\uparrow + 4H_2O(l)}\\)。"],"answer":"(1) 稀硫酸提供了 H⁺，激活溶液中剩余的 NO₃⁻ 氧化溶解铜；(2) \\(\\mathrm{3Cu + 8H^+ + 2NO_3^- \\to 3Cu^{2+} + 2NO\\uparrow + 4H_2O}\\)。","markingPoints":["指出溶液中尚存 NO₃⁻ 且稀硫酸补足了 H⁺（2分）","正确写出离子方程式并配平电荷与原子（2分）"],"verification":"左右电荷均为 +6（左 8×(+1)+2×(-1)=+6；右 3×(+2)=+6），原子守恒。","pitfall":"误答“稀硫酸和铜反应放出氢气”，稀硫酸单独绝对不能溶解铜！"}],"practice":[{"id":"chem13-13.3-q1","tier":"L1","tierLabel":"L1 基础","examStyle":"P1 选择","q":"常温下能用铝制槽车或容器安全储运的试剂是（　）。","options":["A. 浓盐酸","B. 浓硝酸","C. 稀硝酸","D. 稀硫酸"],"correctOption":"B","given":"金属铝与四种常见酸常温作用","method":"识别冷浓氧化性酸的钝化现象","principle":"常温下冷浓硝酸（及冷浓硫酸）可使 Fe、Al 表面钝化形成致密氧化膜。","steps":["浓盐酸、稀硝酸、稀硫酸均会持续腐蚀铝；唯有冷浓硝酸使铝表面钝化，故可用铝槽车储运（教材思考题 13c 第1题）。"],"ans":"B","markingPoints":["准确识别冷浓硝酸使铝钝化"],"verification":"对照化上 p.305 感知生活与 p.307。","pitfall":"误以为稀硝酸也能使铝钝化。"},{"id":"chem13-13.3-q2","tier":"L2","tierLabel":"L2 期末","examStyle":"P1 选择","q":"下列关于硝酸的叙述，正确的是（　）。","options":["A. 稀硝酸是弱酸，浓硝酸是强酸","B. 铜与浓硝酸和稀硝酸都能反应生成二氧化氮","C. 浓硝酸和稀硝酸都是强氧化剂","D. 稀硝酸与活泼金属反应主要放出氢气，而浓硝酸则使金属钝化"],"correctOption":"C","given":"硝酸酸性与氧化性辨析（教材思考题 13c 第2题）","method":"逐项检验硝酸浓度对其酸性与氧化性的影响","principle":"浓稀硝酸皆为强酸且皆为强氧化剂；与金属反应一般不放 H₂。","steps":["A 错：稀硝酸同样完全电离，属于强酸。","B 错：Cu 与稀硝酸主要生成 NO，而非 NO₂。","C 对：无论浓稀均具强氧化性（+5 价 N）。","D 错：稀硝酸与活泼金属反应放出 NO、N₂O 等而非 H₂；浓硝酸仅使 Fe、Al 在常温下钝化，不能使其他活泼金属（如 Zn、Mg）钝化。"],"ans":"C","markingPoints":["把握稀硝酸也是强酸和强氧化剂"],"verification":"对照化上 p.309 思考题 13c。","pitfall":"受中学一般酸与金属产 H₂ 的惯性思维误选 D。"},{"id":"chem13-13.3-q3","tier":"L3","tierLabel":"L3 预试","examStyle":"P2 实验与工业","q":"工业上采用奥斯特瓦尔德法（氨催化氧化法）生产硝酸：(1) 写出氨气在铂—铑合金催化加热下的反应方程式，并标明反应中电子转移的方向或氧化剂、还原剂；(2) 在第三步二氧化氮被水吸收的塔中，为什么通常需要一边通入水一边补充一定量的空气？写出相关总反应解释。","given":"Ostwald process 三步骤（化上 p.308）","method":"根据 3NO₂+H₂O→2HNO₃+NO 解释补空气氧化副产 NO 的作用","principle":"2NO + O₂ → 2NO₂ 与循环吸收以提高氮原子利用率。","steps":["(1) \\(\\mathrm{4NH_3(g) + 5O_2(g)} \\xrightarrow{\\text{Pt-Rh}/\\Delta} \\mathrm{4NO(g) + 6H_2O(g)}\\)。其中 \\(\\mathrm{O_2}\\)（0 → −2）为氧化剂，\\(\\mathrm{NH_3}\\)（−3 → +2）为还原剂。","(2) 因为 \\(\\mathrm{3NO_2(g) + H_2O(l) \\longrightarrow 2HNO_3(aq) + NO(g)}\\) 中只有 \\(2/3\\) 的 \\(\\mathrm{NO_2}\\) 转化为 \\(\\mathrm{HNO_3}\\)，其余 \\(1/3\\) 转变为 \\(\\mathrm{NO}\\)；补充空气中的 \\(\\mathrm{O_2}\\) 可不断将副产 \\(\\mathrm{NO}\\) 重新氧化为 \\(\\mathrm{NO_2}\\)（\\(\\mathrm{2NO + O_2 \\to 2NO_2}\\)），使氮氧化物尽可能完全转化为硝酸并减少尾气污染。"],"ans":"(1) \\(\\mathrm{4NH_3+5O_2 \\xrightarrow{\\text{Pt-Rh}/\\Delta} 4NO+6H_2O}\\)；(2) 将水吸收产生的 NO 氧化回 NO₂ 循环吸收，提高原料利用率。","markingPoints":["催化氧化方程式及氧化剂还原剂准确（2分）","写出 3NO₂+H₂O 方程并说明 1/3 变为 NO 需空气氧化循环利用（2分）"],"verification":"总循环合式：\\(\\mathrm{4NO_2 + O_2 + 2H_2O \\to 4HNO_3}\\)。","pitfall":"误写氨催化氧化直接生成 NO₂。"},{"id":"chem13-13.3-q4","tier":"L4","tierLabel":"L4 统考压轴","examStyle":"P2 综合计算","q":"将 \\(1.92\\text{ g}\\) 铜粉投入一定量浓硝酸中，铜粉完全溶解后收集到标准状况下的气体共 \\(1.12\\text{ L}\\)（仅含 \\(\\mathrm{NO_2}\\) 和 \\(\\mathrm{NO}\\)）。(1) 计算生成的气体中 \\(\\mathrm{NO_2}\\) 和 \\(\\mathrm{NO}\\) 各有多少摩尔；(2) 若要使收集到的该 \\(1.12\\text{ L}\\) 混合气体通入足量水中恰好完全转化为硝酸而无任何气体剩余，在标准状况下至少需要混入多少升空气（设空气中 \\(\\mathrm{O_2}\\) 体积分数为 \\(20\\%\\)）？","given":"m(Cu) = 1.92 g (0.030 mol)，V(气体, STP) = 1.12 L (0.050 mol)","method":"先由电子守恒与气体总物质的量求 NO₂ 和 NO；再用“全过程电子守恒”（Cu 失电子数 = O₂ 得电子数）一步求需氧量！","principle":"Cu → Cu²⁺ 失电子最终全部转移给 O₂！","steps":["(1) \\(n(\\mathrm{Cu}) = \\frac{1.92}{64} = 0.030\\text{ mol}\\)，失去电子 \\(0.060\\text{ mol}\\)；气体总物质的量 \\(n(\\mathrm{NO_2}) + n(\\mathrm{NO}) = \\frac{1.12}{22.4} = 0.050\\text{ mol}\\)。","设 \\(n(\\mathrm{NO_2}) = a\\)，\\(n(\\mathrm{NO}) = b\\)，则 \\(a + b = 0.050\\) 且 \\(a + 3b = 0.060\\)。","解得 \\(2b = 0.010 \\implies b = 0.0050\\text{ mol}\\ \\mathrm{NO}\\)，\\(a = 0.045\\text{ mol}\\ \\mathrm{NO_2}\\)。","(2) 全过程（\\(\\mathrm{HNO_3}\\) 先被 Cu 还原成气体，气体又被 \\(\\mathrm{O_2}\\) 氧化回 \\(\\mathrm{HNO_3}\\)，N 的价态原地转一圈归 +5）本质等价于 \\(\\mathrm{Cu}\\) 失去的 \\(0.060\\text{ mol }e^-\\) 全部被 \\(\\mathrm{O_2}\\) 吸收！","故需氧气：\\(n(\\mathrm{O_2}) = \\frac{0.060}{4} = 0.015\\text{ mol}\\)，\\(V(\\mathrm{O_2}) = 0.015 \\times 22.4 = 0.336\\text{ L}\\)。","至少需要空气体积：\\(V(\\text{空气}) = \\frac{0.336\\text{ L}}{20\\%} = 1.68\\text{ L}\\)。"],"ans":"(1) \\(n(\\mathrm{NO_2}) = 0.045\\text{ mol}\\)，\\(n(\\mathrm{NO}) = 0.0050\\text{ mol}\\)；(2) 至少需要空气 \\(1.68\\text{ L}\\)。","markingPoints":["正确求得 n(NO₂)=0.045 mol 与 n(NO)=0.0050 mol（2分）","求得需 O₂ 为 0.015 mol / 0.336 L（2分）","折算为空气体积 1.68 L（1分）"],"verification":"分步验证需氧量：\\(\\frac{1}{4}(0.045) + \\frac{3}{4}(0.0050) = 0.01125 + 0.00375 = 0.015\\text{ mol}\\)，完全一致！","pitfall":"最后忘记除以空气含氧量 20%，误把 0.336 L 当作空气体积是常见大题扣分点。"}],"cheatSheet":["浓硝酸（~69%, 16 mol/L）见光分解 4HNO₃ → 4NO₂↑ + O₂↑ + 2H₂O，棕色瓶阴凉保存；王水 = 浓HNO₃ : 浓HCl = 1:3（体积比）。","Cu+4HNO₃(浓) → 2NO₂↑；3Cu+8HNO₃(稀) → 2NO↑；冷浓硝酸使 Fe、Al 钝化（化学变化）。","奥斯特瓦尔德法 3 步：4NH₃+5O₂→4NO+6H₂O；2NO+O₂→2NO₂；3NO₂+H₂O→2HNO₃+NO。"],"kbEntryIds":["kb-chem13-hno3-redox","kb-chem13-hno3-ostwald"],"quiz":{"q":"实验室将固体硝酸钠与浓硫酸放在曲颈甑中微微加热制取硝酸，写出化学方程式并说明为什么生成的是 \\(\\mathrm{NaHSO_4}\\) 而不是 \\(\\mathrm{Na_2SO_4}\\)。","given":"化上 p.307 图13-9 实验室制硝酸","method":"考虑硝酸易受热分解及反应温度不宜过高","principle":"高沸点酸制低沸点挥发性酸。","steps":["反应式：\\(\\mathrm{NaNO_3(s) + H_2SO_4(aq,\\text{浓})} \\xrightarrow{\\Delta} \\mathrm{NaHSO_4(s) + HNO_3(g)}\\uparrow\\)。","生成 \\(\\mathrm{Na_2SO_4}\\) 需强热至高温，而高温会导致制得的 \\(\\mathrm{HNO_3}\\) 剧烈分解为 \\(\\mathrm{NO_2}\\) 和 \\(\\mathrm{O_2}\\)。"],"ans":"\\(\\mathrm{NaNO_3 + H_2SO_4(\\text{浓})} \\xrightarrow{\\Delta} \\mathrm{NaHSO_4 + HNO_3\\uparrow}\\)；高温虽可得 \\(\\mathrm{Na_2SO_4}\\)，但会造成 \\(\\mathrm{HNO_3}\\) 受热分解。"}},{"id":"13.4","t":"硝酸盐","anchor":{"pages":"化上 p.309–315","syllabus":"3.7.4 硝酸盐热分解规律、NO₃⁻ 棕色环检验与自然界氮循环","examScopes":["sem2_final","uec"],"examWeight":"P1 硝酸盐热分解规律与金属位置判断 + P2 棕色环检验实验探究","terms":"thermal decomposition of nitrates · brown ring test · black powder · nitrogen cycle","prerequisites":["金属活动性顺序与氧化物稳定性","Fe²⁺ 的还原性与硝酸根在酸性下的氧化性"],"goals":["熟记表13-4 三类金属硝酸盐（活泼、较不活泼、不活泼）受热分解的产物通式与典型方程式。","独立完成活动5“棕色环实验”操作步骤、试剂顺序及三步反应原理，掌握亚硝酸钠的工业用途与防误食安全常识。","结合氮的循环图说明固氮（雷电、根瘤菌、工业合成氨）与脱氮作用维持生态平衡的意义。"]},"concepts":[{"kind":"table","title":"硝酸盐通性与三类热分解规律（表13-4）","pageRef":"化上 p.310–311","body":["**通性**：所有硝酸盐均极易溶于水，多数有潮解性（吸湿性）；固体受热极易分解并放出氧气，因此**高温下硝酸盐是强氧化剂**。随金属活动性由强到弱，分解产物分为三类（活动3 硝酸铜分解、活动4 硝酸银分解）。"],"table":{"headers":["硝酸盐类别","典型代表","受热分解产物","教材典型化学方程式","固体与气体特征现象"],"rows":[["活泼金属的硝酸盐","\\(\\mathrm{KNO_3}\\)、\\(\\mathrm{NaNO_3}\\)","亚硝酸盐 + \\(\\mathrm{O_2}\\)","\\(\\mathrm{2NaNO_3(s)} \\xrightarrow{\\Delta} \\mathrm{2NaNO_2(s) + O_2(g)}\\)","无红棕色气体，放出的无色气体使带余烬木枝复燃"],["较不活泼金属的硝酸盐","\\(\\mathrm{Mg, Al, Zn, Fe, Pb, Cu}\\) 硝酸盐","金属氧化物 + \\(\\mathrm{NO_2}\\) + \\(\\mathrm{O_2}\\)","\\(\\mathrm{2Cu(NO_3)_2(s)} \\xrightarrow{\\Delta} \\mathrm{2CuO(s) + 4NO_2(g) + O_2(g)}\\)","蓝色晶体变黑（CuO），产生红棕色 \\(\\mathrm{NO_2}\\)，U型管冷却液化 \\(\\mathrm{N_2O_4}\\) 后带余烬木枝在管口复燃（若不冷却，\\(4\\mathrm{NO_2}:1\\mathrm{O_2}\\) 比例 \\(\\mathrm{O_2}\\) 占 20% 与空气相近或因 \\(\\mathrm{NO_2}\\) 助燃）"],["不活泼金属的硝酸盐","\\(\\mathrm{Hg(NO_3)_2}\\)、\\(\\mathrm{AgNO_3}\\)","金属单质 + \\(\\mathrm{NO_2}\\) + \\(\\mathrm{O_2}\\)","\\(\\mathrm{2AgNO_3(s)} \\xrightarrow{\\Delta} \\mathrm{2Ag(s) + 2NO_2(g) + O_2(g)}\\)","白色固体最终留下银白/灰黑银单质，放红棕色 \\(\\mathrm{NO_2}\\) 与 \\(\\mathrm{O_2}\\)（\\(2:1\\) 比空气更富氧，木枝剧烈复燃）"]]},"takeaway":"判断标准是“受热后金属氧化物的热稳定性”：Ag₂O、HgO 受热也会继续分解为单质金属，故不活泼金属硝酸盐直接分解成金属！"},{"kind":"experiment","title":"活动5：棕色环法（Brown ring test）检验硝酸根","pageRef":"化上 p.312–313","body":["**实验步骤（活动5）**：① 取少量待测硝酸盐样品溶于水；② 加入少量**新制备的硫酸铁(II)（\\(\\mathrm{FeSO_4}\\)）溶液**；③ 倾斜试管，沿内壁**慢慢加入浓硫酸**（密度大沉入下层，切勿振荡混匀）。","**实验现象（图13-14）**：在浓硫酸与水溶液两液相的交界面处出现一个清晰的**棕色环**。","**三步反应机理**：① 浓硫酸与硝酸盐生成硝酸：\\(\\mathrm{NO_3^-(aq) + H_2SO_4(aq,\\text{浓}) \\to HSO_4^-(aq) + HNO_3(aq)}\\)；② 硝酸被 \\(\\mathrm{Fe^{2+}}\\) 还原为 \\(\\mathrm{NO}\\)：\\(\\mathrm{2HNO_3(aq) + 6FeSO_4(aq) + 3H_2SO_4(aq) \\to 3Fe_2(SO_4)_3(aq) + 4H_2O(l) + 2NO(g)}\\)；③ 生成棕色配合物：\\(\\mathrm{FeSO_4(aq) + NO(g) \\to FeSO_4\\cdot NO(aq)}\\)（棕色环）。"],"takeaway":"棕色环化合物 FeSO₄·NO 受热或振荡极易分解破坏，故滴加浓硫酸时必须沿管壁缓慢流下形成清晰分层！"},{"kind":"definition","title":"重要硝酸盐（KNO₃、NH₄NO₃、NaNO₂）与自然界氮循环","pageRef":"化上 p.311–314","body":["**硝酸钾（黑火药，图13-11）**：黑火药含 \\(75\\%\\ \\mathrm{KNO_3}\\)、\\(10\\%\\) 硫磺与 \\(15\\%\\) 木炭粉，点燃爆发：\\(\\mathrm{2KNO_3(s) + 3C(s) + S(s)} \\xrightarrow{\\text{点燃}} \\mathrm{K_2S(s) + N_2(g) + 3CO_2(g)}\\)。","**硝酸铵（\\(\\mathrm{NH_4NO_3}\\)）**：含氮量约 \\(35\\%\\)（\\(28/80\\)），是速效性氮肥，工业上用于制笑气与维生素 B 等；**亚硝酸钠（\\(\\mathrm{NaNO_2}\\)）**：俗称“工业盐”，外观味似食盐但剧毒，用于混凝土防冻促凝剂与肉类发色防腐剂，严防误食。","**氮的循环（图13-15）**：游离态 \\(\\mathrm{N_2}\\) 经**固氮作用**（雷电固氮、豆科植物根瘤菌生物固氮、工业合成氨人工固氮）转为氨/铵盐或硝酸盐被植物吸收合成蛋白质，动物摄食；动植物遗体排泄物经土壤细菌分解复归铵盐与硝酸盐，土壤**脱氮菌**再把部分硝酸盐还原为 \\(\\mathrm{N_2}\\) 返回大气。"],"takeaway":"氮循环中氮元素既有被氧化（如 N₂ → NO、NH₄⁺ → NO₃⁻ 硝化）也有被还原（如 N₂ → NH₃ 固氮、NO₃⁻ → N₂ 脱氮）。"}],"formulas":[{"title":"黑火药爆炸与硝酸盐三类热分解核心方程式","tex":"\\mathrm{2KNO_3 + 3C + S} \\xrightarrow{\\text{点燃}} \\mathrm{K_2S + N_2\\uparrow + 3CO_2\\uparrow},\\qquad \\mathrm{2Cu(NO_3)_2} \\xrightarrow{\\Delta} \\mathrm{2CuO + 4NO_2\\uparrow + O_2\\uparrow}","plain":"2KNO3 + 3C + S --点燃--> K2S + N2 + 3CO2; 2Cu(NO3)2 --Δ--> 2CuO + 4NO2 + O2","conditions":"黑火药配比 KNO₃:S:C = 75%:10%:15%；硝酸铜加热分解","pageRef":"化上 p.311","note":"对比气体体积比：较不活泼金属二价硝酸盐分解 NO₂:O₂ = 4:1；AgNO₃ 分解 NO₂:O₂ = 2:1。"},{"title":"棕色环检验硝酸根的三步反应式","tex":"\\mathrm{2HNO_3 + 6FeSO_4 + 3H_2SO_4 \\longrightarrow 3Fe_2(SO_4)_3 + 4H_2O + 2NO},\\qquad \\mathrm{FeSO_4 + NO \\longrightarrow FeSO_4\\cdot NO}","plain":"2HNO3 + 6FeSO4 + 3H2SO4 -> 3Fe2(SO4)3 + 4H2O + 2NO; FeSO4 + NO -> FeSO4·NO","conditions":"新制 FeSO₄ 溶液 + 沿壁缓加浓硫酸不摇晃","pageRef":"化上 p.312–313","note":"不可使用久置氧化变质（已含大量 Fe³⁺）的硫酸亚铁溶液。"}],"pitfalls":[{"title":"误把所有硝酸盐分解产气比当成 4:1","wrong":"“某二价金属硝酸盐加热分解生成 \\(\\mathrm{NO_2}\\) 和 \\(\\mathrm{O_2}\\) 的物质的量之比为 \\(2:1\\)，因此该金属在反应中化合价不变。”","diagnosis":"若金属氧化数不变（由 +2 变为 +2 氧化物），电子全由 \\(+5 \\to +4\\) 的 N（得 1e⁻）与 \\(-2 \\to 0\\) 的 O（每 1 个 O₂ 失 4e⁻）交换，故 \\(\\mathrm{NO_2}:\\mathrm{O_2}\\) 必为 \\(4:1\\)！若比为 \\(2:1\\)（如 \\(\\mathrm{AgNO_3}\\) 或 \\(\\mathrm{Fe(NO_3)_2} \\to \\mathrm{Fe_2O_3}\\)），说明有额外电子出入！","right":"当硝酸盐分解产 \\(\\mathrm{NO_2}\\) 与 \\(\\mathrm{O_2}\\) 的比为 \\(2:1\\) 时：对 \\(\\mathrm{AgNO_3}\\) 是 \\(\\mathrm{Ag^+}\\) 降为 \\(\\mathrm{Ag}\\)（氧化数**降低**）；若分解产生高价氧化物（假想情况）则升高。按教材思考题 13d 第1题，典型即 \\(\\mathrm{AgNO_3}\\) 或 \\(\\mathrm{Hg(NO_3)_2}\\)，该金属氧化数**降低**！","checkRule":"牢记：\\(\\mathrm{NO_2}:\\mathrm{O_2}=4:1 \\iff\\) 金属价态不变；\\(\\mathrm{NO_2}:\\mathrm{O_2} < 4:1\\)（即 O₂ 偏多）\\(\\iff\\) 金属也得电子（化合价降低）！"},{"title":"棕色环实验中直接滴加浓硫酸并剧烈振荡","wrong":"“将硝酸盐溶液、硫酸铁(II)溶液与浓硫酸在试管中充分振荡混合，整支试管变为均匀棕色即证明含 \\(\\mathrm{NO_3^-}\\)。”","diagnosis":"振荡混匀会放出大量稀释热，导致 \\(\\mathrm{FeSO_4\\cdot NO}\\) 立刻受热分解且干扰层消失。","right":"必须**沿管壁缓慢注入浓硫酸**让其沉至管底，静置在两液界面观察清晰的棕色环。","checkRule":"棕色环实验关键词：新制 FeSO₄、沿管壁缓加浓 H₂SO₄、勿振荡、界面棕色环。"}],"examples":[{"label":"例 13.4.1","tier":"L3","tierLabel":"L3 预试拔高","title":"硝酸铜热分解实验现象与气体倒扣水槽计算","prompt":"按教材活动3 图13-12 装置加热干燥的硝酸铜(II)晶体 \\(\\mathrm{Cu(NO_3)_2}\\)。(1) 若将反应产生的混合气体（未经过冰盐冷却）直接全部通入倒立在水槽中的大试管内，最终试管内液面上升至试管容积的几分之几？(2) 若用带余烬的木枝分别伸入直接收集的混合气体和经过冰盐 U 型管冷却后的气体，现象有何不同？","clues":"写准 2Cu(NO₃)₂ —Δ→ 2CuO + 4NO₂ + O₂ 中 NO₂ : O₂ = 4 : 1，对照 4NO₂ + O₂ + 2H₂O = 4HNO₃！","strategy":"利用 NO₂ 与 O₂ 恰为 4:1 判断是否全部溶于水；根据 O₂ 体积分数对比判断是否强烈复燃。","given":"2Cu(NO₃)₂(s) —Δ→ 2CuO(s) + 4NO₂(g) + O₂(g)","principle":"4NO₂ + O₂ + 2H₂O = 4HNO₃（恰好完全吸收）。","steps":["(1) 由 \\(\\mathrm{2Cu(NO_3)_2(s)} \\xrightarrow{\\Delta} \\mathrm{2CuO(s) + 4NO_2(g) + O_2(g)}\\) 可知，生成 \\(\\mathrm{NO_2}\\) 与 \\(\\mathrm{O_2}\\) 的物质的量（同温压下体积）之比恰好为 \\(4:1\\)。","该比例与 \\(\\mathrm{4NO_2(g) + O_2(g) + 2H_2O(l) \\longrightarrow 4HNO_3(aq)}\\) 完全吻合，因此气体全部转化为硝酸溶于水，无气体剩余，水**充满整支试管**（液面上升至 \\(1\\) 或 \\(100\\%\\)）。","(2) 直接收集的混合气体中 \\(\\mathrm{O_2}\\) 体积分数为 \\(\\frac{1}{4+1} = 20\\%\\)（与空气中 \\(\\mathrm{O_2}\\) 约 \\(21\\%\\) 接近），带余烬的木枝在此混合气中**不复燃（或迅速熄灭/微弱闪亮，若计入 NO₂ 助燃性则较弱，教材思考题 13d 第2题考查若直接收集并考虑氧浓度约为 20% 与空气相近或熄灭/无明显复燃）**；而经冰+盐 U 型管冷却后，\\(\\mathrm{NO_2}\\) 液化为红棕色 \\(\\mathrm{N_2O_4}\\) 留在 U 型管内，逸出的几乎为纯 \\(\\mathrm{O_2}\\)，故带余烬的木枝**立刻剧烈复燃**！"],"answer":"(1) 充满整支试管（全部溶解）；(2) 经冰盐冷却除去 NO₂ 后逸出纯 O₂ 使带余烬木枝复燃（未冷却时 O₂ 仅占 20% 且混有大量 NO₂）。","markingPoints":["指出分解产出 NO₂:O₂=4:1 并结合 4NO₂+O₂+2H₂O=4HNO₃ 得出完全吸收（2分）","解释冰盐 U 型管液化分离 NO₂ 后得纯 O₂ 令木枝复燃（2分）"],"verification":"注意对比教材 p.310 图13-12 与 p.315 思考题 13d 第2题：图13-12 正是利用了“冰+盐”冷却除去 NO₂ 后再在末端试管用带余烬木枝检验 O₂！","pitfall":"若把未经过冰盐浴直接收集到的 4NO₂+O₂ 气体误以为全是 O₂，忽略了 NO₂ 占 80% 体积。"},{"label":"例 13.4.2","tier":"L4","tierLabel":"L4 统考压轴","title":"未知硝酸盐热分解产物的定量推断","prompt":"称取 \\(10.2\\text{ g}\\) 无水硝酸银（\\(\\mathrm{AgNO_3}\\)）与硝酸钠（\\(\\mathrm{NaNO_3}\\)）的固体混合物，充分加热至质量不再变化，冷却后称得剩余固体总质量为 \\(7.08\\text{ g}\\)。试通过计算求原混合物中 \\(\\mathrm{AgNO_3}\\) 的质量分数。（\\(\\mathrm{Na}=23,\\ \\mathrm{N}=14,\\ \\mathrm{O}=16,\\ \\mathrm{Ag}=108\\)）","clues":"AgNO₃ → Ag + NO₂↑ + ½O₂↑（1 mol AgNO₃ 减重 62 g）；NaNO₃ → NaNO₂ + ½O₂↑（1 mol NaNO₃ 减重 16 g）！","strategy":"利用“差量法”设 AgNO₃ 与 NaNO₃ 物质的量，联立总质量和总减重。","given":"m(原固体)=10.2 g，m(剩余固体)=7.08 g，Δm=3.12 g","principle":"不同类别硝酸盐受热分解反应计量关系与质量差守恒。","steps":["总质量减少：\\(\\Delta m = 10.2\\text{ g} - 7.08\\text{ g} = 3.12\\text{ g}\\)。","写出两分解式及每 \\(1\\text{ mol}\\) 固体减重：\\(M(\\mathrm{AgNO_3}) = 170\\text{ g}\\cdot\\mathrm{mol^{-1}}\\)，\\(\\mathrm{AgNO_3} \\xrightarrow{\\Delta} \\mathrm{Ag} + \\mathrm{NO_2\\uparrow} + \\frac{1}{2}\\mathrm{O_2\\uparrow}\\)，每 \\(1\\text{ mol}\\) 减重 \\(170 - 108 = 62\\text{ g}\\)。","\\(M(\\mathrm{NaNO_3}) = 85\\text{ g}\\cdot\\mathrm{mol^{-1}}\\)，\\(\\mathrm{NaNO_3} \\xrightarrow{\\Delta} \\mathrm{NaNO_2} + \\frac{1}{2}\\mathrm{O_2\\uparrow}\\)，每 \\(1\\text{ mol}\\) 减重 \\(85 - 69 = 16\\text{ g}\\)。","设原混合物含 \\(\\mathrm{AgNO_3}\\ x\\text{ mol}\\)，\\(\\mathrm{NaNO_3}\\ y\\text{ mol}\\)：","\\(170x + 85y = 10.2\\)（除以 85 得 \\(2x + y = 0.12\\)）；\\(62x + 16y = 3.12\\)。","将 \\(y = 0.12 - 2x\\) 代入减重方程：\\(62x + 16(0.12 - 2x) = 3.12 \\implies 30x + 1.92 = 3.12 \\implies 30x = 1.20 \\implies x = 0.040\\text{ mol}\\)，\\(y = 0.040\\text{ mol}\\)。","\\(\\mathrm{AgNO_3}\\) 质量分数：\\(w(\\mathrm{AgNO_3}) = \\frac{0.040 \\times 170}{10.2} \\times 100\\% = \\frac{6.80}{10.2} \\times 100\\% \\approx 66.7\\%\\)。"],"answer":"原混合物中 \\(\\mathrm{AgNO_3}\\) 的质量分数约为 \\(66.7\\%\\)。","markingPoints":["正确写出 AgNO₃ 与 NaNO₃ 两个热分解方程式及每摩尔固体减重 62 g、16 g（2分）","列出联立方程 170x+85y=10.2 与 62x+16y=3.12（2分）","解出 x=0.040 mol 并算得质量分数 66.7%（1分）"],"verification":"验证：\\(0.040\\text{ mol Ag}(4.32\\text{ g}) + 0.040\\text{ mol }\\mathrm{NaNO_2}(2.76\\text{ g}) = 7.08\\text{ g}\\)，完全一致！","pitfall":"若把 NaNO₃ 的热分解产物误记为 Na₂O + NO₂ + O₂，会导致方程彻底写错。"}],"practice":[{"id":"chem13-13.4-q1","tier":"L1","tierLabel":"L1 基础","examStyle":"P1 选择","q":"下列硝酸盐受热分解后，能得到金属单质、二氧化氮和氧气的是（　）。","options":["A. \\(\\mathrm{KNO_3}\\)","B. \\(\\mathrm{Cu(NO_3)_2}\\)","C. \\(\\mathrm{AgNO_3}\\)","D. \\(\\mathrm{Mg(NO_3)_2}\\)"],"correctOption":"C","given":"表13-4 硝酸盐热分解三类规律","method":"依据金属活泼性定位硝酸盐分解产物","principle":"不活泼金属（Hg、Ag）的硝酸盐分解生成金属单质 + NO₂ + O₂。","steps":["KNO₃ 得 KNO₂+O₂；Cu(NO₃)₂ 和 Mg(NO₃)₂ 得金属氧化物+NO₂+O₂；AgNO₃ 得 Ag+NO₂+O₂。"],"ans":"C","markingPoints":["准确识别不活泼金属硝酸盐产物"],"verification":"对照化上 p.311 表13-4。","pitfall":"误选 B（Cu(NO₃)₂ 分解得到黑色 CuO 固体，不是单质铜）。"},{"id":"chem13-13.4-q2","tier":"L2","tierLabel":"L2 期末","examStyle":"P1 选择","q":"下列关于自然界中氮循环的说法，**不正确**的是（　）。","options":["A. 氮循环过程中，氮元素均被氧化","B. 工业合成氨属于人工固氮","C. 含氮无机物和含氮有机物可相互转化","D. 碳、氢、氧三种元素也参与了氮循环"],"correctOption":"A","given":"氮循环路径（化上 p.314 图13-15，思考题 13d 第3题）","method":"分析固氮、硝化与脱氮过程的价态升降","principle":"氮循环既含氧化也含还原过程。","steps":["A 错：固氮（如 N₂ → NH₃）和脱氮作用（NO₃⁻ → N₂）中氮元素价态降低被还原，并非均被氧化。"],"ans":"A","markingPoints":["识别氮循环包含氧化和还原双向转化"],"verification":"对照化上 p.315 思考题 13d 第3题。","pitfall":"误认为氮气变硝酸盐才是固氮而忽略根瘤菌和合成氨还原路径。"},{"id":"chem13-13.4-q3","tier":"L3","tierLabel":"L3 预试","examStyle":"P2 实验探究","q":"实验室用“棕色环法”检验某无色溶液是否为硝酸盐溶液，操作如下：取 \\(2\\text{ mL}\\) 待测液于试管中，加入少量新制的 \\(\\mathrm{FeSO_4}\\) 溶液，再沿试管内壁缓慢滴入浓硫酸并静置。(1) 观察到的阳性现象是什么？写出最终显色物质的化学式；(2) 若实验人员错用了久置泛黄的 \\(\\mathrm{FeSO_4}\\) 溶液，或在滴入浓硫酸后用力振荡试管，实验均会失败，分别解释原因。","given":"棕色环法（化上 p.312–313 活动5）","method":"从 Fe²⁺ 还原性与 FeSO₄·NO 热稳定性分析失败原因","principle":"棕色环为 FeSO₄·NO；Fe²⁺ 易被氧化，FeSO₄·NO 受热/振荡易分解。","steps":["(1) 两液分层交界面出现**棕色环**，显色物质为 \\(\\mathrm{FeSO_4\\cdot NO}\\)。","(2) ① 久置泛黄的 \\(\\mathrm{FeSO_4}\\) 溶液中 \\(\\mathrm{Fe^{2+}}\\) 已被空气氧化为 \\(\\mathrm{Fe^{3+}}\\)，失去还原 \\(\\mathrm{HNO_3}\\) 生成 \\(\\mathrm{NO}\\) 及络合 \\(\\mathrm{NO}\\) 的能力；② 滴入浓硫酸后若用力振荡，浓硫酸稀释剧烈放热使不稳定的棕色配合物 \\(\\mathrm{FeSO_4\\cdot NO}\\) 分解，棕色环随即消失。"],"ans":"(1) 界面出现棕色环，\\(\\mathrm{FeSO_4\\cdot NO}\\)；(2) 久置变质失去 Fe²⁺，振荡放热破坏分层及络合物。","markingPoints":["说出界面棕色环及化学式 FeSO₄·NO（2分）","解释 FeSO₄ 氧化变质与浓硫酸放热破坏络合物（2分）"],"verification":"对照化上 p.312 活动5 与 p.313 反应机理。","pitfall":"将显色物质错写为 Fe(NO₃)₃ 或棕黄色 Fe³⁺。"},{"id":"chem13-13.4-q4","tier":"L4","tierLabel":"L4 统考压轴","examStyle":"P1 选择","q":"某金属硝酸盐 \\(\\mathrm{M(NO_3)}_n\\) 受热完全分解，生成的二氧化氮和氧气的物质的量之比为 \\(2:1\\)，则在加热分解过程中，该金属元素 M 的氧化数（　）。","options":["A. 降低","B. 升高","C. 不变","D. 无法确定"],"correctOption":"A","given":"NO₂ : O₂ = 2 : 1（教材思考题 13d 第1题）","method":"得失电子守恒对比","principle":"若 M 价态不变，NO₂:O₂ 必为 4:1；现 O₂ 比例偏高（失电子多），必有 M 得电子降低氧化数。","steps":["生成 \\(2\\text{ mol }\\mathrm{NO_2}\\)（N: +5 → +4）仅得 \\(2\\text{ mol }e^-\\)；而生成 \\(1\\text{ mol }\\mathrm{O_2}\\)（O: −2 → 0）共失 \\(4\\text{ mol }e^-\\)。","失电子（4 mol）大于 N 所得电子（2 mol），差额 \\(2\\text{ mol }e^-\\) 必由金属离子 M 得电子，故 M 的氧化数**降低**（例如 \\(\\mathrm{2AgNO_3 \\to 2Ag + 2NO_2 + O_2}\\)）。"],"ans":"A","markingPoints":["用电子守恒判断 M 得电子氧化数降低"],"verification":"对照化上 p.315 思考题 13d 第1题。","pitfall":"不计算电子得失只凭直觉猜测。"}],"diagrams":[{"src":"assets/fig/v2/chem13-n-cycle.svg","caption":"图 13-1 氮及其化合物“价—类”二维转化全图（涵盖 NH₃、N₂、NO、NO₂、HNO₃ 与盐类核心反应）","alt":"氮及其化合物价类二维转化图","pageRef":"化上 p.298–322"}],"cheatSheet":["硝酸盐热分解（表13-4）：K/Na → 亚硝酸盐+O₂；Mg~Cu → 氧化物+4NO₂+O₂；Hg/Ag → 金属+2NO₂+O₂。","棕色环检验 NO₃⁻：样品 + 新制 FeSO₄ + 沿管壁缓加浓 H₂SO₄（勿摇），界面出棕色环 FeSO₄·NO。","电子守恒金规：硝酸盐分解产气 NO₂:O₂ = 4:1（M价态不变）；< 4:1 如 2:1（M价态降低，如 Ag）；> 4:1（M价态升高，如 Fe(NO₃)₂ → Fe₂O₃）。"],"kbEntryIds":["kb-chem13-nitrate-decomp"],"quiz":{"q":"某硝酸盐晶体受热分解生成金属氧化物、二氧化氮和氧气。若实验时将生成的混合气体全部通过足量水吸收（无空气混入）后无任何气体剩余，推测该硝酸盐中的金属离子加热前后氧化数是否改变？请举一例并写出反应式。","given":"生成物为金属氧化物 + NO₂ + O₂，且全部溶于水无剩余","method":"由 4NO₂ + O₂ + 2H₂O = 4HNO₃ 反推气体比 4:1","principle":"NO₂ : O₂ = 4 : 1 时，N 得电子数恰好等于 O 失电子数。","steps":["气体全溶于水无剩余意味着 \\(n(\\mathrm{NO_2}) : n(\\mathrm{O_2}) = 4 : 1\\)。","此时 N 得电子数等于 O 失电子数，金属元素氧化数保持不变。"],"ans":"不变；例如 \\(\\mathrm{2Cu(NO_3)_2(s)} \\xrightarrow{\\Delta} \\mathrm{2CuO(s) + 4NO_2(g) + O_2(g)}\\)"}},{"id":"13.5","t":"氨","anchor":{"pages":"化上 p.315–320","syllabus":"3.7.5 氨的性质（氢键、喷泉、弱碱性、还原性）与实验室/工业制法","examScopes":["sem2_final","uec"],"examWeight":"P1/P2 最高频板块（喷泉实验、干燥剂禁忌、哈伯合成氨、氨氧化）","terms":"ammonia · fountain experiment · ammonia solution · soda lime · Haber process","prerequisites":["氢键对物质沸点与溶解度的影响（化上 Ch 7.2.2）","可逆反应与氨水弱电解质概念"],"goals":["从氨分子间氢键与氨—水分子间氢键解释氨气易液化（制冷剂）及极易溶于水（1:700）的物理性质。","分析喷泉实验（活动6）和浓氨水+浓盐酸白烟实验（活动7）的原理，写出氨水中存在的平衡及与酸反应方程式。","掌握实验室加热氯化铵与氢氧化钙固体制氨的装置、碱石灰干燥原因（禁用浓硫酸、无水 CaCl₂）、棉花作用及哈伯合成氨工艺条件。"]},"concepts":[{"kind":"definition","title":"氨的物理性质、氢键作用与喷泉实验（活动6）","pageRef":"化上 p.316–317","body":["**物理性质**：氨（\\(\\mathrm{NH_3}\\)）是无色、有刺激性臭味的气体，密度比空气小（\\(M=17 < 29\\)）。因氨分子之间可形成**氢键**（图13-17），氨加压极易液化；液氨汽化吸收大量热，广泛用作制冷剂（图13-16 冷藏车）。","**极易溶于水（1:700）**：常温下 \\(1\\) 体积水约溶解 \\(700\\) 体积氨气。氨分子与水分子间形成氢键，大部分结合成一水合氨（\\(\\mathrm{NH_3\\cdot H_2O}\\)）。","**活动6 喷泉实验（图13-18）**：干燥圆底烧瓶充满 \\(\\mathrm{NH_3}\\)，挤压预先吸有少量水的胶头滴管，再打开止水夹。水进入烧瓶迅速溶解大量氨气使瓶内气压骤降，烧杯中的酚酞溶液被大气压压入烧瓶形成**红色喷泉**（证明氨极易溶于水且氨水呈碱性）。"],"takeaway":"喷泉实验成功三要素：烧瓶绝对干燥、氨气尽量充满、装置气密性良好（HCl、SO₂ 配 NaOH 也能做喷泉）。"},{"kind":"law","title":"氨水的弱碱性、与酸成盐及氨的还原性（活动7）","pageRef":"化上 p.317","body":["**弱碱性**：常温下约 \\(1\\%\\) 的 \\(\\mathrm{NH_3\\cdot H_2O}\\) 电离：\\(\\mathrm{NH_3(g) + H_2O(l) \\rightleftharpoons NH_3\\cdot H_2O(aq) \\rightleftharpoons NH_4^+(aq) + OH^-(aq)}\\)。一水合氨不稳定，受热分解放出氨气，故浓氨水加热可快速制氨。","**活动7 白烟实验**：分别蘸取浓氨水和浓盐酸（或浓硝酸）的两根玻璃棒相互靠近，上方冒出浓厚白烟：\\(\\mathrm{NH_3(g) + HCl(g) \\longrightarrow NH_4Cl(s)}\\)（挥发出的氨气与氯化氢直接化合生成氯化铵固体微粒；而蘸浓硫酸则无白烟，因浓硫酸不挥发）。","**还原性**：在催化剂（Pt、\\(\\mathrm{Fe_2O_3}\\)、\\(\\mathrm{Cr_2O_3}\\)）存在下，氨被氧气氧化为 \\(\\mathrm{NO}\\)（硝酸工业第一步）：\\(\\mathrm{4NH_3 + 5O_2} \\xrightarrow{\\text{催化剂}} \\mathrm{4NO + 6H_2O}\\)；也能在加热下还原 \\(\\mathrm{CuO}\\) 生成 \\(\\mathrm{Cu}\\)、\\(\\mathrm{H_2O}\\) 和 \\(\\mathrm{N_2}\\)。"],"takeaway":"氨水中的主要溶质分子是 NH₃·H₂O（不是 NH₄OH），水溶液中微粒有三种分子（NH₃、H₂O、NH₃·H₂O）与三种离子（NH₄⁺、OH⁻、极少 H⁺）。"},{"kind":"experiment","title":"活动8：实验室制氨装置细节与哈伯法工业合成氨","pageRef":"化上 p.318–319","body":["**实验室固固加热制法（图13-19）**：\\(\\mathrm{2NH_4Cl(s) + Ca(OH)_2(s)} \\xrightarrow{\\Delta} \\mathrm{CaCl_2(s) + 2NH_3(g)\\uparrow + 2H_2O(g)}\\)。","**关键装置细节（必考！）**：① 试管口略**向下倾斜**（防反应生成的水倒流炸裂试管）；② 干燥剂只能选**碱石灰**（\\(\\mathrm{NaOH + CaO}\\)），**严禁用浓硫酸**（酸碱中和）**或无水 \\(\\mathrm{CaCl_2}\\)**（会吸收 \\(\\mathrm{NH_3}\\) 生成 \\(\\mathrm{CaCl_2\\cdot 8NH_3}\\) 络合物）；③ 用**向下排空气法**收集（不可用排水法），收集试管口塞一团**棉花**（减小与空气对流，防氨气逸散并提高纯度；若用蘸稀硫酸的棉花置于多余尾气出口则可吸收尾气）；④ 检验集满：湿润红色石蕊试纸置于管口变蓝。","**哈伯法（Haber process，图13-21）**：\\(\\mathrm{N_2(g) + 3H_2(g)} \\underset{\\text{催化剂}}{\\stackrel{\\text{高温、高压}}{\\rightleftharpoons}} \\mathrm{2NH_3(g)}\\)，工业典型条件：**500℃**、**3×10⁷ Pa**、**铁粉催化剂**，单程转化率约 \\(15\\%\\)，通过冷却将 \\(\\mathrm{NH_3}\\) 液化分离，未反应的 \\(\\mathrm{N_2}\\)、\\(\\mathrm{H_2}\\) 循环压缩回反应器。"],"takeaway":"记住实验室干燥氨气唯一标配：碱石灰（或 NaOH 固体）；收集管口棉花防对流，绝不可使用无水 CaCl₂！"}],"formulas":[{"title":"氨水电离平衡及与酸反应通式","tex":"\\mathrm{NH_3(g) + H_2O(l) \\rightleftharpoons NH_3\\cdot H_2O(aq) \\rightleftharpoons NH_4^+(aq) + OH^-(aq)},\\qquad \\mathrm{2NH_3(g) + H_2SO_4(aq) \\longrightarrow (NH_4)_2SO_4(aq)}","plain":"NH3 + H2O ⇌ NH3·H2O ⇌ NH4+ + OH-; 2NH3 + H2SO4 -> (NH4)2SO4","conditions":"NH₃·H₂O 为一元弱碱，受热易逆向分解出 NH₃","pageRef":"化上 p.317","note":"向浓氨水中加入生石灰（CaO）或固体 NaOH，既吸水放热又增加 OH⁻ 浓度，可在不直接加热玻璃器皿时快速制氨。"},{"title":"实验室制氨气与工业哈伯合成氨方程式","tex":"\\mathrm{2NH_4Cl(s) + Ca(OH)_2(s)} \\xrightarrow{\\Delta} \\mathrm{CaCl_2(s) + 2NH_3(g)\\uparrow + 2H_2O(g)},\\qquad \\mathrm{N_2(g) + 3H_2(g)} \\underset{500\\ ^\\circ\\mathrm{C},\\ 3\\times 10^7\\text{ Pa}}{\\stackrel{\\text{铁粉}}{\\rightleftharpoons}} \\mathrm{2NH_3(g)}","plain":"2NH4Cl + Ca(OH)2 --Δ--> CaCl2 + 2NH3 + 2H2O; N2 + 3H2 ⇌ 2NH3","conditions":"实验室用固体 Ca(OH)₂（不用易结块腐蚀玻璃的 NaOH）且管口向下倾斜","pageRef":"化上 p.318–319","note":"实验室不可用 NH₄NO₃ 代替 NH₄Cl（硝酸铵受热易爆炸或分解生成 N₂O）。"}],"pitfalls":[{"title":"使用无水 CaCl₂ 或浓硫酸干燥氨气","wrong":"“氨气是中性或还原性气体，可用浓硫酸或无水氯化钙干燥瓶除去水蒸气。”","diagnosis":"\\(\\mathrm{NH_3}\\) 为碱性气体与浓硫酸发生中和；且 \\(\\mathrm{CaCl_2}\\) 会与 \\(\\mathrm{NH_3}\\) 形成 \\(\\mathrm{CaCl_2\\cdot 8NH_3}\\) 配合物。","right":"氨气只能选用碱性干燥剂（**碱石灰**、固体 \\(\\mathrm{NaOH}\\) 或生石灰 \\(\\mathrm{CaO}\\)）干燥（教材思考题 13e 第2、3题）。","checkRule":"遇到气体共存与干燥选择题，首先划掉“NH₃ + HCl / 浓 H₂SO₄ / CaCl₂”组合！"},{"title":"结束制氨实验时忘记先撤导管或未防倒吸","wrong":"“用浓氨水加热制氨结束时，先停止加热，再用水直接插导管吸收尾气。”","diagnosis":"停止加热且管内氨气极易溶于水导致负压骤增，水或稀硫酸会迅速倒吸入灼热试管引起炸裂。","right":"尾气吸收需用**浸有稀硫酸的棉花**置于导管口或用倒置漏斗防倒吸；用排水/液封操作结束时应先撤导管再熄灭酒精灯。","checkRule":"极易溶于水的气体（NH₃、HCl）尾气吸收必须设防倒吸措施（倒置漏斗、安全瓶或棉团）。"}],"examples":[{"label":"例 13.5.1","tier":"L3","tierLabel":"L3 预试拔高","title":"实验室制取并干燥氨气的装置评价与改良","prompt":"某学生设计用 \\(\\mathrm{NH_4Cl}\\) 固体与 \\(\\mathrm{Ca(OH)_2}\\) 固体共热制取干燥纯净的氨气，装置顺序为：试管（管口微向上倾斜）→ 盛有浓硫酸的洗气瓶 → 向上排空气法集气瓶 → 导管直接插入稀硫酸烧杯吸收尾气。(1) 请指出该设计中的**四处**明显错误；(2) 若改用浓氨水与生石灰快速制取氨气，说明生石灰在此过程中的双重作用。","clues":"逐一核查：发生管口朝向、干燥剂选择、排空气方向、尾气防倒吸。","strategy":"对照图13-19标准装置四部位依次排雷。","given":"错误装置四部分：试管朝向、浓硫酸、向上排空气、直插尾气","principle":"固体加热生水防倒流；碱性气体干燥原则；NH₃ 密度小于空气；极易溶气体防倒吸。","steps":["(1) 四处错误及改正：① 发生装置试管口**不应向上倾斜**，应**略向下倾斜**，防止反应生成的水蒸气冷凝回流炸裂试管；② **不能用浓硫酸干燥**（\\(\\mathrm{NH_3}\\) 与浓硫酸反应被吸收），应改为盛有**碱石灰**的干燥管；③ **不能用向上排空气法**，因 \\(M(\\mathrm{NH_3})=17 < 29\\)，应改为**向下排空气法**（管口塞棉花）；④ **导管不能直接插入稀硫酸**，极易发生倒吸，应改用**倒置漏斗**刚刚接触液面或用蘸有稀硫酸的棉花吸收尾气。","(2) 生石灰的双重作用：① \\(\\mathrm{CaO + H_2O \\to Ca(OH)_2}\\) 消耗水并**放出大量热**，促使 \\(\\mathrm{NH_3\\cdot H_2O}\\) 受热分解并降低氨气溶解度；② 生成的 \\(\\mathrm{OH^-}\\) 使平衡 \\(\\mathrm{NH_3 + H_2O \\rightleftharpoons NH_3\\cdot H_2O \\rightleftharpoons NH_4^+ + OH^-}\\) 逆向移动，利于 \\(\\mathrm{NH_3}\\) 逸出。"],"answer":"(1) 管口未向下倾斜、错用浓硫酸干燥、错用向上排空气、尾气直插未防倒吸；(2) 吸水放热促分解 + 增大 OH⁻ 使平衡逆移。","markingPoints":["准确指出并改正 4 处装置错误（每处1分，共4分）","完整说明 CaO 吸水放热与增大 OH⁻ 移平衡作用（2分）"],"verification":"对照化上 p.318 图13-19 逐一核对完全一致。","pitfall":"若漏写“向上排空气法”或把干燥剂改写成“无水 CaCl₂”，会被判错。"},{"label":"例 13.5.2","tier":"L4","tierLabel":"L4 统考压轴","title":"喷泉实验后烧瓶内氨水物质的量浓度定量推导","prompt":"在标准状况（STP）下，用一个干燥的圆底烧瓶（容积为 \\(V\\text{ L}\\)）收集满纯净的氨气并完成喷泉实验，假设烧瓶内最终充满液体且溶质无扩散损失。(1) 求所得氨水的物质的量浓度 \\(c(\\mathrm{NH_3})\\)（以 \\(\\mathrm{mol}\\cdot\\mathrm{L^{-1}}\\) 表示，保留三位有效数字）；(2) 若该烧瓶中收集的是含体积分数 \\(80\\%\\ \\mathrm{NH_3}\\) 与 \\(20\\%\\ \\mathrm{N_2}\\) 的混合气体，喷泉停止后烧瓶内溶液体积占容积的 \\(80\\%\\)，此时所得氨水的物质的量浓度又是多少？","clues":"标况下 \\(n = V / 22.4\\)，溶液体积恰好等于溶解的氨气体积（无论是否充满，溶解多少体积 NH₃ 就吸入多少体积水）！","strategy":"用符号 V 推导，发现烧瓶容积 V 与氨气体积分数均消去！","given":"STP 下气体摩尔体积 22.4 L/mol；V(溶液) = V(NH₃)","principle":"c = n / V_solution；氮气难溶于水不产生压强差。","steps":["(1) 标况下纯氨气的物质的量：\\(n(\\mathrm{NH_3}) = \\frac{V}{22.4}\\text{ mol}\\)。喷泉完成后溶液体积恰好为 \\(V\\text{ L}\\)，","故氨水浓度：\\(c = \\frac{n}{V_{\\text{液}}} = \\frac{V/22.4}{V} = \\frac{1}{22.4} \\approx 0.0446\\text{ mol}\\cdot\\mathrm{L^{-1}}\\)。","(2) 混合气体中 \\(V(\\mathrm{NH_3}) = 0.80V\\)，则 \\(n(\\mathrm{NH_3}) = \\frac{0.80V}{22.4}\\text{ mol}\\)。","因 \\(\\mathrm{N_2}\\) 难溶于水，吸入烧瓶内的溶液体积仅为 \\(V_{\\text{液}} = 0.80V\\text{ L}\\)。","故浓度仍为：\\(c = \\frac{0.80V/22.4}{0.80V} = \\frac{1}{22.4} \\approx 0.0446\\text{ mol}\\cdot\\mathrm{L^{-1}}\\)！"],"answer":"(1) \\(0.0446\\text{ mol}\\cdot\\mathrm{L^{-1}}\\)（或 \\(\\frac{1}{22.4}\\text{ mol}\\cdot\\mathrm{L^{-1}}\\)）；(2) 仍为 \\(0.0446\\text{ mol}\\cdot\\mathrm{L^{-1}}\\)。","markingPoints":["利用 n = V/22.4 推得 1/22.4 ≈ 0.0446 mol/L（2分）","说明仅溶解的 NH₃ 决定进水体积，推得浓度不变（2分）"],"verification":"只要初始气体在同温压下仅含可溶气体与完全不溶气体，喷泉浓度永远等于 \\(1/V_m\\)（前提是不考虑溶质体积效应）。","pitfall":"误以为混合气中氨气只占 80% 浓度就乘以 0.80，忘记了溶液体积也同步缩减为 0.80V。"}],"practice":[{"id":"chem13-13.5-q1","tier":"L1","tierLabel":"L1 基础","examStyle":"P1 选择","q":"常温常压下氨气极易液化并常用作冷冻剂，其主要微观原因及热效应分别是（　）。","options":["A. 分子间存在氢键；液氨汽化吸收大量的热","B. 分子间存在范德华力；液氨汽化放出大量的热","C. 分子内部共价键极弱；液氨分解吸收大量的热","D. 氨气密度比空气大；液氨凝华吸收大量的热"],"correctOption":"A","given":"化上 p.316 氨的物理性质与图13-17","method":"对照分子间氢键与汽化吸热制冷原理","principle":"NH₃ 分子间有氢键故易液化；液氨汽化剧烈吸热降低周围温度。","steps":["由教材 p.316 原文可知：氨分子间氢键增强分子间作用力致易液化，汽化吸热用作制冷剂。"],"ans":"A","markingPoints":["准确识别氢键与汽化吸热"],"verification":"对照化上 p.316 图13-17 与 p.320 思考题 13e 第1题。","pitfall":"把“汽化吸热”误记成“放热”或“化学分解”。"},{"id":"chem13-13.5-q2","tier":"L2","tierLabel":"L2 期末","examStyle":"P1 选择","q":"通常状况下能共存，且能用浓硫酸干燥的一组气体是（　）。","options":["A. 氢气、氧气、氮气","B. 氧气、一氧化氮、二氧化氮","C. 氢气、氮气、氨气","D. 氨气、氯化氢、一氧化氮"],"correctOption":"A","given":"气体共存与干燥剂适配（教材思考题 13e 第2题）","method":"逐组排查常温反应与浓硫酸反应","principle":"O₂ 与 NO 不共存；NH₃ 不与浓 H₂SO₄ 共存；NH₃ 与 HCl 不共存。","steps":["B 错：2NO + O₂ → 2NO₂，O₂ 与 NO 不能共存。","C 错：NH₃ 与浓硫酸反应生成 (NH₄)₂SO₄，不能用浓硫酸干燥。","D 错：NH₃ + HCl → NH₄Cl 白烟，且 NH₃ 被浓硫酸吸收。","A 对：H₂、O₂、N₂ 常温下互不反应，且均不与浓硫酸反应。"],"ans":"A","markingPoints":["排查反应与酸性干燥剂禁忌"],"verification":"对照化上 p.320 思考题 13e 第2题。","pitfall":"忽略 H₂ 和 O₂ 在常温（未点燃/无催化剂）下其实可以稳定共存。"},{"id":"chem13-13.5-q3","tier":"L3","tierLabel":"L3 预试","examStyle":"P2 简答","q":"工业采用哈伯法合成氨，其典型生产条件为 \\(500\\ ^\\circ\\mathrm{C}\\)、\\(3\\times 10^7\\text{ Pa}\\) 及铁粉作催化剂，气体通过合成塔后单程转化率仅约 \\(15\\%\\)。(1) 写出哈伯法合成氨的化学方程式；(2) 结合图13-21 工业生产流程图，说明如何分离出产物氨并提高原料氮气与氢气的总利用率。","given":"图13-21 哈伯法合成氨流程（化上 p.319）","method":"利用氨易液化分离及未反应 N₂、H₂ 循环压缩进料解答","principle":"沸点/液化差异分离 + 未反应气体循环利用。","steps":["(1) \\(\\mathrm{N_2(g) + 3H_2(g)} \\underset{\\text{铁粉}}{\\stackrel{500\\ ^\\circ\\mathrm{C},\\ 3\\times 10^7\\text{ Pa}}{\\rightleftharpoons}} \\mathrm{2NH_3(g)}\\)。","(2) 从合成塔出来的混合气体（\\(\\mathrm{N_2}\\)、\\(\\mathrm{H_2}\\)、\\(\\mathrm{NH_3}\\)）通入冷却塔降温液化——由于氨气分子间存在氢键，沸点远高于氮气和氢气而率先液化成为**液态氨**分离出来；剩余未反应的 \\(\\mathrm{N_2}\\) 和 \\(\\mathrm{H_2}\\) 则通过管道重新输送回压缩机，混合新原料后循环进入合成塔继续反应，从而大幅提高原料总利用率。"],"ans":"(1) 见步骤；(2) 冷却液化分离 NH₃，未反应的 N₂、H₂ 返回压缩机循环利用。","markingPoints":["可逆号及高温高压催化剂条件准确（2分）","说明冷却液化分离 NH₃ 及未反应 N₂/H₂ 循环利用（2分）"],"verification":"对照化上 p.319 图13-21 流程标注。","pitfall":"忘记写出可逆符号“⇌”或漏写未反应气体循环机制。"},{"id":"chem13-13.5-q4","tier":"L4","tierLabel":"L4 统考压轴","examStyle":"P2 探究分析","q":"实验室分别用等物质的量的下列气体充满干燥烧瓶进行喷泉实验（水或稀酸/碱液足量）：① 纯 \\(\\mathrm{NH_3}\\)（水+酚酞）；② 纯 \\(\\mathrm{NO_2}\\)（纯水+石蕊）；③ \\(\\mathrm{NO_2}\\) 与 \\(\\mathrm{O_2}\\) 按体积比 \\(4:1\\) 混合（纯水）。(1) 预测实验②与实验③最终液体占烧瓶容积的分数各是多少（同温同压，不计 \\(\\mathrm{N_2O_4}\\)）？(2) 对比说明实验①的喷泉颜色及微粒来源。","given":"三组不同气体喷泉模型","method":"由气体溶解/反应后的剩余气体体积推算进水体积分数","principle":"3NO₂ + H₂O = 2HNO₃ + NO；4NO₂ + O₂ + 2H₂O = 4HNO₃。","steps":["(1) 实验②：由 \\(\\mathrm{3NO_2(g) + H_2O(l) \\longrightarrow 2HNO_3(aq) + NO(g)}\\) 可知，\\(3\\) 体积 \\(\\mathrm{NO_2}\\) 反应后生成 \\(1\\) 体积难溶 \\(\\mathrm{NO}\\)，故吸入液体占据的容积分数为 \\(1 - \\frac{1}{3} = \\frac{2}{3}\\)（约 \\(66.7\\%\\)）。","实验③：由 \\(\\mathrm{4NO_2(g) + O_2(g) + 2H_2O(l) \\longrightarrow 4HNO_3(aq)}\\) 可知，\\(4:1\\) 混合气恰好完全反应无气体剩余，故液体充满整个烧瓶（占容积分数 \\(1\\) 或 \\(100\\%\\)）。","(2) 实验①喷泉呈**红色**，因为 \\(\\mathrm{NH_3}\\) 溶于水生成的 \\(\\mathrm{NH_3\\cdot H_2O}\\) 部分电离出 \\(\\mathrm{OH^-}\\) 使无色酚酞变红。"],"ans":"(1) 实验②占 \\(2/3\\)，实验③占 \\(1\\)（充满）；(2) 红色喷泉，源于 NH₃·H₂O 电离出 OH⁻。","markingPoints":["正确求得实验②进水 2/3 与实验③充满 1（2分）","准确描述实验①颜色变化及 OH⁻ 来源（2分）"],"verification":"实验②所得硝酸浓度在 STP 下为 \\(\\frac{2/3}{22.4 \\times (2/3)} = \\frac{1}{22.4}\\text{ mol}\\cdot\\mathrm{L^{-1}}\\)，与氨水恰同！","pitfall":"误以为 NO₂ 喷泉也能像 NH₃ 一样完全充满烧瓶，忽略了生成的 NO 难溶于水占去 1/3 体积。"}],"cheatSheet":["NH₃：氢键致易液化（制冷剂）且极易溶水（1:700，红酚酞喷泉）；NH₃·H₂O 为一元弱碱（受热易分解释氨）。","干燥氨气唯一标配：碱石灰（禁浓硫酸、禁无水 CaCl₂）；收集向下排空气（管口塞棉花）。","工业哈伯法：500℃、3×10⁷ Pa、铁粉，N₂ + 3H₂ ⇌ 2NH₃（液化分离氨，原料气循环）。"],"kbEntryIds":["kb-chem13-nh3-fountain"],"quiz":{"q":"分别蘸取浓氨水和浓盐酸的两根玻璃棒靠近时产生大量白烟，而蘸取浓氨水和浓硫酸靠近时却几乎无白烟。为什么？写出白烟产生的化学方程式。","given":"活动7（化上 p.317）","method":"比较浓盐酸（易挥发）与浓硫酸（难挥发）的物理性质","principle":"白烟为气态 NH₃ 与气态 HCl 直接化合生成 NH₄Cl 固体微粒。","steps":["浓盐酸易挥发放出 \\(\\mathrm{HCl}\\) 气体，与浓氨水挥发出的 \\(\\mathrm{NH_3}\\) 气体在空气中相遇生成固体氯化铵白烟：\\(\\mathrm{NH_3(g) + HCl(g) \\longrightarrow NH_4Cl(s)}\\)。","浓硫酸难挥发，不能散发酸蒸气在空气中与氨气相遇，故无白烟。"],"ans":"浓硫酸难挥发无酸气逸出；白烟方程式 \\(\\mathrm{NH_3(g) + HCl(g) \\longrightarrow NH_4Cl(s)}\\)"}},{"id":"13.6","t":"铵盐","anchor":{"pages":"化上 p.320–323","syllabus":"3.7.6 铵盐的热分解、与碱反应及 NH₄⁺ 检验与氮肥保存","examScopes":["sem2_final","uec"],"examWeight":"P1 离子鉴别（Ba(OH)₂ 一步鉴别）与热分解本质辨析 + P2 检验规范","terms":"ammonium salt · ammonium ion test · urea · thermal dissociation","prerequisites":["氨的碱性与石蕊试纸显色（化上 Ch 13.5）","物理变化与化学变化的本质判据（化上 Ch 1.4.4）"],"goals":["归纳铵盐的物理共性及受热易分解的通性，写出 NH₄Cl、(NH₄)₂CO₃、NH₄HCO₃ 的热分解方程式。","区分“NH₄Cl 受热分解又凝结”与“碘升华又凝华”的本质差异（化学变化 vs 物理变化）。","掌握加 NaOH 溶液加热并用湿润红色石蕊试纸检验 NH₄⁺ 的标准步骤（活动10），以及铵态氮肥和尿素的保存与施用原则。"]},"concepts":[{"kind":"experiment","title":"活动9 与 活动10：铵盐的热分解及与强碱共热检验（表13-7）","pageRef":"化上 p.321","body":["**物理共性**：常见铵盐（\\(\\mathrm{NH_4NO_3}\\)、\\(\\mathrm{NH_4Cl}\\)、\\(\\mathrm{(NH_4)_2SO_4}\\) 等）均为白色、易溶于水的离子晶体。","**活动9（加热封闭玻璃管内 \\(\\mathrm{NH_4Cl}\\)）**：管底白色固体受热消失，在管壁较冷上部重新凝结出白色固体。实质是发生了**化学分解与重新化合**：\\(\\mathrm{NH_4Cl(s)} \\xrightarrow{\\Delta} \\mathrm{NH_3(g) + HCl(g)}\\)，遇冷后又重新反应 \\(\\mathrm{NH_3(g) + HCl(g) \\to NH_4Cl(s)}\\)，故属**化学变化**（而碘升华凝华过程中始终是 \\(\\mathrm{I_2}\\) 分子，属物理变化！）。","**活动10（铵盐与碱共热检验 \\(\\mathrm{NH_4^+}\\)）**：向 \\(\\mathrm{(NH_4)_2SO_4}\\)、\\(\\mathrm{NH_4NO_3}\\) 中加 \\(10\\%\\ \\mathrm{NaOH}\\) 溶液并**加热**，产生刺激性气味气体，使管口**湿润的红色石蕊试纸变蓝**。离子方程式：\\(\\mathrm{NH_4^+(aq) + OH^-(aq)} \\xrightarrow{\\Delta} \\mathrm{NH_3(g)\\uparrow + H_2O(l)}\\)。"],"takeaway":"检验 NH₄⁺ 务必记住两个关键条件：“加浓强碱（NaOH）并加热”与“湿润红色石蕊试纸变蓝”（不加热时微量氨易溶水不易逸出！）。"},{"kind":"table","title":"常见铵盐热分解产物规律与化肥氮含量对比","pageRef":"化上 p.321–322","body":["并不是所有铵盐受热分解都只产生氨气！当酸根具有强氧化性（如 \\(\\mathrm{NO_3^-}\\)）时，在较高温度下会发生自身氧化还原反应，分解不产生 \\(\\mathrm{NH_3}\\)。"],"table":{"headers":["铵盐 / 氮肥","热分解或转化反应方程式","含氮质量分数","使用与储存注意事项"],"rows":[["氯化铵（\\(\\mathrm{NH_4Cl}\\)）","\\(\\mathrm{NH_4Cl(s)} \\xrightarrow{\\Delta} \\mathrm{NH_3\\uparrow + HCl\\uparrow}\\)","\\(26.2\\%\\)","遇冷复原；不可与碱混存"],["碳酸氢铵（\\(\\mathrm{NH_4HCO_3}\\)）","\\(\\mathrm{NH_4HCO_3(s)} \\xrightarrow{\\Delta} \\mathrm{NH_3\\uparrow + H_2O + CO_2\\uparrow}\\)","\\(17.7\\%\\)","常温或日光暴晒即可分解，须阴凉密封深施"],["硫酸铵（\\(\\mathrm{(NH_4)_2SO_4}\\)）","强热分解生成 \\(\\mathrm{NH_3}\\)、\\(\\mathrm{N_2}\\)、\\(\\mathrm{SO_2}\\) 等","\\(21.2\\%\\)","不宜长期过量单独施用以免土壤酸化板结"],["硝酸铵（\\(\\mathrm{NH_4NO_3}\\)）","\\(\\mathrm{NH_4NO_3(s)} \\xrightarrow{\\Delta} \\mathrm{N_2O\\uparrow + 2H_2O}\\)","\\(35.0\\%\\)","受撞击或高温易爆炸，严禁猛烈敲击结块"],["尿素（\\(\\mathrm{CO(NH_2)_2}\\)）","中性有机分子，土壤微生物作用下水解产 \\(\\mathrm{NH_4^+}\\)","\\(46.7\\%\\)（最高）","中性肥料，肥效持久、不破坏土壤结构"]]},"takeaway":"铵态氮肥严禁与草木灰（主要成分 K₂CO₃ 水解显碱性）或熟石灰混用，否则释放 NH₃ 造成肥效流失！"},{"kind":"mechanism","title":"氯化铵热分解与碘升华辨析及尿素氮肥优势","pageRef":"化上 p.321–322","body":["**现象相似但本质截然不同**：碘单质受热升华、遇冷重新凝华，全程始终是 \\(\\mathrm{I_2}\\) 分子，没有新物质生成，属于**物理变化**；而氯化铵固体受热消失并在冷壁复现，经历了化学键断裂分解为 \\(\\mathrm{NH_3}\\) 与 \\(\\mathrm{HCl}\\) 两种气体（\\(\\mathrm{NH_4Cl(s)} \\xrightarrow{\\Delta} \\mathrm{NH_3(g) + HCl(g)}\\)）及遇冷重新化合的逆过程，属于**化学变化**。","**铵态氮肥储存与施肥铁律**：\\(\\mathrm{NH_4HCO_3}\\)、\\(\\mathrm{(NH_4)_2SO_4}\\) 等应阴凉干燥密封保存、深施覆土，切忌在烈日下摊晒，更严禁与草木灰（\\(\\mathrm{K_2CO_3}\\)）或熟石灰混施（防止发生 \\(\\mathrm{NH_4^+ + OH^- \\to NH_3\\uparrow + H_2O}\\) 跑氨失效）。","**尿素（\\(\\mathrm{CO(NH_2)_2}\\)）优势**：含氮量达 \\(46.7\\%\\)（固体氮肥最高），且为中性有机分子，长期施用不会使土壤酸化板结。"],"takeaway":"必考辨析：\\(\\mathrm{NH_4Cl}\\) 加热“先消后现”是**化学变化**，绝不是物理升华；尿素中性且含氮量 \\(46.7\\%\\) 最高。"}],"formulas":[{"title":"碳酸铵与碳酸氢铵受热分解及铵根离子检验通式","tex":"\\mathrm{(NH_4)_2CO_3(s)} \\xrightarrow{\\Delta} \\mathrm{2NH_3(g) + H_2O(l) + CO_2(g)},\\qquad \\mathrm{NH_4^+(aq) + OH^-(aq)} \\xrightarrow{\\Delta} \\mathrm{NH_3(g)\\uparrow + H_2O(l)}","plain":"(NH4)2CO3 --Δ--> 2NH3 + H2O + CO2; NH4+ + OH- --Δ--> NH3 + H2O","conditions":"NH₄⁺ 检验须加热且使用湿润红色石蕊试纸","pageRef":"化上 p.321","note":"若在加热后产物气体全部通过碱石灰，(NH₄)₂CO₃/NH₄HCO₃ 分解出来的 H₂O 和 CO₂ 被吸收，只留纯 NH₃。"},{"title":"硫酸铵与氢氧化钡一步鉴别离子方程式","tex":"\\mathrm{2NH_4^+(aq) + SO_4^{2-}(aq) + Ba^{2+}(aq) + 2OH^-(aq)} \\xrightarrow{\\Delta} \\mathrm{BaSO_4(s)\\downarrow + 2NH_3(g)\\uparrow + 2H_2O(l)}","plain":"2NH4+ + SO4^2- + Ba^2+ + 2OH- --Δ--> BaSO4↓ + 2NH3↑ + 2H2O","conditions":"加热条件下同时产生白色沉淀与刺激性氨气","pageRef":"化上 p.322 思考题 13f","note":"这一反应是一步鉴别 Na₂SO₄、NaCl、(NH₄)₂SO₄、NH₄Cl 四种无色溶液的关键钥匙！"}],"pitfalls":[{"title":"混淆“氯化铵受热再凝结”与“碘升华凝华”的本质","wrong":"“固态氯化铵受热变成气体、遇冷又变回固体，与碘的升华和凝华一样，都是物理变化。”","diagnosis":"现象虽相似（固体→气体→固体），但微观粒子是否改变截然不同。","right":"碘升华凝华前后都是 \\(\\mathrm{I_2}\\) 分子，无新物质生成，是**物理变化**；而氯化铵受热拆成新分子 \\(\\mathrm{NH_3}\\) 与 \\(\\mathrm{HCl}\\)，遇冷再化合回 \\(\\mathrm{NH_4Cl}\\)，有化学键断裂与重新形成，是**化学变化**（教材思考题 13f 第2题）。","checkRule":"看到“NH₄Cl 升华”字眼必警觉：NH₄Cl 根本不是物理升华，而是热分解+化合！"},{"title":"将硫酸铵与草木灰（K₂CO₃）混合施肥","wrong":"“草木灰补钾、硫酸铵补氮，混合施用能省工增效。”","diagnosis":"草木灰主要成分 \\(\\mathrm{K_2CO_3}\\) 水解呈强碱性（含大量 \\(\\mathrm{OH^-}\\)），与 \\(\\mathrm{NH_4^+}\\) 反应生成 \\(\\mathrm{NH_3}\\) 气体逸出。","right":"铵态氮肥（\\(\\mathrm{NH_4^+}\\)）绝对不可与草木灰、生石灰、熟石灰等碱性肥料混用或混存，以免跑氨失效。","checkRule":"农用化学常识考题：看到“铵态氮肥 + 草木灰/石灰”直接判错。"}],"examples":[{"label":"例 13.6.1","tier":"L2","tierLabel":"L2 校内期末","title":"仅用一种试剂鉴别四种无色盐溶液（思考题 13f 第1题）","prompt":"只用一种试剂（必要时可加热）就能把 \\(\\mathrm{Na_2SO_4}\\)、\\(\\mathrm{NaCl}\\)、\\(\\mathrm{(NH_4)_2SO_4}\\)、\\(\\mathrm{NH_4Cl}\\) 四种无色溶液一次鉴别开来。(1) 该试剂是什么？(2) 分别描述四种溶液加入该试剂并微热后的实验现象。","clues":"需要同时检出 NH₄⁺（需 OH⁻）和 SO₄²⁻（需 Ba²⁺），故选择同时含 Ba²⁺ 和 OH⁻ 的碱！","strategy":"选用 Ba(OH)₂ 溶液，按“沉淀有无 × 气体有无”2×2 矩阵区分四种溶液。","given":"四种溶液：Na₂SO₄, NaCl, (NH₄)₂SO₄, NH₄Cl","principle":"Ba²⁺ + SO₄²⁻ → BaSO₄↓；NH₄⁺ + OH⁻ —Δ→ NH₃↑ + H₂O。","steps":["(1) 所用试剂为**氢氧化钡（\\(\\mathrm{Ba(OH)_2}\\)）溶液**。","(2) 分别取少量四种溶液于试管中，各滴加足量 \\(\\mathrm{Ba(OH)_2}\\) 溶液并微热：","① **只产生白色沉淀、无刺激性气体**的是 \\(\\mathrm{Na_2SO_4}\\) 溶液；","② **既有白色沉淀生成、又有刺激性气味气体（使湿润红色石蕊试纸变蓝）放出**的是 \\(\\mathrm{(NH_4)_2SO_4}\\) 溶液；","③ **无沉淀生成、只放出刺激性气味氨气**的是 \\(\\mathrm{NH_4Cl}\\) 溶液；","④ **既无沉淀又无气体产生（无明显现象）**的是 \\(\\mathrm{NaCl}\\) 溶液。"],"answer":"(1) 氢氧化钡溶液；(2) Na₂SO₄ 仅白沉；(NH₄)₂SO₄ 白沉+氨气；NH₄Cl 仅氨气；NaCl 无现象。","markingPoints":["选定 Ba(OH)₂ 溶液（1分）","按 2×2 现象组合准确区分 4 种溶液并提加热条件（3分）"],"verification":"四种现象组合（白沉+气、白沉+无气、无沉+气、无沉+无气）两两互异，完全鉴别。","pitfall":"若选 BaCl₂ 只能分出含 SO₄²⁻ 与不含 SO₄²⁻ 两组，选 NaOH 只能分出含 NH₄⁺ 与不含 NH₄⁺ 两组，唯有 Ba(OH)₂ 能双管齐下。"},{"label":"例 13.6.2","tier":"L3","tierLabel":"L3 预试拔高","title":"白色晶体 A 的双向离子检验与推断（思考题 13f 第3题）","prompt":"某易溶于水的白色晶体 A，做如下实验：① 向 A 的溶液中滴加硝酸银溶液，产生白色沉淀，再加稀硝酸，沉淀不溶解；② 另取少量 A 的溶液，加入氢氧化钠溶液并加热，产生刺激性气味气体，能使湿润的红色石蕊试纸变蓝。③ 将固体 A 放入干燥密闭试管加热，观察到试管底部固体逐渐消失，试管壁上部又重新出现白色固体。(1) 推断 A 是什么物质，写出 ①、② 两步反应的离子方程式；(2) 解释步骤 ③ 中“固体消失又复现”是化学变化而不是升华的原因。","clues":"加 AgNO₃+稀 HNO₃ 不溶白沉 → Cl⁻；加 NaOH 加热产氨 → NH₄⁺。","strategy":"由阴阳离子检验锁定 NH₄Cl，再写出两步离子方程式并从分子变化角度辩析 ③。","given":"白色晶体 A，AgNO₃/HNO₃ 白沉，NaOH/Δ 产 NH₃","principle":"Cl⁻ 检验（AgCl↓）与 NH₄⁺ 检验（NH₃↑）。","steps":["(1) A 为**氯化铵（\\(\\mathrm{NH_4Cl}\\)）**。步骤 ① 离子方程式：\\(\\mathrm{Ag^+(aq) + Cl^-(aq) \\longrightarrow AgCl(s)\\downarrow}\\)；步骤 ② 离子方程式：\\(\\mathrm{NH_4^+(aq) + OH^-(aq)} \\xrightarrow{\\Delta} \\mathrm{NH_3(g)\\uparrow + H_2O(l)}\\)。","(2) 步骤 ③ 并非物理升华，而是发生了两个可逆化学变化：管底 \\(\\mathrm{NH_4Cl}\\) 受热分解生成新物质气体 \\(\\mathrm{NH_3}\\) 和 \\(\\mathrm{HCl}\\)（\\(\\mathrm{NH_4Cl} \\xrightarrow{\\Delta} \\mathrm{NH_3\\uparrow + HCl\\uparrow}\\)），气体扩散至较冷试管上部后，\\(\\mathrm{NH_3}\\) 与 \\(\\mathrm{HCl}\\) 重新化合生成 \\(\\mathrm{NH_4Cl}\\) 白色晶体，全过程有旧化学键断裂和新物质生成，故属化学变化。"],"answer":"(1) \\(\\mathrm{NH_4Cl}\\)；离子方程式见步骤；(2) 先热分解成 NH₃ 和 HCl 气体，遇冷再化合回 NH₄Cl，有新物质生成属化学变化。","markingPoints":["准确推断 NH₄Cl 并写出两步离子方程式（2分）","清晰阐明“热分解+遇冷化合”两步化学反应本质（2分）"],"verification":"对照教材 p.323 思考题 13f 第2、3题核验。","pitfall":"第 ① 步离子方程式误把稀硝酸写进方程式，实际上稀硝酸只起到排除 CO₃²⁻/PO₄³⁻ 等干扰的验证作用。"}],"practice":[{"id":"chem13-13.6-q1","tier":"L1","tierLabel":"L1 基础","examStyle":"P1 选择","q":"下列化肥中，含氮量最高且属于中性、不破坏土壤结构的是（　）。","options":["A. 碳酸氢铵（\\(\\mathrm{NH_4HCO_3}\\)）","B. 硫酸铵（\\(\\mathrm{(NH_4)_2SO_4}\\)）","C. 硝酸铵（\\(\\mathrm{NH_4NO_3}\\)）","D. 尿素（\\(\\mathrm{CO(NH_2)_2}\\)）"],"correctOption":"D","given":"四种常见氮肥（化上 p.322 资料链接）","method":"计算或熟记四种氮肥 w(N)","principle":"尿素含氮量 28/60 ≈ 46.67%，目前固体氮肥最高。","steps":["尿素 \\(w(\\mathrm{N}) = \\frac{28}{60} \\times 100\\% = 46.67\\%\\)，远高于硝酸铵（35.0%）、硫酸铵（21.2%）和碳铵（17.7%）。"],"ans":"D","markingPoints":["掌握尿素的高含氮量与中性特性"],"verification":"对照化上 p.322 资料链接“含氮量最高的氮肥——尿素”。","pitfall":"误以为硝酸铵或氨水含氮量更高（纯液氨虽 82.4% 但非固体常用农肥且易挥发烧苗）。"},{"id":"chem13-13.6-q2","tier":"L2","tierLabel":"L2 期末","examStyle":"P1 选择","q":"实验室检验某固体肥料中是否含有 \\(\\mathrm{NH_4^+}\\) 时，最规范的实验操作及现象是（　）。","options":["A. 直接取固体置于酒精灯上加热，看是否有白烟","B. 溶于水后加入稀盐酸，看是否有无色气体放出","C. 溶于水后加入 \\(\\mathrm{NaOH}\\) 溶液并加热，用湿润的红色石蕊试纸在管口检验变蓝","D. 溶于水后加入 \\(\\mathrm{NaOH}\\) 溶液振荡，直接闻气味或用干燥蓝色石蕊试纸检验"],"correctOption":"C","given":"NH₄⁺ 检验规范（化上 p.321 活动10）","method":"核对试剂（强碱）、条件（加热）与试纸（湿润红色石蕊）","principle":"NH₄⁺ + OH⁻ —Δ→ NH₃↑ + H₂O；NH₃ 使湿润红色石蕊试纸变蓝。","steps":["A 错：硝酸铵、硫酸铵等加热不直接生白烟。","B 错：NH₄⁺ 与稀盐酸不反应。","C 对：强碱、加热、湿润红色石蕊试纸三要素齐全。","D 错：未加热氨气不易逸出，且检验碱性气体须用**湿润红色**石蕊试纸（干燥或蓝色均无效）。"],"ans":"C","markingPoints":["把握加碱+加热+湿润红色石蕊三要素"],"verification":"对照化上 p.321 活动10。","pitfall":"选 D 忽略了加热或试纸颜色/湿润条件。"},{"id":"chem13-13.6-q3","tier":"L3","tierLabel":"L3 预试","examStyle":"P1 选择","q":"只用一种试剂即可一次鉴别 \\(\\mathrm{Na_2SO_4}\\)、\\(\\mathrm{NaCl}\\)、\\(\\mathrm{(NH_4)_2SO_4}\\)、\\(\\mathrm{NH_4Cl}\\) 四种溶液，应选用（　）。","options":["A. 硝酸银溶液","B. 氢氧化钠溶液","C. 氯化钡溶液","D. 氢氧化钡溶液"],"correctOption":"D","given":"教材思考题 13f 第1题","method":"同时匹配 Ba²⁺（检 SO₄²⁻）和 OH⁻（检 NH₄⁺）","principle":"Ba(OH)₂ 能同时与 SO₄²⁻ 生成白色沉淀、与 NH₄⁺ 在加热下放出氨气。","steps":["Ba(OH)₂ 分别产生：只白沉（Na₂SO₄）、白沉+气（(NH₄)₂SO₄）、只气（NH₄Cl）、无现象（NaCl）。"],"ans":"D","markingPoints":["选定 Ba(OH)₂ 一步鉴别"],"verification":"对照化上 p.322 思考题 13f 第1题。","pitfall":"误选 A（AgNO₃ 与硫酸钠若浓也会微溶出 Ag₂SO₄ 且无法区分 Na⁺ 与 NH₄⁺）。"},{"id":"chem13-13.6-q4","tier":"L4","tierLabel":"L4 统考压轴","examStyle":"P2 综合计算","q":"将 \\(20.3\\text{ g}\\) 由 \\(\\mathrm{NH_4Cl}\\) 和 \\(\\mathrm{(NH_4)_2CO_3}\\) 组成的固体混合物放入试管中充分加热至完全分解，并将全部气态产物依次通过足量碱石灰干燥管和足量浓硫酸洗气瓶（设反应与吸收均完全）。测得浓硫酸洗气瓶增重 \\(6.80\\text{ g}\\)，求：(1) 原固体混合物中 \\(\\mathrm{NH_4Cl}\\) 与 \\(\\mathrm{(NH_4)_2CO_3}\\) 的物质的量；(2) 碱石灰干燥管共吸收了多少克气体？（已知摩尔质量：\\(\\mathrm{NH_4Cl}=53.5,\\ \\mathrm{(NH_4)_2CO_3}=96,\\ \\mathrm{NH_3}=17,\\ \\mathrm{HCl}=36.5,\\ \\mathrm{H_2O}=18,\\ \\mathrm{CO_2}=44\\text{ g}\\cdot\\mathrm{mol^{-1}}\\)）","given":"m(混合)=20.3 g；碱石灰吸 HCl/H₂O/CO₂；浓硫酸吸 NH₃ 增重 6.80 g","method":"理清每一种气体被哪一个试剂吸收，再用质量守恒一步求出碱石灰增重","principle":"碱石灰（碱性干燥剂）吸收酸性气体 HCl、CO₂ 及水蒸气 H₂O；浓硫酸仅吸收剩余的碱性气体 NH₃。","steps":["写出分解方程式：\\(\\mathrm{NH_4Cl(s)} \\xrightarrow{\\Delta} \\mathrm{NH_3\\uparrow + HCl\\uparrow}\\)；\\(\\mathrm{(NH_4)_2CO_3(s)} \\xrightarrow{\\Delta} \\mathrm{2NH_3\\uparrow + H_2O(g) + CO_2\\uparrow}\\)。","(1) 碱石灰吸收 \\(\\mathrm{HCl}\\)、\\(\\mathrm{CO_2}\\) 和 \\(\\mathrm{H_2O}\\)，唯有 \\(\\mathrm{NH_3}\\) 通过碱石灰后被浓硫酸完全吸收，故 \\(m(\\mathrm{NH_3}) = 6.80\\text{ g}\\)，\\(n(\\mathrm{NH_3}) = \\frac{6.80}{17} = 0.40\\text{ mol}\\)。","设混合物中 \\(n(\\mathrm{NH_4Cl}) = x\\text{ mol}\\)，\\(n(\\mathrm{(NH_4)_2CO_3}) = y\\text{ mol}\\)。","由总 \\(\\mathrm{NH_3}\\) 量：\\(x + 2y = 0.40\\)；由总固体质量：\\(53.5x + 96y = 20.3\\)。","将 \\(x = 0.40 - 2y\\) 代入质量方程：\\(53.5(0.40 - 2y) + 96y = 20.3 \\implies 21.4 - 11y = 20.3 \\implies 11y = 1.1 \\implies y = 0.10\\text{ mol}\\)，\\(x = 0.20\\text{ mol}\\)。","(2) 因为固体完全分解成气体，总气体质量等于原固体质量 \\(20.3\\text{ g}\\)，故碱石灰吸收的气体总质量为：\\(20.3\\text{ g} - 6.80\\text{ g} = 13.5\\text{ g}\\)。"],"ans":"(1) \\(n(\\mathrm{NH_4Cl}) = 0.20\\text{ mol}\\)，\\(n(\\mathrm{(NH_4)_2CO_3}) = 0.10\\text{ mol}\\)；(2) \\(13.5\\text{ g}\\)。","markingPoints":["判断浓硫酸增重即生成的 NH₃ 质量（0.40 mol）（1分）","联立方程解得 NH₄Cl 为 0.20 mol、(NH₄)₂CO₃ 为 0.10 mol（2分）","用质量守恒算得碱石灰吸收 13.5 g（1分）"],"verification":"碱石灰吸收气体总质量分项核验：\\(0.20\\times 36.5(\\mathrm{HCl}) + 0.10\\times (18+44)(\\mathrm{H_2O+CO_2}) = 7.3 + 6.2 = 13.5\\text{ g}\\)！","pitfall":"若把“浓硫酸增重”错当成水蒸气质量，会导致整题列式失效；碱石灰同时吸收水、氯化氢和二氧化碳。"}],"cheatSheet":["NH₄Cl 受热分解为 NH₃+HCl 遇冷复原，是化学变化（不同于 I₂ 升华的物理变化）。","检验 NH₄⁺：加 NaOH 溶液并加热，湿润红色石蕊试纸变蓝。","Ba(OH)₂ 可一步鉴别 Na₂SO₄、NaCl、(NH₄)₂SO₄、NH₄Cl；尿素 CO(NH₂)₂ 含氮 46.67% 最高。"],"kbEntryIds":["kb-chem13-nh4-salts"],"quiz":{"q":"为什么碳酸氢铵（\\(\\mathrm{NH_4HCO_3}\\)）氮肥在炎热阳光下摊晒极易失去肥效？写出化学方程式。","given":"NH₄HCO₃ 的热稳定性","method":"利用受热分解放出三种气体","principle":"铵盐热分解导致氮元素转化为 NH₃ 挥发损失。","steps":["\\(\\mathrm{NH_4HCO_3(s)} \\xrightarrow{\\Delta} \\mathrm{NH_3(g)\\uparrow + H_2O(l) + CO_2(g)\\uparrow}\\)。","受热分解生成气态氨挥发到空气中，氮元素流失。"],"ans":"受热易分解放出氨气：\\(\\mathrm{NH_4HCO_3} \\xrightarrow{\\Delta} \\mathrm{NH_3\\uparrow + H_2O + CO_2\\uparrow}\\)"}},{"id":"13.7","t":"磷及其重要化合物","anchor":{"pages":"化上 p.323–328","syllabus":"3.7.7 白磷与红磷同素异形体、P₂O₅ 与磷酸及磷酸盐（磷肥）","examScopes":["sem2_final","uec"],"examWeight":"P1 白磷红磷对比、偏磷酸/正磷酸与磷肥辨析 + P2 相似性推导（如 PH₄I）","terms":"white phosphorus · red phosphorus · phosphoric acid · calcium superphosphate · compound fertilizer","prerequisites":["同素异形体概念（碳的同素异形体，化上 Ch 12.1.2）","VA族原子结构与同主族递变规律（化上 Ch 13.1）"],"goals":["根据图13-25 与表13-8 对比白磷（P₄ 正四面体）与红磷（链状高分子）在物理性质、毒性、着火点、保存及相互转化上的差异。","写出磷在不足或充足氧气、氯气中燃烧产物的差异，以及 P₂O₅ 与冷水、热水分别反应生成偏磷酸与正磷酸的方程式。","了解磷酸的工业制法、用途及磷酸盐溶解性与常见磷肥（普钙、重过磷酸钙、复合肥）成分。"]},"concepts":[{"kind":"table","title":"白磷与红磷的性质对比及相互转变（表13-8）","pageRef":"化上 p.323–324","body":["白磷（\\(\\mathrm{P_4}\\)，正四面体分子，键角 \\(60^\\circ\\) 张力大、极活泼）与红磷（链状结构，图13-25）互为磷元素的**同素异形体**。安全火柴盒侧面涂有红磷（发火剂）和 \\(\\mathrm{Sb_2S_3}\\)，摩擦产热使少量红磷转为白磷进而引燃火柴头（\\(\\mathrm{KClO_3}\\)、\\(\\mathrm{MnO_2}\\)、硫）。"],"table":{"headers":["比较项目","白磷（黄磷）","红磷（赤磷）"],"rows":[["外观、气味与毒性","无色或淡黄色蜡状固体，具蒜臭，**剧毒**（人服 0.1 g 可致死）","红棕色粉末，无臭，**无毒**"],["溶解性","不溶于水，**易溶于 \\(\\mathrm{CS_2}\\)**","不溶于水，也**不溶于 \\(\\mathrm{CS_2}\\)**"],["熔点、沸点与着火点","熔点 44℃，沸点 281℃，**着火点 40℃**（极易自燃）","416℃ 升华，**着火点 240℃**"],["贮存方式","必须**隔绝空气保存在水中**（既防氧化自燃又比水重）","可放置于空气中密封保存"],["暗处发光与氧化性","露置空气中低温缓慢氧化且暗处发冷光","空气中较难被氧化，不发光"],["相互转变（化学变化）","隔绝空气加热至 **280~340℃** → 红磷","隔绝空气加热至 **416℃ 以上**蒸汽骤冷 → 白磷"]]},"takeaway":"白磷转为红磷和红磷转为白磷都是同素异形体之间的化学变化！可用 CS₂ 洗去红磷中混有的少量白磷。"},{"kind":"law","title":"磷的燃烧反应及磷酸（H₃PO₄）的性质与制法","pageRef":"化上 p.324–326","body":["**与 \\(\\mathrm{O_2}\\)、\\(\\mathrm{Cl_2}\\) 反应（活动11–12）**：在空气不足时生成三氧化二磷 \\(\\mathrm{P_2O_3}\\)，充足时生成五氧化二磷 \\(\\mathrm{P_2O_5}\\)（浓厚白烟）；在不足氯气中生成液态三氯化磷 \\(\\mathrm{PCl_3}\\)（白雾），在过量氯气中生成固态五氯化磷 \\(\\mathrm{PCl_5}\\)（图13-26 白烟）。","**磷酸（正磷酸，\\(\\mathrm{H_3PO_4}\\)）**：纯磷酸为无色晶体（mp 42.4℃），加热逐渐脱水故无沸点，具有吸湿性，与水以任意比例混溶；市售磷酸为约 \\(85\\%\\) 黏稠溶液。它是**中等强度的三元酸**，分步电离出 \\(\\mathrm{H^+}\\)。","**酸酐 \\(\\mathrm{P_2O_5}\\) 的双产物反应**：冷水得**剧毒**的偏磷酸（\\(\\mathrm{HPO_3}\\)），热水得**无毒**的正磷酸（\\(\\mathrm{H_3PO_4}\\)）。工业用磷酸钙与硫酸制磷酸：\\(\\mathrm{Ca_3(PO_4)_2(s) + 3H_2SO_4(aq) \\longrightarrow 3CaSO_4(s)\\downarrow + 2H_3PO_4(aq)}\\)（滤去 \\(\\mathrm{CaSO_4}\\) 沉淀即得磷酸溶液），用于制磷肥、金属表面防锈磷化膜、化学抛光剂及可乐酸化防腐剂。"],"takeaway":"偏磷酸 HPO₃ 有毒而正磷酸 H₃PO₄ 无毒，用 P₂O₅ 制磷酸食用或医药用途时务必用热水！"},{"kind":"definition","title":"磷酸盐溶解性规律及常见磷肥与复合肥","pageRef":"化上 p.327–328","body":["**溶解性规律（必记！）**：**所有磷酸二氢盐（\\(\\mathrm{H_2PO_4^-}\\)）都溶于水**；而磷酸氢盐（\\(\\mathrm{HPO_4^{2-}}\\)）和正磷酸盐（\\(\\mathrm{PO_4^{3-}}\\)）中除钾、钠、铵盐外，几乎都不溶于水（如磷灰石主要成分 \\(\\mathrm{Ca_3(PO_4)_2}\\) 难溶）。","**三种常见肥料**：① **过磷酸钙（简称普钙）**：磷灰石与适量稀硫酸反应制得，成分为 \\(\\mathrm{Ca(H_2PO_4)_2 + CaSO_4\\cdot 2H_2O}\\)（水溶性速效磷肥，但含大量无用硫酸钙）；② **重过磷酸钙**：磷酸与磷酸钙反应制得，纯为 \\(\\mathrm{Ca(H_2PO_4)_2}\\)，含磷量高、高效水溶；③ **复合肥（含 N、P、K 中至少两种养分）**：如磷酸氢二铵 \\(\\mathrm{(NH_4)_2HPO_4}\\) 和磷酸二氢铵 \\(\\mathrm{NH_4H_2PO_4}\\)。"],"takeaway":"磷灰石 Ca₃(PO₄)₂ 难溶于水无法被植物直接吸收，用硫酸或磷酸将其转化为水溶性的 Ca(H₂PO₄)₂ 是磷肥工业核心思路。"}],"formulas":[{"title":"磷在氧气、氯气中的限度与过量燃烧反应","tex":"\\mathrm{4P(s) + 5O_2(g)} \\xrightarrow{\\text{点燃}} \\mathrm{2P_2O_5(s)},\\qquad \\mathrm{2P(s) + 3Cl_2(g)} \\xrightarrow{\\text{点燃}} \\mathrm{2PCl_3(l)},\\qquad \\mathrm{2P(s) + 5Cl_2(g)} \\xrightarrow{\\text{点燃}} \\mathrm{2PCl_5(s)}","plain":"4P + 5O2 -> 2P2O5; 2P + 3Cl2 -> 2PCl3; 2P + 5Cl2 -> 2PCl5","conditions":"O₂/Cl₂ 不足生成 +3 价 P₂O₃/PCl₃；充足或过量生成 +5 价 P₂O₅/PCl₅","pageRef":"化上 p.325","note":"注意 PCl₃ 常温下为无色液体（遇水蒸气易水解产生白雾），PCl₅ 常温为固体（白烟）。"},{"title":"五氧化二磷水化产物差异及磷酸工业制取","tex":"\\mathrm{P_2O_5(s) + H_2O(l,\\text{冷水}) \\longrightarrow 2HPO_3(aq)},\\qquad \\mathrm{P_2O_5(s) + 3H_2O(l,\\text{热水}) \\longrightarrow 2H_3PO_4(aq)},\\qquad \\mathrm{Ca_3(PO_4)_2 + 3H_2SO_4 \\longrightarrow 3CaSO_4\\downarrow + 2H_3PO_4}","plain":"P2O5 + H2O(冷) -> 2HPO3; P2O5 + 3H2O(热) -> 2H3PO4; Ca3(PO4)2 + 3H2SO4 -> 3CaSO4↓ + 2H3PO4","conditions":"冷水得偏磷酸（剧毒）；热水得正磷酸（无毒）","pageRef":"化上 p.326","note":"磷酸的分步电离：H₃PO₄ ⇌ H⁺ + H₂PO₄⁻（主）；H₂PO₄⁻ ⇌ H⁺ + HPO₄²⁻；HPO₄²⁻ ⇌ H⁺ + PO₄³⁻。"}],"pitfalls":[{"title":"误把白磷与红磷互相转化当成物理变化","wrong":"“白磷加热变为红磷只是聚集状态改变，没有元素种类改变，属于物理变化。”","diagnosis":"白磷是独立四原子分子 \\(\\mathrm{P_4}\\)，红磷是长链状大分子，化学键发生了断裂与重组，二者是不同物质。","right":"同素异形体之间的互相转化（如白磷 ⇌ 红磷、\\(\\mathrm{3O_2 \\rightleftharpoons 2O_3}\\)、石墨 → 金刚石）全部属于**化学变化**。","checkRule":"遇到“同素异形体互变”，直接判定为化学变化！"},{"title":"混淆五氧化二磷吸水后的直接产物与食用磷酸安全","wrong":"“\\(\\mathrm{P_2O_5}\\) 溶于水无论温度高低都直接生成无毒的正磷酸 \\(\\mathrm{H_3PO_4}\\)。”","diagnosis":"冷水条件下主要生成链状/环状的偏磷酸（\\(\\mathrm{HPO_3}\\)），具有强毒性。","right":"\\(\\mathrm{P_2O_5}\\) 遇**冷水**生成有毒偏磷酸 \\(\\mathrm{HPO_3}\\)，遇**热水**才能生成无毒正磷酸 \\(\\mathrm{H_3PO_4}\\)。","checkRule":"记住口诀：“冷偏有毒，热正无毒”。"}],"examples":[{"label":"例 13.7.1","tier":"L3","tierLabel":"L3 预试拔高","title":"同主族相似性推理：碘化鏻（PH₄I）结构与性质（思考题 13g 第2题）","prompt":"同主族元素形成的同一类化合物，结构与性质往往很相似。已知磷化氢（\\(\\mathrm{PH_3}\\)）与氨（\\(\\mathrm{NH_3}\\)）类似，化合物碘化鏻（\\(\\mathrm{PH_4I}\\)）是一种白色晶体。请判断下列关于 \\(\\mathrm{PH_4I}\\) 的性质预测并说明理由：(1) 它属于离子化合物还是共价化合物？(2) 它能否与 \\(\\mathrm{NaOH}\\) 溶液反应？若能，写出反应方程式；(3) 将 \\(\\mathrm{PH_4I}\\) 晶体加热分解，能否**只**得到无色气体？","clues":"将 PH₄I 类比 NH₄I（或 NH₄Cl）与 HI 的热稳定性差异！","strategy":"① 由 NH₄⁺ 类比 PH₄⁺ 判断离子晶体与碱反应；② 结合第15章 HI 不稳定热分解为 H₂ + 紫红色 I₂ 蒸汽判断现象！","given":"PH₄I 类比 NH₄I，白色晶体","principle":"同主族相似性与 HI 受热易分解（2HI ⇌ H₂ + I₂）。","steps":["(1) 属于**离子化合物**（由 \\(\\mathrm{PH_4^+}\\) 阳离子与 \\(\\mathrm{I^-}\\) 阴离子通过离子键结合而成，类似 \\(\\mathrm{NH_4Cl}\\)，含共价键但整体为离子化合物）。","(2) **能**与 \\(\\mathrm{NaOH}\\) 溶液反应：\\(\\mathrm{PH_4I + NaOH \\longrightarrow NaI + PH_3\\uparrow + H_2O}\\)。","(3) **不能只得到无色气体**！因为 \\(\\mathrm{PH_4I}\\) 受热分解首先生成 \\(\\mathrm{PH_3}\\) 和 \\(\\mathrm{HI}\\)，而生成的 \\(\\mathrm{HI}\\) 极不稳定，在加热条件下立即部分分解为无色 \\(\\mathrm{H_2}\\) 和**紫色 \\(\\mathrm{I_2}\\) 蒸气**（\\(\\mathrm{2HI \\rightleftharpoons H_2 + I_2(g)}\\)），因此可观察到紫色蒸气而非纯无色气体！"],"answer":"(1) 离子化合物；(2) 能，\\(\\mathrm{PH_4I + NaOH \\to NaI + PH_3\\uparrow + H_2O}\\)；(3) 不能只得无色气体，因 HI 热分解产生紫色 I₂ 蒸气。","markingPoints":["正确判断 PH₄I 为离子化合物（1分）","写出与 NaOH 反应方程式（1分）","联系 HI 热分解说明会出现紫色碘蒸气（2分）"],"verification":"对照教材 p.328 思考题 13g 第2题核验（A 错、B 错、C 对、D 对）。","pitfall":"若不跨章联想 HI 的热不稳定性，极易错认为 PH₄I 分解就像 NH₄Cl 一样只得到无色气体。"},{"label":"例 13.7.2","tier":"L2","tierLabel":"L2 校内期末","title":"白磷贮存、中毒急救及普钙与重过磷酸钙对比计算","prompt":"(1) 为什么少量白磷必须保存在水中，而不能像金属钠那样保存在煤油中？(2) 计算重过磷酸钙有效成分 \\(\\mathrm{Ca(H_2PO_4)_2}\\) 中磷元素的质量分数（精确到 \\(0.1\\%\\)），并说明为何农业上称其肥效高于普通“普钙”。（\\(\\mathrm{Ca}=40,\\ \\mathrm{H}=1,\\ \\mathrm{P}=31,\\ \\mathrm{O}=16\\)）","clues":"(1) 思考白磷在非极性有机溶剂中的溶解性与密度；(2) 计算 Mr(Ca(H₂PO₄)₂)。","strategy":"白磷易溶于有机溶剂/煤油且不与水反应、密度大于水；用 w(P) 对比普钙含无用 CaSO₄。","given":"Ca(H₂PO₄)₂，普钙 Ca(H₂PO₄)₂ + CaSO₄·2H₂O","principle":"相似相溶与质量分数计算。","steps":["(1) 白磷是分子晶体，不与水反应且密度（\\(1.83\\text{ g}\\cdot\\mathrm{cm^{-3}}\\)）大于水，沉于水底能隔绝空气防自燃（白磷着火点仅 40℃）；而煤油是有机溶剂，白磷能部分溶解于煤油且易随煤油挥发暴露导致自燃，故只能保存在水中。","(2) \\(M_r[\\mathrm{Ca(H_2PO_4)_2}] = 40 + 2\\times(2 + 31 + 64) = 40 + 194 = 234\\)。","其中含 \\(2\\) 个 P 原子（\\(2 \\times 31 = 62\\)）：\\(w(\\mathrm{P}) = \\frac{62}{234} \\times 100\\% \\approx 26.5\\%\\)。","因为普钙中混有大量难溶且无磷肥效的副产物 \\(\\mathrm{CaSO_4\\cdot 2H_2O}\\)，大幅稀释了含磷量；重过磷酸钙用磷酸代替硫酸制得，不含无用 \\(\\mathrm{CaSO_4}\\)，有效含磷量高得多且全水溶。"],"answer":"(1) 白磷不溶水且比水重，溶于有机溶剂煤油故存水中；(2) \\(26.5\\%\\)，重过磷酸钙不含无用 CaSO₄ 因而肥效更高。","markingPoints":["解释存水不存煤油原因（2分）","算得 Mr=234 与 w(P)=26.5%（2分）"],"verification":"\\(2\\times 97 = 194\\)，\\(194+40=234\\)，\\(62/234 = 0.26496\\)。","pitfall":"算式量时忘记把括号内 2 个 H₂PO₄⁻ 乘以 2。"}],"practice":[{"id":"chem13-13.7-q1","tier":"L1","tierLabel":"L1 基础","examStyle":"P1 选择","q":"下列关于白磷和红磷的比较中，**错误**的是（　）。","options":["A. 两者互为同素异形体，白磷转变为红磷属于化学变化","B. 白磷着火点只有 40℃，有剧毒，必须保存在水中","C. 白磷与红磷在过量氧气中充分燃烧的最终产物均为 \\(\\mathrm{P_2O_5}\\)","D. 白磷和红磷都易溶于二硫化碳（\\(\\mathrm{CS_2}\\)）"],"correctOption":"D","given":"表13-8 白磷与红磷性质对比","method":"逐项核对教材表13-8","principle":"白磷易溶于 CS₂，红磷既不溶于水也不溶于 CS₂。","steps":["D 错：红磷为长链状结构，不溶于 \\(\\mathrm{CS_2}\\)，而白磷（\\(\\mathrm{P_4}\\)）易溶于 \\(\\mathrm{CS_2}\\)。"],"ans":"D","markingPoints":["区分白磷与红磷在 CS₂ 中的溶解性差异"],"verification":"对照化上 p.324 表13-8。","pitfall":"误以为两种同素异形体溶解性相同。"},{"id":"chem13-13.7-q2","tier":"L2","tierLabel":"L2 期末","examStyle":"P1 选择","q":"磷酸（\\(\\mathrm{H_3PO_4}\\)）的酸酐与水反应时，反应条件不同产物也不同。将五氧化二磷投入冷水和热水中分别得到的主要含氧酸是（　）。","options":["A. 冷水得正磷酸（\\(\\mathrm{H_3PO_4}\\)），热水得偏磷酸（\\(\\mathrm{HPO_3}\\)）","B. 冷水得偏磷酸（\\(\\mathrm{HPO_3}\\)），热水得正磷酸（\\(\\mathrm{H_3PO_4}\\)）","C. 两者均只生成正磷酸，但热水反应速率更快","D. 两者均只生成亚磷酸（\\(\\mathrm{H_3PO_3}\\)）"],"correctOption":"B","given":"P₂O₅ 与冷水/热水反应（化上 p.326）","method":"对应教材 p.326 两行方程式","principle":"P₂O₅ + H₂O(冷) → 2HPO₃；P₂O₅ + 3H₂O(热) → 2H₃PO₄。","steps":["冷水生成有毒偏磷酸 \\(\\mathrm{HPO_3}\\)，热水生成无毒正磷酸 \\(\\mathrm{H_3PO_4}\\)。"],"ans":"B","markingPoints":["记牢冷水偏磷酸与热水正磷酸"],"verification":"对照化上 p.326。","pitfall":"将冷热水产物颠倒。"},{"id":"chem13-13.7-q3","tier":"L3","tierLabel":"L3 预试","examStyle":"P1 选择","q":"下列化肥中，属于水溶性速效磷肥或氮磷高效复合肥且不含无用副产物 \\(\\mathrm{CaSO_4}\\) 的是（　）。","options":["A. 磷矿粉 \\(\\mathrm{Ca_3(PO_4)_2}\\)","B. 普钙（\\(\\mathrm{Ca(H_2PO_4)_2 + CaSO_4\\cdot 2H_2O}\\)）","C. 磷酸二氢铵 \\(\\mathrm{NH_4H_2PO_4}\\)","D. 磷酸氢钙 \\(\\mathrm{CaHPO_4}\\)"],"correctOption":"C","given":"磷肥与磷酸盐溶解性（化上 p.327–328）","method":"检查溶解性与养分种类","principle":"NH₄H₂PO₄ 既含 N 又含 P，全溶于水，不含 CaSO₄。","steps":["A、D 几乎不溶于水；B 含大量无用 CaSO₄；C 为优质氮磷复合肥且极易溶于水。"],"ans":"C","markingPoints":["把握磷酸二氢盐全溶及复合肥定义"],"verification":"对照化上 p.327–328。","pitfall":"误选 D，忘记 CaHPO₄ 几乎不溶于水。"},{"id":"chem13-13.7-q4","tier":"L4","tierLabel":"L4 统考压轴","examStyle":"P2 综合计算","q":"将 \\(6.20\\text{ g}\\) 红磷在盛有标准状况下 \\(8.96\\text{ L}\\) 氯气的密闭容器中点燃并充分反应，冷却至室温。试通过计算确定反应后密闭容器内有哪些生成物？各生成物分别是多少摩尔？（\\(\\mathrm{P}=31\\)）","given":"m(P)=6.20 g (0.20 mol)，V(Cl₂, STP)=8.96 L (0.40 mol)","method":"判断 Cl₂/P 物质的量比在 3/2 (1.5) 与 5/2 (2.5) 之间，确定同时生成 PCl₃ 和 PCl₅，再用 P 与 Cl 原子守恒联立求解！","principle":"原子守恒（反应前后 P 原子、Cl 原子总数守恒）。","steps":["计算投料：\\(n(\\mathrm{P}) = \\frac{6.20}{31} = 0.20\\text{ mol}\\)，\\(n(\\mathrm{Cl_2}) = \\frac{8.96}{22.4} = 0.40\\text{ mol}\\)（即 \\(n(\\mathrm{Cl}) = 0.80\\text{ mol}\\)）。","比值判别：若全生成 \\(\\mathrm{PCl_3}\\) 需 \\(\\mathrm{Cl_2}\\) 为 \\(0.20 \\times 1.5 = 0.30\\text{ mol}\\)；若全生成 \\(\\mathrm{PCl_5}\\) 需 \\(\\mathrm{Cl_2}\\) 为 \\(0.20 \\times 2.5 = 0.50\\text{ mol}\\)。","因 \\(0.30 < 0.40 < 0.50\\)，反应后 P 与 Cl₂ 均恰好消耗完，生成物为 **\\(\\mathrm{PCl_3}\\) 与 \\(\\mathrm{PCl_5}\\) 的混合物**。","设生成 \\(n(\\mathrm{PCl_3}) = x\\text{ mol}\\)，\\(n(\\mathrm{PCl_5}) = y\\text{ mol}\\)：","由 P 守恒：\\(x + y = 0.20\\)；由 Cl 守恒：\\(3x + 5y = 0.80\\)。","解得：\\(2y = 0.20 \\implies y = 0.10\\text{ mol}\\ \\mathrm{PCl_5}\\)，\\(x = 0.10\\text{ mol}\\ \\mathrm{PCl_3}\\)。"],"ans":"生成物为 \\(\\mathrm{PCl_3}\\)（\\(0.10\\text{ mol}\\)，液态）和 \\(\\mathrm{PCl_5}\\)（\\(0.10\\text{ mol}\\)，固态）。","markingPoints":["算出 n(P)=0.20 mol 与 n(Cl₂)=0.40 mol（1分）","通过极值区间判断出同时生成 PCl₃ 和 PCl₅（1分）","列出 P、Cl 守恒方程并求得各 0.10 mol（2分）"],"verification":"总 P = 0.20 mol，总 Cl = 0.30 + 0.50 = 0.80 mol（0.40 mol Cl₂），完全吻合。","pitfall":"切忌分两步先写 P+Cl₂ 剩一半再盲目套比例，直接用极限区间判定+原子守恒最省时准确。"}],"cheatSheet":["白磷（P₄, 40℃自燃, 剧毒, 溶 CS₂, 存水中）vs 红磷（240℃, 无毒, 不溶 CS₂）；互变为化学变化。","P₂O₅ + H₂O(冷) → 2HPO₃(偏磷酸，有毒)；P₂O₅ + 3H₂O(热) → 2H₃PO₄(正磷酸，无毒)。","所有磷酸二氢盐均溶于水（Ca(H₂PO₄)₂ 是重过磷酸钙）；(NH₄)₂HPO₄ 与 NH₄H₂PO₄ 是高效氮磷复合肥。"],"kbEntryIds":["kb-chem13-phosphorus"],"quiz":{"q":"安全火柴为什么只有擦在火柴盒侧面的红磷涂层上才能点燃？请简述其中发生的磷的转化过程。","given":"化上 p.323 感知生活“安全火柴”","method":"结合摩擦产热及白磷极低着火点（40℃）分析","principle":"红磷与白磷的着火点差异及高温相互转化。","steps":["火柴盒侧面涂有红磷和 \\(\\mathrm{Sb_2S_3}\\)，火柴头含有 \\(\\mathrm{KClO_3}\\)、\\(\\mathrm{MnO_2}\\) 和硫。","摩擦生热使少量与氯酸钾接触的红磷转化为着火点仅 \\(40\\ ^\\circ\\mathrm{C}\\) 的白磷，白磷迅速自燃引燃火柴头。"],"ans":"摩擦产热使红磷转为着火点极低的白磷（40℃），白磷迅速燃烧引燃火柴头上的易燃物。"}}]},"化学14":{"lessonKey":"化学14","courseCode":"chemistry","subject":"化学","chapter":14,"title":"VIA族元素：氧和硫","syllabus":"3.8 VIA族元素","bookId":"sm1-chemistry-2017","bookCitation":"《马来西亚华文独中教科书 · 化学（上册）》（2017年11月版）第14章 p.336–377","examScopes":["sem2_final","uec"],"chapterOverview":{"summary":"第14章聚焦地壳中丰度第一的氧（O）和工业基石硫（S）：涵盖氧族元素结构递变、O₂ 与同素异形体 O₃（极强氧化性及臭氧层保护）、氧化物按氧化数与酸碱性的双维度分类（含 H₂O₂、Na₂O₂、KO₂）、单质硫、H₂S 强还原性及启普发生器制法、SO₂ 四重性质（酸性、氧化、还原、可逆漂白）与酸雨防治、浓硫酸三大特性（吸水性、脱水性、强氧化性）及接触法制硫酸工业，以及 SO₄²⁻ 排除干扰的标准检验。","conceptTree":[{"branch":"1. 氧、臭氧与氧化物家族（p.336–348）","items":["O₂ 燃烧反应（Fe→Fe₃O₄, S→SO₂）与 KClO₃/H₂O₂ 制氧","O₃ 同素异形体 · 淀粉-KI 变蓝 · 臭氧层破坏机制","氧化物双分类 · H₂O₂ 双向氧化还原 · Na₂O₂ 与 KO₂ 供氧"]},{"branch":"2. 硫单质与硫化氢（p.349–357）","items":["硫的同素异形体 · Fe/Cu 仅被氧化为低价态 FeS/Cu₂S","H₂S（弱酸性、强还原性、不完全燃烧、禁浓硫酸干燥）","启普发生器制 H₂S · 醋酸铅试纸变黑检验"]},{"branch":"3. 二氧化硫与酸雨防治（p.357–362）","items":["H₂SO₃ 酸性 · SO₂ + 2H₂S → 3S 氧化性 · 使溴水/KMnO₄ 褪色还原性","SO₂ 可逆漂白品红（加热复红）vs 氧化永久漂白","硫酸型酸雨成因（pH < 5.6）与防治"]},{"branch":"4. 硫酸、接触法与硫酸盐（p.363–371）","items":["浓硫酸吸水性 vs 脱水性（蔗糖黑面包）vs 强氧化性（钝化、Cu/C/S）","接触法三步骤（沸腾炉→V₂O₅接触室→98.3% 浓硫酸吸收塔）","先稀盐酸酸化再加 BaCl₂ 检验 SO₄²⁻ · 石膏、重晶石、绿矾"]}]},"paperFocus":["下半年期末考 / UEC 统考卷一（30%）：常考氧化物四类/酸碱两性分类、H₂O₂ 氧化还原判断、SO₂ 可逆漂白与还原性褪色辨析、浓硫酸吸水性 vs 脱水性对比、SO₄²⁻ 检验试剂先后顺序。","UEC 统考卷二甲部必答/探究（34%）及乙部无机选答（18%）：高频命制接触法制硫酸工业流程图（净化防中毒、98.3% 浓硫酸吸收防酸雾原因）、Cu+浓硫酸（活动25）及蔗糖炭化（活动24）实验分析、SO₄²⁻ 与 CO₃²⁻/SO₃²⁻ 干扰离子检验设计以及硫化物/氧化物定量计算。"],"solvingWorkflow":["判断漂白机制：遇到“使品红褪色且加热恢复红色”，必属 SO₂ 的化合可逆漂白；遇到“使溴水、KMnO₄ 溶液褪色”，这是 SO₂ 或 H₂S 或 H₂O₂ 的氧化还原反应，绝不能叫漂白！","浓硫酸特性三问法：吸去现成水分子（游离水、胆矾结晶水）→ **吸水性**；把有机物 H、O 按 2:1 剥离炭化 → **脱水性**；金属/碳/硫单质化合价升高且放 SO₂ → **强氧化性**。","SO₄²⁻ 检验铁律：必须“先足量稀 HCl 酸化（无沉淀、无气泡）→ 再加 BaCl₂”，绝不能用稀 HNO₃ 或 Ba(NO₃)₂（防止把 SO₃²⁻ 氧化成 SO₄²⁻ 造成误判）。","Na₂O₂ 气体差量计算：牢记 2Na₂O₂ + 2CO₂ → 2Na₂CO₃ + O₂ 增重相当于等物质的量的 CO（28 g/mol）；2Na₂O₂ + 2H₂O → 4NaOH + O₂ 增重相当于等物质的量的 H₂（2 g/mol）。"],"questionTypes":["氧化物按氧化数（普通、过氧、超氧、复合）及酸碱性（碱/酸/两/中性）综合归类","H₂O₂、Na₂O₂、KO₂ 的供氧定量计算与电子转移分析","H₂S 与 SO₂ 性质对比、启普发生器适用条件及鉴别（CO₂ vs SO₂）","浓硫酸与蔗糖、铜、铁反应的实验探究与接触法工艺流程解析","SO₄²⁻ 干扰排除检验设计及沉淀称量纯度计算"],"scoringNotes":["描述“硫酸根检验”时，若只写“加稀硝酸酸化的 BaCl₂”或“先加 BaCl₂ 再加稀盐酸”，均会因未排除 SO₃²⁻ 氧化或 Ag⁺ 干扰而被扣分。","接触法制硫酸回答“为什么不用水直接吸收 SO₃”时，关键词是“反应放热易形成大量**酸雾**，不利于 SO₃ 吸收”。"],"vid":[{"t":"过氧化氢、过氧化钠与超氧化钾专题","q":"过氧化钠 过氧化氢 超氧化钾 性质与计算 高中化学"},{"t":"硫化氢、二氧化硫漂白性与酸雨对比","q":"二氧化硫 漂白性 硫化氢 性质 高中化学"},{"t":"浓硫酸三大特性与接触法制硫酸工艺","q":"浓硫酸 吸水性 脱水性 强氧化性 接触法制硫酸"},{"t":"硫酸根离子的标准检验与干扰排除","q":"硫酸根离子的检验 氯化钡 稀盐酸 高中化学"}],"sections":[{"id":"14.1","t":"氧","anchor":{"pages":"化上 p.336–340","syllabus":"3.8.1 VIA族通性及氧气的性质与实验室双制法","examScopes":["sem2_final","uec"],"examWeight":"P1 基础概念与实验现象（活动1–4）+ P2 制氧定量与装置对比","terms":"chalcogens · potassium chlorate · hydrogen peroxide · manganese(IV) oxide catalyst","prerequisites":["催化剂改变化学反应速率而不改变自身质量与化学性质","排水集气法与向上排空气法选择依据"],"goals":["结合表14-1 说明VIA族（氧族）元素原子最外层排布（ns²np⁴）与非金属性递变规律。","准确描述细铁丝与硫分别在空气和纯氧中燃烧的实验现象（表14-2），并写出金属、非金属及化合物与 O₂ 反应方程式。","对比实验室加热 KClO₃/MnO₂ 混合物（图14-5）与常温催化分解 H₂O₂（图14-6）两种制氧装置与反应式。"]},"concepts":[{"kind":"table","title":"VIA族（氧族）元素原子结构与主要性质（表14-1）","pageRef":"化上 p.336","body":["VIA族位于元素周期表第16纵行，包括氧（O）、硫（S）、硒（Se）、碲（Te）、钋（Po）和鉝（Lv）。最外层有 \\(6\\) 个电子（\\(ns^2np^4\\)），随着原子序数递增，电子层数增加，原子半径增大，得电子能力减弱，非金属性逐渐减弱。"],"table":{"headers":["元素","原子序数","最外层排布","状态与外观（常温）","密度 / \\(\\mathrm{kg\\,m^{-3}}\\)","熔点 / ℃","沸点 / ℃"],"rows":[["氧（O）","8","\\(2s^2 2p^4\\)","无色气体（液态/固态淡蓝）","1.43","−218.4","−183"],["硫（S）","16","\\(3s^2 3p^4\\)","黄色固体","2060","113","444.6"],["硒（Se）","34","\\(4s^2 4p^4\\)","灰色固体（光敏半导体）","4810","217","685"],["碲（Te）","52","\\(5s^2 5p^4\\)","银白色固体","6240","450","990"],["钋（Po）","84","\\(6s^2 6p^4\\)","银灰色固体（放射性金属）","9398","254","962"]]},"takeaway":"氧是地壳中质量分数最高（几乎占一半）的元素；O₂ 在液态和固态时均呈淡蓝色。"},{"kind":"experiment","title":"活动1 与 活动2：铁丝与硫在空气及纯氧中的燃烧对比（表14-2）","pageRef":"化上 p.337–338","body":["**活动1（铁丝燃烧，图14-2）**：在空气中加热只发红热不燃烧；盘成螺旋状（增大受热面积）下端系火柴引燃后伸入充满纯氧的集气瓶，**剧烈燃烧、火星四射、放出大量热、生成黑色固体**（\\(\\mathrm{3Fe(s) + 2O_2(g)} \\xrightarrow{\\text{点燃}} \\mathrm{Fe_3O_4(s)}\\)）。瓶底预先放少量水或铺细沙，防止高温熔融四氧化三铁溅落炸裂瓶底。","**活动2（硫燃烧，图14-3）**：在空气中燃烧发出微弱**淡蓝色火焰**，在纯氧中燃烧发出**明亮的蓝紫色火焰**，放热并生成刺激性气味气体（\\(\\mathrm{S(s) + O_2(g)} \\xrightarrow{\\text{点燃}} \\mathrm{SO_2(g)}\\)）。","**与化合物剧烈氧化**：\\(\\mathrm{2H_2S + 3O_2} \\xrightarrow{\\text{点燃}} \\mathrm{2SO_2 + 2H_2O}\\)；\\(\\mathrm{CH_4 + 2O_2} \\xrightarrow{\\text{点燃}} \\mathrm{CO_2 + 2H_2O}\\)；\\(\\mathrm{4NH_3 + 5O_2} \\xrightarrow{\\text{点燃/催化}} \\mathrm{4NO + 6H_2O}\\)。"],"takeaway":"燃烧剧烈程度取决于氧气浓度！铁在空气中不能持续燃烧，硫在空气与纯氧中无论氧气是否足量均只生成 SO₂。"},{"kind":"experiment","title":"活动3 与 活动4：实验室两种制取氧气方案（表14-3）","pageRef":"化上 p.338–339","body":["**活动3（加热氯酸钾，图14-5）**：\\(\\mathrm{2KClO_3(s)} \\xrightarrow{\\mathrm{MnO_2}/\\Delta} \\mathrm{2KCl(s) + 3O_2(g)\\uparrow}\\)。试管口略向下倾斜，管口可放一小团棉花，\\(\\mathrm{MnO_2}\\) 作催化剂（\\(\\mathrm{Fe_2O_3}\\)、沙子、玻璃粉也可作催化剂）。","**活动4（双氧水常温分解，图14-6）**：锥形瓶加 \\(0.1\\text{ g }\\mathrm{MnO_2}\\)，通过分液漏斗滴加 \\(6\\%\\ \\mathrm{H_2O_2}\\) 溶液：\\(\\mathrm{2H_2O_2(aq)} \\xrightarrow{\\mathrm{MnO_2}} \\mathrm{2H_2O(l) + O_2(g)\\uparrow}\\)。此法无需加热、分液漏斗易于控制反应速率且副产物仅水无污染。","**检验氧气**：将**带余烬的木枝**伸入集气瓶中，木枝**复燃**。"],"takeaway":"H₂O₂ 制氧是“固+液不加热型”经典发生装置，配合分液漏斗可随时控制滴加速率从而控制气流平稳。"}],"formulas":[{"title":"氧气与铁、钠、硫化氢的典型反应","tex":"\\mathrm{3Fe(s) + 2O_2(g)} \\xrightarrow{\\text{点燃}} \\mathrm{Fe_3O_4(s)},\\qquad \\mathrm{2Na(s) + O_2(g)} \\xrightarrow{\\text{点燃}} \\mathrm{Na_2O_2(s)},\\qquad \\mathrm{2H_2S(g) + 3O_2(g)} \\xrightarrow{\\text{点燃}} \\mathrm{2SO_2(g) + 2H_2O(l)}","plain":"3Fe + 2O2 -> Fe3O4; 2Na + O2 -> Na2O2; 2H2S + 3O2 -> 2SO2 + 2H2O","conditions":"铁需纯氧引燃；钠燃烧生成淡黄色过氧化钠；硫化氢充分燃烧","pageRef":"化上 p.338","note":"对比钠在常温空气中只氧化为白色 Na₂O，加热或点燃时生成淡黄色 Na₂O₂。"},{"title":"实验室制取氧气双路径方程式","tex":"\\mathrm{2KClO_3(s)} \\xrightarrow{\\mathrm{MnO_2}/\\Delta} \\mathrm{2KCl(s) + 3O_2(g)\\uparrow},\\qquad \\mathrm{2H_2O_2(aq)} \\xrightarrow{\\mathrm{MnO_2}} \\mathrm{2H_2O(l) + O_2(g)\\uparrow}","plain":"2KClO3 --MnO2/Δ--> 2KCl + 3O2; 2H2O2 --MnO2--> 2H2O + O2","conditions":"MnO₂ 反应前后质量和化学性质不变","pageRef":"化上 p.339","note":"KClO₃ 分解结束后若需回收固态催化剂 MnO₂，可经“溶解 → 过滤 → 洗涤 → 干燥”分离（KCl 易溶于水，MnO₂ 难溶于水）。"}],"pitfalls":[{"title":"忘记铁丝在氧气中燃烧生成 Fe₃O₄ 而错写成 Fe₂O₃","wrong":"“铁丝在纯氧中剧烈燃烧生成红棕色氧化铁（\\(\\mathrm{Fe_2O_3}\\)）。”","diagnosis":"铁高温熔融与纯氧迅速燃烧的产物是黑色四氧化三铁（\\(\\mathrm{Fe_3O_4}\\)），只有缓慢生锈或常温/高温漫长氧化才生成红棕色 \\(\\mathrm{Fe_2O_3}\\)。","right":"纯氧中剧烈燃烧：\\(\\mathrm{3Fe + 2O_2} \\xrightarrow{\\text{点燃}} \\mathrm{Fe_3O_4}\\)（黑色固体）。","checkRule":"遇到“Fe 在 O₂ 中燃烧”，产物必为黑色 Fe₃O₄。"},{"title":"做 KClO₃ 制氧实验忘记放水倒吸防护与过滤分离错误","wrong":"“排水法集满氧气后先熄灭酒精灯再撤导管；用蒸发结晶回收固体催化剂 \\(\\mathrm{MnO_2}\\)。”","diagnosis":"先撤酒精灯会导致冷缩水倒吸入热试管炸裂；\\(\\mathrm{MnO_2}\\) 难溶于水而 \\(\\mathrm{KCl}\\) 溶于水，应采用过滤分离。","right":"实验结束先将导管移出水面，再熄灭酒精灯；回收 \\(\\mathrm{MnO_2}\\) 用“加水溶解、过滤、洗涤、干燥”。","checkRule":"固体+液体催化剂分离选“过滤”，切忌用蒸发。"}],"examples":[{"label":"例 14.1.1","tier":"L2","tierLabel":"L2 校内期末","title":"氯酸钾与二氧化锰混合物加热减重求纯度","prompt":"称取 \\(28.0\\text{ g}\\) 氯酸钾（\\(\\mathrm{KClO_3}\\)）和二氧化锰（\\(\\mathrm{MnO_2}\\)）的固体混合物放入大试管中充分加热至质量不再变化，冷却后称得剩余固体总质量为 \\(18.4\\text{ g}\\)。求：(1) 反应共生成多少克氧气？(2) 原固体混合物中 \\(\\mathrm{MnO_2}\\) 的质量分数。（\\(\\mathrm{K}=39,\\ \\mathrm{Cl}=35.5,\\ \\mathrm{O}=16\\)）","clues":"固体减少的质量就是逸出氧气的质量！","strategy":"由质量守恒得 m(O₂)，再依 2KClO₃ → 2KCl + 3O₂↑ 求 m(KClO₃) 及 m(MnO₂)。","given":"m(原固体)=28.0 g，m(剩固体)=18.4 g，M(KClO₃)=122.5 g/mol","principle":"物质不灭定律（Δm = m(O₂)）与化学方程式计量。","steps":["(1) 生成氧气的质量：\\(m(\\mathrm{O_2}) = 28.0\\text{ g} - 18.4\\text{ g} = 9.60\\text{ g}\\)，即 \\(n(\\mathrm{O_2}) = \\frac{9.60}{32} = 0.30\\text{ mol}\\)。","(2) 依据 \\(\\mathrm{2KClO_3} \\xrightarrow{\\mathrm{MnO_2}/\\Delta} \\mathrm{2KCl + 3O_2\\uparrow}\\)，\\(n(\\mathrm{KClO_3}) = \\frac{2}{3} \\times 0.30 = 0.20\\text{ mol}\\)。","原氯酸钾质量：\\(m(\\mathrm{KClO_3}) = 0.20\\text{ mol} \\times 122.5\\text{ g}\\cdot\\mathrm{mol^{-1}} = 24.5\\text{ g}\\)。","原 \\(\\mathrm{MnO_2}\\) 质量：\\(m(\\mathrm{MnO_2}) = 28.0\\text{ g} - 24.5\\text{ g} = 3.5\\text{ g}\\)，质量分数 \\(w(\\mathrm{MnO_2}) = \\frac{3.5}{28.0} \\times 100\\% = 12.5\\%\\)。"],"answer":"(1) \\(9.60\\text{ g}\\) 氧气；(2) \\(12.5\\%\\)。","markingPoints":["利用质量差求得 m(O₂)=9.60 g (0.30 mol)（1分）","算得 KClO₃ 质量为 24.5 g（2分）","求得 MnO₂ 质量分数为 12.5%（1分）"],"verification":"剩余固体中 \\(m(\\mathrm{KCl}) = 0.20 \\times 74.5 = 14.9\\text{ g}\\)，加 \\(3.5\\text{ g }\\mathrm{MnO_2}\\) 恰好为 \\(18.4\\text{ g}\\)。","pitfall":"切忌把剩余固体 18.4 g 全当成 KCl 去算！"},{"label":"例 14.1.2","tier":"L3","tierLabel":"L3 预试拔高","title":"活动1 与 活动2 装置操作细节与异常诊断","prompt":"(1) 实验室做“铁丝在氧气中燃烧”和“硫在氧气中燃烧”两个实验时，集气瓶底通常都要预先放入少量水。请分别说明这两个实验中瓶底放水的**不同作用**；(2) 某同学改用 \\(\\mathrm{H_2O_2}\\) 溶液与 \\(\\mathrm{MnO_2}\\) 制氧时，发现气泡产生过于剧烈甚至将橡皮塞冲出，从图14-6 装置角度提出两项改进操作。","clues":"铁丝燃烧生成高温熔融物（物理防炸裂）；硫燃烧生成有毒大气污染物 SO₂（化学吸收防污染）。","strategy":"区分物理吸热防护与化学尾气吸收；从降低接触/滴加速率与反应物浓度改进固液装置。","given":"活动1 铁丝燃烧；活动2 硫燃烧；图14-6 分液漏斗制氧","principle":"实验安全与绿色化学尾气处理。","steps":["(1) 铁丝燃烧中放水的作用是：**防止高温熔融的四氧化三铁生成物溅落瓶底，引起集气瓶炸裂**（可用细沙代替）；硫燃烧中放水（或稀碱液）的作用是：**吸收反应生成的有毒 \\(\\mathrm{SO_2}\\) 气体，防止污染空气**（不能用细沙代替）。","(2) 改进措施：① 旋紧或调小**分液漏斗活塞**，逐滴缓慢滴加 \\(\\mathrm{H_2O_2}\\) 溶液以控制反应速率；② 将 \\(\\mathrm{H_2O_2}\\) 溶液适当**稀释**（或减少 \\(\\mathrm{MnO_2}\\) 用量）。"],"answer":"(1) 铁丝实验防熔融物炸裂瓶底；硫实验吸收有毒 SO₂ 气体防污染；(2) 调慢分液漏斗滴速、适当稀释双氧水。","markingPoints":["准确区分两实验中水的不同用途（2分）","提出合理控速改进措施（2分）"],"verification":"对照化上 p.337–339 实验设计逻辑核对。","pitfall":"回答硫燃烧放水时误写“防止炸裂瓶底”，硫燃烧产物 SO₂ 是气体而非熔融固体。"}],"practice":[{"id":"chem14-14.1-q1","tier":"L1","tierLabel":"L1 基础","examStyle":"P1 选择","q":"下列关于氧族元素及氧气的描述中，**错误**的是（　）。","options":["A. 氧族元素原子最外层都有 6 个电子","B. 液态氧与固态氧均呈淡蓝色","C. 硫在纯氧中燃烧发出明亮的蓝紫色火焰并生成三氧化硫","D. 工业上可通过分离液态空气的方法大量制取氧气"],"correctOption":"C","given":"VIA族基本性质与硫燃烧","method":"对照硫在氧气中燃烧产物","principle":"硫无论在空气还是纯氧中燃烧都只生成 SO₂。","steps":["C 错：硫在纯氧中燃烧火焰由淡蓝变为明亮蓝紫色，但产物依然是二氧化硫（\\(\\mathrm{SO_2}\\)），而不是 \\(\\mathrm{SO_3}\\)。"],"ans":"C","markingPoints":["识别硫燃烧只生成 SO₂"],"verification":"对照化上 p.338 及思考题 14d 第1题 D。","pitfall":"误以为氧气充足就能把硫直接烧成 SO₃。"},{"id":"chem14-14.1-q2","tier":"L2","tierLabel":"L2 期末","examStyle":"P1 选择","q":"用 \\(\\mathrm{KClO_3}\\) 和 \\(\\mathrm{MnO_2}\\) 混合加热制取氧气后，要从完全反应后的剩余固体混合物中回收纯净干燥的 \\(\\mathrm{MnO_2}\\)，最合理的实验操作顺序是（　）。","options":["A. 加水溶解 → 蒸发结晶 → 洗涤 → 干燥","B. 加水溶解 → 过滤 → 洗涤 → 干燥","C. 直接高温煅烧使氯化钾挥发","D. 加入稀盐酸溶解 → 过滤 → 干燥"],"correctOption":"B","given":"剩余固体为 KCl（可溶）与 MnO₂（难溶）","method":"根据溶解性差异选分离方法","principle":"过滤可分离难溶固体与可溶性盐溶液。","steps":["KCl 溶于水而 MnO₂ 不溶于水，因此先加水溶解使 KCl 进入滤液，过滤截留 MnO₂ 滤渣，洗涤去表面残留 KCl 后干燥即得纯净 MnO₂。"],"ans":"B","markingPoints":["掌握溶解—过滤—洗涤—干燥流程"],"verification":"对照化上 p.339 反应产物状态验证。","pitfall":"选 A 蒸发结晶会把 KCl 重新析出混在 MnO₂ 里。"},{"id":"chem14-14.1-q3","tier":"L3","tierLabel":"L3 预试","examStyle":"P1 选择","q":"将一定量的 \\(\\mathrm{H_2S}\\)、\\(\\mathrm{CH_4}\\) 和 \\(\\mathrm{NH_3}\\) 各 \\(1\\text{ mol}\\) 分别在氧气中按教材方程式完全氧化（生成 \\(\\mathrm{SO_2}\\)、\\(\\mathrm{CO_2}\\) 和 \\(\\mathrm{NO}\\)），耗氧量由大到小的正确顺序是（　）。","options":["A. \\(\\mathrm{CH_4 > H_2S > NH_3}\\)","B. \\(\\mathrm{H_2S > CH_4 > NH_3}\\)","C. \\(\\mathrm{NH_3 > CH_4 > H_2S}\\)","D. \\(\\mathrm{CH_4 > NH_3 > H_2S}\\)"],"correctOption":"A","given":"化上 p.338 三条化合物氧化方程式","method":"计算每 1 mol 燃料消耗 O₂ 的物质的量","principle":"化学计量数比例换算。","steps":["\\(\\mathrm{CH_4 + 2O_2 \\to CO_2 + 2H_2O}\\)：每 \\(1\\text{ mol}\\) 耗 \\(2.0\\text{ mol }\\mathrm{O_2}\\)；","\\(\\mathrm{2H_2S + 3O_2 \\to 2SO_2 + 2H_2O}\\)：每 \\(1\\text{ mol}\\) 耗 \\(1.5\\text{ mol }\\mathrm{O_2}\\)；","\\(\\mathrm{4NH_3 + 5O_2 \\to 4NO + 6H_2O}\\)：每 \\(1\\text{ mol}\\) 耗 \\(1.25\\text{ mol }\\mathrm{O_2}\\)。"],"ans":"A","markingPoints":["准确换算 2.0 > 1.5 > 1.25"],"verification":"电子数核对：CH₄ 失 8e⁻，H₂S 失 6e⁻，NH₃ 失 5e⁻，故耗氧比 8:6:5。","pitfall":"看错系数未除以 2 或 4 直接比较 3、2、5。"},{"id":"chem14-14.1-q4","tier":"L4","tierLabel":"L4 统考压轴","examStyle":"P2 实验与计算","q":"在 \\(t\\ ^\\circ\\mathrm{C}\\) 下，将 \\(2.50\\text{ g }\\mathrm{MnO_2}\\) 投入 \\(68.0\\text{ g}\\) 质量分数为 \\(10\\%\\) 的 \\(\\mathrm{H_2O_2}\\) 水溶液中充分反应至完全分解。(1) 写出反应方程式并计算在标准状况下放出氧气的体积；(2) 若实验发现随着反应进行，液体温度明显升高且反应结束后过滤洗涤干燥所得黑色固体质量仍为 \\(2.50\\text{ g}\\)，请说明该实验从哪两方面证明 \\(\\mathrm{MnO_2}\\) 是催化剂？（已知 \\(M(\\mathrm{H_2O_2})=34\\text{ g}\\cdot\\mathrm{mol^{-1}}\\)）","given":"m(MnO₂)=2.50 g，m(溶液)=68.0 g，w(H₂O₂)=10%","method":"先算溶质 H₂O₂ 物质的量，依 2:1 算 O₂ 体积；结合催化剂‘改速率+质量化学性质不变’作答","principle":"催化剂定义与反应计量。","steps":["(1) \\(\\mathrm{2H_2O_2(aq)} \\xrightarrow{\\mathrm{MnO_2}} \\mathrm{2H_2O(l) + O_2(g)\\uparrow}\\)。","\\(m(\\mathrm{H_2O_2}) = 68.0\\text{ g} \\times 10\\% = 6.80\\text{ g}\\)，\\(n(\\mathrm{H_2O_2}) = \\frac{6.80}{34} = 0.20\\text{ mol}\\)。","由计量比得 \\(n(\\mathrm{O_2}) = 0.10\\text{ mol}\\)，标况体积 \\(V(\\mathrm{O_2}) = 0.10 \\times 22.4 = 2.24\\text{ L}\\)。","(2) ① 加快了 \\(\\mathrm{H_2O_2}\\) 分解速率（迅速产气且放热明显）；② 反应前后 \\(\\mathrm{MnO_2}\\) 质量保持 \\(2.50\\text{ g}\\) 不变（还需验证其化学性质也未变，如再次加入新 \\(\\mathrm{H_2O_2}\\) 仍能快速催发产生气泡）。"],"ans":"(1) \\(2.24\\text{ L}\\)；(2) 加快反应速率且反应前后质量保持 2.50 g 不变（再加新双氧水可验证化学性质不变）。","markingPoints":["写出方程式并求得 2.24 L（2分）","答出加快反应速率与反应前后质量不变（若提化学性质验证更佳，2分）"],"verification":"6.80 g H₂O₂ 含 O 6.40 g，一半变 O₂ 即 3.20 g (0.10 mol, 2.24 L)。","pitfall":"误把溶液质量 68.0 g 直接当作溶质 H₂O₂ 质量代入计算。"}],"cheatSheet":["VIA族（ns²np⁴）：O、S、Se、Te、Po，非金属性随原子序数增大而减弱。","燃烧要点：3Fe + 2O₂ → Fe₃O₄（黑色）；S + O₂ → SO₂（无论 O₂ 是否过量均不生成 SO₃）。","制氧双法：2KClO₃ —MnO₂/Δ→ 2KCl + 3O₂↑（固固加热）；2H₂O₂ —MnO₂→ 2H₂O + O₂↑（固液常温）。"],"kbEntryIds":["kb-chem14-o2-prep"],"quiz":{"q":"为什么铁丝在空气中加热只能红热而不能剧烈燃烧，但在纯氧中却能火星四射剧烈燃烧？","given":"活动1（化上 p.337 表14-2）","method":"从反应物氧气浓度对反应速率和放热速率的影响解释","principle":"反应物浓度越大，单位时间有效碰撞越多，反应越剧烈。","steps":["空气中氧气仅占约 \\(21\\%\\)，浓度较低且大量氮气带走热量，反应速率慢、放热不足以维持剧烈燃烧。","纯氧中 \\(\\mathrm{O_2}\\) 浓度极大，单位时间内与铁表面碰撞反应剧增，放热迅速积聚引起火星四射剧烈燃烧。"],"ans":"纯氧中氧气浓度远高于空气（21%），碰撞频率高、反应放热集中，故能剧烈燃烧。"}},{"id":"14.2","t":"臭氧","anchor":{"pages":"化上 p.341–343","syllabus":"3.8.2 臭氧的性质、极强氧化性检验、消毒机制与臭氧层保护","examScopes":["sem2_final","uec"],"examWeight":"P1 同素异形体与检验辨析 + P2 臭氧层破坏催化机理简答","terms":"ozone · allotrope · nascent oxygen · starch-potassium iodide paper · ozone depletion","prerequisites":["同素异形体定义（化上 Ch 12.1.2）","碘单质遇淀粉变蓝检验反应"],"goals":["对比 O₃ 与 O₂ 的物理性质差异，说明 3O₂ ⇌ 2O₃ 互为同素异形体的化学转化本质。","掌握臭氧氧化 Ag、黑色 PbS 及使湿润淀粉—碘化钾试纸变蓝的方程式，理解其杀菌消毒三大优点（高效、广谱、无二次污染）。","结合思考题 14b 分析氟利昂与超声速飞机尾气（NO）催化加速平流层臭氧分解的机理。"]},"concepts":[{"kind":"definition","title":"臭氧的物理性质、生成与不稳定性","pageRef":"化上 p.341","body":["**同素异形体**：臭氧（\\(\\mathrm{O_3}\\)）与氧气（\\(\\mathrm{O_2}\\)）互为氧元素的同素异形体。在常温常压下，臭氧是具有**特殊臭味**的**淡蓝色气体**，密度比氧气大，也比氧气易溶于水；液态呈深蓝色（bp −112.4℃），固态呈紫黑色（mp −251℃）。","**生成途径**：闪电放电、复印机高压放电或实验室臭氧发生器中 \\(\\mathrm{3O_2(g)} \\xrightarrow{\\text{放电}} \\mathrm{2O_3(g)}\\)。雷雨后微量臭氧可刺激中枢神经、加速血液循环使人感到爽快；但高浓度吸入会刺激呼吸道甚至诱发肺水肿。","**不稳定性**：臭氧不稳定，常温缓慢分解、受热迅速分解放热：\\(\\mathrm{2O_3(g)} \\xrightarrow{\\Delta} \\mathrm{3O_2(g)}\\)。"],"takeaway":"3O₂ → 2O₃ 与 2O₃ → 3O₂ 均为同素异形体之间的化学变化（且反应前后气体分子数不同）。"},{"kind":"law","title":"臭氧的极强氧化性及湿润淀粉—碘化钾检验","pageRef":"化上 p.342","body":["**极强氧化性**：臭氧氧化性远强于氧气，分解时先产生极活泼的初生态氧（\\(\\mathrm{O}\\)），常温下即可氧化通常不与氧气反应的银和黑色硫化铅(II)：","① 氧化黑色硫化铅(II)成白色硫酸铅(II)：\\(\\mathrm{PbS(s) + 2O_3(g) \\longrightarrow PbSO_4(s) + O_2(g)}\\)；","② 常温氧化金属银：\\(\\mathrm{2Ag(s) + 2O_3(g) \\longrightarrow Ag_2O_2(s) + 2O_2(g)}\\)。","**经典检验（酸性淀粉-KI 试纸）**：酸性条件下，臭氧将 \\(\\mathrm{I^-}\\) 氧化为 \\(\\mathrm{I_2}\\)，使湿润的淀粉—碘化钾试纸**变蓝**：\\(\\mathrm{2KI(aq) + H_2SO_4(aq) + O_3(g) \\longrightarrow I_2(s) + O_2(g) + K_2SO_4(aq) + H_2O(l)}\\)。"],"takeaway":"注意 Cl₂、NO₂、O₃ 都能使湿润淀粉—KI 试纸变蓝，故该试纸只能验证强氧化性气体存在，不可单独定性区分三者。"},{"kind":"mechanism","title":"臭氧溶菌消毒优点与平流层臭氧空洞催化破坏机理","pageRef":"化上 p.342–343","body":["**臭氧灭菌三大优点（资料链接 p.342）**：① **高效性**（杀菌速度比氯快 600~3000 倍）；② **广谱性**（溶菌级，杀灭细菌繁殖体、芽孢、病毒、真菌等）；③ **无污染**（多余氧原子在 30 分钟后自行结合回 \\(\\mathrm{O_2}\\)，不留任何消毒剂二次残留物）。","**臭氧层破坏机理（思考题 14b 第3题）**：高空平流层臭氧可吸收太阳有害紫外线；但制冷剂氟利昂光解产生的氯原子（Cl·）和超音速飞机尾气中的 \\(\\mathrm{NO}\\) 都会催化加速臭氧分解。以 \\(\\mathrm{NO}\\) 为例：\\(\\mathrm{NO + O_3 \\longrightarrow NO_2 + O_2}\\)（或按教材分步 \\(\\mathrm{NO + O_3 \\to NO_2 + 2O}\\)、\\(\\mathrm{NO_2 + O \\to NO + O_2}\\)），总反应为 \\(\\mathrm{2O_3 \\longrightarrow 3O_2}\\)（\\(\\mathrm{NO}\\) 在循环中不断再生，起**催化剂**和**还原剂**作用）。"],"takeaway":"在平流层破坏机理中，极微量 NO 或 Cl 原子就能催化破坏成千上万个 O₃ 分子，正因为它们充当了催化剂！"}],"formulas":[{"title":"臭氧生成、分解与淀粉-KI 检验方程式","tex":"\\mathrm{3O_2(g)} \\xrightarrow{\\text{高压放电}} \\mathrm{2O_3(g)},\\qquad \\mathrm{2KI(aq) + H_2SO_4(aq) + O_3(g) \\longrightarrow I_2(s) + O_2(g) + K_2SO_4(aq) + H_2O(l)}","plain":"3O2 --放电--> 2O3; 2KI + H2SO4 + O3 -> I2 + O2 + K2SO4 + H2O","conditions":"1 mol O₃ 仅还原生成 1 mol O₂ 和 1 mol I₂（转移 2 mol 电子！）","pageRef":"化上 p.341–342","note":"切忌写成 1 mol O₃ 得 6 mol 电子！臭氧氧化 KI 时，3 个 O 原子中仅 1 个降为 −2 价进入 H₂O，另 2 个保留 0 价变为 O₂ 逸出！"},{"title":"臭氧氧化硫化铅(II)与金属银的方程式","tex":"\\mathrm{PbS(s) + 2O_3(g) \\longrightarrow PbSO_4(s) + O_2(g)},\\qquad \\mathrm{2Ag(s) + 2O_3(g) \\longrightarrow Ag_2O_2(s) + 2O_2(g)}","plain":"PbS + 2O3 -> PbSO4 + O2; 2Ag + 2O3 -> Ag2O2 + 2O2","conditions":"常温即可进行，利用强氧化性漂白或氧化金属","pageRef":"化上 p.342","note":"对比教材第342页：臭氧作消毒剂和脱色漂白剂，原理就是强氧化破坏有色基团或微生物结构。"}],"pitfalls":[{"title":"错算臭氧作氧化剂时的电子转移数","wrong":"“\\(\\mathrm{1\\ mol\\ O_3}\\) 氧化酸性 KI 溶液时，因为含 3 个 O 原子全变成 −2 价水，共得到 \\(6\\text{ mol}\\) 电子。”","diagnosis":"对照教材 p.342 反应式 \\(\\mathrm{2KI + H_2SO_4 + O_3 \\to I_2 + O_2 + K_2SO_4 + H_2O}\\)，反应后明显放出了 \\(\\mathrm{1\\ mol\\ O_2}\\)！","right":"臭氧在中性/酸性水溶液中作氧化剂时，通常只有 **1 个氧原子**被还原为 \\(\\mathrm{H_2O}\\)（得 \\(2\\text{ mol }e^-\\)），另外 2 个氧原子仍以 \\(\\mathrm{O_2}\\) 形式放出。","checkRule":"遇到臭氧氧化计量题，牢记教材标准式：\\(\\mathrm{O_3 \\leftrightarrow I_2 \\leftrightarrow 2e^-}\\)！"},{"title":"认为臭氧只对人体有益无害","wrong":"“臭氧杀菌无残留污染，因此室内空气中臭氧浓度越高对人体越有益。”","diagnosis":"臭氧在平流层防紫外线、低浓度令人精神振奋，但地面空气中臭氧过量（如光化学烟雾或复印机旁大量积聚）会强烈氧化呼吸道黏膜。","right":"长期吸入过量臭氧会引起口干舌燥、咳嗽甚至诱发中毒性肺水肿（教材思考题 14b 第1、2题）。","checkRule":"臭氧有“平流层守护神、近地面光化学污染物”两面性。"}],"examples":[{"label":"例 14.2.1","tier":"L3","tierLabel":"L3 预试拔高","title":"臭氧发生器体积差量法测转化率","prompt":"在臭氧发生器中装入 \\(100\\text{ mL}\\) 纯净氧气（同温同压下测定），经过高压放电一段时间后，测得容器内混合气体总体积缩减为 \\(92\\text{ mL}\\)。试计算：(1) 生成了多少毫升臭氧？(2) 氧气的转化率是多少？（同温同压测定）","clues":"利用 3O₂ → 2O₃，每反应 3 体积 O₂ 生成 2 体积 O₃，气体总体积减少 1 体积！","strategy":"用气体体积差量 ΔV 一步锁定反应消耗的 O₂ 和生成的 O₃ 体积。","given":"V₀(O₂) = 100 mL，反应后 V = 92 mL，ΔV = 8 mL","principle":"阿伏加德罗气体体积定律与差量法。","steps":["写出转化方程式及体积差量关系：\\(\\mathrm{3O_2(g)} \\xrightarrow{\\text{放电}} \\mathrm{2O_3(g)}\\)，每消耗 \\(3\\text{ mL }\\mathrm{O_2}\\)，生成 \\(2\\text{ mL }\\mathrm{O_3}\\)，气体体积减少 \\(\\Delta V = 3 - 2 = 1\\text{ mL}\\)。","(1) 实验测得总体积减少：\\(\\Delta V = 100\\text{ mL} - 92\\text{ mL} = 8\\text{ mL}\\)。","按比例关系，生成臭氧体积为：\\(V(\\mathrm{O_3}) = 2 \\times 8\\text{ mL} = 16\\text{ mL}\\)。","(2) 消耗氧气体积为：\\(V_{\\text{耗}}(\\mathrm{O_2}) = 3 \\times 8\\text{ mL} = 24\\text{ mL}\\)。","氧气转化率：\\(\\alpha(\\mathrm{O_2}) = \\frac{24\\text{ mL}}{100\\text{ mL}} \\times 100\\% = 24\\%\\)。"],"answer":"(1) 生成 \\(16\\text{ mL}\\) 臭氧；(2) 氧气转化率为 \\(24\\%\\)。","markingPoints":["列出 3O₂ → 2O₃ 体积差 ΔV=1 比例（1分）","求得生成臭氧 16 mL（1.5分）","算得消耗氧气 24 mL 与转化率 24%（1.5分）"],"verification":"反应后剩余 \\(\\mathrm{O_2} = 100 - 24 = 76\\text{ mL}\\)，加上 \\(16\\text{ mL }\\mathrm{O_3}\\)，总体积 \\(76 + 16 = 92\\text{ mL}\\)！","pitfall":"错把减少的 8 mL 当成生成的臭氧体积。"},{"label":"例 14.2.2","tier":"L2","tierLabel":"L2 校内期末","title":"平流层一氧化氮破坏臭氧层的机理分析（思考题 14b 第3题）","prompt":"超音速飞机尾气排放的 \\(\\mathrm{NO}\\) 能加速平流层臭氧的分解，教材中给出的两步反应过程如下：第一步 \\(\\mathrm{NO + O_3 \\longrightarrow NO_2 + 2O}\\)（或产生氧原子中间体），第二步 \\(\\mathrm{NO_2 + O \\longrightarrow NO + O_2}\\)（若写成 \\(\\mathrm{NO + O_3 \\to NO_2 + O_2}\\) 与 \\(\\mathrm{NO_2 + O \\to NO + O_2}\\) 配平）。(1) 请写出消去中间产物 \\(\\mathrm{NO_2}\\) 和 \\(\\mathrm{O}\\) 后的净总化学方程式；(2) 在上述破坏过程中，一氧化氮起什么作用？","clues":"两步反应相加，观察 NO 在反应前后质量与化学形态是否复原。","strategy":"对照教材思考题 14b 第3题：用第一步 + 2×第二步消去 O 原子与 NO₂，指出 NO 的催化角色与第一步还原剂角色。","given":"① NO + O₃ → NO₂ + 2O；② NO₂ + O → NO + O₂（注：此处按教材原文 p.343 思考题3给定式子分析）","principle":"催化剂参与中间反应并在后续步骤再生；反应前后总化学计量不变。","steps":["(1) 教材 p.343 原文给出两式为 \\(\\mathrm{NO + O_3 \\to NO_2 + 2O}\\) 与 \\(\\mathrm{NO_2 + O \\to NO + O_2}\\)（实际微观总过程净效果即臭氧分解转化为氧气）：配平消去中间体后的总反应净结果是：\\(\\mathrm{2O_3(g)} \\xrightarrow{\\mathrm{NO}} \\mathrm{3O_2(g)}\\)（按标准基元循环：\\(\\mathrm{NO + O_3 \\to NO_2 + O_2}\\) 与 \\(\\mathrm{NO_2 + O \\to NO + O_2}\\) 联合光解 O₃）。","(2) 在第一步中，\\(\\mathrm{NO}\\) 夺取氧变成 \\(\\mathrm{NO_2}\\) 起**还原剂**作用；从全过程来看，\\(\\mathrm{NO}\\) 先消耗后又完全再生，极大地加速了 \\(\\mathrm{O_3}\\) 的分解，因此其本质作用是**催化剂**（同时第一步中作**还原剂**）。"],"answer":"(1) \\(\\mathrm{2O_3} \\xrightarrow{\\mathrm{NO}} \\mathrm{3O_2}\\)；(2) 起**催化剂**和**还原剂**作用。","markingPoints":["正确写出臭氧分解为氧气的总方程式 2O₃ → 3O₂（2分）","指明 NO 起催化剂和第一步还原剂作用（2分）"],"verification":"对照化上 p.343 思考题 14b 第3题两空标准设计核对。","pitfall":"注意若照机械相加 p.343 印刷式（①式右方含 2O 会导致 O 原子总数多 1），回答时务必写出标准化学计量总式 \\(\\mathrm{2O_3 \\to 3O_2}\\)。"}],"practice":[{"id":"chem14-14.2-q1","tier":"L1","tierLabel":"L1 基础","examStyle":"P1 选择","q":"高压电机和复印机工作时会因放电产生臭氧（\\(\\mathrm{O_3}\\)）。下列关于臭氧的说法中，**不正确**的是（　）。","options":["A. 臭氧和氧气是氧元素的同素异形体","B. 臭氧在酸性条件下可使湿润的淀粉—碘化钾试纸变蓝","C. 臭氧的存在对人体只有益处，没有任何危害","D. 臭氧是高效的消毒剂和脱色漂白剂"],"correctOption":"C","given":"臭氧性质与安全（化上 p.343 思考题 14b 第2题）","method":"逐项比对教材原文","principle":"大量吸入臭氧对人体呼吸道有害。","steps":["C 错：微量臭氧使人精神振奋，但空气中过量臭氧会刺激呼吸道、诱发咳嗽与肺水肿。"],"ans":"C","markingPoints":["识别过量臭氧对人体的危害"],"verification":"对照化上 p.343 思考题 14b 第2题。","pitfall":"误以为杀菌无残留就等于吸入高浓度臭氧安全。"},{"id":"chem14-14.2-q2","tier":"L2","tierLabel":"L2 期末","examStyle":"P1 选择","q":"相同质量的氧气（\\(\\mathrm{O_2}\\)）和臭氧（\\(\\mathrm{O_3}\\)）相比，下列说法正确的是（　）。","options":["A. 两者所含分子个数相等","B. 两者在同温同压下的体积相等","C. 两者所含氧原子总数相等","D. 两者的化学性质完全相同"],"correctOption":"C","given":"等质量的 O₂ 与 O₃（M=32 vs 48）","method":"设质量为 96 g，比较分子数、体积与氧原子数","principle":"质量相等且全由 O 原子组成时，氧原子总数必然相等。","steps":["取 \\(96\\text{ g}\\)：\\(n(\\mathrm{O_2}) = 3\\text{ mol}\\)（含 \\(6\\text{ mol O}\\)），\\(n(\\mathrm{O_3}) = 2\\text{ mol}\\)（含 \\(6\\text{ mol O}\\)）。","分子数与同温压体积比为 \\(3:2\\)，仅氧原子总数相等；分子构成不同化学性质迥异。"],"ans":"C","markingPoints":["运用等质量单质原子守恒"],"verification":"Atom count = m / 16。","pitfall":"误选 A 或 B，忽略两者摩尔质量不同（32 vs 48）。"},{"id":"chem14-14.2-q3","tier":"L3","tierLabel":"L3 预试","examStyle":"P2 简答","q":"自来水厂现代消毒工艺中常用臭氧逐步替代部分氯气消毒。(1) 与氯气消毒相比，简述臭氧消毒的三项突出优势；(2) 向酸性碘化钾淀粉溶液中通入少量臭氧，写出观察到的现象及发生反应的化学方程式。","given":"化上 p.342 资料链接“臭氧杀菌的作用机制与特性”","method":"直接提炼教材三大优点并写全 p.342 检验式","principle":"高效（比氯快 600~3000 倍）、广谱溶菌、无残留（O 复原为 O₂）。","steps":["(1) 三项优势：① **高效性**（灭菌速度比氯快 \\(600\\sim 3000\\) 倍）；② **广谱性**（溶菌级，可杀灭细菌繁殖体、芽孢、病毒及真菌）；③ **无二次污染**（多余氧原子在约 30 分钟后复合成 \\(\\mathrm{O_2}\\)，不留有害化学残留物）。","(2) 现象：溶液变为**蓝色**（同时有气泡逸出）。化学方程式：\\(\\mathrm{2KI(aq) + H_2SO_4(aq) + O_3(g) \\longrightarrow I_2(s) + O_2(g) + K_2SO_4(aq) + H_2O(l)}\\)。"],"ans":"(1) 高效、广谱、无残留二次污染；(2) 溶液变蓝，方程式见步骤。","markingPoints":["完整列出高效、广谱、无残留三大优点（2分）","现象与配平方程式准确（2分）"],"verification":"对照化上 p.342 原文。","pitfall":"写方程式时漏掉右边产物 O₂。"},{"id":"chem14-14.2-q4","tier":"L4","tierLabel":"L4 统考压轴","examStyle":"P2 综合计算","q":"将标准状况下体积为 \\(2.24\\text{ L}\\) 的 \\(\\mathrm{O_2}\\) 和 \\(\\mathrm{O_3}\\) 混合气体全部通入足量的酸性碘化钾（\\(\\mathrm{KI}\\)）溶液中（\\(\\mathrm{O_2}\\) 在该条件下不与 \\(\\mathrm{KI}\\) 反应），充分反应后用硫代硫酸钠溶液滴定生成的碘单质，测得共生成了 \\(0.025\\text{ mol}\\ \\mathrm{I_2}\\)。(1) 求原混合气体中 \\(\\mathrm{O_3}\\) 的体积分数；(2) 将反应后溢出的气体在标准状况下全部收集，其体积为多少升？","given":"V(总, STP)=2.24 L (0.10 mol)；n(I₂)=0.025 mol；反应 O₃ + 2I⁻ + 2H⁺ → I₂ + O₂ + H₂O","method":"根据 1 mol O₃ ↔ 1 mol I₂ 求出 n(O₃)，再由“1 mol O₃ 释放 1 mol O₂”判断溢出气体总物质的量根本不变！","principle":"O₃ 氧化 KI 气体分子数 1:1 守恒（1 mol O₃ 变成 1 mol O₂）。","steps":["(1) 原混合气体总物质的量：\\(n_{\\text{总}} = \\frac{2.24\\text{ L}}{22.4\\text{ L}\\cdot\\mathrm{mol^{-1}}} = 0.10\\text{ mol}\\)。","依据反应 \\(\\mathrm{2KI + H_2SO_4 + O_3 \\longrightarrow I_2 + O_2 + K_2SO_4 + H_2O}\\) 可知，\\(n(\\mathrm{O_3}) = n(\\mathrm{I_2}) = 0.025\\text{ mol}\\)。","故 \\(\\mathrm{O_3}\\) 的体积分数（等于物质的量分数）：\\(\\varphi(\\mathrm{O_3}) = \\frac{0.025}{0.10} \\times 100\\% = 25.0\\%\\)。","(2) 原混合气体中原有 \\(\\mathrm{O_2}\\) 为 \\(0.10 - 0.025 = 0.075\\text{ mol}\\)；反应中消耗的 \\(0.025\\text{ mol}\\ \\mathrm{O_3}\\) 恰好同时释放出 \\(0.025\\text{ mol}\\ \\mathrm{O_2}\\)，故反应后总 \\(\\mathrm{O_2}\\) 仍为 \\(0.075 + 0.025 = 0.10\\text{ mol}\\)，标况体积仍为 \\(2.24\\text{ L}\\)！"],"ans":"(1) \\(25.0\\%\\)；(2) \\(2.24\\text{ L}\\)。","markingPoints":["利用 1:1 关系算出 n(O₃)=0.025 mol 与体积分数 25.0%（2分）","指出 1 mol O₃ 反应放 1 mol O₂ 故溢出 O₂ 仍为 2.24 L（2分）"],"verification":"反应前后气体体积居然完全相等（\\(\\mathrm{O_3(g) \\to O_2(g)}\\)，化学计量均为 1）！","pitfall":"若认为 O₃ 全被吸收不放气体，就会误算出溢出体积为 1.68 L。"}],"cheatSheet":["O₃ 与 O₂ 为同素异形体；3O₂ —放电→ 2O₃（吸热，体积减小），2O₃ —Δ→ 3O₂。","检验臭氧：酸性淀粉—KI 试纸变蓝，计量记住 1 mol O₃ → 1 mol I₂ + 1 mol O₂（得 2e⁻）。","臭氧消毒三大优势：高效、广谱、无二次残留污染；Cl· 和 NO 会催化破坏平流层臭氧。"],"kbEntryIds":["kb-chem14-o3-ozone"],"quiz":{"q":"把黑色硫化铅(II)（\\(\\mathrm{PbS}\\)）粉末置于臭氧气流中会发生什么颜色变化？写出化学方程式。","given":"化上 p.342 臭氧极强氧化性","method":"利用臭氧将 −2 价 S 氧化至 +6 价白色 PbSO₄","principle":"O₃ 氧化性远强于 O₂，室温即可氧化 PbS。","steps":["黑色固体逐渐变成白色的硫酸铅(II)：\\(\\mathrm{PbS(s) + 2O_3(g) \\longrightarrow PbSO_4(s) + O_2(g)}\\)。"],"ans":"黑色固体变为白色；\\(\\mathrm{PbS(s) + 2O_3(g) \\longrightarrow PbSO_4(s) + O_2(g)}\\)"}},{"id":"14.3","t":"氧化物","anchor":{"pages":"化上 p.343–349","syllabus":"3.8.3 氧化物的两种分类法与 H₂O₂、Na₂O₂、KO₂ 性质","examScopes":["sem2_final","uec"],"examWeight":"P1 氧化物分类与 H₂O₂ 角色判断 + P2 Na₂O₂ 供氧及过碳酸钠探究","terms":"peroxide · superoxide · composite oxide · amphoteric oxide · neutral oxide","prerequisites":["化合价与氧化数计算规则（化上 Ch 8.2）","酸、碱与盐的复分解中和概念"],"goals":["依据表14-4 与表14-5 熟练按“氧的氧化数与组成”（普通、过氧、超氧、复合）和“酸碱性”（碱性、酸性、两性、中性）对氧化物分类。","掌握过氧化氢（H₂O₂）的结构、弱酸性、分解条件（碱性/光/金属氧化物加速）及在反应中既作氧化剂又作还原剂的实例（活动9–11）。","写出 Na₂O₂ 和 KO₂ 与 H₂O、CO₂ 反应的方程式，理解其在宇航、潜艇及消防“化学氧自救器”中的应用。"]},"concepts":[{"kind":"table","title":"氧化物双维度分类法（表14-4 & 表14-5，活动5–8）","pageRef":"化上 p.344–345","body":["**按氧的氧化数和组成分类（表14-4）**：① **普通氧化物**（O 为 \\(-2\\)，如 \\(\\mathrm{Na_2O, CO_2, Al_2O_3}\\)）；② **过氧化物**（O 为 \\(-1\\)，含过氧键 \\(\\mathrm{-O-O-}\\)，如 \\(\\mathrm{H_2O_2, Na_2O_2, BaO_2}\\)）；③ **超氧化物**（O 为 \\(-\\frac{1}{2}\\)，含超氧离子 \\(\\mathrm{O_2^-}\\)，如 \\(\\mathrm{KO_2}\\)）；④ **复合氧化物**（含不同氧化态同种金属，如 \\(\\mathrm{Fe_3O_4}\\)、\\(\\mathrm{Pb_3O_4}\\)）。","**按酸碱性分类（活动5–8）**：① **碱性氧化物**（能与酸生成盐和水，如 \\(\\mathrm{MgO, Fe_2O_3, CuO}\\)）；② **酸性氧化物**（能与碱生成盐和水，如 \\(\\mathrm{CO_2, SO_2}\\)）；③ **两性氧化物**（既溶酸又溶碱，如 \\(\\mathrm{Al_2O_3 + 6HCl \\to 2AlCl_3 + 3H_2O}\\)、\\(\\mathrm{Al_2O_3 + 2NaOH \\to 2NaAlO_2 + H_2O}\\)）；④ **中性氧化物**（既不与酸也不与碱反应，如 \\(\\mathrm{NO, CO}\\)）。"],"table":{"headers":["分类依据","类别","核心判据 / 特征","教材代表实例"],"rows":[["按氧的氧化数与组成","普通 / 过氧 / 超氧 / 复合","O 氧化数依次为 \\(-2\\) / \\(-1\\) / \\(-1/2\\) / 混合态","\\(\\mathrm{Na_2O}\\) / \\(\\mathrm{Na_2O_2}\\) / \\(\\mathrm{KO_2}\\) / \\(\\mathrm{Fe_3O_4, Pb_3O_4}\\)"],["按酸碱性（表14-5）","碱性 / 酸性 / 两性 / 中性","只溶酸 / 只溶碱 / 酸碱皆溶 / 皆不溶","\\(\\mathrm{Fe_2O_3}\\) / \\(\\mathrm{SO_2}\\) / \\(\\mathrm{Al_2O_3}\\) / \\(\\mathrm{NO, CO}\\)"]]},"takeaway":"注意 Na₂O₂ 与酸反应除生成盐和水外还放出 O₂，因此过氧化钠不属于碱性氧化物（它属于过氧化物）！"},{"kind":"experiment","title":"活动9–11：过氧化氢（H₂O₂）的双重氧化还原性与油画修复（表14-6）","pageRef":"化上 p.345–347","body":["**结构与物理性质（图14-12）**：纯 \\(\\mathrm{H_2O_2}\\) 为无色黏稠液体，分子间强氢键致沸点（158℃）远高于水；水溶液俗称双氧水，呈**弱酸性**，3% 溶液作温和消毒剂，30% 溶液常用于实验室；碱性溶液、见光、受热或金属氧化物皆会加速其分解（\\(\\mathrm{2H_2O_2 \\to 2H_2O + O_2\\uparrow}\\)），故须棕色瓶或塑料瓶阴凉保存。","**氧化性（遇还原剂，本身被还原为 \\(\\mathrm{H_2O}\\)）**：① **活动9**：浅绿色 \\(\\mathrm{FeSO_4}\\) 溶液加双氧水变棕黄色（\\(\\mathrm{2Fe^{2+} + H_2O_2 + 2H^+ \\to 2Fe^{3+} + 2H_2O}\\)）；② **活动10**：黑褐色 \\(\\mathrm{PbS}\\) 沉淀加双氧水氧化变回白色 \\(\\mathrm{PbSO_4}\\)（\\(\\mathrm{PbS + 4H_2O_2 \\to PbSO_4 + 4H_2O}\\)，解释了图14-11 含铅白颜料发黑油画“整旧如新”的化学原理！）。","**还原性（遇强氧化剂，本身被氧化放 \\(\\mathrm{O_2}\\)）**：**活动11**：酸性 \\(\\mathrm{KMnO_4}\\) 溶液紫色褪去并产生气泡（\\(\\mathrm{2MnO_4^- + 5H_2O_2 + 6H^+ \\to 2Mn^{2+} + 8H_2O + 5O_2\\uparrow}\\)）；\\(\\mathrm{Ag_2O + H_2O_2 \\to 2Ag + H_2O + O_2\\uparrow}\\)。","**制备**：实验室 \\(\\mathrm{BaO_2(s) + H_2SO_4(aq) \\to BaSO_4(s)\\downarrow + H_2O_2(aq)}\\)；工业电解硫酸得过二硫酸（\\(\\mathrm{H_2S_2O_8}\\)）再水解制取。"],"takeaway":"H₂O₂ 中 O 为 −1 价中间价态，遇强还原剂作氧化剂（变 H₂O 不放气，绿色无副产物），遇更强氧化剂（KMnO₄、O₃、Cl₂）则作还原剂放出 O₂！"},{"kind":"experiment","title":"活动12–13：过氧化钠（Na₂O₂）与超氧化钾（KO₂）供氧原理","pageRef":"化上 p.347–348","body":["**过氧化钠（\\(\\mathrm{Na_2O_2}\\)，淡黄色粉末，表14-7）**：① **活动12**：滴水放大量热产生能使带余烬木枝复燃的气体，所得溶液呈强碱性：\\(\\mathrm{2Na_2O_2(s) + 2H_2O(l) \\to 4NaOH(aq) + O_2(g)\\uparrow}\\)；② **活动13**：通入 \\(\\mathrm{CO_2}\\) 后白色粉末生成（\\(\\mathrm{Na_2CO_3}\\)）且右端逸出气体使带余烬木枝复燃：\\(\\mathrm{2Na_2O_2(s) + 2CO_2(g) \\to 2Na_2CO_3(s) + O_2(g)\\uparrow}\\)。广泛用于航天、潜艇和矿井救援。","**超氧化钾（\\(\\mathrm{KO_2}\\)，黄色晶体）**：钾在过量氧气中燃烧制得（\\(\\mathrm{K + O_2} \\xrightarrow{\\text{点燃}} \\mathrm{KO_2}\\)）；与水蒸气剧烈产氧：\\(\\mathrm{4KO_2(s) + 2H_2O(g) \\to 4KOH(s) + 3O_2(g)}\\)，生成的 \\(\\mathrm{KOH}\\) 进一步吸收呼出的 \\(\\mathrm{CO_2}\\)：\\(\\mathrm{KOH + CO_2 \\to KHCO_3}\\)，故称“化学氧自救器”，用于消防员与矿工面罩（图14-15）。"],"takeaway":"2Na₂O₂ + 2CO₂ → 2Na₂CO₃ + O₂ 中 Na₂O₂ 既是氧化剂又是还原剂（1 mol Na₂O₂ 反应仅转移 1 mol 电子，不是 2 mol！）。"}],"formulas":[{"title":"H₂O₂ 作氧化剂与还原剂的代表方程式","tex":"\\mathrm{PbS(s) + 4H_2O_2(aq) \\longrightarrow PbSO_4(s) + 4H_2O(l)},\\qquad \\mathrm{2MnO_4^-(aq) + 5H_2O_2(aq) + 6H^+(aq) \\longrightarrow 2Mn^{2+}(aq) + 8H_2O(l) + 5O_2(g)\\uparrow}","plain":"PbS + 4H2O2 -> PbSO4 + 4H2O; 2MnO4- + 5H2O2 + 6H+ -> 2Mn^2+ + 8H2O + 5O2↑","conditions":"前者体现氧化性（修复发黑油画）；后者在稀硫酸酸化下体现还原性","pageRef":"化上 p.346","note":"KMnO₄ 不可用盐酸酸化（HCl 会被 KMnO₄ 氧化生成 Cl₂）。"},{"title":"Na₂O₂ 与 KO₂ 供氧及固体质量差规律","tex":"\\mathrm{2Na_2O_2(s) + 2CO_2(g) \\longrightarrow 2Na_2CO_3(s) + O_2(g)},\\qquad \\mathrm{4KO_2(s) + 2H_2O(g) \\longrightarrow 4KOH(s) + 3O_2(g)}","plain":"2Na2O2 + 2CO2 -> 2Na2CO3 + O2; 4KO2 + 2H2O -> 4KOH + 3O2","conditions":"1 mol CO₂ 与足量 Na₂O₂ 反应固体增重 28 g；1 mol H₂O 反应增重 2 g","pageRef":"化上 p.348","note":"同质量下，KO₂（M=71）释放 O₂ 的质量多于 Na₂O₂（M=78）。"}],"pitfalls":[{"title":"误以为 1 mol Na₂O₂ 参与反应转移 2 mol 电子","wrong":"“\\(\\mathrm{1\\ mol\\ Na_2O_2}\\) 与足量 \\(\\mathrm{CO_2}\\) 或 \\(\\mathrm{H_2O}\\) 完全反应时，电子转移总数为 \\(2N_A\\)。”","diagnosis":"\\(\\mathrm{Na_2O_2}\\) 中两个 −1 价氧原子发生歧化：一半升至 0 价进入 \\(\\mathrm{O_2}\\)，另一半降至 −2 价进入 \\(\\mathrm{Na_2CO_3/NaOH}\\)。","right":"在 \\(\\mathrm{2Na_2O_2 + 2CO_2 \\to 2Na_2CO_3 + O_2}\\) 中，每 \\(2\\text{ mol }\\mathrm{Na_2O_2}\\) 只生成 \\(1\\text{ mol }\\mathrm{O_2}\\)，转移 \\(2\\text{ mol}\\) 电子，即每 **1 mol Na₂O₂ 转移 1 mol 电子（\\(N_A\\)）**！","checkRule":"看到 Na₂O₂ 与 H₂O/CO₂ 计算电子转移，牢记 1:1（1 mol Na₂O₂ ↔ 1 mol e⁻ ↔ 0.5 mol O₂）。"},{"title":"错把过氧化钠当成“碱性氧化物”或把 NO 当成“酸性氧化物”","wrong":"“\\(\\mathrm{Na_2O_2}\\) 能与盐酸反应生成 \\(\\mathrm{NaCl}\\) 和 \\(\\mathrm{H_2O}\\)，属于碱性氧化物；\\(\\mathrm{NO}\\) 是非金属氧化物，属于酸性氧化物。”","diagnosis":"碱性氧化物与酸反应只能生成盐和水（不能同时放出 \\(\\mathrm{O_2}\\)）；非金属氧化物不一定都是酸性氧化物。","right":"\\(\\mathrm{Na_2O_2}\\) 与酸反应生成盐、水并放出 \\(\\mathrm{O_2}\\)，属于**过氧化物**；\\(\\mathrm{NO}\\) 和 \\(\\mathrm{CO}\\) 既不与酸也不与碱成盐，属于**中性氧化物**。","checkRule":"定义检验：酸碱氧化物反应前后化合价不得变化且只生成盐和水。"}],"examples":[{"label":"例 14.3.1","tier":"L3","tierLabel":"L3 预试拔高","title":"思考题 14c 第2、3题：过碳酸钠稳定性与 CO₂ 通过过氧化钠固体增重","prompt":"(1) 工业上常将液态 \\(\\mathrm{H_2O_2}\\) 转化为固态过碳酸钠晶体（\\(\\mathrm{2Na_2CO_3\\cdot 3H_2O_2}\\)），它兼具 \\(\\mathrm{Na_2CO_3}\\) 和 \\(\\mathrm{H_2O_2}\\) 的双重性质。下列物质中，**不会**使过碳酸钠晶体失效的是哪一项？A. \\(\\mathrm{MnO_2}\\)　B. \\(\\mathrm{H_2S}\\)　C. 稀盐酸　D. \\(\\mathrm{NaHCO_3}\\)；(2) 把 \\(4.4\\text{ g}\\ \\mathrm{CO_2}\\) 气体通过足量的过氧化钠固体后，固体质量增加了多少克？","clues":"(1) 分别排查各物质是否与 Na₂CO₃（酸反应）或 H₂O₂（催化剂/还原剂）反应；(2) 利用 2Na₂O₂ + 2CO₂ → 2Na₂CO₃ + O₂ 差量计算！","strategy":"(1) 逐项检测碳酸根与双氧水的反应；(2) 用“1 mol CO₂ 增重 28 g”或差量比例求解。","given":"过碳酸钠 2Na₂CO₃·3H₂O₂；m(CO₂) = 4.4 g (0.10 mol)","principle":"H₂O₂ 催化分解及还原消耗；碳酸盐与酸反应；质量差量法。","steps":["(1) A 项 \\(\\mathrm{MnO_2}\\) 催化 \\(\\mathrm{H_2O_2}\\) 分解使其失效；B 项 \\(\\mathrm{H_2S}\\) 强还原性与 \\(\\mathrm{H_2O_2}\\) 氧化还原而失效；C 项稀盐酸既与 \\(\\mathrm{Na_2CO_3}\\) 反应放 \\(\\mathrm{CO_2}\\) 又加快反应失效；D 项 \\(\\mathrm{NaHCO_3}\\) 既不与 \\(\\mathrm{Na_2CO_3}\\) 反应又不与 \\(\\mathrm{H_2O_2}\\) 反应，不会使其失效，故选 **D**。","(2) \\(n(\\mathrm{CO_2}) = \\frac{4.4\\text{ g}}{44\\text{ g}\\cdot\\mathrm{mol^{-1}}} = 0.10\\text{ mol}\\)。","由 \\(\\mathrm{2Na_2O_2 + 2CO_2 \\longrightarrow 2Na_2CO_3 + O_2}\\)，每消耗 \\(2\\text{ mol }\\mathrm{CO_2}\\)，固体从 \\(2\\mathrm{Na_2O_2}(156\\text{ g})\\) 变为 \\(2\\mathrm{Na_2CO_3}(212\\text{ g})\\)，增重 \\(212 - 156 = 56\\text{ g}\\)。","故 \\(0.10\\text{ mol }\\mathrm{CO_2}\\) 反应后固体增重：\\(\\Delta m = 0.10 \\times \\frac{56}{2} = 2.8\\text{ g}\\)。"],"answer":"(1) D（\\(\\mathrm{NaHCO_3}\\)）；(2) 固体质量增加了 \\(2.8\\text{ g}\\)。","markingPoints":["准确排除 MnO₂、H₂S、HCl 并选出 NaHCO₃（2分）","利用 2Na₂O₂→2Na₂CO₃ 差量算出固体增重 2.8 g（2分）"],"verification":"质量守恒验证：吸收 \\(4.4\\text{ g }\\mathrm{CO_2}\\)，放出 \\(0.050\\text{ mol }\\mathrm{O_2}\\)（\\(1.6\\text{ g}\\)），固体净增重 \\(4.4 - 1.6 = 2.8\\text{ g}\\)！","pitfall":"第(2)题容易错将增重答成吸收的 CO₂ 质量 4.4 g，忘记了反应同时放出了氧气。"},{"label":"例 14.3.2","tier":"L4","tierLabel":"L4 统考压轴","title":"CO 与 H₂ 混合气完全燃烧后通入足量 Na₂O₂ 的惊人增重规律","prompt":"将 \\(5.6\\text{ g}\\) 由一氧化碳（\\(\\mathrm{CO}\\)）和氢气（\\(\\mathrm{H_2}\\)）组成的混合气体在足量氧气中充分燃烧，然后将燃烧后的全部混合产物（\\(\\mathrm{CO_2}\\) 与 \\(\\mathrm{H_2O(g)}\\)）通过盛有足量 \\(\\mathrm{Na_2O_2}\\) 固体的干燥管，充分吸收后测得干燥管增重了多少克？请给出数学证明。","clues":"写下燃烧式 CO+½O₂→CO₂、H₂+½O₂→H₂O，再把它们分别与 2Na₂O₂+2CO₂→2Na₂CO₃+O₂、2Na₂O₂+2H₂O→4NaOH+O₂ 相加！","strategy":"消去中间体 CO₂、H₂O 与 O₂，看 Na₂O₂ 固体最终净吸收了什么物质。","given":"m(CO + H₂) = 5.6 g","principle":"反应耦合总加和（Na₂O₂ + CO = Na₂CO₃；Na₂O₂ + H₂ = 2NaOH）。","steps":["对 \\(\\mathrm{CO}\\)：将 \\(\\mathrm{CO + \\frac{1}{2}O_2 \\to CO_2}\\) 与 \\(\\mathrm{Na_2O_2 + CO_2 \\to Na_2CO_3 + \\frac{1}{2}O_2}\\) 相加，净反应相当于：\\(\\mathrm{Na_2O_2 + CO \\longrightarrow Na_2CO_3}\\)。","对 \\(\\mathrm{H_2}\\)：将 \\(\\mathrm{H_2 + \\frac{1}{2}O_2 \\to H_2O}\\) 与 \\(\\mathrm{Na_2O_2 + H_2O \\to 2NaOH + \\frac{1}{2}O_2}\\) 相加，净反应相当于：\\(\\mathrm{Na_2O_2 + H_2 \\longrightarrow 2NaOH}\\)。","由此可见，无论原 \\(\\mathrm{CO}\\) 与 \\(\\mathrm{H_2}\\) 的比例如何，充分燃烧后经足量 \\(\\mathrm{Na_2O_2}\\) 吸收，净效果等效于原 \\(\\mathrm{CO}\\) 和 \\(\\mathrm{H_2}\\) 直接“全部并入”过氧化钠固体中（消耗的 \\(\\mathrm{O_2}\\) 与释放的 \\(\\mathrm{O_2}\\) 恰好相等）！","因此干燥管增加的质量**恰好等于原混合气体质量**，即 \\(\\Delta m = 5.6\\text{ g}\\)。"],"answer":"干燥管增重 **5.6 g**（恰好等于原 CO 与 H₂ 混合气总质量）。","markingPoints":["写出两组反应净相加方程式（2分）","说明耗氧与放氧等量抵消，固体增重等于原混合气质量 5.6 g（2分）"],"verification":"特例检验：设全是 \\(0.20\\text{ mol CO}\\)（\\(5.6\\text{ g}\\)），烧成 \\(0.20\\text{ mol }\\mathrm{CO_2}\\)，再与 \\(\\mathrm{Na_2O_2}\\) 反应增重 \\(0.20 \\times 28 = 5.6\\text{ g}\\)；设全是 \\(2.8\\text{ mol }\\mathrm{H_2}\\)（\\(5.6\\text{ g}\\)），烧成 \\(2.8\\text{ mol }\\mathrm{H_2O}\\)，增重 \\(2.8 \\times 2 = 5.6\\text{ g}\\)！","pitfall":"若试图设 x, y 联立方程硬算，因未知比例会发现少一个方程而卡壳；用耦合加合法一秒破题。"}],"practice":[{"id":"chem14-14.3-q1","tier":"L1","tierLabel":"L1 基础","examStyle":"P1 选择","q":"下列物质按照“碱性氧化物、两性氧化物、过氧化物、中性氧化物”顺序排列正确的一组是（　）。","options":["A. \\(\\mathrm{Fe_2O_3,\\ Al_2O_3,\\ Na_2O_2,\\ CO}\\)","B. \\(\\mathrm{Na_2O_2,\\ Al_2O_3,\\ H_2O_2,\\ NO}\\)","C. \\(\\mathrm{CuO,\\ Fe_3O_4,\\ KO_2,\\ CO_2}\\)","D. \\(\\mathrm{MgO,\\ SiO_2,\\ BaO_2,\\ NO}\\)"],"correctOption":"A","given":"表14-4 与表14-5 氧化物分类","method":"逐项核对四个类别归属","principle":"Na₂O₂ 是过氧化物；Fe₃O₄ 是复合氧化物；CO₂ 是酸性氧化物。","steps":["A 项 \\(\\mathrm{Fe_2O_3}\\)（碱性）、\\(\\mathrm{Al_2O_3}\\)（两性）、\\(\\mathrm{Na_2O_2}\\)（过氧化物）、\\(\\mathrm{CO}\\)（中性）全部准确。"],"ans":"A","markingPoints":["掌握氧化物双维度分类标准"],"verification":"对照化上 p.344–345。","pitfall":"误把 Na₂O₂ 归入碱性氧化物或把 Fe₃O₄ 当两性氧化物。"},{"id":"chem14-14.3-q2","tier":"L2","tierLabel":"L2 期末","examStyle":"P1 选择","q":"下列关于过氧化氢（\\(\\mathrm{H_2O_2}\\)）的说法中，**错误**的是（　）。","options":["A. 其水溶液俗称双氧水，呈弱酸性，3% 溶液可用作伤口消毒剂","B. 过氧化氢在碱性溶液、见光或遇到金属氧化物时分解加速","C. 过氧化氢中氧元素为 −1 价，在化学反应中既可作氧化剂也可作还原剂","D. 过氧化氢是离子化合物，常温下比纯水更易挥发"],"correctOption":"D","given":"化上 p.345–346 及思考题 14c 第1题","method":"判断 H₂O₂ 的化学键类型与氢键导致的沸点升高","principle":"H₂O₂ 为共价分子化合物，因分子间强氢键沸点（158℃）高于水，挥发性比水小。","steps":["D 错：\\(\\mathrm{H_2O_2}\\) 是由分子构成的**共价化合物**（不是离子化合物），且挥发性比水**小**（bp 158℃ > 100℃）。"],"ans":"D","markingPoints":["明确 H₂O₂ 是共价分子且沸点高难挥发"],"verification":"对照化上 p.345 原文及 p.348 思考题 14c 第1题。","pitfall":"受 Na₂O₂ 是离子化合物的影响误以为 H₂O₂ 也是离子化合物。"},{"id":"chem14-14.3-q3","tier":"L3","tierLabel":"L3 预试","examStyle":"P2 简答","q":"油画颜料中的铅白主要成分为 \\(\\mathrm{2Pb(OH)_2\\cdot PbCO_3}\\)，长期暴露在含微量硫化氢的空气中会变黑。将 \\(3\\%\\) 双氧水涂在变黑的油画表面，油画即可恢复白色。(1) 解释油画变黑以及双氧水能使油画恢复白色的化学原理，并写出相关恢复反应方程式；(2) 若实验室将双氧水滴入酸化的高锰酸钾溶液中，现象如何？此时双氧水表现什么性质？","given":"化上 p.343 感知生活（图14-11）及 p.346 活动10–11","method":"PbS(黑) + 4H₂O₂ → PbSO₄(白) + 4H₂O；KMnO₄(H⁺) + H₂O₂ 褪色放 O₂","principle":"H₂O₂ 的氧化还原两性。","steps":["(1) 空气中微量 \\(\\mathrm{H_2S}\\) 与铅白作用生成黑色的硫化铅(II)（\\(\\mathrm{PbS}\\)）导致油画发黑；涂抹双氧水后，\\(\\mathrm{H_2O_2}\\) 表现**氧化性**将黑色 \\(\\mathrm{PbS}\\) 氧化为白色的硫酸铅(II)（\\(\\mathrm{PbSO_4}\\)）使油画复白：\\(\\mathrm{PbS(s) + 4H_2O_2(aq) \\longrightarrow PbSO_4(s) + 4H_2O(l)}\\)。","(2) 现象：酸性高锰酸钾溶液的**紫红色褪去**，并有**无色气泡（\\(\\mathrm{O_2}\\)）产生**；此时双氧水表现**还原性**。"],"ans":"(1) 生成黑色 PbS 而变黑，H₂O₂ 将其氧化为白色 PbSO₄（方程式见步骤）；(2) 紫红色褪去并冒气泡，表现还原性。","markingPoints":["指出黑色 PbS 与白色 PbSO₄ 转化并写对配平方程式（2分）","描述酸性 KMnO₄ 褪色放气泡及 H₂O₂ 还原性（2分）"],"verification":"对照化上 p.343、p.346 核验。","pitfall":"修复方程式系数常把 4H₂O₂ 误写为 2H₂O₂（S 从 −2 到 +6 共升 8 价，需 4 个 H₂O₂ 得 8 个电子）。"},{"id":"chem14-14.3-q4","tier":"L4","tierLabel":"L4 统考压轴","examStyle":"P2 综合计算","q":"潜艇与消防面罩常采用过氧化钠（\\(\\mathrm{Na_2O_2}\\)）或超氧化钾（\\(\\mathrm{KO_2}\\)）作供氧再生剂。已知 \\(1\\) 摩尔人体呼出的 \\(\\mathrm{CO_2}\\) 分别与足量 \\(\\mathrm{Na_2O_2}\\) 及 \\(\\mathrm{KO_2}\\) 反应如下：\\(\\mathrm{2Na_2O_2 + 2CO_2 \\longrightarrow 2Na_2CO_3 + O_2}\\)；\\(\\mathrm{4KO_2 + 2CO_2 \\longrightarrow 2K_2CO_3 + 3O_2}\\)。(1) 若要为呼吸系统提供 \\(3.0\\text{ mol}\\ \\mathrm{O_2}\\)，分别至少需要消耗多少克 \\(\\mathrm{Na_2O_2}\\) 和多少克 \\(\\mathrm{KO_2}\\)？（\\(\\mathrm{Na}=23,\\ \\mathrm{K}=39,\\ \\mathrm{O}=16\\)）(2) 结合计算结果，说明消防员“化学氧自救器”优选 \\(\\mathrm{KO_2}\\) 而非 \\(\\mathrm{Na_2O_2}\\) 的两大原因。","given":"目标 n(O₂) = 3.0 mol；M(Na₂O₂)=78, M(KO₂)=71 g/mol","method":"按两方程式比例分别计算所需固体质量，再从轻量化与耗材效率对比","principle":"化学计量比例换算与单位质量供氧能力比较。","steps":["(1) 对 \\(\\mathrm{Na_2O_2}\\)：\\(n(\\mathrm{Na_2O_2}) = 2 \\times 3.0 = 6.0\\text{ mol}\\)，\\(m(\\mathrm{Na_2O_2}) = 6.0 \\times 78 = 468\\text{ g}\\)。","对 \\(\\mathrm{KO_2}\\)：由 \\(\\mathrm{4KO_2 \\sim 3O_2}\\)，\\(n(\\mathrm{KO_2}) = \\frac{4}{3} \\times 3.0 = 4.0\\text{ mol}\\)，\\(m(\\mathrm{KO_2}) = 4.0 \\times 71 = 284\\text{ g}\\)。","(2) 两大原因：① **单位质量供氧效率高得多**（产等量 \\(\\mathrm{O_2}\\) 时 \\(\\mathrm{KO_2}\\) 质量比 \\(\\mathrm{Na_2O_2}\\) 轻近 \\(40\\%\\)，便于单兵背负）；② \\(\\mathrm{KO_2}\\) 与人体呼出的水蒸气反应生成更多 \\(\\mathrm{O_2}\\)（\\(\\mathrm{4KO_2+2H_2O \\to 4KOH+3O_2}\\)），且生成的 \\(\\mathrm{KOH}\\) 能同时吸收呼出的 \\(\\mathrm{CO_2}\\)（\\(\\mathrm{KOH+CO_2\\to KHCO_3}\\)）实现呼气完全循环。"],"ans":"(1) 需 \\(\\mathrm{Na_2O_2}\\ 468\\text{ g}\\)，需 \\(\\mathrm{KO_2}\\ 284\\text{ g}\\)；(2) 同等供氧量自重更轻，且产氧比更高兼能循环吸收水汽和 CO₂。","markingPoints":["正确算出 Na₂O₂ 468 g（1.5分）和 KO₂ 284 g（1.5分）","从供氧质量比及水汽/CO₂ 循环机理说明原因（2分）"],"verification":"单位摩尔产氧：1 mol Na₂O₂ 产 0.5 mol O₂；1 mol KO₂ 产 0.75 mol O₂（且 KO₂ 摩尔质量还更小！）。","pitfall":"误将 KO₂ 方程式系数算成 2KO₂ → 1O₂（氧原子和电子都不守恒：4×(−1/2) → 4×(−2) + 3×0，失6e⁻、得6e⁻）。"}],"cheatSheet":["氧化物分类：普通(O: −2)、过氧(−1: H₂O₂, Na₂O₂, BaO₂)、超氧(−1/2: KO₂)、复合(Fe₃O₄, Pb₃O₄)；酸碱分类：碱/酸/两性(Al₂O₃)/中性(NO, CO)。","H₂O₂ 两性：氧化 Fe²⁺ 和黑色 PbS（变白 PbSO₄ 修复油画）；遇 KMnO₄(H⁺) 作还原剂放 O₂。","1 mol Na₂O₂ 与 CO₂/H₂O 反应转移 1 mol e⁻ 并放 0.5 mol O₂；CO/H₂ 燃烧后过 Na₂O₂ 增重恰好等于原 CO/H₂ 质量。"],"kbEntryIds":["kb-chem14-oxides-class"],"quiz":{"q":"为什么 \\(\\mathrm{Al_2O_3}\\) 被称为两性氧化物，而 \\(\\mathrm{Fe_2O_3}\\) 被称为碱性氧化物？写出 \\(\\mathrm{Al_2O_3}\\) 与氢氧化钠溶液反应的化学方程式。","given":"活动5–8（化上 p.344–345 表14-5）","method":"依据金属氧化物能否与强碱反应生成盐和水判别","principle":"既能与酸又可与碱反应只生成盐和水的氧化物为两性氧化物。","steps":["\\(\\mathrm{Fe_2O_3}\\) 只溶于酸而不溶于 \\(\\mathrm{NaOH}\\) 溶液，属碱性氧化物；\\(\\mathrm{Al_2O_3}\\) 既能与盐酸反应生成 \\(\\mathrm{AlCl_3}\\) 和水，又能与 \\(\\mathrm{NaOH}\\) 溶液反应生成偏铝酸钠和水。","方程式：\\(\\mathrm{Al_2O_3(s) + 2NaOH(aq) \\longrightarrow 2NaAlO_2(aq) + H_2O(l)}\\)。"],"ans":"Al₂O₃ 酸碱皆溶生成盐和水，Fe₂O₃ 只溶酸；\\(\\mathrm{Al_2O_3 + 2NaOH \\longrightarrow 2NaAlO_2 + H_2O}\\)"}},{"id":"14.4","t":"硫","anchor":{"pages":"化上 p.349–353","syllabus":"3.8.4 硫的同素异形体、硫的氧化性与还原性及硫单质制取","examScopes":["sem2_final","uec"],"examWeight":"P1 硫与变价金属产物（FeS、Cu₂S）及汞处理 + P2 硫转化路径推断","terms":"rhombic sulphur · monoclinic sulphur · plastic sulphur · sublimed sulphur · pyrite","prerequisites":["同素异形体与分子晶体溶解性","氧化还原反应电子转移分析（化上 Ch 8）"],"goals":["了解硫在自然界中的存在形式（游离态菱形硫/单斜硫/弹性硫，以及黄铁矿、黄铜矿、石膏、芒硝）及硫物理性质。","掌握活动14 硫粉与铁粉反应现象及硫与 Fe、Cu、Hg、Ag、C、H₂、F₂、浓硫酸、浓硝酸反应的双重氧化还原性。","理解硫的炼制（升华硫华与黄铁矿有限空气碳还原炼硫）以及热碱洗去试管残留硫的歧化反应。"]},"concepts":[{"kind":"definition","title":"硫的存在、同素异形体与物理性质","pageRef":"化上 p.349–350","body":["**存在形式**：硫在自然界既有火山口的游离态单质——**菱形硫（斜方硫）**、**单斜硫**和**弹性硫**（三者互为同素异形体），也有化合态的金属硫化物（黄铁矿 \\(\\mathrm{FeS_2}\\)、黄铜矿 \\(\\mathrm{CuFeS_2}\\)、方铅矿 \\(\\mathrm{PbS}\\)、闪锌矿 \\(\\mathrm{ZnS}\\)）和硫酸盐（石膏 \\(\\mathrm{CaSO_4\\cdot 2H_2O}\\)、芒硝 \\(\\mathrm{Na_2SO_4\\cdot 10H_2O}\\)）。","**物理性质（图14-19）**：淡黄色脆性固体，不传热导电（电的优良绝缘体），**不溶于水**，微溶于酒精，**易溶于二硫化碳（\\(\\mathrm{CS_2}\\)）**。"],"takeaway":"清洗试管壁附着的硫单质，物理方法用 CS₂ 溶解，化学方法用热 NaOH 溶液歧化清洗。"},{"kind":"experiment","title":"活动14 与 硫的氧化还原两性（0 价居中）","pageRef":"化上 p.350–351","body":["**弱氧化性（表现氧化性，0 → −2，活动14 图14-20）**：用灼热玻璃棒触及石棉网上铁粉（稍过量）与硫粉混合物一端，移开玻璃棒后反应**自行放出热量继续红热蔓延**，最终生成黑色硫化亚铁：\\(\\mathrm{Fe(s) + S(s)} \\xrightarrow{\\Delta} \\mathrm{FeS(s)}\\)。同理：\\(\\mathrm{2Cu(s) + S(s)} \\xrightarrow{\\text{高温}} \\mathrm{Cu_2S(s)}\\)（生成 +1 价硫化亚铜！）、\\(\\mathrm{Hg(l) + S(s) \\longrightarrow HgS(s)}\\)（常温化合，故实验室常撒硫粉覆盖洒落水银以消除汞蒸气毒害！）、\\(\\mathrm{2Ag + S \\to Ag_2S}\\)（银器发黑变暗）、\\(\\mathrm{H_2 + S \\rightleftharpoons H_2S}\\)、\\(\\mathrm{C + 2S} \\xrightarrow{\\Delta} \\mathrm{CS_2}\\)。","**还原性（遇强氧化剂，0 → +4 或 +6）**：① \\(\\mathrm{S + O_2} \\xrightarrow{\\text{点燃}} \\mathrm{SO_2}\\)；② \\(\\mathrm{S + 3F_2 \\longrightarrow SF_6}\\)；③ \\(\\mathrm{S + 2H_2SO_4(\\text{浓})} \\xrightarrow{\\Delta} \\mathrm{3SO_2\\uparrow + 2H_2O}\\)；④ \\(\\mathrm{S + 6HNO_3(\\text{浓}) \\longrightarrow H_2SO_4 + 6NO_2\\uparrow + 2H_2O}\\)。","**自身歧化（热碱洗硫）**：\\(\\mathrm{3S(s) + 6NaOH(aq)} \\xrightarrow{\\Delta} \\mathrm{2Na_2S(aq) + Na_2SO_3(aq) + 3H_2O(l)}\\)。"],"takeaway":"氧化性比较必记结论：Cl₂ 与 Fe/Cu 加热生成高价 FeCl₃/CuCl₂，而 S 氧化性较弱，与 Fe/Cu 加热仅生成低价 FeS/Cu₂S！"},{"kind":"mechanism","title":"硫单质的工业制取与主要用途","pageRef":"化上 p.351–352","body":["**天然硫矿熔滤与蒸馏**：隔绝空气加热天然硫矿使其熔化并与砂石分离；进一步蒸馏使硫蒸汽冷却成微细结晶粉末，称为**硫华（sublimed sulphur）**。","**黄铁矿有限空气碳还原法**：将 \\(\\mathrm{FeS_2}\\) 与焦炭在炼硫炉有限空气中高温燃烧：\\(\\mathrm{3FeS_2(s) + 12C(s) + 8O_2(g)} \\xrightarrow{\\text{高温}} \\mathrm{Fe_3O_4(s) + 12CO(g) + 6S(l)}\\)。","**用途**：最主要用途是**制造硫酸（\\(\\mathrm{H_2SO_4}\\)）**，其次用于橡胶硫化（增强弹性耐磨，图14-22）、黑火药、火柴、造纸、染料、农药与皮肤病药膏/硫黄温泉。"],"takeaway":"活动14 中若“在空气中”加热硫粉与铁粉，除观察到红热变黑（FeS）外，还会见到少量淡蓝色火焰和刺激性气味（部分硫与空气中氧气生成 SO₂，思考题 14d 第3题）。"}],"formulas":[{"title":"硫与变价金属（Fe、Cu、Hg）及热碱反应的经典方程式","tex":"\\mathrm{Fe(s) + S(s)} \\xrightarrow{\\Delta} \\mathrm{FeS(s)},\\qquad \\mathrm{2Cu(s) + S(s)} \\xrightarrow{\\text{高温}} \\mathrm{Cu_2S(s)},\\qquad \\mathrm{3S(s) + 6NaOH(aq)} \\xrightarrow{\\Delta} \\mathrm{2Na_2S(aq) + Na_2SO_3(aq) + 3H_2O(l)}","plain":"Fe + S --Δ--> FeS; 2Cu + S --高温--> Cu2S; 3S + 6NaOH --Δ--> 2Na2S + Na2SO3 + 3H2O","conditions":"硫的氧化性弱于 Cl₂，故生成 Fe(+2)、Cu(+1)","pageRef":"化上 p.351","note":"对比：热碱洗硫中 S 既是氧化剂（4份→S²⁻）又是还原剂（2份→SO₃²⁻），还原产物与氧化产物物质的量之比为 2:1！"},{"title":"硫与浓硫酸、浓硝酸共热的还原性反应","tex":"\\mathrm{S(s) + 2H_2SO_4(aq,\\text{浓})} \\xrightarrow{\\Delta} \\mathrm{3SO_2(g)\\uparrow + 2H_2O(l)},\\qquad \\mathrm{S(s) + 6HNO_3(aq,\\text{浓}) \\longrightarrow H_2SO_4(aq) + 6NO_2(g)\\uparrow + 2H_2O(l)}","plain":"S + 2H2SO4(浓) --Δ--> 3SO2 + 2H2O; S + 6HNO3(浓) -> H2SO4 + 6NO2 + 2H2O","conditions":"浓硫酸将 0 价硫归中至 +4 价 SO₂；浓硝酸将 0 价硫彻底氧化至 +6 价 H₂SO₄","pageRef":"化上 p.351","note":"注意第一条为归中反应（0 与 +6 归中到 +4），转移电子 4e⁻（不是 6e⁻）。"}],"pitfalls":[{"title":"错把硫与铁、铜的产物写成高价态 Fe₂S₃ 和 CuS","wrong":"“\\(\\mathrm{2Fe + 3S} \\xrightarrow{\\Delta} \\mathrm{Fe_2S_3}\\)；\\(\\mathrm{Cu + S} \\xrightarrow{\\Delta} \\mathrm{CuS}\\)。”","diagnosis":"单质硫的氧化性比 \\(\\mathrm{Cl_2}\\) 和 \\(\\mathrm{O_2}\\) 弱得多，无法在直接化合中把 Fe、Cu 氧化至最高价（且 \\(\\mathrm{Fe^{3+}}\\) 与 \\(\\mathrm{S^{2-}}\\) 在水溶液中还会双水解或氧化还原）。","right":"硫与铁、铜直接加热化合，产物必定是低价硫化物：**\\(\\mathrm{FeS}\\)（+2 价）和 \\(\\mathrm{Cu_2S}\\)（+1 价）**。","checkRule":"遇变价金属 Fe、Cu：遇 \\(\\mathrm{Cl_2}\\) 升最高价（\\(\\mathrm{FeCl_3, CuCl_2}\\)），遇 \\(\\mathrm{S}\\) 停低价（\\(\\mathrm{FeS, Cu_2S}\\)）！"},{"title":"空气中加热 Fe+S 混合物忽视部分硫燃烧","wrong":"“把硫粉和铁粉放在石棉网上加热只生成黑色 FeS，无任何气味。”","diagnosis":"若在敞口空气中加热，熔化气化的少量硫会与空气中氧气接触燃烧。","right":"在空气中加热会同时观察到**淡蓝色火焰及刺激性 \\(\\mathrm{SO_2}\\) 气味**，以及混合物呈红热放热变为黑色 \\(\\mathrm{FeS}\\) 固体（教材思考题 14d 第3题）。","checkRule":"开放空气做 Fe+S 反应务必防硫氧化损耗与通风处理。"}],"examples":[{"label":"例 14.4.1","tier":"L2","tierLabel":"L2 校内期末","title":"单质连续转化推导（思考题 14d 第2题）","prompt":"某元素单质按下列路径可全部实现直接一步转化：\\(\\text{单质} \\xrightarrow{+\\mathrm{O_2}} \\text{氧化物} \\xrightarrow{+\\mathrm{H_2O}} \\text{酸或碱} \\xrightarrow{+\\mathrm{NaOH}\\text{或}\\mathrm{HCl}} \\text{盐}\\)。在**硅、硫、铜、铁**四种单质中，符合该连续转化关系的是哪一种？请依次写出每一步转化对应的化学方程式。","clues":"分别检验 SiO₂、CuO、Fe₃O₄/Fe₂O₃ 能否直接与水一步反应生成相应的酸或碱！","strategy":"利用氧化物水溶性与水化反应筛选唯一符合条件的元素（硫）。","given":"四种候选：Si、S、Cu、Fe","principle":"二氧化硅、氧化铜、铁的氧化物皆不溶于水且不与水直接化合；唯有 SO₂ 溶于水生成亚硫酸。","steps":["排查：硅燃烧生成 \\(\\mathrm{SiO_2}\\) 不溶于水也不与水反应；铁在氧气中燃烧得 \\(\\mathrm{Fe_3O_4}\\)、铜加热得 \\(\\mathrm{CuO}\\)，两者均难溶于水且不与水直接化合生成碱。","唯有**硫（S）**完全满足连续一步转化：","① \\(\\mathrm{S(s) + O_2(g)} \\xrightarrow{\\text{点燃}} \\mathrm{SO_2(g)}\\)；","② \\(\\mathrm{SO_2(g) + H_2O(l) \\rightleftharpoons H_2SO_3(aq)}\\)；","③ \\(\\mathrm{H_2SO_3(aq) + 2NaOH(aq) \\longrightarrow Na_2SO_3(aq) + 2H_2O(l)}\\)（或生成 \\(\\mathrm{NaHSO_3}\\)）。"],"answer":"符合条件的是**硫（S）**，方程式见步骤。","markingPoints":["排除 Si、Cu、Fe 并锁定硫（1分）","正确写出三步连续转化方程式（3分）"],"verification":"对照化上 p.352 思考题 14d 第2题（答案 B）。","pitfall":"容易误以为 Fe₂O₃ 或 CuO 能与水化合生成碱，记住除 K、Na、Ba、Ca 外绝大多数金属氧化物都不与水直接化合。"},{"label":"例 14.4.2","tier":"L3","tierLabel":"L3 预试拔高","title":"活动14 铁粉过量反应产物与稀盐酸检验设计","prompt":"按教材活动14 将铁粉（稍过量）与硫粉混合均匀堆成条状，用灼热玻璃棒触发反应至放热完毕并冷却得到黑色固体。(1) 为什么实验中常采用“铁粉稍过量”的投料比？(2) 若某同学未看到过量铁粉，欲设计实验证明产物中既有 \\(\\mathrm{FeS}\\) 又有未反应的单质 \\(\\mathrm{Fe}\\)（假设硫已耗尽），只需加入足量稀盐酸并观察气味与收集气体检验，请写出两个反应式并说明如何鉴定两种气体成分。","clues":"FeS + 2HCl → FeCl₂ + H₂S↑（臭鸡蛋气味/醋酸铅试纸变黑）；Fe + 2HCl → FeCl₂ + H₂↑（爆鸣声）！","strategy":"解释铁过量防硫在空气燃烧或保 Fe 充分反应；用醋酸铅/CuSO₄ 除尽 H₂S 后再点燃气体验证 H₂。","given":"产物 FeS + 过量 Fe，加入足量稀 HCl","principle":"FeS 与非氧化性酸复分解放 H₂S；过量 Fe 置换放 H₂。","steps":["(1) 铁粉稍过量可保证有毒、易氧化挥发的硫粉完全转化为 \\(\\mathrm{FeS}\\)，减少硫在空气中燃烧生成污染气体 \\(\\mathrm{SO_2}\\)（同时也因铁粉价廉且散热均匀）。","(2) 发生反应：\\(\\mathrm{FeS(s) + 2HCl(aq) \\longrightarrow FeCl_2(aq) + H_2S(g)\\uparrow}\\)；\\(\\mathrm{Fe(s) + 2HCl(aq) \\longrightarrow FeCl_2(aq) + H_2(g)\\uparrow}\\)。","鉴定方案：将产生的气体先通过湿润的**醋酸铅(II)试纸**（或通入 \\(\\mathrm{CuSO_4}\\) 溶液），试纸变黑（或产生黑色 \\(\\mathrm{CuS}\\) 沉淀）证明含 \\(\\mathrm{H_2S}\\)（即原固体含 \\(\\mathrm{FeS}\\)）；再将经足量 \\(\\mathrm{NaOH}\\) 或 \\(\\mathrm{CuSO_4}\\) 溶液充分除去 \\(\\mathrm{H_2S}\\) 后剩余的无色气体收集验纯点燃，发出淡蓝色火焰且罩干冷烧杯内壁起水雾（或听到爆鸣声），证明含 \\(\\mathrm{H_2}\\)（即原固体含单质 \\(\\mathrm{Fe}\\)）。"],"answer":"(1) 保证硫充分反应并减少 SO₂ 污染；(2) 醋酸铅试纸变黑检出 H₂S（FeS），除尽 H₂S 后点燃气体验水雾检出 H₂（Fe）。","markingPoints":["说明铁过量目的（1分）","写出 FeS 与 Fe 溶酸两方程式（2分）","设计醋酸铅检 H₂S 及除杂后点燃检 H₂（1分）"],"verification":"注意 H₂S 也能燃烧产生淡蓝色火焰，所以必须**先用碱液或硫酸铜溶液彻底除尽 H₂S** 后才能点火检验 H₂！","pitfall":"未除尽 H₂S 就直接点燃混合气，无法证明产物中必定有 H₂。"}],"practice":[{"id":"chem14-14.4-q1","tier":"L1","tierLabel":"L1 基础","examStyle":"P1 选择","q":"下列试剂或物品中，可用于安全清除实验室地面不慎洒落的水银（汞）及洗涤试管壁残留的硫粉的一组分别是（　）。","options":["A. 硫粉；热 \\(\\mathrm{NaOH}\\) 溶液（或 \\(\\mathrm{CS_2}\\)）","B. 沙子；冷稀盐酸","C. 食盐水；酒精","D. 生石灰；浓硝酸（常温）"],"correctOption":"A","given":"化上 p.350–351 硫的性质与问题解决","method":"对照 Hg+S 常温化合及硫溶 CS₂/热碱歧化","principle":"Hg + S → HgS；3S + 6NaOH(热) → 2Na₂S + Na₂SO₃ + 3H₂O。","steps":["水银洒落撒硫粉生成无挥发性的 \\(\\mathrm{HgS}\\)；试管壁硫单质易溶于 \\(\\mathrm{CS_2}\\) 也可与热碱液歧化除去。"],"ans":"A","markingPoints":["掌握撒硫粉除汞与热碱/CS₂ 洗硫"],"verification":"对照化上 p.351 问题解决(1)(2)。","pitfall":"误以为硫粉能溶于稀盐酸或酒精。"},{"id":"chem14-14.4-q2","tier":"L2","tierLabel":"L2 期末","examStyle":"P1 选择","q":"下列物质中，**不能**由两种单质直接化合而制得的是（　）。","options":["A. \\(\\mathrm{FeS}\\)","B. \\(\\mathrm{Cu_2S}\\)","C. \\(\\mathrm{Fe_3O_4}\\)","D. \\(\\mathrm{CuS}\\)"],"correctOption":"D","given":"单质硫与变价金属化合产物规律","method":"对比 S 与 Fe、Cu 反应价态","principle":"S 氧化性较弱，Cu 与 S 高温直接化合生成 Cu₂S 而非 CuS。","steps":["Fe+S → FeS；2Cu+S → Cu₂S；3Fe+2O₂ → Fe₃O₄；唯有 CuS 无法由铜与硫直接化合得到（需 Cu²⁺ 与 H₂S 复分解）。"],"ans":"D","markingPoints":["识别 2Cu + S → Cu₂S 而非 CuS"],"verification":"对照化上 p.351 方程式与 p.430。","pitfall":"误选 B，忘记铜与硫生成的是硫化亚铜 Cu₂S。"},{"id":"chem14-14.4-q3","tier":"L3","tierLabel":"L3 预试","examStyle":"P2 方程式与分析","q":"完成下列反应方程式并指明硫元素在反应中所表现的性质（氧化性、还原性或兼而有之）：(1) 工业上在炼硫炉中用黄铁矿和焦炭在有限空气中高温燃烧炼硫；(2) 用热氢氧化钠溶液洗涤试管壁上残留的硫单质；(3) 硫粉与热浓硫酸共热。","given":"化上 p.351–352 硫的制备与反应","method":"写出配平方程式并比较反应前后 S 的氧化数变化","principle":"氧化数升高为还原性，降低为氧化性，既有升高又有降低为歧化兼性。","steps":["(1) \\(\\mathrm{3FeS_2(s) + 12C(s) + 8O_2(g)} \\xrightarrow{\\text{高温}} \\mathrm{Fe_3O_4(s) + 12CO(g) + 6S(l)}\\)，\\(\\mathrm{FeS_2}\\) 中 −1 价硫升高为 0 价单质硫，表现**还原性**。","(2) \\(\\mathrm{3S(s) + 6NaOH(aq)} \\xrightarrow{\\Delta} \\mathrm{2Na_2S(aq) + Na_2SO_3(aq) + 3H_2O(l)}\\)，硫单质既降至 −2 价又升至 +4 价，**既表现氧化性又表现还原性**。","(3) \\(\\mathrm{S(s) + 2H_2SO_4(aq,\\text{浓})} \\xrightarrow{\\Delta} \\mathrm{3SO_2(g)\\uparrow + 2H_2O(l)}\\)，单质硫由 0 价升至 +4 价，表现**还原性**。"],"ans":"(1) 还原性；(2) 既氧化性又还原性；(3) 还原性（方程式见步骤）。","markingPoints":["3 条方程式系数与条件完全正确（3分）","3 处硫元素性质判断准确（1.5分）"],"verification":"热碱歧化电子守恒：\\(2\\times 2e^- = 1\\times 4e^-\\)。","pitfall":"漏记黄铁矿高温炼硫系数 3、12、8 → 1、12、6（可用 Fe 守恒 3Fe → Fe₃O₄ 迅速推导出全式）。"},{"id":"chem14-14.4-q4","tier":"L4","tierLabel":"L4 统考压轴","examStyle":"P2 综合计算","q":"将 \\(5.6\\text{ g}\\) 铁粉与 \\(4.8\\text{ g}\\) 硫粉混合均匀，在隔绝空气的密闭容器中充分加热反应，冷却至室温后，向容器内所有固体中加入足量稀盐酸使之充分溶解，在标准状况下共收集到混合气体多少升？其中各气体成分的体积分数分别是多少？（\\(\\mathrm{Fe}=56,\\ \\mathrm{S}=32\\)）","given":"m(Fe)=5.6 g (0.10 mol)，m(S)=4.8 g (0.15 mol)，隔绝空气加热","method":"先判断 Fe 与 S 谁过量（S 过量！），注意 S 不溶于稀盐酸，只计算生成的 FeS 与稀盐酸放出的 H₂S！","principle":"限量反应物判别；S 不溶于稀盐酸；FeS + 2HCl → FeCl₂ + H₂S↑。","steps":["计算投料：\\(n(\\mathrm{Fe}) = \\frac{5.6}{56} = 0.10\\text{ mol}\\)，\\(n(\\mathrm{S}) = \\frac{4.8}{32} = 0.15\\text{ mol}\\)。","反应 \\(\\mathrm{Fe + S} \\xrightarrow{\\Delta} \\mathrm{FeS}\\) 按 \\(1:1\\) 进行，故 \\(\\mathrm{Fe}\\) 为限量反应物，反应完全，生成 \\(n(\\mathrm{FeS}) = 0.10\\text{ mol}\\)，剩余单质 \\(\\mathrm{S} = 0.15 - 0.10 = 0.05\\text{ mol}\\)。","加入足量稀盐酸后，剩余单质 \\(\\mathrm{S}\\) 不与稀盐酸反应，无剩余铁粉，只有 \\(\\mathrm{FeS}\\) 溶解：\\(\\mathrm{FeS(s) + 2HCl(aq) \\longrightarrow FeCl_2(aq) + H_2S(g)\\uparrow}\\)。","故仅收集到单一气体 \\(\\mathrm{H_2S}\\)：\\(n(\\mathrm{H_2S}) = 0.10\\text{ mol}\\)，标准状况体积 \\(V = 0.10 \\times 22.4 = 2.24\\text{ L}\\)，其中 \\(\\mathrm{H_2S}\\) 占 \\(100\\%\\)。"],"ans":"共收集到标准状况下气体 \\(2.24\\text{ L}\\)，成分全部为 \\(\\mathrm{H_2S}\\)（体积分数 \\(100\\%\\)）。","markingPoints":["准确判断 Fe 限量、S 过量 0.05 mol 且得 FeS 0.10 mol（2分）","说明剩余 S 不溶盐酸，仅生成 0.10 mol H₂S 即 2.24 L（2分）"],"verification":"无论 S 过量多少，因 1 mol Fe → 1 mol FeS → 1 mol H₂S，只要 Fe 不剩余，放出气体体积只由 Fe 的量决定。","pitfall":"若习惯性以为一定会有过量铁产生 H₂，或以为过量硫也会和稀盐酸产生气体，就会算错。"}],"cheatSheet":["硫单质（菱形、单斜、弹性硫同素异形体）：淡黄色不溶水、易溶 CS₂；撒硫粉除洒落汞（Hg+S→HgS）；热碱洗硫 3S+6NaOH → 2Na₂S+Na₂SO₃+3H₂O。","氧化性弱于 Cl₂：Fe+S —Δ→ FeS；2Cu+S —高温→ Cu₂S。","还原性：S+O₂ → SO₂；S+2H₂SO₄(浓) —Δ→ 3SO₂↑+2H₂O；S+6HNO₃(浓) → H₂SO₄+6NO₂↑+2H₂O。"],"kbEntryIds":["kb-chem14-sulfur-allotropes"],"quiz":{"q":"将 \\(1\\text{ mol}\\) 单质硫与足量热浓硫酸共热充分反应，转移的电子总数是多少摩尔？写出化学方程式。","given":"S + 2H₂SO₄(浓) —Δ→ 3SO₂↑ + 2H₂O","method":"利用归中反应只看一端价态变化（0 → +4）计算电子转移","principle":"单质 S 由 0 价升至 +4 价（SO₂），失 4 mol e⁻；2 mol H₂SO₄ 中 +6 价 S 降至 +4 价，得 4 mol e⁻。","steps":["\\(\\mathrm{S(s) + 2H_2SO_4(aq,\\text{浓})} \\xrightarrow{\\Delta} \\mathrm{3SO_2(g)\\uparrow + 2H_2O(l)}\\)。","1 mol S 由 0 价升至 +4 价，共转移 \\(4\\text{ mol}\\) 电子。"],"ans":"转移 \\(4\\text{ mol}\\) 电子；\\(\\mathrm{S + 2H_2SO_4(\\text{浓})} \\xrightarrow{\\Delta} \\mathrm{3SO_2\\uparrow + 2H_2O}\\)"}},{"id":"14.5","t":"硫化氢","anchor":{"pages":"化上 p.353–357","syllabus":"3.8.5 硫化氢的弱酸性、强还原性、可燃性、启普发生器制备及醋酸铅检验","examScopes":["sem2_final","uec"],"examWeight":"P1 还原性/干燥禁忌/沉淀辨析 + P2 启普发生器操作及 H₂S+SO₂ 归中定量","terms":"hydrogen sulphide · hydrosulphuric acid · Kipp's apparatus · lead(II) acetate paper","prerequisites":["硫元素最低负价（−2）的强还原性","启普发生器‘随开随用、随关随停’工作原理"],"goals":["熟记 H₂S 的物理性质（臭鸡蛋气味、剧毒、1:2.6 溶于水）和氢硫酸二元弱酸性质。","掌握 H₂S 与稀硝酸、浓硝酸、浓硫酸、SO₂、酸化 KMnO₄、O₂（足量 vs 不足）及热分解的各类反应方程式。","理解实验室 FeS + 稀硫酸/稀盐酸制 H₂S 与启普发生器使用条件（图14-28），以及湿润醋酸铅试纸变黑检验原理。"]},"concepts":[{"kind":"experiment","title":"活动15–17：硫化氢的溶解性、氢硫酸弱酸性与强还原性（表14-9）","pageRef":"化上 p.354–355","body":["**物理性质与毒性**：\\(\\mathrm{H_2S}\\) 是无色、有**臭鸡蛋气味**的**剧毒**气体（空气含量达 0.1% 即危及生命），密度比空气略大（\\(M=34 > 29\\)）；常温 1 体积水溶 2.6 体积（活动15 针筒液面略推入，pH < 7）。","**弱酸性（氢硫酸，活动16）**：\\(\\mathrm{H_2S}\\) 水溶液使石蕊变红，为二元弱酸，加热后因 \\(\\mathrm{H_2S}\\) 气体受热逸出红色变浅。","**强还原性（−2 价为最低氧化数）**：① **活动17**：\\(\\mathrm{H_2S}\\) 水溶液加 \\(\\mathrm{SO_2}\\) 水溶液立即出现**黄色浑浊（硫沉淀）**：\\(\\mathrm{SO_2(g) + 2H_2S(g) \\longrightarrow 2H_2O(l) + 3S(s)\\downarrow}\\)；② 与浓硫酸反应析出硫：\\(\\mathrm{3H_2S + H_2SO_4(\\text{浓}) \\longrightarrow 4S\\downarrow + 4H_2O}\\)（故**绝不能用浓硫酸干燥 \\(\\mathrm{H_2S}\\)**！可用无水 \\(\\mathrm{CaCl_2}\\) 或 \\(\\mathrm{P_2O_5}\\)）；③ 通入稀硝酸得红棕色 \\(\\mathrm{NO_2}\\) 与黄色 S，通入过量浓硝酸彻底氧化为 \\(\\mathrm{H_2SO_4}\\)；④ 使酸化 \\(\\mathrm{KMnO_4}\\) 紫色褪去并析出黄色 S。"],"takeaway":"记住实验室四大禁用浓硫酸干燥的气体：碱性 NH₃ 和强还原性 H₂S、HBr、HI！"},{"kind":"law","title":"硫化氢的可燃性（分步产物）与热分解","pageRef":"化上 p.355","body":["**可燃性（淡蓝色火焰，图14-26）**：① 氧气充足时完全燃烧生成 \\(\\mathrm{SO_2}\\)：\\(\\mathrm{2H_2S(g) + 3O_2(g)} \\xrightarrow{\\text{点燃}} \\mathrm{2SO_2(g) + 2H_2O(l)}\\)；② 氧气不充足时不完全燃烧析出黄色单质硫：\\(\\mathrm{2H_2S(g) + O_2(g)} \\xrightarrow{\\text{点燃}} \\mathrm{2S(s) + 2H_2O(l)}\\)。","**热分解**：在较高温度（缺氧）下分解为氢气和硫：\\(\\mathrm{H_2S(g)} \\xrightarrow{\\text{高温}} \\mathrm{S(s) + H_2(g)}\\)。"],"takeaway":"H₂S 燃烧与 P 燃烧同理：氧气足得高价氧化物（SO₂），氧气不足停留在单质（S）。"},{"kind":"experiment","title":"实验室制法（启普发生器）与醋酸铅(II)试纸检验","pageRef":"化上 p.356–357","body":["**制备反应**：用块状硫化铁(II)（\\(\\mathrm{FeS}\\)）与稀盐酸或稀硫酸常温反应：\\(\\mathrm{FeS(s) + 2HCl(aq) \\longrightarrow FeCl_2(aq) + H_2S(g)\\uparrow}\\) 或 \\(\\mathrm{FeS(s) + H_2SO_4(aq) \\longrightarrow FeSO_4(aq) + H_2S(g)\\uparrow}\\)（切忌用浓硫酸或硝酸，因强氧化性会氧化 \\(\\mathrm{H_2S}\\)；且制气须在通风橱内操作）。","**启普发生器（Kipp's apparatus，图14-28）**：由球形漏斗、容器部分、带活塞导管三部分组成，适用于**块状固体 + 液体常温制取难溶或微溶气体**（如 \\(\\mathrm{H_2, CO_2, H_2S}\\)）。开启活塞，酸流下接触 \\(\\mathrm{FeS}\\) 产气；关闭活塞，气体压强增大把酸压回球形漏斗与固体分离，反应立即停止（**随开随用、随关随停**）。","**检验方法**：湿润的**醋酸铅(II)试纸**遇到 \\(\\mathrm{H_2S}\\) 立刻变成深棕色或黑色（难溶硫化铅 \\(\\mathrm{PbS}\\)）：\\(\\mathrm{Pb(CH_3COO)_2(aq) + H_2S(g) \\longrightarrow PbS(s)\\downarrow + 2CH_3COOH(aq)}\\)。"],"takeaway":"粉末状固体（如 MnO₂ 或 Na₂O₂）不能用启普发生器，因为粉末会穿过玻璃颈漏入底部无法与酸液彻底分离！"}],"formulas":[{"title":"H₂S 的燃烧、归中及与氧化性酸的反应方程式","tex":"\\mathrm{SO_2(g) + 2H_2S(g) \\longrightarrow 2H_2O(l) + 3S(s)\\downarrow},\\qquad \\mathrm{3H_2S(g) + H_2SO_4(aq,\\text{浓}) \\longrightarrow 4S(s)\\downarrow + 4H_2O(l)}","plain":"SO2 + 2H2S -> 2H2O + 3S↓; 3H2S + H2SO4(浓) -> 4S↓ + 4H2O","conditions":"归中反应是工业脱硫制硫或瓶壁生成黄粉的经典反应","pageRef":"化上 p.355","note":"SO₂ + 2H₂S 中氧化产物与还原产物均为 S，两者物质的量之比为 2:1。"},{"title":"实验室制取 H₂S 及醋酸铅试纸检验方程式","tex":"\\mathrm{FeS(s) + H_2SO_4(aq,\\text{稀}) \\longrightarrow FeSO_4(aq) + H_2S(g)\\uparrow},\\qquad \\mathrm{Pb(CH_3COO)_2(aq) + H_2S(g) \\longrightarrow PbS(s)\\downarrow + 2CH_3COOH(aq)}","plain":"FeS + H2SO4(稀) -> FeSO4 + H2S↑; Pb(CH3COO)2 + H2S -> PbS↓ + 2CH3COOH","conditions":"块状 FeS 与稀酸在启普发生器常温反应；PbS 为深棕/黑色沉淀","pageRef":"化上 p.356–357","note":"不能用启普发生器制取乙炔或 NH₃/Cl₂（放热剧烈/生成糊状物或需加热）。"}],"pitfalls":[{"title":"用浓硫酸干燥 H₂S 或用硝酸与 FeS 制 H₂S","wrong":"“硫化氢是酸性气体，可以用浓硫酸洗气瓶来干燥；或者用稀硝酸代替稀硫酸与 FeS 反应。”","diagnosis":"浓硫酸和硝酸都具有强氧化性，而 \\(\\mathrm{H_2S}\\) 处于最低 −2 价具极强还原性，两者一相遇立刻氧化析出硫或生成 \\(\\mathrm{NO_2/SO_2}\\)。","right":"制 \\(\\mathrm{H_2S}\\) 只能用非氧化性酸（稀盐酸或稀硫酸）；干燥 \\(\\mathrm{H_2S}\\) 只能用无水 \\(\\mathrm{CaCl_2}\\) 或 \\(\\mathrm{P_2O_5}\\)，**严禁用浓硫酸**。","checkRule":"凡见“\\(\\mathrm{H_2S}\\) + 浓硫酸/硝酸/溴水/KMnO₄”，必定发生氧化还原反应！"},{"title":"误以为 H₂S 通入强酸铜盐溶液不能生成沉淀","wrong":"“由弱酸制强酸规律，\\(\\mathrm{H_2S + CuSO_4 \\to CuS\\downarrow + H_2SO_4}\\) 不可能发生。”","diagnosis":"\\(\\mathrm{CuS}\\)、\\(\\mathrm{PbS}\\)、\\(\\mathrm{Ag_2S}\\) 极度难溶（既不溶于水也不溶于稀酸），足以反向驱动反应进行。","right":"该反应能顺利生成黑色 \\(\\mathrm{CuS}\\) 沉淀（教材 Ch 16 p.432 专用于检验 \\(\\mathrm{Cu^{2+}}\\)！），但 \\(\\mathrm{H_2S}\\) 与 \\(\\mathrm{FeSO_4}\\) 无法直接生成 \\(\\mathrm{FeS}\\)（因 \\(\\mathrm{FeS}\\) 溶于稀酸）。","checkRule":"牢记：\\(\\mathrm{CuS, PbS, Ag_2S}\\) 极难溶可耐强酸，\\(\\mathrm{FeS, ZnS}\\) 溶于强酸（故用 \\(\\mathrm{FeS + HCl}\\) 制 \\(\\mathrm{H_2S}\\)）。"}],"examples":[{"label":"例 14.5.1","tier":"L3","tierLabel":"L3 预试拔高","title":"不同氧气投料比下 H₂S 燃烧产物的定量计算","prompt":"在标准状况下，将 \\(4.48\\text{ L}\\) 硫化氢气体与 \\(5.60\\text{ L}\\) 氧气混合于密闭容器中点火充分反应，恢复至常温常压后，求：(1) 反应后容器中生成单质硫（S）的质量是多少克？(2) 生成的气态二氧化硫在标准状况下的体积相当于多少升？（\\(\\mathrm{S}=32\\)）","clues":"全变 S 需 O₂:H₂S = 1:2 (0.5)；全变 SO₂ 需 O₂:H₂S = 3:2 (1.5)。现比值为 5.60/4.48 = 1.25，介于 0.5 与 1.5 之间！","strategy":"由极限比判定同时生成 S 和 SO₂，设 n(SO₂)=x、n(S)=y，用 S 守恒和 O 守恒（或电子守恒）联立求解。","given":"n(H₂S) = 4.48/22.4 = 0.20 mol；n(O₂) = 5.60/22.4 = 0.25 mol","principle":"硫原子守恒与氧原子/电子守恒。","steps":["计算投料：\\(n(\\mathrm{H_2S}) = 0.20\\text{ mol}\\)，\\(n(\\mathrm{O_2}) = 0.25\\text{ mol}\\)，故 \\(\\frac{n(\\mathrm{O_2})}{n(\\mathrm{H_2S})} = 1.25\\)。","因为 \\(0.5 < 1.25 < 1.5\\)，反应后 \\(\\mathrm{H_2S}\\) 与 \\(\\mathrm{O_2}\\) 均消耗完，产物中既有 \\(\\mathrm{SO_2}\\) 又有 \\(\\mathrm{S}\\)（外加 \\(0.20\\text{ mol }\\mathrm{H_2O}\\)）。","设生成 \\(n(\\mathrm{SO_2}) = x\\text{ mol}\\)，\\(n(\\mathrm{S}) = y\\text{ mol}\\)：","由 S 守恒：\\(x + y = 0.20\\)；","由氧原子守恒（全部 H₂S 转化为 \\(0.20\\text{ mol }\\mathrm{H_2O}\\) 用掉 \\(0.10\\text{ mol }\\mathrm{O_2}\\)，即 \\(0.20\\text{ mol O}\\) 原子，总 O 原子为 \\(0.50\\text{ mol}\\)）：\\(2x + 0.20 = 0.50 \\implies 2x = 0.30 \\implies x = 0.15\\text{ mol}\\)！","代回得 \\(y = 0.20 - 0.15 = 0.050\\text{ mol}\\)。","(1) 生成单质硫质量：\\(m(\\mathrm{S}) = 0.050 \\times 32 = 1.60\\text{ g}\\)；(2) \\(V(\\mathrm{SO_2,\\ STP}) = 0.15 \\times 22.4 = 3.36\\text{ L}\\)。"],"answer":"(1) 生成硫 \\(1.60\\text{ g}\\)；(2) 生成 \\(\\mathrm{SO_2}\\) 标况体积 \\(3.36\\text{ L}\\)。","markingPoints":["算出投料并判定同时生成 S 与 SO₂（1分）","列出 S 与 O 守恒求得 n(SO₂)=0.15 mol, n(S)=0.050 mol（2分）","算出 m(S)=1.60 g 与 V(SO₂)=3.36 L（1分）"],"verification":"化学式检验：\\(0.15\\text{ mol }\\mathrm{SO_2}\\) 耗 \\(0.225\\text{ mol }\\mathrm{O_2}\\)，\\(0.050\\text{ mol S}\\) 耗 \\(0.025\\text{ mol }\\mathrm{O_2}\\)，总耗 \\(\\mathrm{O_2} = 0.250\\text{ mol}\\)！","pitfall":"若写两个反应式先耗光一反应再转下一步，不如直接“先扣去 H 变 H₂O 的氧，剩余 O 全进 SO₂”快得多。"},{"label":"例 14.5.2","tier":"L2","tierLabel":"L2 校内期末","title":"无机框图串联推断（思考题 14e 第2题）","prompt":"已知盐 X 与酸 Y 反应，可放出有臭鸡蛋气味的气体 Z；Z 跟氢氧化钠溶液反应又得到盐 X；Z 在氧气中充分氧化的最终产物为气体 W；W 溶于水后又能进一步转化得到酸 Y。(1) 推断 X、Y、Z、W 分别是什么物质（写出化学式）；(2) 写出 X 与 Y 反应、以及 Z 完全氧化生成 W 的化学方程式。","clues":"有气味气体 Z（H₂S）氧化最终产物 W（SO₃），W 溶于水得酸 Y（H₂SO₄），Z+NaOH 得正盐 X（Na₂S）！","strategy":"从“Z 最终氧化产物 W 溶于水得酸 Y”逆推 Y 必为 H₂SO₄（而非 HCl），从而锁定整条转化链。","given":"X(盐)+Y(酸)→Z；Z+NaOH→X；Z→W→Y","principle":"硫元素价态连续转化：Na₂S / H₂S (−2) → SO₂ (+4) → SO₃ (+6) → H₂SO₄ (+6)。","steps":["(1) 由 Z 为臭鸡蛋气味气体（或可氧化连续转化）且最终氧化产物 W 溶于水得酸 Y，可知 **Y 为稀 \\(\\mathrm{H_2SO_4}\\)**（排除了不含氧的盐酸），**W 为 \\(\\mathrm{SO_3}\\)**，**Z 为 \\(\\mathrm{H_2S}\\)**，**X 为 \\(\\mathrm{Na_2S}\\)**（因为 \\(\\mathrm{H_2S + 2NaOH \\to Na_2S + 2H_2O}\\)）。","(2) X + Y 反应：\\(\\mathrm{Na_2S(aq) + H_2SO_4(aq,\\text{稀}) \\longrightarrow Na_2SO_4(aq) + H_2S(g)\\uparrow}\\)；","Z 完全氧化到 W 分两步（先燃成 \\(\\mathrm{SO_2}\\) 再催化氧化成 \\(\\mathrm{SO_3}\\)）：\\(\\mathrm{2H_2S + 3O_2} \\xrightarrow{\\text{点燃}} \\mathrm{2SO_2 + 2H_2O}\\)，\\(\\mathrm{2SO_2 + O_2} \\underset{\\Delta}{\\stackrel{\\mathrm{V_2O_5}}{\\rightleftharpoons}} \\mathrm{2SO_3}\\)。"],"answer":"(1) X: \\(\\mathrm{Na_2S}\\)，Y: 稀 \\(\\mathrm{H_2SO_4}\\)，Z: \\(\\mathrm{H_2S}\\)，W: \\(\\mathrm{SO_3}\\)；(2) 方程式见步骤。","markingPoints":["正确锁定 X, Y, Z, W 四种物质（2分）","写出反应方程式（2分）"],"verification":"对照化上 p.357 思考题 14e 第2题（答案 A：Na₂S 和稀硫酸）。","pitfall":"极易错选 C（Na₂S 和盐酸）或 D（Na₂SO₃ 和稀硫酸——SO₃ 溶于水得硫酸而非亚硫酸且 Na₂SO₃ 放 SO₂）。"}],"practice":[{"id":"chem14-14.5-q1","tier":"L1","tierLabel":"L1 基础","examStyle":"P1 选择","q":"实验室用湿润的醋酸铅(II)试纸检验 \\(\\mathrm{H_2S}\\) 气体时，试纸呈现的颜色变化及生成的黑色物质分别是（　）。","options":["A. 变黑；\\(\\mathrm{PbS}\\)","B. 变蓝；\\(\\mathrm{I_2}\\)","C. 变红；\\(\\mathrm{PbSO_4}\\)","D. 变白；\\(\\mathrm{S}\\)"],"correctOption":"A","given":"化上 p.357 硫化氢气体的检验","method":"直接对应教材反应方程式","principle":"Pb(CH₃COO)₂ + H₂S → PbS↓（黑色）+ 2CH₃COOH。","steps":["湿润醋酸铅试纸遇 H₂S 立刻变成深棕色或黑色 PbS。"],"ans":"A","markingPoints":["熟记醋酸铅试纸变黑及 PbS"],"verification":"对照化上 p.357。","pitfall":"把 PbS（黑色）与 PbSO₄（白色）颜色混记。"},{"id":"chem14-14.5-q2","tier":"L2","tierLabel":"L2 期末","examStyle":"P1 选择","q":"向下列四种溶液中通入 \\(\\mathrm{H_2S}\\) 气体后，**不会**产生沉淀的是（　）。","options":["A. 稀硝酸","B. 浓硫酸","C. 氢氧化钠溶液","D. 溴水"],"correctOption":"C","given":"思考题 14e 第1题（化上 p.357）","method":"检查各溶液是否氧化 H₂S 析出硫粉","principle":"强氧化剂将 H₂S 氧化成不溶的黄色硫沉淀；碱液与 H₂S 生成易溶的 Na₂S/NaHS。","steps":["A、B、D 均将 \\(\\mathrm{H_2S}\\) 氧化为黄色 \\(\\mathrm{S}\\) 沉淀；C 项发生中和生成可溶的 \\(\\mathrm{Na_2S}\\) 或 \\(\\mathrm{NaHS}\\) 溶液，无沉淀产生。"],"ans":"C","markingPoints":["判断强氧化剂析硫 vs 强碱生成可溶钠盐"],"verification":"对照化上 p.357 思考题 14e 第1题。","pitfall":"误选 A 或 B。"},{"id":"chem14-14.5-q3","tier":"L3","tierLabel":"L3 预试","examStyle":"P2 实验探究","q":"实验室采用图14-28 所示启普发生器制取硫化氢气体。(1) 请说明启普发生器“随关随停”的物理工作原理；(2) 若要制取干燥的 \\(\\mathrm{H_2S}\\) 气体，为什么**不能**选用浓硫酸作干燥剂？写出相关化学方程式。","given":"图14-28 启普发生器与 H₂S 强还原性","method":"解释气压压回酸液机制；写出 H₂S+浓 H₂SO₄ 归中反应","principle":"气体压强差实现固液分离；H₂S 与浓硫酸发生氧化还原。","steps":["(1) 使用前先检气密性。打开活塞，稀硫酸由球形漏斗流入容器与块状 \\(\\mathrm{FeS}\\) 接触产气；关闭活塞后，继续产生的 \\(\\mathrm{H_2S}\\) 使容器内气压增大，把酸液重新压回球形漏斗中，使酸液与固体 \\(\\mathrm{FeS}\\) 脱离接触，反应随即自动停止。","(2) 因为 \\(\\mathrm{H_2S}\\) 具有强还原性，会被强氧化性的浓硫酸氧化析出硫沉淀：\\(\\mathrm{3H_2S(g) + H_2SO_4(aq,\\text{浓}) \\longrightarrow 4S(s)\\downarrow + 4H_2O(l)}\\)，所以不能用浓硫酸干燥 \\(\\mathrm{H_2S}\\)。"],"ans":"(1) 关活塞气压增大将酸压回球形漏斗使固液分离；(2) H₂S 被浓硫酸氧化，方程式见步骤。","markingPoints":["完整叙述气压增大固液分离机制（2分）","写出 H₂S+浓硫酸反应方程式并说明不可用原因（2分）"],"verification":"对照化上 p.355–356 原文。","pitfall":"误把启普发生器用于粉末状固体（粉末无法隔绝于球腰上方）。"},{"id":"chem14-14.5-q4","tier":"L4","tierLabel":"L4 统考压轴","examStyle":"P2 综合计算","q":"将标准状况下 \\(6.72\\text{ L}\\) 的 \\(\\mathrm{H_2S}\\) 气体和 \\(4.48\\text{ L}\\) 的 \\(\\mathrm{SO_2}\\) 气体同时通入一个干燥且足够大的集气瓶中，充分混合反应后，瓶内出现大量黄色固体和无色液滴。(1) 判断集气瓶内哪一种气体过量？反应后瓶内剩余气体的标况体积是多少升？(2) 计算生成黄色固体硫的质量。（\\(\\mathrm{S}=32\\)）","given":"V(H₂S)=6.72 L (0.30 mol)；V(SO₂)=4.48 L (0.20 mol)","method":"按 SO₂ + 2H₂S = 3S↓ + 2H₂O 判限量反应物","principle":"限量试剂控制反应物消耗与产物生成。","steps":["投料：\\(n(\\mathrm{H_2S}) = \\frac{6.72}{22.4} = 0.30\\text{ mol}\\)，\\(n(\\mathrm{SO_2}) = \\frac{4.48}{22.4} = 0.20\\text{ mol}\\)。","(1) 由反应 \\(\\mathrm{SO_2(g) + 2H_2S(g) \\longrightarrow 3S(s)\\downarrow + 2H_2O(l)}\\) 可知，\\(0.30\\text{ mol}\\ \\mathrm{H_2S}\\) 仅需消耗 \\(0.15\\text{ mol}\\ \\mathrm{SO_2}\\)，故 **\\(\\mathrm{SO_2}\\) 过量**。","剩余 \\(\\mathrm{SO_2}\\) 的物质的量为 \\(0.20 - 0.15 = 0.050\\text{ mol}\\)，标况体积 \\(V = 0.050 \\times 22.4 = 1.12\\text{ L}\\)。","(2) 生成固体硫的物质的量：\\(n(\\mathrm{S}) = \\frac{3}{2} \\times 0.30 = 0.45\\text{ mol}\\)，质量 \\(m(\\mathrm{S}) = 0.45 \\times 32 = 14.4\\text{ g}\\)。"],"ans":"(1) \\(\\mathrm{SO_2}\\) 过量，剩余气体标况体积 \\(1.12\\text{ L}\\)；(2) 生成单质硫 \\(14.4\\text{ g}\\)。","markingPoints":["判断 SO₂ 过量并求出剩余 1.12 L（2分）","算得生成单质硫 0.45 mol 即 14.4 g（2分）"],"verification":"总 S 原子 = 0.30 + 0.20 = 0.50 mol；反应后固体 S 0.45 mol + 剩余 SO₂ 0.05 mol = 0.50 mol，原子守恒。","pitfall":"忘记 H₂O 常温为液态，误把生成的水蒸气也算入剩余气体。"}],"cheatSheet":["H₂S：臭鸡蛋气味、剧毒、微弱酸（氢硫酸）；−2 价具极强还原性，严禁用浓硫酸干燥或硝酸氧化制备。","燃烧：O₂ 足生 SO₂，O₂ 不足析出 S；归中：SO₂ + 2H₂S → 3S↓ + 2H₂O。","启普发生器制 H₂S（FeS + 稀 H₂SO₄/HCl，随开随用随关随停）；湿润醋酸铅试纸变黑（PbS）检验。"],"kbEntryIds":["kb-chem14-h2s-test"],"quiz":{"q":"将 \\(\\mathrm{H_2S}\\) 气体通入足量浓硝酸和稀硝酸中，分别能观察到什么现象？","given":"化上 p.355 硫化氢的还原性","method":"对比稀硝酸得 S(黄沉)+NO₂ 与浓硝酸彻底氧化成 H₂SO₄","principle":"硝酸氧化性强弱受浓度影响。","steps":["通入稀硝酸：生成红棕色 \\(\\mathrm{NO_2}\\) 气体和黄色硫沉淀（\\(\\mathrm{H_2S + 2HNO_3(\\text{稀}) \\to 2NO_2 + S\\downarrow + 2H_2O}\\)）。","通入过量浓硝酸：硫化氢被彻底氧化为可溶的 \\(\\mathrm{H_2SO_4}\\) 并放出大量红棕色 \\(\\mathrm{NO_2}\\)（\\(\\mathrm{H_2S + 8HNO_3(\\text{浓}) \\to H_2SO_4 + 8NO_2 + 4H_2O}\\)），**无硫沉淀**。"],"ans":"稀硝酸：红棕色气体 + 黄色硫沉淀；过量浓硝酸：红棕色气体，无沉淀（生成硫酸）。"}},{"id":"14.6","t":"二氧化硫","anchor":{"pages":"化上 p.357–363","syllabus":"3.8.6 二氧化硫的四大化学性质、可逆漂白机制与酸雨形成防治","examScopes":["sem2_final","uec"],"examWeight":"P1 漂白 vs 还原性褪色辨析、CO₂/SO₂ 鉴别 + P2 酸雨防治与实验探究高频点","terms":"sulphur dioxide · reversible bleaching · fuchsine · acid rain · potassium dichromate","prerequisites":["酸性氧化物通性与可逆反应（化上 Ch 14.3）","氧化还原价态桥梁：−2 ← 0 ← +4 → +6"],"goals":["通过活动18–20 归纳 SO₂ 的物理性质（易液化 bp −10℃，1:40 溶于水）及酸性氧化物、氧化性、还原性、可逆漂白性四大化学性质。","准确区分 SO₂ 漂白品红（化合可逆，加热复红）与 Cl₂/HClO/O₃/H₂O₂ 漂白（强氧化永久褪色），以及 SO₂ 使溴水/KMnO₄/K₂Cr₂O₇ 褪色属还原性。","阐明硫酸型酸雨的形成过程（图14-32）、危害及防治措施，掌握 CO₂ 与 SO₂ 的科学鉴别方案。"]},"concepts":[{"kind":"experiment","title":"活动18–20：二氧化硫四大性质实验归纳（表14-10）","pageRef":"化上 p.358–360","body":["**物理性质**：无色、有刺激性气味的有毒气体，密度比空气大（\\(M=64 > 29\\)），易液化（bp −10℃），易溶于水（常温常压 1 体积水溶约 40 体积）。","**活动18（溶解与酸性）**：充满 \\(\\mathrm{SO_2}\\) 的试管倒立水中，水面迅速上升（易溶），测水溶液 pH 呈明显酸性：\\(\\mathrm{SO_2(g) + H_2O(l) \\rightleftharpoons H_2SO_3(aq)}\\)（亚硫酸不稳定易分解并易被空气/\\(\\mathrm{H_2O_2}\\) 氧化为硫酸）。","**活动19（可逆漂白性）**：\\(\\mathrm{SO_2}\\) 水溶液使品红（fuchsine）溶液**褪色**，但**加热试管后溶液又恢复原来的红色**！原因：\\(\\mathrm{SO_2}\\) 与有机色素结合生成**不稳定的无色物质**，受热或日久分解复原（如漂白过的银耳、草帽日久变黄）。","**活动20（还原性转 \\(\\mathrm{SO_4^{2-}}\\) 检验）**：向 \\(\\mathrm{BaCl_2}\\) 溶液中滴加 \\(\\mathrm{SO_2}\\) 水溶液**无明显沉淀**（因亚硫酸酸性弱于盐酸，\\(\\mathrm{SO_2 + H_2O + BaCl_2}\\) 不能逆向生出强酸 HCl）；再滴加 \\(3\\%\\ \\mathrm{H_2O_2}\\) 后立刻产生大量**不溶于稀盐酸的白色沉淀 \\(\\mathrm{BaSO_4}\\)**（\\(\\mathrm{H_2SO_3 + H_2O_2 \\to H_2SO_4 + H_2O}\\)）。"],"takeaway":"把 SO₂ 通入 BaCl₂ 溶液不产生沉淀；若通入 Ba(NO₃)₂ 溶液则因 NO₃⁻ 在酸性下氧化 H₂SO₃ 会立刻生成白色 BaSO₄ 沉淀！"},{"kind":"table","title":"常见漂白剂原理对比与易混淆褪色实验辨析","pageRef":"化上 p.359–360","body":["考场极易把“\\(\\mathrm{SO_2}\\) 使品红褪色”和“\\(\\mathrm{SO_2}\\) 使溴水/高锰酸钾褪色”混为一谈，必须严格区分化合漂白与氧化还原反应。"],"table":{"headers":["试剂 / 过程","褪色本质与类型","加热后能否复色","检验 / 典型方程式"],"rows":[["\\(\\mathrm{SO_2}\\) 漂白品红溶液","化合作用生成不稳定无色物质（非氧化还原）","**能**（恢复红色）","特征鉴定 \\(\\mathrm{SO_2}\\) 气体"],["\\(\\mathrm{HClO}\\)（氯水）、\\(\\mathrm{O_3}\\)、\\(\\mathrm{H_2O_2}\\)","强氧化作用彻底破坏有机色素分子","**不能**（永久褪色）","氯水使石蕊试纸先变红后褪色"],["活性炭（木炭）脱色","物理吸附作用（多孔结构表面吸附色素）","物理变化","脱除红糖色素、防毒面具"],["\\(\\mathrm{SO_2}\\) 使酸性 \\(\\mathrm{KMnO_4}\\) / 溴水 / 酸性 \\(\\mathrm{K_2Cr_2O_7}\\) 褪色或变色","**氧化还原反应**（\\(\\mathrm{SO_2}\\) 表现**还原性**，绝不是漂白性！）","**不能**","\\(\\mathrm{3SO_2 + K_2Cr_2O_7(\\text{橙}) + H_2SO_4 \\to K_2SO_4 + Cr_2(SO_4)_3(\\text{绿}) + H_2O}\\)"]]},"takeaway":"若将 SO₂ 和 Cl₂ 按 1:1 体积比同时通入品红溶液，会发生 Cl₂ + SO₂ + 2H₂O → H₂SO₄ + 2HCl，漂白性双双丧失！"},{"kind":"definition","title":"硫酸型酸雨的形成、危害与综合防治","pageRef":"化上 p.360–362","body":["**硫酸型酸雨形成两条路径（图14-32）**：大量燃烧含硫煤炭、石油及冶炼含硫矿石排出 \\(\\mathrm{SO_2}\\)：① 气相催化氧化：\\(\\mathrm{2SO_2 + O_2} \\xrightarrow{\\text{尘埃金属氧化物/光照}} \\mathrm{2SO_3}\\)，\\(\\mathrm{SO_3 + H_2O \\to H_2SO_4}\\)；② 液相溶水氧化：\\(\\mathrm{SO_2 + H_2O \\rightleftharpoons H_2SO_3}\\)，\\(\\mathrm{2H_2SO_3 + O_2 \\to 2H_2SO_4}\\)（故亚硫酸水溶液久置空气中 pH 会**变小**，且检出 \\(\\mathrm{SO_4^{2-}}\\)，思考题 14g 第2题！）。","**酸雨危害**：使土壤 K、Na、Ca、Mg 养分流失及酸化，毁坏农作物与森林（图14-33）；酸化湖泊致鱼类死亡；加速桥梁、石灰石雕像腐蚀（图14-34）。","**防治**：调整能源结构、煤炭脱硫技术（如钙基固硫）、废气回收硫资源（\\(\\mathrm{SO_2 + 2CO} \\xrightarrow{\\text{催化剂/高温}} \\mathrm{S + 2CO_2}\\)）。"],"takeaway":"久置空气中的亚硫酸或酸雨样品，H₂SO₃ 逐渐被 O₂ 氧化为强酸 H₂SO₄，H⁺ 浓度增大、pH 进一步降低。"}],"formulas":[{"title":"二氧化硫的氧化性与还原性经典检验方程","tex":"\\mathrm{SO_2(g) + 2CO(g)} \\xrightarrow{\\text{催化剂、高温}} \\mathrm{S(s) + 2CO_2(g)},\\qquad \\mathrm{3SO_2 + K_2Cr_2O_7(\\text{橙}) + H_2SO_4 \\longrightarrow K_2SO_4 + Cr_2(SO_4)_3(\\text{绿}) + H_2O}","plain":"SO2 + 2CO -> S + 2CO2; 3SO2 + K2Cr2O7 + H2SO4 -> K2SO4 + Cr2(SO4)3 + H2O","conditions":"前者为氧化性（从废气回收硫）；后者为重铬酸钾检验 SO₂（由橙变绿）","pageRef":"化上 p.359","note":"SO₂ 还可还原浓硝酸：SO₂ + 2HNO₃(浓) → H₂SO₄ + 2NO₂↑，及还原酸性 KMnO₄（紫色褪去）。"},{"title":"亚硫酸溶液露置空气变质与氯水/双氧水氧化反应","tex":"\\mathrm{2H_2SO_3(aq) + O_2(g) \\longrightarrow 2H_2SO_4(aq)},\\qquad \\mathrm{SO_2(g) + Cl_2(g) + 2H_2O(l) \\longrightarrow H_2SO_4(aq) + 2HCl(aq)}","plain":"2H2SO3 + O2 -> 2H2SO4; SO2 + Cl2 + 2H2O -> H2SO4 + 2HCl","conditions":"亚硫酸被氧化后弱酸变强酸，pH 明显降低","pageRef":"化上 p.359、p.361","note":"等物质的量的 SO₂ 与 Cl₂ 同时通入品红溶液中，反应生成无漂白性的 H₂SO₄ 和 HCl，品红不褪色！"}],"pitfalls":[{"title":"用澄清石灰水鉴别 CO₂ 和 SO₂","wrong":"“将两种未知气体分别通入澄清石灰水，变浑浊的是 \\(\\mathrm{CO_2}\\)，无明显现象的是 \\(\\mathrm{SO_2}\\)。”","diagnosis":"\\(\\mathrm{SO_2}\\) 与 \\(\\mathrm{Ca(OH)_2}\\) 同样迅速反应生成白色难溶亚硫酸钙（\\(\\mathrm{CaSO_3\\downarrow}\\)），且过量时同样转变为可溶 \\(\\mathrm{Ca(HSO_3)_2}\\) 变澄清，现象完全相同！","right":"鉴别 \\(\\mathrm{CO_2}\\) 和 \\(\\mathrm{SO_2}\\) 必须利用 \\(\\mathrm{SO_2}\\) 独有的漂白性或还原性，选用**品红溶液**、**酸性 \\(\\mathrm{KMnO_4}\\) 溶液**或**溴水**（教材思考题 14f 第2题）。","checkRule":"看到“鉴别 CO₂ 与 SO₂”选澄清石灰水或紫色石蕊均错！除杂 \\(\\mathrm{CO_2}\\) 中混有的 \\(\\mathrm{SO_2}\\) 应先过饱和 \\(\\mathrm{NaHCO_3}\\) 或酸性 \\(\\mathrm{KMnO_4}\\)。"},{"title":"把“SO₂ 使高锰酸钾/溴水褪色”错归因于漂白性","wrong":"“\\(\\mathrm{SO_2}\\) 能使品红溶液和酸性 \\(\\mathrm{KMnO_4}\\) 溶液褪色，这都证明了 \\(\\mathrm{SO_2}\\) 具有漂白性。”","diagnosis":"\\(\\mathrm{KMnO_4}\\)、\\(\\mathrm{Br_2}\\) 都是无机强氧化剂，根本不是有机色素，被 \\(\\mathrm{SO_2}\\) 褪色是电子转移过程。","right":"\\(\\mathrm{SO_2}\\) 使品红褪色体现**漂白性**；使酸性 \\(\\mathrm{KMnO_4}\\)、溴水、氯水、碘水褪色体现的是**还原性**。","checkRule":"记住：只有面对有机染料（如品红）才能叫“漂白性”，面对强氧化剂褪色全叫“还原性”！"}],"examples":[{"label":"例 14.6.1","tier":"L3","tierLabel":"L3 预试拔高","title":"CO₂ 与 SO₂ 混合气体的连续检验与除杂装置设计","prompt":"某混合气体中可能同时含有 \\(\\mathrm{CO_2}\\) 和 \\(\\mathrm{SO_2}\\)（例如碳与浓硫酸共热后的产物），现有如下洗气试剂瓶：A. 品红溶液、B. 酸性 \\(\\mathrm{KMnO_4}\\) 溶液、C. 澄清石灰水。请按气体流向排出最严谨的检验顺序（试剂可重复使用），并说明每一瓶的作用及若证明“既有 \\(\\mathrm{SO_2}\\) 又有 \\(\\mathrm{CO_2}\\)”应出现的全部实验现象。","clues":"SO₂ 也会使澄清石灰水变浑浊！因此在用澄清石灰水检 CO₂ 前，必须先检出 SO₂、再彻底除尽 SO₂ 并验证已除尽！","strategy":"四瓶串联逻辑：检 SO₂（品红）→ 除 SO₂（酸性 KMnO₄）→ 验 SO₂ 是否除尽（品红）→ 检 CO₂（澄清石灰水）。","given":"混合气体（CO₂ + SO₂），试剂 A 品红、B 酸性 KMnO₄、C 澄清石灰水","principle":"先检后除、防干扰、验除尽、再检后。","steps":["最严谨的洗气瓶连接顺序为：**A（品红） → B（酸性 \\(\\mathrm{KMnO_4}\\)） → A（品红） → C（澄清石灰水）**。","各瓶作用与现象说明：","① 第 1 瓶 A（品红）：检验 \\(\\mathrm{SO_2}\\) 的存在——若**品红褪色**，证明含有 \\(\\mathrm{SO_2}\\)；","② 瓶 B（足量酸性 \\(\\mathrm{KMnO_4}\\)）：利用强氧化性将 \\(\\mathrm{SO_2}\\) 全部氧化除去（\\(\\mathrm{5SO_2 + 2MnO_4^- + 2H_2O \\to 2Mn^{2+} + 5SO_4^{2-} + 4H^+}\\)）；","③ 第 2 瓶 A（品红）：确认 \\(\\mathrm{SO_2}\\) 已被除尽——**品红不褪色**；","④ 瓶 C（澄清石灰水）：检验 \\(\\mathrm{CO_2}\\)——在确认无 \\(\\mathrm{SO_2}\\) 干扰下**石灰水变浑浊**，证明含有 \\(\\mathrm{CO_2}\\)。"],"answer":"顺序 A → B → A → C；现象：第一瓶品红褪色、第二瓶品红不褪色、澄清石灰水变浑浊。","markingPoints":["排出正确四步串联顺序 A→B→A→C（2分）","说明第二个品红瓶‘验证 SO₂ 已除尽’的作用与现象（2分）"],"verification":"若省去第 3 瓶品红，一旦 B 中 KMnO₄ 不足导致 SO₂ 漏出，C 变浑浊就无法确认归属于 CO₂。","pitfall":"切忌先通过澄清石灰水（SO₂ 先反应干扰）或只用一瓶酸性 KMnO₄ 而不复验品红。"},{"label":"例 14.6.2","tier":"L4","tierLabel":"L4 统考压轴","title":"二氧化硫还原高锰酸钾与双氧水氧化钡盐定量分析","prompt":"实验室测定某工业废气样品中 \\(\\mathrm{SO_2}\\) 的含量（假设其他成分不反应）：将标准状况下 \\(22.4\\text{ L}\\) 该废气缓缓通入 \\(100\\text{ mL}\\) 浓度为 \\(0.20\\text{ mol}\\cdot\\mathrm{L^{-1}}\\) 的酸性 \\(\\mathrm{KMnO_4}\\) 溶液中，恰好使高锰酸钾紫红色完全褪去（反应式：\\(\\mathrm{5SO_2 + 2KMnO_4 + 2H_2O \\to K_2SO_4 + 2MnSO_4 + 2H_2SO_4}\\)）。(1) 计算反应消耗的 \\(\\mathrm{SO_2}\\) 物质的量；(2) 求该废气样品中 \\(\\mathrm{SO_2}\\) 的体积分数（保留三位有效数字）。","clues":"利用 5 SO₂ ↔ 2 KMnO₄ 比例直接计算。","strategy":"先求 n(KMnO₄)，再求 n(SO₂) 与标况体积。","given":"V(废气, STP)=22.4 L (1.00 mol)；n(KMnO₄)=0.100 × 0.20 = 0.020 mol","principle":"氧化还原计量关系 5 SO₂ ~ 2 KMnO₄。","steps":["(1) 消耗高锰酸钾：\\(n(\\mathrm{KMnO_4}) = 0.100\\text{ L} \\times 0.20\\text{ mol}\\cdot\\mathrm{L^{-1}} = 0.020\\text{ mol}\\)。","依据化学计量比 \\(n(\\mathrm{SO_2}) : n(\\mathrm{KMnO_4}) = 5 : 2\\)，得 \\(n(\\mathrm{SO_2}) = \\frac{5}{2} \\times 0.020 = 0.050\\text{ mol}\\)。","(2) 标准状况下 \\(\\mathrm{SO_2}\\) 体积：\\(V(\\mathrm{SO_2}) = 0.050\\text{ mol} \\times 22.4\\text{ L}\\cdot\\mathrm{mol^{-1}} = 1.12\\text{ L}\\)。","体积分数：\\(\\varphi(\\mathrm{SO_2}) = \\frac{1.12\\text{ L}}{22.4\\text{ L}} \\times 100\\% = 5.00\\%\\)。"],"answer":"(1) \\(0.050\\text{ mol}\\)；(2) \\(5.00\\%\\)。","markingPoints":["算出 n(KMnO₄)=0.020 mol（1分）","利用 5:2 算得 n(SO₂)=0.050 mol（2分）","求得体积分数 5.00%（1分）"],"verification":"电子守恒核验：\\(0.050\\text{ mol }\\mathrm{SO_2}\\times 2 = 0.10\\text{ mol }e^-\\)，\\(0.020\\text{ mol }\\mathrm{MnO_4^-}\\times 5 = 0.10\\text{ mol }e^-\\)。","pitfall":"算反 5:2 比例得出 0.008 mol。"}],"practice":[{"id":"chem14-14.6-q1","tier":"L1","tierLabel":"L1 基础","examStyle":"P1 选择","q":"下列关于二氧化硫的说法中，**不正确**的是（　）。","options":["A. 能使品红等某些有色物质褪色，且加热后颜色复原","B. 是一种无色、有刺激性气味、无毒的气体","C. 既有氧化性，又有还原性","D. 既易溶于水，又可与水反应生成亚硫酸"],"correctOption":"B","given":"思考题 14f 第1题（化上 p.363）","method":"直接对照 SO₂ 物理与毒性特征","principle":"SO₂ 有毒，是主要大气污染物和酸雨成因。","steps":["B 错：二氧化硫是**有毒**气体（不是无毒）。"],"ans":"B","markingPoints":["明确 SO₂ 的毒性"],"verification":"对照化上 p.359 原文与 p.363 思考题 14f 第1题。","pitfall":"大意漏读选项末尾“无毒”二字。"},{"id":"chem14-14.6-q2","tier":"L2","tierLabel":"L2 期末","examStyle":"P1 选择","q":"在下列试剂中，能够用来明确鉴别 \\(\\mathrm{CO_2}\\) 和 \\(\\mathrm{SO_2}\\) 两种无色气体的是（　）。","options":["A. 澄清的石灰水","B. 品红溶液","C. 紫色石蕊试液","D. 氯化钡溶液"],"correctOption":"B","given":"思考题 14f 第2题（化上 p.363）","method":"逐项检验两气体通入现象是否相同","principle":"两气体均为酸性氧化物，仅 SO₂ 具可逆漂白性。","steps":["A 均变浑浊；C 均变红（SO₂ 不漂白石蕊）；D 均无现象；唯有 B 品红溶液中，\\(\\mathrm{SO_2}\\) 使其褪色而 \\(\\mathrm{CO_2}\\) 无变化。"],"ans":"B","markingPoints":["掌握品红溶液鉴别 CO₂ 与 SO₂"],"verification":"对照化上 p.363 思考题 14f 第2题。","pitfall":"误选 C（记住：SO₂ 不能使紫色石蕊试液褪色，只使其变红！）。"},{"id":"chem14-14.6-q3","tier":"L3","tierLabel":"L3 预试","examStyle":"P2 实验现象解释","q":"将 \\(\\mathrm{SO_2}\\) 气体分别通入下列三种溶液中，请描述现象并写出对应的化学方程式或离子方程式：(1) 酸化的 \\(\\mathrm{K_2Cr_2O_7}\\) 溶液；(2) 氯化钡溶液与 \\(3\\%\\ \\mathrm{H_2O_2}\\) 的混合液（活动20）；(3) 等体积混合 \\(\\mathrm{SO_2}\\) 与 \\(\\mathrm{Cl_2}\\) 后通入品红溶液。","given":"活动19–20 及 p.359 反应式","method":"逐一分析还原性、氧化钡沉淀生成与 Cl₂+SO₂ 反应失去漂白性","principle":"Cr₂O₇²⁻(橙)→Cr³⁺(绿)；H₂SO₃+H₂O₂→H₂SO₄；Cl₂+SO₂+2H₂O→H₂SO₄+2HCl。","steps":["(1) 溶液由**橙色变为绿色**：\\(\\mathrm{3SO_2 + K_2Cr_2O_7 + H_2SO_4 \\longrightarrow K_2SO_4 + Cr_2(SO_4)_3 + H_2O}\\)。","(2) 单独通入 \\(\\mathrm{BaCl_2}\\) 无明显沉淀，滴加 \\(\\mathrm{H_2O_2}\\) 后立刻产生不溶于稀盐酸的**白色沉淀 \\(\\mathrm{BaSO_4}\\)**：\\(\\mathrm{SO_2 + H_2O_2 + BaCl_2 \\longrightarrow BaSO_4\\downarrow + 2HCl}\\)。","(3) **品红溶液不褪色**：\\(\\mathrm{SO_2(g) + Cl_2(g) + 2H_2O(l) \\longrightarrow H_2SO_4(aq) + 2HCl(aq)}\\)，两者恰好反应生成无漂白性的硫酸和盐酸。"],"ans":"(1) 橙变绿；(2) 产生白色 BaSO₄↓；(3) 品红不褪色（方程式见步骤）。","markingPoints":["橙变绿现象与方程式（1.5分）","BaSO₄ 沉淀与双氧水氧化方程式（1.5分）","等比 Cl₂+SO₂ 失去漂白性解释与方程式（1.5分）"],"verification":"对照化上 p.358–359 确认。","pitfall":"第(3)题误以为“强强联合漂白加倍”。"},{"id":"chem14-14.6-q4","tier":"L4","tierLabel":"L4 统考压轴","examStyle":"P2 探究解释","q":"将一定量 \\(\\mathrm{SO_2}\\) 气体通入蒸馏水中制成亚硫酸（\\(\\mathrm{H_2SO_3}\\)）饱和溶液，先测其 pH 并取样滴加 \\(\\mathrm{BaCl_2}\\) 溶液，发现无沉淀生成。随后将该亚硫酸溶液敞口放置于空气中几天后，再测其 pH 并滴加 \\(\\mathrm{BaCl_2}\\) 溶液，发现 pH 明显减小且出现了不溶于稀盐酸的白色沉淀。请结合化学方程式完整解释上述变化过程，并说明这与自然界“酸雨酸度随时间加剧”之间的联系。","given":"思考题 14g 第2题（化上 p.368）","method":"利用 2H₂SO₃ + O₂ → 2H₂SO₄ 解释弱酸变强酸导致 pH 下降及 SO₄²⁻ 生成","principle":"H₂SO₃ 易被空气中 O₂ 氧化为强酸 H₂SO₄。","steps":["刚配制的亚硫酸是弱酸，仅部分电离，且 \\(\\mathrm{H_2SO_3}\\) 酸性弱于盐酸，无法与 \\(\\mathrm{BaCl_2}\\) 发生复分解生成 \\(\\mathrm{BaSO_3}\\) 沉淀（符合“强酸制弱酸”反向禁则）。","敞口放置空气中，亚硫酸缓慢被空气中的氧气氧化为强酸——硫酸：\\(\\mathrm{2H_2SO_3(aq) + O_2(g) \\longrightarrow 2H_2SO_4(aq)}\\)。","由于弱酸转化为完全电离的二元强酸，溶液中 \\(\\mathrm{H^+}\\) 浓度大幅增大，故 **pH 明显减小**；同时溶液中产生了大量 \\(\\mathrm{SO_4^{2-}}\\)，遇 \\(\\mathrm{BaCl_2}\\) 立刻生成既不溶于水也不溶于盐酸的白色 \\(\\mathrm{BaSO_4}\\) 沉淀。","这也正是雨水吸收 \\(\\mathrm{SO_2}\\) 形成亚硫酸后，在空气中氧化转化为硫酸型酸雨、酸度加剧的微观本质。"],"ans":"亚硫酸被空气中 O₂ 氧化为强酸 H₂SO₄（\\(\\mathrm{2H_2SO_3 + O_2 \\to 2H_2SO_4}\\)），H⁺ 浓度升高致 pH 减小，生成的 SO₄²⁻ 与 Ba²⁺ 生成 BaSO₄↓。","markingPoints":["指出初始 H₂SO₃ 为弱酸不能与 BaCl₂ 生成沉淀（1分）","写出 2H₂SO₃ + O₂ → 2H₂SO₄ 方程式（1.5分）","解释弱酸变强酸致 pH 减小及生成 BaSO₄↓ 与酸雨联系（1.5分）"],"verification":"对照化上 p.361 与 p.368 思考题 14g 第2题。","pitfall":"错以为是 CO₂ 溶解或水分蒸发导致 pH 减小，未点出 H₂SO₃ 被 O₂ 氧化成强酸 H₂SO₄ 这一根本原因。"}],"cheatSheet":["SO₂ 四大性质：酸性（SO₂+H₂O⇌H₂SO₃）、氧化性（SO₂+2H₂S→3S↓）、还原性（褪溴水、KMnO₄，橙 K₂Cr₂O₇ 变绿）、可逆漂白（品红褪色加热复红）。","SO₂ 不使紫色石蕊试液褪色（只变红）；不能用澄清石灰水鉴别 CO₂ 与 SO₂（选品红/溴水/KMnO₄）。","亚硫酸露置空气：2H₂SO₃ + O₂ → 2H₂SO₄，弱酸变强酸导致 pH 下降。"],"kbEntryIds":["kb-chem14-so2-bleach"],"quiz":{"q":"将 \\(\\mathrm{SO_2}\\) 气体分别通入品红溶液和紫红色酸性高锰酸钾溶液中，两者均褪色。如何通过简单实验证明两种褪色的化学本质完全不同？","given":"活动19 与 p.359–360","method":"对褪色后的两支试管分别进行加热操作","principle":"SO₂ 漂白品红为可逆化合（加热分解复红），而氧化还原反应不可逆。","steps":["分别加热两支褪色后的试管：原品红溶液受热后**恢复红色**（可逆化合漂白）；原高锰酸钾溶液受热后**不恢复紫色**（不可逆氧化还原反应）。"],"ans":"分别加热褪色后溶液：品红恢复红色（可逆漂白），高锰酸钾不恢复紫红色（氧化还原）。"}},{"id":"14.7","t":"硫酸","anchor":{"pages":"化上 p.363–368","syllabus":"3.8.7 浓硫酸三大特性（吸水性、脱水性、强氧化性）与接触法工业制硫酸","examScopes":["sem2_final","uec"],"examWeight":"UEC 最高频核心节（浓硫酸三大特性实验辨析 + 接触法三阶段工艺流程）","terms":"hygroscopicity · dehydration · passivation · Contact Process · oleum · vanadium(V) oxide","prerequisites":["二氧化硫的性质与三氧化硫生成（化上 Ch 14.6）","化学平衡移动与催化剂对反应速率的影响"],"goals":["掌握浓硫酸物理性质（98.3%，1840 kg m⁻³，bp 338℃）及“酸入水、沿壁慢倒不断搅拌”的正确稀释方法。","通过活动23–25 严格区分浓硫酸的吸水性、脱水性（蔗糖炭化）与强氧化性（钝化与热氧化 Cu、Fe、C、S）。","完整写出接触法制硫酸（图14-39）沸腾炉造气、接触室 V₂O₅ 催化氧化及吸收塔用 98.3% 浓硫酸吸收 SO₃ 的方程式与工艺理由。"]},"concepts":[{"kind":"definition","title":"稀硫酸强酸通性与浓硫酸稀释规范（活动22）","pageRef":"化上 p.364–365","body":["**物理性质与安全稀释**：纯硫酸是无色、无臭、不挥发油状液体，市售浓硫酸质量分数 **98.3%**，密度 **1840 kg m⁻³**（\\(1.84\\text{ g}\\cdot\\mathrm{cm^{-3}}\\)），沸点高达 **338℃**。稀释浓硫酸时因水合放出巨量热且浓硫酸密度大于水，**必须将浓硫酸沿容器壁慢慢倒入水中并不断搅拌散热**，严禁把水倒入浓硫酸（水浮在表面沸腾飞溅灼伤）。","**微粒差异决定性质差异**：稀硫酸中 \\(\\mathrm{H_2SO_4}\\) 完全电离为 \\(\\mathrm{H^+}\\) 和 \\(\\mathrm{SO_4^{2-}}\\)，仅体现强酸通性；而 98.3% 浓硫酸中主要以未电离的 **\\(\\mathrm{H_2SO_4}\\) 分子**形式存在，从而体现出独特的三大特性。"],"takeaway":"稀硫酸与活泼金属（Zn、Fe）反应生成 H₂（+1 价 H 得电子）；浓硫酸与金属加热则生成 SO₂（+6 价 S 得电子）。"},{"kind":"experiment","title":"活动23–25：浓硫酸三大特性（表14-11 吸水性 vs 脱水性 vs 强氧化性）","pageRef":"化上 p.365–366","body":["**① 吸水性（活动23，图14-37）**：浓硫酸投入蓝色胆矾（\\(\\mathrm{CuSO_4\\cdot 5H_2O}\\)），蓝色晶体脱水变为**白色粉末 \\(\\mathrm{CuSO_4}\\)**。本质是**吸收现成的游离水或结晶水**，可用作干燥剂（可干燥 \\(\\mathrm{H_2, O_2, CO_2, SO_2, Cl_2, HCl}\\)，不可干燥 \\(\\mathrm{NH_3, H_2S, HBr, HI}\\)）。","**② 脱水性（活动24“黑面包实验”）**：将浓硫酸加入湿润蔗糖（\\(\\mathrm{C_{12}H_{22}O_{11}}\\)）中搅拌，蔗糖迅速变黄变黑并剧烈膨胀成疏松多孔“黑面包”，同时放出刺激性气体使品红褪色。先发生**脱水炭化**（按 \\(\\mathrm{H:O = 2:1}\\) 夺取化合态氢氧元素）：\\(\\mathrm{C_{12}H_{22}O_{11}(s)} \\xrightarrow{\\text{浓硫酸}} \\mathrm{12C(s) + 11H_2O(l)}\\)，继而放出热量触发**强氧化性**：\\(\\mathrm{C + 2H_2SO_4(\\text{浓})} \\xrightarrow{\\Delta} \\mathrm{CO_2\\uparrow + 2SO_2\\uparrow + 2H_2O}\\)，生成气体导致碳块膨胀多孔！","**③ 强氧化性（活动25，图14-38）**：常温下浓硫酸使 **Fe、Al** 表面生成致密氧化膜而**钝化**（故可用铁制或铝制槽车贮运冷浓硫酸）；**加热条件下**可氧化除金、铂外绝大多数金属（\\(\\mathrm{Cu + 2H_2SO_4(\\text{浓})} \\xrightarrow{\\Delta} \\mathrm{CuSO_4 + SO_2\\uparrow + 2H_2O}\\)，\\(\\mathrm{2Fe + 6H_2SO_4(\\text{浓})} \\xrightarrow{\\Delta} \\mathrm{Fe_2(SO_4)_3 + 3SO_2\\uparrow + 6H_2O}\\)）及非金属 C、S。图14-38 装置中，乙试管品红褪色，试管口**浸有碱液的棉花**用于吸收有毒 \\(\\mathrm{SO_2}\\) 尾气；将甲试管冷却后溶液倒入水中呈蓝色（证明生成 \\(\\mathrm{Cu^{2+}}\\)）。"],"takeaway":"判断Cu+浓硫酸反应后甲试管中是否生成 Cu²⁺，必须等冷却后将甲中反应液“慢慢倒入水中”看溶液显蓝色，严禁直接往含大量残余浓硫酸的甲试管中加水！"},{"kind":"mechanism","title":"接触法（Contact Process）工业制硫酸三阶段工艺（图14-39）","pageRef":"化上 p.366–368","body":["**① 造气与净化**：沸腾炉内高温煅烧硫黄或黄铁矿（\\(\\mathrm{FeS_2}\\)）：\\(\\mathrm{S + O_2} \\xrightarrow{\\text{点燃}} \\mathrm{SO_2}\\) 或 \\(\\mathrm{4FeS_2(s) + 11O_2(g)} \\xrightarrow{\\text{高温}} \\mathrm{2Fe_2O_3(s) + 8SO_2(g)}\\)。黄铁矿原料气含砷（As）、硒（Se）化合物及矿尘水蒸气，**必须经过净化和干燥**，防止接触室内的催化剂中毒失效（燃烧硫黄制得气体已较纯净，可免净化）。","**② 接触催化氧化**：在 **400~500℃** 及催化剂**五氧化二钒（\\(\\mathrm{V_2O_5}\\)）**接触室内：\\(\\mathrm{2SO_2(g) + O_2(g)} \\underset{400\\sim 500\\ ^\\circ\\mathrm{C}}{\\stackrel{\\mathrm{V_2O_5}}{\\rightleftharpoons}} \\mathrm{2SO_3(g)}\\)（放热可逆反应，配套热交换器利用反应热预热进入接触室的原料气）。","**③ 吸收与二次转化**：工业上**严禁用纯水或稀硫酸直接吸收 \\(\\mathrm{SO_3}\\)**（反应剧烈放热易形成大量难以沉降的**酸雾**，大幅降低吸收率），而是用 **98.3% 浓硫酸**作吸收剂生成发烟硫酸（oleum）：\\(\\mathrm{SO_3(g) + H_2SO_4(l) \\to H_2SO_4\\cdot SO_3(l)}\\)，再加水稀释成商品浓硫酸：\\(\\mathrm{H_2SO_4\\cdot SO_3(l) + H_2O(l) \\to 2H_2SO_4(aq)}\\)。从吸收塔排出的含少量未反应 \\(\\mathrm{SO_2}\\) 的气体还需经过**二次氧化与二次吸收**并净化回收尾气，既节约原料又防止酸雨污染。"],"takeaway":"接触法四大高频考问：① 净化除 As/Se/尘（防 V₂O₅ 中毒）；② 热交换器（节能控温）；③ 98.3% 浓 H₂SO₄ 吸收 SO₃（防酸雾）；④ 二次转化吸收（提产率+环保）。"}],"diagrams":[{"src":"assets/fig/v2/chem14-s-contact.svg","caption":"图 14-1 接触法制硫酸三阶段工艺流程与浓硫酸吸水性、脱水性、强氧化性对比图","alt":"接触法制硫酸工业流程与浓硫酸特性图","pageRef":"化上 p.364–367"}],"formulas":[{"title":"浓硫酸的脱水炭化与强氧化反应方程式","tex":"\\mathrm{Cu + 2H_2SO_4(\\text{浓})} \\xrightarrow{\\Delta} \\mathrm{CuSO_4 + SO_2\\uparrow + 2H_2O},\\qquad \\mathrm{C + 2H_2SO_4(\\text{浓})} \\xrightarrow{\\Delta} \\mathrm{CO_2\\uparrow + 2SO_2\\uparrow + 2H_2O}","plain":"Cu + 2H2SO4(浓) --Δ--> CuSO4 + SO2 + 2H2O; C + 2H2SO4(浓) --Δ--> CO2 + 2SO2 + 2H2O","conditions":"需加热；Cu 反应中仅 1/2 的浓硫酸表现氧化性（另 1/2 表现酸性生成 CuSO₄），C 反应中浓硫酸全部表现氧化性","pageRef":"化上 p.366","note":"足量 Cu 与一定量浓硫酸加热反应时，浓硫酸变稀后反应立即停止（稀硫酸不与 Cu 反应），这与浓硝酸变稀仍可继续溶解铜截然不同！"},{"title":"接触法制硫酸三步核心反应式","tex":"\\mathrm{4FeS_2 + 11O_2} \\xrightarrow{\\text{高温}} \\mathrm{2Fe_2O_3 + 8SO_2},\\qquad \\mathrm{2SO_2 + O_2} \\underset{400\\sim 500\\ ^\\circ\\mathrm{C}}{\\stackrel{\\mathrm{V_2O_5}}{\\rightleftharpoons}} \\mathrm{2SO_3},\\qquad \\mathrm{SO_3 + H_2SO_4(\\text{浓}) \\longrightarrow H_2SO_4\\cdot SO_3}","plain":"4FeS2 + 11O2 -> 2Fe2O3 + 8SO2; 2SO2 + O2 ⇌ 2SO3; SO3 + H2SO4 -> H2SO4·SO3","conditions":"1 mol FeS₂ 理论上最多制得 2 mol H₂SO₄（硫原子守恒）","pageRef":"化上 p.366–367","note":"4 mol FeS₂ 煅烧消耗 11 mol O₂ 共转移 44 mol 电子，即每 1 mol FeS₂ 转移 11 mol 电子！"}],"pitfalls":[{"title":"混淆浓硫酸的“吸水性”和“脱水性”","wrong":"“浓硫酸使胆矾变白体现了脱水性；浓硫酸使蔗糖变黑体现了吸水性。”","diagnosis":"胆矾（\\(\\mathrm{CuSO_4\\cdot 5H_2O}\\)）内部本来就含有结晶水（\\(\\mathrm{H_2O}\\) 分子），被浓硫酸吸走；而蔗糖分子（\\(\\mathrm{C_{12}H_{22}O_{11}}\\)）里原本没有水分子。","right":"吸去现成的游离水或结晶水（湿气体、胆矾变白）是**吸水性**；把不含水分子的有机物（蔗糖、纸张、木屑、皮肤）按 \\(\\mathrm{H:O = 2:1}\\) 夺取化合态氢氧生成碳黑是**脱水性**。","checkRule":"原物质中“本来有 H₂O”→ 吸水性；原物质中“本来无 H₂O、反应后炭化变黑”→ 脱水性。"},{"title":"以为足量铜和一定量浓硫酸加热也能把硫酸完全耗尽","wrong":"“\\(0.10\\text{ mol}\\) 浓硫酸与足量铜片加热充分反应，能生成 \\(0.050\\text{ mol }\\mathrm{SO_2}\\)。”","diagnosis":"浓硫酸随反应消耗及生成水而浓度逐渐下降变成稀硫酸，而**稀硫酸在加热条件下也不能与铜反应**！","right":"足量铜与含 \\(0.10\\text{ mol}\\) 溶质的浓硫酸共热时，反应中途就会停止，实际生成 \\(\\mathrm{SO_2}\\) 的物质的量**一定小于 \\(0.050\\text{ mol}\\)**（同理足量 Zn 与浓硫酸先放 \\(\\mathrm{SO_2}\\)，变稀后转为放 \\(\\mathrm{H_2}\\)！）。","checkRule":"遇“浓硫酸 + Cu（或 MnO₂ + 浓 HCl）”算产气，只要金属/二氧化锰过量，实际产气必“小于”理论极限值。"}],"examples":[{"label":"例 14.7.1","tier":"L3","tierLabel":"L3 预试拔高","title":"金属与浓硫酸反应由浓变稀的气体分段计算","prompt":"将 \\(19.5\\text{ g}\\) 锌粉投入 \\(25.0\\text{ mL}\\) 浓度为 \\(16.0\\text{ mol}\\cdot\\mathrm{L^{-1}}\\) 的浓硫酸中并微热，反应结束后锌粉与硫酸恰好均无剩余。在标准状况下共收集到混合气体 \\(6.72\\text{ L}\\)。(1) 请说出收集到的混合气体中有哪两种气体，并写出各自生成的化学方程式；(2) 计算这两种气体在标准状况下的体积分别是多少升？（\\(\\mathrm{Zn}=65\\)）","clues":"锌（活泼金属）先与浓硫酸生 SO₂（1 mol Zn ↔ 1 mol SO₂，耗 2 mol H₂SO₄），浓硫酸变稀后继续与 Zn 反应生 H₂（1 mol Zn ↔ 1 mol H₂，耗 1 mol H₂SO₄）！","strategy":"设 n(SO₂)=x、n(H₂)=y，联立气体总数（或 Zn 守恒）与 H₂SO₄ 消耗总量方程求解。","given":"m(Zn)=19.5 g (0.30 mol)；n(H₂SO₄)=0.025 × 16.0 = 0.40 mol；V(总气, STP)=6.72 L (0.30 mol)","principle":"电子守恒（每 mol 气体均对应 1 mol Zn 失 2 mol e⁻）与酸耗量差异（生 SO₂ 耗 2 mol 酸，生 H₂ 耗 1 mol 酸）。","steps":["(1) 混合气体含 **\\(\\mathrm{SO_2}\\)** 和 **\\(\\mathrm{H_2}\\)**。前期浓硫酸表现强氧化性：\\(\\mathrm{Zn + 2H_2SO_4(\\text{浓})} \\xrightarrow{\\Delta} \\mathrm{ZnSO_4 + SO_2\\uparrow + 2H_2O}\\)；后期浓硫酸稀释为稀硫酸，氢离子体现氧化性：\\(\\mathrm{Zn + H_2SO_4(\\text{稀}) \\longrightarrow ZnSO_4 + H_2\\uparrow}\\)。","(2) 计算投料：\\(n(\\mathrm{Zn}) = \\frac{19.5}{65} = 0.30\\text{ mol}\\)，\\(n(\\mathrm{H_2SO_4}) = 0.025\\text{ L} \\times 16.0\\text{ mol}\\cdot\\mathrm{L^{-1}} = 0.40\\text{ mol}\\)。","设生成 \\(n(\\mathrm{SO_2}) = x\\text{ mol}\\)，\\(n(\\mathrm{H_2}) = y\\text{ mol}\\)。","由总气体（或 Zn 守恒）：\\(x + y = 0.30\\)；由硫酸恰好完全反应：\\(2x + y = 0.40\\)。","两式相减得：\\(x = 0.10\\text{ mol}\\ \\mathrm{SO_2}\\)，\\(y = 0.20\\text{ mol}\\ \\mathrm{H_2}\\)。","标准状况体积：\\(V(\\mathrm{SO_2}) = 0.10 \\times 22.4 = 2.24\\text{ L}\\)，\\(V(\\mathrm{H_2}) = 0.20 \\times 22.4 = 4.48\\text{ L}\\)。"],"answer":"(1) 含 \\(\\mathrm{SO_2}\\) 和 \\(\\mathrm{H_2}\\)；(2) \\(V(\\mathrm{SO_2}) = 2.24\\text{ L}\\)，\\(V(\\mathrm{H_2}) = 4.48\\text{ L}\\)。","markingPoints":["写出浓/稀硫酸分别与 Zn 反应的两条方程式（2分）","列出气体守恒与硫酸用量方程并解得 x=0.10, y=0.20 mol（2分）","算得体积 2.24 L 与 4.48 L（1分）"],"verification":"分步核验：0.10 mol Zn + 0.20 mol 浓硫酸 → 0.10 mol SO₂；0.20 mol Zn + 0.20 mol 稀硫酸 → 0.20 mol H₂，总 Zn 0.30 mol、总酸 0.40 mol、总气 0.30 mol (6.72 L)。","pitfall":"若认为浓硫酸与锌反应只生成 SO₂，则 0.40 mol 酸最多溶解 0.20 mol Zn（13.0 g），无法解释 19.5 g 锌全部溶解。"},{"label":"例 14.7.2","tier":"L4","tierLabel":"L4 统考压轴","title":"黄铁矿接触法制硫酸全流程产率与原料守恒计算","prompt":"某硫酸厂以含 \\(\\mathrm{FeS_2}\\) 质量分数为 \\(80\\%\\) 的黄铁矿为原料采用接触法生产硫酸。已知各步反应转化率分别为：沸腾炉煅烧 \\(\\mathrm{FeS_2}\\) 利用率为 \\(95\\%\\)，接触室 \\(\\mathrm{SO_2}\\) 氧化率为 \\(96\\%\\)，吸收塔 \\(\\mathrm{SO_3}\\) 吸收率为 \\(98\\%\\)。试求使用 \\(1.00\\text{ t}\\)（\\(1000\\text{ kg}\\)）该黄铁矿最终可生产质量分数为 \\(98\\%\\) 的浓硫酸多少吨？（\\(\\mathrm{Fe}=56,\\ \\mathrm{S}=32,\\ \\mathrm{H}=1,\\ \\mathrm{O}=16\\)）","clues":"1 mol FeS₂ 含 2 mol S，理论上最多生成 2 mol H₂SO₄！只需将总理论产率乘以三步转化率连乘积！","strategy":"建立关系式 FeS₂ ~ 2 H₂SO₄（120 kg ↔ 196 kg），代入矿石纯度 80% 与三步收率连乘。","given":"m(矿石)=1.00 t，纯度 80%，三步效率 95%、96%、98%，成品浓度 98%","principle":"硫原子守恒（FeS₂ ~ 2H₂SO₄）及多步反应总收率连乘法。","steps":["关系式：\\(\\mathrm{FeS_2 \\sim 2SO_2 \\sim 2SO_3 \\sim 2H_2SO_4}\\)，对应摩尔质量 \\(M(\\mathrm{FeS_2}) = 120\\text{ g}\\cdot\\mathrm{mol^{-1}}\\)，\\(2M(\\mathrm{H_2SO_4}) = 2 \\times 98 = 196\\text{ g}\\cdot\\mathrm{mol^{-1}}\\)。","参与有效转化的纯 \\(\\mathrm{FeS_2}\\) 质量：\\(m(\\mathrm{FeS_2}) = 1.00\\text{ t} \\times 80\\% \\times 95\\% = 0.760\\text{ t}\\)。","最终生成的纯 \\(\\mathrm{H_2SO_4}\\) 质量：\\(m_{\\text{纯}}(\\mathrm{H_2SO_4}) = 0.760\\text{ t} \\times \\frac{196}{120} \\times 96\\% \\times 98\\% \\approx 1.168\\text{ t}\\)。","换算成质量分数为 \\(98\\%\\) 的浓硫酸总质量：\\(m_{\\text{浓}} = \\frac{1.168\\text{ t}}{98\\%} = \\frac{0.760 \\times 196 \\times 0.96 \\times 0.98}{120 \\times 0.98} = 0.760 \\times \\frac{196}{120} \\times 0.96 \\approx 1.19\\text{ t}\\)。"],"answer":"可生产 \\(98\\%\\) 浓硫酸约 **1.19 吨**。","markingPoints":["正确建立 FeS₂ ~ 2H₂SO₄ 硫原子守恒关系（1分）","连乘 80%×95%×96%×98% 求出纯硫酸 1.168 t（2分）","除以成品浓度 98% 得浓硫酸 1.19 t（1分）"],"verification":"分子分母中 98% 恰好约去：\\(0.76 \\times 1.6333 \\times 0.96 = 1.1917\\text{ t}\\)，约 1.19 t！","pitfall":"最易犯两错：① 忘记 1 个 FeS₂ 含 **2 个**硫原子导致结果减半；② 漏除以成品浓硫酸质量分数 98%。"}],"practice":[{"id":"chem14-14.7-q1","tier":"L1","tierLabel":"L1 基础","examStyle":"P1 选择","q":"下列关于浓硫酸的叙述，正确的是（　）。","options":["A. 浓硫酸与铜片共热的反应中，浓硫酸既表现出强氧化性，又表现出酸性","B. 浓硫酸与活泼金属锌反应生成的气体一定是纯净的氢气","C. 常温下铁或铝不与浓硫酸反应，所以可用铁制或铝制容器贮存冷浓硫酸","D. 实验室可用浓硫酸与硫化铁(II)反应制取硫化氢气体"],"correctOption":"A","given":"思考题 14g 第1题（化上 p.368）","method":"逐项比对浓硫酸酸性、氧化性与钝化本质","principle":"Cu + 2H₂SO₄(浓) → CuSO₄（体现酸性） + SO₂↑（体现氧化性） + 2H₂O。","steps":["A 对：一半硫酸成盐体现酸性，一半被还原成 SO₂ 体现氧化性。","B 错：浓硫酸强氧化性初期生成 SO₂。","C 错：常温下冷浓硫酸使铁或铝表面发生**钝化**（生成致密氧化膜阻止继续反应），不是“不反应”。","D 错：H₂S 会被浓硫酸氧化析硫。"],"ans":"A","markingPoints":["理解浓硫酸兼具酸性与强氧化性并识别钝化陷阱"],"verification":"对照化上 p.368 思考题 14g 第1题。","pitfall":"极易被 C 项字面迷惑误选 C。"},{"id":"chem14-14.7-q2","tier":"L2","tierLabel":"L2 期末","examStyle":"P1 选择","q":"在下列实验现象中，主要体现浓硫酸**脱水性**的是（　）。","options":["A. 浓硫酸露置于空气中一段时间后质量增大、浓度降低","B. 浓硫酸加入蓝色胆矾晶体中，胆矾变为白色粉末","C. 浓硫酸滴在蔗糖上，蔗糖变黑并膨胀成疏松多孔海绵状固体","D. 浓硫酸作为干燥剂除去氧气和二氧化碳中的水蒸气"],"correctOption":"C","given":"活动23与活动24对比","method":"区分吸现成水（吸水性）与按 2:1 夺取有机物 H、O 炭化（脱水性）","principle":"蔗糖炭化是脱水性的标志反应。","steps":["A、B、D 均吸走本来就存在的 H₂O 分子，体现吸水性；C 中蔗糖炭化变黑主要体现脱水性（随后的膨胀放气体现强氧化性）。"],"ans":"C","markingPoints":["准确区分吸水性与脱水性实例"],"verification":"对照化上 p.365–366。","pitfall":"把胆矾变白误选为脱水性。"},{"id":"chem14-14.7-q3","tier":"L3","tierLabel":"L3 预试","examStyle":"P2 工业流程","q":"接触法工业制硫酸包括造气、催化氧化和吸收三大步骤（图14-39）。请回答以下三个关键工艺问题：(1) 若用黄铁矿造气，进入接触室前为什么必须进行净化和干燥处理？(2) 在接触室催化氧化阶段，写出反应方程式并说明工业选用 \\(400\\sim 500\\ ^\\circ\\mathrm{C}\\) 与常压 \\(\\mathrm{V_2O_5}\\) 催化的原因；(3) 在吸收塔中，为什么用 \\(98.3\\%\\) 浓硫酸而不用水直接吸收 \\(\\mathrm{SO_3}\\)？","given":"接触法工艺细节（化上 p.366–367）","method":"围绕防催化剂中毒、兼顾速率活性转化率、防酸雾三点精答","principle":"工业化学工艺优化三核心原则：保护催化剂、动力学与热力学平衡兼顾、提高吸收传质效率。","steps":["(1) 原料气含砷（As）、硒（Se）化合物及矿尘会导致接触室内催化剂 \\(\\mathrm{V_2O_5}\\) **中毒**失活，水蒸气则会腐蚀设备并影响催化生产，故必须净化干燥。","(2) \\(\\mathrm{2SO_2(g) + O_2(g)} \\underset{400\\sim 500\\ ^\\circ\\mathrm{C}}{\\stackrel{\\mathrm{V_2O_5}}{\\rightleftharpoons}} \\mathrm{2SO_3(g)}\\)。选用 \\(400\\sim 500\\ ^\\circ\\mathrm{C}\\) 是因为此温度下 \\(\\mathrm{V_2O_5}\\) 催化剂活性最高，既能保证较高反应速率，又不致使放热可逆平衡过度左移（常压下转化率已达 90% 以上）。","(3) \\(\\mathrm{SO_3}\\) 直接与水反应剧烈放热，会使水汽化并在塔内形成大量难以被吸收的**酸雾**，大幅降低吸收效率；改用 \\(98.3\\%\\) 浓硫酸吸收生成发烟硫酸 \\(\\mathrm{H_2SO_4\\cdot SO_3}\\)（几乎无酸雾），吸收率极高。"],"ans":"(1) 防 As/Se/尘使催化剂中毒及水汽腐蚀设备；(2) 方程式见步骤，400~500℃ 是 V₂O₅ 最佳活性温度兼顾速率与平衡；(3) 防止形成大量酸雾阻碍吸收。","markingPoints":["答出防催化剂中毒与防腐蚀（1.5分）","写对反应式并解释 V₂O₅ 最佳活性温度（1.5分）","答出用水易形成酸雾降低吸收率（1.5分）"],"verification":"对照化上 p.367 原文核验。","pitfall":"第(3)问只答“会放热爆炸”，未写关键字“酸雾”。"},{"id":"chem14-14.7-q4","tier":"L4","tierLabel":"L4 统考压轴","examStyle":"P2 实验探究","q":"某同学利用教材图14-38 装置进行“铜与浓硫酸反应”实验（甲试管装铜片和 \\(3\\text{ mL}\\) 浓硫酸加热，乙试管盛品红溶液，乙管口塞浸有碱液的棉花）。(1) 实验结束冷却后，该同学观察到甲试管底部有少量白色固体析出，溶液中似乎不是蓝色而是呈灰白色浑浊。如何用实验证明甲试管中确实生成了 \\(\\mathrm{Cu^{2+}}\\)？写出正确操作及注意安全事项；(2) 乙试管管口棉花所浸碱液的作用是什么？写出对应化学方程式。","given":"活动25 铜与浓硫酸反应（化上 p.365–366）","method":"利用浓硫酸吸水导致无水 CuSO₄ 白色固体析出，冷却后“把甲内液体缓慢倒入盛水烧杯”看显蓝色","principle":"浓硫酸吸水性与稀释放热安全操作；碱液吸收 SO₂ 尾气。","steps":["(1) 甲中生成的硫酸铜在浓硫酸强吸水性环境下以白色无水 \\(\\mathrm{CuSO_4}\\) 固体析出。验证操作：待甲试管**冷却至室温**后，小心将甲试管内混合液**沿着烧杯内壁慢慢倒入盛有少量蒸馏水的烧杯中**并不断搅拌（**严禁直接向甲试管中加水**，以防残留浓硫酸遇水剧烈放热沸腾飞溅），观察到烧杯中形成**蓝色溶液**，即可证明生成了 \\(\\mathrm{Cu^{2+}}\\)。","(2) 浸有碱液（如 \\(\\mathrm{NaOH}\\)）的棉花用于**吸收逸出的有毒 \\(\\mathrm{SO_2}\\) 气体，防止污染实验室空气**：\\(\\mathrm{SO_2(g) + 2NaOH(aq) \\longrightarrow Na_2SO_3(aq) + H_2O(l)}\\)。"],"ans":"(1) 冷却后把甲中液体慢慢倒入水中搅拌，溶液变蓝；严禁直接向试管加水；(2) 吸收有毒 SO₂ 尾气防污染，\\(\\mathrm{SO_2 + 2NaOH \\to Na_2SO_3 + H_2O}\\)。","markingPoints":["说明白色固体因浓硫酸吸水成无水 CuSO₄（1分）","强调“冷却后将酸慢倒入水中”安全规范并变蓝（2分）","说明尾气吸收作用及方程式（1.5分）"],"verification":"对照化上 p.364–365 稀释规范与活动25装置图。","pitfall":"若答“反应后直接向甲试管中加少量水溶解白色沉淀”必扣操作安全分！"}],"cheatSheet":["稀释浓硫酸：酸入水、沿器壁、慢倾倒、不断搅。","三大特性速判：胆矾变白=吸水性；蔗糖变黑=脱水性（后膨胀产气=强氧化性）；常温 Fe/Al 钝化、热溶 Cu/C/S=强氧化性。","接触法三阶段：沸腾炉造气净化（防 V₂O₅ 中毒）→ 接触室 V₂O₅/400~500℃ → 98.3% 浓硫酸吸收（防酸雾）+ 二次转化。"],"kbEntryIds":["kb-chem14-h2so4-props","kb-chem14-contact-process"],"quiz":{"q":"将 \\(12.8\\text{ g}\\) 铜片放入盛有含 \\(0.40\\text{ mol}\\) 溶质的浓硫酸中持续加热，充分反应后发现铜片还有剩余。此时在标准状况下产生的 \\(\\mathrm{SO_2}\\) 气体体积是否等于 \\(4.48\\text{ L}\\)？为什么？","given":"n(Cu)=0.20 mol，n(H₂SO₄)=0.40 mol","method":"考虑浓硫酸随反应进行变稀后停止与 Cu 反应","principle":"稀硫酸在加热下也不与铜反应。","steps":["理论上若 \\(0.40\\text{ mol}\\) 浓硫酸完全按 \\(\\mathrm{Cu + 2H_2SO_4(\\text{浓}) \\to CuSO_4 + SO_2\\uparrow + 2H_2O}\\) 耗尽，生成 \\(0.20\\text{ mol}\\ \\mathrm{SO_2}\\)（\\(4.48\\text{ L}\\)）。","但随着反应消耗和生成水，浓硫酸浓度下降变为稀硫酸，稀硫酸不再与铜反应，故实际产气**小于 \\(4.48\\text{ L}\\)**。"],"ans":"不等于，实际生成 SO₂ **小于 4.48 L**（浓硫酸变稀后反应停止）。"}},{"id":"14.8","t":"硫酸盐","anchor":{"pages":"化上 p.368–371","syllabus":"3.8.8 硫酸根的检验（活动26）与重要硫酸盐（石膏、重晶石、绿矾）","examScopes":["sem2_final","uec"],"examWeight":"P1 离子检验正误判断 + P2 硫酸根检验探究题及硫酸钡重量分析计算","terms":"barium sulphate · gypsum · plaster of Paris · barite · green vitriol","prerequisites":["溶解性规律（难溶钡盐：BaSO₄、BaCO₃、BaSO₃）","酸与碳酸盐/亚硫酸盐反应放气（化上 Ch 14.6）"],"goals":["通过活动26（表14-12）阐述检验 SO₄²⁻ 必须“先加足量稀盐酸酸化无现象、再滴加 BaCl₂ 溶液”的原理，并排除 Ag⁺、CO₃²⁻、SO₃²⁻ 干扰。","明确禁止用稀硝酸酸化或硝酸钡溶液来检验亚硫酸根可能共存体系中的硫酸根。","熟记生石膏/熟石膏转化、重晶石（BaSO₄ 钡餐）及绿矾（FeSO₄·7H₂O）的化学式与工农业医学用途。"]},"concepts":[{"kind":"experiment","title":"活动26：硫酸根（SO₄²⁻）检验标准步骤与干扰排除（表14-12）","pageRef":"化上 p.368–369","body":["**为什么不能直接加 \\(\\mathrm{BaCl_2}\\)（活动26）？**因为 \\(\\mathrm{CO_3^{2-}}\\)、\\(\\mathrm{SO_3^{2-}}\\)（以及 \\(\\mathrm{Ag^+}\\)）都能与 \\(\\mathrm{BaCl_2}\\) 产生白色沉淀（\\(\\mathrm{BaCO_3\\downarrow}\\)、\\(\\mathrm{BaSO_3\\downarrow}\\) 或 \\(\\mathrm{AgCl\\downarrow}\\)）。","**加稀盐酸对比结果（表14-12）**：① 稀硫酸 / \\(\\mathrm{Na_2SO_4}\\) + \\(\\mathrm{BaCl_2}\\) → 生成白色 \\(\\mathrm{BaSO_4}\\) 沉淀，再加稀盐酸**沉淀不溶解**；② \\(\\mathrm{Na_2CO_3}\\) + \\(\\mathrm{BaCl_2}\\) → 白色 \\(\\mathrm{BaCO_3}\\) 沉淀，加稀盐酸**溶解并放出无色无味 \\(\\mathrm{CO_2}\\)**；③ \\(\\mathrm{Na_2SO_3}\\) + \\(\\mathrm{BaCl_2}\\) → 白色 \\(\\mathrm{BaSO_3}\\) 沉淀，加稀盐酸**溶解并放出刺激性 \\(\\mathrm{SO_2}\\)**。","**实验室最严谨标准操作**：先向待测液中加入**足量稀盐酸酸化**（若无沉淀也无气泡，既彻底除去 \\(\\mathrm{CO_3^{2-}}\\)、\\(\\mathrm{SO_3^{2-}}\\)，又排除了 \\(\\mathrm{Ag^+}\\)），再滴加 \\(\\mathrm{BaCl_2}\\) 溶液，若出现白色沉淀，必含 \\(\\mathrm{SO_4^{2-}}\\)！"],"takeaway":"禁止用稀硝酸（HNO₃）或 Ba(NO₃)₂ 检验 SO₄²⁻：如果原溶液含 SO₃²⁻（不含 SO₄²⁻），HNO₃ 会把 BaSO₃ 或 SO₃²⁻ 氧化成不溶的 BaSO₄ 白色沉淀造成假阳性！"},{"kind":"table","title":"三种重要硫酸盐（石膏、重晶石、绿矾）性质与用途","pageRef":"化上 p.369–370","body":["一般硫酸盐易溶于水，但硫酸银（\\(\\mathrm{Ag_2SO_4}\\)）、硫酸钙（\\(\\mathrm{CaSO_4}\\)）微溶，**硫酸钡（\\(\\mathrm{BaSO_4}\\)）和硫酸铅（\\(\\mathrm{PbSO_4}\\)）难溶**。可溶性硫酸盐结晶时常带结晶水。"],"table":{"headers":["俗称 / 矿物名","化学式","物理特征 / 转化","主要工农业与医药用途"],"rows":[["生石膏（gypsum）","\\(\\mathrm{CaSO_4\\cdot 2H_2O}\\)","白色固体；150~170℃ 脱水变为熟石膏","调节水泥凝固时间；制粉笔、石膏模型"],["熟石膏（plaster）","\\(\\mathrm{2CaSO_4\\cdot H_2O}\\)","与水混成糊状后迅速水化凝固变回生石膏","医疗骨折固定用**石膏绷带**、雕塑模型"],["重晶石（barite）","\\(\\mathrm{BaSO_4}\\)","白色重质晶体，既不溶于水也不溶于酸，**不透 X 射线**","医疗胃肠 X 射线检查内服“**钡餐**”；白色颜料"],["绿矾（green vitriol）","\\(\\mathrm{FeSO_4\\cdot 7H_2O}\\)","浅绿色晶体（图14-42），易溶于水","医疗补血剂；净水剂；工业制铁红（\\(\\mathrm{Fe_2O_3}\\)）；农业杀害虫"]]},"takeaway":"虽然重金属 Ba²⁺ 有剧毒，但 BaSO₄ 既难溶于水又难溶于胃酸（HCl），不会被人体吸收，因此作“钡餐”；误服可溶性 BaCl₂ 或 BaCO₃（溶于胃酸！）则剧毒致死！"},{"kind":"mechanism","title":"常见硫酸盐溶解性分级与重晶石医用安全机理","pageRef":"化上 p.368–370","body":["**溶解性分级规律（参考附录2）**：绝大多数硫酸盐易溶于水（如 \\(\\mathrm{Na_2SO_4}\\)、\\(\\mathrm{CuSO_4}\\)、\\(\\mathrm{MgSO_4}\\)、\\(\\mathrm{FeSO_4}\\)），\\(\\mathrm{CaSO_4}\\) 与 \\(\\mathrm{Ag_2SO_4}\\) 微溶于水，而 **\\(\\mathrm{BaSO_4}\\) 和 \\(\\mathrm{PbSO_4}\\) 既难溶于水又难溶于强酸**。","**钡餐安全机理 vs 误服解毒**：可溶性重金属离子 \\(\\mathrm{Ba^{2+}}\\) 有剧毒，但 \\(\\mathrm{BaSO_4}\\) 不溶于胃酸（\\(\\mathrm{HCl}\\)），可安全作为胃肠 X 射线检查内服造影剂；而 \\(\\mathrm{BaCO_3}\\) 虽也难溶于水，却会与胃酸反应（\\(\\mathrm{BaCO_3(s) + 2H^+(aq) \\to Ba^{2+}(aq) + H_2O(l) + CO_2(g)\\uparrow}\\)）释放有毒 \\(\\mathrm{Ba^{2+}}\\)。若误服 \\(\\mathrm{BaCl_2}\\) 或 \\(\\mathrm{BaCO_3}\\)，可服用 \\(\\mathrm{Na_2SO_4}\\) 或 \\(\\mathrm{MgSO_4}\\) 溶液使其转化为无毒难溶的 \\(\\mathrm{BaSO_4}\\) 沉淀解毒。"],"takeaway":"记住安全判据：X 射线“钡餐”只能用既不溶水也不溶胃酸的 \\(\\mathrm{BaSO_4}\\)，绝不能用 \\(\\mathrm{BaCO_3}\\)！"}],"formulas":[{"title":"硫酸根检验与碳酸钡/亚硫酸钡干扰消除离子方程式","tex":"\\mathrm{Ba^{2+}(aq) + SO_4^{2-}(aq) \\longrightarrow BaSO_4(s)\\downarrow},\\qquad \\mathrm{BaSO_3(s) + 2H^+(aq) \\longrightarrow Ba^{2+}(aq) + H_2O(l) + SO_2(g)\\uparrow}","plain":"Ba^2+ + SO4^2- -> BaSO4↓; BaSO3 + 2H+ -> Ba^2+ + H2O + SO2↑","conditions":"先用稀盐酸酸化排除 CO₃²⁻、SO₃²⁻ 与 Ag⁺ 干扰","pageRef":"化上 p.369","note":"对比：BaCO₃(s) + 2H⁺(aq) → Ba²⁺(aq) + H₂O(l) + CO₂(g)↑。"},{"title":"生石膏与熟石膏可逆水化/脱水反应","tex":"\\mathrm{2(CaSO_4\\cdot 2H_2O)(s)} \\underset{\\text{加水凝固}}{\\stackrel{150\\sim 170\\ ^\\circ\\mathrm{C}}{\\rightleftharpoons}} \\mathrm{2CaSO_4\\cdot H_2O(s) + 3H_2O(g)}","plain":"2(CaSO4·2H2O) --150~170℃--> 2CaSO4·H2O + 3H2O","conditions":"加热温度不宜过高，否则变成全脱水无水 CaSO₄（死烧石膏失去凝结力）","pageRef":"化上 p.369","note":"医疗石膏绷带利用的正是熟石膏吸水重新变为结晶交织的生石膏而硬化定型。"}],"pitfalls":[{"title":"使用稀硝酸酸化或硝酸钡检验硫酸根（思考题 14h 第1题 A vs C）","wrong":"“向待测液中加入用稀硝酸酸化的 \\(\\mathrm{Ba(NO_3)_2}\\) 溶液出现白色沉淀，说明原溶液一定含 \\(\\mathrm{SO_4^{2-}}\\)。”","diagnosis":"若原溶液仅含 \\(\\mathrm{SO_3^{2-}}\\)（如 \\(\\mathrm{Na_2SO_3}\\)），酸化的 \\(\\mathrm{NO_3^-}\\) 会迅速将 \\(\\mathrm{SO_3^{2-}}\\) 氧化为 \\(\\mathrm{SO_4^{2-}}\\)，继而生成同样不溶于酸的白色 \\(\\mathrm{BaSO_4}\\) 沉淀！此外，若含 \\(\\mathrm{Ag^+}\\)，后加 \\(\\mathrm{HCl}\\) 也会生成白色 \\(\\mathrm{AgCl}\\) 沉淀！","right":"唯有**“先加入足量稀盐酸无明显现象，再加入 \\(\\mathrm{BaCl_2}\\) 溶液出现白色沉淀”**（思考题 14h 第1题 C），才能百分之百排除 \\(\\mathrm{Ag^+},\\ \\mathrm{CO_3^{2-}},\\ \\mathrm{SO_3^{2-}}\\) 的全部干扰！","checkRule":"检验 \\(\\mathrm{SO_4^{2-}}\\) 顺序死记：**先 HCl（无现象）→ 后 BaCl₂（白沉）**，绝对排斥 \\(\\mathrm{HNO_3}\\) 和先加 \\(\\mathrm{BaCl_2}\\)！"},{"title":"误把碳酸钡当作胃肠检查“钡餐”","wrong":"“碳酸钡也是白色难溶于水的固体，同样可用作胃肠 X 射线检查的内服钡餐。”","diagnosis":"人体胃液中含有大量盐酸（胃酸），\\(\\mathrm{BaCO_3 + 2HCl \\to BaCl_2 + H_2O + CO_2\\uparrow}\\)，生成可溶性有毒 \\(\\mathrm{Ba^{2+}}\\) 导致重金属中毒。","right":"只有**硫酸钡（\\(\\mathrm{BaSO_4}\\)）**既难溶于水又难溶于胃酸（HCl），才能安全用作“钡餐”。","checkRule":"误食可溶钡盐（或 \\(\\mathrm{BaCO_3}\\)）急救可服用硫酸钠（\\(\\mathrm{Na_2SO_4}\\)）或硫酸镁溶液，转化成无毒沉淀 \\(\\mathrm{BaSO_4}\\)。"}],"examples":[{"label":"例 14.8.1","tier":"L2","tierLabel":"L2 校内期末","title":"四种无色钠盐溶液实验鉴别（思考题 14h 第2题）","prompt":"实验室有失去标签的四瓶无色溶液：\\(\\mathrm{NaCl}\\)、\\(\\mathrm{Na_2SO_4}\\)、\\(\\mathrm{NaNO_3}\\)、\\(\\mathrm{Na_2CO_3}\\)。请设计最简便可靠的实验方案将它们一一鉴别出来，写出操作步骤、现象和对应离子方程式。","clues":"分别检出 CO₃²⁻（稀酸冒气泡）、SO₄²⁻（BaCl₂/稀盐酸不溶白沉）、Cl⁻（AgNO₃/稀硝酸不溶白沉），余下无现象即 NaNO₃（或用棕色环验证）！","strategy":"分取少量四份样本，依次用“稀硝酸（检 CO₃²⁻）→ 硝酸钡（检 SO₄²⁻）→ 硝酸银（检 Cl⁻）”逐级排除；或者先用 BaCl₂+稀盐酸 + AgNO₃ 组合。","given":"四种溶液：NaCl, Na₂SO₄, NaNO₃, Na₂CO₃","principle":"CO₃²⁻ 遇酸放 CO₂；SO₄²⁻ 遇 Ba²⁺ 生不溶于酸白沉；Cl⁻ 遇 Ag⁺ 生不溶于酸白沉。","steps":["① 分别取少量四种溶液于四支洁净试管中，各滴加足量**稀硝酸**：有**无色无味气泡**产生的是 \\(\\mathrm{Na_2CO_3}\\)（\\(\\mathrm{CO_3^{2-} + 2H^+ \\to H_2O + CO_2\\uparrow}\\)）。","② 另取剩余三种未冒气泡的溶液少量，分别滴加 **\\(\\mathrm{Ba(NO_3)_2}\\) 溶液**（此时溶液不含亚硫酸根且已酸化无碳酸根干扰）：产生白色沉淀的是 \\(\\mathrm{Na_2SO_4}\\)（\\(\\mathrm{Ba^{2+} + SO_4^{2-} \\to BaSO_4\\downarrow}\\)）。","③ 另取最后两种溶液少量（未事先加盐酸引入 Cl⁻！），分别滴加 **\\(\\mathrm{AgNO_3}\\) 溶液**和几滴稀硝酸：产生不溶白色沉淀的是 \\(\\mathrm{NaCl}\\)（\\(\\mathrm{Ag^+ + Cl^- \\to AgCl\\downarrow}\\)）；无明显现象的是 \\(\\mathrm{NaNO_3}\\)（可进一步用棕色环实验验证 \\(\\mathrm{NO_3^-}\\)）。"],"answer":"依次用稀硝酸（鉴出 Na₂CO₃）、Ba(NO₃)₂（鉴出 Na₂SO₄）、AgNO₃/稀硝酸（鉴出 NaCl，余下为 NaNO₃）。","markingPoints":["明确先用稀硝酸或稀盐酸排除并鉴出 CO₃²⁻（1.5分）","特别注意检 Cl⁻ 时另取原液（不可用已加过 BaCl₂ 或 HCl 的溶液）加 AgNO₃（1.5分）","正确写出三个离子方程式（1分）"],"verification":"另取新样本加 AgNO₃ 是关键规范，避免前面加 BaCl₂ 或稀盐酸引入外源 Cl⁻ 导致 NaNO₃ 出现假白沉！","pitfall":"若同一支试管里加了 HCl 或 BaCl₂ 后紧接着直接滴 AgNO₃ 检验 Cl⁻，必然导致全部都出 AgCl 白沉而误判！"},{"label":"例 14.8.2","tier":"L4","tierLabel":"L4 统考压轴","title":"硫酸钡重量分析法测定工业硫酸钠样品纯度","prompt":"某工业硫酸钠（\\(\\mathrm{Na_2SO_4}\\)）样品中混有少量氯化钠（\\(\\mathrm{NaCl}\\)）杂质。称取 \\(5.00\\text{ g}\\) 该样品溶于适量蒸馏水中，先加足量稀盐酸酸化，再滴加过量 \\(\\mathrm{BaCl_2}\\) 溶液至不再产生沉淀。将沉淀过滤、洗涤、烘干至恒重，称得白色 \\(\\mathrm{BaSO_4}\\) 固体质量为 \\(4.66\\text{ g}\\)。(1) 检验沉淀是否“洗涤干净”的实验操作方法是什么？(2) 计算该工业硫酸钠样品的纯度（\\(\\mathrm{Na_2SO_4}\\) 的质量分数）。（\\(\\mathrm{Na}=23,\\ \\mathrm{S}=32,\\ \\mathrm{O}=16,\\ \\mathrm{Ba}=137\\)）","clues":"M(BaSO₄) = 233 g/mol，M(Na₂SO₄) = 142 g/mol；洗涤干净标准是最后一次洗涤液不含 Cl⁻！","strategy":"用 AgNO₃ 溶液检验最后一次洗涤液是否含 Cl⁻；由 n(BaSO₄) 等于 n(Na₂SO₄) 求纯度。","given":"m(样品)=5.00 g，m(BaSO₄)=4.66 g","principle":"硫元素守恒 n(Na₂SO₄) = n(BaSO₄)；洗液 Cl⁻ 检验。","steps":["(1) 沉淀表面吸附的主要杂质离子是 \\(\\mathrm{Cl^-}\\)（及过量 \\(\\mathrm{Ba^{2+}}\\)）。检验方法：取**最后一次洗涤滤液**少量于试管中，滴加几滴 **\\(\\mathrm{AgNO_3}\\) 溶液**（及稀硝酸），若**无白色沉淀生成**，说明沉淀已洗涤干净。","(2) 计算 \\(\\mathrm{BaSO_4}\\) 的物质的量：\\(n(\\mathrm{BaSO_4}) = \\frac{4.66\\text{ g}}{233\\text{ g}\\cdot\\mathrm{mol^{-1}}} = 0.0200\\text{ mol}\\)。","由硫酸根守恒：\\(n(\\mathrm{Na_2SO_4}) = 0.0200\\text{ mol}\\)，故 \\(m(\\mathrm{Na_2SO_4}) = 0.0200 \\times 142 = 2.84\\text{ g}\\)。","样品纯度：\\(w(\\mathrm{Na_2SO_4}) = \\frac{2.84\\text{ g}}{5.00\\text{ g}} \\times 100\\% = 56.8\\%\\)。"],"answer":"(1) 取最后一次洗涤液加 AgNO₃ 溶液无白色沉淀；(2) 纯度为 \\(56.8\\%\\)。","markingPoints":["准确写出取最后一次洗涤液加 AgNO₃ 检验 Cl⁻ 的规范（2分）","求得 n(BaSO₄)=0.0200 mol 及 m(Na₂SO₄)=2.84 g（1.5分）","算得纯度 56.8%（0.5分）"],"verification":"杂质 NaCl 质量为 \\(5.00 - 2.84 = 2.16\\text{ g}\\)；若沉淀未洗净表面吸附了 NaCl 或 BaCl₂，会导致称得沉淀偏重、结果偏高。","pitfall":"若检验洗净时错用“稀硫酸看是否有白沉”，虽能检 Ba²⁺ 但用错沉淀试剂易丢掉常用标准答案分；AgNO₃ 检 Cl⁻ 最灵敏通用。"}],"practice":[{"id":"chem14-14.8-q1","tier":"L1","tierLabel":"L1 基础","examStyle":"P1 选择","q":"下列检验某无色未知溶液中是否含有 \\(\\mathrm{SO_4^{2-}}\\) 的操作方法，最严谨正确的是（　）。","options":["A. 加入用稀硝酸酸化的 \\(\\mathrm{Ba(NO_3)_2}\\) 溶液，出现白色沉淀，说明一定有 \\(\\mathrm{SO_4^{2-}}\\)","B. 直接加入 \\(\\mathrm{BaCl_2}\\) 溶液，出现白色沉淀，说明一定有 \\(\\mathrm{SO_4^{2-}}\\)","C. 先加入足量稀盐酸无明显现象，再加入 \\(\\mathrm{BaCl_2}\\) 溶液出现白色沉淀，说明一定有 \\(\\mathrm{SO_4^{2-}}\\)","D. 先加入 \\(\\mathrm{BaCl_2}\\) 溶液产生白色沉淀，再加入稀盐酸沉淀不溶解，说明一定有 \\(\\mathrm{SO_4^{2-}}\\)"],"correctOption":"C","given":"思考题 14h 第1题（化上 p.370）","method":"逐项排除 Ag⁺、CO₃²⁻、SO₃²⁻ 干扰","principle":"先加足量稀盐酸无现象可同时排除 Ag⁺（若含则先出 AgCl↓）、CO₃²⁻ 和 SO₃²⁻。","steps":["A 错：稀硝酸会把 SO₃²⁻ 氧化成 SO₄²⁻ 产生假阳性；","B 错：CO₃²⁻、SO₃²⁻、Ag⁺ 均会与 BaCl₂ 生白沉；","D 错：若原溶液含 Ag⁺ 而不含 SO₄²⁻，加 BaCl₂ 生 AgCl 白色沉淀，再加稀盐酸同样不溶解，易误判！","C 对：唯一严密无懈可击的检验顺序。"],"ans":"C","markingPoints":["掌握先 HCl 无现象再加 BaCl₂ 检验顺序"],"verification":"对照化上 p.370 思考题 14h 第1题。","pitfall":"D 项极具迷惑性，90% 学生常忽略 Ag⁺ + Cl⁻ → AgCl↓ 也不溶于稀盐酸的干扰！"},{"id":"chem14-14.8-q2","tier":"L2","tierLabel":"L2 期末","examStyle":"P1 选择","q":"关于重要硫酸盐的用途和性质，下列说法**错误**的是（　）。","options":["A. 生石膏 \\(\\mathrm{CaSO_4\\cdot 2H_2O}\\) 加热至 \\(150\\sim 170\\ ^\\circ\\mathrm{C}\\) 变为熟石膏 \\(\\mathrm{2CaSO_4\\cdot H_2O}\\)","B. 医用“钡餐”的主要成分是碳酸钡（\\(\\mathrm{BaCO_3}\\)）","C. 七水合硫酸亚铁（\\(\\mathrm{FeSO_4\\cdot 7H_2O}\\)）俗称绿矾，可用于制作补血剂和净水剂","D. 石膏在水泥工业中可用于调节水泥的凝固时间"],"correctOption":"B","given":"化上 p.369–370 重要硫酸盐","method":"对照重晶石成分及耐酸特性","principle":"重晶石 BaSO₄ 不溶于胃酸且不透 X 射线，故作钡餐；BaCO₃ 溶于胃酸致毒。","steps":["B 错：医用钡餐成分是硫酸钡（\\(\\mathrm{BaSO_4}\\)），绝不可用碳酸钡。"],"ans":"B","markingPoints":["区分 BaSO₄ 与 BaCO₃ 胃酸溶解性"],"verification":"对照化上 p.370。","pitfall":"把钡盐的毒性记忆混为一谈。"},{"id":"chem14-14.8-q3","tier":"L3","tierLabel":"L3 预试","examStyle":"P2 简答","q":"某溶液可能同时含有 \\(\\mathrm{CO_3^{2-}}\\)、\\(\\mathrm{SO_3^{2-}}\\) 和 \\(\\mathrm{SO_4^{2-}}\\) 中的一种或几种。某同学取少量该溶液加入 \\(\\mathrm{BaCl_2}\\) 溶液，产生大量白色沉淀，随后向沉淀中加入足量稀盐酸。(1) 若观察到沉淀**部分溶解**并放出具有刺激性气味的气体（不含 \\(\\mathrm{CO_2}\\)），判断原溶液中一定存在哪些阴离子？(2) 写出滴加稀盐酸时沉淀部分溶解的离子方程式。","given":"活动26 表14-12 沉淀溶解与气体现象分析","method":"沉淀部分溶解=既有不溶的 BaSO₄ 又有溶于酸的 BaCO₃/BaSO₃；刺激性气味（不含 CO₂）锁定 SO₃²⁻","principle":"BaSO₄ 不溶酸；BaSO₃ 溶酸放刺激性 SO₂ 气体。","steps":["(1) 原溶液中一定同时存在 **\\(\\mathrm{SO_4^{2-}}\\)**（对应不溶于稀盐酸的 \\(\\mathrm{BaSO_4}\\) 残余白色沉淀）和 **\\(\\mathrm{SO_3^{2-}}\\)**（对应溶酸放出刺激性 \\(\\mathrm{SO_2}\\) 气体的 \\(\\mathrm{BaSO_3}\\) 沉淀），不含 \\(\\mathrm{CO_3^{2-}}\\)。","(2) 离子方程式：\\(\\mathrm{BaSO_3(s) + 2H^+(aq) \\longrightarrow Ba^{2+}(aq) + H_2O(l) + SO_2(g)\\uparrow}\\)。"],"ans":"(1) 一定存在 \\(\\mathrm{SO_4^{2-}}\\) 和 \\(\\mathrm{SO_3^{2-}}\\)；(2) \\(\\mathrm{BaSO_3 + 2H^+ \\to Ba^{2+} + H_2O + SO_2\\uparrow}\\)。","markingPoints":["由部分溶解与刺激气味正确判断 SO₄²⁻ 与 SO₃²⁻（2分）","写出 BaSO₃ 溶酸离子方程式（2分）"],"verification":"对照表14-12 现象逻辑一致。","pitfall":"只答沉淀溶出 SO₂ 而漏掉“部分溶解”说明必定共存 SO₄²⁻。"},{"id":"chem14-14.8-q4","tier":"L4","tierLabel":"L4 统考压轴","examStyle":"P2 综合计算","q":"将 \\(17.2\\text{ g}\\) 生石膏（\\(\\mathrm{CaSO_4\\cdot 2H_2O}\\)，式量 \\(172\\)）置于坩埚中加热脱水，随着温度升高，固体质量逐步减小。若在 \\(160\\ ^\\circ\\mathrm{C}\\) 下恒温加热一段时间后，称得剩余固体质量为 \\(14.5\\text{ g}\\)，试通过计算确定此时剩余固体的化学式。（\\(\\mathrm{CaSO_4}=136,\\ \\mathrm{H_2O}=18\\)）","given":"m(CaSO₄·2H₂O)=17.2 g (0.100 mol)；m(剩余)=14.5 g","method":"先算 0.100 mol 无水 CaSO₄ 质量（13.6 g），余下质量差即为残留结晶水质量，求 n(CaSO₄):n(H₂O)！","principle":"结晶水合物受热失去部分结晶水，盐基 CaSO₄ 质量恒定。","steps":["初始生石膏物质的量：\\(n(\\mathrm{CaSO_4\\cdot 2H_2O}) = \\frac{17.2\\text{ g}}{172\\text{ g}\\cdot\\mathrm{mol^{-1}}} = 0.100\\text{ mol}\\)，其中所含无水 \\(\\mathrm{CaSO_4}\\) 为 \\(0.100\\text{ mol}\\)，其质量 \\(m(\\mathrm{CaSO_4}) = 0.100 \\times 136 = 13.6\\text{ g}\\)。","在 \\(160\\ ^\\circ\\mathrm{C}\\) 加热后，剩余固体中尚留有的结晶水质量：\\(m_{\\text{剩}}(\\mathrm{H_2O}) = 14.5\\text{ g} - 13.6\\text{ g} = 0.90\\text{ g}\\)。","剩余结晶水的物质的量：\\(n_{\\text{剩}}(\\mathrm{H_2O}) = \\frac{0.90\\text{ g}}{18\\text{ g}\\cdot\\mathrm{mol^{-1}}} = 0.050\\text{ mol}\\)。","故剩余固体中 \\(n(\\mathrm{CaSO_4}) : n(\\mathrm{H_2O}) = 0.100 : 0.050 = 2 : 1\\)，即化学式为 **\\(\\mathrm{2CaSO_4\\cdot H_2O}\\)**（或 \\(\\mathrm{CaSO_4\\cdot \\frac{1}{2}H_2O}\\)，熟石膏）。"],"ans":"剩余固体的化学式为 \\(\\mathrm{2CaSO_4\\cdot H_2O}\\)（熟石膏）。","markingPoints":["算出 n(CaSO₄)=0.100 mol 及无水质量 13.6 g（2分）","算得剩余结晶水 0.050 mol（1分）","确定 2:1 比例并写出 2CaSO₄·H₂O（1分）"],"verification":"\\(M_r(\\mathrm{2CaSO_4\\cdot H_2O}) = 272 + 18 = 290\\)，\\(0.050 \\times 290 = 14.5\\text{ g}\\)，完全吻合！","pitfall":"若直接算失去的水 17.2-14.5=2.7 g (0.15 mol)，切记化学式中要放的是**剩余的** 0.050 mol 水，而不是失去的水！"}],"cheatSheet":["SO₄²⁻ 标准检验（铁律）：先加足量稀盐酸无明显现象（除 CO₃²⁻、SO₃²⁻ 及 Ag⁺），再加 BaCl₂ 产生白色沉淀（严禁用稀 HNO₃ 或先加 BaCl₂）。","石膏：生石膏 CaSO₄·2H₂O —150~170℃→ 熟石膏 2CaSO₄·H₂O（加水硬化成石膏绷带）。","重晶石 BaSO₄（不溶水与胃酸，医用钡餐）；绿矾 FeSO₄·7H₂O（浅绿晶体，补血与净水）。"],"kbEntryIds":["kb-chem14-so4-test"],"quiz":{"q":"某同学为检验未知溶液中是否含有 \\(\\mathrm{SO_4^{2-}}\\)，先向溶液中滴加 \\(\\mathrm{BaCl_2}\\) 溶液产生白色沉淀，再加入足量稀盐酸发现沉淀不溶解。为什么该同学的结论仍然**不够严谨**？","given":"思考题 14h 第1题 D vs C","method":"寻找既不溶于水又与 Cl⁻ 反应生成不溶于盐酸白色沉淀的阳离子","principle":"Ag⁺ + Cl⁻ → AgCl↓ 同样既不溶于水也不溶于稀盐酸。","steps":["如果原溶液中不含 \\(\\mathrm{SO_4^{2-}}\\)，但含有 **\\(\\mathrm{Ag^+}\\)**（如 \\(\\mathrm{AgNO_3}\\) 溶液），滴加 \\(\\mathrm{BaCl_2}\\) 溶液时 \\(\\mathrm{Cl^-}\\) 会与 \\(\\mathrm{Ag^+}\\) 生成白色的 \\(\\mathrm{AgCl}\\) 沉淀，且该沉淀同样不溶于稀盐酸。","因此必须**先**加足量稀盐酸酸化（若含 \\(\\mathrm{Ag^+}\\) 会提前暴露），确认无沉淀和气泡后再加 \\(\\mathrm{BaCl_2}\\)。"],"ans":"若原溶液含 Ag⁺ 而无 SO₄²⁻，也会生成不溶于稀盐酸的 AgCl 白色沉淀，因此必须先加稀盐酸后加 BaCl₂。"}}]},"化学15":{"lessonKey":"化学15","courseCode":"chemistry","subject":"化学","chapter":15,"title":"VIIA族元素：卤素","syllabus":"3.9 VIIA族元素","bookId":"sm1-chemistry-2017","bookCitation":"《马来西亚华文独中教科书 · 化学（上册）》（2017年11月版）第15章 p.378–407 & 附录2 p.446","examScopes":["sem2_final","uec"],"chapterOverview":{"summary":"第15章系统阐释典型非金属元素VIIA族——卤素（F、Cl、Br、I）的递变律与核心反应：从单质物理递变（气→液→固、颜色加深）及氧化性递减（F₂>Cl₂>Br₂>I₂、卤素间置换与 CCl₄ 萃取），深入氯水成分（HClO 分解与漂白）、Cl₂ 与冷稀/热浓 NaOH 歧化（漂白液与漂白粉）、实验室 MnO₂+浓盐酸制取纯净干燥氯气的全套除杂装置及离子膜氯碱工业、HCl 喷泉与分步制法、AgX 沉淀颜色及溶解性（关联附录2），以及卤氧酸命名和酸性/稳定性/氧化性递变规律。","conceptTree":[{"branch":"1. 卤素性质递变与单质反应（p.378–387）","items":["表15-1 物理递变（F₂ 淡黄绿气 · Cl₂ 黄绿气 · Br₂ 深红棕液 · I₂ 紫黑固升华）","氧化性递减（FeCl₃、与 H₂ 化合条件、Cl₂>Br₂>I₂ 置换与 CCl₄ 萃取）","氯水(HClO 漂白分解) · Cl₂+冷/热碱歧化 · 漂白粉 Ca(ClO)₂"]},{"branch":"2. 氯气的实验室制法与氯碱工业（p.389–392）","items":["MnO₂ + 4HCl(浓) —Δ→ MnCl₂ + Cl₂↑ + 2H₂O（稀盐酸不反应）","除杂顺序：饱和食盐水(除HCl) → 浓硫酸(干燥) → 向上排空气 → NaOH(吸尾气)","阳离子交换膜法电解饱和食盐水（只许 Na⁺ 通过）"]},{"branch":"3. 氯化氢、卤化物溶解性与卤氧酸（p.393–400, p.446）","items":["HCl 喷泉实验(1:500) · NaCl+浓 H₂SO₄ 分步制法与倒置漏斗防倒吸","AgCl(白)、AgBr(淡黄)、AgI(黄) 不溶稀硝酸检验（附录2 溶解性表）","表15-5 卤氧酸命名与酸性、稳定性、氧化性递变（图15-22/23）"]}]},"paperFocus":["下半年期末考 / UEC 统考卷一（30%）：常考氯水光照变化、漂白粉有效成分与失效原理、卤素互置换与 CCl₄ 分层颜色、MnO₂+浓盐酸限量产气比较（思考题 15b 第1题）、AgX 沉淀鉴别及卤氧酸酸性/氧化性顺序。","UEC 统考卷二甲部必答/探究（34%）及乙部无机选答（18%）：最高频命制“实验室制取干燥纯净氯气全套装置排序与试剂作用探究”、氯碱工业离子交换膜正负极产物分析、HCl 防倒吸及氯气与碱歧化定量计算。"],"solvingWorkflow":["气体制备除杂顺序黄金法则：先除水溶性杂质气体（饱和食盐水除 Cl₂ 中的 HCl），**后**干燥（浓硫酸），最后收集和尾气吸收（NaOH）。顺序一旦颠倒会重新带入水汽！","液溴与碘的物理特性速查：Br₂ 常温深红棕色**液体**，试剂瓶需加水液封防挥发；I₂ 易升华（物理变化），用 CCl₄ 萃取后下层溶 Br₂ 呈橙红色、溶 I₂ 呈紫红色。","MnO₂ + 浓盐酸产气陷阱：浓盐酸会随反应变稀而使反应中途停止，故算“足量 MnO₂ + 定量浓 HCl”时 Cl₂ 必小于理论值；而改用 KMnO₄ 常温即可制 Cl₂。","卤氧酸两套递变图别搞反：同卤素价态升高（HClO → HClO₄）酸性↑、稳定性↑、氧化性↓；同价次卤酸（HClO → HBrO → HIO）酸性↓、稳定性↓、氧化性依教材图15-23 ↑。"],"questionTypes":["卤素单质及卤化物性质递变、CCl₄ 萃取分层现象与氧化还原顺序推断","氯水成分动态变化（pH、AgNO₃、品红、光照）及漂白粉失效探究","实验室 Cl₂ 制取/净化/干燥/尾气装置组装改错与氯碱电解池电极判断","HCl 喷泉、倒置漏斗防倒吸及卤离子（Cl⁻/Br⁻/I⁻）硝酸银鉴定与混合沉淀计算","卤氧酸命名、酸性强弱与高氯酸氧化还原反应配平"],"scoringNotes":["回答“饱和食盐水的作用”必须同时答出两层要点：① 除去混有的 \\(\\mathrm{HCl}\\) 气体；② 降低 \\(\\mathrm{Cl_2}\\) 在水中的溶解度（Cl⁻ 同离子效应抑制 Cl₂+H₂O 平衡）。","回答“阳离子交换膜作用”须紧扣两害防范：① 隔开阳极 \\(\\mathrm{Cl_2}\\) 与阴极 \\(\\mathrm{H_2}\\) 防止混合爆炸；② 隔开 \\(\\mathrm{Cl_2}\\) 与阴极区 \\(\\mathrm{OH^-}\\) 防止反应生成 \\(\\mathrm{ClO^-}\\) 降低烧碱纯度。"],"vid":[{"t":"卤素性质递变、氯水成分与漂白粉","q":"卤素 氯水成分 次氯酸 漂白粉 高中化学"},{"t":"实验室制取纯净干燥氯气装置与氯碱工业","q":"氯气的实验室制法 除杂 氯碱工业 离子交换膜"},{"t":"氯化氢喷泉、防倒吸与卤化银检验","q":"氯化氢 喷泉实验 防倒吸 卤离子检验"},{"t":"卤氧酸命名与酸性、氧化性递变规律","q":"氯的含氧酸 酸性 稳定性 氧化性 递变"}],"sections":[{"id":"15.1","t":"卤素的性质与用途","anchor":{"pages":"化上 p.378–388","syllabus":"3.9.1 卤素物理递变、金属/非金属反应、氯水、歧化及置换顺序","examScopes":["sem2_final","uec"],"examWeight":"P1/P2 核心重点（氯水微粒、Cl₂ 与冷/热碱歧化、卤素互置换与萃取）","terms":"halogens · chlorine water · hypochlorous acid · bleaching powder · disproportionation","prerequisites":["原子半径与最外层 7 电子得电子能力递变（化上 Ch 6.3）","氧化还原反应与氧化剂相对强弱判断（化上 Ch 8.3）"],"goals":["对照表15-1 概述 F₂、Cl₂、Br₂、I₂ 的聚集状态、颜色、熔沸点、水溶性及溴液封、碘升华特性。","掌握 Cl₂ 与金属（Na、Fe、Cu）、H₂（点燃与光照爆炸）、H₂O（活动5–8 氯水成分及 HClO 分解）、冷稀与热浓 NaOH 溶液及熟石灰反应的方程式。","通过活动10–11 掌握卤素单质氧化性顺序（F₂ > Cl₂ > Br₂ > I₂）及借助 CCl₄ 萃取验证溴、碘单质的实验现象。"]},"concepts":[{"kind":"table","title":"卤族（VIIA）单质原子结构与物理性质递变（表15-1）","pageRef":"化上 p.379–380","body":["卤素（F、Cl、Br、I、At、Ts）最外层均为 \\(7\\) 个电子（\\(ns^2np^5\\)），自然界全以化合态存在，单质皆为双原子分子。随原子序数增大，电子层数递增，由气态过渡到固态，颜色由浅变深，熔沸点依次升高（注意：氟气极活泼直接与水剧烈反应放 \\(\\mathrm{O_2}\\)，不发生置换）。"],"table":{"headers":["单质","最外层排布","常温颜色和状态","熔/沸点（℃）","100 g 水溶解度与保存/特性"],"rows":[["氟 \\(\\mathrm{F_2}\\)","\\(2s^2 2p^5\\)","淡黄绿色气体","−219.6 / −188.1","与水剧烈反应（\\(\\mathrm{2F_2 + 2H_2O \\to 4HF + O_2}\\uparrow\\)）"],["氯 \\(\\mathrm{Cl_2}\\)","\\(3s^2 3p^5\\)","黄绿色气体","−101 / −34.6","约 \\(226\\text{ cm}^3\\)（1:2 溶解得黄绿色氯水）"],["溴 \\(\\mathrm{Br_2}\\)","\\(4s^2 4p^5\\)","**深红棕色液体**（唯一液态非金属）","−7.2 / 58.8","4.17 g；易挥发，试剂瓶常**加水液封**并用玻璃塞"],["碘 \\(\\mathrm{I_2}\\)","\\(5s^2 5p^5\\)","**紫黑色固体**","113.5 / 184.4","0.029 g；受热易**升华**成紫色蒸气，易溶酒精（碘酒）与 \\(\\mathrm{CCl_4}\\)"]]},"takeaway":"生活应用（p.378）：含氟牙膏中 F⁻ 取代牙齿羟基磷灰石 Ca₅(PO₄)₃OH 中的 OH⁻ 生成更坚硬耐酸的氟磷灰石 Ca₅(PO₄)₃F 预防蛀牙。"},{"kind":"experiment","title":"活动1–8：氯气与金属、氢气反应及新制氯水多重成分剖析（表15-2/15-3）","pageRef":"化上 p.380–384","body":["**与金属反应（活动1–3）**：\\(\\mathrm{2Na + Cl_2 \\to 2NaCl}\\)（黄色火焰、白烟）；\\(\\mathrm{2Fe + 3Cl_2} \\xrightarrow{\\text{高温}} \\mathrm{2FeCl_3}\\)（棕褐色烟，溶于水呈棕黄色——直接氧化成 **+3 价**；但**干燥氯气常温不与铁反应**，故用钢瓶储运液氯！）；\\(\\mathrm{Cu + Cl_2} \\xrightarrow{\\text{高温}} \\mathrm{CuCl_2}\\)（棕黄色烟，溶于少量水呈绿色/稀则蓝）。","**与 \\(\\mathrm{H_2}\\) 反应（活动4，图15-7/15-8）**：安静燃烧呈**苍白色火焰**并形成白雾（\\(\\mathrm{H_2 + Cl_2} \\xrightarrow{\\text{点燃}} \\mathrm{2HCl}\\)）；若混合后用点燃镁条强光照射则**迅速化合爆炸**（弹起塑料片）。溴需加热至 500℃、碘需持续加热及铂催化且可逆（\\(\\mathrm{H_2 + I_2 \\rightleftharpoons 2HI}\\)），反映非金属性 \\(\\mathrm{Cl > Br > I}\\)。","**新制氯水性质（活动5–8，表15-3）**：① 呈黄绿色（含 \\(\\mathrm{Cl_2}\\) 分子）；② 滴加 pH 试纸**先变红后褪色**（\\(\\mathrm{HCl}\\) 显酸性，\\(\\mathrm{HClO}\\) 漂白性）；③ 滴 \\(\\mathrm{AgNO_3}\\) 生白色沉淀（含 \\(\\mathrm{Cl^-}\\)）；④ **干燥有色纸条放入干燥氯气不褪色，放入新制氯水迅速褪色**——证明真正起漂白作用的是 **\\(\\mathrm{HClO}\\)** 而非 \\(\\mathrm{Cl_2}\\)！","**光照分解（图15-9）**：\\(\\mathrm{2HClO(aq)} \\xrightarrow{\\text{光照}} \\mathrm{2HCl(aq) + O_2(g)\\uparrow}\\)（释放初生态氧 O 杀菌漂白，自来水晒太阳可除余氯养鱼）。"],"takeaway":"新制氯水含“三分子四离子”：Cl₂、HClO、H₂O 与 H⁺、Cl⁻、ClO⁻、极少 OH⁻；久置氯水因 HClO 全部分解而变成稀盐酸！"},{"kind":"experiment","title":"活动9–11：氯气与碱歧化（漂白粉）及卤素互置换萃取（表15-4）","pageRef":"化上 p.385–387","body":["**与强碱歧化（温度/浓度决定产物）**：① **冷稀 \\(\\mathrm{NaOH}\\)**：\\(\\mathrm{Cl_2(g) + 2NaOH(aq,\\text{冷稀}) \\to NaClO(aq) + NaCl(aq) + H_2O(l)}\\)（制漂白液，有效成分 **\\(\\mathrm{NaClO}\\)**）；② **热浓 \\(\\mathrm{NaOH}\\)**：\\(\\mathrm{3Cl_2(g) + 6NaOH(aq,\\text{热浓}) \\to NaClO_3(aq) + 5NaCl(aq) + 3H_2O(l)}\\)（制氯酸钠）。","**漂白粉（Ca(ClO)₂）**：\\(\\mathrm{2Cl_2(g) + 2Ca(OH)_2(s) \\to Ca(ClO)_2(s) + CaCl_2(s) + 2H_2O(l)}\\)。使用原理：与空气中 \\(\\mathrm{CO_2}\\)、水蒸气反应释出 \\(\\mathrm{HClO}\\)：\\(\\mathrm{Ca(ClO)_2 + CO_2 + H_2O \\to CaCO_3\\downarrow + 2HClO}\\)，故漂白粉需**密封、干燥、避光**保存（否则 \\(\\mathrm{HClO}\\) 分解彻底失效）。","**卤素置换与 \\(\\mathrm{CCl_4}\\) 萃取（活动10–11）**：新制氯水入 \\(\\mathrm{KBr}\\) 溶液加 \\(\\mathrm{CCl_4}\\) 振荡静置，下层呈**橙红色**（\\(\\mathrm{Br_2}\\)）；氯水或溴水入 \\(\\mathrm{KI}\\) 溶液加 \\(\\mathrm{CCl_4}\\)，下层呈**紫红色**（\\(\\mathrm{I_2}\\)）。证明氧化性：**\\(\\mathrm{F_2 > Cl_2 > Br_2 > I_2}\\)**，还原性：**\\(\\mathrm{I^- > Br^- > Cl^- > F^-}\\)**。"],"takeaway":"向含 Br⁻ 和 I⁻ 的混合溶液中逐滴加入氯水，氯水会优先氧化还原性更强的 I⁻（先出紫红色 I₂），然后再氧化 Br⁻！"}],"formulas":[{"title":"氯水可逆反应、次氯酸见光分解与漂白粉失效反应","tex":"\\mathrm{Cl_2 + H_2O \\rightleftharpoons HCl + HClO},\\qquad \\mathrm{2HClO} \\xrightarrow{\\text{光照}} \\mathrm{2HCl + O_2\\uparrow},\\qquad \\mathrm{Ca(ClO)_2 + CO_2 + H_2O \\longrightarrow CaCO_3\\downarrow + 2HClO}","plain":"Cl2 + H2O ⇌ HCl + HClO; 2HClO --光照--> 2HCl + O2↑; Ca(ClO)2 + CO2 + H2O -> CaCO3↓ + 2HClO","conditions":"Br₂、I₂ 与水反应极微弱，溴水漂白性极弱，碘水无漂白性","pageRef":"化上 p.383–385","note":"Cl₂ 溶于水仅部分反应（多数以 Cl₂ 分子形式存在）；若向氯水中加 CaCO₃ 粉末，会消耗 HCl 而提高 HClO 浓度。"},{"title":"Cl₂ 与冷稀/热浓 NaOH 歧化及卤素间置换方程式","tex":"\\mathrm{3Cl_2 + 6NaOH(\\text{热浓}) \\longrightarrow NaClO_3 + 5NaCl + 3H_2O},\\qquad \\mathrm{2KBr + Cl_2 \\longrightarrow 2KCl + Br_2},\\qquad \\mathrm{2KI + Br_2 \\longrightarrow 2KBr + I_2}","plain":"3Cl2 + 6NaOH(热浓) -> NaClO3 + 5NaCl + 3H2O; 2KBr + Cl2 -> 2KCl + Br2; 2KI + Br2 -> 2KBr + I2","conditions":"热浓 NaOH 歧化中氧化剂与还原剂（均为 Cl₂）物质的量之比为 5:1","pageRef":"化上 p.385、p.387","note":"记住：冷稀歧化得 ClO⁻（+1 价）与 Cl⁻（1:1）；热浓歧化得 ClO₃⁻（+5 价）与 Cl⁻（1:5）。"}],"pitfalls":[{"title":"把湿润 Cl₂ 的漂白归因于 Cl₂ 分子本身","wrong":"“干燥的氯气本身具有强漂白性，能使干燥有色布条褪色。”","diagnosis":"活动8 证明干燥有色纸条在干燥 \\(\\mathrm{Cl_2}\\) 中**不褪色**，只在湿润或氯水中褪色。","right":"真正起漂白作用的是氯气与水反应生成的**次氯酸（\\(\\mathrm{HClO}\\)）**（释放初生态氧强氧化色素），干燥 \\(\\mathrm{Cl_2}\\) 没有漂白性。","checkRule":"实验装置中若先经浓硫酸干燥 Cl₂，干燥红布条不褪色、湿润红布条褪色。"},{"title":"认为 F₂ 通入 NaCl 溶液也能置换出 Cl₂","wrong":"“氟的非金属性强于氯，所以将 \\(\\mathrm{F_2}\\) 通入 \\(\\mathrm{NaCl}\\) 水溶液中可置换出 \\(\\mathrm{Cl_2}\\)。”","diagnosis":"\\(\\mathrm{F_2}\\) 氧化性太强，在水中会第一时间剧烈氧化水分子放出氧气。","right":"\\(\\mathrm{F_2}\\) 通入盐溶液中优先与水发生 \\(\\mathrm{2F_2 + 2H_2O \\to 4HF + O_2\\uparrow}\\)，无法在水溶液中置换出 \\(\\mathrm{Cl_2}\\)（\\(\\mathrm{Br_2}\\)、\\(\\mathrm{I_2}\\) 同理）。","checkRule":"卤素间水溶液置换只限 \\(\\mathrm{Cl_2 \\to Br_2 \\to I_2}\\)，不包含 \\(\\mathrm{F_2}\\)！"}],"examples":[{"label":"例 15.1.1","tier":"L3","tierLabel":"L3 预试拔高","title":"Cl₂ 与热浓 NaOH 歧化电子转移及混合盐定量计算","prompt":"将标准状况下 \\(13.44\\text{ L}\\) 的 \\(\\mathrm{Cl_2}\\) 气体全部通入足量热浓氢氧化钠溶液中，充分反应后完全转化为 \\(\\mathrm{NaCl}\\) 和 \\(\\mathrm{NaClO_3}\\)。(1) 写出反应方程式并指明该反应中作氧化剂的氯气与作还原剂的氯气的物质的量之比；(2) 计算反应过程中转移电子的总物质的量以及生成的 \\(\\mathrm{NaClO_3}\\) 质量。（\\(\\mathrm{Na}=23,\\ \\mathrm{Cl}=35.5,\\ \\mathrm{O}=16\\)）","clues":"3Cl₂ + 6NaOH(热浓) → NaClO₃ + 5NaCl + 3H₂O，共 6 个 Cl 原子中 5 个降为 −1（氧化剂）、1 个升为 +5（还原剂）。","strategy":"先算 n(Cl₂)=0.60 mol，利用每 3 mol Cl₂ 转移 5 mol e⁻ 并生 1 mol NaClO₃ 比例一步算出结果。","given":"V(Cl₂, STP) = 13.44 L (0.60 mol)；热浓 NaOH 足量","principle":"歧化反应中氧化剂与还原剂比例确定及电子转移计量。","steps":["(1) \\(\\mathrm{3Cl_2(g) + 6NaOH(aq,\\text{热浓}) \\longrightarrow NaClO_3(aq) + 5NaCl(aq) + 3H_2O(l)}\\)。","生成 \\(5\\) 个 \\(\\mathrm{NaCl}\\)（0 → −1）和 \\(1\\) 个 \\(\\mathrm{NaClO_3}\\)（0 → +5），故作氧化剂与作还原剂的 \\(\\mathrm{Cl_2}\\) 物质的量之比为 **\\(5:1\\)**。","(2) \\(n(\\mathrm{Cl_2}) = \\frac{13.44}{22.4} = 0.60\\text{ mol}\\)。","每 \\(3\\text{ mol }\\mathrm{Cl_2}\\) 反应转移 \\(5\\text{ mol }e^-\\) 并生成 \\(1\\text{ mol }\\mathrm{NaClO_3}\\)（\\(M=106.5\\text{ g}\\cdot\\mathrm{mol^{-1}}\\)）。","故转移电子：\\(n(e^-) = 0.60 \\times \\frac{5}{3} = 1.00\\text{ mol}\\)；","生成 \\(\\mathrm{NaClO_3}\\)：\\(n(\\mathrm{NaClO_3}) = 0.60 \\times \\frac{1}{3} = 0.20\\text{ mol}\\)，质量 \\(m = 0.20 \\times 106.5 = 21.3\\text{ g}\\)。"],"answer":"(1) 氧化剂与还原剂之比 \\(5:1\\)；(2) 转移电子 \\(1.00\\text{ mol}\\)，生成 \\(\\mathrm{NaClO_3}\\ 21.3\\text{ g}\\)。","markingPoints":["写对方程式并判断氧化剂:还原剂=5:1（2分）","算得转移电子 1.00 mol（1.5分）","算得 NaClO₃ 质量 21.3 g（1.5分）"],"verification":"NaCl 生成 \\(1.00\\text{ mol}\\)（得 \\(1.00\\text{ mol }e^-\\)），NaClO₃ 生成 \\(0.20\\text{ mol}\\)（失 \\(0.20\\times 5 = 1.00\\text{ mol }e^-\\)），总 Cl = \\(1.00 + 0.20 = 1.20\\text{ mol}\\)（即 \\(0.60\\text{ mol }\\mathrm{Cl_2}\\)），完全吻合！","pitfall":"若误套用冷稀 NaOH 比例，会错算成 0.60 mol Cl₂ 转移 0.60 mol 电子；实际上热浓歧化时每 3 mol Cl₂ 转移 5 mol 电子，即 0.60 mol 转移 1.00 mol 电子。"},{"label":"例 15.1.2","tier":"L4","tierLabel":"L4 统考压轴","title":"新制氯水与不同试剂反应的微粒选择性探查","prompt":"新制氯水中含有多种分子和离子。现向四支分别装有下列试剂的试管中逐滴加入新制氯水，请分别指出观察到的现象，并写出对应起到核心作用的氯水微粒及反应方程式（或离子方程式）：(1) 紫色石蕊试液；(2) \\(\\mathrm{AgNO_3}\\) 溶液；(3) 滴加 \\(\\mathrm{CCl_4}\\) 的 \\(\\mathrm{KI}\\) 溶液；(4) 碳酸钠固体（\\(\\mathrm{Na_2CO_3}\\)）。","clues":"利用氯水微粒多重性：H⁺ 显酸性、HClO 漂白、Cl⁻ 沉淀 Ag⁺、Cl₂ 氧化 I⁻。","strategy":"逐一匹配“微粒 → 现象 → 离子方程式”。","given":"新制氯水（Cl₂, HClO, H₂O; H⁺, Cl⁻, ClO⁻）","principle":"溶液多重组分各自发挥独立化学性质。","steps":["(1) 紫色石蕊试液：**先变红后褪色**（主要微粒：**\\(\\mathrm{H^+}\\)** 使石蕊变红，**\\(\\mathrm{HClO}\\)** 将红色色素强氧化漂白）。","(2) \\(\\mathrm{AgNO_3}\\) 溶液：**产生白色沉淀**（主要微粒：**\\(\\mathrm{Cl^-}\\)**；\\(\\mathrm{Ag^+ + Cl^- \\to AgCl\\downarrow}\\)）。","(3) \\(\\mathrm{KI + CCl_4}\\)：振荡静置后溶液分层，**下层 \\(\\mathrm{CCl_4}\\) 层呈紫红色**（主要微粒：**\\(\\mathrm{Cl_2}\\)**；\\(\\mathrm{Cl_2 + 2I^- \\to 2Cl^- + I_2}\\)）。","(4) \\(\\mathrm{Na_2CO_3}\\) 固体：**产生无色无味气泡**（主要微粒：**\\(\\mathrm{H^+}\\)**；\\(\\mathrm{CO_3^{2-} + 2H^+ \\to H_2O + CO_2\\uparrow}\\)；因 \\(\\mathrm{HClO}\\) 酸性极弱仅由 \\(\\mathrm{HCl}\\) 电离的 \\(\\mathrm{H^+}\\) 反应）。"],"answer":"(1) 先红后褪（H⁺, HClO）；(2) 白沉（Cl⁻）；(3) 下层紫红（Cl₂）；(4) 冒气泡（H⁺）。","markingPoints":["每项现象、核心微粒与方程式全部对应准确（每项1分，共4分）"],"verification":"对照化上 p.383 表15-3 活动5–8 核对完全一致。","pitfall":"第(1)问常漏写“先变红”，只答褪色。"}],"practice":[{"id":"chem15-15.1-q1","tier":"L1","tierLabel":"L1 基础","examStyle":"P1 选择","q":"下列关于卤素单质性质递变规律的叙述中，**错误**的是（　）。","options":["A. 从 \\(\\mathrm{F_2}\\) 到 \\(\\mathrm{I_2}\\)，常温下聚集状态由气体过渡到液体再到固体","B. 从 \\(\\mathrm{F_2}\\) 到 \\(\\mathrm{I_2}\\)，颜色由淡黄绿逐渐加深至紫黑色","C. 从 \\(\\mathrm{F_2}\\) 到 \\(\\mathrm{I_2}\\)，氧化性逐渐增强，卤离子的还原性逐渐减弱","D. 溴易挥发，实验室保存液溴时试剂瓶中常加入少量水进行液封"],"correctOption":"C","given":"表15-1 卤素物理与化学递变","method":"核对氧化性与卤离子还原性递变方向","principle":"原子半径增大，得电子能力减弱 → 单质氧化性减弱，阴离子还原性增强。","steps":["C 错：从 \\(\\mathrm{F_2}\\) 到 \\(\\mathrm{I_2}\\)，非金属性和单质氧化性逐渐**减弱**，对应卤离子（\\(\\mathrm{F^- \\to I^-}\\)）的还原性逐渐**增强**。"],"ans":"C","markingPoints":["把握单质氧化性与离子还原性相反递变趋势"],"verification":"对照化上 p.379、p.387。","pitfall":"把单质氧化性和阴离子还原性方向记反。"},{"id":"chem15-15.1-q2","tier":"L2","tierLabel":"L2 期末","examStyle":"P1 选择","q":"下列关于新制氯水与久置氯水的对比说法中，**错误**的是（　）。","options":["A. 新制氯水呈黄绿色，久置氯水变为无色","B. 久置氯水的酸性比新制氯水强（pH 更小）","C. 新制氯水与久置氯水分别滴加 \\(\\mathrm{AgNO_3}\\) 溶液均能产生白色沉淀","D. 久置氯水依然保持很强的漂白能力"],"correctOption":"D","given":"氯水中 HClO 光照分解机制（化上 p.383–384 图15-9）","method":"追踪 2HClO → 2HCl + O₂↑ 后溶质成分变化","principle":"HClO 分解成强酸 HCl 和 O₂，导致 Cl₂ + H₂O 平衡持续右移直到 Cl₂ 和 HClO 耗尽。","steps":["久置氯水最终变为较稀的盐酸溶液，失去全部 \\(\\mathrm{Cl_2}\\) 和 \\(\\mathrm{HClO}\\)，因此无色、酸性更强、仍有 \\(\\mathrm{Cl^-}\\)，但**完全丧失漂白性**，故 D 错。"],"ans":"D","markingPoints":["明确久置氯水变成稀盐酸且漂白性消失"],"verification":"对照化上 p.383–384。","pitfall":"误以为久置氯水酸性变弱（弱酸 HClO 变强酸 HCl，酸性反而增强！）。"},{"id":"chem15-15.1-q3","tier":"L3","tierLabel":"L3 预试","examStyle":"P2 简答","q":"实验室将少量新制氯水滴入盛有 \\(\\mathrm{KBr}\\) 溶液的试管中，再加入少量四氯化碳（\\(\\mathrm{CCl_4}\\)）充分振荡后静置。(1) 描述试管内观察到的分层现象与颜色，并写出发生反应的化学方程式；(2) 工业上使用熟石灰吸收氯气制取漂白粉，写出漂白粉制备及露置空气中产生有效漂白成分并最终失效的相关方程式。","given":"活动10 与 p.385 漂白粉反应","method":"Br₂ 易溶于密度大于水的 CCl₄ 下层；漂白粉失效分两步：吸 CO₂/H₂O 出 HClO 再分解","principle":"萃取分层原理与强酸制弱酸（碳酸比次氯酸强）。","steps":["(1) 液体分为两层，水层几乎无色或微黄，**下层 \\(\\mathrm{CCl_4}\\) 层呈橙红色**；方程式：\\(\\mathrm{2KBr(aq) + Cl_2(g) \\longrightarrow 2KCl(aq) + Br_2(l)}\\)。","(2) 制备：\\(\\mathrm{2Cl_2(g) + 2Ca(OH)_2(s) \\longrightarrow Ca(ClO)_2(s) + CaCl_2(s) + 2H_2O(l)}\\)；失效两步：\\(\\mathrm{Ca(ClO)_2(s) + CO_2(g) + H_2O(l) \\longrightarrow CaCO_3(s)\\downarrow + 2HClO(aq)}\\)，\\(\\mathrm{2HClO(aq)} \\xrightarrow{\\text{光照}} \\mathrm{2HCl(aq) + O_2(g)\\uparrow}\\)。"],"ans":"(1) 下层呈橙红色，\\(\\mathrm{2KBr + Cl_2 \\to 2KCl + Br_2}\\)；(2) 制备与失效三式见步骤。","markingPoints":["准确描述下层橙红色并写出置换方程式（2分）","写出漂白粉制备、生成 HClO 与分解失效三步方程式（2.5分）"],"verification":"对照化上 p.385–387 原文。","pitfall":"误把 CCl₄ 写成在上层（CCl₄ 密度 1.59 g/cm³ > 水，在下层；苯/汽油在上层）。"},{"id":"chem15-15.1-q4","tier":"L4","tierLabel":"L4 统考压轴","examStyle":"P2 综合计算","q":"向含有 \\(0.20\\text{ mol}\\ \\mathrm{KI}\\) 和 \\(0.20\\text{ mol}\\ \\mathrm{KBr}\\) 的混合水溶液中缓慢通入一定量氯气（假设无气体逸出且不考虑氯气与水反应），充分反应后将溶液蒸干并灼烧（灼烧时 \\(\\mathrm{I_2}\\) 全部升华逸出，\\(\\mathrm{Br_2}\\) 全部挥发逸出，\\(\\mathrm{KCl}\\)、\\(\\mathrm{KBr}\\)、\\(\\mathrm{KI}\\) 热稳定）。称得最终剩余干燥固体质量为 \\(34.25\\text{ g}\\)。试计算通入氯气在标准状况下的体积为多少升？（\\(\\mathrm{K}=39,\\ \\mathrm{Cl}=35.5,\\ \\mathrm{Br}=80,\\ \\mathrm{I}=127\\)）","given":"n(KI)=0.20 mol, n(KBr)=0.20 mol；剩余固体 34.25 g","method":"先判断氧化还原先后顺序（I⁻ 优先氧化），再用质量差量法求出参与反应的 KBr 量","principle":"还原性 I⁻ > Br⁻；固体质量变化等于 Cl⁻ 置换 I⁻、Br⁻ 的摩尔质量差。","steps":["原溶质总质量：\\(m_0 = 0.20 \\times 166 + 0.20 \\times 119 = 33.2 + 23.8 = 57.0\\text{ g}\\)。","因还原性 \\(\\mathrm{I^- > Br^-}\\)，\\(\\mathrm{Cl_2}\\) 优先氧化 \\(\\mathrm{I^-}\\)。若 \\(0.20\\text{ mol KI}\\) 全部转化为 \\(\\mathrm{KCl}\\)（耗 \\(0.10\\text{ mol }\\mathrm{Cl_2}\\)），固体质量变为：\\(0.20 \\times 74.5 + 23.8 = 14.9 + 23.8 = 38.7\\text{ g}\\)。","实际剩余固体 \\(34.25\\text{ g} < 38.7\\text{ g}\\)（且若全部转化为 \\(\\mathrm{KCl}\\) 仅剩 \\(0.40 \\times 74.5 = 29.8\\text{ g}\\)），说明 \\(\\mathrm{KI}\\) 已**完全氧化**，且**部分 \\(\\mathrm{KBr}\\) 也被氧化**。","由 KBr 转化为 KCl 引起的额外减重：\\(\\Delta m = 38.7 - 34.25 = 4.45\\text{ g}\\)。","每 \\(1\\text{ mol KBr}\\)（119 g）变成 \\(1\\text{ mol KCl}\\)（74.5 g）减重 \\(44.5\\text{ g}\\)，故被氧化的 \\(\\mathrm{KBr}\\) 为 \\(\\frac{4.45}{44.5} = 0.10\\text{ mol}\\)（耗 \\(\\mathrm{Cl_2}\\ 0.050\\text{ mol}\\)）。","总消耗氯气：\\(n(\\mathrm{Cl_2}) = 0.10 + 0.050 = 0.15\\text{ mol}\\)，标况体积 \\(V(\\mathrm{Cl_2}) = 0.15 \\times 22.4 = 3.36\\text{ L}\\)。"],"ans":"通入氯气在标准状况下的体积为 \\(3.36\\text{ L}\\)。","markingPoints":["判定还原性 I⁻ > Br⁻ 并算出 KI 完全反应节点 38.7 g（2分）","通过差量法求出反应的 KBr 为 0.10 mol（1.5分）","算得总 Cl₂ 为 0.15 mol 即 3.36 L（1分）"],"verification":"反算核对：剩余固体含 \\(0.30\\text{ mol KCl}(22.35\\text{ g}) + 0.10\\text{ mol KBr}(11.90\\text{ g}) = 34.25\\text{ g}\\)，完全吻合！","pitfall":"若未判断氧化先后顺序，误以为 Cl₂ 同时等比例氧化 Br⁻ 和 I⁻，会导致错算各离子转化量。"}],"cheatSheet":["物理递变（F₂→I₂）：气→液(Br₂加水液封)→固(I₂易升华)；CCl₄ 下层溶 Br₂ 橙红、溶 I₂ 紫红。","氧化性顺序：F₂ > Cl₂ > Br₂ > I₂；F₂ 遇水直接放 O₂；Fe/Cu 与 Cl₂ 高温直接生高价 FeCl₃/CuCl₂。","氯水漂白成分为 HClO（2HClO —光照→ 2HCl+O₂↑）；Cl₂+冷稀 NaOH→NaClO；Cl₂+热浓 NaOH→NaClO₃。"],"kbEntryIds":["kb-chem15-halogen-trends","kb-chem15-cl2-water-alkali"],"quiz":{"q":"新制氯水能使紫色石蕊试液“先变红后褪色”，而将其在阳光下照射几天后，再滴入紫色石蕊试液却“只变红不褪色”。为什么？","given":"活动6 与图15-9","method":"追踪 HClO 光照分解对 H⁺ 与 HClO 浓度的影响","principle":"2HClO —光照→ 2HCl + O₂↑。","steps":["新制氯水中 \\(\\mathrm{HCl}\\) 电离出 \\(\\mathrm{H^+}\\) 使石蕊变红，随后 \\(\\mathrm{HClO}\\) 将色素氧化漂白使之褪色。","阳光照射几天后，\\(\\mathrm{HClO}\\) 全部分解为 \\(\\mathrm{HCl}\\) 和 \\(\\mathrm{O_2}\\)，氯水变成稀盐酸（仅有 \\(\\mathrm{H^+}\\) 无 \\(\\mathrm{HClO}\\)），故只能使石蕊变红而不再褪色。"],"ans":"HClO 光照分解为 HCl 和 O₂，久置氯水只剩酸性 H⁺ 而无漂白成分 HClO。"}},{"id":"15.2","t":"氯气的制取","anchor":{"pages":"化上 p.389–393","syllabus":"3.9.2 氯气的实验室制法（除杂干燥吸收）与工业电解饱和食盐水（氯碱工业）","examScopes":["sem2_final","uec"],"examWeight":"P1/P2 必考实验大题（图15-12 装置全套解析 + 离子膜电解池电极判别）","terms":"chlor-alkali industry · cation-exchange membrane · saturated brine · manganese(IV) oxide","prerequisites":["氧化还原反应配平与浓盐酸还原性（化上 Ch 8）","电解池阴阳极离子放电基本概念"],"goals":["熟练书写 MnO₂ 与浓盐酸加热、KMnO₄ 与浓盐酸常温制氯气的化学方程式，理解浓盐酸变稀即停的限度规律。","完整说出图15-12 五部分装置顺序与各瓶试剂作用（分液漏斗控制浓盐酸、饱和食盐水除 HCl、浓硫酸干燥、向上排空气收集、NaOH 溶液吸收尾气）。","结合图15-13 与图15-14 阐明氯碱工业电解饱和食盐水的阴阳极产物、检验方法以及阳离子交换膜的双重隔离作用。"]},"concepts":[{"kind":"experiment","title":"活动12：实验室制取纯净干燥氯气五部分装置全解析（图15-12）","pageRef":"化上 p.389–390","body":["**主反应方程式**：\\(\\mathrm{MnO_2(s) + 4HCl(aq,\\text{浓})} \\xrightarrow{\\Delta} \\mathrm{MnCl_2(aq) + Cl_2(g)\\uparrow + 2H_2O(l)}\\)（注意：必须使用**浓盐酸**和**加热**，稀盐酸不与 \\(\\mathrm{MnO_2}\\) 反应；若改用 \\(\\mathrm{KMnO_4}\\) 则常温即可：\\(\\mathrm{2KMnO_4 + 16HCl(\\text{浓}) \\to 2KCl + 2MnCl_2 + 8H_2O + 5Cl_2\\uparrow}\\)）。","**五部分全套装置（严格按气流方向）**：","① **气体发生**：圆底烧瓶（装 \\(\\mathrm{MnO_2}\\)）+ 分液漏斗（盛浓盐酸控速）+ 酒精灯石棉网缓热；","② **除杂（洗气瓶1，饱和食盐水）**：除去挥发出的 \\(\\mathrm{HCl}\\) 气体，同时大量 \\(\\mathrm{Cl^-}\\) 抑制 \\(\\mathrm{Cl_2 + H_2O \\rightleftharpoons H^+ + Cl^- + HClO}\\) 减小 \\(\\mathrm{Cl_2}\\) 溶解损失；","③ **干燥（洗气瓶2，浓硫酸）**：吸收水蒸气得干燥 \\(\\mathrm{Cl_2}\\)（洗气瓶须**长管进、短管出**，且**严禁先干燥后除 HCl**！）；","④ **收集（集气瓶）**：**向上排空气法**（\\(M(\\mathrm{Cl_2})=71 > 29\\)，导管插至瓶底）或排饱和食盐水法；","⑤ **尾气吸收（烧杯，\\(\\mathrm{NaOH}\\) 溶液）**：吸收有毒余氯防止污染环境（\\(\\mathrm{Cl_2 + 2NaOH \\to NaCl + NaClO + H_2O}\\)）。"],"takeaway":"4 mol HCl(浓) 与 1 mol MnO₂ 反应生成 1 mol Cl₂ 时，仅有 2 mol HCl（一半）作还原剂被氧化，另外 2 mol HCl 起酸性作用生成 MnCl₂！"},{"kind":"experiment","title":"活动13 与 工业氯碱工业（阳离子交换膜法，图15-13/15-14）","pageRef":"化上 p.391–392","body":["**氯碱工业总方程式**：\\(\\mathrm{2NaCl(aq) + 2H_2O(l)} \\xrightarrow{\\text{电解}} \\mathrm{2NaOH(aq) + H_2(g)\\uparrow + Cl_2(g)\\uparrow}\\)。","**活动13（U型管电解现象）**：① 与直流电源**正极**相连的**阳极**（石墨棒，b 管）产生**黄绿色气体（\\(\\mathrm{Cl_2}\\)）**，使湿润淀粉—KI 试纸变蓝，导管通入 \\(\\mathrm{NaOH}\\) 溶液吸收；② 与**负极**相连的**阴极**（铁棒，a 管）产生**无色气体（\\(\\mathrm{H_2}\\)）**，移近火焰产生淡蓝色火焰或爆鸣声，且关闭电源后向阴极区滴加酚酞**变红色**（生成 \\(\\mathrm{NaOH}\\)）。","**工业离子交换膜法（图15-14）**：阳极用镀铂钛网（\\(\\mathrm{2Cl^- - 2e^- \\to Cl_2\\uparrow}\\)），阴极用碳钢网（\\(\\mathrm{2H^+ + 2e^- \\to H_2\\uparrow}\\)）。槽中央设**阳离子交换膜**——**只允许阳离子（\\(\\mathrm{Na^+}\\)）通过，严密阻止阴离子（\\(\\mathrm{Cl^-, OH^-}\\)）与气体分子通过**。双重作用：① 防止阳极 \\(\\mathrm{Cl_2}\\) 与阴极 \\(\\mathrm{H_2}\\) 混合遇光/热爆炸；② 防止 \\(\\mathrm{Cl_2}\\) 与阴极区生成的 \\(\\mathrm{OH^-}\\) 反应生成 \\(\\mathrm{NaClO}\\) 污染烧碱产品。"],"takeaway":"记住氯碱电解口诀：“阳氧正氯（正极阳极Cl⁻失电子出Cl₂），阴还负氢碱（负极阴极H⁺得电子出H₂并留OH⁻变红）”。"},{"kind":"mechanism","title":"浓盐酸变稀停反应机制与 KMnO₄ 免加热替代方案","pageRef":"化上 p.389–390","body":["**浓盐酸与稀盐酸的氧化还原边界**：\\(\\mathrm{MnO_2}\\) 只能在加热条件下氧化**浓盐酸**；随着反应消耗 \\(\\mathrm{HCl}\\) 并生成水，盐酸浓度降低变为稀盐酸后反应立即停止，因此定量的浓盐酸与足量 \\(\\mathrm{MnO_2}\\) 共热，生成的 \\(\\mathrm{Cl_2}\\) 总是小于理论按 \\(4:1\\) 算出的最大值。","**盐酸的双重作用**：在 \\(\\mathrm{MnO_2 + 4HCl(\\text{浓})} \\xrightarrow{\\Delta} \\mathrm{MnCl_2 + Cl_2\\uparrow + 2H_2O}\\) 中，每消耗 \\(4\\text{ mol HCl}\\)，只有 \\(2\\text{ mol }\\mathrm{Cl^-}\\) 被氧化为 \\(\\mathrm{Cl_2}\\)（作**还原剂**），另外 \\(2\\text{ mol }\\mathrm{Cl^-}\\) 保留在 \\(\\mathrm{MnCl_2}\\) 中（体现**酸性**）。","**高锰酸钾常温替代法**：由于 \\(\\mathrm{KMnO_4}\\) 氧化性强于 \\(\\mathrm{MnO_2}\\)，与浓盐酸反应无需酒精灯加热即可迅速放出 \\(\\mathrm{Cl_2}\\)（\\(\\mathrm{2KMnO_4 + 16HCl(\\text{浓}) \\to 2KCl + 2MnCl_2 + 8H_2O + 5Cl_2\\uparrow}\\)）。"],"takeaway":"考场计算必警觉：足量 \\(\\mathrm{MnO_2}\\) 加一定量浓盐酸“充分反应”后，溶液中仍留有大量未反应的稀盐酸（\\(\\mathrm{H^+}\\) 和 \\(\\mathrm{Cl^-}\\)）！"}],"diagrams":[{"src":"assets/fig/v2/chem15-cl2-lab.svg","caption":"图 15-1 实验室 MnO₂+浓盐酸制取干燥纯净氯气全套五步装置及功能解析","alt":"实验室制取干燥纯净氯气装置图","pageRef":"化上 p.389–391"}],"formulas":[{"title":"实验室制氯气两种方法方程式（加热法 vs 免加热法）","tex":"\\mathrm{MnO_2(s) + 4HCl(aq,\\text{浓})} \\xrightarrow{\\Delta} \\mathrm{MnCl_2(aq) + Cl_2(g)\\uparrow + 2H_2O(l)},\\qquad \\mathrm{2KMnO_4 + 16HCl(\\text{浓}) \\longrightarrow 2KCl + 2MnCl_2 + 8H_2O + 5Cl_2\\uparrow}","plain":"MnO2 + 4HCl(浓) --Δ--> MnCl2 + Cl2↑ + 2H2O; 2KMnO4 + 16HCl(浓) -> 2KCl + 2MnCl2 + 8H2O + 5Cl2↑","conditions":"KMnO₄ 氧化性极强，与浓盐酸常温即可剧烈反应","pageRef":"化上 p.390","note":"制得 1 mol Cl₂ 时：MnO₂ 消耗 4 mol HCl（仅 2 mol 被氧化），KMnO₄ 消耗 3.2 mol HCl（仍仅 2 mol 被氧化）。"},{"title":"氯碱工业离子膜电解饱和食盐水总式与两极离子半反应","tex":"\\mathrm{2NaCl(aq) + 2H_2O(l)} \\xrightarrow{\\text{电解}} \\mathrm{2NaOH(aq) + H_2(g)\\uparrow + Cl_2(g)\\uparrow}","plain":"2NaCl + 2H2O --电解--> 2NaOH + H2↑ + Cl2↑","conditions":"阳极(正极)：2Cl⁻ − 2e⁻ → Cl₂↑；阴极(负极)：2H₂O + 2e⁻ → H₂↑ + 2OH⁻","pageRef":"化上 p.391–392","note":"整个电解过程中，Na⁺ 物质的量保持不变（从阳极室穿过交换膜迁往阴极室维持电中性）。"}],"pitfalls":[{"title":"认为足量 MnO₂ 能把定量浓盐酸中的 HCl 100% 消耗完（思考题 15b 第1题）","wrong":"“\\(146\\text{ g}\\)（\\(4\\text{ mol}\\)）浓盐酸中的 \\(\\mathrm{HCl}\\) 与足量 \\(\\mathrm{MnO_2}\\) 共热，能制得 \\(1.0\\text{ mol}\\ \\mathrm{Cl_2}\\)，与 \\(87\\text{ g}\\)（\\(1\\text{ mol}\\)）\\(\\mathrm{MnO_2}\\) 加足量浓盐酸制得的氯气一样多。”","diagnosis":"\\(\\mathrm{MnO_2}\\) 仅能氧化**浓**盐酸；反应耗酸并生水，浓度降至稀盐酸时反应立即停止，剩余 \\(\\mathrm{HCl}\\) 无法再反应。","right":"\\(146\\text{ g}\\ \\mathrm{HCl}\\)（浓）+ 足量 \\(\\mathrm{MnO_2}\\) 产生的 \\(\\mathrm{Cl_2}\\) **小于 1.0 mol**；而 \\(87\\text{ g}\\ \\mathrm{MnO_2}\\) + 足量浓盐酸，因浓盐酸过量足使 \\(\\mathrm{MnO_2}\\) 耗尽，恰好生成 **1.0 mol \\(\\mathrm{Cl_2}\\)**，故后者制得的 \\(\\mathrm{Cl_2}\\) 更多！","checkRule":"牢记：稀盐酸不与 \\(\\mathrm{MnO_2}\\) 反应（与稀硝酸能溶 Cu 不同，稀盐酸失去氧化/还原势）。"},{"title":"把图15-12 除杂顺序颠倒或错用石灰水吸收 Cl₂ 尾气","wrong":"“先用浓硫酸干燥氯气，再通过饱和食盐水除去 HCl；尾气改用澄清石灰水吸收。”","diagnosis":"先干燥后过饱和食盐水（水溶液）会重新带入水蒸气；澄清石灰水 \\(\\mathrm{Ca(OH)_2}\\) 溶解度极小，浓度太低吸收不完氯气。","right":"必须**先过饱和食盐水除 HCl，再过浓硫酸干燥**；实验室尾气吸收必须用浓的 **\\(\\mathrm{NaOH}\\) 溶液**（工业制漂白粉才用石灰乳或消石灰固体）。","checkRule":"气体除杂铁律：水溶液洗气在前，固体/浓硫酸干燥在后！"}],"examples":[{"label":"例 15.2.1","tier":"L3","tierLabel":"L3 预试拔高","title":"实验室制取纯净干燥氯气装置组装与故障排查","prompt":"实验室欲使用 \\(\\mathrm{MnO_2}\\) 和浓盐酸制备一瓶纯净、干燥的氯气（装置参见图15-12）。(1) 写出反应发生装置中发生反应的离子方程式；(2) 若某同学将饱和食盐水换成水、或省去饱和食盐水、或将饱和食盐水与浓硫酸位置互换，分别会导致什么后果？(3) 如何通过简单操作验证集气瓶中已集满氯气？","clues":"写离子方程式注意浓盐酸拆成 H⁺ 和 Cl⁻，MnO₂ 和 H₂O 保留化学式；验满可用湿润淀粉-KI 试纸（注意也可看瓶口颜色）。","strategy":"逐项分析杂质（HCl 与 H₂O）及 Cl₂ 溶解损失对纯度/干燥度/产率的影响。","given":"图15-12 五步实验装置","principle":"同离子效应、洗气与干燥顺序、强氧化性验满。","steps":["(1) 离子方程式：\\(\\mathrm{MnO_2(s) + 4H^+(aq) + 2Cl^-(aq)} \\xrightarrow{\\Delta} \\mathrm{Mn^{2+}(aq) + Cl_2(g)\\uparrow + 2H_2O(l)}\\)。","(2) ① 若把饱和食盐水换成纯水，会溶解损失大量 \\(\\mathrm{Cl_2}\\)（产率大降）；② 若省去饱和食盐水，挥发出的 \\(\\mathrm{HCl}\\) 无法除去，导致制得的 \\(\\mathrm{Cl_2}\\) 混有 \\(\\mathrm{HCl}\\) 杂质；③ 若两者位置互换，干燥后的 \\(\\mathrm{Cl_2}\\) 再次经过水溶液洗气瓶会重新混入水蒸气，导致集得的 \\(\\mathrm{Cl_2}\\) 潮湿。","(3) 验满方法：观察到集气瓶充满黄绿色气体，或将**湿润的淀粉—碘化钾试纸**放在集气瓶口（靠近排气管口），试纸立刻**变蓝**，证明已集满。"],"answer":"(1) \\(\\mathrm{MnO_2 + 4H^+ + 2Cl^-} \\xrightarrow{\\Delta} \\mathrm{Mn^{2+} + Cl_2\\uparrow + 2H_2O}\\)；(2) 损失 Cl₂ / 混 HCl / 重新带入水蒸气；(3) 湿润淀粉-KI 试纸放瓶口变蓝。","markingPoints":["离子方程式拆写与配平完全准确（1.5分）","三种异常情况后果对应清晰（2分）","说出湿润淀粉-KI 试纸瓶口变蓝验满（1分）"],"verification":"对照化上 p.390 图15-12 核验无误。","pitfall":"写离子方程式时常把弱/不溶的 MnO₂ 拆掉或把 4Cl⁻ 全放左端而右边忘了留 2Cl⁻ 生成 MnCl₂（正确净离子仅 2Cl⁻ 变 Cl₂，另 2Cl⁻ 未参与反应，故左边只写 2Cl⁻！）。"},{"label":"例 15.2.2","tier":"L4","tierLabel":"L4 统考压轴","title":"氯碱工业离子膜电解池定量与电极产物分析","prompt":"工业上用阳离子交换膜法电解 \\(500\\text{ mL}\\) 精制饱和食盐水（图15-14，设电解过程溶液体积始终保持 \\(500\\text{ mL}\\) 不变且无副反应）。通电一段时间后，在阳极收集到标准状况下 \\(11.2\\text{ L}\\) 气体。(1) 阳极与阴极发生的电极反应（离子形式）分别是什么？(2) 计算阴极区最终所得 \\(\\mathrm{NaOH}\\) 溶液的物质的量浓度（\\(\\mathrm{mol}\\cdot\\mathrm{L^{-1}}\\)）；(3) 解释电解过程中电解槽内的阳离子是如何迁移的，若撤掉阳离子交换膜会产生什么危害？","clues":"V(Cl₂, STP)=11.2 L -> n(Cl₂)=0.50 mol -> 根据 2NaCl + 2H₂O → 2NaOH + H₂↑ + Cl₂↑，n(NaOH) = 2 × 0.50 = 1.00 mol！","strategy":"利用总方程式 1 Cl₂ ↔ 2 NaOH 算出浓度，结合图15-14 说明 Na⁺ 迁移与两重隔离。","given":"V(溶液)=0.500 L；V(Cl₂, STP)=11.2 L (0.500 mol)","principle":"法拉第电解计量关系与阳离子交换膜选择透过性。","steps":["(1) 阳极（镀铂钛网，发生氧化）：\\(\\mathrm{2Cl^-(aq) - 2e^- \\longrightarrow Cl_2(g)\\uparrow}\\)；","阴极（碳钢网，发生还原）：\\(\\mathrm{2H_2O(l) + 2e^- \\longrightarrow H_2(g)\\uparrow + 2OH^-(aq)}\\)（或 \\(\\mathrm{2H^+ + 2e^- \\to H_2\\uparrow}\\)）。","(2) 生成氯气：\\(n(\\mathrm{Cl_2}) = \\frac{11.2\\text{ L}}{22.4\\text{ L}\\cdot\\mathrm{mol^{-1}}} = 0.500\\text{ mol}\\)。","由总反应 \\(\\mathrm{2NaCl + 2H_2O} \\xrightarrow{\\text{电解}} \\mathrm{2NaOH + H_2\\uparrow + Cl_2\\uparrow}\\) 可知，\\(n(\\mathrm{NaOH}) = 2 \\times 0.500 = 1.00\\text{ mol}\\)。","故所得 \\(\\mathrm{NaOH}\\) 物质的量浓度：\\(c(\\mathrm{NaOH}) = \\frac{1.00\\text{ mol}}{0.500\\text{ L}} = 2.00\\text{ mol}\\cdot\\mathrm{L^{-1}}\\)。","(3) 阳极区消耗 \\(\\mathrm{Cl^-}\\) 后，阳离子 \\(\\mathrm{Na^+}\\) 透过阳离子交换膜向**阴极室**迁移（因此 \\(\\mathrm{Na^+}\\) 总量不变，只是从阳极室转入阴极室与生成的 \\(\\mathrm{OH^-}\\) 组成纯净 \\(\\mathrm{NaOH}\\)）。若撤掉交换膜：① 阳极 \\(\\mathrm{Cl_2}\\) 与阴极 \\(\\mathrm{H_2}\\) 混合遇火/光易发生爆炸；② \\(\\mathrm{Cl_2}\\) 扩散入阴极区与 \\(\\mathrm{OH^-}\\) 反应生成 \\(\\mathrm{NaClO}\\) 和 \\(\\mathrm{NaCl}\\)，无法得到纯净烧碱。"],"answer":"(1) 电极式见步骤；(2) \\(2.00\\text{ mol}\\cdot\\mathrm{L^{-1}}\\)；(3) Na⁺ 迁向阴极室；撤膜易致 H₂/Cl₂ 爆炸且 Cl₂ 与 OH⁻ 反应降低烧碱纯度。","markingPoints":["阴阳极半反应式正确（1.5分）","算出 n(NaOH)=1.00 mol 与浓度 2.00 mol/L（2分）","说明 Na⁺ 迁移及撤膜的两项严重后果（1.5分）"],"verification":"对照化上 p.392 图15-14 与思考题 15b 第2题核验，完全一致。","pitfall":"误认为电解过程中 Na⁺ 浓度或总物质的量减少了（思考题 15b 第2题 D 错项正是此陷阱！）。"}],"practice":[{"id":"chem15-15.2-q1","tier":"L1","tierLabel":"L1 基础","examStyle":"P1 选择","q":"实验室用下列两种方法分别制取氯气：① 用含 \\(146\\text{ g}\\ \\mathrm{HCl}\\) 的浓盐酸与足量的二氧化锰共热反应；② 用 \\(87\\text{ g}\\ \\mathrm{MnO_2}\\) 与足量的浓盐酸共热反应。则理论上制得 \\(\\mathrm{Cl_2}\\) 的质量（　）。（\\(\\mathrm{H}=1,\\ \\mathrm{Cl}=35.5,\\ \\mathrm{Mn}=55,\\ \\mathrm{O}=16\\)）","options":["A. ① 比 ② 多","B. ② 比 ① 多","C. 一样多","D. 无法比较"],"correctOption":"B","given":"思考题 15b 第1题（化上 p.392）","method":"判别稀盐酸不与 MnO₂ 反应对 ① 产气量的限制","principle":"MnO₂ 只氧化浓盐酸，浓度下降变为稀盐酸后反应停止。","steps":["① 中 \\(146\\text{ g HCl}\\) 为 \\(4\\text{ mol}\\)，但随反应进行浓盐酸变稀即停止反应，故产 \\(\\mathrm{Cl_2} < 1\\text{ mol}\\)；","② 中 \\(87\\text{ g }\\mathrm{MnO_2}\\) 为 \\(1\\text{ mol}\\)，因浓盐酸足量能保证 \\(\\mathrm{MnO_2}\\) 完全耗尽，产 \\(\\mathrm{Cl_2} = 1\\text{ mol}\\)。"],"ans":"B","markingPoints":["识别浓盐酸变稀即停止反应的经典陷阱"],"verification":"对照化上 p.392 思考题 15b 第1题。","pitfall":"机械按 1:4 比例误选 C（一样多）。"},{"id":"chem15-15.2-q2","tier":"L2","tierLabel":"L2 期末","examStyle":"P1 选择","q":"下列关于工业上用阳离子交换膜法电解饱和食盐水的说法中，正确的是（　）。","options":["A. 电解饱和食盐水的工厂既能生产氯气也能联产氢氧化钠和氢气","B. 与直流电源正极相连的电极区有氢氧化钠生成","C. 与直流电源负极相连的电极上有氯气放出","D. 在电解过程中，槽内溶液中 \\(\\mathrm{Na^+}\\) 的总物质的量不断减少"],"correctOption":"A","given":"思考题 15b 第2题（化上 p.392–393）","method":"核对阴阳极、正负极及 Na⁺ 守恒","principle":"2NaCl + 2H₂O —电解→ 2NaOH + H₂↑(负极阴极) + Cl₂↑(正极阳极)。","steps":["B 错：NaOH 在负极（阴极区）生成；C 错：负极生成 H₂；D 错：Na⁺ 不参与放电，只是迁往阴极区，总量不变；A 对（氯碱工业三大产品）。"],"ans":"A","markingPoints":["明晰氯碱工业三大产物及正负电极位置"],"verification":"对照化上 p.392–393 思考题 15b 第2题。","pitfall":"把电解池正极（阳极）与原电池正极混淆。"},{"id":"chem15-15.2-q3","tier":"L3","tierLabel":"L3 预试","examStyle":"P2 简答","q":"按图15-12 实验室制备纯净干燥 \\(\\mathrm{Cl_2}\\) 时，气体通过两个洗气瓶后再进入集气瓶。(1) 两个洗气瓶中盛放的试剂依次是什么？说明第一个洗气瓶这样选用的化学原理；(2) 若改用高锰酸钾晶体与浓盐酸制取氯气，写出化学方程式并说明此时发生装置应作何简化。","given":"图15-12 氯气制取与 KMnO₄ 替代法（化上 p.390）","method":"说明饱和食盐水抑制 Cl₂ 溶解兼除 HCl；KMnO₄ 无需酒精灯加热","principle":"除 HCl 在前、干燥在后；KMnO₄ 强氧化性常温反应。","steps":["(1) 依次盛放**饱和食盐水**和**浓硫酸**。饱和食盐水能极易溶解吸收挥发出的 \\(\\mathrm{HCl}\\) 气体，同时食盐水中高浓度的 \\(\\mathrm{Cl^-}\\) 抑制了 \\(\\mathrm{Cl_2 + H_2O \\rightleftharpoons H^+ + Cl^- + HClO}\\) 的溶解平衡，最大限度减少 \\(\\mathrm{Cl_2}\\) 的溶解损失。","(2) \\(\\mathrm{2KMnO_4(s) + 16HCl(aq,\\text{浓}) \\longrightarrow 2KCl(aq) + 2MnCl_2(aq) + 8H_2O(l) + 5Cl_2(g)\\uparrow}\\)；简化之处：**无需使用酒精灯加热**（撤去酒精灯与石棉网，常温下滴加浓盐酸即可反应）。"],"ans":"(1) 饱和食盐水、浓硫酸（原理见步骤）；(2) \\(\\mathrm{2KMnO_4+16HCl\\to 2KCl+2MnCl_2+8H_2O+5Cl_2\\uparrow}\\)，撤去酒精灯加热。","markingPoints":["依次答出饱和食盐水和浓硫酸（1分）","说明饱和食盐水除 HCl 及 Cl⁻ 抑制 Cl₂ 溶解原理（1.5分）","写对 KMnO₄ 方程式并指出无需加热（2分）"],"verification":"对照化上 p.390 原文完全匹配。","pitfall":"写 KMnO₄+浓盐酸方程式时常漏掉副产物 KCl 或系数未配平（2、16 → 2、2、8、5）。"},{"id":"chem15-15.2-q4","tier":"L4","tierLabel":"L4 统考压轴","examStyle":"P2 综合计算","q":"实验室将 \\(17.4\\text{ g}\\) 二氧化锰与 \\(100\\text{ mL}\\) 浓度为 \\(10.0\\text{ mol}\\cdot\\mathrm{L^{-1}}\\) 的浓盐酸混合加热，充分反应后直到不再有气体产生（设浓盐酸挥发忽略不计），在标准状况下实际收集到 \\(\\mathrm{Cl_2}\\) 的体积为 \\(3.36\\text{ L}\\)。随后将反应后残留的固液混合物过滤，向滤液中加入足量 \\(\\mathrm{AgNO_3}\\) 溶液充分反应。(1) 计算有多少摩尔 \\(\\mathrm{MnO_2}\\) 参加了反应？(2) 计算最终生成的 \\(\\mathrm{AgCl}\\) 沉淀物质的量（即反应后滤液中残留的总 \\(\\mathrm{Cl^-}\\) 物质的量）。（\\(\\mathrm{Mn}=55,\\ \\mathrm{O}=16\\)）","clues":"利用实际生成的 Cl₂ (0.15 mol) 求出反应的 MnO₂ (0.15 mol)；注意滤液中的 Cl⁻ 包含生成的 MnCl₂ 和未反应的稀盐酸！由氯原子守恒直接求：总 HCl(1.00 mol) = 逸出 Cl₂ 中的 Cl(0.30 mol) + 滤液中的 Cl⁻！","strategy":"n(Cl₂) 定反应消耗 MnO₂；氯原子守恒一步算出残留 Cl⁻ 从而避免浓变稀无法直接算稀盐酸余量的难题！","given":"m(MnO₂)=17.4 g (0.20 mol)；n(HCl)=0.100 × 10.0 = 1.00 mol；V(Cl₂, STP)=3.36 L (0.15 mol)","principle":"化学方程式计量与氯原子守恒。","steps":["(1) 收集到的 \\(\\mathrm{Cl_2}\\) 物质的量：\\(n(\\mathrm{Cl_2}) = \\frac{3.36\\text{ L}}{22.4\\text{ L}\\cdot\\mathrm{mol^{-1}}} = 0.15\\text{ mol}\\)。","依据 \\(\\mathrm{MnO_2 + 4HCl(\\text{浓})} \\xrightarrow{\\Delta} \\mathrm{MnCl_2 + Cl_2\\uparrow + 2H_2O}\\)，参加反应的 \\(\\mathrm{MnO_2}\\) 为 \\(0.15\\text{ mol}\\)（剩余未反应的 \\(\\mathrm{MnO_2}\\) 为 \\(0.20 - 0.15 = 0.050\\text{ mol}\\)）。","(2) 初始溶液中含氯原子总量 \\(n_{\\text{总}}(\\mathrm{Cl}) = 1.00\\text{ mol}\\)；反应中以 \\(\\mathrm{Cl_2}\\) 气体逸出的氯原子量为 \\(2 \\times 0.15 = 0.30\\text{ mol}\\)。","由氯原子守恒（Cl⁻ 全部留在滤液的 \\(\\mathrm{MnCl_2}\\) 与剩余稀盐酸中），滤液中 \\(n(\\mathrm{Cl^-}) = 1.00 - 0.30 = 0.70\\text{ mol}\\)。","加入足量 \\(\\mathrm{AgNO_3}\\) 溶液后，生成 \\(\\mathrm{AgCl}\\) 沉淀的物质的量为 **\\(0.70\\text{ mol}\\)**。"],"ans":"(1) 参加反应的 \\(\\mathrm{MnO_2}\\) 为 \\(0.15\\text{ mol}\\)；(2) 生成 \\(\\mathrm{AgCl}\\) 沉淀 \\(0.70\\text{ mol}\\)。","markingPoints":["算出 n(Cl₂)=0.15 mol 及消耗 MnO₂ 0.15 mol（2分）","运用氯原子守恒求得滤液残留 Cl⁻ 0.70 mol 即 AgCl 0.70 mol（2分）"],"verification":"分项核验：生成 \\(0.15\\text{ mol }\\mathrm{MnCl_2}\\) 含 \\(0.30\\text{ mol }\\mathrm{Cl^-}\\)，未反应稀盐酸含 \\(1.00 - 4(0.15) = 0.40\\text{ mol HCl}\\)（此时稀盐酸浓度 \\(4.0\\text{ mol/L}\\) 恰好停止与 \\(\\mathrm{MnO_2}\\) 反应），总 \\(\\mathrm{Cl^-} = 0.30 + 0.40 = 0.70\\text{ mol}\\)！","pitfall":"若漏算剩余稀盐酸中大量的 Cl⁻（只算 MnCl₂ 中的 0.30 mol），就会得到错误答案 0.30 mol。"}],"cheatSheet":["实验室制 Cl₂：MnO₂ + 4HCl(浓) —Δ→ MnCl₂ + Cl₂↑ + 2H₂O（浓变稀即停）；KMnO₄+浓 HCl 免加热。","装置顺序不可逆：发生 → 饱和食盐水（除 HCl 抑 Cl₂ 溶） → 浓硫酸（干燥） → 向上排空气 → NaOH 吸尾气。","氯碱工业：2NaCl+2H₂O —电解→ 2NaOH+H₂↑(阴/负)+Cl₂↑(阳/正)；阳离子交换膜只许 Na⁺ 通过（防 H₂+Cl₂ 爆、防 Cl₂+OH⁻ 反应）。"],"kbEntryIds":["kb-chem15-cl2-lab-chloralkali"],"quiz":{"q":"在实验室制取氯气的整套装置中，为什么尾气吸收选用氢氧化钠溶液而**不**选用澄清石灰水？","given":"图15-12 尾气吸收装置","method":"比较 NaOH 与 Ca(OH)₂ 在常温水中的溶解度差异","principle":"吸收有毒气体需高浓度碱液以确保彻底吸收。","steps":["\\(\\mathrm{Ca(OH)_2}\\) 微溶于水，澄清石灰水中 \\(\\mathrm{OH^-}\\) 浓度极低，无法充分吸收大量氯气尾气；","\\(\\mathrm{NaOH}\\) 易溶于水，可配成较浓溶液迅速彻底吸收多余 \\(\\mathrm{Cl_2}\\)：\\(\\mathrm{Cl_2 + 2NaOH \\to NaCl + NaClO + H_2O}\\)。"],"ans":"Ca(OH)₂ 微溶于水，溶液浓度太低吸收不充分；NaOH 溶解度大，可迅速彻底吸收多余 Cl₂。"}},{"id":"15.3","t":"氯化氢","anchor":{"pages":"化上 p.393–396","syllabus":"3.9.3 氯化氢的喷泉实验、盐酸酸性及实验室分步制备与防倒吸","examScopes":["sem2_final","uec"],"examWeight":"P1 喷泉/白雾白烟区分 + P2 防倒吸漏斗与高沸点酸制挥发性酸探究","terms":"hydrogen chloride · hydrochloric acid · anti-suckback funnel · non-volatile acid","prerequisites":["浓硫酸的高沸点难挥发性（化上 Ch 14.7）","气压差与液体倒吸物理机制"],"goals":["掌握 HCl 的物理性质（0℃ 1:500 极易溶于水）、活动14 紫色石蕊红色喷泉现象及干燥 HCl 无酸性的微粒解释。","严格区分浓盐酸打开瓶塞产生的“白雾”与浓氨水靠近产生的“白烟”（图15-17）。","写出固体 NaCl 与浓硫酸在不加热/微热与 500~600℃ 条件下的两步制法方程式（图15-18），并解释图15-19 倒置漏斗防倒吸原理。"]},"concepts":[{"kind":"experiment","title":"活动14：氯化氢喷泉实验、白雾 vs 白烟与干燥 HCl 的酸性条件","pageRef":"化上 p.393–394","body":["**极易溶于水与喷泉（活动14，图15-16）**：\\(\\mathrm{HCl}\\) 是无色、有刺激性气味的气体，密度比空气大（\\(M=36.5 > 29\\)），0℃ 时 1 体积水大约溶解 **500 体积** \\(\\mathrm{HCl}\\)。烧瓶挤入少量水后气压骤降，水槽中的紫色石蕊溶液喷入烧瓶并变成**红色喷泉**（证明 \\(\\mathrm{HCl}\\) 极易溶于水且水溶液呈酸性）。","**必须在水中才显酸性**：干燥的 \\(\\mathrm{HCl}\\) 气体以分子形式存在，没有自由 \\(\\mathrm{H^+}\\)，因此**不能使干燥的蓝色石蕊试纸变红**；遇到湿润试纸才电离出 \\(\\mathrm{H^+}\\) 变红。","**白雾 vs 白烟（图15-17）**：浓盐酸挥发出的 \\(\\mathrm{HCl}\\) 气体与空气中水蒸气结合形成盐酸小液滴产生**白雾**；当浓盐酸与浓氨水敞口靠近时，挥发出的气体直接化合成固体氯化铵晶体微粒形成**白烟**：\\(\\mathrm{HCl(g) + NH_3(g) \\longrightarrow NH_4Cl(s)}\\)。"],"takeaway":"工业盐酸常因混有少量 Fe³⁺（铁盐杂质）而呈黄色，纯净浓盐酸是无色液体。"},{"kind":"experiment","title":"活动15：高沸点酸制挥发性酸与防倒吸倒置漏斗（图15-18/15-19）","pageRef":"化上 p.394–395","body":["**制备原理**：利用高沸点、难挥发的浓硫酸与固体氯化钠反应制取低沸点、易挥发的 \\(\\mathrm{HCl}\\) 气体（与制取硝酸原理相同）：","① **不加热或稍微加热**：生成硫酸氢钠和氯化氢：\\(\\mathrm{NaCl(s) + H_2SO_4(aq,\\text{浓}) \\longrightarrow NaHSO_4(aq) + HCl(g)\\uparrow}\\)；","② **500~600℃ 强热条件下**：\\(\\mathrm{NaHSO_4}\\) 继续与 \\(\\mathrm{NaCl}\\) 反应，总反应式为：\\(\\mathrm{2NaCl(s) + H_2SO_4(aq,\\text{浓})} \\xrightarrow{\\Delta} \\mathrm{Na_2SO_4(aq) + 2HCl(g)\\uparrow}\\)。","**收集与吸收制盐酸（图15-18/15-19）**：由于 \\(\\mathrm{HCl}\\) 密度大于空气且极易溶于水，采用**向上排空气法**收集（可用浓硫酸干燥，因两者不反应）；将 \\(\\mathrm{HCl}\\) 溶于水制盐酸时，**不能将导管直接插入水中**（易发生剧烈倒吸进入烧瓶），必须使用**倒置漏斗**使其边缘刚刚接触水面：一旦发生倒吸，水上升进入漏斗体积变大，烧杯液面下降随即脱离漏斗口，重力使水回落，从而自动消除负压**防止倒吸**！"],"takeaway":"对比实验室制 HCl、HBr、HI：HCl 可用 NaCl + 浓 H₂SO₄ 制取（因 Cl⁻ 还原性弱不能还原浓硫酸）；而 NaBr、NaI 严禁用浓硫酸制 HBr、HI，否则浓硫酸会将其氧化成 Br₂、I₂（须改用浓磷酸 H₃PO₄）！"},{"kind":"mechanism","title":"卤化氢制备试剂选择对比：浓硫酸制 HCl vs 浓磷酸制 HBr/HI","pageRef":"化上 p.394–395","body":["**高沸点酸制挥发性酸原则**：利用难挥发酸将易挥发卤化氢从盐晶体中加热赶出；但试剂酸还必须不能氧化生成的卤化氢。","**浓硫酸的适用边界**：卤离子还原性顺序为 \\(\\mathrm{I^- > Br^- > Cl^-}\\)。\\(\\mathrm{Cl^-}\\) 还原性较弱，常温或加热均不能被浓硫酸氧化，因此实验室既可用固体 \\(\\mathrm{NaCl}\\) 与浓硫酸制 \\(\\mathrm{HCl}\\)，也可用浓硫酸干燥 \\(\\mathrm{HCl}\\)；但 \\(\\mathrm{Br^-}\\) 与 \\(\\mathrm{I^-}\\) 还原性强，遇热浓硫酸立刻被氧化为红棕色 \\(\\mathrm{Br_2}\\) 蒸气与紫色 \\(\\mathrm{I_2}\\) 蒸气（浓硫酸被还原成 \\(\\mathrm{SO_2}\\) 或 \\(\\mathrm{H_2S}\\)）。","**HBr 与 HI 的正确制法**：实验室制取 \\(\\mathrm{HBr}\\)、\\(\\mathrm{HI}\\) 时必须改用**非氧化性高沸点酸——浓磷酸（\\(\\mathrm{H_3PO_4}\\)）**与 \\(\\mathrm{NaBr}\\)、\\(\\mathrm{NaI}\\) 共热。"],"takeaway":"记忆锚点：浓 \\(\\mathrm{H_2SO_4}\\) 可制并干燥 \\(\\mathrm{HCl}\\)，却绝对不能制取或干燥 \\(\\mathrm{HBr}\\) 与 \\(\\mathrm{HI}\\)（改用浓 \\(\\mathrm{H_3PO_4}\\)）！"}],"formulas":[{"title":"浓硫酸与 NaCl 固体分步反应及总反应方程式","tex":"\\mathrm{NaCl(s) + H_2SO_4(aq,\\text{浓}) \\longrightarrow NaHSO_4(aq) + HCl(g)\\uparrow},\\qquad \\mathrm{2NaCl(s) + H_2SO_4(aq,\\text{浓})} \\xrightarrow{\\Delta} \\mathrm{Na_2SO_4(aq) + 2HCl(g)\\uparrow}","plain":"NaCl + H2SO4(浓) -> NaHSO4 + HCl↑; 2NaCl + H2SO4(浓) --Δ--> Na2SO4 + 2HCl↑","conditions":"微热停留于 NaHSO₄；500~600℃ 强热完全转化为 Na₂SO₄","pageRef":"化上 p.395","note":"切记：浓硫酸不氧化 HCl，因此既可用浓硫酸制备 HCl，也可用浓硫酸干燥 HCl。"},{"title":"氯化氢与氨气生成白烟及盐酸中和方程式","tex":"\\mathrm{HCl(g) + NH_3(g) \\longrightarrow NH_4Cl(s)},\\qquad \\mathrm{HCl(aq) + NaOH(aq) \\longrightarrow NaCl(aq) + H_2O(l)}","plain":"HCl(g) + NH3(g) -> NH4Cl(s); HCl + NaOH -> NaCl + H2O","conditions":"“烟”为固体小颗粒（NH₄Cl）；“雾”为液体小液滴（盐酸雾）","pageRef":"化上 p.394","note":"实验室用蘸浓氨水的玻璃棒靠近待测气体冒白烟，可辅助检验 HCl。"}],"pitfalls":[{"title":"把制备 HCl 的方法直接照搬用来制取 HBr 和 HI","wrong":"“用固体 \\(\\mathrm{NaI}\\) 和浓硫酸共热，利用高沸点酸制挥发性酸原理制取纯净 \\(\\mathrm{HI}\\) 气体。”","diagnosis":"阴离子还原性 \\(\\mathrm{I^- > Br^- > Cl^-}\\)；浓硫酸不能氧化 \\(\\mathrm{Cl^-}\\)，但会剧烈氧化 \\(\\mathrm{Br^-}\\) 生成红棕色 \\(\\mathrm{Br_2}\\) 蒸气、氧化 \\(\\mathrm{I^-}\\) 生成紫色 \\(\\mathrm{I_2}\\) 蒸气（同时浓硫酸被还原为 \\(\\mathrm{SO_2}\\) 或 \\(\\mathrm{H_2S}\\)）！","right":"浓硫酸与 \\(\\mathrm{NaCl}\\) 共热制 \\(\\mathrm{HCl}\\) 成立，但实验室制取 \\(\\mathrm{HBr}\\)、\\(\\mathrm{HI}\\) 必须选用**非氧化性难挥发酸——浓磷酸（\\(\\mathrm{H_3PO_4}\\)）**。","checkRule":"遇到“NaBr/NaI + 浓 H₂SO₄”，产物一定混有 Br₂/I₂ 和 SO₂，制不出纯 HX！"},{"title":"忽视“干燥 HCl”与“盐酸”在石蕊显色和导电性上的差别","wrong":"“干燥的 \\(\\mathrm{HCl}\\) 气体通入干燥的蓝色石蕊试纸上，试纸也会立刻变红。”","diagnosis":"干燥 \\(\\mathrm{HCl}\\) 分子内为共价键，无水分子电离作用时不存在 \\(\\mathrm{H^+}\\) 离子，不显酸性也不导电。","right":"只有**湿润**的蓝色石蕊试纸或水溶液（盐酸）中电离出 \\(\\mathrm{H^+}\\)，才能变红并体现酸的通性。","checkRule":"审题紧盯“干燥气体 + 干燥试纸”字眼，绝大多数酸性/碱性气体（HCl、SO₂、NH₃）均须在有水时才显酸碱性。"}],"examples":[{"label":"例 15.3.1","tier":"L2","tierLabel":"L2 校内期末","title":"图15-19 倒置漏斗防倒吸机制与浓硫酸双用法比较","prompt":"(1) 在实验室用图15-19 装置将氯化氢气体溶解于水中制取盐酸时，为什么不直接把玻璃导管插入水中，而要连接一个倒置的漏斗使漏斗边缘刚好接触水面？(2) 在工业和实验室中，浓硫酸与 \\(\\mathrm{NaCl}\\) 在常温微热下、以及在强热（500~600℃）下反应产物不同，分别写出两个反应方程式并说明浓硫酸为什么可以制 \\(\\mathrm{HCl}\\) 却不能制 \\(\\mathrm{HI}\\)。","clues":"结合 HCl 1:500 极易溶水分析气压骤降及倒置漏斗大口径缓冲效果。","strategy":"分“极易溶水易倒吸”、“倒置漏斗液面脱离回落”与“浓硫酸高沸点+强氧化性（对 I⁻）”两问精答。","given":"图15-18 与 15-19 装置","principle":"气压平衡防倒吸原理；高沸点酸制低沸点酸及氧化还原限制。","steps":["(1) 因为 \\(\\mathrm{HCl}\\) 极易溶于水（0℃ 时 1 体积水溶 500 体积），若将导管直接插入水中，气体溶解使导管内气压骤降，水会迅速倒吸入高温发生装置导致烧瓶炸裂；改用倒置漏斗且边缘刚接触水面时，即使水上升进入容积较大的漏斗内，烧杯液面随之迅速下降而脱离漏斗边缘，漏斗内的水在重力作用下回落烧杯，气压重新平衡，从而有效防止倒吸。","(2) 常温微热：\\(\\mathrm{NaCl(s) + H_2SO_4(aq,\\text{浓}) \\longrightarrow NaHSO_4(aq) + HCl(g)\\uparrow}\\)；强热（500~600℃）：\\(\\mathrm{2NaCl(s) + H_2SO_4(aq,\\text{浓})} \\xrightarrow{\\Delta} \\mathrm{Na_2SO_4(aq) + 2HCl(g)\\uparrow}\\)。","原因：浓硫酸具有高沸点难挥发性和强氧化性，\\(\\mathrm{Cl^-}\\) 还原性较弱不能被浓硫酸氧化故可得纯净 \\(\\mathrm{HCl}\\)；而 \\(\\mathrm{I^-}\\) 还原性极强，会被浓硫酸氧化为 \\(\\mathrm{I_2}\\) 无法制得纯净 \\(\\mathrm{HI}\\)。"],"answer":"(1) 漏斗容积大且边缘刚触水面，倒吸即脱离液面回落从而防倒吸；(2) 见步骤。","markingPoints":["清晰描述液面下降脱离漏斗边缘自动回落机理（2分）","写对两温度条件下方程式（2分）","对比 Cl⁻ 与 I⁻ 还原性差异（1分）"],"verification":"对照化上 p.395 问题解决核对完全一致。","pitfall":"若把倒置漏斗完全深埋入烧杯水底，大漏斗同样会充满水失效（必须“刚刚接触水面”）。"},{"label":"例 15.3.2","tier":"L3","tierLabel":"L3 预试拔高","title":"HCl 与 NH₃ 气相反应产生白烟的定量与剩余气体分析","prompt":"在标准状况下，向一个容积固定为 \\(5.60\\text{ L}\\) 的真空干燥密闭玻璃容器中充入 \\(3.36\\text{ L}\\) 氨气（\\(\\mathrm{NH_3}\\)）和 \\(2.24\\text{ L}\\) 氯化氢气体（\\(\\mathrm{HCl}\\)），充分反应生成大量白色固体并冷却恢复至标准状况（不计固体所占体积）。(1) 写出反应方程式并计算生成的白色固体质量；(2) 计算反应后容器内剩余气体的成分及其在标准状况下的压强与初始总压强之比（\\(p_{\\text{后}} / p_{\\text{前}}\\)）。（\\(\\mathrm{N}=14,\\ \\mathrm{H}=1,\\ \\mathrm{Cl}=35.5\\)）","clues":"n(NH₃)=0.15 mol，n(HCl)=0.10 mol，1:1 生成 0.10 mol NH₄Cl 固体，余 0.05 mol NH₃ 气体！同温同体积下，压强比等于气体物质的量之比！","strategy":"先判限量（HCl 限量），算固体质量，再用理想气体 p ∝ n 求出压强比。","given":"n(NH₃)=0.15 mol, n(HCl)=0.10 mol；总初始 n=0.25 mol","principle":"限量反应物定量计算；阿伏加德罗/理想气体定温定容压强正比于气体物质的量。","steps":["(1) 方程式：\\(\\mathrm{NH_3(g) + HCl(g) \\longrightarrow NH_4Cl(s)}\\)。","投料：\\(n(\\mathrm{NH_3}) = \\frac{3.36}{22.4} = 0.15\\text{ mol}\\)，\\(n(\\mathrm{HCl}) = \\frac{2.24}{22.4} = 0.10\\text{ mol}\\)。因按 \\(1:1\\) 反应，\\(\\mathrm{HCl}\\) 完全反应，\\(\\mathrm{NH_3}\\) 过量 \\(0.050\\text{ mol}\\)。","生成 \\(\\mathrm{NH_4Cl}\\) 白色固体（\\(M=53.5\\text{ g}\\cdot\\mathrm{mol^{-1}}\\)）：\\(m(\\mathrm{NH_4Cl}) = 0.10 \\times 53.5 = 5.35\\text{ g}\\)。","(2) 反应后容器内仅剩余气态 \\(\\mathrm{NH_3}\\ 0.050\\text{ mol}\\)，初始总气体为 \\(0.15 + 0.10 = 0.25\\text{ mol}\\)。","在同温同容积条件下，气体压强与气体物质的量成正比：\\(\\frac{p_{\\text{后}}}{p_{\\text{前}}} = \\frac{n_{\\text{后}}}{n_{\\text{前}}} = \\frac{0.050}{0.25} = \\frac{1}{5}\\)（即 \\(0.20\\)）。"],"answer":"(1) 白色固体 \\(\\mathrm{NH_4Cl}\\) 质量为 \\(5.35\\text{ g}\\)；(2) 剩余 \\(\\mathrm{NH_3}\\)，压强比 \\(p_{\\text{后}} / p_{\\text{前}} = 1:5\\)。","markingPoints":["判断 HCl 限量并算得 NH₄Cl 质量 5.35 g（2分）","求得剩余 NH₃ 0.050 mol 及压强比 1:5（2分）"],"verification":"体积比即物质的量比：\\(3.36:2.24\\) 反应后只剩 \\(1.12\\text{ L}\\)，\\(1.12 / 5.60 = 1/5\\)。","pitfall":"若把固体 NH₄Cl 也算作气态，会错误算成压强不变。"}],"practice":[{"id":"chem15-15.3-q1","tier":"L1","tierLabel":"L1 基础","examStyle":"P1 选择","q":"打开浓盐酸试剂瓶的瓶塞，瓶口上方常会出现“白雾”；把浓盐酸和浓氨水两瓶敞口靠近时上方产生大量“白烟”。关于这两种现象的本质，下列说法正确的是（　）。","options":["A. 白雾是氯化氢气体，白烟是氨气","B. 白雾是盐酸小液滴，白烟是氯化铵固体小颗粒","C. 白雾和白烟都是物理变化","D. 白雾和白烟都能使干燥的蓝色石蕊试纸变红"],"correctOption":"B","given":"化上 p.394 氯化氢物理性质及图15-17","method":"严格区分“雾（液滴）”和“烟（固体微粒）”","principle":"HCl 遇水蒸气凝成酸雾（物理变化）；NH₃+HCl→NH₄Cl 固体白烟（化学变化）。","steps":["B 对：雾为液滴（盐酸液滴），烟为固体微粒（NH₄Cl 晶体）。"],"ans":"B","markingPoints":["区分白雾（液滴）和白烟（固体颗粒）"],"verification":"对照化上 p.394。","pitfall":"混淆“烟”与“雾”的物态。"},{"id":"chem15-15.3-q2","tier":"L2","tierLabel":"L2 期末","examStyle":"P1 选择","q":"下列有关氯化氢（\\(\\mathrm{HCl}\\)）的实验操作或性质描述，**错误**的是（　）。","options":["A. 工业浓盐酸常因混有铁盐杂质而呈黄色","B. 干燥的 \\(\\mathrm{HCl}\\) 气体可用浓硫酸干燥","C. 将 \\(\\mathrm{HCl}\\) 气体通入饱和食盐水中没有任何变化","D. 在 0℃ 时，1 体积水大约能溶解 500 体积的氯化氢气体"],"correctOption":"C","given":"化上 p.394 HCl 性质","method":"考虑浓 HCl 溶解产生大量 Cl⁻ 对 NaCl 溶解平衡的同离子沉淀效应","principle":"HCl 在水中极易电离出 Cl⁻，使饱和食盐水中 NaCl 结晶析出白色晶体（可用以纯化粗盐）。","steps":["A、B、D 均符合教材原文；C 错：将 \\(\\mathrm{HCl}\\) 气体通入饱和 \\(\\mathrm{NaCl}\\) 溶液中，Cl⁻ 浓度增大促使 \\(\\mathrm{NaCl(s)}\\) 晶体析出（并非无任何变化）。"],"ans":"C","markingPoints":["理解 HCl 通入饱和食盐水析出 NaCl 晶体的同离子效应"],"verification":"溶解平衡 \\(\\mathrm{NaCl(s) \\rightleftharpoons Na^+ + Cl^-}\\) 因 Cl⁻ 增多左移。","pitfall":"误以为“HCl 不和 NaCl 反应”就无任何现象。"},{"id":"chem15-15.3-q3","tier":"L3","tierLabel":"L3 预试","examStyle":"P2 简答","q":"完成教材活动14（图15-16 \\(\\mathrm{HCl}\\) 喷泉实验，水槽中盛紫色石蕊溶液）：(1) 描述引发喷泉的操作方法及实验现象；(2) 若实验结束时烧瓶内没有完全被溶液充满，分析可能的两条实验失误原因。","given":"活动14 图15-16 HCl 喷泉实验（化上 p.393）","method":"对照喷泉实验引发操作（挤滴管水+开止水夹）与不满瓶原因（漏气、混有空气、烧瓶潮湿）","principle":"极易溶气体产生压强差引发喷泉；残留不溶气体或漏气导致不满瓶。","steps":["(1) 操作：打开止水夹，挤压预先吸有少量水的胶头滴管使水进入烧瓶。现象：水槽中的紫色石蕊溶液迅速沿玻璃管喷入烧瓶，形成**红色喷泉**。","(2) 两条可能原因：① 收集的 \\(\\mathrm{HCl}\\) 气体不纯，**混有空气**（空气难溶于水留在烧瓶内）；② 实验前**烧瓶未干燥**（部分 \\(\\mathrm{HCl}\\) 提前溶于管壁水膜，甚至倒吸入水/混空气）或**装置气密性不好漏气**。"],"ans":"(1) 挤滴管水入瓶形成红色喷泉；(2) HCl 不纯混有空气，或装置漏气/烧瓶未干燥。","markingPoints":["准确叙述引发操作及红色喷泉现象（2分）","列出两条合理未充满原因（2分）"],"verification":"对照化上 p.393 活动14。","pitfall":"错答成“酚酞变红色喷泉”——图15-16 中 HCl 喷泉用的是**紫色石蕊溶液**（酸性变红；酚酞遇酸不变色！）。"},{"id":"chem15-15.3-q4","tier":"L4","tierLabel":"L4 统考压轴","examStyle":"P2 综合计算","q":"实验室将 \\(23.4\\text{ g}\\) 干燥的 \\(\\mathrm{NaCl}\\) 固体与 \\(30.0\\text{ g}\\) 质量分数为 \\(98\\%\\) 的浓硫酸混合，在 \\(550\\ ^\\circ\\mathrm{C}\\) 下充分加热反应至气体不再放出，将生成的全部 \\(\\mathrm{HCl}\\) 气体通过倒置漏斗完全吸收于 \\(100\\text{ mL}\\) 蒸馏水中（设吸收后溶液体积仍近似为 \\(100\\text{ mL}\\) 且不计损失）。(1) 判断反应物哪一种过量？(2) 计算所得稀盐酸的物质的量浓度。（\\(\\mathrm{Na}=23,\\ \\mathrm{Cl}=35.5,\\ \\mathrm{H}=1,\\ \\mathrm{S}=32,\\ \\mathrm{O}=16\\)）","given":"m(NaCl)=23.4 g (0.40 mol)；m(98% 浓H₂SO₄)=30.0 g -> m(H₂SO₄)=29.4 g (0.30 mol)；T=550℃","method":"550℃ 时按 2NaCl + H₂SO₄(浓) —Δ→ Na₂SO₄ + 2HCl↑（2:1）判定限量试剂","principle":"限量反应物判别与溶液浓度计算 c = n / V。","steps":["(1) 计算投料：\\(n(\\mathrm{NaCl}) = \\frac{23.4}{58.5} = 0.40\\text{ mol}\\)；纯硫酸 \\(m(\\mathrm{H_2SO_4}) = 30.0 \\times 98\\% = 29.4\\text{ g}\\)，\\(n(\\mathrm{H_2SO_4}) = \\frac{29.4}{98} = 0.30\\text{ mol}\\)。","在 \\(550\\ ^\\circ\\mathrm{C}\\) 下反应方程式为 \\(\\mathrm{2NaCl(s) + H_2SO_4(aq,\\text{浓})} \\xrightarrow{\\Delta} \\mathrm{Na_2SO_4(s) + 2HCl(g)\\uparrow}\\)。","\\(0.40\\text{ mol NaCl}\\) 完全反应只需消耗 \\(0.20\\text{ mol }\\mathrm{H_2SO_4}\\)，而现有 \\(0.30\\text{ mol }\\mathrm{H_2SO_4}\\)，因此 **浓硫酸（\\(\\mathrm{H_2SO_4}\\)）过量**（余 \\(0.10\\text{ mol}\\)）。","(2) 生成 \\(\\mathrm{HCl}\\) 物质的量等于限量反应物 \\(\\mathrm{NaCl}\\) 的物质的量：\\(n(\\mathrm{HCl}) = 0.40\\text{ mol}\\)。","所得盐酸浓度：\\(c(\\mathrm{HCl}) = \\frac{0.40\\text{ mol}}{0.100\\text{ L}} = 4.00\\text{ mol}\\cdot\\mathrm{L^{-1}}\\)。"],"ans":"(1) 浓硫酸过量；(2) \\(4.00\\text{ mol}\\cdot\\mathrm{L^{-1}}\\)。","markingPoints":["正确算出 0.40 mol NaCl 与 0.30 mol H₂SO₄ 并据 2:1 判断浓硫酸过量（2分）","求出 n(HCl)=0.40 mol 及浓度 4.00 mol/L（2分）"],"verification":"由于硫酸过量 0.10 mol，事实上 0.40 mol NaCl 与 0.30 mol H₂SO₄ 即使不强热在低温按 1:1 也能部分生成 NaHSO₄ 与 0.30 mol HCl，在 550℃ 强热才确保全部 0.40 mol Cl⁻ 转变成 HCl↑！","pitfall":"若按 1:1 写 NaHSO₄ 方程去判断限量，就会误以为 NaCl 过量而错算成只得 0.30 mol HCl。"}],"cheatSheet":["HCl：极易溶水（0℃ 1:500），石蕊红色喷泉；干燥 HCl 无酸性（湿润才变红）。","白雾 = 盐酸小液滴；白烟 = NH₃ + HCl → NH₄Cl 固体微粒。","制 HCl（高沸点酸制挥发性酸）：微热得 NaHSO₄，500~600℃ 强热得 Na₂SO₄；倒置漏斗刚触水面防倒吸。"],"kbEntryIds":["kb-chem15-hcl-prep"],"quiz":{"q":"为什么 HCl 气体适合在干燥烧瓶中用紫色石蕊试液做“红色喷泉”实验，而若改用无色酚酞试液却看不到颜色变化？","given":"活动14 图15-16","method":"比较石蕊与酚酞在酸性溶液中的变色范围","principle":"石蕊遇酸变红，酚酞遇酸不变色（仅遇碱变红）。","steps":["\\(\\mathrm{HCl}\\) 极易溶于水生成强酸盐酸，能引发喷泉；","酸性溶液能使**紫色石蕊试液变红**，但不能使**无色酚酞试液变色**（依然无色），因此选紫色石蕊。"],"ans":"盐酸显酸性，可使紫色石蕊变红而使无色酚酞不变色。"}},{"id":"15.4","t":"卤化物在水中的溶解性","anchor":{"pages":"化上 p.397–398 & 附录2 p.446","syllabus":"3.9.4 卤化物溶解性、卤化银感光与人工降雨及 Cl⁻/Br⁻/I⁻ 检验","examScopes":["sem2_final","uec"],"examWeight":"P1 卤化银颜色与溶液推理（思考题 15d）+ P2 附录2溶解性复分解判断","terms":"silver halides · silver chloride · silver bromide · silver iodide · solubility table","prerequisites":["离子反应与沉淀生成条件（化上 Ch 4 & 附录2）","硝酸酸化的抗干扰作用（化上 Ch 14.8）"],"goals":["结合附录2《常见酸、碱和盐的溶解性表（20℃）》掌握常见卤化物溶解性规律（氯、溴、碘化物除 Ag⁺、Pb²⁺ 盐外皆易溶）。","通过活动16 熟记 AgCl（白）、AgBr（淡黄）、AgI（黄）均不溶于稀硝酸的性质，掌握 Cl⁻、Br⁻、I⁻ 的标准检验与鉴别。","了解卤化银（AgBr/AgCl）见光分解在感光胶片/变色镜片中的应用及 AgI 人工降雨原理（图15-21）。"]},"concepts":[{"kind":"table","title":"附录2：常见酸、碱和盐的溶解性表（20℃）核心规律速查","pageRef":"化上 p.397 & p.446","body":["常见金属氯化物、溴化物、碘化物中，除 **\\(\\mathrm{Ag^+}\\)、\\(\\mathrm{Pb^{2+}}\\)** 盐（以及 \\(\\mathrm{Cu^+}\\)、\\(\\mathrm{Hg_2^{2+}}\\) 盐）外，几乎都易溶于水（注意 \\(\\mathrm{PbCl_2}\\) 冷水难溶但热水微溶）。教材附录2（p.446）汇总了五种最常考阴离子与十四个阳离子的溶解性，是配写离子方程式和设计鉴别实验的总依据。"],"table":{"headers":["阴离子家族","全溶 / 常见溶离子","微溶物质","难溶物质（沉淀）或不存在（‘—’）"],"rows":[["硝酸盐 \\(\\mathrm{NO_3^-}\\)","**全部可溶**（\\(\\mathrm{HNO_3}\\) 挥发）","无","无"],["钾/钠/铵盐 \\(\\mathrm{K^+, Na^+, NH_4^+}\\)","**全部可溶**（\\(\\mathrm{NH_3\\cdot H_2O}\\) 挥发）","无","无"],["氯化物 \\(\\mathrm{Cl^-}\\)","表内除 \\(\\mathrm{Ag^+}\\) 外均**溶**（\\(\\mathrm{HCl}\\) 挥发）","（\\(\\mathrm{PbCl_2}\\) 微溶）","**\\(\\mathrm{AgCl}\\) 难溶**（白色，不溶稀硝酸）"],["硫酸盐 \\(\\mathrm{SO_4^{2-}}\\)","多数可溶（\\(\\mathrm{Mg, Al, Zn, Fe, Cu}\\) 等）","**\\(\\mathrm{CaSO_4, Ag_2SO_4}\\)**","**\\(\\mathrm{BaSO_4}\\) 难溶**（不溶酸），\\(\\mathrm{PbSO_4}\\) 难溶"],["氢氧化物 \\(\\mathrm{OH^-}\\)","\\(\\mathrm{KOH, NaOH, Ba(OH)_2}\\) 溶","**\\(\\mathrm{Ca(OH)_2}\\)**","**\\(\\mathrm{Mg, Al, Mn, Zn, Fe^{2+}, Fe^{3+}, Cu^{2+}}\\)** 难溶；\\(\\mathrm{AgOH}\\) 不存在（‘—’）"],["碳酸盐 \\(\\mathrm{CO_3^{2-}}\\)","\\(\\mathrm{K^+, Na^+, NH_4^+}\\) 溶（\\(\\mathrm{H_2CO_3}\\) 挥发）","**\\(\\mathrm{MgCO_3}\\)**","\\(\\mathrm{Ba, Ca, Mn, Zn, Fe^{2+}, Cu, Ag}\\) 难溶；**\\(\\mathrm{Al^{3+}, Fe^{3+}}\\) 遇水分解不存在（‘—’）**"]]},"takeaway":"由附录2 立刻可知：Fe³⁺ 和 Al³⁺ 遇 CO₃²⁻ 不能生成碳酸盐沉淀，而是双水解生成 Fe(OH)₃/Al(OH)₃ 沉淀和 CO₂ 气体！"},{"kind":"experiment","title":"活动16：硝酸银与稀硝酸检验 Cl⁻、Br⁻、I⁻","pageRef":"化上 p.397–398","body":["**实验步骤与现象（活动16）**：向分别盛有 \\(\\mathrm{NaCl}\\)、\\(\\mathrm{NaBr}\\)、\\(\\mathrm{NaI}\\) 溶液的试管中滴加 \\(\\mathrm{AgNO_3}\\) 溶液，再滴加几滴**稀硝酸**：","① \\(\\mathrm{NaCl + AgNO_3 \\to AgCl(s)\\downarrow + NaNO_3}\\)（**白色**沉淀，加稀硝酸**不溶解**）；","② \\(\\mathrm{NaBr + AgNO_3 \\to AgBr(s)\\downarrow + NaNO_3}\\)（**淡黄色**沉淀，加稀硝酸**不溶解**）；","③ \\(\\mathrm{NaI + AgNO_3 \\to AgI(s)\\downarrow + NaNO_3}\\)（**黄色**沉淀，加稀硝酸**不溶解**）。","**为什么必须加稀硝酸？**因为 \\(\\mathrm{CO_3^{2-}}\\)、\\(\\mathrm{PO_4^{3-}}\\) 等也会与 \\(\\mathrm{AgNO_3}\\) 生成白色 \\(\\mathrm{Ag_2CO_3}\\) 或黄色 \\(\\mathrm{Ag_3PO_4}\\) 沉淀，但它们都能溶于稀硝酸（如 \\(\\mathrm{Ag_2CO_3 + 2HNO_3 \\to 2AgNO_3 + H_2O + CO_2\\uparrow}\\)），唯有 \\(\\mathrm{AgCl}\\)、\\(\\mathrm{AgBr}\\)、\\(\\mathrm{AgI}\\) 均不溶于稀硝酸！"],"takeaway":"特例注意：AgF 易溶于水（不沉淀），故用 AgNO₃ 检验卤离子仅适用于 Cl⁻、Br⁻、I⁻（且检验 I⁻ 不可加过浓硝酸以免氧化 I⁻）。"},{"kind":"definition","title":"卤化银的光敏分解与碘化银人工降雨","pageRef":"化上 p.397–398","body":["**感光材料与变色眼镜（思考题 15d 第1题）**：\\(\\mathrm{AgBr}\\) 和 \\(\\mathrm{AgCl}\\) 具有感光性，见光发生氧化还原分解：\\(\\mathrm{2AgBr} \\xrightarrow{\\text{光照}} \\mathrm{2Ag + Br_2}\\)（照相胶片曝光生成极细银粒，不可逆；变色眼镜镜片中掺有微晶 \\(\\mathrm{AgBr/AgCl}\\) 和极少量 \\(\\mathrm{CuO}\\)，户外紫外光下分解出银微粒变暗，回到室内又可逆复原变透明）。","**人工降雨（图15-21）**：用飞机或火箭向过冷云层播撒 \\(\\mathrm{AgI}\\) 细粉（晶格结构与冰晶极为相似），作为凝结核使水蒸气凝结成雨（**物理过程**，未涉及化学变化，思考题 15d 第2题；但会造成微量重金属银污染，可用干冰代替）。"],"takeaway":"区分：AgBr 感光曝光是化学变化（2AgBr → 2Ag + Br₂）；AgI 人工降雨作凝结核是物理变化！"}],"formulas":[{"title":"卤离子（Cl⁻、Br⁻、I⁻）检验离子方程式","tex":"\\mathrm{Ag^+(aq) + Cl^-(aq) \\longrightarrow AgCl(s)\\downarrow},\\quad \\mathrm{Ag^+(aq) + Br^-(aq) \\longrightarrow AgBr(s)\\downarrow},\\quad \\mathrm{Ag^+(aq) + I^-(aq) \\longrightarrow AgI(s)\\downarrow}","plain":"Ag+ + Cl- -> AgCl↓(白); Ag+ + Br- -> AgBr↓(淡黄); Ag+ + I- -> AgI↓(黄)","conditions":"必须在稀硝酸酸化条件下沉淀不溶解方能确认","pageRef":"化上 p.398","note":"颜色渐变规律：AgCl（白）→ AgBr（淡黄）→ AgI（黄），水溶性依次更小。"},{"title":"卤化银光分解与碳酸银溶于稀硝酸干扰排除式","tex":"\\mathrm{2AgBr(s)} \\xrightarrow{\\text{光照}} \\mathrm{2Ag(s) + Br_2(l)},\\qquad \\mathrm{Ag_2CO_3(s) + 2H^+(aq) \\longrightarrow 2Ag^+(aq) + H_2O(l) + CO_2(g)\\uparrow}","plain":"2AgBr --光照--> 2Ag + Br2; Ag2CO3 + 2H+ -> 2Ag+ + H2O + CO2↑","conditions":"AgCl、AgBr 需置于棕色试剂瓶避光保存","pageRef":"化上 p.398","note":"不可用稀盐酸代替稀硝酸酸化 AgNO₃ 检验液（会人为引入 Cl⁻！）。"}],"pitfalls":[{"title":"检验 Cl⁻ 时忘记加稀硝酸酸化（或错用稀盐酸酸化）","wrong":"“向待测液直接滴加 \\(\\mathrm{AgNO_3}\\) 溶液，出现白色沉淀就说明原溶液一定含 \\(\\mathrm{Cl^-}\\)；或者先加稀盐酸酸化后再滴 \\(\\mathrm{AgNO_3}\\)。”","diagnosis":"直接滴 \\(\\mathrm{AgNO_3}\\) 无法排除 \\(\\mathrm{CO_3^{2-}}\\)（生成白色 \\(\\mathrm{Ag_2CO_3\\downarrow}\\)）或浓 \\(\\mathrm{SO_4^{2-}}\\)（\\(\\mathrm{Ag_2SO_4}\\) 微溶）；先加稀盐酸则人为引入大量 \\(\\mathrm{Cl^-}\\)！","right":"标准检验法：**先用稀硝酸酸化（无沉淀气泡）→ 再加 \\(\\mathrm{AgNO_3}\\) 溶液**（或加 \\(\\mathrm{AgNO_3}\\) 后加足量稀硝酸不溶解），切勿用盐酸或硫酸酸化。","checkRule":"牢记分工：检 \\(\\mathrm{SO_4^{2-}}\\) 用**稀 HCl** 酸化；检 \\(\\mathrm{Cl^-}\\) 用**稀 HNO₃** 酸化！"},{"title":"误以为 AgI 人工降雨也发生了化学变化","wrong":"“飞机播撒 \\(\\mathrm{AgI}\\) 人工降雨利用了 \\(\\mathrm{AgI}\\) 见光分解放氧气的化学变化。”","diagnosis":"\\(\\mathrm{AgI}\\) 人工降雨利用的是其六方晶体结构与冰晶极其相似的性质，充当水蒸气凝结的“晶核”。","right":"\\(\\mathrm{AgI}\\) 人工降雨**未涉及化学变化**（凝结核凝水成雨属物理相变），思考题 15d 第2题。","checkRule":"AgI 人工降雨 = 物理凝结核；AgBr/AgCl 感光胶片 = 光分解化学变化。"}],"examples":[{"label":"例 15.4.1","tier":"L3","tierLabel":"L3 预试拔高","title":"无色/彩色四种盐碱溶液的沉淀溶解推断（思考题 15d 第3题）","prompt":"现有 \\(\\mathrm{K_2CO_3}\\)、\\(\\mathrm{NaOH}\\)、\\(\\mathrm{CuCl_2}\\)、\\(\\mathrm{AgNO_3}\\) 四种物质的溶液，分别置于 A、B、C、D 四支试管中，不贴标签进行如下实验：① 将 A、B 混合，产生**蓝色沉淀**；② 将 A、D 混合，产生**白色沉淀**，加入**稀硫酸**后沉淀不溶解；③ 将 C、D 混合，产生**白色沉淀**，加入**稀硝酸**后沉淀溶解且有气泡产生。请根据实验现象判断 A、B、C、D 各是什么物质，并写出 ①、②、③ 的离子方程式。","clues":"蓝色沉淀必为 Cu(OH)₂（锁定 CuCl₂ 和 NaOH）；C、D 混合生溶于酸放气泡的白沉必为 Ag₂CO₃（锁定 K₂CO₃ 和 AgNO₃）；A 既和 B 得蓝沉，又和 D 得白沉（不溶稀硫酸），说明 A 是 CuCl₂（含 Cu²⁺ 和 Cl⁻）！","strategy":"从“蓝色沉淀”和“不溶稀硫酸白沉”交叉定位 A 为 CuCl₂，继而唯一确定 B、D、C。","given":"四种溶液：K₂CO₃, NaOH, CuCl₂, AgNO₃；① A+B 蓝沉；② A+D 白沉不溶稀 H₂SO₄；③ C+D 白沉溶稀 HNO₃ 冒气泡","principle":"附录2 溶解性表沉淀规律与酸溶性质。","steps":["由 ① A、B 混合产生蓝色沉淀 \\(\\mathrm{Cu(OH)_2}\\)，可知 A、B 必为 \\(\\mathrm{CuCl_2}\\) 和 \\(\\mathrm{NaOH}\\) 中的两种。","由 ② A 与 D 产生不溶于稀硫酸的白色沉淀（四者中能与 \\(\\mathrm{CuCl_2}\\) 或 \\(\\mathrm{NaOH}\\) 生成白色沉淀的只有 \\(\\mathrm{AgNO_3}\\) 与 \\(\\mathrm{CuCl_2}\\) 反应得白色 \\(\\mathrm{AgCl}\\)——注意 \\(\\mathrm{NaOH}\\) 遇 \\(\\mathrm{AgNO_3}\\) 生棕黑色氧化银沉淀，而非白色），故 **A 必为 \\(\\mathrm{CuCl_2}\\)**，**B 为 \\(\\mathrm{NaOH}\\)**，**D 为 \\(\\mathrm{AgNO_3}\\)**！","余下 **C 为 \\(\\mathrm{K_2CO_3}\\)**。检验 ③：\\(\\mathrm{K_2CO_3}\\) 与 \\(\\mathrm{AgNO_3}\\) 混合生成白色 \\(\\mathrm{Ag_2CO_3}\\) 沉淀，加稀硝酸溶解并放出 \\(\\mathrm{CO_2}\\) 气泡，完全吻合！","离子方程式：① \\(\\mathrm{Cu^{2+} + 2OH^- \\longrightarrow Cu(OH)_2\\downarrow}\\)；② \\(\\mathrm{Ag^+ + Cl^- \\longrightarrow AgCl\\downarrow}\\)；③ \\(\\mathrm{2Ag^+ + CO_3^{2-} \\longrightarrow Ag_2CO_3\\downarrow}\\)，\\(\\mathrm{Ag_2CO_3 + 2H^+ \\longrightarrow 2Ag^+ + H_2O + CO_2\\uparrow}\\)。"],"answer":"A: \\(\\mathrm{CuCl_2}\\)，B: \\(\\mathrm{NaOH}\\)，C: \\(\\mathrm{K_2CO_3}\\)，D: \\(\\mathrm{AgNO_3}\\)。","markingPoints":["准确推断 A, B, C, D 四种物质（2分）","写出三步沉淀与酸溶离子方程式（2分）"],"verification":"对照化上 p.398 思考题 15d 第3题及 p.446 附录2 核对。","pitfall":"若把 B 当作 CuCl₂（则 A 成了 NaOH），会导致第②步 NaOH + AgNO₃ 产生棕褐色 Ag₂O 沉淀而非白色沉淀，且易溶于稀硫酸，与题设矛盾。"},{"label":"例 15.4.2","tier":"L4","tierLabel":"L4 统考压轴","title":"NaCl 与 NaBr 混合卤化物沉淀重量定量计算","prompt":"称取 \\(16.15\\text{ g}\\) 由氯化钠（\\(\\mathrm{NaCl}\\)）和溴化钠（\\(\\mathrm{NaBr}\\)）组成的固体混合物溶于蒸馏水中，加入足量稀硝酸酸化的 \\(\\mathrm{AgNO_3}\\) 溶液，充分反应后将生成的全部卤化银沉淀过滤、避光洗涤、烘干，称得沉淀总质量为 \\(33.15\\text{ g}\\)。求原固体混合物中 \\(\\mathrm{NaCl}\\) 的质量分数（保留三位有效数字）。（\\(\\mathrm{Na}=23,\\ \\mathrm{Cl}=35.5,\\ \\mathrm{Br}=80,\\ \\mathrm{Ag}=108\\)）","clues":"利用差量法（每个 X⁻ 结合 1 个 Ag⁺，沉淀比原钠盐正好重了“把 Na⁺(23) 换成 Ag⁺(108)”的质量，即每 1 mol 卤化物增重 108−23=85 g）可以秒求总物质的量！","strategy":"既可联立二元一次方程，也可用“Na⁺→Ag⁺ 置换增重 85 g/mol”一秒求得总物质的量后再解组分！","given":"m(NaCl+NaBr)=16.15 g；m(AgCl+AgBr)=33.15 g；M(NaCl)=58.5, M(NaBr)=103","principle":"卤素守恒与质量差量法。","steps":["设原混合物含 \\(\\mathrm{NaCl}\\ x\\text{ mol}\\)，\\(\\mathrm{NaBr}\\ y\\text{ mol}\\)，则反应后生成 \\(\\mathrm{AgCl}\\ x\\text{ mol}\\)（\\(M=143.5\\)），\\(\\mathrm{AgBr}\\ y\\text{ mol}\\)（\\(M=188\\)）。","由质量增重（\\(\\mathrm{Na^+ \\to Ag^+}\\) 每 \\(1\\text{ mol}\\) 增重 \\(108 - 23 = 85\\text{ g}\\)）：","\\(85(x + y) = 33.15 - 16.15 = 17.00\\text{ g} \\implies x + y = 0.200\\text{ mol}\\)。","结合原固体总质量方程：\\(58.5x + 103y = 16.15\\)。","将 \\(y = 0.200 - x\\) 代入：\\(58.5x + 103(0.200 - x) = 16.15 \\implies 20.60 - 44.5x = 16.15 \\implies 44.5x = 4.45 \\implies x = 0.100\\text{ mol}\\)。","故 \\(m(\\mathrm{NaCl}) = 0.100 \\times 58.5 = 5.85\\text{ g}\\)，质量分数 \\(w(\\mathrm{NaCl}) = \\frac{5.85}{16.15} \\times 100\\% \\approx 36.2\\%\\)。"],"answer":"原混合物中 \\(\\mathrm{NaCl}\\) 的质量分数为 \\(36.2\\%\\)。","markingPoints":["列出原盐与沉淀质量守恒方程（或差量法求出总 moles 0.200 mol）（2分）","准确解出 n(NaCl)=0.100 mol 及 m(NaCl)=5.85 g（1.5分）","算得质量分数 36.2%（0.5分）"],"verification":"\\(0.100\\text{ mol NaCl}(5.85\\text{ g}) + 0.100\\text{ mol NaBr}(10.30\\text{ g}) = 16.15\\text{ g}\\)；\\(0.100\\text{ mol AgCl}(14.35\\text{ g}) + 0.100\\text{ mol AgBr}(18.80\\text{ g}) = 33.15\\text{ g}\\)，分毫不差！","pitfall":"若沉淀洗涤烘干时未避光导致部分 AgBr 见光分解成 Ag 和 Br₂ 挥发，沉淀称重会偏小。"}],"practice":[{"id":"chem15-15.4-q1","tier":"L1","tierLabel":"L1 基础","examStyle":"P1 选择","q":"向三支分别盛有 \\(\\mathrm{NaCl}\\)、\\(\\mathrm{NaBr}\\)、\\(\\mathrm{NaI}\\) 溶液的试管中滴加 \\(\\mathrm{AgNO_3}\\) 溶液并再加稀硝酸，三支试管中观察到的沉淀颜色依次是（　）。","options":["A. 白色、淡黄色、黄色","B. 黄色、淡黄色、白色","C. 白色、橙红色、紫黑色","D. 均迅速溶解变为无色溶液"],"correctOption":"A","given":"活动16（化上 p.397–398）","method":"直接对应 AgCl、AgBr、AgI 沉淀颜色","principle":"AgCl 白、AgBr 淡黄、AgI 黄，均不溶稀硝酸。","steps":["三种卤化银均不溶于稀硝酸，颜色依次由白变淡黄再变黄。"],"ans":"A","markingPoints":["记牢 AgCl、AgBr、AgI 三色"],"verification":"对照化上 p.398。","pitfall":"把溴水/碘水在 CCl₄ 中的颜色（橙红、紫红）误安在 AgBr/AgI 上。"},{"id":"chem15-15.4-q2","tier":"L2","tierLabel":"L2 期末","examStyle":"P1 选择","q":"查阅教材《常见酸、碱和盐的溶解性表（20℃）》（附录2 p.446），下列各组物质在溶液中混合后**能**大量共存而不生成沉淀或气体的是（　）。","options":["A. \\(\\mathrm{AgNO_3}\\) 与 \\(\\mathrm{NaCl}\\)","B. \\(\\mathrm{BaCl_2}\\) 与 \\(\\mathrm{Na_2SO_4}\\)","C. \\(\\mathrm{CuSO_4}\\) 与 \\(\\mathrm{KNO_3}\\)","D. \\(\\mathrm{FeCl_3}\\) 与 \\(\\mathrm{Na_2CO_3}\\)"],"correctOption":"C","given":"附录2 常见酸碱盐溶解性表（化上 p.446）","method":"逐组排查是否存在难溶物或‘—’双水解反应","principle":"钾盐、钠盐、硝酸盐全溶；硫酸铜、硫酸钾、硝酸铜均易溶于水。","steps":["A 生成 \\(\\mathrm{AgCl\\downarrow}\\)；B 生成 \\(\\mathrm{BaSO_4\\downarrow}\\)；D 中 \\(\\mathrm{Fe^{3+}}\\) 与 \\(\\mathrm{CO_3^{2-}}\\) 在附录2 中标“—”（遇水分解），实际生成 \\(\\mathrm{Fe(OH)_3\\downarrow}\\) 和 \\(\\mathrm{CO_2\\uparrow}\\)；唯有 C 组全部离子可溶不反应。"],"ans":"C","markingPoints":["结合附录2 判断复分解与双水解共存"],"verification":"对照化上 p.446 附录2。","pitfall":"容易误选 D，以为“Fe₂(CO₃)₃”即使沉淀也未必知道其双水解，或误以为不反应。"},{"id":"chem15-15.4-q3","tier":"L3","tierLabel":"L3 预试","examStyle":"P1 选择","q":"在干旱严重的地区，可用飞机向冷云层中喷撒碘化银（\\(\\mathrm{AgI}\\)）或干冰实现人工降雨。下列有关人工降雨的说法中，**不合理**的是（　）。","options":["A. 人工降雨对改善农业灌溉与局部气候有一定积极效益","B. 大量喷撒 \\(\\mathrm{AgI}\\) 中的重金属银元素可能对土壤和水体造成潜在污染","C. 若将 \\(\\mathrm{AgI}\\) 换成干冰，可避免重金属元素污染","D. 喷撒 \\(\\mathrm{AgI}\\) 产生降雨的过程主要通过 \\(\\mathrm{AgI}\\) 分解放热发生化学变化实现"],"correctOption":"D","given":"思考题 15d 第2题（化上 p.398）","method":"对照 AgI 作人工凝结核的物理机制","principle":"AgI 人工降雨未涉及化学变化，仅作冰晶凝结核。","steps":["D 项“发生化学变化实现”不合理；AgI 人工降雨属于物理凝结过程。"],"ans":"D","markingPoints":["明确 AgI 人工降雨属物理变化"],"verification":"对照化上 p.398 思考题 15d 第2题。","pitfall":"误选 B，忽略银属于重金属对土壤水体的潜在生态影响。"},{"id":"chem15-15.4-q4","tier":"L4","tierLabel":"L4 统考压轴","examStyle":"P2 实验设计","q":"某无色工业废水中可能同时含有 \\(\\mathrm{Cl^-}\\)、\\(\\mathrm{CO_3^{2-}}\\) 和 \\(\\mathrm{SO_4^{2-}}\\) 三种阴离子。现仅提供以下试剂：稀盐酸、稀硝酸、\\(\\mathrm{Ba(NO_3)_2}\\) 溶液、\\(\\mathrm{AgNO_3}\\) 溶液。请你设计**在同一份废水样品中**依次逐一检出这三种阴离子的最严谨实验方案（注意不得因前一步加入试剂引入干扰离子），写明每步操作、现象与结论。","clues":"同一份溶液不能加 HCl（引入 Cl⁻）！应按“检并除尽 CO₃²⁻（用足量稀 HNO₃）→ 检并除尽 SO₄²⁻（用过量 Ba(NO₃)₂，注意 Ag₂SO₄ 微溶必须先除尽 SO₄²⁻！）→ 最后用 AgNO₃ 检 Cl⁻”顺序！","strategy":"三步串联：稀 HNO₃（除并检 CO₃²⁻）→ 过量 Ba(NO₃)₂（除并检 SO₄²⁻，静置取上层清液！）→ AgNO₃（检 Cl⁻）。","given":"同一样本含 Cl⁻, CO₃²⁻, SO₄²⁻；试剂：稀 HNO₃, Ba(NO₃)₂, AgNO₃（不可引入 Cl⁻）","principle":"同一份溶液串联检验防干扰规则：严禁加含待测离子试剂、先除微溶/共沉淀干扰。","steps":["① **先检并除尽 \\(\\mathrm{CO_3^{2-}}\\)**：向废水样品中加入**足量稀硝酸**至不再产生气泡为止。若有无色无味气泡（\\(\\mathrm{CO_2}\\)）产生，证明含 \\(\\mathrm{CO_3^{2-}}\\)，且酸过量已将其彻底除去（不引入 \\(\\mathrm{Cl^-}\\) 或 \\(\\mathrm{SO_4^{2-}}\\)）。","② **再检并除尽 \\(\\mathrm{SO_4^{2-}}\\)**：向上述酸化后的溶液中加入**过量 \\(\\mathrm{Ba(NO_3)_2}\\) 溶液**，充分静置。若产生白色沉淀（\\(\\mathrm{BaSO_4}\\)），证明含 \\(\\mathrm{SO_4^{2-}}\\)，且过量钡离子已将 \\(\\mathrm{SO_4^{2-}}\\) 彻底沉淀除去（防止下一步生成微溶 \\(\\mathrm{Ag_2SO_4}\\) 干扰 \\(\\mathrm{Cl^-}\\)）。","③ **最后检 \\(\\mathrm{Cl^-}\\)**：取第 ② 步反应后的**上层清液（或过滤后的滤液）**，滴加少量 **\\(\\mathrm{AgNO_3}\\) 溶液**，若产生白色沉淀（\\(\\mathrm{AgCl}\\)），证明原废水中含有 \\(\\mathrm{Cl^-}\\)。"],"ans":"顺序：足量稀 HNO₃（检除 CO₃²⁻）→ 过量 Ba(NO₃)₂ 静置取清液（检除 SO₄²⁻）→ AgNO₃（检 Cl⁻）。","markingPoints":["第一步用足量稀硝酸而非盐酸，且说明“检并除尽”CO₃²⁻（1.5分）","第二步用过量 Ba(NO₃)₂ 而非 BaCl₂，并取上层清液（1.5分）","第三步加 AgNO₃ 检出 Cl⁻ 并逻辑严密无外源引入（1.5分）"],"verification":"全过程只引入了 H⁺、NO₃⁻、Ba²⁺，无任何 Cl⁻ 或 SO₄²⁻ 外源污染！","pitfall":"若先加 AgNO₃ 后加 Ba(NO₃)₂，高浓度 SO₄²⁻ 会与 Ag⁺ 生成微溶 Ag₂SO₄ 干扰白色沉淀判断；若错用 BaCl₂ 或稀 HCl 会引入 Cl⁻。"}],"cheatSheet":["常见卤化物除 Ag⁺、Pb²⁺ 外皆易溶于水；AgCl（白）、AgBr（淡黄）、AgI（黄）均不溶于稀硝酸。","检验 Cl⁻/Br⁻/I⁻：用稀硝酸酸化的 AgNO₃ 溶液（严禁用盐酸或硫酸酸化）；同一份液三检（CO₃²⁻、SO₄²⁻、Cl⁻）：足量稀 HNO₃ → 过量 Ba(NO₃)₂ 取清液 → AgNO₃。","附录2 口诀：钾钠铵硝全可溶；氯化物不溶氯化银；硫酸盐难溶硫酸钡（微溶钙银）；碳酸盐只溶钾钠铵（Al³⁺/Fe³⁺ 遇水双水解）。"],"kbEntryIds":["kb-chem15-halide-test","kb-appendix2-solubility"],"quiz":{"q":"把变色眼镜镜片中的溴化银（\\(\\mathrm{AgBr}\\)）放到强紫外线下照晒，镜片为什么会立刻变暗？写出化学方程式。","given":"思考题 15d 第1题（化上 p.398）","method":"利用卤化银感光见光分解生成银微粒原理","principle":"2AgBr —光照→ 2Ag + Br₂。","steps":["见光发生分解：\\(\\mathrm{2AgBr(s)} \\xrightarrow{\\text{光照}} \\mathrm{2Ag(s) + Br_2(l)}\\)，生成的极细黑色银微粒使镜片变暗。"],"ans":"见光分解出细小银粒：\\(\\mathrm{2AgBr} \\xrightarrow{\\text{光照}} \\mathrm{2Ag + Br_2}\\)"}},{"id":"15.5","t":"卤氧酸","anchor":{"pages":"化上 p.399–401","syllabus":"3.9.5 卤氧酸的命名体系及酸性、稳定性与氧化性递变规律","examScopes":["sem2_final","uec"],"examWeight":"P1 酸性/稳定性/氧化性排序必考 + P2 高氯酸强氧化性配平","terms":"oxoacid · hypohalous acid · halous acid · halic acid · perhalic acid","prerequisites":["氧化数计算（化上 Ch 8.2）","氧化还原方程式配平（化上 Ch 8.4）"],"goals":["掌握表15-5 卤氧酸四级中英文命名规律（+1 次卤酸 HXO、+3 亚卤酸 HXO₂、+5 卤酸 HXO₃、+7 高卤酸 HXO₄），理解氟不能形成含氧酸的原因。","结合图15-22 对比同种卤素不同价态含氧酸（HClO → HClO₂ → HClO₃ → HClO₄）酸性、热稳定性与氧化性的变化规律。","结合图15-23 掌握次卤酸（HClO、HBrO、HIO）从氯到碘酸性、稳定性与氧化性的递变及 HIO₃ 比 HClO₃ 稳定的特性。"]},"concepts":[{"kind":"table","title":"卤氧酸的四级命名与常见存在物种（表15-5）","pageRef":"化上 p.399","body":["卤素含氧酸（oxoacid）依中心卤素原子正氧化数命名如下。注意：**氟（F）因电负性居全周期表之冠，无正氧化数，不能形成含氧酸**；氯具有全部四种价态含氧酸，其中**高氯酸（\\(\\mathrm{HClO_4}\\)）是已知最强的无机含氧酸**，也是氯的含氧酸中唯一能以纯品稳定存在的物种。"],"table":{"headers":["卤素氧化数","通式","中文名","英文名","氯 / 溴 / 碘 实际存在物种"],"rows":[["+1","\\(\\mathrm{HXO}\\)","次卤酸","hypohalous acid","\\(\\mathrm{HClO}\\)、\\(\\mathrm{HBrO}\\)、\\(\\mathrm{HIO}\\)（均不稳定，仅存于溶液）"],["+3","\\(\\mathrm{HXO_2}\\)","亚卤酸","halous acid","仅 \\(\\mathrm{HClO_2}\\)（不稳定，仅存于溶液）"],["+5","\\(\\mathrm{HXO_3}\\)","卤酸","halic acid","\\(\\mathrm{HClO_3}\\)、\\(\\mathrm{HBrO_3}\\)、\\(\\mathrm{HIO_3}\\)（碘酸较稳定可制晶体）"],["+7","\\(\\mathrm{HXO_4}\\)","高卤酸","perhalic acid","\\(\\mathrm{HClO_4}\\)（最稳定）、\\(\\mathrm{HIO_4}\\)（溴无 +7 价高溴酸于教材体系）"]]},"takeaway":"卤素中唯有氯能形成全套 +1、+3、+5、+7 四种含氧酸；记住“氟无含氧酸（F 只显 0 和 −1 价）”！"},{"kind":"law","title":"卤氧酸酸性、热稳定性与氧化性的双重递变规律（图15-22 & 15-23）","pageRef":"化上 p.400","body":["**规律一：同种卤素、不同氧化数（图15-22，以氯为例）**：","① **酸性和稳定性随氧化数升高而增强**：\\(\\mathrm{HClO < HClO_2 < HClO_3 < HClO_4}\\)（极弱酸 → 中强酸 → 强酸 → 最强无机酸）；","② **氧化性按教材图15-22 箭头方向，从 +7 价向 +1 价增强**（即稀溶液中 \\(\\mathrm{HClO}\\) 氧化性最强、最快，\\(\\mathrm{HClO_4}\\) 相对最弱——但注意热/浓高氯酸仍具极强氧化性，如工业用 \\(\\mathrm{HClO_4}\\) 氧化除去人造金刚石中混有的石墨杂质！）。","**规律二：同一氧化数、不同卤素（图15-23）**：","① 对**次卤酸（HXO）**来说，从 Cl → Br → I，**稳定性与酸性依次减弱**（\\(\\mathrm{HClO > HBrO > HIO}\\)），而依教材图15-23 所示，**氧化性从 \\(\\mathrm{HClO}\\) 到 \\(\\mathrm{HIO}\\) 增强**；","② 在**卤酸（\\(\\mathrm{HXO_3}\\)）**中，碘酸（\\(\\mathrm{HIO_3}\\)）反而比氯酸（\\(\\mathrm{HClO_3}\\)）更稳定。"],"takeaway":"备考教材必按图15-22 与图15-23 记住两条核心结论：① 同卤素正价越高，酸性越强、越稳定；② 卤酸中 HIO₃ 比 HClO₃ 稳定。"},{"kind":"mechanism","title":"高氯酸的强酸与强氧化特性及非羟基氧酸性判据","pageRef":"化上 p.399–401","body":["**最强无机含氧酸与唯一纯品**：在氯的四种含氧酸中，只有高氯酸（\\(\\mathrm{HClO_4}\\)）能脱离水溶液以纯液体形式稳定存在，且在水中完全电离，是已知最强的无机含氧酸。","**非羟基氧数目判据**：将含氧酸改写为 \\(\\mathrm{XO}_m\\mathrm{(OH)}_n\\)（\\(m\\) 为非羟基氧原子数）：\\(\\mathrm{Cl(OH)}\\)（0 个）、\\(\\mathrm{ClO(OH)}\\)（1 个）、\\(\\mathrm{ClO_2(OH)}\\)（2 个）、\\(\\mathrm{ClO_3(OH)}\\)（3 个）。非羟基氧越多，中心原子正电性越高、对羟基 O—H 键电子吸引越强，越易电离出 \\(\\mathrm{H^+}\\)，酸性与稳定性同步递增。","**人造金刚石除石墨应用（教材思考题 15e）**：工业上利用热/浓高氯酸的强氧化性氧化除去人造金刚石中夹杂的石墨：\\(\\mathrm{4HClO_4(l) + 7C(s,\\text{石墨}) \\longrightarrow 2Cl_2(g)\\uparrow + 7CO_2(g)\\uparrow + 2H_2O(l)}\\)。"],"takeaway":"判断同一元素含氧酸酸性只需数“非羟基氧原子数”：\\(\\mathrm{HClO_4(3) > HClO_3(2) > HClO_2(1) > HClO(0)}\\)。"}],"formulas":[{"title":"氯的含氧酸酸性与热稳定性递增序列","tex":"\\text{酸性与稳定性：}\\mathrm{HClO < HClO_2 < HClO_3 < HClO_4},\\qquad \\text{氧化性（图15-22）：}\\mathrm{HClO_4 < HClO_3 < HClO_2 < HClO}","plain":"酸性稳定性：HClO < HClO2 < HClO3 < HClO4; 氧化性(教材图15-22)：HClO4 < HClO3 < HClO2 < HClO","conditions":"同一种卤素、稀溶液/教材规律对照","pageRef":"化上 p.400","note":"同中心原子含氧酸酸性判断通法：非羟基氧原子数越多（0, 1, 2, 3 个），酸性越强！"},{"title":"高氯酸常温氧化除去人造金刚石中石墨杂质（思考题 15e 第2题）","tex":"\\mathrm{4HClO_4(l) + 7C(s,\\text{石墨}) \\longrightarrow 2Cl_2(g)\\uparrow + 7CO_2(g)\\uparrow + 2H_2O(l)}","plain":"4HClO4 + 7C(石墨) -> 2Cl2↑ + 7CO2↑ + 2H2O","conditions":"高氯酸中 Cl 为 +7 价，常温下选择性氧化石墨而金刚石不反应","pageRef":"化上 p.399–400","note":"利用得失电子守恒配平：Cl(+7→0, 得7e⁻)×4；C(0→+4, 失4e⁻)×7，最小公倍数 28！"}],"pitfalls":[{"title":"误以为所有卤素含氧酸的酸性或氧化性都“从 Cl 到 I 减弱”","wrong":"“次氯酸 \\(\\mathrm{HClO}\\) 比高氯酸 \\(\\mathrm{HClO_4}\\) 酸性更强；次卤酸氧化性顺序是 \\(\\mathrm{HClO > HBrO > HIO}\\)。”","diagnosis":"前者把高价含氧酸的强酸性趋势颠倒；后者违背教材图15-23 明确标示的次卤酸趋势。","right":"同种卤素，中心价态越高，**酸性和稳定性越强**（\\(\\mathrm{HClO_4}\\) 最强）；按教材图15-23，次卤酸 \\(\\mathrm{HClO \\to HBrO \\to HIO}\\) 稳定性与酸性减弱，而图15-23 箭头所示氧化性增强。","checkRule":"遇到卤氧酸排序题，直接默写教材图15-22 与图15-23 箭头方向，一字不差！"},{"title":"忘记氟元素没有正氧化数而瞎写“高氟酸 HFO₄”","wrong":"“高氟酸（\\(\\mathrm{HFO_4}\\)）是比高氯酸更强的无机酸。”","diagnosis":"氟（F）在所有元素中电负性最大，无法失去或偏离电子形成正氧化数含氧酸。","right":"教材 p.399 首句明文指出：**氟不能形成含氧酸（oxoacid）**。","checkRule":"只要看到选项出现 \\(\\mathrm{HFO}\\) 或 \\(\\mathrm{HFO_4}\\)，立刻判错！"}],"examples":[{"label":"例 15.5.1","tier":"L3","tierLabel":"L3 预试拔高","title":"高氯酸纯化人造金刚石机理与氧化还原配平（思考题 15e 第2题）","prompt":"工业上利用石墨在高温高压下人工合成金刚石，所得产品常混有未转化的石墨杂质，可用高氯酸（\\(\\mathrm{HClO_4}\\)）浸泡除去石墨。已知高氯酸与石墨在常温下反应生成三种物质：水、有毒的氯气和一种常见的无毒气态氧化物。(1) 高氯酸中氯元素的氧化数是多少？(2) 该过程主要体现了高氯酸的什么化学性质？(3) 写出并配平该反应的化学方程式。","clues":"无毒气态氧化物必为 CO₂！用化合价升降最小公倍数 28 配平 Cl(+7→0) 和 C(0→+4)。","strategy":"标出 Cl 与 C 氧化数变化，求最小公倍数配平电子转移后再补水配 H 与 O。","given":"反应物 HClO₄ + C；产物 H₂O + Cl₂ + CO₂","principle":"氧化还原反应得失电子守恒与原子守恒。","steps":["(1) 在 \\(\\mathrm{HClO_4}\\) 中，H 为 +1、O 为 −2，设 Cl 为 \\(x\\)：\\((+1) + x + 4(-2) = 0 \\implies x = +7\\)。","(2) 高氯酸将 0 价石墨氧化为 +4 价 \\(\\mathrm{CO_2}\\)，自身从 +7 价降为 0 价，主要体现了高氯酸的**强氧化性**。","(3) 配平：1 个 \\(\\mathrm{HClO_4}\\) 中 Cl(+7 → 0) **得 7e⁻**，1 个 C(0 → +4) **失 4e⁻**，最小公倍数为 28 → 取 \\(4\\ \\mathrm{HClO_4}\\) 和 \\(7\\ \\mathrm{C}\\)，生成 \\(2\\ \\mathrm{Cl_2}\\)、\\(7\\ \\mathrm{CO_2}\\)，再由 H 守恒配 \\(2\\ \\mathrm{H_2O}\\)：","\\(\\mathrm{4HClO_4(l) + 7C(s) \\longrightarrow 2Cl_2(g)\\uparrow + 7CO_2(g)\\uparrow + 2H_2O(l)}\\)。"],"answer":"(1) +7；(2) 强氧化性；(3) \\(\\mathrm{4HClO_4 + 7C \\longrightarrow 2Cl_2\\uparrow + 7CO_2\\uparrow + 2H_2O}\\)。","markingPoints":["算出 +7 价并指出强氧化性（2分）","利用电子守恒配平 4, 7 → 2, 7, 2（2分）"],"verification":"氧原子核验：左边 \\(4 \\times 4 = 16\\) 个 O；右边 \\(7 \\times 2 + 2 \\times 1 = 16\\) 个 O，完全配平！","pitfall":"若误把产物气态碳氧化物当成 CO（CO 有毒！题目明确“无毒的气态化合物”），就会写错产物与系数。"},{"label":"例 15.5.2","tier":"L2","tierLabel":"L2 校内期末","title":"卤素含氧酸命名、酸性比较及饮用水余氯检测（思考题 15e 第1题）","prompt":"(1) 写出 \\(\\mathrm{HBrO_3}\\) 和 \\(\\mathrm{HIO_4}\\) 中溴与碘的氧化数及其中文名称；(2) 市面上若有不法商贩用自来水厂氯气消毒后的自来水冒充纯净矿泉水出售，请利用本章所学知识设计一个简单实验进行鉴别（简述操作步骤、现象和结论）。","clues":"(1) 对照表15-5（+5 卤酸、+7 高卤酸）；(2) 自来水含残余 Cl⁻ 和微量 HClO，可分别用 AgNO₃/稀 HNO₃（白沉）或淀粉-KI（变蓝）检出，而纯矿泉水不含 Cl⁻（或余氯）。","strategy":"先按表15-5 定价定名；再选最灵敏的特征离子/氧化剂检测自来水余氯及 Cl⁻。","given":"HBrO₃, HIO₄；思考题 15e 第1题自来水鉴别","principle":"卤氧酸命名规则；Cl⁻ 的 AgNO₃ 检验与 HClO 的淀粉-KI 氧化变蓝反应。","steps":["(1) \\(\\mathrm{HBrO_3}\\) 中 Br 氧化数为 **+5**，名称为**溴酸**；\\(\\mathrm{HIO_4}\\) 中 I 氧化数为 **+7**，名称为**高碘酸**。","(2) 鉴别方案（任选其一，推荐双检或滴加 \\(\\mathrm{AgNO_3}\\) 溶液）：","取少量待测水样于洁净试管中，滴加**用稀硝酸酸化的 \\(\\mathrm{AgNO_3}\\) 溶液**（或加入酸化的淀粉—碘化钾溶液）。","现象与结论：若出现**白色沉淀**（或溶液变蓝），说明水中含有 \\(\\mathrm{Cl^-}\\)（或残余 \\(\\mathrm{HClO}\\)），必为**冒充的自来水**；若无明显现象，则为纯净水。"],"answer":"(1) +5 溴酸，+7 高碘酸；(2) 加稀硝酸酸化的 AgNO₃ 出现白色 AgCl 沉淀（或淀粉-KI 变蓝）即为假冒自来水。","markingPoints":["正确说出氧化数和中文命名（2分）","设计合理实验、现象与结论完整（2分）"],"verification":"对照化上 p.399 表15-5 与 p.400 思考题 15e 第1题。","pitfall":"若只写“滴加紫色石蕊看褪色”，因自来水余氯浓度极低（1 L 仅 0.002 g）不足以肉眼使石蕊显著褪色，不如 AgNO₃ 或淀粉-KI 灵敏！"}],"practice":[{"id":"chem15-15.5-q1","tier":"L1","tierLabel":"L1 基础","examStyle":"P1 选择","q":"下列卤氧酸按照酸性由弱到强、热稳定性由差到好排列正确的是（　）。","options":["A. \\(\\mathrm{HClO < HClO_2 < HClO_3 < HClO_4}\\)","B. \\(\\mathrm{HClO_4 < HClO_3 < HClO_2 < HClO}\\)","C. \\(\\mathrm{HClO < HClO_3 < HClO_2 < HClO_4}\\)","D. \\(\\mathrm{HIO < HBrO < HClO < HFO}\\)"],"correctOption":"A","given":"图15-22 氯含氧酸递变（化上 p.400）","method":"随中心 Cl 氧化数从 +1 增至 +7 判断酸性与稳定性","principle":"同种卤素氧化数越高，含氧酸酸性与热稳定性越强。","steps":["D 错（HFO 不存在）；A 完全符合教材图15-22 递增顺序。"],"ans":"A","markingPoints":["掌握氯含氧酸酸性与稳定性顺次递增"],"verification":"对照化上 p.400 图15-22。","pitfall":"误把氧化性趋势套用到酸性上而选 B。"},{"id":"chem15-15.5-q2","tier":"L2","tierLabel":"L2 期末","examStyle":"P1 选择","q":"下列关于卤素含氧酸的说法中，**不正确**的是（　）。","options":["A. 氟元素电负性最大，不能形成含氧酸","B. 氯的四种含氧酸中，只有高氯酸（\\(\\mathrm{HClO_4}\\)）最稳定可以纯态存在","C. 依据教材次卤酸性质变化规律，\\(\\mathrm{HClO}\\) 比 \\(\\mathrm{HBrO}\\)、\\(\\mathrm{HIO}\\) 更稳定、酸性更强","D. 在 \\(\\mathrm{HXO_3}\\) 型卤酸中，氯酸（\\(\\mathrm{HClO_3}\\)）比碘酸（\\(\\mathrm{HIO_3}\\)）稳定得多"],"correctOption":"D","given":"化上 p.399–400 卤氧酸正文与图15-23","method":"对照 p.400 明确陈述“而卤酸中，碘酸（HIO₃）比氯酸（HClO₃）稳定”","principle":"高价碘含氧酸热稳定性反常高于氯酸。","steps":["教材 p.400 明文指出：次卤酸中稳定性 HClO > HBrO > HIO，而**卤酸中碘酸（\\(\\mathrm{HIO_3}\\)）比氯酸（\\(\\mathrm{HClO_3}\\)）稳定**，故 D 错。"],"ans":"D","markingPoints":["记牢教材特例：卤酸中 HIO₃ 比 HClO₃ 稳定"],"verification":"对照化上 p.400 原文。","pitfall":"不看原文直接把次卤酸递变外推到卤酸而错判。"},{"id":"chem15-15.5-q3","tier":"L3","tierLabel":"L3 预试","examStyle":"P2 简答","q":"完成下表空白并回答问题：\n(1) 写出亚氯酸、高氯酸、次碘酸、溴酸的化学式；\n(2) 结合教材图15-22 和图15-23，说明在氯的四种含氧酸中，氧化性最强的和最稳定的分别是哪一种？次卤酸（\\(\\mathrm{HClO, HBrO, HIO}\\)）中酸性最弱的是哪一种？","given":"表15-5 及图15-22/15-23（化上 p.399–400）","method":"对照 +1/+3/+5/+7 价态定化学式，结合两张趋势图作答","principle":"卤氧酸四级通式与教材两张变化趋势图。","steps":["(1) 亚氯酸（+3）：\\(\\mathrm{HClO_2}\\)；高氯酸（+7）：\\(\\mathrm{HClO_4}\\)；次碘酸（+1）：\\(\\mathrm{HIO}\\)；溴酸（+5）：\\(\\mathrm{HBrO_3}\\)。","(2) 依图15-22：氯的含氧酸中（稀溶液）氧化性最强的是 **\\(\\mathrm{HClO}\\)**，最稳定的是 **\\(\\mathrm{HClO_4}\\)**；依图15-23：次卤酸中酸性从 \\(\\mathrm{HClO}\\) 到 \\(\\mathrm{HIO}\\) 减弱，故酸性最弱的是 **\\(\\mathrm{HIO}\\)**。"],"ans":"(1) \\(\\mathrm{HClO_2, HClO_4, HIO, HBrO_3}\\)；(2) 氧化性最强 HClO，最稳定 HClO₄，酸性最弱 HIO。","markingPoints":["四个化学式全部准确（2分）","三项递变极值判断全部准确（2分）"],"verification":"对照化上 p.399–400 核对无误。","pitfall":"亚氯酸和氯酸化学式易混淆（+3 亚氯酸 2 个 O，+5 氯酸 3 个 O）。"},{"id":"chem15-15.5-q4","tier":"L4","tierLabel":"L4 统考压轴","examStyle":"P2 综合计算","q":"工业用氯酸钠（\\(\\mathrm{NaClO_3}\\)）制备强效二氧化氯（\\(\\mathrm{ClO_2}\\)）水处理消毒剂时，常用 \\(\\mathrm{SO_2}\\) 气体在硫酸介质中还原氯酸钠，同时生成硫酸氢钠（\\(\\mathrm{NaHSO_4}\\)）：\\(\\mathrm{2NaClO_3(aq) + SO_2(g) + H_2SO_4(aq) \\longrightarrow 2ClO_2(g)\\uparrow + 2NaHSO_4(aq)}\\)。(1) 标出反应中氯元素与硫元素的氧化数变化，并指出氧化剂和还原剂；(2) 若要制备标准状况下 \\(4.48\\text{ L}\\) 的 \\(\\mathrm{ClO_2}\\) 气体，理论上至少需要消耗多少克 \\(\\mathrm{NaClO_3}\\)？反应共转移多少摩尔电子？（\\(\\mathrm{Na}=23,\\ \\mathrm{Cl}=35.5,\\ \\mathrm{O}=16\\)）","given":"V(ClO₂, STP)=4.48 L (0.20 mol)；M(NaClO₃)=106.5 g/mol","method":"Cl(+5 → +4, 得 1e⁻) 与 S(+4 → +6, 失 2e⁻) 计算","principle":"氯氧酸盐制备及氧化还原计量关系。","steps":["(1) Cl 氧化数由 \\(+5\\)（\\(\\mathrm{NaClO_3}\\)）降至 \\(+4\\)（\\(\\mathrm{ClO_2}\\)），故 **\\(\\mathrm{NaClO_3}\\) 为氧化剂**；S 氧化数由 \\(+4\\)（\\(\\mathrm{SO_2}\\)）升至 \\(+6\\)（\\(\\mathrm{NaHSO_4}\\)），故 **\\(\\mathrm{SO_2}\\) 为还原剂**。","(2) 生成 \\(\\mathrm{ClO_2}\\) 的物质的量：\\(n(\\mathrm{ClO_2}) = \\frac{4.48\\text{ L}}{22.4\\text{ L}\\cdot\\mathrm{mol^{-1}}} = 0.20\\text{ mol}\\)。","由方程式 \\(n(\\mathrm{NaClO_3}) = n(\\mathrm{ClO_2}) = 0.20\\text{ mol}\\)，故 \\(m(\\mathrm{NaClO_3}) = 0.20 \\times 106.5 = 21.3\\text{ g}\\)。","每生成 \\(1\\text{ mol }\\mathrm{ClO_2}\\) 仅转移 \\(1\\text{ mol }e^-\\)（+5 → +4），故反应共转移电子 **\\(0.20\\text{ mol}\\)**。"],"ans":"(1) 氧化剂 \\(\\mathrm{NaClO_3}\\)，还原剂 \\(\\mathrm{SO_2}\\)；(2) 消耗 \\(21.3\\text{ g}\\) \\(\\mathrm{NaClO_3}\\)，转移 \\(0.20\\text{ mol}\\) 电子。","markingPoints":["准确标出 Cl(+5→+4) 和 S(+4→+6) 并判别角色（2分）","算出 NaClO₃ 质量 21.3 g 与电子转移 0.20 mol（2分）"],"verification":"同时消耗 \\(0.10\\text{ mol }\\mathrm{SO_2}\\)，\\(0.10 \\times 2 = 0.20\\text{ mol }e^-\\)，完全守恒。","pitfall":"错算 Cl(+5→0) 转移 5 份电子，忽略产物是 +4 价的 ClO₂。"}],"cheatSheet":["表15-5 四级命名：+1 次卤酸(HXO)、+3 亚卤酸(HXO₂)、+5 卤酸(HXO₃)、+7 高卤酸(HXO₄)；F 无含氧酸。","同卤素递变（图15-22）：HClO → HClO₂ → HClO₃ → HClO₄，酸性与稳定性↑，稀溶液氧化性↓（但 HClO₄ 仍能氧化石墨）。","同价次卤酸（图15-23）：HClO → HBrO → HIO，酸性与稳定性↓，教材标示氧化性↑；而卤酸中 HIO₃ 比 HClO₃ 稳定。"],"kbEntryIds":["kb-chem15-oxoacids"],"quiz":{"q":"为什么氟元素（F）在所有卤素中非金属性最强，却**不能**形成类似 \\(\\mathrm{HClO}\\) 或 \\(\\mathrm{HClO_4}\\) 的含氧酸？","given":"化上 p.399 卤氧酸开篇","method":"从电负性大小与 F 在化合物中的唯一化合价分析","principle":"氟是电负性最大的元素，只得电子不失电子（无正氧化数）。","steps":["含氧酸中心卤素须呈正氧化数（+1, +3, +5, +7），电子云偏向氧原子。","而氟的电负性大于氧，在任何化合物中只显 −1 价而不显正氧化数，故不能形成含氧酸。"],"ans":"氟的电负性大于氧（全周期表最大），在化合物中只显 −1 价而无正氧化数，因此不能形成含氧酸。"}}]},"化学16":{"lessonKey":"化学16","courseCode":"chemistry","subject":"化学","chapter":16,"title":"过渡元素","syllabus":"3.5 过渡元素","bookId":"sm1-chemistry-2017","bookCitation":"《马来西亚华文独中教科书 · 化学（上册）》（2017年11月版）第16章 p.408–440","examScopes":["sem2_final","uec"],"chapterOverview":{"summary":"第16章聚焦周期表中部（IIIB 至 IIB 族）的过渡元素（d 区与 f 区金属）：从能量最低原理与 3d/4s 能级交错阐明其核外电子排布（含 Cr 3d⁵4s¹、Cu 3d¹⁰4s¹ 特例），归纳五大通性（全为金属高熔高硬、多种氧化数、有色离子与化合物、易形成配合物、优良催化性能），再以最重要且高频必考的两种金属——**铁（Fe）**（铁三角转化、氧化物与氢氧化物变色、Fe²⁺/Fe³⁺ 四法检验、高炉炼铁与转炉炼钢）和**铜（Cu）**（铜绿、CuO/Cu₂O、胆矾、Cu²⁺ 三法检验及黄铜矿冶炼与粗铜电解精炼）为核心展开。","conceptTree":[{"branch":"1. 过渡元素概论与五大通性（p.408–413）","items":["IIIB–IIB 族 10 个纵行 · 3d/4s 填充与 Cr(3d⁵4s¹)/Cu(3d¹⁰4s¹)","高熔沸高硬（W、Os、Cr）· 多价态（表16-1 Mn +2~+7）· 催化活性（d带空穴）","表16-2/16-3 有色离子 · 配离子（[Cu(NH₃)₄]²⁺ 深蓝、[Ag(NH₃)₂]⁺）"]},{"branch":"2. 铁：性质、铁三角、检验与冶炼（p.413–427）","items":["Fe + 弱氧化剂(HCl/Cu²⁺/S) → Fe²⁺；+ 强氧化剂(Cl₂/热浓H₂SO₄) → Fe³⁺；+ H₂O(g) → Fe₃O₄","Fe(OH)₂ 白→灰绿→红褐 · 铁三角转化（Fe+2Fe³⁺→3Fe²⁺；2Fe³⁺+Cu→2Fe²⁺+Cu²⁺）","表16-8 Fe²⁺/Fe³⁺ 四法检验（KSCN、NaOH、K₄/K₃[Fe(CN)₆]、H₂S）","高炉炼铁（CO还原 + CaCO₃/CaO 造 CaSiO₃ 渣）· 氧气顶吹转炉炼钢"]},{"branch":"3. 铜：性质、检验、冶炼与精炼（p.428–435）","items":["不与稀盐酸/稀硫酸反应 · 溶浓硫酸/浓稀硝酸 · Cu₂(OH)₂CO₃ 铜绿","CuO(黑) —1100℃+Cu→ Cu₂O(红) · 胆矾 CuSO₄·5H₂O 蓝⇄白检水","Cu²⁺ 检验（NaOH 蓝沉、H₂S 黑沉、过量氨水深蓝 [Cu(NH₃)₄]²⁺）","黄铜矿火法炼铜 · 粗铜电解精炼（阳极泥含 Au, Ag）"]}]},"paperFocus":["下半年期末考 / UEC 统考卷一（30%）：常考第4周期过渡元素电子排布（Cr、Cu、Fe³⁺ 3d⁵ 半满稳态）、表16-2/16-3 离子与硅胶变色（CoCl₂）、Fe³⁺/Cu²⁺/Fe/Cu 混合体系共存判断（思考题 16b/16c）、Fe²⁺/Fe³⁺ 检验试剂选择以及生铁与钢含碳量区别。","UEC 统考卷二甲部必答/探究（34%）及乙部无机选答（18%）：高频命制“铁三角”框图推断、Fe(OH)₂ 制备防氧化探究、高炉炼铁与转炉炼钢方程式、印刷电路板 FeCl₃ 蚀刻铜计算、Cu²⁺ 配合物实验与粗铜电解精炼电极分析。"],"solvingWorkflow":["金属+氧化剂混合体系共存排序铁律：牢记氧化性 **Fe³⁺ > Cu²⁺ > H⁺ > Fe²⁺**，还原性 **Fe > Cu > Fe²⁺**。只要溶液中有 Fe 粉剩余，绝对不可能存在 Fe³⁺ 和 Cu²⁺；只要溶液中有 Fe³⁺ 剩余，绝对不可能存在 Fe 粉和 Cu 粉！","Fe²⁺ 与 Fe³⁺ 鉴别策略：只检 Fe³⁺ 选 **KSCN**（血红）或 **K₄[Fe(CN)₆]**（深蓝）；在有大量 Fe³⁺ 存在下要检出微量 Fe²⁺，不可用 NaOH（红褐掩盖白沉），应选 **K₃[Fe(CN)₆]**（深蓝）或**酸性 KMnO₄**（褪色）。","配合物离子方程式书写：氨水过量溶 AgCl 得 \\(\\mathrm{[Ag(NH_3)_2]^+}\\)、溶 Cu(OH)₂ 得深蓝色 \\(\\mathrm{[Cu(NH_3)_4]^{2+}}\\)，注意配位数 Ag⁺ 为 2（直线）、Cu²⁺ 为 4（平面正方形）。","电解精炼铜阳极质量与电解液变化：阳极溶解比 Cu 活泼的 Zn、Fe 和 Cu，阴极只析出 Cu，因此电解液中 \\(c(\\mathrm{Cu^{2+}})\\) 略有下降，而不活泼的 Au、Ag 沉入阳极泥。"],"questionTypes":["过渡元素电子排布（d/s 能级交错）、有色水合离子与配离子结构分析","Fe—Fe²⁺—Fe³⁺ 铁三角转化及 Fe³⁺/Cu²⁺/Fe/Cu 混合反应后固液成分判断","Fe²⁺/Fe³⁺ 检验方法对比及防氧化制备 Fe(OH)₂ 实验探究","高炉炼铁反应分区、造渣除 SiO₂ 及转炉炼钢脱碳脱氧计算","Cu²⁺ 检验、胆矾脱水热重计算及粗铜电解精炼原理分析"],"scoringNotes":["书写 \\(\\mathrm{Fe^{3+}}\\) 与 \\(\\mathrm{SCN^-}\\) 反应时，教材 p.412 与 p.421 明确写作 \\(\\mathrm{Fe^{3+}(aq) + SCN^-(aq) \\longrightarrow [Fe(SCN)]^{2+}(aq)}\\)（血红色配离子，不是沉淀！不可加沉淀箭头 ↓）。","答高炉炼铁“铁矿石中焦炭的作用”有两点：① 燃烧放热提供高温；② 生成还原剂 CO 还原氧化铁。石灰石作用是分解成 CaO 结合脉石 SiO₂ 生成炉渣 CaSiO₃。"],"vid":[{"t":"过渡元素核外电子排布、颜色与配合物","q":"过渡元素通性 配位化合物 电子排布 高中化学"},{"t":"铁三角氧化还原与 Fe²⁺/Fe³⁺ 检验专题","q":"铁三角 铁离子与亚铁离子的检验 高中化学"},{"t":"高炉炼铁、转炉炼钢及 Fe₃O₄ 反应","q":"高炉炼铁 炼钢 铁与水蒸气 高中化学"},{"t":"铜的性质、Cu²⁺ 检验与粗铜电解精炼","q":"铜的性质 铜离子检验 粗铜电解精炼 高中化学"}],"sections":[{"id":"16.1","t":"过渡元素的概论","anchor":{"pages":"化上 p.408–409","syllabus":"3.5.1 过渡元素周期表位置及 (n−1)d/ns 核外电子排布特征","examScopes":["sem2_final","uec"],"examWeight":"P1 电子排布（含 Cr、Cu 半满全满特例）+ 周期表分区概念","terms":"transition elements · d-block · Aufbau principle · titanium · biological metal","prerequisites":["能量最低原理、泡利不相容原理与洪特规则（化上 Ch 5.4）","元素周期表 s/p/d/f 分区结构（化上 Ch 6.3.2）"],"goals":["准确说出过渡元素在周期表中的位置（第 IIIB 族至 IIB 族共 10 个纵行，包含镧系和锕系），理解其连接 s 区与 p 区的桥梁地位。","结合图16-1 与能量最低原理，书写 Sc 至 Zn（Z=21–30）的外围电子排布式，并解释 Cr（3d⁵4s¹）与 Cu（3d¹⁰4s¹）的特例原因。","了解重要过渡金属钛（Ti）的优异性能及“生物金属”、宇航材料应用。"]},"concepts":[{"kind":"definition","title":"过渡元素在周期表中的位置与电子排布特点（图16-1）","pageRef":"化上 p.408–409","body":["**定义与位置**：元素周期表中间从 **IIIB 族到 IIB 族共 10 个纵行**（包括镧系和锕系），习惯上称为过渡元素。它们像桥梁一样把左边活泼的 s 区金属（IA、IIA）与右边 p 区金属、准金属和非金属连接起来。","**能级交错与轨道填充**：一般过渡元素原子含有未充满的 d 和 f 副层轨域。因 **3d 轨域能量高于 4s 轨域而低于 4p 轨域**，根据能量最低原理，电子先填满 4s（两个电子），再从 Z=21（Sc）起逐步填充到次外层 3d 轨域（如 Sc 为 \\(3d^1 4s^2\\)、Fe 为 \\(3d^6 4s^2\\)、Zn 为 \\(3d^{10} 4s^2\\)）；镧系、锕系则主要填充倒数第 3 层的 f 轨域。"],"takeaway":"注意主族元素递增电子填在最外层，而第4周期过渡元素递增电子主要填在“次外层 3d 轨域”，最外层始终只有 1~2 个 4s 电子！"},{"kind":"table","title":"第4周期过渡元素（Sc → Zn）外围电子排布与特例对照","pageRef":"化上 p.408、p.410","body":["根据洪特规则特例：等价轨域全空（\\(d^0\\)）、**半充满（\\(d^5\\)）**或**全充满（\\(d^{10}\\)）**时体系能量更低、更稳定，因此 **Cr（24号）** 和 **Cu（29号）** 各自有一个 4s 电子跃迁进入 3d 轨域。"],"table":{"headers":["元素与原子序数","族别","外围电子排布式","核心结构特点"],"rows":[["Sc (21) / Ti (22) / V (23)","IIIB / IVB / VB","\\(3d^1 4s^2\\) / \\(3d^2 4s^2\\) / \\(3d^3 4s^2\\)","电子依次填入次外层 3d"],["**Cr (24)**","VIB","**\\(3d^5 4s^1\\)**（特例！）","3d 半满、4s 半满双稳定构型（非 \\(3d^4 4s^2\\)）"],["Mn (25) / Fe (26) / Co (27) / Ni (28)","VIIB / VIIIB","\\(3d^5 4s^2\\) / \\(3d^6 4s^2\\) / \\(3d^7 4s^2\\) / \\(3d^8 4s^2\\)","Fe 失 2 个 4s 得 \\(\\mathrm{Fe^{2+}}(3d^6)\\)，再失 1 个 3d 得稳态 \\(\\mathrm{Fe^{3+}}(3d^5)\\)"],["**Cu (29)**","IB","**\\(3d^{10} 4s^1\\)**（特例！）","3d 全满、4s 半满（非 \\(3d^9 4s^2\\)）"],["Zn (30)","IIB","\\(3d^{10} 4s^2\\)","3d 全充满（\\(\\mathrm{Zn^{2+}}\\) 亦为 \\(3d^{10}\\) 故无色、氧化数唯一）"]]},"takeaway":"在书写过渡金属阳离子电子排布时，务必记住：电子总是**先失去最外层 4s 电子**，后失去次外层 3d 电子！"},{"kind":"definition","title":"典型过渡金属应用——“生物金属”钛（Ti）","pageRef":"化上 p.408","body":["**钛（Ti，Z=22，\\(3d^24s^2\\)）**：强度与钢相近但比钢轻 **45%**；仅比铝重约 60%，但强度是铝的两倍，且耐高低温耐腐蚀，广泛用于宇航工业、火箭、喷气发动机与导弹。","**生物金属**：钛对人体完全无毒无排异，能够与肌肉和骨骼生长在一起，因此广泛用于制造人造关节和接骨固定材料。"],"takeaway":"金属钛冶炼常用活泼金属 Na 或 Mg 在高温下还原 TiCl₄（p.434）：TiCl₄ + 4Na —高温→ Ti + 4NaCl。"}],"formulas":[{"title":"第4周期典型原子及离子外围电子排布转化","tex":"\\mathrm{Fe}:\\ [\\mathrm{Ar}]3d^6 4s^2 \\xrightarrow{-2e^-} \\mathrm{Fe^{2+}}:\\ [\\mathrm{Ar}]3d^6 \\xrightarrow{-e^-} \\mathrm{Fe^{3+}}:\\ [\\mathrm{Ar}]3d^5","plain":"Fe([Ar]3d6 4s2) -> Fe2+([Ar]3d6) -> Fe3+([Ar]3d5)","conditions":"电离时先失去能量较高的最外层 4s 电子，再失去 3d 电子","pageRef":"化上 p.408–409、p.414","note":"Fe³⁺ 的 3d⁵ 半充满结构比 Fe²⁺ 的 3d⁶ 结构更稳定。"},{"title":"铜及其常见阳离子电子排布转化","tex":"\\mathrm{Cu}:\\ [\\mathrm{Ar}]3d^{10} 4s^1 \\xrightarrow{-e^-} \\mathrm{Cu^+}:\\ [\\mathrm{Ar}]3d^{10},\\qquad \\mathrm{Cu} \\xrightarrow{-2e^-} \\mathrm{Cu^{2+}}:\\ [\\mathrm{Ar}]3d^9","plain":"Cu([Ar]3d10 4s1) -> Cu+([Ar]3d10); Cu -> Cu2+([Ar]3d9)","conditions":"水溶液中由于 Cu²⁺ 水合能远大于 Cu⁺，Cu²⁺(aq) 比 Cu⁺(aq) 稳定","pageRef":"化上 p.408、p.429","note":"Cu⁺ 3d¹⁰ 全满无未成对电子（多数白色或无色），Cu²⁺ 3d⁹ 有 1 个未成对电子呈蓝色。"}],"pitfalls":[{"title":"过渡金属失电子形成离子时错先拆 3d 电子","wrong":"“\\(\\mathrm{Fe}\\)（\\(3d^64s^2\\)）失去 2 个电子生成 \\(\\mathrm{Fe^{2+}}\\) 的外围排布是 \\(3d^44s^2\\)。”","diagnosis":"虽然原子填充电子时先填 4s 后填 3d，但一旦电子填入 3d 后，3d 处于内层受到屏蔽较弱，能量反而低于外层 4s。","right":"过渡金属原子电离失电子时**一律先失去最外层 4s 电子**，故 \\(\\mathrm{Fe^{2+}}\\) 为 **\\(3d^6\\)**，\\(\\mathrm{Fe^{3+}}\\) 为 **\\(3d^5\\)**，\\(\\mathrm{Cu^{2+}}\\) 为 **\\(3d^9\\)**。","checkRule":"写过渡金属离子电子排布，把 4s 抹掉再数 3d，绝对不能留下 4s²！"},{"title":"忘记 Cr 与 Cu 的半满/全满特例","wrong":"“24 号铬（Cr）和 29 号铜（Cu）的外围电子排布分别是 \\(3d^44s^2\\) 和 \\(3d^94s^2\\)。”","diagnosis":"忽视了 3d 轨道半充满（\\(3d^5\\)）和全充满（\\(3d^{10}\\)）具有额外交换能稳定性。","right":"正确排布：**Cr 为 \\(3d^54s^1\\)**，**Cu 为 \\(3d^{10}4s^1\\)**（教材 p.408 图16-1 及 p.410 表16-1）。","checkRule":"考电子排布选择题，遇 Cr(24) 找 `3d⁵4s¹`，遇 Cu(29) 找 `3d¹⁰4s¹`！"}],"examples":[{"label":"例 16.1.1","tier":"L2","tierLabel":"L2 校内期末","title":"Fe³⁺ 比 Fe²⁺ 稳定及第4周期元素电子排布判断","prompt":"(1) 写出 24 号元素铬（Cr）、25 号元素锰（Mn）和 29 号元素铜（Cu）基态原子的核外外围电子排布式；(2) 从电子排布结构解释为什么水溶液中 \\(\\mathrm{Fe^{3+}}\\) 通常比 \\(\\mathrm{Fe^{2+}}\\) 更稳定（空气中 \\(\\mathrm{Fe^{2+}}\\) 易被氧化为 \\(\\mathrm{Fe^{3+}}\\)）。","clues":"参考教材 p.414 图16-8 轨域表示式。","strategy":"严格遵循能级顺序及半满/全满特例写排布，再对比 3d⁵ 与 3d⁶ 未成对电子数稳定性。","given":"Z(Cr)=24, Z(Mn)=25, Z(Cu)=29, Z(Fe)=26","principle":"能量最低原理与洪特规则半充满/全充满稳态。","steps":["(1) Cr(24)：\\(3d^5 4s^1\\)；Mn(25)：\\(3d^5 4s^2\\)；Cu(29)：\\(3d^{10} 4s^1\\)。","(2) Fe 原子外围电子排布为 \\(3d^6 4s^2\\)。失去 2 个 4s 电子形成 \\(\\mathrm{Fe^{2+}}\\)（\\(3d^6\\)），再失去 1 个 3d 电子形成 \\(\\mathrm{Fe^{3+}}\\)（\\(3d^5\\)）。由于 \\(\\mathrm{Fe^{3+}}\\) 的 3d 轨域处于 5 个轨域各占 1 个自旋平行电子的**半充满稳定结构**，能量更低，故 \\(\\mathrm{Fe^{3+}}\\) 比 \\(\\mathrm{Fe^{2+}}\\) 稳定。"],"answer":"(1) Cr: \\(3d^54s^1\\)，Mn: \\(3d^54s^2\\)，Cu: \\(3d^{10}4s^1\\)；(2) \\(\\mathrm{Fe^{3+}}\\) 的 \\(3d^5\\) 为半充满稳定结构。","markingPoints":["三个外围电子排布式全对（2分）","准确写出 Fe²⁺(3d⁶) 与 Fe³⁺(3d⁵) 并指出 3d⁵ 半充满稳态（2分）"],"verification":"对照化上 p.408 图16-1 与 p.414 图16-8。","pitfall":"若写全电子排布忘了前面 `[Ar]` 即 `1s²2s²2p⁶3s²3p⁶`，题目问“外围电子排布（价电子排布）”只需写 `3d... 4s...`。"},{"label":"例 16.1.2","tier":"L3","tierLabel":"L3 预试拔高","title":"未成对电子数与氧化数极限推算","prompt":"某第4周期过渡元素基态原子 M，其 3d 轨域中未成对电子数在同周期过渡元素中最少（非 0），且 M 的常见稳定氧化数为 +1 和 +2（以 +2 最稳）。(1) 推断元素 M 是哪一种元素，写出其基态原子完整核外电子排布式；(2) 该元素形成 +2 价离子后，3d 轨域中还有几个未成对电子？若将 Zn 排除在典型变价过渡元素外，试从电子结构解释 Zn 为何只有 +2 价而 Mn 最高可达 +7 价。","clues":"3d¹⁰ 4s¹ 的 Cu 在基态仅 4s 有 1 个未成对电子（或 Sc 3d¹ 仅 1 个，但 Sc 只有 +3 价！）；Cu 常见 +1 和 +2 价！","strategy":"结合氧化数 +1/+2 锁定 Cu，再用“ns 与 (n−1)d 电子均可参与成键，而全满 3d¹⁰ 极难拆开”解释 Zn 与 Mn 差异。","given":"第4周期过渡元素，稳定氧化数 +1, +2","principle":"轨域表示式与价电子成键数限制。","steps":["(1) 第4周期过渡元素中唯一常见 +1 和 +2 氧化数的是**铜（Cu, Z=29）**。其基态完整核外电子排布式为：\\(1s^2 2s^2 2p^6 3s^2 3p^6 3d^{10} 4s^1\\)（基态总计仅 4s 上有 1 个未成对电子）。","(2) \\(\\mathrm{Cu^{2+}}\\) 排布为 \\([\\mathrm{Ar}]3d^9\\)，5 个 3d 轨域中 4 个全满、1 个半满，故有 **1 个**未成对电子。","原因解释：Zn（\\(3d^{10}4s^2\\)）的次外层 3d 轨域已经**全充满**且能量很低，难以再失去或参与成键，只能失去最外层 2 个 4s 电子故氧化数唯一为 +2；而 Mn（\\(3d^54s^2\\)）的 4s 与未充满的 3d 轨域能量相近，共有 7 个电子可逐步参与成键，故最高氧化数可达 +7（如 \\(\\mathrm{KMnO_4}\\)）。"],"answer":"(1) 铜（Cu），\\(1s^22s^22p^63s^23p^63d^{10}4s^1\\)；(2) 1 个未成对电子；Zn 的 3d¹⁰ 全满不参与成键故只有 +2 价，Mn 的 3d⁵4s² 共 7 个电子皆可成键故最高 +7 价。","markingPoints":["锁定 Cu 并写出完整电子排布式（2分）","数出 Cu²⁺ 含 1 个未成对电子（1分）","从 3d¹⁰ 全满稳态与 3d/4s 能量相近解释 Zn(+2) 和 Mn(+7)（2分）"],"verification":"对照化上 p.410 表16-1 核验。","pitfall":"若写错 `Cu²⁺` 电子排布为 `3d⁸4s¹`，就会误答成有 3 个未成对电子。"}],"practice":[{"id":"chem16-16.1-q1","tier":"L1","tierLabel":"L1 基础","examStyle":"P1 选择","q":"过渡元素在元素周期表中的位置是（　）。","options":["A. IA 族和 IIA 族","B. IIIA 族至 VIIA 族","C. IIIB 族至 IIB 族共 10 个纵行（含镧系和锕系）","D. 第 4 周期至第 7 周期的 0 族元素"],"correctOption":"C","given":"化上 p.408 过渡元素概论","method":"直接对应周期表副族与 VIII 族位置","principle":"IIIB 到 IIB 族共 10 个纵行（其中 VIIIB 占 3 个纵行）。","steps":["教材 p.408 原文：从 IIIB 族到 IIB 族的 10 个纵行，包括镧系和锕系，称为过渡元素。"],"ans":"C","markingPoints":["牢记 IIIB 至 IIB 族 10 个纵行"],"verification":"对照化上 p.408。","pitfall":"误把第 VIII 族看成 1 列而错以为只有 8 个纵行。"},{"id":"chem16-16.1-q2","tier":"L2","tierLabel":"L2 期末","examStyle":"P1 选择","q":"下列基态原子或离子的外围（价）电子排布式书写**正确**的是（　）。","options":["A. \\(\\mathrm{Cr}\\): \\(3d^4 4s^2\\)","B. \\(\\mathrm{Cu}\\): \\(3d^9 4s^2\\)","C. \\(\\mathrm{Fe^{2+}}\\): \\(3d^4 4s^2\\)","D. \\(\\mathrm{Fe^{3+}}\\): \\(3d^5\\)"],"correctOption":"D","given":"图16-1 与图16-8 排布式","method":"检验半满/全满特例及先失 4s 电子规则","principle":"Cr 为 3d⁵4s¹；Cu 为 3d¹⁰4s¹；电离先失 4s。","steps":["A 应为 \\(3d^54s^1\\)；B 应为 \\(3d^{10}4s^1\\)；C 应为 \\(3d^6\\)；D 项 \\(\\mathrm{Fe^{3+}}\\) 正确。"],"ans":"D","markingPoints":["准确应用能量最低原理与特例"],"verification":"对照化上 p.408、p.414。","pitfall":"极易错选 A 或 C。"},{"id":"chem16-16.1-q3","tier":"L3","tierLabel":"L3 预试","examStyle":"P1 选择","q":"过渡金属钛（\\(\\mathrm{Ti}\\)）因优异的性能被称为“生物金属”和宇航金属。下列有关钛及过渡元素结构特点的说法中，**错误**的是（　）。","options":["A. 钛的强度与钢相近，但质量轻得多，且无毒能与骨骼肌肉相容","B. 第 4 周期过渡元素递增的电子大多填充在次外层 \\(3d\\) 轨域中","C. 过渡元素原子的最外层电子数通常不超过 2 个","D. 过渡元素中包含少量像硅、砷一样的准金属和非金属元素"],"correctOption":"D","given":"化上 p.408–409 原文","method":"核对过渡元素全为金属的本质","principle":"所有过渡元素最外层电子数一般为 1~2 个，全都是金属元素（亦称过渡金属）。","steps":["D 错：过渡元素**全都是金属元素**，不存在准金属或非金属元素。"],"ans":"D","markingPoints":["明确过渡元素 100% 是金属"],"verification":"对照化上 p.409“过渡元素都是金属”。","pitfall":"把 p 区金属与准金属的位置混入 d 区过渡元素。"},{"id":"chem16-16.1-q4","tier":"L4","tierLabel":"L4 统考压轴","examStyle":"P2 简答","q":"写出原子序数从 21（Sc）到 30（Zn）的第 4 周期过渡元素中：(1) 哪些原子的基态电子排布不严格按“先填满 \\(4s^2\\) 再填 \\(3d\\)”顺序，而是出现 \\(4s^1\\) 构型？写出它们的外围电子排布式并说明结构原因；(2) 对比 \\(\\mathrm{Sc^{3+}}\\)、\\(\\mathrm{Ti^{3+}}\\)、\\(\\mathrm{Fe^{2+}}\\)、\\(\\mathrm{Fe^{3+}}\\)、\\(\\mathrm{Zn^{2+}}\\) 五种离子的 \\(3d\\) 电子数，指出哪些离子具有 \\(d^0\\) 或 \\(d^{10}\\) 闭壳层结构（据此预测其水溶液是否无色）。","given":"Z=21~30 原子与离子电子排布","method":"识别 Cr(24), Cu(29) 特例；按先失 4s 后失 3d 逐一计算 3d 电子数","principle":"半满(d⁵)/全满(d¹⁰)额外稳定；d⁰ 与 d¹⁰ 离子不能发生 d-d 电子跃迁故通常无色。","steps":["(1) 出现 \\(4s^1\\) 构型的是**铬（Cr，\\(3d^5 4s^1\\)）**和**铜（Cu，\\(3d^{10} 4s^1\\)）**。原因：等价的 3d 轨域在**半充满（\\(3d^5\\)）**或**全充满（\\(3d^{10}\\)）**时体系能量更低、更稳定，故各自有 1 个 4s 电子进入 3d 轨域。","(2) 五种离子的 3d 电子数依次为：\\(\\mathrm{Sc^{3+}}\\)（\\(3d^0\\)）、\\(\\mathrm{Ti^{3+}}\\)（\\(3d^1\\)）、\\(\\mathrm{Fe^{2+}}\\)（\\(3d^6\\)）、\\(\\mathrm{Fe^{3+}}\\)（\\(3d^5\\)）、\\(\\mathrm{Zn^{2+}}\\)（\\(3d^{10}\\)）。","具有 \\(d^0\\) 或 \\(d^{10}\\) 结构的离子是 **\\(\\mathrm{Sc^{3+}}\\)** 和 **\\(\\mathrm{Zn^{2+}}\\)**，它们无未充满 d 轨域跃迁，水溶液呈**无色**（其余三种因 3d 未充满而分别呈紫红、浅绿、棕黄色）。"],"ans":"(1) Cr(3d⁵4s¹) 与 Cu(3d¹⁰4s¹)；(2) Sc³⁺(3d⁰) 与 Zn²⁺(3d¹⁰) 无色。","markingPoints":["正确指出 Cr、Cu 排布及半满/全满原因（2分）","全部算对五种离子 3d 电子数并指出 Sc³⁺、Zn²⁺ 无色（2.5分）"],"verification":"对照化上 p.410–411 表16-1 与表16-2 颜色数据完全相符。","pitfall":"误以为 Fe³⁺(3d⁵) 半满也无色——3d⁵ 仍有 5 个未充满空自旋态，跃迁吸收可见光呈棕黄色！"}],"cheatSheet":["过渡元素：IIIB~IIB 族 10 个纵行（含镧系、锕系），全为金属；3d 能量高于 4s 低于 4p。","两大特例：Cr = 3d⁵4s¹（半满），Cu = 3d¹⁰4s¹（全满）。","离子电离规则：先失去最外层 4s 电子（如 Fe²⁺ = 3d⁶，Fe³⁺ = 3d⁵ 半满稳态，Cu²⁺ = 3d⁹）。"],"kbEntryIds":["kb-chem16-config"],"quiz":{"q":"基态锰原子（Mn，Z=25）的核外电子排布中，未成对电子共有几个？Mn 失去 2 个电子形成 \\(\\mathrm{Mn^{2+}}\\) 后，未成对电子数是否发生变化？","given":"Z(Mn)=25","method":"写出 Mn(3d⁵4s²) 与 Mn²⁺(3d⁵) 轨域表示式数单电子","principle":"电离先失 4s²（成对电子），3d⁵ 保持 5 个平行单电子不变。","steps":["Mn 为 \\([\\mathrm{Ar}]3d^5 4s^2\\)，4s 上 2 个电子自旋成对，3d 上 5 个电子分占 5 个轨域，故有 **5 个**未成对电子。","失去 2 个 4s 电子变为 \\(\\mathrm{Mn^{2+}}([\\mathrm{Ar}]3d^5)\\)，依然保留 **5 个**未成对电子，未发生变化。"],"ans":"均有 5 个未成对电子，未发生变化。"}},{"id":"16.2","t":"过渡元素的通性","anchor":{"pages":"化上 p.409–413","syllabus":"3.5.2 过渡元素五大通性（金属特性、变价、有色、配合物、催化性）","examScopes":["sem2_final","uec"],"examWeight":"P1 有色水合离子与配离子识别 + P2 变色硅胶及 AgCl/Cu(OH)₂ 溶氨实验","terms":"variable oxidation states · coloured ions · complex ion · ligand · coordination compound · catalyst","prerequisites":["金属键与共价键基本特征（化上 Ch 7.1）","氨分子的孤对电子与配位键概念"],"goals":["熟练列举过渡元素的五大通性，并能从原子结构角度解释原因（d 电子参与成键、ns/(n−1)d 能量相近、d-d 电子跃迁、空轨域+孤对电子配位、d 带空穴吸附催化）。","熟记表16-1 第4周期氧化数及表16-2/16-3 常见水合离子（Cu²⁺、Fe²⁺、Fe³⁺、Mn²⁺、Zn²⁺）和化合物（CuSO₄/CuSO₄·5H₂O、CoCl₂/CoCl₂·6H₂O）的颜色。","掌握活动1–2 中 AgCl 和 CuSO₄ 溶于过量氨水形成配离子的现象与反应方程式。"]},"concepts":[{"kind":"law","title":"过渡元素五大通性及其结构根源","pageRef":"化上 p.409–413","body":["① **全为金属，且高密度、高熔沸点、高硬度**：原子半径比同周期主族金属小，采用最紧密堆积，且原子间除 s 电子外**还有部分 d 电子参与成键**（兼有金属键和部分共价键，结合极为牢固）。金属之最：熔点最高**钨（W）**、密度最大**锇（Os）**、硬度最大**铬（Cr）**。","② **具有多种氧化数（除 Sc +3、Zn +2 外）**：因 \\(ns\\) 与 \\((n-1)d\\) 能阶能量相差不大，两者电子均可参与成键（表16-1 如 Mn 有 +2, +3, +4, +6, +7；Cr 有 +2, +3, +6；Fe 有 +2, +3；Cu 有 +1, +2）。","③ **易生成有色离子和化合物**：未充满的 3d 电子在 d 轨域间跃迁吸收部分可见光而显色（此外与配对阴离子及结晶水有关，如 \\(\\mathrm{CuSO_4}\\) 白色 vs \\(\\mathrm{CuSO_4\\cdot 5H_2O}\\) 蓝色；蓝宝石含 FeO/TiO₂、红宝石含 Cr₂O₃，图16-2）。","④ **易形成配位化合物**：过渡金属离子（如 \\(\\mathrm{Fe^{3+}, Fe^{2+}, Cu^{2+}, Ag^+, Zn^{2+}}\\)）具有空 \\((n-1)d, ns, np\\) 轨域作电子对接受体，与有孤对电子的**配位体**（\\(\\mathrm{NH_3, H_2O, F^-, Cl^-, CN^-, SCN^-}\\)）通过配位键形成**配离子**（如 \\(\\mathrm{[Cu(NH_3)_4]^{2+}}\\)、\\(\\mathrm{[Ag(NH_3)_2]^+}\\)、\\(\\mathrm{[Fe(SCN)]^{2+}}\\)，图16-6/16-7）。","⑤ **单质及化合物常作优良催化剂**：d 带存在空穴，可与被吸附气体分子形成表面吸附中间体（合成氨铁触媒、制硝酸铂、接触法 \\(\\mathrm{V_2O_5}\\)、分解 \\(\\mathrm{H_2O_2/KClO_3}\\) 用 \\(\\mathrm{MnO_2}\\)）。"],"takeaway":"过渡元素五大通性背诵口诀：“全金属高熔硬、多价态、显色彩、易配位、作催化”。"},{"kind":"table","title":"表16-2 & 表16-3：常见过渡元素水合离子与典型化合物颜色速查","pageRef":"化上 p.411","body":["下表所有颜色均为统考无机推断题（框图题“突破口”）的直接线索，务必牢记！"],"table":{"headers":["水合离子 / 化合物","关键特征 / 价态","标准颜色"],"rows":[["\\(\\mathrm{Fe^{2+}(aq)}\\)","\\(3d^6\\)（绿矾 \\(\\mathrm{FeSO_4\\cdot 7H_2O}\\)）","**浅绿色**"],["\\(\\mathrm{Fe^{3+}(aq)}\\)","\\(3d^5\\)（\\(\\mathrm{FeCl_3}\\) 溶液）","**棕黄色**（极稀呈淡黄）"],["\\(\\mathrm{Cu^{2+}(aq)}\\) / \\(\\mathrm{CuSO_4\\cdot 5H_2O}\\)","\\(3d^9\\)（胆矾晶体）","**蓝色**"],["无水 \\(\\mathrm{CuSO_4}\\) / \\(\\mathrm{CuF_2}\\)","无结晶水或 F⁻ 配位","**白色**"],["\\(\\mathrm{Mn^{2+}(aq)}\\) / \\(\\mathrm{Co^{2+}(aq)}\\)","\\(3d^5\\) / \\(3d^7\\)","**粉红色**"],["\\(\\mathrm{Ni^{2+}(aq)}\\) / \\(\\mathrm{V^{3+}(aq)}\\)","\\(3d^8\\) / \\(3d^2\\)","**绿色**"],["\\(\\mathrm{Cr^{3+}(aq)}\\) / \\(\\mathrm{Zn^{2+}(aq)}\\)","\\(3d^3\\) / \\(3d^{10}\\)（全满）","**蓝紫色** / **无色**"],["无水 \\(\\mathrm{CoCl_2}\\) ⇄ \\(\\mathrm{CoCl_2\\cdot 6H_2O}\\)","硅胶干燥剂显色指示剂","**蓝色**（未吸水）⇄ **粉红色**（已吸水失效）"]]},"takeaway":"注意：硅胶干燥剂显色剂 CoCl₂ 在干燥无水时为蓝色，吸湿过多结合 6 分子水变为粉红色 CoCl₂·6H₂O（思考题 16a 第2题）！"},{"kind":"experiment","title":"活动1 与 活动2：配离子形成实验（银氨配离子与铜氨配离子）","pageRef":"化上 p.411–413","body":["**活动1（\\(\\mathrm{AgNO_3}\\) / \\(\\mathrm{AgCl}\\) 溶于浓氨水，思考题 16a 第1题）**：向 \\(3\\%\\ \\mathrm{AgNO_3}\\) 溶液中逐滴加浓氨水，先产生白色或棕褐色沉淀（\\(\\mathrm{AgOH/Ag_2O}\\)），继续加过量氨水沉淀迅速**溶解**生成无色澄清溶液（含直线形配离子 **\\(\\mathrm{[Ag(NH_3)_2]^+}\\)**）；同理白色 \\(\\mathrm{AgCl}\\) 沉淀也溶于氨水：\\(\\mathrm{AgCl(s) + 2NH_3\\cdot H_2O(aq) \\longrightarrow [Ag(NH_3)_2]^+(aq) + Cl^-(aq) + 2H_2O(l)}\\)。","**活动2（\\(\\mathrm{CuSO_4}\\) 溶液与氨水，图16-6/16-7）**：向 \\(5\\%\\ \\mathrm{CuSO_4}\\) 溶液中逐滴加氨水，先产生**蓝色絮状沉淀 \\(\\mathrm{Cu(OH)_2}\\)**，继续滴加过量氨水，沉淀溶解并最终变成**深蓝色澄清溶液**：\\(\\mathrm{Cu(OH)_2 + 4NH_3\\cdot H_2O \\longrightarrow [Cu(NH_3)_4]^{2+} + 2OH^- + 4H_2O}\\)。在平面正方形配离子 \\(\\mathrm{[Cu(NH_3)_4]^{2+}}\\) 中，\\(\\mathrm{Cu^{2+}}\\) 提供空轨域为中心阳离子，4 个 \\(\\mathrm{NH_3}\\) 分子的 N 原子各提供 1 对孤对电子形成配位键。"],"takeaway":"配合物 [Cu(NH₃)₄]SO₄ 溶于水仅在外界电离为 [Cu(NH₃)₄]²⁺ 和 SO₄²⁻，内界配位键不电离（因此加入 BaCl₂ 有白沉，而加少量 NaOH 却无 Cu(OH)₂ 沉淀！）。"}],"formulas":[{"title":"氯化银与氢氧化铜溶于过量氨水形成配离子的方程式","tex":"\\mathrm{AgCl(s) + 2NH_3\\cdot H_2O \\longrightarrow [Ag(NH_3)_2]^+ + Cl^- + 2H_2O},\\qquad \\mathrm{Cu^{2+} + 4NH_3\\cdot H_2O \\longrightarrow [Cu(NH_3)_4]^{2+} + 4H_2O}","plain":"AgCl + 2NH3·H2O -> [Ag(NH3)2]+ + Cl- + 2H2O; Cu2+ + 4NH3·H2O -> [Cu(NH3)4]2+ + 4H2O","conditions":"氨水需过量；沉淀“先生成后溶解”是 Cu²⁺ 配位反应标志现象","pageRef":"化上 p.412–413、p.432–433","note":"对比：向 [Cu(NH₃)₄]SO₄ 溶液中加入乙醇（极性较水弱），可降低其溶解度析出深蓝色 [Cu(NH₃)₄]SO₄·H₂O 晶体。"},{"title":"变色硅胶吸水变色及胆矾脱水反应","tex":"\\mathrm{CoCl_2(\\text{蓝色}) + 6H_2O(l) \\rightleftharpoons CoCl_2\\cdot 6H_2O(\\text{粉红色})},\\qquad \\mathrm{CuSO_4(\\text{白色}) + 5H_2O(l) \\rightleftharpoons CuSO_4\\cdot 5H_2O(\\text{蓝色})}","plain":"CoCl2(蓝) + 6H2O ⇌ CoCl2·6H2O(粉红); CuSO4(白) + 5H2O ⇌ CuSO4·5H2O(蓝)","conditions":"粉红色失效硅胶可经加热烘干脱水恢复蓝色再生重复使用","pageRef":"化上 p.411、p.413","note":"两种水合反应均为可逆化学变化（配位水合引发 d 轨域分裂能改变，故颜色巨变）。"}],"pitfalls":[{"title":"误把配合物内界的配体当成游离离子","wrong":"“\\(\\mathrm{[Cu(NH_3)_4]SO_4}\\) 溶于水能电离出 \\(\\mathrm{Cu^{2+}}\\)、\\(\\mathrm{NH_3}\\) 和 \\(\\mathrm{SO_4^{2-}}\\)，所以滴入 \\(\\mathrm{BaCl_2}\\) 和 \\(\\mathrm{NaOH}\\) 均立刻生成沉淀。”","diagnosis":"配合物内界（方括号内）中心离子与配位体通过稳定的配位键结合，水溶液中几乎不发生离解。","right":"\\(\\mathrm{[Cu(NH_3)_4]SO_4(aq) \\longrightarrow [Cu(NH_3)_4]^{2+}(aq) + SO_4^{2-}(aq)}\\)，仅电离出配离子与外界 \\(\\mathrm{SO_4^{2-}}\\)（只与 \\(\\mathrm{BaCl_2}\\) 生成 \\(\\mathrm{BaSO_4\\downarrow}\\)，难以与 \\(\\mathrm{NaOH}\\) 产生 \\(\\mathrm{Cu(OH)_2}\\) 沉淀）。","checkRule":"遇到 `[M(L)n]X` 式配合物，电离时**方括号内视为不可分割的整体**！"},{"title":"把所有金属的高熔点只归功于金属键而忽略过渡金属 d 电子","wrong":"“钙与铁同在第 4 周期且最外层都只有 2 个 4s 电子，因此两者熔点和硬度应该差不多。”","diagnosis":"主族金属 Ca 只有 2 个 4s 价电子成键；铁是过渡元素，内层未充满的 3d 电子大量参与金属键（共价作用）且原子半径更小。","right":"过渡金属单质熔点与硬度远高于同周期主族金属（如 W 熔点 3422℃，Cr 硬度极高），源于**半径小密堆积及 d 电子参与成键**。","checkRule":"问过渡金属高硬度高熔点结构原因：必答“原子半径小 + 除 s 电子外还有部分 d 电子参与成键（部分共价键）”。"}],"examples":[{"label":"例 16.2.1","tier":"L2","tierLabel":"L2 校内期末","title":"配合物反应与变色硅胶指示剂原理（思考题 16a 第1、2题）","prompt":"(1) 写出下列反应的化学方程式（或离子方程式）：① 氯化银沉淀溶于过量氨水；② 在硫酸铜(II)溶液中逐滴加入过量浓氨水（分别写出沉淀生成与溶解两步总过程或分步式）；(2) 硅酸凝胶（简称硅胶）是一种常用干燥剂，常加入一定量显色剂 \\(\\mathrm{CoCl_2}\\) 指示吸湿程度。未吸水时呈蓝色，吸水过多失去吸水能力后呈粉红色，请用化学知识解释变色原因并说明如何使失效硅胶再生。","clues":"利用思考题 16a 第1、2题及表16-3 CoCl₂ vs CoCl₂·6H₂O 颜色对比！","strategy":"严格写准配离子 [Ag(NH₃)₂]⁺ 与 [Cu(NH₃)₄]²⁺ 电荷与配位数；结合配位水合变色与可逆脱水解答硅胶再生。","given":"思考题 16a；表16-3 CoCl₂(蓝) 与 CoCl₂·6H₂O(粉红)","principle":"配合物形成反应及配位水合导致金属离子颜色变化。","steps":["(1) ① \\(\\mathrm{AgCl(s) + 2NH_3\\cdot H_2O(aq) \\longrightarrow [Ag(NH_3)_2]^+(aq) + Cl^-(aq) + 2H_2O(l)}\\)（化学方程式可写生成 \\(\\mathrm{[Ag(NH_3)_2]Cl}\\)）。","② 先生成蓝色沉淀：\\(\\mathrm{CuSO_4(aq) + 2NH_3\\cdot H_2O(aq) \\longrightarrow Cu(OH)_2(s)\\downarrow + (NH_4)_2SO_4(aq)}\\)；后过量氨水使沉淀溶解成深蓝色溶液：\\(\\mathrm{Cu(OH)_2(s) + (NH_4)_2SO_4(aq) + 2NH_3\\cdot H_2O(aq) \\longrightarrow [Cu(NH_3)_4]SO_4(aq) + 4H_2O(l)}\\)（或合写 \\(\\mathrm{CuSO_4 + 4NH_3\\cdot H_2O \\to [Cu(NH_3)_4]SO_4 + 4H_2O}\\)）。","(2) 未吸水时硅胶中 \\(\\mathrm{CoCl_2}\\) 为无水状态，呈**蓝色**；吸收水分后结合成六水合二氯化钴 \\(\\mathrm{CoCl_2\\cdot 6H_2O}\\)，呈**粉红色**（表明已吸湿饱和）。再生方法：将粉红色硅胶放入烘箱**加热烘干**脱水，即可恢复蓝色重新使用。"],"answer":"(1) 见步骤；(2) 无水 CoCl₂ 蓝 → 吸水形成 CoCl₂·6H₂O 粉红；加热烘干脱水即可再生。","markingPoints":["两个溶于氨水方程式及配离子写法完全准确（2.5分）","解释 CoCl₂→CoCl₂·6H₂O 变色及加热再生（2分）"],"verification":"对照化上 p.411 表16-3 与 p.413 思考题 16a。","pitfall":"第(1)① 题易把配位数写错成 4，记住 Ag⁺ 配位数是 **2**（\\(\\mathrm{[Ag(NH_3)_2]^+}\\)），Cu²⁺ 是 **4**（\\(\\mathrm{[Cu(NH_3)_4]^{2+}}\\)）。"},{"label":"例 16.2.2","tier":"L3","tierLabel":"L3 预试拔高","title":"配合物内界与外界离子的电离及 AgCl 定量鉴定","prompt":"某钴(III)配合物的化学式可表示为 \\(\\mathrm{[Co(NH_3)_5Cl]Cl_2}\\)（其中 Co 为 +3 价，配位数为 6）。取 \\(0.100\\text{ mol}\\) 该配合物溶于水，加入足量用稀硝酸酸化的 \\(\\mathrm{AgNO_3}\\) 溶液充分反应。(1) 写出该配合物在水溶液中的电离方程式；(2) 指出该配合物中的中心离子、配位体及配位数；(3) 实验测得共生成多少摩尔白色 \\(\\mathrm{AgCl}\\) 沉淀？（提示：只有外界自由电离的 \\(\\mathrm{Cl^-}\\) 才能与 \\(\\mathrm{Ag^+}\\) 瞬间反应沉淀）","clues":"方括号内 [Co(NH₃)₅Cl]²⁺ 不电离出 Cl⁻！只有方括号外面的 2 个 Cl⁻ 才能电离与 Ag⁺ 沉淀！","strategy":"区分配合物“内界（共价/配位结合）”和“外界（离子键结合）”，据此计算外界 Cl⁻ 的物质的量。","given":"0.100 mol [Co(NH₃)₅Cl]Cl₂ + 足量 AgNO₃(H⁺)","principle":"配合物内界不电离、外界完全电离。","steps":["(1) 电离方程式：\\(\\mathrm{[Co(NH_3)_5Cl]Cl_2(aq) \\longrightarrow [Co(NH_3)_5Cl]^{2+}(aq) + 2Cl^-(aq)}\\)。","(2) 中心离子为 **\\(\\mathrm{Co^{3+}}\\)**，配位体为 **\\(\\mathrm{NH_3}\\) 分子和 \\(\\mathrm{Cl^-}\\) 离子**（共 5 个 NH₃ 与 1 个 Cl⁻），配位数为 **6**。","(3) \\(0.100\\text{ mol}\\) 配合物溶于水仅电离出外界自由 \\(\\mathrm{Cl^-}\\) 为 \\(2 \\times 0.100 = 0.200\\text{ mol}\\)（内界 \\(\\mathrm{Cl^-}\\) 与 Co³⁺ 以配位键牢固结合不能电离），故与足量 \\(\\mathrm{AgNO_3}\\) 反应只生成 **\\(0.200\\text{ mol}\\)** \\(\\mathrm{AgCl}\\) 沉淀。"],"answer":"(1) \\(\\mathrm{[Co(NH_3)_5Cl]Cl_2 \\to [Co(NH_3)_5Cl]^{2+} + 2Cl^-}\\)；(2) 中心离子 \\(\\mathrm{Co^{3+}}\\)，配体 \\(\\mathrm{NH_3, Cl^-}\\)，配位数 6；(3) \\(0.200\\text{ mol}\\) \\(\\mathrm{AgCl}\\)。","markingPoints":["准确写出外界电离方程式（1.5分）","识别两种配位体与配位数 6（1.5分）","区分内外界 Cl⁻ 得出 0.200 mol AgCl（1.5分）"],"verification":"此题是 UEC 统考与高三预试最经典配合物计算模型，若不理解内外界必错选 0.300 mol。","pitfall":"把化学式里全部 3 个 Cl 都当成游离氯离子得出 0.300 mol。"}],"practice":[{"id":"chem16-16.2-q1","tier":"L1","tierLabel":"L1 基础","examStyle":"P1 选择","q":"下列有关过渡元素水合离子或常见化合物颜色的描述中，**错误**的是（　）。","options":["A. 含有 \\(\\mathrm{Fe^{2+}}\\) 的水溶液通常呈浅绿色","B. 含有 \\(\\mathrm{Fe^{3+}}\\) 的水溶液通常呈棕黄色","C. 含有 \\(\\mathrm{Zn^{2+}}\\) 的水溶液通常呈蓝色","D. 无水 \\(\\mathrm{CuSO_4}\\) 粉末是白色的，\\(\\mathrm{CuSO_4\\cdot 5H_2O}\\) 晶体是蓝色的"],"correctOption":"C","given":"表16-2 与表16-3（化上 p.411）","method":"对比 Zn²⁺(3d¹⁰ 全满) 与 Cu²⁺(3d⁹) 颜色","principle":"Zn²⁺ 的 3d 轨域全充满无 d-d 跃迁，水溶液呈无色。","steps":["C 错：\\(\\mathrm{Zn^{2+}}\\) 水溶液为**无色**（呈蓝色的是 \\(\\mathrm{Cu^{2+}}\\)）。"],"ans":"C","markingPoints":["记住 Zn²⁺ 无色、Fe²⁺ 浅绿、Fe³⁺ 棕黄、Cu²⁺ 蓝色"],"verification":"对照化上 p.411 表16-2 与表16-3。","pitfall":"误以为所有过渡族离子都带颜色。"},{"id":"chem16-16.2-q2","tier":"L2","tierLabel":"L2 期末","examStyle":"P1 选择","q":"过渡金属及其化合物常在化工生产中用作高效催化剂（如合成氨用铁触媒、接触法制硫酸用 \\(\\mathrm{V_2O_5}\\)、氨氧化用铂—铑合金）。其微观结构上的最主要原因在于过渡元素（　）。","options":["A. 原子半径非常大，容易失去所有外层电子","B. 次外层 \\(d\\) 轨域未填满存在空穴，能与被吸附气体分子形成表面吸附化学键与中间物种","C. 全都是熔点低于 100℃ 的活泼金属","D. 在反应中绝对不发生任何吸附或中间化学作用"],"correctOption":"B","given":"化上 p.413 过渡元素催化性能原文","method":"直接对应 p.413 催化机理解释","principle":"d 带空穴形成表面吸附中间体降低反应活化能。","steps":["教材 p.413 指出：过渡元素次外层 d 电子层未填满，具有 d 带空穴，能与被吸附气体分子形成吸附化学键，生成表面中间物种从而显现催化性能。"],"ans":"B","markingPoints":["理解 d 带空穴与表面中间物种催化原理"],"verification":"对照化上 p.413 原文。","pitfall":"误把过渡金属熔沸点说低。"},{"id":"chem16-16.2-q3","tier":"L3","tierLabel":"L3 预试","examStyle":"P2 简答","q":"在深蓝色的 \\(\\mathrm{[Cu(NH_3)_4]SO_4}\\) 水溶液中含有配离子 \\(\\mathrm{[Cu(NH_3)_4]^{2+}}\\)（如图16-7 所示）。(1) 指出该配离子的中心阳离子、配位体及配位键数目；(2) 从原子轨域和孤对电子角度分析过渡金属离子为什么普遍容易形成配位化合物？(3) 另举出两种教材中出现过的过渡金属配离子。","given":"化上 p.412–413 图16-6/16-7 配位化合物讲解","method":"依据空 (n−1)d/ns/np 轨域接收孤对电子机理回答","principle":"路易斯酸（金属空轨域）与路易斯碱（配体孤对电子）形成配位键。","steps":["(1) 中心阳离子：**\\(\\mathrm{Cu^{2+}}\\)**；配位体：**\\(\\mathrm{NH_3}\\)** 分子；配位键数目：**4**。","(2) 过渡金属离子具有 **\\((n-1)d\\)、\\(ns\\)、\\(np\\)** 共 9 个价电子轨域，其中 \\(ns\\)、\\(np\\) 轨域全空且 \\((n-1)d\\) 部分或全空，这种电子构型非常利于**接受配位体（如 \\(\\mathrm{NH_3, CN^-, SCN^-, H_2O}\\)）提供的孤对电子**，从而形成稳定的配位键。","(3) 教材实例：**\\(\\mathrm{[Ag(NH_3)_2]^+}\\)**（银氨配离子）与 **\\(\\mathrm{[Fe(SCN)]^{2+}}\\)**（硫氰合铁(III)配离子，血红色）。"],"ans":"(1) Cu²⁺、NH₃、4个；(2) 具有空的 (n−1)d/ns/np 价轨域可接受配体孤对电子；(3) [Ag(NH₃)₂]⁺、[Fe(SCN)]²⁺。","markingPoints":["指出中心离子、配体及 4 个配位键（1.5分）","说明空价轨域接收孤对电子成键机理（2分）","列举教材其他两种配离子（1分）"],"verification":"对照化上 p.412 原文核对一字不差。","pitfall":"注意不要把离子电荷数 +2 当作配位数。"},{"id":"chem16-16.2-q4","tier":"L4","tierLabel":"L4 统考压轴","examStyle":"P2 实验设计","q":"现有三瓶失去标签的同浓度无色或浅色溶液：\\(\\mathrm{ZnSO_4}\\)、\\(\\mathrm{CuSO_4}\\) 和 \\(\\mathrm{CoCl_2}\\)，以及三瓶试剂：\\(\\mathrm{BaCl_2}\\) 溶液、浓氨水、\\(\\mathrm{NaOH}\\) 溶液。(1) 不加任何试剂即可先区分出的溶液是哪一瓶？简述各溶液（浓度适中）的视觉特征；(2) 若将 \\(\\mathrm{ZnSO_4}\\) 溶液和 \\(\\mathrm{MgCl_2}\\) 溶液对比鉴别（均为无色溶液），向两溶液中分别逐滴加入过量氨水至不再变化，推测两试管中可能出现的不同现象（提示：\\(\\mathrm{Zn^{2+}}\\) 像 \\(\\mathrm{Cu^{2+}}\\) 一样易形成 \\(\\mathrm{[Zn(NH_3)_4]^{2+}}\\) 配离子，而主族 \\(\\mathrm{Mg^{2+}}\\) 不能与氨形成配离子）。","given":"表16-2 颜色与 p.413 过渡离子易配位通性","method":"利用 Cu²⁺ 蓝、Co²⁺ 粉红、Zn²⁺ 无色直接目视分辨；用过量氨水溶 Zn(OH)₂ 不溶 Mg(OH)₂ 区分过渡与主族！","principle":"过渡金属离子显著特点：显色且易形成氨配合物溶解沉淀。","steps":["(1) 不加试剂目视即可全部区分：**\\(\\mathrm{CuSO_4}\\) 呈蓝色**，**\\(\\mathrm{CoCl_2}\\) 水溶液呈粉红色**，**\\(\\mathrm{ZnSO_4}\\) 呈无色**。","(2) 分别逐滴加入氨水直至过量：","① 装有 \\(\\mathrm{MgCl_2}\\) 的试管中生成**白色 \\(\\mathrm{Mg(OH)_2}\\) 沉淀，继续滴加过量氨水沉淀不溶解**（主族离子无空 d 轨域易配位倾向）；","② 装有 \\(\\mathrm{ZnSO_4}\\) 的试管中先生成**白色 \\(\\mathrm{Zn(OH)_2}\\) 沉淀，继续滴加过量氨水沉淀逐渐溶解**形成无色澄清的 \\(\\mathrm{[Zn(NH_3)_4]^{2+}}\\) 配离子溶液（\\(\\mathrm{Zn(OH)_2 + 4NH_3\\cdot H_2O \\to [Zn(NH_3)_4]^{2+} + 2OH^- + 4H_2O}\\)）。"],"ans":"(1) 蓝=CuSO₄、粉红=CoCl₂、无色=ZnSO₄；(2) MgCl₂ 白沉不溶；ZnSO₄ 先白沉后过量氨水溶解。","markingPoints":["准确说出三种溶液表16-2 对应颜色（1.5分）","结合过渡金属易配位通性正确预测 Zn(OH)₂ 溶而 Mg(OH)₂ 不溶（2.5分）"],"verification":"教材 p.413 明确列举了 \\(\\mathrm{Fe^{3+}, Fe^{2+}, Cu^{2+}, Ag^+, Zn^{2+}}\\) 都具有空轨域易形成配合物！","pitfall":"平时只记 Cu²⁺ 与 Ag⁺ 溶于氨水，忽略了同为 IIB 族具有配位能力的 Zn²⁺（且要注意 Fe(OH)₃、Mg(OH)₂、Al(OH)₃ 均不溶于过量氨水）。"}],"cheatSheet":["五大通性：全金属高熔硬（d电子参与，最熔W、最密Os、最硬Cr）；多价态（Mn+2~+7）；有色离子；易配位；作催化（d带空穴）。","颜色速记：Cu²⁺ 蓝、Fe²⁺ 浅绿、Fe³⁺ 棕黄、Mn²⁺/Co²⁺ 粉红、Zn²⁺ 无色；CoCl₂(蓝) ⇄ CoCl₂·6H₂O(粉红)。","配合物口诀：方括号内不电离！AgCl 溶氨得 [Ag(NH₃)₂]⁺，Cu(OH)₂ 溶过量氨得深蓝 [Cu(NH₃)₄]²⁺。"],"kbEntryIds":["kb-chem16-general"],"quiz":{"q":"某同学在实验室向硫酸铜溶液中滴入几滴浓氨水产生蓝色沉淀，接着继续加入过量浓氨水发现沉淀消失。写出导致沉淀消失的离子方程式，并说出最终溶液的颜色。","given":"活动2（化上 p.411–412）","method":"将 Cu(OH)₂ 蓝色沉淀与过量 NH₃·H₂O 转化为四氨合铜(II)配离子","principle":"过渡金属离子形成稳定配合物的驱动力。","steps":["\\(\\mathrm{Cu(OH)_2(s) + 4NH_3\\cdot H_2O(aq) \\longrightarrow [Cu(NH_3)_4]^{2+}(aq) + 2OH^-(aq) + 4H_2O(l)}\\)。","最终溶液变为**深蓝色**。"],"ans":"\\(\\mathrm{Cu(OH)_2 + 4NH_3\\cdot H_2O \\to [Cu(NH_3)_4]^{2+} + 2OH^- + 4H_2O}\\)；最终为深蓝色溶液。"}},{"id":"16.3","t":"铁","anchor":{"pages":"化上 p.413–427","syllabus":"3.5.3 铁的性质、化合物、Fe²⁺/Fe³⁺ 检验、电化学腐蚀及高炉炼铁与炼钢","examScopes":["sem2_final","uec"],"examWeight":"全册最重要金属节（铁三角、四法检验、Fe+H₂O(g)、蚀刻PCB、炼铁炼钢必考）","terms":"iron triangle · potassium thiocyanate · blast furnace · slag · basic oxygen furnace · pig iron","prerequisites":["原电池原理与铁的氧化还原性（化上 Ch 8 & Ch 16.1）","弱氧化剂与强氧化剂对变价金属氧化数的影响"],"goals":["掌握铁的物理性质及化学性质：与非金属（O₂、Cl₂、S）、酸、盐溶液反应，以及活动3 高温铁粉与水蒸气反应生成 Fe₃O₄ 和 H₂（图16-9）。","理解铁的氧化物（FeO、Fe₂O₃、Fe₃O₄）、氢氧化物（活动4 Fe(OH)₂ 变色过程）与 Fe²⁺/Fe³⁺ 铁三角互相转化（活动5 与 PCB 蚀刻 活动6）。","熟记表16-8 鉴别 Fe²⁺ 与 Fe³⁺ 的四种方法，并掌握高炉炼铁（图16-19）及氧气顶吹转炉炼钢（图16-20）的核心反应与生铁/钢区别。"]},"concepts":[{"kind":"experiment","title":"活动3–6：铁的化学性质（水蒸气、Fe(OH)₂ 氧化、铁三角与 PCB 蚀刻）","pageRef":"化上 p.414–421","body":["**与强/弱氧化剂分层**：铁作还原剂时，遇弱氧化剂（稀盐酸、稀硫酸、\\(\\mathrm{CuSO_4}\\) 溶液、S 粉）只生成 **+2 价 \\(\\mathrm{Fe^{2+}}\\)**；遇强氧化剂（\\(\\mathrm{Cl_2}\\)、热浓硫酸、浓/稀硝酸）直接生成 **+3 价 \\(\\mathrm{Fe^{3+}}\\)**。","**活动3（铁与水蒸气反应，图16-9）**：先加热湿棉花产生水蒸气，再移至铁粉位置高温加热，导出气体通入肥皂水起泡，点燃产生爆鸣声：\\(\\mathrm{3Fe(s) + 4H_2O(g)} \\xrightarrow{\\text{高温}} \\mathrm{Fe_3O_4(s) + 4H_2(g)}\\)（注意产物是黑色磁性 \\(\\mathrm{Fe_3O_4}\\)，不是 FeO 或 Fe₂O₃！）。","**活动4（Fe(OH)₂ 变色，图16-14）**：向 \\(\\mathrm{FeSO_4}\\) 溶液滴加 \\(\\mathrm{NaOH}\\)，生成**白色絮状沉淀 \\(\\mathrm{Fe(OH)_2}\\)，迅速变为灰绿色，最后变为红褐色 \\(\\mathrm{Fe(OH)_3}\\)**：\\(\\mathrm{4Fe(OH)_2(s) + O_2(g) + 2H_2O(l) \\longrightarrow 4Fe(OH)_3(s)}\\)（若在实验室制备纯净白色 Fe(OH)₂，须将 NaOH 煮沸除氧并在液面滴加苯/植物油隔绝空气，用长滴管插至液面下挤出）。","**活动5 & 活动6（铁三角与蚀刻电路板）**：配制 \\(\\mathrm{FeSO_4}\\) 溶液常加少量**铁粉**防止氧化（\\(\\mathrm{Fe + 2Fe^{3+} \\to 3Fe^{2+}}\\)）；\\(\\mathrm{Fe^{2+}}\\) 加氯水或 \\(\\mathrm{H_2O_2}\\) 氧化成 \\(\\mathrm{Fe^{3+}}\\)；**活动6（图16-17）** 用 \\(30\\%\\ \\mathrm{FeCl_3}\\) 溶液蚀刻铜片制作印刷电路板：\\(\\mathrm{2Fe^{3+}(aq) + Cu(s) \\longrightarrow 2Fe^{2+}(aq) + Cu^{2+}(aq)}\\)。"],"takeaway":"由蚀刻反应 2Fe³⁺ + Cu → 2Fe²⁺ + Cu²⁺ 可知氧化性：Fe³⁺ > Cu²⁺，还原性：Fe > Cu > Fe²⁺！"},{"kind":"table","title":"表16-8：Fe²⁺ 与 Fe³⁺ 的四种经典鉴别方法全对照","pageRef":"化上 p.421–422","body":["除了直接观察水溶液颜色（\\(\\mathrm{Fe^{2+}}\\) 浅绿、\\(\\mathrm{Fe^{3+}}\\) 棕黄）外，实验室常用以下四种特异性试剂进行严格检验："],"table":{"headers":["鉴别试剂","与 \\(\\mathrm{Fe^{2+}}\\) 溶液现象与反应","与 \\(\\mathrm{Fe^{3+}}\\) 溶液现象与反应"],"rows":[["① **硫氰化钾（KSCN）**","无明显颜色变化（再滴新制氯水后变血红）","立刻呈**血红色**：\\(\\mathrm{Fe^{3+} + SCN^- \\to [Fe(SCN)]^{2+}}\\)"],["② **碱溶液（NaOH）**","先生成**白色絮状沉淀**，迅速变**灰绿**，最终变**红褐色**","直接生成**红褐色絮状沉淀** \\(\\mathrm{Fe(OH)_3}\\)"],["③ **氰化铁配合物**","遇深红色**铁(III)氰化钾** \\(\\mathrm{K_3[Fe(CN)_6]}\\) 生**深蓝色**沉淀","遇黄色**铁(II)氰化钾** \\(\\mathrm{K_4[Fe(CN)_6]}\\) 生**深蓝色**沉淀"],["④ **硫化氢气体（\\(\\mathrm{H_2S}\\)）**","产生**黑色**沉淀：\\(\\mathrm{Fe^{2+} + H_2S \\to FeS\\downarrow + 2H^+}\\)","产生**黄色**硫沉淀：\\(\\mathrm{2Fe^{3+} + H_2S \\to 2Fe^{2+} + S\\downarrow + 2H^+}\\)"]]},"takeaway":"记忆技巧：“黄血盐 K₄[Fe(CN)₆] 专检 Fe³⁺，赤血盐 K₃[Fe(CN)₆] 专检 Fe²⁺”，两者都是“错位配对”出深蓝沉淀！"},{"kind":"mechanism","title":"铁的电化学腐蚀防护与高炉炼铁、转炉炼钢工艺","pageRef":"化上 p.416–417、p.423–427","body":["**钢铁腐蚀与防护（图16-10/16-12）**：不纯铁在潮湿空气中形成无数微小原电池发生**电化学腐蚀**（Fe 作负极失电子成 \\(\\mathrm{Fe^{2+}}\\)，最终生锈成 \\(\\mathrm{Fe_2O_3\\cdot xH_2O}\\)）。防护法：覆盖保护层（涂油漆、镀锌/锡/铬、烤蓝致密 \\(\\mathrm{Fe_3O_4}\\)）、制不锈钢（加 Cr、Ni）及**牺牲阳极的阴极保护法**（钢闸门连接活泼金属锌板作牺牲阳极）。","**高炉炼铁（图16-19）**：原料为铁矿石（赤铁矿 \\(\\mathrm{Fe_2O_3}\\)、磁铁矿 \\(\\mathrm{Fe_3O_4}\\)）、焦炭、空气和**石灰石（助熔剂）**。炉内反应：① 产生还原剂：\\(\\mathrm{C + O_2 \\to CO_2}\\)、\\(\\mathrm{C + CO_2 \\to 2CO}\\)；② 还原铁矿石：\\(\\mathrm{3CO + Fe_2O_3} \\xrightarrow{\\Delta} \\mathrm{2Fe(l) + 3CO_2}\\)；③ **造渣除脉石 \\(\\mathrm{SiO_2}\\)**：\\(\\mathrm{CaCO_3} \\xrightarrow{\\text{高温}} \\mathrm{CaO + CO_2\\uparrow}\\)、\\(\\mathrm{CaO + SiO_2} \\xrightarrow{\\text{高温}} \\mathrm{CaSiO_3(l)}\\)（炉渣浮在铁水上层）。","**生铁 vs 钢（氧气顶吹转炉炼钢，图16-20）**：高炉产品是含碳 **2%~4.5%** 的生铁（硬脆）。炼钢实质是**降低含碳量（至 0.02%~2%，表16-9 低碳/中碳/高碳钢）**并除去硫、磷等杂质：向熔融铁水吹入纯氧（>99%）氧化生成 \\(\\mathrm{FeO}\\)，再由 \\(\\mathrm{FeO}\\) 氧化 Si、Mn、C 除去（出钢前加硅铁、锰铁或铝脱氧：\\(\\mathrm{2FeO + Si \\to 2Fe + SiO_2}\\)）。"],"takeaway":"高炉炼铁中真正的“主力还原剂”是 CO（气固接触面积大），而不是固体焦炭 C 直接还原。"}],"diagrams":[{"src":"assets/fig/v2/chem16-fe-triangle.svg","caption":"图 16-1 “铁三角” Fe—Fe²⁺—Fe³⁺ 氧化还原转化路径及四种鉴别方法全图","alt":"铁三角氧化还原与离子检验图","pageRef":"化上 p.414–422"}],"formulas":[{"title":"铁与水蒸气高温反应及印刷电路板蚀刻离子式","tex":"\\mathrm{3Fe(s) + 4H_2O(g)} \\xrightarrow{\\text{高温}} \\mathrm{Fe_3O_4(s) + 4H_2(g)},\\qquad \\mathrm{2Fe^{3+}(aq) + Cu(s) \\longrightarrow 2Fe^{2+}(aq) + Cu^{2+}(aq)}","plain":"3Fe + 4H2O(g) --高温--> Fe3O4 + 4H2; 2Fe3+ + Cu -> 2Fe2+ + Cu2+","conditions":"铁与水蒸气反应中氧化剂为 H₂O（4 mol H₂O 得 8 mol e⁻ 生成 4 mol H₂）","pageRef":"化上 p.415–416、p.421","note":"注意 Fe₃O₄ 中铁的平均氧化数为 +8/3（由 1 个 +2 价 Fe 和 2 个 +3 价 Fe 组成，即 FeO·Fe₂O₃）。"},{"title":"高炉炼铁核心还原反应与造渣除杂方程式","tex":"\\mathrm{3CO(g) + Fe_2O_3(s)} \\xrightarrow{\\Delta} \\mathrm{2Fe(l) + 3CO_2(g)},\\qquad \\mathrm{CaCO_3(s)} \\xrightarrow{\\text{高温}} \\mathrm{CaO(s) + CO_2(g)},\\qquad \\mathrm{CaO(s) + SiO_2(s)} \\xrightarrow{\\text{高温}} \\mathrm{CaSiO_3(l)}","plain":"3CO + Fe2O3 --Δ--> 2Fe + 3CO2; CaCO3 -> CaO + CO2; CaO + SiO2 -> CaSiO3","conditions":"高炉温度梯度 250℃~1500℃；CaSiO₃ 密度小浮于熔融铁水上层","pageRef":"化上 p.423–425","note":"对比转炉炼钢脱氧反应：2FeO(s) + Si(s) —高温→ 2Fe(l) + SiO₂(s)。"}],"pitfalls":[{"title":"误判 Fe₃O₄ 能否由铁与水蒸气或氧气直接生成及 Fe³⁺/Fe/Cu 混合共存（思考题 16b & 16c）","wrong":"“向 \\(\\mathrm{FeCl_3}\\) 溶液中同时加入铁粉和铜粉，反应结束后容器内可能出现‘有铁无铜’或‘有 \\(\\mathrm{FeCl_3}\\) 又有单质铜’。”","diagnosis":"还原性 **\\(\\mathrm{Fe > Cu}\\)**，所以 Fe 会先于 Cu 与 \\(\\mathrm{Fe^{3+}}\\) 反应（而且就算 Cu 先溶解成 \\(\\mathrm{Cu^{2+}}\\)，过量 Fe 也会把 \\(\\mathrm{Cu^{2+}}\\) 置换回单质 Cu）；同时只要有 \\(\\mathrm{Fe^{3+}}\\) 剩余，单质 Cu 和 Fe 早就完全溶光。","right":"Fe 与 Cu 投入 \\(\\mathrm{FeCl_3}\\) 溶液，可能的结果只有三种：**有铜无铁**、**铁铜皆有**、**铁铜皆无**；绝对不可能出现**“有铁无铜”**（思考题 16b 第2题），且若 \\(\\mathrm{FeCl_3}\\) 仍有剩余，容器中绝对**不可能有 Fe 和 Cu 单质**（思考题 16c 第3题）。","checkRule":"铁铜竞争体系铁律：Fe 先溶后 Cu 溶；先析出 Cu 再看 Fe 剩不剩——绝不存在“有铁无铜”！"},{"title":"铁在氯气或盐酸中反应产物价态记混","wrong":"“铁丝在氯气中燃烧生成氯化铁(II)（\\(\\mathrm{FeCl_2}\\)）；铁与稀盐酸反应生成氯化铁(III)（\\(\\mathrm{FeCl_3}\\)）。”","diagnosis":"完全记反了氧化剂强弱！\\(\\mathrm{Cl_2}\\) 氧化性极强把 Fe 一步氧化到 +3 价，而稀盐酸中 \\(\\mathrm{H^+}\\) 氧化性较弱只能氧化到 +2 价。","right":"**\\(\\mathrm{2Fe + 3Cl_2} \\xrightarrow{\\text{高温}} \\mathrm{2FeCl_3}\\)**（+3价）；**\\(\\mathrm{Fe + 2HCl \\longrightarrow FeCl_2 + H_2\\uparrow}\\)**（+2价）。","checkRule":"记住：想要用非金属单质直接化合得 \\(\\mathrm{FeCl_2}\\) 是不可能的（教材思考题 16b 第1题 C）。"}],"examples":[{"label":"例 16.3.1","tier":"L3","tierLabel":"L3 预试拔高","title":"Fe、Cu、FeCl₃、FeCl₂、CuCl₂ 混合体系反应后成分推理（思考题 16c 第3题）","prompt":"将铁粉、铜粉、\\(\\mathrm{FeCl_3}\\) 溶液、\\(\\mathrm{FeCl_2}\\) 溶液和 \\(\\mathrm{CuCl_2}\\) 溶液混合于某密闭容器中充分反应（假定容器不参与反应），试判断下列四种情况下容器中一定存在或不可能存在的金属离子和金属单质：(1) 若**铁粉有剩余**，则容器中不可能有哪些金属离子？(2) 若**\\(\\mathrm{CuCl_2}\\) 有剩余**，则容器中还可能有哪些固体或离子（说明 \\(\\mathrm{Fe^{3+}}\\) 与单质状态）？(3) 若**\\(\\mathrm{FeCl_3}\\) 和 \\(\\mathrm{CuCl_2}\\) 都有剩余**，则容器中不可能有哪些金属单质，一定有哪些离子？(4) 若**\\(\\mathrm{FeCl_3}\\) 有剩余**，则容器中不可能有哪些金属单质？","clues":"排好反应顺序：还原性 Fe > Cu；氧化性 Fe³⁺ > Cu²⁺。最先反应的一定是“最强还原剂 Fe + 最强氧化剂 Fe³⁺”，其次看剩余！","strategy":"依据氧化性 Fe³⁺ > Cu²⁺ > Fe²⁺ 依次判断每一种物质剩余时，所有能与之反应的对手必已耗尽！","given":"混合体系：Fe, Cu, Fe³⁺, Fe²⁺, Cu²⁺","principle":"氧化还原反应先后顺序律（强强优先）及物质不可共存推论。","steps":["(1) 若铁粉（最强还原剂）有剩余，则所有氧化性比 \\(\\mathrm{Fe^{2+}}\\) 强的离子均已被彻底还原，故容器中**不可能有 \\(\\mathrm{Fe^{3+}}\\) 和 \\(\\mathrm{Cu^{2+}}\\)**（只含 \\(\\mathrm{Fe^{2+}}\\) 离子与 Fe、Cu 单质）。","(2) 若 \\(\\mathrm{CuCl_2}\\) 有剩余（未反应完），说明最强的还原剂铁粉已耗尽（否则 Fe 会置换 \\(\\mathrm{Cu^{2+}}\\)），但可能剩余 \\(\\mathrm{Cu}\\) 粉；因 \\(\\mathrm{Cu^{2+}}\\) 与 \\(\\mathrm{Fe^{2+}}\\) 共存且可能还有 \\(\\mathrm{Fe^{3+}}\\)（若连 Cu 粉也耗尽），故容器中一定有 \\(\\mathrm{Fe^{2+}}\\)，还可能有 **\\(\\mathrm{Fe^{3+}}\\) 或单质 \\(\\mathrm{Cu}\\)**（两者不可同时存在，但绝对不可能有单质 Fe）。","(3) 若 \\(\\mathrm{FeCl_3}\\) 和 \\(\\mathrm{CuCl_2}\\) 都有剩余，由于 \\(\\mathrm{Fe^{3+}}\\) 能溶解 Fe 和 Cu，故容器中**不可能有 Fe 粉和 Cu 粉**，溶液中**一定有 \\(\\mathrm{Fe^{2+}}\\)**（以及剩余的 \\(\\mathrm{Fe^{3+}}\\)、\\(\\mathrm{Cu^{2+}}\\)）。","(4) 若 \\(\\mathrm{FeCl_3}\\) 有剩余，则容器中**不可能有 Fe 粉和 Cu 粉**（均会被 \\(\\mathrm{Fe^{3+}}\\) 氧化溶解）。"],"answer":"(1) 不可能有 \\(\\mathrm{Fe^{3+}, Cu^{2+}}\\)；(2) 还可能有 \\(\\mathrm{Fe^{3+}}\\) 或 Cu 粉（及一定有 \\(\\mathrm{Fe^{2+}}\\)），绝无 Fe 粉；(3) 不可能有 Fe、Cu，一定有 \\(\\mathrm{Fe^{2+}}\\)（和 \\(\\mathrm{Fe^{3+}, Cu^{2+}}\\)）；(4) 不可能有 Fe、Cu。","markingPoints":["第(1)问准确排除 Fe³⁺ 和 Cu²⁺（1分）","第(2)问排除 Fe 粉并指出可能有 Fe³⁺ 或 Cu（1分）","第(3)问排除 Fe/Cu 单质并确定一定有 Fe²⁺（1.5分）","第(4)问排除 Fe/Cu 单质（1分）"],"verification":"对照化上 p.435 思考题 16c 第3题逐问验证完全吻合。","pitfall":"第(2)问若仅考虑 CuCl₂ 剩余，很容易忘记“若连 Cu 粉也被 FeCl₃ 溶光，容器里还可能残余 Fe³⁺”这一分支。"},{"label":"例 16.3.2","tier":"L4","tierLabel":"L4 统考压轴","title":"高炉炼铁矿石用量、炉渣及含碳生铁产量计算","prompt":"某钢铁厂使用含 \\(\\mathrm{Fe_2O_3}\\) 质量分数为 \\(80\\%\\) 的赤铁矿石（其余脉石主要成分为 \\(\\mathrm{SiO_2}\\)）和石灰石在高炉中冶炼生铁。若投入 \\(2000\\text{ t}\\) 该赤铁矿石（设铁元素全部被还原回收并熔入生铁，最终炼得的生铁中含碳质量分数为 \\(4.0\\%\\)，其余全部按铁计）。(1) 写出高炉内一氧化碳还原赤铁矿以及石灰石造渣除去脉石的三个化学方程式；(2) 计算理论上最多可炼得含碳 \\(4.0\\%\\) 的生铁多少吨？（\\(\\mathrm{Fe}=56,\\ \\mathrm{O}=16\\)）","clues":"利用铁原子守恒求出纯铁质量（1120 t），再除以生铁中铁的质量分数 (1 − 4.0% = 96.0%) 得生铁总质量！","strategy":"Fe₂O₃(160) ~ 2Fe(112)，求出纯铁质量后再折算为含碳 4.0% 的合金生铁总质量。","given":"m(矿石)=2000 t，w(Fe₂O₃)=80%，生铁中 w(C)=4.0%（w(Fe)=96.0%）","principle":"铁原子守恒及含杂质矿石与合金产品双折算。","steps":["(1) 还原铁矿：\\(\\mathrm{3CO(g) + Fe_2O_3(s)} \\xrightarrow{\\Delta} \\mathrm{2Fe(l) + 3CO_2(g)}\\)；","石灰石造渣：\\(\\mathrm{CaCO_3(s)} \\xrightarrow{\\text{高温}} \\mathrm{CaO(s) + CO_2(g)\\uparrow}\\)，\\(\\mathrm{CaO(s) + SiO_2(s)} \\xrightarrow{\\text{高温}} \\mathrm{CaSiO_3(l)}\\)。","(2) 矿石中纯 \\(\\mathrm{Fe_2O_3}\\) 质量：\\(m(\\mathrm{Fe_2O_3}) = 2000\\text{ t} \\times 80\\% = 1600\\text{ t}\\)。","由 \\(\\mathrm{Fe_2O_3}\\)（\\(M=160\\)）\\(\\sim 2\\mathrm{Fe}\\)（\\(2\\times 56 = 112\\)），生成纯铁质量：\\(m(\\mathrm{Fe}) = 1600\\text{ t} \\times \\frac{112}{160} = 1120\\text{ t}\\)。","由于生铁含碳 \\(4.0\\%\\)，即含铁 \\(1 - 4.0\\% = 96.0\\%\\)，故生铁总产量为：","\\(m(\\text{生铁}) = \\frac{1120\\text{ t}}{96.0\\%} \\approx 1167\\text{ t}\\)（精确值 \\(1166.7\\text{ t}\\)）。"],"answer":"(1) 方程式见步骤；(2) 可炼得生铁约 \\(1167\\text{ t}\\)（\\(1166.7\\text{ t}\\)）。","markingPoints":["写出还原与造渣三个正确方程式（2分）","算出纯铁质量 1120 t（1.5分）","正确除以 96.0% 得生铁质量 1167 t（1.5分）"],"verification":"\\(1166.7\\text{ t} \\times 96\\% = 1120\\text{ t Fe}\\)，对应 \\(10\\times 10^6\\text{ mol }\\mathrm{Fe_2O_3} = 1600\\text{ t}\\)。","pitfall":"最后一步最易把“除以 96%”错算成“乘以 96%”（记住：生铁是混合物，质量必大于其中纯铁的质量！）。"}],"practice":[{"id":"chem16-16.3-q1","tier":"L1","tierLabel":"L1 基础","examStyle":"P1 选择","q":"下列物质中，**不能**由组成它的两种元素的单质直接化合而得到的是（　）。","options":["A. \\(\\mathrm{FeS}\\)","B. \\(\\mathrm{Fe_3O_4}\\)","C. \\(\\mathrm{FeCl_2}\\)","D. \\(\\mathrm{FeCl_3}\\)"],"correctOption":"C","given":"思考题 16b 第1题（化上 p.427）","method":"比对 Fe 与 S、O₂、Cl₂ 直接反应氧化数产物","principle":"Cl₂ 氧化性极强与 Fe 直接化合生成 FeCl₃，无法停留于 FeCl₂。","steps":["Fe+S → FeS；3Fe+2O₂ → Fe₃O₄；2Fe+3Cl₂ → 2FeCl₃；只有 FeCl₂ 不能由 Fe 与 Cl₂ 直接化合制得（需 Fe+HCl 或 Fe+FeCl₃）。"],"ans":"C","markingPoints":["识别 Fe 与 Cl₂ 只得 FeCl₃"],"verification":"对照化上 p.427 思考题 16b 第1题。","pitfall":"误选 A 或 B。"},{"id":"chem16-16.3-q2","tier":"L2","tierLabel":"L2 期末","examStyle":"P1 选择","q":"要证明某 \\(\\mathrm{FeCl_2}\\) 溶液中是否混有少量已经氧化变质的 \\(\\mathrm{Fe^{3+}}\\)，同时又能检验另一瓶久置 \\(\\mathrm{FeCl_3}\\) 溶液中是否混有 \\(\\mathrm{Fe^{2+}}\\)，最佳的试剂组合分别是（　）。","options":["A. 均选用 \\(\\mathrm{NaOH}\\) 溶液","B. 先用 \\(\\mathrm{KSCN}\\) 溶液检 \\(\\mathrm{Fe^{3+}}\\)；再用 \\(\\mathrm{K_3[Fe(CN)_6]}\\)（铁(III)氰化钾）溶液检 \\(\\mathrm{Fe^{2+}}\\)","C. 均选用 \\(\\mathrm{KSCN}\\) 溶液","D. 先用氯水检 \\(\\mathrm{Fe^{3+}}\\)；再用 \\(\\mathrm{K_4[Fe(CN)_6]}\\) 检 \\(\\mathrm{Fe^{2+}}\\)"],"correctOption":"B","given":"表16-8 Fe²⁺ 与 Fe³⁺ 检验方法（化上 p.421–422）","method":"避免大量 Fe³⁺ 生成的红褐色沉淀掩盖少量 Fe²⁺ 的白色沉淀","principle":"KSCN 专检 Fe³⁺（血红）；K₃[Fe(CN)₆] 专检 Fe²⁺（深蓝，不受 Fe³⁺ 干扰）。","steps":["检验 Fe²⁺ 中的微量 Fe³⁺ 用 KSCN（极灵敏血红色）；在大量 Fe³⁺ 共存下检验 Fe²⁺ 用 K₃[Fe(CN)₆]（生深蓝沉淀，而 NaOH 会被大量红褐色 Fe(OH)₃ 彻底掩盖白色 Fe(OH)₂）。"],"ans":"B","markingPoints":["掌握混合体系中微量离子特异检验方法"],"verification":"对照化上 p.421–422。","pitfall":"误选 A，忘记大量红褐色 Fe(OH)₃ 会完全盖住白色 Fe(OH)₂。"},{"id":"chem16-16.3-q3","tier":"L3","tierLabel":"L3 预试","examStyle":"P2 实验探究","q":"实验室采用教材图16-9 装置进行“铁粉与水蒸气高温反应”实验（活动3），并同时开展活动4 制备氢氧化亚铁 \\(\\mathrm{Fe(OH)_2}\\)。(1) 活动3 中为什么酒精灯要先加热湿棉花的位置一会儿，再移至放铁粉的位置加热？写出反应方程式；(2) 活动4 中向 \\(\\mathrm{FeSO_4}\\) 溶液滴加 \\(\\mathrm{NaOH}\\) 溶液时观察到白色沉淀迅速变成灰绿色最后变成红褐色，写出颜色转变的方程式，并提出两条能较长时间看到纯白色 \\(\\mathrm{Fe(OH)_2}\\) 沉淀的实验改进措施。","given":"活动3 图16-9 与 活动4 图16-14","method":"解释排尽空气/预生水蒸气；解释 4Fe(OH)₂+O₂+2H₂O→4Fe(OH)₃ 及隔绝氧气三法（煮沸除氧、油封液面、长滴管伸入液面下）","principle":"铁与水蒸气反应规律；Fe(OH)₂ 极易被空气氧化。","steps":["(1) 先加热湿棉花产生充足水蒸气，既能**排出试管内的空气**（防止加热铁粉时铁被氧气氧化，也防后续产生的 \\(\\mathrm{H_2}\\) 混空气爆炸），又为反应提供气态水反应物；方程式：\\(\\mathrm{3Fe(s) + 4H_2O(g)} \\xrightarrow{\\text{高温}} \\mathrm{Fe_3O_4(s) + 4H_2(g)}\\)。","(2) 氧化变色方程式：\\(\\mathrm{4Fe(OH)_2(s) + O_2(g) + 2H_2O(l) \\longrightarrow 4Fe(OH)_3(s)}\\)。","改进措施（任两条）：① 将新配 \\(\\mathrm{NaOH}\\) 溶液事先**煮沸**除去溶解氧（\\(\\mathrm{FeSO_4}\\) 溶液现配并加少量铁粉）；② 在 \\(\\mathrm{FeSO_4}\\) 溶液表面加一层植物油或苯进行**液封隔绝空气**，并用长滴管伸入液面以下挤出 \\(\\mathrm{NaOH}\\) 溶液。"],"ans":"(1) 排空气并供水蒸气，\\(\\mathrm{3Fe+4H_2O(g)} \\xrightarrow{\\text{高温}} \\mathrm{Fe_3O_4+4H_2}\\)；(2) \\(\\mathrm{4Fe(OH)_2+O_2+2H_2O \\to 4Fe(OH)_3}\\)；煮沸除氧 + 油封液面/长滴管液下滴加。","markingPoints":["说明先加热湿棉花排空气与供蒸汽作用并写对方程式（2分）","写出氧化变色方程式（1分）","提出两条合理隔绝氧气改进措施（1.5分）"],"verification":"对照化上 p.415 活动3 与 p.418–419 活动4。","pitfall":"写铁与水蒸气反应漏掉 Fe₃O₄ 或错写成 Fe₂O₃。"},{"id":"chem16-16.3-q4","tier":"L4","tierLabel":"L4 统考压轴","examStyle":"P2 综合计算","q":"电子工业常用 \\(30\\%\\) 的 \\(\\mathrm{FeCl_3}\\) 溶液腐蚀绝缘板上的铜箔来制造印刷电路板（活动6）。现将 \\(9.60\\text{ g}\\) 铜片投入 \\(100\\text{ mL}\\) 浓度为 \\(2.00\\text{ mol}\\cdot\\mathrm{L^{-1}}\\) 的 \\(\\mathrm{FeCl_3}\\) 溶液中充分反应（设溶液体积始终保持 \\(100\\text{ mL}\\) 不变）。(1) 写出反应的离子方程式并判断反应后铜片是否有剩余（若有剩余，求剩余质量）；(2) 求反应后溶液中 \\(\\mathrm{Fe^{2+}}\\) 和 \\(\\mathrm{Cu^{2+}}\\) 的物质的量浓度。（\\(\\mathrm{Cu}=64\\)）","given":"m(Cu)=9.60 g (0.150 mol)；n(FeCl₃)=0.100 × 2.00 = 0.200 mol","method":"依据 2Fe³⁺ + Cu → 2Fe²⁺ + Cu²⁺ 判限量试剂（FeCl₃ 限量！）","principle":"2:1 氧化还原计量关系。","steps":["(1) 离子方程式：\\(\\mathrm{2Fe^{3+}(aq) + Cu(s) \\longrightarrow 2Fe^{2+}(aq) + Cu^{2+}(aq)}\\)。","投料：\\(n(\\mathrm{Cu}) = \\frac{9.60}{64} = 0.150\\text{ mol}\\)，\\(n(\\mathrm{Fe^{3+}}) = 0.100 \\times 2.00 = 0.200\\text{ mol}\\)。","按 \\(2:1\\) 比例，\\(0.200\\text{ mol}\\ \\mathrm{Fe^{3+}}\\) 最多溶解 \\(0.100\\text{ mol}\\ \\mathrm{Cu}\\)，故 **铜片有剩余**：","剩余铜的物质的量为 \\(0.150 - 0.100 = 0.050\\text{ mol}\\)，质量为 \\(0.050 \\times 64 = 3.20\\text{ g}\\)。","(2) \\(\\mathrm{Fe^{3+}}\\) 全部转化为 \\(\\mathrm{Fe^{2+}}\\)，故 \\(n(\\mathrm{Fe^{2+}}) = 0.200\\text{ mol}\\)，\\(n(\\mathrm{Cu^{2+}}) = 0.100\\text{ mol}\\)。","溶液体积 \\(0.100\\text{ L}\\)，浓度分别为：\\(c(\\mathrm{Fe^{2+}}) = \\frac{0.200}{0.100} = 2.00\\text{ mol}\\cdot\\mathrm{L^{-1}}\\)，\\(c(\\mathrm{Cu^{2+}}) = \\frac{0.100}{0.100} = 1.00\\text{ mol}\\cdot\\mathrm{L^{-1}}\\)。"],"ans":"(1) 铜有剩余，剩余 \\(3.20\\text{ g}\\)；(2) \\(c(\\mathrm{Fe^{2+}}) = 2.00\\text{ mol}\\cdot\\mathrm{L^{-1}}\\)，\\(c(\\mathrm{Cu^{2+}}) = 1.00\\text{ mol}\\cdot\\mathrm{L^{-1}}\\)。","markingPoints":["写出离子方程式并判断 Fe³⁺ 限量、Cu 剩 3.20 g（2分）","算得 c(Fe²⁺)=2.00 mol/L 与 c(Cu²⁺)=1.00 mol/L（2分）"],"verification":"电荷守恒核验：反应前正电荷 \\(0.200\\times 3 = 0.600\\text{ mol}\\)；反应后 \\(0.200\\times 2 + 0.100\\times 2 = 0.600\\text{ mol}\\)，完全守恒！","pitfall":"若把比例误记成 1:1，就会误算为 Cu 完全反应且剩 Fe³⁺。"}],"cheatSheet":["Fe 氧化态：遇弱氧化剂（HCl、Cu²⁺、S）→ Fe²⁺；遇强氧化剂（Cl₂、热浓 H₂SO₄/HNO₃）→ Fe³⁺；3Fe+4H₂O(g) —高温→ Fe₃O₄+4H₂。","Fe²⁺/Fe³⁺ 四法检验：KSCN（Fe³⁺ 血红 [Fe(SCN)]²⁺）；NaOH（Fe²⁺ 白→灰绿→红褐）；K₃[Fe(CN)₆] 检 Fe²⁺ 深蓝、K₄[Fe(CN)₆] 检 Fe³⁺ 深蓝；H₂S（Fe²⁺ 黑沉 FeS、Fe³⁺ 黄沉 S）。","高炉炼铁：3CO+Fe₂O₃→2Fe+3CO₂；CaCO₃→CaO+CO₂；CaO+SiO₂→CaSiO₃(炉渣)；生铁含碳 2%~4.5%，钢含碳 0.02%~2%。"],"kbEntryIds":["kb-chem16-fe-triangle","kb-chem16-fe-ions-test","kb-chem16-iron-steel"],"quiz":{"q":"实验室配制并长期保存 \\(\\mathrm{FeSO_4}\\) 溶液时，为了防止其被氧化变质和水解，通常要在试剂瓶底部放入少量什么物质？写出防氧化的离子方程式。","given":"化上 p.419 活动探究3 正文","method":"利用铁粉将刚被空气氧化产生的 Fe³⁺ 还原回 Fe²⁺","principle":"Fe + 2Fe³⁺ → 3Fe²⁺。","steps":["常向溶液中加入少量洁净的**铁粉（或铁钉）**（同时常加少量稀硫酸抑制水解）。","即使少量 \\(\\mathrm{Fe^{2+}}\\) 被空气氧化为 \\(\\mathrm{Fe^{3+}}\\)，也会立即被铁粉还原回来：\\(\\mathrm{Fe(s) + 2Fe^{3+}(aq) \\longrightarrow 3Fe^{2+}(aq)}\\)。"],"ans":"加入少量铁粉（或铁钉）；\\(\\mathrm{Fe + 2Fe^{3+} \\longrightarrow 3Fe^{2+}}\\)"}},{"id":"16.4","t":"铜","anchor":{"pages":"化上 p.428–436","syllabus":"3.5.4 铜的性质、铜的重要化合物、Cu²⁺ 检验及黄铜矿冶炼与电解精炼","examScopes":["sem2_final","uec"],"examWeight":"P1/P2 核心重点（铜与酸/非金属反应、胆矾、Cu²⁺ 三法检验、粗铜电解精炼）","terms":"copper patina · copper(I) oxide · blue vitriol · Bordeaux mixture · electrolytic refining · anode slime","prerequisites":["硝酸和浓硫酸的强氧化性（化上 Ch 13.3 & Ch 14.7）","配合物形成与阳离子检验（化上 Ch 16.2）"],"goals":["掌握铜的物理性质（紫红色、导电导热优良）、铜合金（黄铜 Cu-Zn、青铜 Cu-Sn）以及潮湿空气生铜绿 Cu₂(OH)₂CO₃ 的特点。","写出铜高温与 S、Cl₂、O₂（含 CuO 1100℃ 转为红色 Cu₂O）以及与浓硫酸、浓/稀硝酸反应的方程式；掌握胆矾受热脱水/分解及检验水的用途。","通过活动8–9（表16-11）掌握 Cu²⁺ 三种检验方法，并阐明黄铜矿高温冶炼流程及粗铜电解精炼（阳极泥、阴阳极反应）原理。"]},"concepts":[{"kind":"definition","title":"铜的物理性质、合金、铜绿及化学反应（活动7）","pageRef":"化上 p.428–430","body":["**物理性质与合金**：铜是具有**紫红色**光泽的金属，熔点 **1083℃**，密度 8920 kg m⁻³，质软，延展性、导电性和导热性极其优良（全球一半铜用于电器电线）。重要合金：**黄铜（Cu-Zn 合金）**、**青铜（Cu-Sn 合金）**。","**生锈（铜绿）**：铜不活泼，干燥空气中不与氧气反应；但在潮湿空气中与 \\(\\mathrm{O_2, H_2O, CO_2}\\) 缓慢作用生成绿色的碱式碳酸铜(II) **\\(\\mathrm{Cu_2(OH)_2CO_3}\\)**（俗称铜绿，有毒）：\\(\\mathrm{2Cu + O_2 + H_2O + CO_2 \\longrightarrow Cu_2(OH)_2CO_3}\\)。","**高温与非金属化合（活动7）**：铜丝伸入硫蒸气中发红反应生成黑灰色的 \\(\\mathrm{Cu_2S}\\)（\\(\\mathrm{2Cu + S} \\xrightarrow{\\text{高温}} \\mathrm{Cu_2S}\\)）；与 \\(\\mathrm{Cl_2}\\) 生成 \\(\\mathrm{CuCl_2}\\)；空气中加热生成黑色 \\(\\mathrm{CuO}\\)，若继续加热至 **1100℃** 赤热状态，黑色 \\(\\mathrm{CuO}\\) 与铜反应又被还原为**红色的 \\(\\mathrm{Cu_2O}\\)**：\\(\\mathrm{CuO(s) + Cu(s)} \\xrightarrow{1100\\ ^\\circ\\mathrm{C}} \\mathrm{Cu_2O(s)}\\)（铜在高温下**不与氮气反应**）。","**与酸反应**：铜不与稀盐酸、稀硫酸反应（金属活动性在 H 之后），但在**氧化性酸**（热浓硫酸、浓硝酸、稀硝酸）中容易被氧化为 \\(\\mathrm{Cu^{2+}}\\) 盐。"],"takeaway":"注意金属铜加热的“变黑又变红”两步曲：先 2Cu+O₂ → 2CuO（黑），极高温 1100℃ 时 CuO 又转为 Cu₂O（红）！"},{"kind":"experiment","title":"活动8–9：铜的重要化合物、胆矾检水及 Cu²⁺ 三法检验（表16-11）","pageRef":"化上 p.431–433","body":["**铜的氧化物与硫酸铜**：\\(\\mathrm{Cu_2O}\\)（红色，制玻璃搪瓷红色颜料和电器整流器）与 \\(\\mathrm{CuO}\\)（黑色）均不溶于水。蓝色**胆矾**（\\(\\mathrm{CuSO_4\\cdot 5H_2O}\\)）受热脱水变为**白色无水 \\(\\mathrm{CuSO_4}\\)**（遇水立即复蓝，是**检验微量水存在**的灵敏试剂）；再高温分解为 \\(\\mathrm{CuO + SO_3\\uparrow}\\)。\\(\\mathrm{CuSO_4}\\) 溶液与石灰乳混合配成**波尔多液**作农业杀菌剂（图16-30）。","**Cu²⁺ 三种检验方法（表16-11）**：","① **加碱（NaOH）**：生成**蓝色絮状沉淀**：\\(\\mathrm{Cu^{2+}(aq) + 2OH^-(aq) \\longrightarrow Cu(OH)_2(s)\\downarrow}\\)；","② **通 \\(\\mathrm{H_2S}\\)**：生成不溶于酸的**黑色沉淀**：\\(\\mathrm{Cu^{2+}(aq) + H_2S(g) \\longrightarrow CuS(s)\\downarrow + 2H^+(aq)}\\)；","③ **逐滴加氨水直至过量（活动9）**：先生成蓝色 \\(\\mathrm{Cu(OH)_2}\\) 沉淀，继而溶解形成**深蓝色澄清溶液**：\\(\\mathrm{Cu(OH)_2 + 4NH_3\\cdot H_2O \\longrightarrow [Cu(NH_3)_4]^{2+} + 2OH^- + 4H_2O}\\)。"],"takeaway":"配制农业杀菌剂“波尔多液”（CuSO₄ + Ca(OH)₂ 悬浊液）时，严禁使用铁制容器，否则 Fe 会置换 Cu²⁺ 导致药效丧失并腐蚀容器！"},{"kind":"mechanism","title":"黄铜矿火法炼铜与粗铜电解精炼（图16-34）","pageRef":"化上 p.433–434","body":["**矿石与火法炼铜（黄铜矿 \\(\\mathrm{CuFeS_2}\\)）**：主要铜矿石有赤铜矿（\\(\\mathrm{Cu_2O}\\)）、孔雀石（\\(\\mathrm{CuCO_3\\cdot Cu(OH)_2}\\)）、蓝铜矿（\\(\\mathrm{2CuCO_3\\cdot Cu(OH)_2}\\)）、黄铜矿（\\(\\mathrm{CuFeS_2}\\)）和辉铜矿（\\(\\mathrm{Cu_2S}\\)）。","火法流程：**选矿** → **焙烧**（\\(\\mathrm{2CuFeS_2 + O_2} \\xrightarrow{\\text{焙烧}} \\mathrm{Cu_2S + 2FeS + SO_2\\uparrow}\\)） → **转炉吹炼**（\\(\\mathrm{2Cu_2S + 3O_2} \\xrightarrow{\\text{高温}} \\mathrm{2Cu_2O + 2SO_2\\uparrow}\\)，接着 \\(\\mathrm{2Cu_2O + Cu_2S} \\xrightarrow{\\text{高温}} \\mathrm{6Cu + SO_2\\uparrow}\\)）。所得**粗铜**含铜 99.5%~99.7%，仍含 **Ag、Au、Fe、Zn** 等杂质。","**粗铜电解精炼（电气用铜纯度需 99.95%~99.98%）**：用**粗铜作阳极**（接直流电源正极）、**纯铜薄片作阴极**（接负极）、**硫酸铜酸性溶液作电解液**。通电时：阳极上较活泼杂质 **Zn、Fe** 优先于 **Cu** 失电子进入溶液，而不活泼贵金属 **Au、Ag** 不放电直接沉降于槽底形成**阳极泥**（可回收金银）；阴极上仅氧化性最强的 **\\(\\mathrm{Cu^{2+}}\\)** 优先得电子析出纯铜（\\(\\mathrm{Cu^{2+} + 2e^- \\to Cu}\\)），因此电解过程中溶液中 \\(c(\\mathrm{Cu^{2+}})\\) 会**略微减小**。"],"takeaway":"电解精炼“阳极粗铜、阴极纯铜、阳极泥收金银、阴极增重阳极减重但两者质量变化并不相等（因阳极先溶 Zn/Fe）”！"}],"diagrams":[{"src":"assets/fig/v2/chem16-cu-refining.svg","caption":"图 16-2 粗铜电解精炼装置原理及铜及其重要化合物转化网络","alt":"粗铜电解精炼与铜化合物转化图","pageRef":"化上 p.428–435"}],"formulas":[{"title":"铜在空气及高温下的转化与胆矾热分解方程式","tex":"\\mathrm{2Cu + O_2 + H_2O + CO_2 \\longrightarrow Cu_2(OH)_2CO_3},\\qquad \\mathrm{CuSO_4\\cdot 5H_2O(s)} \\xrightarrow{\\Delta} \\mathrm{CuSO_4(s) + 5H_2O(l)}","plain":"2Cu + O2 + H2O + CO2 -> Cu2(OH)2CO3; CuSO4·5H2O --Δ--> CuSO4 + 5H2O","conditions":"CuSO₄ 进一步高温分解：CuSO₄ —高温→ CuO + SO₃↑","pageRef":"化上 p.429、p.431","note":"胆矾白色无水硫酸铜遇水复蓝，是有机实验和无机实验定性检验水蒸气最常用试剂。"},{"title":"粗铜电解精炼阴阳极反应与黄铜矿冶炼核心式","tex":"\\text{阳极：}\\mathrm{Cu(s) - 2e^- \\longrightarrow Cu^{2+}(aq)},\\qquad \\text{阴极：}\\mathrm{Cu^{2+}(aq) + 2e^- \\longrightarrow Cu(s)},\\qquad \\mathrm{2Cu_2O + Cu_2S} \\xrightarrow{\\text{高温}} \\mathrm{6Cu + SO_2\\uparrow}","plain":"阳极: Cu - 2e- -> Cu2+; 阴极: Cu2+ + 2e- -> Cu; 2Cu2O + Cu2S -> 6Cu + SO2↑","conditions":"粗铜阳极上 Zn、Fe 也同时溶解：Zn−2e⁻→Zn²⁺，Fe−2e⁻→Fe²⁺","pageRef":"化上 p.433–434","note":"火法炼铜最后一步 2Cu₂O + Cu₂S → 6Cu + SO₂ 为归中反应（Cu 从 +1 降至 0，S 从 −2 升至 +4）。"}],"pitfalls":[{"title":"认为电解精炼铜时“阳极减少的质量 = 阴极增加的质量”","wrong":"“粗铜电解精炼过程中，电解液里 \\(\\mathrm{Cu^{2+}}\\) 浓度始终严格保持不变，阳极减重等于阴极增重。”","diagnosis":"粗铜中混有比铜活泼的 **Zn、Fe** 杂质，阳极上不仅有 Cu 溶解，Zn 和 Fe 也会优先或同步失电子进入溶液，而阴极上却只析出 Cu。","right":"粗铜电解精炼时，由于阳极有 Zn、Fe 溶解分担了一部分电量，阴极上析出 \\(\\mathrm{Cu}\\) 消耗的 \\(\\mathrm{Cu^{2+}}\\) 多于阳极溶入的 \\(\\mathrm{Cu^{2+}}\\)，故电解液中 **\\(c(\\mathrm{Cu^{2+}})\\) 会逐渐减小**，且两极质量变化通常不等。","checkRule":"区分“电镀铜（纯铜阳极，\\(c(\\mathrm{Cu^{2+}})\\) 严格不变）”与“电解精炼粗铜（粗铜阳极，\\(c(\\mathrm{Cu^{2+}})\\) 略减小）”！"},{"title":"把 Cu²⁺ 加过量氨水现象记成“蓝色沉淀不溶”","wrong":"“硫酸铜溶液加入氨水生成的蓝色 \\(\\mathrm{Cu(OH)_2}\\) 沉淀与 \\(\\mathrm{Al(OH)_3}\\) 一样不溶于过量氨水。”","diagnosis":"虽然两者都是弱碱，但 \\(\\mathrm{Cu^{2+}}\\) 是过渡金属离子，能与 \\(\\mathrm{NH_3}\\) 形成极稳定的深蓝色配离子 \\(\\mathrm{[Cu(NH_3)_4]^{2+}}\\)。","right":"\\(\\mathrm{Cu(OH)_2}\\) 遇过量氨水**迅速溶解**变为深蓝色溶液；而 \\(\\mathrm{Al(OH)_3}\\)、\\(\\mathrm{Fe(OH)_3}\\)、\\(\\mathrm{Mg(OH)_2}\\) 不溶于过量氨水。","checkRule":"过量氨水溶解的三大沉淀：\\(\\mathrm{AgCl/Ag_2O}\\)、\\(\\mathrm{Cu(OH)_2}\\)、\\(\\mathrm{Zn(OH)_2}\\)。"}],"examples":[{"label":"例 16.4.1","tier":"L3","tierLabel":"L3 预试拔高","title":"孔雀石高温分解与限用试剂湿法/火法炼铜设计（思考题 16c 第2题）","prompt":"某地所产孔雀石的主要成分是碱式碳酸铜 \\(\\mathrm{CuCO_3\\cdot Cu(OH)_2}\\)（已知铜的氢氧化物受热会分解成氧化铜和水）。(1) 写出孔雀石在高温下完全分解的化学方程式；(2) 若以(1)所得的黑色金属氧化物为原料制取金属铜，现供选择的试剂只有：**木炭、铁屑、生石灰、稀硫酸**，不得另选其他试剂。请写出你采用**高温还原法（火法）**以及**湿法冶金**两种路线制取铜的相关化学方程式。","clues":"(1) CuCO₃·Cu(OH)₂ → 2CuO + CO₂↑ + H₂O↑；(2) 火法用木炭 C 高温还原 CuO；湿法先用稀硫酸溶解 CuO 得 CuSO₄，再用铁屑置换出 Cu！","strategy":"严格限用给定四种试剂，写出火法（碳还原）和湿法（酸溶+铁置换）全套方程式。","given":"孔雀石 CuCO₃·Cu(OH)₂；限定试剂：木炭、铁屑、生石灰、稀硫酸","principle":"碱式盐热分解；高温还原冶金与湿法置换冶金。","steps":["(1) 孔雀石高温分解：\\(\\mathrm{CuCO_3\\cdot Cu(OH)_2(s)} \\xrightarrow{\\text{高温}} \\mathrm{2CuO(s) + CO_2(g)\\uparrow + H_2O(g)\\uparrow}\\)。","(2) **路线一（高温冶炼火法）**：利用木炭作还原剂在高温下还原 \\(\\mathrm{CuO}\\)：\\(\\mathrm{2CuO(s) + C(s)} \\xrightarrow{\\text{高温}} \\mathrm{2Cu(s) + CO_2(g)\\uparrow}\\)（或高温过量木炭生成 \\(\\mathrm{CO}\\)：\\(\\mathrm{CuO + C} \\xrightarrow{\\text{高温}} \\mathrm{Cu + CO\\uparrow}\\)）。","**路线二（湿法冶金，教材 p.434）**：先用稀硫酸溶解 \\(\\mathrm{CuO}\\)：\\(\\mathrm{CuO(s) + H_2SO_4(aq) \\longrightarrow CuSO_4(aq) + H_2O(l)}\\)；再加入铁屑置换金属铜：\\(\\mathrm{Fe(s) + CuSO_4(aq) \\longrightarrow FeSO_4(aq) + Cu(s)}\\)。"],"answer":"(1) \\(\\mathrm{CuCO_3\\cdot Cu(OH)_2 \\xrightarrow{\\text{高温}} 2CuO + CO_2\\uparrow + H_2O\\uparrow}\\)；(2) 火法 \\(\\mathrm{2CuO+C \\xrightarrow{\\text{高温}} 2Cu+CO_2\\uparrow}\\)，湿法酸溶加铁置换见步骤。","markingPoints":["正确配平孔雀石高温分解方程式（1.5分）","在限定试剂范围内写对火法木炭还原方程式（1.5分）","写对湿法酸溶与铁屑置换两步方程式（1.5分）"],"verification":"对照化上 p.434 资料链接“金属冶炼的常用方法”及 p.435 思考题 16c 第2题。","pitfall":"若在高温冶炼中误用生石灰 CaO 去还原 CuO 是行不通的（CaO 不是还原剂），注意限定试剂中仅木炭和铁屑可作还原剂。"},{"label":"例 16.4.2","tier":"L4","tierLabel":"L4 统考压轴","title":"胆矾两阶段热重分解计算与湿法铁铜合金纯度测定","prompt":"(1) 称取 \\(25.0\\text{ g}\\) 蓝色胆矾晶体（\\(\\mathrm{CuSO_4\\cdot 5H_2O}\\)，式量 \\(250\\)）置于坩埚中持续升温加热，先在 \\(250\\ ^\\circ\\mathrm{C}\\) 完全失去结晶水，再升温至 \\(700\\ ^\\circ\\mathrm{C}\\) 以上完全分解成黑色固体和单一酸性气体。试计算最终剩余黑色固体的质量；(2) 将 \\(12.0\\text{ g}\\) 铁铜混合粉末（黄铜外另加铁屑模型）加入足量稀盐酸充分反应，在标准状况下收集到 \\(2.24\\text{ L}\\) 气体。求原混合粉末中铜的质量分数。（\\(\\mathrm{Cu}=64,\\ \\mathrm{Fe}=56,\\ \\mathrm{S}=32,\\ \\mathrm{O}=16\\)）","clues":"(1) 25.0 g 胆矾为 0.100 mol → 700℃ 彻底分解为 0.100 mol 黑色 CuO（8.00 g）！；(2) Cu 不溶于稀盐酸，仅 Fe 与稀盐酸生成 0.100 mol H₂（2.24 L）→ m(Fe)=5.60 g！","strategy":"分两小问分别利用 Cu 守恒（胆矾→CuO）与 Fe+HCl 产 H₂ 计量（Cu 不溶）计算。","given":"(1) m(CuSO₄·5H₂O)=25.0 g (0.100 mol)；(2) m(Fe+Cu)=12.0 g，V(H₂, STP)=2.24 L (0.100 mol)","principle":"铜原子守恒与金属活动性顺序（Cu 在 H 后不与非氧化性酸反应）。","steps":["(1) 胆矾物质的量：\\(n(\\mathrm{CuSO_4\\cdot 5H_2O}) = \\frac{25.0}{250} = 0.100\\text{ mol}\\)。","高温两步变化：\\(\\mathrm{CuSO_4\\cdot 5H_2O} \\xrightarrow{\\Delta} \\mathrm{CuSO_4 + 5H_2O}\\)，\\(\\mathrm{CuSO_4(s)} \\xrightarrow{\\text{高温}} \\mathrm{CuO(s) + SO_3(g)\\uparrow}\\)。","由铜原子守恒，最终得到黑色 \\(\\mathrm{CuO}\\)（\\(M=80.0\\text{ g}\\cdot\\mathrm{mol^{-1}}\\)）为 \\(0.100\\text{ mol}\\)，质量 \\(m(\\mathrm{CuO}) = 0.100 \\times 80.0 = 8.00\\text{ g}\\)。","(2) 铜不与稀盐酸反应，唯有铁溶解：\\(\\mathrm{Fe + 2HCl \\longrightarrow FeCl_2 + H_2\\uparrow}\\)。","收集到氢气：\\(n(\\mathrm{H_2}) = \\frac{2.24}{22.4} = 0.100\\text{ mol}\\)，故 \\(n(\\mathrm{Fe}) = 0.100\\text{ mol}\\)，\\(m(\\mathrm{Fe}) = 0.100 \\times 56 = 5.60\\text{ g}\\)。","铜的质量为 \\(12.0 - 5.60 = 6.40\\text{ g}\\)，质量分数 \\(w(\\mathrm{Cu}) = \\frac{6.40}{12.0} \\times 100\\% \\approx 53.3\\%\\)。"],"answer":"(1) 最终黑色 \\(\\mathrm{CuO}\\) 质量为 \\(8.00\\text{ g}\\)；(2) 原混合粉末中铜的质量分数约为 \\(53.3\\%\\)。","markingPoints":["写出胆矾两步分解并算得 CuO 为 8.00 g（2分）","指出 Cu 不溶稀盐酸，由 H₂ 算出 m(Fe)=5.60 g（1.5分）","求出 m(Cu)=6.40 g 与质量分数 53.3%（1分）"],"verification":"第一步中 250℃ 时无水 CuSO₄ 质量为 16.0 g，再升温分解放出 SO₃ 8.00 g 后剩 8.00 g CuO。","pitfall":"若忘记 700℃ 以上 CuSO₄ 也会分解（p.431 明确给出高温分解式），会错答成无水硫酸铜质量 16.0 g！"}],"practice":[{"id":"chem16-16.4-q1","tier":"L1","tierLabel":"L1 基础","examStyle":"P1 选择","q":"下列关于金属铜的叙述中，**不正确**的是（　）。","options":["A. 纯铜是一种具有紫红色金属光泽的金属","B. 铜是热和电的良导体，大量用于制作电线和热交换器","C. 铜在自然界中主要以游离态单质形式大量存在","D. 铜是人类历史上使用最早、目前产量居铁和铝之后第三位的金属"],"correctOption":"C","given":"思考题 16c 第1题（化上 p.435）","method":"对照铜在地壳中存在形式（赤铜矿、孔雀石、黄铜矿、辉铜矿）","principle":"自然界中天然游离铜很少，绝大多数铜以硫化物、碳酸盐等化合态形式存在。","steps":["C 错：虽然有少量天然铜，但自然界中的铜**主要以化合态**存在于矿石中（化上 p.433）。"],"ans":"C","markingPoints":["明确铜在自然界主要以化合态存在"],"verification":"对照化上 p.433 原文与 p.435 思考题 16c 第1题。","pitfall":"误以为铜不活泼就在自然界主要以单质存在（金 Au 才主要以游离态存在）。"},{"id":"chem16-16.4-q2","tier":"L2","tierLabel":"L2 期末","examStyle":"P1 选择","q":"检验某未知溶液中是否含有 \\(\\mathrm{Cu^{2+}}\\) 时，下列实验现象与结论对应**错误**的是（　）。","options":["A. 滴入 \\(\\mathrm{NaOH}\\) 溶液，立即产生蓝色絮状沉淀 \\(\\mathrm{Cu(OH)_2}\\)","B. 通入 \\(\\mathrm{H_2S}\\) 气体，产生不溶于稀硫酸的黑色沉淀 \\(\\mathrm{CuS}\\)","C. 逐滴加入浓氨水直至过量，先产生蓝色沉淀，继续滴加后沉淀溶解变成深蓝色溶液","D. 向溶液中投入一小块干燥的无水 \\(\\mathrm{CuSO_4}\\) 粉末，看是否变成红色"],"correctOption":"D","given":"表16-11 Cu²⁺ 检验与胆矾变色（化上 p.431–433）","method":"逐一核对 Cu²⁺ 检验反应及无水硫酸铜用途","principle":"无水 CuSO₄ 遇水变蓝（检验水，而不是检验 Cu²⁺，且不变红）。","steps":["A、B、C 均是教材表16-11 及活动9 正规检验 \\(\\mathrm{Cu^{2+}}\\) 的反应；D 错，无水硫酸铜检验水且遇水变**蓝**（而非红）。"],"ans":"D","markingPoints":["掌握 Cu²⁺ 三大检验法与胆矾检验水的区别"],"verification":"对照化上 p.431–433。","pitfall":"把无水 CuSO₄ 遇水变蓝记成检验 Cu²⁺ 或记错颜色。"},{"id":"chem16-16.4-q3","tier":"L3","tierLabel":"L3 预试","examStyle":"P2 简答","q":"工业上由黄铜矿（\\(\\mathrm{CuFeS_2}\\)）高温冶炼得到的粗铜纯度约为 \\(99.5\\%\\sim 99.7\\%\\)，仍含有 \\(\\mathrm{Ag, Au, Fe, Zn}\\) 等杂质，必须经过电解精炼才能满足电气工业要求（如图16-34）。(1) 写出电解精炼装置中的阳极材料、阴极材料和电解质溶液；(2) 写出电解过程中的阳极泥成分及阴极发生的电极反应；(3) 简述电解过程中电解质溶液里 \\(\\mathrm{Cu^{2+}}\\) 浓度将如何变化？为什么？","given":"化上 p.433 粗铜电解精炼原理","method":"按金属活动性差异分析阳极各元素去向（Zn/Fe 溶、Cu 溶、Au/Ag 沉阳极泥）","principle":"电解池氧化还原优先放电规律。","steps":["(1) 阳极：**粗铜**（接正极）；阴极：**纯铜薄片**（接负极）；电解质溶液：**含稀硫酸的 \\(\\mathrm{CuSO_4}\\) 溶液**。","(2) 阳极泥主要含不活泼贵金属 **\\(\\mathrm{Au}\\) 和 \\(\\mathrm{Ag}\\)**；阴极电极反应：\\(\\mathrm{Cu^{2+}(aq) + 2e^- \\longrightarrow Cu(s)}\\)。","(3) 电解液中 \\(c(\\mathrm{Cu^{2+}})\\) 会**略微减小**。原因：通电时阳极上活泼杂质 \\(\\mathrm{Zn}\\) 和 \\(\\mathrm{Fe}\\) 会先于或同步与 \\(\\mathrm{Cu}\\) 失电子溶解（\\(\\mathrm{Zn \\to Zn^{2+} + 2e^-}\\)、\\(\\mathrm{Fe \\to Fe^{2+} + 2e^-}\\)），即相同电量下阳极溶出的 \\(\\mathrm{Cu^{2+}}\\) 物质的量**少于**阴极得电子析出的 \\(\\mathrm{Cu}\\) 物质的量，因此 \\(c(\\mathrm{Cu^{2+}})\\) 减小。"],"ans":"(1) 阳极粗铜、阴极纯铜、CuSO₄ 酸性溶液；(2) 阳极泥含 Au/Ag，阴极 \\(\\mathrm{Cu^{2+}+2e^- \\to Cu}\\)；(3) c(Cu²⁺) 减小（因阳极 Zn/Fe 分担失电子电量）。","markingPoints":["准确指明阳极、阴极、电解液组成（1.5分）","答出阳极泥 Au/Ag 及阴极反应（1.5分）","正确解释 c(Cu²⁺) 略微减小原因（1.5分）"],"verification":"对照电极电势与电量守恒核验。","pitfall":"误答溶液中的 Fe²⁺、Zn²⁺ 也会在阴极跟着铜一起析出（Cu²⁺ 氧化性远强于 Zn²⁺、Fe²⁺、H⁺，故阴极只出纯铜）。"},{"id":"chem16-16.4-q4","tier":"L4","tierLabel":"L4 统考压轴","examStyle":"P2 综合计算","q":"某粗铜样品仅含杂质铁和银（不含其他成分）。取 \\(10.28\\text{ g}\\) 该粗铜粉末投入足量稀硝酸中（设金属全部溶解，还原产物只有 \\(\\mathrm{NO}\\) 气体，\\(\\mathrm{Fe}\\) 全部被氧化至 \\(\\mathrm{Fe^{3+}}\\)，\\(\\mathrm{Cu}\\) 至 \\(\\mathrm{Cu^{2+}}\\)，\\(\\mathrm{Ag}\\) 至 \\(\\mathrm{Ag^+}\\)），在标准状况下收集到 \\(2.688\\text{ L}\\) 的 \\(\\mathrm{NO}\\) 气体；若将反应后的全部溶液（无酸过量妨碍）加入足量 \\(\\mathrm{NaCl}\\) 溶液，得到 \\(1.435\\text{ g}\\) 白色沉淀。(1) 计算该粗铜样品中银的质量；(2) 计算样品中铁和铜各有多少摩尔？（\\(\\mathrm{Fe}=56,\\ \\mathrm{Cu}=64,\\ \\mathrm{Ag}=108,\\ \\mathrm{Cl}=35.5\\)）","method":"由 AgCl 沉淀质量定银的物质的量与失电子数；由 NO 体积求总得失电子数，扣除银所失电子后得铁与铜共失电子数，再联立铁铜质量方程与电子守恒方程求解。","given":"\\(m(\\text{粗铜}) = 10.28\\text{ g}\\)；\\(V(\\mathrm{NO,\\ STP}) = 2.688\\text{ L}\\)（\\(0.120\\text{ mol}\\)）；\\(m(\\mathrm{AgCl}) = 1.435\\text{ g}\\)（\\(0.010\\text{ mol}\\)）。","principle":"原子守恒（\\(\\mathrm{Ag}\\to\\mathrm{AgCl}\\)）与氧化还原反应得失电子守恒（\\(\\mathrm{NO_3^-}\\to\\mathrm{NO}\\) 每摩得 \\(3\\text{ mol }\\mathrm{e^-}\\)）。","steps":["(1) 白色沉淀 \\(\\mathrm{AgCl}\\)（\\(M=143.5\\)）物质的量：\\(n(\\mathrm{AgCl}) = \\frac{1.435}{143.5} = 0.0100\\text{ mol}\\)。","由银守恒，\\(n(\\mathrm{Ag}) = 0.0100\\text{ mol}\\)，故银的质量：\\(m(\\mathrm{Ag}) = 0.0100 \\times 108 = 1.08\\text{ g}\\)。","(2) 样品中 Fe 与 Cu 的总质量为：\\(10.28 - 1.08 = 9.20\\text{ g}\\)。","收集到 NO 的物质的量：\\(n(\\mathrm{NO}) = \\frac{2.688}{22.4} = 0.120\\text{ mol}\\)，故硝酸共得到电子：\\(n(e^-) = 3 \\times 0.120 = 0.360\\text{ mol}\\)。","扣除 \\(0.0100\\text{ mol Ag}\\)（\\(0\\to +1\\)）失去的 \\(0.0100\\text{ mol }e^-\\)，Fe（\\(0\\to +3\\)）和 Cu（\\(0\\to +2\\)）共失去 \\(0.360 - 0.010 = 0.350\\text{ mol }e^-\\)。","设 \\(n(\\mathrm{Fe}) = x\\text{ mol}\\)，\\(n(\\mathrm{Cu}) = y\\text{ mol}\\)，联立质量与电子守恒方程：","\\(56x + 64y = 9.20\\)，\\(3x + 2y = 0.350\\)。","将第二式乘 32 得 \\(96x + 64y = 11.20\\)，减去第一式得 \\(40x = 2.00 \\implies x = 0.050\\text{ mol}\\)，代回得 \\(y = 0.100\\text{ mol}\\)。"],"ans":"(1) \\(m(\\mathrm{Ag}) = 1.08\\text{ g}\\)；(2) \\(n(\\mathrm{Fe}) = 0.050\\text{ mol}\\)，\\(n(\\mathrm{Cu}) = 0.100\\text{ mol}\\)。","markingPoints":["由 AgCl 沉淀算得 Ag 为 0.0100 mol（1.08 g）（1.5分）","由 NO 算出总转移电子 0.360 mol 并扣除 Ag 得 0.350 mol（1.5分）","联立质量与电子方程解得 n(Fe)=0.050 mol、n(Cu)=0.100 mol（2分）"],"verification":"总质量检验：\\(0.050\\times 56 + 0.100\\times 64 + 1.08 = 2.80 + 6.40 + 1.08 = 10.28\\text{ g}\\)；总失电子检验：\\(0.050\\times 3 + 0.100\\times 2 + 0.010\\times 1 = 0.360\\text{ mol}\\)，对应 \\(n(\\mathrm{NO}) = 0.360/3 = 0.120\\text{ mol}\\)，\\(V(\\mathrm{NO}) = 2.688\\text{ L}\\)，完全吻合。","pitfall":"若将足量稀硝酸中的铁误按生成 \\(\\mathrm{Fe^{2+}}\\) 计算（失 \\(2\\mathrm{e^-}\\) 而非 \\(3\\mathrm{e^-}\\)），或忘记减去 \\(\\mathrm{Ag}\\to\\mathrm{Ag^+}\\) 所消耗的 \\(0.010\\text{ mol }\\mathrm{e^-}\\)，均会导致联立方程解出错误物质的量。"}],"cheatSheet":["铜性质：紫红良导体；黄铜(Cu-Zn)、青铜(Cu-Sn)；潮湿空气生铜绿 Cu₂(OH)₂CO₃；不溶稀 HCl/H₂SO₄，溶浓硫酸与浓/稀硝酸。","变色检验：无水 CuSO₄(白) + 5H₂O → 胆矾(蓝) 检水；2Cu+S —高温→ Cu₂S；CuO+Cu —1100℃→ Cu₂O(红)。","Cu²⁺ 三法检验：NaOH(蓝沉)、H₂S(黑沉 CuS)、过量氨水(深蓝 [Cu(NH₃)₄]²⁺)；粗铜精炼（阳极粗铜、阴极纯铜、阳极泥 Au/Ag）。"],"kbEntryIds":["kb-chem16-cu-props-test","kb-chem16-cu-refining"],"quiz":{"q":"把纯净无水硫酸铜白色粉末投入某有机溶剂（如含微量水的无水乙醇）中，若观察到粉末变成蓝色，这说明了什么？写出化学方程式。","given":"化上 p.431 硫酸铜(II)脱水与水合","method":"利用无水 CuSO₄ 结合结晶水生成蓝色胆矾检验微量水","principle":"CuSO₄(白) + 5H₂O → CuSO₄·5H₂O(蓝)。","steps":["白色粉末变蓝说明该有机溶剂中含有**水分**。","反应方程式：\\(\\mathrm{CuSO_4(s) + 5H_2O(l) \\longrightarrow CuSO_4\\cdot 5H_2O(s)}\\)。"],"ans":"说明该溶剂中含有水分；\\(\\mathrm{CuSO_4 + 5H_2O \\longrightarrow CuSO_4\\cdot 5H_2O}\\)"}}]}};
  window.NOTES_V2 = Object.assign(window.NOTES_V2 || {}, NOTES_V2_DATA);
  window.LESSONS = window.LESSONS || {};
  window.BATCH_NOTES = window.BATCH_NOTES || {};
  window.STUDY_FORMULAS = window.STUDY_FORMULAS || {};

  function conceptToParagraphs(concepts) {
    const out = [];
    for (const c of concepts) {
      out.push('**' + c.title + '**（' + c.pageRef + '）：' + (c.body || []).join(' '));
      if (c.takeaway) out.push('**核心要点：**' + c.takeaway);
    }
    return out;
  }

  function toBatchQuestion(q, ch) {
    return {
      id: q.id,
      tier: q.tier,
      tierLabel: q.tierLabel,
      examStyle: q.examStyle,
      subject_code: ch.courseCode,
      chapter_id: ch.chapter,
      paper_no: null,
      question_origin: 'original_textbook_aligned',
      q: q.q,
      options: q.options || null,
      correctOption: q.correctOption || null,
      analysis: q.clues || q.analysis || '',
      given: q.given || '',
      method: q.method || '',
      principle: q.principle || '',
      steps: q.steps || [],
      ans: q.ans,
      markingPoints: q.markingPoints || [],
      verification: q.verification || '',
      pitfall: q.pitfall || ''
    };
  }

  for (const [lessonKey, ch] of Object.entries(NOTES_V2_DATA)) {
    const existingLesson = window.LESSONS[lessonKey] || {};
    const existingBatch = window.BATCH_NOTES[lessonKey] || {};
    const flatExamples = [];
    const flatPractice = [];

    const syncedSections = ch.sections.map(s => {
      const prevSec = (existingLesson.sections || []).find(x => x.id === s.id) || {};
      const bodyParas = conceptToParagraphs(s.concepts);
      for (const ex of s.examples) {
        flatExamples.push({
          lv: ex.tierLabel || ex.tier,
          q: '[' + s.id + '] ' + ex.prompt,
          steps: ex.steps,
          ans: ex.answer,
          pts: (ex.markingPoints || []).join('；')
        });
      }
      for (const p of s.practice) {
        flatPractice.push({
          lv: p.tier === 'L1' ? '基础' : p.tier === 'L2' ? '中等' : '困难',
          q: '[' + s.id + ' · ' + (p.tierLabel || p.tier) + '] ' + p.q,
          ans: p.ans,
          sol: p.steps.join(' ')
        });
      }
      return {
        id: s.id,
        t: s.t,
        syl: s.anchor.syllabus,
        body: bodyParas,
        figs: prevSec.figs || s.figs || [],
        f: s.formulas.map(f => f.title + '：' + (f.plain || f.tex)),
        terms: s.anchor.terms || prevSec.terms || '',
        tips: s.pitfalls.map(p => [p.title, p.diagnosis + ' 正解：' + p.right])
      };
    });

    window.LESSONS[lessonKey] = {
      ...existingLesson,
      syl: ch.syllabus || existingLesson.syl || '',
      status: ch.bookCitation + ' · 已按教材精校并升级为 UEC 高效笔记 V2（' + ch.sections.length + ' 节）。',
      sections: syncedSections,
      ex: flatExamples,
      pr: flatPractice,
      method: {
        format: ch.paperFocus || existingLesson.method?.format || [],
        steps: ch.solvingWorkflow || existingLesson.method?.steps || [],
        types: ch.questionTypes || existingLesson.method?.types || [],
        score: ch.scoringNotes || existingLesson.method?.score || []
      },
      vid: ch.vid || existingLesson.vid || []
    };

    const nextBatch = { ...existingBatch };
    for (const s of ch.sections) {
      const prevB = existingBatch[s.id] || {};
      nextBatch[s.id] = {
        ...prevB,
        note_version: 2,
        subject_code: ch.courseCode,
        chapter_id: ch.chapter,
        section_id: s.id,
        goals: s.anchor.goals,
        prerequisites: s.anchor.prerequisites || [],
        flow: s.concepts.map(c => c.title),
        deep: conceptToParagraphs(s.concepts),
        derive: s.formulas.map(f => '**' + f.title + '**：\[' + f.tex + '\]（' + f.conditions + '）'),
        examples: s.examples.map(ex => ({
          subject_code: ch.courseCode,
          chapter_id: ch.chapter,
          paper_no: null,
          q: ex.prompt,
          analysis: ex.clues,
          given: ex.given || '',
          method: ex.strategy,
          principle: ex.principle || '',
          steps: ex.steps,
          ans: ex.answer,
          verification: ex.verification || '',
          pitfall: ex.pitfall || '',
          markingPoints: ex.markingPoints || []
        })),
        strategy: {
          worked_example_index: 0,
          trigger: s.examples[0]?.clues || '',
          method: s.examples[0]?.strategy || '',
          principle: s.examples[0]?.principle || '',
          verification: s.examples[0]?.verification || '',
          pitfall: s.examples[0]?.pitfall || ''
        },
        exam: ch.paperFocus || prevB.exam || [],
        exam_evidence: prevB.exam_evidence || [],
        error_analysis: s.pitfalls.map(p => ({
          wrong_approach: p.wrong,
          correction: p.diagnosis + '；' + p.right,
          verification: p.checkRule
        })),
        practice: s.practice.map(q => toBatchQuestion(q, ch)),
        quick: s.cheatSheet,
        quiz: toBatchQuestion({ ...s.quiz, id: lessonKey + '-' + s.id + '-quiz', tier: 'L2', tierLabel: '自检' }, ch),
        content_sources: [
          {
            source_id: ch.bookId,
            page: s.anchor.pages,
            version: ch.bookCitation,
            access_date: '2026-11-28'
          }
        ]
      };
      if (s.formulas.length) {
        window.STUDY_FORMULAS[lessonKey + '/' + s.id] = s.formulas.map(f => [f.title, f.tex, f.conditions]);
      }
    }
    window.BATCH_NOTES[lessonKey] = nextBatch;
  }
})();
